// 每集摘要（AI 依文字稿整理）：s = 摘要，p = 重點，k = 主題標籤
window.SUMMARIES = {"6094-a26_001":{"s":"本集為單元開場，說明依平實導師《法華經講義》以「演義」而非科判方式解說佛「開示悟入」佛知見，指佛知見以第八識如來藏為中心。並釋經名「妙法」即如來藏，介紹其第一種微妙法性「能生」：十八界皆由如來藏藉緣出生。","p":["佛知見以第八識如來藏為中心而說","引《中阿含》說明明解脫始於親近善知識","《法華經》顯示諸佛真實本質，勿當神話看","經名「妙法」即指如來藏心","如來藏能生：意根、五根、六塵、六識皆由其生"],"k":["如來藏","妙法","能生","開示悟入","八識論","善知識"]},"6106-a26_002":{"s":"本集續說如來藏「能生」之性：十八界具足成人，萬法種子含藏於如來藏，器世間亦由共業有情的如來藏共同成就。並依《中論》破斥一神教造物主屬「他生」、以根塵和合生六識屬「共生」的見解，強調萬法以如來藏為根本因、藉緣而生。","p":["具足十八界方為完整欲界有情","盲人復明：見色功能本在如來藏中","器世間由共業有情如來藏共同成就","造物主之說屬「他生」邪見","根塵和合生六識屬「共生」邪見"],"k":["如來藏","能生","十八界","器世間","共業","中論四句"]},"6109-a26_003":{"s":"本集講如來藏第二種妙性「金剛性」：本來不可壞，非修行而成，十方諸佛合力亦不能壞任一有情之如來藏。以虛空、鏡像為喻，並批評印順無因共生之說、琅琊閣疑見與見取見，以及密宗自稱金剛乘，指只有證如來藏者方得金剛三昧。","p":["如來藏不可壞，如虛空而能生萬法","所生之法不能反壞能生之如來藏","金剛性本來如是，非修而得","證如來藏並轉依者方是金剛三昧","批評密宗自稱金剛乘、雙身法之說"],"k":["金剛性","如來藏","金剛三昧","見取見","聖教量","破邪顯正"]},"6096-a26_004":{"s":"本集續說金剛性，闡釋「聖教量」與「法界現量／定量」：如來藏不可壞是法界中不可改變的事實，故佛法不許有創見。以空相與空性辨正，並以「第八識何時生、何時滅」反詰主張阿賴耶識生滅者，批評印順「大乘非佛說」等創見如盲人摸象。","p":["違背聖教量即違背法界現量","空相指緣起蘊處界，空性指如來藏","法界定量不可改，佛法不許創見","問阿賴耶生滅者：第八識何時生滅","所生之法不能壞能生者，故稱妙法"],"k":["金剛性","法界現量","聖教量","創見","空性","阿賴耶識"]},"6107-a26_005":{"s":"本集講如來藏第三種妙性「本來性」：法爾而有，諸佛宿住隨念智亦推究不出其出生時。依「有生必滅」說明本來不生故不滅，引六祖「將滅止生非佛菩提」辨二乘與佛菩提之別，並以一境四見說明相分由第八識變現，指如來藏是「唯我獨尊」的無二妙法。","p":["如來藏法爾而有，無出生之時","批評「地獄是聖人施設」之說","一境四見：相分由各自第八識變現","二乘將滅止生，佛菩提本來不生","妙法無二，即「唯我獨尊」"],"k":["本來性","如來藏","不生不滅","將滅止生","四種涅槃","唯我獨尊"]},"6115-a26_006":{"s":"本集開講〈序品〉，說明序品記錄結集因緣，逐句解釋「如是我聞」「一時」「王舍城耆闍崛山」及萬二千阿羅漢等法眾。重點闡述比丘四義與阿羅漢斷漏，並舉阿支羅迦葉為例，說明證果者不論在家出家皆為佛所認可的沙門。","p":["「如是我聞」為佛臨終交代，證經可信","用「一時」避免紀年紛爭","沙門以證果論，非以出家相論","比丘四義：乞士、破煩惱、淨持戒、怖魔","四果次第斷見惑思惑而證阿羅漢"],"k":["序品","如是我聞","比丘","沙門","阿羅漢","四沙門果"]},"6121-a26_007":{"s":"本集續講〈序品〉，解釋經文形容阿羅漢「諸漏已盡…心得自在」之義。詳述聲聞以四聖諦、四念處、八正道斷三縛結至五上分結的四果次第，以及緣覺觀十因緣「齊識而還」、十二因緣的觀行，並指二乘未斷習氣與所知障，實未證涅槃，只是佛方便說。","p":["聲聞依四聖諦斷見思惑而入無餘涅槃","三苦八苦與苦集滅道四聖諦","初果至四果所斷結使與證境","緣覺觀十因緣齊識而還、十二因緣可滅","二乘以慧入涅槃，實無人證涅槃"],"k":["阿羅漢","四聖諦","十二因緣","三縛結","無餘涅槃","二乘菩提"]},"6120-a26_008":{"s":"本集續講〈序品〉列名的大阿羅漢，介紹阿若憍陳如因三轉四聖諦法輪最先證阿羅漢、舍利弗與目犍連隨馬勝比丘因緣出家。以鴿入佛影與舍利弗影之事說明阿羅漢習氣未盡、神通有限，並述目犍連救母、度量佛音聲、償宿債，以及迦旃延論議第一，兼及各人受記作佛名號。","p":["憍陳如聞三轉法輪最先證阿羅漢","鴿影故事：阿羅漢習氣未斷、神通有限","目犍連救母為盂蘭盆會由來","目犍連被打而亡：神通敵不過業力","迦旃延以少年法、老年法折服梵志"],"k":["序品","大阿羅漢","舍利弗","目犍連","授記","業力"]},"6134-a26_009":{"s":"本集續介紹〈序品〉中的四位大阿羅漢：阿那律因施辟支佛得無貧，佛為其穿針說明福德為成佛資糧；富樓那答佛之問展現忍辱與為法捨身之志；須菩提因瞋習而成佛最晚，告誡菩薩忌犯瞋；阿難請佛度大愛道出家而有八敬法，並因摩登伽女成為《楞嚴經》緣起。","p":["阿那律失明得天眼，佛示福力最勝","六度前五度培植福德，福不足易退轉","富樓那善修忍辱，願為正法捨身","須菩提瞋習重，成佛最晚，菩薩忌瞋","阿難請度大愛道，比丘尼依八敬法"],"k":["福德","忍辱","瞋習","八敬法","大阿羅漢","授記"]},"6126-a26_010":{"s":"本集講難陀因往昔供養獨覺得三十相，以及佛引其見天宮與地獄而證阿羅漢；接著講經文中八萬菩薩摩訶薩的功德，解釋陀羅尼即總持，並以正覺總持咒為例。再介紹文殊、觀世音為古佛示現，彌勒菩薩當來下生與龍華三會，並以德光論師為例說明我慢障道。","p":["福德應迴向佛道，勿求生天享樂","難陀見天宮與地獄後精進證果","陀羅尼即將法義貫串成偈的總持","文殊、觀音皆為古佛倒駕慈航示現","德光論師我慢不禮彌勒而錯失證果"],"k":["序品","菩薩摩訶薩","陀羅尼","文殊師利菩薩","觀世音菩薩","彌勒菩薩"]},"6118-a26_011":{"s":"本集講〈序品〉中前來法華勝會的天眾，說明諸天與他方菩薩也是此經的證人，並批評印順「佛教只在人間」之說自相矛盾。依序介紹釋提桓因與忉利天三十三天、四大天王六齋日巡察、化樂天與他化自在天、初禪至四禪各天的天主與天眾，並說明無想天依定而無意識、福盡下墮，不值得羨慕。","p":["天人與他方菩薩同為法華經證人","批評「佛教只在人間」的說法","釋提桓因即道教玉皇大帝，護持佛法","化樂天與他化自在天名稱的由來","無想天無意識，福盡易墮畜生"],"k":["序品","天眾","釋提桓因","四大天王","色界四禪","無想天"]},"6136-a26_012":{"s":"本集續介紹法華會上的天龍八部：釋尸棄大梵、光明大梵等色界天王；八大龍王各自名義與典故，如難陀、跋難陀與目犍連鬥法後成歡喜龍王，以及龍化人身的五種限制。並解說四緊那羅王分唱四聖諦、因緣法、六度與三乘總持，四乾闥婆王掌管樂與絃樂，以及婆稚阿修羅王戰敗的故事。","p":["尸棄大梵為二禪天王，光明大梵為三禪天王","八大龍王名義，難陀二龍改名歡喜龍王","龍化人身有五種時節不能保持","四緊那羅王以歌唱誦三乘法義","乾闥婆奏樂；婆稚阿修羅王被般若咒降伏"],"k":["序品","天龍八部","八大龍王","緊那羅","乾闥婆","阿修羅"]},"6150-a26_013":{"s":"本集續介紹法華會眾：毘摩質多羅等阿修羅王因舍脂之事與釋提桓因交戰後和好，一同聽法；四迦樓羅王（金翅鳥）的成因、卵胎濕化四生與食龍的限制。接著以阿闍世王為人證，敘述其受提婆達多唆使弒父、囚母，韋提希因此請佛而有《觀經》，以及阿闍世後來懺悔歸佛、得無根信的經過。","p":["阿修羅王與帝釋恩怨，法會中仍同聽法","大布施卻懷瞋慢，死後生為金翅鳥","金翅鳥與龍皆有四生，各有食與不食之限","阿闍世弒父囚母，韋提希請佛說《觀經》","阿闍世懺悔得無根信，免墮地獄"],"k":["序品","阿修羅","迦樓羅","阿闍世王","韋提希","觀無量壽佛經"]},"6152-a26_014":{"s":"本集講世尊說法華前的安排：佛先為菩薩說《無量義經》，闡明一法（如來藏）含攝無量義，說畢入無量義處三昧，天雨四華、六種震動。說明《無量義經》為《法華經》序經，並解釋五時三教、頓教與圓教之義，指法華將一切法收歸如來藏而「收圓」，最後講佛放眉間白毫光照東方萬八千世界。","p":["《無量義經》說一法即如來藏攝無量義","入無量義處三昧，天雨四華、六種震動","《無量義經》是《法華經》的序經","五時三教：權教、實教、圓教","華嚴頓教先說，法華圓教收圓"],"k":["無量義經","圓教","五時三教","如來藏","白毫相光","序品"]},"6145-a26_015":{"s":"本集續講佛眉間白毫光照東方萬八千世界，上至色究竟天、下至阿鼻地獄，使大眾見他方六道、諸佛說法與菩薩修行，目的在令眾生對十方三世佛教生起信心，並勸以宏觀調伏我慢。接著講彌勒菩薩代大眾起疑，請問文殊師利放光因緣，說明大菩薩配合佛「演戲」作開場，並語譯彌勒問偈前段。","p":["思量自身在萬八千世界中的渺小可伏慢心","放光令見他方六道、諸佛與菩薩","目的在令眾生對十方佛教起信","法華難信，須由大菩薩先問答作序曲","彌勒問文殊：三乘隨根說法、布施迴向佛道"],"k":["白毫相光","序品","彌勒菩薩","文殊師利菩薩","十方佛土","信心"]},"6146-a26_016":{"s":"本集解說彌勒偈頌所見東方佛土菩薩的種種行門：布施寶車、身肉手足乃至頭目，捨王位出家，獨處誦經、入山思惟佛道，離欲修定得五神通。引《大乘本生心地觀經》等說明求無上道須以布施修福為基礎，並強調神通須先離欲，以五通仙人起欲失通為例，批評密宗祖師神通之說。","p":["布施內外財、頭目身體以求佛智慧","不修福德只求證道是妄想","等覺菩薩捨身命修相好福德","菩薩形形色色，不可一概而論","神通須禪定兼離欲，起欲即失通"],"k":["布施波羅蜜","福德","五神通","離欲","禪定","菩薩行"]},"6148-a26_017":{"s":"本集續說偈文：神通須離欲深修禪定，批評喇嘛雙身法不可能得神通；「以千萬偈讚諸法王」，以提婆達多稱「南無」而在地獄得樂為例說明讚佛功德。並解說「智深志固」須見道勝解，「定慧具足」能以無量喻說法，及入地方為能荷擔如來家業的真佛子，警示瞋火與邪見燒功德林。","p":["密宗雙身法無離欲前提，不可能得神通","偈頌讚佛乃至一稱南無皆有功德","瞋火與謗法邪見會燒毀功德林","定慧具足能以無量譬喻為眾說法","入地菩薩方為能荷擔家業的真佛子"],"k":["讚佛功德","定慧具足","佛子","提婆達多","功德林","說法"]},"6147-a26_018":{"s":"本集解說「破魔兵眾，而擊法鼓」，以正覺破斥密宗雙身法為例，說明被罵愈甚表示破邪愈有成效，不顧面子才能擊法鼓。續講菩薩寂然宴默不喜天龍恭敬、林中放光濟地獄苦、經行不眠求道、持戒威儀如寶珠，以及安住忍辱力面對增上慢人辱罵，並語譯下一段布施佛僧的經文。","p":["擊法鼓以正法令眾生我見邪見死去","顧面子即落五陰我所，未斷我見","天龍恭敬不以為喜，放光濟地獄苦","持戒威儀清淨如寶珠以求佛道","弘了義法必遭增上慢人罵，應安忍"],"k":["破魔兵眾","擊法鼓","忍辱","持戒","增上慢","破邪顯正"]},"6160-a26_019":{"s":"本集講「離諸戲笑及癡眷屬，親近智者」：批評只講人天善法或以意識離念靈知為真如屬戲論與癡眷屬，並分說聲聞、緣覺、佛菩提三種智者的教導，強調福慧雙修。續解布施飲食湯藥、衣服、精舍、園林供養佛僧，以及菩薩「說寂滅法」，指菩薩須兼住持二乘菩提，先斷我見再修大乘。","p":["離戲論與癡眷屬，親近智者極重要","以離念靈知為真如即愚癡","三乘智者各教現觀十八界、因緣法、如來藏","以飲食、衣、舍、園林供佛僧集福德","菩薩須兼說二乘寂滅法，先斷我見"],"k":["親近善知識","戲論","離念靈知","福慧雙修","寂滅法","二乘菩提"]},"6162-a26_020":{"s":"本集講「觀諸法性，無有二相，猶如虛空」為諸法攝歸如來藏的實相一相，並以魔波旬化牛擾亂說明心無所著。續解佛滅後供養碎身舍利、造塔廟莊嚴國界，及彌勒請文殊決疑「為說妙法或為授記」。指出放光所示他方菩薩各階修行，即顯釋迦因地所歷，成佛須多世修行。","p":["諸法攝歸如來藏，實相一相如虛空","心無所著以妙慧求無上道，魔擾不住","諸佛多留碎身舍利，便於眾生種福","塔與廟的區別及寺名由來","他方菩薩各階修行即顯佛因地歷程"],"k":["實相","如來藏","舍利","塔廟","彌勒菩薩","文殊師利菩薩"]},"6166-a26_021":{"s":"本集講解〈序品〉中文殊菩薩回答彌勒之問：佛放光後將說大法，並舉過去日月燈明如來為例。先說明故意曲解佛語即成謗法、破法、謗佛三種因果，再逐一解釋佛十號中的應供、正遍知、明行足、善逝、世間解，並對比阿羅漢與佛的差別。","p":["文殊答彌勒：佛現瑞光即將演說大法","曲解佛法而稱佛說，即成謗法、破法、謗佛","應供、正遍知：佛具足世出世間法之知","明行足：阿羅漢三明有限，佛能授記無限劫","善逝、世間解：佛示現受生入滅，遍知世間成因"],"k":["如來十號","日月燈明佛","明行足","謗佛","授記","序品"]},"6165-a26_022":{"s":"本集續講佛十號中的無上士、調御丈夫、天人師、佛、世尊。說明佛以軟語、如實語、雜語、時語及大威德力調御眾生；天人師須度化天人天主；佛即覺者，三寶本質歸於佛；世尊則超越生天、解脫天與第一義天，為三界中最尊。","p":["無上士：佛於諸法門善巧無人能超越","調御丈夫具軟語、如實語、雜語、時語四種語","威德力來自智慧與三大阿僧祇劫福德","天人師須度天人，批評自稱菩薩化身的密宗行者","世尊超越解脫天、第一義天，為三界中尊"],"k":["如來十號","調御丈夫","天人師","第一義天","三寶","增上慢"]},"6168-a26_023":{"s":"本集講解日月燈明如來說法「初善、中善、後善，其義深遠，純一無雜」，指出諸佛所說皆不離如來藏妙義，並批評堆砌名相、無法實證的說法屬像法、末法現象。接著解釋「為求聲聞者說應四諦法」的「應」字，即須先修施論、戒論、生天之論等次法，再說四聖諦而證初果。","p":["諸佛說法初中後善，不會龍頭蛇尾","以堆砌名相為像法、末法之說，批評《妙雲集》","純一無雜：三世諸佛所說皆演如來藏","具足清白梵行，批評雙身法非梵行","應四諦法：先說施戒生天次法，再說四聖諦"],"k":["四聖諦","次法","如來藏","像法末法","清白梵行","布施"]},"6176-a26_024":{"s":"本集講解「為求辟支佛者說應十二因緣法」與「為諸菩薩說應六波羅蜜」。說明相應於十二因緣的前提是識與名色互緣、齊識而還的本識常住，並須先以五停心觀安心；修六波羅蜜則須以八識論、如來藏為前提，否則以六識論修學終將落入斷滅空而退轉。","p":["佛世大阿羅漢亦有辟支佛證量，稱緣覺","應十二因緣法：識緣名色、名色緣識，齊識而還","五停心觀調伏心性，為觀因緣法之前行","六識論修般若會恐懼斷滅而退轉","應六波羅蜜必以如來藏為中心修學"],"k":["十二因緣","六波羅蜜","如來藏","八識論","五停心觀","緣覺"]},"6178-a26_025":{"s":"本集說明以實證如來藏為前提修六度，方能證無上正等正覺並成就一切種智，因一切種子皆含藏於如來藏中，否定如來藏則無從成就種智。接著解說兩萬日月燈明佛同名同姓、最後一佛八王子捨位出家，以及佛說《無量義經》後入無量義處三昧、天雨四花、六種震動的瑞相。","p":["如來藏為無上、正等、正覺之法","一切種子藏於如來藏，否定之則無法成種智","兩萬日月燈明佛同名，諸佛平等說法無別","八王子善根深厚，捨王位隨父出家","《無量義經》之一法無量義即如來藏"],"k":["一切種智","如來藏","日月燈明佛","無量義經","八王子","無量義處三昧"]},"6179-a26_026":{"s":"本集講解日月燈明佛放光照東方佛土、為妙光菩薩說《妙法蓮華經》六十小劫、聽眾感如食頃，以及入滅前授記德藏菩薩成佛。強調授記是諸佛常法，並以此檢驗自稱成佛者與密宗即身成佛說之虛妄；最後介紹妙光弘經八十小劫、八王子成佛及弟子求名貪著利養。","p":["過去佛亦放白毫光照萬八千土，非刻意新創","六十小劫說法如食頃，喻佛威神力","日月燈明佛入滅前授記德藏菩薩","授記為諸佛常法，可檢驗自稱成佛者","妙光弘《法華》，八王子成佛，末為燃燈"],"k":["授記","妙光菩薩","日月燈明佛","即身成佛","燃燈佛","求名菩薩"]},"6186-a26_027":{"s":"本集說明求名菩薩雖貪著名利，仍因種善根而值遇無量諸佛供養，故勸學人以憐愍心看待求名而誹謗者。經文揭曉妙光即文殊、求名即彌勒，顯示彌勒不搶先說、文殊點明不可輕視彌勒的倫理。接著進入重頌偈，並勸應信受經中無量劫之說，區分新學與久學菩薩。","p":["求名者仍須供養無量諸佛才能見道","面對誹謗應生憐愍心而繼續弘法","妙光即文殊、求名即彌勒，顯佛教倫理","大菩薩示現演戲度眾，悟後不應生慢","經中可實證之法可信，疑者為新學菩薩"],"k":["求名菩薩","彌勒菩薩","文殊菩薩","妙光菩薩","重頌","久學菩薩"]},"6184-a26_028":{"s":"本集續解重頌偈，勸學人信受聖教、不輕信選擇性取材的學術考證，並說明菩薩遍布三界六道，批評只限人間的佛教觀。又講諸佛示現眷屬圓滿而後出家，以及諸佛必說大乘法、最後以《無量義經》將一切法收歸如來藏，再說《法華經》圓滿一代時教；最後說明先供養後請法的諸佛常法。","p":["疑見不斷難以證道，應信受經中聖教","批評學術考證先有立場、選擇性取材","菩薩遍布三界六道，天界尤多","諸佛必說大乘法，《無量義經》收歸如來藏","供佛須先供養後請法，佛法不可交易"],"k":["無量義經","如來藏","大乘法","人間佛教","供養","新學菩薩"]},"6185-a26_029":{"s":"本集解說重頌中天雨曼陀華、佛放眉間光照東方萬八千佛土，示眾生生死業報處，以昭因果。強調佛法不只在人間、地球或娑婆，批評「人間佛教」說與解脫道四果天界受生之理自相矛盾，並批評視釋迦佛為偶然成佛、否定十方諸佛的說法。","p":["聽法前先供養，坐位不擋佛前","光照六道業報處，令眾生信因果","諸佛土眾寶莊嚴，佛教遍十方世界","初果至三果生天仍修行，反證天界有佛法","諸佛成佛非偶然，十方不只一佛"],"k":["人間佛教","因果","十方諸佛","佛土","世界海","放光"]},"6188-a26_030":{"s":"本集講解偈頌中佛光所照諸佛土的各類修行者：無數聲聞眾、山林持戒比丘、行施忍辱菩薩、以定為禪者及知法寂滅相的證悟菩薩。說明聲聞性與菩薩性的程度差別，勸未來度眾要攝受並培養弟子的菩薩性；持戒能令心得決定，施忍等雖非見道卻是必要資糧。","p":["聲聞性與菩薩性有程度差別，皆應攝受","度眾應令弟子發起菩薩性，佛土才莊嚴","持戒如護明珠，因戒令心得決定","行施忍辱是見道前資糧，不宜否定","知法寂滅相：諸法攝歸如來藏故寂滅"],"k":["菩薩性","聲聞性","持戒","福德資糧","寂滅相","以定為禪"]},"6198-a26_031":{"s":"本集先整理〈序品〉情節順序：世尊說《無量義經》入三昧放光，文殊憶念日月燈明佛同樣瑞相，預示將說最後最上的《法華經》。接著開始講五時三教：華嚴時為十方大菩薩說法，如日照高山、窮子喻之「旁追」；鹿苑時說阿含解脫道為藏教，如日照幽谷，於《法華》中喻為化城、「二誘」。","p":["《法華經》為諸佛入滅前最後最上之法","五時：華嚴、鹿苑、般若、唯識、法華","華嚴時為大菩薩說，顯佛初成道即圓滿","鹿苑時說阿含解脫道，稱藏教","阿含解脫道喻化城，窮子喻中為二誘"],"k":["五時三教","華嚴時","鹿苑時","窮子喻","化城喻","藏教"]},"6200-a26_032":{"s":"本集續講五時三教。般若時二轉法輪，依如來藏說空有不二，三乘同聽各得其解，稱通教，如日照大地、窮子喻之「體信」；唯識種智時三轉法輪，說一切種智，只攝大心菩薩，稱別教、「領知」；法華時直說如來藏本來成佛，為圓教、「付業」。並整理頓、漸、圓三類與化法四教等名相。","p":["般若時說空有不二，三乘共聞稱通教","批評視大乘空與二乘空相同之說","唯識時說種智，只攝大心菩薩為別教","法華時為圓教，五千增上慢人退席","窮子喻對應旁追、二誘、體信、領知、付業"],"k":["五時三教","般若時","唯識種智","圓教","窮子喻","通教別教"]},"6208-a26_033":{"s":"本集強調五時三教即每位佛弟子從凡夫到成佛的修學次第，《法華經》為終點與地圖，並以此解釋正法、像法、末法的成因。以乳、酪、生酥、熟酥、醍醐比喻五時，說明五時皆是如來藏一味，即一佛乘；唯有真見道者才嚐得此味，並批評未證言證及將《法華》說為神話的說法。","p":["五時三教對應佛弟子修證的次第","正像末三時差別在有無善知識依次第教導","五時如乳酪酥醍醐，皆是如來藏一味","意識理解只是聞慧，未證言證成大妄語","玄奘通宗通教，批評《法華》神話說"],"k":["五時三教","五時一味","一佛乘","醍醐","如來藏","正像末法"]},"6201-a26_034":{"s":"本集勸學人以五時三教檢驗自身修證落處，並說明佛經偈頌與長行的關係：古印度以口誦傳承，偈頌為總持，往往較早。接著解釋無量義三昧：十八界一切法皆有限量，唯真如如來藏能具無量義，即《法華經》的一佛乘；並引《華嚴經》普賢身說明一切法皆在自心如來藏中。","p":["以五時次第檢驗自己修證的落處","古印度口誦傳承，偈頌為總持主體","十八界法皆有限量，不能成就無量義","唯如來藏具無量義，即一佛乘核心","《華嚴》普賢身：修行不離自心如來藏"],"k":["無量義","一佛乘","如來藏","偈頌","普賢身","十八界"]},"6202-a26_035":{"s":"本集講解日月燈明佛讚妙光菩薩為持法者，說明「勝解」須聞思修證具足，警惕未悟言悟。並指出《法華經》重點在諸法實相，批評以緣起性空為實相之說；引《中阿含經》說明佛滅後無人等同於佛，弟子依法不依人。最後進入〈方便品〉開頭，佛告舍利弗如來智慧甚深，唯佛與佛乃能究盡。","p":["勝解須聞思修證具足，非意識理解","說法六十小劫不起於座，暗指如來藏","《法華》重點在諸法實相，非緣起性空想法","佛滅後無人等同佛，弟子依法不依人","〈方便品〉：如來智慧甚深，唯佛與佛乃能究盡"],"k":["諸法實相","勝解","方便品","妙光菩薩","授記","一佛世界唯一佛"]},"6209-a26_036":{"s":"本集講解〈方便品〉偈「世雄不可量……無能知佛者」，說明佛福慧兩足、威德為三界至尊，故稱世雄、大雄。以鴿入佛影不怖、入舍利弗影仍怖說明佛大慈悲與習氣斷盡之別；並引《大乘起信論》「歸命盡十方，普作大饒益，智無限自在，救護世間尊」，解說四智、三智與般若、解脫帶來的自在。","p":["世雄：佛福德智慧威德為三界至尊","鴿入佛影不怖，顯佛大悲與習氣斷盡","歸命盡十方：應歸命十方三世諸佛","智無限：一切種智圓滿、四智圓明","自在源於般若慧與解脫慧；佛為大醫王"],"k":["方便品","世雄","四智圓明","一切種智","大乘起信論","大慈大悲"]},"6216-a26_037":{"s":"本集講解〈方便品〉「佛力無所畏、解脫諸三昧」等偈，列舉佛十力與四無所畏，並說明三昧有禪定三昧與智慧三昧。詳解禪定三三昧（有覺有觀、無覺有觀、無覺無觀）並區別於般若經之離覺觀，再說二乘與大乘的空、無相、無願三昧；最後解釋道場成果與「是法不可示，言辭相寂滅」指如來藏。","p":["佛具十力、四無所畏、三種解脫","三昧分禪定三昧與心得決定的智慧三昧","禪定三三昧：初禪、未到地定、二禪以上","二乘依蘊處界、大乘依如來藏證三解脫門","是法不可示，指離言寂滅的如來藏"],"k":["三三昧","十力","四無所畏","空無相無願","如來藏","方便品"]},"6230-a26_038":{"s":"本集講解〈方便品〉偈：縱使十方遍滿如舍利弗的阿羅漢、辟支佛、新發意菩薩、不退菩薩共同思量，皆不能測佛智。說明分段生死與變易生死的差別，阿羅漢只斷煩惱障現行，所知障須至佛地方斷盡；新發意菩薩已供養無數佛，並引《金剛經》與《瓔珞經》說明福德與善知識攝受的重要，介紹五種不退。","p":["遍滿十方如舍利弗者亦不能測佛智","分段生死依五陰命根，變易生死依種子流注","所知障即無始無明，明心破而佛地斷盡","新發意菩薩已供養無數佛，福德最重要","五種不退：信、位、行、念、究竟不退"],"k":["變易生死","分段生死","所知障","五種不退","新發意菩薩","佛智"]},"6217-a26_039":{"s":"本集續講「不退諸菩薩……亦復不能知」，以明心者無法測見性境界為例，說明眼見佛性須定力、慧力、福德具足，並介紹禪門三關、明心與見性的差別。再解「唯我知是相，十方佛亦然」與「諸佛語無異」，佛佛道同皆證一切種智；最後引《成唯識論》說第八識的心、所知依、種子識、阿賴耶、異熟識、無垢識等異名。","p":["下位菩薩不能測上位境界，何況佛地","眼見佛性須定力、慧力、福德三資糧","明心與見性為如來藏兩面，非一非異","諸佛語無異：佛佛道同，皆證一切種智","第八識隨位立名：阿賴耶、異熟、無垢識"],"k":["眼見佛性","第八識","阿賴耶識","成唯識論","禪門三關","佛佛道同"]},"6218-a26_040":{"s":"本集講解「於佛所說法，當生大信力；世尊法久後，要當說真實」，說明佛先說二乘法建立信心，再說大乘真實法；並解「佛以方便力，示以三乘教」，概述人天乘、二乘化城與五時三教。最後講千二百阿羅漢等四眾生疑，舍利弗代眾請問並以重頌祈請佛說具足道。","p":["對佛所說應生大信力，否則易退轉","佛先說二乘虛相法，再說大乘實相法","以方便力示三乘教，引眾生出離執著","五時三教次第：華嚴、阿含、般若、方廣、法華涅槃","四眾生疑，舍利弗長行與重頌請佛說法"],"k":["方便品","三乘教","五時三教","舍利弗","大信力","一佛乘"]},"6231-a26_041":{"s":"本集承接〈方便品〉「止！止！不須復說……皆當驚疑」經文，說明佛先說《無量義經》以如來藏一法攝無量義，再說《法華經》。並辨正教判：批評將《法華經》判為佛入滅前最後說法之誤，介紹平實導師依玄奘菩薩所立「五時三教」，說明法華時將三乘匯歸一佛乘。","p":["先說《無量義經》，以如來藏一法函蓋無量義","法華後尚有《大般涅槃經》，非臨滅最後說","空有之諍是未悟者戲論，智光三時判教顛倒","五時：華嚴、阿含、般若、種智、法華","三時分以四諦相、隱密相、顯了相轉法輪"],"k":["五時三教","判教","一佛乘","如來藏","無量義經","三轉法輪"]},"6219-a26_042":{"s":"本集講解〈方便品〉舍利弗三度請法、佛三次制止的經文。說明佛擔心增上慢比丘聞法不信、謗法而墮大坑；舍利弗以三明六通見會眾多世曾隨佛受化，故為大眾慇懃請法。並解釋增上慢、「佛長子」與「無上兩足尊」福慧雙足之義。","p":["佛三止：說此事則天人驚疑，增上慢者墜大坑","增上慢即未得謂得、未證謂證，唯地上菩薩不犯","舍利弗見會眾世世隨佛學法，故堅持請法","大乘經賴菩薩結集流傳，舍利弗等是大恩人","兩足尊即福慧雙足，智慧須福德支撐"],"k":["舍利弗請法","增上慢","方便品","福慧雙足","無明"]},"6242-a26_043":{"s":"本集講解〈方便品〉五千增上慢四眾退席，以及佛說「無復枝葉，純有貞實」、「諸佛唯以一大事因緣出現於世」的經文。說明開示悟入佛知見即為宣說如來藏大法；並批評今日有法師主張佛只是普通人、成佛是演化偶然，等同佛即阿羅漢之說。","p":["五千人退席，因罪根深重與增上慢","定性阿羅漢自認與佛同證，亦屬增上慢","「枝葉」「貞實」之喻；法會本是說法聚會","一大事因緣：令眾生開示悟入佛之知見","批評「佛只是普通人、成佛屬演化偶然」之說"],"k":["一大事因緣","開示悟入","增上慢","五千退席","如來藏","阿羅漢不是佛"]},"6250-a26_044":{"s":"本集說明「一佛乘」的「一」有唯一與整體兩義：成佛之法與佛地境界只有一種，且佛法整體不可切割，二乘法只是大乘的一部分，單修二乘只能滅盡五陰入無餘涅槃而無法成佛。並引〈方便品〉「諸佛如來但教化菩薩」「如來但以一佛乘故為眾生說法」經文說明。","p":["「一」有唯一與整體兩義","成佛須三大阿僧祇劫修六度，具足一切種智","二乘法是大乘的一部分，不能抽離而成佛","諸佛如來但教化菩薩，以佛知見示悟眾生","過去諸佛方便說法，皆為一佛乘"],"k":["一佛乘","一切種智","六度波羅蜜","教化菩薩","二乘","無餘涅槃"]},"6243-a26_045":{"s":"本集延續一佛乘主題，說明佛知見的究竟是一切種智，即了知第八識如來藏一切功能差別。講者提到末法有人錯解佛法（舉友人詢問《廣論》為例），強調須辨別正法。並引經文說明佛隨眾生本性，以因緣、譬喻、方便力說法，舉佛帶貪欲弟子觀天宮、地獄的故事為例。","p":["佛知見究竟即一切種智，了知如來藏功能差別","末法有人以外道法或割裂之法為佛法","諸佛但教化菩薩，令眾生入佛之知見","佛隨眾生本性，以因緣譬喻方便說法","舉弟子見天女、見地獄油鍋而回心修行之例"],"k":["佛之知見","一切種智","方便力","一佛乘","如來藏","末法"]},"6244-a26_046":{"s":"本集講解〈方便品〉「十方世界中尚無二乘……於一佛乘分別說三」經文，說明諸佛出於五濁惡世，因眾生垢重而將一佛乘方便分說三乘。二乘解脫道原屬佛法整體，菩薩入初地亦須圓滿阿羅漢果證。並以化城喻說明二乘涅槃只是中途化城，不究竟也不真實。","p":["五濁惡世眾生垢重，佛於一佛乘分別說三","聲聞緣覺法本屬一佛乘整體之內","菩薩入初地前須圓滿阿羅漢果證","化城喻：導師於長路中途化城，休息後化滅","二乘入無餘涅槃只是滅己，非究竟解脫"],"k":["方便說三乘","化城喻","五濁","一佛乘","解脫道","無餘涅槃"]},"6251-a26_047":{"s":"本集續講「佛以方便力，於一佛乘分別說三」，再以化城喻說明二乘法是幻化而成、不究竟的安止處，佛在弟子建立信心後化去化城，引導前往佛道。並指出阿羅漢、辟支佛都聽聞過大乘法，二乘果建立在佛菩提之上；自稱阿羅漢卻不知諸佛教化菩薩之事者，非真佛弟子。","p":["化城即二乘法，幻化而成，不真實也不究竟","佛待眾生建立信心後化滅化城，引向佛道","阿羅漢、辟支佛皆曾聽聞大乘法","二乘果建立在佛菩提之上","先以二乘攝信心不足者，再說大乘法"],"k":["化城喻","方便說三乘","一佛乘","阿羅漢","辟支佛","迴小向大"]},"6245-a26_048":{"s":"本集說明「佛語」即唯一佛乘，佛地果證是究竟了知第八識如來藏的一切功能差別；但此真實法不屬三界境界，難以證知，以燃香、魔術師為喻。並解說〈方便品〉自謂已得阿羅漢而不求無上菩提者是增上慢人的經文，勸勉應「一心信解受持佛語」。","p":["佛語即唯一佛乘，涵攝聲聞乘與緣覺乘","成佛須究竟了知如來藏一切功能差別","真實法非三界境界，以魔術師喻其微細難見","自謂已得阿羅漢、不求菩提者是增上慢","諸佛言無虛妄：無有餘乘，唯一佛乘"],"k":["信解受持","唯一佛乘","增上慢","如來藏","阿羅漢","實相"]},"6258-a26_049":{"s":"本集依平實導師《法華經講義》第三輯，回顧〈序品〉、〈方便品〉，開始探討「阿羅漢不是佛」。舉《法華經》、《大般若經》及阿含經典說明諸佛皆十號具足；阿含中唯有彌勒尊者被宣示未來成佛並授金縷衣，阿羅漢弟子到法華會才被授記，可見阿羅漢不是佛。","p":["諸佛智慧甚深，聲聞辟支佛所不能知","法華中過去佛與受授記弟子皆十號具足","大般若經十方諸佛、阿含經皆說十號具足","中阿含記彌勒未來成佛十號具足，授金縷衣","大迦葉入雞足山待彌勒；阿羅漢至法華方授記"],"k":["阿羅漢不是佛","十號","授記","彌勒菩薩","阿含經","大迦葉"]},"6270-a26_050":{"s":"本集以六念（念佛、法、僧、施、戒、天）中念佛與念僧的差異，續論「阿羅漢不是佛」。說明念住是以智慧觀所念內涵而住，不只是持名；引大乘經論與阿含經說明六念的修法與功用。念佛是憶念如來十號功德，念僧是憶念四雙八輩功德，兩者內涵不同。","p":["六念的念住是以智慧觀察所念而住，非僅持名","大乘經說六念是福德、智慧二莊嚴之因","阿含教在家居士依四不壞淨修六念","念佛憶念十號功德，念僧憶念四雙八輩","念佛與念僧內涵不同，證阿羅漢不是佛"],"k":["六念","念佛","念僧","阿羅漢不是佛","四不壞淨","念住"]},"6259-a26_051":{"s":"本集先說明獨覺所證與阿羅漢同位，故辟支佛也不是佛；再以四念處類推，引《瑜伽師地論》解說「念」與「念住」，並依七種作意解析阿含「學戒多福利、慧為上首、解脫堅固、念為增上」，指出念為增上即觀察作意。最後提出六念同時是修忍，稱為「六念忍」。","p":["獨覺所證同阿羅漢果，辟支佛也不是佛","以四念處類推，說明念與念住的意義","作意心所：警覺心識、引心趣向所緣境","念為增上即觀察作意，貫穿戒定慧修學","修六念須先接受自己未究竟，即六念忍"],"k":["念住","四念處","作意","六念忍","辟支佛","戒定慧三學"]},"6260-a26_052":{"s":"本集略說「六念忍」：引平實導師開示「安忍就是接受」，說明知與忍有差距，能安忍於自己尚未究竟才能增進道業。逐一解說念佛、念法、念僧、念施、念戒、念天如何同時修忍，並指出法華會五千人退席，是因增上慢、我慢與不信而不能安忍。","p":["安忍即接受；知道與安忍之間差距很大","念佛：如以調御丈夫反觀自身煩惱","念法：觀罵者受者皆空、剎那生滅","念僧、念施、念戒、念天皆具修忍之實","五千人退席，因增上慢、我慢與不信"],"k":["六念忍","安忍","增上慢","我慢","菩薩戒","止觀"]},"6272-a26_053":{"s":"本集說明法華會五千人不信「阿羅漢不是佛」的根本原因是我慢與增上慢。依《瑜伽師地論》定義我慢為因我存在而喜樂，並非與人比較的慢，是五上分結中最難斷者；增上慢分世間法未得謂得與出世間法未證言證，大乘增上慢最重。實證阿羅漢而不信法華、不迴心者，也名增上慢人。","p":["我慢是因自我存在而喜樂，非與人比較之慢","我慢為最難斷的上分結，乃至細至非想定中","阿含：五陰非我、不異我、不相在","增上慢分世間法未得謂得、出世間法未證言證","實證阿羅漢而不迴心大乘，亦稱增上慢人"],"k":["我慢","增上慢","阿羅漢不是佛","五上分結","五陰","迴心大乘"]},"6261-a26_054":{"s":"本集回顧〈方便品〉三請、五千人退席與一大事因緣，接著解說偈頌「若人信歸佛……為說實相印」的四個重點。本集講前三點：如來不欺誑眾生，由持菩薩戒而有廣長舌相；如來已斷煩惱障與所知障，菩薩斷障歷程異於二乘；佛出世是令眾生悟入佛菩提，阿含解脫道只是化城。","p":["如來不欺誑，因地持菩薩戒，成佛有廣長舌相","三十二相從初住位開始修集，至佛地圓滿","批評釋印順稱實相不可知、不可證","如來斷盡煩惱障、所知障，菩薩起惑潤生","三轉法輪中，阿含解脫道是方便化城"],"k":["唯一佛乘","實相印","煩惱障","所知障","菩薩戒","化城喻"]},"6282-a26_055":{"s":"本集說明第四個重點「實相印」即一切有情的生命實相，又名如來藏、阿賴耶識，出生五陰與器世間。接著語譯偈頌「舍利弗當知，我本立誓願……來世得作佛」，歸納四個重點，本集講前兩點：佛願眾生皆成佛道、不以小乘化度而墮法慳貪；不能悟入佛菩提者必是福德欠缺。","p":["實相印即如來藏、阿賴耶識，一切有情皆有","二乘滅盡蘊處界，菩薩則親證實相印","佛願眾生如我無異，以小乘化人即墮慳貪","三乘是方便施設，佛本懷令眾生皆成佛","福德是智慧之基，福德欠缺者難悟佛菩提"],"k":["實相印","如來藏","唯一佛乘","福德資糧","法慳貪","阿賴耶識"]},"6278-a26_056":{"s":"本集續講偈頌後兩個重點。第三點談邪見：講者批評台灣四大山頭以意識靈知心為實相，喇嘛教樂空雙運落入受陰與識陰，自續派、應成派中觀墮於斷常二見。第四點說明涅槃不是斷滅空、本來寂靜，以苦之本際與《心經》說明三轉法輪的次第，並批評達賴喇嘛主張三轉法輪前後顛倒。","p":["邪見即取顛倒法堅著不捨，障礙悟入佛菩提","批評以有念、無念、斷際靈知心為實相","批評喇嘛教樂空雙運及兩派中觀","無餘涅槃非斷滅空，有苦之本際存在","以《心經》說明空性心與涅槃寂靜"],"k":["涅槃寂靜","邪見","實相印","心經","斷常二見","三轉法輪"]},"6283-a26_057":{"s":"本集解說偈頌「我有方便力，開示三乘法……助顯第一義」。從佛初成道欲入涅槃、梵天請法談起，依次說明阿含時三轉十二行法輪隱說本際，般若時令聖弟子證悟並修別相智、發十大願、起惑潤生入地，以及唯識種智時的內容。並說明第一義諦即實相印的多種異名，結論是阿羅漢不是佛。","p":["佛初成道欲入涅槃，大梵天請佛住世說法","阿含時三轉十二行法輪，隱說苦之本際","般若時修別相智、發十大願、起惑潤生入初地","第一義諦即實相印：本際、阿賴耶識等異名","解脫德三乘共證但有差異，阿羅漢不是佛"],"k":["方便力","第一義諦","三轉法輪","別相智","實相印","唯一佛乘"]},"6284-a26_058":{"s":"本集解說偈頌「若有眾生類，值諸過去佛……聚沙為佛塔，皆已成佛道」。說明六度萬行是修集福德與智慧，五乘修學皆需福德，發菩提心即攝一切福德；福德足才能遇真善知識而證悟。並舉金天夫婦供僧、老人一句南無佛、貧女難陀燃燈三例，勸人種良善福田，批評喇嘛教為毒田。","p":["六度萬行即修集福德與智慧資糧","人天、二乘、菩薩各乘皆需福德莊嚴","發菩提心攝一切福德，前五度皆修福","菩薩種性難得，福德足方能證悟","金天夫婦、南無佛老人、貧女燃燈三例"],"k":["福德資糧","六度萬行","發菩提心","菩薩種性","福田","聚沙為塔"]},"6280-a26_059":{"s":"本集依〈方便品〉「彩畫作佛像……皆已成佛道」經文，探討家中供養如來聖像能否成就佛道。說明久學菩薩發願值遇諸佛，懂得恭敬供養，與新學菩薩不同；引《瑜伽師地論》卷44，說明供養不現前佛及制多可得無量大福德，並談家中安立佛像的方式與自他共供養。","p":["值遇諸佛並供養，是成就佛道的因緣","發願值遇賢劫未來佛，親隨彌勒尊佛修學","久學菩薩自然恭敬供養，新學菩薩則否","供養不現前佛像、佛塔，亦得無量大福德","條件不足可用小桌供像，並勸他人同供養"],"k":["供養佛像","福德","久學菩薩","瑜伽師地論","彌勒菩薩","自他共供養"]},"6285-a26_060":{"s":"本集依〈方便品〉「歌唄頌佛德，乃至一小音，皆已成佛道」經文，探討梵唄唱誦法會能否成就佛道。說明梵唄法會屬「次法」，可作為契入三乘菩提之緣起，培養五根、五力；講者批評只趕法會而無所證、道場不教隨聞入觀，法會流於積蓄資財。本集先講梵唄成就信根，進根留待下集。","p":["隨喜唱誦乃至一小音，可為成佛緣起","梵唄法會屬次法，藉以契入三乘菩提之法","批評只跑道場趕法會，一生於法無所證","法會應有事上與理上功德，須教隨聞入觀","梵唄讚佛種下信根，講者自述聞鐘鼓感動"],"k":["梵唄","法與次法","五根五力","信根","法會","供養如來"]},"6311-a26_061":{"s":"本集延續探討《法華經》「乃至一小音，皆已成佛道」，說明如法參加梵唄法會可依序成就信、精進、念、定、慧五根五力，並增上戒定慧三無漏學。講者強調須依善知識教導，以無相憶佛淨念隨文入觀、懺悔迴向，並指出真實「法會」是善知識講經說法之會。","p":["信根、信力具足後方能成就精進根","依善知識教導隨文入觀，漸成念、定、慧根力","以無相憶佛淨念禮佛、懺悔並迴向冤親債主","如法參加法會可增上戒定慧及解脫道智慧","真實法會是善知識宣講三乘菩提之會"],"k":["梵唄法會","五根五力","隨文入觀","無相憶佛","懺悔滅罪","三無漏學"]},"6313-a26_062":{"s":"本集依〈方便品〉「但化諸菩薩，度脫無量眾」等偈，說明諸佛示現人間的本懷是以大乘佛菩提道開示悟入如來藏，二乘法只是方便施設，種種法門「其實為一乘」。並引《長阿含經》說明世尊次第說法，批評「大乘非佛說」及印順六識論之說與經義相違。","p":["諸佛但化菩薩，非為教導二乘小法而來","種種法門的實證標的皆為第八識如來藏","不迴心的定性二乘被喻為焦芽敗種","阿含亦先說施論、戒論、生天之論再勸出離","批評大乘非佛說與印順六識論違背經義"],"k":["唯一佛乘","大乘非佛說","如來藏","定性聲聞","五乘佛法","六識論"]},"6308-a26_063":{"s":"本集為此系列最後一集，引印順《印度之佛教》等書文句，指其主張「大乘非佛說」且前後自相矛盾，並以阿含「生天之論」反問其以考據否定肉眼不見的天界與淨土。講者並述平實導師自1995年起破斥此說，認為其見源自應成派中觀六識論，最後總結大乘經典為佛金口所說。","p":["指印順「直趨解脫教人，不令成佛」之說前後矛盾","以眾生有無真如佛性反問六識論者","以世間考據否定天界、淨土等出世間法不能成立","平實導師《念佛三昧修學次第》已破斥此說","結論：大乘經為佛說，六識論與雙身法非正法"],"k":["大乘非佛說","印順","六識論","八識正教","應成派中觀","生天之論"]},"6309-a26_064":{"s":"本集講解〈方便品〉「我始坐道場…云何而可度」至「雖復說三乘，但為教菩薩」，說明世尊成佛後三七日思惟眾生根鈍難度，經諸天請轉法輪，憶念過去佛方便力而決定分說三乘。並說明三轉法輪次第及《無量義經》、《法華經》宣講緣起，強調說三乘目的仍在教化菩薩。","p":["道場指所證無垢識境界及其功德妙用","三七日思惟眾生五根鈍、著樂癡盲難度","諸梵王、帝釋、四天王等請轉法輪","但讚佛乘則眾生不信破法，故依諸佛說三乘","三轉法輪次第，最後講《無量義經》與《法華經》"],"k":["轉法輪","三乘方便","唯一佛乘","三轉法輪","諸天請法","無量義經"]},"6315-a26_065":{"s":"本集講解「我聞聖師子…我常如是說」經文，說明「喜稱南無佛」與「唯我獨尊」不相矛盾，後者指第八識自心如來。並敘述世尊至鹿野苑為五比丘三轉四聖諦十二行法輪，人間始有涅槃音、阿羅漢及法僧之名；諸法因附屬寂滅的如來藏而為寂滅相，難以言宣，故先說聲聞法。","p":["唯我獨尊指自心如來，諸佛皆喜稱南無佛","鹿野苑為憍陳如等五比丘三轉四諦法輪","以玻璃球喻說明諸法附屬如來藏故寂滅","初轉法輪後人間始有真實涅槃音與僧寶","世尊久遠劫來於各世界示現成佛"],"k":["初轉法輪","諸法寂滅相","如來藏","四聖諦","五比丘","唯我獨尊"]},"6310-a26_066":{"s":"本集講解「我見佛子等…但說無上道」經文，說明靈山聽法眾包含諸天鬼神，人數難計，批評以凡夫心「將心比心」把經文推為神話。並說明鈍根小智、著於表相而生憍慢者不能信受唯一佛乘，舉現代禪李元松遭佛教界批評、平實導師被大法師否定等事為例。","p":["聞法眾包含諸天與大力鬼神，非僅人類","以凡夫心境將心比心不適用於佛法實證","眾多曾聞諸佛方便法者來集，正是說佛慧之時","著相者只看出家、在家表相而生憍慢","佛菩提道超出解脫道範圍，故無從論爭"],"k":["唯一佛乘","著相憍慢","鈍根小智","佛菩提道","解脫道"]},"6319-a26_067":{"s":"本集續講「今我喜無畏…正直捨方便，但說無上道」及「千二百羅漢，悉亦當作佛」，指出「正直捨方便」非指直心修行，而是捨人天乘、二乘等方便道而單說唯一佛乘。並說明喜無畏來自三乘菩提皆證，千二百阿羅漢本是菩薩，故於《法華經》授記作佛。","p":["落在意識的直心修行並非正直，方便指方便道","三乘菩提皆通方能歡喜無畏","從施論、戒論、生天之論到四聖諦皆屬方便道","初轉法輪時佛亦私下為菩薩說無上道","千二百阿羅漢本為菩薩，故得授記當作佛"],"k":["無上道","正直捨方便","喜無畏","方便道","授記","迴小向大"]},"6325-a26_068":{"s":"本集講解「如三世諸佛，說法之儀式，我今亦如是，說無分別法」，說明三世諸佛皆以方便次第接引，最終必說無上菩提的無分別法。講者批評宗喀巴《廣論》以方便導向雙身法、以解脫道取代佛菩提道之說，並指出無分別法不是把意識修到不起念，而是以意識找到本來無分別的真如心。","p":["三世諸佛也包括未來成佛的謗法者","五濁世須依三轉法輪次第施設方便","批評《廣論》以方便引人入雙身法","打坐一念不生仍是分別，了了即已分別","證得本來無分別的如來藏才是無分別法"],"k":["無分別法","如來藏","說法儀式","方便施設","菩提道次第廣論"]},"6320-a26_069":{"s":"本集講解〈方便品〉「諸佛興出世，懸遠值遇難…過於優曇花」，說明聽聞無分別法之難：佛出世間隔懸遠、密意不可明說故說法難、眾生得聞與能聽亦難，並以平實導師早期明講密意的經驗為例。最後說明聞法歡喜讚歎乃至一言，即是法供養三世一切佛。","p":["佛出世間隔懸遠，賢劫千佛為大福報","無分別法密意不可明講，須隱覆而說","眾生無量劫中聞法亦難，如優曇花","聞法讚歎一言即法供養三世諸佛","以文字讚歎功德更為久遠廣大"],"k":["諸佛值遇難","無分別法","優曇花","法供養","密意","賢劫千佛"]},"6321-a26_070":{"s":"本集講解「汝等勿有疑，我為諸法王…無聲聞弟子」，說明法王須具一切種智，唯佛堪稱，並批評西藏密宗自稱法王。講者指佛法究竟圓滿，佛門不許創見，「大乘非佛說」屬創新佛法之論；世尊以一乘道教化菩薩，五十位定性聲聞不算佛弟子，並舉須跋陀羅入滅為例。","p":["法王須具一切種智，唯諸佛可稱","佛說究竟圓滿，佛門不許創見","大乘非佛說為創新佛法的錯誤論述","唯以一乘道教化菩薩，無聲聞弟子","須跋陀羅證果即入滅，為聲聞種姓之例"],"k":["唯一佛乘","法王","一切種智","定性聲聞","大乘非佛說"]},"6327-a26_071":{"s":"本集講解「汝等舍利弗…廣讚一乘道」，分三要點：唯一佛乘是諸佛祕要，只傳迴小向大的菩薩，並述四阿含結集與菩薩另行結集大乘經之說；五濁惡世眾生樂著諸欲不求佛道，未來惡人聞一乘不信而破法；應為有慚愧清淨、志求佛道者廣讚一乘。","p":["實相般若是諸佛祕要，不傳定性聲聞","五百結集成四阿含，菩薩另行結集大乘經","解說見濁、煩惱濁、命濁、眾生濁、劫濁","聞一乘不信、謗如來藏者破法墮惡道","有慚有愧者心清淨，應為其廣讚一乘"],"k":["諸佛祕要","唯一佛乘","五濁惡世","慚愧","經典結集"]},"6336-a26_072":{"s":"本集講解〈方便品〉最後一段「諸佛法如是，以萬億方便，隨宜而說法…自知當作佛」，說明諸佛觀察根器因緣，以無量方便說法，最後皆匯歸唯一佛乘。舉阿含中外道次第聽法證果、平實導師早期急於助人明心而受警為例，並批評見樹不見林、以解脫道為成佛之道者。","p":["諸佛觀根器隨宜說法，非隨興而講","阿含記載外道依次第聽法證阿羅漢","種種方便最後皆匯歸佛菩提道","以四聖諦等為全部佛法是見樹不見林","知諸佛方便事而無疑，自知當作佛"],"k":["隨宜說法","方便善巧","唯一佛乘","佛菩提道","方便品"]},"6338-a26_073":{"s":"本集進入〈譬喻品 第3〉首段，講解舍利弗聞佛說「自知當作佛」而踴躍歡喜，自述昔見菩薩受記作佛而己不預、常自剋責，今斷疑悔，知真是佛子。講者說明入地即得授記、未滿三地菩薩有隔陰之迷而請問授記，並指大阿羅漢是世尊特地來度之人。","p":["舍利弗知將受記而心懷踴躍","菩薩入初地時即為諸佛授記","未滿三地有隔陰之迷，故請問往昔授記","舍利弗自責以小乘見度，今斷諸疑悔","今知真是佛子，從法化生，得佛法分"],"k":["授記","譬喻品","舍利弗","隔陰之迷","佛子"]},"6352-a26_074":{"s":"本集探討「無上法輪」，引《大毘婆沙論》釋法輪義，及《法華經講義》說無上法輪首尾相接、法法相通。講者說明佛說法以萬法根源如來藏為核心，故勝一切法、能貫攝諸法而無矛盾，並論深廣並進、梵天請法之意，主張三轉法輪皆佛金口所說，信受此為四不壞淨的基礎。","p":["法輪取輪之動轉不住、摧伏怨敵等義","無上法輪首尾相接無疏漏、法法相通","以如來藏為核心，故勝一切法","修學深與廣成正比，趨向一理通萬理徹","三轉法輪皆佛所說，化緣圓滿方入滅"],"k":["無上法輪","如來藏","四不壞淨","三轉法輪","梵天請法"]},"6339-a26_075":{"s":"本集探討「作意」心所，引《成唯識論》說明其警心引心作用，並據《瑜伽師地論》指菩薩以利益眾生為作意，與阿羅漢厭背生死不同，舉舍利弗自責為例。並介紹解脫道七種作意、菩薩隨攝等作意、不如理作意四相，以及悟後真如作意、七真如與殷重作意。","p":["作意為遍行心所，引導心行","菩薩以眾生饒益為樂，自利利他","解脫道依四聖諦次第生起七種作意","不如理作意引生煩惱、毀壞羞恥","悟後真如作意與殷重作意尤為重要"],"k":["作意","如理作意","真如作意","七真如","菩薩種姓","自利利他"]},"6340-a26_076":{"s":"本集以舍利弗自述未得金色三十二相等經文為引，說明明心見性不等於成佛，亦無即身成佛。講者依經論解說無見頂相、白毫光相源自如來藏與宣說正法，千輻輪等相與孝養尊長有關，梵音聲相來自實語愛語，並說明上品十善業與等覺菩薩百劫修相好。","p":["明心見性非成佛，一悟即至佛地為方便說","無見頂相顯示佛地無垢識功德","白毫光相因無量世宣說真實正法","孝養父母、奉事師長與成就諸相有關","等覺百劫修相好，除最後身菩薩無即身成佛"],"k":["三十二相","百劫修相好","如來藏","即身成佛","十善業","福德"]},"6354-a26_077":{"s":"本集依〈譬喻品〉舍利弗初聞授記疑「將非魔作佛」一段，說明以世尊所說實道與方便善巧判別真佛與天魔。講者引經論介紹得決擇、魔的定義、魔事範圍與四魔，說明天魔因眷屬欲障礙正法、助長憍慢者，並列遠離菩薩魔道四法，強調對治憍慢心。","p":["舍利弗以世尊說實道確認非魔作佛","得決擇：了知修行位階與現觀以免被籠罩","夢中、定中所聞法須以聖教檢驗","奪慧命、退善法皆為魔事，有四魔之分","遠離魔道四法，尤須不生輕慢"],"k":["魔事","四魔","天魔","得決擇","憍慢","授記"]},"6341-a26_078":{"s":"本集依「佛說過去世，無量滅度佛」偈及經論，說明諸佛示現滅度只是應化身，法身無垢識不生不滅，故成佛盡未來際、利樂眾生無窮。講者解說無上正等正覺、佛佛道同、眾生皆有如來藏，並以《長阿含經》如來終不終四句說明，強調如來藏法義是四不壞信的基礎。","p":["滅度者為應化身，法身無垢識不生不滅","佛果圓滿不增不減，持無漏種盡未來際","正等指諸佛所證相同，眾生皆有如來藏","成佛須歷三大阿僧祇劫，非一世可成","如來藏法義為四不壞信的基礎"],"k":["盡未來際","無垢識","應化身","無上正等正覺","如來藏","四不壞信"]},"6372-a26_079":{"s":"本集先介紹〈譬喻品〉佛告舍利弗昔曾教其志願佛道、授記華光如來及其國土等三段經文，並探討舍利弗為何忘失本願。講者依《菩薩瓔珞本業經》舍利弗退住之例，說明未滿三地者有隔陰之迷，須世世重新斷我見、明心，並告誡學人勿以明心為身分榮耀而生慢心。","p":["三段經文：憶本願、授記華光如來、以本願說三乘","舍利弗曾入七住，遇惡因緣而退","三地滿心證意生身前皆有隔陰之迷","明心是責任非榮譽，勿生慢心","須先斷我見、定慧等持，否則明心必退"],"k":["授記","隔陰之迷","斷我見","明心","華光如來","慢心"]},"6364-a26_080":{"s":"本集依《優婆塞戒經》逐一解說如來十號：如來、阿羅呵、三藐三佛陀、明行足、善逝、世間解、調御丈夫、天人師、佛、婆伽婆，並旁及二十五有、兩種世間、《瑜伽師地論》「無上丈夫調御士」合為一號之說及四魔。講者指出阿羅漢只能少分相應，唯佛完全符合十號。","p":["莊嚴地可解為資糧位，具戒定慧而成如來","阿羅漢含無生、殺賊、應供三義","善逝指不復受生於二十五有","世間解了知眾生世界與國土世界","婆伽婆能破四魔，唯佛完全符合"],"k":["如來十號","優婆塞戒經","二十五有","四魔","世間解","調御丈夫"]},"6373-a26_081":{"s":"本集先引《大乘本生心地觀經》講一佛寶具三身：自性身即不生不滅、超時空的第八識如來藏；自受用身為十地滿心於色究竟天成就的真報身，四智圓明；他受用身為地上菩薩說一乘法；變化身具三十二相，為地前與二乘凡夫說三乘法。並引三譯《楞伽經》說明初次成佛必在色究竟天，以此破斥藏密無上瑜伽，最後總結佛寶六種微妙功德。","p":["自性身即受熏持種的如來藏，具八不中道","自受用身是真報身，色究竟天成佛、有始無終","引三譯《楞伽經》破藏密男女雙修成佛之說","他受用身八萬四千相好，只為地上菩薩說一乘法","變化身三十二相，為地前、二乘凡夫說三乘法"],"k":["三身","真報身","如來藏","色究竟天","六種微妙功德","破斥藏密"]},"6374-a26_082":{"s":"本集回到《優婆塞戒經》〈息惡品〉，從大乘實證角度重解如來十號。說「莊嚴地」究竟義是密嚴國土阿賴耶識，如來是乘如實道而來、唯佛能如實語；以舍利弗食不淨食的故事說明阿羅漢習氣未斷；等正覺即具足五分法身、四智圓明；明行足、善逝則須斷二種無明並遠離五陰區宇，並引平實導師《電子報》說明諸地菩薩次第滅除五陰。","p":["莊嚴地究竟指密嚴國土阿賴耶識","唯佛能如實語，故名如來","舍利弗受罰故事顯阿羅漢習氣未盡","等正覺即具足五分法身、四智圓明","善逝除遠離二十五有，還須過五陰區宇"],"k":["如來十號","五分法身","五陰區宇","阿賴耶識","所知障","優婆塞戒經"]},"6366-a26_083":{"s":"本集續講如來十號的大乘義，配合《心地觀經》三身六德與《楞嚴經》「自覺已圓，能覺他者」。說明應供因佛是無上功德田與報恩田；善逝對應解脫，世間解對應解脫知見，以一水四見與「遍計所起色」說明唯佛真知器世間；調御丈夫、天人師屬覺他；佛號表一切種智；最後引窺基《大乘法苑義林章》把四魔分為分段、變易兩類。","p":["應供：佛是無上功德田與報恩田","善逝對應解脫，世間解對應解脫知見","一水四見說明唯佛如實了知器世間","調御丈夫、天人師屬自覺之後的覺他","四魔分煩惱障、所知障兩類"],"k":["如來十號","五分法身","世間解","遍計所起色","四魔","自覺覺他"]},"6375-a26_084":{"s":"本集講《法華經》〈譬喻品〉華光佛壽十二小劫、授記堅滿菩薩為華足安行佛，以及正法、像法各住三十二小劫。重點解釋「多陀阿伽度」本意為如去，依如來藏常住無來去而立名，並引《楞嚴經》、《大智度論》說明諸法實相即如來藏，藉此反駁琅琊閣「第八識是梵我見」的說法；也解釋阿羅訶、三藐三佛陀兩個名號。","p":["華光佛壽十二小劫，授記堅滿菩薩作佛","多陀阿伽度本意如去，如來亦如去","陰處界皆從如來藏出生，諸法實相即如來藏","反駁琅琊閣「如來藏是梵我」之說","正法、像法各三十二小劫，無末法期"],"k":["多陀阿伽度","如來藏","諸法實相","華光如來","授記","琅琊閣"]},"6384-a26_085":{"s":"本集解說〈譬喻品〉授記舍利弗的重頌，描述華光佛離垢國土與其菩薩眾。由偈中「無上道」比較有上道、無上道、有下道、無下道，批評藏密無上瑜伽雙身法實為與阿鼻地獄相應的無下道，引《楞嚴經》十種魔為證；再引《大般涅槃經》、《楞伽經》、《如來藏經》、《大智度論》說明無上道即依如來藏修證涅槃而成佛。","p":["重頌再述華光佛國土、壽命與正像法","無上道相對於辟支佛、阿羅漢的有上道","批評藏密無上瑜伽為無下道","無上士：佛證涅槃法，為眾生中最上","般若波羅蜜即如來藏，依此成無上道"],"k":["無上道","如來藏","無上士","重頌","破斥藏密","涅槃"]},"6399-a26_086":{"s":"本集講四眾天龍見舍利弗受記而歡喜供養、諸天說偈讚佛「今復轉無上最大法輪」一段。說明同修見同儕受記自知亦有分，入初地即是受記之時；勉勵在彌勒下生前先入內門修六度，於龍華三會成為大阿羅漢再入地，才是善學菩薩道；並說波羅奈初轉法輪只是建立聲聞僧團，菩薩僧團早已存在，駁大乘後出之說。","p":["大眾見舍利弗受記，脫衣供佛、諸天說偈","入初地即被授記，退席五千人無分","彌勒下生前應先入內門修六度","初轉法輪只建立聲聞僧團，菩薩僧團早在","法華甚深奧，少有能信者"],"k":["授記","善學菩薩道","龍華三會","菩薩僧團","初轉法輪","譬喻品"]},"6398-a26_087":{"s":"本集解說諸天偈「於一切世間，最尊無有上；佛道叵思議，方便隨宜說」及迴向佛道。說明過去學佛者多誤以緣起性空、人間佛教為佛法，平實導師提出佛菩提二主要道次第表，標明二道並修與修證次第；再引《不增不減經》、《勝鬘經》說明如來藏不可思議、自性清淨而有染汙、兼具有為與無為，以此批評釋印順、琅琊閣的見解。","p":["大乘非佛說等於否定佛為無上正等正覺","佛菩提二主要道次第表：解脫道與佛菩提道並修","證悟後才知佛道難以言說、叵思議","《不增不減經》：眾生界即如來藏即法身","如來藏自性清淨而有染汙，駁琅琊閣之說"],"k":["佛道叵思議","如來藏","二主要道次第","不增不減經","勝鬘經","琅琊閣"]},"6385-a26_088":{"s":"本集開始講〈譬喻品〉火宅喻：長者宅舍朽壞、四面火起，諸子嬉戲不知出離，長者勸說而子不信受。說明世尊說二乘菩提本意在傳佛菩提，須先斷我見我執才能承認並安忍如來藏，成第七住不退；並以火宅比喻當今佛教界執意識常住、貪著五欲，批評學術界與琅琊閣把佛法分系，違背唯一佛乘、佛佛道同之旨。","p":["諸佛種種方便說法，皆為無上正等正覺","先斷我見我執，才能承認如來藏而不退","觀五陰十八界虛妄，成實義菩薩","火宅諸子喻執意識常住、貪五欲的佛教界","分宗立派、分系研究違背唯一佛乘"],"k":["唯一佛乘","火宅喻","斷我見","如來藏","譬喻品","分宗立派"]},"6395-a26_089":{"s":"本集依《法華經講義》第四輯，講長者以羊車、鹿車、牛車誘子出火宅的經文，並說明三車分喻聲聞、緣覺、佛菩提，大白牛車能載眾生與法寶同出。以平實導師之說解釋三界無安：欲界有火災、初禪被火烤、二禪有水災、三禪有風災，四禪與無色界仍有壽盡的無常火；佛以眾生所好施設方便，引導修學三乘菩提。","p":["羊車、鹿車、大白牛車喻三乘菩提","標點斷句影響經文理解","火、水、風三災對應眾生動而不止","四禪、無色界仍有壽盡無常火","佛隨眾生所好施方便，引入三乘"],"k":["火宅喻","三車","三界無安","三災","大白牛車","方便善巧"]},"6393-a26_090":{"s":"本集講長者等心各賜諸子七寶大白牛車、諸子得未曾有的經文。說明大阿羅漢在佛眼中只是幼童：迴心後熏習般若仍屬六住，證悟才入七住，離妙覺尚遠，佛滅後無阿羅漢敢紹繼佛位；佛無偏黨，迴心即全給大白牛車。大白牛車喻真如佛性第八識如來藏，隨從喻禪定、五根五力、十力等功德，須依如來藏修學，並批評謗阿賴耶識者無信根。","p":["長者等心各賜諸子七寶大車","大阿羅漢在佛眼中只是幼童","阿羅漢迴心證悟僅入第七住","大白牛車喻真如佛性第八識如來藏","僕從喻五根、十力等，須依如來藏修"],"k":["大白牛車","如來藏","阿羅漢與佛","菩薩五十二位","一佛乘","五根"]},"6410-a26_091":{"s":"本集講佛問舍利弗「長者等與諸子珍寶大車，寧有虛妄不」，舍利弗答只要救子出火宅即非虛妄。說明佛度聲聞成阿羅漢後再助其證悟佛菩提即是給大白牛車；證悟後未具佛地功德如幼童看不見全車，不算虛妄；並舉有人只要阿羅漢果不要菩薩法為例，批評古今自稱出離火宅卻仍貪著意識境界與雙身法者。","p":["舍利弗答：救子出火宅即非虛妄","證悟如幼童入車，看不見大白牛車全貌","有人只要羊車、不要大白牛車","大白牛車只是見面禮，佛法寶無量","外道與密宗口說出離，實愛樂火宅"],"k":["火宅喻","大白牛車","方便不虛妄","出離三界","佛菩提","破斥藏密"]},"6416-a26_092":{"s":"本集講「如來亦復如是，則為一切世間之父」一段經文。說明如來直接或間接攝受一切眾生，故為世間之父；並以醉象事件、難陀貪習等說明阿羅漢仍有怖畏、憂患與無明習氣，唯如來永盡無餘，因而成就十力、四無所畏及方便、智波羅蜜；如來為度眾生三毒之火而受生三界，教化眾生證得無上正等正覺，即證無分別法第八識如來藏。","p":["如來直接、間接攝受眾生，為世間之父","醉象衝佛事顯如來無畏、阿羅漢有畏","怖畏、衰惱、憂患、無明唯如來永盡","方便、智波羅蜜於七地、十地圓成","無上正等正覺即證第八識如來藏"],"k":["世間之父","無上正等正覺","如來藏","阿羅漢習氣","十力四無所畏","三毒之火"]},"6422-a26_093":{"s":"本集續解如來大慈大悲常無懈惓的原因：眾生被生老病死、憂悲苦惱燒煮而不自知。舉寒山詩、安世高償命、世尊頭痛三天說明因果不爽，並述追求財利五欲之苦、天人五衰與愛別離、人間貧窮苦及愚癡苦，歸為八苦、三苦、五陰熾盛苦；批評大法師暗修雙身法而不求解脫，勉勵菩薩為正法奮鬥、傳揚正見。","p":["眾生被生老病死、憂悲苦惱燒煮不知","寒山詩、安世高償命說明因果律","天人五衰、愛別離、怨憎會之苦","八苦、三苦歸為五陰熾盛苦","批評名師修雙身法、不求解脫"],"k":["三界火宅","八苦","因果律","大慈大悲","五陰熾盛苦","破斥藏密"]},"6418-a26_094":{"s":"本集先回顧〈序品〉日月燈明佛、妙光菩薩，〈方便品〉一大事因緣與五千退席，以及〈譬喻品〉舍利弗受記，再介紹法華七喻中的火宅喻與三乘歸一乘。接著講經文「我為眾生之父，應拔其苦難」及「若捨方便，眾生不能以是得度」，以孩童只信明日玩具為喻，說明眾生難信遙遠的佛果，故如來須隨根性施設方便。","p":["回顧序品、方便品與舍利弗受記","法華七喻：火宅、窮子、藥草、化城等","三乘歸於一大乘，三乘即一乘","若捨方便只讚佛智，眾生不能得度","隨眾生根性施設方便，引入正道"],"k":["火宅喻","三乘歸一乘","法華七喻","方便善巧","一大事因緣","譬喻品"]},"6425-a26_095":{"s":"本集續講「若捨方便只讚如來知見，眾生不能得度」，以飢餓孩童只需麵包為喻，說明須先以聲聞菩提解決眾生眼前的生老病死憂悲苦惱，取得信任後再引入佛菩提，即「先以欲鉤牽，後令入佛道」。並述正覺同修會先教觀行五陰十八界、斷我見再參禪的次第，平實導師著《阿含正義》以建立信心，也提到世尊初成道欲入涅槃、梵天請轉法輪。","p":["眾生距佛地太遠，須先解決眼前苦","阿羅漢不懂七住明心的非知非不知","先以欲鉤牽，後令入佛道","正覺先斷我見再證悟如來藏，較不退轉","先給羊車讓眾生現世可驗證"],"k":["方便善巧","聲聞菩提","斷我見","火宅三車","阿含正義","如來藏"]},"6420-a26_096":{"s":"本集講「如彼長者，雖復身手有力而不用之」至「乘是三乘以無漏根、力、覺、道…而自娛樂」的經文。說明強拉眾生入涅槃無用，須以智慧方便使其自願出離；批評以聲聞菩提取代佛菩提、主張大乘非佛說者，並引《增壹阿含》聲聞乘、辟支佛乘、佛乘證明阿含已說三乘；再述如來保證、勸勤修精進，並依次教羊車、鹿車、大白牛車的法樂。","p":["強拉入涅槃無用，我執種子會再現行","須以智慧方便令眾生自願出離火宅","《增壹阿含》已說三乘，駁大乘非佛說","如來保證「終不虛也」，勸勤修精進","三乘自在無繫，以根力覺道而自娛樂"],"k":["三乘菩提","方便善巧","大乘非佛說","增壹阿含經","火宅三車","無餘涅槃"]},"6443-a26_097":{"s":"本集解說〈譬喻品〉中三乘行者根性之別：內有智性、自求涅槃者為聲聞乘（求羊車）；求自然慧、樂獨善寂、深知諸法因緣者為辟支佛乘（求鹿車）；求一切智、佛智、自然智、無師智、如來知見及力無所畏，並愍念安樂無量眾生者為大乘摩訶薩（求牛車）。並解釋十因緣、四智與自然智、無師智的意涵，強調菩薩須以大悲利樂眾生。","p":["聲聞乘：內有智性，自求涅槃、自知作證","辟支佛乘：求自然慧，深知十因緣","辟支佛僅推知本識出生名色，未實證","一切智、佛智（四智）、自然智、無師智","大乘須愍念安樂無量眾生，名摩訶薩"],"k":["三乘根性","聲聞乘","辟支佛乘","摩訶薩","一切種智","十因緣"]},"6437-a26_098":{"s":"本集講「如彼長者…等以大車而賜諸子」至「諸佛方便力故，於一佛乘分別說三」的經文。說明本無三乘，因眾生根器怯弱才方便分說；眾生出三界苦後，如來平等給予大乘，以如來滅度而滅度之。並分辨二乘滅度是滅盡五陰十八界，如來滅度則不妨世世受生廣度眾生；大白牛車內已含羊車、鹿車，故長者無虛妄之咎。","p":["本無三乘，為根器差別方便分說","出三界後如來平等給予大乘","以如來滅度而滅度，非僅二乘滅度","大白牛車已含羊車、鹿車，無虛妄","眾生不盡能受，故一佛乘分別說三"],"k":["一佛乘","如來滅度","三乘方便","大白牛車","譬喻品","淨妙第一之樂"]},"6432-a26_099":{"s":"本集接續「初說三乘…然後但以大乘而度脫之」，分辨「不盡能受」與「不能盡受」，指出末法時能受持正法者極少，多數人信位不滿、對三寶缺乏恭敬，甚至主張大乘非佛說，故世尊須如分級教學般施設三乘。接著進入火宅喻偈頌，以大宅久故頓弊喻眾生無量劫輪迴的世間（娑婆即堪忍），並述其中惡禽毒蟲、魑魅夜叉之可怖。","p":["「不盡能受」與「不能盡受」之別","末法能受持正法者如金字塔頂端","三寶名相被世俗化，信心不具足","大宅久故頓弊喻無量劫輪迴的世間","惡禽毒蟲、夜叉鬼魅：其舍恐怖變狀"],"k":["火宅喻","偈頌","娑婆世界","三乘方便","三寶信心","末法"]},"6426-a26_100":{"s":"本集續解火宅偈「其舍恐怖變狀如是」。說明末法是佛法將從此人間消失而非世界末日，並引《俱舍論》說明三千大千世界由一佛教化；指出眾生已在三界堂舍住無量劫，不知窮通壽夭；以「業力共同體」與「變狀」說明六道輪迴非固定，引《楞嚴經》四種顛倒成四生、「生從順習，死從變流」及十習因六交報。","p":["末法指正法將離此人間，非世界末日","三千大千世界的構成，由一佛教化","業力共同體：動物前世也可能是人","「變狀」：六道輪迴並非固定一道","《楞嚴經》四種顛倒成卵胎濕化四生"],"k":["三界火宅","六道輪迴","業力共同體","三千大千世界","楞嚴經","四生"]},"6444-a26_101":{"s":"本集依《楞嚴經》卷8「十習因、六交報」，舉貪物、貪色、貪惑三種重罪為例，說明地獄罪畢後轉為鬼、旁生再回人間的果報次第，並以鐵柱套環比喻無始串習難除。進而呼應〈譬喻品〉「其舍恐怖變狀如是」，指出三界無安、生天亦非永遠，勸人諸惡莫作、眾善奉行，從布施起修六度。","p":["十習因造業、受六根六塵交報之苦","貪物成𩲓鬼→梟類→參合頑類","貪色成魃鬼→咎徵異類；貪惑成魅鬼→狐類","串習如鐵柱層層套環，煩惱難除","三界無安，依如來藏方有盡未來際"],"k":["十習因六交報","楞嚴經","三界火宅","習氣","六度","如來藏"]},"6434-a26_102":{"s":"本集講解〈譬喻品〉偈頌「是朽故宅屬于一人，其人近出未久之間」，說明三千大千世界為一佛所化，佛依眾生得度因緣於各處示現成佛，並在三界火起時出世。再從理、事兩面闡釋「今此三界皆是我有」：理上三界皆自心如來藏所變現；事上以電影《間諜遊戲》為喻，顯示世尊以三大阿僧祇劫福德攝受眾生，等視諸子。","p":["三千大千世界為一佛剎","「近出未久」：依得度因緣他處示現","火宅將起時佛出人間","理上：三界皆自心如來藏所變現","事上：佛以無漏福德攝受，眾生皆佛子"],"k":["今此三界皆是我有","三千大千世界","火宅喻","如來藏","佛子","福德"]},"6462-a26_103":{"s":"本集續講火宅偈頌，以「舍宅忽然火起」喻無常，並批評把佛法說成追求幸福快樂的說法。說明長者以羊車、鹿車、牛車引諸子出火宅，即「先以欲勾牽，後令入佛智」；「空地」一語，二乘指蘊處界空，大乘指如來藏空性。再從理、事解釋「唯我一人能為救護」：理上為如來藏真我救護，事上唯佛能究竟救護。","p":["舍宅火起喻無常，眾生惶怖不能出","先以欲勾牽，後令入佛智","空地：二乘證蘊處界空，大乘證空性","證果後仍須隨佛修學，法無所得","唯我能救護：理為真我，事為諸佛"],"k":["火宅喻","三車","空性","一佛乘","如來藏","方便"]},"6456-a26_104":{"s":"本集講解偈頌「以此譬喻說一佛乘，汝等若能信受是語，一切皆當成得佛道」，強調唯一佛乘以如來藏為法界根本，具圓成實性、非斷非常。節目批評密宗金剛乘、密咒大乘與宗喀巴、釋印順的六識論，並引阿含「意、法因緣生」、如來十力、三蘆相依及嗏帝比丘等經證，說明名色之外另有入胎識、一切種子識。","p":["如來本懷：令一切眾生成佛","批評密咒大乘、金剛乘不如理","如來藏為一切法所依，非斷非常","業種須由第八識執藏，否則無種智","三蘆相依：識在名色之外，為入胎識"],"k":["一佛乘","如來藏","八識論","六識論","識緣名色","一切種智"]},"6448-a26_105":{"s":"本集講解偈頌「是乘微妙清淨第一，於諸世間為無有上」，說明佛法是實證法界實相，非思想或玄學，應恭敬持法法師。述及拈花微笑、教外別傳與玄奘菩薩使禪宗興盛；指出所證心體本來無分別，並非打坐修成，批評宗喀巴止觀。另將佛法與其他宗教、西方邏輯與哲學相比，說其皆不出六識生滅。","p":["一佛乘微妙清淨，是實證非思想","應恭敬持如來藏妙法的善知識","拈花微笑、教外別傳與玄奘之功","心體本來無分別，非打坐修成","他教與哲學皆不出六識生滅之思"],"k":["一佛乘","第八識","無分別","教外別傳","涅槃","六識論"]},"6465-a26_106":{"s":"本集講解偈頌「乘此寶乘直至道場…更無餘乘，除佛方便」，說明十方求之別無他乘，三乘與人天乘皆為佛的方便，批評密教乘及聲聞勝於大乘之說。述玄奘曲女城大會破「大乘非佛說」，並引《中阿含》「如來所依識」、「如來是梵」、《長部》「名色之因稱為識」、《雜阿含》「齊識而還」，說明第八識為本有之法；最後勸人受菩薩戒。","p":["乘寶乘直至道場，十方無餘乘","三乘及人天乘皆是佛的方便","玄奘曲女城大會破大乘非佛說","帝釋、自在天求如來所依識不能得","識為名色之因，齊識而還；勸受菩薩戒"],"k":["一佛乘","方便","第八識","大乘是佛說","菩薩戒","玄奘"]},"6458-a26_107":{"s":"本集講解偈頌「汝諸人等，皆是吾子…所化眾生皆是菩薩」，說明二乘只盡分段生死，佛以化城喻方便說三乘，究竟都歸一佛乘。引《大薩遮尼乾子所說經》、《楞伽經》、《央掘魔羅經》等，說明如來藏不同外道神我、能取所取皆空、無我法中有真我，並指出謗法罪重於殺佛，如來視一切眾生如同一子。","p":["二乘但盡分段生死，實不滅度","化城喻：方便說三乘，歸一佛乘","大般涅槃即實相心本自涅槃","如來藏離能取所取，無我中有真我","謗法罪重；佛視眾生猶如一子"],"k":["一佛乘","化城喻","如來藏","大般涅槃","無我","謗法"]},"6460-a26_108":{"s":"本集講解偈頌「若人小智深著愛欲，為此等故說於苦諦」，說明佛為小智眾生方便說四聖諦，教其斷我見、滅貪愛而得二乘解脫。進而指出四聖諦皆不離如，滅諦即心體本來寂滅；引〈如來壽量品〉塵點劫之喻，說法身無垢識常住不滅。並批評應成派、自續派中觀，強調發菩提心、護持正法、如教修行。","p":["為小智眾生方便說苦集滅道","行苦與意識生滅，應斷我見","大乘四聖諦皆不離如","如來壽量久遠，法身無垢識常住","護持正法須臾，功德超淨土一劫"],"k":["四聖諦","方便","法身","真如","如來壽量","護持正法"]},"6480-a26_109":{"s":"本集開始依《法華經講義》第五輯講〈譬喻品〉，先介紹天台五時判教（講者認為般若與方等應互換）及導師講《法華經》的緣起。接著解釋「但離虛妄名為解脫」，指解脫是遠離我見、我執、我所執，阿羅漢習氣仍在，未得一切解脫；並說「我為法王於法自在，安隱眾生」，批評喇嘛自稱法王及密宗雙身法。","p":["天台五時判教，般若方等應互換","解脫即遠離我見、我執、我所執","阿羅漢習氣尚存，未得一切解脫","於法自在方稱法王，批喇嘛自稱","密宗被內外火所燒，不能安隱眾生"],"k":["譬喻品","解脫","阿羅漢","法王","五時三教","密宗"]},"6470-a26_110":{"s":"本集講解〈譬喻品〉「在所遊方勿妄宣傳」，說明此經只為菩薩子說，故五千聲聞凡夫退席時佛未阻止。以「諸子生育甚難」說明十信須一劫至萬劫方生菩薩性，再以六度養育，並把住、行、向位比作年歲。接著解釋「隨喜頂受，當知是人阿鞞跋致」，分述信不退、住不退、位不退、行不退、念不退、究竟不退。","p":["法華妙法只為菩薩子說，勿妄宣傳","十信一劫至萬劫，菩薩子生育甚難","以六度養育；六住如六歲","十迴向滿心如三十歲，可付如來家業","阿鞞跋致不退有多種層次"],"k":["阿鞞跋致","菩薩種性","十信位","六度","五十二位"]},"6474-a26_111":{"s":"本集續講〈譬喻品〉，說明能信受此經的人往昔已曾見佛、聽聞此經，因此修道應重道情過於親情，也不應輕視其他老師。接著講「斯法華經為深智說」，聲聞、辟支佛力所不及，舍利弗也是以信得入。再說明佛囑咐不要對憍慢、懈怠、計我見三種人說此經，並批評「大乘非佛說」的主張。","p":["信受此經者往昔已見佛、聞是法","道情遠勝親情，依法抉擇","勿輕視他班老師，或為往世師","法華為深智說，二乘力所不及","憍慢、懈怠、計我見者莫說此經"],"k":["譬喻品","信受","深智","我見","大乘非佛說"]},"6481-a26_112":{"s":"本集講解「凡夫淺識深著五欲，聞不能解亦勿為說」及「若人不信毀謗此經，則斷一切世間佛種」。講者批評某老法師主張大乘非佛說，並把淨土說成太陽神崇拜，認為這是斷人佛種；也提到佛世時五千人退席，而彌勒佛時不會有人誹謗。並說明謗經者「輕賤憎嫉而懷結恨」，命終入阿鼻地獄無數劫，再經餓鬼道轉入畜生道。","p":["凡夫淺識深著五欲，勿為說此經","大乘非佛說即斷一切世間佛種","彌勒佛時人壽八萬四千歲不謗","謗者輕賤憎嫉持經人而懷結恨","入阿鼻獄無數劫，再轉餓鬼畜生"],"k":["謗法","斷佛種","大乘非佛說","阿鼻地獄","六識論"]},"6472-a26_113":{"s":"本集續講謗經罪報：從地獄、餓鬼出後生為狗、野干一類，身形枯瘦、疥癩，常困飢渴，生受楚毒、死被瓦石，皆因「斷佛種故」。講者批評「佛即阿羅漢」及七、八識為部派創造的說法，認為其中自相矛盾；並強調菩薩應以悲憫說明六識論的過失，救護謗法者懺悔回歸，而不是詛咒他們。","p":["謗經者轉生狗、野干，枯瘦疥癩","生受楚毒死被瓦石，斷佛種故","批「佛即阿羅漢」與部派造經說","應以悲心說明六識論過失救護之","弘法目的在提升知見，不在斂財"],"k":["斷佛種","謗法","六識論","八識論","大悲","畜生道"]},"6476-a26_114":{"s":"本集講解〈譬喻品〉誹謗大乘法的正報與花報：謗經者出地獄、餓鬼後生為駱駝、驢、馬，負重挨打，只念水草；或為疥癩獨眼的野干，再受五百由旬大蟒身，被小蟲唼食。若得為人則諸根闇鈍、身形矬陋，說話無人信受，口臭而鬼魅所著，貧窮多病，行醫反增他疾，自病服良藥反增劇。","p":["生駝驢負重挨打，但念水草","野干疥癩獨眼，被童子打擲","受蟒身五百由旬，小蟲唼食","為人諸根闇鈍、矬陋，言不見信","口臭鬼魅所著，貧病、醫藥反劇"],"k":["正報花報","謗法","畜生道","異熟果報","譬喻品"]},"6496-a26_115":{"s":"本集續講謗經罪報：橫遭反逆、抄劫等罪殃，永不見佛，常生難處、狂聾心亂不聞法，常處地獄如遊園觀；為人則聾盲瘖瘂、病苦纏身。接著就「深著我見增益瞋恚」，說明謗大乘者必我見深重，並解釋我見即認意識常住，分為斷續分別我見與俱生我見，須現觀識陰六識由根、塵、觸三緣所生。","p":["橫羅其殃、永不見佛、常生難處","常處地獄如遊園觀，惡道如舍宅","為人聾盲瘖瘂，以疾病為衣服","謗大乘者必我見深重","我見分斷續分別與俱生；觀識陰虛妄"],"k":["我見","識陰","謗法","正報花報","斷我見","一闡提"]},"6503-a26_116":{"s":"本集續論識陰：引《雜阿含》說執取識陰境界即具足我所貪愛，並指意識雖虛妄，亦能熏習正法、證悟第八識。引《入楞伽經》「如來藏阿梨耶識共七識生」，說明轉相與二法。講者批評宗喀巴主張意識結生相續、某法師立「意識細心常住」，又以「婬欲熾盛不擇禽獸」指密宗雙身法；最後總結謗經罪窮劫不盡，無智人中莫說此經。","p":["執取識陰境界即具我所貪愛","意識亦能熏習正法、證第八識","如來藏阿梨耶識與七識俱生","批意識結生相續、細心常住之說","婬欲熾盛指雙身法；無智人莫說"],"k":["識陰","如來藏","阿賴耶識","我見","見取見","密宗"]},"6500-a26_117":{"s":"本集講解〈譬喻品〉佛說可為演說此經的十種人中，前四種：利根多聞強識求佛道者、曾見億百千佛深心堅固者、精進常修慈心不惜身命者、恭敬無異心獨處山澤者（在家指不攀緣）。接著講後六種中的前兩種：捨惡知識、親近善友者，以及持戒清潔如明珠、專求大乘經者；並說明十信位修行須一劫至一萬大劫。","p":["利根多聞強識求佛道者可為說","曾見億百千佛、深心堅固者","精進修慈心、不惜身命者","恭敬無異心、獨處山澤不攀緣者","捨惡知識親近善友；持戒求大乘經者"],"k":["十種人","譬喻品","多聞","善知識","持戒","十信位"]},"6494-a26_118":{"s":"本集續講可為說《法華經》的六種人中的後四種：無瞋質直柔軟、常愍一切恭敬諸佛者；於大眾中以清淨心、譬喻言辭說法無礙者；比丘為求一切智而四方求法、但樂大乘經者；以及如求佛舍利般求經頂受、不求餘經與外道典籍者。中間引《心地觀經》說菩薩僧、聲聞僧、凡夫僧三種僧，並批評「出家人不可向居士學法」的觀念。","p":["否定大乘者心曲，求大乘者心直","無瞋質直柔軟、恭敬諸佛者","說法無礙者；為一切智但樂大乘者","三種僧：菩薩僧、聲聞僧、凡夫僧","求經如求舍利；肉身舍利與法舍利"],"k":["十種人","一切種智","三種僧","法舍利","大乘經典"]},"6505-a26_119":{"s":"本集開始講〈信解品〉：須菩提、迦旃延、迦葉、目犍連四大弟子聽聞舍利弗受記，歡喜踊躍而欲說譬喻。講者說明此品主旨在於對佛菩提道生起信解極難，阿羅漢得授記後信心具足，才願起惑潤生；並說明「解」分聞解、思解、修解、證解，知道密意不等於開悟，不可洩漏密意。","p":["四大弟子聞舍利弗授記而歡喜","對佛菩提道生起信解極為困難","信具足方願起惑潤生行菩薩道","解有聞解、思解、修解、證解","知密意非開悟，洩密意為大惡業"],"k":["信解品","授記","起惑潤生","證解","密意","能取所取空"]},"6501-a26_120":{"s":"本集續講〈信解品〉的修證次第：十行位滿心有陽焰觀；如夢觀須先有眼見佛性的如幻觀、陽焰觀，並具滿證初禪以上與頂級三果。入地三條件為大福德、三種現觀與永伏性障，再發十無盡願。接著解說經文中四大弟子整衣、偏袒右肩、胡跪合掌的行儀與問訊的本義，以及迦葉代眾稟白的內容。","p":["十行滿心現觀七轉識如陽焰","如夢觀須如幻觀、陽焰觀與禪定","入地：大福德、三現觀、永伏性障","發十無盡願增上意樂方入初地","偏袒右肩、胡跪合掌與問訊本義"],"k":["信解品","如夢觀","陽焰觀","如幻觀","入地","十無盡願"]},"6523-a26_121":{"s":"本集續講〈信解品〉大迦葉稟白「我等居僧之首，年並朽邁；自謂已得涅槃」一段，說明大阿羅漢灰心泯智、聽方廣唯識經疲懈而住空無相無作三昧、對菩薩法心不喜樂的心境；並解釋聽聞聲聞得授記為何「心甚歡喜，得未曾有」，以及授記成佛須具備的條件。","p":["阿羅漢入涅槃作意，故灰心泯智、無心世間","「自謂已得涅槃」：實未知無餘涅槃中是如來藏","聽不懂唯識經而身體疲懈，安住三三昧","批評學者以聲聞結集文獻判斷大乘經","授記為希有之法，須道種智、解脫果與福德"],"k":["信解品","授記","阿羅漢心境","空無相無作三昧","本來自性清淨涅槃","大乘經結集"]},"6515-a26_122":{"s":"本集講解〈信解品〉大阿羅漢知自己亦將被授記而歡喜「無量珍寶不求自得」，並開始大迦葉所說窮子喻：幼年走失的兒子流浪五十年，輾轉來到富甲一方的父親宅舍門外，見長者踞師子床、威德特尊而心生恐懼想逃。逐句解說師子床、寶几承足、白拂、寶帳、華幡、出內取與等經文。","p":["聽聞舍利弗授記，生起增上意樂","大迦葉以譬喻說明授記時節之理，為未悟者說","長者富有、日夜思念走失之子","窮子遙見長者威德，恐被逼迫而欲逃","解說高廣大床與菩薩戒之關係"],"k":["窮子喻","信解品","授記","高廣大床","菩薩戒"]},"6520-a26_123":{"s":"本集續講窮子喻：窮子「疾走而去」反被長者認出，遣人強拉回來，窮子驚怖悶絕，長者知其志意下劣，遂放他離去。講者以此譬喻大阿羅漢以為大乘法是菩薩的事、聽不進去，並對照現今佛教界不信可斷我見、證如來藏的現象，說明攝受眾生須經磨練、待因緣成熟而不強求。","p":["窮子疾走被認出，強牽回而悶絕倒地","長者知子心劣，方便放他「隨意所趣」","世俗人顛倒，以凶事辦喜事","喻阿羅漢及今日佛教界不信能斷我見","度眾先傳播正知見，待緣熟不勉強"],"k":["窮子喻","信解品","方便攝受","斷我見","善根成熟"]},"6517-a26_124":{"s":"本集從〈方便品〉佛說一大事因緣及往昔於二萬億佛所教化舍利弗談起，講述釋迦佛因地為海濟婆羅門時所發大悲願：不以願力取土，而以六波羅蜜攝度五濁惡世難化眾生；並舉慈力王以身血施五夜叉、設頭羅健寧王化大魚、羼提波梨仙人受割截等本生，說明憍陳如五比丘最先得度的因緣。","p":["諸佛唯以一大事因緣出現於世","海濟婆羅門發願於五濁惡世以六度攝眾","對比阿彌陀佛以願力取度眾生","慈力王、大魚、忍辱仙人本生度憍陳如等","應信無數劫來受釋迦佛攝受培植善根"],"k":["大悲願","本生故事","六波羅蜜","憍陳如","一佛乘","五濁惡世"]},"6525-a26_125":{"s":"本集探討「二乘窮子成為佛子之信解」：先回顧火宅三車喻，再完整敘述大迦葉窮子喻中長者換穿粗衣、以四攝法接近窮子、令其除糞二十年、掌管寶藏、臨終宣布父子關係的過程。引《大寶積經》說明大迦葉信佛具足卻不信自己能作佛，並辨聲聞與如來真實佛子之別。","p":["火宅三車喻：以一佛乘分別說三","長者以布施愛語利行同事攝窮子","窮子經手寶藏仍不捨下劣心","大迦葉自謂退於無上菩提，即窮子心境","往來生死利益眾生的菩薩方為真實佛子"],"k":["窮子喻","信解","四攝法","真實佛子","如來藏","大寶積經"]},"6521-a26_126":{"s":"本集講解〈信解品〉「蠲除諸法戲論之糞，得至涅槃一日之價」，說明二乘涅槃只是佛法寶藏的一日之價、是入佛道的方便門。引《大法鼓經》大迦葉僅願護法四十年而被佛訶責之事，並依實相法與虛相法、《大般若經》菩提五義，解釋為何二乘菩提稱為小法。","p":["解脫果僅是入佛道的方便門","《大法鼓經》大迦葉願護法四十年被訶","斷我見我執如除戲論之糞","虛相法無我空與實相法無我空之別","二乘菩提未及真如、實際、法界等義故為小法"],"k":["一日之價","除糞喻","二乘涅槃","實相法","諸法戲論","大法鼓經"]},"6531-a26_127":{"s":"本集探討佛陀以二乘為教化佛子的方便門。引《菩薩瓔珞本業經》說明六住入七住須善知識護念，舉舍利弗六十劫行菩薩道進退、因乞眼事件迴小向大；講者並以正覺同修會四次退轉事件為例。後引《首楞嚴三昧經》四種授記及華光開敷遍身佛之語，說明大迦葉「我等不知真是佛子」之意。","p":["七住不退須值善知識護念","舍利弗六十劫進退，因乞眼退向小乘","菩薩道兩難：遠離惡友、無求攝眾","大迦葉聞未發心授記，於眾生生世尊想","諸佛常以方便分別說三乘"],"k":["方便門","七住不退","舍利弗","授記","真實佛子","退轉"]},"6543-a26_128":{"s":"本集講解大迦葉所說「世尊於佛智慧無所吝惜」，說明佛實以大乘教化聲聞，二乘修道次第亦是菩薩法。以信行為例，比較菩薩直接信入佛知見（如來藏無色受想行識、一切法空）與二乘依四聖諦修學之別，並引《雜阿含經》甚深緣起經文，論證涅槃本際即如來藏，非斷滅空。","p":["佛於菩薩前毀呰聲聞，實以大乘教化","聲聞緣覺所行亦是菩薩法","菩薩信入如來藏無色受想行識之佛知見","四聖諦滅諦之本際即如來藏","甚深緣起指能藉緣現起者，涅槃非斷滅"],"k":["佛智慧","四聖諦","如來藏","甚深緣起","無餘涅槃","大乘非佛說"]},"6539-a26_129":{"s":"本集進入〈信解品〉，說明對佛菩提生起信解之難，大迦葉以長者窮子喻比喻世尊對他們的方便攝受。並探討佛法是有我還是無我：引《父子合集經》外道之問，及《大般涅槃經》佛以乳母餵嬰為喻，說明佛先說無常無我，待弟子堪任再說常樂我淨，以煩惱為薪、智慧為火煮成「涅槃飯」。","p":["阿羅漢未滿六住福德，聞授記方信心具足","長者換破衣、執除糞器方便接近窮子","初轉說無我，二轉以實相心說第一義諦","如餵嬰兒，依根器次第給予法味","涅槃飯之真米即第八識如來藏"],"k":["涅槃飯","信解品","常樂我淨","無我","如來藏","大般涅槃經"]},"6533-a26_130":{"s":"本集續講〈信解品〉除糞之喻，說明學人須先除貪瞋癡等染汙心性，再修參禪功夫，並說阿羅漢因心中無貪而無意承接法寶，佛至《法華經》才總結點交。舉《菩薩瓔珞經》五千正士退席、勇智菩薩往昔為忘恩獅子王被木雀啄眼的故事，說明不信如來三身、誹謗正法的惡種子難以得度。","p":["除糞喻：先除染汙心性再修參禪","阿羅漢心無貪，佛以方便漸轉其心量","五千正士退席不聽如來三身法要","獅子王忘恩、木雀啄眼之本生","誹謗正法惡種子須懺悔方能根除"],"k":["如來三身","除糞喻","菩薩瓔珞經","如來藏","誹謗正法","懺悔"]},"6545-a26_131":{"s":"本集依《大乘本生心地觀經》說明前佛後佛皆依如來寶藏識成佛，並解說佛地四智圓明：轉異熟識成大圓鏡智、轉末那成平等性智、轉意識成妙觀察智、轉前五識成成所作智。再述佛三轉法輪次第轉化阿羅漢心量，並解釋大迦葉「一切諸法皆悉空寂，無生無滅，無大無小，無漏無為」之意。","p":["諸佛皆依根本識如來寶藏識成就","四智圓明為自受用報身","第八識是聚寶盆，人人本具而不知","佛訶不迴心二乘為焦芽敗種","依如來藏現觀一切法無生無滅"],"k":["四智圓明","如來三身","如來藏","三轉法輪","焦芽敗種"]},"6541-a26_132":{"s":"本集從大迦葉說「一切諸法皆悉空寂無生無滅」談起，指出阿羅漢不否定第八識，否定者無法斷我見。引《六度集經》蝨子報恩故事，說明供養持戒比丘勝過供養凡夫；再引《楞伽經》說如來藏不同外道神我，並分辨聲聞依蘊處界的空、無相、無願三昧，與大乘依如來藏的解脫三三昧。","p":["否定第八識者必有內外恐怖，不能證果","蝨子報恩僅供養七日，喻凡夫心量","供養持戒比丘功德勝於凡庶","如來藏不同外道所說之我","聲聞三三昧為表相，依如來藏三三昧為本"],"k":["解脫三三昧","如來藏","第八識","楞伽經","外道神我","六度集經"]},"6547-a26_133":{"s":"本集續引《楞伽經》說如來藏又名離自性、不生不滅、本來寂靜、自性涅槃，並說佛為斷愚夫畏無我句而說離妄想如來藏門，不同神我、梵我。後講〈信解品〉大迦葉「於無漏法得清淨眼」「法王法中久修梵行，今得無漏無上大果」及「世尊大恩，無量億劫誰能報者」，說明二乘與大乘法眼淨之別及佛恩難報。","p":["涅槃是真如別名，非斷滅空無","如來藏離自性、本來寂靜、自性涅槃","佛說如來藏，令外道離我見入三解脫門","大乘清淨眼指入地，阿羅漢只欠十無盡願","證量愈高愈知佛恩無量難報"],"k":["如來藏","自性涅槃","法眼淨","佛恩","信解品","楞伽經"]},"6564-a26_134":{"s":"本集開始「勝難希有不可思議諸佛」主題，說明眾生不敬佛或妄稱成佛，是因不了解成佛須三大阿僧祇劫。從時間角度引《長阿含經》說佛出世如優曇缽華難遇；再以命濁、眾生濁、煩惱濁、見濁、劫濁五濁說明釋迦佛於娑婆成佛之難，並在見濁中批評藏密喇嘛教雙身法。","p":["不知成佛歷程，故妄稱成佛造大妄語","佛難值遇如優曇缽華，賢劫釋迦為第四佛","命濁、眾生濁、煩惱濁之相","見濁：批評雙身法非佛法","劫濁：刀兵、疾疫、飢饉"],"k":["五濁惡世","諸佛希有","優曇缽華","大妄語","雙身法批判"]},"6559-a26_135":{"s":"本集續講「勝難希有不可思議諸佛」，以佛菩提道五十二位階說明成佛之難：分遠、近、大、圓滿四種波羅蜜多，詳述十信、十住六度修集、六住斷我見、四加行到七住明心，再說十住眼見佛性成就如幻觀、十行陽焰觀、十迴向如夢觀，並提及十迴向應進修的唯識增上慧學。","p":["成佛須經五十二位、十種現觀、三種意生身","批評即身成佛之說，強調次第實修","六住斷我見，七住證悟本來自性清淨涅槃","十住眼見佛性成就世界如幻觀","十行陽焰觀、十迴向如夢觀"],"k":["五十二位階","十種現觀","如幻觀","陽焰觀","如夢觀","眼見佛性"]},"6551-a26_136":{"s":"本集續講菩薩修證歷程：如夢觀須先發起初禪、於定中夢中相應過去世修行，以對治意根遍計執、性障永伏如阿羅漢。三種現觀圓滿並具增上慧學、十無盡願，加上諸佛加持得大乘照明三昧而入初地；再說初地鏡像觀、二地光影觀與持戒、三地修四禪八定成就谷響觀及無漏妙定意生身。","p":["如夢觀須初禪證量，對治意根染汙","三種現觀圓滿發起聖種性","入地須增上慧學、十無盡願、諸佛加持","初地鏡像觀、二地光影觀與持戒","三地修禪定神通，成谷響觀與意生身"],"k":["十種現觀","如夢觀","初地","意根","鏡像觀","意生身"]},"6565-a26_137":{"s":"本集續講三地滿心無漏妙定意生身可破隔陰之迷，並以此批評喇嘛教活佛認證之說。接著解說谷響觀、四地依大乘安立諦十六品心細觀四聖諦並成就水中月觀、五地以無生法忍觀十二因緣而成變化所成觀，以及六地細觀十二有支成似有非有觀，自然證滅盡定成俱解脫大乘無學。","p":["三地滿心意生身無隔陰之迷","批評活佛轉世認證之說","四地觀安立諦十六品心，成水中月觀","五地斷下乘涅槃貪，成變化所成觀","六地似有非有觀，不由加行證滅盡定"],"k":["十種現觀","意生身","隔陰之迷","四聖諦十六品心","十二因緣","滅盡定"]},"6560-a26_138":{"s":"本集講完菩薩道後段：七地念念入滅盡定，佛授引發如來無量妙智三昧，成犍闥婆城觀；八地於相於土自在並專修願波羅蜜，九地修四無礙辯成善慧地，十地受十方諸佛灌頂成法雲地受職菩薩，等覺百劫修相好，妙覺待緣下生成佛。最後略述佛地四智、十力等功德，勸勿妄稱成佛。","p":["七地念念入滅盡定，佛授妙智三昧","八地相土自在，證三種意生身","九地法、義、詞、樂說四無礙辯","十地受職灌頂為法王子","等覺百劫修相好，妙覺待緣成佛"],"k":["菩薩十地","等覺妙覺","四無礙辯","意生身","四智圓明","諸佛希有"]},"6567-a26_139":{"s":"本集開始「唯一佛乘」主題，引〈方便品〉三世諸佛皆以一佛乘說法、究竟得一切種智，說明三乘皆依如來藏方便建立。再講〈藥草喻品〉「如來說法一相一味，所謂解脫相、離相、滅相」，指阿含之名即顯成佛之道；並以誦經、稱佛名、老人喊「南無佛」得出家因緣為例，說明受持讀誦有功德而自不覺知。","p":["佛以一佛乘析分三乘應眾生根性","一切種智為成佛必備，依如來藏證知","一相一味即解脫相、離相、滅相","阿含意為成佛之道，然未說悟入如來藏","受持讀誦經典功德自不覺知"],"k":["一佛乘","一切種智","一相一味","藥草喻品","如來藏","阿含"]},"6576-a26_140":{"s":"本集續講〈藥草喻品〉，解釋如來知一相一味之法終歸於空，觀眾生心欲而將護之，故不即說一切種智；說明眾生根性因緣不同，如來無所不知，猶如卉木藥草不自知上中下性。並述佛先令人證阿羅漢以建立信心，再漸說般若；最後解說「破有法王出現世間」偈中大雲普雨之喻。","p":["佛觀眾生心欲將護，不即說一切種智","眾生念思修各異，唯如來如實照見","一切種智即如來藏所含種子之圓滿證知","先令證阿羅漢建立信心再漸說深法","大雲普雨喻佛法平等滋潤眾生"],"k":["藥草喻品","一相一味","一切種智","隨宜說法","大雲喻","根性差別"]},"6579-a26_141":{"s":"本集續講〈藥草喻品〉偈頌，說明「破有法王出現世間，隨眾生欲種種說法」：佛陀出世專破外道落於三界有的假阿羅漢，並因如來尊重、智慧深遠而「久默斯要」，隨眾生根力說法。再以大雲普雨之喻，配合五時三教（華嚴、阿含、般若、唯識種智、法華）說明法雨普潤三乘根性。","p":["佛為破有法王，專破落於三界有的外道","隨眾生欲先說解脫，久默斯要不務速說","有智聞則信解，無智疑悔則永失","大雲慧雨普潤卉木藥草大小諸樹","以五時三教說明如來次第施設法雨"],"k":["破有法王","藥草喻","五時三教","三乘菩提","如來藏"]},"6568-a26_142":{"s":"本集講解偈頌「其雲所出一味之水，草木叢林隨分受潤」至「常為大乘而作因緣」，說明佛如大雲以一味法雨平等普潤，眾生隨根器各得生長。重點闡釋「諸法之實」：以五陰非無因生、自生、共生、他生，推知其由如來藏所生，緣起性空不是如來出世本懷；並批評「開悟者不應自稱開悟」之說。","p":["一味之雨隨草木大小各得滋茂","佛出世為眾生分別演說諸法之實","五陰不能自生、他生、共生、無因生","五陰由各自如來藏所生，上帝亦然","緣起性空非佛本懷；批評開悟不可自稱之說"],"k":["諸法之實","如來藏","緣起性空","一味法雨","藥草喻","五陰"]},"6578-a26_143":{"s":"本集續講「我為如來兩足之尊」及「為大眾說甘露淨法，其法一味解脫涅槃」等偈，說明如來宣示自身證量是為利益人天、防止眾生誹謗造業。講解甘露淨法之義，指佛法只有二乘菩提與佛菩提兩大甘露法門，並批評藏密明光大手印、雙修及所謂甘露；強調如來本懷是唯一佛乘而非緣起性空。","p":["阿羅漢、如來宣示證量是隨俗利眾","佛為福慧兩足尊，令得世間樂及涅槃樂","批評藏密以一念不生為成佛、雙修為法","甘露喻清淨法，佛法只有兩大甘露法門","其法一味指佛地解脫涅槃，本懷唯一佛乘"],"k":["甘露淨法","唯一佛乘","兩足尊","解脫涅槃","破斥密宗"]},"6581-a26_144":{"s":"本集開講〈藥草喻品〉偈頌「我觀一切普皆平等」至「釋梵諸王是小藥草」（講義第七輯第31頁起），說明如來無愛憎、無限礙，恆為一切眾生平等說法。指出平等法即一切有情同具的第八識如來藏，緣起性空不是平等法；眾生隨根性領受不同，並以人天、轉輪聖王、釋梵諸王為小藥草。","p":["如來觀眾生平等，本意令一切人成佛","批評大乘非佛說，阿含僅記大乘名相","佛說法不限聽眾，四眾隨根領受","平等法是如來藏，非緣起性空","人天、輪王、釋梵諸王為小藥草"],"k":["藥草喻品","平等說法","如來藏","小藥草","大乘非佛說"]},"6587-a26_145":{"s":"本集講解〈藥草喻品〉偈頌「知無漏法能得涅槃」至「如彼草木所稟各異」，界定其餘四類聞法根性：證涅槃、三明六通及緣覺果者為中藥草，發願作佛並行精進定者為上藥草，專心佛道、常行慈悲至三地滿心前者為小樹，能起意生身、安住神通轉不退輪者為大樹。並說明阿含經典是聲聞人依自身稟性結集，勉勵擴大心量、護持正法修集福德。","p":["阿羅漢乃至緣覺聖者皆屬中藥草","求作佛且有定心所、精進不退為上藥草","證悟至三地滿心前常行慈悲為小樹","三地滿心起意生身度眾者為大樹","聲聞結集大乘經成阿含；護法修福"],"k":["藥草喻品","三草二木","大樹菩薩","意生身","菩薩種姓","護持正法"]},"6603-a26_146":{"s":"本集講解偈頌「佛以此喻方便開示」至「是名小樹而得增長」（講義第七輯第66頁起），說明佛以種種言辭只演說佛菩提一法。引《大薩遮尼乾子所說經》指三乘之說是示地、法相、人之差別而非乘差別；強調法隨法行、漸次修行皆得道果，並說明聲聞緣覺聞法得果、證悟後智慧堅固的小樹菩薩如何增長。","p":["佛所說法如海一渧，只是唯一佛乘","三乘是地、法相、人之別，非乘差別","法隨法行，一味之法隨力修行","五乘法皆須漸次修行方得道果","七住至三地滿心前智慧堅固為小樹"],"k":["唯一佛乘","法隨法行","藥草喻品","漸次修行","小樹","如來藏"]},"6600-a26_147":{"s":"本集講解偈頌「復有住禪得神通力，聞諸法空心大歡喜」至「潤於人華各得成實」（講義第七輯第84頁起），說明三地滿心菩薩以無生法忍、道種智成就猶如谷響現觀並起意生身，成為能住持十方佛法的大樹。並引《瑜伽師地論》勸對甚深法先信受不誹謗，檢討三草二木的成就條件，勉勵由上藥草轉為小樹、謹言慎行。","p":["三地滿心成猶如谷響現觀，名為大樹","大樹菩薩能以化身度十方眾生","對未證甚深法應仰推如來、不誹謗","錯誤的二乘法如毒草，非中藥草","小樹勿自滿，業種皆存於如來藏"],"k":["藥草喻品","大樹菩薩","三地滿心","意生身","菩薩性","如來藏"]},"6588-a26_148":{"s":"本集講解〈藥草喻品〉偈頌結尾「今為汝等說最實事：諸聲聞眾皆非滅度；汝等所行是菩薩道，漸漸修學悉當成佛」（講義第七輯第104頁起）。說明三乘是方便施設、本唯一佛乘，引《不退轉法輪經》指釋迦佛因娑婆眾生下劣而分別說三、引入一乘；並總結五種根性，強調依止諸佛與善知識，如來本懷是佛地究竟解脫。","p":["種種因緣譬喻開示佛道皆是方便","聲聞所證非真滅度，所行是菩薩道","引《不退轉法輪經》說分別說三、引入一乘","佛法不演變，三乘根源同一如來藏","二乘解脫是化城，佛地解脫方究竟"],"k":["唯一佛乘","藥草喻品","三乘方便","化城","發菩提心","究竟解脫"]},"6605-a26_149":{"s":"本集以專題方式說明《法華經》所標示的佛教正法即是成佛之法：引「十方佛土中，唯有一乘法」指二乘是方便、須附屬於佛菩提方為佛法，大乘法依涅槃如來藏而說，並批評「大乘非佛說」為謗佛謗法。後段引〈藥王菩薩本事品〉、〈普賢菩薩勸發品〉及印光大師語，介紹聞持《法華經》的功德與感應事例。","p":["佛法分世間、出世間、世出世間法","十方佛土唯一乘法，二乘是方便化城","以〈正覺總持咒〉檢驗說法是否圓滿","大乘依如來藏，因果須如來藏執行","聞持《法華經》一偈一句功德無量"],"k":["唯一佛乘","大乘非佛說","涅槃如來藏","成佛之道","法華功德"]},"6602-a26_150":{"s":"本集說明《法華經》標明行菩薩道者會被授記成佛：從五千增上慢人退席談起，列舉四大弟子授記名號及《法華論》所說六種授記。闡釋「為實施權、開權顯實」，以三車與化城之喻說明會三歸一、勸二乘迴小向大，並強調大乘因果法則與一切眾生皆有佛性；最後講述兩則《法華經》感應故事。","p":["五千增上慢人退席，不堪授記","四大弟子授記名號與六種授記","為實施權、開權顯實，會三歸一","二乘止於化城，佛勸迴小向大","眾生皆有佛性；法華感應事例"],"k":["授記","開權顯實","化城喻","迴小向大","佛性"]},"6616-a27_001":{"s":"本集進入〈授記品〉大目犍連授記段落，先回顧迦葉、須菩提、迦旃延三人的授記，再介紹大目犍連的過往。引《如來不思議祕密大乘經》目犍連度量佛音至光明幢世界的事蹟、《大智度論》鴿入佛影與舍利弗影之事，說明阿羅漢神通遠不及佛；並以琉璃王滅釋迦族、目犍連被執杖梵志打死，說明神通敵不過業力、菩薩畏因。","p":["佛先授記迦葉、須菩提、迦旃延","目犍連測佛音聲，至光明幢世界而懺悔","鴿入舍利弗影仍恐懼，因三毒習氣未盡","琉璃王滅釋迦族，神通敵不過業力","目犍連臨終償宿債；菩薩畏因"],"k":["授記品","大目犍連","神通","業力","習氣種子","菩薩畏因"]},"6627-a27_002":{"s":"本集講解〈授記品〉世尊為大目犍連授記的長行經文：先供養八千佛、再供養二百萬億佛後成佛，號多摩羅跋栴檀香如來。引《舊雜譬喻經》說明目犍連因道眼見八千佛世界起慢，故須先供養八千佛以消慢心，並勸菩薩不宜過早修神通；接著解說佛十號中的「應供」與「正遍知」，佐以拔提布施燋木、舍利弗教錯觀法等事例。","p":["目犍連授記：號多摩羅跋栴檀香如來","因見八千佛世界起慢，須先供養八千佛","菩薩宜至三地將滿心時修禪定神通","應供：供佛福德無量，應迴向求解脫成佛","正遍知：佛知眾生根性而因材施教"],"k":["授記品","大目犍連","如來十號","慢心","神通","布施迴向"]},"6631-a27_003":{"s":"本集續講如來十號，依序解說明行足、善逝、世間解、無上士、調御丈夫、天人師、佛、世尊的意涵，引苦得外道死後為食吐鬼、地神聞法證初果等事例，並批評主張上師勝佛者為大妄語。最後講解大目犍連授記的重頌，指出佛國淨土與成佛者的願力及相應有情有關，舉目犍連國多三明六通聲聞、迦旃延國無阿修羅為例。","p":["明行足、善逝：佛知眾生死因與去向","世間解：了知五陰世間及器世間","無上士、調御丈夫、天人師之義","佛為三覺圓滿者，世尊為凡聖所尊","重頌授記；佛國淨土與願力相應有情相關"],"k":["如來十號","大目犍連","授記品","佛國淨土","三覺圓滿"]},"6620-a27_004":{"s":"本集進入〈化城喻品〉，先說明化城是佛從唯一佛乘析出二乘解脫道，作為二乘人暫時止息處。講解大通智勝如來的長行與重頌：以三千大千世界磨墨點塵之喻形容其滅度久遠，說明世尊威神之力可推知無量劫事（舉老人一句「南無佛」得度、鴿子因緣），並說三轉法輪次第、虛空無盡故佛國淨土無量，以及如來藏無始不生不滅。","p":["化城：二乘法是佛菩提中暫歇處","大通智勝佛滅度久遠，以磨墨點塵為喻","老人一句南無佛種善根，佛知而度之","三轉法輪次第，終令開示悟入佛知見","虛空無盡，佛國淨土無量；如來藏無始"],"k":["化城喻品","大通智勝佛","唯一佛乘","三轉法輪","佛國淨土","如來藏"]},"6622-a27_005":{"s":"本集續講〈化城喻品〉大通智勝佛坐道場十小劫而佛法不現前、諸天雨華擊鼓供養，以及十六王子讚佛請轉法輪的經文。說明十小劫佛法不現前，是因明心後尚未眼見佛性、成所作智未現，並區分明心與眼見佛性；指出成佛前最後供養為最殊勝供養之一。另解釋「大威德」源於福慧與慈悲，批評喇嘛教大威德金剛，並說有佛出世應請轉法輪。","p":["大通智勝佛十小劫佛法不現在前","因未眼見佛性，成所作智未現前","明心與眼見佛性不同","成佛前及入滅前最後供養最殊勝","大威德源於福慧；十六王子請轉法輪"],"k":["化城喻品","大通智勝佛","眼見佛性","成所作智","請轉法輪","十六王子"]},"6633-a27_006":{"s":"本集講解〈化城喻品〉大通智勝佛成道時十方各五百萬億佛世界六種震動、幽冥之處皆大明，以及東方梵天宮殿光明倍常、救一切梵天王說偈共議其因的經文。以天文學與蓮華藏世界海對照，批評大乘非佛說者隨意否定經典；說明六種震動用以警覺大眾、大光明使幽冥眾生互見，並解釋初禪三天及天主有生必滅。","p":["十方各五百萬億佛世界六種震動","以蓮華藏世界海對照天文學所知","判經真偽須依三量，不知者仰推佛菩薩","六種震動警覺大眾，大光照幽冥處","初禪三天；梵王推測天生或佛出世"],"k":["化城喻品","六種震動","大通智勝佛","大梵天王","大乘非佛說","蓮華藏世界海"]},"6641-a27_007":{"s":"本集講解東方五百萬億國土諸梵天王攜宮殿與天華西行，供養大通智勝如來、奉獻宮殿並說偈讚佛的經文。說明供養佛具田勝、施主勝、供物勝、法勝，福德廣大；從大通智勝佛十劫坐道場說明諸佛難值遇，但如理修學者常蒙佛護念，並提及彌勒龍華三會之保證，以及提婆達多在地獄受佛護念之事。","p":["梵天王與宮殿俱來，散華供養佛","供佛具田勝、施主勝、供物勝、法勝","諸佛難值遇，十劫坐道場方成佛","如理修學者蒙佛護念，悟緣有時","佛具無量功德能救護一切，為天人師"],"k":["化城喻品","供養","大梵天王","諸佛難值","佛護念","大通智勝佛"]},"6653-a27_008":{"s":"本集講解東方諸梵天王偈請大通智勝如來轉法輪、如來默然許之，以及東南方五百萬億國土大梵天王見宮殿光明、大悲梵天王說偈並西北而來供佛獻宮殿的經文。說明佛以大慈悲力出世度眾，批評「佛爭一爐香」等說法；解釋佛默然即是應許，並指十方梵王實為同時受光而來，供佛具福田、施者、供物三勝。","p":["梵天王請佛轉法輪，開涅槃道","佛以大慈悲力出世，非爭供養","佛默然即應許，舉居士請佛受供為例","東南方梵王由大悲梵王帶領尋光而來","十方梵王同時受光；供佛具三種殊勝"],"k":["化城喻品","請轉法輪","大梵天王","大慈悲力","供養","大通智勝佛"]},"6648-a27_009":{"s":"本集講解東南方諸梵天王讚大通智勝佛的偈頌：「一百八十劫空過無有佛，三惡道充滿，諸天眾減少；今佛出於世，為眾生作眼，世間所歸趣」。說明無佛時三惡道增、天眾減的道理，佛為人天眼目、能救護一切而為世間所歸趣，越深證越知佛尊貴；並以民間稱神為「爺公」對比「眾生之父」，強調佛不與外道爭，說法如實不是爭。","p":["一百八十劫無佛，三惡道充滿天眾少","佛為眾生作眼，即人天眼目","四聖六凡皆應歸趣如來","如來交代之事應毫不懷疑承擔","佛為眾生之父；如實說法不是爭"],"k":["化城喻品","世間所歸趣","人天眼目","大梵天王","大通智勝佛"]},"6666-a27_010":{"s":"本集講解東南方梵天王偈請「大聖轉法輪，顯示諸法相」及南方五百萬億國土諸梵天王北行供佛、讚「世尊甚難見，破諸煩惱者」的經文。說明唯有如來堪稱大聖，法相須歸八識心王、不可捨離；區分佛法中得道與生天，並解釋見惑、思惑、無始無明、塵沙惑及所知障等煩惱內涵，指佛如優曇缽花難得值遇。","p":["唯如來可稱大聖，借齊天大聖為喻","顯示諸法相，法相皆歸八識心王","得道須三乘實證，生天只是異熟果","破諸煩惱：見思惑、無始無明、塵沙惑","南方梵王百三十劫方見佛，如優曇缽花"],"k":["化城喻品","大聖轉法輪","法相唯識","破諸煩惱","所知障","大梵天王"]},"6650-a27_011":{"s":"本集講解〈化城喻品〉南方梵天王偈請大通智勝如來「轉無上法輪、擊大法鼓」。說明外道與二乘皆非真「安隱」，唯證不生滅的佛菩提心得安隱；區分二乘法輪與無上法輪，並以塗毒鼓、趙州「好殺」說明擊大法鼓即殺盡我見、破無始無明。","p":["外道意識境界生滅，二乘滅盡五陰，皆非真安隱","證佛菩提不生滅法，五陰現前而心得安隱","讀《法華》須明佛說經的時空背景","唯佛菩提道法輪稱無上法輪，二乘非無上","大法鼓塗法毒殺我見，並能破無始無明"],"k":["無上法輪","大法鼓","安隱","我見","佛菩提","大通智勝如來"]},"6668-a27_012":{"s":"本集講解梵天王請佛「吹大法螺、普雨大法雨、度無量眾生、演深遠音」。說明人天善法、二乘與佛菩提法螺的層次，批評誤解禪定與自稱成佛者；指出大菩薩皆仰推如來而無慢，二乘度眾有限，唯佛菩提為深遠音。","p":["人天善法法螺如四禪次第，末法已難得","批評先得四禪、離念即無想定等誤解","能吹大法螺者皆仰推如來，不敢自稱成佛","大法雨須五乘具足；二乘度眾有限易失傳","深遠音唯指須三大阿僧祇劫的佛菩提"],"k":["大法螺","大法雨","五乘","禪定","慢心","度無量眾生"]},"6660-a27_013":{"s":"本集講解上方梵天王尸棄等推尋光明、供養宮殿，並以偈讚大通智勝佛為「救世之聖尊」。講者以三界層次檢視一神教救世主的瞋、慢、血食而判屬欲界鬼神；指出真救世者須能教眾生出三界乃至成佛。","p":["上方梵天王見宮殿光明，下尋見佛並散華供養","偈讚佛能於三界獄中救出眾生、開甘露門","批評一神教救世主瞋慢重、愛血食屬欲界","真救世須教五戒十善、離欲乃至出離三界","能教眾生破無始無明而成佛者方為聖尊"],"k":["救世之聖尊","三界","梵天王","一神教","出離三界"]},"6670-a27_014":{"s":"本集續講「能開甘露門，廣度於一切」，說明成佛之道只有二大甘露法門：解脫道與佛菩提道，並以此檢驗是否證悟或成佛。講者批評假藏傳佛教自稱有佛未說之法；並解釋「無量劫空過無佛，十方暗冥」時惡道增長，佛為世間眼。","p":["救世聖尊不可自稱，大妄語可公開懺悔","二大甘露門：解脫道與佛菩提道，函蓋一切","解脫道如化城，令人確信可出三界再受授記","批評密宗自稱佛未說法、甘露丸等","無佛時三惡道增、阿修羅盛，佛為世間眼"],"k":["甘露門","解脫道","佛菩提道","大妄語","密宗","佛為世間眼"]},"6673-a27_015":{"s":"本集講解上方梵天王迴向「皆共成佛道」及請佛轉法輪、擊甘露法鼓、開示涅槃道之偈。說明真正轉法輪是演說三乘菩提使人斷我見，批評轉經輪之說；闡釋涅槃不生不死、不可演變，四種涅槃，以及「敷演」與「無量劫習法」之義。","p":["梵天王迴向一切共成佛道，顯菩薩種性","轉經輪無人斷我見，演說佛法才是轉法輪","甘露法鼓只毒死黑品法，令我見無明死","涅槃本來不生不死，不可演變","敷是鋪陳、演是解說，須哀愍而敷演"],"k":["轉法輪","涅槃","甘露法鼓","四種涅槃","敷演","總持"]},"6672-a27_016":{"s":"本集講解大通智勝如來受請「三轉十二行法輪」及廣說十二因緣的經文。說明《佛說三轉法輪經》僅講四聖諦，不是指整個成佛之道的三轉法輪；以佛度五比丘為例，解說示轉、勸轉、證轉三次，各具苦集滅道四行，合為十二行。","p":["諸佛初轉法輪必先三轉十二行法輪","《三轉法輪經》僅指四聖諦，非否定大乘","第一轉釋義示現，第二轉勸修：知斷證修","第三轉自我檢驗已知、已斷、已證、已修","成阿羅漢尚缺緣覺功德，須再說十二因緣"],"k":["三轉十二行法輪","四聖諦","十二因緣","五比丘","阿羅漢"]},"6675-a27_017":{"s":"本集探討十二因緣中的「無明」。由老死逆推至無明，說明無明不只是執著五陰，還包括不知名色從何而來；依龍樹八不中道與「諸法不自生、不他生、不共不無因」，論證名色非物生、非上帝生、非根塵共生，而是第八識如來藏所生。","p":["十二因緣逆推：老死、生、有、取、愛至無明","無明含執著五陰，及不知名色所從來","依八不中道與四不生檢驗名色出生之因","名色非物、上帝、虛空或根塵所生，為第八識","斷三縛結見道後，次第斷欲漏、有漏、無明漏"],"k":["無明","十二因緣","名色","八不中道","如來藏","三漏"]},"6677-a27_018":{"s":"本集解說「於諸漏心得解脫」：欲漏以發起初禪為斷除的驗證，有漏以二禪推知上二界而斷五下分結，無明漏即對微細意識自我的我慢。並講三明六通、八解脫與「不受一切法」，以及十六王子童子出家為沙彌、請佛說無上正等正覺法。","p":["二果薄貪瞋癡；斷欲漏須以初禪現前為證","有漏斷除可推知色無色界有，斷五下分結","無明漏即我慢，斷盡則五上分結盡","須不受一切法，方於諸漏心得解脫","十六王子出家為沙彌，請佛說無上菩提法"],"k":["欲漏","有漏","無明漏","心得解脫","十六王子","八解脫"]},"6698-a27_019":{"s":"本集講解大通智勝佛受十六沙彌請，二萬劫後說《妙法蓮華經》，「教菩薩法，佛所護念」，說經八千劫後入定八萬四千劫，由十六沙彌昇座廣說。說明說《法華》前須先講般若與種智，並勸供養諸佛修福，以釋迦答應魔王三月後入涅槃為例。","p":["二萬劫中先說般若、種智，後說《法華》","供養諸佛福德最大，如給孤獨、菴婆婆梨女","阿羅漢信大乘而不解，餘眾生皆生疑惑","佛入定八萬四千劫，待法傳無虞方入涅槃","十六沙彌廣說分別，示教利喜發菩提心"],"k":["教菩薩法","佛所護念","十六沙彌","供養諸佛","入涅槃","福德"]},"6686-a27_020":{"s":"本集講解大通智勝佛出定讚歎十六菩薩沙彌稀有，勸眾親近供養；並說十六沙彌所化眾生世世相隨，如今十六人皆已在十方成佛，包括阿閦佛、阿彌陀佛與釋迦牟尼佛。講者藉銀河系、世界海說明宇宙廣大，勸人放大心量、包容利生。","p":["佛出定讚十六沙彌，令大眾生仰信親近","所化眾生世世與菩薩俱，值四萬億佛","十六沙彌已於八方成佛，第十六為釋迦佛","以銀河系、世界海層次說明宇宙廣大","勸放大心量，除護法外凡事包容"],"k":["十六沙彌","法緣","阿彌陀佛","阿閦佛","世界海","心量"]},"6694-a27_021":{"s":"本集講解釋迦佛為沙彌時所化眾生今仍住聲聞地，須以聲聞法接引而漸入佛道，因「如來智慧難信難解」。說明不知、不覺菩薩所行者會生滅度想；並解釋「我於餘國作佛，更有異名」，指出只有本尊如來才演說《法華經》。","p":["先以聲聞法實證，再對照說佛地境界","各階位不知上位，如來智慧難信難解","實證者知自身定位而不生慢心","知、覺菩薩所行須證實相般若、明五十二位","佛有化身於餘國，唯本尊如來講《法華》"],"k":["如來智慧","聲聞地","菩薩所行","滅度想","化身佛","一佛乘"]},"6700-a27_022":{"s":"本集講解如來示現入涅槃的四個條件：眾清淨、信解堅固、了達空法、深入禪定，具足時才集眾說《法華經》，顯示唯一佛乘得滅度。並說對志樂小法、深著五欲者先說二乘涅槃；最後開講化城喻的「五百由旬險難惡道」。","p":["如來入涅槃四條件，具足方說《法華》","說《法華》令眾知二乘與菩薩的定位","聽聞《法華》種子終令聲聞回入菩薩道","對樂小法、著五欲者先說苦集滅道","成佛之道如險難惡道，以大妄語者為例"],"k":["入涅槃","唯一佛乘","化城喻","二乘涅槃","險難惡道","大妄語"]},"6687-a27_023":{"s":"本集續講化城喻：以悟錯堅持、誤入密宗、只行善不學佛等說明成佛之道「曠絕無人怖畏」，須互相扶持。導師見眾中路懈退，於三百由旬處化作大城，此城即譬喻阿羅漢解脫果；入城後仍須回頭收拾路上珍寶，即斷習氣種子與所知障。","p":["悟錯不改、誤入密宗，顯成佛之道險難","成佛之道少人行，須互相扶持勿作自了漢","如來為導師，善知險道通塞之相","三百由旬處化城，譬喻阿羅漢解脫果","阿羅漢須從初地補修習氣與所知障"],"k":["化城喻","解脫果","阿羅漢","險難惡道","習氣種子","相似佛法"]},"6696-a27_024":{"s":"本集講解導師見眾止息後「即滅化城」，告以寶處在近，說明二乘涅槃是如來方便施設，真正解脫在八地乃至佛地。佛在二轉、三轉法輪為阿羅漢講般若與唯識，猶如所給寶物；並解釋眾生若只聞一佛乘便生怯弱，故「於一佛乘分別說三」。","p":["滅化城：阿羅漢果非究竟，須從初地再修","二轉講般若、三轉講唯識，如佛所給寶物","阿羅漢至授記時才知珍惜這些寶物","弘法難，須方便善巧、善觀時節因緣","眾生怯弱，故佛於一佛乘分別說三乘"],"k":["化城喻","方便施設","三乘菩提","一佛乘","二乘涅槃","般若"]},"6712-a27_025":{"s":"本集說明本來只有一佛乘，三乘是方便。須先令眾實證二乘，再以《法華》授記使人信受。論證二乘無餘涅槃中無人證涅槃，故不真實；明心證本來自性清淨涅槃與八地亦未究竟，唯佛地四智圓明的無住處涅槃為真實。並說不能想像不等於不存在。","p":["弘法須有實證結果，再以授記堅固信心","無餘涅槃中無能觀者，故二乘涅槃不真實","明心、八地所證涅槃仍非究竟","佛地四智圓明、無住處涅槃才是真實涅槃","舉地圓說、日心說，說明難想像不等於不存在"],"k":["一佛乘","真實涅槃","無住處涅槃","二乘涅槃","授記","四智圓明"]},"6702-a27_026":{"s":"本集進入〈化城喻品〉末偈頌，說明偈頌即總持陀羅尼，原為古印度口傳背誦的記憶方便。舉道安、義淨、護法手抄本、《十誦律》譯事對照中印傳承差異；並以《心經》咒依玄奘「五不翻」之祕密故不譯、《實相般若經》的「底唎」，點出陀羅尼可含經文密意。","p":["偈頌是總持陀羅尼，扼要重述前段經文","中國早用統一文字，印度以師誦弟習為主","舉道安、義淨、護法、十誦律說明口傳","陀羅尼原義是濃縮經文以便記憶","《心經》咒依祕密故不翻，含經文密意"],"k":["陀羅尼","總持","偈頌","心經","五不翻","口傳"]},"6723-a27_027":{"s":"本集先提醒後期密教咒語可能借用印度教含義而背離佛法；再批評部分學界與教界據殘本主張《法華經》晚出、「大乘非佛說」，引季羨林、辛島靜志研究指出《法華經》不晚於其他文獻、漢譯早於梵本。並介紹品名梵文意為「往世因緣」，提出大通智勝佛十小劫佛法不現前的問題。","p":["密教化咒語可能暗含性意涵，須慎辨","學術推論隨新證據修正，不宜奉為定論","辛島靜志：《法華》不晚出，漢譯早於梵本","本品梵名意為往世因緣，羅什譯為化城喻","大通智勝佛坐道場十小劫佛法不現前"],"k":["大乘非佛說","學術研究","辛島靜志","化城喻品","大通智勝佛","陀羅尼"]},"6726-a27_028":{"s":"本集續談大通智勝佛十劫坐道場而佛法不現前。引太虛大師解釋為「大道難成」、非眾生可測，評其不知即說不知為保守；批評隨學界主張大乘非佛說的出家人，並述慈航法師與印順法師的分歧及平實導師的辨正。最後說明修證有次第須證轉，圜悟、大慧曾以此題考問天下。","p":["坐道場表示功德圓滿，本應即得四智圓明","太虛大師釋為大道難成，不知即說不知","學術結論常被修正，不應據以謗大乘","慈航駁印順，後由平實導師著書辨正","圜悟、大慧以十劫坐道場考問而無人能答"],"k":["十劫坐道場","大乘非佛說","太虛大師","印順","四智圓明","修證次第"]},"6706-a27_029":{"s":"本集解釋「十劫坐道場佛法不現前」，指出這屬於真見道、十住如幻觀以上才能窺知的境界。說明轉識成智分下、中、上品轉，六七因中轉、五八果上轉；大通智勝佛大圓鏡智已成就而成所作智未現起，十劫後才四智圓明。並說明心與見性不同，見性須善知識、福德與定慧等持。","p":["十劫不現前須真見道、十住如幻觀方能窺見","轉識成智有下、中、上品轉的次第","明心對應大圓鏡智，眼見佛性對應成所作智","大通智勝佛成所作智未現起，十劫後方圓明","明心為體、見性為用，見性須定慧等持"],"k":["眼見佛性","轉識成智","四智圓明","明心","十劫坐道場","成所作智"]},"6703-a27_030":{"s":"本集引《大般涅槃經》師子吼菩薩問佛性，說明十住菩薩可眼見佛性、九地仍有聞見，批評竄改「十住」為「十地」者。接著敘述宋代士大夫入禪及克勤、大慧接引居士，大慧以看話禪起疑情，並嚴斥宏智默照禪令人落入禪寂。最後引平實導師開示：不知佛性境界即無法答十劫坐道場之問。","p":["涅槃經：十住眼見佛性，九地仍屬聞見","宋代士大夫普遍入禪，克勤、大慧廣攝居士","大慧看話禪以疑情為先，參究話頭","大慧斥默照禪為邪禪，宏智僅有初關","不知佛性境界，無法通達十劫坐道場"],"k":["默照禪","看話禪","大慧宗杲","眼見佛性","宏智正覺","十劫坐道場"]},"6727-a27_031":{"s":"本集從平實導師《法華經講義》第八輯開講〈五百弟子受記品〉，解說富樓那聽聞佛說法、授記及宿世因緣後心淨踊躍的經文。並引《佛藏經》、《雜阿含經》、《觀經》介紹富樓那說法第一、往輸盧那弘法的忍辱及為頻婆娑羅王說法等事蹟，最後引《佛藏經》說明釋迦菩薩因住於有所得而未獲諸佛授記。","p":["富樓那聞授記與宿世因緣，心淨踊躍禮佛","《佛藏經》讚富樓那清淨說法、法師第一","大阿羅漢的證量不只如阿含部所顯","富樓那願赴輸盧那弘法，展現忍辱","釋迦菩薩供養無數佛，因有所得未得授記"],"k":["五百弟子受記品","富樓那","授記","有所得","佛藏經","忍辱"]},"6729-a27_032":{"s":"本集續講〈五百弟子受記品〉，依《佛藏經》說明不被授記的癥結在於不能通達諸法實相、貪著計我的有所得見。講者解釋諸法實相即一切法從如來藏出生、歸於如來藏，區分二乘與大乘無生忍，說明釋迦菩薩證無生忍後得錠光佛授記，並介紹顯授記、密授記，且以佛十號檢驗自稱成佛者。","p":["不被授記因不通實相、貪著計我有所得","諸法實相：一切法從如來藏生、歸如來藏","二乘無生忍與大乘無生忍的差別","證大乘無生忍乃得錠光佛授記","授記分顯授記、密授記，各有兩種"],"k":["授記","大乘無生忍","諸法實相","如來藏","無所得","密授記"]},"6731-a27_033":{"s":"本集解說〈五百弟子受記品〉中世尊讚歎富樓那的經文：富樓那於過去九十億佛、七佛及賢劫諸佛座下皆說法第一，內行菩薩道而外現聲聞相，以方便度眾迴小向大。世尊授記其成佛號法明如來，講者說明其國土莊嚴及法喜食、禪悅食，並強調菩薩道須次第修學，批評即身成佛之說。","p":["佛讚富樓那護持助宣佛法、說法第一","富樓那示現聲聞，引眾迴小向大","未來護持無量無邊諸佛之法，心量廣大","授記成佛號法明如來，國名善淨","法喜食、禪悅食；菩薩道須次第而修"],"k":["富樓那","法明如來","授記","法喜食","禪悅食","菩薩道次第"]},"6735-a27_034":{"s":"本集續述法明如來國土的廣大境界，講者據此說明學佛應有遍及十方三世的眼界，批評把佛教侷限於地球的狹義人間佛教，並說明三地滿心後的度眾範圍與歸依十方諸佛。接著解說重頌「內祕菩薩行，外現是聲聞」，說明菩薩以示現三毒、邪見等方便度眾，以及最後身菩薩示現從凡夫修行成佛的用意。","p":["法明如來國土境界非人間所能有","批評把佛教侷限於地球的人間佛教觀","學佛應歸依十方諸佛、放大眼界","重頌：內祕菩薩行，外現是聲聞","佛示現凡夫成佛，為令眾生生信"],"k":["內祕菩薩行外現聲聞","富樓那","人間佛教","十方諸佛","方便示現","法明如來"]},"6737-a27_035":{"s":"本集解說世尊為千二百阿羅漢授記，先授記憍陳如將供養六萬二千億佛後成佛，號普明如來，並引《賢愚經》羼提波梨忍辱仙人與迦梨王的往世因緣，說明其最先得度的緣由。接著講五百阿羅漢同號普明、轉次授記，以及衣裏繫珠之喻，指出他們本是菩薩，聲聞緣覺道只是從一佛乘方便分出。","p":["千二百阿羅漢希望如大弟子般得授記","憍陳如供養六萬二千億佛後成普明如來","忍辱仙人往世因緣，說明憍陳如最先得度","五百阿羅漢同號普明，前佛為後佛授記","衣裏繫珠喻：本是菩薩，得少為足"],"k":["憍陳如","普明如來","衣珠喻","忍辱仙人","一佛乘","授記"]},"6736-a27_036":{"s":"本集概說菩薩與聲聞的差異：聲聞弟子經《法華經》授記，才知自己所證的涅槃只是少分，實際上並未證得本來自性清淨涅槃。講者說明聲聞依四聖諦、八正道修行至四果，滅五陰不再受生，但阿羅漢果在佛菩提道上並非究竟，並以化城喻及憍陳如「得少涅槃分」偈說明唯有成佛才是究竟。","p":["授記使聲聞知所證涅槃只是少分","聲聞依四聖諦、八正道修證四果","阿羅漢果只暫滅五陰受生，並非究竟","化城喻：中途安止，尚未到寶所","憍陳如偈：得少涅槃分，便自以為足"],"k":["聲聞","四聖諦","阿羅漢","化城喻","本來自性清淨涅槃","授記"]},"6739-a27_037":{"s":"本集續談菩薩與聲聞，從憍陳如、阿難的授記說明成佛時劫極為長遠。講者區分真實法與虛妄法：能出生三界一切法的根源是真實法，無常生滅的現象界法是虛妄法；未證真實法即如處長夜，須依佛菩薩慈悲教化。並解說《法華經》偈「世尊於長夜，常愍見教化，令種無上願」的意涵。","p":["成佛須供養無數佛，時劫極為長遠","真實法是三界一切法的根源","現象界法無常生滅，是虛妄法","未證真實法，如生於漫漫長夜","佛於長夜慈愍教化，令弟子種無上願"],"k":["真實法","現象界","長夜","慈悲教化","無上願","授記"]},"6747-a27_038":{"s":"本集說明阿難受授記供養六十二億佛即成佛、時劫較短的兩個原因：慈悲攝受眾生，以及發願憶持諸佛法藏，讓佛法得以結集流傳。講者解說阿難成佛號山海慧自在通王佛的經文，指出法藏是修學與印證的依據，可使眾生信受第八識如來藏真實法，並勉勵菩薩為眾生宣講佛法。","p":["阿難成佛時劫短，因慈悲與持法藏","阿難憶持佛法，使經典結集流傳後世","授記成佛號山海慧自在通王佛","法藏是印證所悟、令眾生信受的依據","菩薩應以佛法利益眾生、為眾宣講"],"k":["阿難","持法藏","山海慧自在通王佛","授記","如來藏","弘法利生"]},"6740-a27_039":{"s":"本集開講〈法師品〉，依《雜阿含經》說明聲聞法中的法師是為人說五陰應生厭、離欲、滅盡、寂靜者，契合三法印，不一定是出家人。講者批評主張意識或離念靈知常住者不符法師定義，並說明儀式主法不說法、或僅持戒而不說法也不算法師，再引《長阿含經》〈梵動經〉說明持戒只是小緣，佛的甚深大法能照破六十二見。","p":["《雜阿含》：說五陰生厭離欲者名法師","五陰無常正觀，對應三法印","主張意識常住者違背聖教，非法師","持戒是基礎，但不說法不算法師","〈梵動經〉：戒行是小緣，大法破六十二見"],"k":["法師品","法師","五陰","三法印","持戒","六十二見"]},"6744-a27_040":{"s":"本集說明為何講大乘〈法師品〉要先強調聲聞法的法師定義：三法印與實相印並不衝突，五陰攝歸如來藏時即離常與無常二邊，並引鏡與影像之喻說明。講者指出阿含已隱說本識，如「齊識而還」；修佛菩提須先斷我見，批評六識論者同時落入增益執與損減執，並說明一切種智與無餘涅槃都依如來藏而成立。","p":["三法印印小乘，實相印印大乘，不相違","鏡影喻：五陰攝歸如來藏即離二邊","阿含已說本識，如「齊識而還」","不斷我見而求明心，必落入意識","六識論者雙具增益、損減二執"],"k":["三法印","實相印","如來藏","斷我見","六識論","一切種智"]},"6755-a27_041":{"s":"本集說明大乘法師所說須契合實相印，並依平實導師講義指出〈法師品〉的法師是佛滅後能為人解說《法華經》者。講者歸納第一個條件：聽聞《法華經》一偈一句乃至一念隨喜，即得佛授記，並引《瑜伽師地論》法印與隨喜得聖財之說，說明隨喜代表菩薩種性已發起，也略述《法華經》會三歸一的主旨。","p":["大乘法師所說法義須契合實相印","〈法師品〉法師：佛滅後解說《法華》者","第一條件：聞《法華經》一念隨喜","隨喜即種下佛菩提種子、發起菩薩種性","《法華經》主旨在會三乘方便入一乘"],"k":["法師品","一念隨喜","菩薩種性","實相印","授記","會三歸一"]},"6746-a27_042":{"s":"本集先依《瑜伽師地論》歸依四緣，比較三歸依所發的菩提心與聽聞《法華經》隨喜而發起菩薩種性在層次上的差異。接著講法師的第二個條件：受持、讀誦、解說、書寫《妙法華經》，對照《金剛經》相近經文，說明「此經」指第八識如來藏，此類法師通常已證悟。最後檢討釋印順把「此經」解為般若性空法門，講者認為有母女互生的矛盾。","p":["三歸依發心與隨喜發起菩薩種性層次不同","第二條件：受持讀誦解說書寫《法華》","《金剛經》亦說受持此經功德無量","「此經」指第八識如來藏，通常須證悟","批評釋印順以般若性空法門解「此經」"],"k":["受持讀誦","此經","如來藏","三歸依","金剛經","釋印順"]},"6759-a27_043":{"s":"本集續論法師第二條件，引平實導師講義及《大法鼓經講義》自序，說明受持以實證為前提，諸經所說「此經」多指第八識如來藏。講者以《大乘起信論》本覺、始覺、究竟覺之說，駁斥把釋印順「老般若」等同如來藏的類比，並引《大寶積經》「勿說此經」證明「此經」並非指經典文字，最後提到凡夫講《法華經》也應隨喜讚歎。","p":["受持以勝解為前提，勝解源自實證","諸經所說「此經」多指第八識如來藏","《起信論》：始覺、究竟覺皆不離本覺","駁以「老般若」比附如來藏的說法","凡夫講《法華經》亦應隨喜讚歎"],"k":["此經","如來藏","本覺","大乘起信論","釋印順","法師"]},"6761-a27_044":{"s":"本集講〈法師品〉佛滅後說《法華經》的三個條件：入如來室、著如來衣、坐如來座，講者指出不可依文解義理解為出家登座即可。「時時令說法者得見我身」是指見法身如來藏，而非幻見的佛身、定中化身或報身；如來室即大慈悲心，如來衣即柔和忍辱心，如來座即一切法空，其真實義留待下集。","p":["說《法華》三要件：如來室、衣、座","依文解義理解三要件，恐誤導眾生","「得見我身」即見法身如來藏","如來室：對不信者亦起大慈悲心","如來衣：柔和忍辱，破邪而不起瞋"],"k":["如來室","如來衣","如來座","法身","一切法空","法師品"]},"6757-a27_045":{"s":"本集解說「如來座者，一切法空是」：法空分二種，二乘從現象法界觀緣起性空，大乘菩薩證實相法界的如來藏。講者引《大般若經》「真如雖生諸法而真如不生」說明法身與真如之義，指出否定本識的緣起性空會成為斷滅空，並引阿含「齊識而還」、「有因有緣集世間」，批評釋印順與琅琊閣的六識論見解。","p":["法空分二乘現象界與大乘實相界兩種","真如雖生諸法而不生，名為法身","大乘一切法空：諸法攝歸如來藏","否定本識的緣起性空即成斷滅空","阿含說「齊識而還」，本識為諸法根本因"],"k":["一切法空","真如","緣起性空","本識","斷滅空","六識論"]},"6749-a27_046":{"s":"本集續講一切法空的真實義，講者批評釋印順否定第八識後，緣起性空變成等同外道的緣生性空斷滅見。依其解釋，「若見緣起便見法」的見法，是見諸法本源的第八識；緣起性空只是所顯法，不能生法。講者並說明中道與眾生平等應依如來藏而說，評述印順「大乘非佛說」對當代及南傳法師的影響。","p":["否定第八識的緣起性空即成緣生性空","「見緣起便見法」的法指第八識如來藏","緣起性空是所顯法，不能出生諸法","中道、眾生平等皆依如來藏而說","批評印順「大乘非佛說」的影響"],"k":["緣起性空","見緣起即見法","大乘非佛說","釋印順","眾生平等","如來藏"]},"6754-a27_047":{"s":"本集解說偈頌「是經難得聞，信受者亦難」，講者指出「是經」是如來藏妙法即第一義諦，難在值遇能依此妙法說《法華》的真善知識，且信眾多以出家身相簡擇，致使信受者少。並引《長阿含經》說明佛先說施論、戒論、生天之論再說四聖諦的次第說法，以穿鑿高原求水之喻說明漸近法水，勸人親近真善知識。","p":["「是經」指如來藏妙法，即第一義諦","難遇能依如來藏說《法華》的善知識","信眾多以出家身相簡擇，故信受者難","佛次第說法：施論、戒論、生天之論","穿鑿求水喻：見濕土知近法水"],"k":["是經難得聞","如來藏","第一義諦","次第說法","穿鑿求水喻","真善知識"]},"6750-a27_048":{"s":"本集解說「不聞《法華經》，去佛智甚遠；若聞是深經，決了聲聞法」，說明三乘五乘皆從一佛乘分出，菩薩證如來藏後於相見道完成諸現觀，入地前即具大乘阿羅漢果證，而二乘阿羅漢離佛智仍遠。講者對比四宏誓願、十無盡願與二乘心量，批評「大乘非佛說」與密宗之說，並引玄奘《成唯識論》「實我若無」破斷滅空見。","p":["三乘、五乘皆從唯一佛乘分析而出","證此經可決了聲聞法，漸次通達","阿羅漢不證如來藏，離佛智甚遠","菩薩發四宏誓願、十無盡願度眾","玄奘：實我若無，何有憶識恩怨"],"k":["決了聲聞法","實我","一切法空","十無盡願","大乘非佛說","成唯識論"]},"6763-a27_049":{"s":"本集開講〈見寶塔品〉，先說明佛出生、得道、初轉法輪、入涅槃四處建塔的因緣，再逐句解說七寶塔從地踊出的經文義理。講者以塔高五百由旬表佛法崇高，縱廣表廣大，從地踊出表佛法依三界境界相建立，住在空中表非凡夫所及且無所住，五千欄楯表菩薩五大階段，龕室千萬表果德無量，幢幡表福德。","p":["建塔四因緣：出生、得道、轉法輪、涅槃","塔高五百由旬，表佛法深妙崇高","從地踊出：佛法依三界境界相建立","五千欄楯表十信至十地五大階段","龕室表果德無量，幢幡表福德圓滿"],"k":["見寶塔品","七寶塔","多寶如來","菩薩階位","福德莊嚴","建塔因緣"]},"6770-a27_050":{"s":"本集續解〈見寶塔品〉：瓔珞表菩薩本業，寶鈴表法音引十方菩薩，栴檀香表戒德功德香；三十三天表三賢三十心與三類聖位，曼陀羅華表赤誠之心。講者解釋多寶如來讚歎世尊「以平等大慧教菩薩法」，平等法即真如，說明《法華經》是菩薩法，並指寶塔出現為證前啟後，也隱喻各人身中的多寶如來，證悟即得親見。","p":["瓔珞表菩薩本業，寶鈴表法音遠播","栴檀香表戒香，能逆風遍飄世界","三十三天表三賢三十心及三類聖位","平等大慧即真如，《法華》是菩薩法","寶塔證前啟後，喻身中多寶如來"],"k":["見寶塔品","多寶如來","平等大慧","真如","證前啟後","瓔珞"]},"6768-a27_051":{"s":"本集講解〈見寶塔品〉四眾見寶塔住空、大樂說菩薩請問寶塔從地踊出及發聲因緣一段。講者以理解釋：「地」指境界，寶塔從地踊出喻破無始無明而見如來藏，「住在空中」表分明不再遮隱；並以能仁、寂靜解釋「釋迦牟尼」為自心真如的體性。","p":["「從地踊出」喻如來藏從自身境界中顯現","破無始無明後，寶塔「住在空中」分明現前","初悟者「怪未曾有」，推究不出如來藏源頭","如來藏不可增損，故只能「卻住一面」","釋迦牟尼即能仁、寂靜，喻自心真如"],"k":["七寶塔","多寶如來","如來藏","無始無明","大樂說菩薩","見寶塔品"]},"6775-a27_052":{"s":"本集講解佛答大樂說菩薩：寶塔中有多寶如來全身，其因地發願凡十方說《法華經》處，寶塔必踊現作證並讚善哉。講者依序說明三問的答覆，並以理解釋菩薩每世依「地」（三界境界相）重建七寶塔（五陰身心），如來藏全身住於其中；大樂說請見佛身，則引出見多寶如來需有條件。","p":["多寶如來因地發願：說法華處寶塔必踊現作證","臨滅度囑起大塔，為七寶塔由來","菩薩世世依地重建、莊嚴自己的七寶塔","每人如來藏皆「全身」住於五陰塔中","大樂說請見佛身，見多寶如來需有條件"],"k":["多寶如來","誓願","七寶塔","如來藏","五陰","見寶塔品"]},"6773-a27_053":{"s":"本集講解多寶佛深重願：欲示其身，說法華之佛須召集十方分身諸佛，以及佛放白毫光照見十方諸佛來集。講者說明值佛、聞法華等諸難；以理解釋參禪須收攝一切心所、不向外攀緣，方能見自心多寶如來；並據此說明說法華者是應身佛，化身佛不說此經。","p":["多寶佛願：分身諸佛全集方現全身","值佛、聞法華、能讚歎等皆極難","白毫光照十方國土，喻種子流注清淨莊嚴","參禪須收攝一切心所，不向外攀緣","說法華者是應身佛，化身佛不說此經"],"k":["多寶如來","分身諸佛","應身佛","化身佛","參禪","白毫相光"]},"6764-a27_054":{"s":"本集講解娑婆世界變為清淨、諸佛各至寶樹下師子座，及釋迦佛八方更變國土以容分身諸佛的經文。講者以譬喻解釋：釋迦牟尼佛喻五蘊，多寶如來喻如來藏，寶樹喻法聚，化身佛喻心所法，黃金為繩界八道喻八正道；並說明悟後須令各類法聚清淨、除惡道種子，是悟後進修之道。","p":["經中譬喻：五蘊、如來藏、法聚、心所法","黃金為繩界八道，喻成佛唯八正道","成佛境界中無世界、無有情的莊嚴相","寶樹高五百由旬，喻諸法聚平等","變化清淨國土，喻除惡道種子、悟後進修"],"k":["譬喻","如來藏","法聚","八正道","心所法","悟後進修"]},"6785-a27_055":{"s":"本集講解釋迦佛為諸佛當來坐復變八方國土、十方分身諸佛來集坐於八方、遣侍者問訊並請開寶塔一段，先釋經文字義，再說隱含譬喻。講者以八方喻七識加色身，化佛全集喻如來藏一切功能差別具足現行；並說明化身佛遣侍者問訊，顯示化身佛的尊貴。","p":["再變八方國土，皆清淨無三惡道與阿修羅","十方化身佛來集，坐寶樹下師子座","八方喻七識加色身，再加上下為十方","化佛全集喻如來藏一切功能差別現行","遣侍者捧寶華問訊，顯化身佛尊貴"],"k":["分身諸佛","化身佛","八方","如來藏","功能差別","譬喻"]},"6777-a27_056":{"s":"本集續講化身諸佛遣侍者問訊「少病、少惱，氣力安樂」並請開寶塔一段的譬喻。講者引《維摩詰經》說明應身如來因感應五濁眾生受生而示現病惱，並批評以「憐愍故病」解釋的說法；又以合集化佛開塔喻成佛時統合一切心、心所觀察無垢識，指出經文顯示諸佛有分身、滅度非斷滅空。","p":["化佛遣侍者供養，喻悟後以心所朝禮法身","應身佛感應五濁眾生受生，故示現病惱","問訊座下菩薩、聲聞，顯其尊貴","同開寶塔，喻成佛時合集心所觀無垢識","古佛今佛互證：諸佛有分身、非斷滅"],"k":["化身佛","應身佛","維摩詰經","無垢識","斷滅空","分身諸佛"]},"6783-a27_057":{"s":"本集講解釋迦佛住虛空以右指開七寶塔戶，眾見多寶如來全身不散如入禪定、二佛分座，及佛問誰能於娑婆廣說此經一段。講者引六祖「開示悟入」，說明開塔喻參禪理合而破參、一剎那全體見如來藏；「如入禪定」則喻如來藏不出不入，非世間禪定。","p":["經文字義：開塔、讚善哉、分半座、付囑","六祖以開示悟入概括法華要旨","以右指開塔戶，喻參禪理合即開悟","見如來藏是一剎那全體同見","「如入禪定」：如來藏不出不入，非四禪八定"],"k":["開七寶塔","多寶如來","開示悟入","參禪","如來藏","禪定"]},"6781-a27_058":{"s":"本集續講多寶如來讚釋迦佛快說法華、開塔分座及接眾至虛空等經文的譬喻。講者以釋迦牟尼佛喻自己的五陰（能仁、寂靜至佛地方圓滿），多寶如來喻本來涅槃的如來藏；並以開塔見多寶如來對應「開佛知見」，二佛同座、接眾入虛空對應「示佛知見」。","p":["釋迦牟尼喻五陰，多寶如來喻如來藏","能仁屬五陰，絕對寂靜須至佛地","如來藏本無生死，即久已滅度之佛","開塔見多寶如來為「開佛知見」","分半座、接眾入虛空為「示佛知見」"],"k":["開佛知見","示佛知見","開示悟入","五陰","如來藏","無垢識"]},"6788-a27_059":{"s":"本集探討「諸法因緣不雜亂」，說明諸法皆由如來藏直接或間接出生，故能正確解釋因緣果報與法住法位。講者引《入楞伽經》、《瑜伽師地論》、《成唯識論》說明非無因說、能取可取皆自心所現、「定異」無雜亂性，唯異熟第八識能建立染淨因果；並批評六識論及造物主、冥性等說。","p":["如來藏難信，禪宗公案並非無頭公案","依根本因如來藏說緣起，不無因、不雜亂","能取、可取皆自心所現，無真實體性","法住法位、定異：諸法依因果各安其位","唯異熟第八識能持種、建立染淨因果"],"k":["如來藏","因緣","法住法位","異熟識","八識論","因果"]},"6778-a27_060":{"s":"本集探討「他圓滿」，說明修學佛法除自身努力外，外在環境亦極重要。講者引《法華經講義》「化長劫入短劫」及《瑜伽師地論》，解說諸佛出世、說正法教、法教久住、法住隨轉、他所哀愍五項，強調須依有實證的善知識受教授教誡；並介紹五濁惡世修學的六種方便善巧，勸珍惜現代聞法因緣。","p":["值遇善知識可化長劫入短劫","多劫無佛出世，正法難聞應珍惜","他圓滿五項：諸佛出世至他所哀愍","法住隨轉須證正法者教授教誡","依內修證佛法的六種方便善巧"],"k":["他圓滿","善知識","正法久住","方便善巧","瑜伽師地論","五濁惡世"]},"6791-a27_061":{"s":"本集探討「發願令正法久住」，指出令此經久住的第一步是自己先實證。講者引《大般若經》發菩提心、護持正法、如教修行「三事最為無上」，說明穢土護法功德大，並介紹初地十無盡願與增上意樂清淨；又強調須以抉擇慧分辨正說與邪說，並引《大智度論》「願如御者」說明發願的重要。","p":["令正法久住，第一步要自己先實證","發菩提心、護持正法、如教修行三事無上","穢土須臾護法，勝淨土一劫功德","初地十無盡願須增上意樂清淨","須抉擇所護持者是否正法；願如御者"],"k":["發願","護持正法","十無盡願","增上意樂","菩提心","正法久住"]},"6795-a27_062":{"s":"本集探討「修學安忍方便」。講者引《法華經講義》以猛風吹小樹成大樹，喻菩薩應接受磨練，並主張對落入邪見者應方便指正、不可姑息；說明以五陰無我、無我所及內相分觀行修忍，並須數數觀行轉變意根；指出憍慢、瞋、癡為修忍障礙，法上之忍是「忍可」而非強忍。","p":["菩薩如小樹須經猛風，才成棟梁","對邪見者應方便指正，不可鄉愿姑息","觀五陰無我及內相分，於諸塵無所傷","意根煩惱須數數觀行，漸次轉變","憍慢瞋癡為障礙；法忍為忍可非強忍"],"k":["忍辱度","安忍","五陰無我","內相分","意根","法忍"]},"6800-a27_063":{"s":"本集探討「分辨邪正」。講者引《大乘廣百論釋論》「智與愚異謂識是非」、「應以大乘摧邪立正」，說明須把正邪對比講清楚才能救護眾生，且須以親證如來藏為依據；並引經論說明邪見成因與善知識守護之德，指出障礙破邪顯正將招愚鈍報、與無明相應。","p":["智愚之別在能辨是非，應摧邪立正","錯說法義難辨，須明確對比正邪","破邪顯正須以證空性如來藏為依據","邪見由親近惡知識、不如理作意而起","障礙破邪顯正將招愚鈍報"],"k":["破邪顯正","邪見","善知識","無明","愚鈍報","如來藏"]},"6792-a27_064":{"s":"本集先回顧〈見寶塔品〉前段，再語譯世尊重宣偈：多寶佛常遊十方為是經故，及佛滅後於惡世說、書、讀、持此經為難等。講者歸納四個重點，本集說明第一點：多寶如來即有情真心，在五陰七寶塔中流轉三界；並引《楞伽經》、《華嚴經》等說明真心與佛地無垢識自性無別，唯因地有染。","p":["回顧寶塔踊出、化佛來集、開塔分座","偈頌語譯：諸難事中說持此經最難","四重點：真心流轉、供佛、發願、說法華","真心名號雖多，與佛地無垢識無別","眾生煩惱身中有如來藏，自性清淨而有染"],"k":["見寶塔品","多寶如來","真心","如來藏","心佛眾生三無差別","無垢識"]},"6789-a27_065":{"s":"本集續講〈見寶塔品〉偈頌第二重點：供養諸佛稀有難得，可培大福德。講者以優曇缽花、過去七佛說明佛世難遇，引《優婆塞戒經》說佛為無量報福田；並從十信位起，說明菩薩依次修布施、持戒、忍辱、精進、禪定各度所需福德，並提及無相憶佛拜佛的動中定。","p":["佛出世如優曇缽花，供佛應具恭敬心","供佛得無量報，佛為大福田","十信位須經一劫至萬劫方成就","布施四利益；菩薩種性由善業因緣成就","持戒、忍辱、精進、禪定依次圓滿"],"k":["供養諸佛","福德","十信位","六度","菩薩種性","動中定"]},"6798-a27_066":{"s":"本集續講菩薩各階位修行與福德：具足三資糧後依善知識參禪，找到第八識並以《心經》印證，轉依成第七住明心菩薩，並以退轉者為例說明疑見未斷之害。接著說明眼見佛性所需定、慧、福德及如幻觀，十行位陽焰觀、十迴向位如夢觀，以及入初地前的阿羅漢證量與勇發十大願。","p":["具足福德、定力、慧力三資糧方能證悟","證第八識，以《心經》現觀非一非異","未心得決定者易退轉，評論正法成謗業","眼見佛性須更深定力與廣大福德","十行陽焰觀、十迴向如夢觀，發十大願入初地"],"k":["明心","眼見佛性","般若度","如幻觀","陽焰觀","如夢觀"]},"6807-a27_067":{"s":"本集續說菩薩從初地至十地、等覺、妙覺的修行歷程，說明各地所行波羅蜜、所斷隨眠及所證現觀，如鏡像、光影、谷響、水中月、變化所成、似有非有、犍闥婆城，以及意生身、滅盡定等。講者藉此說明每一階位皆須修集更廣大福德，等覺百劫修相好，故佛是大福田。","p":["初地至十地各行一波羅蜜並斷隨眠","各地現觀：鏡像、光影、谷響、水中月等","七地滿心佛授引發如來無量妙智三昧","十地受職灌頂，等覺百劫修相好","佛一毛功德即等於眾生功德總和"],"k":["十地","現觀","道種智","意生身","福德","大福田"]},"6802-a27_068":{"s":"本集講〈見寶塔品〉偈頌第三、四重點。第三，菩薩應發通願與成佛別願，舉阿彌陀佛、釋迦如來、彌勒、地藏、迦旃延、富樓那的本願為例。第四，菩薩應發願宣講《法華經》，講者逐一解釋演說、暫讀、受持、解義趣、奉持五難，並批評六識論者與「大乘非佛說」的主張。","p":["通願即四宏誓願，別願為成佛本願","舉阿彌陀、釋迦、彌勒、地藏等本願","願越廣，佛國越大、所需時劫越長","法華五難：演說、暫讀、受持、解義、奉持","發願宣講法華，福德速集、成佛較快"],"k":["發願","本願","法華五難","佛國淨土","四宏誓願","見寶塔品"]},"6811-a27_069":{"s":"本集講解〈見寶塔品〉重頌結尾「此經難持，若暫持者……是則勇猛，是則精進」。講者說明受持此經即受持如來藏，勇猛、精進是不畏生死、世世以四攝法攝受眾生；引《大寶積經》、阿難誓願、《說無垢稱經》說明攝受眾生即攝受佛土，並以三個建築工人的故事作譬喻。","p":["暫持此經，諸佛歡喜讚歎","真受持非依文解義，乃受持如來藏","以四攝法長劫攝受眾生即菩提道","攝受眾生即攝受佛土，不必急於成佛","菩薩不畏世世生死，異於定性聲聞"],"k":["勇猛精進","攝受佛土","四攝法","受持法華","如來藏","定性聲聞"]},"6809-a27_070":{"s":"本集續講受持《法華經》者為何是持戒、行頭陀者。講者舉光明婆羅門以大悲心娶伽吒的本生故事，說明先利眾生、後成就自己，並指成佛最難修集的是福德；又從理上說明依真如、佛性受持此經，懂戒相開遮、忍受被誤解，即真持戒與頭陀行，能解其義者為「諸天人世間之眼」。","p":["光明婆羅門本生：以大悲心成滿眾生","成佛最難修集的是福德而非智慧","依真如佛性受持，堅持不退為勇猛","懂戒相開遮，不被戒相綁死為真持戒","能解此經真義者是諸天人世間之眼"],"k":["持戒","頭陀行","攝受眾生","真如","佛性","開遮"]},"6801-a27_071":{"s":"本集說明受持《法華經》即是受持「此經」如來藏，並總持一切佛法。引《楞伽經》、《金剛經》、《華嚴經》、《大寶積經》等，指出大乘經典以如來藏為貫串主軸；依《大般若經》〈付囑品〉解說受持此經的十種法，並批評釋印順把讀誦受持「神祕化」及大乘分系之說。","p":["諸經所說「此經」多指如來藏法義","一切菩薩無上正等正覺皆屬此經","受持此經十法：書寫、供養至修習","法供養為最第一的供養","批評大乘三系、四系及大乘非佛說"],"k":["如來藏","受持此經","十種受持法","法供養","大乘非佛說","釋印順"]},"6803-a27_072":{"s":"本集講解〈提婆達多品〉開頭經文：釋迦往昔為國王，捨位奉事仙人千年以求《妙法蓮華經》。並依《增壹阿含》、律部、《大方便佛報恩經》等敘述提婆達多出佛身血、破僧、墮無間地獄卻如三禪樂，說明他是示現因果與「禪定神通非解脫」的逆行菩薩，前身即為佛說法華的仙人。","p":["釋迦往昔為王，捨國奉仙人千年求法","提婆達多與阿闍世謀新佛新王","地獄中如三禪樂，示現惡業必報","示現四禪五通不能免生死與惡業","千年講法華的仙人即提婆達多前身"],"k":["提婆達多","逆行菩薩","提婆達多品","因果業報","禪定神通","求法"]},"6817-a27_073":{"s":"本集講解〈提婆達多品〉重頌：國王不貪五欲，為眾生求大法而奉事阿私仙。說明唯有《妙法蓮華經》才是真正的「大法」，因其顯示佛地境界與授記等佛不共菩薩之處；聽聞如實演說的法華，可知成佛不易，未來證悟時不致自認成佛而犯大妄語。","p":["國王為眾生而非為己求大法","《金剛經》、般若、種智皆未足稱大法","法華顯示佛地境界，如授記與多寶證明","阿私仙意為無比仙、莊嚴仙","聽法華種下知佛地遙遠的種子"],"k":["大法","佛地境界","授記","阿私仙","大妄語","即身成佛"]},"6815-a27_074":{"s":"本集講解提婆達多為佛之善知識、被授記為天王如來的經文，及聞〈提婆達多品〉淨心信敬可不墮三惡道。重點說明「具足六波羅蜜」：六度須次第修學，不可只修般若；以早期學人未修前五度即開悟而退轉為例，並指出成佛所需功德極多，批評自稱成佛、四地菩薩者。","p":["因提婆達多善知識，佛具足六度諸功德","授記提婆達多成天王如來","六度須次第修，不能只修般若","前五度未具足而開悟易退轉、生慢","三地滿心猶如谷響觀，駁自稱地上菩薩"],"k":["六波羅蜜","提婆達多品","天王如來","淨心信敬","退轉","次第修行"]},"6821-a27_075":{"s":"本集續講〈提婆達多品〉，說明圓滿六度入地後仍須修四無量心、等覺百劫修相好方成正等覺，提婆達多的逆行真相須到法華時才揭曉。以法難促成《燈影》為例說逆行者的作用，並解析天王如來二十中劫住世、天道世界、恆河沙眾得阿羅漢、無量眾不退轉等授記內容。","p":["三地滿心須四無量心，等覺百劫修相好","逆行菩薩真相須最後才揭曉","法難促成《燈影》及八識論的楷定","提婆達多一無量劫可成佛，顯其證量","天王佛住世及正法各二十中劫"],"k":["逆行菩薩","天王如來","百劫修相好","授記","四無量心","八識論"]},"6824-a27_076":{"s":"本集說明聞〈提婆達多品〉淨心信敬不疑者，生生不墮三惡道、生十方佛前、蓮華化生。接講智積菩薩請多寶佛還歸本土、文殊師利從龍宮踊出一段，討論多寶如來「滅度」實為無住處涅槃，並說明應身佛四種不可思議尚未示現完畢，故留多寶佛；千葉蓮華唯佛方坐，顯文殊非等閒。","p":["淨心信敬不疑者永離三惡道","多寶如來滅度與否：無住處涅槃","引《央掘魔羅經》說釋迦永不滅度","四種不可思議：佛、法、僧、佛土","文殊坐千葉蓮華，先禮二世尊"],"k":["淨心信敬","無住處涅槃","四種不可思議","文殊師利","多寶如來","千葉蓮華"]},"6813-a27_077":{"s":"本集以文殊不能令女人出定、罔明菩薩一彈指即出定的典故，說明眾生須與相應層次的菩薩親近。接著解說智積問文殊所化眾生數目、無數菩薩從海踊出，他們已滿六度至少為七地菩薩；智積偈讚「演暢實相義，開闡一乘法」，顯示菩薩僧與佛土不可思議，並將三乘歸結於唯一佛乘。","p":["文殊與罔明菩薩出女人定的典故","凡夫較易親近初地菩薩","從海踊出菩薩已滿六度，至少七地","讚文殊即讚釋迦，喻如水漲船高","三乘、五乘皆歸一佛乘"],"k":["文殊師利","智積菩薩","一佛乘","菩薩僧不可思議","六度波羅蜜","罔明菩薩"]},"6819-a27_078":{"s":"本集說明佛陀先說施論、戒論、生天之論再說四聖諦的說法次第，指出唯一佛乘不易宣說。接講文殊言於海中唯說《法華經》，智積問有無修此經速成佛者，文殊舉八歲龍女，逐句解說其利根、得陀羅尼（以粽子綱喻總持）、慈念眾生如赤子、慈悲仁讓、志意和雅等功德。","p":["施論、戒論、生天之論的說法次第","文殊於海中唯說《法華經》","陀羅尼即總持，旋陀羅尼能運轉","慈念如赤子、仁讓不爭，駁佛爭供養說","佛不妄笑；文殊說龍女能至菩提"],"k":["龍女","陀羅尼","一佛乘","文殊師利","慈悲仁讓","施論戒論生天之論"]},"6826-a27_079":{"s":"本集開講龍女成佛：智積不信龍女須臾成佛，龍女現前以偈讚佛並自言成菩提唯佛證知。講者提醒此品示現四種不可思議，批評以龍女成佛否定法華或轉為男女平等議題者；並回顧從〈方便品〉至〈提婆達多品〉的經文脈絡，說明文殊再度出現的因緣及《妙法蓮華經》甚深微妙。","p":["智積質疑，龍女現前偈讚佛","批評否定法華及男女平等式解讀","地上菩薩可隨願示現女身","回顧〈方便品〉至〈提婆達多品〉要旨","妙法蓮華喻如來藏能生萬法"],"k":["龍女成佛","四種不可思議","提婆達多品","大乘非佛說","如來藏","一佛乘"]},"6835-a27_080":{"s":"本集續講文殊「我於海中唯常宣說《妙法華經》」，說明「常」為始終如此，藉龍宮無數大菩薩顯示釋迦佛土與法不可思議，娑婆非僅穢土。接著解說龍女「善知眾生諸根行業」，引《瑜伽師地論》說善、惡、無記業；並詳述禪定、未到地定、根本定及安住、引發、辦事三種靜慮。","p":["「唯常宣說」指始終只說法華","龍宮菩薩顯釋迦佛土不可思議","智積與文殊一問一答共演大戲","善、惡、無記三業與工巧處業","未到地定、根本定與三種靜慮"],"k":["佛土不可思議","龍女","三種靜慮","未到地定","善惡無記業","瑜伽師地論"]},"6840-a27_081":{"s":"本集解說龍女「深入禪定」至「能至菩提」諸功德：依《伽耶山頂經》判其屬一生補處發心，慈念眾生如赤子、心念口演、慈悲仁讓，顯為妙覺勝義菩薩僧。接講智積「釋迦如來無量劫難行苦行、積功累德」，說明積功為自受用、累德為他受用，並舉捨身飼虎、度外道等難行苦行。","p":["龍女屬一生補處菩薩發心","慈念赤子、四無礙辯等功德","龍女顯示勝義菩薩僧不可思議","積功為自受用，累德為他受用","菩薩難行苦行非外道苦行"],"k":["龍女","積功累德","難行苦行","勝義菩薩僧","一生補處","慈悲"]},"6830-a27_082":{"s":"本集講解智積「無有如芥子許非是菩薩捨身命處」及「不信此女須臾成佛」，以劫數計算說明三大阿僧祇劫捨身之多與成佛之難，證量越高越覺佛地難思。接講龍女偈讚「深達罪福相，遍照於十方」，解為豎窮種智與廣通權智，並引《楞嚴經》十習因六交報說罪福相，強調須深信因果與如來藏。","p":["三千大千世界無處非捨身命處","先說成佛之難才顯龍女可貴","深達罪福相為豎窮種智","《楞嚴經》十習因、地獄鬼畜報","遍照十方為廣通權智"],"k":["深達罪福相","一切種智","三大阿僧祇劫","因果","龍女","如來藏"]},"6832-a27_083":{"s":"本集講解龍女讚佛「微妙淨法身，具相三十二，以八十種好莊嚴法身」：法身指第八識無垢識，並說明阿賴耶識、異熟識、無垢識的階位差別，批評自稱成佛的喇嘛及意識常住之見。再依《大智度論》說相好攝受眾生、福德為證菩提基礎；最後解「我闡大乘教」，顯示龍女即將成佛的勝義菩薩不可思議。","p":["法身即無垢識，非色身音聲可見","阿賴耶、異熟、無垢識的階位","批評意識常住及自稱成佛者","三十二相由百劫修福德而顯","龍女自言闡大乘教度苦眾生"],"k":["無垢識","法身","三十二相","八十種好","龍女","福德"]},"6827-a27_084":{"s":"本集說明文殊為七佛之師、示現輔佐釋迦，龍女為其所度；舍利弗出面質疑「女身垢穢，非是法器」。講者批評以重男輕女或密教「毀謗婦女慧自性」解讀此段，指出一切人實由自心如來所生；並依《瑜伽師地論》說欲界天男女欲漸淡、梵天無男女相，及三十三天五百天女侍一天子，說明女身五障乃法爾如是。","p":["文殊為七佛之師，龍女為其所化","舍利弗質疑女身非法器","批評密教十四根本墮及抱身佛說","欲界諸天男女欲漸淡，梵天無男女相","天主有眾天女奉侍，屬法爾如是"],"k":["女身五障","舍利弗","龍女","欲界天","密教批判","如來藏"]},"6846-a27_085":{"s":"本集續講女身五障：帝釋、魔王為欲界天主必現男相；轉輪聖王七寶中有玉女寶，故以男身示現；佛三十二相有陰藏相，故於人間以男身成佛。講者說明五障非重男輕女，障礙在於內在由貪著五欲形成的「女人性」，並述大愛道出家與八敬法因緣，及觀世音菩薩隨應示現女相。","p":["帝釋、魔王不以女身示現","轉輪聖王七寶有玉女寶","佛三十二相中有陰藏相","障礙在內在的女人性，相由心生","大愛道出家、八敬法與八十四態"],"k":["女身五障","轉輪聖王","陰藏相","八敬法","大愛道","觀世音菩薩"]},"6842-a27_086":{"s":"本集以《維摩詰經》天女轉舍利弗身為例，說明八地以上菩薩於相自在，一切諸法非男非女，龍女示現女身無可質難；不宜只從外相論斷。接講舍利弗「佛道懸曠，經無量劫勤苦積行」，以四宏誓願、佛有百億萬名號、《佛說十號經》「正等覺」及一切種智說明佛道懸曠，並批評大乘非佛說、以解脫道取代佛菩提道者。","p":["天女轉舍利弗身：諸法非男非女","不應只從外相論斷證量","四宏誓願與佛道懸曠","佛於娑婆有百億萬名號","批評以解脫道取代佛菩提道"],"k":["佛道懸曠","一切種智","四宏誓願","非男非女","大乘非佛說","本際"]},"6838-a27_087":{"s":"本集續說「佛道懸曠」：菩薩亦須證二乘一切智，仍要平等開覺眾生並令起大乘作意。講者以世間共享成果之樂對比佛法的此世樂、來世樂，說明世尊以三乘方便度眾，阿羅漢實為久受菩薩教導者；阿含時須提諸法本母、本際才能斷我見。並以「為什麼要學佛」引出離苦得樂與一切法苦的觀察。","p":["菩薩也要證二乘一切智","須令眾生起大乘作意","世間樂與佛法此世樂、他世樂","不提本際則難斷我見","「為什麼學佛」與一切法苦"],"k":["大乘作意","佛道懸曠","一切智","本際","一切法苦","三乘方便"]},"6856-a27_088":{"s":"本集說明苦、空、無我的觀察若只停於蘊處界，學人將趣向無餘涅槃；菩薩進一步顯示一切法匯歸如來藏，故本然解脫。接講〈勸持品〉藥王、大樂說菩薩誓願於惡世受持說此經，講者列十點勉勵自他於娑婆度眾，並說明須先分證解脫道、離五欲，樂住生死同時讚歎遠離生死。","p":["蘊處界觀察：一切法苦、空、無我","一切法匯歸如來藏則本然解脫","藥王等菩薩誓於惡世說此經","十點勉勵：於娑婆度眾不作逃兵","樂住生死亦讚歎遠離生死"],"k":["如來藏","勸持品","佛道懸曠","解脫道","樂住生死","四聖諦"]},"6836-a27_089":{"s":"本集講解〈勸持品〉五百阿羅漢及學無學八千人誓願於他國土廣說此經，因娑婆眾生弊惡、增上慢。說明娑婆為堪忍世界，菩薩攝受眾生即攝受佛土；並引經論計算娑婆修行、護持正法功德遠勝極樂世界，指出如來藏功德與佛無異、心佛眾生三無差別。","p":["阿羅漢誓於他方廣說此經","娑婆得名堪忍世界之由","菩薩不畏惡世，留此護持正法","娑婆護法一須臾勝極樂一大劫","心佛眾生三無差別，指如來藏心"],"k":["勸持品","娑婆世界","護持正法","如來藏","攝受佛土","極樂世界"]},"6844-a27_090":{"s":"本集說明護持正法可加速經歷三大阿僧祇劫，以阿難、迦旃延樂於利樂眾生而成佛速為例；並指出實相心如來藏只有一個。講者敘述佛滅五百年後二乘證者漸少、外道興起而大乘菩薩出世，引《中阿含》說二乘涅槃為施設、依本際而說，二乘涅槃為化城；最後批評釋印順六識論之說。","p":["護持正法可快速經歷三大劫","攝受眾生即攝受佛土","每一有情只有一個實相心","二乘涅槃為施設之化城，依本際","批評釋印順視七八識為意識細分"],"k":["護持正法","如來藏","化城喻","二乘涅槃","八識論","釋印順"]},"6852-a27_091":{"s":"本集講解《法華經》卷4佛為姨母摩訶波闍波提及六千有學、無學比丘尼授記的經文，佛號一切眾生喜見如來，六千人次第相續成佛；並說明授記有初發心授記、現前授記、未發心授記、密授記與廣授記等差別。後半駁斥「佛滅後五百年無大乘經流傳」之說，指部派對如來壽量、真如、心性本淨的激烈爭論，顯示當時已有大乘經。","p":["佛為大愛道及六千比丘尼授記，次第相續成佛","授記有初發心、現前、未發心授記之別","密授記與廣授記（一合掌皆已成佛道）","部派於二乘法義本無異味，分裂另有原因","部派爭論佛壽、真如、心性本淨，可證有大乘經"],"k":["授記","摩訶波闍波提","部派佛教","大乘非佛說","心性本淨","無生法忍"]},"6868-a27_092":{"s":"本集以「摧邪顯正」為題，先剖析一貫道「老母娘」源自斗母（北斗）信仰，又經密宗摩利支天女附會而成，屬求世間吉凶的宗教。再以《成唯識論述記》曾失傳為例，批評歐美學者以流傳記載判定大乘經後出並不可靠；並說明識為生死所依的十因緣法，依《攝大乘論》駁斥釋印順以意識為本、等同阿陀那識的六識論說法。","p":["眾生信邪不信正，護持正法不易","一貫道老母娘出自斗母與摩利支天附會","以《述記》失傳為例，駁歐美學者考證","十因緣法：本識為生死所依與本際","《攝大乘論》分說五識與意識，破印順曲解"],"k":["摧邪顯正","六識論","釋印順","第八識","一貫道","十因緣法"]},"6848-a27_093":{"s":"本集講解羅睺羅母耶輸陀羅受記為具足千萬光相如來、佛壽無量阿僧祇劫，以及諸比丘尼願於他方廣宣此經的經文，勉勵學人應在此土弘揚如來藏妙義。並說明化城、三車、龍女成佛皆指如來藏，報身壽量長遠而法身無生，佛法以無所得為方便；後半批判密宗金剛薩埵、天根信仰及蓮花生、那洛巴、密勒日巴、達賴等雙身法傳承非佛法。","p":["耶輸陀羅獨自受記，佛壽無量阿僧祇劫","化城、三車、龍女成佛皆指此經如來藏","釋迦報身壽量七百阿僧祇劫，示現八十歲","有所得為魔眷屬，佛法以無所得為方便","批判密宗金剛薩埵與雙身法傳承"],"k":["耶輸陀羅","佛壽","如來藏","無所得","密宗雙身法","法身"]},"6859-a27_094":{"s":"本集進入〈勸持品〉（依《法華經講義》第十一輯），說明「勸持」是勸大眾受持、讀誦、廣說此經使其流傳不絕。前三批受記者皆願於他方弘經，世尊乃視八十萬億那由他菩薩；講者依「得諸陀羅尼」判其為九地菩薩，並解說「佛今默然」表菩薩應自行抉擇、承擔果報，以及其獅子吼誓願於惡世十方世界宣說此經、忍受辱罵刀杖。","p":["勸持即勸受持、讀誦、廣說此經","八十萬億那由他菩薩得陀羅尼，為九地菩薩","佛默然：菩薩須自有智慧判斷並承擔","獅子吼：知真實義仍願於惡世十方弘經","偈頌重說以鼓勵心量未廣的菩薩"],"k":["勸持品","獅子吼","陀羅尼","九地菩薩","五濁惡世","忍辱"]},"6854-a27_095":{"s":"本集解說〈勸持品〉偈頌「惡世中比丘，邪智心諂曲，未得謂為得，我慢心充滿」等句。講者以「坐、請坐、請上座」對聯說明諂媚與慢心源於名聞利養，舉趙州三等接待檀越的方便作對照，並對比正覺不分功德主等級、法不買賣；再解釋假阿練若外示清高、實貪利養而為白衣說法，求人視如六通羅漢。","p":["諂曲源於貪財利，對施主分等接待","未得謂得、未證謂證以求供養","趙州三等接待是為正法的方便","正覺不分功德主等級，法不賣","假阿練若自命清高，實為名聞利養"],"k":["勸持品","未得謂得","名聞利養","增上慢","阿練若","諂曲"]},"6849-a27_096":{"s":"本集續講〈勸持品〉偈頌，說明「假名阿練若」的惡比丘為何好出弘經菩薩之過，誣其說外道論議、自作經典。講者指《法華經》所說「此經」即如來藏，批評身受菩薩戒卻倡「大乘非佛說」者為獅子身中蟲，並反駁《法華經》為神話之說，勉勵學人效法諸菩薩安忍誹謗、不求回報而護持正法。","p":["講如來藏者常被罵為外道神我","阿羅漢迴心至入地，距佛地尚遠","受菩薩戒卻倡大乘非佛說，為獅子身中蟲","法華經非後人所能編造，亦非神話","被誹謗仍安忍，只求正法久住"],"k":["勸持品","大乘非佛說","如來藏","安忍","誹謗正法","印順"]},"6860-a27_097":{"s":"本集續講〈勸持品〉，說明佛門最大邪見是把五陰、意識當作真如佛性，而弘揚第八識妙法者反被誣為邪見人；並解釋「汝等皆是佛」為譏諷之語，批評隨意自稱入地者為輕率妄語。接著進入「濁劫惡世中」偈頌，解說五濁以見濁為起因，依次形成煩惱濁、眾生濁、命濁與劫濁，並提及世尊是捨苦行參究實相而成佛。","p":["大邪見：以五陰意識為真如佛性","「汝等皆是佛」是譏諷說法者大妄語","自稱入地卻不解法華真義，即屬輕率","五濁由見濁起，次第成劫濁","世尊捨六年苦行，參究實相而成佛"],"k":["勸持品","五濁惡世","邪見","大妄語","見濁","如來藏"]},"6869-a27_098":{"s":"本集講完〈勸持品〉。先說明五濁之世水、火、風等劫災的成因，勉勵不造惡業共業便無須恐懼；再解釋「惡鬼入其身」、「當著忍辱鎧」、「我不愛身命，但惜無上道」、「數數見擯出」等偈，指弘揚如來藏者常被辱罵、擯出塔寺，應安忍而不故意挑釁；最後以菩薩自稱世尊使、佛自知我心作結，勸誡勿謗三寶。","p":["水劫及二禪、風劫及三禪，欲界有火劫","不造惡業共業，不必恐懼天災","著忍辱鎧，惜無上道而不故入難處","認同如來藏者常被擯出塔寺","我是世尊使，處眾無畏；慎勿謗三寶"],"k":["勸持品","忍辱鎧","無上道","五濁惡世","擯出","護持正法"]},"6866-a27_099":{"s":"本集開始講〈安樂行品〉：文殊菩薩請問後惡世如何說此經，佛答應安住四法，首為菩薩行處及親近處。講者先白話解釋整段經文，說明此處主要指三賢位中已悟的出家菩薩；並詳解「住忍辱地」須以智慧了知「眾生本來如是」而不生氣，同時仍應詳細說明對方錯處以救護之，方具生忍與法忍。","p":["安樂行：後惡世如何弘經而長久利生","文殊請法，佛說應安住四法","所指主要為三賢位已悟出家菩薩","住忍辱地：信受眾生本來如是","忍辱不等於不作為，仍須辨正救護"],"k":["安樂行品","菩薩行處","住忍辱地","親近處","文殊師利","生忍法忍"]},"6862-a27_100":{"s":"本集續講菩薩行處，解說「柔和善順而不卒暴，心亦不驚」應依四攝法的愛語、隨順學人心性，並具足膽與識。再闡釋「於法無所行，而觀諸法如實相」唯證如來藏者能作到，批評應成派的緣起性空實同共生；並說明「亦不行不分別」：無分別的是第八識，覺知心悟後仍須分別，才能救護眾生、護持正法。","p":["柔和善順、不卒暴，重愛語與口德","心亦不驚：有膽有識，仍須提防","三界諸法皆有所行，唯如來藏無所行","緣起須有因，根塵只是緣","無分別是第八識，覺知心不應不分別"],"k":["菩薩行處","於法無所行","如實相","不行不分別","緣起性空","如來藏"]},"6872-a27_101":{"s":"本集先總結菩薩行處的兩部分，再進入親近處：說明不親近國王大臣，舉禪師令皇帝先歸依受戒、慧忠國師以「無縫塔」不輕傳法為例；不親近外道梵志、尼揵子及以文筆讚詠外書者，以免眾生誤認。並詳解「路伽耶陀」順世外道，舉氣功、求長壽、生天、密宗，以及主張意識、細意識或離念靈知常住等說。","p":["菩薩行處：心性轉變與悟後不行不分別","不親近國王大臣；禪師不輕傳法","不親近外道及讚詠外書者，免眾生誤認","順世外道：氣功、長壽、生天、密宗","主張意識或離念靈知常住亦屬順世"],"k":["親近處","順世外道","路伽耶陀","意識常住","離念靈知","慧忠國師"]},"6864-a27_102":{"s":"本集續談順世外道後，解說「逆路伽耶陀」反順世外道，舉老莊無為的消極之說與死後斷滅的斷見論為例，並批評以滅相為真如、又改稱細意識為結生相續識之說承襲宗喀巴；依《瑜伽師地論》指結生相續識為阿賴耶識。講者強調弘法華者不可和稀泥，最後解釋「兇戲、相扠相撲、那羅」等不應親近。","p":["不靠兩邊的老好人中道，亦屬順世","反順世外道：老莊無為與斷見論","《瑜伽師地論》：結生相續識即阿賴耶","斷見論者深心仍執常見","兇戲、相扠、相撲、那羅皆不應親近"],"k":["逆路伽耶陀","斷見","結生相續識","阿賴耶識","宗喀巴","親近處"]},"6875-a27_103":{"s":"本集講完菩薩行處與第一親近處。說明「那羅」角力及「變現之戲」魔術屬障眼欺騙，與誠實執行因果的如來藏相違；不親近屠夫、畜養豬羊雞狗與畋獵漁捕等惡律儀者，但其來訪仍應說法而無所悕望。又解釋不親近求聲聞四眾、亦不問訊之理，並依五種種性說明應觀察對方而隨宜說法。","p":["那羅角力與魔術皆不應親近","如來藏秉公執行因果，從不欺誑","惡律儀者來訪，仍說法而無所悕望","不親近求聲聞四眾，亦不問訊","依種性觀察，隨宜說大乘法"],"k":["親近處","惡律儀","聲聞種性","隨宜說法","五種種性","如來藏"]},"6877-a27_104":{"s":"本集說明末法惡世弘揚如來藏須先安住菩薩行處：除六度作意外，最重要是以實證如來藏所轉依的真如法性為行處，以無所住心行六度。講者引《雜譬喻經》道俗相反，說明如實說法必遭世俗化教界反彈；並引《大般若經》善現答「行在勝義諦，能取所取不可得」及《心經》，闡釋行深般若即轉依無所得的真如。","p":["菩薩行處：轉依如來藏真如法性行六度","道俗相反，如實說法必遭教界反彈","聽聞正法方具信根，能得諸善法","行深般若在勝義諦，無能取所取","悟後未轉依，仍非真正菩薩行處"],"k":["菩薩行處","真如法性","無所得","行深般若","轉依","心經"]},"6891-a27_105":{"s":"本集說明佛對出家實義菩薩的親近處遮止，如不親近權貴、外道、惡律儀者，並避免與女人親密，以免末法眾生誤解。講者將初親近處「常好坐禪，在於閑處修攝其心」對照《大寶積經》三處依止與《維摩詰經》宴坐之義，指真正坐禪是轉依真如；再說明第二親近處須觀一切法空如實相，即諸法自相空、五蘊為如來藏所現。","p":["親近處遮止：權貴、外道、與女人親密","《大寶積經》：住阿蘭若、諍息滅、佛菩提處","維摩詰：不於三界現身意是為宴坐","二乘無常空只是一切法空的表相","五蘊自相空，如大海生聚沫水泡"],"k":["親近處","宴坐","自相空","一切法空","維摩詰","如來藏"]},"6879-a27_106":{"s":"本集續講第二親近處，解說經文「觀一切法空如實相，不顛倒、不動、不退、不轉，如虛空」及「一切語言道斷，不生不出不起，無名無相」。講者指一切法空非斷滅，而是能生萬法的如來藏體性如虛空；並以顯境名言與表義名言說明六識覺知不離語言道，唯如來藏言語道斷；最後說明佛以假名相說法不壞法性，菩薩說如來藏而無所執著。","p":["一切法空非斷滅，指如來藏空性","五蘊有生滅起退，是顛倒有所得法","顯境名言、表義名言：六識不離語言道","夢幻泡影須有如來藏為所依","假名相說法不壞法性，說真如非執著"],"k":["一切法空","如實相","語言道斷","顯境名言","無所有性","如來藏"]},"6880-a27_107":{"s":"本集講〈安樂行品〉重頌「若有菩薩於後惡世，無怖畏心欲說是經」，白話說明應遠離國王、兇險戲者、增上慢人、貪著小乘者、破戒比丘等，若其好心來聽則不懷悕望為說。講者舉網路上達賴喇嘛「佛教應隨科學改變」、「信不信輪迴不重要」等言論加以批評，引《楞嚴經》、《大般涅槃經》說明，並指依法實證方能無怖畏說此經。","p":["重頌重申菩薩行處與應遠離之人","後末世如實說法華必遭反對誹謗","批評達賴「佛教應隨科學改變」之說","《涅槃經》：身雖丈夫，行同畜生","依法實證，方能無怖畏說此經"],"k":["安樂行品","無怖畏心","親近處","達賴喇嘛","我見我執","如來藏"]},"6895-a27_108":{"s":"本集說明「此經」如來藏雖為常住法，卻依《楞伽經》不同於外道之我，並比較聲聞與大乘的空、無相、無願三三昧。接著解說偈中不親近增上慢人與「貪著小乘三藏學者」，引《心地觀經》說親近善友為第一，批評日本學者及其呼應者倡大乘非佛說、尊阿含貶大乘，並區分一世受持的聲聞律與依如來藏盡未來際的菩薩戒。","p":["如來藏非外道神我，引《楞伽經》","聲聞三三昧依蘊處界，大乘依藏識空性","增上慢：未證言證、未悟言悟、錯判果位","貪著小乘三藏者以阿含排斥大乘","聲聞律只一世，菩薩戒依如來藏永受"],"k":["貪著小乘三藏","增上慢","菩薩戒","三三昧","大乘非佛說","如來藏"]},"6887-a27_109":{"s":"本集續說聲聞戒僅盡形壽、菩薩戒依根本方便成已判定罪福，並將遠離「貪著小乘三藏學者」歸結為遠離僧衣崇拜。再解說應遠離破戒比丘、名字羅漢、好戲笑比丘尼及深著五欲求現滅度的優婆夷，若其好心來則不懷悕望為說；並釋「不行上中下法…不分別是男是女」，引《大薩遮尼乾子所說經》說三乘無乘差別，終歸一佛乘。","p":["聲聞戒盡形壽，捨壽後受戒不成","菩薩戒依根本、方便、成已判罪福","貪著小乘三藏即僧衣崇拜","否定七八識即成謗菩薩藏重罪","不行上中下法；三乘無乘差別歸一佛乘"],"k":["菩薩戒","僧衣崇拜","菩薩行處","一佛乘","謗菩薩藏","不分別男女"]},"6897-a27_110":{"s":"本集先回顧初親近處，如不親近寡女、處女、非男及屠夫等，並不行上中下法、不分別男女；再進入第二「法親近處」偈頌「一切諸法空無所有，無有常住亦無起滅」。講者說明佛法可實證而異於宗教與哲學玄想，指空無所有是就蘊處界生滅法而言，生滅法須依不生滅的如來藏而存在，故從如來藏看諸法亦無起滅。","p":["初親近處：避免令人誤會的親近關係","不行上中下法，一體看待眾生","佛法可實證，異於宗教信仰與哲學","生滅法依不生滅法，有為住於無為","諸法本是如來藏中法，故亦無起滅"],"k":["法親近處","一切法空","如來藏","初親近處","生滅法","不生滅法"]},"6883-a27_111":{"s":"本集續講安樂行品「法親近處」，以明珠映現胡人漢人影像為喻，說明五陰諸法空無所有、無有常住，但攝歸如來藏時則無起無滅。並解釋「顛倒分別諸法有無」，舉能量說、造物主等為增益執，並批評印順否定第七、八識為損減執，又立細意識常住而落入增益執。","p":["明珠映像喻：五陰影像歸屬如來藏明珠","諸法空無所有，攝歸如來藏則無起滅","菩薩須先實證，方能如實為人說法","增益執：能量、造物主等虛妄建立為實有","損減執：否定意根與如來藏，再立細意識常住"],"k":["法親近處","如來藏","增益執","損減執","五陰","安樂行品"]},"6889-a27_112":{"s":"本集講「是實非實、是生非生」的顛倒分別，批評六識論者以「性空唯名」判般若，指出般若諸經所說是真實心如來藏；又反駁「阿賴耶識是生滅法」之說，說明真如是第八識體性所顯，舉花與美麗為喻。並解釋「觀一切法皆無所有，猶如虛空無有堅固」，說明虛空是色邊色、有為法住於無為法中。","p":["批評「性空唯名」把般若說成戲論","般若所說非心心、無住心即如來藏","阿賴耶識本有不生滅，離念靈知非真如","真如是第八識所顯性，如花與美麗","虛空依色法邊際施設，有為法住如來藏中"],"k":["顛倒分別","真如","阿賴耶識","性空唯名","般若","法親近處"]},"6894-a27_113":{"s":"本集辨析緣起法與緣生法：緣起法須有如來藏為根本因，藉緣生起諸法；六識論者所說緣起性空實為緣生性空，並以細意識常住落入增益執。接著以明珠影像解釋「不生」，以本住法界大定解釋「不出」，再從位退、行退、念退說明退轉的原因在於心動搖、未得決定。","p":["緣起法以如來藏為因，藉緣生諸法；緣生法只說結果","否定第八識即成無因唯緣的斷滅見","意識粗細皆是意法因緣生","不出：如來藏本住法界大定，不入不出","退有位退、行退、念退，因心動搖"],"k":["緣起性空","緣生法","如來藏","法界大定","不退轉","細意識"]},"6885-a27_114":{"s":"本集說明不退轉的關鍵在心得決定，而心得決定來自親自經歷參究與觀行的過程；區分「了知」與「觀見」，並以佛世時隨聞入觀斷我見證初果為例，強調現量觀行與定力。再從理上說如來藏對一切法從不動心，才是真實的不動不退、常住一相，具足二種親近處方可為人演說此經。","p":["心得決定才能不動、不退轉","參究觀行過程使智慧出生；了知異於觀見","隨聞入觀、具定力方能斷我見得法眼淨","如來藏從不動心，才是真不動不退","常住一相，智慧展開而攝受佛土"],"k":["不動不退","現觀","心得決定","隨聞入觀","常住一相","法親近處"]},"6899-a27_115":{"s":"本集進入安樂行品第二安樂行，說明末法時欲說《法華經》應先住安樂行，經文要求不樂說人及經典過、不輕慢諸餘法師等。講者強調此是對佛門內部而言，對外道及相似像法則須破邪顯正，引《雜阿含》偽寶喻說相似像法流行則正法漸沒；並說明說法時不當眾指人過失，真經各有因緣不應指其不圓滿。","p":["末法說《法華經》須先修安樂行","第二安樂行：不樂說人及經典過","此規範對教內，對外道須破邪顯正","相似像法流行則正法漸沒；辨正非批評人","真經各有因緣，無一部能圓滿三乘"],"k":["安樂行","破邪顯正","相似像法","安樂行品","法義辨正"]},"6905-a27_116":{"s":"本集續講第二安樂行「不樂說經典過」，說明佛依眾生因緣次第說法，先說《華嚴》再說阿含、般若、唯識，最後以《法華經》收攝為圓教，故不應尋真經過失；但偽經須破斥，舉《天地八陽神咒經》及密教經典為例。並講「不輕慢諸餘法師，不說他人好惡長短」，闡釋「僧讚僧，佛法興」的前提與法師的定義。","p":["佛依藏通別圓次第說法，終以法華收圓","真經不應尋過，偽經則須舉證破斥","不說他人好惡長短，不作人身攻擊","僧讚僧的前提是法義正確、不壞正法","說五陰虛妄應厭離者，方為法師"],"k":["安樂行","判教","圓教","偽經","僧讚僧","法師"]},"6907-a27_117":{"s":"本集講第二安樂行中對聲聞人「不稱名說其過惡、不稱名讚歎其美、不生怨嫌」，並批評宗喀巴、印順等主張意識常住為相似像法，說明二乘與大乘中真正法師的條件。講者說初果、二果仍有貪瞋屬正常，不應議論以免謗僧；又說弘菩薩道者不讚歎阿羅漢，答難時以大乘法解說，令得一切種智。","p":["主張意識常住者屬相似像法","依文解義但護正法者應包容讚歎","初果、二果仍有貪瞋，議論其過屬謗僧","不稱名讚歎聲聞，以免引人走羅漢道","答難不以小乘法，但以大乘解說"],"k":["安樂行","聲聞","謗僧","相似像法","一切種智","焦芽敗種"]},"6901-a27_118":{"s":"本集續說「不以小乘法答，但以大乘解說」的用意，舉七葉窟內外結集說明聲聞法不等於成佛之道，定性聲聞被稱焦芽敗種，但菩薩仍可供養阿羅漢以種福田。並總結第二安樂行只針對演述正法者，仿冒佛法者仍須破斥；再解釋偈頌「安隱說法、於清淨地而施床座、澡浴塵穢、著新淨衣、和顏為說」等說法威儀。","p":["七葉窟結集顯示聲聞法非成佛之道","供養阿羅漢：施者、施物、福田三勝","幫弟子發菩薩性勝於幫證阿羅漢","第二安樂行不及於仿冒佛法者","安隱說法：高座、淨身淨衣、和顏說妙義"],"k":["安樂行","焦芽敗種","結集","安隱說法","說法威儀","一切種智"]},"6921-a27_119":{"s":"本集講第二安樂行偈頌：遇難問應隨義而答，以因緣、譬喻、敷演、分別層層解說，方便使人發菩提心、漸入佛道。並說講《法華經》者須除嬾惰意、懈怠想，離諸憂惱，慈心說法，常說無上道教，對衣食供養無所悕望；且須安住生忍、法忍、慈忍以離橫逆，其功德千萬億劫說不能盡。","p":["隨義而答，不答非所問，不知則直言","因緣、譬喻、敷演、分別層層說明","發心即歸依三寶、發四宏誓願","除嬾惰懈怠、離憂惱、慈心說無上道","安住生忍、法忍、慈忍以離橫逆"],"k":["安樂行","因緣譬喻","發菩提心","慈心說法","安忍","無上道"]},"6902-a27_120":{"s":"本集開講〈安樂行品〉第三安樂行，先回顧前兩種安樂行，再解說經文：末世受持此經者無懷嫉妒諂誑之心、勿輕罵學佛道者、勿惱人令其疑悔。講者認為在無了義正法時即同末法，批評相似像法、應成派中觀及以能見能聞為佛性之說；並以平實導師親身經歷說明疑悔障道，強調不輕未學、不輕新學。","p":["無了義正法、只剩表相佛法即是末法","真密教是如來藏密意，批評顯密之分","受持此經者無嫉妒、諂媚、欺誑之心","輕視學人會令其疑悔，疑悔障道甚深","不輕未學、不輕新學，因有隔陰之迷"],"k":["第三安樂行","安樂行品","疑悔","相似像法","不輕新學","嫉妒諂誑"]},"6915-a27_121":{"s":"本集續講第三安樂行，說明不可對學人說「汝等去道甚遠、終不能得一切種智」，因人有隔陰之迷，舉不識字老菩薩開悟與六祖慧能為例。又講「不應戲論諸法、有所諍競」，批評狂禪以輕語說如來，說明有諍競心表示異生性未斷。最後解釋「於一切眾生起大悲想」，對照第四安樂行的大慈心，並引《大智度論》區分小悲與大悲。","p":["勿斷言他人無望開悟，人有隔陰之迷","舉不識字老菩薩與六祖慧能為例","不應戲論諸法，狂禪輕語說如來不足取","有諍競心表示異生性未斷，真悟者不諍","對世俗眾生起大悲；大悲能令脫苦"],"k":["第三安樂行","不輕新學","戲論","諍競","大悲","隔陰之迷"]},"6917-a27_122":{"s":"本集講第三安樂行「於諸如來起慈父想、於諸菩薩起大師想」。說明菩薩階位越高越知不了如來境界，乃至一生補處菩薩亦起慈父想；起大師想前須先定義菩薩，分凡夫、名義、勝義菩薩與菩薩摩訶薩，不應對否定正法者起大師想。並說歸依應歸依十方常住菩薩僧，平等說法須隨順根機、不多不少。","p":["如來恩逾慈母，應起慈父想","階位越高越覺不知如來境界","菩薩分凡夫、名義、勝義菩薩及摩訶薩","歸依十方常住菩薩僧，而非個人","平等說法：觀根機，不多不少"],"k":["第三安樂行","慈父想","大師想","菩薩摩訶薩","歸依十方僧","隨機說法"]},"6913-a27_123":{"s":"本集續講「平等說法、不多不少」，依《楞伽經》五種種姓說明對無種姓者說人天善法或因果，並舉阿含中佛先說施論、戒論、生天之論；強調平等是依立足點而非齊頭式平等，深愛法者亦不為多說。接著總結第三安樂行，解說成就者無能惱亂及偈頌要旨：捨嫉恚慢、恭敬三寶、慈悲一切，並批評訶佛罵祖之狂禪。","p":["五種種姓，各依其性說適宜之法","無種姓者說人天善法或因果律","佛對外道先說施論、戒論、生天之論","平等非齊頭式；深愛法者亦不多說","對上恭敬三寶，對下起大悲，避狂禪"],"k":["第三安樂行","五種種姓","人天善法","平等說法","恭敬三寶","狂禪"]},"6909-a27_124":{"s":"本集總結第三安樂行，強調所恭敬的是大乘佛法與十方菩薩僧；說法者有大悲心並恭敬三寶，即使有錯聽眾也不惱亂。解釋「得好同學共讀誦是經」，同學如來藏則不分裂，舉部派佛教分裂為對照，並談福慧雙修。再解說偈頌：捨嫉恚慢與諂誑邪偽、常修質直行、不輕蔑於人、不戲論法、不令他疑悔說「汝不得佛」。","p":["恭敬大乘三寶，歸依十方菩薩僧","有大悲心、敬三寶，說法無人惱亂","得好同學則同見同行；部派因異學分裂","福慧如金翅鳥雙翼，須同時增長","不輕蔑人、不戲論法、不洩密意"],"k":["第三安樂行","好同學","質直行","法毘奈耶","福慧雙修","部派佛教"]},"6919-a27_125":{"s":"本集開講〈授記品〉，說明學佛的大目標是成佛而非只求解脫，成佛需長劫修行，批評即身成佛等說法；並解釋授記的意義。接著講佛授記摩訶迦葉當供養三百萬億佛而成光明如來，國名光德，國土莊嚴、魔民皆護法；又講目犍連等請求授記，須菩提受記為名相如來，並依平實導師之說以須菩提瞋習與好住空性說明其成佛較慢，勸勿起瞋。","p":["學佛大目標是成佛，非只求解脫","授記：佛預告成佛時、國土與名號","摩訶迦葉授記為光明如來，國名光德","須菩提授記為名相如來","須菩提因瞋習與好空性而成佛較慢"],"k":["授記品","授記","摩訶迦葉","須菩提","成佛之道","瞋習"]},"6911-a27_126":{"s":"本集續講〈授記品〉，解說大迦旃延供養諸佛、起七寶塔廟，當成閻浮那提金光如來，國土平正、無四惡道，講者以其心性柔和、重人情、行四攝法說明國土依報。再講大目犍連當成多摩羅跋栴檀香如來，劫名喜滿、國名意樂，並以其神通生慢的故事說明慢心障道。最後提到五百弟子皆當授記，勸勉勿起瞋慢、廣結善緣。","p":["大迦旃延當成閻浮那提金光如來","心性柔和、行四攝感得國土平正無惡道","目犍連當成多摩羅跋栴檀香如來","目犍連神通生慢，慢心障道","五百弟子皆當授記，勸勿起瞋慢"],"k":["授記品","大迦旃延","目犍連","四攝法","慢心","佛國淨土"]},"6923-a27_127":{"s":"本集講〈安樂行品〉中《法華經》的珍貴：化身佛不講此經，唯應身佛示現成佛時才說，故無量國中難聞其名。解說髻中明珠喻：鐵輪王依戰功賞賜而不予髻中明珠，如來以禪定、智慧力王於三界，魔王不服，賢聖弟子與五陰魔、煩惱魔、死魔、天魔作法戰。並引《不退轉法輪經》佛答魔王「度眾生而眾生未得度」的故事。","p":["化身佛不講《法華經》，唯應身佛說","髻中明珠喻：鐵輪王不以髻珠賞賜","如來以禪定、智慧力王於三界為法王","「度眾生而未得度」：如來藏本在彼岸","賢聖諸將斷煩惱，與無形四魔作戰"],"k":["髻中明珠","安樂行品","法王","天魔","四魔","應身佛"]},"6931-a27_128":{"s":"本集續講「如來賢聖諸將與魔共戰」，說明賢聖弟子以法義辨正救護眾生，並詳析離念靈知屬意識心、與五別境心所相應、以意根與六塵為俱有依，非第八識真如。又說明天魔不干擾只修欲界善法者，唯對證初禪而不離欲界度眾的菩薩干擾，以大地主與牛羊喻說明；魔考即五欲之繩，斷三縛結即令魔宮震動。","p":["賢聖弟子摧邪顯正，即是與魔共戰","離念靈知是意識心所，非真如","天魔只干擾證初禪而留欲界度眾者","大地主與牛羊喻；魔考即五欲之繩","有人斷三縛結證初果，魔宮即震動"],"k":["與魔共戰","離念靈知","天魔","魔考","初禪","三縛結"]},"6925-a27_129":{"s":"本集講如來對與魔共戰有功者賜以禪定、解脫、無漏根力及諸法之財，最後才賜《法華經》。講者以正覺同修會學人經驗說明修學次第清楚，依阿含自檢初果至四果的斷結內涵；並說菩薩證如來藏真如而知本來自性清淨涅槃，以與阿羅漢問答說明本際即異熟識。再談菩薩禪定與外道不同，及信根所依的三寶意涵。","p":["如來賜禪定、解脫、無漏根力、法財","《法華經》是最後賜與的最勝法財","依阿含自檢初果至四果的斷結","菩薩證真如，知本來自性清淨涅槃","菩薩禪定增益無漏根力；信根依三寶"],"k":["無漏根力","解脫道","本來自性清淨涅槃","五根五力","三寶","禪定"]},"6927-a27_130":{"s":"本集續講五根五力：信根圓滿生信力，以種子生根發芽為喻。引《大乘本生心地觀經》修勝道四法要：親近善友、聽聞正法、如理思量、如法修證，並引《華嚴經》說真善知識難遇，依《瑜伽師地論》說明以算數、稱量行相思惟諸法。最後說明念根念力、定根定力、慧根慧力依次增長，至斷三縛結證初果，再求明心見性。","p":["信根圓滿方生信力，如根穩方發芽","四法要：親近善友、聽聞正法等","如理思量：算數行相與稱量行相","如法修證：法隨法行、尋思伺察","念、定、慧根力漸增，至證初果"],"k":["五根五力","四法要","善知識","如理作意","法隨法行","三縛結"]},"6929-a27_131":{"s":"本集續講〈安樂行品〉如來賞賜弟子的法財，說明「諸法之財」即聲聞、緣覺、佛菩提三乘諸法，並解釋「又復賜與涅槃之城，言得滅度」一段經文。講者區分二乘的有餘、無餘涅槃與大乘四種涅槃，指出本來自性清淨涅槃非修得亦非不修得，並說明佛要等弟子各種條件具足後才演說《法華經》。","p":["諸法之財即聲聞、緣覺、佛菩提三乘諸法","二乘須斷盡煩惱才證有餘、無餘涅槃","大乘四種涅槃，其中兩種不共二乘","本來自性清淨涅槃本有，非修得非不修得","菩薩留惑潤生，條件具足後佛才說法華"],"k":["涅槃","諸法之財","本來自性清淨涅槃","無住處涅槃","留惑潤生","三乘菩提"]},"6933-a28_001":{"s":"本集講〈安樂行品〉轉輪聖王解髻中明珠賞賜大功者之喻，說明如來見弟子與五陰魔、煩惱魔、死魔戰有功，最後才演說祕藏的《法華經》。講者把經意分為四個重點，本集先講第一點：轉輪聖王有金、銀、銅、鐵四種，並介紹金輪王的七寶、四德、王四天下、千子具足，以及賢劫千佛的由來與頂生王的故事。","p":["髻中明珠喻：法華經是諸佛祕密之藏，最後才說","經意分四重點：輪王、四魔、一切種智、善巧方便","金輪王具七寶、四德、王四天下、千子具足","賢劫千佛由來；頂生王貪五欲而墮落命終","經中動兵征戰的轉輪聖王是鐵輪王"],"k":["安樂行品","轉輪聖王","髻中明珠","賢劫千佛","七寶","頂生王"]},"6942-a28_002":{"s":"本集續講〈安樂行品〉第二個重點：魔有四種。先說明魔能奪眾生法身慧命、障礙修行，再依次講五陰魔（以聚沫、泡、燄、芭蕉、幻來比喻五陰生滅）、煩惱魔、死魔（喪子婦人聞法證初果）與天魔波旬，並舉同修會退轉事件、新書發表受阻等例，勸人提高警覺，別讓天魔有機可乘。","p":["魔能奪眾生法身慧命，障礙破壞修行","五陰皆生滅法；一念不生仍落在想陰","煩惱魔：貪瞋癡及謗真善知識造成無明","死魔：喪子婦人知死而證初果","天魔波旬阻撓修行人與正法弘傳"],"k":["四魔","五陰魔","煩惱魔","死魔","天魔","無餘涅槃"]},"6947-a28_003":{"s":"本集講〈安樂行品〉第三個重點：一切種智的內涵。講者從明心證如來藏入第七住開始講起，說明解脫德、法身德、般若德三德，再講相見道的後得無分別智與如幻、陽焰、如夢三種現觀，然後是入地的增上意樂、諸地現觀，一直到妙覺成佛時四智圓明。講者強調一切種智以真見道為基礎，沒有明心而自稱活佛、法王就是大妄語。","p":["一切種智為佛地，道種智屬地上菩薩","明心入七住，發起解脫、法身、般若三德","相見道別相智：如幻、陽焰、如夢三觀","發十大願、增上意樂清淨後才入初地","歷經諸地至妙覺，四智圓明成一切種智"],"k":["一切種智","道種智","明心","根本無分別智","後得無分別智","非安立諦三品心"]},"6953-a28_004":{"s":"本集講〈安樂行品〉第四個重點：佛度眾生的善巧方便。講者先說明華嚴、阿含、般若、方等、法華涅槃五時與藏、通、別三教，再講四悉檀中的三種：世界悉檀（五陰世間與器世間，以及施論、戒論、生天之論的說法次第）、為人悉檀（隨根器三轉法輪）、對治悉檀（舍利弗教錯方法、難陀貪戀美色的故事）。第一義悉檀留到下集再講。","p":["佛說法四十九年，匯歸五時三教","世界悉檀：二種世間皆阿賴耶識所變現","施論、戒論、生天之論是諸佛常用的說法次第","為人悉檀：依眾生根器三轉法輪","對治悉檀：依煩惱施教，如二比丘與難陀"],"k":["四悉檀","五時三教","善巧方便","世界悉檀","對治悉檀","為人悉檀"]},"6938-a28_005":{"s":"本集講第一義悉檀：佛在初轉法輪時隱說涅槃本際，以「名色緣識」顯示二乘入無餘涅槃不是斷滅，但二乘人並未證得本際；二轉般若時旁開別教，讓弟子證悟真心，之後依三大阿僧祇劫的次第修行。接著解說「此經為尊」偈中讀誦、演說《法華經》的功德與好夢，並批評喇嘛教把五方佛配上各種顏色，主張佛的常光、身光是金色。","p":["初轉隱說本際，名色緣識顯示涅槃非斷滅","二乘人未證本際；菩薩證之不可思議","般若時旁開別教，菩薩悟後依次第修行","演說法華經者得種種功德與好夢","佛身光為金色，批評喇嘛教五佛配色"],"k":["第一義悉檀","無餘涅槃本際","名色緣識","佛身金色","喇嘛教","三大阿僧祇劫"]},"6944-a28_006":{"s":"本集解說〈安樂行品〉偈「佛為四眾說無上法……得陀羅尼，證不退智」。講者說明佛所說都是無上法，二乘菩提本是佛菩提的一部分，只是依次第鋪陳；夢中合掌讚佛是瑞相。接著談供佛的功德田與報恩田，並解釋法、義、咒、忍四種陀羅尼的意涵，指出每一個修證階位各有這四種陀羅尼。","p":["佛說皆無上法，二乘菩提屬佛菩提一部分","排斥大乘時，所說二乘法就不是佛法","夢中合掌讚佛、聞法供養屬於好相","供佛是功德田兼報恩田","法、義、咒、忍四種陀羅尼，各階位皆有"],"k":["陀羅尼","不退智","無上法","供佛","四悉檀","安樂行品"]},"6949-a28_007":{"s":"本集續講夢中或定中見佛聞法時，應如實勝解並作供養，以得陀羅尼與不退智。講者指出退轉者缺少義、咒、忍陀羅尼，不肯受持阿賴耶識；並說明不退智的層次、授記的具體內容與密授記。接著解說「諸佛身金色……常有是好夢」，強調要依四安樂行及兩種親近處演說《法華經》，不可用二乘法解經，也不可自讚毀他。","p":["聞法要勝解、供養，得陀羅尼證不退智","退轉者缺義、咒、忍陀羅尼，不受持阿賴耶識","不退分信、位、行、念、究竟不退","授記有具體內容；定中密授記不宜外說","依四安樂行、二親近處如實演說法華"],"k":["不退智","授記","陀羅尼","四安樂行","親近處","夢中見佛"]},"6955-a28_008":{"s":"本集解說〈安樂行品〉偈「又夢作國王，捨宮殿眷屬……如煙盡燈滅」。講者以石崇、和珅說明國王所享的上妙五欲，並講菩提樹與師子座的名稱由來、釋迦如來六年苦行後改行中道而成佛。講者也說明夢中成佛度眾、長劫入短劫的道理，「如煙盡燈滅」並不是斷滅；最後勸大眾發願在未來世如實宣講《法華經》。","p":["國王的上妙五欲是人間最勝，菩薩能捨","菩提樹因佛在樹下成道而得名","釋迦六年苦行後改行中道，夜睹明星成佛","夢中也能度眾；如煙盡燈滅不是斷滅","惡世說第一法得大利，應發願講法華"],"k":["安樂行品","上妙五欲","菩提樹","夢中成佛","如煙盡燈滅","發願"]},"6940-a28_009":{"s":"本集開講第十五品〈從地踊出品〉：他方來的八恆河沙菩薩請求在佛滅後護持此經，佛制止他們，說娑婆世界自有六萬恆河沙菩薩，各帶六萬恆河沙眷屬。講者談在此土如實演講《法華經》之難、菩薩應感恩戴德、度眾不起慢心，並解釋三千大千世界、地裂與「下方虛空」的意思，以及「唱導之首」的含義。","p":["他方菩薩願護持此經，佛止之","娑婆自有六萬恆河沙菩薩及眷屬","如實演講法華難，真菩薩必感恩戴德","與諸佛所度相比，度眾不應起慢心","娑婆是三千大千世界，菩薩住下方虛空"],"k":["從地踊出品","六萬恆河沙菩薩","三千大千世界","唱導之首","護持法華","慢心"]},"6952-a28_010":{"s":"本集解說從地踊出的菩薩們禮拜多寶如來與釋迦牟尼佛，讚歎經過五十小劫，佛以神力令大眾覺得如同半日。講者以平實導師夢中蒙世尊召見、呈現前世一事，說明時間是相對的，長劫可入短劫；並依《解深密經》說修行的劫數隨精進程度而不同。講者也談末那識的習氣、判別夢境的方法，以及尚未證得不等於不存在。","p":["菩薩禮讚二世尊五十小劫，佛力令如半日","時間是相對的，長劫入短劫非神話","依精進程度不同，一劫可短至一剎那","末那遍緣一切法，習氣須長時轉變","判別夢境；未親證不等於不存在"],"k":["從地踊出品","長劫入短劫","時間","末那識","夢境","多寶如來"]},"6963-a28_011":{"s":"本集講從地踊出菩薩眾中的四位上首唱導之師：上行、無邊行、淨行、安立行，以及他們向世尊問訊「少病少惱、安樂行不」。講者逐一說明四位菩薩分工所教：上行教一切佛法往上修，無邊行教種種菩薩行與次法，淨行教斷三界愛的現行與習氣種子，安立行教如何施設五時三教等權巧方便；並以五十三層樓為喻說明修行階位。","p":["四導師：上行、無邊行、淨行、安立行","上行教一切佛法，無邊行教無量次法","淨行：先斷我見我執現行，再斷習氣種子","安立行：施設五時三教等方便，安立不虛妄","以五十三層樓喻說明成佛階位"],"k":["四大菩薩","唱導之師","安立行","淨行","五時三教","次法"]},"6967-a28_012":{"s":"本集解說四大菩薩的問訊：為何不問「遊步輕利」，而問「少病少惱、安樂行不」，以及應身佛為何也會生病、需要密跡金剛護持，並比較五濁惡世與人壽八萬四千歲度眾的難易。世尊回答眾生容易化度，是因為他們世世受佛教化，只有學小乘者例外。講者指出「此經」就是如來藏，不容易聽聞，並舉「聽無」公案，說明《金剛經》不是講一切法空。","p":["下方菩薩住虛空，故不問遊步輕利","應身佛隨眾生而有病，需密跡金剛護持","五濁惡世度眾辛苦，故須問訊安樂行","所化眾生世世受教，易度；學小乘者難","此經即如來藏，難以真正聽聞"],"k":["此經","如來藏","應身佛","五濁惡世","問訊","從地踊出品"]},"6957-a28_013":{"s":"本集解說四大菩薩以「善哉善哉大雄世尊」讚佛，以及世尊稱許他們能發隨喜心。講者說明諸佛的報身、意生身、法身都沒有人能傷害，所以稱「大雄」；說「易可化度」指的是那些大菩薩，而非人類。講者並以阿那律穿針的故事勸人隨喜、不起嫉妒。之後彌勒菩薩代表大眾以偈請問：這些菩薩從何處來、因什麼因緣聚集。","p":["實證此經後讀金剛經，才算入於佛慧","諸佛三身不可傷，故稱大雄世尊","易可化度指下方大菩薩，非人類","應隨喜不嫉妒；阿那律穿針喻福德不嫌多","彌勒代眾請問踊出菩薩的來處與因緣"],"k":["大雄世尊","隨喜","入於佛慧","密跡金剛","彌勒菩薩","從地踊出品"]},"6973-a28_014":{"s":"本集續解彌勒菩薩的請問偈：踊出菩薩的眷屬數量多到用竹籌計算恆沙劫也數不完，並問是誰教化他們、從誰初發心、修什麼經，分身諸佛的侍者也同樣發問。世尊讚歎阿逸多後，表示將宣示諸佛的智慧、自在神通、師子奮迅、威猛大勢四種力量。講者批評六識論者與釋印順把阿羅漢當作佛，強調佛智不可思議，自稱成佛者必是凡夫。","p":["踊出菩薩無量，行籌數經恆沙劫仍不能盡","彌勒問誰為說法、從誰發心、修何佛道","分身佛侍者亦問，佛令待彌勒問答","佛將宣示智慧、神通、奮迅、威猛四力","佛智叵思議，批評以羅漢為佛之說"],"k":["佛智叵思議","彌勒菩薩","釋印順","六識論","分身諸佛","從地踊出品"]},"6962-a28_015":{"s":"本集說明大阿羅漢一世證果其實是方便說，因為他們多劫以來就隨佛修學；也提到正覺不急於取證阿羅漢的門風。接著闡釋佛將宣示的四力：自在力（應身之外的報身、自受用身、他受用身無人能害）、神通力、師子奮迅三昧（從未到地定、初禪到四禪八定的深淺與難度），以及由智慧、自在、神通、禪定與廣大福德匯成的威猛大勢之力。","p":["大阿羅漢一世證果是方便說，多劫已修","菩薩不急取解脫果，入地前才斷五下分結","諸佛三身自在，唯應身需密跡金剛護持","師子奮迅三昧：禪定順逆往返迅速自在","威猛大勢力由智慧、神通、禪定、福德成"],"k":["師子奮迅三昧","威猛大勢之力","自在神通","阿羅漢","禪定","福德"]},"6965-a28_016":{"s":"本集解說世尊偈「當精進一心……佛智叵思議」：講者說明聽聞佛境界時容易生起的疑與掉悔，以及實證佛法的條件（除性障、修福德、鍊定力、熏般若知見）；又說「出信力，住於忍善」，佛四十九年所說有限，佛無不實語。講者批評「大乘非佛說」，並解說世尊宣告踊出菩薩是成道後教化、住下方虛空，再以三地滿心菩薩意生身說明佛化度之廣。","p":["聞佛境界勿疑勿悔，佛智叵思議","實證須除性障、修福德、鍊定力、熏知見","四十九年所說有限，佛無不實語","批評大乘非佛說；證量越高越知佛智難測","三地滿心意生身度眾，何況諸佛"],"k":["佛智叵思議","疑悔","信力","大乘非佛說","意生身","從地踊出品"]},"6969-a28_017":{"s":"本集從「此諸菩薩，皆於是娑婆世界之下此界虛空中住」講到諸佛的淨土，說明四種佛土：凡聖同居土、方便有餘土、實報莊嚴土、常寂光淨土，並以極樂世界上、中、下三品往生者為例，指出四土依智慧心境施設，不是分層居住。講者認為儀器、學術無法檢驗證悟，應以至信、仰信信受佛語；並解說菩薩「讀誦通利、思惟分別、正憶念」。","p":["娑婆不只有人間這種穢土","四土：凡聖同居、方便有餘、實報莊嚴、常寂光","極樂三品往生分住三土，依心境而非分層","儀器與學術無法檢驗證悟，應信受佛語","讀誦通利、思惟分別、正憶念源於勝解"],"k":["四種淨土","實報莊嚴土","方便有餘土","極樂世界","凡聖同居土","正憶念"]},"6959-a28_018":{"s":"本集解說踊出菩薩修道的樣子：不樂在大眾中多說話、常樂靜處勤行精進、不依止人天而住、愛樂深智，以及二乘法為何只在人間演說。接著講世尊重宣偈「阿逸汝當知」：這些菩薩是佛無數劫來所化，令發大道心；講者說明如來藏金剛心是成佛標的，佛稱為「我子」者至少已入地，並說明捨憒鬧、常行頭陀與入地所需的過程。","p":["不樂在眾多說，離攀緣，常樂靜處精進","下方虛空淨土菩薩樂諸佛法，不求二乘","二乘法適合人間說，諸天不易相應","如來藏金剛心不可壞，為成佛標的","被佛稱為我子者至少已入地"],"k":["捨憒鬧","精進","佛子","大道心","如來藏","頭陀行"]},"6976-a28_019":{"s":"本集解說「學習我道法」中的道與法。講者比較世間道與天道（以一貫道、基督教的天堂為例，評其仍不出欲界），說明佛所傳的是聲聞道、緣覺道、菩薩道三道及各自的法門，佛菩提道兼含通教與別教。講者又以道德與方術的關係，指出用三乘菩提謀取名利是有術無道，批評密宗收費傳咒，並強調法與次法都要傳、都要修。","p":["世間道、天道仍在欲界，不及解脫道","佛傳聲聞、緣覺、菩薩三道，各有其法","入地前須通達三乘，入地後明確授記","有術無道者以三乘謀名利，是退轉","傳法須兼傳次法；批評密宗收費傳咒"],"k":["道與法","法與次法","菩薩道","三乘菩提","授記","天道"]},"6972-a28_020":{"s":"本集講解〈從地踊出品〉偈頌「晝夜常精進」至「我從久遠來，教化是等眾」，說明下方空中住的菩薩精進求佛道、志念力堅固、說法無畏，至少為地上菩薩。並述世尊於菩提樹下參究成佛、三轉四聖諦法輪度五比丘之艱難，預告彌勒將代眾請問。","p":["精進為求佛道，精進必有佛菩薩感應","下方空中住為方便施設的實報莊嚴土","志念力堅固源於勝解具足與重法之心","世尊於菩提樹下參究成佛，非靠入定","三轉十二行法輪，此等菩薩久遠受教化"],"k":["從地踊出品","精進","三轉法輪","四聖諦","地上菩薩","念力"]},"6985-a28_021":{"s":"本集講解〈從地踊出品〉彌勒菩薩與大眾生疑、以「二十五歲人指百歲人為子」為喻請問世尊的經文。講者指出不可因儀器無法檢驗或自己未證就否定如來藏等唯證乃知之事；有所不解應歸於自己智慧未到，不可懷疑真經，並批評否定如來藏者與六字大明咒所依的偽經。","p":["彌勒代眾請問：成佛四十餘年何能化無量菩薩","父少子老之喻，世所難信","儀器檢驗不了心，如來藏唯證乃知","未知之事應歸己智淺，不可疑佛所說","妙覺菩薩尚且請問，凡夫勿謗法華為神話"],"k":["從地踊出品","彌勒請問","父少子老喻","如來藏","唯證乃知","偽經"]},"6977-a28_022":{"s":"本集續講彌勒請問的經文，說明六萬恆河沙菩薩眾的數量與證量，指出此問只是依世間表相而發。講者以平實導師此世學佛五年、參禪半小時即明心見性為例，說明往世證悟種子今世現行；又述世尊示現一夜成佛，並辨正「人中之寶」（仁波切）須斷我見且證實相，批評密宗濫用此名。","p":["從地踊出菩薩數量無量，皆有意生身","彌勒明知故問，為大眾請問釋疑","導師半小時明心見性，乃往世種子現行","世尊示現一夜成佛，前事皆為示現","人中之寶須斷我見並證法界實相"],"k":["從地踊出品","表相","往世種子","明心見性","人中之寶","仁波切"]},"6981-a28_023":{"s":"本集語譯〈從地踊出品〉彌勒菩薩重宣的偈頌，並講述悉達多太子降生說「天上天下唯我獨尊」、相師預言、淨飯王建四季宮殿留太子等示現因緣。講者指出唯我獨尊是指人人本有之心，人身可以成佛、佛法非宿命論；佛菩提道須三大阿僧祇劫，世尊成佛實為示現。","p":["彌勒以偈重問，恐後世生疑墮惡道","唯我獨尊指每人身中本有的真心","人間為六道樞紐，佛法非宿命論","相師預言太子必出家成佛","佛道須三大阿僧祇劫，非一世成就"],"k":["從地踊出品","彌勒偈頌","三大阿僧祇劫","示現成佛","唯我獨尊","宿命論"]},"6990-a28_024":{"s":"本集解釋偈中「忍辱心決定」，指出一般只談眾生忍，真正困難的是法忍。聲聞法忍在於接受覺知心、識陰虛妄，智慧上的心得決定遠勝禪定之力；並依《阿含正義》說明修因緣法須先懂十因緣「名色緣識、齊識而還」，批評執細意識、離念靈知為真如者未斷我見，指出無明死後存於如來藏。","p":["忍辱不只眾生忍，法忍更難","聲聞法忍：接受覺知心與識陰虛妄","智慧的心得決定勝於非想非非想定","不懂十因緣，因緣法無法成就","執細意識為真如，仍落名色未斷我見"],"k":["忍辱心決定","法忍","十因緣","識陰虛妄","名色","我見"]},"7004-a28_025":{"s":"本集續說三乘的「忍辱心決定」：依十因緣推知名色由本識如來藏所生，修十二因緣便不怕斷滅而能成辟支佛，此為緣覺法忍；通教菩薩再求證名色所緣之識，得大乘真見道的忍辱心。並說明真見道、相見道至初地通達位的次第，以《金剛經》被輕賤仍不退為例，說明實相智慧令忍辱心決定。","p":["名色由本識所生，齊識而還不能過彼","知有本識不墮斷滅，因緣觀方能成就","通教菩薩須證本識方入大乘見道","真見道、相見道至初地方為通達位","被輕賤仍不退轉，即大乘忍辱心決定"],"k":["忍辱心決定","十因緣","十二因緣","緣覺","真見道","相見道"]},"6987-a28_026":{"s":"本集導讀《法華經講義》第十四輯「忍辱心決定」一句，指出忍辱不是表面強忍或和稀泥。講者對照鳩摩羅什譯本與黃寶生新譯，認為此段說的是久學菩薩應有的修證與菩薩修行位階，批評太虛大師僅作字面解釋；並指出華文佛教界少有人講五十二階位，因講者自身未證解脫，無從宣說解脫知見。","p":["強壓怒氣、和稀泥並非真忍辱","唯四雙八輩才是佛的賢聖弟子","對照新舊譯，此段說菩薩修行位階","一字一拜拜法華，對道業助益有限","未得解脫者無法教人解脫知見"],"k":["忍辱心決定","五十二階位","久學菩薩","解脫知見","四雙八輩"]},"6980-a28_027":{"s":"本集說明「忍辱心決定」是對所證之法得決定忍，以法智忍、法智、類智忍、類智解釋修證完成的過程。講者指出初地之前皆可能退轉，二乘三果前亦有退分，引《中阿含》十八學人、九無學人與《菩薩瓔珞本業經》舍利弗等退轉之例，並以《經律異相》初果人退失後精進證三果的彩畫瓶故事為證。","p":["安忍即真正接受安住，於法得決定","法智忍、法智、類智忍、類智的次第","福德不足常致證悟後退轉","初地方為行不退，七住以前名退分","彩畫瓶喻：初果人重拾修證至三果"],"k":["忍辱心決定","法智忍","退轉","四向四果","行不退","福德"]},"6983-a28_028":{"s":"本集先引《雜阿含》與《瑜伽師地論》說明涅槃是內證法，不能僅靠信解思惟，每一位階都有應完成的忍辱心決定。接著介紹十信位的六堅（堅信、堅法、堅修、堅德、堅頂、堅覺）與初住至六住的信忍、法忍、修忍、正忍，以新手父親漸漸接受孩子為喻說明安忍，並強調六住斷我見、修四加行的重要。","p":["涅槃須實證，不能僅由信與思惟得","五十二位階各有應完成的心決定","十信位須完成六種堅固","安忍如新手父親漸漸接受孩子","六住正忍：斷我見、修四加行"],"k":["五十二階位","十信位","十住位","安忍","斷我見","四加行"]},"6992-a28_029":{"s":"本集續講菩薩位階，引《菩薩瓔珞本業經》說明七住以前為退分，得善知識護持方能入七住位不退。依序介紹七住無垢忍（證如來藏）、八至十住一切智忍（十住眼見佛性、世界如幻觀）、十行位聞慧至寂照慧（牢關），以及十迴向位習相定、性定至正觀定，並說明銅、銀、金寶瓔珞的差別。","p":["七住以前名退分，須善知識護持","七住無垢忍：現觀如來藏，真見道","十住眼見佛性，具世界如幻觀","十行位由聞慧至寂照慧，過牢關","十迴向修習相定至正觀定，準備入地"],"k":["七住位","眼見佛性","十行位","十迴向","菩薩瓔珞本業經","位不退"]},"7009-a28_030":{"s":"本集講入地後的十地位階與六觀。先以世親菩薩由五百部小乘論迴小向大、因曾謗大乘而僅鄰於初地的事蹟，說明入地之難，並批評「唯識三年，俱舍八年」之說。接著介紹初至三地住觀、四地行觀、五地向觀、六地重觀、七地無相觀、八至十地一切種智觀與等覺妙覺，最後指出法忍難成多因福德不足。","p":["世親謗大乘後迴心，僅鄰於初地","批評「唯識三年，俱舍八年」之說","初至三地住觀，三地發起意生身","五地向觀、七地無相觀、八地一切種智觀","法忍難成，多因福德不足、心性難轉"],"k":["十地","地上菩薩","世親菩薩","一切種智","無相觀","法忍"]},"6999-a28_031":{"s":"本集概說〈從地踊出品〉：先回顧〈安樂行品〉四安樂行，再敘述他方菩薩請求護持此經，佛答娑婆已有六萬恆河沙菩薩，隨即大地震裂、無量菩薩從地踊出，禮讚諸佛歷五十小劫。並述四位上首導師、彌勒請問菩薩來處、世尊答以皆其久遠所化，以及大眾以父少子老喻生疑，待〈如來壽量品〉解答。","p":["四安樂行：親近處、不自讚毀他、敬三寶、慈悲","他方菩薩請護經，佛言娑婆自有菩薩","菩薩從地踊出，禮讚諸佛經五十小劫","世尊言此等菩薩皆久遠以來所教化","彌勒為未來眾生請問，待壽量品解答"],"k":["從地踊出品","安樂行品","四安樂行","地涌菩薩","彌勒請問"]},"6993-a28_032":{"s":"本集說明從地踊出之事顯示佛道非一世可成，釋迦如來是古佛再來，為圓滿千兄弟次第成佛之願而示現為賢劫第四佛。接著依七種性介紹五十二位階：十信位凡夫性、十住位習種性（七住明心、十住見性）、十行位性種性（陽焰觀）、十迴向位道種性（破邪顯正的金剛行、如夢觀），至十地聖種性。","p":["釋迦如來古佛再來，為賢劫第四佛","十信位須深信因果、信受八識論","十住習種性：六住加行，七住明心","十行性種性須證陽焰觀","十迴向道種性破邪顯正，證如夢觀"],"k":["五十二階位","七種性","古佛再來","十信位","十迴向","八識論"]},"7011-a28_033":{"s":"本集依《法華經講義》第十五輯概說禪定：四禪八定須先修未到地定，依煩惱以不淨觀、慈心觀、數息觀、因緣觀對治，正覺則以無相念佛鍛鍊動中定力。並介紹欲界定、初禪須離欲界愛而非靠打坐、初禪善根發的三種情形；說明禪定皆是意識境界，不等於開悟，菩薩於三地滿心前須具足四禪八定與五神通。","p":["四禪八定前須先證未到地定","依煩惱選用不淨、慈心、數息、因緣觀","離欲界愛後，初禪自然發起","禪定屬意識境界，不能說是開悟","三地滿心前須具足四禪八定與五神通"],"k":["四禪八定","未到地定","初禪","無相念佛","四無量心","五神通"]},"7006-a28_034":{"s":"本集開講〈如來壽量品〉，說明從地踊出菩薩引起大眾信心危機，故世尊三誡信解誠諦之語。講者引《阿彌陀經》、《長阿含》七佛壽量、《佛名經》與《華嚴經》各佛剎時間差異，說明諸佛示現壽量差距極大，乃隨眾生因緣與諸佛因地別願；並以阿彌陀佛四十八願成就極樂世界為例，預告探討釋迦如來為何於五濁惡世成佛。","p":["世尊三誡信解，因大眾生信心危機","七佛壽量隨當時人壽而示現","各佛剎時間長短不同，壽量差異極大","淨土由大願善根生，穢土由業煩惱生","阿彌陀佛四十八願成就極樂世界"],"k":["如來壽量品","諸佛壽量","別願","四宏誓願","阿彌陀佛","淨土"]},"7017-a28_035":{"s":"本集依《悲華經》說明諸佛取淨土或穢土皆依本願，世尊因成就大悲而於五濁惡世成佛。講述世尊因地為寶海梵志，以「先歸依三寶、發菩提心才受施」度化閻浮提眾生，並供養寶藏如來七年；梵志夢見三種景象，寶藏如來解說轉輪聖王等以三福業求人天果報乃久受生死之相，梵志遂勸聖王發菩提心。","p":["諸佛以願力取淨土或五濁惡土","世尊因成就大悲，於穢土成佛","寶海梵志要人歸依三寶發心方受施","三夢之一：聖王諸子求人天果報之相","只求人天果報如癡嬰兒，唯菩提心離苦"],"k":["悲華經","寶海梵志","大悲","五濁惡世","發菩提心","三福業"]},"7001-a28_036":{"s":"本集續講《悲華經》：轉輪聖王初愛樂生死，見寶藏如來顯現諸佛世界後，發願於無三惡道的清淨世界成佛，千王子等亦求淨土。梵志八十子發願於不淨世界成佛，觀世音、普賢發願於穢土救護眾生；梵志說明心向菩提而行布施、持戒、多聞、思惟方為助菩提法，三億弟子多願於此界成佛，婆由比紐願於五濁惡世成佛。","p":["轉輪聖王回心，願於清淨世界成佛","成就大悲者方取不清淨世界","觀世音、普賢發願在穢土救護眾生","心向菩提而行布施等，方為助菩提法","婆由比紐發願於五濁惡世成佛"],"k":["悲華經","寶海梵志","淨土與穢土","助菩提法","大悲願","轉輪聖王"]},"6995-a28_037":{"s":"本集續述《悲華經》梵志弟子的發願與授記：婆由比紐授記為金山王如來，九百九十九人於賢劫成佛，迦葉佛於初入五濁時成佛，持力捷疾為樓至如來。寶海梵志感慨眾菩薩多捨五濁眾生，遂發願於賢劫人壽一百二十歲以下的五濁惡世成佛，不惜入地獄受苦以攝受眾生，共發五百大悲願，十方菩薩來三讚歎。","p":["娑婆名忍土，賢劫有千佛大悲出世","賢劫諸佛未必都在五濁惡世成佛","梵志不捨被諸佛世界擯棄的惡世眾生","願於人壽百二十歲以下時下生成佛","五百大悲願，感十方菩薩三讚歎"],"k":["悲華經","寶海梵志","五百大願","賢劫千佛","五濁惡世","授記"]},"7013-a28_038":{"s":"本集總結《悲華經》：寶藏佛授記寶海梵志於五濁惡世成佛；世尊攝受眾生首先勸令「歸依三寶、發阿耨多羅三藐三菩提心」，再勸住六波羅蜜行菩薩道。講者說明依止佛才是究竟歸依、菩薩性非本有，並以《悲華經》十方諸佛多是世尊昔日勸發心者，佐證〈如來壽量品〉「我實成佛已來無量無邊百千萬億那由他劫」。","p":["寶藏佛授記梵志於五濁惡世成佛","先由佛調伏，方能歸依法與僧","菩薩性非本有，須有因緣促發","十方諸佛多為世尊昔日勸發心者","淨土與穢土成佛是諸佛默契分工"],"k":["如來壽量品","悲華經","歸依三寶","發菩提心","六波羅蜜","菩薩性"]},"7007-a28_039":{"s":"本集講〈如來壽量品〉「如來如實知見三界之相，無有生死若退若出」，說明如來具一切種智與死生智力，所說皆實不虛。如來依佛眼見眾生本具的第八識如來藏真實我，本無生死；凡夫執五陰為我而怖畏生死，或厭世或縱欲。講者以生死大事為檢驗善知識的照妖鏡，舉廣欽老和尚「沒來沒去沒代誌」為例，勸學人向所依止者問明。","p":["如來是真語者，如實知見三界之相","依第八識真實我，有情本無生死","凡夫執五陰為我，或厭世或縱欲造惡","一神教永生之說不能解決生死","生死大事可作檢驗善知識的照妖鏡"],"k":["如來壽量品","生死大事","如來藏","真實我","善知識","五陰"]},"6997-a28_040":{"s":"本集為「如何看待生死大事？」第二集，先依《大乘入楞伽經》說明聲聞、緣覺、如來、不定、無種性五種種性，指出許多信眾只修人天善法、尚未探究生死大事。接著點名批評廣論團體以布施行善包裝宗喀巴《廣論》與喇嘛教六識論、雙修之法，並指其領導者金真如名為真如而未證真如。","p":["《楞伽經》五種種性與探究生死大事的關係","無種性者以人天善法為佛法全部","修三福淨業者已入十信位、長養信根","廣論團體以人天善法包裝喇嘛教邪見","金真如名真如卻未證第八識真如心"],"k":["生死大事","五種種性","人天善法","廣論團體","六識論","真如"]},"7032-a28_041":{"s":"本集引金真如〈給武漢同學的一封信〉所說「心上無自性、證得無自性即離輪迴苦」，對照達賴「萬法畢竟無自性」，逐一追問所說是哪個心、哪個我會去後世，論其墮入斷滅空見。並指雙修樂受屬六識了知六塵、眠熟即斷，非真如心；引《佛藏經》「身未證法而在高座」說明法義辨正的用意。","p":["檢視金女士無自性、證空性的說法","追問：是哪個心、哪個我去到下一世","捨報即無則成斷滅空外道見","雙修樂受屬六識，眠熟即滅，非真如","引《佛藏經》說未證而教人之過失"],"k":["無自性","斷滅空","六識論","真如心","佛藏經","雙身法"]},"7024-a28_042":{"s":"本集引《佛藏經》「比丘說法雜外道義，善比丘應從座去」，勸廣論信眾離開。說明佛法探究生命本源、超越世間哲學；佛世前外道已有斷滅見，外於第八識如來藏修道即屬外道。並以眼識能見之性為例，解釋現象諸法依因緣和合而有，故說無自性，凡夫執六識身為我即是身見。","p":["《佛藏經》：說法雜外道義應從座去","佛法究明生死根本，非世間哲學","外於如來藏言修道即屬外道、墮斷滅","無餘涅槃是第八識獨住境界","眼識自性因緣和合假有，故無自性"],"k":["無自性","如來藏","斷滅空","身見","無餘涅槃","佛藏經"]},"7029-a28_043":{"s":"本集為「如何看待生死大事？」完結篇，依三轉法輪說明正確的諸法無自性空：阿含觀行蘊處界無常而斷三縛結至四果，阿羅漢不懼涅槃因有本際；阿含以入胎識等隱說第八識。大乘無自性依空性如來藏的圓成實性而說，勝義無自性性為八地以上所證；批評達賴「空性哲學」，並以《法華經》「無有生死」作總結。","p":["阿含觀行諸法無自性空、次第證四果","《雜阿含》法住法空法如法爾指真實法","阿含以入胎識、齊識而還隱說第八識","大乘依如來藏真實自性說諸法無自性","總結：有情真實我本無生死"],"k":["無自性","空性如來藏","三轉法輪","圓成實性","無餘涅槃","勝義無自性性"]},"7034-a28_044":{"s":"本集講解〈如來壽量品〉「我本行菩薩道所成壽命，今猶未盡，復倍上數」至「如來難可得見」一段。說明如來報身壽命依因果必定無盡，唱言滅度只是方便；因五濁惡世薄德之人見佛常在會起憍恣厭怠，故以優曇缽華、過去七佛間隔等說明佛難值遇，令眾生生起難遭之想與恭敬心。","p":["行菩薩道所成報身壽命無盡","唱言滅度是教化眾生的方便","五濁薄德者見佛常住會生憍恣厭怠","優曇缽華、過去七佛喻佛難值遇","生難遭之想才會恭敬親近"],"k":["如來壽量品","如來難可值遇","方便示現滅度","報身壽命","優曇缽華","五濁惡世"]},"7040-a28_045":{"s":"本集續講「如來難可得見」，指出諸佛比父母更應恭敬，薄德者可能無量劫不見佛。批評一般佛教徒只參加法會，以及主張大乘非佛說、如來藏是外道神我者罪重如一闡提。說明佛宣告三月後入滅，令自負外道與眾生生戀慕渴仰而種善根，同時示現五陰終滅、勸斷我見我執。","p":["諸佛如來比生身父母更值得恭敬","薄德之人可經無量劫不遇佛","謗大乘、謗如來藏者斷善根罪重","宣告入滅令眾生戀慕渴仰而種善根","示現滅度亦教人不執著五陰"],"k":["如來難可值遇","種善根","一闡提","大乘非佛說","示現滅度","如來壽量品"]},"7026-a28_046":{"s":"本集白話解說〈如來壽量品〉良醫喻全段，並開始講解：良醫出遠門、諸子誤飲毒藥，有失本心與不失本心者。失本心喻退轉者，誤信一念不生、離念靈知、如來藏是外道神我等而正邪不分；「依諸經方，求好藥草」喻諸對治法，「擣篩和合」喻統整為五乘法，大良藥即法與次法。","p":["良醫喻經文白話語譯","諸佛示現滅度如良醫不能長伴諸子","失本心喻退轉、正邪不分之人","擣篩和合喻統整為五乘法","大良藥即法與次法具足"],"k":["良醫喻","如來壽量品","失本心","法與次法","五乘法","退轉"]},"7030-a28_047":{"s":"本集續講良醫喻：不失心者喻三賢位不退、願具修法與次法者；失心者我見我執深重，不肯依法實修。父親示現死亡後諸子醒悟服藥，喻弟子在佛滅後自行修法與次法、降伏煩惱，名聞、財物、眷屬、權力最難除；煩惱漸輕時如來再來示現，弟子便能速成阿羅漢乃至入地，故良醫無虛妄之過。","p":["不失心者具修法與次法而病除","失心者我見我執深，不肯服藥","佛滅後弟子醒悟，依法藥自修","欲界愛中名財眷屬權力最難除","煩惱除後如來再現，速證果入地"],"k":["良醫喻","法與次法","失本心","性障","如來壽量品","方便示現滅度"]},"7038-a28_048":{"s":"本集講解〈如來壽量品〉重頌「自我得佛來」至「但謂我滅度」。說明諸佛因十無盡願常住，世人只見悉達多成佛的表相；如來留碎身舍利，讓信根未具者藉供養舍利維持信心。眾生質直柔軟、一心欲見佛時，佛便出現說法，如阿闍世王見佛得無根信；並指如來必說完大乘無上法才示現涅槃。","p":["偈頌重宣：成佛久遠、常住靈鷲山","十無盡願故諸佛不入滅","碎身舍利令眾生維持信心","質直意柔軟、一心欲見佛時佛現","如來必說大乘無上法方示涅槃"],"k":["如來壽量品","常住靈鷲山","舍利","十無盡願","無根信","無上法"]},"7054-a28_049":{"s":"本集依《法華經講義》講解「我見諸眾生，沒在於苦惱，故不為現身，令其生渴仰；因其心戀慕，乃出為說法」。說明佛不常現身是因物以稀為貴；舉平實導師早年勸同修不被相信、願者上鉤為例，以佛法精品店喻如來藏妙法需七聖財。並說佛菩薩依眾生因緣安排受生與接引。","p":["佛不常現身，令眾生生渴仰","平實導師早年勸法不被信的例子","如來藏妙法如精品，須七聖財","渴仰戀慕成熟，佛才出現說法","佛菩薩依因緣安排受生與接引"],"k":["如來壽量品","渴仰心","如來藏","七聖財","佛難值遇"]},"7044-a28_050":{"s":"本集講解偈頌「神通力如是」至「速成就佛身」，重點說明釋迦如來的四種淨土：常寂光土、實報莊嚴土、方便有餘土、凡聖同居土，並舉大迦葉住方便有餘土、通教菩薩往生該土為例。從理上說每人自身也有四土；強調未見不等於不存在，劫火不燒淨土；謗法具根本、方便、成已三罪者即一闡提。","p":["釋迦如來亦有四種淨土","大迦葉、通教菩薩住方便有餘土","理上每人自身亦具四種淨土","未見不等於不存在，劫火不燒淨土","謗法具三罪者久不聞三寶名"],"k":["四種淨土","如來壽量品","凡聖同居土","通教菩薩","一闡提","謗法"]},"7056-a28_051":{"s":"本集講解「諸有修功德，柔和質直者，則皆見我身」以下偈頌。說明修功德、柔和質直者能值遇諸佛，供養應身佛功德最大；對菩薩性具足者說佛壽無量，對根淺者說佛難值、勸念佛往生極樂，作為對治方便。並勸留在娑婆值遇賢劫千佛，續釋「我智力如是」「如醫善方便」等句。","p":["柔和質直、修功德者能見佛","賢劫千佛應一一承事供養","對不同根性說佛壽無量或佛難值","念佛往生極樂是對治的方便","佛語實不虛，良醫喻再申明"],"k":["佛難值遇","佛壽無量","柔和質直","念佛法門","賢劫千佛","如來壽量品"]},"7060-a28_052":{"s":"本集講解「以常見我故，而生憍恣心，放逸著五欲，墮於惡道中」。批評有人斥正覺為阿賴耶外道，指若然則諸地菩薩皆成外道。並詳述佛世鸚鵡摩納都提因對佛起憍慢而墮為白狗、其子先起惡心後懺悔的故事，說明對佛起善心或惡心果報差距極大，應對佛生恭敬。","p":["常見佛者易生憍恣、放逸五欲","反駁稱實證阿賴耶識為外道的說法","鸚鵡摩納都提墮為白狗的故事","對佛善心生天，惡心墮惡道","佛為利生取人身，本質非凡人"],"k":["恭敬心","憍慢","阿賴耶識","因果業報","如來壽量品"]},"7046-a28_053":{"s":"本集講解「我常知眾生，行道不行道，隨所應可度，為說種種法」，以佛用火堆譬喻勸誡出家人、六十比丘證果與六十比丘還俗為例；並解「速成就佛身」為三身，結束〈如來壽量品〉。接著進入〈分別功德品〉，說明聞佛壽長遠得大饒益，並解釋無生法忍、聞持陀羅尼、樂說無礙辯才、旋陀羅尼對應的菩薩地位。","p":["佛觀眾生根性，隨所應度說法","火堆喻：六十比丘證果、六十還俗","以何令眾生速成就三身佛","〈分別功德品〉：聞佛壽長遠得大饒益","無生法忍、陀羅尼、無礙辯對應諸地"],"k":["分別功德品","如來壽量品","無生法忍","陀羅尼","樂說無礙辯","善巧方便"]},"7050-a28_054":{"s":"本集探討培植福德，引《法華經講義》說外道猖狂時護持正法福德最大，但須以八識論判別正法以免種於毒田。引《成唯識論》說明第八識持種使因果不失，並說天魔亦修福、破戒樂施者墮惡道仍飽滿。依《瑜伽師地論》說福依智起、福慧缺一不能成佛，六度須全修，否則只成乾慧。","p":["外道猖狂時護持正法福德最大","以八識論抉擇正法，避免種毒田","第八識持種，因果昭然不失","福慧須雙修，六度不可只修般若","菩薩二作意：悟入所知、利益眾生"],"k":["培植福德","護持正法","八識論","福慧雙修","六度","種子識"]},"7058-a28_055":{"s":"本集探討「佛名聞十方，廣饒益眾生」：諸佛互相讚歎，釋迦讚阿彌陀佛，十方佛亦讚娑婆修行快速。引《悲華經》等說明釋迦因地大悲菩薩的願眼，名號意為能仁、寂靜。並以十號中的正遍知、佛佛道同說明諸佛本質，萬法源於如來藏，須依八識論理解；彌勒成佛前此世界無人成佛。","p":["諸佛互相讚歎，應不同眾生根性","釋迦因地大悲菩薩發大悲願眼","釋迦牟尼意為能仁與寂靜","正遍知與佛佛道同，皆依如來藏","彌勒成佛前，自稱成佛者皆誤"],"k":["佛名號","大悲願","正遍知","八識論","佛壽無量","諸佛本質"]},"7062-a28_056":{"s":"本集探討修學般若波羅蜜，依《法華經》「於八十萬億那由他劫數，行五波羅蜜」，指許多人因師說落在意識與現象界，只修前五度及表相般若。分析意識與五別境心所相應而易被誤認為真我；說明般若即親證常住真心第八識而真見道，第一義諦為非安立諦，並以三種流轉、錠光佛授記說明其重要。","p":["無真善知識者多劫只修前五度","表相般若以意識當作實證標的","意識與五別境相應，易被執為我","親證第八識常住真心方有般若","三種流轉須依八識論方能解釋"],"k":["般若波羅蜜","如來藏","第一義諦","六度","意識","真見道"]},"7048-a28_057":{"s":"本集探討「多聞聖弟子」，說明智慧從多聞而生，須經聞思修並由善知識指導，引《心地觀經》親近善友為第一。依《瑜伽師地論》說具足多聞的十相：說法者五種、聽法者五種；並引《大智度論》、《楞嚴經》「清淨在音聞」、《月燈三昧經》多聞利益，最後勸以四攝法與同修廣結善緣。","p":["智慧從多聞熏習、融會貫通而生","親近善友為修學第一步","具足多聞須說者與聽者各五條件","多聞與智慧須兼具，如燈與目","以四攝法與同修廣結善緣"],"k":["多聞","善知識","聞思修","親近善友","四攝法"]},"7051-a28_058":{"s":"本集探討「多聞能總持，隨義解佛語」，說明總持即總綱憶持，如〈正覺總持咒〉。二乘總持為斷我見、我執，且須信有本際；大乘總持為真如與佛性，即明心見性，再次第證七真如、十地真如至一切種智。並引篤補巴《山法》基道果，以及《心地觀經》教理行果四種法寶，作為掌握法義的架構。","p":["總持是掌握佛法綱要的方便","二乘總持：斷我見與我執","大乘總持：真如與佛性、明心見性","《山法》基道果與成佛要旨一致","教理行果四面向理解法寶"],"k":["總持","真如佛性","明心見性","斷我見","教理行果","正覺總持咒"]},"7064-a28_059":{"s":"本集講解〈分別功德品〉「若有聞佛壽命長遠，解其言趣……能生一切種智」。說明「解其言趣」須實證此經如來藏，知有情自心如來不生不滅，非僅知報身壽無量；並依次解釋廣聞是經、教人聞、自持教人持、自書教人書的功德。強調經教是證明如來藏的依據、宗門與教門一致，並批評印順大乘非佛說、如來藏梵我說。","p":["解其言趣須實證此經如來藏","悟後應廣聞諸菩薩演說《法華經》","教人受持此經功德勝度萬阿羅漢","書寫保存經教，作為法義依據","宗門與教門所證同為如來藏"],"k":["分別功德品","佛壽命長遠","如來藏","宗門與教門","受持經典","大乘非佛說"]},"7070-a28_060":{"s":"本集接續〈如來壽量品〉，說明解其言趣、聽聞、受持、書寫此經的功德為何無有限量：功是自受用、德是他受用，須以證得此經如來藏為基礎，並舉梁武帝與達摩的對話區分福德與功德。又說以香花等供養經卷也是功德無量，但前提是先在正法道場聽聞了義法，並以一行三昧須先聞般若為例說明。","p":["功是自受用、德是他受用，無形不可限量","梁武帝造寺度僧只得人天有漏福報","供養經卷前須先聽聞了義正法","一行三昧須先聞般若波羅蜜","一切種智的根源在證如來藏"],"k":["功德","福德","如來藏","一行三昧","供養經卷","一切種智"]},"7066-a28_061":{"s":"本集講解〈分別功德品〉「聞我說壽命長遠，深心信解，則為見佛常在耆闍崛山」一段。說明深心信解須實證如來藏且不退轉，靈鷲山即指如來藏，並批評釋印順否定佛壽長遠與大乘佛說。再以極樂世界三輩往生為例，論證諸佛皆有四種淨土，釋迦如來也有方便有餘土與實報莊嚴土。","p":["深心信解須實證且不退轉","批評釋印順視大乘為對佛的永恆懷念","四阿含已說三乘，證大乘是佛說","常在靈鷲山的靈鷲山即如來藏","諸佛皆具四種淨土，釋迦如來亦然"],"k":["四種淨土","深心信解","如來壽量","如來藏","大乘是佛說","分別功德品"]},"7080-a28_062":{"s":"本集續說釋迦如來的淨土：往生其方便有餘土、實報莊嚴土至少須斷三縛結或已開悟，並與往生極樂、琉璃世界的條件對比；同時批評釋印順「大乘經出於對佛永恆懷念」之說自相矛盾。接著解釋聞經不毀訾、起隨喜心即是深信解相，讀誦受持則為頂戴如來，並以趙州轉經公案說明真正的讀誦。","p":["知見心量廣闊則福德智慧增長快","往生釋迦淨土至少須斷三縛結或開悟","批評「永恆懷念」說無法立足","聞經不毀訾而隨喜即深信解相","頂戴如來者，如來盡量教授"],"k":["四種淨土","深信解相","頂戴如來","讀誦受持","釋印順批評","轉經"]},"7074-a28_063":{"s":"本集講解〈分別功德品〉「不須為我復起塔寺……則為以佛舍利起七寶塔，高廣漸小至于梵天」經文。說明深心信解並讀誦受持此經者，功德勝過造寺供僧，因為正法存續比寺廟表相更重要；並區分碎身舍利與法舍利，以在眾生心中建法舍利七寶塔、以三十七道品為莊嚴來解釋經義。","p":["頂戴如來須具足深信解等四條件","受持此經即等同起塔造僧坊供眾僧","正法存在比寺院表相更重要","法舍利即如來所傳三乘菩提妙法","七寶塔漸小至梵天，喻實證者次第上生"],"k":["頂戴如來","法舍利","七寶塔","供養眾僧","分別功德品","三十七道品"]},"7083-a28_064":{"s":"本集依《法華經講義》第十六輯，講解〈分別功德品〉「精進勇猛攝諸善法」與「常貴坐禪得諸深定」。說明在正覺修學悟前悟後都很辛苦，菩薩乃至成佛也不輕鬆，還須忍受辱罵；勸勉勿忘「法門無量誓願學」。又說末法時深定難得，至少須達離五塵的二禪，能具足這些功德者必是利根。","p":["悟前悟後修福、除性障都辛苦","世尊成佛後度眾、制戒亦不輕鬆","菩薩受辱罵可消先世罪業","莫忘四宏誓願「法門無量誓願學」","深定至少須離五塵，具諸德者必利根"],"k":["精進勇猛","深定","四宏誓願","忍辱","利根","分別功德品"]},"7086-a28_065":{"s":"本集說明「利根智慧善答問難」：利根菩薩不是世間聰明伶俐的人，而是無心世法、願為眾生與正法吃虧付出的人，所以能斷三縛結。接著講「已趣道場，近阿耨多羅三藐三菩提，坐道樹下」及「若坐若立若行處，此中便應起塔」，並回顧正覺二十餘年著書弘揚此經如來藏的艱辛。","p":["世間聰明者在出世間法上反是鈍根","願為眾生、正法吃虧者道業進展快","末法弘揚此經如來藏極為困難","已趣道場指入地、邁向佛地","坐道樹下即能為眾廣說種種法"],"k":["利根","善答問難","已趣道場","如來藏","弘法艱辛","起塔供養"]},"7072-a28_066":{"s":"本集續講「若坐若立若行處，此中便應起塔」，說明其根源在於智慧，即《解深密經》所說七真如的實證與無生法忍。接著語譯、釋義〈分別功德品〉重頌「若我滅度後，能奉持此經，斯人福無量」，指出末法眾生執著離念靈知等內我所，受持此經如來藏而不退極難，所以福德無量，並以稀有黑珍珠為喻。","p":["功德歸根於智慧，即七真如的實證","奉持此經即為起七寶塔供養","大師教人「把握自己」是執著內我所","末法受持此經如稀有黑珍珠","被罵可消先世罪業，反能攝受對方"],"k":["七真如","起塔供養","此經如來藏","末法受持","離念靈知","重頌"]},"7068-a28_067":{"s":"本集語譯〈分別功德品〉重頌「若能持此經，則如佛現在，以牛頭栴檀，起僧坊供養」等段，說明受持此經如來藏勝過建造三十二堂僧坊供養，因為此經是三乘菩提的根本。並批評「緣起性空、大乘非佛說」等是相似像法，述及天竺大乘正法被密教排擠而滅，最後說明真正受持、讀誦、書寫此經的意涵。","p":["受持此經勝過造僧坊供養僧眾","佛教根本在法，不在寺院與僧數","相似像法廣弘則了義正法隱沒","天竺「密教興而佛教亡」","真書寫此經是為人書寫如來藏妙法"],"k":["受持讀誦書寫","如來藏","相似像法","僧坊供養","密教興佛教亡","重頌"]},"7078-a28_068":{"s":"本集續說受持、讀誦、書寫此經的真義，舉捧經過頂、向虛空一勾等例，並提醒證悟者與野狐大師都可能如此表現。說明證悟者從實際理地供養經卷，功德福德勝過凡夫的豐盛供養；介紹須曼、瞻蔔、阿提目多伽、薰油等供品，並批評密宗用動物酥油。接著講「兼布施持戒……遠離自高心」，勸悟後勿起慢心而應一味平懷。","p":["總持讀誦、虛空書寫，須辨證悟與野狐","證悟者依實際理地供養，功德更大","解釋善攝意花、薰香草、薰油等供品","悟後須除自高心，修非安立諦三品心","遇出家人合掌，崇隆表相僧寶"],"k":["受持讀誦書寫","供養經卷","遠離自高心","一味平懷","實際理地","野狐大師"]},"7077-a28_069":{"s":"本集講解〈分別功德品〉重頌「有問難不瞋，隨順為解說」及「若見此法師……生心如佛想」等句。說明菩薩犯瞋罪重，應把問難視為請法並隨根性解說，以攝受眾生與佛土；分析「況復」二字所顯示三種人的功德層次，依《雜阿含經》定義法師，批評以離念靈知為開悟者不是法師，並解釋「應起塔」是在心中恭敬這位法師。","p":["菩薩犯瞋罪重，惡緣令眾生不隨學","把問難當作誠懇請法，隨根性解說","「況復」顯示三種人功德遞增","依《雜阿含》，說五陰厭離滅盡者名法師","起塔指心中恭敬法師的五蘊七寶塔"],"k":["有問難不瞋","法師","攝受佛土","四攝法","離念靈知","分別功德品"]},"7085-a28_070":{"s":"本集說明重頌「其所住止處……是中應起塔」之所以要如此供養，是因為這位法師證得七真如，並區分二乘法師、大乘法師與此處法師的層次。接著依《解深密經》、《成唯識論》、《瑜伽師地論》解說七真如中的邪行真如（集諦實性，含惡行、外道邪行與佛門三學邪行）及流轉真如（一切行流轉中真如無先後地顯示）。","p":["法師須證七真如方值得起塔供養","二乘法師與大乘法師的說法內涵不同","列出七真如的名目","邪行真如即集諦的實性","流轉真如：一切行流轉中真如無先後"],"k":["七真如","邪行真如","流轉真如","法師","集諦","解深密經"]},"7092-a28_071":{"s":"本集續講七真如中的了別真如、相真如與安立真如。了別真如指一切有情了別的過程（率爾心、尋求心、決定心等）中剎那顯示第八識真如性；相真如指從人無我、法無我的法相中顯示真如；安立真如則依苦聖諦，為三界六道一切有苦的有情安立種種真如。","p":["一切有情皆有了別，了別過程即行陰","了別真如：一切行唯是識性","相真如是二無我所顯的實性","三界有情沒有純樂無苦者","安立真如依苦聖諦而安立"],"k":["了別真如","相真如","安立真如","七真如","二無我","苦聖諦"]},"7088-a28_072":{"s":"本集講解七真如中的清淨真如：二乘以滅聖諦為清淨，初果到阿羅漢的清淨層次各不相同，阿羅漢也不是究竟清淨。入地菩薩須依勝鬘夫人所說無作、無量四聖諦，依本來無生而修，斷盡現行與習氣種子，度過變易生死，到佛地才是究竟清淨真如；並描述三地滿心色陰盡等五陰盡的境界。","p":["二乘的清淨真如即滅聖諦","初果到阿羅漢清淨程度不同","菩薩依無作四聖諦、本來無生而修","斷盡習氣種子與變易生死才究竟清淨","色陰盡在三地滿心，識陰盡在佛地"],"k":["清淨真如","七真如","大乘四聖諦","五陰盡","變易生死","滅聖諦"]},"7102-a28_073":{"s":"本集講解七真如最後的正行真如，即道諦實性：二乘雖行八正道但未證真如，大乘須先證此經如來藏，依本來無生修八正道，到妙覺位才圓滿。並以趙州「胡來胡現」與明鏡為喻，說一切法攝歸如來藏本來無生；強調法師只看實證、不論身相；最後說「是中應起塔」是在心中起塔、行法供養，「佛子住此地，則是佛受用」指入地菩薩受用此經。","p":["正行真如即道聖諦的實性","大乘無生是本來無生，非將滅止生","胡來胡現喻一切法攝歸如來藏不生","法師不論身相，只看有無實證","心中起塔，以護持正法為法供養"],"k":["正行真如","本來無生","八正道","七真如","法供養","法師"]},"7106-a28_074":{"s":"本集接續〈分別功德品〉「能奉持此經，斯人福無量」，從世俗角度談為何修學真正的佛法很重要。說明上香求平安財富只是民間信仰，學佛至少要與解脫道相應，進而走上佛菩提道；以貧富差距、天災、生死等世間無解的問題，質疑「萬能創造者」之說；並引《悲華經》說明娑婆即堪忍之義與賢劫千佛的因緣。","p":["上香求世俗願只是民間信仰","學佛至少須與聲聞解脫道相應","世間法無法解決病死、天災等問題","質疑創造者為何讓人先生人間受苦","《悲華經》說娑婆名忍土、賢劫千佛"],"k":["真正學佛","奉持此經","娑婆世界","民間信仰","賢劫千佛","解脫道"]},"7096-a28_075":{"s":"本集續談奉持此經福德無量的原因，從「若世間沒有真正佛法住世」來設想：三乘菩提才是真正的佛法，人天乘之法與外道共通；末法時佛法只剩名相與表相，偏重名聞利養，人天善法也會隨之變質。並比較其他宗教標榜唯一、未能令人出離生死，引《八十華嚴經》發心住，說明佛菩薩多劫示現護持學人建立信心。","p":["真正佛法是三乘菩提，人天乘共外道","無正法住世，佛教只剩表相","人天善法也將隨之變質","其他宗教未能助人出離生死","佛菩薩多劫示現，助學人發菩提心"],"k":["三乘菩提","末法","奉持此經","發心住","人天善法","三世因果"]},"7100-a28_076":{"s":"本集先引《增壹阿含經》迦葉尊者授記末法比丘貪著衣食、經法凋落，說明末法佛法表面興盛而多求世間福。接著進入〈隨喜功德品〉，說明「聞是經隨喜轉教，展轉至第五十」功德不可思議，「此經」即每一有情身中的真心如來藏；並引《大般若經》較量，教一人趣向無上菩提勝過令全洲有情證獨覺，因能令世間佛眼不斷。","p":["末法借佛法名相謀利者眾多","迦葉授記比丘貪衣食致經法凋落","此經即有情身中的真心如來藏","第五十人隨喜功德勝過大施主","教一人趣無上菩提，令佛眼不斷"],"k":["隨喜功德","如來藏","第五十人","奉持此經","末法","大般若經"]},"7094-a28_077":{"s":"本集說明此經之法須有更多人奉持才能在世間弘傳，並分析不能奉持此經的人：只高唱「明天會更好」而不求出離者，以及自以為能救眾生卻貪名利者。舉世尊降伏六師外道、玄奘菩薩造《成唯識論》破外道為例，指出依此經受持才是佛道；批評醫學、哲學、AI誤計萬法本因，並解說「四依四不依」其實是一，都是依是否受持此經而說。","p":["不求出離者不可能奉持此經","世尊、玄奘皆以善巧降伏外道","依此經受持名佛道，此外名外道","醫學、哲學、AI皆誤計萬法本因","四依四不依其實是一"],"k":["四依四不依","外道","奉持此經","玄奘","萬法本因","依法不依人"]},"7090-a28_078":{"s":"本集為「不思議福」系列的總結，從「信為道元功德母」談佛法所說的信：先對佛法僧生清淨信、信自身有本際，並持五戒成就四不壞信，才能分證解脫道；發菩提心進入初住位則需要更深的信。並引《分別布施經》、《八十華嚴經》、《摩訶般若波羅蜜經》，說明學般若如說行勝過供養無量諸佛，歸結奉持此經福德無量。","p":["佛法的信不同於世間與哲學的信","分證三乘須先於佛法僧生清淨信","歸依並持戒，成就四不壞信","發菩提心入初住，須信自己可成佛","學般若如說行，福勝供養無數佛"],"k":["清淨信","四不壞信","發菩提心","般若波羅蜜","奉持此經","本際"]},"7104-a28_079":{"s":"本集講解〈隨喜功德品〉：勸人聽講《法華經》，來世可與持陀羅尼的九地菩薩共會，口齒健康、相貌端嚴；輾轉隨喜到第五十人，功德仍勝過廣施無量世界眾生並令成阿羅漢的大施主。也說往詣聽法、分座勸坐的天人果報；後段說明二乘涅槃是滅盡五陰而實無人入涅槃，涅槃本際即第八識如來藏，大乘涅槃是如來藏自住境界。","p":["勸人聽法華經，來世與九地菩薩共會","第五十人隨喜功德勝過大施主","往詣聽法、分座勸坐皆得天人果報","二乘涅槃是滅盡五陰，實無人入涅槃","涅槃即如來藏的自住境界"],"k":["隨喜功德","涅槃","如來藏","第五十人","一佛乘","勸人聽法"]},"7098-a28_080":{"s":"本集說明真正的「法師」須有學有證、不排斥大乘並能親證實相。講者指離念靈知仍是六識心，無法去到後世；引《佛說法印經》「諸蘊本空，由心所生」及《雜阿含經》，說明五陰由如來藏出生，如來藏無記、離見聞覺知，能容受善惡種子，是生死與涅槃共同的所依。","p":["法師須有學有證，不排斥大乘並親證實相","離念靈知仍屬六識心，無法去到後世","諸蘊由心所生，五陰依如來藏流注種子而有","如來藏無記性，能容受一切善惡種子","二乘法亦說法不離如，阿羅漢滅不了本識"],"k":["法師","如來藏","五陰","離念靈知","二乘聖教","無記性"]},"7112-a28_081":{"s":"本集引《雜阿含經》「法住、法空、法如、法爾；法不離如，法不異如」，說明緣起諸法皆攝歸本住法如來藏，顯示阿含中已有大乘法。再以「識緣名色」「齊識而還，不能過彼」說明名色之外有不可滅的本識（第八識），十二因緣所滅的是無明而非本識；並引《中阿含經》說如來所依識。","p":["法住、法空、法如、法爾皆攝歸如來藏","識緣名色：名色之外有本識即第八識","齊識而還：本識是源頭，不生不滅","十二因緣滅的是無明，不是滅第八識","中阿含：諸天求如來所依識而不可得"],"k":["二乘聖教","本識","第八識","十因緣","十二因緣","真如"]},"7120-a28_082":{"s":"本集講受持《法華經》者得六根功德，說明眼根有侷限為八百功德、耳根周遍為一千二百功德，並述三地滿心色陰盡時能以肉眼觀眾生因緣業報。另談《楞嚴經》五陰盡與六根互通、明心與眼見佛性兩階段，以六即佛說明修證次第，最後勸法師領眾應心懷慈愍。","p":["眼根八百、耳根一千二百功德的差別","三地滿心色陰盡，肉眼能觀眾生業報","楞嚴經說五陰盡與六根互通，非偽經","六即佛：從理即佛到究竟即佛的次第","法師領眾不宜絕情，應慈愍弟子"],"k":["六根功德","色陰盡","楞嚴經","六即佛","明心見性","法師"]},"7115-a28_083":{"s":"本集批評密宗為相似佛法，指其雙身法、金剛薩埵、灌頂、輪座等違背須離欲方得初禪的法理，並批評月輪觀、五方佛、誅殺法、時輪續及以歸依金剛上師為首的四歸依。講者也談一貫道斗姥與摩利支天密續的關聯，勸清淨法師遠離密宗、剔除相關儀軌。","p":["雙身法違背須離欲界愛方得初禪之理","批評金剛薩埵、灌頂與輪座等說法","批評月輪觀、五方佛與誅殺法","四歸依將金剛上師置於三寶之前","一貫道斗姥與摩利支天密續的關聯"],"k":["密宗","雙身法","金剛薩埵","四歸依","初禪","一貫道"]},"7108-a28_084":{"s":"本集講〈法師功德品〉耳根一千二百功德經文。理上說一切聲皆由如來藏所發，並以《楞嚴經》耳根圓通「入流亡所」說明須聽聞善知識正法、放流五陰我見；事上指三地滿心色陰盡者不需天耳即能以父母所生耳聽聞。並解說象馬牛車、啼哭愁嘆、螺鼓、鐘鈴等聲的意涵。","p":["受持此經得耳根一千二百功德","理上一切聲皆是如來藏聲","入流亡所：聽聞正法、放流五陰我見","三地滿心色陰盡，不需天耳即能聽聞","啼、哭、愁嘆之別及鐘鈴用途不同"],"k":["耳根功德","耳根圓通","入流亡所","如來藏聲","色陰盡","法師功德品"]},"7118-a28_085":{"s":"本集續講耳根功德經文中各種聲音：笑聲語聲、男女聲、童子童女聲、法聲與非法聲、苦樂聲、凡夫聲與聖人聲、喜與不喜聲。並說明天龍八部的聲音特徵，詳述阿修羅遍於五趣、金翅鳥依層次食龍及受八關齋戒的例外，最後談三惡道聲及餓鬼與大力鬼之別。","p":["從笑聲語聲可知眾生心行","依說話內涵分辨凡夫聲與聖人聲","天龍八部各類眾生的聲音特徵","阿修羅遍於五趣，修羅類鬼神性暴烈","金翅鳥依層次食龍，受八關齋戒則不可食"],"k":["耳根功德","天龍八部","阿修羅","金翅鳥","凡夫聲聖人聲","餓鬼"]},"7124-a28_086":{"s":"本集說明比丘比丘尼聲（未斷我見的凡夫僧）、聲聞聲、辟支佛聲、菩薩聲與佛聲的分辨，並誦讀耳根功德重頌。講者解釋「清淨常耳」屬三地滿心色陰盡後的境界，理上一切聲皆是如來藏聲，故「聽之而不著」；並解說諸天聲、迦陵頻伽與命命鳥、地獄、餓鬼及阿修羅之聲。","p":["比丘聲指未斷我見的凡夫僧說法聲","辟支佛先說十因緣，再說十二因緣","佛聲不需擴音，遠近皆能聽清","一切聲皆如來藏聲，故聽之而不著","迦陵頻伽、命命鳥與餓鬼求食聲"],"k":["清淨常耳","如來藏聲","辟支佛","色陰盡","重頌","餓鬼"]},"7122-a28_087":{"s":"本集續解耳根重頌：說法者遙聞阿修羅大聲而不壞耳根，能聞十方禽獸及梵天至有頂天之聲，並能分辨凡夫比丘、證果沙門、菩薩撰集註解與諸佛說法之聲。講者強調分辨音聲須慧眼、法眼配合，批評將耳根圓通解為聽聲的說法，指「聞所聞盡」是實證空性如來藏的智慧。","p":["耳根清淨又為人宣說法華，故不壞耳根","證初果即名沙門，在家出家無別","能講如來藏經典者方是菩薩聲","分辨音聲須慧眼、法眼配合","聞所聞盡依證空性如來藏，非聽聲法"],"k":["耳根圓通","清淨常耳","沙門果","慧眼法眼","聞所聞盡","如來藏"]},"7117-a28_088":{"s":"本集講〈法師功德品〉鼻根八百功德經文並作白話解說。前提是受持了義《法華經》且鼻根清淨：事上嗅所當嗅、不執著香塵，理上觀一切香（含臭）皆是如來藏香。講者說明清淨約為三地滿心色陰盡的證境，解釋常精進之名的意涵，並逐一解說各種花香、樹香與檀香。","p":["鼻根清淨須嗅所當嗅、不執香塵","理上一切香塵皆是如來藏香","常精進之名：精進方得六根清淨","色陰盡屬三地滿心，另需禪定等功德","解說各種花香、樹香與檀香木差別"],"k":["鼻根功德","如來藏香","常精進","色陰盡","法師功德品"]},"7111-a28_089":{"s":"本集續講鼻根功德經文，說明沈香的形成與種植、牛頭栴檀、多摩羅跋與多伽羅，以及末香、丸香、塗香三類和香與塗香供佛的用法。接著說明眾生身香與天香：忉利天圓生樹、拘鞞陀羅樹、曼陀羅與曼殊沙華、釋提桓因勝殿與妙法堂之香，以及空居天、色界天身香越上越淡。","p":["沈香的形成、分級與人工種植","和香分末香、丸香、塗香三類","忉利天圓生樹、拘鞞陀羅樹等天香","空居天淫欲漸淡，身香亦漸淡","欲界有情皆有臭味，越往下越臭"],"k":["鼻根功德","沈香","忉利天","釋提桓因","空居天","天香"]},"7126-a28_090":{"s":"本集說明色界天以禪悅為食、無鼻識舌識，身香因定境不同而異，諸天所燒之香僅限欲界。講者解釋聲聞香、辟支佛香、菩薩香、諸佛身香屬法香，差別在於有無慢心、恐懼及福慧是否圓滿；並誦讀鼻根重頌與白話譯文，涵蓋轉輪王、伏藏、懷妊、男女心念與忉利天宮殿等。","p":["色界天以禪悅為食，無鼻識舌識","色界身香因定境不同而異","獨覺有慢，身香與聲聞緣覺不同","菩薩無恐懼，諸佛福慧圓滿","重頌：聞香知懷妊、心念與伏藏"],"k":["鼻根功德","法香","色界天","辟支佛","重頌","禪悅"]},"7130-a28_091":{"s":"本集續解鼻根重頌，說明持經者聞香能知入出禪者、精進比丘、菩薩與諸佛說法之所在。講者解釋六根互通原是如來藏整體功能，因執著被分割成六結，須次第解結，並提醒勿妄想境界；又指《法華經》對象不限人類。後段詳述四種轉輪王、七寶與千子，及釋迦如來排行第四的因緣。","p":["六根本是如來藏功能，因執著成六結","六根清淨須次第解結，勿妄想境界","法華、華嚴不能只以人類為前提理解","四種轉輪王及輪寶等七寶","轉輪王千子與賢劫千佛的因緣"],"k":["六根互通","轉輪聖王","六結","鼻根功德","賢劫千佛"]},"7137-a28_092":{"s":"本集說明釋迦如來早已成佛，因與千兄弟約定而於賢劫示現成佛，並指轉輪王必教人民受五戒、修十善。接著逐句解說鼻根重頌：聞香知轉輪王眷屬珍寶、諸天行坐神變、阿修羅、懷妊與順產、男女心念、伏藏與瓔珞貴賤、忉利天圓生樹、宮殿與天衣，乃至色界入禪出禪者。","p":["釋迦如來早已成佛，賢劫為示現","轉輪王必教人民受五戒、修十善","聞香知懷妊、男女心念與伏藏","忉利天圓生樹、宮殿、天衣之香","色界稱梵世，入禪出禪香味不同"],"k":["鼻根功德","轉輪聖王","忉利天","重頌","梵世"]},"7141-a28_093":{"s":"本集從《法華經》一佛乘、授記與佛壽無量的主旨，說明演述《法華經》的菩薩須具阿羅漢解脫證量、實證如來藏並達初地以上。講者以五分法身為道德之香，引《雜阿含經》說戒香逆風而熏，並述聞如來戒香得鼻根清淨的修學次第；後舉摩那祇謗佛為例，並批評琅琊閣等人的指控。","p":["法華主旨：一佛乘、授記、佛壽無量","演述法華須具解脫證量並證如來藏","五分法身是道德之香，戒香逆風而熏","聞如來戒香得鼻根清淨，須次第修學","四不壞信得法鏡，舉摩那祇謗佛為例"],"k":["戒香","五分法身","鼻根清淨","一佛乘","四不壞信","法鏡"]},"7134-a28_094":{"s":"本集講舌根功德，說明佛的上味相源於因地口業的修集，指未證言證、未得禪定言得的大妄語使舌根不清淨。引「真諦之妙說，是則味之上」，以聚沫、浮泡、陽燄、芭蕉、幻化之喻說五蘊虛妄假施設，並引《般若經》說真法界即如來藏、非心心，批評六識論的相似像法。","p":["上味相源於因地口業的善法修集","大妄語使舌根不能清淨","真諦之妙說即是味之上","五蘊如聚沫浮泡等，虛妄假施設","如來藏是非心心，否定者落相似像法"],"k":["舌根功德","大妄語","五蘊","非心心","如來藏","相似像法"]},"7136-a28_095":{"s":"本集說明菩薩法師以舌根宣說如來藏正法、摧邪顯正，其深妙聲能入人心；舉佛食馬麥仍為上味、世親以舌謗大乘後依無著教誨造論弘揚大乘為例。講者說明修清淨舌根須行如實語、質直語、依法語，批評琅琊閣等人言論，並引《長阿含經》說入胎識即涅槃本際、十二因緣甚深。","p":["深妙聲能入大眾心，令皆歡喜","佛食馬麥仍是上味相","世親以舌謗大乘，後以解說大乘懺罪","修如實語、質直語、依法語等善語","入胎識即涅槃本際，十二因緣甚深"],"k":["舌根功德","法布施","世親菩薩","如實語","入胎識","十二因緣"]},"7152-a28_096":{"s":"本集續講舌根偈「舌根淨，終不受惡味」，說明舌根清淨須長劫不大妄語、不依佛法欺誑眾生，說法者能以因緣與譬喻引導眾生且心無所懼，聞法者應設上供養。接著談天龍夜叉來聽法，說明好施而嗜酒肉者成地行夜叉，並引《舍利弗問經》說天龍八部因善惡二業成人非人，警惕性障。","p":["舌根淨須不大妄語、不欺誑眾生","以因緣、譬喻引導眾生心","弟子應恭敬供養說法之師","好施而嗜酒肉者將生為地行夜叉","天龍八部因善惡二業成人非人"],"k":["天龍八部","舌根清淨","夜叉","性障","人非人","舍利弗問經"]},"7128-a28_097":{"s":"本集續說三種夜叉：急性好快者成空行夜叉、好比較爭勝者生須彌山腰，並指密宗空行母、勇父屬夜叉層次，提醒布施須作意清淨、遠離酒肉。接著解釋天界阿修羅又名無酒，並引《大方等大集經》述弗沙耶若為度八弟千年苦行，八弟含彌勒、魔波旬、提婆達多與四阿修羅王，說明有漏心修行的果報。","p":["空行夜叉與山腰夜叉的成因","密宗空行母、勇父屬夜叉層次","布施時心須調柔，遠離瞋嫉與酒肉","阿修羅脾氣暴躁，又名無酒","弗沙耶若千年苦行度八弟的本生"],"k":["夜叉","阿修羅","布施作意","魔波旬","大方等大集經","天龍八部"]},"7132-a28_098":{"s":"本集先解舌根偈：梵天王、魔王等常來聽法，諸佛及弟子護念說法者。接著講身根八百功德經文「得清淨身如淨琉璃」，說明受持「此經」即證如來藏且轉依，讀、誦、解說、書寫各有層次；身根因不能如舌根全方位演繹故只八百功德，並說如來藏清淨身無取捨，一切世間皆於其中顯現。","p":["諸天常來聽法，諸佛護念說法者","受持此經即證如來藏且轉依不退","讀此經是悟後觀察如來藏自性","身根不能全方位演繹，故八百功德","一切世間皆於如來藏清淨身中現"],"k":["身根功德","如來藏","此經","清淨身","讀誦解說書寫"]},"7139-a28_099":{"s":"本集說明器世間由有情如來藏依業以「不可知執受」變現，如來藏非色非非色、具大種性自性，故能生色身與器世間。解偈「唯獨自明了，餘人所不見」為菩薩所獨證；並引《楞伽經》說種性、非種與心量，引《大般若經》說菩薩種性超越聲聞獨覺，也說明世尊晚說《法華》與五千人退席。","p":["器世間由有情如來藏依業變現","如來藏非色非非色，具大種性自性","唯獨自明了：二乘亦不見此清淨身","楞伽經：種性、非種與心量","菩薩種性超越聲聞獨覺，故稱尊貴"],"k":["菩薩種性","如來藏","大種性自性","器世間","楞伽經","清淨身"]},"7143-a28_100":{"s":"本集引《楞嚴經》說明十二類有情的本覺心體與諸佛無二無別，並辨正這不是眾生共有一個如來藏；眾生因迷理、癡愛而有虛空與世界生起。接著解說〈法師功德品〉身根清淨重頌「諸天宮殿…皆於身中現」，配合《楞伽經》藏識海喻，勉勵行者具足菩薩種性。","p":["眾生與佛心體無二無別，非共一大我","迷理癡愛而有虛空與世界生起","虛空依色法邊際假名施設，名色邊色","諸天宮殿山海皆於如來藏清淨身中現","藏識海與七識浪喻，萬法唯識"],"k":["如來藏","清淨身","楞嚴經","楞伽經","萬法唯識","菩薩種性"]},"7145-a28_101":{"s":"本集講〈法師功德品〉八百身功德。先界定「法師」須於三乘菩提有實證、依如來藏演說《法華經》，並說明受持、讀、誦、解說、書寫「此經」的真義。再解釋偈頌「雖未得無漏，法性之妙身，以清淨常體，一切於中現」，論證清淨常體是第八識如來藏，而不是五蘊身。","p":["法師須於三乘菩提有實證","六根功德皆依如來藏妙真如性而有","受持是悟後心得決定、轉依不退","讀誦解說書寫此經的實義","清淨常體能現一切，即如來藏非五蘊"],"k":["法師功德品","八百身功德","清淨身","受持讀誦","如來藏","轉依"]},"7157-a28_102":{"s":"本集解說〈法師功德品〉意根清淨得千二百功德的經文，說明讀、誦、解說、書寫自身「此經」的意義，其中書寫包括著書流布與主持禪三。再以鏡體與鏡像為喻，說明從如來藏看一切法本不生滅，與解脫道觀生滅的角度不同；最後說染汙意根處處作主，須轉依如來藏才能清淨。","p":["讀此經是悟後不斷觀察如來藏","書寫：著書流布與主持禪三","解脫道觀生滅，實相觀法本不生滅","鏡體鏡像喻、螞蟻五陰喻","染汙意根因取捨而處處作主"],"k":["意根清淨","千二百意功德","一切法本不生滅","鏡像喻","無量義","轉依"]},"7161-a28_103":{"s":"本集複習受持、讀、誦、解說、書寫「此經」的內涵，再依《楞嚴經》說明六根功德為何有八百與一千二百之別：眼根前明後暗，三分缺一故八百；耳根周聽十方無遺故千二百；鼻根出入息中交有闕故八百；舌根言有方分而理無窮盡，故千二百。","p":["受持：證悟後對此經心得決定不改","讀經要讀透經背、讀自身法華經","眼根前明後暗，僅八百功德","耳根周聽十方無遺，圓滿千二百","鼻根闕中交八百，舌根理無窮盡千二百"],"k":["六根功德","楞嚴經","法師功德品","耳根","受持讀誦"]},"7166-a28_104":{"s":"本集續講六根功德差別：身根合時能覺、離中不知，闕一分故八百功德；經中所說的根是含攝五識、意識的功能，不是扶塵根。重點解說意根「默容十方三世一切世間出世間法」：意根了別慧差、不起語言卻作決定，默容往世種子，故具千二百功德，修行到後來須從意根入手。","p":["身根合時能覺離中不知，八百功德","根指功能，非扶塵根或勝義根","意根默容十方三世一切法","意根不起語言，看意識處理後作決定","往世善惡緣、夢見往世皆意根相應"],"k":["意根","默容","六根功德","身根","種子","楞嚴經"]},"7160-a28_105":{"s":"本集續談意根「惟聖與凡，無不包容」，舉初學佛時似曾相識、夢見往世等例，說明意根默容往世所熏種子，緣熟時便相應。並說眠熟時睡的是意根，六識運作都不離意根；意根千二百功德不能取代前五根，須到成佛四智圓明才圓滿，法與次法具足修證即可證清淨意根。","p":["意根默容四聖六凡十法界種子","似曾相識、夢見往世等例證","菩薩世世不捨七轉識，藉意根淨化","眠熟位：意識斷而意根仍在","意根功德到成佛時才圓滿"],"k":["意根","惟聖與凡無不包容","眠熟位","四智","種子","法與次法"]},"7155-a28_106":{"s":"本集解說意根清淨者能知六趣眾生心行，所說世間法亦順正法。以龍樹《中論》為例，說明用八識論解釋則外道質疑也成正法，用六識論的應成、自續派中觀解釋則成邪法，並述龍樹與提婆的試驗典故，批評釋印順。再說意根清淨的層次，以荷花「花果同時」比喻開悟時如來藏種子本已具足。","p":["正人說邪法，邪法亦隨正","《中論》須以八識論解才通","批評應成派中觀與釋印順六識論","意根清淨由不貪五欲到離欲得禪","荷花花果同時喻開悟見如來藏種子"],"k":["意根清淨","八識論","中論","應成派中觀","花果同時","妙法蓮華"]},"7147-a28_107":{"s":"本集以往生極樂時蓮苞開敷為例續講「花果同時」，說明意根清淨有不同層次：從不貪額外五欲、離欲界貪，到俱解脫、三明六通，所知眾生心行隨之增多，到佛地才圓滿。並依八識心王現行多寡，觀察人、畜生、鬼神、地獄及三界諸天眾生的「心之所行」，說明悟後能「皆悉知之」。","p":["極樂蓮苞開敷喻花果同時","意根清淨分層次，佛地圓滿知之","意根時時作主，如見香腸攤之例","眾生八識現行多寡，最少剩三識","三界六道心之所行可比量了知"],"k":["意根清淨","八識心王","心之所行","花果同時","三界六道","極樂淨土"]},"7149-a28_108":{"s":"本集解說「雖未得無漏智慧，而其意根清淨如此」：意根第一分清淨是悟後轉依如來藏、不再認五陰為真我，並批評「要當自己、把握自己」是我見的美化。說明此菩薩思惟籌量言說皆是佛法、同於先佛所說，因佛佛道同、實相唯一；再解讀重頌，說五根清淨皆依意根清淨。","p":["意根第一分清淨：不再執五陰為真","「把握自己」是我見我執的美化","佛佛道同，實相只有一種","八萬四千法門同入一個大殿","五根清淨皆依意根，意根統攝諸法"],"k":["意根清淨","佛佛道同","我見","實相唯一","先佛所說"]},"7163-a28_109":{"s":"本集解說重頌「以此妙意根，知上中下法；乃至聞一偈，通達無量義」，說明通達須知諸法在佛菩提道中的位階（法住法位），並具解脫道四果及大乘真見道、相見道功德。以「涅槃」「真如」為例，示範由一法貫串四種涅槃、施戒生天之論、十因緣與十二因緣，說明通達者能從一法說盡佛法。","p":["意根清淨使意識專注第一義諦","通達須知法住法位、諸法位階","未通達而自稱入地是大妄語","由涅槃一詞演說四種涅槃至成佛","由真如貫串世間法、聲聞、緣覺"],"k":["通達無量義","法住法位","四種涅槃","十因緣","真如","意根清淨"]},"7168-a28_110":{"s":"本集續說真如與佛菩提五十二位階的關聯，強調「法住法位，法爾如是」不可改變，說主張佛法演變者是凡夫；並解說「次第如法說」，指出見地通達才能摧邪顯正。再解「所念若干種，一時皆悉知」：眾生總念是我、別念在我所，皆緣真如而有；並說攝受眾生即攝受佛土。","p":["真如貫串菩薩種性與五十二位階","法住法位法爾如是，不可演變","次第說、如法說，見地通達可摧邪","眾生總念是我，別念是我所","利益攝受眾生即攝受佛土"],"k":["法住法位","法爾如是","通達","眾生心念","攝受佛土","意根清淨"]},"7173-a28_111":{"s":"本集先總結〈法師功德品〉六根功德與意根清淨，再講偈頌「十方無數佛，百福莊嚴相」。引《增壹阿含經》三乘之教，批評六識論者說大乘由懷念佛陀演化而來是謗佛謗法，並論十方有無數佛。再引經論說明三十二大人相每一相都具百福，百福來自十善業各有前後十思、合為百思。","p":["意根清淨統攝五根清淨","阿含說三乘之教，駁大乘非佛說","佛示現涅槃後於他方續示現","三十二相一一相皆具百福","十善業各十思，合為百思百福"],"k":["百福莊嚴相","三十二相","大乘非佛說","十善業","三乘之教"]},"7182-a28_112":{"s":"本集具體說明百思的修法：依《大毘婆沙論》，十善業每一業先作離殺、勸道、讚美、隨喜、迴向五思，事後再作加行淨、根本淨、後起淨、離尋伺害、念攝受五思。以被問「你悟了沒有」如何得體回答為例逐一解釋，並說攝受是利益對方而非拉眷屬，福德是實證智慧的支撐。","p":["每一善業前五思、後五思共十思","前五思：離殺勸道讚美隨喜迴向","以回答「悟了沒有」為例說明","後五思：加行淨根本淨後起淨等","念攝受是利益他人，非拉眷屬"],"k":["百福莊嚴相","十善業","前五思後五思","福德","攝受"]},"7169-a28_113":{"s":"本集說明以百思修百福的利益：言語不帶酸諂嫉妒、去除暴戾之氣、快速修除性障乃至取證三果，未來受彌勒佛授記的層次更高。並引《優婆塞戒經》說佛的三十二相具百福，轉輪聖王相則不明了；善業夾帶不淨會使福德流失。最後說諸佛以百福莊嚴相攝受眾生，故聞法者能受持。","p":["百思使言語清淨、去除暴戾之氣","快速除性障，利於彌勒授記","佛相具百福，與轉輪王相不同","善業夾雜不淨，福德會流失打折","百福莊嚴相令眾生信受所說"],"k":["百福","性障","三十二相","轉輪聖王","授記","福德"]},"7177-a28_114":{"s":"本集解說重頌「思惟無量義，說法亦無量；終始不忘錯，以持法華故」，說明真見道是相見道與通達位的基礎，通達後一法可思惟無量義，且依現觀而說，所以前後不矛盾。再解「悉知諸法相，隨義識次第」，批評佛法演變之說；並說「此人有所說，皆是先佛法」，佛法沒有創見，故於眾無所畏。","p":["真見道證真如是通達的基礎","依現觀而說，終始不忘錯不矛盾","諸法次第位階不可改變","一切法收圓於法華唯一佛乘","所說皆先佛法，佛法無創見"],"k":["通達無量義","真見道","終始不忘錯","法住法位","先佛所說","唯一佛乘"]},"7189-a28_115":{"s":"本集解說「持法花經者，意根淨若斯；雖未得無漏，先有如是相」，說明見地通達至少要證三果並通達般若，並起惑潤生、世世受生。再解「是人持此經，安住希有地…分別而說法」，說三轉法輪諸經皆依如來藏而說，並舉平實導師弘法、寫《狂密與真密》為例，說明受持如來藏才能安住希有地、善巧說法。","p":["意根淨：起惑潤生，不入無餘涅槃","三轉法輪諸經皆依此經如來藏說","安住希有地，外道不能推翻","施設方便譬喻，分別而說法","無量義經開演，法華收歸一法"],"k":["意根清淨","安住希有地","善巧方便","唯一佛乘","無量義經","如來藏"]},"7179-a28_116":{"s":"本集說明明心與見性都是頓悟、沒有漸悟，悟後須次第漸修。引《楞嚴經》「理則頓悟，乘悟併銷；事非頓除，因次第盡」，說六根清淨分見地與事修。並區分明心與眼見佛性，批評觀想中脈明點及「捨識用根」之說，以劫波羅巾六結喻說明須根識合作、次第解結，選耳根圓通入手。","p":["明心見性皆一念相應頓悟","理則頓悟，事非頓除因次第盡","明心與眼見佛性的差別","批評觀想明點、捨識用根之說","劫波羅巾六結：根識合作次第解"],"k":["頓悟漸修","楞嚴經","六根清淨","眼見佛性","解結","耳根圓通"]},"7175-a28_117":{"s":"本集解說《楞嚴經》觀世音菩薩「從聞思修入三摩地；初於聞中，入流亡所」的意義：所聞是善知識所說的如來藏正法而非聲塵，三摩地是佛菩提智慧心得決定而非禪定。說明入流亡所、所入既寂、動靜二相了然不生，以耳根聞正法流亡邪見、親證如來藏即入流成正覺，末談常不輕、常精進。","p":["聞思修所聞是正法，非聽聲音","三摩地是智慧決定境界，非禪定","入流亡所、動靜二相了然不生","耳根聞正法，流亡五蘊真實邪見","常不輕、常精進可化長劫入短劫"],"k":["耳根圓通","觀音法門","入流亡所","聞思修","三摩地","化長劫入短劫"]},"7184-a28_118":{"s":"本集說明六根清淨分見地上（通達位完成）與事修上（初地起次第進修至等覺），清淨意根須先清淨意識，並批評捨識用根、宗喀巴《菩提道次第廣論》及即身成佛之說。接著進入〈常不輕菩薩品〉，解說謗持法華者獲大罪報的經文，介紹得大勢菩薩與極樂三聖紹繼佛位，比較極樂與娑婆修行的長短劫。","p":["六根清淨分見地與事修兩層","意根清淨須靠意識修行與取捨","批評宗喀巴廣論與即身成佛","〈常不輕菩薩品〉：謗者獲大罪報","得大勢菩薩與極樂佛位紹繼"],"k":["六根清淨","常不輕菩薩品","捨識用根","得大勢菩薩","極樂世界","宗喀巴"]},"7171-a28_119":{"s":"本集說明娑婆修行屬短劫，因修福易成、慧學快速、賢劫千佛出世，並勸修信、精進、念、定、慧五根轉成五力。再解說〈常不輕菩薩品〉謗持法華者獲大罪報：依根本、方便、成已三事及被謗者證量，罪報從小地獄到阿鼻地獄不等，並說「劫盡更生」，以及受邪教導誤以如來藏為神我而誹謗的情形。","p":["娑婆修福修慧快速，化長劫入短劫","五根轉為五力的修行次第","根本、方便、成已決定罪報輕重","謗法重者入阿鼻地獄劫盡更生","受邪教導誤謗如來藏為神我"],"k":["化長劫入短劫","誹謗正法","根本方便成已","地獄罪報","五根五力","常不輕菩薩品"]},"7193-a28_120":{"s":"本集進入〈常不輕菩薩品〉，先說誹謗「妙法蓮華」如來藏者歷經地獄、畜生，再生人間貧賤、橫禍不斷且不聞正法的長劫罪報，與受持者得六根清淨作對比；再解說威音王如來、離衰劫、大成國的經文，並闡釋「應四諦法」中「應」字的意義。","p":["謗如來藏者墮地獄，再轉生牛馬蟒蛇，歷劫久遠","還生人間五根缺陷、貧賤橫禍、不聞正法","受持妙法蓮華者得六根清淨功德","威音王如來為最初佛，釋離衰劫、大成國之名","所學須與四聖諦相應；阿闍世王僅得無根信"],"k":["常不輕菩薩品","誹謗正法罪報","威音王如來","應四諦法","六根清淨","如來藏"]},"7195-a28_121":{"s":"本集說明佛陀開示四聖諦前，先講施論、戒論、生天之論及欲為不淨等次法，並依根性教導五停心觀作為「應四諦法」，現代則以無相念佛為之；又說阿含中增說因緣法即「應十二因緣法」，並指十二因緣每一支背後皆以阿賴耶識為根本因。","p":["先說施論戒論生天論，再說欲為不淨、上漏為患","不淨觀、數息、慈心、因緣觀、界差別觀各有對治","念佛觀與因材施教；無相念佛為現代應四諦法","增說因緣法是為使聽者與十二因緣相應","十二因緣每一支皆依阿賴耶識根本因而有"],"k":["應四諦法","五停心觀","十二因緣","無相念佛","阿賴耶識","界差別觀"]},"7200-a28_122":{"s":"本集從佛教主張眾生皆可成佛談起，說明《法華經》所講的成佛「如是因」即實證般若、證第八識如來藏，並須以菩薩道五十二階位為「如是緣」。講者批評以緣起性空為佛法核心的無因唯緣論，並以如來藏說明三寶常住、往生「去則實不去」及因果業報。","p":["佛教與一神教不同：願一切眾生皆成佛","成佛之因為證如來藏，須五十二階位為緣","有因有緣集世間，其因即第八識如來藏","批評把緣起性空當佛法核心的無因唯緣論","三寶常住、去則實不去皆依如來藏而說"],"k":["如是因","如來藏","緣起性空","無因唯緣論","般若","三寶"]},"7185-a28_123":{"s":"本集說明《法華經》是佛特意宣講、為開示悟入成佛之道的經典。講者批評清朝以來喇嘛教被當作佛教，以及2016年版《中華電子佛典》於《大藏經補編》收錄宗喀巴等著作，呼籲將其擯除或另立標題；最後說佛法核心是如來藏，佛意難知。","p":["法華經非隨宜說法，乃佛特意宣講","清朝皇室崇奉喇嘛教，致如來藏妙義難弘","批評CBETA大藏經補編收錄宗喀巴著作","編修藏經應揀擇真偽，不應淪為學術集成","心經密意即如來藏；學佛究竟在成佛道"],"k":["法華經","大藏經編修","喇嘛教","宗喀巴","如來藏","開示悟入"]},"7204-a28_124":{"s":"本集解說〈方便品〉中五千聲聞增上慢退席的原因：他們以為解脫生死即學佛究竟、阿羅漢等同佛。講者藉舍利弗三請與「止止不須說」經文，說明阿羅漢涅槃與佛地常樂我淨、無住處涅槃不同，並批評印順以涅槃寂靜為究極理想的說法。","p":["五千人以為解脫生死即學佛畢業，故退席","舍利弗三請，佛說止止不須說、我法妙難思","增上慢即未證言證、未得謂得","阿羅漢涅槃非常樂我淨，唯佛地無垢識是","二乘法須依大乘如來藏方能成立"],"k":["增上慢","五千退席","方便品","常樂我淨","無住處涅槃","二乘與佛乘"]},"7191-a28_125":{"s":"本集講「諸佛唯以一大事因緣出現於世」，說明此大事是令眾生成佛，而非僅解脫生死；並解釋開、示、悟、入佛之知見，強調宗不離教、教不離宗，佛之知見即證悟如來藏的真如與佛性，明心與見性為兩關。講者也批評以離念靈知為開悟等錯誤修行。","p":["一大事因緣是令眾生成就佛道","二乘法是於一佛乘分別說三的方便","開示悟入佛知見；宗門與教門須互相配合","佛之知見即如來藏真如與佛性，明心見性兩關","一念不生、離念靈知仍屬意識境界"],"k":["一大事因緣","開示悟入","佛之知見","一佛乘","明心見性","真如"]},"7208-a28_126":{"s":"本集從如是相、性、體、力、作、因、緣、果、報等面向說明成佛的法華：成佛之報為常樂我淨，依大乘法涅槃以如來藏為體，成佛以三乘菩提實證為因、菩薩道五十二階位為次第。講者批評六識論者的無因唯緣論，並引〈方便品〉偈說明佛智不可測度。","p":["成佛須有七世清淨父母等如是緣","成佛以三乘菩提為因，其報為常樂我淨","依大乘法，涅槃以如來藏為體","批評六識論者之無因唯緣論","開悟僅七住位，佛智不可測量"],"k":["成佛之道","如是因緣果報","常樂我淨","涅槃","菩薩五十二階位","八識論"]},"7198-a28_127":{"s":"本集解說〈常不輕菩薩品〉經文：威音王佛像法時期，常不輕比丘禮拜四眾說「汝等皆當作佛」，遭罵詈打擲仍不改。講者說明常不輕即釋迦牟尼佛前身，引《大悲經》摩竭大魚聞佛名得度的故事，並說他依所證如來藏禮拜以滅慢心與往昔罪業，臨終聞《法華經》而六根清淨。","p":["常不輕比丘禮拜四眾：我不敢輕於汝等","大悲經：摩竭大魚聞佛名，終證阿羅漢","像法時期增上慢比丘有大勢力","只對行菩薩道的佛門四眾禮拜讚歎","禮拜滅慢心習氣與罪業，臨終得六根清淨"],"k":["常不輕菩薩","增上慢","威音王佛","滅罪","慢心","六根清淨"]},"7202-a28_128":{"s":"本集講常不輕菩薩六根清淨增壽後，廣說《法華經》（即如來藏經），以大神通力、樂說辯力、大善寂力令增上慢四眾信伏，並值遇日月燈明佛、雲自在燈王佛。講者說明見取見使意識不淨，引《大般若經》說壞正法業重於五無間，及輕賤者二百億劫不值三寶的果報。","p":["六根清淨後增壽二百萬億那由他歲廣說此經","大神通力、樂說辯力、大善寂力三種功德","先後值遇二千億日月燈明佛、雲自在燈王佛","見取見以鬥爭為業，致意識與諸根不淨","壞正法業重於五無間；以得大勢為緣起人"],"k":["常不輕菩薩","四無礙辯","見取見","謗法罪業","得大勢菩薩","法華經"]},"7187-a28_129":{"s":"本集講「則我身是」：常不輕菩薩即釋迦牟尼佛，因世世受持、讀誦、為人演說此經如來藏而疾得菩提。講者說明真實僧寶的定義，引《雜阿含》「斧在口中生」與《大般若經》匱正法業歷經地獄、傍生、餓鬼的長劫苦報，說明一千五百位輕賤者的後果，勸人勿輕易評論善知識。","p":["常不輕菩薩即釋迦如來，因受持此經疾得成佛","此經即如來藏，亦即金剛經、心經","僧寶須明心不退，所說須符八識論","斧在口中生；匱正法業長劫輪轉三惡道","無法眼慧眼時應謹言慎行，勿隨意評論"],"k":["謗法罪報","常不輕菩薩","如來藏","僧寶","口業","匱正法業"]},"7206-a28_130":{"s":"本集解說「常應受持、讀誦、解說、書寫是經」：受持、讀誦為自利，即悟後現觀如來藏；解說、書寫為利他與流傳後世。講者引《賢愚經》說阿難總持的因緣，並依偈頌說明眾生皆有無始無明、無人無始成佛，故必有最初的威音王佛；並釋「計著於法」，勉勵延續正法、破邪顯正。","p":["受持讀誦為自己，解說書寫為有緣人與後世","阿難往昔供養小沙彌，故得總持不忘","阿難是諸大阿羅漢中最快成佛者","眾生皆有無始無明，無人無始成佛","計著於法者未證言證，須破邪顯正救護"],"k":["受持讀誦解說書寫","總持","阿難","無始無明","二障","計著於法"]},"7222-a28_131":{"s":"本集說明常不輕菩薩說「我不輕汝，汝等皆當作佛」是有所本：一切有情皆有此經如來藏，理上本是佛，並非僅因有善根。他依實相具足生忍與法忍，長時安忍打罵以最快速滅罪，未來得眷屬和合；罪畢臨終得聞此經而六根清淨、增益壽命，再廣說此經。","p":["悟後見蚊蠅亦有此經，故不敢輕視他人","一低頭、一舉手皆已成佛道，理上本是佛","生忍與法忍：依實相現觀而能長時安忍","被輕賤打罵即滅先世罪業，金剛經亦有此說","罪畢得聞此經六根清淨，增壽廣說此經"],"k":["常不輕菩薩","安忍","生忍法忍","滅罪","如來藏","眷屬和合"]},"7210-a29_001":{"s":"本集概述〈常不輕菩薩品〉：此品講娑婆世界佛教的由來，並勉勵悟後回頭提攜有緣眾生。講者重述誹謗受持者的罪報、威音王佛事蹟、常不輕菩薩禮拜四眾至臨終聞經六根清淨、增壽說法，及輕賤者的果報；最後說明受持、讀誦為自度，解說、書寫為度人與流傳後世。","p":["悟後應回頭提昇有緣法眾，不當自了漢","誹謗受持法華者墮三塗，輪轉無有了期","威音王佛與常不輕菩薩事蹟概述","輕賤者二百億劫不值三寶、千劫受苦阿鼻","受持讀誦為自度，解說書寫為度人傳後世"],"k":["常不輕菩薩品","威音王佛","受持讀誦解說書寫","誹謗罪報","如來藏"]},"7219-a29_002":{"s":"本集續講〈常不輕菩薩品〉：此經是每人本具的如來藏，常不輕菩薩依此經教化諸著法眾，值無量佛而早成佛。講者勉勵悟後勿起慢心、勿否定第八識，對誹謗者也不放棄而為其種下正法種子；並串連〈如來壽量品〉、〈法師功德品〉與本品，指出一切歸結於此經如來藏。","p":["此經即人人本具的如來藏經、妙法蓮華","九百九十九兄弟之願，示現千佛次第成佛","悟後勿起慢心、勿輕易否定第八識","對謗法者不放棄，先為其種下正法種子","壽量品、法師功德品與本品前後聯結"],"k":["常不輕菩薩品","如來藏","攝受謗法者","如來壽量品","法師功德品","慢心"]},"7216-a29_003":{"s":"本集開講〈如來神力品〉，說明釋迦如來久遠已成佛，從地踊出的菩薩誓願於分身佛滅度處廣說《法華經》，並說只有應身佛能講此經。講者解釋四種涅槃與佛地常樂我淨的「真淨大法」，批評以一念不生為不生的錯誤，並說明因地如來藏心體雖常而種子仍在變異。","p":["從地踊出菩薩誓願於佛滅後廣說此經","唯應身佛能講法華經，化身佛不能","四種涅槃具足者方為大般涅槃","一念不生是將滅止生，非真不生不滅","因地如來藏體常而種子變異，佛地方究竟常"],"k":["如來神力品","常樂我淨","四種涅槃","應身佛","變易生死","無垢識"]},"7228-a29_004":{"s":"本集續講佛地常樂我淨：樂是斷盡二種生死、證無住處涅槃；我是佛地第八識與五別境、善十一心所相應並有證自證分；淨是心體與種子內外俱淨。講者說明二乘只說非常非樂非我非淨，菩薩未斷塵沙惑仍未究竟；並說佛將弘經機會留給從地踊出的嫡傳弟子，及解說能教學相長。","p":["樂：斷分段與變易生死，證無住處涅槃","我：佛地第八識具五別境等心所與證自證分","淨：心體與所含種子內外俱淨","二乘觀蘊處界皆非常非樂非我非淨","弘經機會留給從地踊出菩薩；解說教學相長"],"k":["常樂我淨","無住處涅槃","塵沙惑","無垢識","從地踊出菩薩","如來神力品"]},"7244-a29_005":{"s":"本集說明以受持、讀誦、解說、書寫四種方式供養《妙法蓮華經》，強調解說能教學相長、攝受佛土，書寫則可對治相似像法的流行。講者批評密教部諸經為偽經，並解說〈如來神力品〉「出廣長舌上至梵世」與「一切毛孔放無量色光遍照十方」的意涵。","p":["解說利他亦自利，助眾成長即攝受佛土","不書寫則相似像法遍滿，正法將滅沒","名為法華經講義，表所講為真實義","廣長舌上至梵世：法音警覺至色界諸天","毛孔放無量色光，顯十方諸佛佛佛道同"],"k":["供養法華經","書寫","相似像法","廣長舌","如來神力品","破邪顯正"]},"7232-a29_006":{"s":"本集續解〈如來神力品〉：分身諸佛同現廣長舌、放光百千歲後謦欬彈指，十方大地六種震動，眾生皆見娑婆諸佛及釋迦、多寶二佛同坐寶塔，諸天唱言勸禮，供物化為寶帳，十方如一佛土。講者從密意說十方世界皆是如來藏世界，佛佛道同。","p":["分身諸佛同出廣長舌放光，後謦欬彈指","釋迦與多寶二佛同坐寶塔乃是特例","十方眾生遙散供物，化為寶帳覆諸佛上","密意：十方皆如來藏世界，故如一佛土","諸佛所傳同一心，非夜夜斷滅的離念靈知"],"k":["如來神力品","如一佛土","多寶如來","佛佛道同","如來藏","分身佛"]},"7214-a29_007":{"s":"本集解說世尊告上行等菩薩：以神力於無量劫說此經功德猶不能盡，因如來一切所有之法、自在神力、祕要之藏、甚深之事皆於此經宣說。講者說明上行菩薩指證悟者，此經即真心如來藏，一切法、業種與福德皆在其中，如來藏為萬法總樞紐。","p":["此段對證悟的上行菩薩說，退回識陰者為下行","諸佛神力是智慧，故無量無邊不可稱量","此經即如來藏，故久劫說之亦不能盡","自在神力源於福德與四無所畏，皆依此經","如來藏為萬法根源，如樹之根盤"],"k":["如來神力品","如來藏","上行菩薩","祕要之藏","四無所畏","此經功德"]},"7230-a29_008":{"s":"本集續講「如來一切祕要之藏」：人間十八界具足，如來藏妙法蓮華在人間最圓滿；如來囑咐隱覆說義，以免未熟者生疑謗法。講者舉眼見佛性的如幻觀等現觀與處非處智力，說明祕要與甚深之事皆歸此經，並釋「一心受持……如說修行」，勉勵證悟者自知彌足尊貴、協助摧邪顯正。","p":["人間十八界具足，妙法蓮華在人間最圓滿","須隱覆說義，令學人親自參究","如幻觀等現觀唯證乃知，屬祕要之藏","處非處智力知眾生輾轉受報，為甚深之事","佛滅後應一心依此經修行；證悟者彌足尊貴"],"k":["祕要之藏","隱覆密意","如幻觀","眼見佛性","處非處智力","一心受持"]},"7226-a29_009":{"s":"本集講解〈如來神力品〉中佛滅後應一心受持、讀誦、解說、書寫此經的意涵。受持讀誦為自利，指證悟後於如來藏體性上觀行，才是讀佛門內典；並舉文殊、童女迦葉、維摩詰為例，說明大乘依證量而非聲聞戒定位勝義僧，菩薩戒為正解脫戒；解說書寫則為利益當代與後世。","p":["受持讀誦為自利，解說書寫為利他","真正讀經是觀行如來藏，依文解義如讀外典","大乘依法上證量定位勝義僧，不依聲聞戒","菩薩戒為正解脫戒，聲聞戒為別解脫戒","宗義上如法受持須實證如來藏，不以解脫道為成佛之道"],"k":["受持讀誦解說書寫","如來藏","勝義僧","菩薩戒","如來神力品"]},"7234-a29_010":{"s":"本集續講〈如來神力品〉「當知是處即是道場」一段，說明證悟後見到自身「妙法蓮華經」經卷所在即可起塔供養，重在實質不在表相；證此經不分僧俗貴賤，眾生如來藏平等。諸佛得菩提、轉法輪、般涅槃皆不離第八識，眾生生死亦在如來藏中；並批評否定如來藏為謗法，強調此經不能依文解義。","p":["起塔供養方式無量，重實質不重表相","證此經不分僧俗男女貴賤，如來藏平等","諸佛於此經中得菩提、轉法輪、般涅槃","生死不離如來藏，明此即了生脫死","否定如來藏為謗法，此經不可依文解義"],"k":["道場","起塔供養","如來藏","般涅槃","轉法輪","依文解義"]},"7235-a29_011":{"s":"本集進入〈如來神力品〉重頌，引平實導師語譯說明偈意，並解釋長行後再說重頌的用意。重點辨析「救世者」與世間「救世主」：醫者、仙道、生天之教等救護皆有侷限，不出三界；佛證人無我、法無我而不以主自居，故稱救世者。並批評釋印順以如來為外道思想之說，及指喇嘛教非佛教。","p":["重頌為加深印象並補充長行未說之義","世間種種救世主之救護皆不出三界生死","佛證人無我與法無我，不自居為主故稱救世者","佛出世前外道自稱阿羅漢、如來皆是因中說果","批評釋印順「如來即外道思想」之說及喇嘛教"],"k":["救世者","人無我","法無我","重頌","如來神力品","喇嘛教"]},"7237-a29_012":{"s":"本集續講重頌「諸佛救世者，住於大神通」等句。說明佛度眾先說施論、戒論、生天之論等次法再說四聖諦，能度人超越分段與變易二種生死方稱大醫王；辨析神通層次與佛的宿住隨念智力，示現神通只為度眾。並從理上解釋廣長舌相、謦欬彈指與六種震動即六根震動，及讚美受持者功德說不盡。","p":["佛先說次法再說四聖諦，度人出三界","超越二種生死方為究竟大醫王、救世者","佛具宿住隨念智力，神通為度眾非炫耀","大地六種動於理上指證悟時六根震動","受持此經者功德無盡，以三輪體空布施為例"],"k":["大神通","次法","二種生死","六種震動","廣長舌相","三輪體空"]},"7224-a29_013":{"s":"本集依〈如來神力品〉「讚美受持者」偈，說明能持此經者即實證第八識、傳承正法的大乘菩薩，故稀有難得。進而講佛法修學次第：五乘佛法中人天善法為次法，即施論、戒論、生天之論與欲為不淨、上漏為患、出要為上的三論六學，並介紹四種悉檀與世界悉檀，指次法只是趣入三乘菩提的前方便。","p":["能持此經的證悟菩薩代代傳承如來正法","學佛不知次第，易退失初發菩提心","五乘佛法中人天善法為趣入三乘之次法","三論六學的內涵，三界皆不離生死","四種悉檀，三論主修世界悉檀"],"k":["修學次第","次法","三論六學","四種悉檀","五乘佛法"]},"7241-a29_014":{"s":"本集續說次法圓滿後進入三乘菩提之「法」，以對治、為人、第一義三悉檀對應三轉法輪。闡釋「則為已見我」非見報身或應身色相，而是見無形無相的第八識法身；並說明聲聞四聖諦、緣覺十因緣與十二因緣的教授次第，引《菩薩瓔珞本業經》述十信、十住至七住不退的歷程，最後總結修學階段。","p":["三種悉檀對應三轉法輪的教授內涵","「已見我」是見無形無相的第八識法身","聲聞四聖諦與緣覺十因緣、十二因緣次第","十信圓滿入十住，六住後證悟入七住不退","總結從人天善法到大乘六度的修學次第"],"k":["已見我","第八識","修學次第","十住位","菩薩瓔珞本業經","十二因緣"]},"7247-a29_015":{"s":"本集說明證第八識而入七住不退者即「能持是經者，則為已見我」，為始覺位、相似即佛，並列舉入住位所需條件，如擇法、五根五力、依法不依人。以「諸佛坐道場所得祕要法」說明所證非六識或離念靈知，而是本具如來智慧德相的第八識；並引玄奘《成唯識論》第八識執持流轉與還滅法種為教證。","p":["證此經入七住為始覺位、相似即佛","入住位需擇法、五根五力、依法不依人","諸佛所得祕要法是第八識，非離念靈知","證悟後漸轉識成智，能隨義如實說","引成唯識論：第八識執持流轉與還滅法種"],"k":["已見我","第八識","成唯識論","玄奘","七住位","六即佛"]},"7249-a29_016":{"s":"本集引玄奘《成唯識論》說明第八識隨義立名：心、阿陀那、所知依、種子識通一切位，阿賴耶、異熟識、無垢識則依階位不同，見如來即見此同一心。並引論文破斥經部師等六識論，指無第八識持種則因果相續不成；批評應成派與釋印順「大乘非佛說」，並舉彌勒七因證大乘真是佛說。","p":["已入見道菩薩能證解阿賴耶識","第八識隨階位立阿賴耶、異熟、無垢等名","無第八識持種，則因果相續不能成立","批評應成派與釋印順否定第八識、大乘非佛說","彌勒以七種因證大乘經真是佛說"],"k":["第八識","成唯識論","阿賴耶識","異熟識","無垢識","大乘非佛說"]},"7239-a29_017":{"s":"本集講〈如來神力品〉偈「知佛所說經，因緣及次第，隨義如實說」。說明五濁惡世見濁深重，佛須先以人天次法、二乘菩提為基礎，再引入佛菩提，最後收攝於《法華經》圓教。辨析權教與實教：次法與二乘屬善權方便，實教為第一義悉檀與六度、十度的成佛之道；並以今人不願否定意識說明次法熏習不足。","p":["佛示現人間是為教導實證佛菩提","須依次第弘法，不能一開始直說真實義","人天次法與二乘菩提屬權教","不願承認意識虛妄，顯示次法熏習不足","實教為第一義悉檀、六度十度成佛之道"],"k":["權教","實教","次法","斷我見","第一義悉檀","五濁惡世"]},"7246-a29_018":{"s":"本集說明佛法有頓教與漸教、始教與終教之分。二乘菩提只有漸教，「善來比丘」頓成阿羅漢實為菩薩再來；佛菩提的明心、見性、過牢關皆一念頓悟，但成佛過程仍須漸修。先說《華嚴》為始教，《法華》等為終教即圓教，合為五時三教；後解釋偈中「如日月光明」及「應受持斯經」等句。","p":["二乘菩提只有漸教，善來比丘乃菩薩再來","佛菩提見道皆一念頓悟，成佛仍須漸修","先講《華嚴》為始教，以免眾生疑佛","五時三教缺一不可，《法華》為終教圓教","受持斯經涵蓋如來藏總相及整體佛法"],"k":["頓教","漸教","始教","終教","五時三教","圓教"]},"7251-a29_019":{"s":"本集進入〈囑累品〉，講世尊現大神力三摩無量菩薩頂，付囑流布無上正等正覺法。指出世尊修道歷「無量百千萬億阿僧祇劫」，因最初無佛可依須自行摸索；引平實導師之說論證如來藏雖無始本有，佛地並非本有，最初威音王佛亦須斷二障成佛，否則違平等法。並解釋「一心流布」「廣宣此法」。","p":["世尊同時為無量菩薩摩頂，是如來大神力","世尊修道歷無量百千萬億阿僧祇劫","如來藏無始本有，但無本來成佛之佛","威音王佛後自稱無師成佛者為自然外道","一心流布、廣宣此法，令眾生普得聞知"],"k":["囑累品","本初佛","威音王佛","二障","摩頂付囑"]},"7258-a29_020":{"s":"本集承上集，說今人依佛修學只需三大阿僧祇劫，應感念佛恩師恩；並說明廣宣此法時自己亦須受持讀誦，自他兩利。由世尊說明付囑原因引申，強調學佛須先探究「為何學佛」，舉念佛三年佛在西天為例，並詳述平實導師從念佛、打坐到看話頭而破參的經歷，結論學佛是為成佛，須求開悟。","p":["依佛修學只需三大阿僧祇劫，應感念佛恩","廣宣此法的同時須自己受持讀誦","凡事有因，學佛應探究為何學佛","平實導師從念佛、打坐到看話頭悟入的經歷","學佛為成佛，不求開悟只是修集見道資糧"],"k":["學佛目的","廣宣此法","看話頭","開悟明心","紹隆佛種"]},"7260-a29_021":{"s":"本集講〈囑累品〉「如來有大慈悲，無諸慳悋，亦無所畏」。說明世尊於人壽百歲困苦時示現、教導三乘、財法無吝即大慈悲；並闡釋四無所畏：如來於煩惱障現行與習氣種子、所知障與上煩惱皆已斷盡，且具知對治之法。舉鴿入佛影無怖、阿羅漢抖蛇之例說明習氣，並述通達與入地條件。","p":["佛於困苦時節示現並教三乘，是大慈悲","財物與佛法上皆無慳吝","煩惱障分現行與習氣種子，以鴿影為喻","通達須廣修福德、永伏性障、進修般若","煩惱障與所知障各二無所畏，合為四無所畏"],"k":["四無所畏","大慈悲","煩惱障","所知障","習氣種子","十無盡願"]},"7263-a29_022":{"s":"本集解釋如來所施三種智慧。佛之智慧即一切種智，具足證知如來藏所含一切種子（功能差別），並以共業如來藏變生食物、《起世經》地肥粳米為例；如來智慧指初地至十地修道所證的道種智；自然智慧則是證得本有第八識的實相般若，有別於把離念覺知心當真心及自然外道，又稱無師智。","p":["佛之智慧即一切種智，證知如來藏一切種子","種子即功能差別，共業如來藏變生器世間","如來智慧為初地至十地的道種智","離念覺知心是有生之法，非自然智慧","自然智慧為證本有第八識之實相般若、無師智"],"k":["一切種智","道種智","自然智慧","種子","如來藏","自然外道"]},"7253-a29_023":{"s":"本集說明如來以究竟法施利益眾生，故為一切眾生之大施主，勉菩薩隨學勿慳。解釋「若有善男子、善女人信如來智慧者，當為演說此《法華經》」：引《雜阿含》界定不善男子為行十不善者，並指信如來智慧者才合格；批評六識論者等同佛與阿羅漢，依意根、十八界與涅槃本際說明二乘亦依八識論，末述別教與通教。","p":["法布施最勝，佛為三界最大施主","《雜阿含》：行十不善業者為不善男子","信受如來智慧者才宜為說《法華經》","意根與涅槃本際顯示二乘亦依八識論","別教不共二乘，通教菩薩終將信如來智慧"],"k":["大施主","法布施","善男子善女人","八識論","涅槃本際","通教別教"]},"7266-a29_024":{"s":"本集續講「若有眾生不信受者，當於如來餘深法中示教利喜」。說明對不信如來智慧者，先依八識論說真正二乘菩提，由五陰十八界、意根與涅槃本際導其接受八識；若連三界因果都不信，則先說世界悉檀與次法。信受後再說六度等餘深法乃至此經；依根器如法說法即報諸佛恩，並引彌勒說此為諸佛密意。","p":["二乘菩提對凡夫而言也是如來餘深法","由五陰十八界、意根、本際引入八識論","不信因果者先說世界悉檀與次法","前五度為佛菩提次法，六度圓滿方能實證","依根器如法說法即是報諸佛恩"],"k":["如來餘深法","示教利喜","八識論","方便善巧","報佛恩","囑累品"]},"7269-a29_025":{"s":"本集講〈囑累品〉末段：菩薩摩訶薩聞付囑後遍身歡喜，曲躬低頭合掌三度承諾奉行，世尊遂令分身諸佛各還本土、多寶塔復原。說明多寶如來敬重此經因一切法由此經出生，世尊視菩薩如獨子；並述末法魔子混入佛門之憂，勉弟子承擔護持正法、破斥密宗外道之任，以送真黃金為喻說難能可貴。","p":["多寶如來尊重此經，因一切法由此經生","世尊視菩薩如獨子，殷勤付囑","菩薩曲躬合掌三度承諾如敕奉行","末法魔子混入佛門，須防密教興而佛教亡","難能而為方可貴，勉眾承擔正法"],"k":["囑累品","多寶如來","付囑","護持正法","密宗"]},"7265-a29_026":{"s":"本集進入〈藥王菩薩本事品〉，宿王華菩薩為眾請問藥王菩薩本生因緣，世尊說過去日月淨明德如來及其淨土。說明世尊初提一佛必說十號，是為提示成佛應具功德，免人自稱成佛犯大妄語；並解釋大菩薩摩訶薩、大聲聞的定義，比較淨土與三界諸天之異，及此土無女人、三惡道與諸難的莊嚴。","p":["宿王華菩薩為大眾請問藥王本生因緣","初提一佛必說十號，防自稱成佛大妄語","大菩薩摩訶薩約指八地以上","淨土依諸佛別願成就，不同於三界諸天","《法華經》涵蓋三乘一切佛法"],"k":["藥王菩薩本事品","如來十號","日月淨明德佛","淨土","大妄語"]},"7259-a29_027":{"s":"本集說日月淨明德佛座下大聲聞實為菩薩，讀經不可依文解義。引經講一切眾生喜見菩薩樂習苦行、精進經行，得現一切色身三昧，以神力及燃身供養佛與《法華經》。說明正覺主張制心一處、念念於法的「心苦行」而非身苦行；並解釋迷事與迷理無明，及從理上觀一切色身同由如來藏所生的普現色身三昧。","p":["大聲聞眾現聲聞相，本質為菩薩","喜見菩薩樂習苦行，燃身作法供養","正覺主張心苦行而非身苦行","迷事無明與迷理無明之別","理上觀己身、佛身、眾生身同一如來藏"],"k":["一切眾生喜見菩薩","現一切色身三昧","心苦行","迷理無明","法供養"]},"7255-a29_028":{"s":"本集續說理上的現一切色身三昧：有情無量世輪轉天人、人、三惡道，各世色身皆由如來藏普門示現，現觀而心得決定即是此三昧，亦可生平等心；喜見菩薩則因身根清淨能於事上隨意示現。並說長劫苦行而得明心仍然值得，勉人日常供佛、供衣並作意供養自身如來藏，強調法供養勝於世間供養。","p":["有情世世色身皆是如來藏普門示現","理上現觀而心得決定即現一切色身三昧","喜見菩薩身根清淨，能於事上隨意示現","長劫苦行而得明心仍然值得","日常供佛並作意供養自身如來藏，重法供養"],"k":["現一切色身三昧","普門示現","如來藏","法供養","明心","供佛"]},"7282-a29_029":{"s":"本集講解〈藥王菩薩本事品〉：一切眾生喜見菩薩因聞《法華經》得現一切色身三昧，以三昧力雨下寶華與海此岸栴檀供佛，再服香、塗香油、纏天衣燃身供佛一千二百歲，諸佛讚為真法供養。講者說明施者、福田、施物皆勝而得無量報，並提醒此苦行以證量與報恩為前提，不可盲目效法。","p":["喜見菩薩聞《法華經》得現一切色身三昧","以三昧力雨華香供佛，海此岸栴檀極珍貴","服香塗油燃身，光照八十億恆河沙世界","施主、福田、施物三者皆勝，得無量報","須先衡量自身證量，勿妄效苦行"],"k":["法供養","燃身供佛","現一切色身三昧","一切眾生喜見菩薩","苦行"]},"7288-a29_030":{"s":"本集講喜見菩薩命終後於淨德王家結跏趺坐化生，無胎昧即說偈向父王說明來歷，並於法供養後不求自得解一切眾生語言陀羅尼。講者說明莊嚴菩提心要靠如法修行與報恩供養，而非觀想月輪種子字；又講見佛先讚佛再稟身分的禮儀，及日月淨明德佛告知涅槃時至、令安施床座。","p":["喜見菩薩化生王家，無胎昧即說偈","法供養後不求自得解一切眾生語言陀羅尼","莊嚴菩提心靠如法修行，非觀想月輪","見佛先讚佛再稟身分，是菩薩禮儀","佛示涅槃須安施床座，安詳示寂"],"k":["解一切眾生語言陀羅尼","法供養","菩提心","胎昧","般涅槃"]},"7273-a29_031":{"s":"本集講日月淨明德佛臨入涅槃，將佛法與成佛之道、七寶世界及給侍諸天付囑喜見菩薩與諸菩薩大弟子，並付囑舍利廣起千塔。講者說明付囑對象須具能力與願力；碎身舍利為讓眾生種福田（多寶如來例外），駁舍利為結石之說，強調供養法舍利功德更勝；並述師子奮迅三昧入涅槃及釋迦如來北首之義。","p":["佛法須付囑有能力、願力的菩薩大弟子","付囑含三賢十地成佛之道，不只明心","碎身舍利為眾生種福田，多寶如來例外","駁舍利為吃豆腐結石之說；法舍利功德更勝","諸佛以師子奮迅三昧入涅槃，北首表法北傳"],"k":["付囑","舍利","法舍利","師子奮迅三昧","福田","多寶如來"]},"7286-a29_032":{"s":"本集延續北首之義，講大乘法北傳中國：達摩以《楞伽經》印證宗門所悟即第八識如來藏，開悟唯有頓悟、道不屬修，並以爬樹嚐果為喻；玄奘譯經使禪門得聖教依據而一花五葉。接著講喜見菩薩起八萬四千寶塔、燃臂七萬二千歲供舍利並立誓雙臂還復，勉勵以住持正法、紹隆佛種報恩為真法供養。","p":["達摩以《楞伽經》印證，所悟為第八識","開悟唯頓悟，以爬樹嚐果喻修與悟","玄奘譯經使禪宗得聖教依據，一花五葉","喜見菩薩起八萬四千塔，燃臂七萬二千歲","住持正法、紹隆佛種才是真法供養"],"k":["頓悟","如來藏","燃臂供佛","法供養","玄奘","禪宗"]},"7280-a29_033":{"s":"本集講喜見菩薩以海此岸栴檀荼毘佛身、收舍利起八萬四千塔，並對照釋迦如來舍利由八王均分的故事。喜見菩薩令大眾一心隨喜後燃百福莊嚴臂七萬二千歲，使無量聲聞迴心證現一切色身三昧。講者強調凡夫不可燃指效法，批評濫慈悲與包容相似像法，並評論達賴喇嘛鼓動自焚。","p":["釋迦舍利由婆羅門調停八王均分","喜見菩薩令大眾一心念，得隨喜功德","燃臂度無量聲聞迴心，證現一切色身三昧","凡夫燃指發誓不能還復，恐謗經成罪","慈悲須有智慧，不可容許相似像法"],"k":["燃臂供佛","燃指供佛","現一切色身三昧","迴小向大","舍利","相似像法"]},"7271-a29_034":{"s":"本集說明燃臂供佛的理與事：從如來藏立場燒亦非燒，有事有理功德遠勝；喜見菩薩已過九地、住淨土、具願力與多劫苦行功德，故雙臂能還復，人間凡夫不應燃指，菩薩身根應莊嚴。經文揭示喜見菩薩即今藥王菩薩、捨身無量；講者並述平實導師定中見覺囊派往事，說明如來藏記錄往世經歷。","p":["從如來藏看燒臂非燒，有事有理功德大","證量、願力、環境不同，凡夫勿效燃指","菩薩身根應莊嚴，十指不全令眾生生惱","一切眾生喜見菩薩即今藥王菩薩","定中見覺囊派往事，如來藏記錄往世"],"k":["燃臂供佛","藥王菩薩","如來藏","福德淳厚","捨身布施","覺囊派"]},"7284-a29_035":{"s":"本集講經文的功德較量：燃一指供佛塔勝於以國城妻子及三千大千世界珍寶供養；以七寶滿三千大千世界供養四聖，不如受持《法華經》乃至一四句偈。講者引導觀眾自行較量，指出受持此經是第一義智慧並伴隨大福德，菩薩應護身為道器；並解「海為第一」喻，說大乘諸經皆依如來藏而說，批評印順的判教。","p":["燃一指供佛塔勝於以三千大千世界供養","受持《法華經》乃至一四句偈福德最多","受持此經屬第一義智慧，非僅世間福德","菩薩戒不故入難處，色身是道器","此經如大海，大乘諸經皆依如來藏說"],"k":["功德較量","受持法華經","四句偈","如來藏","燃指供佛","性空唯名"]},"7277-a29_036":{"s":"本集解說須彌山、月天子、日天子三喻：《法華經》如須彌山於諸經最為其上，如月於諸經最為照明（證此經方能讀懂大乘經），如日能破一切不善之闇。講者分析欲界的不善之闇，包括一神教上帝的瞋心與行善只求生天享樂，說明證如來藏現觀業種不失可破之；並論色界天人與大梵天王信徒誤以永生為不死的邪見。","p":["須彌山喻：此經於諸經最為其上","月天子喻：證此經才有讀經的照明智慧","日天子喻：此經能破一切不善之闇","行善只求生天享樂，屬善法之闇","色界天人自認永生不死，是其不善之闇"],"k":["不善之闇","須彌山","照明","欲界","色界","大梵天王"]},"7287-a29_037":{"s":"本集續說三界的不善之闇：欲界求生天享福、色界執永生、四禪無想天誤認無想定為涅槃、無色界四空定誤以為出三界，皆屬不善之闇。進而說俱解脫阿羅漢不知名色緣識、緣覺不知無餘涅槃中境界，二乘雖非凡仍名為愚；七住明心菩薩即能知無餘涅槃境界，須依如來藏才能破除。","p":["欲界行善求生天享福為不善之闇","無想天誤為無餘涅槃，壽盡仍下墮","四空定仍有壽命，並未出三界","阿羅漢不知名色緣識，須學十因緣","緣覺不知涅槃中境界，七住菩薩能知"],"k":["不善之闇","無想天","四空定","十因緣","無餘涅槃","上漏為患"]},"7293-a29_038":{"s":"本集講大乘的不善之闇：七住明心仍不知十住如幻觀與眼見佛性，乃至妙覺不知佛地，皆依「此經」如來藏次第滅除，「此經」非指經卷。接著解轉輪聖王喻，述四種輪王與七寶，說明此經於眾經最為其尊：外道經典與三乘經典的撰寫、結集都依如來藏，二乘、般若、唯識諸經皆圍繞如來藏說，未悟研讀唯識無益。","p":["明心後仍有不善之闇，至成佛方滅盡","「此經」指如來藏，非課誦的經卷","四種轉輪聖王與七寶，喻此經最尊","外道與三乘經典皆依如來藏才能寫出","唯識經悟後方懂，不識本心學法無益"],"k":["不善之闇","轉輪聖王","如來藏","阿賴耶識","般若","唯識"]},"7298-a29_039":{"s":"本集說明此經為諸經中王：唯識諸經若抽離如來藏則不知所云，二乘若無本識則成無因唯緣的外道論。講者解帝釋為三十三天王之喻（並說韋陀菩薩非帝釋化身）與大梵天王喻，說此經是一切學、無學及發菩薩心者之父；辨析學與無學的層次，並指出初果須信有涅槃本際才能斷我見，五千退席者即不信此經。","p":["虛妄唯識門須依真實唯識門成立","帝釋為三十三天王，喻此經為諸經中王","韋陀菩薩為賢劫最後一佛，非帝釋化身","學與無學有層次，菩薩轉依如來藏本無學","初果須信涅槃有本際，才敢斷我見"],"k":["諸經中王","學無學","帝釋","初果","斷我見","如來藏"]},"7301-a29_040":{"s":"本集續說此經為三乘有學、無學之父：五千退席聲聞怕落斷滅而不能斷我見，初果至四果皆因知無餘涅槃有本際而證果。緣覺須懂十因緣與十二因緣的關係及「齊識而還，不能過彼」，最大無明即不懂此義；名色從識生，此識即如來藏。大乘見道證真如即證此經，故也是菩薩與發菩薩心者之父。","p":["五千退席聲聞怕斷滅，不能證初果","初果至四果皆依涅槃本際而證","「齊識而還，不能過彼」為因緣觀關鍵","十二因緣不是十因緣的增說","大乘見道證真如，即實證此經"],"k":["十因緣","齊識而還","聲聞四果","緣覺","證真如","名色"]},"7305-a29_041":{"s":"本集解「凡夫中四果、辟支佛為第一」之喻：講者認為一神教天主乃至大梵天王皆不知名色虛妄，初果人即勝於他們；此經於如來、菩薩、聲聞所說諸經法中最為第一，聲聞若無如來藏則不願斷盡我執。並說受持此經者於眾生中第一，以三歸依實義說明歸依法身佛與法身如來藏，證悟者為勝義僧而不應起慢。","p":["講者評一神教天主屬鬼神類，不知名色虛妄","初果人為一切凡夫中第一","聲聞無如來藏則不願斷盡我執","正覺法義始終依如來藏而說","證法身如來藏為勝義僧，是真歸依僧"],"k":["最為第一","三歸依","勝義僧","法身","初果","如來藏"]},"7291-a29_042":{"s":"本集解「聲聞辟支佛中菩薩第一」與「如佛為諸法王，此經諸經中王」兩喻：皇帝天子層次遠低於聲聞，二、三轉法輪皆說如來藏，《法華經》總其成。講者批評密宗四大法王為大凡夫，說佛為法王不涉政治，述阿闍世王見佛故事；並論證意根與六識皆不能住胎造身，引《阿含經》識入母胎問答，證入胎識即第八識。","p":["天子僅為忉利天主之子，不入聖流","菩薩為三乘中第一，此經諸經法第一","究竟通達一切法方為法王，佛不涉政治","阿闍世王疑懼見佛，終得無根信","意根不能住胎，入胎識即第八識"],"k":["法王","入胎識","意根","三轉法輪","密宗","阿闍世王"]},"7295-a29_043":{"s":"本集說明此經不只是三乘經王，也是外道經論之王，因一切經論都由如來藏所生的名色造作；藥王菩薩之名來自布施治生死病的妙法。接著引「此經能救一切眾生」一段經文，解「離諸苦惱」：此經指如來藏而非經卷，轉依後世間計較減少而離苦惱；又說證此經能「充滿其願」，以未來世受生自在為例。","p":["此經也是外道經論之王","藥王之名來自布施治生死病的妙法","此經是如來藏，非拜經求保佑","轉依如來藏後減少計較，離諸苦惱","證此經未來受生自在，能充滿其願"],"k":["諸經中王","藥王菩薩","離諸苦惱","轉依","充滿其願","如來藏"]},"7299-a29_044":{"s":"本集解「如清涼池」「如寒者得火」「如裸者得衣」三喻：學佛多年不得其門如渴乏者，證得如來藏如遇清涼池；學佛退心如心寒，證悟得智慧之火，並警示勿近密宗唐卡的邪火；學佛多年未悟者羞於被問，證悟後如裸者得衣，並從如來藏本無慚愧說明真慚愧。","p":["清涼池喻：證如來藏解學佛的渴乏","寒者得火：證悟得智慧之火，滅除無明","勿近密宗邪火，免燒壞佛菩提種","裸者得衣：證悟後不再羞於被問開悟","如來藏本無慚愧，懂此方是真慚愧"],"k":["清涼池","寒者得火","裸者得衣","證悟","如來藏","抉擇分"]},"7304-a29_045":{"s":"本集重述「此經能救一切眾生」經文及九種譬喻，說明此經即第八識如來藏，轉依後煩惱漸減，「還是舊時人，不是舊行履」。講者說般若智慧是意識證悟如來藏後所得，如來藏本身無智亦無得；證悟是一念相應慧，須具定慧福德、除性障並轉依成功才是七住不退；並提醒擇真善知識，勿以定為禪。","p":["此經指第八識如來藏，非經卷","般若智慧屬意識所得，如來藏無智亦無得","證悟為一念相應慧，三地滿心前有胎昧","真悟須轉依，有解脫與智慧正受","勿以定為禪，離世覓菩提如求兔角"],"k":["如來藏","轉依","一念相應慧","根本無分別智","胎昧","善知識"]},"7307-a29_046":{"s":"本集解「如商人得主」：以古天竺商隊須有商主帶領為喻，說明修學大乘須親近真善知識，引《華嚴經》善知識八難及《放光般若經》，強調要隨學法與次法。講者批評以觀想中脈明點或一念不生冒充如來藏者為邪主、愚迷之主，並指應成派與自續派中觀源於六識論凡夫論師，真正中觀依八識論。","p":["商主喻：修學大乘須依真善知識","《華嚴經》所說值遇善知識的八難","須隨善知識修學法與次法","觀想明點、一念不生並非如來藏","中觀依八識論；應成、自續屬六識論"],"k":["善知識","商人得主","中觀","八識論","次法","密宗"]},"7309-a29_047":{"s":"本集解「如子得母」「如渡得船」「如病得醫」「如闇得燈」「如貧得寶」五喻：如來藏是《阿含經》所說諸法本母，離念靈知非真如。菩薩證如來藏不捨五蘊即在彼岸，阿羅漢能入涅槃而未證涅槃；諸佛以真如為藥、六度為藥引治生死病；證此經如一燈破千年闇室，法身慧命全現如貧得寶。","p":["如子得母：如來藏是諸法本母","離念靈知非真如，勿認錯母親","如渡得船：菩薩不捨五蘊即在彼岸","如病得醫：真如為藥，六度為藥引","如闇得燈、如貧得寶皆指證此經"],"k":["諸法本母","如渡得船","真如","六度波羅蜜","離念靈知","次法"]},"7319-a29_048":{"s":"本集解「如民得王」：先說藥王菩薩之名源於布施治生死病的此經，再述各類王與轉輪聖王，引《方廣大莊嚴經》說明唯能轉法輪者為法王。講者指出諸法之王即如來藏，能生一切法而於諸法自在，意識夜斷不能為王；證悟時是我見祂而祂不見六塵，開悟只是入門仍須進修，並提醒勿誤信喇嘛法王。","p":["藥王菩薩布施的治生死藥即是此經","轉輪聖王以十善治化，佛轉法輪為法王","如來藏能生諸法、於法自在，是真法王","證悟時我見祂，祂不見六塵","開悟只是入門，勿信自稱法王的喇嘛"],"k":["如民得王","法王","如來藏","轉法輪","轉輪聖王","諸法本母"]},"7323-a29_049":{"s":"本集依〈藥王菩薩本事品〉（講義第二十一輯178頁起）講解「如賈客得海、如炬除闇」。以商賈得海喻證得此經如來藏即能遨遊自身本具的法性大海，以火炬除千年暗室喻實證如來藏能照破無始無明；並批評緣起性空的斷見與意識常住的常見，強調證此經即是見道、得慧眼而能讀懂經典。","p":["法性大海本在自身，入海鑰匙是此經妙法蓮花","批評斷見與意識常住常見，喻為「黑暗海」","聲聞智慧如螢火，大乘實相智慧如火炬","證此經即真見道，得慧眼能轉經、宗教不二","修學前須理智分辨，唯一入手是證如來藏"],"k":["如來藏","法性大海","無始無明","見道","藥王菩薩本事品","常見與斷見"]},"7313-a29_050":{"s":"本集講解〈藥王菩薩本事品〉「能令眾生離一切苦一切病痛，能解一切生死之縛」。指出依文解義者讀經再虔誠也不解其義；此經如來藏離六塵見聞覺知、不受苦痛，轉依祂即無苦無病。並說明法智忍、法智、類智忍、類智的次第，以及證此經自然斷我見、解開生死繫縛，悟後須能安忍才不退轉。","p":["依文解義誤解經文，問題在缺乏正知見","如來藏離見聞覺知，不受苦與病痛","禪門道「不審」：真我從不審察六塵","法智忍、法智、類智忍、類智四種智慧","證此經即斷我見，漸解分段與變易生死縛"],"k":["如來藏","離苦","法智忍","類智","斷我見","生死繫縛"]},"7315-a29_051":{"s":"本集講解〈藥王菩薩本事品〉「若自書，若使人書」功德不可籌量（講義第二十一輯215頁起）。說明「自書」不是抄經，而是禪師所說的「轉經」、日常中運轉此經如來藏；以麻谷公案警示落入五陰、自以為悟的過失。「使人書」更難，同修會分工合作以擴大功德；最後說明事相上抄經並以華香、瓔珞、幡蓋等供養亦得無量功德。","p":["真懂書寫者日常起居皆在書寫此經","麻谷公案：落五陰是風力所轉，終成敗壞","自書即轉經，捧經課誦反被經轉","使人書極難，同修會分工共同度眾","事相抄經並以華香燈等供養亦功德無量"],"k":["書寫此經","轉經","如來藏","功德","供養","禪宗公案"]},"7311-a29_052":{"s":"本集續講〈藥王菩薩本事品〉（講義第二十一輯224頁起），說明聞此品者功德無量、女人受持不復受女身，並引《六度集經》賣膏油女轉成男身得授記的故事。解釋宿王華名義，指出藥王菩薩歷劫修苦行而得「現一切色身三昧」：離放逸行則易與此經相應，先得理上的此三昧，再進至八地於相於土自在的事上境界。","p":["供養經卷引人探究，令此經妙法弘揚","此經即第八識妙法蓮花，為圓教之法","《六度集經》賣膏油女轉男身得授記","苦行易與此經相應，放逸行則心向外散","理上現一切色身三昧：觀往世色身皆由此經生"],"k":["現一切色身三昧","藥王菩薩本事品","苦行","放逸行","宿王華菩薩","轉女成男"]},"7321-a29_053":{"s":"本集解說〈藥王菩薩本事品〉「盡是女身，後不復受」的真義：受持即證得理上的現一切色身三昧，從如來藏看一切有情，所見無非如來藏，便無女身可見。引《佛說未曾有正法經》文殊隱身、摩伽陀王不見一法為證。再講末後五百歲女人如說修行往生極樂，生蓮華寶座上，超越貪瞋癡所對應的三界境界。","p":["區分「女人」與「女身」，不可依文解義","受持即證理上現一切色身三昧","文殊隱身：真如境界不見自他、無能所施","末法女人如說修行，往生極樂上品上生","得無生法忍超越欲界、色界、無色界"],"k":["如來藏","受持","女身","極樂世界","無生法忍","上品上生"]},"7325-a29_054":{"s":"本集講解〈藥王菩薩本事品〉「得是忍已，眼根清淨」，見七百萬二千億那由他恒河沙諸佛。說明往生者斷隨煩惱、得三地滿心的菩薩神通，非想定之樂如地獄苦；引舍利弗與目連比神足的故事，說明神通隨智慧自在。並以七覺支、七聖財解釋「七百萬」的理上含義，說明猗覺支即初禪，以及依阿彌陀佛願力上品上生的道理。","p":["得菩薩神通表示已滿足三地心","非想非非想定之樂如地獄苦，屬愚癡","舍利弗衣帶故事：心神足隨智慧自在","眼根清淨隨欲所見，見無量諸佛","七覺支為根基，猗覺支以初禪為驗證"],"k":["眼根清淨","菩薩神通","七覺支","無生法忍","極樂世界","藥王菩薩本事品"]},"7317-a29_055":{"s":"本集講解〈藥王菩薩本事品〉諸佛遙讚「受持讀誦思惟是經，為他人說」福德無量，「火不能焚，水不能漂」，千佛共說不能盡。說明受持、讀誦、思惟的次第，以及如來藏能仁寂靜的境界；再解釋「破諸魔賊，壞生死軍」：四魔、十八界為法賊、無記異熟種子為「諸餘怨敵」，並引補寺壁孔延命的故事說明福田。","p":["受持、讀誦、思惟、為人說有其次第","如來藏能仁寂靜，永不起惡心、無六塵","功德存於如來藏，瞋火愛水不能損","四魔與十八界法賊，破之須超越五陰","十地滿心受職，百千諸佛共守護"],"k":["功德","受持讀誦","四魔","十八界","如來藏","藥王菩薩本事品"]},"7327-a29_056":{"s":"本集講解〈藥王菩薩本事品〉末段：宿王華名義、口出青蓮華香等十地功德，世尊囑咐宿王華在南閻浮提流傳此經、以神通力守護。強調佛法是心地法門，從凡夫到資糧位都要修心、汰換染汙種子；並說明《央掘魔羅經》被編入阿含部的原因、窺基破斥圓測，以及八萬四千菩薩得解一切眾生語言陀羅尼、多寶如來讚歎。","p":["佛法是心地法門，各階位皆須修心轉依","宿王華表如來藏本住自在，久修此法","囑咐流傳此經，勿令破法者得便","《央掘魔羅經》說如來藏而入阿含部","擊法鼓破邪顯正，舉窺基駁圓測為例"],"k":["宿王華菩薩","心地法門","如來藏","央掘魔羅經","破邪顯正","轉依"]},"7340-a29_057":{"s":"本集說明此經如來藏與無餘涅槃的關係。二乘人未證真如，阿羅漢滅盡十八界後並非斷滅，因為有阿羅漢滅不了的本有法；無餘涅槃是依第八識獨存的寂滅境界而施設。引阿含「滅諦不離如」、「如來所依識」、「齊識而還」等說明真如即第八識，並批評南傳《尼柯耶》多一字的理解，談如來藏有無量名。","p":["意識與意根皆生滅，只是工具非真我","阿羅漢滅十八界，焰摩迦比丘斷滅見有誤","無餘涅槃依本有法第八識而施設","滅諦不離如，「如來所依識」即第八識","第八識自流注，終出無餘涅槃迴小向大"],"k":["無餘涅槃","如來藏","第八識","真如","齊識而還","二乘"]},"7333-a29_058":{"s":"本集說明此經如來藏即第八識，成佛時改名無垢識。勸人對成佛具信心，並解釋意根為何稱第七識、第八識為何稱第八；說明第八識含藏種子、隨緣流注、與名色七識互緣，出生器世間與五陰，果報分毫不差。另說明依第八識施設四種涅槃，以及阿賴耶識、異熟識之名與分段、變易生死的關係。","p":["如來藏、第八識、真如是同一心","意根有了別性，故稱第七識","第八識含藏種子，隨順緣起出生萬法","第八識以大種性自性出生器世間","阿賴耶與異熟識之名，分段與變易生死"],"k":["第八識","如來藏","無垢識","意根","種子","異熟識"]},"7344-a29_059":{"s":"本集闡述「此經」如來藏的體性：如來藏的功德從不失去，三歸依實為自歸依。講者以「阿里不達」等俚語批評藏密雙身法及一神教。說明如來藏是萬法根本因與所知依，性如金剛不可合併分割，無為法性而具有為功德，是真實我，到佛地成為常樂我淨；並勸人相信小低頭皆已成佛道。","p":["如來藏功德常在，不因輪迴惡法改易","三歸依即自歸依自身如來、法藏、僧寶","以俚語諧音批評藏密雙身法與一神教","如來藏性如金剛，不能合併也不能分割","如來藏無為而具有為功德，是真實我"],"k":["如來藏","所知依","真實我","三自歸","藏密批判","因果"]},"7330-a29_060":{"s":"本集依《成唯識論》卷三「若不摧邪，難以顯正」，說明正法、像法、末法三時的弘法現象，月光菩薩與《無量壽經》住世百年，以及比丘尼僧團使正法減為五百年、部派分裂。再界定常見外道（以意識為常）、斷見外道（否定第八識），並具體批評四大山頭、自續與應成派中觀、宗喀巴、達賴喇嘛、印順等人。","p":["正法、像法、末法三時漸漸消滅","相似像法出世間後，正法則滅","女眾出家使正法由千年減為五百年","常見外道以離念靈知等意識為常住","批評宗喀巴、達賴、印順否定第八識"],"k":["摧邪顯正","成唯識論","常見外道","斷見外道","末法","六識論"]},"7337-a29_061":{"s":"本集續講「若不摧邪，難以顯正」，以玄奘菩薩生平說明《成唯識論》的由來：幼年知禮、十三歲出家發願、明心見性、西行取經、戒賢論師忍病等待、曲女城無遮大會立「真唯識量」、回唐譯經七十四部。並說明窺基「有義」建議與《述記》的得失，勉勵菩薩效法摧邪顯正。","p":["玄奘十三歲出家發願「遠紹如來，近光遺法」","發願分通願與別願，成佛須發大願","戒賢論師忍病等待玄奘，業報須坦然承受","曲女城無遮大會立「真唯識量」","窺基「有義」與《述記》未能彰顯破邪效果"],"k":["玄奘菩薩","成唯識論","摧邪顯正","真唯識量","窺基","發願"]},"7342-a29_062":{"s":"本集講「唯一佛乘」上篇：世尊說五乘佛法，人天乘、二乘皆從唯一佛乘析出，引《勝鬘經》證二乘依大乘而增長。依阿含說明次第說法：施論、戒論、生天之論，再說四聖諦。並論證二乘無餘涅槃不是斷滅空，而有本際、如如、真實我；緣覺以十因緣「齊識而還」確認此識，故緣覺勝於聲聞。","p":["五乘佛法中，四乘是唯一佛乘的局部","世尊次第說法：施論、戒論、生天之論","聲聞依四聖諦斷三縛結至五上分結","無餘涅槃非斷滅，有本際如如獨存","十因緣「齊識而還」與十二因緣之識不同"],"k":["唯一佛乘","五乘佛法","四聖諦","無餘涅槃","十因緣","次法"]},"7335-a29_063":{"s":"本集講「唯一佛乘」下篇：二乘法只是世尊在唯一佛乘中化現的化城，以拈花教外別傳令阿羅漢證悟般若，再轉第二、第三轉法輪，最終導歸一佛乘，並引化城喻經文。批評印順、達賴對三轉法輪的主張；接著進入〈妙音菩薩品〉經文語譯，重點說明佛白毫相的殊勝功德。","p":["二乘菩提是唯一佛乘中化現的化城","拈花教外別傳，令阿羅漢證悟般若","三轉法輪：阿含、般若、唯識種智","化城喻：止息後滅化城，導向寶所","白毫相功德須累積無量功德方成"],"k":["唯一佛乘","化城喻","三轉法輪","妙音菩薩品","白毫相","般若"]},"7332-a29_064":{"s":"本集依講義第二十二輯解說〈妙音菩薩品〉的「無緣三昧」與「智印三昧」。先區分智慧三昧與禪定三昧；無緣三昧在三賢位指現觀如來藏於六塵無所緣，初地後轉依真如而不貪三界法，至妙覺圓滿。智印三昧以實相般若印定世間、出世間、世出世間法，須依八識論並親證三自性。最後說明解一切眾生語言三昧與四無礙辯。","p":["三昧分智慧心得決定與禪定兩類","三賢位無緣三昧：如來藏於六塵無所緣","初地以上轉依真如，不貪三界諸法","智印三昧印定世間、出世間、世出世間法","解一切眾生語言三昧與四無礙辯、譯經"],"k":["無緣三昧","智印三昧","妙音菩薩品","三自性","八識論","解一切眾生語言三昧"]},"7355-a29_065":{"s":"本集解說「集一切功德三昧」與「清淨三昧」。依《瑜伽師地論》說明功德與過失，功為自受用、德為他受用；一切功德種子由不生滅的第八識種子識集藏，如來藏有出生名色與共生器世間兩大功德，引《大悲經》說明世界非梵天所造。清淨三昧是現觀如來藏本來自性清淨，並依初地、七地、妙覺分層次。","p":["修行應修集功德、遠離雜染過失","功是自受用，德是他受用","第八識種子識集藏一切功德種子","如來藏出生名色並共生器世間","清淨三昧：現觀如來藏本來自性清淨"],"k":["集一切功德三昧","清淨三昧","種子識","如來藏","功德","器世間"]},"7350-a29_066":{"s":"本集解說「慧炬三昧」：實證此經妙法蓮花即得第一分慧炬三昧，「千年暗室一燈能破」，七住不退可得佛授記。強調智慧火須不受境界風動搖，引經說明觀察瞋心生滅而安忍。並說明菩薩慧通達如所有性、菩薩智通達盡所有性，三地、四地、五地的智慧增上，以及惡見是染慧、世智辯聰屬八難。","p":["證此經得第一分慧炬三昧，照破無明","七住位不退，佛即可為之授記","智慧火須穩定，安忍不隨境界風動","菩薩慧通如所有性，菩薩智通盡所有性","惡見屬染慧，須善知識正確教導"],"k":["慧炬三昧","般若智慧","授記","安忍","惡見","菩薩十地"]},"7353-a29_067":{"s":"本集解說「莊嚴王三昧」與「淨光明三昧」。說明福德莊嚴與智慧莊嚴互攝，六度即菩薩六種印，菩薩性有大悲、大信、大忍、大行四相；菩薩真正的莊嚴是依此經實證而來的智慧，故稱「王」。淨光明三昧指大乘實證並轉依成功後智慧的顯現，非二乘可及；並引《楞嚴經》「性淨明體」，強調心性是道業關鍵。","p":["福德莊嚴與智慧莊嚴互攝，皆由六度成就","菩薩性四相：大悲、大信、大忍、大行","莊嚴王三昧須依此經實證而得","淨光明三昧須大乘實證並轉依成功","如來藏是性淨明體，心性為道業關鍵"],"k":["莊嚴王三昧","淨光明三昧","福德莊嚴","智慧莊嚴","菩薩性","轉依"]},"7346-a29_068":{"s":"本集進入〈妙音菩薩品〉的「淨藏三昧」與「不共三昧」。淨藏指此經如來藏本來清淨、含藏一切清淨法藏，聲聞、緣覺乃至大乘見道修道的清淨法藏皆依之成立，七住得初分、八地以上為大三昧。不共三昧從布施禪定共外道講起，說明聲聞菩提不共，須先具足施論、戒論、生天之論，並批評誤以離念靈知為涅槃。","p":["淨藏：本來清淨的此經含藏一切清淨法藏","二乘清淨法藏亦須依如來藏方能成立","七住得初分淨藏三昧，八地起為大三昧","布施、禪定為共外道法，佛菩提為不共","次法不彰致誤以離念靈知為無餘涅槃"],"k":["淨藏三昧","不共三昧","妙音菩薩品","如來藏","次法","聲聞菩提"]},"7360-a29_069":{"s":"本集續講〈妙音菩薩品〉所列三昧：以聲聞、緣覺到佛菩提的次第說明「不共三昧」，上位所證不共下位；再說「日旋三昧」是悟後智慧如日周旋、不吝法而永續攝受眾生。並解說淨華宿王智佛囑妙音菩薩「莫輕彼國，生下劣想」，顯示佛法遍十方而不侷限於人間。","p":["佛法次第：聲聞、緣覺、佛菩提層層不共","七住證真如、十住見佛性，上位不共下位","日旋三昧：悟後說法如日周旋，不應吝法","三昧是心得決定，非僅指禪定境界","淨華宿王智佛囑妙音菩薩莫輕娑婆國土"],"k":["不共三昧","日旋三昧","妙音菩薩","如來藏","攝受佛土","心得決定"]},"7363-a29_070":{"s":"本集說明「汝莫輕彼國」實為告誡妙音菩薩的隨行眾，並談大菩薩各有法眷屬，無私心即非結黨。接著講諸佛淨土各有事上、理上四土，指娑婆的方便有餘土因五蓋與定障而難恢復，強調斷我見須有未到地定；末說十方世界與劫數之廣，非凡夫所能思議。","p":["「莫輕彼國」實為告誡隨行菩薩","法眷屬源自宿世因緣，無私心即非結黨","諸佛淨土各有事上、理上四土","五蓋與定障障礙入地及斷我見證初果","十方世界與時劫之廣，唯佛能知"],"k":["四土","法眷屬","定障","五蓋","未到地定","十方世界"]},"7352-a29_071":{"s":"本集舉例說明《法華經》背後涵攝他經少說的道理：三賢與諸地各階現觀、聲聞戒嚴而不開緣與菩薩戒多開緣的原因、謗三寶及謗菩薩藏不開緣、佛地四智與三界關聯等。指出《法華經》把一代時教收攝回歸「此經」如來藏，故稱圓教、「一圓一切圓」。","p":["三賢位與諸地各有應證的現觀","聲聞戒為出三界而嚴，菩薩戒為攝眾生多開緣","謗三寶、謗菩薩藏原則上不開緣","聲聞戒為別解脫戒，出家菩薩以菩薩戒為主","法華收攝一代時教歸如來藏，稱為圓教"],"k":["圓教","菩薩戒","聲聞戒","開緣","如來藏","一圓一切圓"]},"7357-a29_072":{"s":"本集講妙音菩薩稟白往詣娑婆「皆是如來之力、神通遊戲、功德智慧莊嚴」，並入三昧於靈鷲山化現八萬四千寶蓮華、文殊菩薩代眾請問一段。說明此「如來」指自心如來第八識，並以閻浮檀金莖喻通三界的般若智慧、白銀葉喻三昧、金剛鬚喻如來藏功德外護、甄叔迦寶臺喻佛菩提莊嚴。","p":["妙音菩薩言往娑婆皆如來之力，非溢美之詞","此「如來」指自心如來第八識如來藏","閻浮檀金為莖：般若實相智慧通三界","白銀為葉喻三昧，金剛為鬚喻如來藏外護","文殊菩薩明知而為大眾請問瑞相因緣"],"k":["妙音菩薩","自心如來","如來藏","三昧","寶蓮華","文殊菩薩"]},"7348-a29_073":{"s":"本集講世尊告文殊：妙音菩薩將率八萬四千菩薩來供養並聽《法華經》，及文殊問「種何善本、修何功德、行何三昧」一段。說明福德為三昧的前方便，須修「現一切色身三昧」，並舉喜見菩薩聞法華得此三昧；又說文殊早已成佛而為眾請問，藉妙音菩薩身量之大彰顯世尊威德與「此經」之重要。","p":["文殊問善本、功德、三昧三個面向","福德是智慧與三昧的基礎與前方便","現一切色身三昧，喜見菩薩聞法華而得","文殊早已成佛，倒駕慈航為眾請問","遠來聽受顯此經重要，學人應心量廣大"],"k":["現一切色身三昧","善本","福德","文殊菩薩","十無盡願","此經"]},"7367-a29_074":{"s":"本集講多寶如來召喚妙音菩薩，其與八萬四千菩薩所經諸國六種震動、雨七寶蓮華、天樂自鳴。說明釋迦如來讓多寶如來召喚以顯賓主互敬，依第八識的心念不受時空限制，所經之處亦成佛事；並解說青蓮華目、面如滿月、真金色身、威德熾盛與那羅延堅固之身，及菩薩在五濁世應忍眾生羞辱。","p":["釋迦如來讓多寶如來召喚妙音，顯賓主互敬","依第八識運作的心念不受時空限制","所經佛國震動、雨華、天樂，廣作佛事","妙音菩薩相好威德來自多劫修福","那羅延堅固之身喻四禪天主堅固身"],"k":["多寶如來","妙音菩薩","六種震動","威德","那羅延堅固之身","福德"]},"7365-a29_075":{"s":"本集續說菩薩威德力層級，指妙音菩薩為妙覺菩薩，而佛地境界非妙覺所能想像，故以好話讚佛並無過失。接著講妙音菩薩到靈鷲山代淨華宿王智佛問訊，說明他方菩薩問訊禮儀；解釋「少病」指世尊取人身故會病，批評以「眾生病故我病」為故意示病之說；「少惱」則舉因事制戒、飢荒托缽等事相煩擾。","p":["無生法忍、十地、最後身菩薩威德力層層倍增","佛地境界連妙覺菩薩亦不能想像","往謁他方佛須表明本師世尊之問訊","「眾生病故我病」指取人身故會病","少惱：因事制戒、飢荒托缽等事相煩擾"],"k":["問訊","妙覺菩薩","威德力","維摩詰經","因事制戒","五濁惡世"]},"7370-a29_076":{"s":"本集續解妙音菩薩的問訊：「起居輕利」、「安樂行」、「四大調和」關乎人身老化；「世事可忍」指佛以人身處世仍有俗務與天人求法；「眾生易度」以彌勒時代對比五濁惡世眾生難辨真假善知識。進而說明貪欲、瞋恚、愚癡代表三界，並以色界天無財色名食之貪為例。","p":["起居輕利、安樂行、四大調和皆因人身老化","四大不調是老化現象，與生病不同","世事可忍：佛以人身處世，俗務與求法者多","五濁世眾生難度，彌勒時代人壽長而易度","貪瞋癡代表三界，色界天已無五欲之貪"],"k":["問訊","貪瞋癡","三界","五濁惡世","色界天","四大調和"]},"7376-a29_077":{"s":"本集續講三界：色界無貪而有瞋，四空定離瞋仍有愚癡，愚癡主在錯認覺知心為真我。再說慢、慳、嫉妒障礙佛菩提道，以及不孝父母的常見；並依《阿含經》定義沙門須證初果或初果向，反駁外道以出家人犯戒批評佛教，引「有犯名菩薩，無犯名外道」。","p":["愚癡通三界，主在錯認見聞覺知心為我","慢源於我見等，障礙開悟","慳心重者難修六度與菩薩道","嫉妒為障道惡心所，不孝父母亦常見","依阿含定義，沙門須證初果或初果向"],"k":["沙門","沙門果","慳慢","嫉妒","愚癡","菩薩戒"]},"7373-a29_078":{"s":"本集說明敢當面向佛挑戰的外道多直爽，論後常斷我見、出家速證阿羅漢；只敢放話者多不可度。依阿含定義，修學正確解脫道者方屬沙門，修雙身法或持六識論否定如來藏者非真沙門。接著講「邪見」主要是把生滅的三界法當作常住，舉一神教永生、跳崖求生天、甘露丸等為例。","p":["當面挑戰佛的外道多直爽，常得法眼淨","廣義沙門：修學正確解脫道的出家人","修雙身法或持六識論者非真正沙門","對沙門應恭敬，對假沙門應辨正","邪見：以生滅三界法為常住不壞"],"k":["沙門","邪見","六識論","法眼淨","自性見","問訊"]},"7379-a29_079":{"s":"本集續解問訊「無不善心不」，以天界不善心漸少對比人間，指「心好就好」者仍對畜生不善，並說否定如來藏、毀謗證真如菩薩者必是凡夫而有不善心。再釋「攝五情」為收攝五根而不攝第六情，「降伏魔怨」至少須降伏五陰魔；末講先向法主稟告再見多寶如來的禮儀。","p":["天界不善心漸少，人間不善心普遍","證初果者不會否定如來藏，否定者為凡夫","攝五情：收攝五根，不攝第六情","降伏魔怨至少須在見地上降伏五陰魔","先向法主釋迦如來稟告，再見多寶如來"],"k":["不善心","攝五情","降伏魔怨","如來藏","多寶如來","問訊"]},"7369-a29_080":{"s":"本集從理上解說妙音菩薩：往娑婆「皆是如來之力」，事上如彌陀願力，理上是自心如來藏妙真如性所成。引《勝鬘經》空如來藏與不空如來藏、《般若經》五蘊實相即如來藏；並說妙音菩薩現種種身說《法華經》，理上即一切有情的如來藏隨業變現五陰、救護眾生。","p":["往娑婆皆如來之力：有事說與理說兩層","五蘊是空相，其本質為如來藏空性","《勝鬘經》說空如來藏與不空如來藏","妙音菩薩現種種身說法，理上即如來藏","如來藏依業種變現六道身而離我我所"],"k":["如來藏","妙音菩薩","空如來藏","不空如來藏","五蘊實相","妙真如性"]},"7378-a29_081":{"s":"本集回顧《法華經》以一佛乘分說三乘、火宅喻、化城喻與授記諸聲聞，說明多寶佛七寶塔依本願踊出為釋迦佛作證，並證諸佛涅槃只是示現、依十無盡願常住，批評釋印順「佛被理想化」之說。接著依《金光明經》講第二個七寶塔：摩訶薩埵王子捨身餵虎，其舍利塔應佛神力踊出。","p":["以一佛乘分說三乘，二乘涅槃如化城","多寶佛本願：有說法華處即踊塔作證","佛入涅槃只是示現，依十無盡願常住","批評釋印順視佛為理想化的說法","摩訶薩埵捨身餵虎，其舍利塔踊出"],"k":["七寶塔","多寶佛","一佛乘","捨身餵虎","十無盡願","本生"]},"7381-a29_082":{"s":"本集依《大方便佛報恩經》講第三個七寶塔：六師外道謗佛不孝，佛說忍辱太子捨眼髓救父王的本生，寶塔隨即踊出。並舉獼猴王救母、割肉奉親、睒摩迦孝養盲父母、救拔五百世之母迦旦遮羅等事蹟，勸菩薩慈忍孝順；並批評釋印順視本生為傳說，強調三乘修證建立在八識上。","p":["外道謗佛不孝，佛以忍辱太子本生回應","寶塔踊出顯佛孝養父母而成佛","割肉奉親、睒摩迦孝養盲父母等本生","救拔五百世之母迦旦遮羅證阿羅漢","批評釋印順以本生為傳說，應信受奉行"],"k":["七寶塔","孝養父母","本生經","知恩報恩","報恩經","八識"]},"7389-a29_083":{"s":"本集指出《法華經》以佛知見開示悟入，須有真如佛性方是佛知見，非僅二乘菩提；佛法有空性如來藏與空相蘊處界，菩薩不離生死而證涅槃。揭示妙音菩薩即每人身中說法的第八識如來藏，批評安慧將阿賴耶識列入識蘊、慧藏作《破大乘論》，並以「以聲聞形得度者」說明隨機現形。","p":["開示悟入佛知見須有真如佛性","空性如來藏與空相蘊處界同時存在","妙音菩薩即第八識如來藏","批評安慧將阿賴耶識歸入識蘊","菩薩出家是出三界家，發四宏誓願"],"k":["妙音菩薩","如來藏","佛知見","空性與空相","六識論","破邪顯正"]},"7393-a29_084":{"s":"本集說明佛教衰微源於誤以「一切法空」為佛法；《法華經》指出阿羅漢入無餘涅槃仍有本識常住，佛果常樂我淨。辨析空相與空性，強調緣起背後須有如來藏；批評六識論者稱「第七意識、第八意識」，引玄奘「愚者難分識與根」說明意根與意識之別，並將六識論溯源至部派與密宗中觀。","p":["學佛究竟是常樂我淨，非一切法空","無餘涅槃非斷滅空，仍有本識常住","緣起性空背後須有如來藏為根本因","第七、八識非意識細分，駁第八意識說","意根恆時現行，是意識所依"],"k":["一切法空","空性","八識論","六識論","意根","常樂我淨"]},"7383-a29_085":{"s":"本集依「以辟支佛形得度者」說明修因緣觀須先修十因緣，觀「齊識而還，不能過彼」，確認名色由第八識出生，十二因緣的還滅門才能成立。批評以緣起性空為核心、以物質或暗能量為萬法根源之說，引《大緣方便經》講十二因緣逆推順推，並批評帶此世意識「活著往生」之說。","p":["辟支佛須先修十因緣，再修十二因緣","齊識而還：名色由第八識出生","物質不能生心，三界唯心萬法唯識","無如來藏只是緣生法，非真緣起","學佛最大障礙是執意識為常住我"],"k":["十因緣","十二因緣","辟支佛","如來藏","緣起","我見"]},"7398-a29_086":{"s":"本集從舍利弗疑悔永盡、受記為華光佛談「無上法輪」：法義首尾相接無疏漏，即「此經」如來藏，法法相通。說明無上指諸佛境界、無下指阿鼻地獄，批評密宗雙身法自稱「無上瑜伽」實為無下；並主張西藏密宗是喇嘛教而非佛教，八識論才是佛教正法。","p":["舍利弗疑悔盡，受記成華光佛","無上法輪即此經如來藏，法法相通","無上是諸佛境界，無下是阿鼻地獄","批評密宗雙身法妄稱無上瑜伽","證如來藏與經相應才是無上瑜伽"],"k":["無上法輪","如來藏","無上瑜伽","授記","八識論","喇嘛教"]},"7396-a29_087":{"s":"本集進入〈妙音菩薩品〉華德菩薩問妙音菩薩住何三昧、佛答「現一切色身三昧」一段。為說明「一切色身」，先依《大寶積經》「眾生無量故」，從人類、傍生、細菌，到《長阿含經》的三千大千世界一佛剎、《華嚴經》華藏莊嚴世界海（娑婆在第十三層），說明世界與眾生無量無邊。","p":["華德菩薩問三昧，佛答現一切色身三昧","《大寶積經》：眾生無量故諸受無量","一佛剎即三千大千世界，有百億四天下","華藏世界海中，娑婆位於第十三層","十方世界海無量，眾生無量無邊"],"k":["現一切色身三昧","眾生無量","三千大千世界","華藏世界海","世界悉檀","華德菩薩"]},"7387-a29_088":{"s":"本集續說「現一切色身三昧」中「一切色」的範圍：人類男女、二根黃門、年齡膚色差異，傍生與水族形態，三界各道色身粗細大小，乃至共業所變的山河大地與植物。強調父母與飲食只是助緣，同卵雙胞胎亦有差異，色身皆由各自如來藏依業種變現；妙音菩薩證如來藏並多劫修學方能運用此三昧。","p":["人類色身有男女、二根、年齡膚色等差異","父母、飲食只是助緣，色身由如來藏變現","傍生、水族色身依果報而形態萬千","三界各道色身粗細大小各不相同","器世間山河與植物亦為共業所變現"],"k":["現一切色身三昧","如來藏","無量色","器世間","共業","異熟果報"]},"7400-a29_089":{"s":"本集續講〈妙音菩薩品〉現一切色身三昧，並引卷七觀世音菩薩應以何身得度即現何身之經文，說明其中有事有理。再依《大寶積經》「眾生無量故受無量」，說明諸受來自根塵所攝的色法，並以百法中十一色法、色聲香塵的繁複細分為例，指出五塵與法處所攝色皆是自心如來所變現的內相分，勉勵學人求證如來藏。","p":["觀世音現種種身說法，事上神通、理上自心示現","眾生諸受依根塵而有，仍屬一切色範圍","百法五位次第與阿含識緣生說並無矛盾","以色卡、電腦色階說明色塵可無限細分","六塵皆如來藏變現內相分，自心取自心"],"k":["現一切色身三昧","如來藏","五塵","百法明門","內相分","妙音菩薩品"]},"7391-a29_090":{"s":"本集探討眾生與如來藏是一是異，引《大般若經》卷四舍利子問行般若一段，解說「不見有菩薩」「不見行，不見不行」「色自性空，不由空故」及色即是空之義，並以依他起、遍計執、圓成實說明菩薩不滅五蘊而清淨遍計執。批評月稱、宗喀巴誤解空性，最後以《不增不減經》「眾生界即如來藏」回扣妙音菩薩品。","p":["行般若是悟後轉依如來藏的事修","五蘊色受想行識與色識受想行兩種次序","色自性空屬空性心，非滅色而得空","評月稱、宗喀巴把蘊處界空相當空性","眾生界即如來藏，二者非一非異"],"k":["色即是空","大般若經","如來藏","三自性","眾生空","五陰與五蘊"]},"7394-a29_091":{"s":"本集進入〈觀世音菩薩普門品〉「一心稱名，即時觀其音聲，皆得解脫」，說明須聽見自家實際理地的觀世音菩薩。接著介紹觀音傳入中國的歷史：最早見於支曜譯《成具光明定意經》稱明士、安玄《法鏡經》譯闚音，並述迦膩色伽王、馬鳴菩薩與大乘弘傳，駁斥避唐太宗諱改名說及學者稱觀音地位低之說。","p":["稱名得解脫指聽見自性觀世音菩薩","批評六識論者否定如來藏卻供奉觀音","最早漢譯稱觀音為明士、闚音","觀音名非因避李世民諱而省字","觀音弘化四類角色，本為正法明如來"],"k":["觀世音菩薩普門品","觀音由來","譯名","迦膩色伽王","如來藏","大乘非佛說批判"]},"7407-a29_092":{"s":"本集說明觀音在般若法會不發言是尊重法主，並引《無量壽經》說觀音、勢至為阿彌陀佛脅士且曾為釋迦佛弟子，駁斥觀音非真實存在之說。再解說一心稱名須證無觀無所不觀的真如心，四字已是四心；介紹竺法護譯「光世音」，以維摩詰經比對見聞覺知，並舉德光論師因慢心不禮彌勒而求法不得為誡。","p":["觀音不發言是尊重法主、佛教倫理","觀音勢至為西方脅士，真實存在","無生法忍須先證無生忍、真見道","一心稱名非專心唸四字，須證真心","德光論師慢心不禮彌勒，疑問終未解"],"k":["一心稱名","光世音","無生法忍","西方三聖","慢心","善知識"]},"7415-a29_093":{"s":"本集解說導師所說的一行三昧，即法界一相的真如如來藏，指出〈普門品〉以實相般若為基礎，觀音本質無形無相、應緣而現種種身。並從考古與文獻說明觀音信仰早已存在，駁斥觀音晚出、大乘與《法華經》晚出之說，介紹早期犍陀羅、秣菟羅造像中觀音與彌勒形像相同，以及蓮華手、西方三聖像。","p":["一行三昧即法界一相、真如如來藏","普門品以實相般若為基礎","觀音本質無相，隨眾生所需現身","文獻考古顯示觀音、淨土信仰甚早","早期觀音彌勒造像相同皆持水瓶"],"k":["一行三昧","實相般若","普門","觀音造像","大乘非佛說批判"]},"7411-a29_094":{"s":"本集介紹觀音信仰在印度與各地的演變：笈多王朝出現度母、馬頭觀音及密教四系觀音，東南亞、西藏以國王或達賴為觀音化身，講者視之為政治手段；中國則自唐起轉為女相。從如來藏義說一切有情皆可謂觀音化身。再述觀音譯名由闚音、光世音至觀世音、觀自在的演變，及玄奘稱舊譯訛謬，並鋪陳印度宗教史背景。","p":["笈多王朝後出現度母與密教觀音","國王自稱觀音化身屬政治統治手段","如來藏義下一切有情皆可稱觀音化身","闚音、光世音、觀世音皆指如來藏知一切","玄奘主觀自在，涉及梵語與印度宗教史"],"k":["觀音譯名","觀自在","密教觀音","如來藏","印度宗教史"]},"7401-a29_095":{"s":"本集解說〈普門品〉「臨當被害，刀杖段段壞」，導師開示應自害五陰、他害不如自害。引《大寶積經》〈神通證說品〉「勿得害我」「我必被害，為善被害」，辨明前者為不可違逆的真我如來藏，後者為五陰妄我。再以趙州「只為老僧好殺」、圜悟「護生須殺，雖殺無傷」說明殺我見是善害，禪師殺人刀背後即是活人劍。","p":["害死五陰我見，法身慧命才能活轉","勿得害我指如來藏，為善被害指五陰","世間殺人、自殺皆是殺不盡的惡害","二乘殺盡色身，菩薩殺我見留身修道","殺人刀背後是活人劍，擊大法鼓"],"k":["殺人刀活人劍","我見","五陰","大寶積經","善害","禪宗"]},"7405-a29_096":{"s":"本集以「內心起時，彼已害我」說明證見自身第八識觀世音菩薩即能否定五蘊我，故參禪是天下第一大善事，其證悟種子世世相隨。引圜悟「蠟人已冰，其功歷爾」，說禪宗頓超、擒賊先擒王、不斷煩惱證菩提，是實相般若之門與教外別傳；並批評學術界以緣起性空解般若，強調善知識是大因緣。","p":["內心起時即證見第八識觀世音","參禪證悟是三界最大的善事","禪宗單刀直入，擒賊先擒王","禪宗是實相般若之門、教外別傳","緣起性空只是意識概念，非法界實相"],"k":["參禪","明心","教外別傳","實相般若","善知識","如來藏"]},"7409-a29_097":{"s":"本集闡釋「不應造逆，勿得害我」之我即如來藏，信受大乘非佛說者法身慧命已死於非命。以永嘉《證道歌》「宗亦通、說亦通」及達摩付《楞伽》、五祖講《金剛經》印心，駁宗門與教下無關之說。並述大乘非佛說源自部派、日本學界與釋印順，指出否定第八識即否定三寶，六識論者亦無法實證解脫。","p":["勿得害我之我是如來藏，不可違逆","宗教俱通：宗門所悟即經教所說之心","大乘非佛說源自部派、日本及釋印順","三歸依一體，否定第八識即否定三寶","六識論者不肯否定意識，難斷我見"],"k":["如來藏","宗教俱通","大乘非佛說批判","三歸依","六識論"]},"7420-a29_098":{"s":"本集講轉依第八識的如如法性，解說〈普門品〉「若有罪、若無罪，杻械枷鎖檢繫其身」：有罪指欲界、無罪指色界，杻械為貪、枷鎖為瞋，稱觀世音名即轉依真如而解脫。引達摩三毒六賊、六祖無相懺悔偈說明實相懺悔，並解說怨賊為惡見之怨家與貪瞋癡慢疑之法賊，批評六識論學者與密宗喇嘛教。","p":["不可違逆如來藏的真實性與如如性","有罪指欲界、無罪指色界有情","杻械是貪、枷鎖是瞋，轉依真如即解脫","實相懺悔：向心中除罪緣","怨家是惡見五利使，法賊是貪瞋癡慢疑"],"k":["轉依","真如法性","實相懺悔","怨賊","五利使","普門品"]},"7413-a29_099":{"s":"本集解說〈普門品〉「三千大千國土滿中怨賊，商主將諸商人齎持重寶經過嶮路」：三千大千喻欲界人間，商主是意根，諸商人是前六識。重寶為五遍行、五別境、十一善心所與六無為法。逐一講解五遍行（並及見性）、五別境唯意識具足，以及信、慚、愧、無貪、無瞋、無癡、精進、輕安等善法。","p":["欲界人間怨賊最多，成佛路充滿嶮路","商主是作主的意根，非第八識","重寶：遍行、別境、善十一、六無為","修行須靠意識正知見引導意根","信為道源，輕安代表未到地定"],"k":["齎持重寶","心所法","意根","善十一","五遍行","普門品"]},"7403-a29_100":{"s":"本集續講善心所的不放逸、行捨、不害，以及六無為法，指出真如無為是見道第一關與未來關卡的金鑰匙。引《瓔珞經》舍利弗等悟後退轉之例強調善知識的攝受。並將修道險路分為瓶頸（如不肯布施、受戒）、岔路（錯悟大師所說）、危途（密宗）及學術研究，批評退轉者與釋印順依文解義。","p":["不放逸、行捨、不害三種善法重寶","真如無為是見道關卡的金鑰匙","悟後無善知識攝受易退轉","嶮路分瓶頸、岔路、危途","學術研究依文解義，無法實證"],"k":["嶮路","六無為","真如無為","善知識","退轉","布施"]},"7427-a29_101":{"s":"本集以《西遊記》比喻八識：意根為商主沙悟淨、意識為孫悟空、前五識為豬八戒、第八識為唐僧、五色根為龍馬，說明「其中一人作是唱言」是意識依正知見呼籲歸命觀世音。遇貪瞋怨賊時轉依無貪無瞋的如來藏即得解脫，入地後怨賊為習氣與塵沙惑；「俱發聲言」表八識和合，並強調要知恩才有交情。","p":["滿中怨賊指根本煩惱與隨煩惱","西遊記喻八識，意根作主依意識分別","唱言者是意識，呼籲歸命觀世音","遇貪瞋嶮路，轉依如來藏即解脫","知恩才有交情，親證是見道關卡"],"k":["一心歸命","八識","意根","怨賊","轉依","普門品"]},"7434-a29_102":{"s":"本集說證悟者應知恩感恩自家觀世音，批評退轉者另求第九識真如無為之誤。引並語譯「多於婬欲，常念恭敬便得離欲」、離瞋、離癡、求男求女及受持名號一段，說明理上一切有情皆有觀世音，事上觀音為正法明如來示現。並舉信眾漸離欲瞋、禪師「方外之交」接引、夢中指引與擲筊等事例。","p":["知恩不否定自家觀音，感恩則廣為人說","真如無為是第八識所顯法性，不離心體","理上一切有情皆有觀世音菩薩","事上觀音為正法明如來倒駕慈航","禪師方外之交與夢中指引等事例"],"k":["常念恭敬","離三毒","事理雙具","真如無為","觀世音信仰"]},"7421-a29_103":{"s":"本集強調十信具足是學佛首要，引《大寶積經》讚信之偈，並說不可以出家相判斷善知識（維摩詰、善財五十三參），引《證契大乘經》說持如來藏者為大導師，謗法者具根本、方便、成已三罪。事上舉求子事例及導師自述破參經過；理上解說觀世音觀五陰心聲、不捨眾生、從不生氣，故為摩訶薩。","p":["信為道元功德母，十信具足最重要","勿以出家與否判斷善知識","謗法具根本、方便、成已三罪","導師自述得菩薩指點而明心見性","理上觀世音觀心聲、不捨眾生為摩訶薩"],"k":["十信","觀世音菩薩摩訶薩","善知識","謗法","明心見性"]},"7423-a29_104":{"s":"本集從理上解說「多於婬欲，常念恭敬觀世音便得離欲」：自身觀世音無始離欲，轉依後可漸離欲乃至發初禪。借《華嚴經·入法界品》婆須蜜多菩薩說明：其「離欲實際清淨法門」中的「我」指如來藏；並解說若天見我我為天女、離欲得無著境界三昧、見我得歡喜三昧、與語得無礙妙音三昧，以禪師應答為例。","p":["自身觀世音無始離欲，轉依漸離欲","婆須蜜多以如幻智入方便門度眾","經中處處說的「我」指第八識如來藏","離欲得無著境界三昧，見我得歡喜三昧","與語得無礙妙音三昧，如禪師隨手拈答"],"k":["婆須蜜多","離欲","如來藏","華嚴經","三昧"]},"7431-a29_105":{"s":"本集續講婆須蜜多其餘方便門：執手得詣一切佛剎三昧、共宿得行解脫光明三昧、目視得寂靜諸行三昧、顰申得壞散外道三昧、觀察得一切佛境界光明三昧、擁抱得攝一切眾生三昧、親吻得諸功德密藏三昧，並舉雲門、趙州、雪峰古鏡公案說明。總結證知自己觀世音即離欲，常心念可離三毒；並開始從理上解釋求男。","p":["每種方便皆令人見到如來藏這個我","攝一切眾生三昧：知一切有情皆此我","諸功德密藏三昧，舉雪峰古鏡等公案","轉依本離三毒的觀世音，事修亦離三毒","理上的好男兒是雙具福德智慧的菩薩"],"k":["婆須蜜多","三昧","禪宗公案","離三毒","如來藏"]},"7438-a29_0106":{"s":"本集解說「福德智慧之男」與「端正有相之女」的理上意義：新學菩薩福慧不足，須修六度至六住滿心、證第八識入七住，才是第一層次的福德智慧之男，女眾亦然。端正有相之女指持戒端正、五蘊用以修道與心性調柔，引《華嚴·十地品》鍊金喻。並說悟前應禮拜供養觀音、福有事福理福，且須隱覆密意說法。","p":["新學菩薩福慧不足，不算好男兒","六度圓滿證第八識入七住為福德智慧之男","所依第八識有大丈夫相，女眾亦是","端正有相之女即持戒端正、心性調柔","福有事福與理福，須依正確法義"],"k":["福德智慧之男","端正有相之女","六度","七住位","心性調柔","福不唐捐"]},"7436-a29_107":{"s":"本集解說經文：受持六十二億恒河沙菩薩名字並盡形供養，與受持觀世音名號一時禮拜供養，二人福等無異。指出從表相難以理解，真實義是實證自身第八識如來藏，即禪宗開悟，所得為世出世間福德，故無量無邊。並說入火不燒、家家阿彌陀戶戶觀世音皆須從實際理地理解，最後邀請參加正覺共修。","p":["語譯六十二億恒河沙菩薩供養之喻","表相上難說二人福德相等","受持觀世音即實證第八識如來藏","火不能燒指第八識體性如金剛","所得世出世間福德無量無邊"],"k":["受持名號","如來藏","福德","實際理地","開悟","普門品"]},"7429-a29_108":{"s":"本集講無盡意問觀音如何遊娑婆說法，引三十二應身經文，以《維摩詰經》「佛以一音演說法」說明根器不同而理解各異，並批評只靠觀音本尊示現化身的理解與一神教無異。理上舉兩例：應以佛身得度者，其第八識為其示現佛身說法，以釋迦降魔、明星見性為證；辟支佛身亦然，並以胎兒由第八識出生說明。","p":["佛以一音演說法，眾生隨根器得解","只依賴觀音化身度化，類似一神教","應以佛身得度：第八識示現佛身說法","釋迦見明星眼見佛性，成所作智現前","胎兒由自身第八識出生，非母親所造"],"k":["三十二應身","如來藏","事理雙具","眼見佛性","辟支佛","普門品"]},"7441-a29_109":{"s":"本集續講〈觀世音菩薩普門品〉「應以聲聞身、梵王身、帝釋身……乃至執金剛身得度者，即現之而為說法」等經文，從理上說明是各人第八識「觀世音菩薩摩訶薩」依其願與業變生相應色身並不斷說法；並引《長阿含經》愚比丘問大梵天王的記載，說明大梵天王並非造物主。","p":["聲聞身得度：第八識為其示現聲聞身並說法","因內有恐怖、因外有恐怖：須信有內識方能斷我見","大梵天王三次答非所問，於佛前承認未造世界","真正造物主是各有情自己的第八識","天大將軍、毘沙門、小王乃至執金剛身皆由第八識變現"],"k":["普門品","第八識","應身說法","造物主","聲聞身","執金剛神"]},"7439-a29_0110":{"s":"本集說明經中所舉觀世音化身只從初禪天下至人間，因二禪以上住等至位、無色界無形色、三惡道受苦無心聞法，故不說為其說法；接著講解無盡意菩薩以寶珠瓔珞供養，觀世音分作二分奉釋迦牟尼佛與多寶佛塔的經文，先作事相解說，並留下「自在神力」之問待下集。","p":["化身範圍只從初禪天到人間的原因","二禪以上禪悅一念不生，無色界無形色可示現","三惡道苦逼或無智，雖有觀世音說法而聽不見","無盡意先稟白佛陀再供養瓔珞，並為大眾請受","瓔珞分奉釋迦牟尼佛與多寶佛塔，世尊讚自在神力"],"k":["普門品","三十二應身","施無畏","無盡意菩薩","瓔珞供養","多寶佛塔"]},"7452-a29_0111":{"s":"本集講「應當一心供養觀世音菩薩摩訶薩」，先釋慈為與樂、悲為拔苦，以悲為體、以慈為用；再從理上說自性觀世音以種種形為初禪以下至人間有情說法；並分別說明禪師、法師、論師、戒師、居士、師父、徒弟及未來法主各應如何作法供養。","p":["慈與樂、悲拔苦，以悲為體以慈為用","如來藏普為初禪以下有情及有福鬼神說法","禪師以「南無觀世音菩薩」答問，如禾山解打鼓","批評以聲聞戒為正解脫戒，正覺傳戒歸依大乘三寶","居士送書、徒弟學神贊、法主須廣開福田"],"k":["法供養","觀世音菩薩","如來藏","慈悲","禪宗公案","菩薩戒"]},"7425-a29_112":{"s":"本集從理上解釋觀世音何以稱施無畏，並釋無盡意為「歸命之意無盡」；說明自性觀世音寸絲不掛而不受瓔珞，經佛勸請後分奉「能仁寂靜」第八識與五蘊身多寶佛塔，於不受中成就法供養；後講重頌「汝聽觀音行……能滅諸有苦」，兼述正法明如來倒駕慈航。","p":["怖畏急難中依自家觀世音得以脫離","諸佛皆依自己第八識成佛，故歸命無盡","實際理地寸絲不掛，故觀世音不肯受供","釋迦牟尼喻第八識，多寶佛塔喻五蘊身","聞名見身結緣，終能證悟或往生滅諸有苦"],"k":["施無畏","無盡意菩薩","法供養","多寶佛塔","如來藏","正法明如來"]},"7449-a29_0113":{"s":"本集依事相講解重頌中火坑、巨海、須彌峰、怨賊、王難、枷鎖、毒藥、惡獸等諸難得解脫的經文，舉玄奘遇盜、《高王觀世音經》為例；隨後進入「觀音法門與外道聽音法門的差異」，說明觀音法門是聞思修入三摩地，並批評清海聽聲音法門屬聲論外道。","p":["念觀音力可避火坑、海難、推墮、怨賊等諸難","玄奘遇盜，盜賊歸還財物並受三歸","惡獸之難若有往世因果，菩薩不干預","觀音法門是聞思修證佛菩提，非修定或聽聲","入流亡所、所入既寂、聞所聞盡、覺所覺空"],"k":["觀音法門","聞思修","入流亡所","普門品偈頌","聽音法門","三摩地"]},"7459-a29_114":{"s":"本集比較外道無所有處定、非想非非想定與觀音法門的「覺所覺空」，說明觀音法門是保留覺知心、離五浮塵根而與如來藏妙真如性相應，終至寂滅現前、超越世出世間、獲二種殊勝；並從理上講先聞熏正確般若、思惟成相似般若，再參究證如來藏而入般若三摩地。","p":["非想非非想定仍有能覺所覺，非真二覺空","觀音法門離五浮塵根而與妙真如性相應","寂滅現前、超越世出世間、獲二種殊勝","先理上入流亡所斷我見，再事修觀音法門","需先明心、眼見佛性，否則盲修瞎練"],"k":["觀音法門","聞思修","如來藏","非想非非想定","入流亡所","般若三昧"]},"7455-a29_115":{"s":"本集講重頌「真觀清淨觀……是故應頂禮」，說明真觀是觀真實常住法而非緣起性空觀，並釋清淨觀、廣大智慧觀、悲觀慈觀；講解三災三劫、悲體戒雷、甘露法雨、諍訟與軍陣之難，舉道信、弘忍退賊為例；最後指出此段前讚「觀」、後讚「音」，為普門品事說的總結。","p":["真觀觀真實常住法，非緣起性空的如幻觀","清淨觀：五蘊附屬清淨如來藏","風火之災泛指壞劫火水風三劫","道信吉州、弘忍蘄州皆有賊兵退散的記載","妙音菩薩與觀世音菩薩同是一類如來藏"],"k":["普門品偈頌","真觀","清淨觀","悲體戒雷","妙音觀世音","感應"]},"7447-a29_116":{"s":"本集開始從理上解釋普門品重頌，先講「聞名及見身，心念不空過，能滅諸有苦」：聞名即聽聞自身有如來藏，引「現前立少物」說明建立正見，見身即實證；再講前六句的理說；並將「推落大火坑」解為密宗樂空雙運的邪見火坑，以及二乘的涅槃貪。","p":["聞名即聽聞自性觀世音即如來藏","現前立少物：先建立有真如的正知見","見身即實證，從理上滅三有諸苦","密宗樂空雙運被視為推人落入的大火坑","對菩薩而言，二乘涅槃貪才是最大火坑"],"k":["理說","如來藏","心念不空過","火坑之難","樂空雙運","涅槃貪"]},"7467-a29_117":{"s":"本集理說「漂流巨海，龍魚諸鬼難」與「須彌峰為人所推墮」：巨海喻自性大海，落於五陰自性者即自性見外道，練禪功、執幻境皆屬龍魚鬼難；須彌峰喻證真如的境界，無明惡人令人疑真如太易證而頭上安頭；念自己的觀世音菩薩即能如日虛空住。","p":["不承認第八識者皆漂流於自性見大海","禪功、打通任督二脈、幻覺被視為龍魚鬼難","須彌峰喻證真如，全球證者極稀有","無明惡人令人疑真如太平凡而另求真如","比對如來藏常住真如，即能如日虛空住"],"k":["理說","自性見外道","證真如","退轉","無明","如來藏"]},"7451-a29_0118":{"s":"本集理說「惡人逐墮金剛山」、「怨賊繞」與「王難苦」：惡人指愛樂追逐境界，七金山喻七轉識境界，應令境界為我所用；怨賊指由宿命通、天眼通所生的六十二種邪見；王難指佛教界大山頭與密宗法王對正法的抵制，念自己的觀世音菩薩即能化解。","p":["惡人是心中愛樂追逐六塵境界","七金山喻七轉識境界，不被牽走即不墮落","娑婆持戒一日勝極樂修行百年，不必遠離五欲","怨賊即六十二見，歸結於如來藏所生即降伏","王難指大山頭與法王抵制及師父否定如來藏"],"k":["理說","六十二見","七轉識","王難","如來藏","法身慧命"]},"7461-a29_0119":{"s":"本集理說枷鎖杻械、咒詛毒藥、惡羅剎毒龍諸鬼等句：枷鎖喻一念無明與無始無明，咒詛喻相似像法，毒藥喻「大乘非佛說」等邪見，羅剎、毒龍、諸鬼喻貪瞋、執聲聞涅槃與邪見；最後依《大唐西域記》敘述清辨論師欲與護法辯論、求觀自在菩薩及入阿修羅宮的故事。","p":["枷鎖杻械喻無明及空有二邊的繫縛","相似像法生則正法滅，舉各山頭說法為例","色法不能生心，以此破無因唯緣論","惡羅剎、毒龍、諸鬼各喻修道中的煩惱邪見","清辨誦咒三年得觀自在指示，入阿修羅宮"],"k":["相似像法","理說","邪見","清辨論師","觀自在菩薩","無明"]},"7457-a29_120":{"s":"本集分析清辨論師的故事，指其錯過護法菩薩、不向觀世音請法只求保留色身，顯示慢心、身見未斷且修行繞遠路，不足以承繼龍樹中觀；接著理說惡獸、蚖蛇蝮蠍、雲雷降雹等句，分喻五欲、嫉妒毒害心與末法邪說，並開始引達賴喇嘛著作加以批評。","p":["清辨與摩訶迦葉等待彌勒的性質不同","不肯拜見護法菩薩，被評為慢過慢","只求保身待彌勒，被評為身見具足","惡獸喻五欲；在家人不行出家法，出家人不行在家法","雲雷降雹喻末法邪說，引達賴書批評雙身法"],"k":["清辨論師","護法菩薩","身見","五欲","雙身法","末法邪說"]},"7469-a29_121":{"s":"本集逐段辨正達賴喇嘛《西藏佛教的修行道》中以貪欲、精液與明妃交合結合空性的說法，指其為有相有為的想像法並違背苦聖諦；接著理說「觀音妙智力」的自受用與他受用、如來藏「具足神通力」與「無剎不現身」，並說惡趣源於異生性。","p":["空性指如來藏體性，非雙修所得之樂","拙火、氣脈屬有為法，與無相空性心相違","藏密樂空之說被指違背苦聖諦與欲為不淨","觀音妙智力：證如來藏可自利亦可救人","如來藏依業變現各道之身，即具足神通力"],"k":["雙身法","空性","如來藏","觀音妙智力","神通","異生性"]},"7473-a29_122":{"s":"本集說明二乘與大乘應斷異生性的廣狹，悟後仍可能遇惡緣退轉，須依如來藏漸修滅除；再理說真觀清淨觀、無垢清淨光、悲體戒雷、諍訟經官等偈，並引《雜寶藏經》離越阿羅漢因往世誣謗辟支佛而受誣入獄十二年的故事，說明因果記錄於如來藏。","p":["大乘異生性至初地入地心方斷盡","假觀、真觀、清淨觀至悲觀慈觀的次第","災火喻欲界貪愛，災風喻心中躁動","悲體戒雷震：道共戒震壞不善念","離越阿羅漢因往世誣謗辟支佛而受報"],"k":["異生性","真觀","道共戒","因果","離越阿羅漢","如來藏"]},"7463-a29_123":{"s":"本集講「妙音觀世音，梵音海潮音」與「念念勿生疑……能為作依怙」，說明如來藏運作恆發清淨、不間斷的法音，應常念以增長轉依；分析生疑源於慧力、定力、福德不足或慢心，強調五停心觀、無相念佛與未到地定能使悟後證轉不退；並說如來藏為苦惱死厄中的依怙。","p":["妙音、梵音即清淨音，海潮音喻恆常法音","生疑因慧力、定力、福德不足或有慢心","證轉：證悟後須能現觀運轉才有受用","無相念佛與未到地定可降伏欲界惑而不退","如來藏無三毒，為生死舟航與依怙"],"k":["如來藏","海潮音","無相念佛","證轉","未到地定","依怙"]},"7480-a29_0124":{"s":"本集講「具一切功德，慈眼視眾生，福聚海無量，是故應頂禮」，說明如來藏生一切身、收藏一切福德；再釋持地菩薩總結與八萬四千眾發無上心，以如來藏如大地持一切；並回顧常不輕、藥王、妙音等諸菩薩品，指出各品法義皆依如來藏相通，並批評印順「佛偶然出現」之說。","p":["如來藏具一切功德，涅槃亦由祂而有","慈眼視眾生、福聚海無量，故應頂禮","持地菩薩出場：如來藏猶如大地持一切","諸菩薩品橫跨久遠時空，批評佛偶然出現說","見釋迦牟尼與多寶如來，喻第一義法智與類智"],"k":["如來藏","持地菩薩","福德","法智類智","妙音菩薩","一佛乘"]},"7477-a29_0125":{"s":"本集總結普門品後的感觸：善知識難遇、佛法須三大阿僧祇劫修證；進入〈陀羅尼品〉，講藥王菩薩問受持法華經之福德及佛答受持一四句偈功德甚多，藥王說咒護持說法者；並引《雜阿含經》說明法師的定義在說法內容而非外相，兼述誦咒宜專持一咒。","p":["善財言善知識出世難、值遇難、得其意難","批評視佛法僅為四聖諦而斥如來藏者","藥王菩薩說咒，護持演說法華經的法師","佛說法師：說五陰生厭離欲滅盡寂靜者","每咒各有部族護持，誦咒專持一種即可"],"k":["陀羅尼品","藥王菩薩","法師定義","善知識","陀羅尼","如來藏"]},"7471-a29_126":{"s":"本集續講〈陀羅尼品〉，說明誦藥王咒可得其部族護持；解釋讀誦通利與不用筆墨的真書寫，藥王故意請問以取得佛陀認可；比較布施各類對象的福德，指出受持一四句偈而讀誦解義、如說修行，功德勝過供養無數諸佛；並說此咒為六十二億恆河沙諸佛所說，含佛法僧三寶。","p":["誦藥王咒可與其部族相應而得護持","通利指如實理解密意，真書寫不用筆墨","布施對象不同，所得福德倍數不同","受持一四句偈並如說修行，勝供養無數佛","咒含佛馱、達磨、僧伽，侵毀法師即侵毀諸佛"],"k":["陀羅尼品","四句偈","受持","福德","藥王菩薩","陀羅尼"]},"7483-a29_0127":{"s":"本集講〈陀羅尼品〉中勇施菩薩、毘沙門天王、持國天王、十羅剎女與鬼子母相繼說咒，擁護演說及受持法華經者；說明護持說法者之咒多由諸佛所說，鼓勵受持並弘傳；並說明鬼子母已證初果、十羅剎女皆為證果的佛弟子，及其偈中對惱亂法師者的警示。","p":["法華經、金剛經、此經同指第八識如來藏","勇施咒為恆河沙諸佛所說，亦護受持一偈者","毘沙門天王護持經者百由旬內無衰患","說法者之咒多由諸佛說，鼓勵受持並弘傳","十羅剎女與鬼子母說咒，鬼子母已證初果"],"k":["陀羅尼品","陀羅尼","護法","羅剎女","鬼子母","法師"]},"4664-a20_001":{"s":"本集為《勝鬘經》系列緒論，說明原始佛法應函蓋三轉法輪，批評以六識論只認四阿含為佛說的觀點；指出宗門之悟不外於教門，悟後欲進修別相智、速入初地者應深入本經，並開始解釋經題中「勝鬘」的意義。","p":["原始佛法應函蓋三轉法輪成佛之道","講者批評六識論否定大乘非佛說","宗門證悟不得外於教門","七住菩薩僅有總相智，須進修別相智入地","解釋「勝鬘」為經主之名與花鬘譬喻"],"k":["勝鬘經","三轉法輪","八識論","如來藏","般若別相智","宗門與教門"]},"4665-a20_002":{"s":"本集解釋經題《勝鬘師子吼一乘大方便方廣經》各詞：勝鬘名字由來、師子吼破邪、一乘即唯一佛乘而函蓋二乘、大方便說明佛菩提道與解脫道的關聯、方廣指佛法函蓋面；並讚歎譯者求那跋陀羅，預告〈如來真實義功德章〉。","p":["勝鬘之名源於母親末利（鬘）夫人","師子吼喻破斥凡夫與二乘的誤解","一乘即唯一佛乘，函蓋二乘法","大方便：闡明佛菩提與解脫道異同","方廣指佛法函蓋範圍；讚譯經者功德"],"k":["經題","一乘","唯一佛乘","師子吼","大方便","方廣"]},"4666-a20_003":{"s":"本集進入〈如來真實義功德章〉，講解波斯匿王與末利夫人遣使旃提羅送信給勝鬘夫人的緣起經文；說明「如是我聞」「一時」、末利夫人出身、阿踰闍國名義，以及勝鬘夫人頂受家書、說偈請佛現身，並論證佛普為世間說人天乘至三乘法。","p":["如是我聞為證信，一時不標年代","末利夫人與勝鬘夫人的身世","阿踰闍意為不可攻克之國","勝鬘頂受家書，對使者修供養","佛普為世間說人天乘及三乘菩提"],"k":["如來真實義功德章","勝鬘夫人","緣起","頂受","人天乘","三乘菩提"]},"4667-a20_004":{"s":"本集講解佛應勝鬘夫人之念於空中現無比身的經文，判定所現為化身而非報身或法身，說明頭面接足禮；並解釋「歎佛實功德」：二乘所證為緣起性空的世俗諦虛相法，菩薩與佛證得無餘涅槃本際如來藏，才是真實功德。","p":["佛於空中所現為化身，非報身法身","頭面接足禮與頭面捉足禮的差別","二乘世俗諦為虛相法，灰身泯智","無餘涅槃中有本際第八識常住","菩薩未斷思惑即證涅槃本際"],"k":["實功德","化身","無餘涅槃","涅槃本際","如來藏","世俗諦"]},"4668-a20_005":{"s":"本集講「如來妙色身，世間無與等」，對比二乘灰身泯智與菩薩實證第八識；引《雜阿含》「智者解脫色」與《央掘魔羅經》說明佛有常住解脫色，並批評某大法師視佛同阿羅漢、主張大乘非佛說及凡夫菩薩行可成佛；說明三轉法輪次第施設。","p":["解脫道與佛菩提道的區別","二乘灰身泯智，佛不入無餘涅槃","引阿含「智者解脫色」證佛色常住","講者批評某法師佛同阿羅漢之說","三轉法輪次第：先解脫道再般若、種智"],"k":["如來妙色身","解脫色","灰身泯智","三轉法輪","一切種智","人間佛教"]},"4669-a20_006":{"s":"本集續講「智者解脫色」：外道練氣求長生終不免死，菩薩證如來藏後能自主生處、視色身為道器；說明二乘聲聞、緣覺與菩薩修證的不同，並開講「如來色無盡」偈，批評某法師及部派、上座部對佛滅後灰身泯智或淨智仍存的說法。","p":["外道求長生不可得，凡生必有死","菩薩不入無餘涅槃，色身為解脫身","聲聞、緣覺、菩薩修證內容差異","般若、種智、習氣修除不共二乘","講者批評上座部「佛滅仍有淨智」說"],"k":["智者解脫色","道器","聲聞","緣覺","部派佛教","如來色無盡"]},"4670-a20_007":{"s":"本集講「如來色無盡，智慧亦復然」：說明凡夫論師造論易誤、須有慧眼法眼才能辨偽經論；佛與阿羅漢涅槃內涵不同，佛入涅槃只是示現；以應身遍世界受生、《央掘魔羅經》釋迦住持百佛世界、化身與莊嚴報身說明如來色無盡。","p":["講者批評安慧、月稱等凡夫造論","慧眼法眼方能辨別偽經論","阿羅漢未斷習氣，佛斷盡二障","應身受生無盡，佛住持百佛世界","化身與他受用報身；大念非大聲念"],"k":["如來色無盡","應身","化身","報身","十無盡願","央掘魔羅經"]},"4671-a20_008":{"s":"本集續以莊嚴報身（七百無量數劫）與自受用法身說明如來色無盡、智慧不斷；解釋「一切法常住」為一切法攝歸如來藏；並詳解《央掘魔羅經》「解脫色是佛，非色是二乘」及空聚落、川竭、瓶空之喻，闡明空如來藏與不空如來藏。","p":["莊嚴報身住七百無量數劫","自受用法身智慧無邊","一切法攝歸如來藏故常住","虛空色是佛，非色是二乘","空與不空如來藏為同一如來藏"],"k":["一切法常住","莊嚴報身","空如來藏","不空如來藏","央掘魔羅經","解脫色"]},"4672-a20_009":{"s":"本集先依次解說佛十號：如來、應供、正遍知、明行足、善逝、世間解、無上士、調御丈夫、天人師、佛世尊的意義；再講「降伏心過惡，及與身四種；已到難伏地，是故禮法王」，說明四種指一念無明四住地煩惱，難伏地指斷盡無始無明塵沙惑，並批評密宗法王稱號。","p":["如來、善逝：乘真如來去而無來去","正遍知顯異於凡夫、外道、二乘、菩薩","身心四過惡即一念無明四住地煩惱","難伏地為斷盡無始無明上煩惱","講者批評藏密法王未斷我見"],"k":["佛十號","一念無明","四住地煩惱","無始無明","法王","塵沙惑"]},"4673-a20_010":{"s":"本集說明本經主旨在顯示佛菩提含攝二乘、破邪顯正，只有佛能稱法王，並批評藏密法王與《妙雲集》作者以解脫道為成佛之道；接著講「知一切爾焰」，解釋爾焰即所知、渴愛，以世間追求、打坐修定為例，分述世間與出世間的爾焰。","p":["本經在顯佛菩提含攝二乘菩提","只有諸佛能稱法王","講者批評《妙雲集》以解脫道為成佛道","爾焰即所知境界對心的惑亂","世間爾焰與出世間爾焰的內容"],"k":["爾焰","一念無明","法王","解脫道","佛菩提道","破邪顯正"]},"4704-a20_011":{"s":"本集續講爾焰與「智慧身自在，攝持一切法」：智慧有作用行相故稱身，攝持一切法源於念心所圓滿，須經聞思修證起勝解；再講「敬禮過稱量」，說明唯如來藏法身不可稱量，二乘所證皆可稱量，並批評《妙雲集》以解脫道代替佛菩提道。","p":["佛知一切爾焰，智慧身自在","智慧有作用行相故名智慧身","攝持一切法因念心所具足圓滿","唯如來藏法身過稱量","講者批評《妙雲集》前後矛盾"],"k":["智慧身","念心所","過稱量","法身","如來藏","勝解"]},"4705-a20_012":{"s":"本集講「敬禮無譬類、無邊法、難思議」：如來藏又名所知依、心，一切所知法依祂而有，不能歸類於所生法，也無法以單一譬喻說清；以造汽車、科技發展、人的生老死及因果業報為例，說明無量法皆依如來藏而有，故名法身。","p":["如來藏又名所知依、心","講者批評「性空唯名」解《心經》","如來藏不可歸類，故無譬類","汽車、科技等萬法皆依如來藏","生老病死與業報由如來藏執行"],"k":["法身","所知依","無譬類","無邊法","如來藏","因果業報"]},"4706-a20_013":{"s":"本集先略述二種無明的重要，再講「哀愍覆護我，令法種增長」：法種即一切法的功能差別、界；說明通教菩薩阿羅漢、菩薩辟支佛及第一義諦三智；判勝鬘夫人仍有胎昧，應為二地或三地初心；並批評某法師「法種是法身種子」之說，主張法身本有。","p":["法種即功能差別，又名界、法界","通教菩薩阿羅漢與菩薩辟支佛","第一義諦三智：總相、別相、種智","勝鬘未離胎昧，判為二地或三地初心","講者批評「法種是法身種子」說"],"k":["法種","功能差別","通教菩薩","第一義諦","胎昧","阿賴耶識"]},"4707-a20_014":{"s":"本集續講法種：以往生極樂蓮花由自己如來藏所生為例，說明法種不等於法身，須悟後進修令其清淨增長；說明勝鬘夫人經佛加持發起往世無漏法種，開悟是頓悟漸修；介紹賴耶緣起，批評十牛圖漸悟之說，並解釋頓教（華嚴）與漸教（三轉法輪）。","p":["極樂蓮花由自己如來藏的法種出生","法種不等於法身，須悟後漸修","明心見性皆頓悟，每世頓悟漸修","阿賴耶識集藏一切種子即賴耶緣起","華嚴為頓教，三轉法輪為漸教"],"k":["法種","頓悟漸修","賴耶緣起","頓教","漸教","胎昧"]},"4708-a20_015":{"s":"本集續述賴耶緣起與業種須由各人阿賴耶識集藏才不錯亂因果，並完成勝鬘夫人歸依佛的經文；之後逐段評析某法師《勝鬘經講記》，講者批評其把勝鬘夫人、阿踰闍國意象化及以意識所生悲心為勝義菩提心，認為這是暗示大乘非佛說。","p":["悟者每一小步如日進千里","業種由各人阿賴耶識集藏，因果不亂","勝鬘夫人求佛攝受，完成歸依","講者批評將勝鬘、阿踰闍意象化","勝義菩提心是如來藏，非意識悲心"],"k":["賴耶緣起","業種","勝義菩提心","世俗菩提心","大乘非佛說","歸依"]},"4709-a20_016":{"s":"本集繼續評析某法師對讚佛偈的註解：講者認為有漏修慧難入真如，如來藏本來出纏、法身非悟後才顯現，並批評其把佛空中示現意象化、以光明無比等同佛德、以滅相真如為法身；同時說明真如佛性不作主、悟後起修及阿賴耶識為金剛心。","p":["有漏修慧難以臨入真如","如來藏本來出纏，凡夫身上亦顯現","講者批評將佛空中示現意象化","光明無比不等於佛無邊功德","阿賴耶識為因地真如、金剛心"],"k":["法身","如來藏","真如","悟後起修","金剛心","大乘非佛說"]},"4710-a20_017":{"s":"本集探討讚佛真實功德與授記：讚佛能增善根、福德等同以寶供佛；依《瑜伽師地論》從妙色、寂靜、勝智、正行、威德五面讚佛，以及佛教法的不共、無倒、自覺三特質；再講佛為勝鬘授記為普光如來，說明授記的種類、意義及依如來藏種子而授記。","p":["讚佛增長善根，福德等同寶供","五面讚佛：妙色、寂靜、勝智等","佛教法不共、無倒、自覺","勝鬘被授記為普光如來","授記有通、別、顯、密，依八識論"],"k":["讚佛","授記","佛十號","十二分教","八識論","普光如來"]},"4711-a20_018":{"s":"本集簡介勝鬘十大受：以願為戒，十大受攝為三大願，再歸攝受正法一大願；並解說前三受：「於所受戒不起犯心」為攝心為戒的總相，「於諸尊長不起慢心」說明慢心障道與感恩師長，「於諸眾生不起恚心」說明以慈悲作意救護眾生。","p":["十大受以願為戒，歸攝受正法","不起犯心即攝心為戒的總相","慢心障道，應恭敬感恩師長","恭敬侍奉尊長與三十二相相關","於眾生不起恚心，以悲心破邪"],"k":["十大受","攝受正法","攝心為戒","慢心","瞋恚","菩薩戒"]},"4712-a20_019":{"s":"本集講勝鬘十大受第四、第五受：依《成唯識論》說明嫉屬瞋一分、慳屬貪一分；嫉心無益且障攝受眾生，慳於內外法則妨布施度，而法布施反能增長自己福慧；引九結、八纏顯示嫉慳的重要，並以隨喜讚歎對治嫉、以布施對治慳。","p":["嫉為瞋一分，慳為貪一分","他人身色資財為因果，不應起嫉","於內法起慳令道業遲緩","九結、八纏皆特別列出嫉與慳","以隨喜治嫉、以布施治慳"],"k":["十大受","嫉","慳","布施","隨喜","九結"]},"4870-a20_058":{"s":"本集延續意生身問題，講者逐條批評某位人間佛教法師《勝鬘經講記》的說法：優陀夷諍論意生身無依據、阿那含未必有意生身、意生身與變易生死無關；並指出其在《印度之佛教》中錯誤斷句《中阿含》經文以論證大乘演化。最後以熏習道理說明第八識，強調佛法應實證而非研究。","p":["優陀夷從未談意生身有色無色","唯三明六通阿羅漢方有神通意生身","意生身有無與斷變易生死無關","錯斷「心意識常」經句以證思想演變","熏習須能熏所熏，可證第八識"],"k":["意生身","變易生死","大乘非佛說","心意識","熏習","實證佛法"]},"4871-a20_059":{"s":"本集講解《勝鬘經》住地煩惱與起煩惱經文：二乘不受後有只是方便說，仍有異熟、變易生死。逐一解說見一處、欲愛、色愛、有愛四住地，以無想定、無想天為例說明色愛，並說明四住地即一念無明，見惑為見道所斷、思惑為修道所斷。","p":["二乘不受後有是方便說非究竟","見一處住地即三縛結，菩薩所知更深","色愛住地：誤入無想定而非涅槃","有愛住地即無色界愛","四住地即一念無明，分見惑與思惑"],"k":["四住地煩惱","起煩惱","變易生死","一念無明","見惑思惑","三縛結"]},"4872-a20_060":{"s":"本集講解「心不相應，無始無明住地」及「四住地力，一切上煩惱依種」。說明眾生與二乘不與無始無明相應，探究實相時方相應，明心時打破；悟後探究為何未成佛才與上煩惱相應。上煩惱如塵沙無量，須三大阿僧祇劫斷盡，四住地力量遠不能比。","p":["無始無明住地與覺知心本不相應","四住地維持五蘊，為上煩惱所依","留惑潤生方能進修上煩惱","明心打破無始無明，未必相應上煩惱","上煩惱如恆沙，非算數譬喻所及"],"k":["無始無明住地","上煩惱","塵沙惑","留惑潤生","明心","四住地煩惱"]},"4904-a20_061":{"s":"本集介紹平實導師的雨傘譬喻：整支傘喻如來藏與色身五陰，手把喻一念無明四住地。說明斷我見如抓到手把，阿羅漢斷盡我執也只摸清手把。詳解見一處住地為三界處處起我見，以孟婆湯說法說明意識不能通三世，並說明初果至俱解脫的次第。","p":["雨傘喻如來藏，眾生在其中而不知","手把喻一念無明四種住地煩惱","阿羅漢所知僅雨傘手把","孟婆湯說法顯意識不通三世","初果見地、二果薄地至俱解脫次第"],"k":["雨傘譬喻","如來藏","見一處住地","一念無明","斷我見","四果"]},"4905-a20_062":{"s":"本集延續雨傘譬喻，區分我見與我執，說明一念無明之名源於定中忽起一念，並以中陰身投胎說明我見我執引生起煩惱。四住地恆時存在而起煩惱有生有滅；傘骨喻四住地習氣種子（異熟種），二乘只斷現行；支架、傘布喻所知障塵沙惑，不障解脫只障成佛。","p":["斷我見與斷我執不同，我執分三界","定中忽起一念，故名一念無明","中陰身投胎源於我見我執","傘骨喻習氣種子，二乘只斷現行","傘布喻所知障，障成佛不障解脫"],"k":["一念無明","我執","習氣種子","所知障","中陰身","雨傘譬喻"]},"4906-a20_063":{"s":"本集以雨傘譬喻說明無始無明：探究實相時相應，破參證如來藏時打破，悟後生起成佛疑惑時上煩惱現起並轉為起煩惱。並依〈般若信箱〉解說「所知障是現非種」，對地上菩薩亦可稱種子；傘帽喻最後身菩薩所斷。最後引經強調親近善知識居四法之首。","p":["破參證如來藏即打破無始無明","上煩惱生起相應即轉為起煩惱","所知障是現非種，地上菩薩亦可說種","窺知雨傘全貌是入地心通達位","修學四法以親近善友為第一"],"k":["無始無明","上煩惱","所知障","明心","初地","善知識"]},"4907-a20_064":{"s":"本集從因明學看佛學研究與實證。講者批評網路文章主張以學者為良師、作為判斷善知識的工具，認為學者不能指導實證卻要釐清聞思修是矛盾；也批評將大乘分體系的作法。說明論著以立宗、辯因、引喻三支論述合乎因明，並指出三段論大前提錯則結論錯。","p":["依學者判斷善知識違背佛說次第","學術視大乘為思想演化並分三系","分體系研究會障礙唯一實相的實證","因明立宗辯因引喻，非預設立場之過","三段論大前提有誤則結論錯（黑天鵝）"],"k":["因明","佛學研究","善知識","實證佛法","大乘非佛說","真實如來藏"]},"4908-a20_065":{"s":"本集講者批評某位法師把四住地與無始無明住地合為一、都說成心不相應，認為其根源在以二乘解脫道取代成佛之道、將般若定位為性空唯名。講者反駁《中論》是《阿含》通論之說，主張《中論》闡大乘中道而隱去如來藏名相，並引阿含經文說明阿羅漢智慧不等於佛。","p":["某師將四住地與無始無明混為一談","講者評其以解脫道取代佛菩提道","《中論》闡大乘中道，非阿含通論","龍樹隱去如來藏名相以攝小乘人","阿含亦載無人智慧等同如來"],"k":["無始無明住地","中論","三乘菩提","性空唯名","如來藏","緣起性空"]},"4909-a20_066":{"s":"本集說明無明有無始無明（所知障）與一念無明（煩惱障）兩種，引《瑜伽師地論》二斷二智、二種淨證明二乘只斷煩惱障。解說四住地與禪定只能伏煩惱，無始無明即對法界實相無知。並批評某法師以「住地即熏習種子」解經，又在《成佛之道》把所知障說成習氣，前後矛盾。","p":["二障二智：二乘僅證煩惱障淨","四定等至只伏煩惱，意識意根未滅","無始無明即所知障、理障","某師以住地為種子，二住地合一","勝鬘經明說大乘出生二乘善法"],"k":["所知障","煩惱障","無始無明","一念無明","瑜伽師地論","二斷二智"]},"4910-a20_067":{"s":"本集說明四住地煩惱連同意根相續我執，剎那相應從不間斷；無始無明住地則要到迴小向大探究實相時才相應。講者逐段引某法師講記，指其前後說法矛盾，並把恆沙上煩惱說成四住地所起、把不染污無知說成二乘習氣；講者主張不染污無知即無始無明。","p":["四住地含意根我執，剎那相應","無始無明至迴小向大方相應","某師對住地相應與否自相矛盾","上煩惱屬無始無明，非四住地所起","不染污無知即無始無明，非習氣"],"k":["四住地煩惱","無始無明住地","上煩惱","不染污無知","起煩惱","勝鬘經"]},"4911-a20_068":{"s":"本集反駁某法師「習氣即極微細無明、即無明住地」之說，主張二乘不斷的不染污無明是對實相的無知。說明習氣多從初地起修斷；所知障隨眠無功用故不稱種子，但斷變易生死須兼斷習氣與所知障隨眠。後半批評佛法隨時代演變之說，並批評其文獻考證立場偏執。","p":["不染污無明是實相無知，非習氣","習氣種子主要自初地起修斷","所知障隨眠無功用，故非種子","斷變易生死須兼斷習氣與所知障","講者駁佛法演變說，評其文獻考證"],"k":["習氣種子","所知障","變易生死","不染污無明","上煩惱","佛法演變"]},"4912-a20_069":{"s":"本集以《華嚴經》菩提心燈破暗譬喻開場，說明業與煩惱，並講《雜寶藏經》娑羅那比丘被惡生王毆打欲還俗，大迦旃延以夢境開導「欲滅怨者當滅煩惱」的故事，說明迷事無明。接著區分一念無明與無始無明（迷理無明），解說無明住地力最大及「有愛數四住地」之義。","p":["菩提心燈能破長劫業煩惱闇障","業種存於如來藏，煩惱略說即三毒","娑羅那比丘故事：滅怨當滅煩惱","無始無明即迷理無明","四住地可計數，故稱有愛數"],"k":["迷理無明","業煩惱","無明住地","有愛數四住地","菩提心","雜寶藏經"]},"4913-a20_070":{"s":"本集續說見一處住地為處處起我見，我執分欲界、色界、無色界三類。說明無明住地力最大：四果不能打破，親證如來藏即可斷見惑，四住地含攝其中。並講解「取緣有漏業因而生三有」及「無明住地緣無漏業因生三種意生身」，說明起惑、留惑潤生屬無漏業因。","p":["見一處即三界處處起我見","斷我見後仍有三住地我執","證如來藏即斷見惑，見無明力大","取緣有漏業因而生三界有","無明住地緣無漏業因生三種意生身"],"k":["無明住地","意生身","有漏業","無漏業","見一處住地","留惑潤生"]},"4944-a20_071":{"s":"本集講解「無明住地異，離四住地，佛地所斷，佛菩提智所斷」，強調真善知識難遇。引《瑜伽師地論》先得聖者之智再除煩惱，及《增壹阿含》舍利弗銅器譬喻，加上果汁杯譬喻，說明修行須先除煩惱垢。並說明先說苦無常再說常法的次第、明心是七住門檻，以及般若如甘露良藥。","p":["無明住地異於四住地，佛地所斷","修觀行者先得聖智，再斷煩惱","銅器、果汁譬喻：先除煩惱垢穢","佛先說苦無常，後說常住法","明心打破無始無明，般若如甘露"],"k":["無明住地","除煩惱","善知識","般若智慧","明心","四住地"]},"4945-a20_072":{"s":"本集續講《未曾有因緣經》世尊教誡羅睺羅、以般若方便斷結成佛；說明聖者為成佛所造善業淨業皆屬無漏業。以菩提芽種與燈炷相續燃燒譬喻，說明發願迴向是在增長菩提種而非執著。引《涅槃經》說明菩薩種性如如意寶，引《瑜伽》說福德資糧，最後總結兩種無明。","p":["世尊以般若方便斷結習成佛","為成佛所造善業淨業皆無漏業","炷心譬喻：念念菩提心相續成佛","菩薩種性經層層淬鍊，如如意寶","福德資糧含值遇真善知識"],"k":["菩提心","無漏業","般若智慧","菩薩種性","福德資糧","無始無明"]},"4946-a20_073":{"s":"本集講解「取緣有漏業因而生三有」一段經文，說明取函蓋欲、色、無色三界愛，以歌舞、禪定、四空定說明三界有漏業因。說明三種聖者緣無明住地無漏業因而有意生身。接著區分四住地（見思惑、起煩惱）與無明住地（塵沙上煩惱），並說明悟後進修所得正受。","p":["取函蓋三界愛，緣有漏業生三有","修禪定、四空定是有漏善業","三種意生身緣無明住地無漏業因","煩惱略分見惑、思惑、塵沙惑","悟後逐分深入法義，圓滿正受"],"k":["取","三界有","有漏業","意生身","塵沙惑","正受"]},"4947-a20_074":{"s":"本集說明「有愛住地數四住地，不與無明住地業同」，兩者不應混同。逐一說明四住地引生的有漏業：見惑謗法、欲愛（講者以雙身法為例批評）、貪著禪定與四空定誤為涅槃。並說明聖者在無始無明住地中造的業是無漏業，如悟後求見佛性、尋訪善知識、布施護法。","p":["四住地可計數，塵沙惑不可計","四住地所緣皆有漏業，導致三界生","貪著禪定、四空定為有漏業因","明心後思惟進修即相應上煩惱","為成佛尋師、布施所造皆無漏業"],"k":["四住地","無明住地","有漏業","無漏業","上煩惱","塵沙惑"]},"4948-a20_075":{"s":"本集說明兩種無明引生的業不同：四住地引生有漏業，無明住地上煩惱引生善淨無漏業；無始無明含攝四住地，反之則否。明心時打破無始無明並斷見一處住地，再經十住、十迴向至初地。並解釋佛菩提智所斷、二乘無漏不盡無自在力，以證如來藏現觀業種不失說明自在力。","p":["無始無明含攝四住地，反之不然","明心時斷五利使，三縛結隨斷","七住經十迴向、十無盡願入初地","佛菩提智函蓋解脫智","證如來藏現觀業種不失得自在力"],"k":["無始無明","四住地","佛菩提智","自在力","明心","無漏業"]},"4949-a20_076":{"s":"本集說明煩惱障與所知障及「煩惱即菩提」，以菩薩三地可入滅盡定而不取、六地才取、八地方斷盡思惑，說明無生忍與無生法忍之別。說明上煩惱多在入地後、無漏業屬有為法，駁某師無明住地次第顯發之說。並比較二乘有餘解脫與佛之究竟解脫，涅槃一味而智慧有別。","p":["煩惱障障解脫，所知障障成佛","菩薩延遲取證滅盡定與解脫果","八地斷盡思惑，以悲願續受生","無明住地與四住地自無始同時存在","無餘涅槃一味，佛菩提智慧不平等"],"k":["所知障","煩惱障","無生法忍","滅盡定","無漏業","涅槃"]},"4950-a20_077":{"s":"本集延續《勝鬘經》〈一乘章〉「無明住地緣無漏業因，生三種意生身」一段，辨正某位導師級法師《勝鬘經講記》的解釋。講者指出三果人雖有神通也不能延壽，因為我慢未斷；並說明無漏業因不是悲願，而是大乘修道位中由無明住地所生的上煩惱。","p":["講者批評該法師說「本經不應這樣說」是增上慢","三果人我慢未斷，有神通也不能延壽","我慢是喜樂自我存在，不是與他人比較","無漏業因是無明住地所生的上煩惱","修道位上煩惱大多屬入地後諸地菩薩所斷"],"k":["無漏業因","上煩惱","無明住地","意生身","我慢","勝鬘經"]},"4951-a20_078":{"s":"本集繼續辨正某法師對變易生死與無漏業的解釋。講者指出變易生死階段所造善業都是無漏業，不招感生死；變易生死本已存在，不是由無漏業招感；並說明無明住地與四住地自無始以來同時存在，以及外道神足通也有意成身等。","p":["無漏業是無漏有為法，並非有漏業","八地以上所造業不再與分段生死相感","變易生死本來存在，不由無漏業招感","講者指該法師曲解《大智度論》淨土之說","無明住地與四住地自無始同時存在"],"k":["變易生死","無漏業","無明住地","四住地","意生身","勝鬘經"]},"4952-a20_079":{"s":"本集辨正某法師在「佛地所斷，佛菩提智所斷」句中自行加入「大力菩薩」的解釋，說明菩薩從七住位起已破無始無明、分證佛菩提智。並講解經文中阿羅漢、辟支佛、最後身菩薩為無明住地覆障而得少分涅槃，以及涅槃一味、等味、解脫味的意義。","p":["講者批評該法師擅加「大力菩薩」為過度解釋","菩薩從七住位起漸次分斷無始無明","實義菩薩已分證如來菩提智","二乘有餘解脫、有餘清淨，得少分涅槃","入無餘涅槃後同為如來藏獨住，故一味"],"k":["無始無明","佛菩提智","少分涅槃","涅槃一味","大力菩薩","勝鬘經"]},"4953-a20_080":{"s":"本集說明涅槃一味、等味從菩薩看是平等，從二乘看則不平等；並解釋最後身菩薩與佛地的差異在於煩惱障習氣與所知障最後一分的斷除。講者說明二乘「所應斷者不斷」、最後身菩薩「不究竟」，並以畢陵尚慢等例子說明阿羅漢的習氣種子。","p":["菩薩能說二乘之法，二乘無法說菩薩之法","最後身菩薩成佛夜斷盡習氣與所知障隨眠","無明住地斷除有極少分至極多分之別","二乘只斷煩惱障現行，未斷習氣種子","畢陵尚慢、阿難習氣顯示有餘清淨"],"k":["最後身菩薩","習氣種子","無明住地","有餘涅槃","所知障","畢陵尚慢"]},"4984-a20_081":{"s":"本集依《勝鬘經講記》第二輯，說明二乘所證只是少分涅槃、名向涅槃界。講者以阿含經說明離欲樂與無義苦行的中道，以「不生不住不異不滅」解釋涅槃，並引《大般涅槃經》八味說明佛地究竟涅槃；最後談明心菩薩乃至等覺菩薩所相應的苦。","p":["中道是遠離欲樂與無義苦行二邊","涅槃不生、不住、不異、不滅","二乘只斷分段生死現行，故為少分涅槃","佛地涅槃八味具足、具四種涅槃","明心後仍有微細苦，等覺百劫修相好"],"k":["少分涅槃","中道","大般涅槃","四種涅槃","苦行","向涅槃界"]},"4985-a20_082":{"s":"本集講解「得常住涅槃，於無覆護世間、無依世間為護為依」。講者說明悟後求一切種智各階位仍有苦，並解釋如來藏本來常住涅槃，故證得第八識者能為世間依護；引《文殊師利普超三昧經》、《佛說未曾有正法經》中大迦葉讓菩薩先行，說明二乘應敬重菩薩。","p":["悟後求種智的各階位都有相應之苦","如來藏不生不滅，一切眾生本來常住涅槃","講者批評以一念不生的意識境界當作開悟","證第八識者方能為無依世間作依護","大迦葉以師子子為喻，敬讓菩薩前行"],"k":["常住涅槃","如來藏","為護為依","菩提心","大迦葉","勝鬘經"]},"4986-a20_083":{"s":"本集講解「法無優劣、智慧等…故涅槃一味、等味、解脫味」，先複習世俗諦四聖諦與初果的條件。講者依經論說明苦集滅道、三十七道品與集諦四要點，並列出初果應具的斷三縛結、四不壞信、七聖財；最後說明如來藏涅槃在聖不增、在凡不減，所以法無優劣、智慧平等。","p":["依經論說明苦、集、滅、道四聖諦","集諦四要點：五陰、貪愛、造業、受熏持種","初果斷三縛結並成就四不壞信","七聖財中的慚愧使初果不墮三惡道","如來藏涅槃無優劣，故說一味等味"],"k":["四聖諦","斷我見","初果","三縛結","四不壞信","七聖財"]},"4987-a20_084":{"s":"本集辨正某位學人對前三集所講經文的解釋。講者指出該學人忽略「不究竟」三字，把最後身菩薩與二乘等同；又批評其「菩薩未得般涅槃」一語，說明菩薩是「不入」而非「未得」；並論常住涅槃德相，以及三德中二乘只有少分解脫德。","p":["無明住地有「不斷」與「斷而不究竟」二種","七住破無始無明，佛地才究竟斷盡","菩薩是悲願不入無餘涅槃，非未得","常住涅槃眾生本具，究竟德相唯佛所得","二乘無法身德、般若德，解脫德不具足"],"k":["無明住地","常住涅槃","三德","本來自性清淨涅槃","最後身菩薩","辨正"]},"4988-a20_085":{"s":"本集說明菩薩明心後依如來藏而有的五分法身：戒、定、慧、解脫、解脫知見，並以平實導師的示現為例。講者以《金剛經》句式說明阿羅漢不懂「入無餘涅槃即非入」，所以沒有法身德、般若德；又舉船子德誠接引夾山善會的公案，並分辨二乘將滅止生與菩薩本來無生。","p":["戒身：轉依如來藏的自性清淨為戒","定身：如來藏無出入，即「大龍常在定」","慧、解脫、解脫知見身依親證而自心流注","阿羅漢不解「入無餘涅槃即非入」之理","船子德誠與夾山善會公案；將滅止生與本來無生"],"k":["五分法身","法身德","般若德","如來藏","無餘涅槃","禪宗公案"]},"4989-a20_086":{"s":"本集針對某位號稱導師的法師把「法無優劣」解為三乘平等，提出辨正。講者引《金剛經》「一切賢聖皆以無為法而有差別」、阿含三乘之說、維摩詰經與法華三車喻、須跋陀羅先佛入滅等，說明三乘法門與證境有優劣，只有三乘根源的實相才是平等。","p":["講者指該法師以三乘無優劣誤導讀者","賢聖以無為法而有差別，悟後果位各異","阿含明載聲聞、辟支、佛三部之別","法華三車喻：二乘是引入大乘的方便","只有法界實相如來藏才是平等的"],"k":["三乘菩提","法無優劣","實相","三車喻","如來藏","辨正"]},"4990-a20_087":{"s":"本集續論「法無優劣，故得涅槃」，指出辟支佛只能推知名色從某識出生、阿羅漢只是信受涅槃有本際，兩者都未證實相。講者批評該法師把二乘相待的緣起性空套為「不二法」，說明唯有如來藏是不二法，必須從如來藏的立場才能說法法平等。","p":["辟支佛推知名色由識生，但不知其所在","阿羅漢信受本際不滅而未證，無般若慧","二乘緣起性空依蘊處界而存，是相待二法","如來藏函蓋二法而不墮二法，才是不二法","須從如來藏立場看，方說法法平等"],"k":["不二法","法法平等","如來藏","緣起性空","實相","辨正"]},"4991-a20_088":{"s":"本集辨正該法師對「智慧等、解脫等，故得涅槃」的註解。講者指出二乘滅盡一切法後無平等智可說，平等必須有法同時存在；只有菩薩現見如來藏遍一切法，才能說法法平等。並說明阿羅漢對生死有恐懼、依佛而住，不是大解脫自在，菩薩則承擔如來家業。","p":["如來藏對業種平等，是真正的法法平等","二乘法是佛為五濁眾生方便施設的化城","滅盡後斷滅空無從比較，非平等智","名色從入胎識來，此識才是法界實相","阿羅漢有恐懼、隨佛入滅，非大解脫"],"k":["平等智","解脫","如來藏","入胎識","化城","辨正"]},"4992-a20_089":{"s":"本集說明菩薩因現見本來涅槃而無所恐懼，才是大解脫自在，接著辨正該法師對「清淨等，故得涅槃」與三德的註解。講者指出二乘所證是意識心修成的清淨，菩薩所證是本來清淨的如來藏；二乘沒有般若德與法身德，解脫德也只有極少分。","p":["菩薩不懼胎昧，願承擔如來家業","講者指與該法師論法須先點破其錯誤前提","二乘清淨是意識心修成，非本性清淨","心解脫、慧解脫所證之心仍是意識","二乘無般若德、法身德，解脫德極少分"],"k":["本性清淨","三德","意識心","如來藏","心解脫","法身德"]},"4993-a20_090":{"s":"本集補充說明三德。講者以業種與異熟果報說明諸法的生起與壞滅依法身如來藏，並說明五分法身以如來藏為身；明心後觀如來藏不生不滅、不斷不常而有般若德，現觀自己本住涅槃而有解脫德。最後以禪門「天地懸隔」的例子說明三乘智慧不平等，而所證之法平等。","p":["諸法生滅依業種，業種由如來藏執持","五分法身以如來藏為身，故如來藏是法身","觀如來藏不斷不常的中道而有般若德","現觀本住涅槃即解脫德，七住即具三德","如來藏是無優劣法，三乘智慧則不等"],"k":["三德","法身","般若德","解脫德","如來藏","法無優劣"]},"5024-a20_091":{"s":"本集從《勝鬘經講記》第二輯「解脫等故得涅槃」講起，說明阿羅漢的解脫與清淨都是以意識心衡量而不平等，菩薩從如來藏看一切眾生則本來解脫、本來清淨。講者並辨正某法師在《成佛之道》中把八地菩薩與阿羅漢等同，以及其「滅相不滅即真如」的說法。","p":["阿羅漢解脫有斷未斷之分，故不平等","講者指八地菩薩斷盡習氣，非與羅漢同","菩薩從如來藏看眾生清淨平等","涅槃三德祕藏須依如來藏本來涅槃而說","將滅止生與本來不生的分別"],"k":["解脫","清淨","如來藏","八地菩薩","三德祕藏","無生"]},"5025-a20_092":{"s":"本集辨正某法師引《小品般若波羅蜜經》卷7以「滅相不滅」為真如之說。講者逐段解釋經中初心後心、燈炷與燈焰之喻，說明意識前後心能相續、善根能增長，是因有第八識真如心不即不離；並批評該法師否定七、八識，把非常非滅解為假名無自性。","p":["燈炷喻第八識，燈焰喻生滅的意識心","意識初心後心靠真如心連結而增長善根","真如心非即意識，亦不離意識","講者指該法師依六識論誤解般若經","滅相只是意識的概念，非真實涅槃"],"k":["真如","滅相不滅","第八識","六識論","小品般若經","三德祕藏"]},"5026-a20_093":{"s":"本集講解《勝鬘經》「無明住地不斷不究竟者，不得一味等味明解脫味」一段。講者說明四住地煩惱稱一念無明，無明住地是從無始來不與眾生心相應的無始無明；二乘斷四住地而得「無明解脫」，菩薩斷無明住地而不究竟，只有佛地是究竟的明解脫；並說明無明住地積聚而生修道所斷煩惱與上煩惱。","p":["四住地煩惱稱為一念無明","無始無明要到探究實相時才初次相應","二乘的解脫是無明解脫，非明解脫","菩薩分明解脫，佛地才究竟明解脫","修道位應斷煩惱習氣種子與上煩惱"],"k":["無明住地","一念無明","明解脫","上煩惱","無始無明","習氣種子"]},"5103-a20_094":{"s":"本集說明解脫道斷現行的修法：斷我見後斷欲界愛，加上未到地定發起初禪而證三果，再斷我慢等五上分結成四果；並轉述平實導師要求學人最多證三果。講者說明解脫道還須斷習氣種子，解釋三轉法輪先說解脫道的原因，以及佛菩提道從十信到七住所需的長遠時劫。","p":["斷欲界愛加未到地定，發起初禪成三果","三果必是心解脫，必已證得初禪","我慢是最難斷的五上分結","五濁世先說解脫道，使眾生生信","十信至七住明心須經長遠劫修六度"],"k":["三果","初禪","五上分結","我慢","三轉法輪","佛菩提道"]},"5027-a20_095":{"s":"本集續說佛菩提道修證的困難：明心之後到十住眼見佛性仍須長時，但肯承擔如來家業則進步快。講者說明成佛必須兼具解脫道與佛菩提道二主要道，斷習氣種子宜在逆境中歷緣對境；並批評某法師以二乘解脫道取代佛菩提道、認為弟子所證與佛平等。","p":["初住到十住眼見佛性需長遠時劫","承擔如來家業則佛加持、道業進步快","成佛須兼具解脫道與佛菩提道","逆境中被辱而不起瞋，可斷習氣種子","講者批評以二乘解脫道取代佛菩提道"],"k":["佛菩提道","二主要道","習氣種子","解脫道","眼見佛性","所知障"]},"5028-a20_096":{"s":"本集說明佛法有解脫道與佛菩提道，合為三乘菩提、五乘佛法，皆依阿賴耶識而建立。講者批評月稱《入中論》與宗喀巴以「見眾生無自性」即入初地之說，及否定阿賴耶識仍能安立業果的主張，並比對《菩提道次第廣論》所引〈攝決擇分〉三士與《瑜伽師地論》原文的差異。","p":["解脫道與佛菩提道合為三乘菩提、五乘佛法","三乘菩提與世間法皆依阿賴耶識建立","批評月稱、宗喀巴以斷三縛結當作初地","否定阿賴耶識則業果無所依持","瑜伽論三士依律儀等差別而立，非另立道次"],"k":["三士道","阿賴耶識","三乘菩提","菩提道次第廣論","入中論","業果"]},"5029-a20_097":{"s":"本集逐一辨析宗喀巴所立下士、中士、上士道的定義。講者認為下士「唯求生死樂」又「希求自利」自相矛盾，中士「求自靜」不離我與我所，其世俗諦解釋有誤，上士道排除親證如來藏、布施「身無苦」說法不如實，並舉例說明以三士區分修行人會產生的過失。","p":["下士道「求自利」與「生死樂」自相矛盾","中士道「求自靜」仍有我與我所","世俗諦須信受本際並觀蘊處界生滅","佛菩提道入門須親證如來藏","以三士判人高下會有過失"],"k":["三士道","世俗諦","如來藏","波羅蜜多","宗喀巴","解脫道"]},"5030-a20_098":{"s":"本集續評宗喀巴「共下士、共中士道」的兩點理由：講者認為「起心」即可為上士與佛說種性不合，四歸依把上師置於三寶之前；又指出解脫道趣向無生，不應說「希求增上生」，初地菩薩留惑潤生亦非求生。最後說明五乘共修人天善法，但二乘修禪定的作意不同於外道。","p":["佛已說聲聞、獨覺、佛種性等四種種性","批評四歸依將上師置於三寶之前","解脫道趣向無生，非求增上生","共下、共中士道無法區分上中下","二乘修禪定為出三界，不共外道"],"k":["三士道","增上生","四歸依","種性","留惑潤生","四禪八定"]},"5031-a20_099":{"s":"本集說明菩薩修四禪八定、證解脫皆依自心如來，不同於外道與二乘，五乘佛法依阿賴耶識而共與不共不相矛盾。講者批評宗喀巴把初地證量拉到七住位以下、混同二乘空相與大乘空性，並評某位當代作者《成佛之道》否定本來自性清淨涅槃、主張「佛法重心在出世」。","p":["菩薩以禪定為工具，上求佛道下化眾生","菩薩依如來藏證解脫，不必滅蘊處界","批評宗喀巴混同二乘空相與大乘空性","四種涅槃不可少本來自性清淨涅槃","自心如來是在世間的出世間法"],"k":["如來藏","四種涅槃","空性","成佛之道","中觀","四禪八定"]},"5032-a20_100":{"s":"本集先解《法華經》「汝等所行是菩薩道」指在場現聲聞相的菩薩，非聲聞乘即大乘。接著列舉以解脫道取代佛菩提道的八種過失，如阿羅漢無人紹繼佛位、辟支佛先入涅槃、階位與時劫不同、所斷煩惱與神通有別，以及否定本來自性清淨涅槃則二乘涅槃也無法成立。","p":["法華「汝等所行是菩薩道」有前提","阿羅漢無人敢紹繼佛位","解脫道四向五果，佛道五十二位三大劫","阿羅漢不斷無始無明與習氣","否定阿賴耶識則解脫道也錯誤"],"k":["佛菩提道","解脫道","法華經","阿羅漢","本來自性清淨涅槃","無始無明"]},"5062-a20_101":{"s":"本集講解《勝鬘經》「無明住地不斷不究竟，不得明解脫味」及心上、得上等上煩惱一段，歸納四個重點。說明無明住地即無始無明、所知障、塵沙惑，與二乘所斷的一念無明（下煩惱）不同；菩薩須斷二障方得明解脫味，並以心上煩惱、得上煩惱舉例說明悟後仍須進修。","p":["無明住地即無始無明、所知障、塵沙惑","一念無明障解脫，無始無明障成佛","未究竟斷無始無明不得明解脫味","心上煩惱：對第八識所知不足","得上煩惱：悟後各地所應證法仍未證"],"k":["無明住地","上煩惱","無始無明","所知障","一念無明","勝鬘經"]},"5063-a20_102":{"s":"本集說明第四個重點：上煩惱唯菩薩能少分、多分斷，唯佛究竟斷。並說明種子是功能差別、又名為界，所知障非種子；但對地上菩薩而言，上煩惱隨眠會現行成為起煩惱。講者批評某位被尊稱導師者將所知障說為種子、將隨煩惱與習氣攝入所知障，並說佛與聲聞所證無別。","p":["上煩惱唯菩薩分斷、唯佛究竟斷","種子是功能差別，又名為界","所知障非種子，地上菩薩時方現行","批評將隨煩惱、習氣歸入所知障","批評佛智與聲聞十智無別之說"],"k":["上煩惱","所知障","種子","煩惱障","習氣","三轉法輪"]},"5064-a20_103":{"s":"本集說明講者所批評的某位導師否定第八識與意根、以七八識為意識細分，指其落入斷見、常見、損減執、增益執。引《大方等如來藏經》、《成唯識論》、《大薩遮尼乾子所說經》說明一切有情皆有如來藏，並列出否定第八識的七種過失，本集詳說否定業力輪迴與否定自性清淨心有染污兩項。","p":["否定第八識與意根落入四種外道見","如來藏經：眾生身中皆有如來寶藏","第八識為一切法所依、涅槃所依","如來藏須於蘊處界中尋覓","否定第八識則不信業力、天堂地獄"],"k":["如來藏","第八識","斷見","損減執","業力因果","自性清淨心"]},"5065-a20_104":{"s":"本集續說否定第八識的其餘五種過失：否定真心有真如自性並視宣說者為神我論、判三轉法輪唯識經為不了義、主張大乘非佛說、貶禪宗悟心為野狐禪，以及把生滅的緣起法當作真實法。講者引《雜阿含經》說明真正緣起須以第八識為因、眾緣和合，並引《佛藏經》提醒違背佛說的果報。","p":["真心有真如性：真實性與如如性","第三轉法輪唯識經典最為究竟了義","大乘法確為佛說","禪宗所傳為教外別傳的如來藏法","緣起須以第八識為因加眾緣"],"k":["如來藏","真如","三轉法輪","大乘非佛說","緣起性空","禪宗"]},"5066-a20_105":{"s":"本集說明否定意根的三種過失：無法解釋眠熟悶絕後醒來、入出滅盡定與中陰入胎，創傷後壓力症反覆出現，以及意識想控制卻不由自主的習氣。又依《中阿含》、《雜阿含》說明意識是意根與法塵為緣所生，細意識亦然，不能來往三世，並批評以意識為常住法屬常見與增益執。","p":["否定意根則無法解釋睡醒與入出滅盡定","意根作主才有中陰身與入胎","創傷壓力與習氣顯示意根作主","意識是意、法因緣生的生滅法","以意識為常住屬常見、增益執"],"k":["意根","末那識","意識","八識論","常見外道","滅盡定"]},"5067-a20_106":{"s":"本集依《勝鬘經》「恒沙菩提智所應斷法皆無明住地所持」，說明兩種無明分為五種煩惱：一念無明含四住地煩惱為下煩惱、煩惱障，障分段生死；無始無明為上煩惱、所知障，障成佛、斷變易生死。強調悟後非即成佛，並說菩薩在人間行道、修心苦行，才能與上煩惱相應而斷除。","p":["一念無明含四住地煩惱，為下煩惱","無始無明為上煩惱、迷理無明、塵沙惑","斷一念無明離分段生死，佛道須斷變易生死","證悟明心不等於成佛","菩薩修心苦行，於人間行道斷上煩惱"],"k":["上煩惱","下煩惱","無始無明","四住地煩惱","變易生死","人間佛教"]},"5068-a20_107":{"s":"本集說明攝受眾生即攝受佛土：在度眾過程中引發上煩惱，並依下品妙觀察智、平等性智觀眾生平等而生慈悲。指出斷上煩惱須依止真善知識，善知識分經典與證悟菩薩兩類；並引《楞伽經》「漸淨非頓」，說明自心現流漸次淨除，以此支持悟入第七住位之說。","p":["攝受眾生中才引發無量上煩惱","證悟轉識成下品妙觀察智、平等性智","斷上煩惱須依止真善知識","善知識分經典與證悟菩薩兩類","楞伽經：自心現流漸淨非頓"],"k":["上煩惱","攝受眾生","善知識","自心現流","楞伽經","第七住位"]},"5069-a20_108":{"s":"本集講無明住地煩惱因熏習邪見而增長，舉講者所批評的密宗四歸依、依人不依法為例。接著說明自然外道「無因唯緣」的主張，以花須有種子為因作比喻，說明萬法須以如來藏為根本因；並批評應成派中觀屬無因論，略介《瑜伽師地論》十七地，說「無上瑜伽」本指諸佛證境。","p":["往世邪見熏習增長無明住地煩惱","批評密宗四歸依與依人不依法","自然外道主張無因唯緣生萬法","花喻：須有種子為因加眾緣","瑜伽即相應，論中分十七地"],"k":["無因論","無明住地","如來藏","應成派中觀","瑜伽師地論","邪見"]},"5070-a20_109":{"s":"本集引《瑜伽師地論》對照：〈聲聞地〉卷27講十二處及增上、所緣、等無間緣，隱覆根本因；〈菩薩地〉卷85明說四緣中「因緣謂諸行種子」，即第八識及其種子。說明如來藏受熏持種使因果不亂、修學不唐捐，並批評多識以《金剛經》論證緣起性空，指有為法如幻須依無為法而說。","p":["聲聞地講眾緣，隱覆根本因","菩薩地四緣：因緣即諸行種子","如來藏受熏持種，因果不亂","否定根本因則修行唐捐","有為法如夢幻須依無為法而說"],"k":["四緣","根本因","瑜伽師地論","受熏持種","無因唯緣","金剛經"]},"5071-a20_110":{"s":"本集引《佛藏經》「一切諸法無生無滅」，說明諸法攝歸實相心時亦無生滅。講者批評某位導師弟子將阿含中的「識」說為靈魂、否定如來藏，並引《央掘魔羅經》「菩薩道謂一切眾生皆有如來藏」與鑽乳求酥之喻，說明阿含已說如來藏；最後批評該導師《勝鬘經講記》誤解上下煩惱。","p":["佛藏經：一切諸法無生無滅","諸法攝歸實相心則無生滅","阿含「齊識而還」之識指本識","央掘魔羅經：眾生皆有如來藏","無如來藏則空修梵行如鑽水求酥"],"k":["如來藏","佛藏經","央掘魔羅經","本識","無因唯緣","上煩惱"]},"5104-a20_111":{"s":"本集講解《勝鬘經》「離一切過惡、得一切功德、法王法主而得自在」一段，講者批評某位法師的註解：離過惡不等於解脫，以金師子、屠夫子修觀為例說明阿羅漢仍有過；得一切功德不等於般若；法王須一切種智圓滿。並說明法身即出生名色與萬法的入胎識如來藏，引經說法王條件，批評以觀想明點代表如來藏。","p":["阿羅漢說法仍有過，非離一切過惡","得一切功德不等於般若","法身即出生名色的入胎識如來藏","法王須一切種智圓滿","批評觀想明點代表如來藏"],"k":["法身","法王","如來藏","一切種智","入胎識","勝鬘經"]},"5105-a20_112":{"s":"本集續說法王須四智圓明、一切種智具足，現今唯釋迦世尊為法主，舉阿羅漢須向佛請法、無人紹繼佛位，說明佛不等於阿羅漢。講者批評某法師以一切清淨、離縛為法身，指出法身是功德所聚的本識，唯如來藏一切時自在；並辨「不染污無知」屬所知障，習氣則屬煩惱障。","p":["成佛四智圓明，具足法身德","佛不等於阿羅漢，阿羅漢須向佛請法","功德聚之法身即本識如來藏","唯如來藏一切時自在","不染污無知屬所知障，習氣屬煩惱障"],"k":["法身","法王","如來藏","不染污無知","煩惱習氣","四智圓明"]},"5106-a20_113":{"s":"本集辨明所知障與煩惱習氣不同。引《楞伽經》說煩惱障為人無我、所知障為法無我；引《大智度論》鎖腳、乳母衣、香器等喻及難陀、舍利弗、畢陵伽的例子說明習氣；指所知障是不與覺知心相應的無始無明，「現非種」。講者批評宗喀巴及某位法師以習氣演化為所知障的看法。","p":["煩惱障即四住地煩惱，斷之證人無我","習氣是煩惱殘氣，如香器餘香","所知障是法界實相所知不足","所知障現非種，明心時破","批評習氣演化成所知障之說"],"k":["所知障","煩惱障","習氣","無始無明","大智度論","八識論"]},"5107-a20_114":{"s":"本集講解《勝鬘經》兩種不受後有智中如來的一種：二乘斷見思惑而出三界，如來兼斷無始無明上煩惱。解釋「爾焰」即心有所渴愛，列五點說明如來與阿羅漢不受後有智的差別，並詳說第一點無上調御與降伏五陰魔、煩惱魔、生死魔、天魔，說明天魔尤其厭惡留在欲界度眾的菩薩。","p":["不受後有即不再受未來世身","二乘斷見思惑，如來兼斷上煩惱","爾焰即心中所渴愛","五點區別如來與阿羅漢的不受後有智","無上調御，具足降伏四魔"],"k":["不受後有智","四魔","爾焰","上煩惱","無上調御","勝鬘經"]},"5108-a20_115":{"s":"本集承接如來與二乘不受後有智的差別，探討後世為何誤認大乘非佛說，歸納為錯誤說法、錯誤考證、未親證如來藏、沒有實修四因，並引須深盜法及《增壹阿含》八關齋、五根經文證佛世已有三乘。結論：二乘以出家相攝眾、易證可明說，大乘多在家菩薩、難證不可明說，故弘傳較晚較難。","p":["如來不受後有仍世世示現，二乘是將滅止生","佛先說解脫道，二轉法輪才弘大乘","講者批評學者、法師考證大乘出自部派","阿含中「識」入胎即指阿賴耶識","增壹阿含已有三乘行、三乘道之說"],"k":["大乘非佛說","三乘菩提","不受後有智","如來藏","阿含經","部派佛教"]},"5109-a20_116":{"s":"本集為《勝鬘經》不受後有智段落的導論，講者依世情、俗理、佛法三面破斥「大乘非佛說」：以西方三聖為情、以巴利寫本十八世紀前幾無保存及阿難更正水老鶴偈為理；再依阿含論證阿羅漢非佛，舉結集三藏、十號、十大弟子各有第一、女身不得作佛等五點。","p":["佛斷二障二死，二乘僅斷分段生死","巴利三藏古寫本幾乎未存，傳誦可疑","阿難糾正年輕比丘誤誦生滅法偈","阿羅漢若是佛，何須結集、何只一號","女阿羅漢多，而女身不能成佛，故羅漢非佛"],"k":["大乘非佛說","阿羅漢非佛","不受後有智","巴利三藏","如來十號","阿含經"]},"5110-a20_117":{"s":"本集續以阿含及律典經文證「阿羅漢非佛」，從第六點講到二十三點：馬陰藏相、瞿低迦六退自殺、婆迦梨、九無學中有退法、迦葉悔過、舍利弗失衣、莎伽陀醉酒、目犍連預言失誤及被打死、十四無記、申恕林樹葉喻、優樓頻螺迦葉自稱無一切智等，說明唯大乘能成佛地不受後有智。","p":["阿羅漢有退轉、自殺、悔過，佛則無","律典記羅漢失威儀、醉酒而制戒","目犍連見前不見後，業報被外道打死","二乘不能答十四無記，未證一切種子識","佛所說法如手中葉，未說如林中葉"],"k":["阿羅漢非佛","一切智","十四無記","不受後有智","大乘非佛說","阿含經"]},"5111-a20_118":{"s":"本集引《增壹阿含》卷一偈證阿含已提菩薩、大乘、六度，並以彌勒菩薩受金縷衣、當來成佛貫通大小乘；介紹《成唯識論》慈氏七因證大乘是佛說；以蘊處界算數行相推論業種無處可持，必有第八識持種；並批評以晚出梵本質疑玄奘譯經及釋法沖之言。","p":["增壹阿含已載菩薩、大乘、六度之名","彌勒為下一尊佛，非聲聞弟子","慈氏七因證大乘經真是佛說","十八界皆生滅，業種須第八識受熏持種","講者批評依晚期梵本質疑玄奘之說"],"k":["大乘非佛說","彌勒菩薩","第八識","成唯識論","算數行相","玄奘"]},"5112-a20_119":{"s":"本集說明玄奘不許舊譯流通的原因：講者指真諦譯《攝大乘論釋》把阿陀那識等同與四煩惱相應的染汙意。並以《瑜伽》六種力及開車串習之例說明意根作主、可現前驗證；聲聞未證圓成實性，如天女散花仍著花相；並批評有相無相唯識、空有之諍，以八不中道指向如來藏。","p":["講者指真諦混淆阿陀那識與染汙意根","六種力修學，串習成就由意根接手","聲聞未證圓成實性，生滅法相混為一","講者批評有相無相唯識、空有之分","八不中道破生滅法，顯不生不滅心"],"k":["意根","阿陀那識","三自性","八不中道","唯識","如來藏"]},"5113-a20_120":{"s":"本集回到《勝鬘經》如來不受後有智經文，解說「出一切世間」（五陰世間、器世間、四聖六凡）、以三自性與四種涅槃對照大小乘，依《成唯識論》卷十釋「不思議法身」與爾焰地，再引《瑜伽師地論》卷五十說十力次第與四無畏，並以《法華經》十如是呼應佛地不受後有智。","p":["如來藏受熏持種，出生根身器世間","佛圓證圓成實性，二乘僅滅遍計執相","法身具體、依、聚三義，五法為性","十力次第與五乘教法相應","四無畏分自利、利他，十如是唯佛能究盡"],"k":["不受後有智","法身","十力","四無所畏","爾焰地","十如是"]},"5144-a20_121":{"s":"本集講解《勝鬘經》二乘不受後有智經文：阿羅漢、辟支佛度生死畏，只斷煩惱障現行，所證僅第一蘇息處。講者評論某法師所說二乘次第斷、次第證，舉弗迦娑、須跋陀羅「善來比丘」證果，說明證果因人往世修行而異，並說三果須斷我見且發起初禪。","p":["二乘不受後有僅斷三界貪愛，未觸所知障","三果須斷我見並發起初禪不退","弗迦娑、須跋陀羅非依次第證四果","比丘意為破煩惱，善來比丘多為久修","解脫道須具足修，斷證次第因人而異"],"k":["不受後有智","解脫道","阿羅漢","善來比丘","初禪","四果"]},"5145-a20_122":{"s":"本集講解「觀第一蘇息處涅槃地」至「聲聞緣覺乘皆入大乘」經文。講者評論某法師對盡智、無生智及金剛喻定的解釋，說明盡智僅知後有永盡，無生智才能為人宣說；二乘無金剛喻定。並以舍梨子為例說明二乘自知自證，再引《法華經》三車喻說二乘是化城，終入大乘佛乘。","p":["盡智與無生智有別，舉周利槃特伽為例","金剛喻定唯佛地有，二乘不得","二乘不愚於法、不由於他、自知有餘","法華三車喻：羊車、鹿車、牛車","二乘只是化城，非定性者終迴小向大"],"k":["一佛乘","盡智","無生智","金剛喻定","法華經","迴小向大"]},"5146-a20_123":{"s":"本集講解「三乘即是一乘」至「究竟法身」經文，說明三乘中唯菩薩乘能成佛，二乘是從大乘析出的部分法。講者批評某法師以荔枝喻解一乘、暗指佛騙人，並引《法華經》方便品、《大薩遮尼乾子所說經》、三車喻及《長阿含》過去佛一會至三會說法，說明唯一佛乘是攝二乘歸大乘。","p":["一乘即無上正覺、涅槃界、如來法身","講者批評法師荔枝喻曲解一乘","諸佛於五濁世方便於一佛乘分別說三","實慧幢王如來佛土只說一乘","過去佛有一會、二會、三會說法"],"k":["一佛乘","三乘","法華經","三車喻","如來法身","五濁惡世"]},"5147-a20_124":{"s":"本集續論三乘即一乘，講者批評某法師以羊車取代大白牛車，把聲聞解脫道當成佛之道、只以不取涅槃與淨化習氣區分大小乘。並逐段評析其註解：略去「彼」字、以二乘智斷等同菩薩無生法忍、佛法不限佛說之論，及引《楞伽經》說無差別法性；講者主張真實平等法性唯是如來藏。","p":["唯一佛乘即大白牛車，羊鹿車為方便","成佛須證如來藏、具一切種智","「彼先所得地」專指二乘所證","二乘果非等同菩薩無生法忍","平等法性在如來藏，阿含已說三乘部眾"],"k":["一佛乘","三車喻","解脫道","佛菩提道","如來藏","無生法忍"]},"5148-a20_125":{"s":"本集講解《勝鬘經》「如來無有限齊時住」一段，說明如來後際等住、大悲無限，是無盡、常住的世間歸依，而阿羅漢有限齊時住、會入涅槃，故非佛。並以法、報、化三身及《法華經》壽量說如來常住；講者批評某法師視如來常住為後人懷念所創、與梵我同化，並引平實導師三點評論。","p":["如來無限齊住，大悲無限安慰世間","應化身示滅，報身壽命無量","能說無盡法、常住法者名善說如來","講者批評法師視如來常住為神化","佛果亦攝道諦，入滅後非斷滅"],"k":["如來常住","無餘涅槃","三身","善說如來","阿羅漢非佛","本際"]},"5149-a20_126":{"s":"本集開始講解《勝鬘經》歸依法與歸依僧經文，先作語譯：法是一乘道，僧是三乘眾，二者皆是少分、有限歸依，究竟歸依在如來。並依《地藏十輪經》說勝義僧七種、在家亦可為僧；談彌勒龍華三會為聲聞會；主張歸依菩薩僧而非聲聞僧，二乘菩提只是佛菩提的副產品。","p":["法即一乘道，僧有聲聞、緣覺、菩薩","勝義僧含佛、菩薩至預流，不限出家","法、僧二依是少分歸依，究竟歸依佛","龍華三會是度聲聞的法會","應歸依菩薩僧，二乘菩提是副產品"],"k":["三歸依","歸依法","歸依僧","勝義僧","一乘道","龍華三會"]},"5150-a20_127":{"s":"本集講「說一乘道法，得究竟法身」，講者批評以離念靈知為悟及否定第八識的六識論。並述世尊成道過程：十因緣逆觀至「齊識而還」，夜半明心證本識，見明星眼見佛性起成所作智而成佛；先施設四聖諦以生眾生大信。說明一乘法身即佛地無垢識，諸佛亦歸依自心如來。","p":["講者批評離念靈知與六識論二類誤導","十因緣逆觀推至本識「齊識而還」","明心證本識，眼見佛性才成佛","先說聲聞道，為令五濁眾生生大信","一乘法身即無垢識，諸佛歸依自心如來"],"k":["一乘法身","無垢識","十因緣","明心","眼見佛性","三歸依"]},"5151-a20_128":{"s":"本集講「三乘眾者有恐怖，歸依如來」等經文，說明三乘僧乃至菩薩皆仍有所畏而須歸依如來；眾生應先由佛調伏，菩薩不搶先示現八相成道。講者強調三寶一體、十方佛法無別，批評以上師高於三寶的四歸依，亦表示正覺不應要人立誓作正覺人；並主張佛法實相不會演變，演變者是錯悟者。","p":["三乘眾皆有恐怖，須歸依如來","眾生先由佛調伏，菩薩不搶先成佛","講者批評以上師高於三寶的四歸依","三寶一體，不可分割歸依","佛法實相不演變，演變出自錯悟"],"k":["三歸依","歸依第一義","三寶一體","四歸依","佛法演變"]},"5152-a20_129":{"s":"本集說明諸佛最後必說《法華經》，以破增上慢與見取見，並述五千聲聞凡夫退席及多寶如來示現證明。依「三乘者入於一乘，一乘者即第一義乘」說明明心證如來藏是大乘見道。講者評某法師把歸依三寶解為歸依眾生自己、以「如來藏性」暗示如來藏為所生，批評其把佛陀人格化。","p":["說法華經是獅子吼，破增上慢見取見","五千退席，多寶如來示現作證","二乘不觸第一義，明心是大乘見道","講者批評「歸依眾生自己」之註","講者批評「如來藏性」說及佛陀人格化"],"k":["法華經","獅子吼","第一義乘","增上慢","明心","如來藏"]},"5153-a20_130":{"s":"本集為歸依法與歸依僧最後一集，講者批評某法師以直覺為真心，主張直覺仍屬意識心所；說明真正自歸依是歸依第八識自心如來，乃至轉成無垢識，非歸依意識自己。並駁「如來藏性」及修後清淨之說，引六祖「自性本自清淨」，最後從無念、不分別善惡、中道與不生不滅三方面對比第八識與意識。","p":["講者指直覺只是意識心所有法","開悟者以公案隱覆密意，留為人處","自歸依是歸依第八識，非意識自己","如來藏本來清淨，非修後才清淨","第八識無念、隨緣任運、具中道性"],"k":["第八識","意識","自歸依","如來藏","離念靈知","中道"]},"5233-a22_020":{"s":"本集接續解說《勝鬘經》作聖諦與無作聖諦：二乘依善知識音聲只能觀行蘊處界範圍的有量四聖諦，斷有為生死；無作四聖諦依無為無作的如來藏而修，知一切受苦、斷一切集，至佛地斷盡變易生死。講者並批評南傳《清淨道論》未談斷我見，及某法師以意識細心、滅相真如避免斷滅。","p":["作聖諦是有量四聖諦，不出蘊處界範圍","生死分有為生死與無為的變易生死","二乘所證無餘涅槃，從大乘看仍是有餘","引《央掘魔羅經》：無作是如來藏義","批評覺音論師與某法師誤會解脫道"],"k":["無作四聖諦","作聖諦","變易生死","如來藏","有餘無餘涅槃","斷我見"]},"5234-a22_021":{"s":"本集依《勝鬘經》二聖諦經文，對比有作與無作四聖諦：二乘聽聞佛說後觀察蘊處界生滅而知苦斷集，所證有量、有為有作，只得兩種涅槃；菩薩在法界實相上用心，經五十二階位斷兩種生死，證四種涅槃。講者並批評學術界某導師認為阿羅漢智證等同佛，強調阿羅漢不是佛。","p":["有作四聖諦是二乘所證，有量、有為有作","二乘依次觀五蘊、十二處、十八界知苦斷集","菩薩依法界實相修，斷分段與變易生死","菩薩證四種涅槃，二乘只證兩種","批評阿羅漢即佛之說，強調阿羅漢非佛"],"k":["無作四聖諦","有作四聖諦","四種涅槃","二乘菩提","阿羅漢非佛"]},"5227-a22_022":{"s":"本集說明有作與無作四聖諦非一非異、非即非離，並以《心經》、三轉法輪及《中論》、《成唯識論》印證。接著解讀「唯如來應等正覺事究竟」經文，分聲聞、緣覺、菩薩下中上品涅槃，詳述聲聞斷我見至四果的次第；講者並批評宗喀巴否定阿賴耶識、以意識為真我。","p":["有作與無作四聖諦非一非異、非即非離","《心經》色空之說即在詮釋兩種四聖諦","三轉法輪對無作四聖諦有隱說與明說","聲聞斷三縛結至五上分結，證下品涅槃","批評宗喀巴以意識為常住真我"],"k":["無作四聖諦","非一非異","斷我見","聲聞四果","心經","阿賴耶識"]},"5229-a22_023":{"s":"本集續講緣覺與菩薩的涅槃法：緣覺先觀十因緣，推究出「齊識而還，不能過彼」之識，再觀十二因緣有支皆可滅，所證為中品涅槃；菩薩經十信、十住、十行、十迴向、十地、等覺、妙覺五十二階位，發起如幻、陽焰、如夢等觀，所證為上品涅槃，唯成佛才究竟證無作四聖諦。","p":["緣覺須先觀十因緣，再觀十二因緣","齊識而還之識是無餘涅槃本際","聲聞下品、緣覺中品、菩薩上品涅槃","五十二階位各階的修證內容","唯佛斷盡兩種生死，究竟無作四聖諦"],"k":["十因緣","十二因緣","緣覺","菩薩五十二階位","無作四聖諦","涅槃"]},"5231-a22_024":{"s":"本集解說「非壞法故名為苦滅」及苦滅的十種體性，講到前七項：二乘以將滅止生滅盡蘊處界而入涅槃，菩薩則證本來自性清淨涅槃，不壞法而度苦；再依次說無作四聖諦無始、無作、無起、無盡、離盡、常住。講者並批評某導師以直覺為悟入真如。","p":["二乘將滅止生，被稱為焦芽敗種","菩薩證本來自性清淨涅槃，不壞法而苦滅","引《成唯識論》說法界實相無始","法界實相於六塵無分別，直覺屬妄心","意識有盡、意根可滅，實相無盡常住"],"k":["苦滅","本來自性清淨涅槃","無作四聖諦","法界實相","無分別","常住"]},"5246-a22_025":{"s":"本集開始講「非壞法故名為苦滅」，先引平實導師語譯，再從眾生執取「有」談起：自出生即貪著財色名食睡等五欲，又建立世間制度、追求名利。以出國旅遊的苦樂參半為例，說明一切「有」都在生住異滅之中，並細述生、病、老、死及愛別離等苦。","p":["引經文與平實導師語譯苦滅之義","眾生自出生即執取五欲種種「有」","以旅遊為例說明得樂過程伴隨苦","一切「有」皆在生住異滅、成住壞空中","生產與嬰兒出生之苦，以及病老死諸苦"],"k":["苦滅","三界有","五欲","生住異滅","八苦"]},"5239-a22_026":{"s":"本集續談苦：死苦之後指出佛法的離苦得樂並非追求五欲之樂，講者批評為五欲而學佛終將走向名利乃至雙修。接著以某甲為例，從持五戒十善生欲界天，到修禪定生色界、無色界，說明三界二十五有皆有壽盡下墮之苦，須漸次教導出離，並留下為何「非壞法」的問題。","p":["佛法離苦是離開五欲所生的苦與樂","欲界天仍有爭戰、五衰相現之苦","色界、無色界壽盡仍會下墮，屬行苦","三界二十五有皆不離生住異滅","眾生執取深重，須依次第漸次引導"],"k":["三界有","苦滅","欲界天","禪定","行苦"]},"5253-a22_027":{"s":"本集回答為何說「非壞法故名為苦滅」：入無餘涅槃後已無有情，無人受苦滅，而如來藏本來無苦。引《央掘魔羅經》「解脫色是佛，非色是二乘」及《雜阿含》善臂別梵天偈，說明能取所取皆是如來藏所生，色法本來清淨，菩薩轉依如來藏，不必滅五蘊也能當體解脫。","p":["無餘涅槃中已無有情，誰證苦滅","如來藏本來無苦，轉依即可不壞法而滅苦","解脫色是佛，非色是二乘","善臂別梵天說貪著金色身仍是煩惱","能取所取皆如來藏所生，色法本清淨"],"k":["苦滅","如來藏","無餘涅槃","解脫色","能取所取空","轉依"]},"5241-a22_028":{"s":"本集說明末法時代佛法被淺化、世俗化與外道化的幾種情形，講者舉例批評：安慧仿《大乘五蘊論》作《廣五蘊論》、將阿賴耶識攝入識蘊；《大乘莊嚴寶王經》被指為偽經而宣揚六字咒；月稱、宗喀巴否定阿賴耶識，廣論立三士道與四歸依；以及把佛法當做人道理或求神通。強調真正入門在親證第八識。","p":["末法破法：仿論自高、暗藏外道法等","評安慧將阿賴耶識歸入識蘊","評《寶王經》與六字咒稱勝過如來","評月稱、宗喀巴否定阿賴耶識與四歸依","佛法入門在親證第八識如來藏"],"k":["末法","阿賴耶識","安慧","宗喀巴","密宗","二主要道"]},"5243-a22_029":{"s":"本集以唯識經典中「牛有角、兔無角」為喻：牛角比喻三界現象法，兔無角比喻依現象虛妄想像的法。二乘只在五蘊現象上觀無我；菩薩證如來藏，以無分別智觀五蘊歸屬如來藏，如浪不離海。講者批評把緣起性空當作能生萬法的空性，即是兔角戲論，並引《入楞伽經》佐證。","p":["牛有角喻現象法，兔無角喻虛妄想像","二乘觀五蘊無常無我，斷我見我執","菩薩證如來藏，觀五蘊歸屬如來藏","不可認離念靈知等意識變相為真我","以緣起性空為能生萬法即兔角戲論"],"k":["牛角兔角","如來藏","緣起性空","無分別智","中道","入楞伽經"]},"5242-a22_030":{"s":"本集就緣起性空提出四個問題，先論前兩項：僅憑業緣、父母、四大等緣不能出生有情，須有入胎識成就壽煖識的命根。講者批評宗喀巴抄《瑜伽師地論》後加入意識結生之說，論證意識由根塵為緣而生、不能入胎持種；依《長阿含》說識是名色之因，即阿賴耶識。並批評某已故法師將如來藏比作神我，另正解《寶性論》。","p":["眾緣和合不能出生有情，須有命根","入胎識須貫穿三世、含藏業種","評宗喀巴主張意識入胎結生相續","《長阿含》緣識有名色：識是因不是緣","正解《寶性論》說佛性是為離五種過"],"k":["緣起性空","入胎識","阿賴耶識","命根","意識","寶性論"]},"5247-a22_031":{"s":"本集說明「若見緣起便見法」的法是如來藏，引《了本生死經》舍利弗「見緣起無命非命為見法、見佛」為證。接著論後兩個問題：五蘊緣起無自性只是現象，真正的空性是阿賴耶識。講者批評某法師對「於無住本立一切法」的解讀，依《維摩詰經》與《金剛經》說無住本即第八識無住心，中道即阿賴耶識。","p":["若見緣起便見法，此法即如來藏","舍利弗：見緣起無命非命即見法身佛","五蘊性空是現象，空性指阿賴耶識","《入楞伽經》說如來藏空與不空","無住本即第八識無住心，乃中道"],"k":["緣起性空","如來藏","阿賴耶識","無住心","中道","維摩詰經"]},"5258-a22_032":{"s":"本集說明中觀是實證阿賴耶識後觀其含攝蘊處界的實相中道觀，並解說《大般若經》卷4「色自性空」、「但假立客名」等經文，指出空性心無生無滅、無染無淨，觀行可除法執。講者批評某法師以性空唯名為中觀核心，認為其否定第八識後成為無因有緣的斷滅見，屬像似佛法。","p":["中觀即證阿賴耶識後的實相中道觀","色自性空指色的自性來自空性心","以玫瑰與美麗為喻，現象不能生法","假立客名的教導在去除法執","評性空唯名否定第八識，落入斷滅見"],"k":["性空唯名","中觀","般若經","阿賴耶識","斷滅見","法執"]},"5255-a22_033":{"s":"本集先辨正一位弘揚六識論法師對如來藏與法身的解釋，講者認為其說法在斷見與常見兩邊之間擺盪。接著進入〈空義隱覆真實章〉，讀經文後區分空性（不空如來藏）與空相（空如來藏所生蘊處界），說明密意隱覆而說的原因，並以「禪字」與悟後無禪味為喻談真實悟入與打探密意的差別。","p":["評在纏離纏、因藏果身無二無別之說","評否定七八識後既斷又常的邊見","引〈空義隱覆真實章〉經文","空性為心體自身，空相為所生萬法","悟後無禪味；打探密意無真實感"],"k":["空義隱覆真實章","如來藏","空性空相","六識論","禪宗","密意"]},"5257-a22_034":{"s":"本集續說〈空義隱覆真實章〉：打探密意不會有智慧受用，空相須依不空如來藏建立；在中間找出如來藏則空、有兩邊都通，並以廬山煙雨浙江潮為喻。接著解釋「如來藏者，一切阿羅漢、辟支佛、大力菩薩本所不見」，說明菩薩須多劫熏習才在七住不退，並談佛陀重視凡夫菩薩勝過阿羅漢。","p":["打探密意無功德受用，須親證","找出如來藏，空性空相兩邊皆通","公開自稱成佛者，連我見都未斷","大力菩薩亦經多劫熏習才證如來藏","凡夫菩薩有菩薩性，佛看重勝過阿羅漢"],"k":["空義隱覆真實章","如來藏","空性空相","明心","菩薩種性"]},"5268-a22_035":{"s":"本集引《金剛經》說明證悟前須在無量佛所種善根、奉事諸佛。接著逐點評析六識論某法師對「如來藏智是如來空智」的註解：講者認為意識夜夜斷滅、不能持種，意根若能持種則可自丟惡業；般若是意識相應法，並以人參各部位功能不同為喻，區分第八識本覺與意識所發起的般若智慧。","p":["證悟前須於無量佛所多聞熏習","評某法師以一切法空性為如來藏","意識夜夜斷滅，不能執持法種","意根亦非持種心，否則可棄惡業","第八識本覺與意識般若智不可混同"],"k":["如來藏","空智","意識","持種","本覺","六識論"]},"5271-a22_036":{"s":"本集續評六識論某法師「無邊功德中主要是般若」與「般若智性與如來藏不二」之說，講者指出無邊功德尚含意生身、成所作智等，並認為其說暗含阿羅漢即佛、大乘經可廢。強調意識不能去到後世，勸其門徒追根究柢，並批評其弟子主張意識不滅，以五位斷滅反駁。","p":["無邊功德不止般若，般若僅大乘入門","評般若智性與如來藏不二之說","認為其說暗示阿羅漢即佛、廢大乘經","勸學人追根究柢，勿做粥飯僧","評意識不滅說：意識於五位斷滅"],"k":["如來藏","六識論","般若","意識","應成派中觀"]},"5266-a22_037":{"s":"本集解說《勝鬘經》兩種如來藏空智中的空如來藏：如來藏離、脫、異一切煩惱藏，雖收藏煩惱種子，卻不與煩惱相應、不被繫縛，也不轉變種子，種子的增減由七轉識決定。以珠寶、蘭花供佛為例，並以「八個兄弟共一胎」偈喻說八識分工，如來藏如看似癡呆的董事長。","p":["空如來藏離、脫、異一切煩惱藏","如來藏收藏供應種子，不與煩惱相應","轉變煩惱種子的是七識心，非如來藏","八兄弟偈：五識、意識、意根、如來藏","清淨自守是本來體性，非修行而得"],"k":["空如來藏","如來藏","煩惱藏","七轉識","八識","種子"]},"5269-a22_038":{"s":"本集解說不空如來藏：如來藏有過於恆沙的不思議佛法與真實自性，凡夫二乘無法思議，唯證悟菩薩能現觀、佛能具足宣說。講者以六識論者對惡報的恐懼為例，說煩惱種子存於如來藏；並說明二乘解脫與生命輪迴都依如來藏，如來藏收藏善惡業種並執行因果。","p":["不空如來藏具過恆沙不思議佛法","以六識論者的恐懼說種子存於如來藏","蘊處界依如來藏而有，二乘依之解脫","前世某甲如來藏出生今世某乙五陰","如來藏收藏業種，緣熟流注執行因果"],"k":["不空如來藏","如來藏","因果","解脫道","心經","輪迴"]},"5276-a22_039":{"s":"本集說明如來藏依本來清淨、本來涅槃的自性執行因果律：同遇八識論正法之緣，講者認為六識論者與信受的菩薩所受果報不同；意識是受報者，如來藏是執行者。並引《中論》「諸法不自生」說明二乘菩提不離如來藏，再以「五百萬花完」譬喻批評「滅相不滅」之說。","p":["如來藏執藏善惡法種，遇緣流注而成果報","意識是因果受報者，如來藏是執行者","二乘所觀蘊處界依如來藏出生，二乘菩提不離如來藏","《中論》不自生、不他生、不共不無因，應知有本來無生法","以五百萬譬喻破「滅相不滅」，滅相亦是無常法"],"k":["不空如來藏","因果律","八識論","中論","二乘菩提","滅相不滅"]},"5259-a22_040":{"s":"本集續講《勝鬘經》「過於恒沙不離、不脫、不異不思議佛法」的不空如來藏：聲聞唯信佛語，緣覺由十因緣逆推名色所從來而推知有根本因；引導師開示說明阿含入胎識即如來藏，並批評意識細心常住說。又以《心經》「無智亦無得」說明如來藏無分別，卻流注三乘智慧。","p":["聲聞唯信佛語知無餘涅槃非斷滅","緣覺由十因緣逆推，知名色必有根本因","阿含入胎識、住胎識即如來藏","批評意識細心、極細心常住之說","如來藏無智亦無得，卻流注三乘菩提智慧"],"k":["不空如來藏","十因緣","入胎識","緣覺","無分別","意識細心"]},"5278-a22_041":{"s":"本集探討「佛為什麼說如來藏」。講者引某六識論法師《以佛法研究佛法》《成佛之道》的說法——將如來藏解為法空性、為誘化畏無我者而方便施設——予以辨正；並依《楞伽經》大慧之問與佛答「我說如來藏，不同外道所說之我」，逐一解釋空、無相、如、法性、涅槃等十二名相，說明如來藏真實常住。","p":["《勝鬘經》如來藏如垢衣所纏的摩尼寶珠","講者辨正以如來藏為緣起性空、方便說的觀點","大慧問：如來藏是否同於外道之我","佛以十二名相說明如來藏不同外道神我","「為斷愚夫畏無我句」不應解為方便施設神我"],"k":["如來藏","楞伽經","神我","法空性","緣起性空","大乘非佛說"]},"5272-a22_042":{"s":"本集比較如來藏與印度梵我。講者針對某法師《如來藏之研究》說如來藏深受印度神學影響，先介紹《奧義書》梵我一如思想，再引《雜阿含》「齊識而還，不能過彼」及《長阿含》識入母胎有名色，說明阿含本說有根本識；並指出商羯羅論梵的矛盾，歸結如來藏各人獨有、可實證，與共有、思想所成的梵不同。","p":["介紹《奧義書》梵我一如的基本概念","佛說「無我如來之藏」，不應稱如來藏我","阿含「齊識而還」：名色由根本識出生","商羯羅說梵無屬性又具意識喜樂，自相矛盾","如來藏各人獨有可實證，梵為眾生共有之思想"],"k":["如來藏","梵我","奧義書","根本識","齊識而還","名色"]},"5281-a22_043":{"s":"本集以「無常是常」為題，辨正某法師把緣起寂滅性說為真如、空性及如來藏，講者稱之為把無常法說成常。以花、汽車、被搶一千萬美元等譬喻說明蘊處界滅則其緣起性空亦隨之不在，並引《楞伽經》兔無角論；又以明鏡影像說明般若經一切法不生不滅須依如來藏而說。","p":["講者批評以緣起寂滅性為真如、如來藏","緣起性空依蘊處界而有，蘊處界滅即不在","以兔無角喻說一切法空是虛相非實相","般若經說一切法不生不滅，須依如來藏而說","禪淨班兩年半重在發菩薩性、如實知五蘊斷我見"],"k":["緣起性空","如來藏","真如","兔無角論","斷我見","般若"]},"5277-a22_044":{"s":"本集講如來藏的圓成實性：如來藏具空性與空相，能圓滿成就世間雜染法與出世間清淨法。講者辨正某法師《勝鬘經講記》對圓成實與空、不空的解釋，並依經文說明二乘本所不見、不得如來藏空智，阿羅漢不等於佛；最後強調空與不空同體同時，修學應真參實證而非學術研究。","p":["空性是如來藏心體，空相是所生蘊處界","圓成實性具足世出世間染淨諸法","講者批評以阿羅漢即佛、緣起性空為不空","二乘未壞一切煩惱藏，維摩詰探病為例","空與不空同一心體、因地即如是，應真修實證"],"k":["圓成實性","空如來藏","不空如來藏","空性","阿羅漢","實證"]},"5283-a22_045":{"s":"本集講《勝鬘經》〈空義隱覆真實章〉：空義有空性（不空如來藏）與空相（空如來藏），佛於三轉法輪中依次第隱覆密意而說，《解深密經》說恐凡愚分別執為我。以拈花微笑說明教外別傳，以香嚴擊竹、圜悟克勤等例說明善知識不明說密意的用意，並引《大寶積經》戒勿向不信者說。","p":["空性為不空如來藏，空相為空如來藏","三轉法輪依次第說，不為凡愚明說本識","拈花微笑：教外別傳仍是隱覆而說","香嚴、圜悟例：不說破是護人法身慧命","未證者修解脫道須先信第八識常住"],"k":["空義隱覆真實","空如來藏","不空如來藏","教外別傳","密意","三轉法輪"]},"5285-a22_046":{"s":"本集回顧空、不空如來藏後，進入《勝鬘經》〈一諦章〉「四聖諦三是無常，一是常」的經文白話。說明四聖諦是解脫道中心，依四諦現觀斷三縛結證初果，乃至斷五上、五下分結成阿羅漢；解脫果是佛菩提道的基礎。再引《中阿含》舍利弗廣說苦諦、集諦（愛內六處）與滅諦。","p":["〈一諦章〉：苦集道三諦入有為相，非第一義","四聖諦現觀斷三縛結，證須陀洹乃至阿羅漢","《瑜伽師地論》煩惱障淨智所行真實即四聖諦","證如來藏以初果為前提，入地以慧解脫為前提","舍利弗說苦諦、集諦愛內六處、滅諦斷捨"],"k":["四聖諦","一諦章","初果","斷三縛結","解脫道","內六處"]},"5286-a22_047":{"s":"本集續講舍利弗所說滅諦與道諦八正道，強調正見為導首且最難具足，並批評否定真如的應成中觀已違「不離於如」。介紹《俱舍論》四諦十六心（法智忍、法智、類智忍、類智）的聖諦現觀，以蓮華女見化人無常而出家證果的故事說明四諦，並引《雜阿含》四十四智。","p":["八正道以正見為導首，方向錯則成邪精進","講者批評應成中觀違背「不離於如」","《俱舍論》四諦各生四心，共十六心成聖諦現觀","蓮華女見美人無常而證阿羅漢","四果皆依四諦現觀，另有四十四智等深細觀行"],"k":["四聖諦","聖諦現觀","八正道","正見","十六心","四十四智"]},"5287-a22_048":{"s":"本集說明證果後仍須修習四聖諦：引《瑜伽師地論》出世間道淨惑所緣仍是四聖諦，並分辨染汙惑與淨惑；引《雜阿含》拘絺羅問舍利弗，從求初果直到已證阿羅漢都要思惟五受陰為病、癰、刺、殺、無常、苦、空、非我。並指出集諦難知在只見緣不見因，批評輾轉為因及「業果報系統」之說。","p":["正覺課程以斷身見我見為增上班條件","淨惑所緣仍是四聖諦，分染汙惑與淨惑","各果位乃至阿羅漢仍思惟五受陰苦空無我","阿羅漢「得未得、證未證、見法樂住」值得深思","批評只見眾緣不見因、業果報系統之說"],"k":["四聖諦","五受陰","淨惑","集諦","阿羅漢","因緣"]},"5298-a22_049":{"s":"本集深入集諦與滅諦：集諦是眾生愛著內六處而蘊集後有苦種，滅諦是斷盡對內六處的愛染。引《雜阿含》說一切即十二入處，並解說六內入、六外入、六識身、六觸身、六受身、六愛身的六六法。強調滅盡五蘊不離「如」，非斷滅；四聖諦是後天學得、隨五蘊而滅的法船，故名安立諦。","p":["集諦：愛著內六處，蘊集未來輪迴業種","一切法即十二入處，外此唯有言說","六六法運作即眾生心行與苦集內容","滅諦不離如如，非外道斷滅","四聖諦如法船，後天安立，故名安立諦"],"k":["安立諦","集諦","滅諦","內六處","六六法","如如"]},"5304-a22_050":{"s":"本集對比安立諦與非安立諦：真如本有、貫通三世三乘，非人為安立，名非安立諦；引《佛性論》說阿羅漢依安立諦觀破煩惱，無明住地須非安立諦觀方能斷，並引《顯揚聖教論》與天魔化車夫問牛的故事。再依《瑜伽論》黑品白品因果建立四諦，及導師開示，說明唯滅諦是常。","p":["真如本來常住，非人為安立，名非安立諦","無明住地非安立諦觀所能破","天魔問牛：佛趣向無六入觸之處","黑品白品因果建立四諦，唯滅為白品果","苦滅諦指無餘涅槃本際，是常、是無為"],"k":["非安立諦","安立諦","真如","四聖諦","滅諦","無明住地"]},"5296-a22_051":{"s":"本集從菩薩實證第一義諦來看二乘四聖諦皆不究竟，屬有餘道；說明二乘入無餘涅槃為方便說，菩薩七住即現觀涅槃本際，初地、三地、八地菩薩有能力入涅槃而因悲願不入。引《不增不減經》「第一義諦即是眾生界……如來藏即是法身」講〈一依章〉，並批評在阿賴耶識外另求所依、以練氣或雙身法求證之說。","p":["由第一義諦觀，二乘四諦皆不究竟","二乘入無餘涅槃是方便說，菩薩當下現觀本際","菩薩有能力入無餘涅槃，因悲願而不入","第一義諦即眾生界、如來藏、法身","阿賴耶識即如來藏，不應另求所依"],"k":["第一義諦","一依章","眾生界","如來藏","無餘涅槃","法身"]},"5301-a22_052":{"s":"本集依《入楞伽經》「第一義諦相諸佛如來藏心」說明如來藏離名字相、境界相、事相相：以張三、李四等名字說明名相非心體本身，以圍棋冠軍及開悟為例說明如來藏不參與事相、不開悟。證悟後智慧轉變即「聖智修行境界行處」；強調大乘證悟唯以如來藏為標的，並批評以緣生性空解〈一依章〉為無因論。","p":["如來藏離名字相，名相只是施設代稱","如來藏離六塵境界相","如來藏離事相相，不參禪亦不開悟","悟後「還是舊時人，不是舊行履」","批評以緣生性空解一依，違有因有緣之教"],"k":["第一義諦","如來藏","離名字相","一依","實相般若","無因論"]},"5309-a22_053":{"s":"本集依《摩訶般若經》《仁王經》講菩薩摩訶薩住二諦說法、於第一義中常照二諦。說明須先修世俗諦斷我見，再證第一義諦；佛度人有施論、戒論、生天之論、諸法無常的常規，違此次第易致退轉謗法。以釀酒、醍醐為喻說明正覺兩年半課程，並強調證悟菩薩須通解脫道，二諦皆依如來藏。","p":["大乘證悟開口見心，一句話可判","菩薩住世諦、第一義諦二諦說法","佛說法常規：施論、戒論、生天論、諸法無常","未斷我見先知密意易退轉謗法","證悟菩薩須通二乘解脫道，二諦依如來藏"],"k":["二諦","第一義諦","世俗諦","斷我見","說法次第","菩薩摩訶薩"]},"5295-a22_054":{"s":"本集先說明實相般若智慧，並指出世俗人、斷見者乃至山河大地皆依如來藏，故一依含攝世出世間法。接著白話解說〈顛倒真實章〉「不思議是滅諦」經文：此滅諦非凡夫心識所緣、非二乘智慧境界，如生盲、七日嬰兒；凡夫落於常見、斷見二邊。並說明滅諦有世俗、五陰無常、涅槃等層次，斷我見是基礎。","p":["實相般若：現觀萬法從如來藏出生","眾生、器世間皆以如來藏為一依","〈顛倒真實章〉：不思議滅諦非凡夫二乘境界","凡夫於五受陰妄想計著，生常見斷見","滅諦有層次，斷我見是實證大乘滅諦的基礎"],"k":["不思議滅諦","顛倒真實章","一依","常見","斷見","實相般若"]},"5313-a22_055":{"s":"本集說明大乘滅諦「過一切眾生心識所緣」：菩薩不斷思惑而證本來自性清淨涅槃，引《大集大虛空藏菩薩所問經》等說眾生本來涅槃，非二乘所知。指出三乘皆有四聖諦而深淺不同，詳解生盲不見雪白、七日嬰兒不見日輪二喻；並說菩薩可令阿羅漢自知不知涅槃本際，再為其建立信心。","p":["菩薩不斷煩惱證菩提，現在即在涅槃中","引經說一切有情本來涅槃","三乘皆有四聖諦，深淺廣狹不同","生盲、七日嬰兒喻凡夫二乘不見大乘滅諦","二乘不落斷常，卻不知真正離二邊的境界"],"k":["大乘滅諦","本來自性清淨涅槃","無餘涅槃","阿羅漢","四聖諦","中道"]},"5293-a22_056":{"s":"本集講《勝鬘經》常見與斷見。講者評論南傳法師以「無記」迴避涅槃是否斷滅的問題，說明佛說無記是因問者尚未斷我見；並說明中道無邊寬廣，阿羅漢所知甚少；五受陰成五盛陰而生邊見。解說「見諸行無常是斷見」，批評某法師否定如來藏而立意識細心常住，並以《西遊記》人物比喻八識。","p":["佛說無記，因問者連我見都未斷","中道無邊寬廣，阿羅漢只知離二邊","凡夫貪愛五受陰，成五盛陰而生邊見","否定如來藏說諸行無常即落斷見","意識細心仍是意法為緣生，以西遊記喻八識"],"k":["斷見","常見","無記","五受陰","意識細心","中道"]},"5315-a22_057":{"s":"本集續講常見與斷見：引《雜阿含》「諸所有意識，彼一切皆意、法因緣生」，指某法師雙具斷常二見。解說「見涅槃常是常見」，批評宗喀巴以雙身法樂觸為俱生樂、涅槃之說，並說明外道五現涅槃及無想天外道。再解「於有相續不見，起於斷見」：須觀五陰虛妄並信受或親證本識常住，方離二邊。","p":["諸所有意識皆意法因緣生，含極細意識","批評以雙身法樂觸為涅槃，屬五現涅槃之一","以初禪至四禪覺知心為涅槃，仍是意識境界","無想天外道未斷身見，非無餘涅槃","觀五陰虛妄並信本識常住，方離斷常二邊"],"k":["常見","斷見","五現涅槃","意識","本識","離念靈知"]},"5319-a22_058":{"s":"本集講解《勝鬘經》「妄想見故，於心相續，愚闇不解；不知剎那間意識境界，起於常見」，說明眾生不知意識剎那變異而誤認意識為常，故起常見；並指出斷見外道深心仍依常見。講者批評當代多位法師及大道場皆屬六識論而落於意識，並引阿含「意法為緣生意識」「本識入胎」駁斥阿含無本住法之說。","p":["誤認剎那變異的意識為常住即起常見","常見之過在把生滅法當常，非在主張有常住心","斷見外道深心仍執意識常住，故不能成阿羅漢","講者批評各大道場皆六識論、落意識境界","引阿含意法為緣生、本識入胎，駁無本住法說"],"k":["常見","斷見","意識","本住法","六識論","勝鬘經"]},"5300-a22_059":{"s":"本集續講常見，說明不能悟入者有人走入密宗，並區分依《楞嚴經》修的真密與講者所批評的狂密。指出意識常住邪見最難破，破之則身見可斷，謗如來藏者必未斷我見；接著講「於彼義若過、若不及，作異想分別」，以同修會歷次退轉者為如來藏另立所依為「過」之例。","p":["不信佛說意法為緣生，只信師父則難斷結","講者批評「從正常變不正常」之說","意識常住見破除，身見自然能斷","謗本識、如來藏者必未斷我見","退轉者為如來藏另立所依，屬太過而落回意識"],"k":["常見","斷我見","過與不及","如來藏","離念靈知","密宗"]},"5316-a22_060":{"s":"本集講解《勝鬘經》過與不及而生異想分別、落斷常兩邊。說明對未斷我見者應慈憫並教其辨識意識的特徵；以讀書不求甚解喻遠離過與不及；並談抉擇善知識需靠法緣與世間智，建立三寶信心需一劫至萬劫，盲從的集體意識使人難入正法，異想分別即不如理作意。","p":["斷我見已難，證如來藏更難，應慈憫未斷者","見聞覺知、五位會斷者皆是意識","過是頭上安頭，不及是不離意識","信三寶需一劫至萬劫，關乎世間智與心性","盲從的集體意識造成共業難轉"],"k":["異想分別","過與不及","斷我見","不如理作意","善知識","集體意識"]},"5325-a22_061":{"s":"本集探討邊見：說明邊見屬惡見五利使，為見道所斷，與五鈍使合為六根本煩惱。講者以應成派中觀以無念為中道為例，批評其否定第八識而墮無邊、斷邊，又立意識細心墮常邊；引《六祖壇經》無念開示與《勝鬘經》邊見經文，並說明常見外道與斷見（唯物論）的見解。","p":["邊見屬五利使，見道時斷；五鈍使修道斷","應成派以意識無念為中道，雙墮斷常（講者批評）","壇經：百物不思令念絕即是邊見","常見者以見聞覺知心為往來三世之我","斷見者如刀與鋒利喻，主張死後斷滅"],"k":["邊見","五利使","六根本煩惱","應成派中觀","常見","斷見"]},"5307-a22_062":{"s":"本集續談邊見與邪見，指出邪見滲入將使佛教名存實亡，佛示現親歷外道是教人勿迷信盲從。說明異想分別源於不如理作意，對治在多聞熏習；並解「見諸行無常是斷見」「見涅槃常是常見」，以印順否定如來藏又立意識細心為例，再引出外道五現涅槃，講者批評喇嘛教樂空雙運屬其第一種。","p":["邪見入佛教則與外道無別","離不如理作意之法在多聞熏習","否定如來藏說諸行無常即成斷見","意識細心仍屬意法為緣生，又轉成常見","樂空雙運、離念靈知皆屬外道五現涅槃"],"k":["邊見","邪見","多聞熏習","意識細心","五現涅槃","斷見"]},"5326-a22_063":{"s":"本集詳述外道五現涅槃：以欲界五欲（講者舉喇嘛教樂空雙運）、初禪、二禪、三禪、四禪中的意識境界誤為涅槃，說明皆為依覺知心與定力的生滅、變異、有為法，不同於無為的真實涅槃。並總結斷見常見皆因「於有相續不見」，過為頭上安頭，不及為不離意識。","p":["第一種：欲界五欲享樂，如樂空雙運","初禪、二禪等至位之寂靜被誤為涅槃","三禪身心俱樂、四禪息脈俱停仍是生滅法","斷見者能見五陰虛妄，但不信本識常住","真如無所依，為其找所依即頭上安頭"],"k":["五現涅槃","常見","斷見","四禪","涅槃","異想分別"]},"5334-a22_064":{"s":"本集講異想分別所生的邪見：除斷常二見外，有否定七、八識的減損見，及以滅相為不滅、把二乘解脫高推為大乘的增益見，講者並批評應成派意識細心說。接著講四顛倒，說明佛所說常樂我淨指如來藏，而眾生以意識為常樂我淨；最後談邪見是十惡業根本，舉持咒殺生之說為例。","p":["減損見：否定第七、八識，成十七界","增益見：說滅相不滅，以二乘道為成佛道","四顛倒：以意識無常為常等","佛說常樂我淨依如來法身，非五陰","邪見是十惡業之根本，如持咒殺生說"],"k":["邪見","減損見","增益見","四顛倒","常樂我淨","十惡業"]},"5340-a22_065":{"s":"本集續講邪見：說明持咒後殺生或食肉即算超度的說法違背因果，邪見會使無知變本加厲。講者批評宗喀巴《廣論》以現象界自性空的緣起性空為究竟，指出佛說緣起須以如來藏為因，否則成無因論；並對達賴喇嘛的明光心最細意識說提出記憶、腦傷、睡眠等質疑。","p":["持咒殺生、食肉超度是違因果的邪見","邪見讓惡業變本加厲，為諸惡之基礎","講者批評《廣論》以自性空為究竟空義","佛說緣起以如來藏為因，非無因而生","質疑明光心最細意識獨立於身之說"],"k":["邪見","緣起性空","廣論","如來藏","意識細心","因果"]},"5331-a22_066":{"s":"本集依《勝鬘經》「如來法身是常波羅蜜、樂波羅蜜、我波羅蜜、淨波羅蜜」，說明阿羅漢未到彼岸：未證所依本識，入涅槃後能依的五陰又滅。並對比菩薩在五陰存在時證得本識而有常波羅蜜，以淨念相繼、隨喜而不起貪說樂波羅蜜，並開始比較聲聞與菩薩所證無我的差異。","p":["到彼岸需所依常住法與能依自己並存","阿羅漢滅盡五陰又未證本識，故無波羅蜜","常波羅蜜：菩薩於五陰在時證本識","樂波羅蜜：隨喜讚歎而轉依如來藏不起貪","聲聞無我在五蘊上，菩薩兼依如來藏空性"],"k":["常樂我淨","波羅蜜","阿羅漢","如來藏","無我","勝鬘經"]},"5338-a22_067":{"s":"本集講菩薩的我波羅蜜：大乘說無我有二層，五蘊無常苦空無我，如來藏亦對一切法不分別故無我，但常住不壞故為真我。說明菩薩需應機解說有我無我；講者評周叔迦質疑玄奘「去後來先作主公」及應成派「不立自宗」，引佛破長爪梵志、惡取空之教，並說五陰與如來藏不一不異。","p":["如來藏不分別一切法，故是無我性","如來藏常住不壞，故又說為真我","依對方落處應機開解有我、無我","應成「不立自宗」同長爪梵志，佛已破之","我到彼岸須真我與五蘊同時並存"],"k":["我波羅蜜","無我","真我","如來藏","應成派中觀","惡取空"]},"5345-a22_068":{"s":"本集講淨波羅蜜：彼岸本然清淨，究竟清淨在佛地，故菩薩不起慢而廣結善緣。說明大乘滅諦可在十八界存在時證得；講者批評一切法緣起性空說、人間佛教的名利取向及樂空雙運，指出三禪樂亦生滅，破意識細心入胎說，並認為否定如來藏者犯謗菩薩藏重戒。","p":["淨波羅蜜本然清淨，究竟在佛地","菩薩知眾生皆當作佛，不起慢、廣結善緣","大乘滅諦於十八界存在時即可證","三禪樂與樂空雙運皆生滅，無樂波羅蜜","否定如來藏即謗菩薩藏（講者說）"],"k":["淨波羅蜜","常樂我淨","滅諦","緣起性空","意識細心","菩薩戒"]},"5330-a22_069":{"s":"本集講《勝鬘經》「正見者是佛真子」：真子是能挑起如來家業、不入無餘涅槃而得佛一切法財者；說明二乘淨智於滅諦非境界。接著介紹依法、依義、依了義、依智四依，詳講依法不依人：以善財參訪為例，評一師一道之說，引經論說抉擇善知識，二乘證果須有相應功德，菩薩依法即依如來藏。","p":["正見者是佛真子，能荷擔如來家業","二乘淨智觀五蘊，於滅諦尚非境界","依法不依人：善財五十三參為典範","證初果須有欲界定、四不壞淨、七聖財","菩薩依法即轉依如來藏清淨涅槃"],"k":["四依","依法不依人","佛真子","滅諦","善知識","初果"]},"5335-a22_070":{"s":"本集續講四依其餘三項。依義不依語：由文字般若入實義般若，佛拒以雅語修飾佛經，名詞一詞多義、第八識多異名，並談拈花微笑的教外別傳。依了義：引《大般涅槃經》嬰兒大人喻，舉以二乘論否定大乘之例。依智不依識：舉玄奘說明中百二論與瑜伽不相違，及身語意業以智為先導。","p":["依義不依語：由文字般若轉入實義般若","佛允許隨各國語言誦習佛經","了義不了義：以嬰兒與大人為喻","玄奘論《中論》《百論》與瑜伽不相違","菩薩身語意業皆以智為先導"],"k":["四依","依義不依語","依了義不依不了義","依智不依識","玄奘","文字般若"]},"5348-a22_071":{"s":"本集為「四依的祕密」首集，先界定四依，再講依了義不依不了義：依《大般涅槃經》，聲聞乘為不了義、大乘為了義，因二乘只觀蘊處界、滅除自我而不證實相。以阿羅漢、辟支佛答不出無餘涅槃中境界為例，說明解脫道非成佛之道；並述平實導師寫《真實如來藏》回應如來藏是外道神我之說。","p":["四依是學佛的判斷準則","聲聞乘不了義，大乘證如來藏為了義","修解脫道實為滅盡自我，非覺知心常住","阿羅漢不知無餘涅槃本際，新悟菩薩能知","解脫道若即成佛之道，佛世應有眾多佛"],"k":["四依","依了義不依不了義","解脫道","無餘涅槃","如來藏","阿羅漢"]},"5364-a22_072":{"s":"本集說明了義是依如來藏常樂我淨而建立。依義不依語方面，講者批評某大師對世俗諦與第一義諦的解釋，並說真如法性是法界最大祕密，以上帝、大梵天實即如來藏為喻，佛經隱覆密意而說。依智不依識方面，指出以理智解釋為落於識情，阿羅漢在菩薩前仍屬依識。","p":["依了義的祕密在如來藏常樂我淨","講者批評某大師對第一義諦的誤解","般若實證以證真如、親證如來藏為準","一神教的上帝、大梵天實即如來藏","阿羅漢依識、菩薩依智，禪語旁人難懂"],"k":["四依","依義不依語","依智不依識","真如","如來藏","密意"]},"5366-a22_073":{"s":"本集講依法不依人：法指三乘菩提，二乘須斷我見我執，佛菩提須親證第八識。舉佛面對外道之例，說明質疑者自身反而依人；談禪門勘驗，指出真正的法是無覺無觀的如來藏。總結四依依常樂我淨，終歸一依如來藏，並解「三乘初業不愚於法」，說明滅諦非斷滅空。","p":["我見是執見聞覺知心為常不壞我","要求他人依法不依人者，常自身依人","所依之法是無覺無觀的如來藏","四依依常樂我淨，終歸一依如來藏","滅諦是蘊處界滅後如來藏獨存，非斷滅"],"k":["四依","依法不依人","如來藏","常樂我淨","滅諦","我見"]},"5358-a22_074":{"s":"本集解「此四依者是世間法」與「一依者一切依止，出世間上上第一義依，所謂滅諦」。說明二乘世俗諦道理極成，但名色仍依本識；以佛先說施論、戒論、生天論再說解脫法為例，說二乘可思議。並指出一依如來藏是一切法所依、即大乘滅諦，二乘滅諦因不知本際仍有疙瘩。","p":["四依須在三界中言說，故為世間法","世俗諦道理極成，但仍依本識而有","佛先說施、戒、生天論，再說解脫法","二乘經思惟可證，屬可思議法","阿羅漢不知本際所在，非真實滅諦"],"k":["一依","滅諦","世俗諦","四依","如來藏","第一義諦"]},"5355-a22_075":{"s":"本集說明大乘菩提不可思議，證得一依如來藏才能通達唯識，並解玄奘真見道功德勝相見道之說。以算術之「一」喻如來藏，說萬法歸一、大乘滅諦依一而立。講者批評某法師對「萬法歸一」的解說，並評某法師《勝鬘經講記》將如來藏解為佛地功德性及「此」字之解，引唐譯入流智為證。","p":["大乘菩提不可思議，證如來藏方能通唯識","真見道是相見道基礎，故功德較勝","如來藏如算術之一，萬法由此而起","講者批評將萬法歸一解為不要分別","四依之此指二乘淨智，唐譯作入流智"],"k":["一依","如來藏","滅諦","真見道","唯識","萬法歸一"]},"5350-a22_076":{"s":"本集講空不空如來藏：空包括諸法緣起的空相及如來藏的空性，如來藏無形無色故說空性，又有寂滅義；如來藏有真實自性並持續運作，故名不空。講者區分如來藏自性與落在六識見分、自證分、證自證分的自性見外道，引《雜阿含》聖法印與《楞伽經》說明，並說如來藏本來自性清淨。","p":["空分空相（蘊處界）與空性（如來藏）","如來藏有真實自性運作不斷，故名不空","自性見外道皆落在六識自性上","如來藏離見聞覺知、離思量，非六識自性","不淨種子屬七識，如來藏本來清淨"],"k":["空不空如來藏","空性","如來藏","自性見","見分自證分","楞伽經"]},"5370-a22_077":{"s":"本集承上集說如來藏本來自性清淨、具足空與不空，進入《勝鬘經》〈自性清淨章〉，先通釋「生死依如來藏」至「依持建立」整段經文。講者強調真實佛法可實證而非想像，舉阿含中佛問阿難「識不入胎有名色否」說明名色依入胎識而有，並批評應成派中觀主張意識能生名色。","p":["如來藏本來自性清淨，不淨種子屬七識","空與不空同在一途，故名〈自性清淨章〉","生死依如來藏，本際依如來藏而說","離念靈知會斷，非真如佛性；聲聞法不等於佛法","識入胎、住胎方有名色，非識陰六識"],"k":["如來藏","自性清淨","勝鬘經","名色","入胎識","離念靈知"]},"5341-a22_078":{"s":"本集依「意法為緣生意識」破意識（細心）出生名色之說，說明名色的生死以及病、老都依如來藏而有。講者批評「種子由意識執持」的主張：若意識持種便會丟棄惡種而無惡道；唯有無記性的如來藏能平等持種、為生死本際。最後解釋「有如來藏故說生死，是名善說」。","p":["意識依意根法塵而生，不能出生名色","生老病死都依如來藏，熱水藥物只是助緣","意識若持種將棄惡種，惡道便不存","如來藏無記性，平等持善惡種為生死本際","依有如來藏說生死者是善說法者"],"k":["如來藏","持種","生死本際","意識細心","善說","無記性"]},"5352-a22_079":{"s":"本集解釋經文「生死者諸受根沒」與「死者謂根壞，生者新諸根起，非如來藏有生有死」：生死依五色根壞滅與新起而說，中陰身亦有微細五色根，如來藏本身無生死。再釋「如來藏離有為相」：如來藏離六塵見聞覺知卻非無知，有六塵外的本覺，與自性見外道所說六識自性不同，因不領受六塵而無貪厭與煩惱相。","p":["受根即五色根，根壞為死、新根起為生","中陰身仍有微細五色根，故有意識","如來藏離六塵見聞覺知，但非木石無知","如來藏本覺在六塵外，異於外道六識自性","不領六塵故無貪厭；世人求名財清譽"],"k":["如來藏","五色根","生死","離有為相","本覺","見聞覺知"]},"5368-a22_080":{"s":"本集續釋「如來藏常住不變，是故如來藏是依、是持、是建立」。講者批評主張阿賴耶識是生滅法、須滅之方開悟者，引《入楞伽經》說阿梨耶識名如來藏，並列舉部派與禪宗對此心的異名。再分述：一切法依如來藏而存；意識會斷且常忘事，不能持種，唯如來藏持種；意識由根塵為緣從如來藏生，故一切法依之建立。","p":["離六塵故離貪厭，如眠熟無夢時","阿賴耶識名如來藏，不可滅，常住不變","部派與禪宗以種種異名指同一第八識","意識眠熟即斷、常忘事，不能持種","根塵意識皆從如來藏出，故如來藏是建立"],"k":["如來藏","阿賴耶識","常住不變","持種","依持建立","入楞伽經"]},"5365-a22_081":{"s":"本集說三乘菩提皆以真如如來藏貫穿：二乘涅槃是如來藏獨存，成佛須證真如並圓滿一切種智。說明第八識因真實又如如而名真如，引《大乘起信論》「以言遣言」辨真如與六識緣起性空的不同；再依《占察善惡業報經》分辨真心與妄心，並說眾生果報皆依諸佛法身（如來藏）而有、建立、生長。","p":["二乘涅槃為如來藏獨存，解脫道是方便道","第八識真實且如如不動，故名真如","起信論：真如是言說之極，非有可遣","占察經：真心如如遍一切處，妄心虛偽","七住明心證真如，至一切種智皆依如來藏"],"k":["真如","如來藏","真心妄心","大乘起信論","占察善惡業報經","一切種智"]},"5383-a22_082":{"s":"本集說明如來藏是一切萬法的根本因。依《成唯識論》「無始時來界」一偈解釋種子識為諸法所依、諸趣與涅槃所由；說如來藏不生不滅、不垢不淨等中道體性；依《瑜伽師地論》四緣說「因緣」即常住心所藏的諸行種子；並以其無覆無記、受熏持種的自性說三世因果，兼引《維摩詰經》及阿賴耶識、異熟識、無垢識名稱之別。","p":["成唯識論「無始時來界」偈釋種子識","如來藏具不生不滅等中道體性","瑜伽四緣：因緣為根本因，餘三為眾緣","無覆無記、受熏持種，三世因果不亂","依階位名阿賴耶、異熟、無垢，心體不變"],"k":["根本因","如來藏","種子識","成唯識論","四緣","中道"]},"5359-a22_083":{"s":"本集依玄奘、窺基判教介紹五時三教，並引《解深密經》三時說：初轉阿含為「有教」、二轉般若以隱密相說為「空教」，皆屬有上有容未了義；三轉唯識以顯了相說第八識，為無上無容的真了義。講者並說阿含中已隱說本識，引《央掘魔羅經》「菩薩道謂一切眾生皆有如來藏」，說明二乘涅槃與菩提都依如來藏而立。","p":["五時三教；三轉法輪為有、空、中道教","初轉二轉有上有容，三轉無上無容了義","阿含以本識、入胎識隱說第八識","央掘魔羅經：無如來藏則空修梵行","於內無恐怖者成阿羅漢，因信有本識"],"k":["三轉法輪","五時三教","解深密經","了義","如來藏","央掘魔羅經"]},"5385-a22_084":{"s":"本集說明涅槃的本際：阿含中佛隱說有一眾苦所依的本際，故阿羅漢入無餘涅槃不是斷滅，緣覺亦知「齊識而還」之識；二轉以無住心等名說，三轉明說其種種名稱與體性。並依《大智度論》說煩惱習氣與所知障非二乘所斷；比較阿含、《中論》、《勝鬘經》對「本際」的說法，再依《增壹阿含》六界說識界即入胎識，非六識。","p":["阿含隱說本際，阿羅漢涅槃非斷滅空","緣覺觀十因緣知有齊識而還之識","二乘未斷習氣與所知障，菩薩須斷","本際不可知是對凡夫二乘而說","增壹阿含六界之識界即入胎識，非六識"],"k":["涅槃本際","入胎識","無餘涅槃","所知障","六界","阿含"]},"5360-a22_085":{"s":"本集解釋第八識何以名阿賴耶識：因具能藏、所藏、我愛執藏的阿賴耶性；斷煩惱障後改名異熟識，佛地名無垢識，心體始終同一。依《大乘起信論》說此識能攝一切法、能生一切法，並以正覺總持咒解說五位百法；再以三界結構與《華嚴經》「心如工畫師」說三界唯心，以入胎生根、變生內六塵、流注六識說萬法唯識。","p":["阿賴耶性：能藏、所藏、我愛執藏","斷煩惱障名異熟識，佛地名無垢識","起信論：此識能攝、能生一切法","總持咒五位百法皆由阿賴耶識出生顯示","心如工畫師；直接、間接、輾轉生萬法"],"k":["阿賴耶識","五位百法","三界唯心","萬法唯識","異熟識","無垢識"]},"5386-a22_086":{"s":"本集由《集論》的有為法定義，說明如來藏無生住異滅、離有為相且常住不變；並指出前世意識若入胎將無法安住胎中，故每世意識都是新生。講者說同一如來藏貫穿聲聞、緣覺、般若與唯識增上慧學，強調學佛先須見道與正見，引《華嚴經》「佛法無人說，雖慧莫能了」，最後提出《金剛經》四句偈常被解為「放下、一切皆空」的問題，留待下集。","p":["集論：有生住異滅者為有為法","如來藏不住六塵，故能安住母胎","每世意識皆新生，不能造色","一個如來藏貫穿三乘菩提無矛盾","佛法無人說雖慧莫能了，須善知識"],"k":["離有為相","如來藏","常住不變","正見","善知識","金剛經"]},"5362-a22_087":{"s":"本集依《金剛經宗通》說四句偈的前提是「不取於相，如如不動」，即依如如不動的如來藏觀有為法如夢幻泡影，否則成無因唯緣的緣起性空。引《中阿含》鹿子母堂空盡牛馬仍有比丘眾的譬喻，說明真實空是蘊處界空而如來藏不空。再述聞思修三慧（《大毘婆沙論》）、《心地觀經》四法，並引犢子外道問目犍連、迦旃延如來滅後有無的公案。","p":["四句偈前提是不取於相、如如不動","緣起性空須依如來藏，否則無因唯緣","鹿子母堂喻：空盡諸物，比丘眾不空","聞思修三慧，正見為因、正智為果","犢子外道問目犍連、迦旃延如來滅後"],"k":["真實空","金剛經","鹿子母堂","聞思修","善知識","如來藏"]},"5384-a22_088":{"s":"本集續說犢子外道再問世尊，所得回答與兩位尊者全同，因而讚歎佛與弟子「義同義、句同句、味同味」（《雜阿含經》卷34），講者據此說佛法以如來藏為所依而法同一味。接著依《瑜伽師地論》解說法隨法行與菩薩實修要點，說菩薩修真實空勝解而不速入涅槃；最後以龍樹《中論》「四不生」偈說萬法以無生的如來藏為根本因。","p":["佛與弟子答犢子外道全同，法同一味","外道各說各話，佛門答案前後吻合","法隨法行：不止聽聞，須如說而行","菩薩修真實空勝解，不速取涅槃","中論四不生：萬法以無生如來藏為因"],"k":["法同一味","法隨法行","犢子外道","四不生","中論","如來藏"]},"5377-a22_089":{"s":"本集以無著菩薩《大乘阿毘達磨集論》說空相、空、空性：蘊處界中無常住的我與我所故空，但同處另有無我而有自性的法，名為空性，與鹿子母舍譬喻相符。並分析五蘊假我由藏識為因、眾緣假合而成；說「如」的兩層意涵；再引《雜阿含經》卷12的因緣法、緣生法與「此法常住，法住法界」，說十二因緣依常住法而起。","p":["集論：蘊處界無常住我故空","同處有無我而有自性者，名空性","五蘊假我以藏識為因、眾緣假合","「如」：本自在恆存，且不受一切境界","雜阿含：此法常住，法住法界，緣生諸法"],"k":["空性","大乘阿毘達磨集論","緣起性空","因緣法","真如","法同一味"]},"5391-a22_090":{"s":"本集以玄奘法師為例說正法傳承義同義：講《成唯識論》「無始時來界」偈呼應勝鬘「依持建立」，並述《大唐西域記》對印度考古的貢獻、在那爛陀作《會宗論》、以「我曹釋子終不害人」收攝順世外道及曲女城無遮大會。再介紹覺囊派篤補巴的「他空」與《山法》、格魯派的長期打壓；講者認為篤補巴契合佛旨，並批評宗喀巴之說悖離佛法。","p":["成唯識論偈：種子識為一切法等依","大唐西域記助印度佛教遺址挖掘","會宗論融合般若唯識；不害順世外道","曲女城無遮大會立真唯識量","篤補巴他空說；覺囊派遭格魯派禁絕"],"k":["玄奘","成唯識論","他空","覺囊派","法同一味","如來藏"]},"5380-a22_091":{"s":"本集講《勝鬘經》的六法與心法智：分辨外我所與內我所，以五遍行、五別境心所舉欣賞書法、重遊等例，說六識自性即內我所；心法智亦有人解為末那識。講者說七法剎那生滅，正因有如來藏才有造惡受苦而厭苦求涅槃；斷見者心底實為常見；以「涅者不黑、槃者不白」說涅槃中道，並引《楞伽經》說如來藏非聲聞緣覺境界。","p":["外我所為身外法，內我所為心所法","遍行、別境心所使六識了別六塵","心法智：六識心所，或解作末那識","有如來藏才有苦果，故厭苦求涅槃","涅槃中道：涅者不黑、槃者不白"],"k":["六識","心所法","心法智","涅槃","中道","斷見"]},"5372-a22_092":{"s":"本集說「如來藏無前際」：如來藏本來就在、從未出生；講者批評「另有一心出生阿賴耶識」之說會導致無窮後退，並舉阿含「齊識而還，不能過彼」為教證。再釋經文「不起不滅法；種諸苦，得厭苦、樂求涅槃」：如來藏不受苦樂，厭苦求涅槃的是六識與心法智；最後依《大乘起信論》說意根執第八識為我的無明熏習，分根本熏與見愛熏。","p":["如來藏無前際，本來而有、從未出生","若另有心生阿賴耶識，將無窮推演","教證：齊識而還，不能過彼","如來藏不起不滅、不受苦，六識厭苦","起信論無明熏習：根本熏與見愛熏"],"k":["如來藏","無前際","不起不滅","厭苦求涅槃","無明熏習","大乘起信論"]},"5408-a22_093":{"s":"本集釋「如來藏非我、非眾生、非命」：講者回應如來藏是外道神我的說法，指神我、梵我是有喜怒的意識，如來藏則離見聞覺知；明心即知人無我，屬法智類智。眾生依五陰定義，如來藏在三界六道都不變，故非眾生；命根在阿含為壽暖識和合，在大乘為心不相應行法，如來藏是命根之源而無壽算。並以嚴陽問趙州「放下著」說參禪須斷意識我見的命根。","p":["如來藏非外道神我梵我，離見聞覺知","明心證人無我，得法智類智","眾生依五陰定義，如來藏處處不變","命根：阿含壽暖識和合；大乘屬不相應行","參禪斷命根：嚴陽問趙州放下著"],"k":["如來藏","非我","非眾生","命根","人無我","參禪"]},"5397-a22_094":{"s":"本集承上說命根依如來藏而有，「所謂命根，即非命根，是名命根」；又說如來藏非人，舉佛答外道「我是佛」、雲門答「如何是佛」等，說轉依如來藏的菩薩非人。再釋「墮身見、顛倒、空亂意眾生非其境界」，先講墮身見：以色身或覺知心為常住我，包括離念靈知與能見能聞之性；講者引《佛藏經》批評未斷身見的法師，強調證如來藏須先斷身見。","p":["命是三位差別所顯，依如來藏而有","如來藏非人；佛答外道「我是佛」","如來藏甚難證，三種眾生非其境界","般若通則吃飯即非吃飯，是名吃飯","身見執色身或覺知心為我，須先斷"],"k":["命根","身見","斷我見","如來藏","禪宗公案","般若"]},"5410-a22_095":{"s":"本集講墮顛倒見的眾生：外道把五陰歸於上帝、大梵天、冥性、自然等，講者認為實為各人的如來藏，並舉比丘問大梵天的經中故事。又批評六識論者立意識細心、極細心為常住，以「諸所有意識，彼一切皆意法因緣生」破之。再引般若經佛問善現一段，說真如是阿賴耶識所顯的自性，不能反過來出生阿賴耶識，並論唯識性與唯識相的關係。","p":["上帝、梵天、冥性之說實指如來藏","比丘問大梵天，梵天推說不知","意識細心極細心仍是意法因緣生","真如是阿賴耶識所顯性，非能生之體","先證唯識性，再修唯識相；八地捨賴耶名"],"k":["顛倒見","真如","阿賴耶識","意識細心","六識論","唯識"]},"5456-a22_115":{"s":"本集依《八識規矩頌》、《成唯識論》與《勝鬘經講記》說明意識具善、惡、無記三性，並指出有六識論者把自性清淨心解為意識、主張無記是心本性，講者認為不正確。並以五趣受生、黑白業與百法心所說明三性會隨因緣轉變，意根與如來藏才屬無記。","p":["意識三性三量通三境，是修行關鍵","批評六識論者以意識為無記本性之說","人趣情想均等，心性決定五趣受生","黑白黑白異熟業顯示善惡間雜","意根有覆無記、如來藏無覆無記"],"k":["意識三性","善惡無記","如來藏","五趣","八識規矩頌","百法"]},"5447-a22_116":{"s":"本集說明自性清淨心如來藏是三乘菩提的根本，二乘人若不信有如來藏，會因內外恐怖而無法斷我見。並以三法印、《法華經》、《華嚴經》說明三轉法輪都以如來藏為核心，再依菩薩五十二階位，介紹凡夫性的十信位與習種性的十住位。","p":["否定如來藏則無佛法可修證","於內恐怖與於外恐怖的差別","三法印須依如來藏才能印定","根本無分別智屬意識，非如來藏所得","十信位修除異生性，十住位修六度、參禪"],"k":["如來藏","自性清淨心","斷我見","五十二階位","十信位","十住位"]},"5461-a22_117":{"s":"本集接續介紹菩薩七類種性：性種性的十行位長養聖性、修集福德；道種性的十迴向位以破邪顯正救護眾生，並說明入初地須永伏性障、修集廣大福德、具初分道種智並發十無盡願。最後解說《勝鬘經》「自性清淨心而有染污難可了知」經文與禪門「走江湖」的由來。","p":["十行位轉依如來藏、長養菩薩性","十迴向位以金剛行救護眾生離四相","入初地三條件與十無盡願","自性清淨心與其染污二法難知","走江湖源自參訪馬祖、石頭"],"k":["十行位","十迴向位","入地條件","自性清淨心","勝鬘經","明心開悟"]},"5470-a22_118":{"s":"本集講禪宗為中國佛教主流，其「不立文字、教外別傳」源自世尊的機鋒，禪宗開悟即親證如來藏，並推介大慧宗杲看話禪。接著說明如來藏自性清淨而含藏染汙種子，兩個難知之法歸結為難以找到如來藏，並談明信、斷內外恐怖與發菩薩性。","p":["教外別傳與機鋒最早出自世尊","禪宗開悟即證如來藏、般若現前","如來藏清淨，染汙種子與五蘊相應","趙州「與一切人煩惱」隱覆密意","證悟須發菩薩性、修福德與智慧"],"k":["如來藏","禪宗","教外別傳","看話禪","自性清淨心","菩薩性"]},"5445-a22_119":{"s":"本集講解《勝鬘經》〈真子章〉，說明能荷擔如來家業（法與次法）者才是佛的真子，定性聲聞阿羅漢不是，並分廣義、狹義真子。接著解釋「隨信增上、依明信、隨順法智」經文與五種巧便觀，強調明信須靠多聞熏習與法義辨正，並舉香林遠禪師十八年開悟公案。","p":["如來家業包含法與次法","阿羅漢不能荷擔家業，非真子","廣義真子證悟不退，狹義須入地","明信靠多聞熏習與比對法義","香林遠侍雲門十八年始悟"],"k":["真子章","如來家業","明信","隨順法智","勝鬘經","禪宗公案"]},"5458-a22_120":{"s":"本集說明證得如來藏後須先有法智忍、才有法智，再隨順法智深入現觀，以完成相見道而入初地。並逐一解說隨順法智的五種功德：觀察施設根意解境界、觀察業報、觀察阿羅漢眼、觀察心自在樂與禪樂，以及觀察二乘與大力菩薩的聖自在通。","p":["先有法智忍，後有法智","真見道、相見道至通達位入地","通達十八界，深信因果離無記愚","心自在樂與悟後靜慮的禪樂","入地菩薩能證涅槃而不取證"],"k":["法智忍","隨順法智","相見道","初地","無記愚","聖自在通"]},"5472-a22_121":{"s":"本集說明入地菩薩須經真見道、相見道，滿足非安立諦三品心與安立諦十六品心、九品心並發十無盡願；強調要斷除以意識為常住真我的見解。並解釋《大般若經》依第四靜慮證真如是指最後身菩薩，不是所有三賢菩薩都須證四禪，也引《成唯識論》說明真如是第八識的真實性。","p":["三大阿僧祇劫：遠、近、大波羅蜜","真見道後須修相見道三品心","斷除意識是常住真我之見","依第四靜慮證真如指最後身菩薩","真如是心真實性，即第八識"],"k":["入地","見道","第四靜慮","真如","斷我見","第八識"]},"5452-a22_122":{"s":"本集講修道正因：一切法的根本因是第八識如來藏，舉安世高所譯阿含經已說入胎識，並說色彩明暗皆如來藏變現。講者批評主張造物主的宗教是不平等因，並說明靜坐、苦行非真法。另述菩薩十種習氣、《瓔珞經》七住不退須善知識護持，及《成唯識論》見道即證解阿賴耶識。","p":["如來藏是一切法的根本平等因","講者批評造物主之說自相矛盾","如來示現靜坐、苦行皆非正道","菩薩的善根、見佛、大願等習氣","見道即證解阿賴耶識，名為明心"],"k":["如來藏","修道正因","阿賴耶識","見道","菩薩習氣","八識論"]},"5474-a22_123":{"s":"本集講如來常住：阿含經已說有入胎識，《楞伽經》說阿賴耶與意根一同入胎，故意識斷滅而七、八識仍相續。講者批評覺音論師在《清淨道論》剔除名色之外的識。並說阿羅漢入滅後第八識仍在，二乘涅槃如化城，如來具十力，不等同阿羅漢。","p":["阿含經已說入胎識與名色相依","阿賴耶與意根俱往下一世","講者批評覺音論師否定入胎識","二乘涅槃是化城，終須迴向佛道","如來十力非二乘所及"],"k":["第八識","入胎識","意根","如來十力","二乘涅槃","名色"]},"5449-a22_124":{"s":"本集依《勝鬘經》說明三種善男子、善女人：成就法智（無師智的聖位菩薩）、隨順法智（依善知識證悟發起根本智）、仰惟如來（雖不能自知但不毀謗）。並述玄奘傳唯識、禪宗在中國廣傳，講者批評密教雙修之說。另說明真如即能生諸法的法身心體，宗門與教門須相輔，並舉大慧禪師語談眼見佛性。","p":["成就法智者具無師智","隨順法智者依善知識證悟","仰惟如來者不毀謗大乘法","大乘法因禪宗而在中國延續","真如即法身，宗門教門相輔"],"k":["隨順法智","仰惟如來","護持正法","禪宗","真如","眼見佛性"]},"5462-a22_125":{"s":"本集講真實佛法須得如來讚歎：發菩提心、護持正法、如教修行。講者反駁大乘非佛說，指出假設有一族人代代編寫大乘經的說法無法自圓其說，並以如來十力、彌勒受記說明有超過二乘的法。再引《思益經》水王之喻、《大般若經》與《持世經》，說明穢土護持正法的功德與受記。","p":["如來讚歎發心、護法、如教修行","反駁大乘經為後人編造之說","如來十力證明有超越二乘之法","菩薩如大海水王，護法至最後","穢土護法須臾勝淨土一劫"],"k":["護持正法","大乘非佛說","如來十力","末法","菩提心","授記"]},"5440-a22_126":{"s":"本集進入《勝鬘經》最後〈勝鬘章〉，說明女眾也能證如來藏，並解說十五種經名中的前兩種：《歎如來真實第一義功德經》讚歎如來證實相法身的真實功德與第一義功德；《不思議大受經》對應十大受，說明前五受屬攝律儀、其次四受屬攝有情、第十受為攝受正法。","p":["證如來藏與男女、在家出家無關","真實功德依法界實相如來藏而有","二乘緣起性空非實相、非究竟","十大受歸攝於菩薩三聚淨戒","攝受正法不忘失即不忘大乘"],"k":["勝鬘章","如來真實功德","十大受","三聚淨戒","攝受正法","如來藏"]},"5467-a22_127":{"s":"本集續講〈勝鬘章〉經名：《一切願攝大願經》說明十大受攝為三大願，具足大智、大悲、大勇；《說不思議攝受正法經》說明諸願歸攝為攝受正法一大願。並以大雲雨、大水聚、大地荷四重擔、大地四寶藏四喻，說明攝受正法即正法、即波羅蜜，以及捨身命財的功德。","p":["三大願具足大智、大悲、大勇","一切願歸攝於攝受正法","攝受正法即破邪顯正、救護眾生","依根器授人天、聲聞、緣覺、大乘法","攝受正法即波羅蜜，須教眾生自修"],"k":["攝受正法","三大願","波羅蜜","勝鬘章","破邪顯正","勝鬘經"]},"5454-a22_128":{"s":"本集講《說入一乘經》，說明二乘法由大乘方便分出，正法住滅、戒律都依大乘而說；阿羅漢心有怖畏而歸依如來。並解說分段生死與不思議變易生死、四住地煩惱與無始無明住地，說明二乘只得有餘功德，唯如來斷盡無明住地，三乘歸於一乘。","p":["二乘法從大乘方便分析出來","阿羅漢有怖畏，故依於如來","分段生死與變易生死之別","四住地煩惱與無始無明住地","三乘攝歸唯一佛乘"],"k":["一乘","無始無明住地","變易生死","四住地","涅槃","勝鬘經"]},"5476-a22_129":{"s":"本集續講〈勝鬘章〉第六至第十一個經名：無邊聖諦、說如來藏、說法身、空義隱覆真實、一諦、常住安隱一依。說明二乘聖諦智只是入門，出世間上上智才是第一義智；作聖諦與無作聖諦的差別；空如來藏與不空如來藏；四聖諦中唯苦滅諦是常，為究竟所依。","p":["佛菩提聖諦無量無邊","作聖諦有量，無作聖諦唯佛究竟","如來法身即不離煩惱藏的如來藏","空如來藏與不空如來藏","唯苦滅諦是常，為一依"],"k":["四聖諦","無作聖諦","空如來藏","法身","滅諦","勝鬘經"]},"5463-a22_130":{"s":"本集講完〈勝鬘章〉最後四個經名：《說顛倒真實經》說明斷常二見與四顛倒，並以常樂我淨與四依說明一依是滅諦；《說自性清淨心隱覆經》說明生死皆依如來藏；《說如來真子經》重述真子的定義；《說勝鬘夫人師子吼經》說明佛可以是阿羅漢，但阿羅漢不是佛，《勝鬘經講記》至此圓滿。","p":["斷見常見皆因不知實相心","如來法身常樂我淨為正見","生死依如來藏，如來藏無生死","三種善男子是不同階段的真子","阿羅漢不可等同於佛"],"k":["四顛倒","斷常二見","常樂我淨","自性清淨心","如來真子","師子吼"]},"3641-a16_019":{"s":"本集說明正法難聞，指出靜坐一念不生是定境而非般若，解脫要靠盡智、無生智等智慧。並講息滅的真義在轉依本無煩惱的如來藏，又說明斷見、常見等邪見，以及出離觀要修十二因緣、破除執覺知心為我的無明。講者也批評以解脫道取代成佛之道的「半截佛法」。","p":["禪有二種：修定之禪與明心之禪","解脫正因是智慧，四禪八定只是助因","息滅真義：如來藏本來無煩惱","無明即執覺知心為常住真我","批評半截佛法與佛教分割化"],"k":["出離觀","十二因緣","無明","如來藏","斷我見","禪定與般若"]},"3642-a16_020":{"s":"本集詳說二乘出離觀：觀察蘊處界虛妄，斷我見、疑見、戒禁取見三縛結而證初果，並依次說明二果、三果、四果。講者據初果至三果生天可說法，批評「唯有人間才有佛法」的說法；並引《無上依經》說明阿羅漢入無餘涅槃不是斷滅，仍有本際，以及聲聞與緣覺斷結方法的差異。","p":["三縛結：我見、疑見、戒禁取見","初果至四果的次第與往返","天界亦有佛法，批評人間佛教說","無餘涅槃有本際，非斷滅空","聲聞依四聖諦，緣覺觀十因緣"],"k":["出離觀","三縛結","四果","無餘涅槃本際","十因緣","斷見外道"]},"3682-a16_021":{"s":"本集講安隱觀：菩薩親證一切有情的本來自性清淨涅槃，轉依其體性修行直至成佛，因而具足法身德、般若德與解脫德，二乘只得解脫德。引《勝鬘經》與《法華經‧化城喻品》說明大乘出生二乘，並概述菩薩五十二階位的修行歷程；講者也批評未斷我見卻自稱是佛的人。","p":["安隱觀是菩薩所修，非二乘法","親證本來自性清淨涅槃，心得安隱","三德：法身德、般若德、解脫德","《勝鬘經》：大乘出生二乘法","菩薩五十二階位修行概要"],"k":["安隱觀","本來自性清淨涅槃","五十二階位","三德","化城喻","明心見性"]},"3684-a16_022":{"s":"本集歸納出離觀與安隱觀，說明佛有阿含、般若、方等三時說法，並引《長阿含經》毗婆尸佛多修安隱、出離二觀為證，過去諸佛亦復如是。講者批評達賴喇嘛「三轉法輪互相矛盾」與「小乘為大乘基礎」等說法，並反駁大乘非佛說，引化城喻說明大乘函蓋二乘、比二乘殊勝。","p":["三時說法：阿含、般若、方等","《長阿含》：毗婆尸佛多修二觀","意識不論粗細皆意法為緣所生","反駁「大乘非佛說」","二乘涅槃為化城，大乘函蓋二乘"],"k":["三轉法輪","出離觀","安隱觀","大乘非佛說","化城喻","原始佛法"]},"3693-a16_023":{"s":"本集說明佛在三轉法輪都說到法界實相：阿含隱說為本際，般若明說為無住心、非心心，唯識說為阿賴耶識等異名，實為同一心。接著說明二乘只斷煩惱現行，菩薩還要斷煩惱習氣與所知障，以「畢陵尚慢」為習氣之例；講者並批評人菩薩行之說，以及把習氣等同所知障的主張。","p":["初轉隱說、二三轉明說法界實相","法界實相的種種異名同指一心","批評不證實相的人菩薩行主張","習氣是煩惱殘氣，例：畢陵尚慢","所知障即上煩惱，與習氣本質不同"],"k":["法界實相","三轉法輪","煩惱習氣","所知障","阿賴耶識","人菩薩行"]},"3697-a16_024":{"s":"本集開講《阿含正義》第三章陰界入，先說明大小乘修證架構，以及一念無明（見惑、思惑）與無始無明（所知障、塵沙惑）的區別。接著講六根的意涵：意根是心而非大腦，五根各有扶塵根與勝義根，六根是識陰所依，斷我見應依根、塵、識次第觀行；最後誦《中阿含經》卷58拘絺羅答舍黎子之經文。","p":["小乘滅蘊處界，大乘證真妄和合","一念無明與無始無明的區分","意根是無色根的心，非大腦","五根有扶塵根與勝義根","根塵觸生識，依根塵識次第斷我見"],"k":["六根","意根","一念無明","無始無明","陰界入","斷我見"]},"3701-a16_025":{"s":"本集語譯並解說《中阿含經》卷58五根各受自境、意為彼依、「意依壽住」的經文。以車子為喻比較小乘厭離五陰與大乘了知真妄和合的不同，並討論「意依壽住」：意根貫通三世，不依一期壽命而住；又以睡眠位等論證意根與意識是兩個法，意根只緣極昧略的法塵，經中是小乘方便說。","p":["五根各受自境，意為彼依","車子喻：小乘厭離、大乘知其運作","意根貫通三世，非依壽而住","以眠熟位證意根與意識是兩法","意根只緣極昧略的法塵"],"k":["意根","意識","六根","中阿含經","十八界","眠熟位"]},"3709-a16_027":{"s":"本集講諸根寂靜：根塵相觸時一觸即止、不續生了知，即「守意如城，防六如龜」，並引《別譯雜阿含》與《增壹阿含》說明守護根門、斷內六入的我執。比較菩薩「應無所住而生其心」是如來藏不住六塵；又說明根與識不同類、意根有覆無記、遍緣而無證自證分，並引《起信論》講意根為現識。","p":["諸根寂靜：根塵觸而不生了知","守意如城、防六如龜，斷內六入","如來藏不住六塵而生六塵","根與識不同類、同時並行","《起信論》：意根又名現識"],"k":["諸根寂靜","意根","內六入","現識","我執","無餘涅槃"]},"3713-a16_028":{"s":"本集探討六塵與六入及五欲過患。說明法塵依附五塵，意識所緣函蓋現量、比量、非量與三世，引《瑜伽師地論》說四種愛樂、《華嚴經》說五欲如逆風執火，並強調不放逸。接著區分外六塵與內六塵、外六入與內六入，說明識陰只取自心如來藏所現的六塵內相分，故所見因業報而不同。","p":["意識所緣廣，函蓋三世與三量","五欲無常虛妄，如逆風執火","六塵惡賊，應修不放逸","識陰只取如來藏所現內六塵","眾生業報不同，所見內相分各異"],"k":["六塵","六入","五欲","內相分","不放逸","如來藏"]},"3717-a16_029":{"s":"本集續談六塵虛幻，引《楞伽經》說諸色相皆自心所現如海中波浪。說明內法塵隨人、心情與作意而異，有無明觸與明觸所生受之分；又引論說明想心所搆畫境界，以及想倒、心倒、見倒，並說業報不同所受六塵各異。最後指出知六塵為自心所現便不受拘束，也要了知六根虛妄，以免誤入無想天。","p":["諸色相自心所現，如水現波浪","作意不同，所領受的法塵各異","想心所搆畫境界；想、心、見三倒","業報不同，所領受六塵範圍各異","也須了知六根虛妄，免入無想天"],"k":["六塵虛幻","內六塵","想心所","顛倒想","自心所現","無想定"]},"3721-a16_030":{"s":"本集講能取與所取二俱無所得。說明色法是心王與心所共同顯現的影像，能取的六識要依根塵為緣才現起，彼因彼緣皆無常；能取心必與六塵相應，一念不生並未離開六塵。引《解深密經》、《辯中邊論》、《起信論》與《攝大乘論釋》的渴鹿、夢境之喻，說明能取所取皆攝歸如來藏而平等無所得。","p":["六識依根塵為緣，彼因彼緣皆無常","能取心必與六塵相應，非實相心","一念不生等境界仍是意識","《辯中邊論》：二取俱成無所得","渴鹿逐焰、夢中境喻能取所取"],"k":["能取所取","識陰","內相分","如來藏","辯中邊論","陽焰觀"]},"3725-a16_031":{"s":"本集說明能取與所取應離虛妄分別。引《楞伽經》說不了自心所現便計著能取所取而墮有無見，又引《成唯識論》說二取習氣即我執習氣與名言習氣，名言安立不可遍計執為實。指出斷我見後有初果與證悟兩分不虛妄分別；並說明如來藏離能取所取，菩薩轉依而得安隱，最後解釋五取蘊並引經觀蘊如夢如幻。","p":["不了自心所現，計能所取墮有無見","二取習氣：我執習氣與名言習氣","名言安立不可執為真實自性","兩分不虛妄分別：初果與證悟","五取蘊：欲貪令蘊相續出生"],"k":["虛妄分別","能取所取","二取習氣","遍計所執","五取蘊","斷我見"]},"3729-a16_032":{"s":"本集略說斷我見：我見即以五陰十八界、尤其意識離念靈知為常住我，離念靈知仍屬想陰。強調要有未到地定支撐才能「證轉」，否則只是初果向；證果本質是捨而非得，自稱證果者反未斷我見。並說明三縛結、假必依實的前提、四加行，以及須具足四不壞淨與受持聖戒才是真正初果。","p":["我見：執五陰、離念靈知為常住我","有知即落想陰，離念靈知亦然","須未到地定支撐才能證轉","證果是捨非得","四不壞淨與聖戒成就須陀洹"],"k":["斷我見","三縛結","初果","未到地定","想陰","四加行"]},"3733-a16_033":{"s":"本集講十八界中的六識界，說明「界」是功能差別，並引《中阿含經》卷47十八界。介紹六根，意根是六識共同所依根，意識負責了別而意根作決定；說明法塵由意識了別、六識身的含義，以及意根與法塵為緣、入胎識為根本因而生意識。並詳述外六入、內六入及眼見色的過程，指出十二處是六識的俱有依。","p":["界即功能差別，六識各有界限","意根是六識共同所依根","意識了別，意根作決定","眼見色：如來藏變現內相分","十二處是六識俱有依"],"k":["十八界","六識","意根","內六入","十二處","入胎識"]},"3737-a16_034":{"s":"本集續講六識界，引《雜阿含經》說識受陰即六識身、無常變易，「諸所有意識，彼一切皆意、法因緣生」。詳述《中阿含經》卷54荼帝比丘執「此識往生後世」遭佛訶責的經文，以及佛以火隨所燃得名喻識依根立名。並說明有念、離念等意識變相皆是緣生法，三界各處意識所依根不同，講者批評意識細心常住之說。","p":["識受陰即六識身，無常變易","一切粗細意識皆意法因緣生","荼帝比丘執識往生後世被訶責","識依根立名，如火隨所燃得名","有念、離念靈知皆是生滅法"],"k":["意識","識陰","荼帝比丘","意法因緣生","離念靈知","斷我見"]},"3741-a16_035":{"s":"本集探討阿含與唯識的關係。說明唯識指八識心王，阿含中第七識稱意根，第八識隱說為識、本際、諸法本母，《央掘魔羅經》明說如來藏，《大般涅槃經》已提一切種智；三法印也要依如來藏才能成立。並解說開示悟入佛知見，以及華嚴、阿含、般若、方廣、法華涅槃的五時三教次第。","p":["唯識：一切法唯八識心王所生顯","阿含隱說第七、第八識","諸法本母即入胎識如來藏","三法印須依如來藏印定","五時三教，由淺入深漸次說法"],"k":["唯識","八識心王","如來藏","五時三教","一切種智","三法印"]},"3745-a16_036":{"s":"本集依《中阿含經》〈象跡喻經〉說明五陰和合：內眼處、色與眼識屬色陰，另有覺、想、思、識四陰，並解說各陰定義與五陰無常故無我、何以稱五盛陰。接著語譯經文，詳述地、水、火、風內外四界，說明色身是本識攝取四大、空大與動能聚合而成，以房屋喻色身是假名，陰為遮蓋、蘊為聚集。","p":["〈象跡喻經〉：觀五陰和合聚會","受想行三陰依色、識二陰而起","五陰無常故苦，苦故無我","內外地水火風四界皆無常","房屋喻：色身是假合之名"],"k":["五陰","色陰","四大","五盛陰","無我","象跡喻經"]},"3749-a16_037":{"s":"本集說明五塵與法處所攝色也攝屬色陰，並逐一說明色身不是上帝、大梵、冥性、四大、父母或自然所造。引《長阿含經》卷10「緣識有名色、緣名色有識」，說明入胎識以其大種性自性執受受精卵、攝取四大造色身，即第八識如來藏，阿羅漢入無餘涅槃後便不可尋。最後引《羅云忍辱經》說佛法背俗、真悟者少。","p":["五塵與法處所攝色攝歸色陰","色身非上帝、梵天、冥性、父母所造","緣識有名色、緣名色有識","入胎識以大種性自性造色身","佛法背俗，真悟者少"],"k":["入胎識","名色","色陰","如來藏","大種性自性","無餘涅槃"]},"3753-a16_038":{"s":"本集續講五陰略說，依《增一阿含經》卷28五盛陰經文解釋色、受、想、行、識各陰定義，強調「想亦是知」、識能「識別是非、亦識諸味」，指出離念靈知屬識陰與想陰。並說明我見最難斷在識陰、想陰，以及學人不能善擇善知識的種種原因。","p":["入涅槃即滅盡十八界自我，覺知心不能入住","增一阿含卷28：寒熱飢渴皆色陰所攝","想即了知，未起苦樂受的了知性已是想陰","離念靈知是識陰所攝的意識，非常住心","我見難斷因不了識陰，又不善擇善知識"],"k":["五陰","斷我見","離念靈知","想陰","識陰","增一阿含經"]},"3757-a16_039":{"s":"本集講五陰的緣起，引《中阿含經‧象跡喻經》「若見緣起便見法」，說明二乘只見意、法為緣生識的表相緣起，菩薩則從如來藏現觀緣起。並辨析緣因與根本因，指出萬法須有因有緣，持種心必是不間斷的本識，最後略述緣起自性與遍計所執性。","p":["五盛陰從因緣生，根壞則識不得生","二乘見表相緣起，菩薩依如來藏見真緣起","阿難說十二緣起淺而被佛訶責","無明等只是緣因，入胎識才是根本因","眠熟後業種不失，證有常住持種心"],"k":["緣起","如來藏","入胎識","十二因緣","遍計所執性","中阿含經"]},"3763-a16_040":{"s":"本集為探討識陰能否去到後世而先說八識心王，介紹玄奘菩薩《八識規矩頌》與曲女城立真唯識量，強調八識具足、所滅是阿賴耶性而非心體。並引《雜阿含經》說明五陰背後必有本際，評析「了知生老病死虛妄當下即如來」之說落於無因、斷滅。","p":["玄奘造八識規矩頌，八識不多不少","曲女城立真唯識量，破邪顯正","滅阿賴耶性非滅心體，後名異熟、無垢識","雜阿含卷6：眾生無明所蓋，不知本際","不識本心學法無益，須先親證本際"],"k":["八識心王","八識規矩頌","阿賴耶識","本際","六識論","玄奘"]},"3767-a16_041":{"s":"本集說明識陰不能去到後世，指出這是了生死的關鍵見地。依阿含「識因緣故起，有緣則生、無緣則滅」說明六識是緣生法，五位中斷滅，且每世所緣五色根不同故不記前世；並引《中阿含經》荼帝比丘執識往生不更異而被佛訶責之事。","p":["二乘斷分段生死，大乘兼斷變易生死","識陰即六識身，眾生於此妄見有我","識有緣則生，無緣則滅","每世五色根不同，故不憶前世","荼帝比丘執識往生不異，遭佛訶責"],"k":["識陰","了生死","斷我見","荼帝比丘","中阿含經","緣生法"]},"3771-a16_042":{"s":"本集講五陰與五盛陰的差別，引《中阿含經》卷28說明正觀、正覺及「癰、癰本、癰一切漏」，以世間追求自我為例。再依卷58法樂比丘尼答毗舍佉：有漏有受即盛陰，無漏無受則非盛陰；斷我見我執後五陰不再熾盛。講者並評析「做自己」等教導仍落五盛陰。","p":["正觀六更觸，正覺三受的習滅味患出要","癰是色身，癰本是欲愛色愛無色愛","肯定自我、展現自我即世間的癰本","有漏有受是盛陰，無漏無受非盛陰","斷我見我執後，五陰不再稱五盛陰"],"k":["五盛陰","五陰","三愛","有漏","斷我執","中阿含經"]},"3775-a16_043":{"s":"本集講四識住與七識住。依《大集法門經》說識陰住於色、受、想、行四境，喜行廣大增長，並以日常生活舉例。再依《長阿含經》卷9說七識住，從欲界人天到無所有處；另說非想非非想與無想天二處，指出這些仍是三界流轉境界，不應貪著禪定法味。","p":["四識住：識於色受想行生、緣、住","貪苦樂、貪了知、貪活著皆是識住","七識住：欲界人天至無所有處","非想非非想、無想天二處亦屬生死","能取所取未離，非涅槃無境界"],"k":["四識住","七識住","識陰","五盛陰","四禪八定","長阿含經"]},"3779-a16_044":{"s":"本集為「如來藏非外道神我、梵我」第一講，辨正以色為神我。引《別譯雜阿含經》犢子事說神我死此生彼是凡夫見，如來斷五陰如斷多羅樹；依「非我、不異我、不相在」及《中論》說明色與如來藏關係。再引阿含、《寶積經》、《瑜伽師地論》說明色身由入胎識藉父母精血而成，非上帝所造。","p":["外道神我皆執無常變異法為真我","如來斷五陰不復受生，是無生法","色非我、不異我、不相在","緣識有名色，識不入胎則無名色","色身差別由業感，入胎識所造"],"k":["外道神我","如來藏","入胎識","色陰","羯羅藍","本際"]},"3783-a16_045":{"s":"本集為外道神我第二講，辨正以受、想、行、識為我的外道。引《長阿含經》說三受依觸而生滅如鑽木取火，並述自性受與境界受及觸食觀；想如陽燄、行如芭蕉；識陰依根塵而生、不能去到未來世，引《佛開梵志阿颰經》說輪迴。結論是斷我見須觀五陰一一虛妄。","p":["三受因觸緣生，觸滅受亦滅","受分自性受與境界受，斷觸食則三受斷","六想身、諸行皆生滅，非真實我","識陰依根塵而生，不能去到後世","觀五陰虛妄是斷我見的先決條件"],"k":["外道神我","斷我見","五陰","三受","觸食","識陰"]},"3787-a16_046":{"s":"本集為外道神我第三講，先述布吒婆樓梵志以色身無常為我，佛示染汙可滅、清淨可生。講者批評某法師把如來藏說成方便說、富外道神我色彩，並引《楞伽經》佛說如來藏不同外道我、陶家喻，及勝鬘空與不空如來藏、《不增不減經》三法、《入楞伽經》如來藏非剎那不住為證。","p":["布吒婆樓：染汙法可滅，清淨法可生","講者批評如來藏方便說之論為謗佛","楞伽經：如來藏不同外道所說之我","空如來藏與不空如來藏","如來藏非剎那不住，是如來所證法"],"k":["如來藏","外道神我","楞伽經","不增不減經","空如來藏","勝鬘經"]},"3791-a16_047":{"s":"本集為外道神我系列末講，辨正梵我與一神教上帝，指其最多為天主、仍在輪迴。引《大般若經》卷578一切有情皆如來藏等四藏、《央掘魔羅經》謗如來藏之過；再以《長阿含經》說大梵天自認造物主的由來、《百喻經》及大梵天不知四大何由滅，證明造有情者是各人如來藏。","p":["上帝最多是忉利天主，自身仍輪迴","一切有情皆如來藏、金剛藏、正法藏、妙業藏","輕慢、誹謗如來藏的過患","大梵天因先生而自認為眾生之父","名色因是第八識，非意識的梵我"],"k":["梵我","如來藏","外道神我","大梵天","大般若經","央掘魔羅經"]},"3813-a16_052":{"s":"本集總論四食：摶食、觸食、意思食、識食。先說有情由六界和合而生，識界即入胎識而非識陰六識，並批評某法師把識界解為有取識。再說四食在三界各地的分布，指出離念靈知仍有觸食、意思食、識食，以此為悟皆未出三界；斷我執須具足四食觀行。","p":["四食長養有情，關乎生死與解脫","六界和合生身，以識界入胎識為中心","識界在六識之前，非識陰六識","欲界具四食，色界三食，無色界識食","離念靈知不離三食，非涅槃心"],"k":["四食","六界","入胎識","識食","離念靈知","斷我執"]},"3817-a16_053":{"s":"本集講四食中的摶食，即欲界入口之食，依《瑜伽師地論》說於變壞時建立、屬香味觸處所攝。並述各洲及龍、阿修羅、欲界天的摶食，《長阿含經》地味與人間摶食起源，佛應身亦受人間食而無貪。以食子肉喻說斷摶食之貪，並批評密宗以五肉五甘露為修行。","p":["摶食須消化變壞能長養才成食","欲界有情皆有摶食，色無色界則無","人因貪地味而身光消失、失神足","佛應身受人間食，示現而無貪愛","食子肉喻：受食不貪味，斷五欲貪"],"k":["摶食","四食","欲界","斷我所","厭離食想","雜阿含經"]},"3821-a16_054":{"s":"本集講觸食，依《成唯識論》說觸境為相，從男女觸、沐浴、衣觸到身內外微細覺受皆是。粗觸由意識領受、微細觸由意根領受；色界禪悅、卵生有情中亦有觸食。以剝皮牛喻說斷觸食，並批評某法師把觸食判為物質而自語相違，及密宗雙身法貪著細滑觸。","p":["觸食即六根觸六塵的領受長養","內外身覺：粗屬意識，細屬意根","色界天以禪悅身心樂觸為觸食","卵生有情初期唯意根觸食","剝皮牛喻：斷觸食則三受斷"],"k":["觸食","四食","意根","細滑觸","禪悅","雙身法"]},"3825-a16_055":{"s":"本集講意思食（念食），即意識、意根思惟念想長養自身。以冬眠及冰凍蛙類為例，分意根與意識同在、意根獨存兩類，並說入胎、卵中皆靠意根念食。再依《雜阿含經》說五蓋與七覺分的有食無食，指出熏習即食，唯佛地離食；以大火聚喻說斷意思食則三界愛斷。","p":["冬眠、凍結動物以意根思食存命","卵生、入胎初期唯意根念食長養","五蓋、七覺分皆依食而起、增廣","食即熏習，只有佛地是離食境界","大火聚喻：斷意思食則三界愛斷"],"k":["意思食","四食","意根","五蓋","七覺分","無餘涅槃"]},"3829-a16_056":{"s":"本集講識食與八背捨。先說識食是本識所現法為食，地獄眾生與無色天以識為食；地獄是內相分如夢而無醒時，並列各識之食。再說四禪八定與無想定仍有食，屬三界有，故須修八背捨；依《中阿含經》卷42說初禪須具五支與身樂，依次講到第四背捨入空無邊處。","p":["地獄眾生、無色天純以識食存活","地獄是內相分，受苦無醒時","四禪八定、無想定仍屬三界有","初禪須五支具足並有胸中樂觸","初禪至空無邊處，識著法味不住內"],"k":["識食","八背捨","四禪八定","初禪","地獄","中阿含經"]},"3833-a16_057":{"s":"本集續講八背捨，從識無邊處、無所有處到非想非非想處，說明非想非非想只是不返觀自己，了知性仍在。斷我見後滅意識而入滅盡定，若煩惱障已斷即俱解脫。再引《中阿含經》卷10說惡人至有愛、善人至明解脫的展轉具成，強調熏習成種即識食，親近善知識至關重要。","p":["第五至第七背捨：識處、無所有、非想非非想","非想非非想僅不返觀，了知性仍在","滅盡定成就，斷煩惱障即俱解脫","親近惡知識展轉具成有愛","熏習成後有種子即識食之集"],"k":["八背捨","識食","滅盡定","俱解脫","善知識","中阿含經"]},"3837-a16_058":{"s":"本集說第八識非有食非無食，食相屬前七識。引《中阿含經‧分別觀法經》說心出外灑散與心不住內，指出執著禪定或離念靈知仍是識食。意根把六識功能據為己有而不肯滅，見聞覺知性生起即是識食。講者批評南北傳大法師落於意識，並強調依止真善知識、斷我見為首要。","p":["第八識非有食非無食，藏七識食種","識著色樂、法樂相則心出外灑散","見聞覺知性正運作時即有食相","意根執六識功能為己，不願滅除","依止真善知識，斷我見是首要之務"],"k":["識食","意根","離念靈知","斷我見","善知識","第八識"]},"3841-a16_059":{"s":"本集為識食與八背捨末講，說識食使中陰後再入胎，斷識食者可中般涅槃。引《雜阿含經》卷15頗求那問佛「識是食」，說明了知即識食，並以六入、觸、受、愛、食集的關係說滅除之道，以三百矛喻觀識食。最後辨析慧解脫、俱解脫與身證，指出未斷我見即使證四禪八定也不能永背捨欲界。","p":["識食使中陰後再入胎，斷之可中般涅槃","識是食：了知六塵即識陰之食","六入集則觸、受、愛、四食集","三百矛喻觀識食，斷名色貪愛","未斷我見，證禪定亦不能永離欲界"],"k":["識食","八背捨","慧解脫","俱解脫","中般涅槃","斷我見"]},"3845-a16_060":{"s":"本集依《阿含正義》說明欲證聲聞解脫須滅除四食，引《雜阿含經》卷14講四食的如實知、食集、食滅與食滅道跡（八聖道）。並指出斷四食須依本識如來藏，否則成斷滅空；又以唯識熏習說明識食，講者並批評以清楚明白、處處作主的意識為真心之說為惡法食。","p":["三界有情皆依四食而存，欲界四食、色界三食、無色界唯識食","依本識真實恆存斷四食貪愛，方不落斷滅空","識食即唯識熏習之理，種子執藏於阿賴耶識","以八聖道為食滅道跡，具足四食的四聖諦","遠離惡知識與惡法食，依法不依人"],"k":["四食","識食","四聖諦","如來藏","熏習","斷我見"]},"3849-a16_061":{"s":"本集說明四食與佛菩提道修證的關係：二乘以滅盡四食入無餘涅槃，大乘菩薩則有四食而無食集，藉四食留惑潤生、成就一切種智。並引《雜阿含經》四不壞淨的安樂食，及《央掘魔羅經》說如來藏離食常堅固、諸佛解脫有妙色。","p":["二乘以滅四食為前提，只成阿羅漢不能成佛","大乘有四食而無食集，藉四食留惑潤生","四不壞淨為安樂食，利益二乘與菩薩","如來藏執藏二種生死種子，亦說為有食","《央掘魔羅經》：摩訶衍離食常堅固"],"k":["四食","佛菩提道","一切種智","留惑潤生","如來藏","四不壞淨"]},"3853-a16_062":{"s":"本集講十二因緣中「名色緣識」的識，指往世識陰六識及意根，與十因緣「齊識而還」的第八識入胎識不同。引《增壹阿含經》卷30說明十二有支皆是假號法、因緣法，並指出若無如來藏儲存無明業種，往前推究將成無窮過。","p":["行緣識、識緣名色的識是識陰六識","六識不願斷滅，故不斷入胎再取名色","講者批評教人保持覺知心不滅為鞏固我見","十二有支是假號法，依因待緣而起","須以十因緣的入胎識為前提，免無窮過"],"k":["十二因緣","名色緣識","假號法","識陰","入胎識","斷我見"]},"3857-a16_063":{"s":"本集續說十二因緣支皆為假號法，因分根本因（如來藏）與方便因（前支為緣）；引鑽木求火喻說明因緣和合。並說四聖諦含攝十二因緣、八正道、三十七道品，大乘依實相法界自性說四聖諦，四聖諦與因緣觀皆有三乘差別。","p":["有因有緣的因含根本因與方便因","鑽木求火喻：火不從木出亦不離木","現觀六識及其十二因緣皆假號法可斷我見","四聖諦含攝因緣法，並有大乘四聖諦","假號法十二因緣的識指六識，十因緣的識指第八識"],"k":["十二因緣","假號法","根本因","四聖諦","如來藏","斷我見"]},"3861-a16_064":{"s":"本集開始講十因緣之名色緣識，指出十二因緣須先經十因緣觀才能實證。引《長阿含・大緣方便經》阿難以為十二因緣淺易而佛斥其甚深，並說「見緣起即見法」的緣起是如來藏；講者批評《唯識學探源》以十支、十二支僅為詳略不同及以流轉還滅總括佛法之說。","p":["十二因緣須先經十因緣觀方能實證","講者批評十支與十二支僅詳略不同之說","《大緣方便經》：十二因緣甚深難見","無明只是緣，如來藏才是根本因","《大寶積經》先說空性法再說甚深緣起"],"k":["十因緣","十二因緣","大緣方便經","緣起","如來藏","根本因"]},"3865-a16_065":{"s":"本集續講《大緣方便經》，述如來逆推、順推十二因緣，並詳說十因緣中由貪愛生追求、利益、欲著、嫉妒、看守、持護乃至刀杖諍訟的次第，及名色緣觸。講者並批評某法師以看災難片放下世間、主張意識活著往生極樂之說，指出意識依根身而生、不能往來三世。","p":["十二因緣須以十因緣為前提才有還滅門","貪愛→追求→利益→欲著→嫉妒→持護→諍訟","名色具足方有根塵觸，因觸生三受","講者批評意識活著往生、看災難片放下之說","《中阿含》：意處壞則意識不生，意識不往來三世"],"k":["十因緣","大緣方便經","名色","意識","斷我見","緣起"]},"3869-a16_066":{"s":"本集解說《大緣方便經》「緣識有名色、緣名色有識」：識不入胎、入胎不出或嬰孩敗壞則無名色，此識是入胎識而非六識，並引三蘆相依喻與「齊識而還，不能過彼」。講者批評以緣起為關係、理則之說（《唯識學探源》作者及宗喀巴應成派），主張緣起根本是如來藏。","p":["入胎識與名色相依，此識非識陰六識","三蘆相依喻說明識與名色輾轉相依","齊識而還：因緣法推究至入胎識為止","講者批評緣起為關係或理則之說","如來藏因性自性是緣起的根本因"],"k":["十因緣","入胎識","齊識而還","緣起","大緣方便經","應成派中觀"]},"3873-a16_067":{"s":"本集續講《大緣方便經》慧解脫比丘知如來終、不終，以及「不知不見，如是知見」，說明是指涅槃本際離見聞覺知，並引《維摩詰經》「法不可見聞覺知」。又述三乘菩提同依入胎識而有深淺差別，並論證入胎識是第八識而非意根或意識。","p":["慧解脫者推知如來滅後入胎識常住","不知不見指涅槃本際離見聞覺知","無漏心解脫是滅盡六識，非離念靈知","聲聞信受、緣覺推知、菩薩親證本識","阿含稱意根為意不稱識，入胎識是第八識"],"k":["入胎識","阿賴耶識","慧解脫","無餘涅槃","三乘菩提","大緣方便經"]},"3877-a16_068":{"s":"本集引《雜阿含經》卷12第287經逐段語譯：世尊憶未成佛時先以十因緣逆推至「齊識而還」，再以十二因緣觀還滅，並以古仙人道、古城喻八聖道。說明此經將十因緣與十二因緣合說，顯示二者有關聯性、不可分割性與前後次第。","p":["第287經前段為十因緣觀，推至入胎識","中段為十二因緣還滅觀，無明滅則行滅","古仙人道喻八聖道","十因緣與十二因緣同經合說，有次第性","十二因緣觀不得外於十因緣觀而獨存"],"k":["十因緣","十二因緣","雜阿含經","齊識而還","八聖道","辟支佛"]},"3881-a16_069":{"s":"本集細說十因緣與十二因緣的關聯：述悉達多太子捨苦行後由老死推究至名色由入胎識生。說明十因緣是流轉門、眾生緣起之法，本身為黑品法而其觀行為白品法；十二因緣觀是還滅門、白品法，在知本識常住前提下滅無明，捨壽不再入胎。","p":["不肯滅離念靈知而再受生，即是我見無明","名色由入胎識生，識前無一法可得","十因緣是黑品法，其觀行是白品法","十二因緣觀是還滅門，探究無明內涵","知本識常住故不墮斷滅，能無恐怖細觀"],"k":["十因緣","十二因緣","流轉門","還滅門","入胎識","無明"]},"3885-a16_070":{"s":"本集講因緣觀的正確觀行，指出單修十二因緣觀會落斷滅見，須先修十因緣觀。依第287經提出四個觀行過程：十因緣逆觀、順觀檢查，再作十二因緣逆觀，最後從無明起對每一支作苦集滅道觀，並說斷我見重在觀察離念靈知心依何因緣而生。","p":["單修十二因緣觀易墮一切法空的斷滅見","第一、二過程：十因緣逆觀與順觀檢查","第三過程：十二因緣逆推至無明","第四過程：每支作苦集滅道四聖諦觀","阿羅漢不須親證本識，信受即可斷結"],"k":["因緣觀","十因緣","十二因緣","四聖諦","斷我見","斷我執"]},"3889-a16_071":{"s":"本集綜述阿含正義：佛先說十支因緣確認名色由本識生，再說十二因緣推究名色何以再生，結論是十二因緣的識指識陰六識。並說阿含部分經典本為大乘經而由二乘結集，引《央掘魔羅經》、《攝大乘論》、《成唯識論》證阿含已隱說如來藏、阿賴耶識。","p":["先十支確認名色根源，再十二支探無明","十二有支名色緣識的識指識陰六識","部分阿含本為大乘經，二乘依其理解結集","增一阿含已密意說愛樂阿賴耶","依入胎識常住說緣起性空，不同斷常外道"],"k":["十因緣","十二因緣","如來藏","阿賴耶識","阿含正義","斷見外道"]},"3893-a16_072":{"s":"本集開講流轉與還滅，講者批評南傳主張須先證四禪才求四果之說。引《雜阿含經》卷2佛答婆羅門「我論因、說因」，說明凡夫不如實知色集滅味患離故有流轉，聖弟子如實知則還滅；並以《百喻經》渴人追陽焰喻凡夫追逐五蘊，結論流轉門在先、還滅門依流轉建立。","p":["講者批評須先證四禪才修四果之說","佛說法總歸「我論因、說因」","不如實知色集滅等故愛取有生，大苦聚集","《百喻經》陽焰喻：追逐五蘊如追幻水","流轉門本有，還滅門依流轉而建立"],"k":["流轉門","還滅門","因緣法","五蘊","四雙八輩","雜阿含經"]},"3897-a16_073":{"s":"本集續說流轉與還滅，指出若只看表相、止息五蘊即成斷滅，佛法實為離斷常的中道。引第287經與《長阿含》說入胎識先於名色存在，並以受精卵發育說明最初入胎的識非識陰六識；又引《法句經》「識神走五道」「形壞神不亡」說本識輪轉受身。","p":["二門若只看表相皆生滅，易成斷滅見","佛法是離斷常的中道，有法可實證","受精卵無根無腦，入胎識非識陰六識","本識不入胎或中途離開，名色不能增長","《法句經》：識神捨身受身，形壞神不亡"],"k":["流轉門","還滅門","入胎識","名色","中道","識神"]},"3901-a16_074":{"s":"本集指出佛法是說因之法，講者批評只看緣不需因的說法。引《法句經》識神偈、南傳增支部「此心淨潔」及《中阿含》卷24「緣識有名色、緣名色有識」，說明流轉門由本識出生根塵識。並介紹南傳《解脫道論》七心輪、八十九心及《攝阿毗達摩義論》，講者認為是無法現觀本識而另立的說法。","p":["佛論因說因，不知因則非佛法","本識清淨，為外來煩惱所染","《中阿含》：識是名色之因、習、本、緣","知流轉才能知還滅，次第不可錯","講者評南傳七心輪為解釋識緣名色的施設"],"k":["流轉門","本識","名色","中阿含經","解脫道論","有分心"]},"3905-a16_075":{"s":"本集續論南傳仍承認識陰一世斷壞與意界、意識界之別，講者並批評某比丘尼主張意識不滅之說。重申完整法義須具流轉、還滅二門，不明流轉則還滅不成；以南嶽懷讓磨磚作鏡、打牛打車公案說明輪迴主體是入胎識而非六識，並引拘提比丘「神識處空與空合體」。","p":["講者批評意識不滅、靈魂不滅之說","完整法義須具流轉門與還滅門","講者批評打得念頭死即見道之說","磨磚作鏡：牛喻本識，車喻蘊處界","滅五陰十八界，入胎識本無生故不滅"],"k":["流轉門","還滅門","入胎識","意識","禪宗公案","涅槃"]},"3909-a16_076":{"s":"本集說明識陰是修道關鍵：以五別境心所分析，只有意識等六識具足別境，意根唯慧心所且了別極劣，如來藏不觸知六塵、是被證悟的標的，故修行主體是意識。引《增壹阿含》定義識陰為六識，說斷我見須現觀六根、六塵、六識虛妄；講者並批評喇嘛教以意識細心為生命本源。","p":["五別境心所唯識陰六識具足","意根僅相應慧心所，了別慧極劣","如來藏離見聞覺知，是被證的標的","識陰為六識，意根是根不屬識陰","現觀根塵識虛妄方斷我見，識陰亦易生邪見"],"k":["識陰","意識","別境心所","意根","斷我見","如來藏"]},"3913-a16_077":{"s":"本集談修道所需的正知見與善知識。講者區分實證佛法與佛學學術研究，批評以演化觀與文獻考證研究佛法、否定如來藏的學術路線，並引林鎮國教授對批判佛教的評論。後引《瑜伽師地論》卷30第五處所圓滿與《佛說法句經》說明親近善知識的重要。","p":["實證佛法須觀行親證，不同於佛學研究","講者批評以宗教演化觀套用佛法","引林鎮國教授：如來藏非佛教之說不能成立","《瑜伽師地論》：善知識攝受為處所圓滿","《法句經》：欲得菩提當親近善知識"],"k":["正知見","善知識","佛學研究","實證佛法","瑜伽師地論"]},"3917-a16_078":{"s":"本集續說「識陰是修道的關鍵」：四種涅槃都是如來藏自住境界，但修行與親證者是含攝意識的識陰，如來藏從不修行。並說明五陰種子各別執藏於如來藏（阿賴耶識），熏習只改變種子染淨而不增減總數；主講者批評以意識細心取代如來藏之說。最後指出識陰常誤認自己常住，須如實了知其虛妄方能斷我見。","p":["四種涅槃皆是如來藏自住境界","修行、證境者是識陰意識，非如來藏","五陰種子各別執藏於如來藏中","熏習改變種子善惡染淨而總數不變","識陰誤認自己常住，故難證解脫果"],"k":["識陰","如來藏","四種涅槃","種子熏習","阿賴耶識","斷我見"]},"3921-a16_079":{"s":"本集依《增壹阿含》卷28、《中阿含》卷7說明識陰即眼至意六識，意根不屬識陰而是意識出生所依；根壞則意識不得生，故意識是緣生虛妄法，並歸納六識同列識陰的四個共因。接著從三苦、八苦觀識陰之苦，描述人們執著財名、氣氛、離念靈知、了了分明等識陰集苦之相，並說識陰苦滅即識陰自身滅除、證無餘涅槃。","p":["識陰即六識，意根不攝於識陰","內處壞則意識不生，意識是緣生法","六識同列識陰的四種共同原因","從苦苦、壞苦、行苦觀識陰虛妄","執境界、氣氛、了了分明皆是集苦"],"k":["識陰","意根","三苦","苦集","無餘涅槃","離念靈知"]},"3925-a16_080":{"s":"本集講「識陰的定義」，引《增壹阿含》、《雜阿含》卷2、卷5說明識陰六識是名色所緣、根塵為緣而生，執六識為我即是「識即是我」的我見；並以意識不記前世、五位必斷、滅盡定能出定等理證意識非常住。主講者批評花蓮某法師所說意識不滅、可淨化回歸第九識即佛性的說法，以《長阿含》頂糞養豬人譬喻說所生法不能轉為能生法。","p":["識陰六識皆名色所緣而生","執六識為我即「識即是我」的我見","意識不憶前世，非從前世而來","意識五位會斷，另有識住持色身","所生的意識不能轉為七、八、九識"],"k":["識陰","我見","意識五位斷","意根","第八識","破邪顯正"]},"3929-a16_081":{"s":"本集講識陰的出生與苦，引《中阿含》卷7、卷54及南傳《相應部》、《雜阿含》卷9，說明一切意識不論粗細皆由意與法為緣而生，「識有緣則生，無緣則滅」。主講者批評佛護、月稱、宗喀巴等否定意根與如來藏，以及新竹某法師以「業果報系統」取代如來藏，指其不可證而唯有如來藏能持種。末段總結六識四共性，並說苦、樂、捨受皆不離苦。","p":["識因緣故起，有緣則生無緣則滅","所有意識皆意、法因緣生","批評以業果報系統取代如來藏","如來藏可證、能持一切業種","苦樂捨諸受皆不離苦，有受皆苦"],"k":["識陰","因緣所生","如來藏","持種","有受皆苦","六識論"]},"3933-a16_082":{"s":"本集講識陰的苦集與苦滅：依《雜阿含》卷3說意、法、意識三和合生觸受愛乃至大苦聚；描述執財名眷屬、重氣氛、執了了分明或離念靈知、師徒情執而起見取見等苦集相。苦滅部分引味、患、離及阿難與純陀問答，說意識依無常因緣而生，不能住於無餘涅槃；滅除意根、法塵、意識即識陰苦滅。","p":["三事和合生觸，乃至純大苦聚","執氣氛、了了分明皆是識陰苦集","師徒情執導致見取見、我見難斷","觀識陰味、患、離而調伏欲貪","意識不能入住無餘涅槃，滅之即苦滅"],"k":["識陰","苦集","苦滅","見取見","無餘涅槃","四聖諦"]},"3937-a16_083":{"s":"本集講「識陰苦滅之道」，依《中阿含》卷7「知識如真」，說須詳知六識及其功能（六識身），並避免將意識變相或見聞知覺性誤認為真如、佛性。引《雜阿含》卷8、卷9說應觀根、塵、識、觸、受皆無常，斷我執須先離欲界愛、發起初禪；意識最難斷，最後說明識陰苦、集、滅、道四聖諦皆由意識熏習觀行而證。","p":["知識如真須詳知六識與六識身","誤認見聞知覺性為佛性是自性見","根塵識觸受皆須觀為無常","斷我執須先離欲界愛、發起初禪","識陰四聖諦須由意識觀行親證"],"k":["識陰","道聖諦","斷我執","六識身","自性見外道","慧解脫"]},"3941-a16_084":{"s":"本集開始講「名色以第八識為根本」，先依《解深密經》介紹有、空、中三時教：初轉阿含說四諦、二轉般若隱說如來藏、三轉唯識顯說第八識，前二時屬有上有容未了義。接著說名色即五陰，並依《楞嚴經》講解五陰由如來藏藉堅固、虛明、融通、幽隱、顛倒五種妄想所變生，以酸醋、懸崖、記憶等譬喻說明。","p":["三時教：有教、空教、中道教","初二轉隱說，第三轉顯說第八識","名色即五陰：名為四陰，色為色陰","《楞嚴經》五陰由五種妄想變生","識陰澄湛之心念念受熏，非常住"],"k":["名色","三時教","楞嚴經","五陰","第八識","解深密經"]},"3945-a16_085":{"s":"本集續講名色以第八識為根本，說明《心經》以「空」隱說空性如來藏，與阿含「識緣名色、名色緣識」不相違。引《雜阿含》298、288經束蘆喻及《長阿含》〈大緣方便經〉、〈世記經〉，說入胎識在六識與意根之外，即第八識，並以「若見緣起便見法」說明十二因緣須依本識才是真實緣起。主講者並批評某法師稱真常唯心為「佛教梵化」之說。","p":["《心經》以空隱說如來藏","識緣名色、名色緣識，三蘆相依","因識有名色之識即第八識","依本識觀緣起，非假號緣起","批評「真常唯心是梵化」之說"],"k":["名色","入胎識","十二因緣","緣起","如來藏","識緣名色"]},"3949-a16_086":{"s":"本集續說名色以第八識為根本，引《增壹阿含》卷29六界經，說識界即入胎識，攝取四大、留存空界而成人身，再有六入、六識，故識界非六識。引《雜阿含》288經舍利弗與拘絺羅的名色問答及束蘆喻、《中阿含》〈大因經〉，說明入胎識是名色之本，「齊識而還」；並依《雜阿含》295經說無為法不生滅，涅槃非斷滅空。","p":["六界中的識界即入胎識","入胎識先有，六識後生","名色非自作他作，緣識而生","入胎識是名色因、本、緣","有為緣起生滅，無為涅槃常住"],"k":["入胎識","六界","名色","齊識而還","本住法","無為法"]},"3953-a16_087":{"s":"本集總結名色以第八識為根本：緣起法依蘊處界而有、入涅槃即滅，無餘涅槃是入胎識獨存的無為法，非斷滅空。主講者批評《妙雲集》作者認為中國佛教「圓融、真常、唯心、頓證」已被困、佛法須隨時演變的說法，以及達賴稱三轉法輪互相矛盾；主張佛法本質不變，三轉法輪皆以第八識為中心而連貫。","p":["無餘涅槃是本識獨存的無為法","先作十因緣觀，再觀十二因緣","辯護圓融、真常、唯心、頓證","佛法本質不可演變，僅弘法方式可變","三轉法輪皆以第八識為中心"],"k":["第八識","無餘涅槃","緣起","三轉法輪","六識論","真常唯心"]},"3957-a16_088":{"s":"本集開講「我與無我」，先說世間人從嬰兒、孩童到成人，執色身、財物、名聲、長生乃至意識靈知心為我；主講者並批評佛門及喇嘛教以意識心為真。再以八苦、三苦說眾苦根源在五陰熾盛苦。接著說明聲聞依四聖諦、八正道斷結證初果至四果，緣覺推究十因緣知「齊識而還」，二乘知涅槃有本際而無恐怖入涅槃。","p":["世間人執色身、我所、意識為我","眾苦根源歸於五陰熾盛苦","聲聞依四聖諦斷結證四果","緣覺推究十因緣知齊識而還","二乘知涅槃有本際，非斷滅空"],"k":["我與無我","我見","四聖諦","聲聞四果","緣覺","八苦"]},"3961-a16_089":{"s":"本集續說菩薩的「我與無我」：菩薩須具定力、慧力、福德三資糧，破參明心後現觀真心真實可證、離見聞覺知而出生七轉識、與蘊處界非一非異。引三法印、《心經》、《雜阿含》卷3「非我、非異我、不相在」及卷16「如如、不離如」，從真心與空相兩立場說我與無我；主講者並批評某學術導師稱無上菩提不可證之說。","p":["菩薩須具定力、慧力、福德三資糧","真心真實存在而可知可證","真心離見聞覺知，出生七轉識","五陰非我、非異我、不相在","從真心與空相兩立場說我與無我"],"k":["我與無我","明心","如來藏","非一非異","三資糧","本來自性清淨涅槃"]},"3967-a16_090":{"s":"本集講「我與無我」中「住不變易法，空無我、我所」：說意識是假我、如來藏是真我，二者皆無我性。依《雜阿含》卷11分四點：蘊處界生滅無我、眾生皆有不變易法、生滅與不生滅對比觀行、當念空諸行。再引《瑜伽師地論》、《成唯識論》、《顯揚聖教論》說諸行剎那生滅、六種無常，並以三因緣及五種貪愛心相說空我所。","p":["假我、真我皆是無我性","蘊處界生滅，空無我、我所","如來藏是不變易法、究竟依靠","諸行剎那生滅，相似相續名住","觀因力、境界力等起煩惱，空我所"],"k":["我與無我","不變易法","無常","我所","如來藏","諸行"]},"3969-a16_091":{"s":"本集講如來藏妙義難知、難解、難證，依《央掘魔羅經》及《十地經論》說明難知因難證（如三世因果需宿命通、唯證乃知），難信因如來藏是無因的本住法；並說阿賴耶識兼具清輕無漏性與粗重集藏性。再依《大般若經》說般若難信解的四因：不勤精進、未種善根、具不善根、為惡知識所攝受，並引《長阿含》婆羅門不捨邪見之例。","p":["如來藏妙義難知、難解、難證","難知因難證，難信因難生決定","阿賴耶識兼具清輕與粗重二性","般若難信解的四種原因","應遠離邪見，修學勝妙如來藏法"],"k":["如來藏","般若","善知識","阿賴耶識","邪見","精進"]},"3973-a16_092":{"s":"本集開講「熏習與本際」，說明種子熏習之理在四阿含中已有，主講者並批評「大乘非佛說」之說。引《中阿含》卷10「有愛者其本際不可知」，說嬰兒生來即有貪愛，顯示有持種的本際心；以《長阿含》入胎識說本際即入胎識。再引《雜阿含》卷12思量名色、識的因集生觸，並說熏習須有能熏的識陰、意根與受熏的入胎識。","p":["種子熏習之理阿含中已略說","有愛本際不可知，顯有本際持種","本際即入胎識，名色緣之而生","《雜阿含》說識滅、行滅之道","熏習須有能熏心與受熏心"],"k":["熏習","本際","入胎識","種子","大乘非佛說","解脫道"]},"3977-a16_093":{"s":"本集續講熏習與本際：能熏的是了別六塵的識陰六識與意根，受熏者須是無記、離見聞覺知、不作主而常住的第八識，否則睡熟後種子盡失。引《雜阿含》卷6說眾生不知本際而流轉，同時宣說五陰非我、不異我、不相在；引《央掘魔羅經》「我住於實際」說明佛住實際而同時示現五陰，並說本際與熏習的關係。","p":["能熏心是識陰六識與意根","受熏心須無記、常住、不作主","眾生不知本際故生死流轉","佛住實際而同時示現五陰","無本際則一切熏習皆無意義"],"k":["熏習","本際","第八識","實際","央掘魔羅經","持種"]},"3981-a16_094":{"s":"本集講「命根與本識」，依《中阿含》卷58及《雜阿含》卷21說壽、暖、識三法合為命根，並以死亡與滅盡定的差別說明：入定時六識全滅而壽暖不失，證明有第八識駐身。接著說真識使阿羅漢入涅槃不墮斷滅空，並引述講解《雜阿含》卷5佛為外道仙尼說三種師（斷見、常見與如來說）及五陰與如來非同非異的問答。","p":["壽、暖、識三法說為命根","死亡與滅盡定差別在識是否離身","六識滅而不死，證第八識存在","仙尼經：斷見、常見與如來三種師","反覆問難五陰與如來的關係"],"k":["命根","本識","滅盡定","入胎識","仙尼經","斷見常見"]},"3985-a16_095":{"s":"本集續講仙尼經：佛說未解義的弟子因慢未斷而再受生，解義者斷慢得無間等而不再相續。主講者析論五陰與自心如來非一非異、不相在，五陰壞時如來不壞，故如來常住非涅槃後無。並說我慢是因「我」而起慢，非對他人比較，三果人須斷此微細我慢；最後強調阿含中的「識」有時指第八識，須以智慧辨明。","p":["慢未斷者捨陰後再相續受生","五陰與自心如來非一非異","如來常住，非涅槃後斷滅","我慢是因我起慢，非比較他人","阿含中「識」有時指第八識"],"k":["無間等法","我慢","自心如來","非一非異","第八識","仙尼經"]},"3989-a16_096":{"s":"本集依《央掘魔羅經》卷2央掘魔羅與滿願子（富樓那）的對答，探討如來藏是否為眾生我或外道神我。講者說明蘊處界人我空只是緣生緣滅的現象空，央掘魔羅所說「法無我」是如來隱覆密意說的如來藏；並引《大般涅槃經》、《雜阿含經》說明眾生我即五陰和合、於色受想行識見我即是我見。","p":["央掘魔羅出家因緣及與滿願子的對答","蘊處界人我空非能生萬法的真實空","三世諸佛求眾生無如來藏不可得","眾生我即五陰和合，離五陰無別我","於五陰見我即我見，須以正見修八聖道"],"k":["眾生我","如來藏","央掘魔羅經","法無我","我見","五陰"]},"3993-a16_097":{"s":"本集續論眾生我、神我、如來藏我，引《雜阿含經》「非我、非異我、不相在」說明五蘊與如來藏不一不異。講者引《大乘理趣六波羅蜜多經》破斥外道以覺知心為神我之說，並批評某法師《印度佛教思想史》將如來藏視同世俗神我；再引《寶性論》、《不增不減經》說眾生界即法身，以《百喻經》羅剎戲服喻說凡夫誤五陰為我。","p":["五蘊非我、不異我、不相在名為正慧","常住不生不滅自在者方名為「我」","外道神我只是覺知心的變相","講者批評某法師視如來藏為神我","眾生界即法身，凡夫誤認五陰為真我"],"k":["如來藏","神我","眾生我","法身","正慧","我見"]},"3997-a16_098":{"s":"本集講解如來藏真我的人無我與法無我，引《摩訶般若經》說諸法實相不垢不淨，並依《楞伽經》解說人無我智與法無我智。講者解釋《我與無我》扉頁偈「無我中有我，我中有無我」，以《阿含經》苦之本際、涅槃本際及般若、方廣經之本際說明皆指如來藏，並批評某法師以如來藏為神我、為方便說。","p":["諸法實相即如來藏，般若說其無我性","《楞伽經》人無我智與法無我智","解釋《我與無我》四句偈義","苦之本際、涅槃本際即如來藏","講者批評「淡化眾生有我」等說法"],"k":["人無我","法無我","如來藏","涅槃本際","楞伽經","般若"]},"4001-a16_099":{"s":"本集以皮影戲與幻化師為喻，說明如來藏不對所生五蘊起念作意，即是其人無我、法無我。講者引《究竟一乘寶性論》說本際本來寂靜無我，非滅煩惱時始有；再引《攝大乘論》十種殊勝處，詳解阿賴耶識為所知依、依他起等三自性為所知相、唯識性為入所知相，主張大乘為佛為菩薩所說。","p":["皮影戲與幻化師喻五蘊與如來藏","《寶性論》：本際寂靜無我本來具足","阿賴耶識名所知依，即如來藏","三自性為所知相，唯識性即真如","《攝大乘論》十處顯大乘異於聲聞"],"k":["所知依","三自性","攝大乘論","人無我","法無我","唯識性"]},"4005-a16_100":{"s":"本集為《阿含正義》導讀，辨正某法師在《印度佛教思想史》將空性解為「空所顯性」、認為如來藏與阿賴耶識由後人結合的說法。講者區分空相與空性，引《心地觀經》、《大般若經》說空性即能生萬法的第八識如來藏、入胎識，並以一人多名為喻，說明如來藏、自性清淨心、阿賴耶識是一心多名。","p":["講者批評「空所顯性」之解","空相無量，空性唯第八識如來藏","阿含所說入胎識即第八識","一心多名，非後人將多心結合","批評法稱以後只論前六識"],"k":["空性","如來藏","入胎識","阿賴耶識","第八識"]},"4009-a16_101":{"s":"本集續辨某法師的說法，說明唯識宗含三能變識，以真實唯識門函蓋虛妄唯識門，阿賴耶識直接、間接、輾轉變生諸法。講者辨無垢識與無垢智不一不二，並主張大乘經於第一、二次結集之間已結集；阿含雖無「自性清淨心」名相，但無餘涅槃本際離六塵貪染，即隱說自性清淨心。","p":["三能變識：真實唯識函蓋虛妄唯識","阿賴耶識直接、間接、輾轉變生諸法","無垢識屬第八識，無垢智屬佛地意識","菩薩「吾等亦欲結集」說大乘佛說","無餘涅槃本際即自性清淨心"],"k":["自性清淨心","三能變識","真實唯識","無垢識","大乘佛說","無餘涅槃"]},"4013-a16_102":{"s":"本集辨正某法師依月稱、宗喀巴之說，主張如來藏、阿賴耶識是不了義的觀點。講者說明晚期印度偏重論議，是因密教化後應成派與瑜伽行派的法義辨正；正確的中觀與瑜伽行皆以如來藏為根本。並論業種須由阿賴耶識執持方不錯亂果報，故如來藏才是了義法。","p":["晚期印度佛教偏重論議的背景","正確中觀與瑜伽行皆以如來藏為本","批評「如來藏與賴耶出自不同思想系」","業種須阿賴耶識收存，果報方不錯亂","如來藏總攝三乘，是了義法"],"k":["阿賴耶識","如來藏","了義","應成派中觀","業種","瑜伽行派"]},"4017-a16_103":{"s":"本集辨正「如來藏是眾生我」之說，回應某法師對寂護引《楞伽經》及《央掘魔羅經》編入阿含部的批評。講者引《大般泥洹經》說我與非我不二，引《大乘舍黎娑擔摩經》六界中「眼識乃至第八識」，並以《央掘魔羅經》說二乘信佛說有如來藏而未親見，結論如來藏無蘊處界我性。","p":["回應對寂護與《楞伽經》的批評","回應《央掘魔羅經》不應入阿含之說","如來藏兼具真我與蘊處界無我","經中明說「眼識乃至第八識」","如來藏難證，須隨真善知識修學"],"k":["如來藏","眾生我","央掘魔羅經","第八識","真我"]},"4021-a16_104":{"s":"本集主張西藏密宗不曾傳授真正如來藏法，所傳實為離念靈知、雙身法中的意識或觀想的中脈明點。講者批評某南傳法師附和六識論者，說佛教因弘如來藏而被外道同化；講者認為天竺晚期坦特羅密教已非佛教。並引《雜阿含經》「非我、不異我、不相在」說有第八識真如心，二乘涅槃方不成斷滅。","p":["西密所傳如來藏實為意識或明點","批評「弘如來藏致佛教被同化」之說","天竺晚期密教被稱為坦特羅、左道","第八識離六塵，意識不離六塵","五陰非我不異我不相在，涅槃非斷滅"],"k":["如來藏","藏傳密宗","坦特羅","六識論","離念靈知","涅槃"]},"4025-a16_105":{"s":"本集續說五陰與第八識真如心「不相在」的八識論義，指出六識論無法解釋此說，以昏迷時意識斷滅及《中阿含經》「識因緣故起」破斥意識細心常住。講者批評宗喀巴等執意識為我落常見、某導師說滅相不滅落斷見，並回應某法師以如來藏為泛外道化名詞之文，最後說如來藏法源自前佛經諸天傳至人間。","p":["六識論無法解釋「不相在」","意識皆因緣生，細心亦非常住","批評執意識為我與滅相不滅說","回應「如來藏是泛外道化名詞」","前佛之法經諸天傳於人間"],"k":["八識論","意識細心","常見","斷見","如來藏","應成派中觀"]},"4029-a16_106":{"s":"本集論證天界有佛法弘傳，以回應「外道先說如來，故如來藏為外道法」之說。講者引《大堅固婆羅門緣起經》大梵天王為輔相婆羅門說無我、離煩惱法，婆羅門出家證阿羅漢並度眾生天；並引《中阿含》須陀洹七往返及《長阿含》露遮經，說明證果者生天，天界必有前佛之法流傳。","p":["外道說如來，不證如來為外道法","大梵天王說無我、離諸煩惱法","輔相婆羅門出家證阿羅漢度眾","初果極七往返天上人間","證果者生天，天界有佛法流傳"],"k":["天界","大堅固婆羅門緣起經","須陀洹","解脫道","如來藏"]},"4033-a16_107":{"s":"本集說明佛前外道所說如來藏多是誤把意識變相當真心，不能因此說如來藏是外道法。講者引《阿含正義》說天竺佛教寺院密教化後如來藏法失傳，「密教興而佛教亡」；批評某導師稱如來藏法門為順應世間的易行方便，並引《大集法門經》四顛倒，說喇嘛教以明點、離念靈知為如來藏墮四顛倒。","p":["外道錯以意識變相為如來藏","天竺密教化後佛教名存實亡","講者批評「如來藏為易行方便」說","以明點、離念靈知為真心墮四顛倒","真正佛法不曾演變"],"k":["密教興佛教亡","如來藏","四顛倒","藏傳密宗","應成派中觀"]},"4037-a16_108":{"s":"本集依《阿含正義》第四輯，先證成彌勒菩薩是真實人物及世尊預記的賢劫第五尊佛。講者引《長阿含‧轉輪聖王修行經》、《中阿含‧說本經》金縷衣授記、《增壹阿含》說釋尊早彌勒成佛之因，再從佛以太子出家無須妄語、四念處等法可如實實證，說明佛是實語人。","p":["《長阿含》預記彌勒人壽八萬歲成佛","《中阿含》金縷織成衣授彌勒","釋尊勇猛精進早彌勒成佛","佛以太子出家，無須妄語","四念處等法可實證，證佛是實語人"],"k":["彌勒菩薩","大乘是佛說","授記","四念處","阿含經"]},"4041-a16_109":{"s":"本集回應「佛法因果輪迴抄襲婆羅門教吠陀、奧義書」之說，講者指外道以意識為常、梵我合一屬六識論，佛具宿命通說七佛事，無須抄襲。並從阿羅漢不是佛證大乘是佛說：十大弟子各有第一、迦葉懺悔、阿羅漢有退轉及橫死、申恕林葉喻佛所未說法甚多，並略論《解深密經》三時判教之爭。","p":["吠陀、奧義書梵我合一屬六識論","佛以宿命通說七佛，無須抄襲","阿羅漢各有第一、會犯錯，非佛","阿羅漢有退轉、橫死等事","申恕林葉喻未說之法極多"],"k":["大乘是佛說","阿羅漢","奧義書","六識論","三轉法輪"]},"4045-a16_110":{"s":"本集續證大乘是佛說：佛慈悲平等，不可能只說二乘法。講者以洗小孩喻大小乘差別，並以輪迴實例與「十八界外必有一法持業種」推論：業種不能存於六塵、六識、五根或意根，故必有不生不滅的阿賴耶識，二乘涅槃方不成斷滅；再引《攝大乘論》與《成唯識論》七因中的「先不記」、「本俱行」。","p":["阿羅漢非佛，佛必說成佛之法","洗小孩喻聲聞與菩薩之別","以輪迴實例說輪迴可信","十八界皆不能持業種，必有第八識","七因：先不記、本俱行"],"k":["大乘是佛說","阿賴耶識","業種","十八界","成唯識論","輪迴"]},"4049-a16_111":{"s":"本集續講《成唯識論》引彌勒七因證大乘是佛說，說明本俱行、非餘境、應極成、有無有、能對治、義異文。講者以螢幕與硬碟為喻說如來藏與阿賴耶識是同一心，並批評熊十力種子可離識獨存之說；再列舉相貌福德差異、習氣難改等問題，主張唯八識論能解，並提及龍樹論中亦說唯識。","p":["七因中的後五因逐一說明","外道神我屬意識，如來藏離見聞覺知","螢幕硬碟喻：如來藏即阿賴耶識","批評熊十力種子獨存之說","列舉問題，主張八識論可解釋"],"k":["大乘是佛說","成唯識論","如來藏","阿賴耶識","八識論","龍樹"]},"4053-a16_112":{"s":"本集開始講《阿含正義》第四輯第六章，以三法印檢驗涅槃，先說諸行無常。講者說明斷盡解脫道無明者不再生中陰；並依《增壹阿含經》依序解說色陰、識陰（六識）、受陰、想陰（了知），再詳述身行、口行、意行各自粗細層次，指出須滅三行、滅盡蘊處界才成無餘涅槃。","p":["三法印用以印定涅槃","誤認色界天身、觀想境界仍屬行陰","識陰為六識，想陰即了知","身口意行陰各有粗細層次","滅除三行、蘊處界成無餘涅槃"],"k":["諸行無常","三法印","行陰","五陰","無餘涅槃"]},"4057-a16_113":{"s":"本集續說諸行無常，區分十二因緣行支（有記善惡業）與五陰行陰（含無記業）。講者引《雜阿含經》卷21說出入息為身行、覺觀為口行、想思為意行，入滅盡定先滅口行，次身行，後意行；並澄清離語言妄想只是欲界定而非無想定，勸修行者在滅除煩惱上用功以修除三行。","p":["行支屬有記業，行陰兼含無記業","出入息身行、覺觀口行、想思意行","入滅盡定先滅口行、次身行、後意行","離語言妄想非無想定","應於滅煩惱上用功修除三行"],"k":["諸行無常","身口意行","滅盡定","無想定","十二因緣","行陰"]},"4713-a20_020":{"s":"本集講解《勝鬘經》十大受中第六至第八受：不自為己受畜財物、以不愛染心、無厭足心、無罣礙心行四攝法、不捨厄難困苦眾生。說明布施、愛語、利行、同事四攝之義，菩薩應學工巧明利眾、遠離對我所財物的貪著，並以世財與法財饒益困苦眾生。","p":["四攝法：布施、愛語、利行、同事皆為方便","行四攝應以不愛染、無厭足、無罣礙心","受畜財物為利眾生，貪結微細難斷","不捨孤獨疾病等厄難困苦眾生","以世財、法財雙重饒益令脫眾苦"],"k":["四攝法","十大受","勝鬘經","布施","方便善巧","工巧明"]},"4764-a20_021":{"s":"本集介紹《勝鬘經講記》與經主勝鬘夫人，解說無始無明（迷理、所知障）與一念無明（四住地煩惱）的區別，並導入〈十受章〉：勝鬘夫人主動受持的十大受即大乘願戒，屬菩薩三聚淨戒所攝；最後讀誦十大受經文，勸觀眾見聖思齊而發願。","p":["無始無明為迷理、所知障，明心時打破","一念無明含四住地，見一處住地為見所斷","勝鬘夫人為地上菩薩，本經為破邪顯正","十大受即以願為戒，屬三聚淨戒範疇","三聚淨戒：攝律儀、攝善法、饒益有情"],"k":["十大受","大乘願戒","一念無明","無始無明","三聚淨戒","菩薩戒"]},"4765-a20_022":{"s":"本集分析十大願與三聚淨戒的對應：前五願屬攝律儀（心地戒），六至九願屬攝有情戒，第十願屬攝善法戒。說明第一願「攝心為戒」為總相，修心是修意識與意根；並詳解第九願捕養惡律儀的過失，及「得力時」指三地滿心發起意生身而能折伏攝受眾生。","p":["前五願屬攝律儀戒，為心地律儀","攝心為戒：修意識與意根而非如來藏","最初以諸佛通偈為戒，後因事制戒","捕養眾生為惡律儀，結惡緣斷人慧命","得力指三地滿心發意生身能折伏攝受"],"k":["攝心為戒","十大受","三聚淨戒","惡律儀","折伏攝受","意生身"]},"4766-a20_023":{"s":"本集續講第九願末句與第十願：折伏邪見者、攝受正見者可令正法久住、天人充滿惡道減少；正法即唯一佛乘大乘法。第十願攝受正法終不忘失，忘失正法即忘大乘、忘波羅蜜。並解說遠、近、大、圓滿四種波羅蜜多的修道次第，及二乘入無餘涅槃不能到彼岸之理。","p":["折伏攝受令正法久住，須破邪顯正","正法即唯一佛乘，二乘法從大乘析出","第十願：攝受正法終不忘失","遠、近、大、圓滿波羅蜜多對應各階位","二乘滅盡蘊處界，無人到彼岸"],"k":["攝受正法","正法久住","波羅蜜多","唯一佛乘","破邪顯正","菩薩五十二位"]},"4823-a20_024":{"s":"本集講〈十受章〉結尾：九願攝歸「攝受正法終不忘失」，勝鬘夫人請佛作證並立誠實誓，天雨妙花出妙音為證，大眾疑除發願追隨，世尊授記如其所願。強調大乘法不分在家出家、男女，並以鬱頭藍弗、琉璃王為例說「出口成願」，勸發善願、勿發惡願，已發應懺悔。","p":["前九願攝歸攝受正法終不忘失","勝鬘立誓，天雨妙花證其真實","大乘不分在家出家男女，唯看證量","出口成願，護法神亦助發願者","鬱頭藍弗、琉璃王示惡願之果"],"k":["十大受","發願","出口成願","攝受正法","懺悔"]},"4767-a20_025":{"s":"本集講〈三願章〉，先談七種最上供養、四宏誓願與發願迴向的功德，菩薩臨終可隨願受生。再解說勝鬘夫人將十大願歸結為三大願：得正法智、以無厭心為眾生說、捨身命財護持正法，即大智、大悲、大勇；世尊以「一切色悉入空界」為喻授記其真實廣大。","p":["七種最上供養與四宏誓願","發願配合無倒迴向，臨終隨願受生","三大願：得正法智、無厭說法、護法","三願即大智、大悲、大勇，可速登地","恆沙諸願皆入三願，如色入空界"],"k":["三大願","發願","迴向","大智大悲大勇","勝鬘經"]},"4768-a20_026":{"s":"本集講〈攝受章〉開頭：三大願攝歸一大願「攝受正法」，正法即具足五乘的大乘佛菩提道，非僅二乘解脫或一切法空。講者批評六識論大法師違玄奘八識之說；並解說佛讚勝鬘智慧方便甚深之意，以德山、臨濟訶佛罵祖及自稱見道即初地為例，說明各種慢與大妄語之過。","p":["恆沙諸願皆入攝受正法一大願","完整佛法含二主要道與五乘","講者批評六識論者違玄奘八識之說","德山、臨濟訶佛罵祖，智慧未達初地","自稱見道即初地為大妄語、增上慢"],"k":["攝受正法","大乘佛菩提道","八識論","增上慢","大妄語","初地"]},"4769-a20_027":{"s":"本集續講攝受正法，依五十二位階說明成佛次第：七住明心得總相智，三賢位修別相智，初地須有道種智。講者批評自稱悟即初地者與藏密的大妄語，強調學佛須膽大且心細，並說明攝受正法即獅子吼、宣說一乘道、救護眾生而成就佛土。","p":["五十二位階：十信、十住至等覺妙覺","真見道僅七住，相見道後才入初地","學佛須膽大且心細，免犯大妄語","講者批評自稱初地者及藏密大妄語","攝受正法即獅子吼、宣說一乘道"],"k":["菩薩五十二位","真見道","相見道","道種智","大妄語","獅子吼"]},"4770-a20_028":{"s":"本集講勝鬘夫人演說攝受正法廣大義：攝受正法得一切佛法、攝八萬四千法門，以劫初大雲降雨及大水聚出生三千大千界藏為喻，說明攝受正法出生大乘無量界藏、菩薩神通、世間安隱、天界如意及出世間安樂五寶。強調以第八識為修學羅盤，二乘法從唯一佛乘析出。","p":["以第八識如來藏為修學佛法的羅盤","攝受正法攝八萬四千法門","以劫初大雲、大水聚為喻","出生五寶：界藏、神通、世間安樂等","二乘從唯一佛乘析出，阿羅漢非佛"],"k":["攝受正法","唯一佛乘","如來藏","三千大千世界","獅子吼"]},"4771-a20_029":{"s":"本集以大地荷負四重任為喻，說明攝受正法的菩薩依眾生根器授以人天乘、聲聞乘、緣覺乘、大乘，並以四種寶藏喻其功德；說明第八識是眾生本有寶藏，因地名阿賴耶識、佛地名無垢識。又引《央掘魔羅經》說正法欲滅餘八十年時，菩薩捨命演說如來藏所荷四擔。","p":["菩薩如大地，忍受欺凌而承載眾生","依根器授人天、聲聞、緣覺、大乘","第八識為本有寶藏，因地果地異名","末法八十年演說如來藏須荷四重擔","淨業者得生兜率值遇彌勒受記"],"k":["攝受正法","如來藏","五乘","阿賴耶識","央掘魔羅經","末法"]},"4772-a20_030":{"s":"本集講攝受正法與波羅蜜的關係，依《勝鬘經》經文逐一說明以布施、持戒、忍辱、精進、禪定、智慧成熟眾生，令其建立正法；舉例以財施、無畏施、威儀、忍受毀辱等方式接引親友到正法道場。並強調正法即第八識如來藏，亦可以念佛淨土法門攝受眾生。","p":["攝受正法即度己度人到彼岸","以布施成熟眾生：財施、法施、無畏施","以戒行威儀、忍辱不瞋感化眾生","以精進、禪定、智慧成熟眾生","否定第八識即非正法，亦可以淨土攝受"],"k":["六波羅蜜","攝受正法","布施","如來藏","成熟眾生","淨土"]},"4783-a20_031":{"s":"本集說明佛菩提道須親證第八識如來藏，如來藏與阿賴耶識為同一實體，本身無慧心所、非六塵境界；講者批評《菩提道次第廣論》對阿賴耶識不置可否。並引不空、達賴喇嘛之說與《金剛頂經》等密續，批評密教以雙身法為修行，且將金剛薩埵、上師置於諸佛三寶之上。","p":["如來藏即第八識阿賴耶識，是實體","如來藏離見聞覺知、非六塵境界","講者批評廣論漠視阿賴耶識","講者引密續批評雙身法非佛法","批評密教將上師、本尊置於三寶前"],"k":["如來藏","阿賴耶識","密宗","雙身法","四歸依","攝受正法"]},"4784-a20_032":{"s":"本集依玄奘「若不摧邪難以顯正」論證大乘是佛說：引南傳《長部》、《中部》及《中阿含》，說明名色之外有入胎識與名色共俱，非意識亦非意根，即第八識；嗏帝比丘執意識流轉被佛呵責，涅槃本來自住。並批評宗喀巴以死、悶絕時為悟及富永仲基只承認六識之說。","p":["若不摧邪難以顯正，務存正理","南北傳阿含皆說名色之外有入胎識","嗏帝比丘執意識流轉三世被佛破斥","涅槃本來自住，非阿羅漢修出","批評宗喀巴開悟說與富永仲基六識說"],"k":["破邪顯正","第八識","入胎識","阿含經","大乘是佛說","名色"]},"4785-a20_033":{"s":"本集開講〈攝受章〉捨身命財經文，提出五個重點並先說第一點：攝受正法者即是攝受正法，人能弘道。說明正法即如來藏法，第八識隨階位有種子識、阿賴耶識、異熟識、無垢識等名，不生不滅、不垢不淨、不增不減，具真實性與如如性；講者批評否定如來藏或以意識為真心之說。","p":["經文：為攝受正法捨身、命、財三分","攝受正法者即是攝受正法，人能弘道","第八識隨階位異名，皆指同一真心","真心不生不滅，具真實性與如如性","講者批評否定真心或以意識為真心者"],"k":["捨身命財","攝受正法","如來藏","真如性","阿賴耶識"]},"4786-a20_034":{"s":"本集講第二點「捨身」的兩種意涵：一為護持正法而捨身，舉《大般涅槃經》有德國王護覺德比丘之例；二為親證如來藏而捨身見、我見。說明意識是意法為緣所生、夜夜斷滅，非常住法；並依《心經》說五蘊與真心非一非異，真心實際理地無所得，即不壞常住的如來法身。","p":["有德國王護覺德比丘捨身，福德極大","未悟前捨身僅為佛道資糧","親證如來藏而捨身見、我見","意識為意法緣生，夜斷朝起非常住","依心經說真心無所得即如來法身"],"k":["捨身","身見","我見","心經","如來法身","護持正法"]},"4787-a20_035":{"s":"本集講第三、四點。捨命：依《百法明門論》、《集論》說命根屬心不相應行、依眾同分假立，從如來藏看非有非無命根，生死後際平等。捨財：分內外世間財與七聖財、法財，舉地主大王求有為果報而福盡之例；親證如來藏後實相中無捨可言，才是真捨財。","p":["生死依如來藏，生死後際平等","命根屬心不相應行，依眾同分假立","菩薩同時現觀實相與現象法界","世間財有內外財，福德應迴向菩提","證如來藏後無捨可捨，是真捨財"],"k":["捨命","捨財","命根","非一非異","七聖財","實相法界"]},"4788-a20_036":{"s":"本集講第五點：實證如來藏的菩薩稀有，常為諸佛授記、眾生瞻仰，並總結四集要點：菩薩同時現觀實相與現象法界，非有非無捨身命財。講者並引一位被學術界尊稱為導師者的著作，批評其將如來藏判為神我、主張菩提不可證及性空唯名，認為屬無因唯緣之說。","p":["證悟菩薩稀有，受諸佛授記與護持","菩薩一腳踏實相、一腳踏現象法界","非有非無捨身命財，生死後際平等","講者批評某導師將如來藏判為神我","講者認為性空唯名屬無因唯緣之說"],"k":["捨身命財","授記","如來藏","實相法界","性空唯名","破邪顯正"]},"4789-a20_037":{"s":"本集評析福嚴法師對《勝鬘經》捨身經文的解釋，講者認為其僅依文解義，實則一生否定如來藏常住、宗應成中觀。依《導師略傳》等敘述其因讀《中論》出家、與法尊法師論辯而受宗喀巴學說影響的經過，並指出講者所見的偏差及其三系判教。","p":["經文：捨身得不壞常住如來法身","講者稱福嚴法師依文解義而否定如來藏","因讀《中論》出家，後受法尊影響","講者認為未斷我見難解般若波羅蜜","三系判教：以性空唯名為中道"],"k":["應成中觀","福嚴法師","中論","性空唯名","宗喀巴","如來藏"]},"4790-a20_038":{"s":"本集續評福嚴法師的應成中觀，以杯子為例說明「緣起性空、性空唯名」的觀點，講者認為此說有緣無因，無法回答業種由誰執持，所立「業果報系統」亦有矛盾；並引平實導師以燒美金為喻，批評「滅相真如」實為斷滅，又以奧斯卡導演的沙堡感言作比。","p":["福嚴只承認六識，以緣起性空為究竟","以杯子為例說明性空唯名之義","講者指出此說有緣無因，違因果","業果報系統的歸屬問題無法回答","滅相真如被喻為燒美金之斷滅"],"k":["應成中觀","性空唯名","滅相真如","斷滅見","因果","福嚴法師"]},"4791-a20_039":{"s":"本集續評福嚴法師「滅相不滅即真如」之說。主講者引《般若經》說菩薩依無盡藏真如心才能出生般若波羅蜜多，並以老王之喻講「假必依實」，論證依生滅五蘊所立的滅相只是意識中的概念。另述福嚴答北投法師「空就空了」一事，主講者批評其誤導學人落入斷滅見，並引平實導師論錯誤知見之害。","p":["滅相真如只是意識概念，無無盡藏功德","依無盡藏真如心方能出生般若波羅蜜多","以老王之喻說明假必依實","福嚴答北投「空就空了」，被評誤導學人","否定第八識則無餘涅槃成斷滅空"],"k":["應成中觀","滅相真如","如來藏","無盡藏","斷滅見","般若波羅蜜多"]},"4792-a20_040":{"s":"本集先續說福嚴之法自相衝突，主講者評其以八不中道包裝斷滅見；再述土城禪寺住持懺悔法師以寺院供養金資助福嚴弟子建佛學院一事。主講者依懺悔自述及林覺非居士所著年譜，說明懺悔是因能辦道場而受付囑，並未得廣欽老和尚證悟之法；並以廣老對金博士之語及「無來也無去」遺偈，說廣老親證如來藏。","p":["福嚴之法被評為以八不中道包裝的斷滅見","懺悔法師自述未開悟，因能辦道場受付囑","懺悔捐資支持否定其師法義者，被評為顛倒","廣老機鋒與遺偈顯示親證如來藏","林覺非年譜說明廣老未傳證悟法之因"],"k":["廣欽老和尚","如來藏","應成中觀","相似佛法","傳法","開悟"]},"4824-a20_041":{"s":"本集講解《勝鬘經》世尊隨喜勝鬘攝受正法大精進力一段：稍微攝受正法即令魔苦惱，如牛王勝群牛、須彌山勝眾山，大乘少攝受正法勝於一切二乘善根。主講者以阿羅漢替發大心弟子揹行囊的典故說明菩薩心之尊貴，並說真攝受正法須所攝為如來藏正法，且以攝受眾生之心為之。","p":["如大力士少觸，少攝受正法令魔憂苦","一位真悟菩薩弘法勝過萬名阿羅漢","大乘少攝受正法勝一切二乘善根，以廣大故","阿羅漢替發大心弟子揹行囊的典故","攝受正法兩層面：所攝為正法、以攝受眾生心"],"k":["攝受正法","勝鬘經","菩薩心","如來藏","二乘善根","天魔"]},"4825-a20_042":{"s":"本集續說否定如來藏者障礙善法、屬魔之所行，並引某法師《勝鬘經講記》以初行、久行區分權實之說，主講者批評其暗以阿羅漢等同於佛。進而說明權教、實教、別教、圓教之判：二乘解脫道為權教，般若為實教；並介紹五時中的華嚴時頓說、阿含期與般若時。","p":["否定如來藏者被說為障善之魔行","批評以初行、久行判權實之說","權實依所證是虛相法或實相法判定","華嚴時二十一日頓說佛法全貌","阿含期講解脫道，般若時講法界實相"],"k":["五時三教","判教","權教實教","華嚴時","般若","如來藏"]},"4826-a20_043":{"s":"本集續講五時三教：第四時方廣唯識教講如來藏一切種子與成佛次第，第五時《無量義經》、《法華經》、《大般涅槃經》收歸唯一佛乘為圓教；並解說漸教由人天乘至三乘次第施設，及《法華經》開示悟入之義。主講者再駁以初行久行判權實之說，認為其因不承認大乘是佛說，並談弘法宜觀眾生因緣。","p":["第四時唯識方廣教講一切種智","第五時法華、涅槃收圓為圓教","漸教由人天乘次第引入三乘","開示悟入佛知見為佛出世大事","結論：阿含為權教，般若唯識為實教"],"k":["五時三教","圓教","漸教","唯識","一切種智","法華經"]},"4827-a20_044":{"s":"本集講解勝鬘夫人說「攝受正法者是摩訶衍」一段：大乘出生一切聲聞、緣覺世間出世間善法，如阿耨大池出八大河、種子依地而生長。主講者引某法師以荔枝之喻解一乘之文，批評其以聲聞解脫道取代三乘、否定如來藏並貶禪宗，並批評以一念不生為悟，勸學人勿憑自信公開未證之見。","p":["攝受正法即是攝受大乘","大乘出生二乘善法，如大池出八河","批評以解脫道取代一乘佛道之說","批評以一念不生、驚斷妄念為開悟","學佛應知之為知之，勿憑自信"],"k":["摩訶衍","攝受正法","一乘","如來藏","應成中觀","大乘非佛說"]},"4828-a20_045":{"s":"本集講解《勝鬘經》六處經文：正法住、正法滅、波羅提木叉、毘尼、出家、受具足皆為大乘而說。主講者說正法住指如來藏仍有人能實證；菩薩戒能斷兩種生死，故為正解脫戒，聲聞毘尼為類解脫；阿羅漢依如來出家受具足，故說其無出家、受具足。末引某法師之解，預告下集評析。","p":["六處皆為大乘而說","正法住指如來藏仍有人能親證","菩薩戒為正解脫戒，聲聞毘尼為類解脫","三聚淨戒方為具足戒、真出家","阿羅漢依如來出家，故說無出家受具足"],"k":["正法住","正法滅","菩薩戒","波羅提木叉","毘尼","具足戒"]},"4829-a20_046":{"s":"本集續評某法師以依聲聞律出家修解脫道為大乘學、為正法住之說，主講者以胎兒與母體之喻駁「聲聞法出於大乘即是大乘學」，並述正覺以學報辨正學術界之計畫。後解「阿羅漢依如來出家受具足」，駁辟支佛從佛受具足之說，並說明辟支佛推尋十因緣，知名色由本識而生。","p":["批評以聲聞律、解脫道為大乘學","以胎兒與母體之喻駁局部等於全體","正覺以學報辨正學術界之計畫","佛世無辟支佛，五百辟支佛先入滅","辟支佛推十因緣知名色由本識生"],"k":["正法住","大乘學","辟支佛","十因緣","聲聞戒","學術研究"]},"4830-a20_047":{"s":"本集續說佛世依佛音聲證因緣觀的阿羅漢仍屬聲聞而非辟支佛，二乘仍有變易生死。接著講解《勝鬘經》「阿羅漢歸依於佛，阿羅漢有恐怖」一段，以胎昧說明阿羅漢不敢發願再來，並述阿羅漢依佛而住；再詳引《雜阿含經》焰摩迦比丘經舍利弗問答，捨棄「阿羅漢滅後無所有」邪見的經過。","p":["依佛音聲證因緣觀者仍是聲聞","阿羅漢因胎昧不敢發願再來","阿羅漢依佛而住，佛世不收弟子","焰摩迦經舍利弗問答捨斷滅邪見","須疑涅槃是否斷滅，改信八識論方斷我見"],"k":["阿羅漢","辟支佛","焰摩迦","斷滅見","胎昧","雜阿含經"]},"4831-a20_048":{"s":"本集逐句解說《雜阿含經》焰摩迦比丘經：舍利弗問色受想行識皆非如來、離五陰亦無如來，令焰摩迦知如來與五陰不一不異而得法眼淨；再以詐親怨家害長者子之喻，說五陰如怨家，焰摩迦斷五陰貪愛成阿羅漢。主講者並批評以離念靈知或見聞覺知為真心者，指出二乘解脫不涉及親證如來藏。","p":["如來與五陰不一不異","善知識以問代答引人悟入","五陰如詐親怨家之喻","以離念靈知為真心被評落入識陰","菩薩留五陰為道器，阿羅漢滅五陰"],"k":["焰摩迦","五陰","斷我見","阿羅漢","離念靈知","善知識"]},"4832-a20_049":{"s":"本集藉焰摩迦比丘見道之事，說明證初果須具簡擇常見斷見之力，以及對善知識無慢的信力、慧力，且須經實證善知識勘驗，並非自由心證。主講者強調須有定力現觀五陰方能安忍，否則落入大妄語；並引《大方便佛報恩經》、《父子合集經》，說聞佛說法即證果入地者，事先皆已有如理觀行。","p":["初果須簡擇常斷見並信受善知識","見道須經實證善知識勘驗","須有定力現觀五陰，否則落大妄語","聞法即證者事先已有如理觀行","六識論者不能助人實證"],"k":["善知識","斷我見","初果","見道","定力","無生法忍"]},"4833-a20_050":{"s":"本集說明阿羅漢不證涅槃本際，靠依止佛、信受佛說無餘涅槃非斷滅，方能斷我執、捨壽入涅槃，故無究竟樂。再引焰摩迦證阿羅漢之經文，說二乘只須滅除對五陰的貪愛，與證如來藏無關，並引《雜阿含》「識不至東西南北」說本識。主講者批評執離念靈知者，說菩薩留五陰為道器而現觀涅槃本際。","p":["阿羅漢依佛語信涅槃非斷滅","二乘解脫只須斷對五陰的貪愛","中般涅槃為三果中最利根者","阿羅漢於一切無行怖畏想住","菩薩現觀本際，不同阿羅漢無究竟樂"],"k":["阿羅漢","無餘涅槃","涅槃本際","五陰","究竟樂","如來藏"]},"4863-a20_051":{"s":"本集講解《勝鬘經》「依、不求依」：眾生因恐怖而求歸依，阿羅漢以怖畏故依於如來；菩薩自歸依本來無所依的如來藏，才是真實究竟的依止。主講者說意識離念靈知須依根塵而起，是有所依，並指另求第九識之過；說未悟者應歸依三寶，並批評某六識論導師及其弟子以學術名義否定八識論。","p":["阿羅漢以怖畏故依於如來","自歸依無所依的如來藏才究竟","離念靈知須依根塵，是有所依","悟阿賴耶識後另求第九識有過失","未悟者應歸依三寶，信受八識論"],"k":["依不求依","如來藏","三歸依","離念靈知","八識論","阿羅漢"]},"4864-a20_052":{"s":"本集講解《勝鬘經》阿羅漢、辟支佛「有餘生法不盡故有生」至「去涅槃界遠」一段。主講者以佛世阿羅漢隨佛共住說明其依佛離怖畏，菩薩則依不求依；並解說分段生與異熟生，阿羅漢「我生已盡」只斷分段生；其梵行不純、不究竟，未斷無始無明與上煩惱，未到涅槃彼岸，故離涅槃功德尚遠。","p":["阿羅漢隨佛共住，依佛離怖畏","生有分段生與異熟生兩種","我生已盡只斷分段生，仍有異熟生","未斷無始無明與上煩惱，當有所斷","七住菩薩現觀本來涅槃，到涅槃彼岸"],"k":["無始無明","分段生死","異熟生","涅槃","上煩惱","阿羅漢"]},"4865-a20_053":{"s":"本集講解《勝鬘經》唯有如來得般涅槃、二乘去涅槃界遠、二乘四智是方便有餘不了義說，以及分段死與變易死二種死。主講者依《瑜伽師地論》說獨覺與聲聞之別，說佛具四種涅槃而二乘只證有餘、無餘涅槃；再引六祖答薛簡「不生不滅」之語，以大海與風浪之喻說明大乘函蓋小乘。","p":["獨覺與聲聞之差別","佛具四種涅槃，二乘僅證兩種","二乘四智為方便、有餘、不了義說","六祖答薛簡：實性不生不滅","大海與風浪喻大乘函蓋小乘"],"k":["分段生死","四種涅槃","辟支佛","涅槃本際","六祖壇經","如來藏"]},"4866-a20_054":{"s":"本集續引六祖說外道「將滅止生」與本自無生之別，並講解經文「分段死者謂虛偽眾生；變易死者謂阿羅漢、辟支佛、大力菩薩意生身」。主講者說斷我見起漸離虛偽眾生、地上菩薩留惑潤生仍受分段死、八地以上捨阿賴耶名，並引《瑜伽師地論》說地上菩薩煩惱無染污而有功德，舉平實導師破邪及覺囊他空見為例。","p":["外道將滅止生，異於本自無生","虛偽眾生即處分段生死者","地上菩薩留惑潤生，仍受分段死","八地以上永捨阿賴耶之名","地上菩薩煩惱無染污，且有功德"],"k":["分段生死","虛偽眾生","留惑潤生","阿賴耶識","意生身","覺囊他空見"]},"4867-a20_055":{"s":"本集續舉平實導師弘法與玄奘大師西行取經為例，說地上菩薩所起煩惱無染污而利益有情；再引《成唯識論》解釋不思議變易生死：無漏業以所知障為緣，感得意生身，種子改轉變易，至佛地方究竟出離。主講者並以醉象事件、牛呞比丘等習氣及十八不共法，說明阿羅漢與佛的差別。","p":["玄奘取經為無染污煩惱之例","變易生死依無漏業與所知障為緣","意生身種子變易，至佛地方盡","醉象事件顯示阿羅漢習氣未斷","十八不共法為阿羅漢所未具足"],"k":["變易生死","意生身","習氣","十八不共法","成唯識論","玄奘"]},"4868-a20_056":{"s":"本集駁小乘部派「阿羅漢即是佛」之見，主講者引《金剛仙論》、《法華經》授記十大弟子及五百阿羅漢悔過，說明阿羅漢並未成佛；並引佛壽無量，說佛示現涅槃非灰身泯智。再舉某法師弟子論文所問「入無餘涅槃後如何發菩提心」，批評緣起性空論實為無因論，說無餘涅槃是第八識獨存。","p":["部派計阿羅漢即佛，被評為斷滅相","法華授記顯示阿羅漢尚未成佛","佛壽無量，示現涅槃非灰身泯智","批評緣起性空論實為無因論","無餘涅槃是第八識獨存，非斷滅"],"k":["阿羅漢","成佛","無餘涅槃","法華經","緣起性空","第八識"]},"4869-a20_057":{"s":"本集講解大力菩薩意生身與變易生死：依《楞伽經》說三種意生身——三昧樂正受、覺法自性性、種類俱生無行作，分別對應三地、八地、九地菩薩。主講者批評某法師以「成佛則意生身不見」解《勝鬘經》，認為其暗示佛如阿羅漢灰身泯智，並引《法華經》說如來常住，強調變易生死並非依意生身生滅而說。","p":["意生身隨意去來，迅疾無礙","三種意生身與菩薩地位對應","批評「成佛則無意生身」之解","引《法華經》說如來常住","變易生死指種子變異，非意生身生滅"],"k":["意生身","變易生死","大力菩薩","楞伽經","如來常住","大乘非佛說"]},"5184-a22_001":{"s":"本集開講〈無邊聖諦章〉，先依《解深密經》、《成唯識論》解釋四種勝義與世俗諦，說明如來藏為勝義勝義、猶如虛空而名為空。再解說經文：二乘以世俗諦智慧漸斷四住地煩惱，屬四智漸至、四緣漸至，非出世間上上智；佛菩提道以如來藏為觀行對象，才是勝義諦。","p":["聖諦是依真相所說的解脫及佛菩提道理","四種勝義：世間、道理、證得、勝義勝義","如來藏似虛空而名空，是萬法所依","二乘次第漸斷四住地，屬世俗諦智","出世間上上智非次第漸修所能到達"],"k":["無邊聖諦","勝義諦","世俗諦","如來藏","四住地煩惱","出世間上上智"]},"5185-a22_002":{"s":"本集以經文「無漸至法是出世間上上智」檢視十牛圖，說明明心證如來藏是一剎那全體親證的頓悟，悟後仍須近三大阿僧祇劫漸修。講者評析某法師《勝鬘經講記》「頓屬如來法、頓漸即大小乘之別」的說法，認為大小乘差別在觀行對象與修證內涵，頓漸只是現象。","p":["證如來藏當下全體顯現，無分證之事","講者認為十牛圖漸次尋牛不合經義","禪法是知見方法，證悟只在一念間","頓悟入道後仍須漸修別相智與種智","大小乘之別在修證內涵而非頓漸"],"k":["頓悟","漸修","明心","如來藏","次第禪觀","十牛圖"]},"5186-a22_003":{"s":"本集解釋「金剛喻者是第一義智」：聲聞依蘊處界觀行次第得苦集滅道智，緣覺觀因緣法推至本識「齊識而還」，皆非第一義智；菩薩親證出生名色的本識，所生實相智慧才是第一義智。並說明八識論在阿含已建立，正覺同修會以明心為主，解脫果是佛菩提道的副產品。","p":["聲聞觀五陰而次第得苦集滅道四智","十因緣「齊識而還、不能過彼」顯本識","八識論於阿含中已建立","親證本識所生智慧方名第一義智","解脫果如碾米所得米糠，為副產品"],"k":["第一義智","四聖諦","十因緣","本識","八識論","佛菩提道"]},"5187-a22_004":{"s":"講者評析某法師對「金剛喻者是第一義智」的註解，指其既說金剛喻為三乘所共、又說二乘不配稱金剛喻智，前後矛盾。本集說明二乘未證金剛心，阿含亦無金剛喻定之名；一切煩惱藏含所知障上煩惱；七住證金剛心只是方便說，佛地心體與種子皆不變易才是金剛喻定。","p":["阿含中部分大乘經被結集為二乘經","二乘滅蘊處界而未證涅槃本際金剛心","一切煩惱藏含習氣種子與所知障上煩惱","證金剛心為轉入內門修六度的標準","佛地種子不再變易方名金剛喻智"],"k":["金剛喻定","金剛心","第一義智","所知障","無始無明","如來藏"]},"5188-a22_005":{"s":"本集依〈無邊聖諦章〉「如來應等正覺非一切聲聞緣覺境界」及《大寶積經》卷119、《中阿含經》，論證阿羅漢不是佛。說明諸佛證不思議空智、壞一切煩惱藏；阿羅漢於內於外仍有恐怖，尚有餘生法、梵行未立、所作未辦，離佛地涅槃仍很遙遠。","p":["諸佛所證平等，講者否定密教佛勝顯教佛","一切煩惱藏含見思惑、習氣與所知障","阿羅漢於內於外有恐怖，無究竟樂","阿羅漢未斷變易生死，故說梵行未立","未證涅槃本際，有餘過，所作未辦"],"k":["阿羅漢","不思議空智","一切煩惱藏","變易生死","所知障","內外恐怖"]},"5189-a22_006":{"s":"本集先說二乘法為化城，再列舉講者對某佛教導師的批評：認為其以解脫道為成佛之道、視阿羅漢等同佛、判大乘非佛說、判唯識為「虛妄唯識」並承襲六識論。又引其《成佛之道》論述，批評其依宗喀巴三士道立五乘次第，並引太虛大師評其將佛法糅成支離破碎。","p":["二乘法為化城，阿羅漢實不證涅槃","講者列舉該導師判教三轉法輪諸論點","批評其否定如來藏、承襲六識論","講者認為其錯解「汝等所行是菩薩道」","太虛大師評其將馬鳴龍樹無著割裂"],"k":["阿羅漢","成佛之道","三轉法輪","六識論","虛妄唯識","判教"]},"5191-a22_007":{"s":"本集說明如來藏是佛法實證的標的而非眾多法門之一，勸學人簡擇善知識所教屬八識或六識論。續評該導師「一切法門無非成佛之道」及以阿含為一乘道之說，引《不退轉法輪經》說唯一佛乘與本願藏；並批評其把不思議空智解為通達一切法性空，落入緣生性空。","p":["如來藏是實證標的，非一種修學法門","人天乘、聲聞乘皆非成佛之道","《不退轉法輪經》說本願藏與一乘道","聲聞阿那含與菩薩阿那含證境懸殊","不思議空智非通達一切法性空之智"],"k":["唯一佛乘","如來藏","不思議空智","緣起性空","本願藏","成佛之道"]},"5190-a22_008":{"s":"本集區分緣起性空與緣生性空：講者說緣起性空是由第八識藉緣生滅諸法而說其性空，否定本識則落斷滅空。再引〈如來藏章〉、《解深密經》、《成唯識論》，及阿含「識緣名色、名色緣識」與《瑜伽師地論》釋名色，論證本識即第八識，阿羅漢未證故不是佛。","p":["緣起性空依第八識而說，異於緣生性空","如來藏是如來境界，非二乘所知","阿陀那識甚深細，佛不為凡愚開演","阿含「名色由識」顯示入胎本識","名色即五陰，與本識如束蘆相依"],"k":["緣起性空","如來藏","識緣名色","入胎識","八識論","阿羅漢"]},"5206-a22_009":{"s":"本集解釋「如來藏處說聖諦義」：若無如來藏，二乘無餘涅槃即成斷滅，意識細心亦是意法因緣生，故二乘與大乘聖諦皆依如來藏而說。再引《楞嚴經》、《解深密經》、《成唯識論》及述記，說明阿陀那識甚深微細，佛不為凡愚開演，恐其分別執為我而謗法、障聖道。","p":["無如來藏則無餘涅槃成斷滅空","意識細心仍是意識，有生必滅","不信本識者於內有恐怖，難斷我見","阿陀那識非真非不真，佛常不開演","恐凡愚執為我而謗法，障生聖道"],"k":["如來藏","聖諦","阿陀那識","斷我見","意識細心","無餘涅槃"]},"5207-a22_010":{"s":"本集續說般若趜多作《破大乘論》是誤會阿含與方廣密意，並以禪門公案說明如來藏總相智已難證，別相智、種智更深。再以胎中十月、隔陰之迷及阿含荼帝比丘遭佛訶責之事，論證意識只存一世、不能去至後世，並批評以意識細心為阿賴耶識的說法。","p":["般若趜多謗大乘源於誤會經中密意","禪宗公案依如來藏而證，屬總相智","意識每世新生，有隔陰之迷","荼帝比丘執意識往後世遭佛訶責","以意識細心代阿賴耶識為多此一舉"],"k":["如來藏","意識","入胎識","隔陰之迷","禪宗公案","阿賴耶識"]},"5216-a22_011":{"s":"本集說明十法界皆是如來藏隨眾生迷悟所變的假法，第八識為一真法界，「假不自假，依真有假；真不自真，藉假顯真」；眾生無明在不知世出世間境界皆如來藏所生。後半辨析佛性：六識見聞覺知性非佛性，眼見佛性異於明心，並以燈與光喻二者不一不異。","p":["十法界依一真法界，無生而生、生而無生","不知世出世間境界真相即是無明","勿錯認離念靈知等意識為真心","眼見佛性異於六識自性與成佛之性","燈與光喻如來藏與佛性不一不異"],"k":["一真法界","十法界","如來藏","眼見佛性","明心","無明"]},"5221-a22_012":{"s":"本集解釋「智者所知，一切世間所不能信」，並說明真善知識應具的條件。辨明「言語道斷、心行處滅」是如來藏自身境界而非修行方法，不應以禁語、不起念為修行；說明密意不可明說、佛觀久學根性才明說，並批評某法師以研究推度、要求先證後信的態度。","p":["真善知識能教解脫道與佛菩提道","言語道斷是如來藏境界，非禁語法門","證悟者能說而不可為人明說密意","烘雲托月與明說皆佛所用，須觀根性","應以參禪求證，不以學術研究推度"],"k":["如來藏","言語道斷","密意","參禪","善知識","本覺"]},"5222-a22_013":{"s":"本集講解「如來藏者是如來境界，非一切聲聞緣覺所知」，說明如來藏為諸法本母，並引《大方等如來藏經》萎花喻。再依《瑜伽師地論》比較佛與阿羅漢解脫同分、智慧異分；說明二乘斷四住地而無漏不盡，並引《央掘魔羅經》、《入楞伽經》說如來藏與七轉識生滅之理非二乘所知。","p":["如來藏是萬法根源，如來藏中藏如來","萎花喻：眾生煩惱身中有如來","佛與阿羅漢解脫同，現等覺等不同","二乘未斷無始無明，故無漏不盡","如來藏與七轉識轉相生滅非二乘所知"],"k":["如來藏","如來境界","萎花喻","一切種智","無始無明","無漏不盡"]},"5209-a22_014":{"s":"本集依《佛性論》所說如來藏三義，講者評某法師引用此說卻不承認如來藏、主張意識細心持種，前後矛盾。說明依止藏必非生滅心，滅盡定中無意識；如來藏識性微細故名隱覆藏；攝持藏收藏一切業種，六識只在內相分運作，業種不失，臨終業鏡現前。","p":["萬法所依止的心必非生滅法","講者批評以意識細心持種之說","滅盡定中六識及受想皆不現起","隱覆藏：了別性微細，證者見其分明","攝持藏：業種不出如來藏，內六入即內相分"],"k":["依止藏","隱覆藏","攝持藏","如來藏","意識細心","內相分"]},"5211-a22_015":{"s":"本集複習如來藏三義，引《大乘起信論》說眾生共有八識。評析某法師對如來、如如、如如智的解釋：引《雜阿含經》、《勝天王般若經》說如如是真如心於諸法不動之性，講者認為以滅相為如無意義；並引《中阿含・大拘絺羅經》說智與識不一不異，如如智是意識親證如來藏所得。","p":["眾生八識，多一少一皆不能成立","如如是真如心於諸法如如不動","如來藏空性異於緣起性空","滅相不能說為於諸法如","智依識而有，如如智為意識所證"],"k":["如如","真如","如如智","八識","空性","如來藏"]},"5219-a22_016":{"s":"本集續評某法師「如如、如如智平等不二名為如來」：講者說如如是第八識自性，如如智屬意識，不可混同，並以毒蛇、黃金為喻。又辨意識細心不能遍十二處、緣起性空非如如；再引〈胎藏喻〉與《大薩遮尼乾子所說經》說煩惱身中有如來藏，其清淨性本來分明顯現。","p":["如如屬如來藏，如如智屬意識","六識論將三識體性混歸意識而支離","意識細心不能遍十二處","煩惱身中有如來藏，如石中金","正見最先，應信八識與如來藏"],"k":["如來藏","如如智","自心如來","胎藏喻","六識論","正見"]},"5235-a22_017":{"s":"本集引《摩訶般若波羅蜜經》「世諦如即是第一義諦如」作補充：二乘世俗諦只觀蘊處界，信佛說有本識而於內外無恐怖即能斷我見我執；菩薩親證本識，從本識看一切法皆如，故世諦與第一義諦不異。並說本識橫跨三界內外，須在三界中尋，第一義諦智為意識所有。","p":["比丘於外、於內有恐怖及內外無恐怖","二乘證生空真如，菩薩證法空真如","一切法依本識而有，故世諦亦如","本識既在三界外亦在三界中","第一義諦智屬意識，存在於三界中"],"k":["世俗諦","第一義諦","真如","本識","斷我見","法空"]},"5236-a22_018":{"s":"本集以趙州「狗子有無佛性」公案說明禪師現見一切法皆如來藏，答語一語雙關。說明種智較般若更深，回應學術研究者的質疑，指如來藏可實證、可反覆檢驗；阿羅漢信而未證故不能成佛。後半開講〈法身章〉，誦出經文並語譯作聖諦與無作聖諦。","p":["趙州狗子佛性公案一語雙關","種智較般若更為甚深","如來藏可實證並可反覆檢驗","阿羅漢信受而未證，不能成佛","〈法身章〉語譯：作聖諦與無作聖諦"],"k":["第一義諦","狗子佛性","如來藏","法身章","作聖諦","無作聖諦"]},"5223-a22_019":{"s":"本集解說〈法身章〉：對煩惱所纏的如來藏不疑者，即能不疑出纏法身。說明如來藏自性清淨而含藏染汙種子，須清淨的是七識心，種子究竟清淨即成佛地無垢識；並教學人檢驗所謂開悟。最後說明作聖諦即有量四聖諦，於五蘊、六入、十八界各作五法觀行。","p":["如來藏自性清淨而有染汙","所淨是七識，種子淨盡即無垢識法身","證如來藏方能對法身心得決定","宜檢驗所說開悟是否落於意識","作聖諦為有量四聖諦，蘊處界各五法"],"k":["法身","在纏如來藏","自性清淨心","作聖諦","四聖諦","無垢識"]},"5406-a22_096":{"s":"本集依《勝鬘經》「空亂意眾生」經文，說明法界有生滅的空相與不生滅的空性兩類法，引《長阿含》舍利弗所說黑白、緣無緣、照無照法的總相智，及《增壹阿含》等壽比丘入金剛三昧火燒不壞事蹟，說明空三昧與金剛三昧相關；並指滅諦是滅盡一切法後仍有真實法，非斷滅。","p":["空亂意眾生即對「空」錯亂理解者","空相是生滅法，空性是不生不滅法","總相智：黑白、緣無緣、照無照兩類法","空三昧得聲聞初果，金剛三昧證第八識","滅諦非斷滅，空三昧為證金剛三昧前提"],"k":["空亂意眾生","空相與空性","金剛三昧","空三昧","滅諦","總相智"]},"5418-a22_097":{"s":"本集說明不思議滅諦含攝空三昧與金剛三昧；引《雜阿含》佛不答婆蹉種有我無我之問，說明如來離常斷二見處中說法，並從十二因緣流轉與還滅同時成立，推論其外必有阿賴耶識。再以舍利弗補衣時入金剛三昧及真實禪經文，說明真實禪所證即金剛三昧，成就般若中道。","p":["滅諦含攝空三昧與金剛三昧","佛不答有我無我，免增常見斷見","流轉還滅並存，隱含因緣外有阿賴耶識","舍利弗補衣時亦在金剛三昧中","真實禪所證即金剛三昧，成般若中道觀"],"k":["中道","十二因緣","常見斷見","金剛三昧","真實禪","阿賴耶識"]},"5417-a22_098":{"s":"本集引《大智度論》須菩提於佛從忉利天下時觀諸法無常而得道證、最初見佛法身的故事，說明正確無常觀須以法身觀為前提。講者批評王恩洋以無常規律為常、為真如，及某法師將空三昧解為日常對治貪染，認為皆缺總相智；並說大乘見道兼得兩種總相智，不需另有真言。","p":["須菩提觀無常見佛法身，佛說其最初禮佛","無常觀須以法身觀為前提","講者批評以「無常之常性」為真如之說","大乘見道得空三昧與金剛三昧總相智","法界只兩類法，不需別有真言"],"k":["法身觀","無常觀","空三昧","須菩提","總相智","般若波羅蜜"]},"5430-a22_099":{"s":"本集說明空三昧的關鍵在完整了知生滅法的範圍，講者批評某法師把空三昧說成近於「看得破」。引《增壹阿含》佛說眾生因不得空三昧而流轉、空三昧為三昧王並引生無願無想三昧；再以《過去現在因果經》善慧仙人布髮掩泥、解一切法空得無生忍，說明一切法空是空相與空性的共相。","p":["空三昧須知生滅法完整範圍而無遺漏","講者批評視空三昧如「看得破」之說","空三昧為三昧王，引生無願、無想三昧","善慧仙人解一切法空而得無生忍","心體上無一切法，故一切法空為共相"],"k":["一切法空","空三昧","三三昧","空相與空性","無生忍"]},"5407-a22_100":{"s":"本集總結一切法空為空相與空性的共相，滅諦即此共相，非二乘所知；並講《勝鬘經》「如來藏無前際，不起不滅」，說如來藏恆與蘊處界同時同處。講者引某法師《勝鬘經講記》《唯識學探源》，批評其說中觀唯識不以空性為所依及「阿賴耶是神我變相」之說自相矛盾，指第八識離見聞覺知、非外道神我。","p":["滅諦即一切法空共相，非二乘境界","如來藏無前際，恆與蘊處界同時同處","講者指某法師否認空性為所依自相矛盾","本識入胎為名色所依，即萬法所依","第八識離見聞覺知，非外道神我"],"k":["滅諦","一切法空","如來藏無前際","阿賴耶識","神我","空亂意眾生"]},"5396-a22_101":{"s":"本集依平實導師《勝鬘經講記》第六輯解釋空亂意眾生，區分空相、性空（緣起性空）、空性三種空，並以明鏡與影像為喻說明其關係。再以《中論》「諸法不自生」偈解說四不生，指出萬法根本因是第八識如來藏；講者批評釋印順「緣起性空即般若實相」之說為變相無因論，亦評「物能生心」。","p":["空相、性空、空性三種空的意涵","明鏡喻：鏡為空性，影像為蘊處界","《中論》四不生說明諸法必有根本因","講者評緣起性空即實相為變相無因論","否定如來藏空性者即空亂意眾生"],"k":["空性","緣起性空","空相","四不生","如來藏","空亂意眾生"]},"5395-a22_102":{"s":"本集說明如來藏空性心是畢竟空，唯如來藏自住境界迥無一法，意識所知者非畢竟空。引《央掘魔羅經》空聚落、空河之喻說空與不空如來藏，指一念不生的離念靈知不能生萬法，非真空妙有。再依平實導師講記解釋「如來藏是法界藏」的法、界、藏三義，及三界唯心、萬法唯識。","p":["畢竟空是如來藏自己的境界","空聚落、空河喻空與不空如來藏","一念不生的離念靈知非真空妙有","法、界（功能差別）、藏三義釋法界藏","三界唯心，萬法由如來藏出生"],"k":["真空妙有","法界藏","畢竟空","空如來藏","三界唯心","離念靈知"]},"5423-a22_103":{"s":"本集探討《勝鬘經》「如來藏是法身藏」，說明法身即諸法所依的第八識，以六即佛說明從理上法身到究竟法身的六階位，阿賴耶識、異熟識、無垢識為同一心體。引《楞嚴經》因地心與果地覺須同的開示；並說二乘雖修戒定慧解脫解脫知見，因未證如來藏，只能方便說有五分法身。","p":["法身是諸法所依身，即第八識如來藏","六即佛對應法身證悟程度的六階位","阿賴耶識、異熟識、無垢識同一心體","因地發心須與果地覺同為此心","阿羅漢五分法身「有法而無身」"],"k":["法身藏","六即佛","五分法身","因地心果地覺","無垢識","盡智與無生智"]},"5393-a22_104":{"s":"本集續講「如來藏是出世間上上藏」，依平實導師講記說明菩薩證如來藏後轉依本來自性清淨涅槃所生的戒、定（大龍之定）、慧、解脫、解脫知見五分法身，及二乘所不知的法身德、般若德、解脫德；再引《法華經講義》說明入地後次第解開六根之結，至六根互通而成佛，皆依如來藏。","p":["菩薩依如來藏生起五分法身","如來藏不出不入，名為大龍之定","菩薩藏以第八識為體，謗之即謗菩薩藏","菩薩三德為阿羅漢所不知","入地後次第解六結，至六根互通成佛"],"k":["出世間上上藏","五分法身","菩薩三德","本來自性清淨涅槃","六根互通","菩薩藏"]},"5402-a22_105":{"s":"本集講解《勝鬘經》「如來藏者是自性清淨藏」，說明如來藏離見聞覺知、不分別六塵，故清淨寂滅。逐句解說《占察善惡業報經》「自性清淨心，湛然圓滿，以無分別相故」：因無分別，如來藏能隨業出生地獄乃至天身，遍在三界並依持一切法；並以三自性說明心體清淨而所藏種子有染。","p":["如來藏不分別六塵，故自性清淨","離相才是寂滅，與六塵相應即喧擾","無分別故能遍三界六道無所不在","如鏡現像，為三界一切法的依持","心體恆淨，而所含七識種子有染"],"k":["自性清淨藏","無分別相","占察善惡業報經","三自性","離見聞覺知"]},"5419-a22_106":{"s":"本集對應《勝鬘經講記》第六輯128至166頁，先講三寶：引《優婆塞戒經》說歸依法即歸依後身菩薩、歸依僧即歸依修道菩薩，以一佛寶為主。再依《大乘本生心地觀經》五百長者怯懦因緣，講父母、眾生、國王、三寶四恩，強調孝養父母福等供佛，勸發大乘心而非只求自利解脫。","p":["三寶以唯一佛寶為尊、為所依","歸依法即後身菩薩，歸依僧即修道菩薩","孝養悲母之福與供佛等無異","眾生多生互為父母，應發大悲報恩","聖王福德參與器世間，國人善惡有其分"],"k":["四恩","三寶","大乘本生心地觀經","孝養父母","菩提心"]},"5436-a22_107":{"s":"本集依《大乘本生心地觀經》講一佛寶具三身：自性身即法身，不在時空蘊處界中，一切如來尚不見心；自受用身有始無終，唯佛與佛互見；他受用身居真淨土為地上菩薩說一乘法；變化身於欲界樹下示現成道。並講四智，強調大圓鏡智心品不等於無垢識，轉識成智非滅掉諸識。","p":["自性身即法身，不在時空蘊處界中","自受用身有始無終，唯諸佛互知互見","轉識成智是轉除二障，非滅八識","他受用身居真淨土為地上菩薩說法","欲界示現成佛者為變化身"],"k":["三身佛","法身","報身","四智","轉識成智","變化身"]},"5400-a22_108":{"s":"本集講法寶的教、理、行、果：聲名句文為教法，有無諸法為理法，戒定慧行為行法，證果為果法。以《瑜伽師地論》卷45「法有二種，謂有、非有」對照理法，講者駁斥依《百法明門論》說阿賴耶識是有為生滅法的見解，並依三自性解說無願、無相、空三摩地的建立。","p":["法寶分教、理、行、果四種","有為無為名為有，我及我所名非有","講者駁「阿賴耶識是生滅有為法」之說","以算數行相問阿賴耶屬何蘊處界","依三自性建立無願、無相、空三摩地"],"k":["法寶","教理行果","三三摩地","三自性","百法明門論","阿賴耶識"]},"5413-a22_109":{"s":"本集講僧寶，引《心地觀經》三種僧與《地藏十輪經》四種僧，說明在家相者有聖法、得聖果即屬勝義僧，並舉阿支羅迦葉、玷牟留外道一日證阿羅漢及裴休等居士明心為證。講者回應對平實導師居士身的批評，主張其釐清斷我見與以含藏識為明心標的，屬勝義僧，並引《起信論講記》說明其恭敬佛。","p":["十輪經：在家相有聖法得聖果屬勝義僧","阿支羅迦葉等未剃髮亦證阿羅漢","六祖說所悟自性即含藏識","講者主張平實導師屬勝義僧所攝","引起信論講記說明其恭敬佛、非愛罵人"],"k":["勝義僧","僧寶","地藏十輪經","居士證果","含藏識","摧邪顯正"]},"5441-a22_110":{"s":"本集引《楞嚴經講記》與2000年《邪見與佛法》，說平實導師早年讚歎佛光山、慈濟，後因受抵制才回應，以示摧邪顯正非罵人。講者反問否定第八識者：無受熏持種心，因果輪迴如何成立、無餘涅槃何異斷滅。再引《菩薩瓔珞本業經》夫婦六親得互為戒師、《摩訶僧祇律》五通居士為比丘尼說四念處令證果，說明居士可傳戒說法。","p":["導師早年讚歎佛光山慈濟，後被動回應","無受熏持種之心，因果輪迴難成立","無餘涅槃若無本際則同斷滅","瓔珞經：夫婦六親得互為戒師","僧祇律：五通居士說四念處令比丘尼證果"],"k":["勝義僧","摧邪顯正","居士傳戒","受熏持種","無餘涅槃","摩訶僧祇律"]},"5433-a22_111":{"s":"本集講解《勝鬘經》「煩惱不觸心，心不觸煩惱」，指此心是第八識如來藏，唯與五遍行相應，不與煩惱相應，只收藏七轉識的煩惱種子。講者批評六識論者以意識解為「法法不相到」，引《集論》《顯揚聖教論》《成唯識論》說心所恆依心起、繫屬於心；並勸輕賤煩惱、增長善心所，正解「自性清淨心而有染」。","p":["此「心」指如來藏，非意識覺知心","阿賴耶識唯與五遍行心所相應","煩惱心所隨惱意識，非各住自性","輕賤煩惱、增長善心所以轉染成淨","自性清淨心而有染：心體淨而含染種"],"k":["煩惱不觸心","如來藏","心所法","八識論","自性清淨心","五遍行"]},"5420-a22_112":{"s":"本集說明末法見濁時像似正法盛行，須正確簡擇法義。依平實導師講記指出佛學與佛教史研究取材凡夫諍論文獻易致錯誤，舉《吐蕃僧諍記》雙方皆以意識為證。引《瑜伽師地論》算數行相與稱量行相作為思惟諸法之法，並說不般涅槃四因緣及《中阿含》算數目揵連問佛法須漸次修學。","p":["見濁時像似正法難以分辨","佛學研究取材凡夫諍論易生錯誤結論","以算數行相、稱量行相思惟諸法","不般涅槃四因緣：無暇、放逸、邪解、障","佛法須漸次修學；惡見屬染汙慧"],"k":["正思惟","見濁","算數行相","稱量行相","像似正法","漸次修學"]},"5438-a22_113":{"s":"本集辨析經論中「空」（空相、空性、空界、虛空、空無）與「有」（三界有、七有、實有、假有、勝義有）的不同意涵，並以《瑜伽師地論》少分一切與一切一切區分「一切法空」。說明空宗有宗、中觀唯識之諍出於誤解，二者皆以如來藏為核心，引玄奘作《會宗論》和會二宗，強調依如來藏才能說真空妙有。","p":["空有空相、空性、空界、虛空、空無","有分實有、假有、勝義有等","一切有少分一切與一切一切之別","空有之諍源於誤解，中觀唯識不相違","玄奘為師子光之誤作會宗論和會二宗"],"k":["真空妙有","空與有","空有之諍","中觀與唯識","如來藏","一切法空"]},"5457-a22_114":{"s":"本集探討無明與惡見兩根本煩惱。引《攝大乘論》「無始時來界，一切法等依」說阿賴耶識是所知依與涅槃之本，否定第八識即「於因無知」。說明見取或因貪利養，或由瞋生邪見；無明障礙聞思修三慧，惡見是以五利使為主的染汙慧；並引愚鈍報十業及謗大乘名放逸死，勸斷惡見、修除無明。","p":["攝大乘論明說阿賴耶識為一切法依","否定根本因即「於因無知」","見取或因貪利養，亦有因瞋生邪見","無明障礙聞思修，惡見是染汙慧","惡見為見道所斷，無明為修道所斷"],"k":["無明","惡見","五利使","見取見","阿賴耶識","斷我見"]},"3600-a16_001":{"s":"本集介紹本系列以平實導師《阿含正義》為教材，說明其專舉四阿含證明佛已隱說大乘與第八識。講者依《長阿含・梵動經》指「甚深微妙大光明法」即如來藏，以外道憶八十成敗劫為例，說明必有不壞、不可分割、不變異的記憶儲存處；佛先解剖名色，確認何者不可能是如來藏。","p":["《阿含正義》專舉四阿含證大乘是佛說","甚深微妙大光明法即如來藏","宿命憶劫顯示有儲存記憶之法","可分割、毀壞、變異的名色非如來藏","觀行即解剖：名、義、自性、差別四尋思"],"k":["如來藏","甚深微妙大光明法","名色","觀行","六十二見","阿含正義"]},"3602-a16_002":{"s":"本集以認知心理學無法研究長期記憶為引，說明佛以宿命明與心理解剖處理此問題。聲聞依佛語將名色分為五陰，再依滅盡定分為五受陰三十法；講者引《中阿含》辨死亡、滅盡定、無想定之別及壽暖識，說滅盡定為色心最大切割，並解釋眠熟與修定中意根與六識的關係。","p":["科學無法研究長期記憶的儲存處","聲聞分名色為五陰，再分五受陰三十法","辨死亡、滅盡定、無想定之差別","眠熟是意根滅六識，修定反控意根","五陰屬別境，五受陰屬遍行心所"],"k":["五受陰","滅盡定","意根","遍行心所","心理解剖","記憶"]},"3606-a16_003":{"s":"本集說明五受陰是唯識學最早根據，並引大拘絺羅之答說聲聞依禪定推知意根，卻不知大光明法為何。接著介紹緣覺以六界、十二處、十八界至六六法解剖名色，色法分析勝於聲聞；再引《長阿含》「識入母胎」經文，說名色增長而入胎識不增長，具此智慧方能轉入大乘六見處觀行。","p":["五受陰為唯識學最早根據","聲聞依禪定與佛語推知意根","緣覺以六界至六六法解剖名色","根、塵二法的區分極為困難","名色增長而入胎識不增長"],"k":["緣覺","十因緣","入胎識","六六法","十八界","意根"]},"3607-a16_004":{"s":"本集說明菩薩以「識緣名色，名色緣識」為基礎轉為六見處，作「五陰非我、不異我、不相在」的操作並參究真實禪，屬生命解剖。講者引《雜阿含》926經、南傳增支部詵陀經及《大乘起信論》，說真實禪不依一切法、諸天歸命參禪菩薩；並說《阿含正義》舉示十因緣與禪宗公案，使阿含成為大乘是佛說的證據。","p":["聲聞緣覺為心理解剖，菩薩為生命解剖","六見處：五陰非我、不異我、不相在","真實禪不依地水火風乃至見聞覺知","南北傳阿含與《起信論》說法一致","舉示阿含中禪宗公案，證大乘是佛說"],"k":["六見處","真實禪","明心","禪宗公案","大乘是佛說","如來藏"]},"3608-a16_005":{"s":"本集為「唯識學探源」首集，說明大乘唯識增上慧學是三轉法輪最甚深之法，而八識心王法理在初轉阿含期已隱說、略說。講者略述從世尊、歷代菩薩、達摩至玄奘、宋代禪師的傳承，並批評某位佛教導師受六識論與日本學術影響，主張大乘非佛說、八識為後人創說、如來藏為神我論。","p":["唯識增上慧學為三轉法輪究竟之法","八識心王法理源於初轉阿含期","阿含對第八識隱說略說以護密意","歷代菩薩及玄奘大師傳承唯識法教","講者批評某導師之大乘非佛說與六識論"],"k":["唯識學","八識心王","增上慧學","六識論","大乘非佛說","玄奘"]},"3609-a16_006":{"s":"本集說明唯識須兼攝真實唯識與虛妄唯識，講者批評某導師將佛法判為真心派、妄心派，並引太虛大師評其支離破碎。接著舉《中阿含》六界觀、「六界合故便生母胎」及《增壹阿含》六界六入六識經文，論證識界有時指入胎識第八識；又引《大乘舍黎娑擔摩經》說識界含眼識乃至第八識。","p":["唯識須兼攝真實唯識與虛妄唯識","講者批評真心派、妄心派之判分","六界中的識界指入胎之本識","六識須待胎兒根身成熟後才出生","識界亦可指八識心王具足而說"],"k":["識界","六界","入胎識","真實唯識","虛妄唯識","八識心王"]},"3610-a16_007":{"s":"本集引《中阿含》、《雜阿含》壽暖識三法經文，辨死亡與滅盡定之別，論證五無心位中六識已滅而命根所依之識仍在，即第八識。並解說玄奘《八識規矩頌》第八識頌，說第八識受熏持種、「去後來先作主公」；最後引《佛說發菩提心破諸魔經》，說此經總攝四阿含，為諸法之母。","p":["壽、暖、識三法為命根所依","滅盡定中六識滅而本識仍在身","五無心位與死亡的差別","八識規矩頌：受熏持種、去後來先","諸法之母總攝四阿含與菩薩藏"],"k":["壽暖識","八識規矩頌","第八識","滅盡定","受熏持種","入胎識"]},"3611-a16_008":{"s":"本集從人天乘因果談起，論證因法已滅不能直接生果，梵天、大自在天亦無法維繫因果，「因中有果」「果中有因」皆不通。講者說明須有一非心之心能出生、儲藏、保持業種，了別眾生心行且三世不變，因果方能平等，此即大乘所說阿賴耶識，雖藏染種而自性清淨。","p":["因法已滅，須有中間連繫方成因果","梵天、大自在天不能擔負因果","因中生果、果中有因皆說不通","須有不變心識出生並執藏業種","此心即阿賴耶識，含染而本性清淨"],"k":["因果","阿賴耶識","業種","人天乘","一切種智","真如性"]},"3612-a16_009":{"s":"本集談聲聞乘基本觀念，引《中阿含》𠻬帝比丘執意識往生不變而遭佛呵責，說明六識隨色身壞滅、不能去後世，中陰與來世六識皆為新生。講者論證意根相續而為名色之「名」，但仍須第八識為本因執持種子；並引《雜阿含》「名色緣識生」，批評六識論把七、八識說成細意識而落斷滅。","p":["𠻬帝比丘以意識往生遭佛呵責","六識隨身壞，中陰與來世六識皆新生","第八識無作無為、行相微細非常見","意根相續至後世，為名色之「名」","細意識仍是意識，六識論成斷滅見"],"k":["意根","六識論","名色緣識","第八識","常見","斷滅見"]},"3613-a16_010":{"s":"本集比較二乘涅槃與大乘涅槃，引《雜阿含》焰摩迦比丘執阿羅漢死後無所有的邪見。講者說阿羅漢滅盡十八界後並無一法入涅槃，生時亦無覺知能證涅槃，涅槃中必有本來不生不滅的心識；如來親證故說涅槃真實清涼，即本來自性清淨涅槃。並引諸佛常法與六波羅蜜，說菩薩法異於二乘。","p":["焰摩迦執阿羅漢死後斷滅為邪見","無一三界法能進入不生不滅涅槃","涅槃是本有心識所顯示","佛親證涅槃，阿羅漢不能親證","諸佛常法修六度，阿羅漢不是佛"],"k":["涅槃","無餘涅槃","本來自性清淨涅槃","阿羅漢","如來藏","六波羅蜜"]},"3633-a16_011":{"s":"本集講者批評某位法師依日本學者宇井伯壽及覺音之說，認為阿育王時尚無四阿含並稱「根本佛教」；講者引《般泥洹經》載首次結集即得四阿含反駁，並指覺音自述未證初果。另批評其「性空唯名」「真常唯心」之判，引《大般若經》說二轉法輪主旨為真如，阿賴耶識即如來清淨藏。","p":["批評依日本學者否定四阿含早出","《般泥洹經》載首次結集即得四阿含","覺音於《清淨道論》自述未證初果","二轉法輪主旨是真如，非性空唯名","阿賴耶識與如來藏為同一心體"],"k":["大乘是佛說","四阿含結集","真如","阿賴耶識","性空唯名","根本佛教"]},"3634-a16_012":{"s":"本集依《長阿含・大本經》說明過去七佛依眾生根器施設一會、二會或三會說法，及釋迦佛何以三會說法：佛見此界眾生剛強而受梵天勸請，初轉先說解脫道以建立信心，再開演般若與唯識。講者批評某法師誤解《法華經》及人天乘加增上即可成佛之說，並以學制為喻說三轉次第。","p":["七佛依根器施設一、二、三會說法","表相上度聲聞，實際所度為菩薩","釋迦因眾生剛強而三會說法","批評人天乘加增上即可成佛之說","三轉法輪由淺入深，非後人所創"],"k":["三會說法","三轉法輪","過去七佛","唯一佛乘","解脫道","法華經"]},"3635-a16_013":{"s":"本集探討佛法是否會演變，先界定佛法為能令人成佛的唯一佛乘。講者批評某法師將佛法分根本、原始、大乘、祕密大乘，並主張大乘由聲聞演化而出，以造紙術為喻反駁。接著詳述《大寶積經・富樓那會》彌樓揵馱如來滅後比丘貪著利養、陀摩尸利王子出家求深法而得帝釋傳授之事，說明大乘深法本有。","p":["佛法即能令人成佛的唯一佛乘","講者批評大乘由聲聞演化之說","彌樓揵馱佛滅後比丘貪著利養","陀摩尸利求深法得釋提桓因傳授","諸佛所證如來藏深法古今不變"],"k":["唯一佛乘","大寶積經","彌樓揵馱如來","大乘是佛說","如來藏","佛法演變"]},"3636-a16_014":{"s":"本集續講《大寶積經》：陀摩尸利、得念、耶舍、導師四位比丘每百年乘願再來宣說更深之法，信者受益、不信者毀謗，導師比丘不再來後法即滅沒。講者據此逐點反駁某法師的解讀：彌樓揵馱佛非只說聲聞法、菩薩法非含容於聲聞法、部派無菩薩說，結論是法義未曾演變，只有弘法方便不同。","p":["四位比丘乘願再來，世世說更深法","比丘眾因信與不信而分為數部","唯大乘菩薩能一再受生延續正法","反駁大乘含容於聲聞法、由演化而來","法義未變，只有弘法方便差異"],"k":["大寶積經","乘願再來","護持正法","部派佛教","大乘是佛說","佛法演變"]},"3637-a16_015":{"s":"本集依《長阿含》毗婆尸佛多修安隱觀與出離觀，說明出離觀以因緣觀、四聖諦觀蘊處界虛妄而出生死，屬世俗諦；安隱觀唯菩薩親證涅槃本際如來藏而得。並比較菩薩斷習氣、留惑潤生與二乘只斷現行，說兩觀皆依第八識；再引《般泥洹經》說首次結集只出四阿含，四阿含非成佛之法。","p":["出離觀屬世俗諦，為二乘所專修","菩薩斷習氣種子並留惑潤生","安隱觀唯菩薩親證如來藏而得","出離觀與安隱觀皆依第八識證得","四阿含屬解脫道，非成佛之法"],"k":["出離觀","安隱觀","如來藏","留惑潤生","世俗諦","三轉法輪"]},"3638-a16_016":{"s":"本集實際主題為「什麼樣的人在學佛」，由阿彌陀佛的祝福意涵與鬼谷子道、法、術談起，說明學佛不止做好人好事，而是三乘菩提的成佛之道。講者強調判斷善知識須具初果向正知見，即知斷我見、意識虛妄；並說意根為意識所依、死後不滅，主張八識心王真妄和合，六識論非佛法。","p":["阿彌陀佛意為無量光、無量壽","以鬼谷子道法術喻大乘學道","初果向須知斷我見、意識虛妄","眠熟昏迷顯示意識會間斷","八識真妄和合，六識論非佛法"],"k":["斷我見","意識虛妄","意根","八識心王","初果","六識論"]},"3639-a16_017":{"s":"本集主題為「緣起性空與真實法」。講者說明六識外有第七識意根（不反觀自己但作決定）與第八識，意識依根身及七、八識而生、只有一世；並談真實三歸依，批評四歸依之說。主張真實法即能生萬法的如來藏，緣起性空的空相須依真實法而有（假必依實），「齊識而還」之識即第八識。","p":["佛說八識，六識論非佛教","意根不反觀自己，卻會下決定","真實三歸依，批評四歸依之說","緣起性空須依如來藏，假必依實","齊識而還之識為第八識，空性非性空"],"k":["緣起性空","真實法","如來藏","意根","三歸依","空性"]},"3640-a16_018":{"s":"本集講者以元、清崇喇嘛教致佛教衰微為例，說證初果須斷我見、知意識虛妄。說明出離觀以十二因緣、四聖諦觀蘊處界虛妄，屬世俗諦；安隱觀依第八識常住不壞、自住清淨涅槃，菩薩因此不畏生死，並以布袋戲、蘋果樹為喻。另批評將意識修成無分別及「活在當下」之說，推薦無相念佛對治妄想。","p":["證初果須斷我見、知意識虛妄","出離觀觀十二因緣與四聖諦","安隱觀依如來藏常住不壞","菩薩具兩觀故不畏生死輪迴","意識修不成無分別，活在當下之誤"],"k":["安隱觀","出離觀","斷我見","如來藏","十二因緣","無相念佛"]},"4061-a16_114":{"s":"本集依《中阿含經》卷7「知行如真」經文，從四聖諦角度講解行陰：說明身行、口行、意行三行的內涵與無常苦性，三行之集如何把有情繫縛於三界，並分析身口意行之滅有慧解脫與俱解脫的差別。","p":["知行、行習、行滅、行滅道如真即得正見","身口意三行皆無常，存在即是苦","攀緣、心中語言、寶愛覺知心為三行之集","行滅分慧解脫與俱解脫，滅盡定為俱解脫","如實觀行三行可證初果乃至四果"],"k":["行陰","四聖諦","身口意行","慧解脫","俱解脫","滅盡定"]},"4065-a16_115":{"s":"本集續講行陰的行味、行患與行出：說明身口意三行的法味，以外道五現見涅槃（講者並批評藏密樂空雙運與離念靈知之說）說明意行法味；再述三行的過患，以八正道、首重正見為出離之法，並引《增壹阿含經》卷18四法本末說諸行無常。","p":["貪著三行法味是輪迴不斷的主因","外道五現見涅槃皆墮意行法味","身口意行皆依眾緣而生，無常是苦","行出須依八正道，首要建立正見","《增壹阿含》四法本末：無常、苦、無我、涅槃"],"k":["諸行無常","行陰","五現見涅槃","八正道","三法印","離念靈知"]},"4069-a16_116":{"s":"本集開始講「阿含經中諸法無我的顯說與隱說」：先解釋何謂法，再說顯說是二乘五陰諸法無我，隱說是大乘第八識如來藏的真如無我；引《佛開解梵志阿拔經》說五陰覆人、誤計五陰為我即我見未斷，並反駁大乘非佛說及將如來藏視同神我的說法。","p":["法涵蓋物質與心理一切現象","顯說：二乘五陰及所生萬法無常無我","隱說：如來藏真實存在而體性無我","五陰覆人令不見道，計五陰為我即未斷我見","講者駁大乘非佛說與如來藏神我論"],"k":["諸法無我","如來藏","五陰","我見","大乘非佛說"]},"4073-a16_117":{"s":"本集解釋《佛開解梵志阿拔經》「心識為行，行受名色」一段，辨析二乘法中心、意、識皆指意識，主張過去名心、現在名識、未來名意；說明無明令眾生輪迴，斷我見須確認五陰無常住性；並依《長阿含經》卷10破計受陰為我，以兩木相攢喻說三受因緣生滅。","p":["二乘法中心意識皆指第六意識","過去名心、現在名識、未來名意","意識細心、極細心仍是妄心","誤計受陰為我仍落我見","三受從觸緣生，觸滅受滅，非我所有"],"k":["受陰","斷我見","心意識","十二因緣","諸法無我"]},"4077-a16_118":{"s":"本集續說誤計想陰、識陰自性為真我的過失（講者批評以能知能覺為真如佛性之說），教導細觀六識自性並具未到地定以斷我見三縛結，勸證初果者迴心大乘；並引《中阿含經》卷54「六見處」與《雜阿含經》卷2說隱說本識，解說十二因緣順逆觀與譯名差異。","p":["計能知能覺為我，墮想陰識陰之中","觀六識自性虛妄，須具未到地定方斷我見","證初果後勸迴心大乘求證本際","六見處隱說與五陰不即不離的真我","十二因緣流轉還滅的順觀與逆觀"],"k":["斷我見","識陰","自性見","六見處","十二因緣","未到地定"]},"4081-a16_119":{"s":"本集逐段解說《中阿含經》卷54後段世尊與比丘的問答，說明如是知見十二因緣者不疑三世、不造五逆、不外求福田與咒術、不受第八有；並指出滅盡十二有支後仍有「恆、不變易法」，以此隱說本識如來藏，非斷滅空，亦非樂空雙運的意識。","p":["十二因緣只是緣，第一因為本住如來藏","如是知見則於三世與內法無疑","信有本住法故不犯戒、不外求","證初果者不受第八有","滅盡有支後仍有恆不變易法，非斷滅"],"k":["十二因緣","如來藏","諸法無我","本際","斷滅空"]},"4086-a16_120":{"s":"本集開講「涅槃寂靜」，恭讀並語譯《長阿含經》卷14〈梵動經〉外道五現見涅槃經文，指出五種皆是意識的生滅境界；詳說第一種以五欲中的覺知心為涅槃（講者舉藏密雙身法及某比丘尼之說為例）與第二種以初禪境界為涅槃，均非真涅槃。","p":["阿含經早已說五現見涅槃，非僅大乘才說","五現見涅槃皆是意識生滅境界","第一種：享受五欲的覺知心為涅槃","第二種：初禪離生喜樂誤為涅槃","真涅槃是第八識離見聞覺知的寂靜"],"k":["涅槃寂靜","五現見涅槃","梵動經","初禪","意識"]},"4090-a16_121":{"s":"本集續說五現見涅槃的第三至第五種，即以二禪、三禪、四禪定境為涅槃，皆是生滅有為法；並說圓寂一詞不可濫用、菩薩留惑潤生，無餘涅槃滅盡十八界唯本識獨存；再引《中阿含經》卷56說依各禪定「觀此覺無常、興衰、滅、斷、捨」方得涅槃。","p":["二禪、三禪、四禪境界仍是生滅變異法","圓寂不可作為捨報的通稱濫用","無餘涅槃滅十八界，唯如來藏獨存","《中阿含》卷56：依禪定觀此覺興衰","此覺即識陰及受想，須斷除"],"k":["涅槃寂靜","五現見涅槃","無餘涅槃","此覺","四禪八定"]},"4094-a16_122":{"s":"本集續講觀「此覺」虛妄：依初禪至四禪等持位漸次觀行，四禪中此覺最細易斷我執；解釋人有勝如、依依立依；說二至四禪的無覺無觀三昧仍有定境覺觀，無想定、滅盡定亦非無餘涅槃；並引《雜阿含經》卷5說五陰非我不異我不相在，須知有本際方能斷我見。","p":["初禪此覺粗韌，四禪此覺最細脆","人有勝如，可依善知識得勝妙觀行","無覺無觀三昧仍有定境法塵覺觀","滅盡定仍有意根，非無餘涅槃","知滅五陰後有本際，方能斷我見"],"k":["此覺","涅槃寂靜","斷我見","禪定","滅盡定","本際"]},"4098-a16_123":{"s":"本集引《雜阿含經》卷5第110經說斷我見後進斷我執、成就三種無上；說明無餘涅槃無一相可得，意識任何粗細心皆不能入；並引《中阿含經》卷43說滅盡定為苦邊、《雜阿含經》卷29說無知解脫，證涅槃無知無見；講者並批評以了了分明作主之心為涅槃心的主張。","p":["斷我執前須知五陰滅後仍有實際","無餘涅槃無六塵、無覺知心，絕對寂靜","滅盡定是苦邊，已無意識之知","涅槃是無知解脫，不知不見","三法印不得外於如來藏"],"k":["涅槃寂靜","滅盡定","無知解脫","我執","離念靈知"]},"4102-a16_124":{"s":"本集為說明三法印依如來藏之前，先講佛法中的智慧：區分人天善法、二乘解脫道智慧與大乘佛菩提智慧；說明解脫道斷我見我執與有餘依涅槃，般若分總相智（明心真見道）、別相智（相見道）與一切種智；講者並批評密宗對法界體性智的解釋。","p":["成佛須具解脫智與一切種智","人天乘為次法，不能出離三界","解脫道斷我見我執，得有餘、無餘涅槃","般若三層次：總相智、別相智、一切種智","法界體性智是如來藏空性與有性的智慧"],"k":["一切種智","般若","解脫道","佛菩提道","總相智","別相智"]},"4106-a16_125":{"s":"本集引阿含部《大般涅槃經》卷3世尊為須跋陀羅開示，說有八聖道才有四沙門、解脫及一切種智，證明阿含已有一切種智之名；並說解脫與一切種智層次不同，三乘解脫有下中上品之別，阿羅漢結集時僅存其名相，以此主張大乘是佛說。","p":["無八聖道則無沙門、解脫及一切種智","須跋陀羅聞法證果，為佛最後弟子","解脫有下品、中品、上品、上上品","佛知法性總相與別相，二乘僅知總相","阿含僅留一切種智名相，證大乘是佛說"],"k":["一切種智","八聖道","解脫","大乘是佛說","須跋陀羅"]},"4110-a16_126":{"s":"本集說明「諸行無常、諸法無我、涅槃寂靜」三法印都須依如來藏才能印定：推論無餘涅槃本際非色法、非虛空，而是入胎識第八識，並引《雜阿含經》焰摩迦斷見被訶之事；指出離念靈知通不過三法印，講者並批評某已故法師「滅相不滅即真如」之說。","p":["無餘涅槃本際非色非虛空，是第八識","焰摩迦執阿羅漢死後無所有被訶為斷見","離念靈知會斷滅，不能過諸行無常","如來藏無我性，成就諸法無我","滅相不滅只是意識觀念，非涅槃"],"k":["三法印","如來藏","無餘涅槃","入胎識","斷滅空","離念靈知"]},"4114-a16_127":{"s":"本集續辨「滅相不滅即涅槃」之說為斷滅空、惡取空：引《勝思惟梵天所問經》、《央掘魔羅經》空聚落喻說空性心不空；依《瑜伽師地論》卷36解說惡取空與善取空，指出增益執與損減執，並說以離念靈知為真如同樣違背三法印。","p":["於諸法寂滅相中求涅槃是邪見","空聚落喻：器在而中虛，如來藏不空","講者批評否定七八識之說使佛法墮斷見","《瑜伽師地論》辨惡取空與善取空","離念靈知同墮增益執與損減執"],"k":["惡取空","善取空","三法印","如來藏","增益執","損減執"]},"4118-a16_128":{"s":"本集開講「業果報系統」，主張因果輪迴的主體是各人自有的第八識如來藏；講者批評某法師所說輪迴不須大我作主體及唯識由部派演變之說，辨大梵天造物的大我說不能成立，並引《長阿含經》卷10「識入胎生名色」，駁斥意識細心相續之說。","p":["業果報系統的主軸是第八識如來藏","大我、大梵天造物說不能說明各自受報","各人自有本識收藏自己的業種","《長阿含》：名色由入胎識出生","無心定中意識滅，意根與入胎識仍在"],"k":["業果報系統","如來藏","因果輪迴","入胎識","細心相續"]},"4122-a16_129":{"s":"本集說明經論所說微細細心指第八識，引《楞伽經》藏識海與七識浪之喻；講者分三點辨正唯識由七識演變、意識細分出本識之說，並說意識不能持種到後世，業果須依如來藏中道性；後引《大般涅槃經》卷31說定業可轉，以懺悔改變業報。","p":["經論中的細心是第八識，非意識細心","藏識如海常住，七轉識如波浪","入胎識不可能由意識細分而出","意識會斷滅，不能執持業種到來世","修道與懺悔可轉重報為輕報"],"k":["業果報系統","如來藏","八識","懺悔","定業","細心相續"]},"4126-a16_130":{"s":"本集引《成唯識論》「無始時來界」偈說第八識是種子識；對新創的「業果報系統」一詞提出六項質問（可否實證、色或心、常或生滅等），說明其實即如來藏；引《楞伽經》說如來藏是善不善因；講者並批評喇嘛教三昧耶誓約與相關醜聞報導，及達賴對中觀的解釋。","p":["第八識執持種子，為諸趣與涅槃所依","六問辨正業果報系統只能是入胎識","「齊識而還」：一切法推至入胎識為止","如來藏是善不善因，能興造諸趣","否定本識則內外有恐怖，難斷我見"],"k":["業果報系統","如來藏","成唯識論","種子識","因果","藏傳佛教批判"]},"4134-a18_001":{"s":"本集區分二乘解脫道的無明（一念無明）與大乘的無始無明，引《雜阿含經》卷8、卷10說明無明即不如實知五陰無常、生滅，斷盡無明可不受後有。並說明斷三縛結的要件須篤信涅槃本際不滅，引增壹阿含四流，開始解說四聖諦的苦諦八苦與集諦。","p":["二乘無明為一念無明，大乘另有無始無明","不如實知五陰無常生滅即是無明","斷三縛結須信五陰滅後有涅槃本際","參禪者須先斷我見，以免錯認離念靈知","苦諦為五陰熾盛，集諦根源在無明"],"k":["無明","三縛結","四聖諦","斷我見","涅槃本際","雜阿含經"]},"4139-a18_002":{"s":"本集續講四聖諦的滅諦與道諦，說明滅無明即滅五陰，但五陰滅後仍有涅槃本際，故非斷滅；八正道以正見為首。並舉外道五現見涅槃及四種常見外道（意識為根本、坐到一念不生、清楚明白心為真心、意識修到不分別），以三條件檢驗意識不能作根本法，末引《長阿含經》常論見。","p":["滅諦滅無明，涅槃有本際獨存非斷滅","八正道每一道都不離正見","誤取離念靈知為常住即墮外道現見涅槃","意識不合根本法三條件，是生滅法","誤認五陰任一法為常即入六十二見"],"k":["常見外道","四聖諦","八正道","五現見涅槃","意識","無餘涅槃"]},"4143-a18_003":{"s":"本集探討阿含經中是否說有第八識，回應只承認六識者的質疑。引《雜阿含經》「齊識而還」、《長阿含經》識入母胎及《中阿含經》卷3六處六界法，說明識緣名色之識即入胎識第八識，不應在其前另立真如；並說明意處即意根，加上六識共有七識。","p":["名色由識而有，「齊識而還，不能過彼」","初受生時唯身根意根，識在名色之前","第八識入胎，不應在其前另立真如","六界中的識界即入胎識","意處為意根，加六識共有七識"],"k":["第八識","入胎識","十因緣","意根","六界","名色"]},"4147-a18_004":{"s":"本集講解心解脫，指出心解脫以證初果斷三縛結為基礎：斷身見要了知意識覺知心與三界法都無常、無真實不壞我；斷疑須信涅槃是本際實有而非斷滅；並斷戒禁取見。接著說明二果薄貪瞋癡、三果證初禪並斷五下分結，以及中般涅槃、上流般涅槃等差別。","p":["心解脫須以初果斷三縛結為基礎","意識隨六塵生滅，非真實不壞我","三界無安，天界亦會壞滅","對涅槃本際不疑，知其非斷滅","三果證初禪斷五下分結，有中般涅槃等"],"k":["心解脫","三縛結","身見","五下分結","三果","初禪"]},"4151-a18_005":{"s":"本集講慧解脫，說明三果人進一步斷五上分結及欲漏、有漏、無明漏，其中最細的我慢是對自我存在的微細喜樂，源於末那的俱生我見。又說明俱解脫加修滅盡定、大阿羅漢再修三明六通；並指出阿羅漢只能轉述佛語而不知涅槃本際，以去大陸的比喻說明，主張大乘本來自性清淨涅槃才是真實。","p":["慧解脫須斷五上分結與三漏","我慢是對自我存在的極細喜樂","俱解脫加修滅盡定，大阿羅漢修三明六通","阿羅漢不能說明涅槃本際內涵","涅槃非處所，無法可出入涅槃"],"k":["慧解脫","五上分結","我慢","俱解脫","涅槃本際","本來自性清淨涅槃"]},"4155-a18_006":{"s":"本集講「先知法住後知涅槃」，說明佛先為二乘人說有常住法，使其滅盡諸法時不恐斷滅、不疑如來。舉阿難自認緣起易解被佛遮止一事，說明有入胎識從入胎、住胎到出胎一直存在，與名色俱、為名色根本；並以彌勒授記成佛為例，指二乘未究竟緣起法，勸修大乘。","p":["先知常住法，修行才不恐懼斷滅","誤取意識證自證分為真我仍是身見","佛遮止阿難，說緣起甚深","入胎識住胎、與名色俱、相續不斷","阿羅漢未成佛，表示成佛之法仍在"],"k":["法住","入胎識","緣起法","涅槃本際","初果","大乘"]},"4159-a18_007":{"s":"本集講解脫修行的見道與修道，引《瑜伽師地論》卷21說明眾生證涅槃無有定量，隨善根、性障、福德、禪定與所遇善知識而異。逐一分析見道時成為初果、二果、三果、慧解脫、俱解脫的不同條件，以及見道後努力與否的種種結果，並說明「先修道後見道」的意義。","p":["見道與修道有種種差別相","見道前已證禪定者可頓成三果或俱解脫","性障深重者雖努力只能停在初果、二果","見道後依次修斷可成慧解脫、俱解脫","先修四禪八定，見道後才可追認為修道"],"k":["見道","修道","俱解脫","慧解脫","四沙門果","善知識"]},"4163-a18_008":{"s":"本集說明「解脫是如」，引《雜阿含經》卷12「法住、法空、法如、法爾；法不離如，法不異如」，解說因緣法與緣生法，主張「如」即本識、妙真如心，亦即涅槃本際，故無餘涅槃非斷滅空，並批評應成派中觀的斷滅見。又指無明依意識、意識依本識，須十因緣與十二因緣並觀。","p":["因緣法、緣生法不離如、不異如","「如」指本識如來藏，即涅槃本際","涅槃非滅盡後的斷滅空","無明依意識，意識依本識而存在","十因緣與十二因緣須並觀"],"k":["真如","因緣法","十二因緣","十因緣","如來藏","斷滅空"]},"4169-a18_009":{"s":"本集講解脫修行中的「不生法」，說明須善知世間集與世間滅，如斷多羅樹頭般使後有不再出生。無明滅則行滅，本識不再入胎；若觀五陰四聖諦仍斷不了我見，可修因緣觀，但不能捨十因緣。並引《雜阿含經》卷12六識身等說明世間集，強調要滅的是五陰而非入胎識。","p":["解脫在使後有不生，成就不生法","無明滅則行滅，本識不再入胎","因緣觀不可捨十因緣直觀十二因緣","有因有緣世間集，有因有緣世間滅","入胎識不可滅也不須滅"],"k":["不生法","世間集","因緣觀","無明","入胎識","無餘涅槃"]},"4174-a18_010":{"s":"本集講「解脫世間種種身」，引《法句譬喻經》「天下之苦無過有身」及四流，說明不得解脫的原因是五陰。依《雜阿含經》卷6五陰「非我、不異我、不相在」，主張確認本識存在是斷我見的大前提；並依《集異門足論》解說六識身、六觸身、六受身、六想身、六思身、六愛身都是根塵為緣而生，是世間集的原因。","p":["身為苦器，五陰是不得解脫之因","五陰非我、不異我、不相在","否定本識者會恐懼斷滅而不能證果","六識身等六六身皆依根塵為緣而生","以燈喻觀六愛身無常，漸滅我執"],"k":["五陰","六識身","非我不異我","我執","如來藏","四流"]},"4178-a18_011":{"s":"本集講佛入滅前對聲聞人的最後遺教「諸行無常，是生滅法；生滅滅已，寂滅為樂」，說明要現觀身行、口行、意行的無常，其中意行最難，即使入非想非非想天亦不離行苦、壞苦。生滅滅已指斷三界無明與欲愛；寂滅為樂指涅槃無法塵。末比較聲聞的相對解脫與大乘證本來自性清淨涅槃的不可思議解脫。","p":["諸行即三界一切法，皆生滅變異","身行口行易觀，意行變相多最難觀","非想非非想天亦無常，非解脫","生滅滅已即盡欲漏、有漏、無明漏","大乘轉依本來自性清淨涅槃"],"k":["諸行無常","無餘涅槃","三漏","意識","本來自性清淨涅槃","大般涅槃經"]},"4182-a18_012":{"s":"本集講「滅知覺方是實取解脫」，依《中阿含經》卷7大拘絺羅答舍利弗的「知覺如真、知覺習、知覺滅、知覺滅道如真」，說明三受伴隨貪瞋癡，受因觸（更樂）而生，觸滅則覺滅，並以一觸不起第二念、阿羅漢托缽減觸為例；滅覺之道為以正見為首的八正道。並批評教人保持覺知或一念不生的修法。","p":["先如實觀苦樂捨三受","受因觸生，觸滅則覺滅","一觸之下不起第二念","八正道以正見為首，否則成邪","保持覺知、一念不生不能解脫"],"k":["知覺","三受","八正道","觸","離念靈知","中阿含經"]},"4186-a18_013":{"s":"本集講四念處觀的身念處（上），指出前提是正知三界因果並有求解脫心，身念處不只是不淨觀。將身念處分為十四項，本集講前五項：行住坐臥正知以養成不放逸、威儀庠序以持戒、以善法念治斷（四正勤、四如意足）、以心治心修定（並提到無相拜佛）、正知出入息配合五蘊觀行。","p":["修四念處須信三界因果、有出離心","身念處不限不淨觀，含六觸身等","行住坐臥正知，養成不放逸","威儀庠序即守持戒律","以心治心修定，觀出入息配五蘊觀"],"k":["四念處","身念處","四正勤","禪定","出入息觀","無相拜佛"]},"4190-a18_014":{"s":"本集續講身念處十四項的後九項：初禪至四禪應斷法相的正知、修光明想（重在法光明，從斷睡眠蓋下手）、善受觀相、觀三十六物不淨、觀六界聚，以及觀死屍九想以斷色身貪欲。講者並批評達賴喇嘛自承看不懂身念住及雙修之法，強調須依實證善知識修學。","p":["正知四禪各應斷的覺觀法相","光明想重在法光明，先斷睡眠蓋","觀三十六物不淨，斷色我欲貪","觀六界聚，知色身非常住","觀死屍九想，不再留戀色身"],"k":["身念處","不淨觀","四禪","光明想","九想觀","善知識"]},"4194-a18_015":{"s":"本集講「真正解脫應滅一切知覺」（上），列出七個要點，說明須斷對五陰的執著、滅盡見聞覺知六種自性，區分常見見與自性見外道，並主張如來藏不墮三界六塵自性，非自性見。引《雜阿含經》羅陀經說心善解脫，引第221經「眼滅，色想則離」說明想即是知，須滅六塵觸知。","p":["五盛陰滅才知有涅槃之道","須滅離念靈知的六種自性","執六識自性為常即自性見外道","如來藏無六塵自性，非自性見","想即是知，須滅六入的觸知"],"k":["自性見","常見外道","心善解脫","想陰","離念靈知","四食"]},"4198-a18_016":{"s":"本集續講滅一切知覺，說明想陰即知覺性，及無想定依禪定次第滅識滅塵；引《別譯雜阿含經》卷8無所依止禪，說明須滅一切禪定覺觀與意識細心。再引《雜阿含經》第345經佛提示舍利弗「真實」，指本識是滅盡五陰而不恐斷滅的前提；末依《遊行經》說自歸依、自熾燃，批評歸依名聞利養。","p":["想陰即知覺性，執之即未斷我見","無所依止禪：不依見聞覺知與禪定","須滅意識細心與極細心","有真實本識，才敢滅五陰不恐斷滅","自歸依、自熾燃即依正法修"],"k":["滅覺觀","想陰","本識","無想定","自歸依","意識細心"]},"4202-a18_017":{"s":"本集講「我與我所俱斷方是解脫」（上），說明須斷我執與我所執，我執最細者為我慢。引《中阿含經》卷49五欲功德，說明前五識與五俱意識的見聞覺知性屬內我所，須觀其無常而斷貪；批評「性為體、心為用」為顛倒；再說外我所，並辨析慢、過慢、慢過慢、增上慢都不是我慢。","p":["真解脫須斷我執與我所執","五欲功德與六識心所同時同處","見聞覺知性屬內我所","「性為體、心為用」是反客為主","慢、過慢、慢過慢、增上慢非我慢"],"k":["我所執","我執","我慢","五欲","心所法","五俱意識"]},"4206-a18_018":{"s":"本集續講我慢，指出講者認為《佛光大辭典》將我慢解為與人比較的高下心有誤。說明阿羅漢所斷的內執有我是對自我存在的微細喜樂，大乘種智所說恆內執我則是執阿賴耶識自性；內執我所為恆執見聞知覺性。並引《長阿含經》說戒行只是小緣威儀，引周那《知法經》強調須斷惡見。","p":["我慢非與他人比較所生的慢","我慢是對自我存在的極細喜樂","大乘恆內執我即愛樂阿賴耶","內執我所為恆執見聞知覺性","戒行只是助緣，須斷惡見我見"],"k":["我慢","我執","我所執","阿賴耶識","四果","惡見"]},"4210-a18_019":{"s":"本集講二乘解脫道的修證原理（一），先說三轉法輪內容及四阿含的次序與關係，再依次說明四果：初果斷三縛結（見結含斷見、常見，戒取結以魚生天為例，疑結）、二果薄貪瞋癡、三果斷五下分結、四果斷五上分結，其中最細的慢是對自我存在的喜悅；末解說阿羅漢自證五句與諸漏永盡。","p":["三轉法輪與四阿含由總而細的次序","初果斷見結、戒取結、疑結","二果薄貪瞋癡，三果斷五下分結","四果斷五上分結，最細慢在自我存在","阿羅漢須諸漏永盡：欲漏、有漏、無明漏"],"k":["四沙門果","三縛結","五上分結","五下分結","阿羅漢","三漏"]},"4214-a18_020":{"s":"本集續講解脫道修證原理，指出其要在離貪欲與離無明；依《瑜伽師地論》解說俱解脫的心解脫即八解脫，前七通外道四禪八定，第八滅受想定為佛門獨有。並介紹八識心王，以五遍行說明滅盡定只剩作意、觸、思而能依設定出定。","p":["解脫道兩大要：離貪欲、離無明","依《瑜伽師地論》解說八解脫","前七解脫即四禪八定，通於外道","以噴飯、捨壽之例證第七識與第八識","滅盡定滅受想，仍有作意觸思而能出定"],"k":["滅盡定","八解脫","俱解脫","八識心王","五遍行","四禪八定"]},"4222-a18_022":{"s":"本集依《長阿含經》卷10阿難自謂十二因緣易懂而被佛制止之事，解說十二因緣的法說、義說與三世輪迴，並以識入母胎問答說明名色背後須有入胎識。再引《雜阿含經》「齊識而還」，說十二因緣之識為七轉識故是假號法，十因緣之識為如來藏故是真實法。","p":["阿難以十二因緣為易，佛說甚深","十二支分屬過去、現在、未來三世","識不入母胎則無名色，此識非意識","十因緣「齊識而還」之識為如來藏","十二因緣為現象界假號法，底層有如來藏"],"k":["十二因緣","十因緣","如來藏","入胎識","假號法"]},"4226-a18_023":{"s":"本集從四聖諦知苦、斷集、證滅、修道說明解脫內涵，以廚師善取主人心意喻善攝自心相。依《瑜伽師地論》分時解脫與不動法阿羅漢，舉六度退失欲自害的比丘為例，並解說八解脫、五種定障及慧解脫與俱解脫的差別，強調禪定只是解脫的增上緣。","p":["如實知四聖諦並無間修證得心慧解脫","廚師喻：善取自心相，勿攀緣外相","時解脫阿羅漢鈍根易退，或生自害念","八解脫內容與忿慢欲貪身見不堪忍五定障","俱解脫兼離定障，禪定為增上緣"],"k":["俱解脫","慧解脫","時解脫","八解脫","定障","四聖諦"]},"4230-a18_024":{"s":"本集以佛最後度化的須跋陀羅為例：他原具四禪八定與五通，聞八聖道後斷三縛結、出家證阿羅漢而成俱解脫，入火界三昧涅槃，說明世間禪定神通不能解脫。再從無學戒、慧、定（空、無相、無願三昧）說解脫功德，並對比偏修禪定、退失四禪而成一闡提的善星比丘。","p":["須跋陀羅具禪定五通仍須八聖道解脫","外道戒屬戒禁取，斷三縛結後受具足戒","無學戒、無學慧、無學定三三昧功德","善星比丘偏修禪定，親近惡友退失四禪","菩薩阿羅漢亦須具解脫功德"],"k":["俱解脫","三三昧","無學戒定慧","須跋陀羅","善星比丘","三縛結"]},"4234-a18_025":{"s":"本集說明慧解脫阿羅漢的無學解脫身與自覺涅槃，引《雜阿含經》說五蘊是壞法、涅槃是不壞法，並指如來藏自性涅槃為無餘涅槃本際。依郁瞿婁之問說六識不觸不著六塵方能見法般涅槃，再解說觸因六入處、六入處因名色，滅其欲貪可盡苦，舉羅睺羅為人說法後證果為例。","p":["無學解脫身：生已盡、梵行已立、所作已辦","五蘊是壞法，涅槃是不生不滅的不壞法","六識不觸、不著、不取六塵方見法涅槃","如來藏本來自性清淨涅槃為無餘涅槃本際","觸因六入處、六入處因名色，滅之盡苦"],"k":["無餘涅槃","六入處","名色","如來藏","本來自性清淨涅槃","羅睺羅"]},"4238-a18_026":{"s":"本集講五受陰的色集、色患、色離，並說眾生對五受陰的四取：欲取（引《賴吒和羅經》論貪財）、見取（蜱肆王堅持無後世見）、戒禁取（提婆菩薩破恆河浴福之俗）、我取。講者批評喇嘛教三昧耶戒與「不變大樂」屬戒禁取與見取，結論為斷三縛結後滅六入處欲貪方證無餘涅槃。","p":["如實知五受陰之集、味、患方能離欲","欲取：世人貪財至死不厭","見取：蜱肆王為顧顏面堅持邪見","戒禁取：提婆菩薩破恆河浴福之俗","我取為我見；滅六入處欲貪證無餘涅槃"],"k":["四取","五受陰","戒禁取見","六入處","無餘涅槃","喇嘛教"]},"4242-a18_027":{"s":"本集說明五陰內涵：依《雜阿含經》《增壹阿含經》解釋色、識、受、想、行陰，舉美食、錢財、睡眠、麻醉等例說明皆為生滅虛妄法，配合聚沫、幻化、水泡、野馬、芭蕉之喻。再引經說名色永滅則六入處滅，觀五受陰非我、無所取著，故滅盡五陰即入無餘涅槃。","p":["五陰是遮蓋有情不得解脫的五法","色如聚沫、識如幻化、受如水泡","想如野馬、行如芭蕉，皆虛妄","名色永滅則六入處滅，究竟苦邊","觀五受陰非我非我所，捨壽入無餘涅槃"],"k":["五陰","無餘涅槃","名色","五受陰","六入處"]},"4246-a18_028":{"s":"本集回答滅盡五陰入無餘涅槃是否斷滅：引《雜阿含經》「苦之本際」、四聖諦「如如、不離如」、《增壹阿含經》「本識」及五陰「非我不異我」，說明有本際存在；並以婆迦梨入涅槃、天魔尋不到其神識為例，說涅槃是如如不動的寂靜境界。講者並批評宗喀巴、達賴喇嘛等否定本際。","p":["無餘涅槃非斷滅，有苦之本際存在","四聖諦依「如」而存在","本識、真實我皆為本際異名","婆迦梨入涅槃，天魔找不到神識去處","講者批評否定阿賴耶識者落入斷常二見"],"k":["無餘涅槃","本際","本識","斷滅空","涅槃寂靜","阿賴耶識"]},"4250-a18_029":{"s":"本集說明阿含所說本際、如、本識，與般若、方等所說真心是同一心。以《心經》解說無所得心、照見五蘊皆空及諸法空相與真心非一非異，以《金剛經》說無住心；再述所知依、阿賴耶識、異熟識、無垢識等異名。講者並批評喇嘛教等誤判三轉法輪、判唯識為不了義。","p":["三轉法輪皆以真心貫穿三世","《心經》無所得心即無餘涅槃本際","諸法空相與真心非一非異","斷阿賴耶性改名異熟識，佛地為無垢識","說法深淺廣狹不同而心是同一"],"k":["三轉法輪","心經","無所得心","阿賴耶識","異熟識","真心"]},"4254-a18_030":{"s":"本集說明二乘人如何斷結證果、滅盡五陰入無餘涅槃。聲聞以四聖諦為主旨、四念處為觀行、八正道為方法，次第斷三縛結、五下分結、五上分結而證初果至四果；緣覺先觀十因緣知有「齊識而還」的入胎識，再觀十二因緣還滅至無明，知涅槃非斷滅而願滅盡五陰。","p":["有因有緣集世間、滅世間","聲聞依四聖諦、四念處、八正道證果","初果至四果所斷結使與果位","緣覺先觀十因緣確認本際之識","再觀十二因緣還滅，知涅槃非斷滅"],"k":["四聖諦","十因緣","十二因緣","聲聞","緣覺","五上分結"]},"4259-a18_031":{"s":"本集說明無餘涅槃是滅盡十八界、唯如來藏獨存，且種子功能仍在，故稱「界」而非斷滅。引《雜阿含經》有為無為二法、「滅有歸本」，並從禪定層次、無色界色種未滅、滅諦二種滅及寂滅清涼清淨真實四性論證；也列舉以意識或禪定為涅槃、滅相真如等錯誤認知。","p":["無餘涅槃是滅盡十八界，本識獨存","「界」指種子功能仍在，非斷滅","滅有歸本：有為法滅，無為法不滅","錯解：以意識心或禪定境界為涅槃","涅槃具寂滅、清涼、清淨、真實四性"],"k":["無餘涅槃","如來藏","十八界","有為無為","滅諦","八識論"]},"4264-a18_032":{"s":"本集說明三果斷五下分結、離欲界愛而發起初禪，是解脫道真正聖者的分水嶺；並說菩薩須在五欲中利樂眾生而不被繫縛。依《雜阿含經》七果解說三果五種般涅槃（中般、生般、無行、有行、上流），以《中阿含經》打鐵火星為喻，並說初、二果不算證有餘涅槃。","p":["三果斷欲界愛、具初禪，不再來欲界","菩薩不離眾生，於欲境中利樂有情","七果：四果二種，三果五種般涅槃","打鐵火星喻五種般涅槃差別","入地須頂級三果；對治貪瞋宜重病先醫"],"k":["三果","有餘涅槃","五下分結","欲界愛","中般涅槃","初禪"]},"4268-a18_033":{"s":"本集區分兩種無生：二乘蘊處界滅盡不再生，與如來藏本來無生，並以龍樹「諸法不自生」偈及「河空非無河」喻說明。依滅、靜、妙、離四行相與滅四種愛解說二乘滅諦；大乘滅諦則兼滅煩惱障與所知障，顯發如來藏功德以利樂眾生，並比較二乘與大乘的無生智。","p":["二乘無生是蘊處界不再生","如來藏本來無生，為諸法根本因","滅諦四行相：滅、靜、妙、離","大乘滅諦滅二障並顯如來藏功德","二乘與大乘無生智名同而義異"],"k":["滅諦","無生","如來藏","所知障","無生智","四聖諦"]},"4272-a18_034":{"s":"本集依《瑜伽師地論》卷20「涅槃為上首」，說明修學須先確立目標：二乘求有餘、無餘涅槃，菩薩求含無住處涅槃的四種涅槃。逐一解說信實有性、信有功德、信己有能、思所成智、無間與殷重方便、修所成智、見道、修道、證涅槃十法，並列舉幾類無法成就的錯誤修法。","p":["修學先定目標，滅諦在道諦之前","四種涅槃依如來藏真實成就","信實有性、信有功德可初步判斷法門","思修二慧與無間、殷重方便","見道、修道、究竟道有次第不可跳躍"],"k":["涅槃為上首","四種涅槃","無住處涅槃","聞思修","見道","善知識"]},"4276-a18_035":{"s":"本集說明學佛不只吃素、拜懺、行善或打坐，而是學解脫道與佛菩提道。引《優婆塞戒經》說三歸依為破苦斷煩惱，解說三寶意義與五戒保人身；講者並批評一神教、一貫道、喇嘛教的歸依不能斷我見。再引沸伽羅娑羅婆羅門及白衣聖弟子得須陀洹，說三歸五戒是證初果的基本條件。","p":["學佛是學解脫道與佛菩提道","三歸依為破諸苦、斷煩惱、得寂滅樂","佛法僧三寶皆關乎壞煩惱因","講者批評一貫道、喇嘛教歸依與戒禁取","持五戒得四增上心，可證須陀洹"],"k":["三歸依","五戒","初果","歸依三寶","戒禁取見"]},"4280-a18_036":{"s":"本集說明持戒清淨只是證果基礎，非涅槃正因。引《增壹阿含經》滿願子以波斯匿王換乘七車為喻，解說戒、心、見、無猶豫、行跡、道、知見七清淨次第；引《陰持入經》說斷三縛結方入見道，說五戒是五大施僅感人天福。再依《長阿含經》說離垢苦行只是皮，佛亦棄捨六年苦行。","p":["持戒清淨是基礎，非證涅槃正因","七車喻：七清淨次第展轉至涅槃","斷三縛結入見道，七返人天出三界","五戒為五大施，只保人天福報","離垢苦行仍是皮毛，佛棄六年苦行"],"k":["持戒","苦行","七清淨","三縛結","五戒","見道"]},"4284-a18_037":{"s":"本集依多部經論分辨有餘與無餘涅槃：《增壹阿含經》以斷五下分結與盡有漏區分，《合部金光明經》以應化二身說有餘、法身說無餘，《解深密經》以諸受是否滅盡區分；並解說三果五種般涅槃與兩類阿羅漢。再引《本事經》《成唯識論》，結論為滅盡十八界、唯如來藏獨存才是無餘涅槃。","p":["斷五下分結為有餘，盡有漏為無餘","佛依應化二身說有餘，依法身說無餘","《解深密經》：無餘依中一切受永滅","三果五種般涅槃與阿羅漢之別","無餘依涅槃唯清淨無戲論體獨存"],"k":["有餘涅槃","無餘涅槃","解深密經","法身","如來藏","五下分結"]},"4288-a18_038":{"s":"本集說明無餘涅槃中唯本際如來藏獨存，無一法可得。引法樂比丘尼「涅槃無對」及《大般若經》有二有所得、無二無所得，配合《心經》說涅槃離相待法；再引《中阿含經》《雜阿含經》說一切想與五陰須滅盡，並以《瑜伽師地論》水澄、金柔、空淨之喻說涅槃非斷滅。","p":["無餘涅槃唯如來藏獨存，無有住處","涅槃無對、無二，故無所得","一切欲想色想皆無常，須滅盡無餘","涅槃是煩惱眾苦永寂，非滅無","以離念靈知住涅槃不能成就"],"k":["無餘涅槃","十八界","如來藏","無所得","心經","五陰"]},"4292-a18_039":{"s":"本集依《阿含正義》第五輯介紹五出要界：欲、瞋恚、嫉妒、色、身見五種出離功能。先說三乘共道與大乘不共道，菩薩須斷所知障並留惑潤生；再說心解脫三果須斷我見且初禪不退，解說五下分結與五上分結。最後引《長阿含經》卷8說各出要對證三果、四果的作用。","p":["界即功能，五出要為五種出離方法","三乘共道與不共道，菩薩留惑潤生","三果心解脫須斷我見並初禪不退","五下分結與五上分結的內容","欲、嫉妒出要成心解脫；斷微細身見成四果"],"k":["五出要界","心解脫","慧解脫","五下分結","五上分結","初禪"]},"4296-a18_040":{"s":"本集續講《中阿含經》卷21的五出要界，依序說明欲出要、恚出要、害心出要、色出要與己身出要：善觀其過患、生起即令消融，心向無欲而發初禪身樂。並強調厭捨五陰是二乘解脫道的歸宿，菩薩不可厭捨五陰；此法是為已斷我見者進一步斷我所執、證三果四果而設。","p":["欲、恚、害心等生起即令融消不令舒張","離欲離恚而發起初禪身樂","色出要兼引《雜阿含》268經觀色陰集滅味患離","厭捨五陰屬二乘法，菩薩以五陰為道器不可捨","五出要界助斷我見者斷我所執證三四果"],"k":["五出要界","初禪","斷我所執","三果","無餘涅槃","中阿含經"]},"4300-a18_041":{"s":"本集依《阿含正義》第五輯介紹二乘頂忍，引《中阿含經》卷21說明頂法與頂法退：觀五蘊無常、苦、空、非我而生忍、生樂、生善法欲。並引《舍利弗阿毘曇論》與《集異門足論》界定內識為識陰六識、外識為住胎本識，主張阿含解脫道以八識論為前提，歸納頂法四種意涵。","p":["以意識入住涅槃屬外道五現涅槃","頂法：觀五蘊無常苦空非我生忍樂欲","內識為識陰六識，外識為住胎識","外識非意根，因意根屬六根不說為識","頂法四義：內識虛妄、外識常住等"],"k":["頂法","內識外識","住胎識","八識論","因緣起","二乘無生忍"]},"4304-a18_042":{"s":"本集續講二乘頂忍，逐一解說《中阿含經》所說觸、受、想、思、愛、界，說明五遍行心所依附六識而生故皆虛妄，愛與界更屬後起虛妄法。如是思惟觀察即能生忍、得頂法。最後提醒斷我見者以《阿含正義》自我檢查、勿急證四果而應迴入大乘，以及證果實無所得、不宣揚果證。","p":["觸作意受想思為五遍行心所，依八識心王","心所依附六識，緣生緣滅故虛妄","愛、界（功能差別）皆後起虛妄法","如理觀行生忍，勿被意識不滅說所退","勸勿急證四果，迴入大乘；證果無所得"],"k":["頂法","五遍行心所","斷我見","初果","迴小向大","虛妄法"]},"4308-a18_043":{"s":"本集講「戒是解脫之依憑」，語譯阿含經文說明持戒自然次第生不悔、歡悅、喜樂、未到地定、初禪、二禪，乃至如實見蘊處界空、厭離、離欲而得解脫。引阿闍世王得無根信之例，強調曾謗法謗賢聖者須懺悔；並解說戒禁取見之斷，及受菩薩戒僅為學戒、二地滿心方名持戒。","p":["持戒自然次第生不悔、喜樂、禪定至解脫","戒律清淨是取證解脫果的根本","阿闍世王殺父未證初果，僅得無根信","謗法謗賢聖者應公開懺悔，否則果證難保","斷戒禁取見；二地滿心方名真持戒"],"k":["持戒","解脫","戒禁取見","懺悔","無根信","菩薩戒"]},"4312-a18_044":{"s":"本集開講「離心意識故名涅槃」，說明二乘法與俱舍宗所說心、意、識皆指意識一心，引《俱舍釋論》《順正理論》為證，與大乘以八、七、六識為心意識不同，故禪宗祖師教人離心意識參。並討論三世意識的命名，主張過去名心、未來名意，且破斥以六識種子為意根之說。","p":["二乘所說心意識同指意識覺知心","大乘以第八識為心、意根為意、六識為識","禪宗「離心意識參」因時人所知皆意識","諸論對三世意識名心名意說法不一","破意根為六識種子說，意根恆為現識"],"k":["心意識","意根","第八識","俱舍宗","離心意識參","六識論"]},"4316-a18_045":{"s":"本集續講離心意識，先說明採「過去名心、未來名意」的理由，再語譯《雜阿含經》卷12（第290經）：凡夫能厭四大色身卻不能厭心意識，三世意識如獼猴攀枝般異生異滅；聖弟子觀觸生受而離受執，終得解脫。講者並批評古今錯悟者及當代大師仍執離念靈知為真心。","p":["未來世意識由意根持作意而現，故名意","凡夫厭色身而不厭心意識","心意識如獼猴攀枝，放一取一","觀樂苦捨觸生受、觸滅受滅，離執清涼","講者批評執離念靈知為悟者"],"k":["心意識","意識虛妄","雜阿含經","離念靈知","斷我見","無餘涅槃"]},"4320-a18_046":{"s":"本集講外道所謂涅槃，語譯《長阿含經》卷14及《梵網六十二見經》的五現見涅槃：以享受五欲、或住初禪至四禪境界為現在涅槃，皆屬意識境界。講者批評藏密雙身法屬第一種，佛門中以離念靈知為真心者亦未離意識常見；並以出生不記前世、孟婆湯之說論證意識不能去到後世。","p":["外道涅槃不外五現見涅槃","五欲自娛及初禪至四禪皆被誤認為涅槃","菩薩所證是如來藏本來涅槃","講者批評雙身法屬第一種現見涅槃","意識不能入胎去後世，以孟婆湯說反詰"],"k":["五現見涅槃","外道涅槃","意識常見","離念靈知","四禪","藏密"]},"4324-a18_047":{"s":"本集以《中阿含經》卷54《嗏帝經》證明六識是因緣生法：嗏帝比丘主張此識往生後世，佛陀訶責，說明識依根塵為緣而生，緣眼色生眼識乃至緣意法生意識，如火依所燃物得名。講者據此批評當代若干法師主張意識常住不壞，認為等同曲解誣謗世尊。","p":["嗏帝比丘執「此識往生後世」之邪見","諸比丘及佛陀訶責，識有緣則生無緣則滅","緣意根法塵生意識，如火依所緣得名","曲解佛說即屬誣謗世尊","講者批評主張意識常住的法師"],"k":["嗏帝經","因緣生法","意識虛妄","六識","一世住","誣謗世尊"]},"4328-a18_048":{"s":"本集總結離心意識一節後，進入「涅槃後有無是否無記法」的討論。講者指出佛對未證果者及外道不記涅槃後有無，是要其專修四聖諦、斷我見我執，引《雜阿含》408經與《長阿含》卷17為證；又引417經說四聖諦如如、真實、不顛倒，主張對已證者並非無記。","p":["知意識緣生，可趣初果乃至三果","佛不記涅槃後有無，令專修解脫","《雜阿含》408經：勸論四聖諦而非戲論","《長阿含》卷17：對梵志只記四聖諦","417經說四聖諦如如真實，非純無記"],"k":["無記","涅槃","四聖諦","斷我見","雜阿含經","長阿含經"]},"4332-a18_049":{"s":"本集續論涅槃後有無，語譯《雜阿含》905經：舍利弗對外道答如來滅後有無皆無記，迦葉說明如來色陰已盡、心善解脫故不可記說。講者認為對外道多說無益故以無記處理，但引《增壹阿含》卷44法身常住說明如來滅後非無；並主張此問題關係是否敢斷我見我執，絕非無記。","p":["《雜阿含》905經舍利弗答外道皆無記","迦葉釋：如來色陰滅盡，故不可記說","對外道解說易生誤解，故以無記應對","引法身常住說明如來滅後非無","知涅槃有本際不斷滅，方敢斷我見我執"],"k":["無記","無餘涅槃","法身常住","本際","外道","斷我執"]},"4336-a18_050":{"s":"本集論無餘涅槃不是斷滅境界，語譯《雜阿含》966經富鄰尼尊者答外道：佛非教斷滅，而是令斷我慢邪見。又引《增壹阿含》卷10「亦無斷壞」及《雜阿含》1077經「我常住耳」，說明阿含中留有大乘法痕跡、涅槃常住。講者批評六識論者推說無記以迴避問題。","p":["富鄰尼：佛非說斷滅，乃令斷我慢邪見","外道誤以滅盡蘊處界為斷滅","《增壹阿含》：滅盡無餘亦無斷壞","央掘魔羅事：「我常住耳，汝自不住」","講者批評否定本識者以無記迴避"],"k":["無餘涅槃","斷滅見","常住","本際","入胎識","雜阿含經"]},"4340-a18_051":{"s":"本集開講「界」的意涵：界即功能差別，種智所說的種子即是界。引《雜阿含》444經說諸界其數無量，勸比丘善學種種界，講者認為此經本屬大乘。以交通工具、建築、水道、氣體、動植物等世間例子說明功能差別，再從五停心觀及《中阿含》六界說明二乘與大乘對識界的不同觀察。","p":["界即功能差別，種子亦名界","《雜阿含》444經：諸界其數無量","以世間器物、自然物說明功能差別","五停心觀各對治不同煩惱，亦是界","六界之識界：二乘指意識，大乘指如來藏"],"k":["界","功能差別","種智","五停心觀","六界","如來藏"]},"4344-a18_052":{"s":"本集續說界的意涵，引《雜阿含》451經講十八界：六根、六塵、六識三三合為一聚，各有功能差別不相重疊，並以收音機頻率為喻。說明十八界中有七個生滅妄心，背後另有不生滅真心，合為八識；並以閉眼仍能聞聲、盲人觸臉等例說明各識功能不同。後略述三界、五趣及色界十八天、四空天。","p":["根塵識三者合為一聚，成十八界","十八界功能各別，不相重疊","六識加意根為七個妄心，另有真心","以閉眼聞聲、盲人摸臉證識各別","三界：欲界五趣、色界十八天、四空天"],"k":["十八界","八識","意根","三界","真心妄心","功能差別"]},"4348-a18_053":{"s":"本集從解脫道角度觀察十八界與三界的虛妄性：佛法所說真實是永不改變之法；五根本無今有、可壞可移植，意根於無餘涅槃亦滅；六塵以汽車、山崩、念頭為例皆暫有；六識須根塵為緣，眠熟時意識斷滅。三界可依禪定次第離去，亦屬十八界所攝，故皆虛妄，二乘人據此觀行證解脫。","p":["佛法的「真實」指永不改變之法","六根本無今有、會壞，意根亦可滅","六塵如汽車、山峰、念頭，皆暫時有","六識依根塵為緣生，眠熟意識斷","三界可離可除，皆虛妄，攝於十八界"],"k":["十八界","三界","虛妄","解脫道","意根","無餘涅槃"]},"4352-a18_054":{"s":"本集從大乘角度觀察界：引《雜阿含》卷1佛告羅睺羅觀諸所有色「非我、不異我、不相在」，說明菩薩須深細觀察六根、六塵、六識的無量差別相以成就種智。十八界及三界皆從如來藏出生而繫屬之；凡夫落有、二乘落空，菩薩證如來藏而行中道。並說以法的功能差別可檢驗禪定、果證之真偽。","p":["佛告羅睺羅：觀色非我不異我不相在","六根六塵六識差別相無量，菩薩須觀","十八界從如來藏出生，故不異我","三界皆如來藏所生，非欲界生色界","凡夫落有、二乘落空，菩薩行中道"],"k":["十八界","如來藏","一切種智","中道","三界","功能差別"]},"4356-a18_055":{"s":"本集開講有為界與無為界，先述《長阿含》卷8佛背痛請舍利弗說法，並引《佛說興起行經》說明背痛是示現因果。舍利弗結集佛法以防諍訟，二法中說有為界、無為界。講者解釋法界是諸法功能界限，舉三界、十八界、十法界為例；無為界指本識，雖無三界有為功能，卻能令人證三乘菩提。","p":["佛背痛、九惱皆是示現因果，非實罪報","舍利弗結集正法以防諍訟，說二界","法界即諸法功能界限，非迴向對象","如來藏出生萬法亦有次第條件","無為界有出世功能，故有三乘差別"],"k":["有為界","無為界","法界","如來藏","三乘菩提","長阿含經"]},"4360-a18_056":{"s":"本集續講無為界，引《雜阿含》卷17：阿難問上座、五百比丘及佛，皆答修止觀證斷界、無欲界、滅界，顯示師弟法同一味。解說三種解脫界的意涵及無漏有為法，並引《雜阿含》卷12主張正確緣起法須雙具有為與無為，依本識說緣起性空；講者批評斷滅空與意識常住之說。","p":["修止觀證斷界、無欲界、滅界","師弟所答同法同義同味，皆阿羅漢","解脫界含初果至四果及無餘涅槃功能","阿羅漢、地上菩薩具無漏有為法","緣起須雙具有為無為，依本識而說"],"k":["解脫界","無為界","無漏有為法","緣起性空","止觀","本識"]},"4364-a18_057":{"s":"本集續解《雜阿含》卷12「無為者不生、不住、不異、不滅」，說明涅槃是本來不生的本識獨住，而非蘊處界滅後的空無。講者批評某法師的「滅相不滅」與意識細心常住說皆屬有為法、想像法；並說「相續滅滅，是名苦邊」，涅槃依本識施設，阿含緣起性空屬世俗諦，如來藏兼空與不空。","p":["無為法不生不住不異不滅，指本識","講者批評「滅相不滅」是將滅止生","意識細心由意法為緣生，不能持種","相續滅滅方是苦邊","阿含緣起性空屬世俗諦；如來藏空不空"],"k":["無為法","涅槃","本識","世俗諦","空如來藏","緣起性空"]},"4368-a18_058":{"s":"本集以《央掘魔羅經》說明如來藏空與不空：先述央掘魔羅殺人取指鬘及被佛陀度化的因緣，再介紹文殊師利與央掘魔羅的對答。央掘魔羅以冰雹誤作琉璃為喻，說空的是煩惱與蘊處界，不空的是如來常住解脫；並說毀壞正法者有斷見、常見兩種。結論為佛法須雙具有為界與無為界。","p":["央掘魔羅受師所騙殺人取指鬘","文殊說諸法如虛空，央掘魔羅以冰雹喻反駁","如瓶無水名空，如來離煩惱故說空而實不空","斷見、常見二種人毀壞正法","二人實為古佛示現；佛法須雙具二界"],"k":["空如來藏","不空如來藏","央掘魔羅經","有為界","無為界","斷常二見"]},"4372-a18_059":{"s":"本集講解《阿含正義》第六輯「本際」一節，比較《中阿含・本際經》、《中論・觀本際品》與《勝鬘經》對本際的定義，主張本際即涅槃本際如來藏。並以「阿羅漢非佛」為證成大乘是佛說的第一點，引佛十號、女阿羅漢、迦葉悔過、舍利弗智不及佛、升攝波葉喻等阿含經文。","p":["小乘本際指生滅流轉中找不到最初點","《中論》破空亂意眾生，隱指蘊處界外有無生之法","《勝鬘經》明說如來藏是生死本際","以阿羅漢非佛、彌勒七因兩點證大乘是佛說","佛自知正法如林葉，不為聲聞說"],"k":["涅槃本際","如來藏","勝鬘經","中論","阿羅漢非佛","大乘是佛說"]},"4376-a18_060":{"s":"本集延續上集，以〈大品福田經〉九無學人、瞿低迦六退後自殺、阿支羅迦葉與玷牟留外道一日證果等，說明阿羅漢有高下而非佛；再依《成唯識論》卷3所引彌勒七因（先不記、本俱行、非餘境、應極成、有無有、能對治、義異文）證大乘是佛說，並以阿難於十四無記悉知悉見作結。","p":["慧解脫、俱解脫等九無學人品次不同","退法、思法阿羅漢如瞿低迦，佛無此事","彌勒七因逐一證成大乘是佛說","義異文：大小乘同說本際而深淺不同","阿難對十四無記非不知非不見"],"k":["阿羅漢非佛","大乘是佛說","成唯識論","九無學人","十四無記","涅槃本際"]},"4380-a18_061":{"s":"本集說明阿含已隱說涅槃本際：引《雜阿含》601經天子「久見婆羅門逮得般涅槃」證佛涅槃非斷滅、焰摩迦經破斷滅見、《中阿含》97經入胎識「識緣名色」，配合《成唯識論》卷3解釋；並引玄奘所舉大眾部根本識、上座部有分識、化地部窮生死蘊、有部愛阿賴耶，證阿含密意說阿賴耶識。","p":["天子偈顯佛久已示現涅槃而非斷滅","焰摩迦「漏盡身壞無所有」被斥為邪見","入胎識「識緣名色、名色緣識」即第八識","部派經中密說根本識、有分識、窮生死蘊","佛不顯說，因定性聲聞不需證本際"],"k":["涅槃本際","入胎識","阿賴耶識","識緣名色","成唯識論","唯識學探源"]},"4384-a18_062":{"s":"本集以問路救命為喻，並引《六祖壇經》「出世破邪宗」與永嘉《證道歌》，說明摧邪顯正是為救人；指六祖開悟在聞《金剛經》而非題壁偈。再辨正常見錯誤：輪迴因果抄自婆羅門、指責玄奘門戶之見；講者批評真諦譯本以阿陀那識為意根，以習慣養成說明意根運作，主張阿陀那識即阿賴耶識，並解「若執唯識真實有者」論句。","p":["摧邪顯正是救人而非罵人","六祖開悟在聞《金剛經》，非題壁偈","輪迴因果非抄襲婆羅門教","以習慣養成觀意根，阿陀那識非意根","「執唯識真實有」是指意識的法執"],"k":["摧邪顯正","阿陀那識","意根","六祖壇經","玄奘","唯識"]},"4388-a18_063":{"s":"本集講異熟：善惡業種由如來藏執藏，因緣成熟而受報；依成熟時間分現報、次生報、後報三種定業及不定業，以外道神通見善人墮惡道為例說明業力大者先報；從異時、異地、異類而熟解釋異熟；再說一念無明與無始無明，唯佛斷盡而無異熟，並引《顯揚聖教論》說異熟識。","p":["業種留存如來藏，緣熟受報","三種定業與不定業，勢力大者先報","異時而熟、異地而熟、異類而熟","一念無明與無始無明的斷除次第","唯佛無異熟，改名無垢識"],"k":["異熟","熏習","業果","無明","異熟識","如來藏"]},"4392-a18_064":{"s":"本集引《伽彌尼經》破瓶喻、《涅槃經》與《雜阿含》446經，說明熏習導致異熟、種子名為界，出世間法熏習可無異熟果；以提婆達多與阿羅漢物以類聚說熏習現象，強調遠離惡知識、依止真善知識（彌醯比丘例），批評過慢與禁讀正法書；最後論若無入胎識如來藏，熏習、異熟與因果皆不能成立。","p":["熏惡下墮、熏善上升，出世熏習無異熟","種子名界，熏習成就功能差別","應依止真善知識，遠離惡知識與過慢","二乘須信滅盡蘊處界後仍有本際","無入胎識則業種不能持至來世"],"k":["熏習","異熟","種子","善知識","入胎識","因果"]},"4396-a18_065":{"s":"本集說蘊處界是有間斷法，無餘涅槃是如來藏獨存的無間等法而非斷滅空；強調求證涅槃須具足解脫知見（引《雜阿含》卷47），並詳述外道五現涅槃：欲界一念不生及初禪至四禪境界，皆是意識未離五陰；末引《雜阿含》259經舍利弗答拘絺羅，說阿羅漢重視無間等法。","p":["蘊處界有間斷，本識才是無間等法","解脫知見不具足不能入無餘涅槃","外道五現涅槃皆是意識覺知境界","否定第八識則緣起性空成無因論","阿羅漢仍思惟五受陰無常苦空非我"],"k":["無間等法","無餘涅槃","五現涅槃","解脫知見","如來藏","斷滅空"]},"4400-a18_066":{"s":"本集延續上集：二乘只聞佛說，菩薩七住位起證如來藏即可現觀無餘涅槃實際；破「滅相不滅」為相對施設的戲論；以《雜阿含》卷1羅睺羅經「非我、不異我、不相在」說明意識與真我同處而不相混；意識夜夜斷滅是有間等法；再以仙尼經說我慢未斷故佛記其生處，入胎識即眾苦邊際。","p":["菩薩證如來藏能現觀涅槃實際","滅相不滅是相對施設的戲論","五陰非我、不異我、不相在","意識會間斷，須全面觀識陰斷我見","我慢斷則佛不記生處，入胎識是苦邊"],"k":["無間等法","涅槃實際","入胎識","我慢","斷我見","識陰"]},"4404-a18_067":{"s":"本集探討眾生為何以意識為我：意識與五十一心所相應而變相多端，又受意根掌控，故難如實知；逐一解釋五別境欲、勝解、念、定、慧，說明眾生因此說我想、我確定、我記得等；加上意識具證自證分能返觀。並說受想行三陰即識陰心所，名色皆生滅，以及三種我見我執。","p":["意識與五十一心所組合多，難如實知","意識受意根影響，六識論觀行易錯","五別境與證自證分使眾生執意識為我","受想行即識陰心所，名色皆生滅法","我執分意識分別、意識俱生、意根俱生"],"k":["意識","斷我見","五別境","心所法","名色","我執"]},"4408-a18_068":{"s":"本集區分「基礎」與「根本」：基礎指前法成就後法方能成就，根本指根源母體。說明二乘解脫道斷我見是大乘證悟般若的基礎，而大乘本住法如來藏是二乘的根本：信本住法解脫道才不成斷滅、不被斷見外道夤緣；菩薩住世方能住持二乘法；大乘非由二乘演變。","p":["基礎是前後次第，根本是根源母體","二乘斷我見是大乘證悟般若的基礎","信受本住法，解脫道才不落斷滅","菩薩住世才能永久住持二乘法","二乘聖人只能結集所解的解脫道經典"],"k":["基礎與根本","二乘與大乘","本住法","斷滅見","如來藏","大乘是佛說"]},"4412-a18_069":{"s":"本集講見道以五蘊正見為先：解說色受想行識內容及施設理由，引《俱舍論》說受、想因諍根別立為蘊，以聚沫、水泡等喻五蘊虛妄；指識蘊最易被執為我，分從解脫道、般若實相、唯識增上慧學說明了知識蘊虛妄的重要；並說八正道以正見為首，須正確聞法、經聞思修。","p":["受想別立為蘊，因貪著諸欲與諸見","五蘊如聚沫、水泡、芭蕉、夢、幻","識蘊尤其意識最易被執為真實我","了知識蘊虛妄是三乘修證的前提","八正道正見為先，須正確聽聞善知識"],"k":["五蘊","識蘊","斷我見","正見","八正道","唯識增上慧學"]},"4416-a18_070":{"s":"本集以《增壹阿含》卷21「十二部經如來所說」含方等、合集，及《央掘魔羅經》說眾生皆有如來藏，論證大乘是佛說；說明本生、本事、授記、尼陀那等經教的意涵，引《瑜伽師地論》契經含大乘相應、《大般涅槃經》說十二部經故名如來；強調佛法是實證義學，非後人思想演變。","p":["《增壹阿含》明列十二部經含方等","《央掘魔羅經》說一切眾生有如來藏","本生、本事隱含執持種子的如來藏","如來必說完整十二部經與三乘","佛法須由實證者說，非想像演變"],"k":["十二部經","大乘是佛說","如來藏","央掘魔羅經","授記","方等"]},"4420-a18_071":{"s":"本集針對某學者著作中「三乘共入無餘」之說提出辨正：引《大法鼓經》「如來涅槃而復常住」為綱領；說明《雜阿含》卷46表面說眾生、羅漢、緣覺、諸佛皆歸涅槃，但涅槃有四種；再以十力、四無所畏唯如來成就及須為如來起塔，論證佛未入無餘涅槃、阿含中隱含大乘。","p":["學者據阿含主張三乘共入無餘涅槃","《大法鼓經》：如來涅槃而復常住","涅槃有四種，阿含用詞簡略未細分","十力、四無所畏非入無餘者所能得","為如來起塔顯佛常住，證阿含有大乘"],"k":["三乘共入無餘","無住處涅槃","十力","四無所畏","如來常住","大乘是佛說"]},"4424-a18_072":{"s":"本集介紹《阿含正義》第十一章，舉《長阿含・遊行經》世尊臨涅槃出金色臂說「如優曇缽花時一現」為禪宗機鋒公案，並以藥山惟儼「法堂倒」、盤山寶積聞屠夫語悟入對照；說明公案的定義，公案在令人起疑情參究本心般若，而非提供人生啟發，並稱此為阿含禪學之開端。","p":["遊行經出金色臂是世尊最後禪宗機鋒","公案是在生活場景中探討佛法根本","公案令人起疑情，非提供人生啟發","藥山法堂倒、盤山精肉公案對照","參究本心般若之性即在修大乘"],"k":["禪宗公案","阿含禪學","般若","遊行經","參禪","本心"]},"4428-a18_073":{"s":"本集續說阿含中的公案：鴦掘魔羅追佛「我自住耳，汝自不住」，解為如來藏本來如如不動、不善不惡，七轉識才會動轉造惡；又舉《中阿含》手長者以如門、如法、如因緣攝眾，對毘沙門天王默然不視，說是顯法界定；並以志逢大師上堂良久對照，證阿含中有大乘般若。","p":["「我自住耳」指如來藏本來不動","如來藏不善不惡，七轉識可善可惡","手長者以如門、如法、如因緣攝眾","手長者默然不視天王，顯法界定","志逢大師上堂良久，作略相同"],"k":["禪宗公案","鴦掘魔羅","如來藏","法界定","如如不動","阿含禪學"]},"4432-a18_074":{"s":"本集講鴦掘魔羅追佛經中的「滅六見之法」：分別對有我見的常見者、無我見的斷見者、知有我無我卻不如實知真我的二乘人說法，並指其中含般若說法形式，為禪門理論架構；由聲聞、緣覺同入無餘推知二乘是為大乘鋪路；再引《雜阿含》真實禪、強良禪與方便禪思內寂其心，說明參禪前提。","p":["三乘同入無餘本身隱含大乘意涵","滅六見對治常見、斷見與二乘人","六見處是禪門理論架構","真實禪對強良禪，忌以貪欲求正受","方便禪思觀五陰、內寂其心為前提"],"k":["六見處","真實禪","方便禪思","鴦掘魔羅","五陰","參禪"]},"4436-a18_075":{"s":"本集開始探討「人間佛教是不是佛教」：先說佛法以解脫道、佛菩提道為內容，三轉法輪一致；講者批評人間佛教受大乘非佛說影響、持六識論。就其「論題核心」從人成佛，引《佛般泥洹經》佛上天說法、彌勒內院、善法堂，駁「離人間無佛法」；並述倡導者視文殊普賢、報身佛、念佛為鬼神化，講者認為實是否定大乘。","p":["佛教以解脫道與佛菩提道為內容","講者認為人間佛教源於大乘非佛說與六識論","經載天界亦有佛說法與天人修學","倡導者以大乘為天化鬼神化","講者判其論題核心實在否定大乘"],"k":["人間佛教","大乘非佛說","六識論","佛菩提道","解脫道","天界佛法"]},"4440-a18_076":{"s":"本集續論人間佛教的理論原則「法與律合一」：講者說倡導者以學術判教分根本、原始、部派佛教及初期大乘，所認可的法是阿含教法與性空唯名論；對比聲聞戒與菩薩戒的內容、受戒方式、戒淨標準（《菩薩善戒經》、《梵網經》），指其以聲聞法行菩薩行，法律無法合一，故判非佛教。","p":["倡導者以學術研究判教，視佛法為思想","其法為阿含教法與性空唯名論","聲聞戒防非止惡，菩薩戒含三聚淨戒","菩薩不求於有名大破戒","講者指法與律合一自相矛盾"],"k":["人間佛教","聲聞戒","菩薩戒","性空唯名論","法與律","戒定慧"]},"4444-a18_077":{"s":"本集續論第二理論原則「緣起與空性的統一」：講者說倡導者以緣起為理則、涅槃為消散後的寧靜、中道為恰到好處，與應成派一切法無自性相同；以長爪梵志主張自我否定的悖論、《中論》八不與四生偈、《金光明經》「無生是實」、《順中論》等，說中道實指無生的如來藏，並引熊十力評語，判其非佛教。","p":["倡導者以緣起性空中道為諸法實相","其涅槃近於滅相，中道如恰到好處","一切法空如長爪梵志，是自我否定悖論","《中論》四生偈推出無生涅槃本際","中道與諸法實相皆指如來藏"],"k":["人間佛教","緣起性空","中道","中論","如來藏","應成派中觀"]},"4448-a18_078":{"s":"本集續論人間佛教第三個理論原則「自利與利他的統一」。講者引《大般若經》《仁王經》《勝鬘經》《心地觀經》說明一切智智依如來藏、菩提種在阿賴耶識，並引《華嚴經》「忘失菩提心修諸善根是為魔業」，批評以十善利他為人菩薩行及以重自利或利他區分二乘與菩薩之說，結論認為人間佛教不能稱為佛教。","p":["檢視「自利與利他的統一」及人菩薩行定義","一切智智即自性清淨如來藏的本覺智慧","菩提種在阿賴耶識，否定第八識即否定菩提心","忘失菩提心而修善根，是為魔業","菩薩異於聲聞在知一切法實性，非僅重利他"],"k":["人間佛教","如來藏","菩提心","一切智智","阿賴耶識","十善業"]},"4452-a18_079":{"s":"本集回應某學問僧《印度佛教思想史》所說阿含無如來藏、念佛法門因佛像流行而後起的主張。講者舉《中阿含》白衣聖弟子念如來得增上心、手長者以如法如門如因緣攝眾、《雜阿含》六念法，說明阿含已有念佛法門；並以仙尼經五陰非我不異我不相在，主張阿含已談如來藏。","p":["批評如來藏與念佛法門為後期發展之說","阿含名相簡略，實含豐富大乘法義","念如來十號、四不壞信即念佛法門","手長者如法如門如因緣與六念法","仙尼經五陰非我不異我不相在即談如來藏"],"k":["念佛法門","如來藏","六念","四不壞信","五陰非我","阿含經"]},"4456-a18_080":{"s":"本集續講《雜阿含》仙尼經，說佛問色受想行識是否如來、如來與五陰是否相在，所說如來即眾生如來藏，並談十四難有記無記視對象而定。講者批評某法師把如來藏說成智慧相好圓滿、將真常唯心與秘密大乘混同，指《大教王經》藏識「無體無事」有能所，與如來藏不同，也駁如來藏如胎藏待誕生之說。","p":["仙尼經中的「我」即如來，指眾生如來藏","十四難有記無記，依對方是否信有本體","如來藏是法身不可見，相好圓滿源於無垢識","《大教王經》藏識無體無事，異於如來藏","如來藏本來存在，非如胎藏待誕生"],"k":["如來藏","仙尼經","秘密大乘","無垢識","十四無記","五陰非我"]},"4460-a18_081":{"s":"本集講者批評某法師將如來藏比作胎藏、外道神我，並指其「後期秘密大乘才有」與「佛教前印度教已有」兩說矛盾；引《大智度論》、《增壹阿含》及希臘巴門尼德不生不滅之論作類比。再以阿含宿命明與宿命通之別，說第八識是記憶與業報所依，可實證，非僅為解說而立。","p":["如來可依佛或眾生而稱，非即外道神我","批評兩種如來藏起源說互相矛盾","以巴門尼德「是者」論類比不生不滅","宿命明與宿命通之別在是否信受第八識","第八識為記憶與業報所依，菩薩可親證"],"k":["如來藏","第八識","記憶","宿命明","神我","不生不滅"]},"4464-a18_082":{"s":"本集辨析《中論》觀如來品「如來不有陰，何處有如來」，講者認為五門求如來是破外道依五陰施設的如來，並以「邪見深厚者，則說無如來」批評某法師斷章否定如來。再舉阿含中大梵、冷、無煩無熱皆如來號，及如來五稱譽，說明如來有無量名，尊祐即上帝義，三寶具尊祐德。","p":["《中論》五門求如來是破外道的如來","邪見深厚者，則說無如來","大梵、冷、無煩無熱皆是如來之名","五稱譽：本作、合會、為命、見、尊祐","尊祐即上帝義，佛法僧三寶皆具尊祐德"],"k":["如來","如來藏","中論","大梵","尊祐","三寶"]},"4468-a18_083":{"s":"本集探討佛會不會罵人、為己辯解、破斥錯說佛法者。講者認為法義辨正關乎法身慧命，不同於說壞話，舉百丈野狐公案及《長阿含》小緣經、阿摩晝經佛嚴斥外道、散陀那經佛自稱能說菩提，說明佛為救護眾生而破邪，並以此為正覺教團批評密宗雙身法與離念靈知等說辯護。","p":["佛菩薩除慈悲外也有破邪顯正的方便","法義辨正關係法身慧命，不是說壞話","百丈野狐：說錯一字墮野狐身","小緣經、阿摩晝經中佛嚴斥外道","佛為利益眾生而自說成佛"],"k":["法義辨正","破邪顯正","長阿含經","野狐禪","密宗雙身法","離念靈知"]},"4472-a18_084":{"s":"本集詳述《長阿含》散陀那經：尼俱陀梵志譏佛如盲牛、欲以一言困佛，佛前往其處，先指出外道苦行中的種種垢穢，再說苦行離垢法，並依次說樹皮、樹節與第一（宿命、天眼）之別；梵志折服禮佛，佛表明說法不為利養名聞，而為滅惡增善。","p":["尼俱陀梵志譏佛如盲牛，欲一言困佛","佛列舉外道苦行中的種種垢穢","苦行離垢法僅如樹皮，再說樹節與第一","梵志折服自歸，禮佛雙足","佛說法非為利養名聞，為滅惡增善"],"k":["散陀那經","苦行","尼俱陀梵志","破斥外道","長阿含經"]},"4476-a18_085":{"s":"本集說外道過分謗佛謗法時佛會前往辨正，講者批評部分法師與他教攀附、支持密宗。引《尼拘陀梵志經》說正直不諂、不曲、不虛誑者，遇善知識可於七年乃至食前食後間證三果，並說明直心三要件，指證果實質在斷結，不應曲意維護未斷我見的師父。","p":["外道謗法危及正信時應辨正破斥","尼拘陀梵志經：直心者短時可證三果","直心三要：不諂、不曲、不虛誑","證果實質在斷結，含斷對師父的情執","師父若停止誤導，則應好好護持"],"k":["直心","證果","斷三縛結","我見","破邪顯正","尼拘陀梵志經"]},"4480-a18_086":{"s":"本集講正直佛弟子應依法不依人，講者認為為正法辯解是必要的。主述《長阿含》阿耨夷經：善宿比丘怨佛不現神通、不教其父祕術而捨戒；佛對房伽婆梵志說明曾預記尼乾子伽羅樓破誓而死、究羅帝七日腹脹死生起屍餓鬼皆應驗，顯示佛為免眾生誤會而為己辯解。","p":["正法邪法不論誰說，應實際研讀判斷","佛顧慮正法弘傳，也會對誣衊作辯解","善宿比丘以佛不現神通為由捨戒還俗","佛預記伽羅樓、究羅帝之死皆應驗","辯解為建立信心，非求名聞利養"],"k":["阿耨夷經","善宿比丘","法義辨正","神通","苦行","依法不依人"]},"4484-a18_087":{"s":"本集依阿含說明說法錯謬即是謗佛。引《別譯雜阿含》比丘捉金銀之問、《雜阿含》羅陀、浮彌、富隣尼「不謗如來」問答，及《長阿含》清淨經「二俱失道，獲無量罪」。講者指誹謗賢聖、誹謗如來藏法為謗菩薩藏的重罪，勸學人重正見熏習、勿輕信傳言。","p":["異於佛意而說即名謗佛","如說說、如法說，即不謗如來","無根誹謗真善知識，死後墮惡道","清淨經：信受邪說則二俱失道獲無量罪","誹謗如來藏法屬謗菩薩藏，果報極重"],"k":["謗佛","謗法","一闡提","正見","如來藏","雜阿含經"]},"4488-a18_088":{"s":"本集依阿含證明有三世及常住本識。舉《長阿含》弊宿經童女迦葉為弊宿婆羅門證明三世實有，說明意識由意法為緣生、只存一世，不能執藏業種，唯本識貫通三世。講者並批評六識論、應成派中觀以意識細心、滅相真如、直覺為常住之說，認為藏密雙身法僅屬意識境界。","p":["三世因果須以第八識本識為所依","弊宿經：童女迦葉證明有情有三世","意識意法為緣生，只存一世","批評意識細心、滅相真如、直覺為常之說","講者認為雙身法僅是欲界意識境界"],"k":["三世因果","本識","弊宿經","六識論","應成派中觀","斷見"]},"4492-a18_089":{"s":"本集證明念佛法門非後來大乘經所發明。引《長阿含》眾集經、十上經、增一經的六念，《雜阿含》第931經佛告摩訶男修六念進得涅槃、第1349經天神觀佛足跡念佛，以及《十一想思念如來經》以十一想念佛可成無餘阿那含，說明念佛法門三根普被、貫通至成佛。","p":["眾集經、十上經、增一經皆列六念","931經：學地比丘修六念乃至涅槃","1349經：天神觀佛足跡默然念佛","十一想思念如來可成無餘阿那含","念佛法門三根普被，至等覺妙覺不離"],"k":["念佛法門","六念","雜阿含經","有相念佛","阿那含"]},"4496-a18_090":{"s":"本集說明苦行不是解脫道正修。舉阿耨夷經善宿比丘推崇究羅帝而被佛斥、《清淨經》佛呵責外苦行、《倮形梵志經》戒見具足勝諸苦行、《師子經》知斷滅盡方名苦行，及佛六年苦行後捨棄而成道。講者指出真苦行是心不放逸、不執內外我所的心苦行。","p":["迷信身苦行者為聖人，佛斥為愚癡","清淨經：外苦行自以為樂，應速除滅","戒具足、見具足勝諸苦行","師子經：知斷滅盡方名苦行","真苦行是心不放逸的內苦行"],"k":["苦行","心不放逸","解脫道","善宿比丘","內我所"]},"4500-a18_091":{"s":"本集為《阿含正義》第七輯「四阿含中已曾說摩訶衍」導讀。先以「五取蘊即自身即苦」說無需另修身苦行，再說三轉法輪中佛菩提道含攝解脫道，並舉泰國龍普多、龍普托傳說示大小乘相合。講者批評大小乘互相攻擊，指南傳經典定型較晚，不應據以否定漢傳阿含與大乘經。","p":["五取蘊即自身即苦，真苦行在知斷滅盡","三轉法輪：佛菩提道含攝解脫道","泰國龍普多、龍普托傳說顯大小乘相合","批評大小乘互相輕視攻擊","南傳經典定型較晚，不宜據以否定漢傳"],"k":["三乘菩提","大乘","解脫道","佛菩提道","南傳佛教","苦行"]},"4501-a18_092":{"s":"本集講三乘經典的初結集。述七葉窟內大迦葉主持五百阿羅漢結集，窟外由富樓那、婆師婆率眾另行結集，為上座部、大眾部之名所由；引《大唐西域記》五藏結集、《大智度論》文殊彌勒與阿難結集摩訶衍。講者推論窟外結集是因窟內未誦出大乘法。","p":["七葉窟內五百阿羅漢結集解脫道三藏","富樓那、婆師婆率眾於窟外另行結集","上座部、大眾部名稱由此而起","大智度論：文殊彌勒與阿難結集大乘","阿難不於聲聞眾中說大乘，以免錯亂"],"k":["經典結集","七葉窟","大眾部","上座部","大乘","阿難"]},"4502-a18_093":{"s":"本集說解脫道與佛菩提道相屬。說大乘出家在家菩薩並重，阿難一夜證俱解脫入結集，並舉阿含部《央掘魔羅經》多處提摩訶衍。講者批評僅憑局部文獻考據否定大乘，並以《弊宿經》童女迦葉率五百比丘、佛號正遍知世間解，及《雜阿含》一切即十二處之說，主張大乘佛世已在弘揚。","p":["大乘出家、在家菩薩僧並重","央掘魔羅經多次提到摩訶衍","科學考據結論可變，不宜據以判佛法","童女迦葉率五百比丘，顯大乘佛世已弘","一切即十二處，外此非其境界"],"k":["大乘","解脫道","童女迦葉","央掘魔羅經","十二處","經典結集"]},"4503-a18_094":{"s":"承上集，講者認為佛說外於十二處「非其境界」暗示十二處外仍有法。詳述鹿母毘舍佉度化公公的故事，及南傳中部法授比丘尼答「涅槃以何為對」時謂超越問之範圍、令向佛請問，說明涅槃本際唯佛能說；再引《雜阿含》無相心三昧，講者認為即本來常住如來藏智。","p":["外於十二處非其境界，暗示仍有法","鹿母毘舍佉度公公證初果並建講堂","法授比丘尼：涅槃非相對法，超出問範圍","涅槃本際唯佛能說，非阿羅漢所堪","無相心三昧不涌不沒，講者指為如來藏"],"k":["涅槃本際","法授比丘尼","鹿母","無相心三昧","如來藏","十二處"]},"4504-a18_095":{"s":"本集講中道及一乘，說明佛法中道非中庸或意識的中道，而是如來藏本具的體性，須親證才能理解。引《法華經》唯有一乘法、《浴佛功德經》因緣偈、《大悲經》毛端水滴喻、《佛藏經》，說三轉法輪次第相連；並以不生不滅、非斷非常、不垢不淨解說心真如中道性。","p":["中道非中庸，是如來藏本具的體性","法華經：十方佛土唯有一乘法","大悲經水滴喻：微細善根永不失","心真如本來即如，非修行而成","不生不滅、非斷非常、不垢不淨即中道"],"k":["中道","一乘","如來藏","真如","心經","三轉法輪"]},"4505-a18_096":{"s":"本集續講二乘涅槃中道性：無餘涅槃是本識如來藏獨存，非五陰自入涅槃，並引「自作自覺墮常見，他作他覺墮斷見」。講者從結集、無偽託取經、童女迦葉、佛久劫修菩薩道等方面論證大乘為佛所說，引《央掘魔羅經》「一乘中道名摩訶衍」，說無我是就蘊處界而說。","p":["無餘涅槃是本識獨存，非五陰入涅槃","自作自覺墮常見，他作他覺墮斷見","多方論證大乘經非部派後世所創","央掘魔羅經：真實我與一乘中道名摩訶衍","無我指蘊處界，本識是入胎識"],"k":["中道","無餘涅槃","本識","大乘非佛說","央掘魔羅經","常見斷見"]},"4506-a18_097":{"s":"本集續說二乘涅槃的中道性：二乘所說中道只依意識觀蘊處界緣起性空，未證實相，非真中道；真中道須親證如來藏本來中道性。並引《楞伽經》兔無角、牛有角之喻，評以意識遣除一切法的妄想中道，及《央掘魔羅經》九十六種外道起源、《心地觀經》三種僧。","p":["二乘中道依意識觀蘊處界，非真實中道","第一義指本來自在、不生不滅的如來藏","緣起性空之無我須依真實法而立","楞伽經兔無角喻：遣除有無的一切法空是邪想","央掘魔羅經外道起源；僧寶須具正知見"],"k":["中道","如來藏","第一義","無我","楞伽經","三種僧"]},"4507-a18_098":{"s":"本集說明般若經講如來藏離有無，並舉《長阿含》安隱觀與出離觀，指四阿含只說出離觀，大乘安隱觀須由般若、唯識經廣說。又舉《雜阿含》阿那律思惟一乘道得真如法，說明聲聞人將大乘法結集為解脫道；並引《央掘魔羅經》「我今常住」、一切眾生有如來藏，證明大乘本為佛說、唯一佛乘。","p":["如來具安隱、出離二觀，阿含只說出離觀","一乘道、真如法被聲聞結集為四念處","聲聞未證如來藏，故將大乘經結集為二乘法","二乘法由大乘分出，本是唯一佛乘","央掘魔羅經：如來常住、眾生有如來藏"],"k":["唯一佛乘","如來藏","第一次結集","大乘是佛說","央掘魔羅經","四念處"]},"4508-a18_099":{"s":"本集導讀〈外道及在家人依佛語證得阿羅漢果〉，駁斥在家人最多只證三果之說，舉《雜阿含》阿支羅迦葉、摩羅迦舅、外道玷牟留，《增壹阿含》在家施主及《長阿含》童女迦葉為證，說明證法在心不在身。並勸出家菩薩以佛菩提道為主修、以菩薩戒為正解脫戒，並說菩薩留惑潤生。","p":["解脫道含攝於佛菩提道，是其極小部分","阿含多例證在家人與外道可證阿羅漢果","童女迦葉以在家身率五百比丘弘法","出家菩薩應以菩薩戒為主、聲聞戒為別解脫戒","地上菩薩留惑潤生，多示現在家身"],"k":["阿羅漢果","在家修證","菩薩戒","留惑潤生","解脫道","佛菩提道"]},"4509-a18_100":{"s":"本集導讀〈二乘無學的五分法身不名五分法身〉，先說明法身即佛地無垢識、如來藏，引《心地觀經》、《央掘魔羅經》及三德之說。再舉《雜阿含》無學五支，指二乘戒、定、慧、解脫、解脫知見依蘊處界而有、捨壽即滅，有法無身；大乘五分法身則依常住如來藏，地地增上至佛地圓滿。","p":["法身指佛地無垢識，與眾生如來藏同體性","證如來藏得法身、般若、解脫三德","二乘五法依無常蘊處界，有法而無身","大乘五分法身依常住本識，至佛地圓滿","增一阿含保留大乘五分法身名相"],"k":["五分法身","法身","如來藏","三德","無學","增一阿含"]},"4540-a18_101":{"s":"本集導讀〈能破邪顯正者方是梵行支具足〉，說明佛法可以實證，引《佛藏經》、《楞嚴經》誡未證言證的大妄語，並批評自稱上人、活佛、法王者。再引《長阿含‧清淨經》說導師須能如法滅異論，《佛般泥洹經》囑驅逐不樂經者，講者並批評雙身法與六識論；最後引《瑜伽師地論》說明正見為修行根本。","p":["佛法聞思修證可實證，非僅是哲學","未證言證屬大妄語，不應自稱上人法王","導師須破斥異論，方是梵行支具足","佛囑驅逐疑經、不持戒的比丘","正見為八正道根本，應依止破邪顯正者"],"k":["破邪顯正","大妄語","梵行","正見","八正道","善知識"]},"4541-a18_102":{"s":"本集導讀〈佛涅槃後當以法為依、以戒為歸〉，說明末法的意涵與附佛法外道之害，引《雜阿含》相似像法令正法滅。再依《大寶積經》、《大集經》說四依法，依《心地觀經》說親近善友、聽聞正法、如理思量、如法修證四法要，並引《增壹阿含》持戒十功德，勸依法不依人、破邪顯正以令正法久住。","p":["末法因眾生根器陋劣、少有實證","相似像法盛行是正法滅亡主因","四依法皆依第八識實相心而說","菩薩修道四法要：親近善友至如法修證","持戒十功德可令正法久住"],"k":["四依法","末法","相似佛法","持戒","善知識","正法久住"]},"4542-a18_103":{"s":"本集為「如何簡擇真正善知識」四集之首，先列出四集大綱，說明阿含期已隱說涅槃本際，並批評某導師的大乘非佛說。引《楞嚴經》邪師說法如恆河沙、《華嚴經》善知識難值遇，區分只有名氣的「名師」與有實證的「明師」，主張依四依法簡擇善知識，並推崇平實導師為明師。","p":["四集主題源自《阿含正義》莫親近惡知識","末法邪師說法如恆河沙，真善知識難遇","名師靠媒體名氣，明師具實證智慧","華嚴經說值遇、親近善知識皆難","依法、依義、依了義、依智簡擇明師"],"k":["善知識","名師與明師","四依法","末法","惡知識"]},"4543-a18_104":{"s":"本集續論真善知識應具備的條件：只講人天善法、雙身法或依文解義者不應依止。引《佛說華手經》善知識四法、《摩訶般若經‧常啼品》能說空、無相、無作及一切種智者，以及《小品般若經》能說魔事令遠離者，說明善知識須實證如來藏並具道種智，並舉平實導師為例，末引出出家相的問題。","p":["人天善法、雙身法、依文解義者不應依止","華手經：善知識具四法，令人入善住正","能說空無相無作及一切種智是善知識","菩薩善知識教般若並令遠離魔事","真善知識須證如來藏、具道種智"],"k":["善知識","道種智","一切種智","般若","魔事"]},"4544-a18_105":{"s":"本集探討善知識是否必須現出家相：依經說出家四種分位（身心俱出家、身出心不出等），強調以心是否出家、有無實證來界定僧寶，並舉在家菩薩為例。再引《雜阿含》卷1法師定義，以及《法華經》自然智，回應無傳承法脈的質疑，主張平實導師承續玄奘大師八識法脈。","p":["出家分四種，重在心是否出家","七住以上菩薩不論在家出家皆是勝義僧","雜阿含：能說五陰厭離滅盡者名法師","地上菩薩依自然智自參自證，不必師承","法脈可上溯玄奘大師八識如來藏正義"],"k":["善知識","出家四分位","菩薩僧","法師","自然智","傳承"]},"4545-a18_106":{"s":"本集論述何謂惡知識：引《雜寶藏經》說惡知識令今世後世眾苦集聚，《業報差別經》十業得地獄報中多屬邪見，《大寶積經》四非善知識。講者批評喇嘛教四歸依、宗喀巴《密宗道次第廣論》雙身法教義，以及自稱活佛或已成佛者，勸學人遠離惡知識。","p":["惡知識使人今世後世眾苦集聚","十業得地獄報，多由斷常等邪見","大寶積經四種非善知識","講者批評喇嘛教四歸依與雙身法","自稱活佛或成佛屬未證言證"],"k":["惡知識","邪見","雙身法","大妄語","四歸依"]},"4546-a18_107":{"s":"本集依《雜阿含》卷14說三縛結（身見、戒取、疑）不斷的原因：不正思惟、習近邪道及懈怠心。說明執取能知能覺或離念靈知的意識為常住，即落外道五現見涅槃的第一種；又說親近惡知識、修雙身法屬習近邪道。並教導依根塵觸生識如實觀察識陰的生滅與識苦。","p":["三縛結不斷因不正思惟、習近邪道、懈怠","以離念靈知為真心即外道第一種現見涅槃","親近惡知識、修雙身法屬習近邪道","如實知識陰苦集滅道，三縛結自斷","根塵相觸生六識，意識無常故苦"],"k":["三縛結","斷我見","識陰","五現見涅槃","離念靈知","初果"]},"4547-a18_108":{"s":"本集續論識陰的觀行：依次說明識苦、識集、識味、識滅（意識五位暫斷）、識患及識出要，並說受、想、行陰亦同樣觀行，以斷我見及三縛結。再說懈怠心的過失，引《雜阿含》說身見的內容，以及須陀洹須具三不壞淨與聖戒成就四法，否則只是初果向。","p":["識苦、識集、識味、識滅、識患、識出要","意識五位暫斷非涅槃，須永滅方入無餘","知見與現觀有距離，勿輕言證果","身見：不見五陰是我、異我、相在","初果須三不壞淨及聖戒成就"],"k":["識陰","三縛結","斷我見","初果","聖戒成就","身見"]},"4548-a18_109":{"s":"本集講「天上天下無如佛」，批評《南傳佛法與大乘佛法》佛法後代演變更好之說，以及《印度之佛教》「釋尊未以佛道教弟子」之說。舉《大般涅槃經》菩薩、一切種智名相及七葉窟外大乘結集，證大乘為佛說；並引《增壹阿含》佛法寶由三阿僧祇劫修集，說明阿羅漢果不等於佛果。","p":["講者批評佛法演變、後代勝前代之說","批評釋尊未以佛道教弟子的主張","阿含中有菩薩、一切種智等大乘名相","七葉窟外大乘結集緊隨第一次結集","佛果須三阿僧祇劫，阿羅漢一生可成"],"k":["天上天下無如佛","大乘是佛說","一切種智","第一次結集","阿羅漢與佛"]},"4549-a18_110":{"s":"本集續說佛為無上正等正覺，若大乘非佛說則等於說後人智慧勝佛；舉《法華經》五千聲聞退席、安慧及般若趜多謗《瑜伽師地論》，說明聲聞不能結集大乘經。佛菩提道須證如來藏、別相智與種智，非解脫道可成；並引《央掘魔羅經》說如來藏的三種人、《增壹阿含》四不可思議。","p":["若大乘非佛說即等於謗佛有上","聲聞不懂大乘，故由菩薩另行結集","解脫道只成阿羅漢，佛道須證種智","能說如來藏者：如來、菩薩、菩薩聲聞","佛有四不可思議事，非小乘所知"],"k":["天上天下無如佛","大乘是佛說","如來藏","一切種智","瑜伽師地論"]},"4580-a18_111":{"s":"本集依《增壹阿含》卷44說釋迦佛授記彌勒菩薩為娑婆下一尊佛，此前自稱成佛者皆大妄語；說明龍華三會度釋迦遺法弟子成阿羅漢，勸人歸依當來下生彌勒尊佛。又說彌勒菩薩傳《瑜伽師地論》予無著菩薩以弘種智，並示現布袋和尚教導般若禪。","p":["阿含授記彌勒為釋迦後成佛第一人","龍華三會度遺法弟子成阿羅漢","應歸依當來下生彌勒尊佛","彌勒傳瑜伽師地論，講成佛一切種智","布袋和尚示現機鋒，教般若中觀"],"k":["彌勒菩薩","授記","龍華三會","瑜伽師地論","一切種智","歸依"]},"4581-a18_112":{"s":"本集從阿含經文論大乘是佛說：彌勒授記已見於最早結集的阿含，顯示佛世已有大乘。引《增壹阿含》念身要探究五陰從何來、誰所造，說明修學須信或證本識，否則恐墮斷滅而不敢斷我見。並列舉多部阿含中三乘、菩薩名相，及《央掘魔羅經》聲聞道與菩薩道之別。","p":["彌勒授記載於阿含，顯佛世已有大乘","念身須探究五陰從何來、誰所造","不信本識恐墮斷滅，不敢斷我見我執","多部阿含記載三乘及菩薩名相","央掘魔羅經：菩薩道即眾生皆有如來藏"],"k":["大乘是佛說","三乘","入胎識","彌勒菩薩","央掘魔羅經","斷我見"]},"4582-a18_113":{"s":"本集續從阿含論大乘是佛說：舉《新歲經》建立三乘、《長阿含》四種人應起塔與佛辟支聲聞之名，說明佛世已有三乘。再引毗婆尸菩薩降神、「如來往昔為菩薩時」、《佛開解梵志阿拔經》「常奉諸佛，行菩薩道」及《增壹阿含》救鴿事，證明諸佛皆由菩薩修成，駁斥阿羅漢即佛之說。","p":["新歲經、長阿含已記載三乘聖人","諸佛皆由最後身菩薩降神成佛","阿含記如來往昔為菩薩、行菩薩道","二乘聖人不能發起般若與種智","大乘非由部派聲聞發展演變而來"],"k":["大乘是佛說","菩薩道","三乘","長阿含","阿羅漢與佛"]},"4583-a18_114":{"s":"本集續舉阿含證據：《恒水經》、《緣起經》記菩薩隨佛，《增壹阿含》如來五事含授菩薩別、彌勒問六波羅蜜，證佛世已有大乘；並說大乘於後期才弘傳，故聲勢較晚。又引《增壹阿含》供養一生補處菩薩得大果報、八關齋值龍華三會，勸學人依止菩薩善知識。","p":["恒水經、緣起經記菩薩隨佛同在","如來五事含立菩薩行、授菩薩別","彌勒於阿含中請問六波羅蜜","大乘後期弘傳，聲勢初不及二乘","供養一生補處菩薩得大果報"],"k":["大乘是佛說","彌勒菩薩","六波羅蜜","龍華三會","善知識"]},"4584-a18_115":{"s":"本集探討細意識是否為生命根源：先說明我見的內容與難斷原因，依《雜阿含》說五陰無常應斷，六識每日斷滅。粗細意識皆由意根、法塵為緣而生，本識才是集世間的因；引《中阿含》識入胎三問，說明入胎識為名色本。並批評某導師以細意識說七、八識的觀點。","p":["我見即執五蘊或十八界某法為真我","六識每日眠熟、悶絕時斷滅","意識不論粗細，皆意根法塵為緣生","中阿含：入胎識是名色因、名色本","講者批評以細意識代七八識之說"],"k":["細意識","入胎識","斷我見","六識論","本際","名色"]},"4585-a18_116":{"s":"本集評析某法師《唯識學探源》認為唯識是由部派佛教演化而來的思想、以緣起為核心的觀點。講者引《增壹阿含》三乘之說證佛世已有大乘，並說明十因緣中出生名色的識支是入胎識本識，非細意識；再以第八識解釋「三界唯心，萬法唯識」，指唯識根源在如來藏。","p":["引增壹阿含三乘部眾，證佛世已說大乘","緣起只是如來藏藉緣所顯現象，非根本","十因緣識支是入胎識，非粗細意識","三界唯心萬法唯識皆以第八識為根本","本際、取陰俱識、真如皆指五陰外真實心"],"k":["唯識","第八識","十因緣","入胎識","細意識","三乘菩提"]},"4586-a18_117":{"s":"本集續評該法師從部派佛教追溯唯識的論點，逐一回應其業果相續、自作自受、業力不失、前世記憶四項疑問，說明是入胎識執持業種、貫通三世。並依《瑜伽師地論》辨無心位中意識已斷，引《雜阿含》五蓋心樹證阿含已有種子說，批評其「七識由細心分出、第八識後起」之說顛倒。","p":["法師以業果相續等問題推出細心相續說","優婆塞戒經：即作即受、異作異受、無作無受","入胎識帶業種至後世，不違諸行無常","五無心位六識皆滅，仍有意根與如來藏","雜阿含已說種子；意根非意識細分所出"],"k":["唯識","入胎識","業果相續","無心位","種子","細意識"]},"4587-a18_118":{"s":"本集探討成佛之道是否在阿含。依《心地觀經》說佛三身與報身有始無終，對照聲聞四果修證與菩薩五十二位、三大阿僧祇劫的次第，說明解脫道只是佛菩提道一小部分；即生成佛唯最後身菩薩能示現。並批評某導師「佛在人間」之說否定天人師功德，結論成佛在一切種智而不在阿含。","p":["佛具三身，真實報身有始無終","聲聞四果最多數世即可成辦解脫","菩薩五十二位須三大阿僧祇劫修證","即生成佛唯最後身菩薩示現；佛具十號","解脫道非成佛之道，成佛在一切種智"],"k":["成佛之道","二主要道","佛菩提道","解脫道","一切種智","人間佛教"]},"4588-a18_119":{"s":"本集進入《阿含正義》第十三章第三節「真我與無我之困擾」，指出此困擾自部派時期即存在並導致分裂。引《雜阿含》薩遮尼揵子聞五陰無我不喜、異比丘疑「無我誰受報」，說明斷我見之難；並說真我即第八識，無我性而常住；末引闡陀比丘雖知無我仍不樂無我。","p":["真我無我之諍是部派分裂原因之一","常見外道不樂聞五陰無常無我","異比丘疑無我則誰受報，斷我見不易","第八識常住而無我性，故名真我","闡陀比丘知無我而恐懼、不喜無我"],"k":["真我","無我","斷我見","第八識","部派佛教","五陰"]},"4589-a18_120":{"s":"本集續談真我與無我，說明實證或信受如來藏常住，方能於內於外無恐怖。講者批評錯悟者執離念靈知為真心，以及應成、自續派中觀之說；引《雜阿含》《中阿含》說明我慢是對自我存在的喜樂；再以薩遮尼犍子國王喻說明能自在獨存者方名真我，並批評只依眾緣生蘊處界為無因論。","p":["信受或實證如來藏，於內於外無恐怖","批評錯悟者以離念靈知意識為常住心","我慢是喜樂自我存在，非對他人起慢","離念靈知、意識細心皆藉緣生，非自在","唯自在常住能生萬法者方名真我"],"k":["真我","我慢","離念靈知","如來藏","無因論","中觀"]},"4620-a18_121":{"s":"本集分析某學派主張的緣起性空無我，講者認為其否定本識，因而落入世俗論、無因論、斷滅論三種本質，並批評「滅相不滅」「滅相真如」之說。說明大乘是安隱觀、二乘是出離觀，真我即入胎識本識；末引《長阿含》「緣識有名色、緣名色有識」，解說本識須住名色方示現三界。","p":["否定本識的緣起性空只是世俗論","滅相依意識而施設，蘊處界滅盡即不存","大乘安隱觀與二乘出離觀之別","真我即涅槃本際的入胎識","緣識有名色、緣名色有識的正解"],"k":["緣起性空","斷滅論","無因論","本識","名色","真我"]},"4621-a18_122":{"s":"本集續辨該法師扭曲「識與名色相依」經文，暗示本識由名色生。引《雜阿含》294經「得此識身」，說明是新生五陰獲得本識功能，菩薩能現觀而不恆內執我；並指入胎初期尚無意識，故入胎識非六識，亦非認識論所能了知；最後說嗏帝比丘被呵是因主張意識往來三世。","p":["本識不由名色生，只須名色方現三界","雜阿含294經「得此識身」之義","入胎識不通六識，入胎初期尚無意識","本識非禪定或認識論所能認識","嗏帝比丘被呵是因執意識往來三世"],"k":["本識","入胎識","名色","十因緣","意識","恆內執我"]},"4622-a18_123":{"s":"本集探討病苦時如何解脫。說明止痛藥、勉強保持一念不生都不究竟，並舉李元松病後懺悔之例。主要講解《雜阿含》卷37阿濕波誓重病不能入定而生悔，佛陀教以五蘊非我、不異我、不相在，依解脫道與佛菩提道的智慧三昧得解脫；再舉德山禪師臨終「哎喲」之公案說明不病者。","p":["止痛藥、一念不生無法真正解脫病苦","禪定依色身意識，重病時無法入定","以空、無相、無願智慧三昧觀五蘊","五蘊非我、不異我、不相在指真我","德山禪師公案：真我不生不病"],"k":["智慧三昧","病苦","禪定","真我","五蘊","無相心"]},"4623-a18_124":{"s":"本集主張《雜阿含》與《增壹阿含》原屬大乘經，因聲聞人聽不懂大乘法義，只結集其中與解脫道相關部分而成二乘經。舉證經中「非我、不異我、不相在」多處出現，以及《雜阿含》558經無相心三昧「不勇、不沒」之說，說明第八識才是真正無相心，並指五百結集未邀菩薩參與。","p":["阿含中已有種子、真如、本識等大乘名相","「非我不異我不相在」為大乘義理","雜阿含558經無相心三昧「不勇不沒」","第八識不與六塵相應，是真正無相心","唯識非源於阿含，而源於大乘經典"],"k":["經典結集","雜阿含","增壹阿含","無相心三昧","第八識","大乘非佛說"]},"4624-a18_125":{"s":"本集講佛教結集史實。先說佛法逆俗，提醒學人應以教證、理證簡擇行銷包裝的相似佛法；再依平實導師《童女迦葉考》所引資料敘述南傳六次結集，得出唯五百結集是阿含經典的結集。並說大乘菩薩當場表示亦欲結集，七葉窟外千人大結集應在五百結集後不久完成，而非數百年後。","p":["佛法與世俗相背，邪常嫉正","須以教證理證簡擇相似佛法","南傳六次結集經過概述","唯五百結集是阿含經典結集","七葉窟外千人大結集緊接五百結集"],"k":["經典結集","七葉窟結集","相似佛法","大乘經典","部派佛教"]},"4625-a18_126":{"s":"本集依《雜阿含》卷1說明佛所說法師，是能說五陰生厭、離欲、滅盡、寂靜而令人斷我見者，不在剃髮著衣的表相；並引《大般涅槃經》說能宣說如來藏者名為菩薩。講斷我見與四聖諦之難，強調親近真善知識；又辨「涅槃後有無」並非一向無記，並批評史密豪森的阿賴耶識成立說。","p":["法師定義在說法內容，不在出家表相","能說如來藏、教人成佛者名為菩薩","射百分之一毫毛喻了知四聖諦之難","毒箭喻：涅槃後有無非一向無記","批評史密豪森認為意根、阿賴耶後起"],"k":["法師","善知識","斷我見","無記","四聖諦","如來藏"]},"4626-a18_127":{"s":"本集說明唯識根源是大乘經典而非阿含：聲聞人聽聞二、三轉法輪後陸續雜誦，形成《雜阿含》與《增壹阿含》。引《雜阿含》213經說六識依根塵二法而生，再列聽聞如來藏法生煩惱而不能斷我見的四原因之一：不知無為本識不生不滅而內有恐怖，並以293經說明「不得得想」之過。","p":["雜阿含、增壹阿含由聲聞人雜誦結集而成","六識皆藉根塵二法生起，是生滅法","解脫道只是唯識增上慧學的極小部分","不知本識無為不生滅，內有恐怖","不得得想、未證言證，障礙斷我見"],"k":["唯識","本識","斷我見","雜阿含","經典結集","有為無為"]},"4627-a18_128":{"s":"本集續講不能斷我見的其餘三原因：只依表相崇拜僧人，並依《心地觀經》說三種僧、《地藏十輪經》說在家勝義僧；不解義理而誹謗如來藏，引阿含部《央掘魔羅經》瓶中燈、乳酥喻；錯悟者執離念靈知而謗如來藏為神我。末提辨別惡知識第一點：否定大乘者有見取見。標題語實見於下一集。","p":["只依僧衣表相崇拜，無法斷我見","三種僧與在家相的勝義僧","央掘魔羅經明說一切眾生有如來藏","無如來藏則三乘修行皆空修梵行","否定大乘者有見取見，非初果人"],"k":["如來藏","勝義僧","斷我見","惡知識","央掘魔羅經","見取見"]},"4628-a18_129":{"s":"本集續講辨惡知識第二點：否定本識者不可能是三果乃至初果人。解說阿含「解名色本，即得應真」，勸謗法者懺悔；引《玉耶女經》「大乘教」與童女迦葉之事證佛世已有大乘。再從五點論證大乘非由部派演變，批評某法師「佛法演變思想史」不符史實與法義。","p":["否定本識者非初果，更非三果","解名色本即得應真：知名色從本識生","勸謗如來藏者懺悔，迴心護持正法","玉耶女經「大乘教」證佛世有大乘","五點論證大乘經典非部派所創"],"k":["本識","名色","大乘非佛說","部派佛教","懺悔","經典結集"]},"4629-a18_130":{"s":"本集為本單元完結篇，續論第六點：方廣唯識經與阿含、般若次第井然而不矛盾，證為菩薩千人結集所成。強調三乘菩提皆以第八識如來藏為核心，佛法從未演變，演變只在凡夫之間；原始佛法應涵蓋三轉法輪。提出判斷錯悟兩標準，並引《雜阿含》卷32相似像法令正法滅，呼籲支持法義辨正。","p":["唯識經與阿含般若不相違，非後人所造","三乘皆以第八識為核心，法不演變","原始佛法應含三轉法輪全部經典","錯悟兩標準：堅持六識論、以意識為第八識","雜阿含卷32：相似像法出則正法沒"],"k":["第八識","如來藏","三乘菩提","相似佛法","原始佛法","八識論"]},"1812-a07_031":{"s":"本集講解大乘與小乘的差別。引《增壹阿含》《長阿含》說明佛世已有大小乘之名，並批評「佛法一味、只差心量」之說淺化佛法。以《大智度論》二道，說明聲聞觀四聖諦、緣覺觀十二因緣，都只斷蘊處界我見我執；大乘則親證本際如來藏，再引《法華經》《深密解脫經》說三乘匯歸一佛乘。","p":["《阿含》經文中已有大乘、小乘之名","講者批評「大小乘只差發心大小」之說","聲聞觀四聖諦，緣覺觀十因緣、十二因緣","大乘以親證本際如來藏為見道","二乘含攝於大乘，匯歸一佛乘"],"k":["大乘小乘","一佛乘","如來藏","四聖諦","十二因緣","斷我見"]},"1866-a07_032":{"s":"本集回答佛教是否相信閻羅王，主張重點不在信或不信，而在佛為何宣說閻羅王。引《長阿含》說閻羅王晝夜受苦，《鐵城泥犁經》說閻羅王教化罪人知道罪業是自作自受，《華嚴經》說菩薩發願示現為閻羅王；並說明不同根器的人聽聞後會有不同的啟示。","p":["不應只討論信不信，應思惟佛說此事的用意","《長阿含》：閻羅王一日中半日受苦","閻羅王教罪人知道罪業是自作自受","《華嚴經》：菩薩發願示現為閻羅王度眾","下、中、上、上上根器聞後的收穫不同"],"k":["閻羅王","世界悉檀","地獄","因果業報","根器","菩薩示現"]},"1848-a07_033":{"s":"本集討論佛教是不是厭世或出世的宗教，指出厭世、出世是就學佛的人說，而不是佛教本身。分析學佛的種種動機與聲聞性、菩薩性、不定性三類根器；引《增壹阿含》說聲聞以滅五陰求出離，引《摩訶般若經》說菩薩常為二乘作福田，菩薩生生入世，同時也有出世功德。","p":["厭世、出世是就學人說，不是佛教本身","一般人生追逐五欲，像永遠咬不到的紅蘿蔔","聲聞性、菩薩性、不定性三類根器","聲聞求滅五陰身而出離生死","菩薩入世利生，同時有出世功德"],"k":["厭世出世","聲聞性","菩薩性","五陰","如來藏","菩薩道"]},"1922-a07_034":{"s":"本集是「最好修學哪一宗」的上集，依序介紹律宗、天台宗、密宗、三論宗、俱舍宗、淨土宗、禪宗、華嚴宗、法相唯識宗的宗旨與修學內涵。講者認為各宗都只是佛法的一部分，並批評密宗是外道法，也批評把三論宗的空說成一切法空；又說明禪宗破參是七住見道，悟後仍須繼續進修。","p":["分宗立派不合佛意，各宗只是佛法一部分","戒律是各宗共修，單持戒不能成佛","講者批評密宗心外求法，三論宗誤解一切法空","淨土宗分廣義與狹義，攝受三乘根器","禪宗破參是七住見道，不是一悟成佛"],"k":["宗派","禪宗","淨土宗","密宗","法相唯識","如來藏"]},"1923-a07_035":{"s":"本集是「最好修學哪一宗」的下集。說明分宗立派的原因，主張修學應以親證法界實相為目標，依「五度修福業，憑之得般若」的次第，先修布施、持戒、忍辱、精進、禪定的福德，再熏習般若正見。逐一說明各宗都離不開六度萬行，並引《增壹阿含》《法華經》說三乘匯歸一佛乘，結論是不應分宗別派。","p":["宗派形成多因感應、大德攝眾或偏好法門","修學應以親證法界實相為目標","五度修福德，再熏習般若正知見","各宗都須回歸六度萬行","一佛乘是佛菩提道，不是只有解脫道"],"k":["六度","一佛乘","宗派","福德資糧","般若","佛菩提道"]},"1808-a07_036":{"s":"本集回答是否一定要看破紅塵才能學佛。先說明紅塵一詞的世俗來源與禪門用例，指出世人所謂看破紅塵只是換到另一種紅塵；再分析各種學佛動機。講者說佛法中的紅塵是六根、六塵、六識十八界，只捨六塵不算看破；也批評只教離貪瞋癡的說法如石壓草；並以大隱、小隱說明菩薩悟後入廛垂手。","p":["紅塵源自世俗詞語，後為佛門借用","世人看破紅塵，只是進入另一種紅塵","學佛動機多樣，不必先看破紅塵","佛法中的紅塵即十八界，須見其虛妄","菩薩悟後入廛垂手，是大隱"],"k":["十八界","看破紅塵","五陰","我見","六塵","解脫"]},"1908-a07_037":{"s":"本集講解學佛者如何課誦。指出佛世沒有課誦形式，課誦是精進用功的方便；儀軌可以參考，但不可本末倒置，法會本來是說法之會。分析六類課誦目的，駁斥「學佛要無所求」；說課誦《阿彌陀經》應熏習三福淨業，課誦《心經》應思惟佛開示悟入的用意，進一步求懂經中真義。","p":["課誦是方便，佛世重在聽法、思惟","法會是說法之會，不應以儀軌取代","應先問自己為何課誦，分六類目的","駁斥學佛要無所求，求悟是動力","誦《心經》應思惟開示悟入佛知見"],"k":["課誦","心經","阿彌陀經","三福淨業","開示悟入","般若知見"]},"1889-a07_038":{"s":"本集講解在家學佛與出家學佛的不同。說明出家有出世俗家與出三界家兩義，引《維摩詰經》《大莊嚴法門經》《增壹阿含》四雙八輩及《佛藏經》，說真正的出家與僧要從證法來看，至少分證初果向。以《譬喻經》井中蜂蜜比喻貪五欲，並說明斷我見後修六度會事半功倍。","p":["出家分出世俗家與出三界家","發菩提心即出家，不只看剃髮染衣","僧以四雙八輩定義，有身見不在僧數","《譬喻經》：貪五欲如貪井中蜂蜜","斷我見後修六度事半功倍"],"k":["出家","斷我見","僧寶","三縛結","六度","五欲"]},"1895-a07_039":{"s":"本集是「如何一門深入」上集。引《楞嚴經》說明一門深入原指於六根中選一根門觀察，與現在專修一法門的意思不同。以念佛求生極樂為例，說明仍須三福淨業及前五度福德；以佛法殿堂八萬四千門作譬喻，說明往生只是階段目標；並指出真正的「一經」是如來藏「此經」，證此經的人不敢說一經通百經通。","p":["《楞嚴經》原意是六根中選一根深入","念佛一門深入仍需三福淨業與五度","佛法殿堂門內有門，須一門接一門開","求生極樂只是階段性目標","真正的一經是如來藏，非一經即通百經"],"k":["一門深入","楞嚴經","念佛","三福淨業","如來藏","六度"]},"1896-a07_040":{"s":"本集續談如何一門深入。主張先親證此經如來藏作為基礎；以念佛為例，說明可從唸佛轉為無語言文字的憶佛，並介紹正覺同修會從憶佛、拜佛到看話頭、參話頭的次第。也說明參禪須具備知見、定力與福德，依止一位老師的前提是真善知識，並引《華嚴經》與《尸迦羅越六方禮經》說善知識難遇。","p":["先證此經，再一門接一門通達","由唸佛轉為憶佛，是一門深入的轉進","唸佛、唸咒修定，受語言文字所限","參禪前須多聞熏習正知見，兩者不衝突","依止一師須是真善知識，善知識難遇"],"k":["一門深入","憶佛","參禪","善知識","如來藏","多聞熏習"]},"1875-a07_041":{"s":"本集回答佛陀是不是創世主。先介紹一神教《創世紀》與《梨俱吠陀》的造物主思想，再說明佛教的宇宙是欲界、色界、無色界三界，並指出初禪以上才是禪定，四面佛其實是大梵天。引《優婆塞戒經》說器世間由眾生十業道所成，造物者是眾生的善惡業；業種由種子識收藏，四大極微也依如來藏和合生滅。","p":["一神教與吠陀思想都主張有造物主","三界包括欲界、色界、無色界","初禪以上才算禪定，四面佛實為大梵天","器世間由眾生善惡業共同成就","業種藏於種子識，四大依如來藏而有"],"k":["創世主","三界","業力","如來藏","四大","禪定"]},"1829-a07_042":{"s":"本集講解佛教為什麼要信仰三寶。引《大乘本生心地觀經》三寶如世間珍寶具足十義，說明佛、法、僧對眾生的恩德。依《悲華經》《法滅盡經》說末法時期有假佛、假法、假僧，講者批評自稱是佛或以意識清明為開悟的人；引《地藏十輪經》說四種僧，並以《六祖壇經》說明無相三歸依、歸依自心三寶。","p":["三寶如世間珍寶，具足十種意義","佛開示法，法說解脫之道，僧住持佛法","末法時期須辨別假佛、假法、假僧","四種僧中，證果者即勝義僧","歸依如註冊，六祖說歸依自心三寶"],"k":["三寶","歸依","勝義僧","末法","無相三歸依","如來藏"]},"1843-a07_043":{"s":"本集回答佛教徒是否都願往生極樂世界。以一位師兄助母親念觀世音菩薩往生的事例開頭，說明佛弟子應預先安排下一世的去處。指出不一定都要往生西方，可以隨願往生十方淨土；再介紹彌陀四十八願的殊勝與十念往生，但五逆和謗法除外，並說往生仍須累積三福淨業。","p":["佛弟子應預先決定下一世去處","不一定都往生極樂，可隨願生十方淨土","持一佛號，現世得十種利益","彌陀四十八願殊勝，十念必生","唯除五逆、謗法，仍須三福淨業"],"k":["往生極樂","淨土","阿彌陀佛","四十八願","三福淨業","念佛"]},"1885-a07_044":{"s":"本集講解「四大皆空」的意思。先指出世俗把空理解成什麼都沒有是誤解；再說明五蘊分為名與色，四大地、水、火、風構成色蘊，連能量也屬於色蘊。以人身與黏土為喻，說四大非淨非不淨，是如來藏種子所現的所生法，互相含攝而運作；了解四大皆空只是空相，探究背後的空性才進入大乘。","p":["世俗把四大皆空誤解為萬念俱灰","五蘊分名與色，四大構成色蘊","能量也是色蘊，非生命本體","四大是如來藏所生法，互相含攝","四大皆空是空相，空性才是大乘"],"k":["四大","五蘊","色蘊","空相","空性","如來藏"]},"1883-a07_045":{"s":"本集解說和尚、尼姑、居士等稱呼的由來，以及四眾弟子的分類。說明居士十德、和尚源自于闐語、尼姑一詞的組成；指出歸依三寶才是佛弟子，五戒是諸戒之本。再說明沙彌戒、比丘戒、八關戒齋，以及菩薩戒是三壇大戒中的根本戒；並舉文殊、維摩詰說明有現在家相的出家人，正覺據此建立在家相菩薩僧團。","p":["四眾：比丘、比丘尼、優婆塞、優婆夷","居士十德，和尚、尼姑名稱的由來","歸依三寶才是佛弟子，五戒是諸戒之本","菩薩戒是三壇大戒中的根本戒","文殊、維摩詰是現在家相的出家人"],"k":["四眾","居士","菩薩戒","五戒","三歸依","出家"]},"1831-a07_046":{"s":"本集介紹佛教的宗派。以臨終時四兒子各持一法的故事開場，說明佛為一大事因緣出世，以五時三教與乳酪酥醍醐五味說明教法由淺入深。指出各宗都不能離開如來藏，正覺不分宗派；並概述南傳上座部、中國十三宗與西藏密宗的源流，講者對覺音論師與無上瑜伽提出批評，最後說選擇宗派應以如來藏為核心。","p":["佛為一大事因緣出世，說五時三教","五時如日照、如五味，由淺入深","各宗派不能離開如來藏真實義","概述南傳、中國十三宗與藏密源流","選擇宗派應以真如法教為核心"],"k":["宗派","五時三教","如來藏","南傳佛教","禪宗","密宗"]},"1913-a07_047":{"s":"本集回答帶業往生是否等於逃債。說明業分共業與別業，業不能代受；往生西方後因為沒有惡緣，業種暫時不現行，等於延後償還。佛菩薩可以用福德幫眾生和冤家解冤，往生者在蓮苞中聞法轉易種子，所以成佛時劫較長；並以佛受金槍刺足、食馬麥為例，說明所作業不亡。","p":["業有共業與別業，業不能代受","往生西方有因無緣，業種暫不現行","佛菩薩以福德助眾生解冤釋結","蓮苞中聞法熏習，轉惡種為善種","佛示現金槍刺足、食馬麥，業報不亡"],"k":["帶業往生","業種","共業別業","因果","西方淨土","種子熏習"]},"1878-a07_048":{"s":"本集回答應先成佛還是先度眾生。舉法師晚年感嘆道業無進步及泰國龍波篤的例子，指出把度眾和修行看成兩件事是錯誤的。說明解脫道與佛菩提道都以斷我見為起點，而斷我見需要長劫福德善緣；再以《雜寶藏經》佛度五百世為其母的老婦人出家證阿羅漢為例，說明度眾就是修行。","p":["一般誤以為度眾會妨礙修行","佛法分解脫道與佛菩提道","斷我見是實證起點，需長劫福德","佛度五百世母親老婦人證阿羅漢","度眾就是修行，兩者一體兩面"],"k":["度眾生","菩薩道","斷我見","福德","佛菩提道","因緣果報"]},"1851-a07_049":{"s":"本集講解佛教的喪葬方式。以佛前世和默王行十善、無病往生忉利天的故事，說明最好的往生要靠生前修福、斷惡。說明臨終應懺悔、迴向、放下自己，斷氣後助念八小時，不要移動遺體；喪儀力求簡單，不燒紙、不殺生，七七期間為亡者作功德迴向；建議火葬，不要用風水牽絆亡者。","p":["和默王行十善，壽終往生忉利天","生前修福德，預先決定往生去處","臨終懺悔迴向，放下自己，不必把握自己","助念八小時，勿動遺體、勿哭鬧","喪儀從簡，宜火葬，不以風水牽絆亡者"],"k":["喪葬","助念","往生","十善業","中陰身","迴向"]},"1810-a07_050":{"s":"本集比較個人自修與集體共修。引《禮記‧學記》學習失敗的六個原因，說明在教團中有師長、同修糾正的好處，大眾共修的功德會相乘增長，並舉佛以尼拘陀樹種子為喻。講者評論某大法師所說共修十點只停在表相；最後以佛世教團與《中阿含》阿那律等三尊者的生活，說明共修與自修是一體兩面。","p":["〈學記〉六因：獨學無友則孤陋寡聞","教團中有師長、同修糾正，進步迅速","大眾共修，功德相乘增長","佛世教團聽法後各自修行","共修與自修是一體兩面"],"k":["共修","自修","善知識","福德","教團","菩薩道"]},"1857-a07_051":{"s":"本集說明佛教並無強制性教條，若要說根本教條即是「四不壞信」：歸依佛、法、僧及持戒。講者解釋戒如山路護欄，是守護而非束縛；並闡述如來藏本住法、破除常見，強調信受大乘賢聖僧，不輕言證悟或洩露公案密意，遠離鬼神崇拜。","p":["佛教根本教條即四不壞信：三歸依與持戒","戒如山路護欄，守護不墮三惡道而非束縛","本心如來藏離見聞覺知，六識非往後世之心","批評否定大乘經典者破壞四不壞信","不應輕言證悟、解說公案密意，應遠離鬼神崇拜"],"k":["四不壞信","三歸依","菩薩戒","如來藏","破常見","賢聖僧"]},"1865-a07_052":{"s":"本集回答輪迴是否確實存在：輪迴本身虛妄，卻是不斷相續、令眾生受苦的存在。講者指出苦行、靜坐求禪定都非涅槃，業報由如來藏如實記錄；菩薩不畏果報而畏覆藏惡事，以懺悔、念佛、發菩提心面對業報，發菩提心才是出離輪迴的根本。","p":["輪迴虛妄而相續，令有情受巨大痛苦","二乘滅盡自己為解脫，非真實解脫","苦行折磨身體、靜坐得定皆非涅槃","業報由雙方如來藏如實記錄，現世報反為好事","菩薩懺悔不覆藏，發菩提心是出離輪迴根本"],"k":["輪迴","因果業報","如來藏","發菩提心","懺悔","二乘涅槃"]},"1834-a07_053":{"s":"本集回答佛教對人間前途是否悲觀，講者認為悲觀或樂觀都不恰當，佛陀已說明人類壽命增減與末法景象。內容批評末法中以淫欲法冒稱佛法及常見、斷見兩類相似佛法，舉阿含名色緣識說明有不可滅之心識，並勉勵護持如來藏法以待彌勒下生。","p":["人類前途隨殺戮與悔改而壽命增減","末法有魔比丘以淫欲法冒稱成佛之法","常見：以為修清淨意識即成真心，意識眠熟即斷","斷見：否認緣起法中不變心識，違阿含聖教","弘如來藏法處境艱難，勿謗賢聖可見彌勒佛"],"k":["末法","常見與斷見","相似佛法","如來藏","十二因緣","彌勒菩薩"]},"1869-a07_054":{"s":"本集回答嬰兒能否信佛：一切有情於任何時節皆可學佛，胎兒、嬰兒可由父母代為三歸依，動物、鬼神乃至地獄眾生亦可學佛。講者舉《大般涅槃經》國王殺謗法婆羅門的故事，並說明三歸依功德勝過供養無量諸佛，往生極樂及兜率內院並不困難。","p":["胎兒嬰兒可由父母代受三歸依，長大再重受","畜生、鬼道、地獄眾生皆可學佛","《大般涅槃經》國王殺謗法婆羅門之事","三歸依功德勝過供養三千大千世界諸佛","童子聚沙為塔、一舉手皆種成佛之因"],"k":["三歸依","信佛","往生極樂","兜率內院","四不壞信"]},"1867-a07_055":{"s":"本集以「佛教禁看異教書籍嗎」為題，實際主要說明何謂異教外道：凡落入斷常二見、認意識心為常住者即是外道，包括佛門中講相似佛法者。講者以根塵觸生識說明意識是被生法，駁斥「真空生萬有」之說，並闡述如來藏無主宰、無我卻隨順緣起。","p":["落入斷常二見、執意識常住者即是外道","佛門內講相似般若者比門外異教更易誤導人","根塵和合生識，意識是被出生之法","空無不能生萬法，駁真空生妙有之說","如來藏無我、無主宰，隨順有情緣起"],"k":["外道","斷常二見","相似佛法","意識虛妄","如來藏","真如"]},"1906-a07_056":{"s":"本集回答學佛是否須放棄生活享受：講者先說明娑婆世界八苦，指出世間享受建立在苦上；但佛不要求一律苦行，只須避免違法違戒的貪著。並詳述極樂淨土色聲香味觸各種清淨五欲之殊勝，說明受戒不難，每週修學時間其實不多。","p":["娑婆八苦：求不得、愛別離、怨憎會、五陰熾盛等","佛不以苦行為修行標準，苦行不能成佛","五欲只要清淨合法、不離佛道即可受用","瞋為重障應速斷，三界微細貪不那麼嚴重","極樂淨土清淨五欲殊勝，助人精進修學"],"k":["八苦","五欲","極樂淨土","苦行","持戒","性障"]},"1892-a07_057":{"s":"本集回答大修行者能否代眾生消業：講者指出業種存於各有情如來藏中，牽涉多方，任何人都無法代為消除；未證如來藏的大修行者更不能轉人業果。真正消業須自己懺悔、以佛法酬償眾生，並真實三歸依、親近證悟的大乘賢聖僧，以了解第一義諦。","p":["業種收藏於自他如來藏，無法由他人代消","業報身由業變現，酬償牽涉無量眾生","菩薩以佛法度化來償還宿債","批評名山大師以六識妄心解《心經》","真實三歸依、了解真心妄心才是真消業"],"k":["消業","如來藏","因果業報","三歸依","懺悔","第一義諦"]},"1835-a07_058":{"s":"本集說明佛教對靈媒的看法：靈媒亦是當攝受的有情，但其能力多來自與鬼道的牽連，替鬼辦事難以脫離，未來易流連鬼道。講者指出求助靈媒介入因果會增生糾葛，令人疑佛、生慢心；應信受業報、懺悔並修學第一義諦，鬼道眾生也可參加超度法會受益。","p":["靈媒能力多源於多生與鬼道眷屬往來","想脫離靈媒身分常被鬼道眾生騷擾","人問鬼、鬼問鬼，終成人鬼同途","靈媒介入因果可能觸犯冤親債主","應信受業報、懺悔，依可親證之佛法修學"],"k":["靈媒","鬼道","因果業報","民間信仰","懺悔","超度"]},"1911-a07_059":{"s":"本集探討密教的源流，講者認為密教興起於佛滅後甚久，帶有濃厚婆羅門教色彩。內容逐一比較：天瑜伽男女法違梵行、護摩源於事火外道、密教秘密灌頂異於十地菩薩光明公開灌頂、明點脈輪近似婆羅門教，並批評真言教貶稱佛教為顯教，質疑六字大明咒經文。","p":["佛世神通須修梵行、離男女欲","護摩火供源自婆羅門事火，佛陀不贊成","佛教灌頂為十地菩薩公開光明灌頂","明點、脈輪與婆羅門教說法相連","批評真言教違離言自性，質疑六字大明咒經"],"k":["密教","婆羅門教","灌頂","護摩","梵行","離言自性"]},"1914-a07_060":{"s":"本集說明忍辱的關鍵在於是否起瞋心，而非忍氣吞聲。講者從無我觀察色身與心皆非我，如來藏不受辱，罵聲亦虛妄；說明瞋的果報及故瞋犯菩薩戒，起瞋後應懺悔；並介紹內忍、外忍及對第一義諦的法忍，舉六祖惠能隱於獵人隊為例。","p":["忍辱關鍵在不起瞋心，不在忍氣吞聲","觀色身、心識皆非我，如來藏不受辱","瞋報醜陋多病，故意起瞋犯菩薩戒","瞋心使菩薩灰心退墮成聲聞","內忍、外忍與第一義諦法忍"],"k":["忍辱波羅蜜","瞋心","無我","如來藏","菩薩戒","法忍"]},"1855-a07_061":{"s":"本集回答佛教的基本教理為何。講者先引一位知名禪師以「緣生性空」為基本教理的說法並加以批評，認為那只是名相建立。接著說明佛法分三乘菩提，解脫道依智慧斷我見我執而非禪定出三界，佛菩提道須證第八識如來藏，唯一佛乘以如來藏為根本。","p":["講者批評以緣生性空為基本教理之說","佛法分解脫道與佛菩提道，三乘菩提","解脫依斷我見我執的智慧，禪定只是助緣","佛菩提以第八識如來藏為根本，三轉法輪次第","唯一佛乘以如來藏為根本，三乘是方便說"],"k":["三乘菩提","解脫道","佛菩提道","如來藏","緣起性空","唯一佛乘"]},"1860-a07_062":{"s":"本集回答功德能否迴向他人：引《大乘義章》說明菩提、眾生、實際三種迴向，以《華嚴經》一燈燃百千燈譬喻迴向無損。並以問答說明迴向法界與迴向冤親債主各有其用、迴向不必在佛前、誦經迴向的功德，強調迴向應有具體對象與次第，以佛道成就為主。","p":["迴向分菩提、眾生、實際三種","一燈燃百千燈，迴向不損自己功德","求世間福可迴向法界，求道無障先迴向冤親債主","迴向不限佛前，起心動念即有作用","迴向應由近而遠，以佛道成就為主"],"k":["迴向","功德","冤親債主","普賢十大願","誦經"]},"1929-a07_063":{"s":"本集探討「立地成佛」是否為真。先以屠夫與小乘聖者轉世因緣的「放下屠刀」故事說明世俗勸善之意，再引克勤圜悟禪師開示說明禪門以此策勵學人求證如來藏。最後以天台六即佛詳述各階位，結論立地成佛是方便說，究竟成佛須三大阿僧祇劫圓滿四法。","p":["屠夫故事：放下屠刀為世俗勸人改過之意","禪門以立地成佛策勵學人速求見道","天台六即佛：理即至究竟即佛","明心者相似即佛，悟後進修為分證即佛","究竟佛須圓滿福德、三昧、種智、四種圓寂"],"k":["立地成佛","六即佛","明心見性","禪宗","一切種智","四種涅槃"]},"1828-a07_064":{"s":"本集說明四悉檀。先講三歸依與三寶功德，引《大智度論》說四悉檀皆真實。世界悉檀以三界二十八天及十法界說明世間唯心；對治悉檀以不淨觀、慈心觀等對治貪瞋癡；為人悉檀依根性施教；第一義悉檀唯在大乘，講者並批評否定如來藏的應成派觀點。","p":["三歸依與佛法僧三寶功德","世界悉檀：三界二十八天、十法界唯心所成","對治悉檀：不淨觀治貪、慈心觀治瞋","為人悉檀：舍利弗二弟子互換法門而證果","第一義悉檀唯大乘有，如來藏為法界實相"],"k":["四悉檀","第一義諦","三界","十法界","如來藏","應成派中觀"]},"1853-a07_065":{"s":"本集回答佛典是否難懂。先略述釋迦世尊生平，再介紹五時三教：華嚴、阿含、般若、方等、法華涅槃各時所說內容，指出阿含已隱說如來藏。講者批評胡適將《法華》《維摩詰》《華嚴》視為文學作品，認為讀懂經典關鍵在親證如來藏及親近善知識。","p":["世尊生平：出家、苦行、菩提樹下成道","五時三教：華嚴、阿含、般若、方等、法華","四阿含中已隱覆密意說如來藏","講者批評胡適以文學角度解讀佛經","能否讀懂經典在於證如來藏與親近善知識"],"k":["五時三教","佛教典籍","阿含經","華嚴經","維摩詰經","如來藏"]},"1888-a07_066":{"s":"本集以十個問答說明在家信佛的常見「禁忌」，包括香爐清理、供品宜忌、歸依後對他教神祇、處理舊經書、生理期入寺、佛堂擺設、燒紙錢源流、祖先牌位、放生與殺蟲等。講者指出多數禁忌源於民間鬼神信仰，提倡護生勝於訂購放生，只要知見正確便無禁忌。","p":["供品不可殘食，辛辣異味不宜供佛","歸依後對他教神祇只合掌問訊不歸依","生理期禁忌出於鬼神，佛門無此禁忌","燒紙錢源自事火外道，佛禁火供","訂購放生反成殺業，與其放生不如護生"],"k":["在家學佛","禁忌","放生","燒紙錢","菩薩戒","供佛"]},"1880-a07_067":{"s":"本集說明加持的作用：佛法有五乘，各層修行都仰賴諸佛菩薩加持護念，加持是以悲願轉變被加持者心靈、增其面對果報的勇氣，而非代為逃債。民間他力加持只能暫擋禍患。講者公布懺悔、發願、迴向三法，並以周利槃特伽因吝法得愚報、拂塵除垢而證果的故事說明。","p":["五乘修學皆仰賴諸佛菩薩加持護念","加持在助人承擔果報，非逃避業債","依賴他人加持如向銀行貸款，終須償還","懺悔、發願、迴向三妙寶之實行方法","周利槃特伽因吝法愚鈍，拂塵除垢證阿羅漢"],"k":["加持","懺悔","發願","迴向","周利槃特伽","五乘"]},"1902-a07_068":{"s":"本集以問答說明嬰靈作祟之說不可信：胎兒死後會出生中陰身，急於再去投胎，轉入鬼道報復者極少，作祟多屬心理因素。講者也說明母體有生命危險可開緣墮胎，但強暴亂倫情況墮胎仍是殺人；並解答太空梭爆炸、孩童、避孕與中陰投胎的問題，強調墮胎罪業是真實的。","p":["胎兒死後生中陰身，多急於再入胎","嬰靈作祟多為愧疚造成的心理因素","母有生命危險可開緣，強暴亂倫墮胎仍屬殺","業種本由如來藏執持，爆炸身亡仍可投胎","嬰靈雖虛妄，墮胎罪業真實"],"k":["嬰靈","墮胎","中陰身","如來藏","殺戒","因果業報"]},"1886-a07_069":{"s":"本集說明因緣果報真實不虛：以同父母所生子女際遇各異，說明有過去世業因。引《楞伽經》「如來之藏是善不善因」，說明業種由各人如來藏執藏，依七種性自性使因果不錯亂。並指出「如是因如是果」是凡夫因果，修行加入不同的緣可轉變果報，菩薩畏因、眾生畏果。","p":["同父母子女際遇不同，顯示有往世業因","《楞伽經》：如來藏是善不善因","業種由各自如來藏執藏，因果不錯亂","修行加入新的緣、迴向冤親債主可轉變果報","今生所為有是因也有是果，菩薩畏因"],"k":["因緣果報","如來藏","楞伽經","業種","冤親債主","布施"]},"1811-a07_070":{"s":"本集說明易行道與難行道，比較禪與淨土的修道。講者認為一切法門歸於禪定、一切修行結果歸於淨土；在娑婆修行因福德易集、逆緣多、劫短而迅速，卻因難遇善知識、五欲易墮而難行；往生極樂則因蓮花住時長、缺乏逆緣而緩慢，卻無退轉、悟後往生可速證無生忍，主張禪淨雙修。","p":["一切法門歸於禪定，修行結果歸於淨土","娑婆易修布施持戒、逆緣多，故為速行道","娑婆難遇真善知識、五欲易墮，故為難行道","極樂蓮花中住時長、少逆緣，修行緩慢","極樂無惡緣不退，悟後往生速證無生法忍"],"k":["易行道","難行道","禪淨雙修","極樂淨土","娑婆世界","無生法忍"]},"1876-a07_111":{"s":"本集回答信佛是否必須出家。依《大乘本生心地觀經》區分身出家與心出家及四種情形，引《大乘理趣六波羅蜜多經》說三種僧寶，以第一義僧如來藏為真歸依處；並說明地上菩薩多現在家相的原因。講者批評台灣部分出家人輕視在家眾的心態，主張四眾應平衡發展。","p":["出家分身出家、心出家，共四種情形","真出家以發菩提心、利益有情為準","三種僧寶：第一義僧、賢聖僧、福田僧","地上菩薩現在家相以斷習氣、離名聞","講者主張出家眾應提升證量、四眾相依"],"k":["出家","僧寶","如來藏","在家菩薩","習氣種子","四眾弟子"]},"1842-a07_112":{"s":"本集回答佛教徒是否相信祈禱。引《華嚴經》《法華經》《楞嚴經》說明佛菩薩有能力感應眾生，但以順、逆、顯、隱方便攝受，不一定滿足世間欲求；並以如來藏異熟性（變異、異時、異類而熟）講三世因果，勸求信、戒、聞等七聖財。講者批評向自稱「法王」「活佛」者求財的做法。","p":["諸佛及八地以上菩薩能感應眾生祈求","佛菩薩有順度、逆度、顯度、隱度","如來藏異熟性使業果不失","應求七聖財而非世間財","講者認為自稱法王者所求對象錯誤"],"k":["祈禱","感應","三世因果","異熟","七聖財","如來藏"]},"1852-a07_113":{"s":"本集講解佛教的修持方法。依《大乘本生心地觀經》親近善友、聽聞正法、如理思量、如法修證四法要，說明彌勒菩薩所說善知識八條件，以如來藏為第一法寶與正法核心；並講修證前須具備人天基礎、滿足十信，再依六度從初住至六住修集資糧，七住明心見道。","p":["修道四法要以親近善友為首","善知識應具八種條件","正法即如來藏，為第一法寶","須先具人天善法並滿足十信位","初住至六住修六度，七住明心"],"k":["善知識","正法","如來藏","十信位","六度","菩薩五十二位階"]},"1838-a07_114":{"s":"本集回答佛教徒可否從政或從軍。講者說明菩薩為修福慧可擔任國王等職，引《瑜伽師地論》說菩薩為王應不加刑罰、不侵他國，但《法華經·安樂行品》告誡不應刻意親近權貴；軍事方面依《梵網經》不得蓄兵器、領軍相伐，並舉隱峰禪師飛錫止戰的故事，說明眾生如來藏平等不應互相殺害。","p":["菩薩為修福慧可擔任政治職務","為王應以正法教化、不侵奪他國","末法時不應為私利親近國王大臣","《梵網經》禁蓄兵器、領軍攻伐","隱峰禪師飛錫解兩軍之戰"],"k":["政治","軍事","菩薩戒","不殺生","眾生平等","梵網經"]},"1859-a07_115":{"s":"本集回答佛教是否相信上帝存在。先以第一義悉檀說法界根本為如來藏，再以世界悉檀說三界二十八天與六道輪迴；指出玉皇上帝屬忉利天，引《長阿含經》說大梵天自以為造物主的由來。講者認為一神教上帝瞋心重屬欲界天人，真正出生萬法的「造物主」是眾生各自的如來藏。","p":["「界」與法界之根本因即如來藏","三界二十八天與六道輪迴的成因","《長阿含》說大梵天誤以為造物主","講者以聖經矛盾推論上帝屬欲界天","上帝存在但未出輪迴，非造物主"],"k":["上帝","如來藏","三界","造物主","大梵天","六道輪迴"]},"1920-a07_116":{"s":"本集講解放生的正確觀念與做法。引《梵網經》《優婆塞戒經》說放生屬無畏施，但功德不及持不殺戒；指出《大智度論》原文為「諸功德中，不殺第一」，講者批評某些團體改為「放生第一」並辦大型放生。主張隨緣低調放生，更重要的是戒殺吃素、推廣護生，並可轉而幫助弱勢孩童。","p":["放生屬無畏施，功德不及持不殺戒","放生可得長壽，但仍屬世間福德","《大智度論》原為不殺第一","大型放生易成放死、破壞生態","應提倡戒殺吃素與護生教育"],"k":["放生","不殺戒","護生","無畏施","吃素","大智度論"]},"1898-a07_117":{"s":"本集回答如何讓人相信三世因果。引經典與古德偈語說明三世因果與輪迴，解釋末法時代眾生少有宿命通、天眼通而難信；並舉儒道典籍、羊祜轉世、史蒂文森研究、催眠回溯與瀕死經驗等為佐證，主張對未實證之事應持謹慎保留態度，信位滿足者則因如來藏而深信因果。","p":["三世因果是聖者共同觀察的真相","末法時禪定神通少，信者也少","引羊祜轉世與史蒂文森輪迴研究","催眠回溯與瀕死經驗可為佐證","未實證之事應謹慎保留而非否定"],"k":["三世因果","六道輪迴","宿命通","如來藏","輪迴研究"]},"1856-a07_118":{"s":"本集講解佛教的授記觀念。說明授記是佛觀察眾生業種勢力而預記其成佛或去處，舉《法華經》為諸阿羅漢授記、釋迦佛被寶藏佛與燃燈佛授記等例；依《首楞嚴三昧經》詳說未發心授記、適發心授記、密授記、無生法忍現前授記四種，並舉貧女難陀燃燈得授記的故事。","p":["授記是佛依業種勢力預告未來","釋迦佛過去曾受寶藏佛、燃燈佛授記","授記有未發心、適發心、密、現前四種","貧女難陀供燈發心即得授記","不可輕視眾生，應精進而非急求授記"],"k":["授記","首楞嚴三昧經","法華經","無生法忍","菩薩"]},"1917-a07_119":{"s":"本集講解如何辨別佛經真偽。說明三轉法輪皆說真心：初轉隱說本際，二轉說無住心、真如，三轉顯說阿賴耶識、如來藏等；以真心離見聞覺知、不分別六塵為標準檢驗經典。講者主張《楞嚴經》《大乘起信論》為真，批評懷疑者未實證；並舉《天地八陽神咒經》及以意識代真心的經典為偽。","p":["佛知見即三界唯心、萬法唯識的真心","三轉法輪對真心有隱說與顯說","以真心離六塵分別作檢驗標準","講者認定《楞嚴經》為真經","以意識取代第八識之經屬偽經"],"k":["真偽經","如來藏","三轉法輪","楞嚴經","第八識","阿賴耶識"]},"1806-a07_120":{"s":"本集檢討「地獄門前僧道多」一說。依《長阿含經》說地獄位置、八大地獄與十六小地獄的苦相、墮入各地獄的業因及地獄壽量之長；講者認為此語源自外道為貶抑僧道而捏造，但也提醒未證法而說法、破戒、否定如來藏者確會造地獄業。","p":["地獄位於兩重大金剛山之間","八大地獄的苦相與各自業因","地獄受苦時劫極為長遠","講者認為此語為外道所渲染","否定如來藏是最重的地獄業"],"k":["地獄","業報","長阿含經","謗法","如來藏","破戒"]},"1840-a07_121":{"s":"本集回答佛教徒是否必須吃素。說明現代肉食污染問題使吃素成為普遍議題，佛教以長養慈悲心為吃素主因；初學三歸五戒者可食三淨肉、五淨肉，受菩薩戒則不食肉，病時有開緣。講者駁斥「吃了眾生就是度了牠」之說，並建議素食應「百味飲食」以求營養均衡。","p":["吃素為長養慈悲，非初學強制","三淨肉：見、聞、疑；另有五淨肉","受菩薩戒不食肉，病時有開緣","駁「吃眾生即度眾生」的說法","素食宜百味飲食、營養均衡"],"k":["吃素","三淨肉","菩薩戒","慈悲心","因果"]},"1863-a07_122":{"s":"本集回答佛教是否相信靈魂實在。舉柏拉圖靈魂三分說與道教三魂七魄，說明這些靈魂觀屬組合性、不離意識與六塵，且視人與動物不平等，故不具實在性；佛教主張第八識如來藏非組合、離見聞覺知，才是貫串三世的輪迴主體，並顯示人與動物平等。","p":["柏拉圖靈魂分理性、激情、欲望","道教三魂七魄同屬組合性","組合且不離意識者可被破壞","第八識非組合、離見聞覺知","如來藏才是輪迴主體，眾生平等"],"k":["靈魂","如來藏","第八識","輪迴主體","意識"]},"1881-a07_123":{"s":"本集講解「劫」的意義。引《雜阿含經》芥子城、拂石譬喻說劫極長；依《增壹阿含經》說有佛出世為大劫、辟支佛出世為小劫；說明三大阿僧祇劫代表修學內涵，以及增減劫、中劫、大劫與三災。並以自然粳米消失的故事說減劫眾生心性，勸人轉為顧念眾生、護持正法的增劫心性。","p":["芥子城、拂石譬喻劫之長久","有佛出世名大劫，辟支佛出世名小劫","三大阿僧祇劫代表修學的內涵","增減劫、中劫、大劫與三災","轉減劫心性為增劫心性、護持正法"],"k":["劫","三大阿僧祇劫","增劫減劫","雜阿含經","如來藏"]},"1832-a07_124":{"s":"本集回答佛教是否反對節育。從解脫道看，修解脫者對子嗣不應罣礙乃至捨離眷屬；從大乘看，菩薩福德廣大，一切眾生都是其子嗣。舉頂生王意不滿足而命終的故事，說明子嗣多少不是關鍵，重在知足；節育由個人決定，只要不殺害眾生的如法方式皆可採用。","p":["解脫道對子嗣不罣礙、捨離眷屬","擔心人人出家而人類滅亡是多餘","大乘中一切眾生皆是佛的子嗣","頂生王意不滿足而命終","不殺生的如法節育方式皆可"],"k":["節育","子嗣","解脫道","眷屬","不殺生"]},"1830-a07_125":{"s":"本集回答佛教是否視異教徒為罪人。說明佛教主張政教分離，視異教徒為無明的無知者而非罪人；引《雜阿含經》說天乘、婆羅門乘、大乘三種正法律乘，承認其他宗教有一定正教。講者評論某種「不突顯佛教教義」的宗教交流主張不符佛意，並以調馬主經說明應向他教宣說佛法。","p":["佛教政教分離，不以異教徒為罪人","異教徒只是無明而值得憐憫","正法律乘：天乘、婆羅門乘、大乘","講者認為宗教交流應談佛教教義","調馬喻：不教誡即斷其法身慧命"],"k":["異教徒","無明","正法律乘","宗教交流","政教分離"]},"1816-a07_126":{"s":"本集講解佛教的飲食觀。先說寺院五觀堂的「食存五觀」，再依《長阿含經》說明摶食（含細滑食）、觸食、念食（意思食）、識食四種食為眾生存續與輪迴之因；並說明解脫須逐步斷除四食，如日中一食降伏摶食貪愛、修八背捨與滅盡定斷觸食、無願三昧斷意思食、厭捨六識以斷識食。","p":["食存五觀：用餐時的五種觀察","眾生依摶、觸、意思、識四食而存","三界眾生各有所依之食","日中一食為降伏對摶食的貪愛","斷四食貪著方能解脫"],"k":["四食","食存五觀","解脫道","滅盡定","無願三昧"]},"1919-a07_127":{"s":"本集回答持咒是否有用。說明持咒可用於修定、驅使鬼神與總持佛法，舉「正覺總持咒」為例；引《長阿含經》說驅鬼咒人屬佛所禁的遮道法，且對有正見者無效。並引《大會經》說佛結咒以除諸天幻偽之心，《佛心總持經》說總持即佛心。講者並評論六字大明咒召請的是護持雙身法的鬼神。","p":["持咒可修定、驅使鬼神、總持佛法","咒術害人屬遮道法，佛所禁止","邪咒對有正見者無效","佛結咒以除諸天幻偽虛妄之心","正覺總持咒總攝解脫道與佛菩提道"],"k":["持咒","總持","遮道法","正覺總持咒","斷我見","鬼神"]},"1836-a07_128":{"s":"本集講解佛教對神通與異能的看法。說明佛教承認五通，但重視唯佛法才有的漏盡通與三明；舉無想天人因神通不足而生無因論、殺羊屠夫自知宿命、四位五通仙人躲避死亡失敗等例，說明神通異能不明因果、敵不過業力。並說神變源自如來藏的四大種性自性，三地以後菩薩才修學。","p":["外道可修五通，漏盡通為佛法獨有","神通不足反生無因論等邪見","屠夫異能見宿命卻不明因果","神通敵不過業力，應修三明","神變為如來藏功能，三地後才修"],"k":["神通","漏盡通","三明","如來藏","業力"]},"1912-a07_129":{"s":"本集探討密教盛行佛教是否會滅亡。講者依《央掘魔羅經》與央掘魔羅追佛公案，主張中國禪宗傳如來藏密意才是真密教；並引平川彰之說，批評以大日如來為教主、以雙身法為核心的「秘密大乘」為假密教。以印度佛教衰亡與唐宋禪宗興盛對比，結論為假密教盛行會使佛教滅亡，真密教則使佛教興盛。","p":["央掘魔羅追佛為禪宗公案之源","講者認為禪宗傳如來藏密意為真密教","講者批評秘密大乘以雙身法為核心","印度佛教衰亡與唐宋禪宗興盛對比","相似像法出世則正法滅"],"k":["密教","禪宗","如來藏","雙身法","大乘非佛說","央掘魔羅經"]},"1909-a07_130":{"s":"本集回答學禪終生不悟怎麼辦。說明終生不悟自古普遍，明心在七住位，之前皆屬未悟；依《成唯識論》漸次悟入唯識，強調資糧位須深信第八識如來藏、三寶、因果、六度與善知識，加行位伏除能取所取即斷我見。即使不悟也可求生淨土、斷我見，並護持正法培養資糧。本集為系列最終集。","p":["終生不悟是學禪的普遍現象","明心在七住位，之前皆未悟","資糧位須深信第八識如來藏","加行位伏除能取所取即斷我見","不悟亦可斷我見、護持正法"],"k":["開悟","斷我見","唯識五位","資糧位","加行位","如來藏"]},"2112-a09_001":{"s":"本集回答佛菩薩色身同樣會死，為何說不生不滅。講者從六道輪迴說明眾生本質也不生不滅，引《不增不減經》指執眾生界有增減為大邪見，並以法身、報身、應化身區分，說明第八識如來藏是因果得以成立的根據。","p":["六道輪迴顯示眾生有過去未來世，本質不生不滅","《不增不減經》：見眾生界增減是大邪見、大險難","應化身生滅，佛報身常住，法身即第八識如來藏","引《華嚴經》心佛眾生三無差別","批評一人轉世成三人之說違背眾生界不增不減、亂因果"],"k":["不生不滅","如來藏","不增不減經","三身","六道輪迴","因果"]},"2075-a09_002":{"s":"本集依《楞嚴經》卷五「知見立知，即無明本」，說明它與觀行的差別。講者指知見立知是不懂五陰十八界自性，把境界中某法當真心；觀行則依佛說的五陰十八界、十二因緣觀察無我，目的在斷我見，而實證如來藏要靠參禪，兩種方法不可混用。","p":["知見立知：在所知所見境界中立一真心，是無明本","觀行依五陰十八界自性歸納，確認皆生滅","觀行目的在斷我見，不是用來尋找真心","以十二因緣否定如來藏屬方法誤用，可用還滅門反問","先觀行斷我見、修福德，再以參禪證如來藏"],"k":["知見立知","觀行","五陰十八界","斷我見","十二因緣","楞嚴經"]},"2109-a09_003":{"s":"本集探討佛法與世法是否矛盾。講者引《六祖壇經》說佛法不離世間，本質上兩者不矛盾；表面矛盾來自世人要無常的名利常存，卻否定常住的如來藏。並引《長阿含經》轉輪聖王本生、《羅云忍辱經》，說明布施與世人守財相反，卻合乎因果。","p":["佛法在世間，不離世間覺","法界同時有無常法與常住的如來藏","轉輪聖王本生：七寶無常，宜割恩愛以存道意","《羅云忍辱經》：俗之所珍，道之所賤","布施看似違反世情，實為來世資財之因"],"k":["佛法與世法","無常","如來藏","布施","因果","六祖壇經"]},"2168-a09_004":{"s":"本集針對江味農居士《金剛經講義》「教下最好不談般若」之說，指出不論宗門教下，未悟者都不應依己意妄說般若。講者舉某禪師的《心經》詮釋，以及某法師《般若經講記》中「實相非離一切而別有實體」「不落能所」等說法，批評它們否定真心、違背般若宗旨。","p":["般若所說即禪宗所悟本心、第八識如來藏","《心經》以否定五陰十八界的方式顯示真心","講者批評某禪師以緣起幻現、無真實自性解《心經》","講者批評「實相不離一切」「不落能所」之說","依經典宗旨說般若則可，不可自己妄說"],"k":["般若","宗門與教下","心經","真心","能所","金剛經"]},"2152-a09_005":{"s":"本集回答學佛後能否萬事如意。講者說世間萬事生滅變異，不可能永遠擁有；引《大乘理趣六波羅蜜多經》說明歸依時應願受過去罪業、誓不擾眾生，並歸依常住的真實三寶。又引《長阿含經》指出須依正見修學，錯誤的法即使勤修也二俱失道。","p":["世間萬事生滅變異，不可能永遠擁有","歸依應願受往昔罪業，誓不再侵擾眾生","老病死無人能代，故歸依常住的真實三寶","得聖智見常住法才能知足，順逆境都用來布施","法不真正則師徒二俱失道，須以正見為前提"],"k":["歸依三寶","無常","常住法","布施","正見","因果"]},"2165-a09_006":{"s":"本集依《圓覺經》金剛藏菩薩之問，回答成佛後會不會再成眾生。講者說「眾生本來成佛」是依如來藏佛性常住而說，眾生七轉識與佛不同；並列舉信解脫、四不壞淨、三果不退、菩薩信位行念不退，說明佛究竟不退，倒駕慈航也不是退轉。","p":["本來成佛是依第八識如來藏的真如法性而說","《雜阿含》四不壞淨成就則不墮三惡道","三果不還、七住位不退、初地行不退、八地念不退","佛四智圓明究竟不退，以學會騎車為喻","觀世音倒駕慈航是無慢與悲願，不是退轉"],"k":["不退轉","圓覺經","佛性","四不壞淨","如來藏","菩薩位階"]},"2175-a09_007":{"s":"本集依《中阿含經》〈梵天請佛經〉探討波旬為何成為魔王。講者說魔王恐懼佛弟子聞法後出離他的境界，自己也懂得不著弟子、行無為的道理卻做不到。魔性根源在捨不下眷屬欲與名聞利養；講者並以李元松老師臨終公開懺悔為能出離魔境的例子。","p":["梵天執梵天常恆，魔波旬出聲勸佛勿違逆","魔王恐懼佛弟子聞法後出離魔的境界","貪著弟子而說法，最多生為妓樂神","欲界最難斷的是眷屬欲與名聞利養","魔常以逆境、順境考驗精進的佛弟子"],"k":["魔波旬","眷屬欲","名聞利養","中阿含經","心魔","欲界"]},"2166-a09_008":{"s":"本集討論學佛該持戒茹素，還是隨順「食色性也」。講者說食色雖是天性但須節制；大乘四眾平等，不以出家為主。引《雜阿含經》卷三十七「自通之法」，以同理心說明不殺、不盜、不邪淫、不妄語、不兩舌、不惡口、不綺語七聖戒，並以此批評雙身法。","p":["食色是天性，但率性而為會帶來過患","大乘四眾平等，不以出家相為主","自通之法即同理心，近於己所不欲勿施於人","依自通之法說明七聖戒","講者以七聖戒批評雙身法；在家可正淫、可茹素"],"k":["自通之法","七聖戒","持戒","茹素","邪淫","雜阿含經"]},"2102-a09_009":{"s":"本集回答佛是否會留惑潤生度眾。講者先解釋見惑、思惑、塵沙惑（所知障），說明菩薩入地後故意保留一分思惑以潤未來生，從初地到七地屬留惑潤生；八地斷盡見思惑後就不再留惑，因此佛也不需要留惑潤生，示現各道身相是佛自在的大解脫。","p":["見惑、思惑屬分段生死，塵沙惑屬變易生死","七住位菩薩斷見惑，超越聲聞所斷","初地至七地保留一分思惑以潤未來生","八地斷盡見思惑，已無留惑潤生可言","佛能自在悠遊十法界，示現度眾而無煩惱"],"k":["留惑潤生","見惑思惑","塵沙惑","所知障","分段生死","菩薩位階"]},"2110-a09_010":{"s":"本集探討佛法實相與物理學是否一致。講者說佛法的實相不受時間限制；《阿含經》說色陰無常變易、世界壞空成住，與物理學相近，但空劫後能再成，是因第八識如來藏。講者並批評以暗能量解釋宇宙擴張，以及某比丘尼主張量子微觀世界因果律不適用的說法。","p":["佛法實相永恆不變，不分古今","色陰無常變易，物質大部分為虛空","《長阿含》壞空成住，空後能成因有如來藏","講者認為暗能量是不知如來藏而假設的","諸行剎那生滅，連續性是錯覺，因果仍然成立"],"k":["物理學","如來藏","因果律","色陰","壞空成住","剎那生滅"]},"2087-a09_011":{"s":"本集開始「什麼是法」系列，說明佛教中的「法」泛指三界一切現象，不論有形無形、真實或想像，並解釋「法界」一詞的淺深兩義。講者引彌勒菩薩《辨法法性論》說法相是虛妄分別，把法分為色法與心法，再以世尊本生故事說明色法由四大構成、法依因果運行。","p":["法指三界一切現象，見聞想像無一不是法","法界淺義為一切法，深義為萬法根源如來藏","《辨法法性論》：法相是虛妄分別","法分色法與心法，同一色法生起的心法因人而異","本生故事：善惡業報如影隨形，色法由四大組成"],"k":["法","色法與心法","法界","四大","辨法法性論","因果"]},"2090-a09_012":{"s":"本集說明「法」就是五蘊。講者以蓮花和視覺為例，說色法由因緣蘊集而成稱色蘊，識、受、想、行四蘊屬心法；眾生把五蘊當真而追逐造業，五蘊遮蓋真如，所以又稱五陰。再以波羅遮那一夜失去所有親人、後聞佛說無常而證阿羅漢的故事說明五蘊無常。","p":["色法、心法都是因緣和合蘊集而成","色蘊為色法，識受想行四蘊為心法","五蘊遮蓋真如光明，故又稱五陰","波羅遮那失去所有親人，聞佛說無常而證果","《雜阿含》：色如聚沫、受如水泡、識如幻"],"k":["五蘊","五陰","無常","色法與心法","因緣和合","雜阿含經"]},"2089-a09_013":{"s":"本集說明「法」就是十八界。講者指出人一生都靠眼耳鼻舌身意六識認識世界，意識是五俱意識、也可以是獨頭意識，眾生最執著意識的我。看見東西必須根、塵、識三者和合，如三束蘆；六識各有根塵識共十八法，彼此各有界限，所以稱十八界。","p":["一切經驗都不離眼耳鼻舌身意六識","意識與前五識俱起，也會偏注一境","眾生最執著能思能量的意識為我","根、塵、識三者和合才能了別，喻如三束蘆","六識各有根塵識共十八法，稱十八界"],"k":["十八界","六識","意識","根塵識","我見"]},"2093-a09_014":{"s":"本集講內法與外法。講者以一位看到的世界上下顛倒的女士為例，說明我們所見都是腦中的內色塵，從未接觸外色塵；若對十八界的內外法如實現觀，可證須陀洹。並引《雜阿含經》第892經講六內入處觀察忍、信行、法行，以及斷身見、戒取見、疑見三縛結。","p":["外色塵是色法，腦中成像的內色塵是心法","我們所見從來都是自己的內相分","《雜阿含》892：觀六內入處得忍，必得初果","初果斷身見、戒取見、疑見三縛結","初果不墮惡趣，最多七次人天往返即得阿羅漢"],"k":["內法外法","內相分","須陀洹","三縛結","六入處","十八界"]},"2091-a09_015":{"s":"本集續講內法與外法。講者以冷熱水實驗、各種動物視覺、羅夏克墨漬測驗、一水四見等例子，說明感官覺受是相對的，加上意識判斷後，每個人的內相分差異極大。並依《辨法法性論》說明內相分、外相分都是虛妄分別，能取與所取都不真實，我、法俱空。","p":["五根的覺受是相對之法，不是絕對量","人與各種動物所見的外境並不相同","意識與過往經驗使每個人的內相分天差地別","一水四見：業報不同，所見內相分完全不同","《辨法法性論》：二取顯現而非實有，我法俱空"],"k":["內相分","外相分","能取所取","我空法空","辨法法性論","一水四見"]},"2092-a09_016":{"s":"本集探討苦的根源。講者以漂在輪迴大海中的眾生比喻：眾生把能取、所取的內法當作我與我所。引《法句經》四比丘爭論何者最苦的故事，佛說有身才是苦的根源；並說明每一識都經過識觸受想思愛六身，共成六六身，依《雜阿含經》第304經說明六六法皆非我。","p":["眾生只執取自己能觸及的五取蘊為我與我所","《法句經》：飢渴淫瞋怖都是枝末，有身為苦本","身指可依靠的功能，非僅肉體","每識歷經識觸受想思愛六身，共三十六","《雜阿含》304六六法經：六六法皆非我"],"k":["苦的根源","有身","六六法","我與我所","五取蘊","雜阿含經"]},"2088-a09_017":{"s":"本集續講六六法。講者說如實觀行六六法可斷三縛結、證初果，但強調證果須福德、定力與一再觀行而生起法忍，只讀懂書就自稱證果會成大妄語。並引《雜寶藏經》祇夜多與餓鬼母子的故事說明三惡道之苦，最後依《成唯識論》說明身見（薩迦耶見）是一切惡見的根源。","p":["如實觀行六六法可斷三縛結證初果","只懂道理、習氣未改就自稱證果，屬大妄語","可檢驗自稱證悟者是否前面的階位已滿足","《雜寶藏經》餓鬼母子：墮三惡道極苦難學佛","薩迦耶見是一切惡見所依，斷身見才預入聖流"],"k":["六六法","身見","薩迦耶見","大妄語","三惡道","須陀洹"]},"2080-a09_018":{"s":"本集回答學佛為何總沒有進步。講者說進步需福德、定力、慧力、除性障四者並進，像椅子的四隻腳，而福德最為根本；並提到同修會以無相念佛培養定力。再以周利槃特唸「掃地」證阿羅漢、提婆達多聰明卻不實行的本生，說明信受奉行與多生福德的重要。","p":["進步需福德、定力、慧力、除性障四者並進","福德須在正法中培植，不足則遇不到正法","以無相念佛培養定力；末法時期正法難遇","周利槃特以「掃地」一偈證阿羅漢","提婆達多聞法多卻不實行；成就來自多生累積"],"k":["福德","定力","性障","周利槃特","提婆達多","無相念佛"]},"2079-a09_019":{"s":"本集回答為何為佛法做好事常多磨難。講者引《六度集經》世尊與彌勒前世兄弟化為獅、象，與惡龍同歸於盡而使一國奉佛的故事，並批評某些教團無真正佛法。講者說善事要由眾多有緣眾生的如來藏共同成就，磨難多代表結緣眾生多、福德更增上。","p":["《六度集經》：兄弟化獅象捨命除惡龍，一國奉佛","講者批評部分教團有表相無正法、否定如來藏","善事要由眾多有緣眾生共同成就，如淨土","菩薩道以攝眾為上，逆緣者亦成有緣","波折愈多，結緣愈廣，福德愈增上"],"k":["福德","攝受眾生","六度集經","護持正法","逆境","菩薩道"]},"2084-a09_020":{"s":"本集說明佛法中的孝道。講者指孝養父母是世間福德的基本，但佛法的大孝在於引導父母進入正法、利益其未來無量生。並舉世尊度姨母波闍波提出家證阿羅漢、為臨終的淨飯王說法使證三果並親自抬棺、上忉利天為摩耶夫人說法使證初果三例說明。","p":["孝養父母是三福中世福的基礎","世俗之孝只安養此生，佛法之孝顧及未來世","世尊允姨母出家，開創比丘尼僧團","為淨飯王說法證三果，並親自抬棺示孝","上忉利天為摩耶夫人說法，使證初果"],"k":["孝道","報恩","世福","波闍波提","淨飯王","摩耶夫人"]},"1910-a07_011":{"s":"本集回答宇宙和生命從何而來。講者認為造物主之說違背現量、比量與聖教量，並依《佛為首迦長者說業報差別經》說明：有情五陰由各自第八識如來藏依自業種出生，器世間則由共業有情的如來藏共同成就；舉十業得短命報、長命報、畜生報為例說明因果。","p":["造物主之說違背現量、比量、聖教量","有情生命由如來藏依自業種藉緣出生","舉十業得短命報與十業得長命報","六道器世間由共業有情如來藏共成","舉十業得畜生報，講者批評雙身法等邪行"],"k":["如來藏","業報","共業","器世間","因果","造物主"]},"1862-a07_012":{"s":"本集說明佛教相信並實踐懺悔：懺是發露，悔是後不復作，須與慚愧相應，引《大般涅槃經》耆婆勸阿闍世王之文。懺悔分事懺（依罪輕重對眾、對首、責心懺及拜懺見好相）與理懺（證悟如來藏、轉依其無罪性的實相懺悔），並警示惡取空者藉此犯戒，舉世親菩薩謗大乘後懺悔護法為例。","p":["懺為發露、悔為永不復作，屬七種最上供養","懺悔須與慚、愧二善心所相應","事懺依罪輕重對眾、對首或責心懺","理懺即實相懺悔，須證悟如來藏而轉依","未悟者宜取相懺悔，以世親菩薩為榜樣"],"k":["懺悔","慚愧","實相懺悔","事懺","如來藏","世親菩薩"]},"1849-a07_013":{"s":"本集回答佛教是否崇拜偶像。講者指佛教以探求真理、實證法界實相心為目標，依四依法而行；禮拜佛菩薩可調柔心性、去除慢心、修集福德，並非迷信。偶像崇拜的問題在個人迷信盲從無智，舉迷信廣告、十字架、大師加持、財神法、崇古、學術崇拜、僧衣崇拜等例。","p":["佛教目標在實證法界實相心而成佛","應依法不依人等四依而行","禮拜佛菩薩可除慢心、增福德","偶像崇拜的過失在迷信盲從、無智","舉學術崇拜、僧衣崇拜（無著比丘見彌勒）等例"],"k":["偶像崇拜","四依","智信","禮佛","附佛外道"]},"1850-a07_014":{"s":"本集說明佛教不重男輕女。眾生皆有平等的法界實相心如來藏，表相差別乃因果所致；從三歸依、造業受報、修福修慧、禪定實證、聲聞四果與緣覺，到大乘明心、見性、三賢十地乃至妙覺，男女的修證機會與內容皆平等，並舉勝鬘夫人、善財參訪、龍女成佛為例。","p":["如來藏具平等性，表相差別由業果而來","三歸依、造業受報、修福慧皆不分男女","禪定及聲聞四果、緣覺證量男女皆可得","大乘明心、見性及諸地證量不分男女","舉勝鬘夫人、善財參訪、龍女成佛為證"],"k":["男女平等","如來藏","解脫道","佛菩提道","明心","平等性"]},"1928-a07_015":{"s":"本集說明禪宗不是禪定。禪定所證屬意識相應的三界有境界法，通於外道；禪宗所證是第八識如來藏，以參禪一念相應而發起般若智慧。講者列舉十種以定為禪的歧路，如以離念靈知、遍滿虛空之心、身心統一、初禪身樂、無覺有觀等定境為真心，並警示以此自居證悟將成大妄語。","p":["禪宗證第八識如來藏，禪定屬意識境界","參禪以智慧參究，修定則制心一處","列舉十種以定為禪的誤會與歧路","離念靈知、初禪二禪等定境皆非真心","以定為禪而自稱證聖，成大妄語業"],"k":["禪宗","禪定","如來藏","離念靈知","般若","以定為禪"]},"1873-a07_016":{"s":"本集以佛十號說明佛陀、菩薩、阿羅漢的意義與差別，引《雜阿含經》《優婆塞戒經》逐一解釋如來、應供、正等正覺、明行足、善逝、世間解、無上士、調御丈夫、天人師、佛、世尊；並說明阿羅漢僅出分段生死，菩薩為覺有情，歷三大無量數劫、五十二位修行，即佛的因地。","p":["十號具足方稱佛陀、如來","阿羅漢即應供，能出三界生死","佛覺了世俗諦與真諦，三明圓滿超越阿羅漢","菩薩為覺有情，七住明心後內門修六度","菩薩歷三賢、十地、等覺而成佛"],"k":["佛十號","阿羅漢","菩薩","二諦","三明","五十二位"]},"1926-a07_017":{"s":"本集略談迴向的實踐，引《瑜伽師地論》說明無倒迴向是將一切善根迴求無上正等菩提，求世間福報的迴向雖非無倒亦屬善法。迴向為七種最上供養之末，可與禮拜、供養、懺悔、隨喜、勸請、發願結合而增益功德；迴向不限於佛前，心中作意亦可，於佛像前胡跪迴向更佳。","p":["無倒迴向即迴求無上正等菩提","求世間福的迴向宜無私並先迴向冤親債主","迴向為七種最上供養之一，可加乘其餘六種","物、田雖下，由迴向力感無量果","迴向不限佛前，佛前胡跪迴向更好"],"k":["迴向","七種最上供養","無倒迴向","普賢十大願","瑜伽師地論"]},"1916-a07_018":{"s":"本集說明念佛人見到瑞相時應如何面對。佛世瑞相常見，佛滅後須以智慧簡擇，依《觀無量壽佛經》「與修多羅合」檢驗，不合即是妄想，也可能是鬼神所變。瑞相非修行必要條件；佛菩薩示現瑞相的常見目的有三：令初機起信、勸發菩提心、加持滅罪；見之應感恩慚愧而不執著。","p":["佛世多瑞相，末法時須以智慧簡擇","所見須與修多羅合，不合即為妄想","瑞相非修行必要，常常見到反屬著魔","示現目的：起信、勸發菩提心、滅罪","見瑞相應更感恩慚愧，勿生憍慢"],"k":["瑞相","念佛","與修多羅合","信力","魔境"]},"1900-a07_019":{"s":"本集討論如何才是廣結善緣。講者說明緣有多種分類，順心未必是善緣、逆心未必是惡緣，應以實質上是否有助道業判斷；選擇善知識要看七聖財、說法是否合三量與四依，而非名氣、道場或僧衣。講者批評結緣雙身法附佛外道為廣結惡緣，並引《大乘本生心地觀經》修道四法。","p":["緣有善惡、順逆、助障、親疏等分類","善緣以實質助道為準，不以順心為準","以七聖財、三量、四依簡擇善知識","講者批評結緣雙身法外道為廣結惡緣","親近善友、聽聞正法、如理思量、如法修證"],"k":["廣結善緣","善知識","七聖財","四依","三量","攝受正法"]},"1877-a07_020":{"s":"本集說明修行的「魔考」。講者指魔不全是外來，佛法說四魔：五陰魔由我見我執而有，降伏首在斷我見；鬼神魔多在追求境界時化現佛菩薩干擾；天魔要到證得穩固初禪、欲出離欲界時才會引誘；煩惱魔為四種住地煩惱；生死魔須成佛才能破盡。並引《楞嚴經》說明魔附人說法之相。","p":["魔有內有外，障難非全是外來魔考","五陰魔源於我見我執，降伏首在斷我見","鬼神魔趁人貪求境界而化現干擾","天魔僅於行者將出離欲界時才來引誘","煩惱魔為四住地煩惱，生死魔至佛地方破盡"],"k":["四魔","五陰魔","天魔","斷我見","煩惱魔","魔境"]},"1874-a07_021":{"s":"本集從佛陀十號說明佛的意涵：佛為福慧兩足尊，自覺、覺他、覺行圓滿的圓覺者。並詳述菩薩經十信、十住至十地、等覺、妙覺五十二位及三大阿僧祇劫的修學次第，以凸顯佛與菩薩、阿羅漢的差異；又說十方有無量諸佛，講者認為自稱即身成佛的「活佛」並非佛教之佛。","p":["佛十號之意涵，佛為福慧兩足尊","阿羅漢自覺、菩薩自覺覺他、佛三覺圓滿","五十二位與三大阿僧祇劫的修學次第","佛可稱阿羅漢，阿羅漢不可稱佛","十方佛無量，講者批評自稱活佛者"],"k":["佛十號","五十二位","福慧兩足","阿羅漢","十方佛","三大阿僧祇劫"]},"1825-a07_022":{"s":"本集探討佛為何度眾生，及《金剛經》「實無有眾生如來度者」之義。諸佛皆於人間八相成道，因四宏誓願、十無盡願而度眾，人間較少八難而易受化；度眾也為莊嚴佛土，須眾生如來藏與己共成佛世界。所度五陰是生滅法，而如來藏本在彼岸，故說實無眾生得滅度。","p":["諸佛皆於人間八相成道，兜率降生為常法","因四宏誓願、十無盡願而度化眾生","人間較少八難，眾生較易受教","莊嚴佛土須教化眾生，共成佛世界","五陰生滅、如來藏本涅槃，故實無眾生得度"],"k":["度眾生","金剛經","莊嚴佛土","十無盡願","八相成道","如來藏"]},"1901-a07_023":{"s":"本集回答娼妓、屠宰、漁獵、販酒等人能否信仰佛教。先依八正道的正命、《大智度論》四種邪命及《瑜伽師地論》聖所愛戒說明如法職業，這些職業因違殺、淫、酤酒戒而屬邪命；但眾生如來藏平等，皆有成佛可能，故可信佛，先受三歸依或少分受戒，再逐步調整職業轉為正命。","p":["八正道之正命即以如法職業營生","四種、五種邪命及聖所愛戒之義","屠宰、漁獵、販酒、娼妓屬佛教所說邪命","如來藏非身、大身平等，皆可成佛","可先受三歸依、少分受戒，漸轉為正命"],"k":["正命","八正道","邪命","五戒","聖所愛戒","平等性"]},"1897-a07_024":{"s":"本集說明佛事的真實意涵。法會原指說法的聚會，而非唱誦敲打；依《華嚴經》諸佛、菩薩十種佛事，佛事即為教化眾生、利樂有情所作之事。以拈花微笑及雲門、趙州洗缽等公案說明禪宗直指的佛事，並指未悟者不能說搬柴運水即是禪；法會、朝山等可調伏心性、累積福德並迴向證悟。","p":["法會的原意是說法的聚會","佛事即教化眾生、利樂有情之事","拈花微笑與禪宗公案皆是殊勝佛事","未悟者不可說搬柴運水即是禪","事相佛事可調伏心性，福德迴向明心"],"k":["佛事","法會","禪宗公案","如來藏","參禪","無相念佛"]},"1841-a07_025":{"s":"本集說明佛教徒並非不孝，佛教反而強調孝順父母。引《增壹阿含經》、《睒子經》及《雜寶藏經》中佛陀前世為長者子、廢除活埋父母惡法的故事；並從福田之義（父母屬敬田、報恩田）、殺父母列五無間罪、《觀經》三福淨業以孝養父母為首等說明；最殊勝的報恩是引導父母學佛。","p":["經中佛陀教誡父母恩重難報","佛陀前世廢除活埋父母惡法的故事","福田四義，父母屬敬田、報恩田","殺父母為五無間罪之一","三福以孝養為首，並應引父母學佛"],"k":["孝養父母","福田","五逆罪","三福淨業","雜寶藏經"]},"1819-a07_026":{"s":"本集說明佛教中法師、禪師、律師的真義。依《雜阿含經》，能說五陰生厭、離欲、滅盡法者即法師；依《法華經》，大乘法師廣演如來藏，不以出家相為限，講者批評六識論與大乘非佛說者不是法師。禪師依《聖善住意天子所問經》為證一切法不生、無所取者，非專修禪定之人；律師為弘通戒律者。","p":["僧寶以心出家為準，不限身相","法師是說五陰生厭、離欲、滅盡之人","大乘法師廣演此經如來藏","禪師證不取三界法的如來藏，非修定者","律師弘通戒律，戒師須不失戒體"],"k":["法師","禪師","律師","如來藏","五陰","菩薩戒"]},"1822-a07_027":{"s":"本集解釋一心不亂。一般指心志專一，佛法中分事一心與理一心：事一心是意識修定所得，如持名或無相念佛念到淨念相繼，有臨終往生極樂之功德；理一心依《華手經》《大乘起信論》《文殊般若經》，指親證真如心如來藏、見自性彌陀的一行三昧。並以臥輪與六祖之偈說明悟得理一心不必先得事一心。","p":["一心即心志專一、心不散亂","事一心為念佛等事修上的一行三昧","持名念佛一心不亂可臨終往生","理一心為親證如來藏、見自性彌陀","六祖偈顯示理一心不依事一心而得"],"k":["一心不亂","事一心","理一心","一行三昧","念佛","自性彌陀"]},"1870-a07_028":{"s":"本集討論佛教是否重視神通。佛菩薩為攝受眾生會示現神通；說明六神通內容及依得、報得、修得，五通依禪定修得而通外道，漏盡通唯阿羅漢與初地以上菩薩可證。講者指神通屬意識境界、抵不過業力，藉鬼神作法消災是干預因果；並舉欎毘羅迦葉現神通歸佛之例及示現神通的原則。","p":["佛菩薩為攝受眾生而示現神通","六神通內容與依得、報得、修得","五通依禪定修得，漏盡通不共外道","神通屬意識境界，不敵業力，應以智慧為導","迦葉尊者現通歸佛及示現神通原則"],"k":["神通","六神通","漏盡通","禪定","般若","鬼神"]},"1884-a07_029":{"s":"本集探討唯識與唯心的關係。依世親《大乘百法明門論》五位百法，說明三界萬法皆由八識心王所生所顯，故說萬法唯識；八識又歸於第八阿賴耶識如來藏，故說三界唯心。三界有情乃至滅盡定皆不離八識，此為可親證的法界事實；哲學唯心論未觸及第八識，與佛法所說不同。","p":["三界唯心、萬法唯識指陳生命實相","百法明門論五位法次第出生顯現","欲界、色界、無色界皆依八識現行","八識歸於第八識如來藏一心","講者批評六識論，哲學唯心論未及第八識"],"k":["唯識","唯心","八識心王","阿賴耶識","百法明門論","如來藏"]},"1891-a07_030":{"s":"本集探討大修行人是否一定要閉關。先界定大修行人，嚴格說為初地以上菩薩及諸佛；再說解脫道與佛菩提道皆是智慧而非禪定，引《大般若經》「非異世俗別有勝義」、《維摩詰經》淤泥生蓮及六祖偈，說明菩薩不斷煩惱證菩提，應在世俗中求悟；閉關並非必要，唯見道前鍛鍊定力時可減少攀緣。","p":["以出離生死界定大修行人，嚴格為初地以上","通教、別教對賢聖凡愚的判別","解脫道、佛菩提道皆為智慧而非禪定","非異世俗別有勝義，不斷煩惱證菩提","不必閉關，見道前可減外務鍛鍊定力"],"k":["閉關","解脫道","佛菩提道","煩惱即菩提","如來藏","勝義諦"]},"1847-a07_071":{"s":"本集回答「佛教是世界性的宗教嗎」。先引《央掘魔羅經》與《法華經》一大事因緣，指出佛教本質是眾生皆有如來藏、皆能成佛；再述南傳、北傳等流傳，並引《佛本行集經》一生補處菩薩在兜率天說法，以及初果人極七返人天，說明天界也有佛法。結論是佛教無國界、通於人天，「世界性」只是通俗說法。","p":["佛教本質：眾生皆有如來藏，皆能成佛","佛為一大事因緣出世，開示悟入佛知見","三轉法輪結集後分南傳、北傳等地流傳","一生補處菩薩在兜率天為諸天說法","初果極七返人天，可證天界有佛法"],"k":["如來藏","一佛乘","天人師","兜率天","南傳北傳","初果"]},"1864-a07_072":{"s":"本集依《地藏菩薩本願經》說明佛教如何看待超度亡靈：超度就是幫亡者免墮三惡道，臨終時懸旛、燃燈、讀經、念佛菩薩名號，讓名號熏入本識，先滅罪；死後七七日內廣造眾善為亡者追福，亡者得七分之一。經中也勸人臨終時勿殺生、勿祭拜鬼神。另引《梵網經》講菩薩戒經律以福資亡者。","p":["超度即助亡者離三惡道，生人天善處","臨終念佛名號熏入本識，先滅罪後追福","七七日內廣造眾善，亡者得七分之一","殺生、祭鬼神無益亡者，反增罪緣","設齋供佛、不殺生、念佛及講菩薩戒皆為福"],"k":["超度","地藏菩薩本願經","追福","中陰","念佛","因果"]},"1821-a07_073":{"s":"本集依《菩薩瓔珞本業經》說明從信佛到成佛的內容、次第與時間：先正三業、習三寶教、信向因果，依次修四十二賢聖位。十信要一劫到十劫才入初住，七住證如來藏不退才算進入第一大阿僧祇劫；三大阿僧祇劫分別圓滿三賢位、初地至七地、八地至十地，之後還有等覺、妙覺。講者據此提醒，不宜輕信即身成佛之說。","p":["成佛先須正三業、習三寶教、信向因果","須受學四十二賢聖名門，十方諸佛同說","十信滿入住位，七住證如來藏方不退","三大阿僧祇劫各有應修證內容","等覺百劫修相好，妙覺示現成佛"],"k":["三大阿僧祇劫","四十二賢聖位","菩薩瓔珞本業經","七住不退","如來藏","十信"]},"1858-a07_074":{"s":"本集回答佛教的生命觀是否合乎科學。依《長阿含經》說明名色由入胎識出生，眾生共有八識；意識屬一期生滅，悶絕、熟睡時斷滅，與醫學觀察相符，意根則被科學界當作潛意識。再引《勝鬘經》，說入胎識即如來藏，不生不滅，是生死、因果與涅槃的主體。講者認為佛教生命觀最完整，能涵蓋科學的發現。","p":["名色由入胎識而出生、增長","眾生有八識，第八識為入胎識","意識一期生滅，悶絕熟睡即斷，合乎科學","有如來藏故說生死，如來藏是依、持、建立","如來藏非我非眾生，非身見者境界"],"k":["如來藏","八識","入胎識","名色","勝鬘經","生命觀"]},"1839-a07_075":{"s":"本集說明佛教徒應如何看待全部佛經。先逐一解釋三藏與十二分教，再提出閱讀注意：前後文要連貫，不可斷章取義；般若的空是如來藏真實空，不是無常空或緣起性空。並列出判別偽經的標準，例如主張意識常住、讚嘆淫欲可以成佛、否定如來藏等。除偽經外，其餘經典都應當作法寶恭敬受持，三藏以如來藏貫串，彼此並不矛盾。","p":["三藏含攝十二分教，逐一說明其義","讀經須前後連貫，不可斷章取義","般若空是如來藏真實空，非緣起性空","意識常住、否定如來藏等說即偽經","三藏以如來藏貫串，並無矛盾"],"k":["三藏十二部","十二分教","偽經","般若","如來藏","讀經態度"]},"1905-a07_076":{"s":"本集回答學佛是否需要知識和學問。講者認為學佛要的是善根、對三寶的淨信與深信因果，世間學歷不是門檻，但須依善知識建立八正道的正見。依《增壹阿含經》說明八難，並以盲龜值浮木比喻人身與正法難得。講者指出，真正的「學問」是向善知識學與問；學術研究只看歷史表相，觸不到斷我見與證如來藏的實證，易落入世智辯聰。","p":["學佛須善根、三寶淨信、深信因果","入佛門後須依善知識建立正見","八難之人難以聞法修行","真學問是向善知識學習與請問","學術研究難觸及斷我見與證如來藏"],"k":["八難","正見","善知識","世智辯聰","斷我見","增壹阿含經"]},"1925-a07_077":{"s":"本集分兩部分回答消災、延生是否可能。消災方面，酒色引起的災禍可以靠受三歸五戒來避免；依《菩薩優婆塞戒經》，五戒是五大施、無畏施，持戒有善神守護，再加行十善。延生指不中途夭折、免於橫死，關鍵在有福，因此要念佛、受菩薩戒、修六度、不故入難處，並實證如來藏以明因果。講者強調消災延生不是向鬼神求來的。","p":["酒色引生災禍，受三歸五戒可消除","五戒即五大施，令眾生離五怖畏","延生即不中途夭折、免於橫死","橫死多因無福，須念佛植福、受菩薩戒","消災延生非求鬼神，應入佛法修學"],"k":["三歸五戒","消災延生","無畏施","橫死","菩薩戒","十善"]},"1813-a07_078":{"s":"本集依《瑜伽師地論》卷一說明中陰身：它六根具足，形類隨將受生之處而定，每七日一死一生，最多七七日必定受生；期間可因眷屬追福或自起瞋念而轉變。又名健達縛、意行，見父母和合而起顛倒欲愛入胎。生無色界或造極重惡業者沒有中陰；往生極樂則有中陰，但是蓮華化生，不經淫欲。","p":["中陰具諸根，形類隨當生之處","中陰七日一死生，最多七七日受生","眷屬追福或亡者起瞋，可轉中陰類別","生無色界、極重惡業者無中陰","往生極樂有中陰，蓮華化生不經淫欲"],"k":["中陰身","瑜伽師地論","七七日","入胎","往生極樂","追福"]},"1868-a07_079":{"s":"本集解釋佛教被稱為無神論的意思。這個稱呼來自西方比較宗教學者。依《大乘理趣六波羅蜜多經》，佛破斥外道「自在天常、能生一切」，指出其常而不常生、無慈悲、一常卻有變易等過失，而神我的過失更大。再引《入楞伽經》，說明如來藏不同於外道神我。講者強調佛教並不否認天神、鬼神，學佛後反而更懂得為祖先追福、開示。","p":["無神論之稱來自西方比較宗教學者","佛破自在天常能生一切之說","見聞覺知的神我不能造作有情","如來藏常住，不同外道神我","佛教不否認天神鬼神，可為祖先追福"],"k":["無神論","如來藏","神我","自在天","入楞伽經","造物主"]},"1823-a07_080":{"s":"本集釐清「專修」與「雜修」。淨土宗所說的雜修，原指不安住念佛、涉獵俗務或外道法；若說只有稱名才算專修，聽經、修六度就不能往生，講者認為這違背因果與經義。並引九品往生與《大寶積經》，說不專念阿彌陀佛而以善根迴向也能往生。再依《梵網經》輕垢戒，指菩薩心背大乘經律、否定如來藏，才是大乘中的雜修。","p":["雜修原指不安住念佛、涉外道俗務","九品攝受，上品須修第一義諦與六度","不專念彌陀而迴向善根，亦得接引","梵網經：背大乘經律犯輕垢罪","專修大乘須信受如來藏，依實證善知識"],"k":["專修雜修","淨土法門","九品往生","梵網經","如來藏","菩薩戒"]},"1871-a07_081":{"s":"本集探討「佛是萬能的嗎」。講者指出萬能和造物主的觀念，來自對五陰世間與器世間形成真相的無明，古印度、希臘早已有之。五陰世間（正報）由別業所成，器世間（依報）由同分妄見的共業所成，並以九二一地震為例。接著引《大悲經》，佛逐一問大梵天世界、劫火、日月、四時、夢中六塵與四姓貧富是否為其所作，梵天都答「不也」。","p":["萬能觀念源於對世間形成真相的無明","造物主思想古印度、希臘早已有之","別業成五陰世間，共業成器世間","大悲經：佛問梵天自身由誰所作","劫火、日月、四時、四姓皆非梵天所作"],"k":["造物主","共業別業","大悲經","大梵天","依報正報","無明"]},"1872-a07_082":{"s":"本集續講《大悲經》：佛再問疾病是否梵天所作，梵天自承出於無智邪見並向佛請法，佛答世界與眾生都是業所作、業力所生，並說十二因緣的流轉與還滅，唯有業與法因緣和合。講者認為造物主萬能的思想是我見顛倒。結論是佛非萬能，有不能度盡眾生、不能化導無緣、不能滅定業三不能；也非非萬能，因自性佛如來藏出生萬法。","p":["疾病苦惱亦非梵天所作，源於業報","世界眾生皆業所作、業力所生","十二因緣流轉與還滅，更無作者","造物主萬能思想是我見顛倒","佛非萬能（三不能），亦非非萬能"],"k":["十二因緣","業力","大悲經","佛三不能","我見","如來藏"]},"1826-a07_083":{"s":"本集以社會學符號互動理論，說明各種信仰透過圖騰寄託崇拜。講者認為基督教的十字架同樣是偶像，只重祈福、經懺的相似佛法寺院也和民間信仰本質無異；又引 religion 的字源（捆綁羈絆）與涂爾幹「神是社會力量的投影」。佛教拜佛不只是祈福、仰慕，更要藉憶佛修定力、思惟第一義，以見真如，故說偶像即非偶像。","p":["信仰透過符號圖騰投射崇拜","講者認為十字架等同屬偶像","religion 字源為重複捆綁羈絆","涂爾幹：神是社會力量的投影","佛教拜佛為修定力、思惟第一義"],"k":["偶像崇拜","符號互動","念佛","民間信仰","體究念佛","真如"]},"1827-a07_084":{"s":"本集續論佛教與民間信仰拜偶像的差異：拜像若只為自己求福、求平安，就和我見、我所相應，與一般偶像崇拜無異；佛教拜佛則是為了斷我見、求解脫、圓滿佛道。再引《大寶積經》卷八十九觀像經文：如來像非覺非知、但有名字、非三界所攝、非取非捨、非生死非涅槃，藉此體會如來藏的體性。","p":["只為祈福而拜，與我見我所相應","佛教拜佛為斷我見、求解脫成佛","如來像非覺非知，喻如來藏體性","像但有名字，自性空寂無所有","畫像非三界攝，非生死非涅槃"],"k":["偶像崇拜","如來藏","大寶積經","觀像念佛","我見","拜佛"]},"1844-a07_085":{"s":"本集探討「宗教」一詞的源流。漢語本無「宗教」這個連綴詞，「宗」原指宗法制度與宗廟祭祀，由此衍生祖先神靈、天道與民間信仰，講者認為這些不離我見。並引《說文》、《孔傳》、《論語》說明。「宗教」一詞出自漢譯佛典：《瑜伽師地論》「觀自宗教」、「佛語心為宗」、《宗鏡錄》「論其宗教，莫非自心是本」，「宗」指如來藏真心。","p":["漢語本無「宗教」連綴詞","「宗」原指宗法制度與宗廟祭祀","祖先神靈與天道信仰衍成民間信仰","宗教一詞出自瑜伽師地論等佛典","佛語心為宗，宗指如來藏真心"],"k":["宗教","宗法制度","佛語心為宗","瑜伽師地論","宗鏡錄","如來藏"]},"1846-a07_086":{"s":"本集續說「宗教」原為佛教專用詞，指宗門與教下：依佛教說修行、證悟如來藏即是宗。依圜悟語錄「宗通說亦通」及《楞伽經》註解「宗者道之本，說者教之跡」，說明宗通與說通須相輔為用。講者指出，以意識心為心內求法其實仍屬心外求法，並以往南走到不了台北作比喻，再舉德山宣鑒被賣餅婆子問倒而焚《金剛經疏鈔》的公案。","p":["宗教原是佛教專詞，即宗門與教下","宗通方能說通，二者相須為用","以意識心求法仍屬心外求法","方向錯如往南欲到台北，終不能至","德山被婆子問點哪個心，焚疏鈔"],"k":["宗通說通","宗門教下","心外求法","楞伽經","德山宣鑒","如來藏"]},"1845-a07_087":{"s":"本集總結「佛教是不是宗教」。日本人借佛教的「宗教」一詞翻譯 religion，此後泛指一切信仰；講者認為 religion 是人神之間的捆綁羈絆，佛教則要解脫這種捆綁。結論是：依 religion 的意義，佛教不是宗教；依「佛語心為宗」的原義，唯有實證如來藏的佛教才是宗教，其他信仰無宗無教，執意識心者也不算。","p":["日本人借「宗教」譯 religion 而泛化","religion 為人神捆綁，佛教求解脫","眾生執內我，並虛妄施設外我","依 religion 義，佛教不是宗教","依原義，唯實證佛教有宗有教"],"k":["宗教","religion","佛語心為宗","如來藏","我見","內我外我"]},"1903-a07_088":{"s":"本集回答「存好心、說好話、做好事就是學佛嗎」。講者指出這是籠統的說法，各人標準不同，其他宗教也這樣教，不明因果時易流於鄉愿，例如替人偷竊把風。應依《佛說阿那律八念經》，把它落實到世間與出世間的八正道。本集依序講解正見、正思惟、正言、正行、正治、正命、正志，並開始講正定。","p":["存好心說好話做好事是籠統概念","不明因果易成鄉愿，反造惡業","應落實於世間與出世間八正道","世間正見知三世因果，道正見依四聖諦","正言須離口四過，並說出離生死之語"],"k":["八正道","正見","阿那律八念經","四聖諦","十善","學佛"]},"1904-a07_089":{"s":"本集續講八正道。出世間正業是除斷苦習、滅愛求度、受戒修定，須以十二因緣觀滅除三界愛；講者並認為所謂「大愛」仍是應滅之愛。正命要求財以道，出世間則捨世占候，不為人算命看風水。正志即正念，出世間要行四意端（四正勤）；正定指智慧上的決定心，出世間得空、無想、無願、見泥洹道。結論：世間八正道是福業，出世間八正道是慧業。","p":["出世間正業：除斷苦習、滅愛求度","講者認為「大愛」仍屬應滅之三界愛","正命求財以道，捨世占候不算命","正念行四意端，即四正勤","正定是智慧決定心，非單指禪定"],"k":["八正道","十二因緣","正命","四正勤","正定","滅愛"]},"1894-a07_090":{"s":"本集回答太歲是否主宰人的禍福。太歲星就是木星，約十二年繞日一周，配上地支，便有值太歲、沖太歲之說。講者認為以太歲主宰禍福，源於不明五陰世間而生的我見與造物主邪見；佛說觀星斗屬四邪命食中的仰口食，寺院收費安太歲即屬邪命。日月星辰的牽引來自眾生的共業與別業，要改變命運，須從改變別業、依佛法斷我見做起。","p":["太歲即木星，約十二年配一地支","值太歲、沖太歲出自曆法地支配置","太歲主宰說源於我見與造物主邪見","觀星占卜屬四邪命食之仰口食","改命須轉別業，依佛法斷我見"],"k":["太歲","邪命","共業別業","造物主","我見","同分妄見"]},"1833-a07_091":{"s":"本集從社會觀感、健康、戒律與修行四方面說明學佛人不應抽煙，引《五分律》說隨方應行之戒亦須遵守；並說明酒戒屬遮戒、菩薩戒中賣酒重於飲酒，以根本、方便、成已判斷是否犯戒；最後說賭博傷身傷財、敗壞事業與家庭。","p":["抽煙令人觀感不好、二手煙害人，並障礙持戒修定","《五分律》：雖非佛所制而當地應行者亦須行","犯戒與否須看根本、方便、成已","菩薩戒中賣酒為重戒、飲酒為輕戒，藥酒可開緣","賭博傷身傷財，導致傾家蕩產、家庭失序"],"k":["戒律","酒戒","菩薩戒","根本方便成已","五蓋","賭博"]},"1893-a07_092":{"s":"本集說明佛教的世界架構：三千大千世界只是一個大千世界，含十億小世界；小世界以須彌山為中心，有金山香水海、鐵圍山間地獄、四大洲與欲界六天，並介紹各處壽命與欲事差異；另以無著、世親、師子覺故事說明兜率外院五欲令人忘學佛。","p":["三千大千世界非三千個大千世界","小世界以須彌山為中心，四方有四大洲","北俱盧洲無憂而學不到佛法，屬於邊地","欲界六天壽命漸長、淫欲漸淡，行十善可生","二禪、三禪、四禪天分屬小千、中千、大千"],"k":["三千大千世界","須彌山","四大洲","欲界六天","地獄","兜率天"]},"1814-a07_093":{"s":"本集依《金剛經》如來具五眼之說，逐一說明肉眼、天眼、慧眼、法眼、佛眼，引《摩訶般若波羅蜜經》《大智度論》講菩薩肉眼淨、天眼的果報得與修得、天眼通與天眼明之別；慧眼屬斷我見或明心證如來藏者，法眼須能斷習氣，成佛時諸眼皆名佛眼。","p":["肉眼見近不見遠，菩薩肉眼淨可見大千","天眼有果報得與修得，二乘與菩薩所見不同","天眼明比天眼通更知眾生投生之因","慧眼：二乘斷我見、菩薩七住明心以上","法眼須能斷習氣，成佛時四眼皆名佛眼"],"k":["五眼","天眼通","慧眼","法眼","如來藏","大智度論"]},"1924-a07_094":{"s":"本集說明殺生即奪取眾生生命，殺人為重戒、殺畜生為輕戒，以對方是人、知是人、起殺心、施設方便、命斷五條件判定犯殺人重戒；並談重戒須懺至好相方滅戒罪而性罪仍在，以及教殺、讚嘆殺、咒殺、殺錯人、意外致死、墮胎等情形。","p":["殺人斷人修行機會為重戒，殺畜生為輕戒","犯殺人重戒須具足五個條件","犯重戒須至誠懺悔見好相，方滅戒罪","教人殺、讚嘆殺、咒殺皆成殺罪","無殺心的意外無戒罪，墮胎屬可悔殺生"],"k":["殺戒","菩薩戒","懺悔","好相","戒罪與性罪","自殺"]},"1837-a07_095":{"s":"本集說明天神、鬼神同屬六道輪迴眾生，佛教不崇拜鬼神而歸依三寶，並講信三寶的迷信、仰信、解信、證信四種心態；再說民間玉皇大帝屬忉利天、土地公城隍屬有財鬼，天神不受人間供養而鬼神受之，最後介紹天龍八部。","p":["天與鬼仍屬六道凡夫，不須崇拜","信受三寶有迷信、仰信、解信、證信","玉皇大帝即帝釋天，土地公為有財鬼","天神不食人間供養，行十善即得眷顧","天龍八部歸化佛的威德而護持佛法"],"k":["鬼神","三寶","證信","天龍八部","六道輪迴","十善業"]},"1861-a07_096":{"s":"本集探討佛教是否相信在劫難逃。依《優婆塞戒經》說因定而果未定，修身戒心慧或懺悔可轉重為輕，舉阿闍世王為例；不肯懺悔的重業則成定業，以善星比丘與外道苦得故事說明。並講火水風三災、刀兵等劫及大中小劫的時間。","p":["劫有災厄與時間兩種意涵","造因已定，果報仍須有緣、可以轉變","懺悔與修行能轉重業為輕受","善星比丘堅持無因果邪見，生身墮地獄","世界成住壞空，三災與刀兵等劫難逃"],"k":["因果","定業","懺悔","善星比丘","成住壞空","三災"]},"1807-a07_097":{"s":"本集解說古德「施主一粒米，大似須彌山，若然不了道，披毛戴角還」偈，原為警惕為利益而出家者；說明道的意義及解脫道、佛菩提道的了道，認為專心修行而未了道者不必墮畜生，並引《分別善惡報應經》說十種得畜生報的業。","p":["偈語警惕為逃苦、得供養而出家者","道有方法、方向之義，分解脫道與佛菩提道","了道：斷我見證初果，或開悟明心","不浪費供養、專心修行者不致墮惡道","中品身語意惡業、貪瞋癡等十業得畜生報"],"k":["出家","了道","解脫道","佛菩提道","畜生道","斷我見"]},"1932-a07_098":{"s":"本集說明蓮花在佛教的意義：依阿彌陀佛第十八願，發願往生者七寶池中即生蓮花，命終花開接引，並說五逆可下品往生而謗法不得往生；再說《妙法蓮華經》以蓮花喻妙法如來藏，取其人愛、花果同時、出淤泥不染、漸次長成等特性。","p":["第十八願：至心信樂十念可生，唯除五逆謗法","發願即於七寶池生蓮，命終花開接引","妙法即如來藏，眾生皆愛樂阿賴耶","花果同時、出淤泥不染喻如來藏清淨","講者指以蓮花喻性器官者不是佛法"],"k":["蓮花","如來藏","淨土","阿彌陀佛第十八願","妙法蓮華經","阿賴耶識"]},"1921-a07_099":{"s":"本集講者引日蓮正宗官網文字，從起源、信仰實踐、行門與對法身、般若的解釋，批評其以日蓮為取代釋尊之佛、未知斷我見，判定不是佛教；再就一貫道三教合一、道統年代不符、天堂掛號地獄除名及點玄關之說，講者亦認為不是佛教。","p":["講者指日蓮自居為佛，與彌勒授記相違","專唱經題，講者評其不知如何斷我見","講者認為其法身、般若解釋屬世間義","一貫道道統傳承與歷史年代不符","生天須行十善，開悟非點破玄關竅"],"k":["日蓮正宗","一貫道","斷我見","法身","般若","外道辨正"]},"1887-a07_100":{"s":"本集探討在家與出家學佛的差別：從斷三縛結證初果到三果、阿羅漢與開悟明心，說明在家人同樣可證；依《雜阿含經》沙門果定義僧寶，主張證果者可為人作三歸依；並引《梵網經》說在家法師可傳菩薩戒，在家菩薩亦可說法。","p":["學佛目的為出離三界或行菩薩道成佛","斷我見、疑見、戒禁取見即證初果","在家出家皆可證果與開悟明心","證沙門果者即僧寶，可為人授三歸依","依《梵網經》在家法師亦可傳菩薩戒"],"k":["在家與出家","證果","三縛結","僧寶","菩薩戒","六識論"]},"1820-a07_101":{"s":"本集說明菩薩即覺有情，須了知佛菩提道次第並有實證，佛所認定的真實義菩薩至少是明心的七住菩薩；介紹五十二階位，以阿羅漢與小沙彌三進三退故事喻發心不易，並逐位講至成佛；最後說明明心者不論在家出家皆為勝義僧。","p":["菩薩即覺有情，須有實證而非世間善人","五十二階位：十信至等覺、妙覺","小沙彌三進三退，喻發菩提心不易","明心僅為七住，是佛菩提道的入門","明心者不論現何相皆為勝義菩薩僧"],"k":["菩薩","五十二階位","明心","十信","勝義僧","菩提心"]},"1927-a07_102":{"s":"本集針對不信天堂地獄與因果之說（講者特別批評應成派中觀），介紹欲界六天與無間地獄，再從教證與如來藏兩方面證明因果：引「假使經百劫」偈、百丈野狐與舍利弗不度者等例，並依《大乘入楞伽經》與轉播、模擬器譬喻說明境界皆如來藏所現。","p":["欲界六天概況，修十善、禪定得生天","犯七逆罪墮無間地獄，長劫受苦","「假使經百劫，所作業不亡」證因果不失","百丈野狐與八萬劫前善根成熟之例","見聞境界皆如來藏所現，業種由其執持"],"k":["因果","天堂地獄","如來藏","欲界六天","無間地獄","應成派中觀"]},"1931-a07_103":{"s":"本集定義自殺與殺生，從世間法說明自殺不能解決問題、業未盡仍須受報，並解釋自殺地點鬧事與抓交替；說明貪口欲殺生結冤、安樂死仍成殺罪。依佛法引《大般涅槃經》說壞五陰即殺生，並舉阿羅漢自盡、有德王護法、菩薩殺極惡者等開緣。","p":["自殺不解決問題，業未盡仍須受報","自殺處鬧事多為他靈求利或找替身","殺生結冤，殺者與被殺者角色互換","安樂死在佛教戒律上仍成殺罪","開緣：定性阿羅漢、護持正法、救眾生"],"k":["自殺","殺生","因果","安樂死","護持正法","戒律"]},"1879-a07_104":{"s":"本集說明出家五眾、在家二眾及具足戒、五戒，以人身難得勸持五戒，並說應受菩薩戒且以之為正解脫戒；舉德光論師不禮彌勒批評聲聞心態，引《大寶積經》、達摩等說真出家依實證而非表相，講者並批評否定第八識等說，最後說出家在家兩軌並行。","p":["佛門七眾與比丘戒、比丘尼戒、五戒","菩薩戒為成佛根本，戒體盡未來際","德光論師以表相不禮彌勒，屬聲聞心態","真出家依實證三乘菩提而非剃髮表相","出家與在家兩制並行、相輔相成"],"k":["出家與在家","菩薩戒","五戒","勝義僧","聲聞心態","第八識"]},"1935-a07_105":{"s":"本集主張佛門只有頓悟與漸修而無「漸悟」：十信至七住破參前的種種行屬漸修，破參時一念相應慧為頓悟；引《大寶積經》偈與六祖聞「應無所住而生其心」開悟為證，說「一悟即至佛地」是方便說，並依《楞嚴經》說悟後仍須漸修至成佛。","p":["十信與六度至七住破參前皆屬漸修","參禪至「見山不是山」後一念相應頓悟","六祖於《金剛經》句下大悟，非四句偈時","「一悟即至佛地」為方便說，悟後非佛","理則頓悟，事非頓除，悟後漸修成佛"],"k":["頓悟漸修","明心","參禪","六祖壇經","五十二階位","楞嚴經"]},"1817-a07_106":{"s":"本集說明三寶分住持、出世、自性三種：住持三寶為佛像、經典與出家人，講者提醒勿供養坦特羅行者；出世三寶含化身佛、四聖諦與因緣法及四向四果聖僧，並辨十因緣之識為入胎識、十二因緣之識為識陰；自性三寶即自心如來第八識。","p":["住持三寶：佛像、經典、住寺出家人","出世法寶：四聖諦、八正道、因緣法","十因緣之識為入胎識，十二因緣為識陰","出世僧寶為四向四果聖僧與辟支佛","自性三寶即第八識，應以親證為目標"],"k":["三寶","如來藏","四聖諦","十二因緣","歸依","坦特羅佛教"]},"1890-a07_107":{"s":"本集說明在家居士如何設佛壇：方位不必依風水，避免面向廁所、房間即可，依空間擺設佛像、香爐、燈、水、花、果與食物並說明細節；講者強調不可供奉坦特羅佛教佛像並批評其法義，另說祖先牌位宜置兩旁前方，開光擇日並非重點。","p":["重在心誠，方位不必看風水","佛像材質不拘，依空間大小擺設","講者主張勿供坦特羅佛教佛菩薩像","香、燈、水、花、果、食物的供養要點","祖先牌位置兩旁前方，開光非必要"],"k":["佛壇","供養","在家居士","坦特羅佛教","觀想"]},"1934-a07_108":{"s":"本集以世人求長生不老為引，舉《出曜經》喪子婦人借火之例與《雜阿含經》說生必有死；依《央掘魔羅經》說眾生色身皆如來藏所生、諸佛不食肉，舉寶志禪師偈說冤冤相報；指出如來藏本無生滅，才是真正的長生不老藥。","p":["喪子婦人借火悟無常，得法眼淨","凡有五陰身者，生必有死","色身皆如來藏所變，故諸佛不食肉","如來藏執持業種，成就三世因果","如來藏無生無滅，即真正長生不老藥"],"k":["如來藏","生死無常","不食肉","因果","無餘涅槃","入胎識"]},"1930-a07_109":{"s":"本集說明結善緣與惡緣的不同果報，以阿難、迦葉往昔對死貓的態度致今世化瓜結果迥異為例，說明種子存於如來藏遇緣相應；引《菩薩善戒經》說菩薩寧起貪護眾生、不起瞋捨眾生，舉鬱頭藍弗起瞋墮惡道；並說菩薩宣說正法助眾生免造惡業。","p":["善緣使人歡喜受教，惡緣令人厭離","阿難、迦葉因往昔一念心而得不同果","菩薩寧起貪護念眾生，不起瞋捨眾生","鬱頭藍弗起瞋詛咒，終墮惡道","菩薩宣說正法，幫助眾生避免造惡業"],"k":["結緣","因果","瞋恚","菩薩戒","如來藏","了業"]},"1882-a07_110":{"s":"本集區分名師與明師：名師具名聲徒眾，所說未必合佛法，講者舉主張意識常住、否定第八識、坦特羅保持全身樂受等說為例批評；引《大乘本生心地觀經》修道四法，定義明師為能教人實證三乘菩提者，並說明真善知識依種性分別教導。","p":["道場大、徒眾多不等於真善知識","講者批評意識常住、否定第八識等說","修道四法以親近善友為第一","明師能教導學人親證三乘菩提","依聲聞、緣覺、菩薩種性分別引導"],"k":["善知識","名師與明師","三乘菩提","第八識","常見斷見","明心"]},"2072-a09_021":{"s":"本集分兩部分探討「一花一世界，一木一菩提」：先引《華嚴經》《梵網經》說明蓮華譬喻如來藏，一葉即一三千大千世界，故應說「一花一如來，一葉一世界」；再引《大般泥洹經》《羅摩伽經》《瑜伽師地論》說明草木僅有物性、無八識心性，只是有情共業感召的依報，不能成佛。","p":["蓮華譬喻如來藏，出淤泥而不染","《梵網經》：一葉一世界即一三千大千世界","應改說「一花一如來，一葉一世界」","草木無八識心性，無佛性不能成佛","草木果實是有情業力感召的增上果依報"],"k":["如來藏","華嚴經","梵網經","三千大千世界","依報","八識"]},"2103-a09_022":{"s":"本集回應「佛教原是緣起論，後期才轉入唯心論」之說。引《雜阿含經》「此法常住，法住法界」、法不離如，說明緣生法背後有常住的如來藏隨順緣起；再以《集論》、《般若經》「唯心所現」及《大乘理趣六波羅蜜多經》說明佛法的唯心是八識運作，非西方哲學唯心論，緣起不能離第八識。","p":["真如常住，佛法宗旨不可能演變","《雜阿含》：緣生法不離如、此法常住","六識須藉眾緣及第八識種子才能出生","唯心所現指第八識，不是意識心","緣起與唯心不相違，皆依八識而說"],"k":["緣起法","唯心","第八識","如來藏","十二因緣","八識論"]},"2114-a09_023":{"s":"本集回答供養三寶是否有金額限制。說明供養是報三寶恩、種福田，引《長阿含經》指出能受法、行法的法供養才是真供養；再引《心地觀經》說三寶恩，《菩薩善戒經》說少物能施是難施及善人施的條件，強調布施重在發心與如法得財，道場應隨喜讚歎隨分布施。","p":["供養是報三寶恩，也是種福田","能受法、行法，才是真正供養如來","少物能施為難施，應給予讚歎","善心施、信心施、如法得財施為善人施","布施能自攝攝他，信施可生忉利天"],"k":["供養","布施","法供養","三寶","福田","七聖財"]},"2071-a09_024":{"s":"本集回答為何聽《無量壽經》易相應、聽《華嚴經》卻茫然。先說《無量壽經》阿彌陀佛四十八願、《大寶積經》往生極樂三種修持及特留此經百歲；再說《華嚴經》宣說菩薩五十二位至佛地的次第，三乘菩提皆以如來藏為根本。結論是知見建立問題而非境界不夠，可依善知識熏習。","p":["《無量壽經》令眾生嚮往遠離生死苦","《大寶積經》所說往生極樂三種修持","《華嚴經》一時圓說菩薩五十二位次第","三乘菩提皆以如來藏為根本","不能契入華嚴是知見未建立，非境界不夠"],"k":["無量壽經","華嚴經","極樂世界","菩薩五十二位","如來藏","淨土"]},"2176-a09_025":{"s":"本集說明自稱活佛、法王者所行灌頂的內容。講者依達賴喇嘛著作，批評無上瑜伽四灌頂及三昧耶戒、十四根本墮皆以雙身法為核心；並以佛制出家不淫、在家不邪淫，以及佛陀於菩提樹下證悟等，論證雙身法非佛法，觀想本尊生起佛慢亦違背斷除我慢之教。","p":["無上瑜伽瓶、祕密、智慧、勝義四灌頂","三昧耶戒與十四根本墮約束修雙身法","講者引達賴著作所述以性交修明光之說","佛制淫戒，佛陀並未以雙身法成道","觀想本尊生佛慢，與斷我慢之教相違"],"k":["灌頂","雙身法","三昧耶戒","密宗","佛慢","淫戒"]},"2177-a09_026":{"s":"本集續談密宗灌頂。講者批評達賴所說的佛慢與以瞋恨辦事皆與煩惱相應，歸納其教義缺乏斷我見、斷煩惱、證初禪與證如來藏的法門；引《瑜伽師地論》說一世界無二如來，質疑活佛處處之說；再以《雜阿含經》說甘露法即解脫法，引《華嚴經》說明佛教灌頂是十地菩薩受職。","p":["佛慢源自我見，與煩惱相應","菩薩不可以瞋恨攝受眾生","講者歸納密宗教義所缺的六點","一三千大千世界無二如來同時出現","佛教灌頂指十地菩薩受職、住法雲地"],"k":["灌頂","斷我見","甘露法","法雲地","初禪","密宗"]},"2170-a09_027":{"s":"本集釐清有念與無念並非同一心。眾生有八識，意識由意法因緣而生、恆是有念心，離念靈知仍不離定境法塵；引《六祖壇經》「無念為宗、無相為體、無住為本」，說明無念心是第八識如來藏，並批評「起心動念即妄想」的教法。證悟者以有念的意識心證無念的如來藏，二者不矛盾。","p":["眾生有八識，各有專屬功能","意識由意法因緣生，永遠是有念心","《壇經》：百物不思、念盡除卻是大錯","無念、無相、無住指第八識真如心","以有念妄心證無念真心，並不矛盾"],"k":["無念","如來藏","八識","六祖壇經","離念靈知","意識"]},"2101-a09_028":{"s":"本集解說天魔、陰魔、煩惱魔。魔指令修行者退失出離生死善法欲的障礙，舉男女欲愛、疑三寶因果、出家貪利養等魔事；陰魔是寶愛五陰、錯認意識常住，煩惱魔含三界貪愛、愚癡無明、瞋恚，天魔是他化自在天主波旬擾亂修行；對治在無常苦空無我及般若實相智慧。","p":["魔是令人退失出離生死善法欲者","欲愛、疑三寶、貪利養等皆屬魔事","陰魔：寶愛五陰、錯認意識為常住","煩惱魔含三界貪愛、愚癡無明、瞋恚","天魔波旬以男女欲愛擾亂修定者"],"k":["天魔","陰魔","煩惱魔","五陰","斷我見","初禪"]},"2157-a09_029":{"s":"本集比較小乘四念處與大乘禪，大手印留待下集。依《雜阿含經》說四念處觀身不淨、受是苦、心無常、法無我，破四顛倒、斷我見而得四果；大乘禪則參究並實證第八識如來藏，驗證其為入胎識、涅槃本際、成佛所依，現觀如來藏與五蘊「非我、不異我、不相在」，須轉依方有禪觀。","p":["四念處破淨、樂、常、我四顛倒","四念處只在五蘊虛妄上斷我見我執","大乘禪是實證第八識如來藏","如來藏與五蘊非我、不異我、不相在","知密意而未能轉依，不能稱為開悟"],"k":["四念處","參禪","如來藏","斷我見","轉依","涅槃本際"]},"2158-a09_030":{"s":"本集續說密教大手印。講者說明其精神瑜伽以修止、觀想白觀音、持六字大明咒並融入「非有非無」觀念為開悟，批評此皆意識心的觀想與定境，不能證得自性心；化身須三地滿心以上；生理瑜伽則為雙身法。結語比較：四念處屬解脫道，大乘禪證如來藏，大手印則被講者評為虛妄想像。","p":["大手印分生理瑜伽與精神瑜伽","修止所得的平和仍是意識變化狀態","化身須三地滿心，非觀想累積可得","真正中道的非有非無依如來藏而說","四念處是如實驗證，不是觀想"],"k":["大手印","中道","四念處","如來藏","觀想","六字大明咒"]},"2154-a09_031":{"s":"本集回答各宗教勸人為善，行善是否都能往生西方。先指出宗教中亦有假借行善之名者；引《成唯識論》定義善、不善、無記；人天善法果報只在人間或欲界天；引《觀無量壽佛經》說往生須修世福、戒福、行福三福淨業並繫念諦觀彼國，三福與三乘菩提相應故稱淨業。","p":["宗教中亦有打著勸善幌子的偽善者","《成唯識論》：此世他世順益名為善","人天善法的果報在人間或欲界天","往生須修三福淨業並繫念諦觀彼國","諸佛名號一歷耳根，永為道種"],"k":["三福淨業","往生極樂","善法","人天善法","觀無量壽佛經","念佛"]},"2180-a09_032":{"s":"本集回答看很多佛書是否障礙修行。先說五乘修行：人天善法不出輪迴，三乘菩提中聲聞修四聖諦、緣覺修十二因緣、菩薩證如來藏；再列舉講者認為不如理的佛書說法，如歡喜布施即入初地、一念不生即無分別智、修雙身法、放下即開悟、妄心修成真心等，提醒錯誤佛書不如不看。","p":["人天善法的果報不出三界輪迴","三乘菩提皆匯歸於佛菩提","菩薩證如來藏，不共二乘","一念不生不是無分別智","妄心不能修成真心，錯誤佛書不如不看"],"k":["三乘菩提","佛書","如來藏","無分別智","四聖諦","十二因緣"]},"2118-a09_033":{"s":"本集回答淨業學人家中可否供「唵嘛呢叭咪吽」條幅。講者主張此咒不如法、建議丟棄，並就其出處密續《佛說大乘莊嚴寶王經》的事相，以反諷方式辨正：經中稱觀自在菩薩功德過於如來、諸佛不知此咒、菩薩為眾生授成佛記、以語言文字為微妙本心等，據此判定非佛所說。","p":["六字咒出自《佛說大乘莊嚴寶王經》","密續稱菩薩證量過於如來，自相矛盾","觀自在菩薩不應與觀世音菩薩畫等號","咒語是生滅法，不能等同微妙本心","判定此密續非世尊所說，宜速遠離"],"k":["六字大明咒","密續","觀世音菩薩","觀自在菩薩","淨業","法義辨正"]},"2119-a09_034":{"s":"本集續辨《佛說大乘莊嚴寶王經》卷4。講者以反諷手法評析經中釋迦佛遍訪諸如來求六字咒不得、蓮華上如來向觀自在菩薩求法並供養瓔珞、推崇戒行缺犯有妻子的法師「同見如來」、念一遍等同七地菩薩功德等情節，指其違背佛的證量與「以戒為師」之教，勸學人遠離此咒。","p":["經稱無數如來皆不知六字咒","如來向菩薩求法、供養菩薩之荒謬","八地菩薩已斷三界愛習氣，不會涕泣","推崇戒行缺犯法師，違「以戒為師」","念咒一遍等同七地功德之說不實"],"k":["六字大明咒","密續","以戒為師","觀自在菩薩","法義辨正","七地菩薩"]},"2178-a09_035":{"s":"本集回答盲目受菩薩戒後不能受持，可否在佛前捨戒改持五戒。引《菩薩瓔珞本業經》說菩薩戒有受法無捨法、盡未來際，捨戒只屬聲聞戒；引《大般若經》說明菩薩尊貴；主張受戒前應由菩薩法師先解說讀誦並熏習布施、持戒、布薩；引《菩薩善戒經》說唯退菩提心、得上惡心才失戒。","p":["菩薩戒有受法而無捨法，盡未來際","教一人趣無上菩提，福勝令眾生證獨覺","起心捨戒，會種下退分種子","受戒前應先解說讀誦，使心開意解","退菩提心、得上惡心，方失菩薩戒"],"k":["菩薩戒","捨戒","失戒","布薩","菩提心","五戒"]},"2115-a09_036":{"s":"本集回答修苦行對成佛是否有幫助。講者指出忍痛盤腿、拜懺朝山、外道泡水行、睡釘床等是表相苦行，世尊示現六年苦行後改行不苦不樂行。真正苦行在心地：不貪五欲、不執取五蘊，修不放逸行，時時觀五欲過患與五蘊虛妄；菩薩更於度眾的煩惱中修行，得解脫之樂與法樂。","p":["自苦其身、外道苦行屬表相苦行","世尊捨六年苦行，改行不苦不樂行","苦樂一體兩面，五欲之樂伴隨痛苦","真苦行是不貪五欲、不執取五蘊","菩薩於度眾煩惱中修苦行而得法樂"],"k":["苦行","五欲","不放逸行","五蘊","解脫道","菩薩行"]},"2138-a09_037":{"s":"本集從《孟子》「生於憂患，死於安樂」引出問題，先探討一般人能否生於安樂。就出生而言，住胎、出胎有迫隘、擠壓、溫差等苦，生日實為母難日；就生活而言，人天之樂源於過去持五戒、行十善，但修福享福反覆不斷，屬有漏法、不出輪迴，人生快樂只是片段。","p":["住胎迫隘、出胎擠壓溫差等生苦","生日實為母難日，應知恩感恩","持五戒行十善，今世得生人天受樂","同一行為因發心不同而果報不同","人天福報屬有漏，仍不出生死輪迴"],"k":["生苦","五戒十善","人天善法","有漏","福報","輪迴"]},"2139-a09_038":{"s":"本集續談菩薩如何生於安樂、死於安樂。菩薩修六度習以為性，世世布施而福報增長；知足常樂，減輕五欲追求；善觀蘊處界虛妄而得解脫之樂，正直受樂而不貪著；證法界實相後得法樂並利樂有情。臨終因持戒行善、斷我見並轉依無我而能坦然捨報，並發願再來人間。","p":["菩薩世世布施，福報輾轉增長","知足常樂，減輕對五欲的追求","觀蘊處界虛妄得解脫之樂、正直受樂","證法界實相後得不共二乘的法樂","斷我見、轉依無我，能坦然捨報"],"k":["法樂","解脫","知足","六度","斷我見","轉依"]},"2179-a09_039":{"s":"本集回答學佛者看到不順眼的事容易生氣該如何克服。先說貪瞋相隨及非理瞋、順理瞋、諍論瞋三種；引《華嚴經》《遺教經》《大智度論》說瞋恚過患，《正法念處經》說離瞋利益；再介紹報恩觀與瞋、恨、怨、惱四階段的自我觀察，最後指向觀察起瞋的「我」是否真實。","p":["瞋由違逆自己貪愛的境界而生起","非理瞋、順理瞋、諍論瞋三種情況","經論：菩薩起一瞋心，開百千障礙門","以報恩觀，觀一切眾生於己有恩","觀察瞋、恨、怨、惱四階段並對治"],"k":["瞋恚","對治","報恩觀","習氣","三毒","慈心觀"]},"2169-a09_040":{"s":"本集回答幾個念佛問題。指出「無心無念」其實仍是意識心在了別空無境界，用以參禪、修定、求生極樂皆不相應：明心須了知八識體性，四禪即四靜慮須除五蓋，往生須修三福並繫念彼國；「觀自己的念」亦然。念佛功德在心不在口，應由口念轉進為一念憶佛的憶佛念佛。","p":["無心無念仍是意識心了別境界","參禪須明七轉識與第八識體性","四禪即四靜慮，須降伏五蓋","往生須修三福並繫念諦觀彼國","念佛在心不在口，應轉進憶佛念佛"],"k":["念佛","無心無念","參禪","五蓋","憶佛念佛","三福淨業"]},"2133-a09_051":{"s":"本集以問答方式說明往生淨土的相關議題：淨土分四種，極樂世界亦具四土；淨土法門不只持名念佛，可由有相念佛次第轉入實相念佛。並依《無量壽經》第十八、十九願說明念佛往生之理，依《觀經》詳述三輩九品的差別，強調生西不等於已出三界，欲上品上生須先在此世見第一義。","p":["淨土分常寂光、實報莊嚴、方便有餘、凡聖同居四種","念佛法門由持名、觀想次第入無相、實相念佛","彌陀第十八、十九願：至心信樂、臨終接引","三輩九品依智慧功德深淺，謗大乘者不得往生","生西後多數仍在三界，上品上生須先證第一義"],"k":["淨土法門","三輩九品","實相念佛","阿彌陀佛四十八願","念佛三昧","往生極樂"]},"2100-a09_052":{"s":"本集講解佛法中「我」與「無我」的分類：佛所破斥的我是世俗與常見外道的覺知心，以及佛門錯悟者所執的放下心、觀照心、離念靈知、意識細心等，都是意識；錯誤的無我則有斷見與常見兩類。真實義是第八識如來藏離見聞覺知故說無我，而恆常不斷故方便說我，雙具我與無我才是了義。","p":["我分佛所破斥之我與佛所說真實我","覺知心、離念靈知、意識細心皆是意識，非常住","斷見論與常見論的無我都未斷我見","阿含、般若、唯識皆隱說或明說第八識","如來藏具無我性又常住，故方便說為我"],"k":["我與無我","如來藏","斷我見","意識","常見外道","斷見"]},"2195-a09_053":{"s":"本集介紹鬼神道：依經論說明墮餓鬼道的業因、鬼的種類（瑜伽師地論分外障、內障、無障三類）、住處與壽量。再回答鬼神附身問題，指出附身需有遠因近緣，心堅定離貪則鬼神難以影響；鬼神斷事只能少分準確，正神多護持正法，少數隨天魔的鬼神會以恐怖、美色、假現佛菩薩形障礙修行，應以三乘經典印證並迴向冤親債主。","p":["下品惡業及慳貪諂曲等輕惡業生餓鬼道","鬼有三十六種，略分外障、內障、無障三類","附身需宿世因緣、貪境界等遠因近緣才成就","鬼神神通有限，多數乩童以模稜兩可回答","魔障三相：現惡形、示美色、假現天佛菩薩形"],"k":["鬼神附身","餓鬼道","魔障","因果業報","迴向冤親債主"]},"2111-a09_054":{"s":"本集探討佛法的精要。講者先引一位大法師以「純淨、純善」二十字為精要的說法，並提出批評：若如此，阿羅漢早該成佛。接著依天台五時三教概說世尊一代時教，說明阿含隱覆密意而說第八識本住法，再講《金剛經》的金剛心與《心經》兼說真心妄心，結論佛法精要即每個有情都有的實相心如來藏。","p":["講者批評以純淨心、純善行為精要之說","天台五時：華嚴、阿含、般若、方等、法華涅槃","阿含以二乘解脫為主，隱覆密意說第八識","金剛經之金剛心即阿賴耶識，不可毀壞","心經說真妄心和合，精要在實相心如來藏"],"k":["如來藏","五時三教","金剛經","心經","真心與妄心"]},"2096-a09_055":{"s":"本集講解「三界唯心、萬法唯識」。講者先舉玄沙與桂琛的公案，批評某大法師的解釋未觸及第一義，指出公案旨在顯示第八識。接著說明欲界、色界、無色界與四聖六凡十法界，引《華嚴經》「心如工畫師」說明三界皆由阿賴耶識所造；再以「八個兄弟共一胎」偈解釋八識心王和合運作，故說萬法唯識。","p":["公案意旨皆指向第八識，非語言文字游戲","三界：欲界、色界十八天、無色界四天","華嚴「心如工畫師」：阿賴耶識造三界一切法","八個兄弟偈：前五識、意識、末那、阿賴耶分工","八識心王為三界萬法根本，故說萬法唯識"],"k":["三界唯心萬法唯識","八識心王","阿賴耶識","末那識","禪宗公案"]},"2160-a09_056":{"s":"本集說明如何修除煩惱。從人生各階段之苦與三苦八苦談起，依四聖諦說苦由愛與欲招集，而煩惱根源在無明。詳解一念無明（四住地煩惱，二乘所斷的我見我執）與無始無明（不知法界實相），說明菩薩證悟第八識後漸斷四住地、分破無始無明直至佛地，並強調入手處須先斷我見、如實了知識陰虛妄而證初果。","p":["苦集聖諦：愛與欲相應，心恆染著招集苦果","一念無明即四住地煩惱，我見為其根本","無始無明是不知法界萬法根源第八識","證悟後漸斷四住地，入地後分破無始無明","修行首要在斷我見、了知意識覺知心虛妄"],"k":["一念無明","無始無明","四住地煩惱","斷我見","四聖諦","識陰"]},"2073-a09_057":{"s":"本集回應「八敬法是否不民主」的疑問。先談中西女性觀與經典中女性菩薩的事例，說明佛法實證上男女平等；再依巴利聖典與《毘尼母經》敘述大愛道出家及八敬法緣起，列出八條內容，分析其為使正法久住及當時社會背景下的權宜施設。講者指出大乘只論證量不分男女，八敬法只約束依聲聞戒的比丘尼，依菩薩戒者無此問題。","p":["經典多見女性菩薩，實證上男女平等","大愛道三請出家，阿難代求，佛制八敬法","八敬法為正法久住、保護尼眾的權宜施設","列舉八敬法八條內容","大乘只論證量；八敬法只約束聲聞比丘尼"],"k":["八敬法","比丘尼","菩薩戒","聲聞戒","男女平等"]},"2161-a09_058":{"s":"本集講解如何懺悔業障。以世親菩薩由謗大乘轉而弘揚大乘、阿闍世王慚愧懺悔的故事說明懺悔可滅罪。再以問答說明三障應為煩惱障、所知障、業障，性障即五蓋屬煩惱障；懺悔要領在發露與永不復作，依重、輕、小戒分別對眾、對首、自責懺；誤以為開悟的大妄語者應公開懺悔，若曾謗法謗賢聖則須盡形壽護持正法。","p":["世親以舌謗大乘，轉以舌弘揚大乘滅罪","慚愧二白法能救眾生，作已懺悔是智者","三障是煩惱障、所知障、業障；性障即五蓋","懺是發露、悔是永不復作，依戒輕重懺法不同","大妄語須公開懺悔；謗法者須盡形壽護法"],"k":["懺悔","業障","三障","大妄語","慚愧","世親菩薩"]},"2105-a09_059":{"s":"本集談佛教徒如何教養小孩。先依《瑜伽師地論》說明入胎須三處現前、無三種過患，親子相聚皆有因緣，惡緣也可藉佛法智慧轉為善緣。接著比較權威式、放任式、不一致、民主自由式四種教養方式，提出以身作則、因勢利導、公平、適度約束、暗示不姑息、態度一致六原則，並引《長阿含經》父母五事。","p":["入胎須三處現前，並無產處、種子、宿業過患","親子有善緣惡緣，可依佛法智慧轉惡為善","四種教養方式各有後果，民主自由式較佳","六原則：以身作則、因勢利導、公平等","長阿含：父母以五事敬親其子"],"k":["教養子女","因緣果報","入胎","家庭眷屬","身教"]},"2108-a09_060":{"s":"本集探討佛教對器官捐贈的看法。先說明器官捐贈與腦死的醫學定義及程序，再從佛法說明死亡過程：初死位意識仍在、正死位與業鏡，五種死亡情形，及《瑜伽師地論》所說第八識漸捨身、冷觸漸起。講者認為息脈停止後數小時意識仍能覺痛，摘取器官恐生大瞋而墮惡道，建議在捐贈文件加註先行全身麻醉；佛教肯定並隨喜器官捐贈。","p":["器官捐贈與腦死判定的醫學說明","初死位意識未滅，正死位如來藏漸捨身","五種死亡情形與中陰身生起","瑜伽師地論：造善惡業者冷觸由下或上漸起","建議加註先行全身麻醉，以免劇痛生瞋"],"k":["器官捐贈","死亡過程","中陰身","布施內財","腦死"]},"2094-a09_061":{"s":"本集說明什麼是身口意業。從「業」的字源與梵文羯磨談起，以戒律中根本、方便、成已說明業包含動機、行為與結果，而意業為首。引《雜阿含經》要於微細罪生大怖畏，以《了凡四訓》衛仲達故事說明起念即成業；並列十不善業跡及以八正道對治，說明黑業、白業、無記業與「已作不失」。講者也批評喇嘛教以雙修消業障之說。","p":["業是動機、造作、承受結果的因果聯結","意業為首，以謗菩薩藏為例說成已罪","衛仲達故事：一念不正，惡業已成","十不善業跡分身三、語四、意三，以八正道斷","已作不失、未作不得；講者批評雙修消業說"],"k":["身口意業","意業","十善業","八正道","因果業報"]},"2078-a09_062":{"s":"本集講解業因與業習。講者指出外道以苦行受盡業報為解脫是邪見，業的成就在無明，業之流轉在如來藏含藏業種。說明雜心阿賴耶識、引業、別業、共業，業報不一定即時現前，善惡主要由意業初發心決定，別業也受共業牽引。再以末那識恆與見、愛、癡、慢相應說明業習形成，強調正聞熏習可改變業習。","p":["苦行受報求解脫是外道邪見","如來藏含藏業種，業因無明而起","引業、別業、共業的區分","善惡果報主要由意業初發心決定","末那識見愛癡慢成業習，正聞熏習可改"],"k":["業習","阿賴耶識","末那識","共業與別業","正聞熏習"]},"2135-a09_063":{"s":"本集講解如何守護身業，以善護律儀為要，說明戒律儀、靜慮律儀、無漏律儀三層次，並著重基本戒。引《大智度論》說殺罪最重，談軍人出於共業的殺業，以婆羅門殺羊祭祖的故事說明殺業果報，並說祭祖宜以布施齋戒迴向。講者也批評喇嘛教以五肉五甘露供佛；再說偷盜戒與須深盜法的故事，以盲龜浮木喻人身難得。","p":["律儀三層：戒律儀、靜慮律儀、無漏律儀","殺罪最重，殺羊祭祖故事顯示業報","祭祖應以布施、齋戒功德迴向","梵網經盜戒：一針一草不得故盜；盜法最重","人身難得如盲龜浮木，應修三福"],"k":["身業","殺戒","盜戒","律儀","人身難得"]},"2143-a09_064":{"s":"本集說明如何檢視邪行。指出觀看色情畫面即在阿賴耶識熏下邪行種子，講者並批評密宗雙身像與兩部《廣論》以雙身法為主軸。談往世眷屬習氣現行（有情相望）不一定是邪淫，應轉為佛道上的互相增上。引《大智度論》、《涅槃經》、《楞嚴經》說淫心繫縛、修定須先斷淫心，最後說身業供養與離邪行的四種利益。","p":["觀看色情即熏習種子，遇緣現行犯戒","講者批評雙身像與兩部廣論偏離佛法","往世眷屬習氣現行，應轉為菩薩道侶","楞嚴經：不斷淫心修定如蒸砂煮飯","離邪行得諸根調順等四種智所讚法"],"k":["邪淫戒","淫欲","阿賴耶識熏習","禪定","身業供養"]},"2142-a09_065":{"s":"本集談如何承受身業的異熟果報。說明人身為四大和合而無常，身有缺陷者可如海倫凱勒等人積極運用尚可用的五蘊行善；生病應就醫，並放鬆身心，如印光大師、鑑真以眼疾精進。以佛陀示現衰老、四梵志避死不成說明生老病死不可免，列舉佛說九種令壽命早夭的因緣，勸以般若正見轉依，將身體作為成佛道器。","p":["得人身者過去世善惡業皆有","身有障礙仍可積極運用五蘊行善","佛陀示現衰老；四梵志以神通避死不成","佛說九種令壽命早夭的因緣","發菩提心者以此身為成佛道器"],"k":["異熟果報","無常","生老病死","身業","菩提心"]},"2134-a09_066":{"s":"本集講解如何守護口業。指出念頭說出口即造較重口業，菩薩應不聽、不說、不傳是非，佛弟子只作法談與聖默然；講者認為平實導師評論法義是護念眾生的善口業。依序說明妄語（最重為未證言證的大妄語）、《瑜伽師地論》十種綺語、兩舌、惡口，以常不輕菩薩為例，並說各項守護迴向菩提所得的如來功德。","p":["惡口傷人恨難消，菩薩應善觀因緣","佛弟子唯作二事：法談與聖默然","大妄語即未證言證，害己害眾生","瑜伽師地論列綺語十種","離兩舌、惡口；常不輕菩薩不以惡口對人"],"k":["口業","妄語","綺語","兩舌","惡口","大妄語"]},"2144-a09_067":{"s":"本集說明如何看到自己的瞋習。分析瞋的三種程度與成因，根本在我相與執著；建議從觀察他人及自己發怒時聲音、肌肉、表情變化覺察情緒，並留意意識帶起的心所法，提醒故瞋是菩薩重戒。以大迦葉與兩比丘爭勝、孝子伯俞等故事說明調伏之道，勸修慈悲喜捨與安忍，必要時避開、念佛或數數化解。","p":["瞋有毀滅、遠離、吵鬧不離三種程度","瞋起於我相、執著己見與境界相違","觀察身口表情變化才能看到並控制情緒","故瞋是菩薩重戒；我見重者好爭勝","以安忍、慈悲喜捨結善緣，可念佛化解"],"k":["瞋習","我見","安忍","慈悲喜捨","菩薩戒"]},"2149-a09_068":{"s":"本集講解學佛人如何對治欲望。說明欲界三大欲（飲食、睡眠、淫欲）與欲的生起是五根觸五塵的比對覺受，舉財物五家共有、男女欲、國家欲望說明欲患；講者並批評達賴喇嘛一次公開談話含政治野心。再說出家人的惡欲、大欲、求生天三種欲，及欲貪的耽著、不知足、謀略、覆蔽等相，以親近善知識、念佛修定力離欲。","p":["欲界眾生受制於飲食、睡眠、淫欲三大欲","欲是五根觸五塵起樂受，虛幻起伏","財物五家共有；男女欲、國家欲望皆成大患","出家人仍可能有惡欲、大欲、求生天欲","離欲須親近善知識、念佛培養定力"],"k":["五欲","欲貪","離欲","男女欲","念佛"]},"2150-a09_069":{"s":"本集談學佛人如何看男女欲。說明眾生即有情，男女相只存於欲界；以耶舍比丘奉母命續種、被佛嚴厲呵責的故事，及其過去世為光音天人首先貪食地味、致眾生失去神足而生男女相的因緣，說明淫欲為大過患。引《涅槃經》對治淫欲之法，講者並批評喇嘛教及宗喀巴對瑜伽菩薩戒條文的解釋，說明該戒條的成立條件。","p":["男女相只在欲界，色界以上無男女相","耶舍續種，佛斥為非法、非律、非如佛教","光音天人貪食地味，漸生男女相與情欲","涅槃經教比丘遠離女人、作臭穢想","講者批評宗喀巴曲解瑜伽菩薩戒條"],"k":["男女欲","淫戒","耶舍比丘","光音天","瑜伽菩薩戒"]},"2085-a09_070":{"s":"本集講解學佛人的飲食觀。指出飲食男女是人之大欲，聲聞律多與飲食有關；說明提婆達多五法與十二頭陀行的差異、彌勒菩薩所說三種苦惱修行人，以及第一、二次結集中與飲食相關的爭議，講者並批評以結集否定大乘的學者與法師。再說菩薩食觀：為身中八萬戶蟲受食、分享布施，給孤獨長者平等施，最後指出一切眾生依識食住，實即依如來藏。","p":["食色是欲界有情業習，聲聞律多涉飲食","提婆達多五法誘新僧，非真解脫之道","第一次結集富樓那提飲食七事不同意見","菩薩受食念八萬戶蟲，不貪美味","一切眾生依食住，究竟依如來藏安住"],"k":["飲食觀","頭陀行","佛教結集","布施","四食","如來藏"]},"2121-a09_071":{"s":"本集探討出家是出哪個家。指出剃髮離俗只是表相出家；依《過去現在因果經》心厭五欲為聲聞的方便真出家；再依《大乘本生心地觀經》、《維摩詰經》、《佛說華手經》說明五陰宅的宅主本識如來藏本離三界六塵，才是第一義的真出家。","p":["剃髮離俗只是出世俗家的表相出家","心厭離五欲為聲聞的方便真出家","五陰火宅的宅主是本識如來藏","如來藏本來出家、無縛無解","如來藏具出世間無分別智"],"k":["出家","如來藏","五陰火宅","厭離五欲","第一義諦","無分別智"]},"2123-a09_072":{"s":"本集續講《佛說華手經》「雖不受持法…離一切法相」偈，說明如來藏不受持諸法而能壞諸法；引《大寶積經》彌勒菩薩言跋陀羅剃度唯是形相，菩薩真出家是離諸相處於三界、成熟眾生；最後歸納身出家與心出家的四種分別。","p":["如來藏不受持法而能壞諸法","如來藏不分別中廣分別","彌勒：剃度唯形相，非真出家","菩薩離諸相處三界、成熟眾生","身出家與心出家的四種分別"],"k":["出家","如來藏","菩薩道","成熟眾生","身出家心出家"]},"2122-a09_073":{"s":"本集續論出家，說明所謂出家即非出家；引達摩「不見性剃除鬚髮亦是外道」、五祖「不識本心學法無益」及「入門須辨主，當面分緇素」，主張白衣黑衣應以是否明心開悟來分。講者批評「在家人是一壺煮不開的水」、白衣不能說法等說法是以表相衡量。","p":["所謂出家即非出家","不見性而剃髮，仍是心外求法","外於或否定如來藏求法即外道","緇素以有無開悟分辨，不在衣相","不以在家身相衡量善知識"],"k":["出家","明心開悟","入門須辨主","白衣黑衣","善知識"]},"2124-a09_074":{"s":"本集主張四眾應互相扶持，不應僧衣崇拜而歧視在家菩薩；解釋波羅提木叉為別別解脫戒，駁斥菩薩戒為附屬戒之說；舉善財參訪、六祖、彌勒文殊現在家相及《瓔珞經》六親可授菩薩戒，並以德光比丘、拾得故事說僧慢之過，批評表相佛法。","p":["四眾應互相扶持，遠離僧衣崇拜","別別解脫戒義，菩薩戒非附屬戒","地上菩薩多現在家相利益眾生","德光比丘因僧慢未得法益","脫離表相佛法，扶持見道居士"],"k":["僧衣崇拜","僧慢","菩薩戒","在家菩薩","表相佛法","四眾"]},"2107-a09_075":{"s":"本集回答佛教是否講三魂七魄、靈魂不滅。說明靈魂見是以五陰中意識為常的常見；剖析儒道三魂七魄之說邏輯不通且皆屬五陰；外道未斷我見而誤認中陰身、鬼身為靈魂；以薪火喻說明異陰相續依如來藏所藏業種，而非靈魂。","p":["靈魂見是以五陰為常的常見","三魂七魄皆不離意識與五陰","外道誤認中陰身、鬼身為靈魂","異陰相續，如薪火非一非異","業種藏於如來藏而相續受生"],"k":["靈魂見","常見","三魂七魄","異陰相續","中陰身","如來藏"]},"2193-a09_076":{"s":"本集說明酒本身無罪但能引生罪惡，故五戒戒飲酒，菩薩十重戒更戒賣酒。飲酒使煩惱現行、遮障聖道、招癡狂果報；舉迦葉波佛時五戒居士醉後殺盜淫妄俱犯，及莎伽陀醉臥而佛制酒戒之事，並列飲酒十種過失。","p":["酒本無罪，但能引生罪惡","菩薩戒賣酒，其過大於飲酒","居士醉後殺盜淫妄俱犯","伏龍的莎伽陀醉臥，佛因制酒戒","飲酒有顏色惡等十種過失"],"k":["酒戒","五戒","菩薩戒","放逸","戒定慧"]},"2106-a09_077":{"s":"本集回答佛教徒有無等級。等級源於世俗見與我見、我所；佛教是非有等級、非無等級：佛破四種姓、理上眾生如來藏平等；依職事、受戒、四果及五十二位階方便安立名稱。引《大般涅槃經》說菩薩實無所得，有所得即成障礙、落四顛倒。","p":["等級觀念源於我見與我所","佛破四種姓，理上眾生平等","職事、戒、果位皆方便安立","修證愈高是捨得愈多","有所得名為礙，即四顛倒"],"k":["等級","我見我所","四種姓","五十二位階","無所得","四顛倒"]},"2104-a09_078":{"s":"本集說明出家人看命看風水不如法且違戒，命相風水與福德相關。評積善餘慶之說可勸善但不盡合因果；宿命觀屬常見，迷信改運落見取見、戒禁取見；命是正報，運與風水是依報，應以五戒十善改善；並以風水師故事說明福人居福地。","p":["出家人看命看風水違反戒律","祖先餘慶餘殃說不盡合因果","迷信改運落入見取見、戒禁取見","命是正報，運與風水是依報","福人居福地，應修五戒十善"],"k":["命相風水","福德","正報依報","因果","見取見","五戒十善"]},"2155-a09_079":{"s":"本集說明將經咒印紙燒給祖先不如法：焚毀經咒有過，應恭敬盛裝經律，往生淨土須修三福、一心念佛。此俗源於我見、見取見與貪著佛法功德，衍生往生錢、紙蓮花、紙紮祭品、陰間信用卡等；燒紙錢受事火習俗影響，並舉迦葉三兄弟捨事火歸佛。","p":["焚毀佛經佛咒有過失","往生淨土靠修三福、一心念佛","我見與見取見衍生燒紙諸邪見","燒紙錢源於事火外道的習俗","迦葉三兄弟棄事火而歸依佛"],"k":["燒紙錢","見取見","我見","事火外道","恭敬經典","念佛往生"]},"2194-a09_080":{"s":"本集回答釋儒道是否相同。講者批評五教合一及以《弟子規》等取代佛法；道家清淨無為屬自然外道，儒家為入世經世之學，佛法涵蓋世出世間；述相似佛法源流如依附老莊、宋明理學及講者批評的雙身法；三家勸善部分相通，但佛說皆以出生萬法的如來藏為前提。","p":["五教合一是長久的錯誤認知","道家道法自然屬自然外道","理學致良知仍是意識心","相似佛法導致正法衰亡","佛說善法以如來藏為前提"],"k":["釋儒道","相似佛法","自然外道","如來藏","世間善法"]},"2159-a09_081":{"s":"本集回答居士可否歸依三寶。先說明四眾與居士之義，舉現出家相與在家相的菩薩、禪師，指出佛門以證法見道而非表相判定出家在家；再釋歸依及住持、出世、自性三種三寶與四類僧；結論居士可以歸依，並批評上師在三寶前的四歸依。","p":["四眾與居士的定義","以證法見道而非表相判出家","歸依是誓願信從三寶至成佛","住持、出世、自性三種三寶","居士可歸依，應遠離四歸依"],"k":["歸依","三寶","居士","勝義僧","自性三寶","四歸依"]},"2113-a09_082":{"s":"本集以七例說明佛菩薩時時護念眾生：乾達多蜘蛛絲、人蟒見舍利弗生天、受三歸得護法神與聞法生喜皆佛神力、明心靠佛菩薩給一念、講者2003年台中授課親歷、十地滿心受諸佛灌頂、釋迦菩薩讚弗沙佛超越九劫。勸學人除慢並感恩。","p":["佛菩薩藉善根救拔惡道眾生","受三歸、聞法生喜皆佛神力","明心見性是佛菩薩給的一念","十地、等覺仍需諸佛加持","成就皆由護念，應除慢感恩"],"k":["佛菩薩護念","善根","明心見性","加持","除慢"]},"2128-a09_083":{"s":"本集回答因工作或家庭需殺生怎麼辦。依《大般涅槃經》壞五陰名殺生；舉安世高償命、悟達國師人面瘡、人蟒說明因果不爽；以根本、方便、成已判業輕重，如動物實驗應作三歸迴向、懺悔輕垢；並說有德國王護法及菩薩為利他少分現行性罪的開緣。","p":["壞眾生五陰名為殺生","安世高、悟達國師見因果不爽","依根本、方便、成已判業輕重","實驗殺生應三歸迴向並懺悔","為利他的開緣反生功德"],"k":["殺生","因果","根本方便成已","菩薩戒","開緣","懺悔"]},"2147-a09_084":{"s":"本集回答學佛人可否占卜、算命、賭博。舉沙彌救蟻延壽及講者鑽研紫微斗數、子平法的親身經驗，說明命可變、非真實法；三世因果由如來藏執持業種，非算命能知；《梵網經》制戒，犯輕垢罪。賭博增長貪癡、違戒、耗損福德、招人譏嫌。","p":["占卜算命結果可變，非真實法","沙彌救蟻延壽，算命算不出","三世因果由如來藏執持業種","梵網經制戒，犯者為輕垢罪","賭博增長貪癡、耗損福德"],"k":["占卜算命","賭博","菩薩戒","因果","如來藏","福德"]},"2164-a09_085":{"s":"本集論證意識是生滅法。引《入楞伽經》一心八識，第八識為真心，前七識生滅；意識依根塵而生、詳細分別法塵；意識在睡眠、悶絕、無想定、滅盡定、重度麻醉時斷滅。講者據此批評離念靈知、一念不生及雙身法樂空不二等說法。","p":["一心八識，第八識為真心","意識依根塵而生，入胎後始現","意識詳細分別法塵、生起三受","睡眠悶絕麻醉等位意識斷滅","執意識為常即落常見外道"],"k":["意識","八識","生滅法","常見外道","離念靈知","滅盡定"]},"2117-a09_086":{"s":"本集以殺與被殺的案例說明冤冤相報。流離王滅釋迦族源於過去漁民捕魚、二魚發毒咒，佛前身打魚頭仍受頭痛餘殃；目犍連一念惡想亦受報；悟達國師人面瘡經迦諾迦化解，後造《慈悲三昧水懺》。勸佛弟子持不殺戒。","p":["流離王滅釋迦族的宿世因緣","佛前身打魚頭仍受頭痛餘殃","目犍連一念惡想亦受果報","悟達國師人面瘡與三昧水懺","殺生報短命多病，應持不殺"],"k":["殺生","因果","冤親債主","慈悲三昧水懺","不殺生戒"]},"2095-a09_087":{"s":"本集回答眾生會否度盡。眾生即有情，皆有如來藏，自性清淨而含染污；講者認為細菌病毒屬有情、植物非有情；引《雜阿含》爪上土喻、科學估計及虛空無邊說明眾生無量；以彌勒龍華三會、須菩提授記說明諸佛所度仍如爪上土，眾生不可能度盡。","p":["有情皆有如來藏，自性清淨有染","細菌病毒屬有情，植物非有情","爪上土與大地土喻眾生無量","虛空無邊，世界與眾生無量","諸佛所度有限，眾生度不盡"],"k":["眾生","有情","如來藏","無量無邊","度眾生"]},"2137-a09_088":{"s":"本集說明念佛退轉的兩個原因：未先聞般若建立正知見、不知念佛次第。依《大寶積經》一行三昧經文，說明散心念佛、出聲念、金剛默念至心念心憶的轉進；一行三昧即念佛三昧、明心見性，須具定力、慧力、福德，並介紹無相憶佛拜佛法門。","p":["念佛退轉因未先建立正知見","一行三昧須先聞般若、隨佛方所","從散心念佛到心念心憶的次第","念佛三昧即禪宗明心見性","須具定力、慧力、福德資糧"],"k":["念佛","一行三昧","念佛三昧","動中定","無相憶佛","正知見"]},"2136-a09_089":{"s":"本集說明正確布施。布施分財施、法施、無畏施；應擇福田供養勝義僧、世俗僧，講者主張不應供養其所指落於常見、斷見、邪淫外道的無慚愧僧；引《賢愚經》貧窮夫妻以一錢、明鏡、瓶水供僧得大果報，歸納九種布施果報；末依《金剛經》說不住相布施。","p":["布施有財施、法施、無畏施","僧分四種，應擇福田而施","貧窮夫妻少物施僧得大果報","至心、自手、信心、時節施等果報","不住相布施，三輪體空"],"k":["布施","福田","勝義僧","三輪體空","不住相布施"]},"2116-a09_090":{"s":"本集說明修行要修的是意識與意根。引《大乘入楞伽經》八識及《勝鬘經》自性清淨心而有染污；七轉識皆可滅；以聲聞斷三縛結至四果、菩薩明心見性至成佛為例，說明意識如理思惟、意根作主接受而漸清淨，第八識則非修非不修。","p":["一心八識，如來藏為真心","自性清淨心而有染污，難可了知","意識意根是輪迴與解脫關鍵","意識如理思惟，意根接受而清淨","第八識非修非不修"],"k":["意識","意根","八識論","如來藏","斷我見","修行"]},"2126-a09_091":{"s":"本集回答醫學系學生做動物實驗殺害眾生是否犯殺戒、有無果報。以根本、方便、成已三條件分析，指出明知會致死仍執行則殺業具足，如來藏如實記錄心行，不能以求知為由卸責；建議以電腦模擬替代、縫合傷口，並發露懺悔、為動物念佛迴向。","p":["未受戒不算犯戒，已受戒則有持犯問題","犯戒需根本、方便、成已三條件具足","如來藏記錄一切心行，求人背書無法免責","求知可用圖表、電腦模擬替代，課程應修正","發露懺悔、與校方溝通，並念佛迴向"],"k":["殺戒","殺業","如來藏","根本方便成已","懺悔","念佛迴向"]},"2130-a09_092":{"s":"本集回答曾墮胎、流產者如何消業。指出生起慚愧即是善根，不必一直掛懷；可於十齋日讀誦《地藏菩薩本願經》、在佛前懺悔並迴向；說明菩薩戒是心地戒，闡述三歸依與五戒功德，勸由三歸五戒進受菩薩戒，並批評以咒語、儀軌乃至男女淫慾消災之說。","p":["慚與愧是善法，覺悟過失已是一大步","十齋日讀誦《地藏經》可免未來惡報","於佛前懺悔，以念佛拜佛功德迴向","三歸依應歸依大乘法與勝義菩薩僧","由三歸五戒進受菩薩戒以消除業力"],"k":["墮胎","懺悔","地藏菩薩本願經","三歸依","五戒","菩薩戒"]},"2162-a09_093":{"s":"本集回答學佛後謹言慎行仍陷入是非該如何。指出娑婆眾生根器差別大、意識千變萬化，是非難免；應先靜默、對事不對人、不傳話，讓是非止於己；菩薩以結緣、布施、持戒等方便潛移默化團體、攝受眾生；但佛法的大是大非則寧可得罪人也要說清楚。","p":["娑婆世界是非難免，先反省自身無明","先不說話、不附和，是非到我為止","以結緣、分享淺易佛法建立威德","以布施持戒莊嚴自身，潛移默化團體","佛法的大是大非必須說清楚"],"k":["待人接物","攝受眾生","菩薩行","布施","堪忍","大是大非"]},"2125-a09_094":{"s":"本集回答學佛人為家人切肉燒菜是否犯戒。以六祖惠能隱於獵人隊中處理肉食為例，說明無殺害的根本動機即不同於犯戒，但不宜宰殺活物；又舉四川婦人被迫按豬腳仍念佛迴向而往生的故事，勸勿為葷素鬧家庭革命，應堪忍並以悲心攝受家人。","p":["六祖隱於獵人隊中處理肉食，不算犯戒","無根本動機與方便，與一般犯戒不同","避免宰殺活物，可推辭並念佛迴向","四川婦人按豬腳念佛迴向，終得往生","不必為葷素鬧家庭革命，應發悲心攝受"],"k":["犯戒","殺業","六祖惠能","念佛往生","攝受眷屬","菩薩戒"]},"2153-a09_095":{"s":"本集回答宗教之外有無方式推動環保。指出器世間由共業有情的業力與心識所成，以薛丁格的貓說明心識影響世界、無純然客觀環境；主張從文化倫理著手，以《弟子規》孝悌、謹信、汎愛眾、親仁教育下一代，使心地清淨並相信因果，才是治本的環保。","p":["器世間由共業眾生的業力所成","以薛丁格的貓說明心識影響世界","心清淨則世間清淨，環保應治本","以《弟子規》孝悌之道建立倫理","相信因果、人心和諧才是真正環保"],"k":["器世間","共業","環保","弟子規","孝悌","因果"]},"2082-a09_096":{"s":"本集回答富貴之人為何反而慳吝。說明富貴之因可能只是少次布施，或來自孝養、法施、無畏施，而慳吝習氣亦無始存在，二者不相牴觸；勸勿議論他人心性，應隨喜並起平等見；並舉慳吝長者轉生為狗、廣欽老和尚父親勉強供養等例，說明富貴布施難與三世因果。","p":["富貴之因不只一種，與慳吝習氣不牴觸","孝養父母、法施、無畏施也是富貴之因","勿議論他人富貴，應隨喜並起平等見","富貴無饜足，錢財為五家所共有","不甘願供養雖得富貴，來世仍會慳吝"],"k":["布施","慳吝","因果","平等心","福田","如來藏"]},"2146-a09_097":{"s":"本集回答兒子媳婦不孝時該怎麼辦。分析三因：過去生不孝父母、今生孝道未圓滿、與子媳宿世過節；指出諸行無常皆可改變，應懺悔、對在世或已故父母盡孝（以父母名義布施迴向），並為子媳修福；舉安世高償命故事，勸讀誦《地藏經》、教子女因果並帶家人三歸依。","p":["不孝果報三因：宿世、今生、與子媳過節","誠心懺悔可減緩業種勢力","父母已故仍可以其名義布施迴向盡孝","安世高償命了結宿怨，不介意生死","教子女因果，帶家人歸依三寶"],"k":["孝道","懺悔","因果","迴向","三歸依","地藏經"]},"2081-a09_098":{"s":"本集回答憍陳如前世為歌利王支解忍辱仙人，佛為何最先度他。說明眾生貪瞋與歌利王相差無幾，忍辱仙人以四無量心攝受他，使現場無量眾生發菩提心，故憍陳如是重要緣起；並引《法華經》等說其為大菩薩示現，勸學忍辱、以平等心攝受眾生，另舉娑羅那比丘故事。","p":["眾生貪瞋癡與歌利王相差無幾","忍辱仙人以四無量心攝受，眾人發菩提心","憍陳如是重要緣起，功德不可思議","憍陳如實為接近佛果的大菩薩示現","應學忍辱行，以平等心攝受眾生"],"k":["憍陳如","忍辱仙人","四無量心","菩提心","忍辱","法華經"]},"2129-a09_099":{"s":"本集回答找不到好同修與師長時可否在家獨修。指出獨學易孤陋寡聞，獨修須去除慢心（舉悟達國師為例）、心平等、深信大乘，至少受三歸五戒並趣向菩薩戒、達信不退；以舍利弗退墮為誡，建議向正法教團請書熏習第一義空，並修淨業三福。","p":["獨學而無友，佛法知見易不完整","慢心生起則護法遠離，如悟達國師","須受三歸五戒，趣向菩薩戒與信不退","應熏習第一義空，向正法教團請書","修淨業三福以成就往生淨土因緣"],"k":["在家修行","慢心","三歸五戒","菩薩戒","第一義空","淨業三福"]},"2132-a09_100":{"s":"本集回答學佛者退轉改信他教時該如何。說明信力成就需長劫，退轉常見；舉某宗教台主持人為例，勸學佛人受三歸、五戒、菩薩戒，以行誼莊嚴自身；並指出知識不等於正見，須靠觀行體驗才能斷我見，介紹大乘禪觀從五蘊中的受蘊入手、回顧一生感受作觀察。","p":["信力成就需長劫，退轉是常有的事","以三歸五戒菩薩戒的行誼影響他人","知識不等於正見，需觀行體驗","身見與我見相關，須觀察受想行","大乘禪觀從受蘊入手，記錄一生感受"],"k":["信不退","三歸五戒","菩薩戒","斷我見","五蘊","觀行"]},"2163-a09_101":{"s":"本集回答念佛為何要常常念。指出須先有正確知見與方向，再勤加練習才能淨念相繼、一心不亂；持名只是方便入手，各種語言發音皆是歸命阿彌陀佛，關鍵在心中憶佛之念；引《觀無量壽佛經》下品下生經文，說明只稱名號不等於念佛，並提及可轉進無相念佛。","p":["正確知見與方向是常常念佛的前提","念佛有持名、觀想、無相、實相等層次","不同發音皆歸命阿彌陀佛，重點在心","下品下生者苦逼不能念佛，只能稱名","四威儀中常有憶佛之念才是真念佛"],"k":["念佛法門","持名念佛","淨念相繼","無相念佛","觀無量壽佛經","一心不亂"]},"2127-a09_102":{"s":"本集回答指出古人語錄著作的錯誤，是法義辨正還是誹謗。主張正見與邪見不能並存，引《瑜伽師地論》說相似像法興盛則正法滅沒；說明法義辨正依法理事實、依法不依人，是為救護眾生而非貶抑；善知識引用未悟者文字時會加註；最後引《大寶積經》四依法為抉擇標準。","p":["正見與邪見不能並存，菩薩不鄉愿","相似像法興盛，正法將速滅沒","法義辨正是依法不依人，非貶抑","引用未悟古德文字時會加註防誤會","依四依：依義、依智、依了義、依法"],"k":["法義辨正","四依法","相似像法","依法不依人","邪見","善知識"]},"2192-a09_103":{"s":"本集回答佛弟子如何看待祖先牌位與三魂七魄之說。指出牌位可隨俗保留以攝受眾生，供養與歸依不同；三魂分居三處之說不符法界事實；依八識論與《瑜伽師地論》說明中陰身最多七七四十九日即投生，唯生於鬼道者可能與牌位相關，迴向不需牌位也能收到。","p":["牌位可隨俗保留，供養不同於歸依","三魂七魄說只見於華人地區，不符事實","中陰身最多七七四十九日必定投生","生於鬼道者才可能與牌位相關","靈魂說屬常見外道見，輪迴主體是第八識"],"k":["祖先牌位","三魂七魄","中陰身","八識論","如來藏","迴向"]},"2173-a09_104":{"s":"本集回答燒紙錢能否讓祖先受用、生意發財。指出燒紙錢只是華人地區約定俗成的默契，效果有限、無普遍性；講者推溯其源與事火外道、密宗火供護摩同類；佛法中無此法，應依《地藏經》讀誦迴向，及依《優婆塞戒經》布施有德修行者並咒願迴向，為祖先追福。","p":["燒紙錢是華人地區約定俗成的默契","西方人不燒紙錢，生意照樣興隆","講者認為其源與事火外道、火供同類","依《地藏經》讀誦迴向救拔惡道眷屬","依《優婆塞戒經》布施咒願為祖先追福"],"k":["燒紙錢","追福","迴向","地藏菩薩本願經","優婆塞戒經","鬼道"]},"2174-a09_105":{"s":"本集回答蒙山施食等法會結束後的供品應丟棄或食用。指出食後不適多見於常與鬼神相應者，與作意心性有關；正法道場如法懺悔迴向，供品烹調後大眾平等食用，不屬以殘食供養三寶；引律典與《優婆塞戒經》說蕩滌汁亦可布施，以丟棄想丟棄好食物有損福德。","p":["食後不適多因作意心性與鬼神相應","蒙山施食為攝受冤親債主、解冤釋結","正法道場供品烹調後大眾平等食用","蒙山後供品自用不屬殘食供養三寶","蕩滌汁亦可布施，不應以丟棄想丟棄"],"k":["蒙山施食","供品","布施","冤親債主","優婆塞戒經","懺悔"]},"2066-a09_106":{"s":"本集為《心經》系列首講。講者批評以緣起性空、性空唯名解經者，介紹聲聞、緣覺、佛菩提三乘；指出《心經》宗旨在「心」，有空性心、所生空相、二者非一非異三重點；並解釋觀自在菩薩是證悟明心、現觀真心本自在的菩薩，非專指觀世音菩薩，及照見五蘊皆空、度一切苦厄。","p":["講者批評以緣起性空解《心經》者","三乘菩提：聲聞、緣覺、佛菩提","三重點：空性心、空相、非一非異","觀自在菩薩指證悟明心者，非觀世音","轉依真心無所得而度一切苦厄"],"k":["心經","空性心","觀自在菩薩","三乘菩提","明心","非一非異"]},"2068-a09_107":{"s":"本集講解「色不異空」至「不生不滅、不垢不淨、不增不減」。以《雜阿含經》非我、非異我、不相在印證五陰與空性心非一非異，說明三轉法輪隱說與明說真心，並以《金剛經》為例；指出諸法攝歸空性心故不生不滅，批評以意識、有念或離念靈知為真心及喇嘛教觀想合併真心之說。","p":["五陰與空性心非一非異","《雜阿含》非我非異我不相在與《心經》同","三轉法輪次第隱說、明說空性心","諸法空相攝歸空性心故不生不滅","有念、離念靈知皆是意識，非真心"],"k":["心經","空性心","非一非異","不生不滅","離念靈知","三轉法輪"]},"2067-a09_108":{"s":"本集講解「是故空中無色」至「無意識界」，說明真心實際理地無五陰十八界，是離見聞覺知的極寂靜境界，引《大集經》與黃檗禪師印證；引《央掘魔羅經》說三界唯心之心即如來藏；說明證悟發起法身、般若、解脫三德；並以模擬機為喻，說明一切境界皆如來藏所變現。","p":["真心實際理地無五陰十八界，極寂靜","真心離見聞覺知，靈知心非真心","《央掘魔羅經》：三界唯心之心即如來藏","證悟發起法身、般若、解脫三德","以模擬機喻一切境界皆如來藏所現"],"k":["如來藏","心經","三界唯心","萬法唯識","三德","離見聞覺知"]},"2070-a09_109":{"s":"本集講解「無無明」至「以無所得故，菩提薩埵」。引《金剛三昧經》心王菩薩語說明真心無得無失、離見聞覺知；講者批評應成派中觀六識論具斷常二見；分析聲聞四聖諦、緣覺十二因緣與真心關係，指二乘實未證涅槃；說明有智者是意識、真心無智，並以三輪體空說明轉依無所得。","p":["真心實際理地無十二因緣、四聖諦","《金剛三昧經》：菩提性中無得無失","二乘入無餘涅槃，實無人證涅槃","有智慧的是意識，真心無智","轉依真心無所得才是真正三輪體空"],"k":["心經","無所得","四聖諦","十二因緣","涅槃","三輪體空"]},"2069-a09_110":{"s":"本集講解「依般若波羅蜜多故，心無罣礙」至咒文。依序說明四種涅槃與菩薩五十二階位：七住明心證本來自性清淨涅槃、十迴向位可證有餘與無餘涅槃、佛地證無住處涅槃；解釋咒即總持，以正覺總持咒為例；最後總結《心經》所說之心即一切有情真心。","p":["依真心無智無得修行，心無罣礙","四種涅槃與菩薩五十二階位次第","七住明心證本來自性清淨涅槃","佛地證無住處涅槃，不住生死涅槃","咒即總持，以正覺總持咒為例"],"k":["心經","四種涅槃","無住處涅槃","菩薩階位","般若波羅蜜多咒","總持"]},"2191-a09_111":{"s":"本集回答學佛是否要時時清清楚楚、處處作主。依八識說明：了別六塵的是前六識，真正作主決定的是第七識末那識，二者都屬五陰十八界生滅法；第八識如來藏恆而不審、不作主，證得此心並轉依而隨緣不作主，死後才能真正自己作主。","p":["前六識分別六塵，意識下決心不算數","末那識恆審思量，是真正作主的心","見聞覺知心夜夜斷滅，非真如佛性","如來藏恆而不審、無所了知、無得無失","轉依不作主之心，死後方能隨願作主"],"k":["末那識","如來藏","八識心王","五陰十八界","自己作主"]},"2097-a09_112":{"s":"本集解說三輪體空。先引《優婆塞戒經》說福田有勝劣、「田勝不如施主勝」，再依《金剛經》、《大般若經》說不住相布施；指出以意識離念或緣起思惟行施仍不出五陰，唯有證如來藏、轉依其離見聞覺知，才能現觀施者、受者、施物皆空；未悟前仍應清淨布施積福。","p":["布施福德隨田與施主證量而有差別","《金剛經》說菩薩應不住相布施","執著施者受者施果仍屬世間布施","意識離念靈知布施仍具四相","依如來藏離見聞覺知才是三輪體空"],"k":["三輪體空","布施波羅蜜","如來藏","金剛經","無住相布施","福田"]},"2076-a09_113":{"s":"本集探討六度第五度「禪定」與玄奘所譯「靜慮」的異同。說明眾生因壞劫三災都曾證四禪，但四禪八定屬世間定不能解脫；引六祖、懷讓磨磚作鏡、維摩詰呵舍利弗，指出靜坐非法要；禪是思惟修，靜慮是於法心得決定的寂靜思慮，用以參究如來藏，故譯為靜慮更恰當。","p":["壞劫火水風三災迫使眾生次第證四禪","打坐求一念不生是障道因緣","禪即思惟修，定是制心一處","靜慮是不緣外境而參究實相","四禪八定依次第於三地修證"],"k":["靜慮","禪定波羅蜜","四禪八定","六度","禪宗","如來藏"]},"2099-a09_114":{"s":"本集依《阿彌陀經》所列五濁逐一說明：劫濁指饑饉、疾疫、刀兵三劫，見濁源於身見等五利使，煩惱濁為其餘根本與隨煩惱，眾生濁在執著行陰，命濁為壽命短促、被命根繫縛。並指出見濁與煩惱濁為因、其餘三濁為果，學佛應先斷除惡見我見。","p":["濁如塵土入清水，指五種遮障重疊","劫濁：饑饉、疾疫、刀兵三劫","見濁源於五利使，以我見為根本","眾生濁在執著行陰，命濁為壽短","見濁煩惱濁為因，餘三濁為果"],"k":["五濁","五利使","我見","煩惱濁","阿彌陀經"]},"2098-a09_115":{"s":"本集解說迴向偈中的「三障」：煩惱障即見惑思惑、四住地煩惱；業障是五無間等重惡業障礙修道；報障是惡業所感三惡道、無佛處或諸根缺陷的異熟果。引《佛說佛名經》說三者相由，又依《菩薩地持經》說諸根、善根、智慧成熟可解脫三障，首要在斷我見。","p":["煩惱障即四住地煩惱、見惑思惑","業障指五無間等重惡業障道","報障即異熟障，如生無佛處、根鈍","煩惱起惡業、惡業感苦果，三障相由","消三障應從煩惱障下手，先斷我見"],"k":["三障","煩惱障","業障","報障","四住地煩惱","斷我見"]},"2074-a09_116":{"s":"本集解釋祖師語「生則決定生，去則實不去」。從事相說，具足信願行、不謗正法者念佛必得往生，五逆者臨終十念亦可下品下生；從理上說，往生的是中陰身與新五陰，前後五陰非一，七、八識亦無來去，故說實不去；但前後五陰相續、同一如來藏，事理兼說才圓滿。","p":["釋迦佛憐憫五濁眾生而說念佛往生","具足信願行念佛必定往生極樂","五逆者臨終十念亦可下品下生","乘臺往生的是中陰身，前後五陰非一","如來藏無來去，前後五陰相續而生"],"k":["淨土法門","往生極樂","信願行","中陰身","如來藏","五陰"]},"2145-a09_117":{"s":"本集討論如何自在學佛。講者指出以五欲滿足或覺知心常存為自在，仍不出三界；佛法的自在是本來就在、不可壞滅、不受五受，唯第八識如來藏具此體性。引《心經》說證此心而照見五蘊皆空即得安隱自在；事修上不自在源於無明，關鍵在建立正知見，於煩惱得自在。","p":["世俗自在多依五欲與外在條件","覺知心不滅即仍住三界，非解脫","自在三義：本來在、不可壞、不受五受","證如來藏照見五蘊皆空即觀自在","學佛能否自在，關鍵在知見正確"],"k":["自在","如來藏","心經","正知見","安隱觀","無明"]},"2171-a09_118":{"s":"本集辨析日本法然、親鸞所倡本願念佛（淨土真宗）。介紹其以第十八願為唯一真實本願、絕對他力、惡人正機、排斥聖道門等主張，及戰國時代一向宗暴動；講者依《無量壽經》三輩、《觀經》九品，指出往生仍須修功德、長劫次第修行，批評其排斥聖道門並省略「唯除五逆誹謗正法」為不如法之見。","p":["法然主張稱名念佛為彌陀本願","親鸞立淨土真宗，倡絕對他力、惡人正機","判第十九、二十願為方便，排斥聖道門","經說三輩九品，上中輩須修諸功德","講者評其斷章取義，非如實正見"],"k":["本願念佛","淨土真宗","淨土法門","聖道門","四十八願","三輩九品"]},"2172-a09_119":{"s":"本集回答吃植物是否殺生。依經論界定有情眾生為六道輪迴、有心識與記憶好惡者，須有第八識如來藏；植物的向光、向地性是物性，屬共業有情如來藏種子所變現的無情生，故食植物非殺生。並說「有情無情同圓種智」是方便說，實指有情成佛時相應的一分器世間隨之。","p":["佛教戒殺的對象是有情眾生","有情須有心識與如來藏，有記憶好惡","植物向光等是物性，屬無情生","植物由共業如來藏變現，食之非殺","「有情無情同圓種智」為方便說"],"k":["有情","無情","殺戒","如來藏","共業","器世間"]},"2148-a09_120":{"s":"本集回答在家學佛人如何面對婚姻。說明學佛目標在成佛，須攝受眾生以成就佛土；引《善巧方便經》光明婆羅門以大悲娶伽吒的本生、《善生子經》夫婦相待之道與邪淫過患、《法句譬喻經》貪欲害身之例；勸夫妻轉情緣為道緣，依《華嚴經》在家菩薩隨緣盡分並攝受配偶學佛。","p":["學佛為成佛，攝受眾生即攝受佛土","光明婆羅門以大悲心娶伽吒的本生","夫婦應互敬互助，不可邪淫","貪欲為三毒，夫妻不應以貪愛為重","將一世情緣轉為無量世道緣"],"k":["婚姻","攝受眾生","邪淫戒","大悲心","在家菩薩","貪欲"]},"2083-a09_121":{"s":"本集回答人死後去向、是否仍為人。比較外道五通、阿羅漢三明六通與佛十力知生死去來的差別，以佛觀螞蟻及輸迦長者愛犬為其父轉生為例，依《分別善惡報應經》說明造業輕重分得地獄、畜生、餓鬼、人天之報。善惡業種存於如來藏而隨業受生，不一定再得人身，應至少持五戒。","p":["「未知死，焉知生」才是究竟之理","神通高下：外道五通、阿羅漢、佛十力","輸迦長者之狗為其父轉生","依業輕重分生地獄、畜生、餓鬼、人天","業種存如來藏，持五戒方能再得人身"],"k":["六道輪迴","善惡業報","如來藏","神通","五戒","十善業"]},"2167-a09_122":{"s":"本集依《瑜伽師地論》說明投生過程：如來藏離身時出生中陰身，形像為將往生之道的樣子，壽最多七日、至多七次，以香為食；極重罪者及生無色界者無中陰；入胎後由如來藏與末那識住受精卵。講者並批評《西藏度亡經》、《西藏生死書》的中陰說違背經論，死後靠讀誦得解脫不實際。","p":["無明業種使眾生不斷受生","中陰形像依所往生之道，至多七七日","中陰身又名尋香，以香氣為食","入胎後如來藏與末那識住受精卵","講者批評《度亡經》中陰說違背經論"],"k":["中陰身","投生","入胎","如來藏","瑜伽師地論","西藏度亡經"]},"2156-a09_123":{"s":"本集回答複製人有無靈性。講者認為科學以唯物觀尋找生命本源方向錯誤；引《雜阿含》識緣名色、《中阿含・大因經》說明須有入胎識如來藏執持，受精卵才能成長。複製人也有自己的如來藏與八識，如同先後出生的雙胞胎，是獨立有情，應平等看待；複製成功率低與無相應有情入胎有關。","p":["生命本源是心識，非物質","識緣名色，須入胎識執持胚胎","複製人有自己如來藏，是獨立有情","複製人與被複製人如先後出生的雙胞胎","物化複製人而造惡，將受惡報"],"k":["複製人","如來藏","入胎識","名色","唯物論","有情"]},"2077-a09_124":{"s":"本集解說「一念萬年，萬年一念」。講者指出把它理解為意識長時一念不生是外道禪定修法；真義是第八識如來藏無始以來不與六塵相應、從不起念。引《占察善惡業報經》一實境界與圓悟禪師語錄，說明此為證悟如來藏後七住不退菩薩的現觀；並引大慧、真淨文禪師呵斥以定為禪。","p":["意識長時不起念是外道禪定修法","如來藏從不與六塵相應、不起一念","依止一實境界修信解入菩薩種性","圓悟禪師以此句指證悟後的現觀","大慧引真淨文呵「古廟香爐」式修法"],"k":["如來藏","一實境界","明心","禪宗","七住位","以定為禪"]},"2140-a09_125":{"s":"本集說明如何從內心深處信佛。信是善心所，深信須過去供養諸佛、熏習正法、累積善根福德，並修滿十信位；介紹世尊先說施論、戒論、生天之論，再說四聖諦的教化次第。講者批評為求世間利益而拜佛者非清淨信，並依《大乘起信論》指出須先信根本真如如來藏。","p":["信為道元功德母，不信為隨煩惱","深信須善根福德，修滿十信位","佛次第說施論、戒論、生天論、四聖諦","為求世間欲樂而拜佛非清淨信","《起信論》以信真如根本為首"],"k":["信心","十信位","三寶","大乘起信論","如來藏","善根福德"]},"2086-a09_126":{"s":"本集辨別伏煩惱與斷煩惱。只壓制妄念如石壓草，《起信論》說此仍是不覺；以神秀與惠能偈、臥輪與六祖偈為例，說明須證真心如來藏才能斷煩惱。介紹五停心觀、念佛觀、無相觀等對治法，並推介正覺同修會無相憶佛拜佛以修動中定，再加正知見與四加行，方能明心而漸斷煩惱。","p":["壓伏煩惱如石壓草，遇境仍會生起","神秀、臥輪偈落在意識上用心","證得如來藏本覺才是始覺","五停心觀等為對治煩惱的方便","無相憶佛拜佛培養動中定"],"k":["伏煩惱","斷煩惱","如來藏","五停心觀","無相念佛","大乘起信論"]},"2131-a09_127":{"s":"本集回答如何不受五欲六塵障礙而專心學佛。講者認為只教人「放下」或硬壓煩惱不得要領，關鍵在認清六塵虛妄：所觸皆如來藏變現的內相分，如坐戰車以潛望鏡看外；並引腦科學、《金剛經》、《華嚴經》、《大智度論》及夢喻說明。根本在斷我見等三縛結、證初果，漸離五欲貪愛。","p":["五欲指對五塵的貪著，加法塵為六塵","只教放下、壓伏煩惱收效有限","所觸皆如來藏變現的內相分","五欲無實如夢，世人貪著至死不捨","斷我見等三縛結、證初果為首要"],"k":["五欲六塵","內相分","如來藏","斷我見","三縛結","初果"]},"2141-a09_128":{"s":"本集說明如何遠離嫉妒。嫉妒屬瞋的一分、為小隨煩惱，也是十不善業之一；以大房因嫉墮二房胎而成食子鬼母的故事示其過患。引帝釋問佛，說嫉妒源於愛憎、欲念、覺觀、無明，須斷我見證初果才能根除；又依《中阿含》說依本無憎嫉的如來藏斷除憎嫉。講者批評「我與人一體」之說，主張隨喜讚歎。","p":["嫉妒是瞋的一分，屬小隨煩惱","鬼母因嫉墮胎發毒誓，自食其子","嫉妒源自愛憎、欲念、覺觀、無明","斷我見證初果才能根除嫉妒","依如來藏無憎嫉體性，並隨喜他人"],"k":["嫉妒","隨煩惱","斷我見","初果","如來藏","隨喜"]},"2120-a09_129":{"s":"本集回答淨土法門是否第一法門。講者指出唯一佛乘依如來藏，如來藏即唯心淨土、真實淨土，廣義而言一切法門皆淨土法門；並解《阿彌陀經》「一切諸佛所護念經」隱指如來藏。比較兩土：極樂一日為娑婆一劫，娑婆為善一日勝極樂百歲，下品下生須住蓮花十二大劫，故勇猛菩薩留娑婆護法。","p":["唯一佛乘以如來藏為根本","唯心淨土是根本，諸佛化土依之而有","經中「是經」「此經」隱說如來藏","娑婆為善一日勝極樂為善百歲","下品下生須住蓮花十二大劫"],"k":["淨土法門","唯心淨土","如來藏","阿彌陀經","極樂世界","娑婆世界"]},"2151-a09_130":{"s":"本集回答修行能否消除宿業、出家人何以死於非命。引經說業依果報與受報時間定或不定分四類，以五種心境造業則成定業；依正法修行可重報輕受、輕報不受。以安世高兩世主動償命債、玄奘臨終小病消盡往業為例，並說念佛、懺悔、隨喜迴向、忍辱等皆能消業。","p":["菩薩畏因，業種存阿賴耶識不失","業分四類，五種心境造業成定業","依正法修行可重報輕受、輕報不受","安世高主動償還兩世命債","護持正法、懺悔、念佛可消宿業"],"k":["宿業","因果","定業","重報輕受","阿賴耶識","懺悔"]},"2455-a11_001":{"s":"本集回答「做人為何要學佛」：以羅盤、保險為喻，說明學佛能讓人面對生死與眷屬離散時得到究竟利益；並指出生天福盡仍墮惡道、三界無安，世間所謂好人心地仍不平整，應追求解脫與涅槃。最後介紹六齋日、十齋日的歷史，說明在家人也可學習吃素。","p":["學佛如航海羅盤，是最究竟的「保險」","天人福盡多墮惡道，三界無安","主張天主創造是不平等因，佛法說一切平等","自認好人仍有煩惱纏縛，需智慧知見","六齋日、十齋日的歷史與吃素傳統"],"k":["學佛目的","三界無安","生死解脫","六齋日","如來藏","吃素"]},"2437-a11_002":{"s":"本集說明佛教與其他宗教的差異：佛陀親自示現說法、正遍知，其他宗教須靠代言人。講者質疑創造主說在生人、教養、救濟三方面不合理，引梵天被佛問倒之例，說明一切有情由自身如來藏出生、無真實創造主；並述佛為無上正等正覺、眾生皆可成佛，佛本不入涅槃，二乘涅槃非究竟。","p":["佛陀親身說法、正遍知，他教須靠代言人","從三點質疑創造主說不如理","有情由自身如來藏所生，無創造主","眾生皆可成佛，非臣服於教主","佛地無垢識，佛本不入涅槃"],"k":["佛教與宗教","創造主","如來藏","無上正等正覺","無垢識","涅槃"]},"2439-a11_003":{"s":"本集比較佛教淨土與基督宗教的天堂：天堂屬欲界天，靠十善生天，福盡仍墮三惡道，且劫火時都會敗壞。講者也提及耶穌青年時曾赴印度接觸佛法的推測。相對地，極樂世界由阿彌陀佛願力成就，往生者無量壽、不退轉、一生補處；並引《華嚴經》普賢十大願王及袁宏道兄弟事例，勸人持戒、往生淨土。","p":["天堂屬天界，福報享盡仍墮惡道","推測耶穌青年時曾到印度接觸佛法","極樂淨土依彌陀願力，超越三界天","惡人臨終念佛亦可往生，蓮苞中聞法","普賢十大願王導引上品往生，須持戒"],"k":["極樂世界","天堂","阿彌陀佛","普賢十大願王","往生淨土","持戒"]},"2507-a11_004":{"s":"本集討論科學能否解釋佛法：引《恆水經》說世間法皆攝於佛法，五地菩薩須學一切世間明。講者舉隨機器實驗、預錄錄音帶受觀察者影響、粒子對稱偏轉、光的波粒二象性、水的記憶等，說明科學無法解釋心識的作用，主張這些都由如來藏出生萬法所致，並以第七識、業鏡解釋預感與臨死現象。","p":["佛法包含世間法，菩薩須學五明","心識能影響隨機機器與預錄錄音帶","粒子對稱偏轉、光波粒二象性難以解釋","水的記憶歸於如來藏的大種性自性","心電感應、業鏡由第七、八識解釋"],"k":["科學與佛法","如來藏","心識","五明","第七識","四大種"]},"2458-a11_005":{"s":"本集探討善惡標準與「善因得惡果」：以共業、宿世業因說明好人遭惡報只是過去業報成熟；殺人的業因輕重依心所與文化而不同，並舉菩薩殺商人救眾的本生事例。講者主張業種由如來藏執持記錄，駁斥由天人或天主記錄之說；三歸五戒是善惡標準，誹謗第一義諦為大惡，受戒懺悔可使業種清淨。","p":["好人遭惡報乃共業或宿世業成熟","業的輕重依善惡心所與教化而異","業種由如來藏記錄，非天主或天人","誹謗大乘如來藏法是首要惡業","受三歸五戒與懺悔，善因得菩提果"],"k":["因果業報","共業","如來藏","三歸五戒","懺悔","第一義諦"]},"2436-a11_006":{"s":"本集說明佛法是可實證的義學，不是哲學思想：佛陀親證後說法，有事有義、有實踐的標的，僅作理論臆想則是戲論。講者以聲聞四果的修證、二乘人發菩提心的劫數說明佛法有真實目標，主張小乘涅槃依如來藏才不成斷滅；並說明阿難誦出阿含、增壹阿含留有大乘法，以及上座部與大眾部的結集。","p":["佛法是親證的義學，臆想理論為戲論","三歸五戒與聲聞四果皆有實踐標的","二乘人須經多劫方發菩提心","小乘涅槃唯剩如來藏，非斷滅","阿難誦出阿含，經中仍留大乘法"],"k":["義學","實證","聲聞四果","阿含經","如來藏","結集"]},"2482-a11_007":{"s":"本集辨析「情與無情同圓種智」：無情沒有心識，不可能生起智慧而成佛；只有具八識的有情能證一切種智。講者以讀小說時浮現意象、心電感應等說明意識與第七識的功能，解釋生公說法頑石點頭是護法神與如來藏的力量；並批評不空所傳密續的魂魄成佛、草木成佛及密教月輪觀、即身成佛之說。","p":["無情無心識，不能成佛得種智","有情具八識，如來藏為第八識","頑石點頭源於菩薩威德與護法","批評密續魂魄、草木成佛之說","菩提心無形相，須三大阿僧祇劫成就"],"k":["情與無情","一切種智","八識","如來藏","即身成佛","密教"]},"2463-a11_008":{"s":"本集說明如何實修佛法：要親近真善知識、歸依三寶、受五戒乃至菩薩戒，並與大乘如來藏法相應。講者批評喇嘛教以「淫欲真如」為名行雙身法、飲酒吃肉、自稱法王、先禮上師後禮佛、護摩供養等；並說明真正灌頂是十地菩薩的放光境界，以及應遠離執覺知心為真心的常見與洩漏公案密意的人。","p":["親近善知識、受三歸五戒與菩薩戒","批評雙身法藉淫欲說真如","淫欲是生死法，以吸毒成癮為喻","真灌頂為入十地菩薩放光的境界","遠離常見、斷見與自稱解公案者"],"k":["實修","善知識","菩薩戒","雙身法","灌頂","常見"]},"2473-a11_017":{"s":"本集區分「學佛」與「佛學」：學佛是依五十二階位修聞思修證、親證實相以至成佛；佛學則是把經論當學問研究，不必實修實證。講者舉學術研究者否定他方淨土與天界佛教、否定七八識為例，並引阿含「識緣名色」「齊識而還」等說明本識存在，主張學術研究屬學佛的岔路，誤信六識論與雙身法則是危途。","p":["學佛須經五十二階位、親證成佛","佛學是學術研究，可無實修實證","否定他方淨土導致念佛唐捐","阿含已說入胎本識，第八識真實存在","學佛嶮路有瓶頸、岔路、危途"],"k":["學佛與佛學","學術研究","第八識","淨土","五十二階位","六識論"]},"2505-a11_018":{"s":"本集說明禪宗是什麼及如何修：禪宗的禪是「靜慮」，目的在參究第八識如來藏，不是四禪八定。講者引《解深密經》六度次第，舉九峯道虔斥首座坐脫立亡仍未會石霜法意的公案；說明禪宗三關（明心、見性、牢關），及正覺以無相念佛、看話頭為次第，並強調以分別的覺知心找到無分別的如來藏。","p":["禪是靜慮，非四禪八定","六度次第：禪那為發起般若慧","九峯公案：坐脫立亡不等於開悟","禪宗三關：明心、見性、牢關","以覺知心找無分別的如來藏"],"k":["禪宗","靜慮","明心見性","如來藏","六波羅蜜","參禪"]},"2504-a11_019":{"s":"本集回答禪淨雙修能否成立：參禪須有定力而不入定境，無相念佛「淨念相繼」可練成動中定，再轉看話頭參禪。講者說明極樂九品往生的差別，指出明心見性者可上品上生、速證初地乃至八地；淨土行人應從持名、憶佛進到體究念佛、實相念佛。引雲棲祩宏、永明延壽四料簡，主張禪淨雙修可以成立。","p":["參禪要定力，不落定境、不著定相","無相念佛淨念相繼即動中功夫","九品往生品位依願力與見道自力","體究念佛即參禪，可得實相念佛","引蓮池大師與永明四料簡證可雙修"],"k":["禪淨雙修","無相念佛","九品往生","實相念佛","看話頭","極樂世界"]},"2408-a11_020":{"s":"本集說明學佛為何要親近善知識：引《法華經》《心地觀經》等，指出值遇真善知識最難，修學四法以親近善友為第一。講者舉念佛停在持名、文人知解公案如鋸秤砣為例；引《瓔珞經》說悟後無善知識攝護會退轉；並說明真善知識的條件在於有正知見與實證、持戒清淨、行四攝，而不看道場大小或出家在家相。","p":["菩提果不難成，真善知識難遇","修學四法：親近善友為第一","知解公案如鋸秤砣，落入意識","悟後無善知識攝護易退轉","真善知識重實證與戒行，非表相"],"k":["善知識","正知見","退轉","念佛","公案","菩薩戒"]},"2435-a11_021":{"s":"本集解釋生忍、法忍與無生法忍：依《大智度論》，生忍是對眾生加惡或恭敬心不動，法忍是對甚深法心無罣礙，並引《佛藏經》說信解無名相法極為稀有。講者述龍樹修二忍的方法，區分二乘以滅止生的無生忍與大乘證如來藏本來無生的無生忍；無生法忍則是初地以上菩薩修道種智所證。","p":["忍兼忍耐與安住於法實相","生忍：八風吹不動，對眾生不瞋","法忍：對甚深無名相法能信受安住","二乘將滅止生，大乘忍如來藏無生","無生法忍唯諸地菩薩能證"],"k":["無生法忍","生忍","法忍","忍辱波羅蜜","如來藏","大智度論"]},"2496-a11_022":{"s":"本集說明什麼是直心及如何在生活中行直心：事相上直心是不諂、不曲、不虛誑，依《大寶積經》應遠離四種曲心、修四種直心相，講者並批評網路匿名毀謗正法者屬曲心。理體上依《維摩詰經》「直心是道場」，直心即永不虛假的如來藏，一切修行都在其中，悟後應轉依其質直體性。","p":["直心即不諂、不曲、不虛誑","四曲心：疑悔、憍慢、嫉妒、訶罵菩薩","四直心相：發露、不妄語、不瞋、信力","直心是道場：真如心如來藏","悟後轉依如來藏質直體性"],"k":["直心","如來藏","道場","大寶積經","維摩詰經","懺悔"]},"2429-a11_023":{"s":"本集解釋無緣大慈與同體大悲：佛教不說愛而說慈悲，因愛是集諦、能生後有。慈悲分生緣、法緣、無緣三種：生緣慈緣眾生苦而起，法緣慈須入地證法空，無緣大慈唯佛圓滿種智才能任運而起。講者引《觀無量壽佛經》說親證如來藏後見一切法平等，生起同體大悲，如來藏是其根本所依。","p":["愛是集諦與能生支，佛教改說慈悲","生緣慈：緣眾生苦而與樂拔苦","法緣慈：入地證法空而起","無緣大慈唯佛任運，不待因緣","同體大悲依如來藏一切法平等性"],"k":["無緣大慈","同體大悲","慈悲","如來藏","一切法平等性","十二因緣"]},"2407-a11_024":{"s":"本集解釋六祖「佛法在世間，不離世間覺」：覺即菩提，菩提涅槃都是如來藏妙心的異名。講者引《法集經》說離世間性見涅槃者不知空性，引《起信論》說本覺即離念的如來藏，須以有念的覺知心去證；並說明始覺、隨分覺到究竟覺都不離五蘊世間，菩薩應在煩惱境緣中修行，如火中生紅蓮。","p":["覺即菩提，菩提涅槃皆如來藏","離蘊處界另求涅槃即不知空性","以有念覺知心證離念本覺如來藏","始覺、隨分覺、究竟覺不離世間","在煩惱境緣中修，如火中紅蓮"],"k":["本覺","菩提","如來藏","六祖壇經","涅槃","煩惱即菩提"]},"2450-a11_025":{"s":"本集說明佛與阿羅漢的差別：講者指部分學者因佛號含「應供」而視阿羅漢等同佛，是把包含誤當等號，並以里長與總統同為公民為喻。阿羅漢經四果斷見思惑、出三界分段生死，分慧解脫與俱解脫；佛須經三大阿僧祇劫、五十二階位，福慧圓滿、具十力十八不共法等，故佛可稱阿羅漢，阿羅漢不是佛。","p":["阿羅漢義：應供、殺賊、無生","四果次第：三縛結至五上分結","慧解脫與俱解脫阿羅漢的差別","佛須三大阿僧祇劫、五十二階位","包含非等號：佛是阿羅漢，反之不成"],"k":["阿羅漢","佛","解脫道","佛菩提道","四果","應供"]},"2484-a11_026":{"s":"本集（上）探討抓周是否合乎邏輯：講者認為抓周是以前世習氣判斷幼兒性向，前提是有前世。以國中、高中、大學比喻前世、今世、來世，說明失去記憶後，畫畫、鋼琴、語文等技能與布施、持戒、慳貪、瞋恚等善惡習氣仍會延續；最後指出執持習氣種子的根本因是如來藏，不是會斷滅的意識。","p":["抓周藉小孩所抓之物判斷性向","三世因果：前世與來世皆無量","技能天分來自前世熏習","善惡習氣會延續到後世","如來藏執持習氣種子，非意識"],"k":["抓周","三世因果","習氣","如來藏","前世"]},"2485-a11_027":{"s":"本集延續「抓周是否合乎邏輯」，以國中、高中、大學比喻前世、今世、來世，說明技藝、善惡習性與人際親疏都是往世習氣在如來藏中遇緣現起，故抓周有其道理。並說明中陰身入胎、意識斷滅而失去記憶，唯第八識能貫通三世、執持業種與習氣。","p":["習氣由前世帶到今世，需大打擊或善緣方能改變","修行即修正身口意行，使如來藏種子漸清淨","見人特別親切或討厭，源於往世熏習","修行要有長遠心，廣結善緣、累積福德","中陰身入胎時意識斷滅，唯如來藏貫通三世"],"k":["三世因果","如來藏","習氣種子","中陰身","長遠心"]},"2474-a11_028":{"s":"本集回答「學佛為什麼要持戒」，先以交通規則比喻說明不受戒者犯惡仍有性罪，再依《毘尼心》說明佛隨犯制戒，並依《優婆塞戒經》解釋戒有制、迮隘、清涼、上、學五義。接著介紹在家與出家各種戒，指出學佛所持以菩薩戒為主，並以「有犯名菩薩，無犯名外道」說明受戒功德。","p":["未受戒造惡雖無戒罪，仍有性罪與果報","佛成道十二年後隨犯廣制戒律","戒有制、迮隘、清涼、上、學五義","在家與出家戒種類，學佛持戒以菩薩戒為主","受戒而犯勝於不受不犯，對眾生成就無畏施"],"k":["菩薩戒","持戒","性罪與戒罪","優婆塞戒經","三聚淨戒","無畏施"]},"2475-a11_029":{"s":"本集續談持戒，以《別譯雜阿含經》爪上土與大地土之喻，說明受戒後縱犯而不捨戒、懺悔並保持慈悲喜捨，功德遠大於罪。強調輕垢罪皆可通懺悔，只要不犯十重戒；並比較菩薩戒戒心、通三世與聲聞戒防身口、因地制宜之差異，最後以斷崖旁彈性圍牆比喻菩薩戒的保護。","p":["爪上土與大地土喻：犯戒不捨戒功德如大地","輕垢罪皆通懺悔，不犯十重戒即可","佛滅度後以戒為師，如暗遇明","菩薩戒兼具防非止過與積極行善，重在戒心","聲聞戒因地制宜，菩薩戒通三世為千佛大戒"],"k":["菩薩戒","聲聞戒","通懺悔","十重四十八輕戒","以戒為師"]},"2478-a11_030":{"s":"本集說明精進的定義為「心不放逸」，凡增身命財、五欲貪、我慢瞋者皆屬放逸。以《百喻經》六枚半餅、三重樓喻強調按部就班與次法的重要；區分邪精進與世間、出世間正精進，並引《地藏十輪經》與《優婆塞戒經》說明正精進、三種勤行精進，以及精進令善法增長的法益。","p":["真正精進是心不放逸，真苦行亦是心不放逸","六枚半餅與三重樓喻：修行須按部就班","受邪師誤導而勤修屬邪精進，增長無明","出世間正精進從理上說唯如來藏能作到","自為法、為他法、為菩提三種勤行精進"],"k":["精進","不放逸","次法","百喻經","優婆塞戒經","六波羅蜜"]},"2479-a11_031":{"s":"本集續講精進的法益：成就不放逸力可勝魔五力、果報至疾（伎兒乞牛喻）、諸天助益（鸚鵡滅火本生）。再以《雜阿含經》二十億耳彈琴說明精進須不急不緩，並提醒要善觀眷屬與環境因緣、愛惜色身；明心僅是七住位，悟後仍須安忍不退、修別相智與一切種智才是真精進。","p":["不放逸力可勝魔的色聲香味觸五力","伎兒乞牛喻：精勤者不覺劫數久遠","鸚鵡滅火感諸天助益，受持五戒亦重要","二十億耳彈琴：精進太急掉悔，太緩懈怠","悟後不得少為足，續修別相智與一切種智"],"k":["精進","不放逸","勝魔","二十億耳","明心","一切種智"]},"2470-a11_032":{"s":"本集探討如何真正放下，先說放下是因已有所提起，再分持重物的放下、對我所與五蘊我的放下，及二乘與大乘的放下。講者批評「一切不執著即可開悟」的說法，指出覺知心是識蘊所攝、須證知其虛妄才是斷我見；證悟者轉依本無提起放下的如來藏，歷緣對境才是真正放下。","p":["之所以要放下，是因為已有所提起","對我所的放下多從無常角度勸勉","二乘以四聖諦、因緣觀斷我見我執而出離","覺知心不執著仍屬我見，須證知其虛妄","轉依如來藏、歷緣對境，方為真正放下"],"k":["放下","我所","斷我見","如來藏","覺知心","我執"]},"2399-a11_033":{"s":"本集探討「學佛越久離佛越遠」，指出主因是學佛方向錯誤，正確方向應以正見為導，發起聞思修證四慧，實證解脫道與佛菩提道。並舉某山頭信徒曹先生學佛二十五年後因事業不順改信基督教為例，講者批評其所學僅是求保佑的相似佛法，並辨析佛法不等於求平安、宗教目的並非都相同。","p":["學佛越久離佛越遠主因是方向錯誤","正確方向：以正見為導，發起聞思修證慧","曹先生學佛二十五年改信基督教之例","佛法不只求富有平安，施戒生天是前方便","宗者佛語心為宗，佛教求解脫與成佛"],"k":["學佛方向","正見","相似佛法","解脫道","佛菩提道"]},"2401-a11_034":{"s":"本集續談學佛越久離佛越遠，逐一辨析對佛法的錯誤認知：感應能力、解厄改運、老莊玄學、儒學、經懺超度、吃素、念佛持咒、打坐、早晚課、做義工環保、學術研究，以及離如來藏單說緣起性空。講者指出這些或屬外道法、世間善法，或僅是助道法，並非佛法本身。","p":["命運由如來藏中的別業共業種子決定","老莊屬自然外道，儒學僅是人天善法","經懺、念佛持咒、打坐、誦經只是助道法","做義工做到歡喜並非初地歡喜地","離如來藏單說緣起性空並非完整佛法"],"k":["佛法正知見","助道法","相似佛法","緣起性空","如來藏"]},"2400-a11_035":{"s":"本集歸納前述錯誤認知後，說明學佛是學成佛之道，佛法含解脫道與佛菩提道，解脫道為佛菩提道所含攝；須證如來藏、具般若總相智、別相智與一切種智才能成佛，阿羅漢並非佛。講者批評曹先生所依道場以世間法及否定如來藏的邪見取代正法，並引十因緣「識緣名色」等說明阿含已說如來藏，勸人護持前先辨道場法義。","p":["學佛是學成佛之道，解脫道為佛菩提道所攝","二乘涅槃是滅盡五陰十八界後如來藏獨處","阿羅漢未成佛，世無二佛","阿含以入胎識、本際說如來藏，識緣名色","護持道場前應先辨其法是否正確"],"k":["佛菩提道","解脫道","如來藏","一切種智","十因緣","惡取空"]},"2402-a11_036":{"s":"本集總結曹先生之例，講者批評其所依道場將佛法世俗化、常見化，並質疑大道場追求建寺與資財。講者並從佛法立場評論一神教的上帝創世說，認為世間由眾生共業所成，曹先生房屋售出是往世福業成熟。最後強調大乘入道須斷我見、求證悟明心，莫隨惡知識，方不致學佛越久離佛越遠。","p":["道場教人追求世俗利益，致信徒退失信心","質疑道場金碧輝煌、廣聚資財的作法","世間由眾生共業形成，非上帝所造","所謂感應實為往世福業因緣成熟","大乘入道以證悟明心為首要，莫隨惡知識"],"k":["學佛方向","因果","共業","證悟明心","惡知識"]},"2443-a11_037":{"s":"本集回答佛與眾生有無差別，答案是「非有差別、非無差別」。非無差別：第八識依所含藏種子不同，分為阿賴耶識、異熟識、無垢識，凡夫、等覺與佛差別甚大；非有差別：一切眾生第八識同具本來自性清淨涅槃性，並以此解釋「心佛眾生三無差別」「天上天下唯我獨尊」及《大般若經》「上從諸佛下至傍生平等平等」。","p":["佛與眾生非有差別、非無差別","第八識分阿賴耶識、異熟識、無垢識三階段","差別在所含藏業種與習氣種子不同","唯我獨尊之我指眾生本具的如來藏","江河之水同具水性而雜質不同為喻"],"k":["眾生平等","如來藏","阿賴耶識","異熟識","無垢識","心佛眾生三無差別"]},"2444-a11_038":{"s":"本集續講佛與眾生有無差別，引「如來清淨藏，世間阿賴耶，如金與指環，輾轉無差別」，以黃金與指環、金礦冶煉為喻：心體無差別，但所含藏種子與顯發功德有別，開悟只是找到金礦，須歷五十二位階淨除種子。並說明種子能變異才能轉凡成聖，佛教講起跑點平等而非齊頭式平等。","p":["金與指環喻：本體無異而相貌功用不同","開悟如找到金礦，仍須冶煉淨除雜染種子","如來藏改其名不改其體，至佛地為無垢識","種子可變異，眾生才能淨除業種轉進","佛教講起跑點平等，如來藏平等酬償業果"],"k":["眾生平等","如來藏","阿賴耶識","無垢識","金與指環","因果"]},"2491-a11_039":{"s":"本集說明一般開經偈為武則天在實叉難陀譯成《八十華嚴》時所作，表達對佛法的仰慕；正覺版本改為「微妙甚深無上法…我今見聞得證悟，願解如來究竟義」。講者解釋無上法即一真法界如來藏，須先證悟才能悟後起修觀其微妙甚深，並引《華嚴經》「我當安住無上法」說明菩薩以利他為先的四宏誓願次第。","p":["讚偈依作者證量有深淺，但皆應隨喜","通行開經偈為武則天讚《八十華嚴》所作","無上法即一真法界、第八識如來藏","證無上法後方能觀其甚深微妙直至成佛","四宏誓願以眾生無邊誓願度為先"],"k":["開經偈","華嚴經","無上法","一真法界","四宏誓願","如來藏"]},"2492-a11_040":{"s":"本集續說正覺開經偈的改動：證悟無上法是外門與內門修行的分水嶺，即「不二門」；「值遇」指遇殊勝難得之法較「遭遇」妥切；如來藏為出生般若之佛母。須先證悟才能真正受持，故改「受持」為「證悟」；證悟只解真實義，至佛地才解究竟義。講者認為此改動提升原偈層次，正是佛菩提道修證次第的縮影。","p":["證悟無上法是外門內門修行的分水嶺","方便有多門，歸元無二路","值遇表殊勝難得，如來藏為般若之佛母","須先證悟找到法體，才能真正受持","證悟解真實義，至佛地方解究竟義"],"k":["開經偈","無上法","不二門","證悟","佛母","佛菩提道"]},"2468-a11_041":{"s":"本集從道理上說明如何相信因果輪迴與極樂世界：依假必依實之理，生滅的蘊處界須依不生不滅的如來藏，如來藏執持業種貫通三世，故有三世因果與六道輪迴，並引《楞嚴經》情想多寡說明往生去處。極樂世界則是阿彌陀佛與願力相應眾生的如來藏共同成就，諸佛願力不同故有淨土與五濁世界。","p":["生滅法須依不生不滅的如來藏方能存在","如來藏執持業種，貫通三世而成就因果","觀察因果須兼顧三世，不可輕易否定","情想多寡決定六道往生之處","極樂世界由彌陀與相應眾生如來藏共成"],"k":["因果輪迴","如來藏","極樂世界","三世因果","阿彌陀佛","願力"]},"2452-a11_042":{"s":"本集探討念佛法門與開悟的關係：無生法即本來不生不滅的如來藏，開悟是找到並安忍於此心，非打坐一念不生。依《觀無量壽佛經》上品中生須善解第一義、上品上生聞法即悟無生法忍，並引《法華經》佛之知見、《大寶積經》一行三昧及彌陀本願，說明念佛與開悟關係密切，末法仍有正法可證悟。","p":["無生法即本來不生不滅的如來藏心","悟無生不是打坐一念不生","上品中生須善解第一義，上品上生悟無生法忍","一行三昧：繫心一佛，參究念佛而證悟","末法仍有正法住世，證悟仍有希望"],"k":["念佛法門","開悟明心","無生法忍","觀無量壽佛經","一行三昧","如來藏"]},"2518-a11_043":{"s":"本集回答誦經時不解義理有無利益。先說明讀是理解義理、誦是課誦，第一義經典隱覆密意且譯文古樸，宜依止善知識並慎選註解。即使不解，誦經仍能攝心修定、堅固信根、種下善種，並有護持經典、鬼神聽經的法布施功德；而佛菩薩最希望的是證悟「此經」如來藏而真正受持讀誦。","p":["讀是瞭解義理，誦是課誦，目的在解義","第一義經典難懂，宜依善知識並慎選註解","誦經能攝心修定、堅固信根、種善種子","誦經亦有鬼神聽經的法布施功德","證悟如來藏「此經」才是真正受持讀誦"],"k":["誦經","讀誦功德","善知識","如來藏","法華經","迴向"]},"2409-a11_044":{"s":"本集說明為什麼執著就是苦：先以壞苦、苦苦、行苦說明苦的內涵，再將執著分三類——對名利眷屬等外我所、對五陰與意識心等自我與內我所、對自心所現諸法執為心外實有，逐一說明其引生的苦與障礙。強調應以八識論為基礎，首先斷除以意識心為真我的我見。","p":["三苦：壞苦、苦苦、行苦","執著生滅法欲長久擁有，必然引生痛苦","只放下外我所仍屬少分，須斷我見","意識心能反觀自己，故被誤執為真我","一切法皆自心現量，非心外實有"],"k":["執著","三苦","斷我見","我所","八識論","自心現量"]},"2467-a11_045":{"s":"本集探討如何有效斷除見惑與思惑（我見與我執）。先列舉眾生無法斷我見的六種原因，如誤認意識為真我、信受六識論、不知有如來藏、定力不足、不知方法等；再說明親近善知識、建立八識論正知見、親自觀行蘊處界生滅並配合定力與福德才能斷我見，最後依《瑜伽師地論》三種對治力說明分分修除我執。","p":["無法斷我見的六種原因","建立以如來藏為核心的八識論正知見","親自觀行蘊處界虛妄，配合定力與福德","我執是深刻的我見，初果至四果漸斷","瑜伽師地論三種對治力降伏煩惱"],"k":["斷我見","我執","八識論","如來藏","親近善知識","瑜伽師地論"]},"2411-a11_046":{"s":"本集回答人死後若未投胎是否變為鬼。講者指出「人死為鬼」是缺乏正知見的推論，依《大寶積經》《瑜伽師地論》等說明人捨報後經中陰身，最多七七四十九日必依業投生六道之一；並從飲食、壽量說明中有與餓鬼道不同，中有不屬五趣，亦說明投生餓鬼的十業與家屬助亡者的正確作法。","p":["人死為鬼是缺乏正知見的觀念","捨報後經中陰身，依業生五趣之一","中陰最多七七四十九日必得生緣","中有以香為食、壽短，與餓鬼不同","十業得餓鬼報，人身難得應慎行"],"k":["中陰身","餓鬼道","六道輪迴","業報","八識論"]},"2494-a11_047":{"s":"本集回答物質生活、現代科技與修持佛法是否衝突。講者說明世間財富善用可成為菩薩福德資糧與攝受眾生的方便，布施居六度與四攝之首；菩薩在欲離欲，不排斥也不追求享受。現代科技可提升自利利他效率，但更須抉擇正法；並說明佛法重實證，符合科學精神。","p":["人身需物質，福德是修學資糧","布施為六度、四攝之首","菩薩在欲而能離欲，不執受用","福德種子由如來藏帶到未來世","善用科技弘法，佛法重實證合科學精神"],"k":["布施","福德","在欲離欲","如來藏","現代科技"]},"2447-a11_048":{"s":"本集辨析佛法因果與宿命論的差別。講者引《中阿含經》《大毘婆沙論》指出宿命論外道認為一切皆前世業所定、須以苦行受盡；佛法則承認現世士用果，依《優婆塞戒經》《大般涅槃經》說明業有定與不定，透過修身、戒、心、慧可重業輕受，並以龍樹「升鹽投大海」喻說明福德增長能轉變業力。","p":["宿命論認為命運已定不可改","佛法承認現世努力的士用果","業有定業與不定業，重業可輕受","外道誤以苦行受盡業報求解脫","懺悔、發願、增福可轉變業力"],"k":["因果","宿命論","定業不定業","懺悔","苦行"]},"2457-a11_049":{"s":"本集回答「既然一切法空，行善作惡、天堂地獄還有差別嗎」。講者說明一切法空是指如來藏所生的蘊處界及其所生法無常無自性，前提是如來藏真實不空、執持善惡業種，故因果昭然；若離如來藏說空，易落斷滅空、撥無因果。並引經說明邪見的果報嚴重，強調應熏聞正法。","p":["行善作惡、天堂地獄差別真實可見","一切法空指蘊處界生滅無自性","如來藏真實不空，執持業種成就因果","否定如來藏易落斷滅空、撥無因果","邪見引生的果報最為嚴重"],"k":["一切法空","如來藏","因果","斷滅空","邪見"]},"2483-a11_050":{"s":"本集回答「所有宗教都一樣、都是勸善嗎」。講者以「一隻羊」為例，對比儒教告朔餼羊、《舊約》燔祭與對不信者的處置，以及佛教《楞嚴經》殺盜淫為輪迴本、《央掘魔羅經》眾生互為親屬的教導，主張各宗教終極主張與修行差異很大；並說一切眾生皆有如來藏，佛教為最平等的宗教，引《佛藏經》批評說法雜外道義者。","p":["儒、耶、佛對生死與成佛的觀點不同","以祭羊為例比較三教對待生命的態度","楞嚴經：殺盜淫為輪迴根本","眾生皆有如來藏，故佛教最平等","佛藏經：說法不應雜外道義"],"k":["宗教比較","如來藏","殺生","輪迴","外道邪見"]},"2445-a11_051":{"s":"本集回答佛教為何分宗立派，總結為「可分非宗、無宗可分」。講者認為佛法唯一的宗是不生不滅的如來藏，無形無相不可分割；簡述小乘大眾部、上座部分裂多因大天五事、十事等枝末爭議；並以《六祖壇經》、達摩傳《楞伽經》及玄奘兼弘般若與唯識，說明空宗、有宗所證是同一真心，不應割裂。","p":["佛法唯一宗是如來藏，不可分割","小乘部派分裂多屬枝末爭議","小乘無餘涅槃亦須依如來藏非斷滅","六祖所悟自性即含藏識第八識","空宗有宗之分違背真實一宗"],"k":["分宗立派","如來藏","部派佛教","空宗有宗","六祖壇經"]},"2446-a11_052":{"s":"本集說明佛法與生活的關係：對菩薩而言生活即佛法。講者指出生活煩惱不離五蘊十八界，修行須依四念處與未到地定斷我見，再明心證如來藏、轉依其清淨性於歷緣對境中伏除性障；並以《梵網經》「佛性常住、孝順心、慈悲心」說明眾生互為父母親屬，應孝順慈悲、不食眾生肉。","p":["生活即佛法，不離五蘊十八界","依四念處、未到地定斷我見","明心後轉依如來藏伏除性障","福德、定、慧與性障相互增益","梵網經：佛性常住、孝順心、慈悲心"],"k":["生活與佛法","斷我見","明心","梵網經","素食","性障"]},"2456-a11_053":{"s":"本集回答出家人為何受供養、托缽而不自食其力。講者認為「所有人都出家」不是正問，區分身出家與心出家；以佛陀為太子出家、窺基大師及迦葉尊者乞食貧婦等事說明出家是為求自他解脫、令眾生植福；並引百丈禪師「一日不作，一日不食」與洞山禪師語，提醒出家人不可貪名聞利養、枉受信施。","p":["問題非正問，不可能人人出家","分身出家與心出家，心出家為真","出家為識心達本、自他解脫","迦葉乞食貧婦，為令眾生植福田","百丈、洞山語：不可枉受信施"],"k":["出家","供養","托缽","福田","僧寶"]},"2403-a11_054":{"s":"本集解釋「煩惱即菩提，生死即涅槃」。講者先以正覺總持咒「五陰十八界、涅槃如來藏」區分生滅法與不生不滅法，說明念佛觀像與《金剛經》不相違，所見世界皆為內相分、唯心淨土；再以張拙秀才偈說明煩惱、菩提、生死、涅槃皆是依如來藏而現的波浪，並批評以「淫欲即菩提」為藉口的說法，強調仍須如實修行。","p":["區分生滅法與不生不滅法","所見世界皆為內相分，唯心淨土","藏識海常住，諸識如波浪","張拙偈：涅槃生死等空花","煩惱即菩提非可不修，批淫欲即菩提"],"k":["煩惱即菩提","如來藏","內相分","唯心淨土","金剛經"]},"2486-a11_055":{"s":"本集為「斷我見為何一定要有未到定」系列第一講。講者說明我見是執五蘊十八界任一法為我，是輪迴根本與三乘修行入門；外道以定為禪，將意識修成不動誤為涅槃；並介紹正覺講堂以無相念佛發起未到地定與四種修，最後以鬱頭藍弗以石壓草修得非想非非想定、因欲瞋失定而發惡願的故事為例。","p":["我見：執五蘊十八界一法為我","斷我見是三乘菩提共同入門","外道以定為禪，誤意識為涅槃","無相念佛發起未到地定與四種修","鬱頭藍弗石壓草失定發惡願"],"k":["斷我見","未到地定","我見","無相念佛","以定為禪","鬱頭藍弗"]},"2488-a11_056":{"s":"本集為系列第二講，續說鬱頭藍弗未斷我見將墮飛狸、地獄之例，歸納凡夫與外道錯誤。講者說明菩薩斷我見不離聲聞七方便、四念處，菩薩所證則是本來自性清淨涅槃的如來藏；並強調依未到地定觀心無常才能斷我見，提出「我見不斷，明心非真」，未斷我見而明心必無法轉依而退轉。","p":["鬱頭藍弗之例說明學錯法門的後果","聲聞七方便：五停心觀至世第一法","四種涅槃，菩薩證本來自性清淨涅槃","依未到地定觀心無常斷我見","我見不斷，明心非真，必退轉"],"k":["斷我見","未到地定","七方便","四念處","明心","涅槃"]},"2487-a11_057":{"s":"本集為系列第三講，說明未到地定的內涵與證得方法。講者介紹五停心觀，以及平實導師依〈大勢至菩薩念佛圓通章〉施設的無相憶佛拜佛法門，以「如母憶子」喻無語言文字的憶佛念；說明定力運用於生活可「先以定動，後以智拔」伏除瞋恚，最後一拜十數分鐘淨念相繼、遠離五塵，即具未到地定；並解說近分定與五蓋。","p":["五停心觀對治貪瞋等煩惱","無相憶佛拜佛，如母憶子","先以定動，後以智拔對治煩惱","淨念相繼、遠離五塵即未到地定","未到地定為初禪近分定，五蓋未盡"],"k":["未到地定","無相念佛","五停心觀","動中定","五蓋"]},"2489-a11_058":{"s":"本集為系列第四講，提出斷我見須有未到地定的經論與理證。講者引《瑜伽師地論》卷69說唯依諸靜慮及未至定能入聖諦現觀，引《俱舍論》說明靜慮律儀與無漏律儀皆依根本或近分定；再以四種修與四念處次第觀身不淨、觀受是苦、觀心無常，比喻層層脫衣，依未到地定實證意識生滅而斷我見。","p":["我見不斷，明心非真，須先斷我見","瑜伽師地論：依未至定入聖諦現觀","俱舍論：定共戒與道共戒","四種修：知見、定力、性障、福德","依四念處次第觀行斷我見證初果"],"k":["未到地定","斷我見","四念處","瑜伽師地論","俱舍論","初果"]},"2464-a11_059":{"s":"本集回答布施者應存何心才能達到布施解脫。講者依《大般若經》說明七住以上菩薩親證般若，現觀施者、受者、財物不可得而具足布施波羅蜜，並指出僅依蘊處界生滅講三輪體空會生疑問；初機宜先信布施果報，再逐步去除求名利、送禮、還願、消災等不清淨布施心態，以清淨迴向漸近布施到彼岸。","p":["布施與布施到彼岸的差別","三輪體空須依親證般若而說","初機先信受布施的因果利益","去除有所求等不清淨布施心態","清淨迴向，轉依後仍持續廣施"],"k":["布施波羅蜜","三輪體空","迴向","福德與功德","般若"]},"2497-a11_060":{"s":"本集為「生從何來，死往何去」上講。講者指出世間以出胎定義生只是方便施設，生從一念無明與業而來：起煩惱造身口意行形成業力，捨報時經中陰隨業入胎；死往何去則依當世善惡業輕重，重者先報，念佛淨念相繼者可往生極樂。最後說明生死是依蘊處界施設的概念，並非真實法。","p":["世間對「生」的定義只是方便施設","生從一念無明與業力而來","依中陰隨業入胎，輪迴相續","死往何去依善惡業輕重，重者先報","生死依蘊處界施設，非真實法"],"k":["生死輪迴","一念無明","業力","中陰身","往生"]},"2498-a11_061":{"s":"本集為「生從何來，死往何去」下講，並回答為何忘記前生。講者說明生死只是不生不滅的如來藏上所現之法；忘前生是因意識依五根身而生，入胎後舊意識已滅、新意識所依不同，並非喝孟婆湯；菩薩依轉依如來藏，雖示現生死實不在生死中，與阿羅漢滅盡十八界、畏懼生死而入無餘涅槃不同。","p":["生死依如來藏而現，非真實法","一般人不正知入胎","意識依根塵而生，故不憶前世","民間孟婆湯之說不足取信","菩薩本來無生死與阿羅漢出離不同"],"k":["生死","如來藏","隔陰之迷","意識","阿羅漢","無餘涅槃"]},"2481-a11_062":{"s":"本集回答「念佛就能往生，何需受五戒、修十善」。講者說明今世能信受念佛法門已是過去世修福的結果，能否一生堅持念佛也與福業相關；依《阿彌陀經》「不可以少善根福德因緣得生彼國」及《觀無量壽佛經》九品往生與三福淨業，指出持戒修善決定往生品位，並質疑只鼓勵下品下生的說法。","p":["能聽信念佛法門已是殊勝福報","念佛能否一生堅持仍待觀察","不可以少善根福德因緣得生彼國","九品往生品位與戒行善業相關","三福淨業：世福、戒福、行福"],"k":["念佛往生","五戒十善","三福淨業","九品往生","淨土法門"]},"2440-a11_117":{"s":"本集探討佛教對神祕現象的看法，從五陰魔、煩惱魔、天魔、死魔說明眾生因不了知法界運作而被境界迷惑。講者舉求降甘露、鬼神索祭等例，指出神祕境界與解脫無關；並評論大圓滿虹光身之說，引索達吉堪布所列四種徵相，先破第一種「肉身飛往淨土」。","p":["四種魔境：五陰魔、煩惱魔、天魔、死魔","所見影像為內相分，眾生易被幻覺迷惑","求降甘露屬天食境界，與解脫生死無關","鬼神索祭不合邏輯，其境界實不如人","法身本自獨存，肉身化光飛往淨土屬妄想"],"k":["神祕現象","四魔","虹光身","鬼神","法身","於相於土自在"]},"2441-a11_118":{"s":"本集續談神祕現象，評論虹光身其餘徵相：智慧火焚身類同人體自燃，引《增壹阿含》四梵志具五通仍不免死，說明神通非證量。再引《楞嚴經》天魔附人與四種決定清淨明誨評析密法；最後以《雜阿含》婆四吒「即得本心」公案，說明證得如來藏才是有智慧的神祕現象。","p":["屍身自焚類同人體自燃，非佛法證量","四梵志具五通仍不免死，神通非解脫","楞嚴經：天魔附人，邪見密興、種智銷滅","四種清淨明誨：斷婬、殺、盜、大妄語","婆四吒見佛即得本心，為真正神祕現象"],"k":["神祕現象","神通","楞嚴經","四種清淨明誨","如來藏","即得本心"]},"2508-a11_119":{"s":"本集回答緣起與進化論是否抵觸。講者認為進化論只描述群體現象，無法回答個人生命從何而來；佛法主張眾生有第八識本體，地球未成時存在於他方世界。並引《中阿含經》卷39光音天人下生、食地味而身轉重闇、漸生男女相的過程，說明業感緣起指出可修離欲回光音天乃至解脫。","p":["進化論只描述群體現象，未答生命本源","眾生有第八識本體，地球未成時在他方","光音天人下生，食地味後身重失光","地味、地肥、粳米漸出，男女相與欲生起","人可修離欲生色界，再斷我見得解脫"],"k":["業感緣起","進化論","光音天","如來藏","中阿含經","離欲"]},"2438-a11_120":{"s":"本集回答佛教是否以出家為重。講者認為以出家為重是二乘觀念，大乘法四眾平等；引《長阿含》「不以除鬚髮為沙門」及《大乘本生心地觀經》身遠離、心遠離之說，指出在家菩薩能心遠離而饒益眾生即是在家出家，以維摩詰為例，並認為寺院請學者講佛學才是真正的白衣說法。","p":["以出家為重屬二乘疾出三界的觀念","長阿含：不以除鬚髮為沙門","遠離行分身遠離與心遠離","在家菩薩心遠離、饒益眾生即在家出家","寺院請未實證學者講課才是白衣說法"],"k":["在家出家","四眾平等","白衣說法","遠離行","大乘本生心地觀經","維摩詰"]},"2493-a11_121":{"s":"本集解釋經典常說的「無始」。講者先介紹哲學上時間有限與無限同時成立的二律背反，以及大爆炸假說、飛矢不動命題的困境，指出問題在缺乏本體座標。佛法以本來存在、無生的第八識如來藏為座標，時間只是心依前後剎那所建立，一個如來藏貫串過去、現在、未來世。","p":["時間有限、無限同時成立的二律背反","大爆炸假說無法說明其條件，落無中生有","缺乏本體座標，才陷入有限無限困惑","第八識無生、本來存在，為一切法根源","一個如來藏貫串三世，故有過去未來世"],"k":["無始","無生","如來藏","時間","二律背反","三世"]},"2509-a11_122":{"s":"本集開始探討藏傳佛教是否正統，先談密教起源與形成。講者依序介紹陀羅尼、持明、真言、瑜伽、無上瑜伽密教的發展，及吠陀說等五種起源說；引學者之說認為《大日經》為集體創作，並述開元三大士、東密台密及無上瑜伽吸收性力思想。講者據此認為密教是演變不斷的混合宗教，與佛教不同。","p":["密教分陀羅尼、持明、真言、瑜伽、無上瑜伽","起源有吠陀、土著、道教、混合、大乘五說","陀羅尼密教抬高法師，後成上師四歸依","學者認為大日經為密教行者集體創作","無上瑜伽結合性力思想，史稱密教興佛教亡"],"k":["藏傳佛教","密教起源","大日經","無上瑜伽","陀羅尼","四歸依"]},"2513-a11_123":{"s":"本集續談無上瑜伽密教在西藏的發展。介紹寧瑪派蓮花生與伏藏（引學者圖奇的質疑）、朗達瑪滅佛與前後弘期、噶舉派那洛六法、薩迦派八思巴、格魯派宗喀巴與達賴喇嘛，及元明清帝王崇信之影響。講者認為四大派不離男女雙身法，唯覺囊派篤補巴、多羅那他的他空見符合如來藏正法，後遭達賴五世摧滅。","p":["寧瑪派蓮花生地位，學者疑為後人吹捧","朗達瑪滅佛，分前弘期與後弘期","噶舉那洛六法、薩迦八思巴、格魯宗喀巴","元明清崇信藏傳佛教，影響中國佛教","覺囊派他空見符合如來藏，遭達賴五世摧滅"],"k":["藏傳佛教","覺囊派","他空見","西藏四大派","如來藏","雙身法"]},"2511-a11_124":{"s":"本集開始逐一檢視《大日經》，列出六大瑜伽、菩提心為因、悲為根本、方便為究竟四重點，先論六大中的識大。講者指出密教行者（舉空海等）與部分古今法師認為識大有了別性，是誤解《稻芉經》；並引《深密解脫經》、《大集經》說明真心離覺觀，能分別六塵的是識陰六識，故講者認為密教落入常見外道。","p":["大日經四重點：六大、菩提心、悲、方便","地水火風空五大屬色法，無了別性","密教行者認識大有了別，舉空海等為例","稻芉經識大是與六識如束蘆的真心","真心離見聞覺知，分別六塵者是識陰六識"],"k":["大日經","六大","識大","離見聞覺知","識陰","常見外道"]},"2517-a11_125":{"s":"本集說明密教認為識大有了別性的第二個原因：《大日經》強調如實知自心、觀想四種曼荼羅、三密加持，皆不離能觀的意識心。講者引《入楞伽經》、《心地觀經》、《心經》、《金剛經》、《金剛三昧經》說明真心離分別，並解釋維摩詰「知是菩提」不代表真心分別六塵，結論為密教落入常見乃至斷見。","p":["大日經強調知自心、四曼觀想、三密","三者皆須能觀的意識心才能進行","入楞伽經：真如法體離分別","心經、金剛經顯示真心離一切相","知是菩提指了眾生心行，真心不分別六入"],"k":["大日經","識大","真如","意識","常見外道","斷見外道"]},"2514-a11_126":{"s":"本集探討《大日經》「菩提心為因」，即如實知自心、自心尋求菩提。講者認為此心有能觀與所觀，屬意識覺觀境界，並引《解節經》、《深密解脫經》說實相超過覺觀；又指其前說覺觀、後說無分別為前後矛盾，以睡眠無夢時意識斷滅為證；並區分禪宗以意識尋找離見聞覺知的真心，與《大日經》著重能觀之心不同。","p":["如實知自心需能觀心，落意識覺觀","解節經：實相超過一切覺觀境界","講者指大日經前後說法自相矛盾","睡眠無夢時意識不現，非本來自在心","禪宗以意識找真心，重在所證之心"],"k":["菩提心","大日經","如實知自心","覺觀","意識","離念靈知"]},"2516-a11_127":{"s":"本集探討《大日經》「悲為根本」及曼荼羅法門。說明曼荼羅源於古印度授戒、登基的土壇，再介紹大、三昧耶、法、羯磨四種曼荼羅與胎藏界十三院、中台八葉院。講者認為這些是把真心物化、相化，屬生滅法；又批評五佛配五色違背佛光金色之說，以煮沙不成飯為喻，主張成佛須找到真心。","p":["曼荼羅源於古印度授戒登基的土壇","四種曼荼羅：大、三昧耶、法、羯磨","講者認為將真心物化相化，屬生滅法","胎藏界十三院，中台八葉院為總體","五佛配五色違佛光金色，如煮沙求飯"],"k":["曼荼羅","悲為根本","大日經","胎藏界","真心","藏傳佛教"]},"2510-a11_128":{"s":"本集進入「方便為究竟」的三密，先談身密手印。介紹密教以左右手配定慧、五指配五輪及合掌、拳等施設，舉大慧刀印、法螺印。講者引《法華經》一大事因緣，認為手印屬行陰，不能斷俱生身見或證涅槃，並說明法身、般若、解脫三德；也批評智拳印與問訊所用毘盧印，建議改用法界定印。","p":["三密即三方便，身密為手結印契","左右手配定慧，五指配地水火風空","法華經：佛為開示悟入佛知見出世","手印屬行陰，不能斷俱生身見證涅槃","涅槃三德：法身德、般若德、解脫德"],"k":["身密","手印","三密","俱生身見","涅槃三德","法界定印"]},"2515-a11_129":{"s":"本集談三密中的語密，即口誦真言。講者說明真言源於吠陀，《阿闥婆吠陀》有息災、增益、降伏三種咒術，為《大日經》護摩所承；引《長阿含經》卷14說佛禁咒術，並區分《心經》咒是開示自心如來。又指誦真言屬行陰、識陰的生滅法，對照菩薩五十二階位成佛次第，講者認為《大日經》為偽經。","p":["真言源自吠陀，有息災、增益、降伏咒術","長阿含：佛禁止咒術等邪命在僧團出現","大日經主張真言法爾如是為實相","心經咒開示自心如來，與吠陀咒不同","成佛須歷五十二階位，非誦咒可成"],"k":["語密","真言","咒術","吠陀","五十二階位","大日經"]},"2512-a11_130":{"s":"本集談三密中的意密觀想，以月輪觀為主，介紹本尊瑜伽、入我我入、生起佛慢、五字嚴身觀，及無上瑜伽的生起與圓滿次第。講者評善無畏「月輪觀成即初地」之說，認為月輪觀屬修定法門，初地須從七住明心及如幻、陽焰、如夢觀等次第而得；並比較無相憶佛拜佛功夫，以觀想火星為喻說觀想虛妄。","p":["月輪觀為密教觀想基礎，衍生本尊瑜伽","入我我入、生起佛慢，自認成佛","月輪觀屬修定，不能斷煩惱","初地須七住明心並修三觀與十六品心","觀想火星人仍在地球，觀想屬虛妄"],"k":["意密","月輪觀","觀想","初地","明心","無相憶佛"]},"2465-a11_063":{"s":"本集依《楞嚴經》「理則頓悟，乘悟併銷；事非頓除，因次第盡」，說明「理事圓融」本是佛道修證的因果，世俗用法已偏離原意。以建屋、方程式、四禪八定與除五蓋為例，說明世間法理事已難圓融；再述出世間解脫道之理在斷我見、我所執、我執，及聲聞四聖諦與緣覺十二因緣觀的不同入手處。","p":["理事圓融出自楞嚴經，世俗用語已失原意","建屋、方程式顯示世間法理事難圓融","禪定為次第法，須先離五蓋方能發初禪","解脫道之理在斷我見、我所執、我執","聲聞依四聖諦，緣覺先十因緣再十二因緣觀"],"k":["理事圓融","楞嚴經","五蓋","四禪八定","斷我見","十二因緣"]},"2466-a11_064":{"s":"本集續說出世間法的「事」及世出世間法的理事。指出須信有第八識如來藏才能修證解脫道，講者批評六識論使無餘涅槃成斷滅；不知蘊處界內涵、貪著五欲、不修定皆是事修障礙。佛菩提道則證如來藏為理上頓悟、得總相智，悟後依《優婆塞戒經》修空三昧、滅定、四禪、慈悲、十二因緣等，次第斷無始無明。","p":["須信第八識如來藏方能修證解脫道","講者批評六識論使無餘涅槃成斷滅","不知蘊處界、貪五欲、不修定障礙事修","證如來藏頓悟總相，悟後事修因次第盡","菩薩證三三昧，斷我執僅是佛道副產品"],"k":["理事圓融","如來藏","無始無明","三三昧","解脫道","六識論"]},"2442-a11_065":{"s":"本集回答「佛法中求財得財，是否就無因果」。以世間捐官、考試、彩券說明求不一定得，得與否關乎過去福業與今世之緣；並指驅使鬼神的五鬼搬運求財恐結惡因果。依《優婆塞戒經》說財富從布施中得，講五種布施及施不同福田得百倍乃至無量報，故求財得財正合因果。","p":["世間求官、考試、彩券顯示求不必得","得與否繫於過去福業及今世之緣","驅使鬼神求財恐招不好因果","優婆塞戒經五種施，財富從布施得","依福田不同，施得百倍乃至無量報"],"k":["因果","布施","福德","優婆塞戒經","財施"]},"2453-a11_066":{"s":"本集從佛號「兩足尊」談福德與成佛之道的關聯。以錢、車票、刷卡說明所用其實是福報，再由家庭、國家、轉輪聖王比較到如來教化百億四天下，顯示福報大小。依平實導師「五度修福業，憑之得般若」，說明布施、持戒、忍辱、精進、禪定各得不同福報，是菩薩入七住證悟的資糧，且福德隨階位越加深廣、越為眾生。","p":["用錢其實是用福報，福報有大小","金輪聖王福報遠不及如來百億四天下","五度修福業為證般若之資糧","布施、持戒、忍辱等各得不同福報","三歸依信心與發菩提心的福德助入住位"],"k":["福德","六度","兩足尊","轉輪聖王","菩提心","布施"]},"2477-a11_067":{"s":"本集討論學佛「離苦得樂」之樂能否永存。先定義苦樂，指出五欲樂伴隨苦、禪定之樂福盡亦下墮；引《大般涅槃經》功德天與黑闇女姊妹之喻，說明苦樂相隨、智者二俱不受。再說「得」屬心不相應行之假施設，引《金剛經》須陀洹無所得及《佛藏經》世尊過去有所得故不得授記，結論唯有無所得才能真正離苦得樂。","p":["樂中伴苦，失樂與求不得皆是苦","禪定之樂亦有盡，福盡仍下墮","功德天與黑闇女喻苦樂相隨","得是假施設，須陀洹亦無所得","佛藏經：有所得故諸佛不為授記"],"k":["離苦得樂","無所得","苦樂","大般涅槃經","金剛經","佛藏經"]},"2460-a11_068":{"s":"本集回應「大乘非佛說」，從2008年研討會中有教授稱其為學術常識談起。依天台五時三教說明佛陀說法次第，指出成佛之道須含解脫道、般若總相別相智與一切種智，講者批評否定如來藏者謗之為外道神我。引《阿含正義》說阿含已隱說第七、八識，並提出前三個理由：聲聞智慧狹劣、念心所不成就，凡夫聲聞不信佛境，聽聞大乘卻以解脫道結集。","p":["講者質疑「大乘非佛說是學術常識」","依五時三教說明佛陀說法次第","成佛之道須具解脫、般若與一切種智","阿含隱說七、八識，免涅槃成斷滅","前三理由：聲聞不能憶持結集大乘法"],"k":["大乘非佛說","五時三教","如來藏","阿含正義","經典結集"]},"2462-a11_069":{"s":"本集續說大乘經典非後人編造的第四至第七理由：二乘聖人聽聞大乘不解而無法結集；聲聞凡夫僧多不信佛菩提道；解脫道易證故聲聞僧多、證悟菩薩極少；出家僧為表相住持，在家菩薩居護持地位，故初次結集偏解脫道，菩薩溝通無效後另行結集。並以平實導師辨正書必晚於諸方錯說為喻，主張應以法義而非結集先後判真偽。","p":["二乘聖人不解大乘，念心所不成難結集","大乘結集必在阿含後，如辨正書晚出","菩薩僧指正聲聞非諍論，強辯者才是","證悟菩薩極少，在家菩薩居護持地位","判經真偽應依法義，不依結集先後"],"k":["大乘非佛說","經典結集","聲聞僧","菩薩僧","四阿含"]},"2461-a11_070":{"s":"本集提出第八、第九理由並作結論。依《佛泥洹經》說四阿含於第一次五百結集即已具足，七百結集只結戒律，故大乘經應在菩薩提出另行結集後不久完成；引《增壹阿含》說明聲聞只修解脫道。又說四阿含只提「安隱觀」名相，須第二、三轉法輪才具說成佛之道。最後列出若謂大乘為後人杜撰將生的三大過失。","p":["四阿含於第一次結集時即已具足","七百結集只結戒律，大乘結集應在其前","聲聞僅修厭患根塵識的解脫道","阿含只提安隱觀名相，須大乘經廣說","杜撰說將致後人智慧勝佛等三過失"],"k":["大乘非佛說","經典結集","安隱觀","四阿含","一切種智"]},"2471-a11_071":{"s":"本集以商人買偈「向前三步想一想」而免於誤傷妻子的故事開場，說明「火燒功德林」指一時瞋恚燒毀長時所修功德。瞋屬六根本煩惱，由我執而起；引《瑜伽師地論》十種瞋事，歸為有情瞋、境界瞋、見瞋。對治須修忍辱，分世間忍、出世間忍、法忍，並以不以惡報惡、觀無常、修慈悲、心不放逸、斷瞋五法成就生忍。","p":["火燒功德林即瞋恚毀損長時功德","瞋屬根本煩惱，由我執引生","瑜伽師地論十種瞋事，歸為三種瞋","忍分世間忍、出世間忍與法忍","五法成生忍：不報惡、觀無常、慈悲等"],"k":["瞋恚","忍辱","火燒功德林","生忍","根本煩惱","瑜伽師地論"]},"2425-a11_072":{"s":"本集從《華嚴經》〈普賢行願品〉十大願中的「恆順眾生」談起，將十願分四類，指出恆順眾生即隨緣，但世間隨緣不等於佛法隨緣；大乘佛法積極進取、函蓋三乘，須簡擇後對善法隨緣、惡法不隨緣。隨緣分理隨緣（如來藏）與事隨緣（意識），本集先說理隨緣前兩種：隨眾生心之緣、隨應眾生果報之緣。","p":["恆順眾生出自普賢十大願","大乘佛法積極進取，非消極逃避","簡擇後對善法隨緣，惡法不隨緣","理隨緣指如來藏，事隨緣指意識","如來藏隨眾生心行、隨業種現果報"],"k":["恆順眾生","隨緣","如來藏","普賢行願品","三界唯心"]},"2427-a11_073":{"s":"本集補充諸佛四種淨土是由攝受眾生、眾生如來藏共同運作而成，說明三界唯心。續說理隨緣第三種隨應眾生現世所需之緣（萬法唯識、八識和合），第四種隨應業種之緣，如來藏如實現報、意識不能持種。再說事隨緣中世俗人的六種隨緣及外道的隨緣，強調事相隨緣須以智慧簡擇。","p":["攝受眾生，眾生如來藏共成佛國淨土","三界境界皆由眾生如來藏共同變現","萬法須八識和合，如來藏隨緣運作","如來藏執持業種，不簡擇而隨緣應報","世俗人六種隨緣與外道隨緣皆須簡擇"],"k":["隨緣","如來藏","佛國淨土","萬法唯識","業種","四攝法"]},"2426-a11_074":{"s":"本集說事隨緣中佛教學人的隨緣：信心不具足者三種（不知法義、自認根器差、不信正法仍住世），信心已生者四種（信師「不求開悟」、隨錯悟之師、隨藏密邪法、人云亦云）。講者批評藏密雙身法與「一表千里」的代表式修法。並說真悟菩薩對未有悟緣者亦隨緣，結論為善法當隨緣、惡法莫隨緣。","p":["信心不具足者有三種隨緣心態","信心已生者誤信師說而安住錯悟","講者批評藏密雙身法與一表千里","未讀其書即隨人評論亦屬惡隨緣","善法當隨緣，惡法莫隨緣"],"k":["隨緣","恆順眾生","明心開悟","藏傳佛教","善知識"]},"2433-a11_075":{"s":"本集引《維基百科》定義，說人間佛教源自太虛大師的人生佛教，講者認為太虛大師大體符合佛意；而批評某法師的人間佛教承襲應成派中觀，否定第七、八識、十方淨土與第三轉法輪。並評論維基百科所列六特點及台灣幾個推動慈善、文化、教育的團體，認為其以人間利樂悲行為主軸，使佛教淺化世俗化，未觸及三乘菩提實證。","p":["人間佛教源於太虛大師的人生佛教","講者認為太虛大師主張大體符合佛意","批評某法師否定如來藏與十方淨土","維基百科歸納人間佛教六項特點","講者認為諸團體以世間善法代替修證"],"k":["人間佛教","人生佛教","如來藏","應成派中觀","三乘菩提"]},"2434-a11_076":{"s":"本集說明佛所說的人間佛教正理：佛法即成佛之法，佛施設三乘應機，聲聞依四聖諦八正道、緣覺依十因緣與十二因緣觀，皆不能成佛；佛菩提道依證如來藏，歷十住、十行、十迴向、十地、等覺，再以百劫修相好成妙覺。人間佛教真義是正法住世時長住人間修三乘菩提最速，法滅後往生彌勒內院或他方淨土續修。","p":["佛法即成佛之法，施設三乘應機","緣覺依十因緣、十二因緣觀斷無明","佛菩提道歷諸階位，百劫修相好成佛","實證佛菩提者必不違三乘菩提","正法住世時長住人間修學最為迅速"],"k":["人間佛教","佛菩提道","三乘菩提","十二因緣","菩薩階位","如來藏"]},"2502-a11_077":{"s":"本集回答天堂地獄是否真實、升天墮獄由誰所使。講者批評視地獄為教化方便之說不合科學精神，舉輪迴事例與宿命通、天眼通，說不應因看不見而否定。依《華嚴經》「心如工畫師」與《心地觀經》說三界唯心，天堂地獄由各人如來藏依業種與異熟性變現；並批評將「唯心造」解為意識心或「心不住相即無地獄」之說。","p":["講者認為否定地獄不符科學精神","未發神通不能見，不應否定六道","三界由眾生如來藏隨業緣變現","七轉識造業，種子存第八識而受報","批評「心不住相即無地獄」之說"],"k":["天堂地獄","如來藏","三界唯心","六道輪迴","業種","異熟"]},"2454-a11_078":{"s":"本集說明修行者如何坦然面對死亡。二乘行者明四聖諦，斷三縛結成初果後不畏死，得四不壞信者不墮三惡道、最多七次人天往還；並指涅槃中無意識我可受樂。大乘菩薩證本來自性清淨涅槃如來藏，不住生死涅槃、留惑潤生；未證者亦具四不壞信與菩薩性。另說深信因果不造惡業、預作往生規劃及助念憶持善法而終。","p":["有生必死，凡夫因無明貪愛而畏死","涅槃中無意識我，以五陰為我即我見","得四不壞信、證初果者不墮三惡道","菩薩證如來藏，不住生死亦不住涅槃","深信因果、規劃往生、助念安樂而終"],"k":["死亡","涅槃","斷我見","四不壞信","如來藏","助念"]},"2480-a11_079":{"s":"本集依《優婆塞戒經》〈業品〉說定業成因：常作無悔、專心作、樂作、立誓願作、作已歡喜五種心境；並說謗法、邪淫雙修等可成無間地獄定業。再引《大般涅槃經》氣噓旃陀羅、鴦掘摩羅、阿闍世王懺悔等事，說聖人修道為壞定業、轉重為輕；藉修身、戒、心、慧，遇福田及懺悔，定業可轉，並引窺基《瑜伽師地論略纂》補充。","p":["以五種心境造業則果報決定","未懺悔之惡業死後成異熟定業","智者轉重為輕，愚者轉輕為重","阿闍世王、鴦掘摩羅懺悔轉業之例","修身戒心慧並懺悔，定業可轉"],"k":["定業","懺悔","因果","優婆塞戒經","大般涅槃經","異熟果報"]},"2404-a11_080":{"s":"本集引阿含、華嚴、《大智度論》，說一切智常指佛智，一切智人為佛專稱；但《般若經》三慧中，一切智為聲聞辟支佛智、道種智為菩薩智、一切種智為佛智。解脫道一切智含十智，屬通教；一切種智須證如來藏後歷般若總相智、別相智、道種智而成，屬別教。並說阿羅漢迴心最高至六住，等覺須百劫圓滿三事方成佛，講者批評「阿羅漢即佛」之說。","p":["一切智常代表佛智，一切智人專指佛","般若經三慧：一切智、道種智、一切種智","解脫道一切智含十智，屬通教","一切種智依證如來藏而修，屬別教","等覺須百劫圓滿三事方成佛"],"k":["一切智","一切種智","道種智","般若","通教別教","阿羅漢"]},"2459-a11_081":{"s":"本集回應某法師批評在家居士組團共修的說法，引《說無垢稱經》區分身出家與心出家，並舉大菩薩多現在家相、善財五十三參多為在家菩薩為例。再依《大乘理趣六波羅蜜多經》說明佛法僧三寶皆以如來藏為根本，主張如法與否在於所教是否為佛陀正法，而非出家或在家表相。","p":["身出家不如心出家，發菩提心勤修正行即是出家","大菩薩多現在家相，五十三參僅六位出家","三寶真實義皆依如來藏而立","《雜阿含》：能說五陰厭離滅盡方名法師","判斷如法在所教是否為佛陀正法"],"k":["三寶","心出家","如來藏","在家菩薩","維摩詰經","說法師"]},"2448-a11_082":{"s":"本集針對「大乘非佛說」的質疑，說明可用法印與四依法檢驗聖言量，本集先講法印。引《大智度論》說法印即諸法實相，三法印、四法印略說即一實相印；並引阿含部《佛說法印經》說空性即聖法印，般若波羅蜜多即空性心如來藏，強調三法印須含流轉門與還滅門整體來看。","p":["大乘經較晚流行，引發大乘非佛說之疑","法印即諸法實相，三法印略說為一實相印","《佛說法印經》以空性為聖法印","般若波羅蜜多即空性心如來藏","三法印含流轉與還滅門，不可割裂"],"k":["法印","三法印","實相印","大乘非佛說","如來藏","流轉門還滅門"]},"2449-a11_083":{"s":"本集續談聖言量，講者批評某大法師只取緣起性空為佛法本質是割裂三法印。並以部派分裂、歷代大菩薩只敢造論等理由反駁大乘非佛說，引《佛藏經》說將佛語說為非佛說即是謗法；最後依《大般涅槃經》四依法逐一說明，結論佛說聖言量經得起考驗。","p":["只取緣起性空是割裂三法印","部派分裂與菩薩只造論反駁大乘非佛說","《佛藏經》：說佛經非佛說即謗法","依法、依義、依智、依了義經逐一解說","如來藏不生滅，故聖言量經得起考驗"],"k":["四依法","聖言量","大乘非佛說","三法印","佛藏經","了義經"]},"2405-a11_084":{"s":"本集回答八萬四千法門與不二法門是否矛盾。先解釋「法」有任持自體與軌則二義，再說法門、四宏誓願及八萬四千的來由（引《大乘本生心地觀經》）。指出諸法門歸為解脫道與佛菩提道，依《法華經》唯一佛乘、化城喻，最後說不二法門即如來藏中道，一切法門皆須匯歸於此。","p":["法有任持自體與軌範二義","八萬四千表數多，心地觀經有其推算","諸法門歸為解脫道與佛菩提道","《法華經》唯一佛乘，二乘如化城","不二法門即如來藏中道，萬法匯歸"],"k":["不二法門","八萬四千法門","唯一佛乘","中道","如來藏","法華經"]},"2428-a11_085":{"s":"本集說明「七情六慾」並非佛法用語，佛法只說六情（即六根）與五欲。五欲有五塵與財色名食睡兩種說法，引《大智度論》譬喻五欲之害及《法句經》藏六如龜典故；再說六欲是五欲加法塵，七情則有一般與中醫兩種說法，並引《中庸》，說明戒除七情六欲是走向解脫的起點。","p":["六情即六根，五欲為色聲香味觸","《大智度論》以譬喻說追求五欲之害","藏六如龜、防意如城典故","財色名食睡五欲障礙修行","七情由五欲六欲生，應先戒止"],"k":["五欲","六根","七情六慾","藏六如龜","財色名食睡"]},"2490-a11_086":{"s":"本集回答「一切皆空，學習還有必要嗎」，從生活經驗、解脫道、佛菩提道三層說空。生活中與四空處之空都是相對說空；解脫道依《雜阿含》十一種觀察五蘊無常而斷我見；佛菩提道則依無著菩薩之說，實證能生萬法的第八識空性心。並引《菩薩地持經》寧起身見不惡取空，強調佛法不是斷滅空。","p":["生活中與四空處之空皆相對而說","依十一種觀察五蘊無常而斷我見","藏六如龜式解脫如以石壓草","菩薩所證空性為能生萬法的第八識","寧起身見不惡取空，佛法非斷滅空"],"k":["空性","惡取空","斷我見","五蘊無常","如來藏","四空定"]},"2424-a11_087":{"s":"本集從繫縛說起，解釋什麼是解脫與如何求解脫。以二箭喻說明凡夫兼受身心二受，聖弟子只受身受；苦樂不苦不樂受分別為貪瞋癡所縛。求解脫須先修次法、依善知識斷我見。再以《雜阿含》仙尼外道一經，說三種師分屬斷見、常見與佛說，並解析佛陀與仙尼關於「色是如來耶」的六段問答。","p":["繫縛來自貪瞋癡與三受","二箭喻：凡夫兼受身受與心受","求解脫須先修施論、戒論、生天之論","仙尼經三種師：斷見、常見、佛說","六段問答通於般若，須正見真我"],"k":["解脫","斷我見","三受","仙尼外道","次法","斷見常見"]},"2500-a11_088":{"s":"本集說大乘解脫的關鍵在證解阿賴耶識。引《大般涅槃經》說真解脫非修生、非和合生，再依《瑜伽師地論》三解脫門由三自性建立、《攝大乘論》所知依，以及世親《六門教授習定論》說解脫即除二障。並強調必須先具足次法與無相念佛定力，引「先以定動，後以智拔」說明沒有定力的悟只是乾慧。","p":["真解脫非修行所生、非和合而生","三解脫門依三自性，三自性依阿賴耶識","解脫即除煩惱、所知二障","見道須具次法與無相念佛定力","先以定動後以智拔，無定則成乾慧"],"k":["阿賴耶識","三解脫門","定力","次法","乾慧","二障"]},"2423-a11_089":{"s":"本集說明煩惱障，指出二障種子皆由執受識阿賴耶識所持。二乘法中煩惱障是三縛結、五下分結、五上分結；大乘分為一念無明（見惑、思惑四住地）與無始無明，並舉鬱頭藍弗因瞋習與邪見下墮為例。又以阿難遭摩登伽、舍利弗與鴿子說明俱生煩惱與習氣，講者並批評喇嘛教與某學者之說。","p":["二障皆依阿賴耶識，須先實證此識","二乘：三縛結、五下分結、五上分結","一念無明分見惑與思惑四住地","鬱頭藍弗因瞋習邪見下墮","八地斷盡煩惱障，阿賴耶改名異熟識"],"k":["煩惱障","一念無明","四住地","阿賴耶識","五上分結","習氣"]},"2422-a11_090":{"s":"本集說明所知障，講者批評將所知障解為世智聰辯、讀經太多或成見的說法。所知障源於無始無明，二乘不能斷，菩薩七住明心起漸斷，上煩惱多如塵沙。引《攝大乘論》阿賴耶識為所知依、《勝鬘經》無明住地力最大、《入楞伽經》智障，以及《瑜伽師地論》皮膚肉三種麁重，說明二障到佛地才究竟斷盡。","p":["所知障非世智聰辯，也非讀經太多","源於無始無明，七住明心起漸斷","阿賴耶識是所知依，所知障是不如實知","無明住地力最大，唯如來菩提智能斷","皮膚肉三種麁重，佛地二障永斷"],"k":["所知障","無始無明","塵沙惑","無明住地","阿賴耶識","常樂我淨"]},"2421-a11_091":{"s":"本集回答能否以九住心作為無相拜佛的入手處，依彌勒菩薩所說九住心，逐一說明修定時意識安住的變化：從內住、正念住、覆審住、近住，到調柔住、寂靜住、降伏住、功用住、任運住，並配合憶佛念的調整方法，說明如何輕提憶佛念、避免昏沉、以定力對治習氣。本集只談定，不涉及慧。","p":["斷我見須未到地定支持","內住靠聞思之力攝心","覆審住只輕提憶佛念，不另起念壓妄想","調柔、寂靜住以輕安定力對治習氣","功用住至任運住，定自然流注"],"k":["九住心","無相念佛","定力","憶佛","輕安","未到地定"]},"2501-a11_092":{"s":"本集依《六門教授習定論》說明修定時的五種心散亂，本集講前四種。外心散亂為五欲所擾，以舔刀上蜜等喻其過患；內心散亂含掉舉、昏沉與貪著定境，並說無相念佛成就者在吵雜處也能安住；邪緣散亂舉難陀求天女及講者對喇嘛教的批評；粗重心散亂則是執取輕安或自卑自慢，須靠利樂眾生斷除二障。","p":["外心散亂：被五塵五欲牽動","內心散亂：掉舉、昏沉、貪著定境","無相念佛成就者不受環境繫縛","邪緣散亂：心住於不正所緣","粗重散亂：執取輕安、起慢或自卑"],"k":["散亂","修定","掉舉昏沉","無相念佛","五欲","我慢"]},"2499-a11_093":{"s":"本集先補說第五種作意散亂的三類，包括抓緊憶佛念、婆子燒庵公案所示的「此乘趣餘乘」與轉換定境。主體則說戒是定的資糧：依《瑜伽師地論》持戒十種功德，由無悔、喜、輕安、樂而得定與解脫；並說佛陀傳出家戒與優婆塞戒的慎重次第，以及善護諸根等四種淨戒之因。","p":["作意散亂三種，含婆子燒庵公案","持戒十功德：無悔、喜、輕安以至解脫","傳出家戒與優婆塞戒須觀察次第","在家戒前須如法求財、離四種惡人","戒淨四因：護根、知量、警覺、正念"],"k":["持戒","修定","作意散亂","優婆塞戒","無相念佛","四威儀"]},"2451-a11_094":{"s":"本集說明修學佛法在成佛之前都不應捨離真善知識。以《中阿含經》彌醯比丘離開佛陀獨修，結果生起惡念又返回的故事，說明心解脫成熟的五種方法；引平實導師在《阿含正義》中對過慢之人的評論，並說七地滿心仍需諸佛引發。最後說簡擇善知識不應看表相，並指出以「依法不依人」為由自立門戶的問題。","p":["成佛之前皆不能捨離善知識","彌醯比丘離佛獨修生起惡念","心解脫成熟須依善知識五法","七地滿心仍需諸佛引發如來妙智","以依法不依人自立門戶，實是依自己"],"k":["善知識","我慢","依法不依人","心解脫","中阿含經"]},"2469-a11_095":{"s":"本集探討罪業從何而生、障礙什麼以及如何真實懺悔。罪業來自現行與隨眠煩惱所造的十不善業，會障礙人天果與善根。依《佛說佛名經》說滅三障應生起七種心，最後一種觀罪性空又從因緣與般若實相兩層解說；並引六祖「修福不能滅罪」，說真懺悔要除掉貪瞋癡與四顛倒這個罪源。","p":["罪業源於煩惱所造十不善業","罪業障礙人天果與善根長養","滅三障須生七種心","觀罪性空：從因緣與如來藏實相觀","修福不能抵罪，應除罪源四顛倒"],"k":["懺悔","十不善業","三障","罪性本空","四顛倒","如來藏"]},"2495-a11_096":{"s":"本集說明了義經與不了義經的分別。引《佛說大乘菩薩藏正法經》說引趣於道、世俗行、染分、厭離輪迴屬不了義，引趣於果、勝義、淨分、悟輪迴涅槃不二屬了義；再依《大般涅槃經》說聲聞乘如半字、初耕為不了義，大乘菩薩法為了義。並說修學不了義法是前方便，只要不當作究竟就不會白費。","p":["了義是真實義，不了義為方便引導","引趣於果、勝義、淨分、不二為了義","聲聞乘如半字、初耕，名不了義","了義指實證如來藏、眾生皆能成佛","不了義法是前方便，非白費"],"k":["了義經","不了義經","四依法","如來藏","聲聞乘","大乘"]},"2430-a11_097":{"s":"本集解釋世間、出世間與世出世間。世間分有情世間與器世間，引《瑜伽師地論》說有樂、有苦有情世間都常懷怖畏。依《大方等大集經》說菩薩善分別五陰為出世間，大乘的出世間是本來解脫的如來藏，與二乘不同。世出世間指不離世間而能出離，並分世間智、出世間智、世出世間智，以五明修學說明。","p":["世間分有情世間與器世間","有樂、有苦有情世間皆常懷怖畏","大乘出世間指本來解脫的如來藏","世出世間：不離世間而出離繫縛","三種智與依般若修學五明"],"k":["世出世間","出世間","有情世間","般若","如來藏","五明"]},"2412-a11_098":{"s":"本集回答人類與宇宙是被創造還是進化而來，講者主張兩者都不是，而是由有情的業與如來藏所成。先說三世輪迴、六道、正報與依報，再引《起世經》說世界壞後重成時，光音天人下生，因食地肥、粳米而失去光明、生出男女根，並有入胎；又引《瑜伽師地論》說器世間依共業成壞。","p":["演化說也須以三世輪迴為前提","有情不出六道，分正報與依報","火災燒至初禪，眾生生於光音天","光音天人食地肥粳米而生男女根","器世間依共業成壞，五陰由自心如來藏造"],"k":["器世間","三世輪迴","共業","起世經","如來藏","光音天"]},"2472-a11_099":{"s":"本集回答學佛是否一定要吃全素。說明三歸五戒階段重在不對眾生起殺念，方便允許三淨肉；但求解脫須斷欲界口欲，出家聲聞戒禁食眾生肉，受菩薩戒者為長養慈悲亦不得食肉。講者並引《大般涅槃經》批評喇嘛吃肉喝酒，以鴿入佛影之例說明大慈悲。","p":["五戒重在不起殺念，方便食三淨肉","外道吃素而未受五戒，不得不殺戒德","求解脫須斷口欲，聲聞戒禁食肉","講者引《涅槃經》批評喇嘛食肉飲酒","菩薩以慈悲不食肉，舉鴿入佛影例"],"k":["素食","三淨肉","五戒","菩薩戒","慈悲","大般涅槃經"]},"2406-a11_100":{"s":"本集探討臨終見瑞相是否代表解脫。依《大寶積經》說明善業者臨終見天界可愛相、面現好相，惡業者見亂色相；但有往生處即未離三界生死。再依《長阿含經》「法鏡」說明須以信三寶、持賢聖戒、斷三縛結等因果判斷有無解脫及生處；往生極樂見瑞相亦僅暫離人間生死。","p":["善心死見不亂色相，惡心死見亂色相","瑞相表示生善處，仍不離三界生死","法鏡：信佛法僧、持賢聖戒知所生處","四雙八輩與斷我見、發初禪的次第","往生極樂見瑞相，為暫離人間生死"],"k":["臨終瑞相","法鏡","解脫","四雙八輩","斷我見","往生極樂"]},"2392-a11_101":{"s":"本集說明信佛與學佛的差別：學佛是以清淨信為基礎學習成佛之法。引《大般涅槃經》三種信不具足（信而不推求、從聞不從思、信有道不信有得道者），以《信佛功德經》舍利弗「了一法、修一法、滅一法、證一法」說明真信；並依《菩薩瓔珞本業經》六入法門說明學佛須次第修菩薩行，講者並批評喇嘛教即身成佛之說。","p":["學佛以信佛為基礎，學習成佛之法","《涅槃經》三種信不具足","舍利弗了法、修法、滅法、證法","菩薩須依十信至妙覺六入法門","講者批評喇嘛教跳過信位、住位"],"k":["信佛","學佛","信不具足","六入法門","如來藏","菩薩戒"]},"2431-a11_102":{"s":"本集介紹五停心觀：貪重修不淨觀、瞋重修慈愍觀、癡重修緣起觀、慢重修界差別觀、尋思重修阿那波那念。並依《瑜伽師地論》說明阿那波那念五種修習次第，詳解數息、隨息，指出把一念不生當開悟是誤會，須進一步悟入五蘊，觀出入息中唯有五蘊諸行。","p":["五停心觀對治貪、瞋、癡、慢、尋思","不淨、慈愍、緣起、界差別觀的內容","阿那波那念五種修習次第","數息隨息只是方便，一念不生非開悟","悟入諸蘊：觀出入息中唯有五蘊"],"k":["五停心觀","安那般那念","數息","不淨觀","五蘊","瑜伽師地論"]},"2432-a11_103":{"s":"本集續講阿那波那念後段次第：悟入緣起，觀五蘊從眾緣生而無常；悟入聖諦，現觀苦集滅道而斷三縛結見道；再以十六勝行修除我執、發起初禪成三果。強調止息煩惱後仍須悟入五蘊、緣起、四聖諦，菩薩更須求證如來藏；引《佛說未曾有因緣經》說明未證言證的大妄語罪，並批評喇嘛教。","p":["悟入緣起：五蘊從眾緣生、無常","悟入聖諦，現觀四聖諦斷三縛結","十六勝行修除我執，發起初禪","菩薩見道後再參禪求證如來藏","未證言證為大妄語，墮阿鼻地獄"],"k":["五停心觀","四聖諦","斷我見","大妄語","初禪","如來藏"]},"2393-a11_104":{"s":"本集說明泰國四面佛即印度教的大梵天王，是初禪天天主。大量引述《梨俱吠陀》原人、金胎等頌，說明吠陀思想以大梵為造物主與第一義諦，種姓制度亦由此而來，而佛陀破斥種姓之說；並開始介紹佛法的三界觀，講述欲界六天直至兜率天。","p":["四面佛即大梵天王，為初禪天主","吠陀以原人、大梵為造物主與本源","種姓制度源於大梵說，佛陀破斥","佛法中大梵天為發起初禪者所生","欲界六天的次第，彌勒住兜率天"],"k":["四面佛","大梵天","吠陀經","種姓制度","三界","欲界六天"]},"2395-a11_105":{"s":"本集續講三界：說明補處菩薩住兜率天的原因、魔天介於欲界與色界之間；引《長阿含經》說明除五蓋則初禪不求自得，講者批評只教枯坐而不知修福者。再說明初禪天的等級，上品初禪者生為大梵天王，以及劫初最先生於梵天者自認為眾生父母的由來，並說吠陀天授之說源於梵天下生者的宿命記憶。","p":["兜率天不放逸亦不闇鈍，宜補處菩薩","魔天定力過欲界，但染著眷屬欲","除五蓋則初禪不求自得","初禪天分等級，大梵天王為上品","最先生梵天者自認為眾生父母"],"k":["大梵天","初禪","五蓋","兜率天","魔天","長阿含經"]},"2394-a11_106":{"s":"本集說明造物主思想源自梵天眾下生人間後於禪定中憶起宿命，而形成常與無常之見；引《長阿含經》說唯佛盡知世間由何造作。並依《大悲經》敘述佛涅槃前大梵天王來見，佛逐一詰問世界、日月、四季、色像聲音、眾生苦樂與疾病災難等是否為其所造，大梵天王一一否認。","p":["創世說源自梵天眾下生憶起宿命","唯佛盡知世間由誰造作","《大悲經》佛將入涅槃告阿難","大梵天王因佛神力見宮殿闇昧","佛詰問萬物是否梵天所造，皆答否"],"k":["大梵天","造物主","大悲經","常見","長阿含經","涅槃"]},"2397-a11_107":{"s":"本集續講《大悲經》：佛以眾生業行、苦報、生老病死、煩惱、五道輪迴等逐一詰問大梵天王，大梵天王承認自己執持邪見。佛開示世界與眾生皆是業種所造、業力所化，依十二因緣流轉，無明滅則諸苦滅，其中並無造作者；諸行如光影、如夢、如谷響，佛現不現世皆本如是。","p":["佛預見後世眾生落入斷常二見","續詰問業行苦報等皆非梵天所造","大梵天王自承執持邪見","世界眾生皆業種所造、業力所化","十二因緣流轉與還滅，無造作者"],"k":["業力","十二因緣","大梵天","大悲經","造物主","涅槃"]},"2396-a11_108":{"s":"本集續講《大悲經》：佛說智者觀諸行無常如光影夢響而厭離，證三乘菩提，皆由諸佛加持；三千大千世界是佛剎土而非梵天國土，大梵天王因而重申歸依。講者說明大梵天王因成就四無量心而為大千世界主，引平實導師《宗通與說通》談修學次第，並指四面代表慈悲喜捨，駁斥不還願遭報及四面代表財運愛情等俗說。","p":["智者觀諸行無常，證三乘菩提","佛法流布皆由諸佛加持","世界為佛剎土，大梵天王歸依","大梵天王成就四無量心","四面表慈悲喜捨，駁斥俗說"],"k":["四無量心","大梵天","四面佛","三乘菩提","大悲經","慈悲喜捨"]},"2398-a11_109":{"s":"本集說明四無量心即大梵所住的「梵堂」，引《增壹阿含經》、《中阿含經》；指出大梵天王是佛陀的主要護法，且是開悟菩薩。依《法華經》一大事因緣，說諸佛出世為開示悟入佛知見即如來藏，並以《大梵天王問佛決疑經》拈花微笑、正法眼藏付囑迦葉，說明大梵天王為此事的緣起者與證悟者。","p":["四無量心名為梵堂、梵住","大梵天王與帝釋為佛左右護法","一大事因緣：開示悟入佛知見","拈花微笑，正法眼藏付囑迦葉","如來藏非思量可及，大梵天王已證悟"],"k":["如來藏","四無量心","拈花微笑","正法眼藏","一佛乘","大梵天"]},"2519-a11_110":{"s":"本集介紹鳩摩羅什生平：父母出身、七歲隨母出家、學二乘與五明後轉學大乘，為王女講五陰十八界假名非實；並以大乘真空妙有之理度化小乘師蒲達多，師反拜其為大乘師。講者以此對比，批評現代某法師接受「空了就空了」的斷滅見；後敘呂光擄羅什、滯留涼州十七年，至401年入長安譯經。","p":["羅什父母出身與七歲隨母出家","宿慧過人，學二乘、五明後轉大乘","以真空妙有度化小乘師蒲達多","講者批評現代法師落入斷滅見","呂光擄羅什，滯涼州十七年後入長安"],"k":["鳩摩羅什","真空妙有","斷滅見","大乘","譯經","佛教史"]},"2521-a11_111":{"s":"本集續講羅什在長安十二年的譯經事業：姚興支持、逍遙園譯場、門下高徒，與慧遠書信往返成《大乘大義章》；講者認為羅什劃分大小乘，其證量少為人知，被迫婚配乃為佛法大局而合於菩薩戒，舌舍利為譯經無誤之證。並說明《阿彌陀經》、〈普門品〉、《金剛經》、《維摩詰經》等流行經典皆其所譯，且始終較玄奘譯本流行。","p":["姚興支持，逍遙園眾僧共同譯經","與慧遠書信往返成《大乘大義章》","被迫婚配，講者認為合乎菩薩戒","火化後舌不壞，為譯經無誤之證","流行經典多出羅什譯，勝於他譯"],"k":["鳩摩羅什","譯經","菩薩戒","金剛經","維摩詰經","阿彌陀經"]},"2520-a11_112":{"s":"本集續談羅什譯經的影響：其譯作涵蓋彌勒經典、《十誦律》、中觀三論、《成實論》、《大智度論》與禪經等，促成三論宗、成實宗；弟子道生倡眾生皆有佛性與頓悟。講者分析羅什譯文以通俗語言攝受眾生，譯作「觀世音」，聲韻可吟唱如〈普門品〉偈，並以《維摩詰經》的戲劇性敘事說明其吸引大眾之處。","p":["羅什譯經涵蓋經、律、論與禪經","促成三論宗、成實宗，道生倡頓悟","譯「觀世音」以通俗攝受眾生","譯文可吟唱，自嘆如嚼飯與人","《維摩詰經》以戲劇性吸引大眾"],"k":["鳩摩羅什","譯經","觀世音菩薩","三論宗","維摩詰經","普門品"]},"2503-a11_113":{"s":"本集回答因緣果報限定下是否有自由意志。引腦神經科學「決策前大腦已先活化」之說，講者認為此顯示五陰無我，大腦活化對應第七識末那的決定，五陰由第八識如來藏出生。依《雜阿含經》「有因有緣眾生有垢、有因有緣眾生清淨」，說明能抉擇見樂而染著或見苦而厭離即自由意志，而意志同時兼具自由與不自由。","p":["因緣果報限定下是否有自由意志","腦科學稱自由意志為假象","五陰無我，背後有第八識如來藏","色非一向苦樂，眾生或染著或厭離","意志同時具有自由與不自由"],"k":["自由意志","五陰無我","如來藏","末那識","因緣果報","雜阿含經"]},"2506-a11_114":{"s":"本集釐清「苦樂皆是煩惱」與「離苦得樂」的不同。依《長阿含經》說三受依觸而生滅，如兩木相攢生火；小乘所離之苦涵蓋世間苦樂，所得為滅盡蘊處界的無餘涅槃樂。大乘則實證第八識如來藏常樂我淨，破除四顛倒，成佛後於十法界自在利益眾生，是為大解脫樂。","p":["苦樂、愛恨皆為相對的煩惱","三受依觸生滅，如兩木相攢生火","小乘離世間苦樂，得無餘涅槃樂","四顛倒：誤認無常、苦、無我、不淨","大乘證如來藏，成佛得大解脫樂"],"k":["離苦得樂","涅槃","三受","四顛倒","如來藏","常樂我淨"]},"2476-a11_115":{"s":"本集以兩個目標說明學佛的最高理想：一是跨越世間種姓階級，引《長阿含經》佛破婆羅門「梵口所生」之說，修行不分種姓、四眾平等；二是跨越宗教性階級，講者對比《舊約》《新約》上帝、人、動物身分固定及永生賴恩賜之說，指出輪迴顯示眾生因第八識如來藏而本即永生，故皆可成佛；並引《悲華經》說佛以大悲於穢土成佛。","p":["學佛非獨善其身，兼利國家社會","跨越世間種姓階級，四眾平等","跨越上帝、人、動物的宗教階級","輪迴顯示眾生依如來藏而永生","佛以悲願取穢土，眾生皆可成佛"],"k":["種姓制度","平等","如來藏","輪迴","成佛","悲華經"]},"2410-a11_116":{"s":"本集討論人心性善或性惡。講者說明人與動物皆有八識心王，心性本非善非惡而可善可惡，因無明而有善惡；引《勝鬘經》「自性清淨心而有染」，以容器比喻第八識含藏七轉識的善惡心行。並解說五遍行、五別境、十一善心所、六根本煩惱與二十隨煩惱，說明成佛時善法具足、煩惱滅盡。","p":["性善性惡之辯，人與動物皆八識","心性非善非惡、可善可惡，因無明","自性清淨心而有染，如容器","五遍行、五別境為心運作基礎","善心所具足、煩惱滅盡而成佛"],"k":["八識心王","心所法","自性清淨心","如來藏","煩惱","勝鬘經"]},"1339-a01_001":{"s":"本集為系列首講，說明佛教雖有人、天、聲聞、緣覺、佛菩提五乘，節目只談三乘菩提的理由，並論證先有佛菩提乘，才分出前四乘作為成佛的階梯。最後指出三乘菩提的核心是八識論，第八識如來藏使世間與出世間因果得以成立。","p":["解脫生死比改變命運、升天更根本","佛成佛所修即佛菩提乘，大乘先於二乘","部派後的大乘興起實為第二次興起","二乘停滯不前被呵為焦芽敗種","三乘核心為八識論，第八識成就因果"],"k":["三乘菩提","五乘","八識論","如來藏","大乘起源","因果"]},"1362-a01_002":{"s":"本集說明佛教採用實證的方法，以蓮霧、顯微鏡為喻，指出實證八識需具足福德、慧力與定力。並以此回答摧邪顯正的必要、平實導師的悟境如何印證，以及大乘經典為何不需結集史等問題，主張以四大教法與法界實相檢驗經典。","p":["實證佛教即把八個識親自找出來","佛不與邪見共存，故稱正遍知","悟境由法界實相印證，如梵動經所述","四大教法：比對經典一致性並推其虛實","大乘所證可現前驗證，不需結集史"],"k":["實證佛教","八識","摧邪顯正","四大教法","大乘經典","如來藏"]},"1343-a01_003":{"s":"本集以對照表說明三界六道與解脫果的關係，指出世間與出世間因果背後皆有如來藏運作。依序講各道所相應的業，並介紹聲聞四果所斷的煩惱，以及慧解脫、俱解脫、三明六通三種阿羅漢的差別。","p":["六道各與五逆十惡、慳吝、愚癡等業相應","以飲食要求分辨天神與鬼神","初果斷三縛結，三果離欲界愛發起初禪","慧解脫為時解脫，俱解脫可非時解脫","明與通的差別在於是否了知因果"],"k":["三界六道","解脫果","四果","阿羅漢","三明六通","如來藏"]},"1356-a01_004":{"s":"本集講解聲聞菩提主要法門四聖諦，說明「聖諦」之義。苦聖諦從三苦、五苦到八苦由粗至細觀察；苦集諦指出如來藏依眾生對五陰的貪愛而出生五陰；滅諦說明滅貪愛後非斷滅；道諦以八正道過中道生活。","p":["聖諦是可驗證、令凡夫成聖的諦實理","苦苦、壞苦、行苦以冰淇淋、輕安為例","貪愛五陰，如來藏便出生五陰","滅除貪愛後如來藏獨存，非斷滅空","依八正道過不苦不樂的中道生活"],"k":["四聖諦","八苦","五陰","八正道","如來藏","無餘涅槃"]},"1341-a01_005":{"s":"本集介紹三法印（亦稱三三昧、三解脫門），引律部與《雜阿含經》說明其名稱早已存在，並解釋實證後稱為三三昧的原因。把三法印分為生滅法與不生不滅法兩組，指出不能用無常或無我含攝全部法印，而應以涅槃印含攝，即大乘一實相印。","p":["三法印是佛施設的佛法檢驗標準","律部已有三法印之名，即三三昧","諸行、諸法為生滅法，涅槃即如來藏","無常、無我無法含攝涅槃","空三昧如空杯喻，以涅槃印含攝即一實相印"],"k":["三法印","三三昧","三解脫門","涅槃寂靜","一實相印","如來藏"]},"1357-a01_006":{"s":"本集總結聲聞菩提的總相：聲聞所證是一切生滅法，而生滅法須層層依附於壽命更長者，最終必依不生不滅法才能存在。以燈光到宇宙的依附為喻，並引阿支羅迦葉與「下至女人亦能受持」等經文，說明在家出家、男女四眾平等。","p":["法界實相唯一，聲聞菩提有一總相","生滅法短者依長者，層層依附","一切生滅法必依不生不滅法而存在","須確定生滅範圍，以免落常見或斷見","在家出家、男女四眾平等可證"],"k":["聲聞菩提","生滅法","不生不滅法","如來藏","四眾平等","斷常二見"]},"1344-a01_010":{"s":"本集講斷三縛結的第一部分「三縛結的內涵」。先解釋聲聞道中煩惱的定義與貪、瞋、癡、慢、疑、惡見六根本煩惱，再說明縛與結的特性，最後逐一解說我見、戒禁取見與疑見，並舉水戒、牛戒、火戒、苦行及一念不生等為戒禁取見之例。","p":["障礙出離生死的心行皆屬煩惱","六根本煩惱與五種惡見","縛令善行不隨所欲，結能和合八苦","戒禁取見：水戒、牛戒、苦行、一念不生","疑見指對三寶與對我見的疑"],"k":["三縛結","戒禁取見","我見","疑見","根本煩惱","聲聞菩提"]},"1342-a01_011":{"s":"本集講斷三縛結的第二部分「三界中的我見」。先複習五陰功能，再列舉欲界中六種我見，如清楚明白心、觸而不了別、離念靈知、活在當下、意識細心常住、樂空雙運；接著說明色界四禪與無想定、無色界四空定若當作涅槃，都落入我見。","p":["我見：把五陰之一當成常住不滅的我","清楚明白的心是識陰與想陰","觸而不了別、離念靈知仍是意識境界","講者批評雙身法樂空雙運落入我見","四禪、無想定、四空定皆非涅槃"],"k":["我見","三界","離念靈知","識陰","四禪八定","五陰"]},"1360-a01_012":{"s":"本集講斷三縛結的第三部分「如何斷三縛結」。先以登山找入口比喻初果見道，並從我見是我慢病因、永不墮三惡道及與禪定比較等角度，說明斷三縛結的意義與好處。接著講斷法：信受三寶，了解五陰虛妄與四聖諦，相信第八識常住，再檢查戒禁取見與疑見。","p":["初果見道如找到登山入口","我見是我慢病因，斷後極七往返","斷三縛結者永不墮三惡道","須信受三寶、確認五陰虛妄","信第八識常住，方能斷我見而不怕斷滅"],"k":["斷三縛結","初果","我見","我慢","三寶","四聖諦"]},"1351-a01_013":{"s":"本集講聲聞道二果與三果的修證。說明一念無明含四種住地煩惱，我見為三界愛之根；初果斷見惑但思惑未除，以磨坊戰馬喻說明。二果須薄貪瞋癡並捨離五蓋，斷盡欲界愛即成三果並發起初禪，最後介紹初禪覺、觀、離生等功德。","p":["一念無明含見一處與三界愛住地","初果斷見惑，思惑習氣仍在","淡薄貪瞋癡、捨五蓋證二果","斷盡欲界愛證三果，同時發起初禪","果位依斷煩惱判定，不依禪定"],"k":["二果","三果","初禪","欲界愛","五蓋","一念無明"]},"1340-a01_014":{"s":"本集續講初禪的喜樂功德，並說明三果不還果的意義。以《經律異相》初果人斷欲的故事，說明初果、二果仍可能貪著欲界；並介紹三果人五類般涅槃的差異，以畢陵伽婆蹉尊者為例說明阿羅漢仍有習氣，強調四果皆以斷我見為前提。","p":["初禪色界身發起，生樂觸，禪定須依序證","三果如射出之箭，不再返回欲界","講者批評以淫欲修道之法違背正法","三果人有中般、生般等五類涅槃","阿羅漢仍有習氣，唯佛斷盡"],"k":["三果","初禪","不還果","習氣種子","斷我見","四沙門果"]},"1365-a01_015":{"s":"本集講斷三界愛我慢證四果上集，先解釋聲聞菩提、三界愛、我慢與四果的意涵，再依四聖諦、四念處觀、八正道的架構，說明五陰十八界的虛妄，並解說初果斷三縛結、二果薄貪瞋癡斷五蓋的修證內容。","p":["聲聞菩提以四聖諦、四念處、八正道修","聲聞所說我慢是樂於自我存在","識、受、想、行陰皆依他而有，虛妄","初果斷我見、疑見、戒禁取見","二果淡薄貪瞋癡、除五蓋，一往返解脫"],"k":["四果","四聖諦","四念處","我慢","五陰","三縛結"]},"1366-a01_016":{"s":"本集講斷三界愛我慢證四果下集，說明三果斷五下分結並發起初禪的兩類情形，四果斷五上分結，以畢陵伽婆蹉稱恆河神為小婢的故事說明阿羅漢仍有習氣。並回答無餘涅槃非斷滅、阿羅漢入涅槃無高下、實無人證涅槃等問題，呼籲迴小向大。","p":["三果斷五下分結，發起初禪有兩類","四果斷色、無色界貪、掉舉、慢、癡","阿羅漢斷煩惱現行，未斷習氣","無餘涅槃有本際，非斷滅空","菩薩具三德，勸聲聞行者迴小向大"],"k":["四果","五上分結","五下分結","無餘涅槃","習氣種子","迴小向大"]},"1374-a01_017":{"s":"本集簡介緣覺菩提，說明緣覺為中乘，分無佛之世的獨覺與佛世聽聞因緣法者兩種。解釋「有因有緣集世間」四句分屬流轉門與還滅門，指出因緣法須有因有緣；並說明先以十因緣逆推至「識緣名色」確認本識，再入還滅門逐支滅除，最終發現根源在無明。","p":["緣覺以因緣觀現前觀察而得解脫","獨覺薄塵薄悲；佛世聲聞再修因緣法","因緣法須有因有緣，非唯緣無因","十因緣推至識緣名色，齊識而還","還滅逐支推究，根源在無明"],"k":["緣覺菩提","因緣觀","十因緣","十二因緣","流轉門","還滅門"]},"1369-a01_018":{"s":"本集續講緣覺菩提的實證。說明緣覺先以十因緣黑品法確認本識存在而不實證，再以十二因緣還滅門逐支觀察識、六入、觸、受、愛、取、有、生皆為因緣所生，斷無明及我見我執。並區分緣生法與緣起法，指出菩薩所證因緣法甚深，不共二乘。","p":["緣覺確認本識常住但不需實證","無明即隱覆真實、顯現虛妄","逐支觀察十二支皆因緣所生無常","緣生法與緣起法內涵不同","菩薩亦須修證因緣法，智慧超越二乘"],"k":["緣覺菩提","十二因緣","無明","緣起法","緣生法","如來藏"]},"1350-a01_019":{"s":"本集說明十因緣中出生名色的入胎識不是六識。依阿含經文論證此識非意識、意根、虛空、自然、因緣或大梵天，而是本識、所知依、本際、非心心，亦即如來藏與阿賴耶識。並比較十因緣與十二因緣的識支，說明佛先說十因緣以免落入無窮過與斷滅論。","p":["入胎識是十因緣與十二因緣的關鍵","入胎識非意識、意根、虛空或梵天","又名本識、所知依、本際、阿賴耶識","十二因緣的識支是過去世六識身","先說十因緣，避免無因論與斷滅見"],"k":["入胎識","十因緣","十二因緣","本識","如來藏","斷滅見"]},"1367-a01_020":{"s":"本集說明十因緣與十二因緣中的流轉門與還滅門：十因緣的識是入胎識，不能滅；十二因緣的識是六識，是還滅的對象。講者批評一般單以十二因緣順逆觀作流轉、還滅門的做法，會落入無因論、無窮過與斷滅論，並說明十因緣的黑品、白品義與正確的觀行次第。","p":["十因緣識為入胎識，十二因緣識為六識","要滅的是入胎識受生的動力","離十因緣觀十二因緣會落無窮過","十因緣兼具黑品與白品義","先逆順觀十因緣，再觀十二因緣"],"k":["流轉門","還滅門","十因緣","十二因緣","入胎識","無因論"]},"1373-a01_021":{"s":"本集說明緣覺菩提的斷我見與斷我執，先界定我見、我執及內外我所執，說明不斷則中陰再尋受生。指出緣覺與聲聞方法不同，以十二因緣還滅；並依《雜阿含經》第287經，強調須先以十因緣觀確立八識、入胎識常住，才能無恐懼地修還滅門，以焰摩迦比丘為反例。","p":["我見是認取五陰或四陰為常恆的我","我所執分外我所與內我所","不斷我見我執，中陰仍會尋求入胎","聲聞依四聖諦，緣覺依十二因緣觀","先建立八識觀念，才能無懼修還滅門"],"k":["斷我見","斷我執","緣覺菩提","十因緣","十二因緣","八識論"]},"1372-a01_022":{"s":"本集說明緣覺法中的無明，依《雜阿含經》第287經指出，無明就是不信或否定第八識入胎識常住，而執持六識論。並說明斷我執須先斷我見，以不起語言妄想的覺知心為無我仍是錯誤；再引經說明苦集源於對諸受的貪愛，以抽煙、吸毒為喻，講者並批評雙身法助長輪迴。","p":["緣覺的無明是否定入胎識、堅執六識論","意識夜夜斷滅，必有常住心使其復起","斷我執須先斷我見","無語言妄想的覺知心仍是識陰","苦集源於對受的貪愛，如抽煙吸毒"],"k":["無明","緣覺菩提","八識論","六識論","斷我見","苦集諦"]},"1361-a01_023":{"s":"本集開始介紹佛菩提道，先以《法華經》三車喻說明三乘菩提差異，指出解脫道為三乘共道、佛菩提為大乘不共。再以「天上天下唯我獨尊」公案引出第八識如來藏，解說其非斷非常、非空非有等六種體性，以及心、所知依、種子識、阿陀那識、阿賴耶識、異熟識、無垢識等名稱，強調皆指同一心。","p":["三車喻：二乘菩提含攝於大乘菩提中","二乘證二種涅槃，大乘可證四種涅槃","唯我獨尊指每人本具的第八識如來藏","如來藏含藏業種，說明眾生差別與因果","如來藏六種體性與七種名稱，同指一心"],"k":["如來藏","佛菩提","阿賴耶識","三乘菩提","中道","四種涅槃"]},"1376-a01_024":{"s":"本集說明大乘見道即禪宗開悟明心，為佛菩提入門，並列出悟前七項條件：聞法建立知見、培植福德、受三皈與戒、減除五欲、懺悔業障深信因果、消除慢心、發大願。接著概述菩薩五十二階位：十信、十住、十行、十迴向、十地、等覺、妙覺，以及總相智、別相智、一切種智的次第。","p":["開悟明心是大乘入道之門","悟前須具備七項條件，如修福、除慢、發願","開悟是一念相應的頓悟，非漸悟","十住七住明心、十住眼見佛性","成佛需歷五十二階位，非一悟即至佛地"],"k":["菩薩五十二階位","開悟明心","大乘見道","般若總相智","一切種智","三賢位"]},"1377-a01_025":{"s":"本集講解菩薩戒的受持。先說明菩薩是發菩提心、求無上正等正覺的有情，有假名菩薩與證菩提者之別；再列舉受菩薩戒的四個理由：遠離惡法、修學善法、速積福慧資糧、速證菩提。並說明受戒前應注意的事項，以及以三聚淨戒精神持戒，強調破邪顯正也屬饒益有情戒。","p":["菩薩是發大菩提心求佛道的有情","菩薩戒是千佛大戒、成佛必經之路","受戒四理由：離惡、修善、積資糧、證菩提","應在正法道場受三皈與菩薩戒，並了解戒相","明心後得真戒體，以智慧自然持戒"],"k":["菩薩戒","三聚淨戒","菩提心","四弘誓願","戒體","明心"]},"1349-a01_027":{"s":"本集講十住位初住至五住修布施、持戒、忍辱、精進、禪定以集見道福德資糧。強調以財施護持了義正法含攝法施與無畏施，法施最殊勝；持戒說明不洩露密意、不謗菩薩藏；忍辱分三種；禪定介紹以無相念佛、拜佛修動中定力，並辨明三界九地都是意識境界。","p":["六度用以饒益有情、對治煩惱","財施護持正法，含攝法施與無畏施","持戒重點：不謗如來藏、不洩露密意","忍辱分耐怨害、安受苦、諦察法三忍","以無相念佛拜佛修動中定力、看話頭"],"k":["福德資糧","六度波羅蜜","十住位","法布施","無相念佛","動中定力"]},"1348-a01_028":{"s":"本集講六住位熏習相似般若、修集見道智慧資糧，依序說明四聖諦、十二因緣、五蘊十八界的正知見，指出苦滅的本際即如來藏，緣覺知有入胎識不滅。並說明如來藏與五蘊體性的差別，七住明心後能否轉依決定退與不退，十住時眼見佛性完成如幻觀。","p":["從五蘊無常說明四聖諦與八正道","緣覺以十因緣為本，知入胎識不滅","五蘊十八界皆如來藏藉緣所生","七住明心，能否轉依決定是否退轉","十住眼見佛性，成就身心世界如幻觀"],"k":["智慧資糧","四聖諦","十二因緣","五蘊十八界","斷我見","轉依"]},"1354-a01_029":{"s":"本集講十行位的修證（上集），先複習五十二階位與十住位內容，說明三賢位分屬習種性、性種性、道種性，並成就如幻、陽焰、如夢三觀。以水泡花鬘故事對比二乘將滅止生與大乘現觀五陰如幻的差別，說明十行位要降伏我執、轉凡夫性為聖性，並介紹初行歡喜行與二行饒益行。","p":["三賢位分習種性、性種性、道種性","三賢位分別成就如幻、陽焰、如夢觀","二乘將滅止生，菩薩現觀五陰如幻","十行位要降伏我執、長養聖性","初行歡喜行三輪體空，二行饒益行持淨戒"],"k":["十行位","陽焰觀","性種性","降伏我執","三賢位","如幻觀"]},"1355-a01_030":{"s":"本集續講十行位第三至第十行：無違逆、無盡、離癡亂、善現、無著、尊重、善法、真實行，說明各行如何依止如來藏修忍辱、精進、正念、說法等，將習種性轉為聖性種性。並提出十行位應注意的五點：培養大福德、直心摧邪顯正、尊師重道、正確理解圓融、不執著僧衣表相。","p":["三行至十行逐一依止如來藏修六度","八行如船師往返兩岸度眾而不住","十行位最難在福德累積","應直心摧邪顯正，尊師重道","圓融不是鄉愿，不應只崇拜僧衣表相"],"k":["十行位","聖性種性","福德","摧邪顯正","尊師重道","如來藏"]},"1364-a01_031":{"s":"本集介紹十迴向位，指出七住見道與初地修道是五十二階位的兩大門檻，十迴向位以金剛行救護眾生、累積福德並成就如夢觀。講者認為儒家仁愛、基督博愛及大愛仍不離愛取與我見，佛法講離我見的慈悲；並分析身我、內我、外我三種我見，說明佛法是非有我非無我，以此詮釋初迴向「救護一切眾生離眾生相迴向」。","p":["七住見道與初地修道是兩大門檻","十迴向位行金剛行，成就如夢觀","講者認為仁愛、博愛、大愛不離我見","眾生執身我、內我、外我三種我見","佛法非有我非無我，以如來藏為根源"],"k":["十迴向位","救護眾生離眾生相","我見","慈悲","如夢觀","非有我非無我"]},"1370-a01_032":{"s":"本集續講十迴向位的金剛行，說明初迴向最重要且吃力不討好，因眾生我見堅固難度，須以堅固如金剛的身口意行破邪顯正。講者列舉常見、斷見、世俗見、在欲行禪（講者批評雙身法）等順生死流的邪見，主張正邪不能並存，並辯明破邪顯正不是說四眾過或自讚毀他，最後由此成就如夢觀而入初地。","p":["十迴向皆是金剛行，初迴向最重要","眾生我見堅固，如狗反咬救它的人","邪見有常見、斷見、世俗見、在欲行禪","破邪顯正只論法義，不是說四眾過","破邪顯正中成就如夢觀，發起聖種性"],"k":["破邪顯正","金剛行","十迴向位","常見與斷見","如夢觀","我見"]},"1378-a01_033":{"s":"本集說明證入初地。先以遠、近、大三種波羅蜜多對應三大阿僧祇劫，指出初地是第二大阿僧祇劫的開始；再列出入地四緣：無生法忍、性障永伏如阿羅漢、增上意樂（十無盡願）、入地所需的大福德。並以尋寶與阿里巴巴故事說明真見道、相見道與通達位，解釋三賢位為何是外聖內凡。","p":["三大阿僧祇劫對應遠、近、大波羅蜜多","入初地須具足四緣","真見道如找到寶藏入口，相見道如逐一觀寶","初地入地心為見道通達位，住地心起為修道位","三賢位外聖內凡，初地方為聖位"],"k":["初地","無生法忍","十無盡願","真見道","相見道","三大阿僧祇劫"]},"1353-a01_034":{"s":"本集說明十地菩薩的修證，入地後於六度外加修方便、願、力、智成十波羅蜜多。初地留法貪法瞋潤生，以法施為主修百法明門；之後逐地說明主修的波羅蜜多與滿心現觀：鏡像、光影、谷響、水中月、變化所成，六地證滅盡定，七地念念入滅盡定，八地於相於土自在，九地四無礙，十地成受職菩薩。","p":["入地後修十波羅蜜多","初地留法貪、法瞋一分思惑潤生","初至五地滿心現觀：鏡像至變化所成","六地證滅盡定，七地斷盡思惑","八地相土自在，九地四無礙，十地受職"],"k":["十地","十波羅蜜多","留惑潤生","道種智","滅盡定","四無礙"]},"1346-a01_036":{"s":"本集為二乘所證涅槃上集，解釋涅槃有解脫義，列舉講者認為非真解脫的欲界、色界、無色界境界，如煉丹、求神通感應、定中幻境、雙身法、四禪八定與離念靈知等，指出都是我相，如煮砂成飯。接著說明五陰即眾生所執之我，並以聚沫、水泡、陽焰、芭蕉之喻說明色受想行四陰虛幻不實。","p":["涅槃有解脫義，須斷我見、證無我","煉丹、神通、感應等皆欲界法","四禪八定與一念不生仍是意識境界","三界境界都是五陰我相，如煮砂成飯","色如聚沫、受如水泡、想如陽焰、行如芭蕉"],"k":["涅槃","解脫","五陰","我相","四禪八定","離念靈知"]},"1347-a01_037":{"s":"本集為二乘所證涅槃下集，先說明識陰猶如幻化，再解釋涅槃有清涼、煩惱熄滅、不再生死輪迴等義。介紹聲聞與緣覺菩提、見惑與思惑，以及有餘涅槃（含三果人中般、生般、無行、有行、上流五種般涅槃）和無餘涅槃。並指出以清明覺知心、作主心或離念靈知入涅槃都是有我，涅槃本際即第八識獨住境界。","p":["識陰猶如幻化，不在內外中間","涅槃含清涼、煩惱熄滅、不再輪迴義","二乘斷見惑思惑，證有餘、無餘涅槃","三果人有五種般涅槃及其比喻","無餘涅槃非斷滅，是第八識獨住境界"],"k":["二乘涅槃","有餘涅槃","無餘涅槃","見惑思惑","五種般涅槃","涅槃本際"]},"1368-a01_038":{"s":"本集探討涅槃的意涵，指出涅槃是安隱安樂之處，不是無常法或斷滅法。詳細說明意識心有生有滅（五位中斷）、有增減、有垢淨，因此禪定境界、放下執著、五蘊空相、緣起性空、一切法空都不是涅槃。並說明如來藏不生不滅、不增不減、不垢不淨、不一不異、不斷不常的中道法性即涅槃，三乘涅槃皆依此施設，差別在智慧。","p":["涅槃是安隱之處，非無常、非斷滅","意識於五位中斷，有生滅增減垢淨","禪定、緣起性空、一切法空皆非涅槃","如來藏無漏無為的中道法性即是涅槃","三乘涅槃皆依如來藏施設，差別在智慧"],"k":["涅槃","如來藏","意識心","中道法性","本來自性清淨涅槃","緣起性空"]},"1380-a01_039":{"s":"本集論證阿賴耶識就是如來藏，引《華嚴經》「轉阿賴耶得本覺智」與《大乘密嚴經》兩段經文（阿賴耶識本來而有同於涅槃、如摩尼寶）加以解釋。並列舉聲聞經與大乘經中如來藏的各種名稱，說明阿賴耶識的能藏、所藏、執藏，及異熟識、無垢識的改名，最後辨明阿賴耶識不是意識細心，也不是外道神我或我執煩惱。","p":["引《華嚴經》：證悟時轉阿賴耶得本覺智","引《密嚴經》：阿賴耶識本有、同於涅槃","阿賴耶識如摩尼寶，與習氣合現異熟果","能藏、所藏、執藏三義及異熟識、無垢識","阿賴耶識非意識細心，亦非外道神我"],"k":["阿賴耶識","如來藏","本覺智","大乘密嚴經","異熟識","無垢識"]},"1358-a01_040":{"s":"本集講菩薩證阿賴耶識所得的智慧：根本無分別智（本覺智、總相智、般若實相智、大乘無生智），說明其無分別是指阿賴耶識本身不分別六塵，而非意識不分別。並以《心經》說明五蘊本來無生，提出後得無分別智、生死即涅槃與涅槃非修非不修的道理，並引彌勒菩薩之說，批評以緣起性空為涅槃是惡取空，源於四種顛倒。","p":["根本無分別智是證阿賴耶識的智慧","無分別指阿賴耶識不分別，非意識不分別","大乘無生是本來無生，非將滅止生","生死即涅槃，涅槃非修非不修而得","以緣起性空為涅槃被稱為惡取空"],"k":["根本無分別智","後得無分別智","阿賴耶識","大乘無生忍","惡取空","生死即涅槃"]},"1345-a01_041":{"s":"本集說明二乘所證果德，詳述聲聞四果的修證：觀五蘊無常苦空無我斷我見、疑見、戒禁取見成初果，薄貪瞋癡成二果，斷五下分結成三果，斷五上分結成阿羅漢；以及緣覺觀十二因緣、知入胎識而還滅流轉。並引《勝鬘經》《法華經》說明二乘涅槃是佛的方便施設，解脫有習氣與所知障未斷。","p":["觀五蘊無常苦空無我，斷三縛結成初果","斷五下分結成三果，斷五上分結成四果","緣覺依十因緣知入胎識，還滅十二因緣","二乘只觀現象界，所證是有上果德","引《勝鬘經》：二乘涅槃是佛方便施設"],"k":["聲聞四果","斷三縛結","五上分結","辟支佛","十二因緣","勝鬘經"]},"1359-a01_042":{"s":"本集說明大乘菩薩所證果德，並總結三乘涅槃的異同。菩薩從七住證如來藏，三賢位通達大乘人無我、法無我，入初地留惑潤生，六地證滅盡定，七地斷盡習氣，至妙覺成就無住處涅槃與四智圓明。三乘涅槃都依如來藏中道法性施設，差別在二乘不證涅槃本際，並強調不能否定如來藏、意識細心不是涅槃心。","p":["菩薩證法界實相，斷煩惱障習氣與所知障","大乘人無我、法無我不同於二乘","七地斷盡習氣，念念入滅盡定","佛地轉八識成四智，證無住處涅槃","三乘涅槃皆依如來藏，不能否定涅槃心"],"k":["大乘果德","無住處涅槃","四智圓明","人無我法無我","三乘涅槃異同","如來藏"]},"1383-a02_001":{"s":"本集論證「大乘是佛說」，引《雜阿含經》卷44婆四吒婆羅門尼「遙見世尊即得本心」，說明本心即第八識如來藏，顯示阿含中已有世尊說般若系大乘經的記錄。並對比《金剛頂經》「持真言成佛」「自心形如月輪」及後世應成、自續中觀說法紛歧，講者據此主張應說「秘密大乘非佛說」，並以二乘人未證如來藏解釋三乘同聞大乘而結集為阿含。","p":["大乘非佛說常以變相說法出現，講者指其自相矛盾","婆羅門尼遙見世尊即得本心，本心指第八識如來藏","證如來藏知眾生永不分離，故不再思子發狂","《金剛頂經》持咒成佛、自心如月輪與阿含及大乘不符","二乘人未證如來藏，故將所聞大乘結集為阿含"],"k":["大乘是佛說","如來藏","阿含經","三乘同聞","密續","中觀"]},"1391-a02_002":{"s":"本集續談「大乘非佛說」的各種變相說法及其錯誤：講者指出主張者多不主張實證，並批評以考證、文字比對研究佛法的方法。引《長阿含》卷12舍利弗所說三世諸佛與「佛總相法」（緣與無緣法），駁斥否定十方佛與極樂世界的人間佛教說；又引《增一阿含》卷49如來十力、四無所畏，反駁「佛即阿羅漢」及無髮髻佛像之說。","p":["二乘人亦須承認如來藏，否則落入斷見或常見","不生不滅法只能實證，考證與文字比對是錯誤方法","阿含稱菩薩為尊者、大士，並非無菩薩","三世諸佛與佛總相法：生滅法與不生不滅法","如來十力、四無所畏非二乘所及，佛不等於阿羅漢"],"k":["大乘非佛說","人間佛教","佛總相法","如來藏","十力四無所畏","阿含經"]},"1381-a02_004":{"s":"本集講解一念無明，即二乘所斷的見惑、思惑、我見我執煩惱，依《勝鬘經》說為四住地煩惱：見一處住地、欲界愛、色界愛、無色界愛住地，並逐一舉例其內容。說明眾生覺知心與四住地煩惱剎那相應，睡眠昏迷時仍有末那識恆審思量；阿羅漢亦有習氣種子隨眠現行，眾生因此一念無明而不斷造業輪迴。","p":["一念無明即見惑思惑、我見我執，二乘所斷","四住地煩惱：見一處住地及三界愛住地","見一處住地含身見、邊見、邪見、見取見、戒禁取見","眠熟昏迷時末那識仍相應煩惱","阿羅漢習氣隨眠仍可現行，如畢陵、迦葉、難陀"],"k":["一念無明","四住地煩惱","勝鬘經","見惑思惑","末那識","習氣種子"]},"1382-a02_005":{"s":"本集續講一念無明如何使眾生造業、生起中陰、投胎、退失禪定及無想天人下墮。接著解說無始無明即所知障、塵沙惑、法我見法我執，障礙菩薩證佛菩提與無住處涅槃；依《勝鬘經》五住地煩惱，說明二乘只斷前四，而無始無明須經五十二位、約三大無量數劫才斷盡，並說明相應、打破無始無明及上煩惱的意涵。","p":["一念無明令眾生造業、起中陰、入胎、退出定境","無始無明即所知障、塵沙惑、法我見法我執","對世間與出世間一切境界實相無知即無始無明","二乘斷四住地，無始無明須三大無量數劫斷盡","破參明心證如來藏即打破無始無明，並起上煩惱"],"k":["無始無明","所知障","一念無明","五住地煩惱","勝鬘經","明心"]},"1386-a02_006":{"s":"本集以經典及禪宗祖師所悟心體論證八識論為佛說正法。引《入楞伽經》卷8列八識，說明各識體性，並指三轉法輪所說阿賴耶識、異熟識、無垢識，二轉法輪的非心心、無住心，以及初轉法輪的無餘涅槃本際與入胎識，皆指第八識。並以「八個兄弟共一胎」偈說明祖師所證。講者批評六識論與將七八識說為意識細心的說法，並認為六識論起因於第八識行相微細難證。","p":["《入楞伽經》明說八識，各有體性","三轉法輪所說諸心異名皆指第八識","禪宗祖師悟後現觀八識，如八兄弟偈","講者批評兩種中觀派分落常見、斷見","第八識行相微細難證，菩薩具三德、阿羅漢唯解脫德"],"k":["八識論","六識論","第八識","阿賴耶識","中觀","禪宗"]},"1387-a02_007":{"s":"本集講六識論的過失：六識由根塵相觸而生，非常住法，以睡眠、昏厥、正死位、無想定、滅盡定、麻醉為例證明可斷，並引經說意識「境界分段計著生」，六識不離受、想、行陰。講者批評六識論使藏傳佛教雙身法合理化，對其名相與主張提出批判；最後說明唯八識論能令人證三乘菩提，佛菩提可證四種涅槃。","p":["六識為根塵相觸所生，第八識為萬法根源","眠熟、悶絕、正死、二無心定、麻醉時六識皆斷","六識是境界法，不離受想行陰","講者批評雙身法借用佛法名相並主張樂空雙運","八識論方能證三乘菩提，佛菩提具四種涅槃"],"k":["六識論","八識論","意識","雙身法","涅槃","三乘菩提"]},"1388-a02_008":{"s":"本集為「雙身法非佛法」上集，先重申八識論，再引述藏傳佛教相關著作內容，講者據此主張男女雙修源自印度教外道法，不能斷結證果。依講者所述的歷史，說明佛滅後部派時期引入印度教思想（含應成派所用辯論方法），坦特羅思想被轉寫成密續、另立金剛乘，經寂護、蓮花生入藏並主導後來的西藏佛教，並舉密續所述即身成佛的修法加以批評。","p":["佛所說為八識論，否定七八識將成斷滅論","講者引藏傳著作，主張雙修為外道法不能證果","部派時期引入印度教法，應成派辯論法源於此","坦特羅思想轉寫為密續，另立秘密乘、金剛乘","講者批評以儀式即身成佛、以性交大樂為空性"],"k":["雙身法","坦特羅","密續","藏傳佛教","應成派中觀","八識論"]},"1389-a02_009":{"s":"本集為「雙身法非佛法」下集，從解脫道四果四向、定學、戒學及菩薩五十二位逐一檢視雙身法。講者認為其以意識領受覺受、增長身見我見，違背斷三縛結與離欲界愛的要求，無法發起初禪，並舉畢陵尊者案說明犯戒在於起心動念，認定其犯邪淫重戒；又批評其以意識細分當作如來藏，主張真正的秘密是證如來藏，並呼籲佛弟子遠離。","p":["雙身法以意識領受覺受，講者認為增長我見身見","淫樂屬欲界粗重法，與二果三果、初禪相違","畢陵尊者案：犯戒與否在於起心動念","講者認為其以意識細分當作如來藏，不能證悟","真正秘密是證如來藏，如拈花微笑"],"k":["雙身法","斷我見","戒律","解脫道","如來藏","邪淫戒"]},"1390-a02_010":{"s":"本集講大乘入道即實證第八識法界實相心如來藏：如來藏是因果所依、收藏善惡業種，證此方入內門修六度。說明行善、修禪定、證四聖諦苦空無常皆非大乘入道；從佛的福德莊嚴與智慧莊嚴、一切種智、四智圓明的次第，說明須以親證如來藏為基礎，並介紹十信至七住的修學次第及正覺同修會禪淨班。","p":["實證如來藏方為入道，否則僅外門修六度","行善、修禪定、證四聖諦皆非大乘入道","如來藏收藏業種，為福德因果所依","一切種智、四智圓明須以證如來藏為基礎","六住圓滿後七住證法界實相心，成入內門菩薩"],"k":["大乘入道","如來藏","一切種智","四智圓明","七住位","六度"]},"1393-a02_011":{"s":"本集說明禪宗以證悟如來藏為標的，引《大梵天王問佛決疑經》拈花微笑、付囑正法眼藏，說明如來藏是諸佛密意，非思量能測，並述持戒顯佛性、如來無漏性戒，以及佛預記滅後有人說大乘非佛說。再以大慧宗杲與應菴、宏智禪師的交往，講者批評某學者所述大慧與宏智的傳聞不實，最後舉大慧竹箆話頭作結。","p":["八萬四千法門皆指向如來藏，禪宗直指心性","拈花微笑付囑正法眼藏，即如來藏密意","持戒顯佛性，證悟者得如來無漏性戒","佛預記滅後有人說大乘非佛說壞正法","大慧與宏智互敬，講者指相關負面傳聞不實"],"k":["禪宗","如來藏","正法眼藏","大梵天王問佛決疑經","大慧宗杲","明心見性"]},"1384-a02_012":{"s":"本集從「三界唯心，萬法唯識」論證玄奘菩薩所弘為八識論。引《華嚴經》「心如工畫師」「應觀法界性，一切唯心造」，說明意識屬識蘊、被出生且可斷，不能出生五蘊及十八界，能生三界一切法者為如來藏。並引《八識規矩頌》「受熏持種根身器，去後來先作主公」及《成唯識論》，說明世間與出世間法皆依第八識成就。","p":["心如工畫師：能生五蘊者非意識而是如來藏","意識依根塵而生，無想天無意識可證其可斷","觀十八界緣生性，知有能生之心即佛心","《八識規矩頌》明說八識，第八識去後來先作主公","《成唯識論》：世出世間法皆依第八識成就"],"k":["三界唯心","萬法唯識","八識論","玄奘","如來藏","八識規矩頌"]},"1392-a02_013":{"s":"本集講完整的佛法不可支離：心善良、行善救災、打坐修定、一念不生、二乘解脫等都只是部分，以偏概全即是誤會。說明人天乘、聲聞緣覺乘、佛乘分屬世間、出世間、世出世間法，完整佛法須三乘菩提不分家；又須戒定慧三無漏學俱修，引《楞嚴經》攝心為戒、因戒生定、因定發慧，並以四依法為智慧揀擇。","p":["行善、救災、修定、一念不生皆非完整佛法","阿羅漢不敢自稱成佛，二乘解脫亦非完整","五乘依世間、出世間、世出世間法分類","三乘菩提不可分家，須具八識論","戒定慧三無漏學俱修，依四依法揀擇"],"k":["完整佛法","三乘菩提","三無漏學","戒定慧","四依法","五乘"]},"1443-a03_001":{"s":"本集為念佛法門系列開端，指出念佛常被輕視或誤解，並從「學佛的目的」談起。講者以心理學實驗說明認知影響情緒，以鏡與影像譬喻三種人，說明須依摩訶般若轉變認知，找到恆不生滅的「摩尼寶珠」，以了生死、除煩惱。","p":["念佛法門普遍被輕視或誤解","生死恐懼與煩惱之苦皆因認知而起","摩訶般若波羅蜜即依大智慧轉變認知","鏡影三喻：解脫智慧與實相智慧之別","五陰與我所如寶珠上影像，生滅不實"],"k":["學佛目的","摩尼寶珠","解脫智慧","實相智慧","般若","五陰"]},"1444-a03_002":{"s":"本集承上集，引《法華經》「開示悟入佛知見」及「欲令一切眾，如我等無異」，說明摩尼寶珠即第八識如來藏，學佛最終目的在成佛。並以十法界判定一神教、神道教神祇屬欲界天凡夫境界，指出二乘只修解脫道非真正學佛，只求平安富足則如窮子。","p":["開示悟入佛知見為佛出世一大事","摩尼寶珠即第八識如來藏","學佛的最終目的是成佛","他教神祇屬欲界天，未出三界輪迴","二乘只修解脫道，非真正學佛"],"k":["如來藏","成佛","法華經","十法界","三界六道","二乘"]},"1428-a03_003":{"s":"本集以信、進、念、定、慧五根五力說明佛法實修次第，引平實導師開示指出凡夫入見道須先收攝心念，念佛法門為最好方法。並解說六念以念佛為首、「念佛一聲滅八十億劫生死重罪」的道理，提出佛有無量且具三身，念哪尊佛、如何念須深入了解。","p":["五根五力代表佛法實修過程","凡夫入見道須先收攝心念","六念之中以念佛最為殊勝","念念清淨繫念佛，能滅罪障","佛有無量且有三身，念法有學問"],"k":["五根五力","六念","念佛","收攝心念","佛三身"]},"1475-a03_004":{"s":"本集說明佛三身中真佛為法身，並依根器知見略述念佛層次：隨興持名、念佛不輟、持名憶佛至有相念佛三昧、觀想念佛、《楞嚴經》大勢至章的無相念佛、體究念佛、明心的果地無相念佛，至見性的實相念佛。勸念佛人勿互相批評，並強調修淨土也需動中功夫。","p":["應化身、報身非真佛，法身為真佛","持名念佛由隨興持名到有相念佛三昧","觀想念佛與《楞嚴經》無相念佛","體究念佛：明心為果地無相，見性為實相念佛","各層次皆是念佛，勿互相排斥"],"k":["念佛層次","無相念佛","體究念佛","實相念佛","念佛三昧","大勢至念佛圓通章"]},"1451-a03_005":{"s":"本集說明求生極樂應求上品上生，須發至誠心、深心、迴向發願心。並整理念佛法門四種殊勝：容易修學、三根普被、現世得利（淨化三業、五逆可往生、修除慢心）、果報殊勝（必定往生、易入實相念佛、具足戒定慧）。最後指出各法門終與第一義相應，念佛即修禪。","p":["求生極樂應以上品上生為目標","念佛容易修學且三根普被","現世得利：淨化三業、修除慢心","念佛具足戒定慧：事一心與理一心","禪是般若非定，念佛即是修禪"],"k":["禪淨圓融","念佛殊勝","九品往生","戒定慧","事一心理一心","至誠心"]},"1417-a03_006":{"s":"本集開始講求生淨土信、願、行三資糧中的「信」。講者以移民為喻，說明須信佛四智圓明、極樂世界存在且莊嚴、往生容易、彌陀壽命無量；並將信分為迷信、仰信、解信、證信。講者批評以阿彌陀佛為太陽神崇拜轉化之說是神佛不分，並以如來藏能變現器世間說明解信。","p":["信願行三資糧，信為首要","信佛四智圓明與極樂世界真實存在","信分迷信、仰信、解信、證信","講者批評太陽神轉化說為神佛不分","如來藏能變現器世間，為解信之理"],"k":["三資糧","信","四智圓明","極樂世界","如來藏","神佛之別"]},"1418-a03_007":{"s":"本集續講「信」，引《大寶積經》、《稱揚諸佛功德經》說明往生極樂不只見於淨土五經，並說由解信進至證信須依善知識實證如來藏，引《華嚴經》「信為道元功德母」偈。後講「願」，分邪願、惡願、許願、善願、正願；講者指誅法、五雷轟頂之誓非佛教，惡願無拘束力，正願又分小願與大願。","p":["多部經典皆說聞名信樂可往生極樂","證信須依善知識實證第八識如來藏","信為道元功德母，能長養善法","邪願、惡願非佛法，惡願無拘束力","正願分小願與大願，以發心大小區分"],"k":["證信","發願","正願","如來藏","華嚴經","邪願惡願"]},"1480-a03_008":{"s":"本集說明二乘只求入無餘涅槃是最小的願，勸大眾發願往生極樂並以斷我見、明心提升品位，發願須出口成願。接著介紹「行」分事行與理行，並開講三福淨業第一福：孝養父母（不剋扣供養、令父母安心、不修雙身法、安頓家庭）、奉事師長（不同儒家為親賢諱而不勸）及慈心不殺。","p":["二乘入無餘涅槃為最小之願","發大願提升品位，發願須出口成願","行分事行與理行","孝養父母：不剋扣供養、令父母安心","奉事師長應以正法勸導，最大回報是引入解脫"],"k":["三福淨業","孝養父母","奉事師長","發願","慈心不殺","事行理行"]},"1438-a03_009":{"s":"本集續說慈心不殺，指一切眾生可能是過去的父母師長，不應殺害或隨喜殺業；並說明修十善業、避免十惡業以積人天福德。接著進入第二福「受持三歸」，以學校校規比喻三歸依戒，解釋「十方薄伽梵、圓滿修多羅、大乘菩薩僧」偈，並說明天魔常慈眉善目，以人天善法拘束人不求解脫。","p":["眾生皆可能是過去父母，不應殺害","不隨喜殺業，修十善業積人天福德","三歸依如進入佛法學校的校規","三寶偈：佛、法、大乘菩薩僧功德難思","天魔以人天善法拘束人，非佛法全部"],"k":["三歸依","慈心不殺","十善業","三寶","天魔外道"]},"1440-a03_010":{"s":"本集解說「歸依法，終不歸依外道邪說」：法是軌則，須符合因果且可實證；「歸依僧，終不歸依外道徒眾」：否定佛與第八識者非僧寶，歸依僧是歸依十方大乘菩薩僧團。並說三歸依即《阿含經》的四不壞淨，講者認為主張雙身法或諸教皆同者不成三歸，引《雜阿含經》說成就四不壞淨不墮三惡道。","p":["法是軌則，須符合因果且可實證","否定佛與第八識者非真僧寶","學佛須能分辨善惡是非","三歸依即四不壞淨，佛法僧皆清淨有戒","成就四不壞淨則不墮三惡道"],"k":["三歸依","四不壞淨","外道邪說","僧寶","雜阿含經","因果"]},"1439-a03_011":{"s":"本集強調受三歸前應先了解道場對佛、法、僧與戒法的說法。說明世間三寶為佛像、經典與出家四眾，引《大方便佛報恩經》指不受三歸則一切戒不得，並解釋戒體即清楚了知持守的範圍。接著講出世間佛寶的法身、自受用與他受用報身、應身、化身，最後點出出世間法寶為四諦、緣生、六度。","p":["受三歸前應先了解道場所說","世間三寶：佛像、經典、出家四眾","不受三歸依，則一切戒皆不得","戒體即清楚了知應持守的界限","佛三身：法身、報身、應身與化身"],"k":["世間三寶","出世間三寶","戒體","佛三身","三歸依"]},"1442-a03_012":{"s":"本集解說出世間法寶：聲聞的四聖諦、緣覺的十二因緣、菩薩的六度詮旨，指六度皆依如來藏成立，菩薩布施即是解脫。出世間僧寶為四向五果及三賢十地，以實證智慧而非外相論位階。講者並回應「白衣說法」的批評，主張出家眾請不信三寶的學術界人士講法才是白衣說法。","p":["四聖諦為聲聞所修，滅盡生滅入無餘涅槃","緣覺修十二因緣，知有入胎識","六度皆依如來藏而成立，菩薩亦有解脫","出世間僧寶：四向五果與三賢十地","僧寶依智慧不依外相；白衣說法之辨"],"k":["出世間三寶","四聖諦","十二因緣","六度","僧寶","三賢十地"]},"1441-a03_013":{"s":"本集講自性三寶（同體三寶）：自性佛即第八識真如，無量壽、無量光表如來藏永恆與遍知因果的功德，非太陽神；自性法寶為如來藏記藏業種、運作因果；自性僧寶依如來藏清淨性而不欺眾生。說明三種三寶互相成就；講者並批評喇嘛教四歸依、上師超越三寶及活佛法王之說違反三歸依戒。","p":["自性佛即第八識真如法身","無量壽、無量光表如來藏的功能德用","如來藏記錄業因，因果終必實現","自性、出世間、世間三寶互相成就","講者批評四歸依與活佛法王之說"],"k":["自性三寶","如來藏","無量光","因果","三歸依","四歸依"]},"1430-a03_014":{"s":"本集補充三歸依的錯誤說法：講者批評某些宗教盜用三寶名相為玄關口訣、以五雷轟頂拘束人，以及「彌勒掌天盤」違背世尊預記；強調佛法僧不可切割，只歸依佛、只歸依法或只歸依僧都不成三歸。接著講具足眾戒中的五戒：不殺（勸素食或吃三淨肉）、不偷盜、不邪淫（出家戒以不淫為首）。","p":["三寶無秘密，以秘密拘束人非佛法","講者指「彌勒掌天盤」違背世尊預記","佛法僧三寶不可切割歸依","五戒保得人身，首重不殺人","三淨肉；出家戒以不淫為第一"],"k":["三歸依","五戒","具足眾戒","三淨肉","不邪淫"]},"1434-a03_015":{"s":"本集續講不妄語戒（含兩舌、惡口、綺語），重在不犯未悟言悟的大妄語，並指法義辨正非惡口；再略說不飲酒為遮戒，及八關齋戒、聲聞戒、菩薩戒與不犯威儀。後半引《佛說無量壽經》說明以疑惑心修功德、不了佛智者生極樂邊地胎生，五百歲不見佛法僧，勸行者完全信受佛語。","p":["不妄語戒重在不犯大妄語","法義辨正是提供資訊，非惡口","八關齋戒、菩薩戒，在家出家皆可受","疑惑佛智者生極樂邊地胎生","胎生五百歲不見佛、不聞法、不見聖眾"],"k":["邊地胎生","不妄語","五戒","菩薩戒","無量壽經","佛智"]},"1469-a03_016":{"s":"本集引《大乘無量壽莊嚴經》說智慧微淺者以為西方不及天界而不求生，講者並引釋印順《淨土新論》的太陽崇拜說加以批評。再依「唯除五逆、毀謗正法」之願與《觀經》下品下生，說明五逆尚有開緣、謗法則不攝；引《大般若經》說毀謗甚深般若即否定如來藏，並說極樂菩薩皆現天人相，勿執外相。","p":["智慧淺者以為西方不及天界而不求生","講者批評阿彌陀佛為太陽崇拜之說","五逆遇善知識十念稱佛尚可往生","毀謗正法即否定如來藏，不得往生","極樂聖眾皆現天人相，勿執著外相"],"k":["毀謗正法","如來藏","五逆","般若波羅蜜","下品下生","往生極樂"]},"1473-a03_023":{"s":"本集依《念佛三昧修學次第》講理行第二資糧：建立定的知見。說明念佛法門三根普被、種類眾多；持名念佛由心念心聽進到心念心憶時，須知捨去佛號、專憶佛念，否則停滯或誤入無覺知定境。強調要成就動中定力而非享受定境，以爬山駐足看風景為喻，並辨淨念相繼與淨念斷續。","p":["念佛法門三根普被，不限持名","缺乏定的知見則不知轉折而停滯","心念心憶時應捨佛號、專憶佛念","要的是定力非定境，無覺知定不利往生","淨念相繼與淨念斷續之別"],"k":["定的知見","憶佛念佛","無相念佛","淨念相繼","定力","體究念佛"]},"1472-a03_024":{"s":"本集講理行第三資糧：深解第一義知見，須讀大乘了義經以了解自性彌陀（真如、第八識），空有不二而非斷滅空。說明不同品位所需條件；講者批評只取一願的選擇本願念佛及獨尊淨土排斥禪法的觀點，並引經說往生後仍須修學、勿執佛名相。總結理行三資糧，指體究念佛即參禪。","p":["第一義即自性彌陀，空有不二","誤解空為斷滅，即落斷滅外道見","講者批評只取一願、排斥禪法之說","往生極樂後仍須隨佛繼續修學","理行三資糧；體究念佛即是參禪"],"k":["第一義","自性彌陀","體究念佛","參禪","九品往生","大乘了義經"]},"1419-a03_025":{"s":"本集依《觀無量壽佛經》講上品上生：須具至誠心、深心、迴向發願心，或慈心不殺具諸戒行、讀誦大乘、修行六念。講者主張三心須真實證悟並轉依成功才易發起，錯悟者易生慢心。並說明上品上生者乘金剛臺彈指往生、即悟無生法忍、歷事諸佛次第受記，所證深淺依此世熏修而異。","p":["上品上生須具至誠心、深心、迴向發願心","三心須真悟且轉依成功才易發起","錯悟者易生慢心，誤以為一悟即成佛","乘金剛臺往生，聞法即悟無生法忍","歷事諸佛受記，所證依此世熏修而異"],"k":["上品上生","三心","觀無量壽佛經","無生法忍","轉依","九品往生"]},"1421-a03_026":{"s":"本集依《觀無量壽佛經》講上品中生：不必受持方等經典，但須善解義趣、於第一義心不驚動、深信因果並成就四不壞信、不謗大乘，再具體迴向發願。並說明西方三聖持紫金臺來迎、讚其行大乘解第一義，紫金臺經宿乃開，勸人平時養成讚佛禮佛習慣，自力他力相合。","p":["上品中生條件：善解義趣、第一義心不驚動","深信因果則歸依三寶，成就四不壞信","毀謗大乘是往生最大障難","西方三聖持紫金臺來迎，讚其解第一義","紫金臺經宿乃開，平時應養成讚佛習慣"],"k":["上品中生","觀無量壽佛經","四不壞信","不謗大乘","第一義諦","迴向發願"]},"1422-a03_027":{"s":"本集續講上品中生：往生前須多聞熏習第一義諦，花開聞法方能相應；介紹禮佛規矩與問訊本義，引《華嚴經》說娑婆一劫為極樂一日一夜，上品中生七日得不退、一小劫得無生法忍。後講上品下生：信因果、不謗大乘、發無上道心，五百化佛持金蓮華來迎，一日一夜花開。","p":["宿習第一義諦，往生聞法方能相應","禮佛規矩：合掌、胡跪、問訊、懺悔、迴向","娑婆一劫為極樂世界一日一夜","上品下生：信因果、不謗大乘、發無上道心","五百化佛持金蓮華來迎，坐已華合"],"k":["上品中生","上品下生","無上道心","多聞熏習","禮佛儀軌","四弘誓願"]},"1420-a03_028":{"s":"本集講完上品下生（七日見佛、三七日了了見、三小劫入初地）並比較上品三生時劫差異；再講中品：中品上生持五戒八戒、不造五逆，佛與比丘眾來迎說苦空無常，花開即成阿羅漢；中品中生一日一夜持戒無缺，七日花開得初果；中品下生孝養父母、行世仁義，臨終須遇善知識。","p":["上品三生修證時劫差異甚大","中品攝受偏聲聞種性的念佛人","中品上生持戒不造五逆，花開即成阿羅漢","戒香逆風而行，成就七聖財中的戒財","中品下生孝養父母，臨終須善知識"],"k":["九品往生","中品上生","中品中生","持戒","五逆","解脫道"]},"1424-a03_029":{"s":"本集講中品下生臨終須善知識開示彌陀四十八願，講者批評說阿彌陀佛是太陽崇拜淨化者不能為人助念；比較上、中品往生在種性、接引與果德上的差異。再講下品上生：作眾惡無慚愧但不謗大乘，臨終聞大乘經名除千劫惡業、稱佛名除五十億劫罪，四十九日花開、十小劫入初地。","p":["中品下生須善知識講四十八願與極樂莊嚴","講者批評以極樂為太陽崇拜者非善知識","上品大乘種性、中品聲聞種性之比較","引《增一阿含》說慚愧二法擁護世間","下品上生聞經名、稱佛名而滅重罪"],"k":["中品下生","下品上生","善知識","慚愧","稱名念佛","不謗大乘"]},"1423-a03_030":{"s":"本集講下品三生：下品上生花開後十小劫入初地；下品中生破戒、盜僧物、不淨說法，臨終聞善知識讚佛十力及戒定慧，地獄火化涼風，六劫花開發無上道心；下品下生五逆十惡，苦逼不能憶佛，稱名十念往生，十二大劫花開。並會通《無量壽經》「唯除五逆、誹謗正法」：五逆可下品下生，謗法則難救。","p":["下品上生花開聞法，十小劫入初地","下品中生聞善知識讚佛與戒定慧滅罪","下品下生苦逼不能憶佛，稱名十念往生","會通《無量壽經》唯除五逆謗法之說","念佛法門三根普被，具事行與理行"],"k":["下品三生","五逆十惡","謗法","稱名念佛","觀無量壽佛經","三根普被"]},"1450-a03_031":{"s":"本集開啟念佛三昧入門，說明須具信、願、行三資糧：信佛語真實、極樂實有、彌陀四十八願；願須遠離惡願、世俗願與自了小願，發切實可行、隨念佛次第提升的菩薩大願；行分事行（三福淨業、功夫）與理行（植德修除慢、建立定慧知見、深解第一義）。信願行如鼎三足，互相增上。","p":["信為道元功德母，是願與行的基礎","發願應為利樂眾生且切實，不打高空","願隨有相、無相、體究、實相念佛提升","事行含三福淨業與功夫，理行含定慧知見","信願行如鼎三足，轉轉增上"],"k":["信願行","念佛三昧","發願","三福淨業","事行理行","自性三寶"]},"1449-a03_032":{"s":"本集說明念佛三昧是以念佛將心制於一處，一心不亂分兩層：事一心（持名、觀想、無相念佛成就定力）與理一心（明心見性後時時觀照自性彌陀）；「一句佛號概括事理」須明心見性後方堪說。並列出本系列將介紹的八種念佛法門，講持名念佛的意義、所念之佛與「萬修萬人去」之殊勝。","p":["一心不亂分事一心與理一心","一句佛號概括事理須明心見性後方可說","念佛法門非僅持名，不應貶抑他法","後續將介紹持名、觀像、觀想等八種念佛","持名念佛仗彌陀願力，萬修萬人去"],"k":["念佛三昧","事一心","理一心","持名念佛","一心不亂","自性彌陀"]},"1455-a03_033":{"s":"本集講持名念佛四次第：隨緣念佛、心念心聽、心念心憶、一行三昧。分析停在隨緣念佛是因缺正信、貪著五欲、常換方法；了解念佛真義與極樂依正莊嚴並懺悔發願後，可轉入心念心聽，消妄想、成有相念佛三昧；再細察憶佛之念轉入心念心憶，並須深信了義法方能修一行三昧。","p":["持名四次第：隨緣、心聽、心憶、一行三昧","隨緣念佛因缺正信、貪著五欲而不得力","心念心聽能消妄想，成有相念佛三昧","心念心聽易偏於定，須察憶佛之念","心念心憶後深信了義法，方入一行三昧"],"k":["持名念佛","心念心聽","心念心憶","隨緣念佛","一行三昧","五欲"]},"1452-a03_034":{"s":"本集講持名念佛一行三昧：功夫不足則往生「人人有希望，個個沒把握」；引《大寶積經》「法界一相，繫緣法界」，解釋法界一相即一真法界的真如一相，一行三昧即淨土禪，由淨入禪求明心見性。再引《六祖壇經》說一行三昧是常行直心，直心指真如心而非意識修到一念不生，執常坐不動則同無情、成障道因緣。","p":["念佛功夫不足則往生無把握","一行三昧：法界一相，繫緣法界","法界一相指一真法界的真如一相","直心是真如心，非意識修到一念不生","一行三昧定慧等持，不是定境"],"k":["一行三昧","淨土禪","法界一相","直心","六祖壇經","一念不生"]},"1454-a03_035":{"s":"本集講入一行三昧的兩個先決條件：先聽聞了解般若波羅蜜（如先看地圖），及具足心念心聽、心念心憶功夫。以《心經》不垢不淨會通《勝鬘經》「自性清淨心而有染污」，講者批評視《勝鬘經》為偽經之說；引《大寶積經》繫心一佛、專稱名字、念念相續，解釋都攝六根，並以廣欽老和尚「一頓」說明念佛三昧不是停止的定境。","p":["入一行三昧須先聞般若波羅蜜","不垢不淨即自性清淨心而有染污","般若理體於一切智無增無減、無所執受","繫心一佛、專稱名字、念念相續","廣欽老和尚「一頓」非停止的定境"],"k":["一行三昧","般若波羅蜜","大寶積經","勝鬘經","都攝六根","心念心憶"]},"1453-a03_036":{"s":"本集續講一行三昧「念中能見三世諸佛」：如來智慧德相即真如相，是真正佛母，明心見性者見眾生佛性即見未來佛，三世諸佛皆乘一如；講者並批評以雙身法解釋「佛母」。講完持名後轉入觀像念佛：須具定力並深解第一義，目的在入體究念佛見自心如來；開始引《大寶積經》大精進菩薩見畫像發願、絕食求出家的經過。","p":["如來智慧德相即真如相，為真正佛母","見眾生佛性即見未來諸佛","持名念佛三根普被，參禪者亦勿輕視","觀像念佛須定力並深解第一義","大精進菩薩見佛畫像，發願出家"],"k":["一行三昧","觀像念佛","如來智慧德相","大精進菩薩","心佛眾生三無差別","大寶積經"]},"1489-a03_037":{"s":"本集續講《大寶積經》大精進菩薩觀像念佛：不食七日唯憶正遍知身，入深山對畫像觀佛，林神示「觀此畫像不異如來」。菩薩次第思惟畫像非覺非知、但有名字、非覺非作、非見非聞，一切諸法與如來身相亦如是；講者藉此闡釋法不離有相無相、生滅與不生滅和合，能覺知者是眾生覺知心，離真如談緣起性空則落斷滅。","p":["大精進菩薩唯憶念如來正遍知身","林神：觀此畫像不異如來，是名觀佛","畫像非覺非知，一切諸法亦復如是","法是生滅與不生滅和合，空有不二","能覺知諸法的是眾生的覺知心"],"k":["觀像念佛","大精進菩薩","非覺非知","緣起性空","真如","大寶積經"]},"1488-a03_038":{"s":"本集講完大精進菩薩觀像念佛：思惟畫像非三界所攝、非取非捨、非實非虛、非生死非涅槃，以顯如來藏體性，並說「方便有多門，歸元無二路」。菩薩一晝夜得五通、四無量心、普光三昧；再解釋「不被袈裟、不見佛、不受禁戒」：真出家是心離五陰宅，並分四種出家，真佛是無形法身，禁戒因五陰而設。","p":["畫像非三界攝，事有分別理不離如","方便有多門，歸元無二路","如來藏非取非捨、非實非虛","真出家是心離五陰，出家有四種","真佛為無形法身，禁戒因五陰而設"],"k":["觀像念佛","大精進菩薩","如來藏","真出家","法身","五陰"]},"1486-a03_039":{"s":"本集講觀想念佛的緣起：阿闍世王囚父，韋提希夫人請佛而說《觀無量壽佛經》十六觀，前十三觀理事兼備，後三觀講九品往生，並略述各品花開與證果時劫。講者列舉大乘非佛說、淨土為太陽崇拜轉化、如來藏似神我、阿賴耶識是生滅法等說法，批評為謗法；最後提供先想後觀、分段練習、參考圖像、動靜憶持等善巧。","p":["韋提希夫人因緣，佛說十六觀","前十三觀理事兼備，後三觀講九品","略述九品往生花開與證果時劫","講者批評大乘非佛說等說法為謗法","先想後觀、分段練習、動靜憶持不忘"],"k":["觀想念佛","觀無量壽佛經","韋提希夫人","十六觀","九品往生","謗大乘"]},"1416-a03_040":{"s":"本集講往生淨土正因的三福淨業：孝養父母、奉事師長、慈心不殺、修十善業；受持三皈、具足眾戒、不犯威儀；發菩提心、深信因果、讀誦大乘、勸進行者。逐項解說時，講者以坦特羅佛教雙身法為反例，批評其違背十善、另立四皈依、三昧耶戒、紅白菩提等，並批評否定淨土與大乘非佛說之說。","p":["三福淨業是三世諸佛淨業正因","孝養父母，奉事真善知識","修十善業，合四種清淨明誨","講者以坦特羅雙身法為反例逐項批評","讀誦大乘、勸進行者依佛說修觀想"],"k":["三福淨業","孝養父母","十善業","三皈依","菩提心","坦特羅佛教"]},"1490-a03_041":{"s":"本集講《觀經》前七觀的實修內涵：日想（看將落之日，開閉目憶持）、水想（水成冰、琉璃地及其上下莊嚴）、地想、樹想、八功德水想、總觀想、花座想。說明各觀分段想觀的技巧與滅罪功德，並判定日想、水想屬靜中功夫非三昧，地想以後須動靜分明，屬觀想三昧而非念佛三昧。","p":["日想：看將落的太陽，開閉目皆分明","水想分五段觀，比日想多用觀","地想須動靜分明，除八十億劫罪","樹想、八功德水想、總觀想分段觀","花座想為法藏比丘願力所成"],"k":["觀想念佛","十六觀","日想","水想","花座想","觀想三昧"]},"1491-a03_042":{"s":"本集講《觀經》第八至十三觀：先引「是心作佛，是心是佛」，再講想像觀、遍觀一切色想（觀無量壽佛身相光明，見佛身即見佛心而成念佛三昧）、觀音觀、勢至觀、普觀想、雜想觀。結論判一二觀非三昧、三至八觀為觀想三昧、九至十三觀為念佛三昧；講者並批評坦特羅佛教觀想天身成佛與遷識法為虛妄。","p":["是心作佛，是心是佛，法身入眾生心想","想像觀：觀佛像與二菩薩坐蓮花","觀佛身見佛心，明心見性為念佛三昧","觀音、勢至二菩薩身相差異","判各觀層次，批評坦特羅觀想成佛"],"k":["觀想念佛","十六觀","念佛三昧","是心作佛","觀世音菩薩","大勢至菩薩"]},"1481-a03_043":{"s":"本集介紹玄奘譯《稱讚淨土佛攝受經》的繫念思惟念佛法門：淨信善男女聞無量壽佛功德、名號、極樂莊嚴三種法後思惟，一至七日繫念不亂，臨終佛來慈悲加佑令心不亂。說明此法比持名一心不亂易成就，持名屬其中一種；淨信者不必擔心能否往生，應求提升品位；並介紹玄奘譯經信達與曲女城大會事蹟以增信心。","p":["繫念思惟出自《稱讚淨土佛攝受經》","淨信：信因果、三寶及眾生有真如佛性","繫念三種法比持名一心不亂易成就","臨終佛來慈悲加佑，令心不亂","玄奘譯經信達，曲女城大會無人能破"],"k":["繫念思惟念佛","稱讚淨土佛攝受經","玄奘","淨信","往生","持名念佛"]},"1483-a03_044":{"s":"本集續講繫念思惟，具體示範如何思惟極樂世界功德莊嚴：無身心憂苦、意念為食、無三惡道、無女人、氣候溫和、心平則地平、黃金寶地、宮殿樓閣、寶樹羅網、妙風說法、八功德水、七寶蓮花、化鳥說法、天樂天花、普放光明。並說明五種不退，指出極樂阿鞞跋致含三賢位不退，開始舉長壽為其原因。","p":["思惟極樂無苦，見色聞香以意為食","無三惡道、無女人，心平則地平","寶樹、妙風、八功德水、化鳥皆說法","五種不退：信、位、行、念、究竟","極樂阿鞞跋致含三賢位，首因為長壽"],"k":["繫念思惟念佛","極樂莊嚴","八功德水","阿鞞跋致","不退轉","稱讚淨土佛攝受經"]},"1465-a03_064":{"s":"本集續講大精進菩薩七日一心憶佛、發起禪定光明，仍自知非真一心念佛。講者以「睡著是否還在念佛」「用哪一識念佛」等問題，說明能念佛的意識心有生有滅；並依《中阿含經》《成唯識論》解說六識、五俱意識及根塵識如束蘆的十八界，指出自性彌陀不在十八界中，須進入體究念佛。","p":["大精進菩薩七日一心仍屬因地念佛","意識念佛睡時即斷，有生必有滅","意根觸法塵生意識，意識非常住法","根塵識相依如束蘆，合為十八界","自性彌陀不在十八界，須體究念佛是誰"],"k":["自性彌陀","十八界","六識","因地念佛","果地念佛","體究念佛"]},"1464-a03_065":{"s":"本集引《念佛三昧修學次第》說明體究念佛一念相應即明心、親證自性彌陀，歸命無量壽佛即歸命自身真如。講者並以《法句譬喻經》四比丘論苦，說明「有身」為眾苦根源；依《雜阿含經》解說六識身衍生的六六身即身見我見，指出大精進菩薩當時仍是凡夫，斷身見方能出離輪迴。","p":["一念相應明心，親證自性彌陀","歸命無量壽佛即歸命自身真如","四比丘論苦：有身為眾苦之本","六識身衍生六六身，執之為身見我見","斷身見我見，輪迴之苦方開始滅除"],"k":["身見","我見","六六身","自性彌陀","明心","苦諦"]},"1468-a03_066":{"s":"本集引《無量壽經》《大阿彌陀經》《觀經》說明果地念佛為無生法忍，有生滅的念佛皆屬因地。講者解說下品往生多造惡業、須在蓮苞中經長劫；書中所述果地無相念佛是以真心念佛真心，斷三縛結證初果；並以《雜阿含經》說明結使即六識貪愛，斷身見得須陀洹，極七往返必成道果。","p":["果地念佛即無生法忍，非生滅之念","下品往生多造惡業，須在蓮苞長劫","以真心念佛真心，斷三縛結入聖流","中品往生關涉二乘解脫果位","結使如五欲之繩，斷身見證須陀洹"],"k":["無生法忍","三縛結","須陀洹","九品往生","結使","斷我見"]},"1466-a03_067":{"s":"本集以闍尼沙說明天界亦有佛法，並批評部分法師以人間佛教否定極樂世界與阿彌陀佛。講者指出二乘將滅止生仍落生滅，引六祖說明本自無生的實相；第八識如來藏才是自性彌陀，證之為大乘見道、可上品上生。後引書解說實相念佛：明心後須在動中體究眼見佛性，體用分明、空有不二即念佛三昧。","p":["闍尼沙斷身見，說明天界亦有佛法","講者批評否定阿彌陀佛的人間佛教說","二乘將滅止生，非無生法忍","第八識如來藏即自性彌陀，大乘見道","明心後動中體究見性，即實相念佛"],"k":["如來藏","實相念佛","眼見佛性","上品上生","大乘見道","念佛三昧"]},"1467-a03_068":{"s":"本集說明明心又見性才是具足的實相念佛，並依書逐字解釋《大佛頂如來密因修證了義諸菩薩萬行首楞嚴經》經名，含大、佛、頂、三種如來、密因、了義與萬行，指出念佛圓通是了義法門而非持名方便。講者另舉廣欽老和尚念佛三昧經驗，並依《地藏十輪經》四種僧，批評否定如來藏的法師。","p":["真如為體、佛性為用，明心見性具足","逐字解釋《楞嚴經》全名意涵","念佛圓通為了義法門，非持名方便","舉廣欽老和尚念佛三昧之自述","依《地藏十輪經》說勝義僧等四種僧"],"k":["楞嚴經","念佛圓通","實相念佛","明心見性","勝義僧","菩薩戒"]},"1474-a03_069":{"s":"本集由正圜老師開講實相念佛人所得功德正受，先複習實相念佛即開悟明心、眼見佛性，再將正受分為見地、定、解脫三種略作說明，並以水與波喻如來藏與五陰非即非離。後引《大寶積經》說明離身見如披甲冑、以安樂乘趣菩提，菩薩不同二乘畏懼世間；最後依《華嚴經》講見地正受第一點。","p":["實相念佛即念佛三昧、明心見性","功德正受分見地、定、解脫三種","如來藏與五陰如水與波，非即非離","離身見如披大甲冑，以安樂乘度眾","見地正受一：親證自性彌陀常住境界"],"k":["功德正受","見地正受","實相念佛","如來藏","明心見性","斷身見"]},"1487-a03_070":{"s":"本集續講見地正受第二至第五點：確知第一義、漸知修道方向與次第、離一切相、漸次明白禪門公案語錄而禪淨俱通。接著講定的正受：一是覺明現前，悟後少眠，但應知真心本在、睡時宜放下；二是非定不禪，功夫須從無相念佛、看話頭循序而進，定力是眼見佛性的必要條件。","p":["確知第一義，說法不再依文解義","漸知悟後修道方向與次第","離一切相，理上平等、事上無妨","漸明公案語錄，禪淨俱通","覺明現前與非定不禪，定力不可少"],"k":["見地正受","定的正受","第一義","非定不禪","看話頭","禪淨俱通"]},"1445-a03_071":{"s":"本集續講定的正受第三至第七點：分辨定力、定相、定境，定力是心不隨定亦不捨定；禪是般若而非禪定，勿以定為禪；正念相續不等於一念不生；悟後須修禪定求俱解脫，並修除煩惱習氣。並引六祖「唯論見性」強調智慧斷惑。再開講解脫正受，介紹具深慈悲心與遠離以我為中心的私心。","p":["分辨定力、定相、定境，動靜一如","禪是般若，勿以定為禪","正念相續非一念不生","悟後修四禪求俱解脫，並除習氣","解脫正受：具深慈悲心、遠離私心"],"k":["定的正受","解脫正受","禪定","正念相續","俱解脫","慈悲心"]},"1492-a03_072":{"s":"本集續講解脫功德正受第三至第七點：從如來藏看眾生平等以消除慢心，並學常不輕菩薩；捨棄瞋恨怨惱，悟後仍有習氣但能一轉身放下；少數人初見道時有貪瞋轉盛現象，終將轉為淡薄；如實了知自身解脫境界；以及分辨功德是解脫的真實受用，福德是五陰所受的依正報。","p":["從如來藏看眾生平等，消除慢心","捨棄瞋恨怨惱，悟後習氣須漸除","少數人初見道會貪瞋轉盛，終將淡薄","如實了知自己的解脫境界","功德是解脫受用，福德是五陰果報"],"k":["解脫正受","慢心","瞋恚","功德與福德","習氣","性障"]},"1493-a03_073":{"s":"本集講解脫正受第八點：各種功德正受並非悟後一時具足，須在歷緣對境中長期思惟整理，並勸捨聲聞自了心態。接著進入第九章後續修行，說明悟後有常住世間與求生極樂兩種趣向，皆應加修禪定或觀想念佛；有大心者應修四禪、五神通，並解說觀鍊熏修四種禪、獅子奮迅三昧、漏盡通與四無量心。","p":["功德正受非悟後一時具足","勸捨聲聞自了心，發菩薩大心","求生極樂者亦應加修禪定與觀想","觀鍊熏修四禪與獅子奮迅三昧","修四無量心，不求梵天果報"],"k":["悟後起修","四禪八定","五神通","四無量心","解脫正受","觀想念佛"]},"1429-a03_074":{"s":"本集先提醒修楞嚴大定時應防陰魔干擾，再講理事相融的菩薩萬行。講者以自性無量壽佛為體，說明自性大勢至、自性觀世音即西方三聖之理，並引《華嚴經》《觀經》說持念大勢至即具文殊、普賢，念一佛即念十方佛；又說普賢十大願王導歸極樂，念佛法門究竟歸於常寂光唯心淨土。","p":["悟後修楞嚴大定，應防陰魔干擾","自性無量壽佛為體，具自性西方三聖","持念大勢至即具文殊、普賢功德","念一佛即念十方佛","普賢十大願導歸極樂，歸於唯心淨土"],"k":["自性彌陀","西方三聖","大勢至菩薩","普賢行","唯心淨土","菩薩萬行"]},"1460-a03_075":{"s":"本集由正德老師進入書中第四篇「肺腑之言」，先引《大乘理趣六波羅蜜多經》與念佛圓通章，說明念佛三昧即都攝六根、淨念相繼後親見自性彌陀。對未證者，勸為人師者莫著名利，修學者應尋求真實善知識，可長養善根、引入內門修六度、發起無生忍，如良醫因病授藥；並說明善知識的前三項條件。","p":["念佛三昧即親見自性彌陀、證諸法實相","前方便須都攝六根、淨念相繼","為人師者莫著名利，以免自誤誤人","真實善知識如良醫，能除業障煩惱","善知識須實證不退、善巧、建立信心"],"k":["念佛三昧","善知識","都攝六根","自性彌陀","六度","無生忍"]},"1462-a03_076":{"s":"本集續講真實善知識的後三項條件：有助人意願、能勘驗所證真偽、能發起道種智攝受學人。接著勸善遮口業：莫執名相毀謗修證、不以神通考驗修證、念佛人勿謗他宗；講者以此批評選擇本願念佛只取第十八願而略去但書，並勸讀淨土三經。又說他宗勿謗無相念佛，並辨析第一義無一法可得與筏喻。","p":["善知識須有助人意願與勘驗能力","善知識須能發起道種智攝受學人","莫執名相毀謗修證，不以神通驗悟","批評選擇本願念佛略去第十八願但書","第一義無一法可得指第八識，非意識"],"k":["善知識","口業","第十八願","淨土三經","無相念佛","第一義諦"]},"1461-a03_077":{"s":"本集續解「如筏喻者，法尚應捨，何況非法」：須先以三十七道品、八聖道為船筏證得解脫，方可不再憶念；不倒單、五熱炙身、男女和合等是見取見所取的非法。講者說明法是順於第一義諦與法毘奈耶，非法是把意識修成不分別或無念當作開悟。接著對已證者勸求善知識印證，並辨一念不生與見聞覺知心皆非自性彌陀。","p":["筏喻：先依道品證果，方可捨筏","不倒單、五熱炙身等屬見取見非法","法是順第一義諦與法毘奈耶","已證者須求真善知識印證，免大妄語","一念不生與見聞覺知心非自性彌陀"],"k":["筏喻","法毘奈耶","三十七道品","見取見","意識心","大妄語"]},"1446-a03_078":{"s":"本集引《維摩詰經》「法不可見聞覺知」，續辨看空無念、未到地定過暗、禪定定心境界都不是自性彌陀，並舉須深盜法、比丘自言慧解脫的例子，說明解脫與禪定無關。接著勸已證念佛三昧者勿得少為足，應繼續親近善知識以通教，發大心常住娑婆，並進修依實相而觀的大乘止觀。","p":["法不可見聞覺知，能聽能知非真心","看空無念與定中暗無覺知皆非開悟","禪定境界非自性彌陀，舉須深盜法","悟後勿得少為足，須繼續通教","勸常住娑婆，並進修大乘止觀"],"k":["自性彌陀","見聞覺知","禪定","慧解脫","大乘止觀","通宗通教"]},"1495-a03_079":{"s":"本集先講度人說法須觀根器，引《華嚴經》《大寶積經》說不可對不信者、求過者、外道及不恭敬者宣說如來藏。接著讚歎念佛法門的微妙：依《觀經》說稱名可下品往生，念佛功德如觀一毛孔相即有殊勝利益，念佛法身則由無相念佛進入實相念佛，並舉德雲比丘念佛門。最後勸念佛人勿自輕，說明中品往生條件。","p":["度人說法須觀根器，勿洩如來藏密意","稱念佛名可除重罪，下品往生","繫念佛功德，一毛孔相亦殊勝","念佛法身即實相念佛，舉德雲比丘","念佛人勿自輕，應求上品往生"],"k":["念佛法門","九品往生","念佛法身","根器","無相念佛","上品往生"]},"1496-a03_080":{"s":"本集說明老實念佛的人有能力上品往生，講者評「老實念佛不必求開悟、下品往生就好」之說自相矛盾。依《觀經》解說上品下生、中生、上生的條件，上上品須實證念佛三昧、受菩薩戒並修行六念。接著說十方佛國皆有淨土，介紹不動如來妙喜世界：生彼可見賢劫諸佛，並舉往生的前兩種因緣。","p":["念佛人具宿世善根，可求上品往生","評「不必求開悟、下品就好」之說","上品三生條件：信因果、不謗大乘等","十方佛國皆有淨土，非僅極樂","妙喜世界可見賢劫諸佛，舉往生因緣"],"k":["上品往生","妙喜世界","不動如來","觀無量壽佛經","菩薩戒","六念"]},"1431-a03_081":{"s":"本集說明往生妙喜世界的第三種因緣：求菩提、捨二乘心、安住真實空性、念住佛法僧名號，並分辨真實空性與空相，指出生不動佛國仍受釋迦攝受。接著勸修念佛圓通法門，依《楞嚴經》二十五圓通，舉琉璃光法王子、彌勒菩薩，說明大勢至菩薩與同倫五十二菩薩，表示念佛法門可貫通五十二階位，並講信位到六住的修學。","p":["往生妙喜因緣：捨二乘心、安住空性","真實空性非空相，指親見自性彌陀","二十五圓通：二乘止觀與大乘止觀","念佛法門貫通菩薩五十二階位","信位持名，漸入無相念佛與六住"],"k":["念佛圓通","妙喜世界","大勢至菩薩","楞嚴經","大乘止觀","菩薩階位"]},"1432-a03_082":{"s":"本集講住位以無相念佛為方便修集福慧資糧並降伏煩惱，進入體究念佛，一念相應即見自性彌陀，並解釋自性彌陀為無量壽、無量光之義。證後須善知識攝受，七住不退方入大乘三摩地，以念佛心入無生忍，地地增上，皆屬自心淨土。最後說往生極樂並非真實解脫，仍須斷煩惱，並批評往生即成佛之說；全書解說圓滿。","p":["住位修福慧資糧，進入體究念佛","自性彌陀即無量壽、無量光之義","證後須善知識攝受，七住不退","以念佛心入無生忍，即自心淨土","往生極樂非真實解脫，仍須斷煩惱"],"k":["體究念佛","自性彌陀","無生忍","自心淨土","帶業往生","大乘三摩地"]},"1511-a04_007":{"s":"本集為「如何修證解脫道」的前言，說明真正的解脫是成佛，二乘的有餘依、無餘依涅槃是佛為小心志者施設，而涅槃的實際是唯一實相如來藏。講者批評南傳大師以意識心求證涅槃、不具四不壞信，並說明證初果須具四不壞信、斷三縛結，在家出家皆可證得。","p":["兩類求涅槃的有情，終須歸於大乘佛道","有餘依、無餘依涅槃是施設，實相唯一如來藏","講者批評南傳以意識心證涅槃、不信佛","初果須具四不壞信並斷三縛結","沙門果在家出家皆可證，須離卑劣慢與我慢"],"k":["四不壞信","涅槃","初果","三縛結","如來藏","解脫道"]},"1513-a04_008":{"s":"本集續講修證解脫道須先具足對三寶的信。講者批評某比丘主張佛未說大乘，並說明有餘依、無餘依涅槃中無意識心，自稱體證涅槃是大妄語，而涅槃非斷滅；引《涅槃經》《楞伽經》《法華經》說二乘終回一佛乘。進而解說四不壞信的內容、斷常二見之誤，以及初果人於四聖諦無間斷作意。","p":["講者批評「佛未說大乘」之說","涅槃中無意識心，自稱自在受用是大妄語","無餘涅槃非斷滅，二乘終回一佛乘","四不壞信：信佛、法、僧、戒","破斷見與常見；初果人於四聖諦無間作意"],"k":["四不壞信","無餘涅槃","斷見常見","一佛乘","四聖諦","初果"]},"1512-a04_009":{"s":"本集續講四不壞信。講者批評部分佛學院只教名相、使學僧不信地獄淨土，並將菩薩戒視為附屬；以六祖為盧行者時得法說明賢聖僧不在表相。接著評述中國、西藏、南洋三地佛法傳承：講者批評藏傳甘露丸與以淫欲灌頂為破戒，南洋內觀以意識心求涅槃；並說明意識不至後世、離念非真心、緣起須有真實因。","p":["講者批評佛學院只講名相、缺正知見","賢聖僧不依表相，以六祖盧行者為例","中國有儒家基礎；講者批評藏傳雙身灌頂破戒","南洋內觀以意識心求涅槃，誤解涅槃","意識不到後世，離念非真心，緣起須真實因"],"k":["四不壞信","賢聖僧","戒","意識心","真心","緣起性空"]},"1545-a04_010":{"s":"本集對信受小乘者說明《阿含經》中已談到的法界實相：涅槃只能趣入、諸法不能自作他作而有真實因，如來有所依識，十因緣推至不可滅的本識，如來不變異常住、滅後非斷滅，以此支持八識論。並以欠人一百元跨劫償還為喻，說明業因的攜帶與記錄須有真實法，唯佛能究竟了知因果。","p":["小乘涅槃只能趣入，不能以意識心體證","諸法不自作、他作，必有真實因","如來有所依識，十因緣推至本識","如來不變異常住，入滅後非斷滅","以欠債為喻：業因須有真實法攜帶記錄"],"k":["阿含經","本識","八識論","真實因","業報","涅槃"]},"1533-a04_011":{"s":"本集說明緣起法並非常住真實法，以父母不知如何造出孩子身體為例，指出緣起背後必有真實法；講者批評南傳內觀以為能現觀涅槃是外道見。接著講斷身見：我須常住自在，五陰皆非我；說明三縛結、心與心所之別、以心緣心安住四聖諦，並解說苦集滅道與三苦。最後講者批評以淫欲修行及自設三昧耶戒等為外道法，引《楞嚴經》為證。","p":["緣起法非常住，背後須有真實法","講者批評南傳內觀現觀涅槃之說","我須常住自在，五陰非我，斷身見","辨心與心所，以心緣心安住四聖諦","講者批評淫欲修行、三昧耶戒為外道"],"k":["緣起法","斷我見","三縛結","四聖諦","戒禁取見","心所法"]},"1542-a04_012":{"s":"本集依《瑜伽師地論》卷三十四，講解以變異行至不自在行等十種行觀察苦聖諦以證初果。強調鈍根者應分內外、就現前所見逐一觀察蘊處界的變異、壞滅、別離、結縛等，從而體會無常、空、無我；再知苦由愛取有而集，制伏我慢，以心緣心無間作意，經三品加行至無分別，最後作意斷見所斷煩惱而證初果。","p":["依瑜伽師地論以十種行觀察苦聖諦","鈍根者須就現前所見觀察內外變異","盡所有性逐一觀察五蘊，悟空與無我","苦由愛取有而集，須制伏我慢","無間作意至無分別，最後作意證初果"],"k":["初果","苦聖諦","瑜伽師地論","觀行","無常","我慢"]},"1526-a04_013":{"s":"本集介紹成佛之道，主張以三量檢驗法義是否正確。先舉非成佛之道：世間行善、花道茶道等無記法、雙身法氣功誅殺法等惡不善道，以及把二乘解脫道或六識論緣起性空當作成佛之道。再說真正的成佛之道是含攝二乘的大乘佛菩提道，並依五十二位、六種菩薩性講解十信至十迴向各位修證，及入地條件之性障永伏如阿羅漢。","p":["以至教量、現量、比量檢驗法義","世間善道、無記法、惡不善道皆非成佛之道","二乘解脫道只是羅漢道","十信凡夫性須信因果、八識論與四不壞信","十住明心見性、十行陽焰、十迴向如夢觀"],"k":["成佛之道","佛菩提道","五十二位","明心見性","三量","解脫道"]},"1527-a04_014":{"s":"本集續講成佛之道，補述入地條件：廣大福德、熏習一切種智知見、佛前發十無盡願。再依次說明初地至十地各主修的波羅蜜多與滿心現觀（鏡像、光影、谷響至大法智雲），以及留惑潤生、意生身、滅盡定等，直至等覺百劫修相好、妙覺成佛。強調成佛以實證如來藏為基礎，並須圓滿福德、無量三昧、四種涅槃與一切種智。","p":["入地須福德、種智知見、十無盡願","初地主修布施，留惑潤生，證鏡像觀","十地各修一度及現觀，三地發意生身","等覺百劫修相好，妙覺示現成佛","成佛須以證如來藏為基礎，圓滿四種涅槃"],"k":["十地","成佛之道","一切種智","留惑潤生","如來藏","四種涅槃"]},"1500-a04_015":{"s":"本集介紹佛法的兩大甘露法門：解脫道與佛菩提道。先說佛法依覺悟內涵分三乘菩提，再分世間甘露、邪教甘露與佛法甘露；講者批評某些宗教以上師便溺製甘露及秘密灌頂雙身法，認為與佛法修證無關。接著以《法華經》三車喻說明菩提即覺悟，並比較兩道在果證高低、所度眾生多寡、智慧深淺上的差別。","p":["佛法分聲聞、緣覺、佛菩提三乘菩提","講者批評邪教甘露及秘密灌頂與修證無關","解脫道與佛菩提道稱為兩大甘露法門","以法華三車喻三乘菩提差別","比較果證、度眾數量與十智等智慧"],"k":["甘露法門","解脫道","佛菩提道","三乘菩提","一切智","阿羅漢"]},"1501-a04_016":{"s":"本集續講兩大甘露法門之差別。說明一切種智是八識心王一切種子的智慧，未圓滿前稱道種智，佛地四智圓明；別教依此建立五十二位、六種菩薩性。指出解脫靠智慧斷煩惱而非禪定，佛菩提所證以第八識如來藏為根本。再比較行門：二乘觀蘊處界屬世俗諦，大乘證如來藏屬勝義諦；並比較道次第與人無我、法無我觀。","p":["一切種智為八識心王一切種子智","解脫由智慧斷煩惱，非由打坐禪定","阿羅漢不是佛，佛亦是阿羅漢","二乘屬世俗諦，大乘證如來藏屬勝義諦","大乘無我觀具足人無我與法無我"],"k":["一切種智","如來藏","勝義諦","世俗諦","法無我","六種菩薩性"]},"1504-a04_017":{"s":"本集說明佛菩提道函蓋解脫道，先從四聖諦談起：菩薩除依二乘法說八苦、三苦及集滅道外，另依大乘義說二乘人因不證如來藏，在大乘法中有苦、集、滅、道而無聖諦，菩薩則四聖諦俱證；並引《決定義經》《大乘義章》《俱舍論》。再談法無我：聲聞依諸法無我、緣覺依十二因緣為法無我智說通者，但皆未證實相心。","p":["菩薩說四聖諦兼依二乘法與大乘密意","二乘不證如來藏，在大乘中無苦聖諦","引經論說明集諦、滅諦、道諦","聲聞為諸法無我之說通者","緣覺觀識緣名色，仍未證實相心"],"k":["四聖諦","佛菩提道","解脫道","法無我","如來藏","緣覺"]},"1505-a04_018":{"s":"本集先說菩薩法無我智涵蓋初地道種智至佛地一切種智，遠勝二乘。再整體介紹兩主要道修學次第：解脫道初果至四果所斷煩惱，聲聞觀蘊處界無常、空，緣覺修十二支緣起，終入無餘涅槃；佛菩提道則從斷我見、禪宗明心、眼見佛性到修種智。並以五十二位及唯識五位說明成佛次第，結論一切佛法匯歸第八識。","p":["菩薩法無我智含道種智與一切種智","初果至四果各斷三縛結至五上分結","聲聞觀蘊處界，緣覺修十二支緣起","大乘以禪宗明心證如來藏為首要","唯識五位次第，一切佛法匯歸第八識"],"k":["解脫道","佛菩提道","唯識五位","明心見性","法無我","第八識"]},"1530-a04_019":{"s":"本集概說大乘見道所需的福德資糧，以蓋高樓須打深地基為喻，指出許多人退失多因福德不足。說明首要歸命、供養三寶，並引《雜寶藏經》《心地觀經》《睒子經》說孝養父母的重要，奉侍師長以除慢心，引經說慈心不殺得五福，並論及自殺不能解脫；最後提到十善業道與三十二相須百福莊嚴。","p":["見道須福德資糧，如高樓須深地基","首要歸命並供養三寶","孝養父母福同供佛，佛因孝行成三界尊","奉侍師長可消慢心，助成見道","慈心不殺得五福；三十二相須百福圍繞"],"k":["福德資糧","孝養父母","供養三寶","慈心不殺","十善業道","見道"]},"1538-a04_020":{"s":"本集講行十善業道。先說菩薩的大利益是在無漏有為、無漏無為法上利益眾生，三十二相由身口意福德之業而成。再解說十惡業：身三、口四、意三，其中意三是業非道，十惡與十善為一體兩面，每一業道有根本、方便、成已三罪。並依次說明殺生（引《大智度論》殺生十罪）、偷盜（含逃漏稅等日常情形）與邪淫的內涵及果報。","p":["大利益指無漏法上的利益，可延續無量世","十惡業：身三、口四、意三，意三是業非道","每一業道具根本、方便、成已三罪","殺生十罪，殺傍生若以瞋心亦為重罪","偷盜含日常小事，邪淫三罪及果報"],"k":["十善業道","十惡業","殺生","偷盜","邪淫","三十二相"]},"1539-a04_021":{"s":"本集續談十惡業道，先說觀察淫欲虛妄，再依根本、方便、成已三罪逐一說明口四業（妄語、兩舌、惡口、綺語）與意三業（貪、瞋、癡），並引《大智度論》卷十三說妄語十罪。結論勸人棄捨十惡、勤修十善，並強調正見居八正道之首。","p":["色身四大假合不淨，色塵為自心如來藏所現","大妄語即未證言證，三罪具足為地獄罪","引《大智度論》說妄語十種過患","兩舌破和合僧、惡口、綺語皆易違犯","意三業貪瞋癡；勤修十善得三乘菩提因緣"],"k":["十善業道","十惡業","大妄語","菩薩戒","根本方便成已","口四業"]},"1506-a04_022":{"s":"本集依《成佛之道》講「佛菩提道首重開悟」，說明十信至妙覺五十二階位，並引《菩薩瓔珞本業經》指出七住明心為關鍵。再比較二乘人、新學與久學菩薩對開悟的看法，逐一辨析前五識、意識、意根皆生滅法，結論第八識才是禪宗所悟真心；講者並批評坦特羅樂空雙運之說。","p":["佛菩提道五十二階位及各位修行內容","七住明心為外門、內門六度萬行的關鍵","二乘只知蘊處界虛妄，未觸生命實相","前五識、意識、意根皆生滅法，非真心","第八識為禪宗證悟標的、菩薩所證真心"],"k":["明心見性","五十二階位","第八識","七住位","意識生滅","大乘見道"]},"1507-a04_023":{"s":"本集續論開悟，引「如金與指環，展轉無差別」偈說明第八識即如來藏、阿賴耶識，並說明第八識是萬法根源、持種識，及其與三轉法輪中本際、我、如、非心心、異熟識、無垢識等名相的關係。講者批評否定第八識或視阿賴耶識為妄心的說法，並舉世親菩薩謗法後弘法為例。","p":["第八識、如來藏、阿賴耶識同一心","經典以本際、如、無住心等異名說同一心","世親菩薩以弘揚大乘法扭轉謗法惡業","第八識出生蘊處界萬法，並為持種識","禪宗所悟即第八識，菩薩轉依故不畏生死"],"k":["如來藏","阿賴耶識","第八識","三轉法輪","持種識","應成派中觀"]},"1502-a04_024":{"s":"本集依《楞伽經》「宗通與說通」說明：宗通即大乘見道明心見性，說通是以宗通之法依眾生根性教導人天、聲聞、緣覺、菩薩法。並比較三乘菩提共與不共，說明明心為七住、明心後仍可能退失，講述四種隨順佛性，並批評觀想成佛、將意識修淨成真心之說。","p":["三乘菩提共觀蘊處界虛妄，菩薩另證法身般若","宗通為明心見性，說通為接引初機","引《瓔珞經》說明心為七住，無善知識仍會退","意識於五位必滅，修淨亦不成真心","四種隨順佛性；說通須觀眾生五種種性"],"k":["宗通說通","明心見性","三乘菩提","眼見佛性","七住位","楞伽經"]},"1503-a04_025":{"s":"本集深入比較佛菩提道與解脫道的共與不共：二乘證有餘、無餘涅槃，菩薩另證本來自性清淨涅槃與無住處涅槃，並發起總相智、別相智、道種智、一切種智。逐字解說「本來、自性、清淨、涅槃」，以《心經》、畢陵尊者慢習公案說明菩薩斷二障與阿羅漢之別。","p":["聲聞四果、緣覺皆證兩種涅槃","菩薩證四種涅槃：加本來自性清淨及無住處","以本來、自性、清淨、涅槃四義解說真心","般若四智：總相、別相、道種、一切種智","畢陵尊者喻阿羅漢未斷習氣種子隨眠"],"k":["四種涅槃","本來自性清淨涅槃","解脫道","佛菩提道","般若智慧","習氣種子"]},"1531-a04_026":{"s":"本集依《如來藏中藏如來》講「經中明說阿賴耶識即是如來藏」，引《央掘魔羅經》、《雜阿含》苦之本際、《楞伽經》等說明如來藏是一切有情真心，不同外道神我、梵我；再論阿賴耶識非生滅法，辨析對《起信論》、《成唯識論》、《瑜伽師地論》「阿賴耶識體是無常」的誤解。","p":["三轉法輪經典皆說眾生有如來藏真心","《楞伽經》明言如來藏不同外道之我","阿賴耶識為一切染淨法所依、五乘種性","論中「體是無常」指所藏種子變異非本體","講者批評宗喀巴等以意識代阿賴耶識"],"k":["阿賴耶識","如來藏","外道神我","大乘起信論","成唯識論","斷見常見"]},"1532-a04_027":{"s":"本集續證如來藏即阿賴耶識，從四方面說明：依《不增不減經》如來藏即法身、阿賴耶識亦為法身與果地無垢識；如來藏、阿賴耶識都有八個識；依《勝鬘經》等兩者皆自性清淨；並引《大乘本生心地觀經》佐證。講者也批評拙火、密灌頂等坦特羅修法之說。","p":["如來藏即法身，第八識隨階位立異名","如來藏、阿賴耶識皆與七轉識共八識","前六識五位必斷，意識細心仍是意識","如來藏與阿賴耶識皆自性清淨","講者批評拙火與密灌頂說非佛法"],"k":["如來藏","阿賴耶識","法身","自性清淨","八識","坦特羅批判"]},"1515-a04_028":{"s":"本集開講「如來藏是妄心七識的俱有依」，先介紹八識心王各自功能及五無心位，說明前七識剎那生滅故稱轉識。再依《成唯識論》解釋俱有依須具決定、有境、為主、令心取自所緣四條件，以國王與宰官為喻，並說五識的俱有依有五色根、意識、末那識、第八識四種。","p":["八識心王各自功能：五識、意識、末那、第八識","五無心位中意識必斷，前七識稱轉識","俱有依四條件：決定、有境、為主、取所緣","國王與宰官喻說俱有依","五識俱有依：五根、六識、七識、八識"],"k":["俱有依","八識心王","七轉識","五無心位","成唯識論","浮塵根勝義根"]},"1517-a04_029":{"s":"本集續說俱有依：五識四依分為同境依、分別依、染淨依、根本依；依《成唯識論》說意識俱有依為七、八識，末那識俱有依唯第八識，阿賴耶識俱有依唯第七識。並強調第八識依第七識是指在三界現行，非其存在依第七識，故無餘涅槃中第八識仍獨存，非斷滅空。","p":["五識四依：同境、分別、染淨、根本依","意識俱有依為七、八識，人間另需五根","末那識俱有依唯第八識","第八識依第七識指三界現行，非其存在","無餘涅槃中意根滅，第八識獨存非斷滅"],"k":["俱有依","末那識","根本依","染淨依","無餘涅槃","成唯識論"]},"1516-a04_030":{"s":"本集引《大乘入楞伽經》「依於藏識故，而得有意轉」偈，說明第八識為前七識俱有依；並以中陰入胎、識緣名色過程，說明末那執著促成投胎、新五根生起新六識，解釋隔陰之迷，並以孿生兄弟、天才兒童佐證第八識持種。最後辨析以離念靈知、處處作主心或觀想佛身為真心之說。","p":["《入楞伽經》偈說依藏識有意根與諸識","中陰入胎、識緣名色的過程","前世六識不至今生，故有隔陰之迷","孿生兄弟、天才兒童佐證第八識持種","離念靈知與觀想佛身皆非常住真心"],"k":["俱有依","識緣名色","隔陰之迷","中陰身","離念靈知","第八識"]},"1518-a04_031":{"s":"本集先總結俱有依：第八識是七轉識共同俱有依，悟錯者是把宰官七轉識誤當國王如來藏。接著開講「如來藏阿賴耶識具圓成實性」，依《瑜伽師地論》、《楞伽經》介紹三自性，以鏡與影像喻說明依他起性與遍計執性，並解說圓成實性的「真」與「如」，指出如來藏不簡擇地含藏善惡業種。","p":["第八識是七轉識共同俱有依","悟錯原因是誤把七轉識自性當如來藏","三自性：遍計所執、依他起、圓成實","鏡與影像喻依他起與遍計執","真如二義：體恆不壞、如如不簡擇業種"],"k":["圓成實性","三自性","依他起性","遍計所執性","真如","俱有依"]},"1519-a04_032":{"s":"本集說明圓成實性與依他起性、遍計執性「非一非二」的關係，以鏡與影像為喻。並引經典與《不增不減經》，說明阿賴耶識同時具生滅變異與清淨真如常住體性、兼具有為與無為法性，含攝心真如門與心生滅門；結論證真如須證阿賴耶識，才是禪宗真正開悟。","p":["依他起、遍計執皆攝歸圓成實，故非二","第八識可獨存於無餘涅槃，故非一","阿賴耶識雙具生滅變異與清淨真如","兼具有為、無為法性方為圓成實","含心真如門與心生滅門；證真如須證阿賴耶"],"k":["圓成實性","非一非二","心真如門","心生滅門","阿賴耶識","三自性"]},"1520-a04_033":{"s":"本集講「妄心永遠不能轉變成真心」，舉出三種常見錯誤：以覺知心一念不生為開悟、以觸而不分別為涅槃、以清清楚楚明明白白的心為真心，並以四禪、無想定、睡眠、隔世不記等逐一辨析。講者再引某法師著作，批評其否定第八識與自性之說，並引《壇經》說明自性存在。","p":["一念不生仍有清明之念，四禪、無想定有意根","錯解真心無念及以為覺知心入無餘涅槃","觸而不分別仍有分別，誤解不分別真義","明白心睡時不在、不能往來三世","引《壇經》說自性存在，批評否定第八識"],"k":["妄心真心","一念不生","離念靈知","第八識","無餘涅槃","斷我見"]},"1521-a04_034":{"s":"本集續說妄心不能變真心，引經「一切眾生阿賴耶識本來而有」及《楞伽經》「藏識滅者不異外道斷見」，證明真心存在；並逐句解說《楞伽經》卷四「如來之藏是善不善因」一段，說明如來藏造作五陰、與七識俱轉。再以「八個兄弟共一胎」偈說八識並行，結論妄心是已生法，體性與真心不同。","p":["經說一切眾生阿賴耶識本來而有、同於涅槃","以藏識為可滅即同外道斷見","解《楞伽》：如來藏是善不善因、造作五陰","如來藏即阿賴耶識；八識並行偈","妄心已生不能變無生，如沙不能成飯"],"k":["妄心真心","如來藏","阿賴耶識","八識並行","楞伽經","斷見"]},"1535-a04_035":{"s":"本集依《生命實相之辨正》說明般若禪與禪定的差別：般若禪是證得真心如來藏後的實相智慧，真心無境界、無所得、無入出；禪定則是覺知心相應的有所得、有境界、有入出之法。並逐一講解「以定為禪」的前九種層次，從散亂攀緣心到無覺有觀三昧。","p":["般若禪是證如來藏後的實相智慧","引《大寶積經》說真心無入無出","禪定是覺知心制心一處，有入有出","攀緣心、以法定心、常寂常照、遍滿虛空皆非真心","未到地定、初禪、虛空粉碎、大地平沉仍是定境"],"k":["般若禪","禪定","如來藏","以定為禪","未到地定","初禪"]},"1536-a04_036":{"s":"本集續講第十種「無覺無觀三昧」，指出十種層次即佛所說外道五現涅槃，四空定亦非涅槃。再以《景德傳燈錄》南嶽懷讓磨磚作鏡點化馬祖道一的公案，並從本質（引《大智度論》說禪定通外道）與修學方法（般若禪需正知見與參話頭）說明般若禪不是禪定。","p":["二禪以上等至位為無覺無觀三昧","十種層次即外道五現涅槃，四空定亦非涅槃","磨磚作鏡公案：坐禪豈得成佛","不識本心學法無益；禪定本質通外道","般若禪需正知見、定力與參話頭功夫"],"k":["般若禪","禪定","五現涅槃","四空定","參禪","公案"]},"1509-a04_037":{"s":"本集說明佛所說「唯識」是出生三界萬法的第八識，而非見聞覺知的六識，並介紹其異名如阿賴耶識、入胎識、所知依、本際、真如、異熟識、無垢識。引《央掘魔羅經》及《雜阿含》《長阿含》說明佛在阿含期已隱覆密意說入胎識，並指唯識妙義是三乘菩提根本，令免斷常二見、成就般若中觀與一切種智。","p":["三界唯心、萬法唯識，所指為第八識","第八識異名：入胎識、本際、真如、無垢識等","阿含已隱說入胎識：齊識而還，不能過彼","唯識令二乘入無餘涅槃不落斷滅","唯識成就般若中觀與一切種智"],"k":["唯識","第八識","如來藏","入胎識","十因緣","一切種智"]},"1510-a04_038":{"s":"本集續說唯識妙義：如來藏真實存在，具可證性、普遍性、再現性與唯一性，不是哲學玄想，是了義而非方便說。講者辨析如來藏非自性見，批評以認識論、細意識解讀唯識者反落自性見，引《入楞伽經》與窺基《成唯識論述記》說第八識非細意識，並認為否定如來藏將使佛法名存實亡。","p":["阿含已以入胎識、有分識等名說第八識","如來藏可證、普遍、再現，非哲學玄學","如來藏是了義說，二乘法是方便化城","如來藏具無自性性，否定者反落自性見","細意識仍是意識，不能成為第八識"],"k":["如來藏","唯識","自性見","細意識","阿賴耶識","了義"]},"1540-a04_039":{"s":"本集說明自性三寶、出世三寶、住持三寶的分別，指出住持僧寶即表相僧寶，出世僧寶即真實義僧寶，判準在是否悟入如來藏，而非現出家或在家相。並區分身出家與心出家，說明真出家是心離三界家、五陰宅，唯菩薩證悟並轉依如來藏方是，舉大精進菩薩及《大寶積經》跋陀羅出家事為例。","p":["三寶分自性、出世、住持三個層次","住持僧寶為表相，出世僧寶為真實義","僧寶以是否開悟為主要判定標準","真出家是心離三界家、五陰宅","大精進菩薩悟後言不被袈裟"],"k":["僧寶","三寶","真出家","如來藏","表相僧寶"]},"1541-a04_040":{"s":"本集續引《大寶積經》彌勒菩薩語：剃度只是形相出家，真出家須離諸相、處於三界、成熟眾生，即證悟如來藏並行菩薩道。列出身心出家的四種情況，引達摩「不見性，剃除鬚髮亦是外道」及「入門須辨主」，舉善財參訪與等覺菩薩多現在家相，勸在家出家互相扶持，出家眾應以大乘見道為要務、去除僧慢。","p":["彌勒說剃度唯形相，非真出家","真出家：離諸相、處三界、成熟眾生","身心出家四種，唯心出家為真出家","達摩：不見性剃髮亦是外道","在家出家互相扶持，以大乘見道為要"],"k":["真出家","僧寶","離諸相","菩薩僧","明心見性"]},"1498-a04_041":{"s":"本集探討佛教人天乘與其他宗教生天之法的不同，反駁以天道貫通各教的說法。以五戒逐條比較：佛教不殺生而素食、反戰；講者批評某些宗教吸收佛法後反對佛教或編造老母娘，以及秘密大乘盜用佛教名相、修雙身法、自稱即身成佛，視為違犯不予取、邪淫與大妄語；結論是佛教人乘已與他教不共。","p":["佛教人乘持守五戒以保人身","不殺生：素食並反對戰爭","不予取：批評盜用佛法名相的宗教","講者批評秘密大乘違犯全部五戒","自稱即身成佛被視為最大妄語"],"k":["人天乘","五戒","不予取","雙身法","大妄語","老母娘"]},"1534-a04_042":{"s":"本集講天乘：引《長阿含》說生天須身口意行善、具正見不謗賢聖，引《雜阿含》四種諸天天道。說明佛教有欲界、色界、無色界諸天，講者認為老母娘信仰最多僅及欲界；並從數量（如來藏無量且不增不減）及出生五教教主的矛盾，論證老母娘不是如來藏，批評盜取佛法義理另立宗教為不予取。","p":["生天須身口意善行並具正見","四種諸天天道：三寶不壞淨、聖戒成就","佛教說三界諸天，他教多僅知欲界","老母娘唯一，如來藏無量不增不減","盜用佛法義理另立宗教即不予取"],"k":["天乘","如來藏","老母娘","七聖戒","正見","不予取"]},"1528-a04_043":{"s":"本集開始導讀摘自《狂密與真密》的「概說坦特羅佛教系列」，講者主張坦特羅佛教非真正佛教。內容實為背景介紹：印度種姓制度、吠陀與奧義書的多元修行思想（火供、甘露、男女和合），微妙身的輪、脈、明點、風息理論，以及佛滅後性力思想漸入佛門，起源於低下社群與墳場環境。","p":["坦特羅佛教須從印度文化背景理解","種姓制度造成多元並存的社群文化","奧義書有火供、甘露、男女和合等法","微妙身思想：輪、脈、明點、風息","性力思想於佛滅後逐漸混入佛門"],"k":["坦特羅佛教","明點","微妙身","種姓制度","奧義書","性力派"]},"1529-a04_044":{"s":"本集續述坦特羅佛教無上瑜伽的修法，以《如意輪總持續》說明其本尊觀想、壇城與雙身修法，講者認為六字大明咒即其「蓮中寶」總持。說明紅白明點和合「成佛」之說，並引平實導師書中開示，批評以明點脈氣為諸佛本源、以雙身法求即身成佛，主張佛身由禪定與一切種智圓滿成就，非鍛鍊精氣。","p":["無上瑜伽以男女雙修為核心","講者認為六字大明咒為雙身法總持","紅白明點和合即身成佛之說","明點脈氣為其入門必修課程","講者認為以明點代替根本識違佛法"],"k":["明點","雙身法","無上瑜伽","如來藏","即身成佛","坦特羅佛教"]},"1522-a04_045":{"s":"本集以「念發財」青年與喪子居士兩則故事引入，說明講者所批評的坦特羅佛教宗見：引新噶當派祖師之說，只承認六識、以意識為染淨法根本，並以觀想「由假修真」。接著講解佛說八識與十八界，指六識身依根塵而生、非真實，眾生執意識為我而輪迴；末舉《雜譬喻經》屠夫殺羊生天故事留待下集。","p":["以意識觀想改變事實的兩則故事","講者批評新噶當派只承認六識","諸佛出世為開示悟入佛之知見","根塵識為十八界，六識身非真實","屠夫自稱殺羊生天的故事"],"k":["六識論","八識","十八界","應成中觀","我見","坦特羅佛教"]},"1523-a04_046":{"s":"本集解答屠夫故事：其生天實因過去生瞻仰辟支佛的福德，殺羊惡報將於後世受，說明六識所見非絕對真實。引《成唯識論》說六識依根塵了別境界，業種現行非意識所能改變；再略述三轉法輪、佛滅後部派分裂、龍樹與無著世親復興正法，及佛護、清辨創中觀應成與自續派，講者認為其否定唯識真實識。","p":["屠夫生天因瞻仰辟支佛的福德","六識依根塵而生，是應捨之法","業種現行非意識心所能改變","三轉法輪：解脫道、般若、唯識種智","佛護、清辨創應成派與自續派"],"k":["應成中觀","自續中觀","六識","業種","三轉法輪","唯識"]},"1524-a04_047":{"s":"本集講者認為中觀應成派源自奧義書的遮詮辯論法，只承認六識而否定第八識，致涅槃成斷滅並須另立意識細心，引玄奘《成唯識論》破遣相空。又說明自續派雖承認實相，卻以一念不生的意識為真如。並講述坦特羅佛教以意識觀想改變一切，結合婆羅門內身與男女交合思想，形成雙身法與無上瑜伽。","p":["講者認為應成派源自奧義書遮詮","否定第八識將使涅槃成斷滅","引玄奘破遣相空與意識細心","自續派以一念不生意識為真如","觀想萬能思想導出雙身法"],"k":["應成中觀","自續中觀","第八識","細意識","遣相空","雙身法"]},"1514-a04_048":{"s":"本集介紹坦特羅佛教的四加行（大禮拜、供曼達、金剛薩埵法、上師相應法），講者認為其目的在為雙身法作準備；再依《瑜伽師地論》解說佛法真正的四加行煖、頂、忍、世第一法，以鑽木取火為喻，說明觀能取所取平等以斷我見、入見道。末批評廣論班隱藏後段內容，並舉譚崔信徒事例勸人辨別正邪。","p":["坦特羅四加行：大禮拜、供曼達等","上師相應法要求視上師即佛法僧","佛法四加行：煖、頂、忍、世第一法","以鑽木取火喻加行至見道","講者批評廣論班隱藏止觀後段"],"k":["四加行","斷我見","見道","坦特羅佛教","雙身法","上師相應法"]},"1653-a05_041":{"s":"本集續講「離二邊通」，以龍樹菩薩八不中道偈逐句說明第八識阿賴耶識不生不滅、不常不斷、不一不異、不來不出及非有非無的中道體性。講者批評以意識不落兩邊為中道的說法屬常見，並依《大般若經》菩薩三心說明「無所得為方便」須依如來藏，不同於斷滅空。","p":["阿賴耶識本來不生故不滅，種子可變故不常","七轉識與第八識非一亦非異","意識不落二邊非中道，乃真妄同時運作","無相不一定是實相，實相是空有不二","無所得為方便須轉依如來藏，非斷滅空"],"k":["八不中道","如來藏","般若中道","無所得","菩薩三心","三輪體空"]},"1611-a05_042":{"s":"本集講解菩薩六通中的「意通」與「說通」。意通指真悟者能通曉其他悟者言教與公案意旨；講者強調禪宗的禪是般若而非禪定，開悟是一念相應的頓悟，並批評十牛圖。說通則依《楞伽經》說明須先宗通，方能隨眾生根器說法而無過失。","p":["意通：真悟者能通公案意旨，深淺隨證量","禪是般若非禪定，解脫靠慧不靠定","悟只有頓悟，悟後才漸修、生後得智","密意屬法毘奈耶，禁止明說","說通依宗通，「宗通說亦通，如日處虛空」"],"k":["意通","說通","宗通","頓悟","禪宗公案","根本無分別智"]},"1551-a05_043":{"s":"本集開講「三乘菩提之異同」，分別說明聲聞菩提、緣覺菩提與佛菩提的內涵。講者依《瑜伽師地論》說獨覺三種種性，並指緣覺必曾親近佛法、先修十因緣；再以渡河喻、大悲為上首及《法華經》三車喻，說明菩薩自利利他與二乘的差別。","p":["聲聞聞佛音聲修四聖諦，出三界生死","緣覺無師獨覺，但必曾聞法、先修十因緣","佛菩提見道是明心，解脫道見道是斷我見","菩薩勸化眾生發菩提心，如大船渡百千人","法華三車喻：三乘方便，本願在大乘"],"k":["三乘菩提","聲聞菩提","緣覺菩提","佛菩提","三車喻","十因緣"]},"1558-a05_044":{"s":"本集講「為戒慧直往菩薩說悟後起修之道」，說明開悟只是七住真見道，並非成佛；悟後須經相見道到初地入地才進入修道位。入初地要具備發起聖性與修道性、無生法忍道種智、勇發十無盡願三件事，並詳說異生性障及十行、十迴向位的修行。","p":["明心只是七住，入地後才進入修道位","入初地三條件：聖性修道性、道種智、十無盡願","異生性種分煩惱障、所知障，各有俱生與分別","十行位轉依真如，前七識清淨無漏","初迴向救護眾生離眾生相、破邪顯正"],"k":["悟後起修","異生性障","十行位","十迴向位","十無盡願","真見道"]},"1570-a05_045":{"s":"本集講「三乘無學應迴向第一義諦」，著重說明大乘通教菩薩缺乏受學第一義諦因緣的三個原因：誤以出家相為菩薩僧、不能安忍摧邪顯正、不與大乘勝義僧結法緣。並解說第一義諦智慧的三層次：般若總相智（根本無分別智）、別相智與一切種智。","p":["三乘無學含二乘及通教、別教無學","通教菩薩以表相判僧，不能依法不依人","不能安忍摧邪顯正，不親近勝義僧","別教五十二位依證如來藏的智慧建立","總相智、別相智、一切種智（道種智）"],"k":["通教菩薩","第一義諦","依法不依人","總相智","別相智","一切種智"]},"1654-a05_046":{"s":"本集總結三乘無學都應迴向第一義諦，因佛陀本懷是令眾生成佛，入無餘涅槃則中斷成佛之道。接著講「為已悟菩薩說應修一切種智」，以植物種子譬喻說明種子又名界、功能差別，介紹《成唯識論》三種能變，駁斥「虛妄唯識」之說，並開始解說有漏、無漏法種。","p":["佛陀本懷非令二乘入無餘涅槃","已悟菩薩應續修一切種智","種子即界、即功能差別","初能變、第二能變、第三能變","阿賴耶性滅而心體不滅，非虛妄唯識"],"k":["一切種智","種子","三種能變","阿賴耶識","有漏無漏","虛妄唯識"]},"1552-a05_047":{"s":"本集續講三種能變，說明真正的無漏須在三乘菩提中實證斷除現行，而非世間的偶然不貪不瞋。初能變令眾生得異熟、等流、士用、增上、離繫五果及無漏有為法；第二能變變生意根末那，與第八識和合貫穿三世，修行即對治意根相應的四煩惱，且唯有現量才能對治意根。","p":["真無漏須實證斷現行，非世間偶爾不貪","初能變成就異熟、等流等五果","菩薩如法取財利生，屬無漏有為法","第二能變生意根，與第八識貫穿三世","意根唯受現量對治，宗通即對治意根"],"k":["三種能變","意根","末那識","無漏有為法","四煩惱","現量"]},"1635-a05_048":{"s":"本集說明修道須在現量中對治末那染污性，四聖六凡的差別依意根清淨程度建立；接著介紹第三能變六識及相應心所，由三能變證成八識論。講者依一心八識與《成唯識論》阿羅漢捨阿賴耶名而不捨識體之文，說唯識有真實唯識門，並開始回應《印度之佛教》以三時教判唯識為虛妄唯識的說法。","p":["修道是在現量中轉末那染污為清淨","四聖六凡依意根清淨與染污區分","第三能變為六識及其相應心所","唯識有真實唯識門與虛妄唯識門","阿羅漢捨阿賴耶名，不捨第八識體"],"k":["真實唯識門","八識論","第三能變","一心八識","異熟識","三時教"]},"1671-a05_049":{"s":"本集續論真實唯識門，回應《印度之佛教》、《如來藏之研究》作者以「境空心有」判唯識為虛妄唯識，以及主張依《大哀經》立三時教的說法。講者引《大哀經》卷六原文，認為其三個次第講的是聲聞見道到不退轉的過程，屬阿含所說，並批評該作者錯解經義、混淆解脫道與佛菩提道。","p":["境空心有的心是真實心，非三界有","講者反駁如來藏經只講一乘之說","《大哀經》三次第是聲聞見道過程","先說解脫道，是為入大乘後不退","大乘見道函蓋聲聞、緣覺之道"],"k":["三時教","真實唯識門","大哀經","判教","聲聞見道","如來藏"]},"1603-a05_050":{"s":"本集先說明正確判教須有大乘見道，未斷我見者易把聲聞次第誤判為三時教。接著依《成唯識論》介紹七種真如並舉邪行真如為例，再進入「為初入地菩薩說修道」，指入地者須證初禪、離欲界愛，講者據此批評雙身法；最後開講入地障礙的建立見與誹謗見。","p":["正確判教須有大乘見道","七真如：流轉、實相、唯識等七種","入地須發初禪、離欲界愛，批評雙身法","建立見：誤立細意識等為法界根源","誹謗見：否定真實存在的第八識、第七識"],"k":["建立見","誹謗見","七真如","三時教","初禪","入地"]},"1664-a05_051":{"s":"本集以《唯識學探源》只舉六識為一切心理活動為例，說明否定七、八識屬誹謗見，並引《雜阿含經》「諸所有意識，彼一切皆意法因緣生」反駁細意識常住之說。接著依《楞伽經》介紹初地菩薩得諸佛加持的大乘照明三昧，並講入地條件及三賢位的如幻、陽焰、如夢觀。","p":["只承認六識、否定七八識屬誹謗見","引《雜阿含》駁細意識常住說","大乘照明三昧：入地菩薩得諸佛加持","入初地要修百法明門、斷思惑成慧解脫","如夢觀須以初禪證量為前提"],"k":["誹謗見","建立見","大乘照明三昧","如夢觀","三賢位","十度波羅蜜"]},"1568-a05_052":{"s":"本集續講十地觀行與修證，說明初地至七地的鏡像、光影、谷響、水月等現觀，以及各地所修增上戒、心、慧學、三地意生身離隔陰之迷、七地念念入滅盡定、八地於相於土自在、九地四無礙辯、十地法雲。最後以唯識五位與《瑜伽師地論》十三住總括成佛次第，結束第三章「從宗入教」。","p":["初地至七地各有猶如鏡像等現觀","三地具意生身，不再有隔陰之迷","七地念念入滅盡定，八地於相於土自在","唯識五位：資糧、加行至究竟位","瑜伽十三住總攝菩薩行與如來住"],"k":["十地","無生法忍","意生身","唯識五位","十三住","滅盡定"]},"1619-a05_053":{"s":"本集開講第四章「從宗出教」，說明證悟者先以三轉法輪經典檢驗所證，再觀察時節因緣出來弘法，教授學人建立正見。講者批評否定實相的緣起性空斷滅見與執意識為真心的常見，並舉玄奘拜勝軍居士、勝鬘夫人、維摩詰等說明勝義僧不在出家在家表相。","p":["證悟者以三轉法輪驗證，得類智忍","觀察時節因緣，出來弘護正法","斷見者否定實相因，說不清業種所依","常見者執意識心為真我","勝義僧依證量，不依出家在家表相"],"k":["從宗出教","斷見","常見","緣起性空","勝義僧","業種"]},"1567-a05_054":{"s":"本集說明證悟者應全盤細膩解說佛法：先辨大小乘涅槃差異，指二乘所證兩種涅槃是佛施設；再為學人分析捨報後的去處，如以無相念佛求生極樂、留娑婆弘法或求生兜率；最後依三轉法輪一貫之理，細說六波羅蜜中布施、持戒、忍辱等的利益與正見。","p":["二乘的有餘、無餘涅槃為佛所施設","大乘說一切法不生不滅，皆如來藏所生","無相念佛、解第一義可上品中生","末法菩薩發願留娑婆或求生兜率","細說六度：布施、持戒、忍辱等利益"],"k":["涅槃","大小乘差別","無相念佛","六波羅蜜","往生極樂","末法"]},"1618-a05_055":{"s":"本集講如何教導大眾功夫行門以引發明心見性的因緣，以無相憶佛為核心：不依佛像佛號，二六時中保持憶佛念，並以十五秒分段等方便鍛鍊。講者指憶佛念非用來對治妄念，引《諸法無行經》、《大般若經》說明不應急斷煩惱而入二乘，最後由憶佛轉看話頭、起疑情。","p":["無相憶佛：不依色聲相，二六時中可修","以標記、分段等方便鍛鍊憶佛念","業報來時不添無謂煩惱","憶佛念不為對治妄念","由看話頭發起疑情，參究如來藏"],"k":["無相念佛","功夫行門","看話頭","疑情","明心見性","煩惱"]},"1566-a05_056":{"s":"本集講善知識如何聚集因緣成熟的學人，舉辦禪三、禪七剋期取證。講者以盆與座檯比喻福德資糧的重要，區分般若之禪與禪定、說明靜慮須先除五蓋，並批評默照禪與一念不生；也說明不可讓人猜測密意而草率印證，以及懺悔與菩薩戒的功德。","p":["剋期取證須信位具足、福德資糧夠","福德如座檯，撐得住智慧之水","般若之禪異於禪定，靜慮先除五蓋","善知識給機鋒，不為猜測者印證","懺悔可轉重業，受持菩薩戒"],"k":["剋期取證","禪七","福德資糧","靜慮","五蓋","菩薩戒"]},"1573-a05_057":{"s":"本集說明學人須因緣具足，善知識才在禪三選佛場中予以錘鍊。條件包括信力具足、憶佛定力純熟、慧力觀行（觀色身與食物不淨、確認意識非我），並以觀行降伏瞋恚與慢心等性障，及具備為眾生不畏苦的菩薩種性。","p":["信力具足：如負薪穿越火城不退","定力：憶佛念想起即起，能觀出入","慧力：觀色身、食物不淨，意識非我","以觀行化解瞋恚，斷除慢心","菩薩種性：為眾生甘入地獄"],"k":["信力","定力","慧力","性障","慢心","菩薩種性"]},"1604-a05_058":{"s":"本集說明證悟者增多後，真善知識應傳授一切種智，引導大眾邁向無生法忍。悟者已得人無我與類智忍，但未證法無我，須熏習《楞伽經》、《瑜伽師地論》、《成唯識論》等唯識經論。講者並解說菩薩煩惱不同於阿羅漢的原因、第一義空，以及不可洩露公案密意、應服膺善知識。","p":["悟者得類智忍、人無我，未證法無我","須熏唯識經論，初地滿心現觀如鏡像","菩薩不捨眾生，伏煩惱方式異於羅漢","《般若經》第一義空異於二乘之空","不可洩露公案密意，應服膺善知識"],"k":["無生法忍","一切種智","類智忍","法無我","第一義空","密意"]},"1665-a05_059":{"s":"本集說明勝義僧團需要許多親教師分擔弘法，而親教師與證悟者應身教重於言教，降伏慢心及貪瞋習氣。講者說明意根是作主之心，須以思擇與如來藏平等性來調伏瞋恚，並依經文解說菩薩自縛的四種行：輕慢他人、追求世間事、散亂心、貪著眷屬。","p":["僧團需多位親教師分擔弘法","證悟者動見觀瞻，身教重於言教","意根作主，須以善思擇調伏習氣","觀無我與如來藏平等，降伏瞋恚","菩薩四縛：輕慢、逐世間、散亂、貪眷屬"],"k":["身教","親教師","意根","性障","瞋恚","慢心"]},"1616-a05_060":{"s":"本集說明菩薩邁向初地須護持正法、破邪顯正，佛陀當年也破斥外道，因邪見會害眾生長劫輪迴。講者批評一念不生、盤腿即修行等說法，並引《佛藏經》與《楞嚴經》卷六四種清淨明誨，批評以雙身法修行、出家食肉、自稱上人或法王及大妄語等行為違背佛誡。","p":["佛陀破斥外道，為眾生究竟利益","批評一念不生即修行之說","引《佛藏經》：未證而登高座教人墮地獄","引《楞嚴經》：婬殺盜妄不除必落魔道","批評雙身法、食肉、自稱上人法王"],"k":["摧邪顯正","護持正法","楞嚴經","雙身法","大妄語","四種清淨明誨"]},"1623-a05_061":{"s":"本集辨正見與邪見，破斥把緣起法當成語言文字法或實際法的說法，指其落入無因論與自性見。再說明涅槃不生不滅，二乘人並未真證涅槃，有餘、無餘涅槃都是方便施設，涅槃唯一即如來藏，眾生本住涅槃；並說阿含識支即第八識，意根為第七識。","p":["緣起法若只是名言，不能說明諸法如何出生","緣起法若作實際法，則是生滅中求常的自性見","涅槃不生不滅，二乘依佛語而未真證","兩種涅槃皆方便，唯一涅槃即如來藏","阿含識支即第八識，楞伽經說八識"],"k":["緣起法","涅槃","如來藏","第八識","八識","斷滅見"]},"1663-a05_062":{"s":"本集從小乘緣起法說明佛與阿羅漢的差別，指出入胎識不是六識，見聞覺知心往生後世之見為佛所斥。以識與名色如三束蘆葦相依、齊識而還說明連佛也滅不了第八識；並引《大般若經》《放光般若經》說十二緣起甚深、空性為佛道、真如出生諸法而不生，即如來藏。","p":["同證緣起，為何阿羅漢不能證一切種智","入胎識非六識，意識往後世是惡見","識與名色如三蘆相依，無此識則無輪迴","齊識而還：佛亦不能滅此識","般若經說真如與法不一不異，即如來藏"],"k":["入胎識","十二因緣","第八識","真如","空性","阿賴耶識"]},"1675-a05_063":{"s":"本集開講第五章，逐句辨析《以佛法研究佛法》書中「阿含與大乘經未說阿賴耶識、緣起性空即可安立生死涅槃」之說。引《央掘魔羅經》、《解深密經》阿陀那識偈、《大乘阿毘達磨經》、《楞伽經》、《心地觀經》證經中處處說第八識，並說否定七八二識則因果錯亂、死即斷滅。","p":["第八識在經中有如來藏、阿陀那等多名","阿陀那識執持種子與根身","「無始時來界」為流轉與涅槃所依","心地觀經四法要，親近善友為首","無七八二識則因果錯亂、死後斷滅"],"k":["阿賴耶識","如來藏","阿陀那識","生死輪迴","因果","應成派中觀"]},"1546-a05_064":{"s":"本集依世親菩薩《大乘百法明門論》「一切最勝故」等偈，概說三界唯心、萬法唯識。以人間、色界、無色界、佛地、滅盡定與無想定說明一切法不離八識心王，故八識最勝；接著介紹五十一心所六類、心所三義，以及遍行五法、別境五法與各識的相應情形。","p":["百法明門論偈概說萬法唯識、三界唯心","三界有情與佛地皆依八識心王運作","滅盡定、無想定中仍有七八二識","五十一心所分六類，心所具三義","遍行五法遍八識，別境五法全與意識相應"],"k":["百法明門論","三界唯心萬法唯識","八識心王","心所法","遍行","別境"]},"1548-a05_065":{"s":"本集續講百法中的心所法，先略說善十一心所的意義及只在意識等相應而不遍一切時；再介紹六根本煩惱，說明貪、瞋的過患，並將癡分為一念無明（四住地煩惱）與無始無明（上煩惱），講二者的斷除層次；最後開始講七種慢，說明第一種「慢」。","p":["善十一法為修行立身基礎，依意識現行","根本煩惱六種，為一切惡業之根","瞋過於貪，火燒功德林","一念無明四住地，阿羅漢斷盡分段生死","無始無明上煩惱，明心始相應，佛地斷盡"],"k":["善心所","根本煩惱","無明","一念無明","無始無明","慢"]},"1547-a05_066":{"s":"本集續講根本煩惱，依次說明過慢、慢過慢、我慢、高慢、卑慢、增上慢，指出想與說都要如實可除諸慢；再講疑與疑蓋三種；最後說惡見即五利使：薩迦耶見、邊見、邪見、見取見、戒禁取見，並區分五利使為見道所斷、五鈍使為修道所斷。","p":["七種慢的差別，我慢最微細難斷","增上慢：未得謂得，阿羅漢亦未能免","所想所說皆如實，則不起諸慢","疑蓋障正信，信為道源功德母","五利使見道所斷，五鈍使修道所斷"],"k":["慢","增上慢","疑蓋","五利使","五鈍使","薩迦耶見"]},"1550-a05_067":{"s":"本集略說二十隨煩惱的小、中、大三類，再講不定心所悔、眠、尋、伺：悔可善可惡，睡眠障觀、應適度，尋伺即覺觀，並略述三界有情的尋伺與《大智度論》覺觀為三昧賊之說。接著講「二所現影故」的十一色法，含扶塵根、勝義根與法處所攝色，皆為心王心所所現之影。","p":["隨煩惱二十種，分小隨、中隨、大隨","悔與眠可善可惡，阿那律尊者故事","尋伺即覺觀，二禪以上無覺無觀","十一色法為心王心所所現之影","法處所攝色是過去五塵影像，無體"],"k":["百法明門論","隨煩惱","不定心所","尋伺","色法","法處所攝色"]},"1549-a05_068":{"s":"本集講「三位差別故」的二十四心不相應行法，是依心王、心所、色法分位假立；再講「四所顯示故」的六種無為法：虛空、擇滅、非擇滅、不動、想受滅、真如無為，說明都是第八識所顯而非所生。最後總結五位百法的次第，歸結萬法唯識、三界唯心。","p":["心不相應行二十四法為分位假立","有為法因緣和合，無為法離因緣造作","虛空無為即本來自性清淨涅槃","六無為是所顯法，四智是所生法","五位百法以八識心王為先，歸於第八識"],"k":["無為法","百法明門論","心不相應行法","本來自性清淨涅槃","真如","萬法唯識"]},"1666-a05_069":{"s":"本集開講第五章第二節「輪迴與解脫之三種緣起」，即業感、賴耶、真如緣起。說明業感緣起是善惡業種存於阿賴耶識而感果，舉行善、謗法、誤認定境或離念靈知為涅槃等例，並及二乘有學與菩薩留惑潤生；再講賴耶緣起是阿賴耶識集藏一切種，虛空不能持種，業感緣起須依賴耶緣起。","p":["三種緣起攝盡輪迴與解脫","業感緣起：業種存阿賴耶識，遇緣受報","誤認定境、離念靈知為悟成大妄語業","賴耶緣起：阿賴耶識持種，因果不亂","虛空是施設名相，不能持種"],"k":["業感緣起","賴耶緣起","阿賴耶識","因果","留惑潤生","業種"]},"1667-a05_070":{"s":"本集講第三種真如緣起：因地阿賴耶識經修行斷二障，轉成佛地真如無垢識。先轉阿賴耶識為異熟識（解脫果），再迴入別教明心、入地，到佛地斷盡變易生死；並說真如「非緣起、非非緣起」為中道，駁斥悟即成佛之說，再解說《大乘起信論》一心二門。","p":["真如緣起：阿賴耶識轉成佛地無垢識","第一階段：斷四住地，轉名異熟識","悟後仍須起修，悟不等於成佛","真如非緣起非非緣起，是中道","起信論一心二門：心真如門與心生滅門"],"k":["真如緣起","大乘起信論","一心二門","無垢識","異熟識","變易生死"]},"1559-a05_071":{"s":"本集開講第五章第三節「二乘菩提與如來藏」，先釋末法意涵，再評南傳內觀禪不如法者以覺醒性為涅槃本際而落入我見，並說北傳亦多落意識細心。指出原因在不懂十八界與涅槃本際，進而解說十八界、扶塵根與勝義根，並引《雜阿含經》說意根是心、不是大腦。","p":["末法是眾生根器陋劣，並非無正法","以覺醒性為涅槃本際，仍落我見","如法內觀：四念處次第斷我見","十八界各有功能差別","意根能去後世，是心而非大腦"],"k":["十八界","意根","斷我見","內觀禪","涅槃本際","二乘菩提"]},"1560-a05_072":{"s":"本集說明解脫道須以本識如來藏常住為前提，才能避免斷常二見。講十二因緣「齊識而還」，說涅槃只是依第八識獨存而立的名稱；依第一義諦，阿羅漢不證無餘涅槃，明心菩薩反能現觀。並舉《長阿含經》五種現見涅槃，講者批評雙身修法與以離念靈知為涅槃的說法。","p":["本識常住是解脫道修證的大前提","一切眾生本來常住涅槃","齊識而還：無明支依第八識","涅槃唯名，依異熟識獨存而立","五種現見涅槃皆是意識境界"],"k":["涅槃","無餘涅槃","如來藏","十二因緣","本來自性清淨涅槃","五現見涅槃"]},"1579-a05_073":{"s":"本集開講第五章第四節，主張唯一佛乘：佛分說三乘是因佛乘甚深，並以化城喻施設中途休息處。從現象與證量說明阿羅漢不是佛；引《中阿含經》六界、《長阿含經》識入母胎有名色，說識界不是六識、入胎識即如來藏，並提出學佛有意義的三個條件。","p":["二乘離大乘不能成佛，故說唯一佛乘","化城喻：二乘涅槃是中途化城","阿羅漢不知如來藏，不是佛","六界之識在六處前，是第八識","學佛有意義：能成佛、有未來世、有因果"],"k":["唯一佛乘","如來藏","阿羅漢","入胎識","化城喻","名色"]},"1575-a05_074":{"s":"本集續講學佛的第三個條件「因果確實存在」，以初果七返、二果一來、三果不還及大乘布施為證，並說三條件都依如來藏成立。再引《央掘魔羅經》說菩薩道是一切眾生皆有如來藏，比較滅苦之法：聲聞依四聖諦八正道、緣覺觀十因緣與十二因緣，都滅五陰；菩薩則依般若度苦厄。","p":["二乘四果與大乘布施都證明因果存在","菩薩道重心在一切眾生皆有如來藏","八苦根源都是五陰","聲聞、緣覺滅五陰入無餘涅槃","菩薩留五陰，以般若度一切苦厄"],"k":["因果","如來藏","四聖諦","八苦","十二因緣","般若"]},"1574-a05_075":{"s":"本集說明修大乘是出於悲心，要保留五陰在世間度眾，並分辨一般人的悲、菩薩的悲與大悲。接著指出大乘精髓為般若與唯識，逐段解說《金剛經》：應無所住行於布施、三輪體空、不可以身相見如來、凡所有相皆是虛妄、然燈佛所無所得、莊嚴佛土，說明都是依如來藏而說。","p":["菩薩因悲心不入無餘涅槃","悲有三層次，能自滅苦又滅眾生苦名大悲","意識必定分別，無所住指如來藏","三輪體空唯如來藏能做到","見諸相非相則見如來，即證如來藏"],"k":["金剛經","如來藏","大悲","應無所住","三輪體空","般若"]},"1578-a05_076":{"s":"本集續解《金剛經》「應無所住而生其心」、具足色身與「若以色見我」偈，說明須證如來藏後轉依。再講《心經》「色即是空」的空指如來藏，以海水海浪、木頭佛像、湯與水比喻五陰與如來藏非一非異；並引《大般若經》、《楞伽經》、《中論》佐證，提醒證後不應執著如來藏。","p":["應無所住而生其心：轉依如來藏而不入涅槃","若以色見我，不能見如來","心經的空指如來藏，非緣起性空","海水與海浪喻五陰與如來藏非一非異","龍樹：以有空義故，一切法得成"],"k":["金剛經","心經","如來藏","空性","非一非異","轉依"]},"1576-a05_077":{"s":"本集續解《心經》：五陰遮蓋實相；「不生不滅、不垢不淨」須有本體，指如來藏的中道性，並以龍樹八不說明。「空中無色」是如來藏自住的無餘涅槃境界，講者認為性空唯名之說有誤，畢竟空即諸法實相；最後講般若的總相智、別相智、道種智與一切種智，駁不證如來藏可契甚深般若之說。","p":["五陰遮蓋實相，故名為陰","不生不滅須有本體，非緣起性空","八不中道依如來藏而說","空中無色是如來藏自住境界","般若層次：總相、別相、道種智、種智"],"k":["心經","中道","如來藏","畢竟空","般若","一切種智"]},"1577-a05_078":{"s":"本集講唯識以如來藏為根本：依《楞伽經》「識廣說有八」，說明阿賴耶識、異熟識、無垢識同是第八識，並解說阿賴耶性與三種異熟性。針對有人引窺基《百法明門論解》說阿賴耶識可滅，引《成唯識論》、《大乘起信論》說所滅是心相而非心體；最後總結唯一佛乘，須親證如來藏。","p":["識廣說有八，無第九、第十識","阿賴耶性：能藏、所藏、我愛執藏","異熟性：異時、異類、變異而熟","唯心相滅，非心體滅（風水喻）","阿梨耶識若滅，同外道斷見"],"k":["唯識","阿賴耶識","異熟識","無垢識","如來藏","唯一佛乘"]},"1659-a05_079":{"s":"本集開講第五節「捨識用根之辨」，先說明六識與六根的功能、扶塵根與勝義根，並舉例說明意根。指出捨盡六識就是五種無心位，而聲聞、緣覺、大乘三種菩提的修證都需要六識運作，所以捨識用根無法修證；並評析台灣某說把捨識用根當成一念不生，以及大陸某說「集起名心」的開頭部分。","p":["六識分別六塵，六根為六識所依","勝義根損壞，識即不能生起","捨六識即眠熟、悶絕等五無心位","三乘菩提的修證都需要六識","捨識用根若指一念不生，亦不能證菩提"],"k":["捨識用根","六識","六根","意根","無心位","三乘菩提"]},"1617-a05_080":{"s":"本集說明「集起名心、思量名意、了別名識」分指第八識、意根與六識，而「同是一心而有三名」是就六識的過去、現在、未來而說；評離心意識參求一念不生之誤，並說〈耳根圓通章〉不是捨識用根。後半講第六節「宗通與胎昧」：胎昧即隔陰之迷，佛說中般涅槃即說中陰身，三地滿心有意生身方除胎昧。","p":["集起名心是第八識，思量名意是意根","一心三名是六識過去、現在、未來","耳根圓通是以耳根聽聞正法而修","胎昧即隔陰之迷，因中陰身滅而生","胎昧不礙二乘修行，三地滿心才能除"],"k":["捨識用根","心意識","胎昧","中陰身","耳根圓通","意生身"]},"1593-a05_081":{"s":"本集開講第六章「宗通與禪定」第一節，說明定是覺知心制心一處，禪定指四禪八定；宗通則須親證如來藏、現觀其體性。從內涵、相應境界（有入有出與無入無出）、《楞嚴經》五現涅槃及《大智度論》所說禪定通外道，並以南嶽懷讓磨磚作鏡公案，論證宗通非禪定。","p":["定是令覺知心專注一境，禪定至少須初禪","宗通須親證如來藏，以山水畫為喻","禪定是意識境界，有所得、有入有出","如來藏無境界、無所得、無入無出","楞嚴五現涅槃與磨磚作鏡公案明禪定非開悟"],"k":["宗通","禪定","如來藏","四禪八定","五現涅槃","磨磚作鏡"]},"1592-a05_082":{"s":"本集先從修行法門說明宗通非禪定：禪定由數息等次第修證，宗通則靠參禪破無明而證如來藏，禪定僅是助益悟後觀行。接著講第二節「宗門無念心體非是定心」，以雲門、洞山語錄及《楞伽經》說明宗門所證是如來藏，並解釋《壇經》「無念為宗」，逐一分析離念靈知、一念不生乃至四禪八定、無想定皆仍有念。","p":["禪定由數息次第修，宗通靠參禪破無明","禪定有助悟後觀行，但非宗通本身","祖師須證如來藏，公案皆留有入處","諸佛出身處、萬法歸一皆指如來藏","離念靈知、四禪八定、無想定皆仍有念"],"k":["無念心體","宗門","如來藏","無念為宗","離念靈知","四禪八定"]},"1584-a05_083":{"s":"本集進入第六章第三節，說明宗通之究竟須具福德、無量三昧、四種圓寂、一切種智四法。先講福德，從十信位行十善、三歸依，到初住至六住的六度、受菩薩戒，再到明心、見性及十行、十迴向位，說明每一位階都須修集相應福德，且修福須以智慧為先導。","p":["宗通究竟須具四法，互相含攝缺一不可","十信位修十善、三歸依，成就四不壞信","初住至六住依六度修集福德，二住受菩薩戒","福德不足者即使觸證也可能退轉","修福須以智慧為先導，不依邪見修福"],"k":["福德","宗通","菩薩五十二位階","三歸依","菩薩戒","六度"]},"1585-a05_084":{"s":"本集續講福德，從初地法布施、二地持戒，依次說明到十地、等覺百劫修相好，各地滿心的現觀與意生身都須福德支撐。之後講第二法「無量三昧」：明心須三德具足、必斷我見，四禪八定須次第證得，各位階都有應證三昧，而三昧的實證又以福德為基礎。","p":["初地至十地各主修一度，皆以福德為基礎","等覺菩薩百劫修三十二相與隨形好","明心須具般若、法身、解脫三德","四禪八定次第證，無先證四禪後證初禪","福德為先，依福德證無量三昧"],"k":["福德","無量三昧","十地","斷我見","四禪八定","十度波羅蜜"]},"1586-a05_085":{"s":"本集講宗通究竟第三法「四種圓寂」，先指出圓寂意為圓滿寂滅，並非捨壽。再說明本來自性清淨、有餘依、無餘依、無住處四種涅槃，菩薩有能力證二乘涅槃卻留惑潤生，唯佛具足四種涅槃。最後開講第四法「一切種智」，以大乘人無我智為基礎，經諸地道種智才能圓滿。","p":["圓寂是圓滿寂靜，並非捨壽之意","七住菩薩證本來自性清淨涅槃","菩薩能證二乘涅槃而留惑潤生","無住處涅槃唯佛獨有","一切種智以人無我智為基礎，四法互相含攝"],"k":["四種涅槃","圓寂","無住處涅槃","留惑潤生","一切種智","人無我"]},"1587-a05_086":{"s":"本集續講一切種智，未圓滿前稱道種智，依次說明初地至十地、等覺、妙覺各地主修的波羅蜜、現觀與意生身，到佛地四智圓明。強調一切種智不能離開第八識如來藏，也要在三界中修證，並說明四法層層依存。最後提醒修福須以正見為先導。","p":["未圓滿前稱道種智，佛地才稱一切種智","各地滿心成就鏡像、光影至大法智雲","佛地四智圓明，一切種智不離如來藏","離如來藏或以緣起性空說種智，非正說","修福須以正見為先導，依三量抉擇"],"k":["一切種智","道種智","十地","四智圓明","如來藏","正見"]},"1588-a05_087":{"s":"本集講第六章第四節「宗通之退與不退」，指出有實證才有退與不退可說，宗通又分明心與見性。明心退轉的原因有福德不足、性障重、打探密意而無親參、受名師否定等，並引《菩薩瓔珞本業經》舍利弗退轉之例。見性的退與不退則取決於看話頭的動中定力，補修定力即可恢復。","p":["有實證才談退與不退，明心見性有別","明心退因福德不足、性障重、未親參","惡知識否定致退，引瓔珞經舍利弗例","見性須定力、慧力、福德三者具足","見性境界隨定力退失，補修定力可恢復"],"k":["宗通退轉","明心","眼見佛性","性障","動中定力","菩薩瓔珞本業經"]},"1583-a05_088":{"s":"本集講第五節「宗通與五陰盡」，針對「禪宗一悟即達五陰盡」的主張，講者批評這是高抬禪宗、誤解五陰盡。說明色陰盡須斷我見並證空無邊處，受想陰盡須俱解脫四禪八定，行識陰盡則是佛地境界；明心、見性、過牢關都還達不到，並建議參閱《楞嚴經講記》。","p":["講者批評一悟即五陰盡為誤解","色陰盡須斷我見並證空無邊處","受陰想陰盡須四禪八定的俱解脫","行陰識陰盡唯佛地，斷變易生死","過三關的慧解脫者仍未達三陰盡"],"k":["五陰盡","禪宗三關","俱解脫","慧解脫","楞嚴經","明心見性"]},"1625-a05_089":{"s":"本集講第六節「橫出三界與漸出三界」，先指出淨土界兩種錯誤說法。本集處理第一種「下品往生就滿足」：依《觀無量壽佛經》說明下品三生都是造惡業者，蓮苞中須待極長時劫；中品中生要證初果、四果也極為久遠。勉勵念佛人兼修聖道門，以上品往生為目標。","p":["淨土界兩種錯誤說法，先論下品往生","觀經說下品三生皆為造惡之人","下品、中品往生出蓮苞與證果極為久遠","娑婆正法中熏習證果可較為迅速","勉勵念佛人兼修聖道門，求上品往生"],"k":["淨土","九品往生","觀無量壽佛經","下品往生","聖道門","橫出三界"]},"1626-a05_090":{"s":"本集處理第二種誤解「往生極樂即橫出三界」。講者說明出三界靠斷見惑、思惑所得的盡智，不靠禪定，所以俱解脫、慧解脫都是頓出，沒有漸出可言，定學也不應高於慧學。又以蓮苞境界與三種淨土仍有十八界，說明極樂並非三界外，應說非三界、非非三界。","p":["出三界靠盡智，不靠四禪八定","俱解脫、慧解脫都是頓出三界","定學有境界，不應高置於慧學之上","極樂三種淨土仍有十八界，非無餘涅槃","極樂世界非三界、非非三界"],"k":["橫出三界","豎出三界","盡智","定學與慧學","極樂世界","解脫果"]},"1614-a05_091":{"s":"本集講第七節「成佛——大菩提果」，說明解脫道只是佛菩提的一部分，菩薩證解脫果後仍留惑潤生行菩薩道。成佛須依第八識修證，佛菩提波羅蜜分遠、近、大三階段。本集詳述第一阿僧祇劫三賢位的遠波羅蜜：住位外門修六度，七住明心轉入內門，經十行、十迴向位，因勢力尚微弱而離佛仍遠。","p":["解脫道只是佛菩提道的一部分","佛菩提波羅蜜分遠、近、大三階段","初住至六住外門修六度，屬資糧與加行位","七住明心轉入內門，經十行、十迴向","三賢位勢力微弱，離佛仍遠，名遠波羅蜜"],"k":["大菩提果","遠波羅蜜多","三賢位","六度","內門外門","留惑潤生"]},"1615-a05_092":{"s":"本集續講近波羅蜜多與大波羅蜜多：第二阿僧祇劫初地至七地，依《楞伽經》說明各地所修布施、戒、忍、精進、禪、般若、方便及其現觀；第三阿僧祇劫八至十地修願、力、智波羅蜜。最後總結十波羅蜜的次第相，說明成佛須次第修證，不能跳越。","p":["初地至七地為第二阿僧祇劫近波羅蜜","依楞伽經說各地虛妄想漸不生","八至十地修願、力、智，名大波羅蜜","初地以上由六度改修十度波羅蜜","布施至智波羅蜜有次第，不能跳越"],"k":["近波羅蜜多","大波羅蜜多","十度波羅蜜","十地","楞伽經","成佛之道"]},"1638-a05_103":{"s":"本集開講「禪宗在佛法中的定位」，說明禪宗即佛心宗，悟的是第八識如來藏，引《宗鏡錄》、《蓮宗寶鑑》，指出禪宗是入道關鍵、內外門分水嶺。講者認為「禪宗是真常唯心系」是淺悟或未悟者之說，因佛地前種子仍有變異。並說明禪宗證悟在解脫果與佛菩提果上的對應果位，悟後仍非成佛。","p":["禪宗名佛心宗，悟第八識如來藏","證悟此心是內門外門的分水嶺","見性成佛指因地佛，悟後尚未成佛","佛地前種子仍有變異，非真常唯心","證悟可對應通教初果至四果、別教七住以上"],"k":["禪宗","佛心宗","如來藏","真常唯心","七住位","解脫果"]},"1640-a05_104":{"s":"本集續論禪宗定位，講者批評「未證如來藏也能契應甚深般若」的主張，以不入台北上不了101為喻。指出以一念不生的覺知或初醒率爾心為真如，仍是意識心與我見之我；並批評應成派中觀落入「一切法空」的誹謗見與「意識細心」的建立見。引《佛祖綱目》說明修禪須契自心源。","p":["未證如來藏不能契應甚深般若","一念不生、率爾初心仍是意識心","意識心即初果應斷的我見之我","批評一切法空為誹謗見，意識細心為建立見","須契自心源，否則如獅子身中蟲"],"k":["般若","如來藏","斷我見","應成派中觀","誹謗見","建立見"]},"1639-a05_105":{"s":"本集說明禪宗的證悟必須是證如來藏，不是意識心。依阿含所說六識、意根與「識緣名色」之識，論證佛在阿含已說八識，第八識是涅槃本際。指出法界實相只有一種，「方便有多門，歸元無二路」，如來藏是不二門、能生般若的佛母；若所悟不是第八識，只能方便說為二乘菩提的兩種悟。","p":["禪宗所悟必是如來藏，非意識心","阿含已說六識、意根與識緣名色之識","第八識是涅槃本際，前七識虛妄","法界實相唯一，八萬四千門歸不二門","非悟第八識者只是二乘兩種方便悟"],"k":["如來藏","八識","阿含","不二門","佛母","二乘菩提"]},"1641-a05_106":{"s":"本集總結禪宗定位。講者批評部分學術研究者落入應成派中觀而否定如來藏，並反駁「強調如來藏即貶斥阿含與中觀」的說法，指出如來藏正是阿含與中觀的根源。說明般若中觀即如來藏的本來、自性、清淨、涅槃性，禪宗參禪是證悟最直接的法門，與三論宗不應分宗；悟後也不應以三關自限。","p":["否定根本識如來藏，經說為一闡提","如來藏學是阿含與中觀的根源","般若中道即如來藏的四種體性","參禪最直捷，禪宗與三論宗不應分宗","悟後應求通達位，不以三關自限"],"k":["禪宗","般若中觀","如來藏","三論宗","阿含","入道關鍵"]},"1569-a05_107":{"s":"本集講「華嚴宗在佛法中的定位」，先介紹杜順、智儼、法藏、澄觀、宗密等祖師的著作與沿革，講者並評宗密以意識心為真如。再解釋「大方廣」指自心如來藏、「華嚴」指萬德莊嚴的菩薩行，說華嚴顯示五十二位成佛之道、法界緣起與三身四土。主張華嚴宗應以證如來藏為宗旨，不應分宗。","p":["華嚴宗沿革：杜順至宗密諸祖與著作","大方廣指自心如來藏，華嚴指萬德莊嚴","華嚴顯示五十二位成佛之道與法界緣起","華嚴初說是為杜絕佛次第成佛的謗說","一真法界即如來藏，華嚴宗不應分宗"],"k":["華嚴宗","華嚴經","一真法界","法界緣起","如來藏","海印三昧"]},"1630-a05_108":{"s":"本集開講「法相唯識宗在佛法中的定位」，說明此宗宗旨是八識心王為一切法主體、諸法相依藏識而生，因此應簡稱「唯識宗」而非「法相宗」。並解釋中道宗、應理圓實宗、普為一切乘教宗、瑜伽宗等異名，再敘述彌勒、無著、世親、護法、戒賢、玄奘、窺基、慧沼、智周的傳承，以及晚唐以後的衰落。","p":["一切法相依八識而生，應簡稱唯識宗","修學目的在斷人我與法我","異名：中道宗、應理圓實宗、瑜伽宗等","函蓋三乘菩提，普度三乘學人","彌勒至玄奘、窺基傳承，晚唐後漸衰"],"k":["唯識宗","八識心王","人無我","法無我","瑜伽師地論","玄奘"]},"1632-a05_109":{"s":"本集續論唯識宗定位，說明晚唐後衰微是因一切種智難知難證、善知識難得。介紹所依的六經十一論，函蓋唯識五位、五法三自性與百法。指出唯識宗與禪宗、三論宗所悟的都是同一個如來藏，三賢位勝解行即般若別相智；禪宗與般若宗悟後若不修唯識種智，就無法通達三乘、進入初地。","p":["一切種智難證、善知識難得，致晚唐衰微","所依六經十一論函蓋三乘與五十二位","宣示五法三自性，以百法攝盡佛法","入門不外禪宗，須依證悟藏識的般若","悟後須修唯識種智，方能入初地"],"k":["唯識宗","六經十一論","五法三自性","一切種智","道種智","三論宗"]},"1631-a05_110":{"s":"本集總結唯識宗定位，說明唯識兼說虛妄唯識門與真實唯識門，後者是前者的所依；唯識行者也不應自外於淨土，可求生極樂或色究竟天。講者評呂澂「性寂」與熊十力「性覺」之爭都因未明心，並批評應成派與某老法師著作否定如來藏。最後提出修唯識須具三緣。","p":["虛妄唯識門須依真實唯識門而立","唯識行者不應自外於淨土行門","評性寂、性覺之爭皆因未明心","未證如來藏學唯識只能稱為熏習","修唯識須具本性住、習所成種性及福德"],"k":["唯識宗","真實唯識門","如來藏","淨土","性寂性覺","應成派中觀"]},"1672-a05_111":{"s":"本集說明四阿含（長、中、雜、增一）各自內容，指出阿含中已隱覆密意說如來藏、本際、「識緣名色」之識。並講解佛為聲聞說阿含、為勸阿羅漢迴心說般若（金剛經、心經），三轉法輪說唯識五位、十地行果，以及四種涅槃。","p":["四阿含各部內容與四悉檀","雜阿含隱說如來藏、本際、入胎識","阿羅漢信佛語知涅槃非斷滅","心經之心不垢不淨即如來藏","四種涅槃與三轉法輪次第"],"k":["阿含經","如來藏","本際","三轉法輪","四種涅槃","般若"]},"1674-a05_112":{"s":"本集續說三轉法輪由淺至深、前後無牴觸，佛於華嚴時已頓說，依根器次第開演至法華圓滿。講者批評某佛學研究法師以應成派中觀研究佛法、否定七八識而建立意識細心，並評坦特羅佛教非佛法；末引雜阿含「取陰俱識」。","p":["三轉法輪前後貫串，法華收圓","誤取意識細心為涅槃心致無明","講者批評應成派中觀否定七八識","講者評坦特羅雙身法非佛教","雜阿含非我非異我不相在、取陰俱識"],"k":["阿含經","應成派中觀","意識細心","識緣名色","取陰俱識","坦特羅"]},"1673-a05_113":{"s":"本集解釋取陰俱識即執持五陰的阿賴耶識，引雜阿含二八九、二八八經說明厭離五陰入無餘涅槃非斷滅、名色緣識而生，證阿含已密說八識。講者批評《唯識學探源》謂原始佛教無唯識之說，強調阿含、般若、唯識如鼎三足，末法起於「人末」。","p":["取陰俱識即阿賴耶識","名色非自作他作，緣識而生","阿含已密說八識","講者批評唯識學探源之觀點","阿含、般若、唯識如鼎三足"],"k":["取陰俱識","阿賴耶識","八識論","名色緣識","無餘涅槃","阿含經"]},"1597-a05_114":{"s":"本集進入第八章「宗教二門不可相離」第一節，複習宗門（禪宗教外別傳）與教門定義，說明除乘願再來者外須依教門熏習方能證悟，真悟者必能以了義經論自我印證，主張宗教無關者屬狂禪。後段敘述平實導師與其師父的往事，回應「不尊師重道」之批評，主張重道更甚於尊師。","p":["宗門與教門之定義","未證言證屬大妄語","所悟違背經論即是悟錯","引錯悟祖師語錄易墮外道見","平實導師與師父往事，重道甚於尊師"],"k":["宗門","教門","大妄語","狂禪","破邪顯正","尊師重道"]},"1599-a05_115":{"s":"本集續說破邪顯正，回應某大德對平實導師的人身攻擊，認同「批判的佛教」理念及昭慧法師之言，主張只作法義辨正、不作人身攻擊。並辨「證悟說不出」「言語道斷」之說，引經說明密意非不可說，只是不為因緣未熟者明說；強調經教流傳能護助宗門。","p":["尊師與重道，法義辨正非人身攻擊","認同批判的佛教理念","證悟非說不出，不為緣未熟者說","定中無覺知非開悟","經教流傳護助宗門正法"],"k":["法義辨正","批判的佛教","密意","言語道斷","經教","大妄語"]},"1598-a05_116":{"s":"本集列出求悟前應讀的基礎佛法與了義經典，悟後須逐一對照。舉某法師評某禪師「分別是識，不分別是智」為例，講者引大寶積經、深密解脫經、維摩詰經、金剛三昧經、大乘同性經辨正：意識恆有分別，第八識真心向來無分別，轉識成智後體性不變；並略論無分別智之分別無窮。","p":["悟前應讀之基礎與了義經典","悟後須與經典完全相符","分別是識指前六識，不分別指真心","引五部經說明真心無分別","一念不生仍是意識有分別"],"k":["分別與無分別","阿賴耶識","意識","轉識成智","了義經典","明心"]},"1600-a05_117":{"s":"本集續舉某法師三則開示辨正：混淆清涼國師所說真如與佛性、錯解圓覺經「淫怒癡俱是梵行」、說二乘斷無明為暫時斷而外道斷妄念為永久斷。講者並指其拈提四十六則公案多錯，以南堂元靜「子胡狗」公案說明一則錯即全錯，評其「老和尚要打人」答話落在意識與意根作主。","p":["清涼國師所說為無住之真如心體","戒定慧淫怒癡俱是梵行之義","阿羅漢永斷一念無明，外道暫伏","公案一則錯則全錯","「要打人」落於意識與末那"],"k":["宗門證悟","公案拈提","真如","佛性","一念無明","無想天"]},"1620-a05_118":{"s":"本集進入第二節「教門的弘揚不得違背宗門」。讚歎謹守本分講經者，講者批評某老法師否定如來藏，評其《印度佛教思想史》「性空唯名論」誤解龍樹中論，主張般若與八不中道乃依第八識藏識的中道性而說，假必依實，離藏識說一切法空即成斷見與戲論。","p":["謹守本分講經值得讚歎","接引初機功德不抵破法根本之過","講者評性空唯名論誤解龍樹","八不中道依藏識中道性而立","離藏識說一切法空同斷見"],"k":["性空唯名","藏識","中道","中論","斷見","般若"]},"1622-a05_119":{"s":"本集續評《印度佛教思想史》將如來藏比為外道神我，講者認為係斷章取義。逐句引大般涅槃經完整經文（佛法有我即是佛性、貧女金藏喻、我者即是佛義、我者名為如來），說明如來藏是須除煩惱方能得見的假名我，不同於意識常見我。","p":["楞伽經已答如來藏非外道神我","佛法有我即佛性，指第八識假名我","貧女金藏喻：佛性被煩惱覆蓋","常樂我淨：我者即是佛義","無我名生死，我名如來法身"],"k":["如來藏我","外道神我","大般涅槃經","佛性","假名我","常見"]},"1621-a05_120":{"s":"本集續辨大法鼓經「勤方便除煩惱垢，爾乃得我」「常住安樂則必有我」，及央掘魔羅經「一切眾生皆有如來藏，我次第斷諸煩惱」被斷句取義之處。引入楞伽經依義不依語、以指示物之喻，批評執文字為義；說明平實導師改為指名評論之緣由，結論般若與種智皆依藏識而說。","p":["除煩惱垢方得如來藏假名我","常住安樂之我非蘊處界我","講者指央掘魔羅經被斷句取義","楞伽經：依義不依語、莫執文字指","般若種智皆依藏識而說"],"k":["如來藏","大法鼓經","央掘魔羅經","依義不依語","楞伽經","外道神我"]},"1636-a05_121":{"s":"本集介紹狂禪：證悟即悟第八識如來藏，悟有淺深，須悟後起修六度。舉臨濟義玄、德山宣鑒（周金剛、點心婆問心、燒青龍疏鈔）、夾山善會訶佛罵祖之語，講者認為淺悟者因慢心墮於狂禪，易誤導後學；並列三賢十地之現觀，說明初悟僅七住，不應輕慢三寶。","p":["證悟即悟如來藏，悟有淺深","理則頓悟，事須因次第盡","臨濟、德山、夾山之狂語","德山遇點心婆與燒疏鈔","初悟僅七住，不應輕慢聖道"],"k":["狂禪","如來藏","悟後起修","德山宣鑒","臨濟義玄","三賢十地"]},"1637-a05_122":{"s":"本集續說狂禪：真悟祖師不輕教門，舉達摩以楞伽經印證、藥山看經遮眼。再介紹狂密：講者批評否定七八識、以意識細心取代如來藏、貶顯教為因位、以雙身法為即身成佛等皆屬狂密。後開始「佛教不應分宗立派」，說明二乘菩提與十八界空相。","p":["真悟者不輕教門，藥山看經","否定七八識或以意識細心代如來藏","講者評雙身法冒稱即身成佛","一切宗派應依經教檢驗","二乘菩提：十八界無常苦空無我"],"k":["狂禪","狂密","八識","意識細心","十八界","二乘菩提"]},"1563-a05_123":{"s":"本集說明聲聞觀五蘊十二處十八界無常苦空無我，斷我見我執成阿羅漢，證有餘、無餘涅槃；緣覺以十二因緣流轉還滅證解脫。再講大乘四種涅槃：七住證本來自性清淨涅槃，菩薩人無我依楞伽經機發像起、咒力起屍喻；初地法無我，初地、三地能取證解脫而不取。","p":["聲聞觀蘊處界斷我見我執","有餘涅槃與無餘涅槃之別","緣覺順逆觀十二因緣","七住證本來自性清淨涅槃","菩薩人無我、法無我與不取證"],"k":["四種涅槃","人無我","法無我","十二因緣","本來自性清淨涅槃","解脫道"]},"1562-a05_124":{"s":"本集續說三地菩薩因十無盡願與大悲而留惑潤生、不取俱解脫；六地證滅盡定，七地念念入滅，佛傳引發如來妙智三昧而入八地，至佛地現起無住處涅槃。再以八識心王說明涅槃是第八識如來藏自住境界，本來不生不死，非修行後才有，取涅槃只是方便說。","p":["十無盡願與大悲，留惑潤生","六地滅盡定、七地佛授三昧","佛地無住處涅槃兼無餘涅槃","八識心王：前七識由第八識生","涅槃即如來藏自住境界"],"k":["無住處涅槃","留惑潤生","八識心王","涅槃","如來藏","十無盡願"]},"1565-a05_125":{"s":"本集說明涅槃是所顯得而非所生得，四種涅槃皆非修非不修而為中道。結論二乘、大乘各自法義無異，不應分宗立派；主張依別教次第：明心後修般若三論，再修唯識，兼學俱舍、華嚴並簡擇天台；依解深密經三時教主張般若應在方等之前。講者亦評坦特羅為附佛外道。","p":["涅槃所顯得，非修非不修","二乘、大乘法無異，不應分宗","明心→般若三論→唯識之次第","俱舍、華嚴、天台之取捨","三時教：阿含、般若、方等"],"k":["分宗立派","涅槃","三時教","唯識","般若","天台宗"]},"1564-a05_126":{"s":"本集講者批評坦特羅金剛乘不應在佛教立宗，主張以道種智重研阿含中如來藏密意；引大薩遮尼乾子所說經說三乘是地、法相、人之差別而非乘差別，本唯一佛乘，故不應分宗，並說明正覺同修會不立宗派。後開始「慎莫盜法」：三轉法輪如來藏密意不明說，盜法罪重於竊盜與大妄語。","p":["講者評金剛乘頭上安頭","以道種智重研阿含如來藏密意","三乘只是方便，本唯一佛乘","正覺同修會不立正覺宗","如來藏密意不明說，盜法罪重"],"k":["唯一佛乘","分宗立派","盜法","如來藏密意","三乘","法華經"]},"1613-a05_127":{"s":"本集講述雜阿含三四七經須深盜法故事：外道派須深出家盜法，慧解脫比丘不具禪定，佛說「先知法住，後知涅槃」並講十二因緣，須深得法眼淨後懺悔，佛以刺三百矛喻盜法苦報更甚。並說明大乘如來藏盜法罪更重，及捨外道、歸依、受五戒修十善的正確學法心態。","p":["不可為師長名利入正法盜法","須深盜法與慧解脫比丘","先知法住，後知涅槃","三百矛喻盜法苦報","學法應捨外道、歸依受戒"],"k":["盜法","須深","慧解脫","法住智","十二因緣","歸依三寶"]},"1612-a05_128":{"s":"本集說明修學別教佛菩提須受菩薩戒，並修次法（定力、斷我見、福德、降伏性障等）方能證悟。講者舉某一貫道講師不歸依受戒、轉學他人後回傳外道之事為盜法例，列盜法四種過失；並引六祖壇經頓漸品「法本一宗」及志誠奉神秀命來盜法而坦白之事。","p":["求證如來藏須受菩薩戒修次法","一貫道講師之盜法案例","盜法四過：相似、無智、無證、違戒","六祖：法本一宗，人有利鈍","志誠坦白來意即非盜法"],"k":["盜法","菩薩戒","次法","六祖壇經","頓漸","如來藏"]},"1627-a05_129":{"s":"本集說明求宗通、說通須先證悟如來藏，勝解般若三論，並熏習唯識經論。不能證悟原因在福慧不足、慢心與著表相；講者主張法義辨正是善法，引雜阿含「我不與世間諍」說明如法說即無諍。並說真善知識不以出家在家相或善於言說判定，引楞伽經「多聞者謂善於義」。","p":["二通須證如來藏並修唯識經論","福慧不足、慢心、著相為障","法義辨正非諍，佛不與世間諍","勿以表相或著作判善知識","大德多聞是善於義"],"k":["宗通與說通","真善知識","法義辨正","無諍","依法不依人","唯識經論"]},"1628-a05_130":{"s":"本集引楞伽經說明宗通即明心見性、證第八識如來藏、住自覺聖智而離一異有無二邊；說通是隨眾生心演說人無我與法無我的智慧。分別說明聲聞、緣覺、菩薩的人無我與法無我，菩薩法無我上至佛地二種轉依果。本集為《宗通與說通》全書介紹之圓滿。","p":["宗通：證阿賴耶識，自覺聖智","宗趣法相與言說法相","三乘人無我之異同","緣覺觀識緣名色之法無我","菩薩法無我至佛地二轉依果"],"k":["宗通","說通","人無我","法無我","自覺聖智","四智圓明"]},"1695-a06_001":{"s":"本集說明製作「三乘菩提概說」的緣起與總綱：佛法是成佛之法，分聲聞、緣覺、佛菩提三乘，可歸為出離生死的解脫道與親證法界實相的佛菩提道。強調解脫靠斷我見我執的智慧而非禪定，並介紹四種涅槃，以及明心證如來藏只到七住，須具四緣才能入初地。","p":["緣起：學人缺乏三乘菩提的正知見而停滯不前","解脫道出離三界，佛菩提道證法界實相","解脫依無我智慧而得，禪定只是助緣","四種涅槃中唯佛具足無住處涅槃","明心只是七住，須具四緣方能入初地"],"k":["三乘菩提","解脫道","佛菩提道","四種涅槃","如來藏","明心"]},"1757-a06_002":{"s":"本集說明聲聞菩提：聽聞佛或聖弟子說蘊處界無真實我，而斷我見、我執證果；並依根性利鈍、五蓋深淺分析各類行者的修證差異，及五下分結、五上分結。接著總說四聖諦：世尊何時對誰說、何以稱「諦」，並引《中阿含經‧象跡喻經》說明一切善法皆為四聖諦所攝。","p":["聲聞菩提：聞法覺悟蘊處界無真實我","根性利鈍與五蓋深淺影響證果遲速","斷五下分結證三果，斷五上分結成四果","初轉法輪對五比丘說四聖諦，臨滅三度問疑","諦是真實不顛倒義，一切善法皆四聖諦所攝"],"k":["聲聞菩提","四聖諦","斷我見","五蓋","五下分結","阿羅漢"]},"1754-a06_003":{"s":"本集先比較二乘與大乘四聖諦：二乘依蘊處界緣起性空的世俗諦說，大乘則依如來藏法界實相說。接著進入苦聖諦，說明唯有聖者如實知見的苦才稱聖諦，列出八苦，並詳述生苦（眾苦所逼、餘苦所依，含胎中之苦）與老苦（增長與壞滅）。","p":["四聖諦通三乘，大乘依如來藏而說","二乘依蘊處界觀無常、苦、無我、空","凡夫知苦而無諦，聖者如實知見方為聖諦","八苦根源在五陰熾盛","生苦為眾苦所逼、餘苦所依；老苦含增長壞滅"],"k":["苦聖諦","四聖諦","八苦","生苦","老苦","如來藏"]},"1748-a06_004":{"s":"本集續講苦聖諦，依《中阿含經‧舍梨子相應品》等說明病苦、死苦、怨憎會苦與愛別離苦。病苦分四大不調的身病與由此引生的心病；死苦分病死與外緣死；怨憎會、愛別離二苦則從事相與理上分說，理上歸於內六處、外六處及六界的和合與分離。","p":["病苦：四大不調成身病，進而引生心病","死苦分病死與外緣而死，身心全面領受","怨憎會苦事相上為遇所厭之人","理上：不可愛的內外六處和合即怨憎會","愛別離苦分生離死別，理上為六處六界分散"],"k":["苦聖諦","病苦","死苦","怨憎會苦","愛別離苦","六界"]},"1747-a06_005":{"s":"本集續講愛別離苦的理上意涵，再從人、事、物及理上說明求不得苦，包括求不生、不老、不死而不可得。接著解釋五陰與五蘊的名義，逐一說明色受想行識熾盛如何成苦；並歸納生老病死屬身苦、怨憎會等屬心苦，五陰熾盛總括身心，須依解脫道或佛菩提道方能離苦。","p":["愛別離苦：內外六處與六界分離之苦","求不得苦涵蓋人事物，理上求不生老死不可得","陰為遮蓋真如，蘊為積聚後有種子","五陰各自熾盛，總攝前七苦","離八苦須依解脫道或大乘佛菩提道"],"k":["苦聖諦","五陰熾盛苦","求不得苦","五蘊","愛別離苦"]},"1749-a06_006":{"s":"本集總結苦聖諦，解釋經中「不離於如」指真如本心，故無餘涅槃非斷滅。隨後講苦集聖諦，依《增壹阿含經》說苦因在愛與欲相應而心恆染著，說明愛、欲心所及欲愛、有愛、無有愛三愛，並依《中阿含經》歸納：對內六處、我所、外六塵、六界的貪愛執著即是苦集。","p":["苦聖諦不離於如，即不離真如本心","苦集聖諦探討八苦生起的原因","愛與欲相應、心恆染著即苦習諦","三愛：欲愛、有愛、無有愛","貪著內六處、我所、外六塵、六界即苦集"],"k":["苦集聖諦","三愛","愛欲","苦聖諦","真如","六界"]},"1750-a06_007":{"s":"本集講苦滅聖諦：依《大乘義章》、《瑜伽師地論》說滅即滅煩惱、滅生死，煩惱滅得有餘依、所依滅得無餘依。再詳說大乘四種涅槃，強調有餘、無餘涅槃都依如來藏的本來自性清淨涅槃而施設；指出四聖諦含流轉與還滅兩種緣起，並引《中阿含經》說對六根、我所、六塵、六界斷捨吐盡即是苦滅。","p":["滅即滅煩惱、滅生死，即是涅槃","煩惱滅得有餘依，所依滅得無餘依","大乘四種涅槃皆依如來藏而說","苦、集為流轉，滅、道為還滅","對六根、我所、六塵、六界斷捨吐盡名苦滅"],"k":["苦滅聖諦","涅槃","四種涅槃","如來藏","有餘涅槃","無餘涅槃"]},"1751-a06_008":{"s":"本集總結苦滅聖諦，強調愛滅苦滅依於「如」，並非一切皆無的斷滅空，並歸納滅苦須斷盡三世對六根、我所、六塵、六界的貪愛。接著進入苦滅道聖諦，依《俱舍論》說道是通往涅槃之路，列出三十七道品七類與八正道，並詳解四念處如何對治淨、樂、常、我四顛倒。","p":["苦滅不離於如，非斷滅空","滅苦須斷盡三世對六根六塵六界的貪愛","道聖諦是通往涅槃之路","三十七道品分七類，含八正道","四念處對治淨、樂、常、我四顛倒"],"k":["苦滅道聖諦","苦滅聖諦","三十七道品","四念處","四顛倒","斷滅空"]},"1753-a06_009":{"s":"本集續講苦滅道聖諦的三十七道品：說明四念處以慧為體、令念住於所觀境，故稱念住；四正勤即斷惡生善的四種精勤，又稱四正斷、四意端；四如意足由欲、勤、念、觀四力引發定慧均等而得名。最後開始講五根、五力，說明由信根、信力進而精進，現觀蘊處界空，輾轉入大乘證如來藏。","p":["四念處以慧為體，令念住境故稱念住","四正勤：已生惡令斷、未生善令生等","因須發自意處，四正勤又稱四意端","四如意足由欲勤念觀引發定慧均等","由信力、精進力現觀蘊處界空而入大乘"],"k":["三十七道品","四念處","四正勤","四如意足","五根五力"]},"1752-a06_010":{"s":"本集完成苦滅道聖諦：依大乘菩薩修行次第說明五根、五力，念力、定力、慧力分別對應悟後進修、三地四禪八定及知他心智。再比較二乘與菩薩的七覺支，指出大乘三十七道品依法界實相如來藏而修。最後總結四聖諦：苦、集為流轉的世間因果，滅、道為還滅的出世間因果。","p":["精進力現觀蘊處界空，輾轉入大乘證如來藏","定力指三地四禪八定，慧力指知他心智","七覺支：二乘與菩薩所觀有別","菩薩依法界實相修三十七菩提分","苦集為流轉因果，滅道為還滅因果"],"k":["五根五力","七覺支","三十七道品","四聖諦","法界實相","如來藏"]},"1790-a06_021":{"s":"本集說明蘊處界對三乘菩提的重要性：證聲聞初果須斷我見，緣覺觀十二因緣也含蘊處界，大乘行者若不懂蘊處界，易把清楚明白心或一念不生誤認為真心（講者的批評）。並說三乘之外沒有其他菩提，介紹三法印與聞思修，最後開始講十二處的「處」義與五根的功能。","p":["斷我見證初果，須先了解蘊處界","十二因緣中的名色、六入、識含蘊處界","誤認清楚明白心為真心是落入我見","三法印：諸行無常、諸法無我、涅槃寂靜","十二處即六根、六塵，處為六入生起處所"],"k":["十二處","蘊處界","三乘菩提","斷我見","三法印"]},"1792-a06_022":{"s":"本集續講十二處的六根：解釋「根」義，五根分浮塵根（扶塵根）與勝義根，說明心無法直接觸及物質，須由五根接收外五塵，再由如來藏變現內五塵供識分別。接著以忘關瓦斯、淡忘等生活例子說明意根對過去事的作用，並說修定不好與意根的執著有關，最後引《中阿含經》說明意根只能察覺法塵的重大變動。","p":["根是識生起與運作的依靠","五根分浮塵根與勝義根","如來藏變現內五塵，覺知心於其上分別","意根依事情重要性提醒，淡忘是重要性降低","意根只能察覺法塵有無重大變動"],"k":["意根","六根","勝義根","浮塵根","十二處","如來藏"]},"1791-a06_023":{"s":"本集續講意根：以消防車聲把人吵醒、預定早起等例子，說明意根在現在、未來事上的作用，指出意根是身口意行的作主者，與貪、癡、我見、慢四煩惱相應，斷盡其相應煩惱即成阿羅漢。講者並從無色界、無心位及來世等角度，駁斥意根是大腦或意識種子的說法，最後簡介六塵。","p":["意根不睡，法塵有大變動即喚起覺知心","意根是身口意行的作主者","意根與四煩惱相應，令六識雜染","從無色界與無心位論證意根非大腦","意根若是意識種子，十八界將成十七界"],"k":["意根","末那識","解脫道","滅盡定","無想定","六塵"]},"1788-a06_024":{"s":"本集開講十八界：「界」指功能差別，一切世間法都不出六根、六塵、六識。依《長阿含經》說內外六入，區分外相分與內相分及見分、相分；依《瑜伽師地論》解說色塵的顯色、形色、表色，並說明五塵上的法塵，以及法處所攝色、夢境、定境法塵等法塵內涵。","p":["界即功能差別，一切法不出十八界","六塵分外六塵（外相分）與內六塵（內相分）","色塵含顯色十三法，另有形色、表色","五塵的差別相即五塵上的法塵","法處所攝色、夢境、定境皆屬法塵"],"k":["十八界","六塵","法塵","相分","法處所攝色","內六入"]},"1789-a06_025":{"s":"本集以百法說明法處範圍：八識與五根、五塵之外的八十二法都屬法處。接著講六識生起的條件，依《雜阿含經》說根塵和合生識，並詳列眼識九緣、耳識八緣、鼻舌身識七緣、意識五緣、意根三緣。最後講者批評想把六識修到無分別的看法是邪見。","p":["八識、五根、五塵以外的八十二法屬法處","根、塵為緣，識才生起","眼識需空、明等九緣，耳識八緣","鼻舌身識七緣，意識五緣，意根三緣","六識本是分別心，不可能修到無分別"],"k":["十八界","六識","九緣","法處","百法","意根"]},"1784-a06_026":{"s":"本集先以吃蘋果為例，把十八界分六組說明其同時運作。再講「現行熏種子」：身口意行造作善、惡、無記業，業種存於第八識並不斷被熏改；「種子生現行」：死後由第八識生中陰身，投胎方向受業力、願力、定力、習氣等影響，出生後個性與根器差異都來自過去熏習。","p":["以吃蘋果為例說明十八界同時運作","現行即身口意行，業種藏於第八識","現行熏習不斷改變第八識中的種子","投胎受業力、願力、定力、習氣等影響","個性根器差異源於過去所熏種子"],"k":["種子","現行","第八識","十八界","中陰身","業力"]},"1705-a06_027":{"s":"本集開講五蘊的空相及苦患：先以四聖諦說明八苦皆因五蘊，斷我見、我執即可完成解脫道。接著講色蘊無常：依《中阿含經》、《長阿含經》說色身由入胎的第八識和合六界而成，既非母親所造也非自然生，並以「色如聚沫」比喻；再說色蘊中的五塵是內五塵，最後開始講受蘊。","p":["八苦皆因有五蘊而起","以四聖諦說明斷我見我執與五蘊的關係","色身由第八識和合地水火風空而成","色如聚沫，依緣而生終歸壞滅","色蘊中的五塵是內五塵"],"k":["五蘊","色蘊","無常","四聖諦","第八識","斷我見"]},"1707-a06_028":{"s":"本集講受蘊無常：以苦瓜、按摩、開店等例說明苦中有樂、樂中有苦、不苦不樂中亦有苦樂，又以聞臭味等例說明受不真實，結論是有受皆苦。接著依《增壹阿含經》說想即是知，講者指出離念靈知、一念不生、了了常知乃至四禪、非想非非想定都未出想陰，想如陽燄而無常。","p":["苦樂與不苦不樂相互夾雜，非純然","受不真實，有受皆苦","想即是知，語言文字妄想亦屬想","離念靈知、一念不生仍落在想陰","想依其餘四陰和合而有，如陽燄"],"k":["五蘊","受蘊","想蘊","無常","離念靈知","五現涅槃"]},"1706-a06_029":{"s":"本集講行蘊與識蘊無常：依《增壹阿含經》說行是能有所成，空間轉換、時間流逝皆屬行，行如芭蕉。識蘊為因緣所生、剎那生滅，於眠熟、悶絕、無想定、滅盡定及死亡時都會中斷；意根雖無始相續，仍是生滅法。並說五蘊依第八識而有，再開始講證入五蘊空相的前方便「聞」，引《華嚴經》說善知識難遇。","p":["行是能有所成，含空間轉換與時間流逝","行蘊依其餘四蘊和合而有，如芭蕉","六識剎那生滅，眠熟、無心定時中斷","意根亦剎那生滅，阿羅漢入無餘時滅","前方便之聞：讀經典並親近難遇的善知識"],"k":["五蘊","行蘊","識蘊","無常","意根","善知識"]},"1708-a06_030":{"s":"本集講證入五蘊空相：前方便由聞而思，從仰信轉為解信。接著介紹三種輔助方法：以四念處觀斷我見、我執；思惟摶食、觸食、念食、識食四食以斷我執，並引《雜阿含經》夫婦食子肉之喻說明如何觀摶食；以及經由參禪明心見性，參禪前須先斷我見，悟後依智慧斷我執。","p":["聞後思惟，由仰信轉為解信","四念處觀可斷我見並斷我執","思惟四食斷我執，所斷是對食的貪愛","以夫婦食子肉喻說明如何觀摶食","參禪前先斷我見，明心後斷我執"],"k":["五蘊空相","四念處","四食","斷我執","明心見性","斷我見"]},"1482-a03_045":{"s":"本集續講繫念思惟念佛法門：先說明極樂世界三賢位菩薩得不退轉的多種殊勝功德（長壽、無女人、六塵殊勝、無惡友等）；再講繫念思惟阿彌陀佛名號不可思議（無量壽、無量光、妙光作佛事），指出持名念佛含攝其中；並引世親菩薩《往生論》五念門，開始介紹佛功德八種莊嚴中的座、身、口莊嚴。","p":["極樂世界多種功德令三賢位菩薩不退轉","佛名號代表無量功德，稱念可滅重罪","無量壽、無量光與妙光作佛事","《往生論》五念門與繫念思惟的關係","八種莊嚴：座、身、口莊嚴"],"k":["繫念思惟念佛","極樂世界","阿彌陀佛名號","五念門","往生論","不退轉"]},"1485-a03_046":{"s":"本集續講阿彌陀佛的心、眾、上首、主、不虛作住持莊嚴，說明佛心如四大虛空無分別，是通達如來藏的無分別智；總結《稱讚淨土佛攝受經》三種繫念思惟法，建議一生至少受持一次八關齋戒一日一夜修此法；再引《大阿彌陀經》讀誦思惟及《阿彌陀過度人道經》十日十夜一心求生的念佛法。","p":["心莊嚴：如四大虛空的無分別智","眾、上首、主、不虛作住持莊嚴","總結《稱讚淨土佛攝受經》三種繫念思惟","建議受八關齋戒一日一夜繫念思惟","《大阿彌陀經》等經的思惟求生法"],"k":["繫念思惟念佛","阿彌陀佛功德莊嚴","無分別智","八關齋戒","稱讚淨土佛攝受經","大阿彌陀經"]},"1484-a03_047":{"s":"本集先完成繫念思惟：引《過度人道經》一日一夜念生佛國、《無量壽經》下輩一向專意、十念及一念求生、《平等覺經》十晝夜一心求生、《大阿彌陀經》稱讚歸命發願，說明多數念佛法門通於繫念思惟；補述疑悔導致邊城胎生；再開始略述念佛種類，介紹四種佛身及念應身佛（八相成道）。","p":["下輩眾生一日一夜或十念求生亦得往生","多數念佛法門與繫念思惟相關","疑悔之心導致邊城胎生","念佛有有相、無相、實相之深淺","四種佛身與念應身佛"],"k":["繫念思惟念佛","下品往生","邊城胎生","無量壽經","念佛種類","應身佛"]},"1477-a03_048":{"s":"本集講念化身佛（定中夢中感應所見之佛）與念報身佛，引《觀無量壽佛經》說明報身不可思議但憑佛宿願力可成就，並引《央掘摩羅經》說釋迦佛報身住持十方八十億佛世界，世間永遠有佛；接著講念法身佛，說法身即如來藏，非色、非心、非佛，須離相而念即無相念佛，並引《佛藏經》說法身言語道斷。","p":["念化身佛：念感應所見之佛","念報身佛憑佛宿願力成就","《央掘摩羅經》：釋迦報身住十方","法身即如來藏，非色非心非佛","念法身佛須離相，言語道斷"],"k":["念報身佛","念法身佛","如來藏","央掘摩羅經","佛藏經","無相念佛"]},"1476-a03_049":{"s":"本集續解《佛藏經》念法身佛「過出諸念、不可得念、一切諸念皆寂滅相」，說明眾生心念五欲、六塵、五陰而法身無念；引《華嚴經》說法身無來去、有相佛如幻；區分因地與果地無相念佛，以母子相憶比喻無相念，對應大勢至念佛圓通「都攝六根、淨念相繼」；並說修無相念佛須除慢心、疑心及覺觀攀緣。","p":["眾生心念五陰六塵，法身無念","《華嚴經》：法身無來去，有相佛如幻","因地無相念佛如母子相憶","都攝六根、淨念相繼可得念佛三昧","須除慢心、疑心及覺觀攀緣"],"k":["無相念佛","念法身佛","都攝六根","淨念相繼","大勢至念佛圓通","慢心"]},"1478-a03_050":{"s":"本集講修無相念佛須具定慧知見與以妄止妄之理，以數息為喻，說明憶佛純熟時應捨佛號轉進；介紹從有相到無相四階段：口念耳聽、心念心聽、心念心憶、不念而憶，並提醒勿走入未到地定；再述修學四轉折：從散亂到專一、從有入無、從無入真（依善知識證悟法身）、從真入實（悟後體究念佛）。","p":["以妄止妄：數目與佛號皆須適時捨","有相到無相念佛四階段","心念心聽過專注易入定而非念佛","修學四轉折：從散亂到從真入實","悟後觀行蘊處界皆真如所生並轉依"],"k":["無相念佛","定慧知見","以妄止妄","不念而憶","體究念佛","轉依"]},"1456-a03_051":{"s":"正旭老師接講《念佛三昧修學次第》第五章第二節，說明念佛為何要無相：持名多注意名號、觀想難至第九觀，都不易與無相的自性彌陀相應；引〈大勢至念佛圓通章〉「不假方便，自得心開」，並以《觀經》上品上生三心與三種眾生條件、《占察經》至心與深心，論證證得自性彌陀者具上品上生資格。","p":["持名多注意名號，名號並非佛","憶佛念佛可不假方便自得心開","上品上生須至誠心、深心、迴向發願心","證自性彌陀者具足上品上生條件","觀想念佛與無相念佛互相抵觸"],"k":["無相念佛","上品上生","自性彌陀","大勢至念佛圓通","觀無量壽佛經","持名念佛"]},"1458-a03_052":{"s":"本集續解《大阿彌陀經》「來無所來、去無所去」，指淨土經亦含般若之理；說明五根根性，根性不足可依善知識；辨「一句佛號概括事理」僅適用於證得自性彌陀者；以敲門磚喻無相念佛，並據五十二菩薩說此法可用至妙覺；最後介紹第一次第無相憶念拜佛，並分享講者由想媽媽轉為憶佛的體驗。","p":["淨土經中亦有般若之理","五根根性，慧根不足可依善知識","一句佛號概括事理是對證悟者說","無相念佛如敲門磚，可用至妙覺","無相憶念拜佛及講者體驗"],"k":["無相念佛","無相憶念拜佛","五根","事理","自性彌陀","憶佛"]},"1457-a03_053":{"s":"本集講無相念佛十次第的前四次第：先補充以想念久別故人體會憶佛，再詳述拜佛要領（緩慢、一拜四十五秒至一分鐘、選定一尊佛菩薩、分段提念）；第二次第每日早晚張眼精進拜佛；第三次第閉眼無相憶念拜佛並分析頭暈三種原因；第四次第避免控制呼吸，說明成因與處理。","p":["以想念久別故人體會憶佛","拜佛要緩慢、專注動作、分段提念","每天早晚至少各拜二十分鐘","閉眼拜佛對治細妄想及頭暈處理","避免意根攀緣呼吸而控制呼吸"],"k":["無相憶念拜佛","無相念佛","拜佛要領","憶佛","妄想"]},"1459-a03_054":{"s":"本集續講無相念佛第五至第十次第：閉眼拜佛一念相續、張眼無相憶念拜佛、四威儀中憶佛（貼標語等方便）、禮拜三至六尊佛菩薩以培養參禪思惟觀、一切時中憶佛不忘、動靜兼修；並對應〈大勢至念佛圓通章〉所說功德，說明可進入憶佛定，性障微薄者可發起初禪。","p":["一念相續比一念不生易見自性彌陀","張眼拜佛時心往內收","四威儀中憶佛即都攝六根淨念相繼","禮拜多尊佛菩薩訓練思惟觀","動靜兼修，可入憶佛定乃至初禪"],"k":["無相念佛","一念相續","思惟觀","四威儀","憶佛定","初禪"]},"1425-a03_055":{"s":"本集開講第六章體究念佛，引蓮池大師《阿彌陀經疏鈔》說明體究即參究念佛者是誰；比較《觀經》上品上生與上品中生的差別，勸求上品上生；分析無相念佛成就後三種狀態；說明話頭即念頭，無相念佛是照顧話頭，參話頭須有疑；並指出體究前應讀阿含與大乘經典具第一義知見，以一念不生為悟是落入我見。","p":["體究念佛即參究「念佛者是誰」","上品上生與上品中生差別甚大","一念相續或憶佛定者可轉體究","無相念佛是照顧話頭，參話頭須有疑","須具第一義知見，一念不生非開悟"],"k":["體究念佛","參話頭","上品上生","第一義","自性彌陀","一念不生"]},"1426-a03_056":{"s":"正益老師說明體究念佛是依般若尋找非三界法的實相心，即法身佛、自性彌陀，不可以色身或意識為如來；以心湖行船比喻持名、默念都擾動心湖，憶佛念則如石沉湖底仍在；勸持名者轉進以提高品位，並須依善知識熏習般若分清真妄心；舉阿難「認賊作父」等說明見聞覺知心與一念不生都不是真心。","p":["體究是尋找法身佛、自性彌陀","不可以色身或意識心為如來","心湖喻：憶佛念無相而仍在","須依善知識聞思修分辨真妄心","見聞覺知與一念不生皆非真心"],"k":["體究念佛","法身佛","如來藏","憶佛","真心妄心","一念不生"]},"1427-a03_057":{"s":"本集先提醒佛法須簡別外道法，講者批評有人將性力派左道及「本初佛」之說引入佛門；接著講體究念佛第一科目思惟觀：憶佛定力純熟後，不用語言文字推理，以直觀看住話頭整句意涵（如「念佛是誰」）；並強調須先對五蘊觀行、分清諸法，以聞思修建立正見，專注日久可發起疑情。","p":["講者批評本初佛等說非佛法","憶佛念純熟如風箏，不必入定境","思惟觀：直觀看話頭，不以文字推理","話頭是疑問句，取意不取文字","先觀行五蘊，日久發起疑情"],"k":["思惟觀","看話頭","體究念佛","疑情","五蘊觀行","簡別外道"]},"1497-a03_058":{"s":"本集講體究念佛第二科目「隨時隨地體究」：除睡眠外隨時可參；強調體究前須具思慧，教以善知識書籍逐步複述、列綱要與法句、遮書練習至提綱挈領，以達思決定；提醒念佛人不求感應，危險工作時勿參；勸勿急求開悟，重在菩薩種性與悟後安止，否則易退轉。","p":["除睡眠外可隨時隨地體究","以複述書籍、列綱要培養思慧","不求感應，慎防鬼神化現佛身","開車、高空等危險工作時勿參","重菩薩種性，悟後須安止免退轉"],"k":["體究念佛","聞思修","菩薩種性","退轉","善知識"]},"1447-a03_059":{"s":"本集講體究念佛第三、四科目：應遠離貪欲，須從布施、持戒著手，引《梵網經》先教捨內財，指出持戒精神在攝受有情，並引玄奘所譯經說三歸依功德殊勝，勸受三歸五戒，但利益眾生的善法欲不可捨；應遠離慢心，指貢高我慢遮障聖道，以善財童子參訪為榜樣，勸親近善知識。","p":["貪欲執取障道，須以布施持戒對治","持戒精神在攝受有情","三歸依功德勝過久供諸佛","利益眾生的善法欲不可捨","慢心遮障聖道，應依止善知識"],"k":["遠離貪欲","遠離慢心","布施","持戒","三歸五戒","善知識"]},"1435-a03_060":{"s":"本集講第五科目勿求神通感應：引《金剛經》「不可以身相得見如來」，說明定境易令人貪著；講者並批評顯密之分，指如來秘密即真心如來藏，貫串三時五教（阿含識支、般若空性、方廣唯識等）；第六科目勿希望佛菩薩現身助悟，指佛菩薩只冥佑，現身說法多為鬼神冒充，並教檢驗方法。","p":["不可以身相見如來，勿求神通","定境易令人貪著不出","如來秘密即如來藏，貫串五時教","講者批評顯密之分貶抑佛法","佛菩薩冥佑，現身助悟多屬鬼神"],"k":["神通感應","如來藏","定境","顯密","十因緣","菩薩種性"]},"1479-a03_061":{"s":"本集講體究念佛第七至九科目：疲倦煩悶是正常現象，因直觀違反語言文字習慣，約一兩月可安住，不應退失；應保持充足睡眠，舉禪師自限期限而錯認真心、二十億耳比丘彈琴之喻，說明精進過與不及皆不好；不必害怕忽略現實，疑情濃時恍惚是功夫得力之相，可預立遺囑並信護法神護持。","p":["直觀異於語言習慣，疲倦煩悶屬正常","退失甚深法需一大劫彌補","勿自限期限，否則易錯認真心","二十億耳比丘：精進須調和","忽略現實是得力之相，學佛須長遠"],"k":["體究念佛","精進","睡眠","疑情","二十億耳比丘","安忍"]},"1448-a03_062":{"s":"本集講最後科目「當發大願心和長遠心」：列舉放下一切、以見聞覺知為真心、一念不生、苦行、禪定等被佛判為外道的知見；勸依止經典與善知識，修布施、持戒；講者批評大型灌頂、自稱法王、雙身法及葷血祭祀等；並舉大悲菩薩化肉山等本生，勉勵發四弘誓願、長遠奉獻佛教。","p":["放下、一念不生、苦行等被判外道","應依止經典與善知識，學善財童子","布施持戒是福德資糧","講者批評灌頂、法王、雙身法","以大悲菩薩肉山勉發長遠大願"],"k":["發大願心","長遠心","菩提心","善知識","簡別外道","四弘誓願"]},"1463-a03_063":{"s":"正偉老師回顧課程並開講第七章果地無相念佛：引研究指台灣佛教徒多以念佛為主；強調念佛在心不在口，引《觀經》「凡有憶想者必得成就」、阿含「一心念佛」及闍尼沙憶佛生天證初果；舉廣欽老和尚心中念佛之例與掛念生病兒子之喻；指出憶佛泉湧乃至大精進菩薩斷諸憶想仍屬因地念佛。","p":["台灣佛教徒多以念佛為主要修行","念佛在心不在口","阿含：常當專精一心念佛","廣欽老和尚：念佛用心念","憶佛泉湧仍屬因地，非果地念佛"],"k":["果地無相念佛","一心念佛","因地念佛","憶佛","淨念相繼"]},"1624-a05_001":{"s":"本集介紹平實導師《宗通與說通》副書名「成佛之道」的由來：講者指出當時有著作依五乘共法等結構、與《廣論》相合而把解脫道等同佛菩提道，並引律部「世間有六阿羅漢，佛為第一」說明阿羅漢不等於佛。另說明書背所述宗門三關皆圍繞第八識，以及自序中具名破斥、依法不依人與張志成、李元松懺悔的因緣。","p":["副書名成佛之道：駁解脫道等同佛菩提道之說","律部記載六阿羅漢而佛為第一，證二道不同","宗門三關的實證皆圍繞第八識如來藏","具名破斥是為法義辨正，應依法不依人","李元松捨壽前懺悔，張志成轉而尋覓正法"],"k":["成佛之道","解脫道與佛菩提道","宗門三關","如來藏","依法不依人","法義辨正"]},"1561-a05_002":{"s":"本集先述張志成懺悔後入正覺同修會並明心，勉人依法不依人、依智不依識；接著講解自序中依玄奘、窺基所立的「五時三教」判教：依《解深密經》三時——四諦相、隱密相、顯了相，並說明華嚴時與法華時存在的必要。講者認為空有之諍其實是實證者與未實證者之辯。","p":["依法不依人、依智不依識","五時：華嚴、阿含、般若、種智、法華","三時教依《解深密經》四諦、隱密、顯了相","空有之諍實為有無實證之辯","法華收三乘歸一佛乘，暢佛本懷"],"k":["五時三教","判教","解深密經","三轉法輪","一佛乘","空有之諍"]},"1607-a05_003":{"s":"本集為正光老師講「總釋宗通與說通」第一講，先概述系列主旨，再以「通即通達、達人」為喻，分世間法、出世間法、世出世間法三類達人。講者批評坦特羅雙身法屬世間有為法；說明二乘四果達人雖斷我見但不知涅槃本際；並依序介紹菩薩五十二階位各階的現觀，結論佛為最究竟達人，明心見性是基本門檻。","p":["通即通達，以三類達人為喻","講者批評坦特羅無上瑜伽違背不淫戒","二乘四果斷我見，然不知無餘涅槃本際","五十二階位與如幻、陽焰、如夢等現觀","佛為最究竟達人，明心見性為門檻"],"k":["宗通與說通","五十二階位","明心見性","聲聞四果","現觀","坦特羅批判"]},"1609-a05_004":{"s":"本集依書第17頁說明「通」不是世俗神通，而是宗門意旨與第一義諦的通達。講者分三點論神通：依附生滅的意識而有（引阿含「意法因緣生」）、屬境界法（舉慧忠國師勘驗大耳三藏他心通）、有出有入（意識在五位與麻醉時斷滅，也敵不過業力）。並說明菩薩應以智慧法門為主，戒慧直往菩薩到三地將滿心時才修禪定與神通。","p":["講者批評「上師比佛更慈悲」之說為謗佛","通指第一義諦通達，非世俗神通","神通依意識而有，意識為意法因緣生","大耳三藏公案：神通敵不過無境界的真心","五位意識必斷；菩薩三地將滿才修神通"],"k":["神通","意識生滅","第一義諦","他心通公案","智慧法門","五位意識斷"]},"1608-a05_005":{"s":"本集講「神通無關證悟」：三種阿羅漢中慧解脫者無禪定也無神通，仍可入無餘涅槃，可見是以智慧入涅槃，與《心經》所述無蘊處界相合。舉黃蘗罵自了漢、九峰道虔勘驗首座坐脫立亡、蓮華色比丘尼等例，說明禪定、神通皆非般若；講者並批評坦特羅修拙火得神通之說，結以「神通度俗人，智慧度學人」。","p":["三種阿羅漢皆以智慧而非定通入涅槃","黃蘗罵渡江羅漢為自了漢","九峰道虔：坐脫立亡不等於懂宗門意旨","禪宗祖師多無神通，不可因此輕視","講者批評拙火與樂空雙運之說"],"k":["神通","般若智慧","阿羅漢","禪定","禪宗公案","無餘涅槃"]},"1610-a05_006":{"s":"本集依書第23頁略說第一義諦：佛菩提道涵蓋二乘解脫道，引《勝鬘經》說明大乘是小乘的基礎；依《楞伽經》「說者授童蒙，宗為修行者」解釋宗通與說通，說明法與次法，以及六種通相。並指出明心後仍可能退失，異生性到初地才除盡；又引《楞伽經》說一切境界皆自心所現，最後舉七住、十住、初地說明各階說通的內容。","p":["佛菩提道含解脫道，大乘為小乘基礎","宗為修行者說，說通授童蒙","法與次法：明心見性及定慧福德","明心可退；異生性至初地方除","一切境界自心所現，百法明門"],"k":["第一義諦","宗通與說通","解脫道","異生性","百法明門","如來藏"]},"1589-a05_007":{"s":"本集講宗通概說上，依書第30頁歸納四點：宗通即明心與見性；明心即親證如來藏（引《大乘理趣六波羅蜜多經》、《央掘魔羅經》）；悟後生起八不中道乃至無量「不」的中道智慧（引《中論》）；此智慧非錯悟凡夫與二乘所能知（引《勝鬘經》）。講者並主張八萬四千法門皆歸向如來藏，批評虛空外道、常見、斷見等說法。","p":["宗通即明心與見性","明心即親證如來藏，眾生悉有","八萬四千法門皆以如來藏為依歸","《中論》八不中道依如來藏而說","自性清淨心而有染汙，二乘難知"],"k":["如來藏","明心","宗通","八不中道","中論","勝鬘經"]},"1591-a05_008":{"s":"本集講宗通概說中，依書第32頁說明悟後須有善知識攝受，否則可能退失（引《瓔珞經》八萬人退）；講者並舉意識不滅、斷際靈知、大乘非佛說、雙身法等為惡知識之例。接著說明信、位、行、念、究竟五種不退，及法智忍、法智、類智忍、類智如何生起下品妙觀察智與平等性智，乃至「六七因中轉，五八果位圓」的轉識成智。","p":["悟後須善知識攝受，否則退失","講者列舉多種惡知識主張","信、位、行、念、究竟五種不退","法智忍、法智、類智忍、類智","四智次第：六七因中轉，五八果位圓"],"k":["善知識","七住不退","五種不退","妙觀察智","平等性智","轉識成智"]},"1590-a05_009":{"s":"本集講宗通概說下，依書第34頁區分兩種見性：明心所見的成佛之性（無境界法），與肉眼所見的眼見佛性（有境界法），並引《大般涅槃經》十住菩薩少分見佛性「如夜見色」。說明禪宗所稱明心見性多指明心；介紹凡夫、未入地、已入地與諸佛四種隨順佛性；最後列出宗通五種：真實義通、離二邊通、得通、不思議通、意通。","p":["成佛之性無境界，眼見佛性有境界","十住菩薩肉眼少分見佛性","禪宗明心見性多指明心","四種隨順佛性與眼見佛性所需福德","宗通五種：真實義、離二邊、得、不思議、意"],"k":["眼見佛性","成佛之性","隨順佛性","宗通","大般涅槃經","十住菩薩"]},"1660-a05_010":{"s":"本集講說通概說上，依書第48頁引《楞伽經》說明說通是隨眾生根性與種性說相應的法，又分為人無我智與法無我智。接著講聲聞的人無我智：解釋四聖諦、三苦、八苦，並逐一分析色、識、受、想、行五陰的虛妄，講者並以此批評把一念不生、平常心或說法聽法之心當作開悟的說法。","p":["說通：隨眾生根性說相契之法","說通分人無我智與法無我智","四聖諦與三苦、八苦","五陰逐一分析皆為生滅虛妄","講者批評落入識陰、受陰、想陰的錯悟"],"k":["說通","人無我智","四聖諦","五陰","八苦","聲聞菩提"]},"1662-a05_011":{"s":"本集講說通概說中：先說四念處觀——觀身不淨、觀受是苦、觀心無常、觀法無我，講者並批評雙身法的「大樂」及以斷際靈知為本覺之說；次述聲聞法無我智與八正道。再引阿含說明無餘涅槃有本際而非斷滅；最後講緣覺觀十因緣「齊識而還」與十二因緣，並區分入胎識與識陰六識。","p":["四念處：身不淨、受苦、心無常、法無我","聲聞法無我智以人無我智為基礎","無餘涅槃有本際，非斷滅空","十因緣「齊識而還」之識為入胎識","十二因緣之識為識陰六識，二者有別"],"k":["四念處","十二因緣","十因緣","入胎識","無餘涅槃","緣覺"]},"1661-a05_012":{"s":"本集講說通概說下，依書第52頁說明菩薩人無我智與二乘同中有異：同樣現觀蘊處界，不同在於菩薩親證自心藏識，屬別教。講者舉三證說明阿含已隱說如來藏：四聖諦「如如、不離如」、「非我、非異我、不相在」，以及《長阿含》識與名色的入胎識問答；並主張二乘解脫道是佛菩提道析出的副產品。","p":["菩薩與二乘人無我智同中有異","四聖諦「如如」即指如來藏","非我、非異我、不相在之真實我","《長阿含》入胎識與名色互緣","二乘道為佛菩提道析出；阿羅漢無人證涅槃"],"k":["法無我智","人無我智","阿含隱說如來藏","入胎識","所知依","別教"]},"1629-a05_013":{"s":"本集講「法師與僧寶」，依書第56頁說明說法授人者名為法師，不限出家。引《雜阿含經》說能為人宣說五陰生厭、離欲、滅盡者名法師，並以五陰虛妄來簡擇各種說法；引《地藏十輪經》說明在家而有聖法聖果者屬勝義僧，舉觀世音、文殊、普賢、童女迦葉、凌行婆為例；也談「老師」古義、慎護口業，以及菩薩摧邪顯正的用意。","p":["如實說五陰虛妄者名為法師","以五陰簡擇各家說法是否如法","能說三乘菩提者為佛所認可法師","勝義僧：在家有聖法聖果亦攝","慎口業；菩薩摧邪顯正為利眾生"],"k":["法師","勝義僧","五陰","在家菩薩","摧邪顯正","口業"]},"1642-a05_014":{"s":"本集為正偉老師講「禪宗的宗通」第一講，先回顧前面課程講過的三界輪迴、如來藏執持業種、念佛法門，再說明學佛為求離苦得樂。宗通是三乘菩提的實證，說通是能為人解說，須先宗通後說通（引《楞伽經》二種法通），並以初果與大乘見道為例。最後引《六度集經》本生，說世尊歷經梵天王、帝釋、轉輪聖王以五戒治國，說明成佛需無量劫。","p":["如來藏執持業種，意識無法命令","宗通為實證，說通為能為人解說","大乘見道即親證真如如來藏","成佛需三大阿僧祇劫","《六度集經》本生：轉輪聖王以五戒治國"],"k":["宗通","說通","如來藏","三乘菩提","本生故事","五戒"]},"1646-a05_015":{"s":"本集續講《六度集經》本生，說明成佛依無量福德圓滿而成，菩薩修行次第不可逾越；以鸚鵡學舌、猜燈謎、空白支票為喻，說只探聽密意而無實質則無受用。講者並批評即身成佛的雙身法；說菩薩生生世世行菩薩道、菩薩戒一受永受；再講商人遭鬼妻迷惑、乘神馬逃離的本生故事，說明持戒累積戒德並受佛菩薩護佑。","p":["成佛依無量福德圓滿而成","五十二階位次第進修不可逾越","鸚鵡、燈謎、空白支票喻無實質","講者批評雙身法即身成佛","鬼妻本生：持戒累德，生生受護佑"],"k":["福德","修行次第","菩薩戒","本生故事","即身成佛批判","密意"]},"1644-a05_016":{"s":"本集談佛法宗門的傳承：引《法華經》序說如來為一大事因緣出世，即教導眾生證自心如來藏。講者主張佛降生前已有菩薩先到印度教化，舉哈拉巴文明、新沙門與魯士修行者為背景，解釋吠陀本體論與佛法表面相似的原因；並談〈原人歌〉、因陀羅讚的「一」、仙人見佛相而哭、《涅槃經》名色繫縛之問，以及六祖三十六對不離自性。","p":["佛為一大事因緣出世：證如來藏","菩薩先頭部隊於佛前教化印度","哈拉巴文明與新沙門傳統","吠陀「一」與佛法表相相似的緣由","六祖三十六對，說一切法不離自性"],"k":["宗門傳承","一大事因緣","吠陀","本體論","如來藏","六祖壇經"]},"1651-a05_017":{"s":"本集續談佛出世前的背景：講者認為吠陀、奧義書屬不了義的相似法，是菩薩為佛出世預作準備；指出證悟關鍵在福德資糧是否具足，並舉初果向為例。又引《大森林書》三類業，說「緣起性空、性空唯名」在佛前已有，講者認為只講緣不講因是無因邪見。最後解說右脅出生、七步金蓮、唯我獨尊的宗門意涵與雲門「一棒打殺」，及佛出家向新沙門求學。","p":["吠陀奧義書為相似法，為佛出世鋪路","證悟關鍵在福德資糧具足","性空唯名佛前已有，講者斥無因唯緣","右脅出生、七步金蓮含宗門深義","雲門一棒打殺作為對佛的供養"],"k":["緣起性空","福德資糧","吠陀","禪宗公案","宗門正義","佛陀出生"]},"1647-a05_018":{"s":"本集講佛陀修定、苦行後於菩提樹下按地明心、睹明星見性而四智圓明，接著依序講五時教化：華嚴時、阿含時（藏教）、般若時（通教）、唯識種智時（別教）、法華時（圓教），配以日照高山、日照幽谷、日照大地之喻，及《法華經》窮子喻各階段。再以乳、酪、生酥、熟酥、醍醐說明「五時一味」，並略述慧遠、智者到玄奘、窺基的判教。","p":["佛按地明心、睹星見性，四智圓明","華嚴時如日照高山，對大菩薩說","藏教、通教、別教、圓教之次第","窮子喻：二誘、體信、領知、付業","乳至醍醐喻五時一味，玄奘窺基判教"],"k":["五時三教","判教","法華經窮子喻","四智圓明","五時一味","玄奘"]},"1649-a05_019":{"s":"本集先解釋玄奘傳記「棲息三禪，巡遊十地」等語，講者認為玄奘已入地；並批評現代否定如來藏、主張大乘非佛說的法師。接著以阿羅漢婁沙迦一生未得飽食的故事，說明福德與證悟的關係、菩薩須福慧兩足。最後引《長阿含》入胎識、《法句經》「識神」、《雜阿含》色集色滅，說明二乘所滅的是五蘊，而非入胎識。","p":["解釋玄奘「棲息三禪，巡遊十地」","講者批評否定如來藏、大乘非佛說","婁沙迦故事：福德不足之苦","福德到何地步，證悟才到何地步","阿含明說入胎識、識神，所滅為五蘊"],"k":["入胎識","福德","玄奘","阿含經","五蘊","識神"]},"1643-a05_020":{"s":"本集續引經證明《阿含經》已說有本識：「齊識而還」稱古仙人道、《雜阿含》車喻偈、南傳經典說涅槃確有與心極光淨；並引《俱舍論》說十四無記是暫置不答，佛弟子也以「梵」稱佛。接著講般若時：《金剛經》「凡所有相皆是虛妄」、《大般若經》非心心與諸法本性唯一，最後預告三轉法輪的阿陀那識。","p":["齊識而還之本識，名為古仙人道","南傳經典說涅槃確有、心極光淨","十四無記為暫置不答，非無答案","佛弟子以「梵」敬稱佛陀","般若經說非心心、諸法本性唯一"],"k":["本際","如來藏","阿含經","涅槃","般若經","非心心"]},"1648-a05_021":{"s":"本集引《解深密經》「阿陀那識甚深細」偈，說明如來藏是貫穿五時三教的同一條線，世尊不對緣未熟者明說密意，直到拈花微笑傳正法眼藏而有禪宗。接著說明求證如來藏須六住圓滿、斷我見並具菩薩種性，有禪宗宗通與藉教悟宗兩途，並舉永明延壽「禮拜著」公案，強調參公案須經善知識印證以免大妄語。","p":["阿陀那識甚深細，佛不為凡愚開演","如來藏是貫穿五時三教的同一條線","密意只因太近，明說易致謗法墮地獄","拈花微笑付正法眼藏為禪宗起源","證悟七住須先斷我見，悟後須求印證"],"k":["如來藏","守護密意","禪宗","教外別傳","大妄語","解深密經"]},"1645-a05_022":{"s":"本集說明禪師觀因緣不明說的用心，舉長慶慧稜、清涼文益「毫釐有差」等公案，說明大乘見道通宗有教外別傳與言教開示二門，禪門以普請之法「不聞而聞、不說而說」。並以周利槃特與《六度集經》死老鼠故事說明信受善知識的重要，再介紹藉教悟宗的讀經悟入（永嘉一宿覺）與依善知識開示、晚參、語錄悟入。","p":["禪師觀因緣，緣未熟者不明說","見道通宗：教外別傳與言教開示","禪門普請之法，不聞而聞不說而說","周利槃特深信一句教誨而得果","藉教悟宗：讀經悟入或依善知識開示"],"k":["教外別傳","藉教悟宗","公案","善知識","禪宗","普請"]},"1650-a05_023":{"s":"本集說明禪宗三關：破初參明心入七住真見道、過重關眼見佛性、破牢關取證慧解脫盡智，並指「一悟便至佛地」只是方便說。再介紹法相唯識宗依《成唯識論》藉教悟宗的特色，最後依《密嚴經》《楞伽經》講大乘通宗見道的歧路，說明不覺悟唯識性者落入常見（執意識靈知）或斷見（六識論緣起性空）。","p":["禪宗三關：明心、見性、牢關盡智","一悟便至佛地是方便說非究竟","法相唯識宗由上師明說而藉教悟宗","不覺唯識性者必墮常見或斷見","六識論否定七八識，本質屬斷見"],"k":["禪宗三關","明心見性","法相唯識","常見","斷見","六識論"]},"1655-a05_024":{"s":"本集進入「大乘通宗見道之岐路」，說明宗門根本理體是第八識如來藏，除常見斷見外還有自性見、邪見、外道見。第一類自性見以數論外道為例，介紹迦毘羅冥性、神我與二十五法及《金七十論》、世親《勝義七十論》的因緣，並逐一分析其心平等根、神我待緣而有、常與剎那覺知矛盾、我慢我執即意根、冥性不可驗證等五種過失。","p":["宗門根本理體即第八識如來藏","岐路含常斷見、自性見、邪見、外道見","數論立冥性與神我，生二十五法","世親造《勝義七十論》破《金七十論》","冥性不可知不可證，無法驗證成戲論"],"k":["自性見","數論外道","神我","冥性","如來藏","通宗見道"]},"1658-a05_025":{"s":"本集講第二類自性見：犢子部所立「不可說補特伽羅我」，說明它其實是依五蘊想像的我執之我，可滅而非輪迴主體；主講者批評一位已故老法師在《唯識學探源》中認同此說，認為加上「不可說」仍落入冥性與神我的過失。接著講第三類自性見：主張意識細心、極細心具空性能生萬法，並引該老法師《如來藏之研究》一段，留待下集辨析。","p":["犢子部立不可說補特伽羅我","此我實為我執，可滅非輪迴主體","不可知不可證之法無從驗證","第三類自性見：意識細心具空性","引老法師中觀不必立阿賴耶識之說"],"k":["自性見","犢子部","補特伽羅我","我執","意識細心","阿賴耶識"]},"1657-a05_026":{"s":"本集辨析上集所引老法師的主張：若無第八識持種，業存於何處、因果如何不亂；所謂性空法性若指五蘊緣起性空，需藉緣而有，不能自然存在、成立因果。主講者說明能生緣起性空的主體是第八識，真中觀須實證中道理體再加檢驗；並指其受部派影響，依說一切有部以「剎那過去六識引後念」為意根，會使十八界成十七界，且無法解釋五無心位。","p":["無持種主體則業無所存、因果失壞","五蘊緣起性空依緣而有，不能持業","第八識才是緣起性空的主體","中觀須實證中道法並自我檢驗","否定意根則十八界成十七界"],"k":["緣起性空","中觀","阿賴耶識","意根","部派佛教","因果"]},"1656-a05_027":{"s":"本集續破「過去六識引後念即意根」之說：眼識須根塵二法為緣，不能自生；若無意根與第八識，阿羅漢我執盡時應即入涅槃，捨報後無餘涅槃也成斷滅。結論意識細心、極細心皆識蘊所攝，屬自性見。接著講外道見（造物主說的矛盾）與邪見定義，並破第一種邪見「無情成佛」，以五種種性、八識、六道歸屬及戒行、四無量心等理由說明草木山河無佛性。","p":["眼識須根塵二法生，前念不能自生","否定意根第八識則無餘涅槃成斷滅","意識細心極細心皆識蘊所攝","外道見：造物主說自相矛盾","邪見一：無情成佛，草木無八識佛性"],"k":["自性見","外道見","邪見","無情成佛","意根","八識"]},"1669-a05_028":{"s":"本集先以極樂世界成就及「前七識有情、第八識無情共成種智」兩方面，解說「有情無情同圓種智」的真實義，非指山河大地成佛。再講多種邪見：真如可分割合併、修氣功拙火吸收宇宙能量合一、以意識覺知心為真如而自稱果地修行，以及觀想明點即菩提心，並逐一指出其過失。","p":["同圓種智真義：佛願與有情共成國土","前七識修道、第八識成大圓鏡智","邪見：真如可分割則因果失壞","邪見：氣功拙火依色身，無常不能成佛","邪見：意識為真如、觀想明點為菩提心"],"k":["邪見","同圓種智","真如","意識","明點","四顛倒"]},"1668-a05_029":{"s":"本集續破觀想明點為不壞菩提心之說，引某教派論著指出色法與能觀意識皆會壞。接著講第六種邪見：男女雙修求遍身樂，稱為大樂光明、無上瑜伽、即身成佛；主講者以佛地正遍知覺是智慧、八地於相於土自在等理路加以破斥，提醒信徒勿受「佛母」名義所騙，並說明聲聞、緣覺、菩薩三乘「斷愚證智」的真實內涵。","p":["明點依色法與意識，非不壞菩提心","雙修求遍身樂被稱無上瑜伽即身成佛","正遍知覺是智慧，非身根樂觸","以佛母名義要求合修者應如理質疑","三乘斷愚證智皆從斷我見破無明起"],"k":["邪見","雙身法","無上瑜伽","明點","斷愚證智","即身成佛"]},"1670-a05_030":{"s":"本集總結前述邪見，建議參考《狂密與真密》，並從世俗道德與佛戒禁邪淫說明清淨解脫法的原則。接著作「宗通歧路」結論：走錯路的根源是不信有第八識，怕斷滅而執取意識，以致不能斷我見；意識細心入涅槃說自相矛盾，涅槃真義是如來藏不再出生五蘊。最後引《雜阿含》卷六說明五蘊與見聞覺知「非我、非異我、不相在」是名正慧。","p":["雙修密續違佛戒，學佛須擇清淨法","歧路根源：不信第八識，恐斷滅執意識","斷我見是清淨解脫法的基礎","涅槃是如來藏不再出生五蘊","雜阿含：五蘊非我非異我不相在"],"k":["斷我見","涅槃","如來藏","雜阿含經","邪見","非我非異我"]},"1594-a05_031":{"s":"本集續解《雜阿含》卷六：於六見處觀察非我非我所即斷三縛結、最多七有往來。接著進入「宗通首重實踐」，說明須親證如來藏，才能以阿含「真實、本際」、般若「無心相心」、唯識「異熟識」等名言一一驗證。並回應現代禪副宗長張志成「畫鬼容易畫狗難」的評論，主講者認為生命意義的省思正是探究識由二法為緣所生、身心從何而來的生命實相。","p":["觀六見處非我非我所即斷三縛結","宗通須親證如來藏並依經驗證","真實、無心相心、異熟識皆指第八識","回應現代禪評論：生命意義即生命實相","識二法為緣生，見聞覺知非真實"],"k":["宗通","如來藏","斷我見","雜阿含經","生命實相","異熟識"]},"1596-a05_032":{"s":"本集分三點回應現代禪副宗長的評論：一是歷代禪師以勘驗、拈提相見，必有同一如來藏為標準；二是緣起性空的根源是第八識，單憑現象界緣起性空落於斷邊，不是甚深般若；三是平實導師依實證為阿含、中觀正確定位，是護持而非貶斥。最後舉張志成後來懺悔、入禪淨班修學並被印證開悟為例，勸誤會者效法。","p":["祖師互相勘驗，須同證一如來藏","緣起性空根源是第八識非五蘊","現象界緣起性空落斷邊非甚深般若","正確定位阿含中觀是護持非貶斥","張志成懺悔修學後獲印證開悟"],"k":["如來藏","般若","緣起性空","禪宗","中觀","懺悔"]},"1595-a05_033":{"s":"本集總結「宗通首重實踐」：真見道即證真如，觸證如來藏並驗證其真實與如如，發起本來無生的涅槃智與大乘人無我智（引《入楞伽經》）。再說明三轉法輪皆須如實履踐：依阿含顯說斷我見，依實證本際履踐般若中觀，於方廣唯識修虛妄唯識與真實唯識、世世行菩薩道護持正法；無證量則以比量臆度而墮非量。","p":["真見道即證真如，驗證真實與如如","發起本來無生涅槃智、大乘人無我智","依阿含顯說如實斷我見","履踐般若中觀須先實證涅槃本際","唯識修道：虛妄唯識、真實唯識"],"k":["真見道","證真如","人無我","如實履踐","唯識","宗通"]},"1633-a05_034":{"s":"本集進入第三章「說通——從宗入教」，說明宗通菩薩悟後起修所得六通，先講真實義通。依《瑜伽師地論》真實義分「如所有性」（第八識真如，無覆無記、持種不失）與「盡所有性」（蘊處界、四聖諦皆無我）；七住菩薩依根本無分別智讀般若即解真實義，初地證法無我。並辨析二乘與大乘的人無我、法無我差別，指出皆須依如來藏成就。","p":["說通即從宗入教，悟後深入經藏","宗通六通：真實義通至說通","如所有性即第八識真如之性","盡所有性：蘊處界一切法無我","三乘人無我法無我皆依如來藏"],"k":["真實義通","說通","真如","人無我","法無我","如來藏"]},"1634-a05_035":{"s":"本集續講真實義通，主講者批評「大小乘只從行願區分、緣起中道為唯一正見」之說，認為緣起只是觀念，不是中道；並指出「大乘非佛說」與佛教演化說的邏輯矛盾，說明外道神我屬意識，不同於第八識。接著說明一切種智與道種智、三法印須依如來藏，無餘涅槃本際即第八識，並以焰摩迦比丘為例，破應成派「滅相不滅」為戲論。","p":["緣起只是觀念，不能稱為中道","大乘非佛說論者自陷矛盾","外道神我是意識，非第八識","一切種智依如來藏，諸地稱道種智","滅相不滅是意識觀念，屬戲論"],"k":["真實義通","緣起性空","一切種智","無餘涅槃","應成派中觀","三法印"]},"1606-a05_036":{"s":"本集講「得通」，即四智心品：佛地無垢識以清淨真如與大圓鏡智、平等性智、妙觀察智、成所作智五法為性，名為法身。說明「六七因中轉、五八果上圓」的轉識成智次第，識是體、智是用，明心只得下品二智而未離生死。最後說明平等性智依眾生同具如來藏而起慈悲，須轉依如來藏無漏有為性，並以妙觀察智觀眾生苦而興大悲。","p":["佛地無垢識以五法為性名法身","四智心品是所生得，依無垢識而常","六七因中轉，五八果上圓","識是體智是用，轉識成智識不滅","平等性智依如來藏平等而起慈悲"],"k":["四智","轉識成智","得通","無垢識","平等性智","法身"]},"1555-a05_037":{"s":"本集開始講不可思議通，先引《勝鬘經》「自性清淨心而有染」，說明證悟者能現見煩惱中有菩提、菩提中有煩惱。再從四種涅槃切入，說明二乘依蘊處界無常觀斷我見我執而證有餘依、無餘依涅槃；依「識緣名色、名色緣識」，名色所緣之識即第八識，是無餘涅槃本際。阿羅漢不知此本際，七住菩薩已知，故不可思議。","p":["自性清淨心而有染，唯證者能知","煩惱中有菩提，菩提中有煩惱","二乘依蘊處界觀證有餘無餘涅槃","名含七識，名色所緣識即第八識","七住菩薩知涅槃本際，阿羅漢不能"],"k":["不可思議通","無餘涅槃","涅槃本際","勝鬘經","識緣名色","阿羅漢"]},"1557-a05_038":{"s":"本集講大乘四種涅槃中的本來自性清淨涅槃：依般若經非心心、無心相心、不念心，及《說無垢稱經》「真如為般涅槃」，說明第八識具本來自在、以無性為自性、寂然清淨、中道涅槃四種體性。再以三法印「涅槃寂靜」與《大樹緊那羅王所問經》寶心，說明阿含也隱說自性清淨心，二乘涅槃本質仍以本來自性清淨涅槃為體。","p":["大乘四種涅槃，七住證自性清淨涅槃","般若經不念心、無心相心即實相心","第八識本來自在、寂然清淨","涅槃寂靜：無六塵覺觀，唯本際獨存","二乘涅槃以自性清淨涅槃為體"],"k":["本來自性清淨涅槃","不可思議通","涅槃寂靜","三法印","阿賴耶識","真如"]},"1556-a05_039":{"s":"本集講佛地無住處涅槃：菩薩從真如心反觀證人無我，至初地證法無我，留惑潤生不取無餘涅槃，至佛地斷盡變易生死，不住生死也不住涅槃。說明四種涅槃皆依阿賴耶識心體而為「所顯得」，非實有法，般若與四智則為「所生得」。並說明誰能證得哪幾種涅槃，指出阿羅漢證解脫而不知涅槃實際。","p":["菩薩從真如心反觀證人無我、法無我","初地留惑潤生，不取無餘涅槃","佛地斷變易生死，成無住處涅槃","涅槃是所顯得，般若智是所生得","阿羅漢證解脫，而不知涅槃實際"],"k":["無住處涅槃","四種涅槃","留惑潤生","法無我","變易生死","不可思議通"]},"1652-a05_040":{"s":"本集講「離二邊通」，即般若中道。說明六識心有入定出定、取捨淨垢，必落兩邊，離念靈知也無法變成中道心；只有如來藏本離六塵、非常非斷、非有變異非無變異、非有作用非無作用，才是中道實相。主講者批評六識論「性空唯名、即有即空」實為緣生性空、無因論，並以明鏡與影像喻真中觀，以「兔無角」喻其說無意義。","p":["離二邊即般若中道","意識入定出定，永落兩邊","如來藏非常非斷，為中道實相心","性空唯名實為無因的緣生性空","明鏡喻畢竟空不礙緣起有"],"k":["離二邊通","中道","如來藏","般若","性空唯名","離念靈知"]},"1730-a06_031":{"s":"本集開始介紹大乘四加行，說明修四加行以實證菩薩初果、斷我見之前須具備的前提：具足菩薩種性、歸依三寶並護持正教以修集福德、伏除性障，以及確認八識論、第八識如來藏的存在。並比較聲聞僧團無法久住世間，唯菩薩僧團能永續弘法。","p":["四加行為斷我見、證菩薩初果所修","須具菩薩種性，悲憫眾生、為正法久住著想","歸依三寶、護持正教以修集廣大福德","伏除性障，貪瞋煩惱降低方能專心於法","須以八識論、第八識存在為前提"],"k":["四加行","菩薩種性","斷我見","性障","歸依三寶","八識論"]},"1740-a06_032":{"s":"本集先補述第八識存在為修四加行的前提：若只承認六識或七識，觀能取所取空時會落入斷滅的恐懼，增立九識、十識則成虛妄想。接著依《成唯識論》唯識五位解釋加行位之義為臨近見道而加快腳步、且有作用，並說明唯識五位與菩薩五十二位階所描述的不同。","p":["六識論、七識論觀能取所取空必落斷滅","九識、十識之說屬虛妄想","唯識五位：資糧、加行、通達、修道、究竟","加行即臨近見道而加快腳步，且有作用","唯識五位指一生修行次第，非五十二位階對應"],"k":["加行位","唯識五位","第八識","成唯識論","菩薩五十二位階","六識論"]},"1741-a06_033":{"s":"本集續說唯識五位與五十二位階之別：資糧與加行在每一位階都需要，並非固定位階；通達位以上才是實證唯識真如，七住明心屬勝解行位。接著提醒修四加行須如實遍觀五陰範圍，以免將離念靈知當真心而犯大妄語，並批評性力派思想，最後依《成唯識論》卷九引出四尋思。","p":["資糧、加行存在於每一位階，非特定位次","入地方實證唯識真如，七住屬勝解行位","將離念清明意識當真心即未斷我見","四加行須現量遍觀，聽懂不等於實證","四尋思：名、義、自性、差別假有實無"],"k":["四尋思","加行位","唯識真如","斷我見","五陰","成唯識論"]},"1755-a06_034":{"s":"本集以「花」為例解說四尋思的名、義、自性、差別皆假有實無，再將之運用於識陰、受陰、想陰、行陰的觀察。說明四加行四個位次煖、頂、忍、世第一，初次如實尋思為煖位；再深入看到事情本質的重觀則趨向頂位，並舉摧邪顯正是善是惡為例。","p":["以花為例說明名、義、自性、差別","名與義皆依六識而建立，假有實無","將四尋思用於識、受、想、行四陰","四加行位次：煖、頂、忍、世第一","創觀得煖位，重觀見本質趨向頂位"],"k":["四尋思","四加行","煖位","頂位","五陰","名義自性差別"]},"1746-a06_035":{"s":"本集說明四加行在於伏除能取、所取二取：先觀所取境界剎那生滅、空無所得，創觀得煖位，重觀至離念靈知亦屬所取而入頂位；再於睡眠、正死等位觀能取覺知心虛妄而安忍為忍位，並引《成唯識論》印順定之文；最後捨離身心而至世第一、斷我見，菩薩則轉而捨身命財護持正法，為大乘見道作準備。","p":["四加行即伏除能取、所取二取","觀所取境界假有實無，得煖位、頂位","觀睡眠、正死位覺知心滅而安忍為忍位","引《成唯識論》印前順後、印順忍","世第一斷我見，菩薩捨身命財護持正法"],"k":["四加行","能取所取","斷我見","忍位","世第一","成唯識論"]},"1798-a06_036":{"s":"本集介紹緣覺菩提：緣覺生於無佛之世，觀察世間現象如落葉、老死而悟無常，證解脫入無餘涅槃。說明緣覺推尋生命必有本識存在，與聲聞同證蘊處界無我，但緣覺智慧較勝；並解說「此有故彼有，此滅故彼滅」的緣起性空，指出性空背後有空性心如來藏。","p":["緣覺生於無佛之世，自觀因緣而覺悟","觀落葉、老死等現象而悟生命無常","緣覺推知每一有情有本識，非斷滅","聲聞緣覺同證蘊處界無我，緣覺分十品","緣起性空：緣生法依空性心而現起"],"k":["緣覺菩提","緣起性空","無我","如來藏","無餘涅槃","聲聞"]},"1799-a06_037":{"s":"本集引《雜阿含經》說明緣起法非佛所作亦非餘人作，法界常住，背後是各有情的第八識如來藏；緣覺雖推知有本識卻不實證。接著區分緣起法與緣生法，並依序解說十二因緣的無明、行、識、名色各支，指出無明所不知的「際」即本際如來藏。","p":["緣起法非佛所作，法界常住","因緣法能存在是因有如來藏","緣覺推知本識而不實證如來藏","緣起偏於因，緣生法指已生的十二支","無明不知本際；行、識、名色各支內涵"],"k":["十二因緣","緣起法","無明","如來藏","雜阿含經","名色"]},"1742-a06_038":{"s":"本集續解十二因緣的六入、觸、受、愛、取、有、生、老死各支，以喜吃葡萄為例說明愛取導致三界有與再生。接著指出只知十二因緣流轉不能解脫，還滅時若無本識即成斷滅，因此須修十因緣；並引《雜阿含經》佛陀憶宿命的十因緣觀，說明從老死逆推到名色，色法與六識、意根皆不能跨越三世，故推至本識而「齊識而還，不能過彼」。","p":["六入、觸至老死各支環環相扣","以葡萄為例說明愛、取、有、生","只知流轉不能解脫，還滅須有本識","引經文：從老死逆推至名色","色法、六識、意根不能來去三世，齊識而還"],"k":["十因緣","十二因緣","齊識而還","本識","雜阿含經","還滅門"]},"1743-a06_039":{"s":"本集說明十因緣的逆推、順推觀，推至本識後再修十二因緣還滅觀，才不會落入斷滅；並指出他處多不談還滅門，是因缺乏十因緣觀。接著介紹內外因緣法與因相應、緣相應，引《佛說大乘稻芉經》說明十二支每一支都不作「我生某支」之念，皆是無我法。","p":["十因緣逆推至識支再順推至老死","有十因緣觀，十二因緣還滅不落斷滅","聽懂理論不等於實證，須逐支細觀","外因緣（植物）與內因緣（十二支）","引《稻芉經》：十二支皆無我法"],"k":["十因緣","十二因緣","還滅門","無我","因相應","稻芉經"]},"1756-a06_040":{"s":"本集說明十二因緣中的識支也是無我法，以機器人攝影鏡頭與輪子沒有連結為喻，指出人覺得「我看到了」是六界和合所產生的錯覺。引《佛說大乘稻芉經》解說地、水、火、風、空、識六界和合的緣相應，並強調因緣觀行須以如來藏存在為前提，二乘解脫果亦含藏於第八識。","p":["識支亦是無我法，有我是錯覺","以機器人比喻眼識、耳識本無我","引《稻芉經》：六界和合為緣相應","胚胎時尚無六識，六識不能生名色","流轉與還滅皆依第八識如來藏而成就"],"k":["緣相應","無我","六界","十二因緣","如來藏","稻芉經"]},"1805-a06_041":{"s":"本集講阿含聖教的真實義，指出南北傳阿含皆說有常住不滅之法。舉焰摩迦比丘的斷滅見被舍利弗破斥、阿難自認緣起易解被佛喝止、荼帝比丘以覺知心為輪迴主體被斥等例，說明能入胎、出胎並伴隨一生的識才是名色之本，也是維繫業報因果所必須的常住法。","p":["南北傳阿含皆說有常住不滅之法","焰摩迦執阿羅漢滅後斷滅，被舍利弗破斥","佛斥阿難：緣起甚深難知難見","荼帝比丘以覺知心為輪迴主體，被佛呵斥","入胎識為名色之本，並維繫業報"],"k":["阿含經","常住法","入胎識","緣起法","名色","業報"]},"1804-a06_042":{"s":"本集續說阿含的微言大義：法不離如、不異如，如來有一所依識；二乘只是依佛語趣向涅槃，並未親證此識。指出名色與識互為緣，南傳所說的alaya即執取，阿賴耶性可滅而識體不可滅、齊識而還；並以哥德爾定理比喻唯有佛能現觀一切而說正遍知，批評視佛陀為哲學家的看法。","p":["法不離如、不異如，如來有所依識","二乘依佛語趣涅槃，未親證此識","名色以識為本，識隨順眾生執取而生諸法","阿賴耶性可滅，識體不可滅，齊識而還","以哥德爾定理喻唯佛能現觀一切"],"k":["常住法","阿賴耶","齊識而還","如","阿含經","涅槃"]},"1711-a06_043":{"s":"本集說明從初轉到二轉法輪的「如」：初轉法輪所說的常住識，在《般若經》以假名「真如」宣說。解釋真如自性空並非空無，而是無所得、不生不滅、無見聞覺知卻能了知眾生心行；真如遍一切法乃至貪瞋癡，也就是《般若經》所說的「心非心」、我界，以及《心經》空三昧的實體。","p":["法不離如，常住識在二轉稱為真如","真如自性空，指無所得而非空無","真如不生不滅、無見聞覺知","真如遍一切法，貪瞋癡亦有真如","心非心、我界、空三昧皆指此真如"],"k":["真如","般若經","空性","心非心","初轉法輪","二轉法輪"]},"1710-a06_044":{"s":"本集說明從初轉到三轉法輪的「識」：齊識而還的如來所依識，在三轉法輪稱為阿賴耶識、藏識、如來藏、法身。阿含所說的阿賴耶是執取，阿賴耶性可滅而心體不可滅，滅執藏性後改稱異熟識，成佛時稱無垢識；並述及七真如、轉識成智、《楞嚴經》五陰滅盡，強調三轉法輪義理一貫。","p":["緣起支中齊識而還之識即如來所依識","阿含說阿賴耶即執取，般若說無阿賴耶","阿賴耶性可滅，心體不可滅","阿賴耶識→異熟識→無垢識","三轉法輪所說一貫，皆不離此識"],"k":["阿賴耶識","如來藏","三轉法輪","異熟識","無垢識","轉識成智"]},"1700-a06_045":{"s":"本集講二乘菩提正知見的實踐與證入：指出疑佛、學術化等疑見的問題，說明意識不能入涅槃，斷見、常見及「人死後為人」皆屬邪見，燒金紙、拜鬼神屬戒禁取見等惡見。並說明初果斷身見、疑見、戒禁取見三縛結，須以對佛法僧戒的四不壞信為基礎。","p":["二乘須由正知見導入，並經觀行體驗","意識不能進入涅槃，滅後亦非斷滅","斷常二見與人死為人皆屬邪見","燒金紙求保庇屬戒禁取見","初果斷三縛結，以四不壞信為基礎"],"k":["三縛結","四不壞信","斷見常見","戒禁取見","身見","二乘菩提"]},"1764-a06_046":{"s":"本集講小乘法與涅槃：涅槃不是境界，有餘、無餘只是方便施設；阿羅漢滅意識而入，並未親證涅槃。說明本住涅槃性即無見聞覺知的真心，二轉、三轉法輪逐步顯示；引《瑜伽師地論》說迴小向大，引《楞伽經》說無餘涅槃只是三昧境界，終將醒來修學佛道，如來則是證得涅槃全體。","p":["涅槃非境界，有餘無餘為方便施設","阿羅漢滅意識而入，未親證涅槃","本住涅槃性即無見聞覺知的真心","《瑜伽師地論》說阿羅漢迴小向大","無餘涅槃如醉酒三昧，終將醒來修學佛道"],"k":["涅槃","無餘涅槃","本住法","小乘","楞伽經","迴小向大"]},"1763-a06_047":{"s":"本集講小乘法與如來藏：引《央掘魔羅經》說明阿含中已有如來藏，並述末法弘揚此法將遭威脅、毀辱、聽眾下劣、處所偏僻等四種困難。說明業種由阿賴耶識執藏，眾生所樂的阿賴耶即如來藏；並從「梵、我、合、一」逐一辨析，認為以外道神我比喻如來藏並不正確。","p":["《央掘魔羅經》說如來藏常住","末法弘如來藏將遇四種困難","業種由阿賴耶識執藏，眾生樂阿賴耶","如來藏無我性，無作、無主宰性","辨「梵我合一」，如來藏非外道神我"],"k":["如來藏","外道神我","阿賴耶識","央掘魔羅經","末法","業種"]},"1783-a06_048":{"s":"本集評論日本批判佛教學者袴谷憲昭與松本史朗對如來藏、本覺思想的看法。講者認為他們以知識論研究佛法、不信佛為正遍知；並說明本覺常住法才能解釋阿羅漢滅後非斷滅與業種的維繫，禪悟也不是離開知識性；又針對松本以如來藏為「界」、為「一」的說法，指出如來藏各有情皆有，非一非多。","p":["學術研究以知識論看佛法，未重親證","講者認為袴谷憲昭不信佛為正遍知","本覺常住法解釋阿羅漢滅後非斷滅","禪悟非離知識性，密意不隨意宣說","批評松本史朗：如來藏非一，各有情皆有"],"k":["批判佛教","如來藏","本覺","正遍知","禪悟","袴谷憲昭"]},"1802-a06_049":{"s":"本集講被誤解的大乘修行：真如遠離見聞覺知，證悟不是境界；空性不是建立在一切法之上，否則成為無因論。指出斷除分別心、長時靜坐並非開悟，舉磨磚作鏡公案說明禪坐不是般若，靜慮應在正知見下參究，以有分別的意識心尋覓無分別的如來藏。","p":["真如遠離見聞覺知，證悟非境界","空性若依一切法而立即成無因論","如來藏不分別六塵，卻能記錄業種","磨磚作鏡公案：打坐不能成佛","以意識心參究，尋覓無分別的如來藏"],"k":["如來藏","真如","空性","禪定","參禪","見聞覺知"]},"1677-a06_050":{"s":"本集講三乘菩提與判教：說明三乘是為度眾而施設，實唯一佛乘。逐一評論「虛妄唯識」、「真常唯心」、「性空唯名」三種判教，講者認為唯識所說的是真實心阿賴耶識，應稱真實唯識；真常之心是阿賴耶識而非六識；性空唯名屬無因的戲論，應說性空真如。最後引化城喻說明二乘涅槃非究竟。","p":["三乘為方便施設，實唯一佛乘","批評「虛妄唯識」，應稱真實唯識","真常唯心之心即阿賴耶識，非六識","性空唯名屬戲論，應說性空真如","化城喻：二乘涅槃是休息處"],"k":["判教","三乘菩提","唯識","性空唯名","真如","一佛乘"]},"1724-a06_051":{"s":"本集開始介紹佛菩提道修證次第，先引《摩訶般若波羅蜜經》說明波羅蜜即般若、以證如來藏為首要，再依《成唯識論》將成佛之道分為遠、近、大三種波羅蜜多。接著講解遠波羅蜜多中的十信位，以及初住發心住至六住正心住的修行內涵。","p":["佛菩提道修證皆以實相心如來藏為核心","波羅蜜即到彼岸，唯般若能度眾生","《成唯識論》分遠、近、大三種波羅蜜多","十信位發起五根，具足菩薩種性方入住位","初住至六住：五根轉為五力，布施至般若"],"k":["遠波羅蜜多","十信位","十住位","如來藏","五根五力","成唯識論"]},"1726-a06_052":{"s":"本集依《楞嚴經》卷八講解七住至十住位：七住明心證如來藏而不退，八住童真住、九住法王子住、十住灌頂住，以胎兒、嬰兒、太子灌頂為喻；並說明十住屬習種性。接著開始介紹十行位的初行歡喜行與二行饒益行，主張破邪顯正才是饒益眾生。","p":["七住不退住：一念相應證如來藏、身心合成","八住童真住：十身靈相，猶如胎兒","九住法王子住、十住灌頂住：分擔弘法","初住至十住屬習種性","十行初行歡喜行、二行饒益行，破邪顯正"],"k":["十住位","七住明心","十行位","楞嚴經","習種性","破邪顯正"]},"1725-a06_053":{"s":"本集續依《楞嚴經》卷八講解十行位第三至第七行：無瞋恨行、無盡行、離癡亂行、善現行、無著行。講者批評「活在當下」等說法仍是意識境界，強調以如來藏一法貫通世間法、解脫道與佛菩提道，並現觀一切塵界皆如來藏，不執著往生某一佛土。","p":["無瞋恨行：自覺覺他，對求法者無違拒","講者批評「活在當下」仍落意識覺知心","無盡行：了知解脫道與佛菩提道種類不同","離癡亂行：以如來藏一以貫之一切法","善現行與無著行：同中見異，塵界不相留礙"],"k":["十行位","如來藏","楞嚴經","解脫道與佛菩提道","一即一切"]},"1729-a06_054":{"s":"本集講解十行位第八至第十行：尊重行以玄沙師備禪師公案說明種種現前皆第一波羅蜜多；善法行說明圓融三乘、成就諸佛弘法軌則，舉世尊三會說法為例；真實行要求前七識轉依如來藏而清淨無漏，圓滿性種性。並強調證悟只是七住，悟後仍須追隨善知識進修。","p":["尊重行：種種現前皆第一波羅蜜多","以玄沙禪師與韋監軍公案說日用而不知","善法行：知何時說何法，如世尊三會說法","真實行：前七識清淨無漏，成就性種性","悟後只是七住，說一悟即至佛地為大妄語"],"k":["十行位","性種性","禪宗公案","三會說法","善知識"]},"1727-a06_055":{"s":"本集依《楞嚴經》講解十迴向位前五位：救護一切眾生離眾生相迴向、不壞迴向、等一切佛迴向、至一切處迴向、無盡功德藏迴向。內容包括滅除度相、壞其可壞以破離念靈知為常、本覺湛然而除異生性現行，以及世界與如來互相涉入、普賢身的意涵。","p":["初迴向：度眾生並滅除得度之相","不壞迴向：壞離念靈知之可壞，遠離諸離","等一切佛迴向：種子清淨，異生性不現行","至一切處迴向：地如佛地，功德迴向一切處","無盡功德藏迴向：世界如來互相涉入"],"k":["十迴向位","離念靈知","留惑潤生","異生性","楞嚴經","普賢行"]},"1728-a06_056":{"s":"本集講解十迴向位第六至第十位：隨順平等善根迴向、隨順等觀一切眾生迴向、如相迴向（即一切法離一切相）、無縛解脫迴向、法界無量迴向（法界量滅），並引真淨克文禪師偈。最後總結遠波羅蜜多，並概述初地至七地的近波羅蜜多與八至十地的大波羅蜜多。","p":["六、七迴向：平等善根，不捨任何眾生","如相迴向：即一切法離一切相，即離無著","無縛解脫迴向與法界量滅、一真法界","三賢位圓滿即第一大阿僧祇劫遠波羅蜜多","初至七地近波羅蜜多，八至十地大波羅蜜多"],"k":["十迴向位","一真法界","近波羅蜜多","大波羅蜜多","道種性","三大阿僧祇劫"]},"1766-a06_057":{"s":"本集開始「應修一切種智」單元，說明總相智、別相智與一切種智（了知如來藏一切種子之智）的分別，並介紹心、意、識三能變。詳述第一能變阿賴耶識的能藏、所藏、我愛執藏，與阿賴耶識、異熟識、無垢識三名；再說第二能變意根末那識恆審思量、遍計執，是無明根源與輪迴主導。","p":["般若總相智、別相智與一切種智的次第","種子即界、功能差別，具三種能變","第八識能藏、所藏、我愛執藏","阿賴耶識、異熟識、無垢識三名的差別","意根恆審思量、處處作主，為無明根源"],"k":["一切種智","阿賴耶識","末那識","三能變","異熟識","無垢識"]},"1767-a06_058":{"s":"本集續講三能變，引《大乘起信論》說意根有業識、轉識、現識、智識、相續識五名，說明意根是三界萬法現起的原動力。再依《增壹阿含經》說識陰即六識，論證離念靈知仍是意識，執之為常即未斷我見。最後說明三乘修證皆不離三能變，勸已悟菩薩繼續進修一切種智。","p":["《大乘起信論》意根五名：業識至相續識","意根是輪迴根本，亦是成佛所需","《增壹阿含經》：識陰即眼至意六識","離念靈知屬識陰，執為常住即未斷我見","三乘修證不離三能變，悟後應修種智"],"k":["末那識","識陰","離念靈知","斷我見","大乘起信論","一切種智"]},"1732-a06_059":{"s":"本集開始介紹十地菩薩修道，先依《楞嚴經》講入地前煖、頂、忍、世第一四種妙圓加行，並區分它與唯識五位明心前斷我見的四加行。接著說明入初地的四條件，再講初地歡喜地：發十無盡願、修百法明門、留惑潤生、以法施為主，證猶如鏡像現觀而滿心。","p":["入地前煖、頂、忍、世第一四加行","此四加行不同於明心前斷我見的四加行","入初地四條件：聖性、修道性、增上慧、十願","初地歡喜地：通達大菩提而心中深喜","修百法明門、留惑潤生、法施，證鏡像觀"],"k":["初地","四加行","無生法忍","道種智","十無盡願","鏡像觀"]},"1735-a06_060":{"s":"本集講解二至四地修道。二地離垢地修持戒波羅蜜與千法明門，證見分如光影現觀而能轉變內相分；三地發光地修四禪八定、四無量心、五神通及萬法明門，證谷響觀；四地焰慧地現觀安立諦等，證猶如水月現觀，示現化身廣度有情。","p":["二地：異性入同，嚴持戒法除邪行障","二地證光影觀，可掌控自心內相分","三地：修四禪八定、四無量心、五神通","三地三種靜慮，成就谷響觀","四地：無始無明多除，證猶如水月觀"],"k":["二地","三地","四地","持戒波羅蜜","四禪八定","無生法忍"]},"1736-a06_061":{"s":"本集由正德老師講解五地極難勝地：以平等清淨心入五地，於四聖諦如實了知，修學醫方明等五明以四攝法利益有情。說明通達七真如中流轉、安立、邪行等真如，斷除「一向作意棄背生死」與「一向作意趣向涅槃」二愚。最後引《華嚴經》十平等法，先解說無相、無體兩種平等。","p":["以十種平等清淨心入五地","修五明世間工巧，以四攝法攝受有情","依如來藏通達四聖諦實性與七真如","斷棄背生死、趣向涅槃二種愚癡","《華嚴經》十平等：先說無相、無體平等"],"k":["五地","四聖諦","七真如","五明","四攝法","華嚴經"]},"1738-a06_062":{"s":"本集續講《華嚴經》十平等法，從無生、無滅到如幻如夢、有無不二，說明五地滿心成就變化所成現觀而入六地。六地現前地依一切種智順逆觀十二有支，空、無相、無願三解脫門現前，證滅盡定、無著智現前，斷二種愚；最後說明六地入七地前須修方便慧及其所依。","p":["十平等後八種：無生、無滅至有無不二","五地滿心成就變化所成現觀","六地順逆觀十二有支，皆一心所攝","證滅盡定，無著智、般若波羅蜜多住現前","入七地須修方便慧，不共聲聞、獨覺"],"k":["六地","十二因緣","三解脫門","滅盡定","方便慧","華嚴經"]},"1733-a06_063":{"s":"本集講六地修方便慧入七地遠行地：七地念念具足十波羅蜜，並逐一比較初地至六地的所緣。說明初地至七地是有加行有功用的無相作意，七地斷意根三界愛最後習氣而第八識轉名異熟識，能念念入滅盡定卻不證無餘涅槃，證揵闥婆城現觀；並強調三賢位須依止善知識。","p":["七地念念具足十波羅蜜","初地至七地為有加行有功用之無相觀","七地第八識阿賴耶性斷盡，轉名異熟識","念念入滅盡定而不取無餘涅槃","斷生相、滅相遍計執，證揵闥婆城現觀"],"k":["七地","方便慧","無相觀","異熟識","滅盡定","善知識"]},"1737-a06_064":{"s":"本集講解八地不動地：八地無生法忍的如實智，可追溯到七住證如來藏的實相般若無生智，並與二乘依五蘊的智慧區別。八地入地時諸佛勸導、授引發如來妙智三昧，得十種自在，斷七地無相住的四種障礙，於相於土自在，究竟轉依真如心。","p":["如實智源自七住證真如的實相般若無生智","八地無加行無功用，任運住於無相","諸佛勸導並授引發如來妙智三昧","得十自在，斷七地無相住四種障礙","色受想陰習氣盡，究竟轉依真如心"],"k":["八地","如實智","無功用行","十自在","轉依真如","無生法忍"]},"1734-a06_065":{"s":"本集講解九地善慧地與十地法雲地。九地發起真如心的功德力用，如實了知眾生心、煩惱、業、根器，以四無礙智善說三乘法，斷兩種愚。並區分菩薩見道（七住至十迴向）與修道（初地至九地），說明十地為受職位，受諸佛光明灌頂，能承受諸佛大法雨。","p":["九地發起真如心功德與力用","四無礙智：法、義、辭、樂說無礙","菩薩見道始於七住，修道始於初地","十地受職：大寶蓮華與諸佛光明灌頂","十地能受諸佛大法雨，故名法雲地"],"k":["九地","十地","四無礙智","見道與修道","法王子","四攝法"]},"1800-a06_066":{"s":"本集說明菩薩十地的意義：諸地因入佛智、證一切種智而有差別，並以大海十種相（次第漸深、不受死屍等）逐一譬喻十地的特質。接著說明等覺須百劫修相好，並區分聲聞、緣覺與佛菩提的發心，強調進入初地修道的前提，是三賢位七住實證如來藏。","p":["十地差別源於所證道種智的差別","以大海十種相譬喻初地至十地","諸地次第相續、不可逾越","等覺須百劫修相好以成大福德","入地修道之要在七住實證如來藏"],"k":["十地","佛智","一切種智","等覺","佛菩提","如來藏"]},"1722-a06_067":{"s":"本集說明佛菩提修證的樞紐在明心見性，先依三大阿僧祇劫劃分三賢位、初地至七地、八九地三階段，強調七住見道是一切進修的前提。再指出開悟與解脫果可證須具三項正知見：眾生有八識、了知何者是生滅法、必有不生不滅之心；講者並認為主張只有六識者未悟也未斷我見。","p":["三大阿僧祇劫的三階段劃分","七住明心見道是佛菩提修證樞紐","須勇猛精進且所學法門能實證","正知見：八識、生滅法、不生滅心","緣起性空依生滅法而顯，非不生滅法"],"k":["明心見性","八識","三大阿僧祇劫","生滅法","緣起性空","斷我見"]},"1723-a06_068":{"s":"本集續講佛菩提修證樞紐，論證必須有真實常住的第八識，才能執持三大阿僧祇劫的福德與智慧資糧。並從轉識成智、四智圓明說明大菩提依第八識成就；再說明本來自性清淨、有餘、無餘、無住處四種涅槃皆依第八識施設，意識不具涅槃法性，故開悟證第八識為關鍵。","p":["福德、智慧資糧須由常住第八識執持","轉識成智：八識各轉一智，四智圓明","七住已生下品平等性智與妙觀察智","四種涅槃皆依第八識法性施設","意識有生滅垢淨增減，不可稱為涅槃"],"k":["如來藏","轉識成智","大菩提","四種涅槃","第八識","大涅槃"]},"1769-a06_069":{"s":"本集開始講開悟證般若前三項注意事項（修集福德資糧、建立正知見、簡擇善知識），先談福德資糧。引《優婆塞戒經》校量外道至辟支佛及發菩提心的福德，引《金剛經》說明受持解說經義的法施勝過七寶布施，強調福德須依實證功德而修，並以信根為首，說明佛、法、僧三寶的正確意涵。","p":["開悟前三事：福德、正知見、善知識","《優婆塞戒經》：發菩提心勝辟支佛果","《金剛經》：如實解說四句偈勝七寶布施","福德依實證如來藏的功德而殊勝","善根以信根為首，須正知三寶意涵"],"k":["福德資糧","信根","三寶","法布施","發菩提心","金剛經"]},"1768-a06_070":{"s":"本集續談開悟前修集福德資糧，先說信根三層次：信有體、信有德、信有能，具足即清淨信，能深信因果、長養五根。再列舉修福德的各項：受三歸五戒與菩薩戒、行十善、布施、法忍、建立正知見、孝養父母，以及引《法華經》五十展轉隨喜說明勸發大乘菩提心的福德；講者並批評謗如來藏為外道神我。","p":["信根三層次：信有體、信有德、信有能","清淨信能深信三世因果、長養五根","受三歸五戒、菩薩戒，行十善不謗菩薩藏","布施應向能助證般若處，忍辱重在法忍","孝養父母、勸人發大乘菩提心"],"k":["福德資糧","信根","十善","法忍","菩薩戒","法華經"]},"1776-a06_071":{"s":"本集講解求悟般若前應建立的基本佛法知見：真正的佛法可以親證，講者批評將佛法視為「理性隨機適應、自由抉擇」的學者說法是把佛法淺化世俗化；並說明法義辨正的必要（引《尸迦羅越六方禮經》），以及須以六度修集福慧，略述布施、持戒、忍辱的意義。","p":["佛法可親證，佛佛道同，非意識思惟抉擇所得","因地不真果招紆曲，實相如來藏本來就在、不可思議","菩薩不忍學人受誤導，須作法義辨正、破邪顯正","求悟須福慧具足，以六度實現，眼光及於過去未來世","布施以法施最勝，持戒止過揚善，忍辱除瞋恚毒"],"k":["般若","法義辨正","六度","如來藏","福德資糧","善知識"]},"1770-a06_072":{"s":"本集續說忍辱、精進、禪定的福德，並勸將五度福德迴向無上正等正覺；說明求悟前須熏習蘊處界正知見、先斷我見，以免錯認意識為真我而犯大妄語；並解釋發願「得遇菩薩僧」並非謗小乘，引《摩訶般若波羅蜜經》說菩薩常為二乘作福田。","p":["忍辱、精進、禪定各有福德，皆應迴向成佛","前五度修福，再加長時熏習般若知見","先觀蘊處界虛妄斷我見，免錯認意識而退轉","菩薩兼含二乘法，常為聲聞辟支佛作福田","依止菩薩僧非謗小乘，三乘終歸一佛乘"],"k":["斷我見","蘊處界","六度","迴向","菩薩僧","一佛乘"]},"1771-a06_073":{"s":"本集依《大般若經》說菩薩種性尊貴，再列出衡量求悟般若進展快慢的八項條件：信心具足（於法、於自、於師）、求悟企圖心、精進心、長遠心、不以私心爭勝心推動、不恃聰明伶俐的意識心、生起出離生死心，以及發大願而不退卻。","p":["四阿含略說菩薩功德，顯聲聞難知菩薩所證","信心三分：信法可證、信自己、信真善知識","求悟要有企圖心、精進心與跨越多世的長遠心","私心、爭勝心與恃意識聰明參究皆為障道","須起出離三界生死之心，並發大願不退"],"k":["菩薩種性","信心","參禪","發願","出離心","開悟明心"]},"1773-a06_074":{"s":"本集講禪法知見：人人不少於也不多於八識，駁斥六識論、另立第九識及「妄心轉成真心」等說；區分禪、禪法與禪定，以《楞嚴經》指月喻說明不可以禪法為禪；並批評以定為禪、以一念不生為悟及五現涅槃的錯誤，引《大寶積經》與六祖偈說明。","p":["睡後意識能再生，須有不間斷的第八識為依","異熟識、無垢識皆第八識，只改其名不改其體","禪非禪法、非禪定；以指為月則亡月亡指","參禪要淨念相繼的定力，非一念不生的定境","五現涅槃：以五欲及四禪境界當作涅槃之誤"],"k":["八識論","六識論","禪定","一念不生","五現涅槃","如來藏"]},"1772-a06_075":{"s":"本集說明否定七、八識而以緣起性空、一切法空解說中觀般若，即成無因論與斷見，並依如來藏重新解讀《中論》「眾因緣生法」偈；講「離心意識參」的真義，列舉常見、斷見、自性見等參禪歧路；最後說明初次明心只是七住位、得根本智，尚須修後得智。","p":["否定第八識的緣起性空，成無因論與斷見","《中論》因緣生法偈，應依如來藏來解釋","禪門心意識指過現未意識；以之往離心意識參","歧路：常見、斷見、自性見（意識細心）","明心僅第七住、得總相智，續修別相智方入初地"],"k":["緣起性空","中觀","離心意識參","常見","斷見","根本智"]},"1774-a06_076":{"s":"本集先說悟後須修後得智、道種智乃至一切種智，不可目空一切；再區分世間老師與佛門善知識，引《雜阿含經》說明解脫道「法師」的定義；接著列出真善知識攝受學人見道的十項條件中的前九項，如教授正確禪法知見、接受定期諮詢、建立參禪功夫、親證明心見性、舉辦精進共修等。","p":["悟後修別相智、道種智，究竟一切種智方成佛","禪門「老師」須證悟者；說五陰生厭離欲者名法師","真善知識不破學人求悟信心，且不為人明說","能教正確禪法知見、接受諮詢、建立參禪功夫","須親證明心見性、發大願、指導悟後起修、辦共修"],"k":["善知識","後得智","一切種智","明心見性","參禪","解脫道"]},"1775-a06_077":{"s":"本集講第十項：尋覓善知識不是行腳參方，悟後不可生慢；引《華嚴經》說善知識出世、值遇、親近等八難，並依佛法意涵重新解釋《尸迦羅越六方禮經》善知識四輩；勸以發願「得遇菩薩僧」並實修六度萬行，作為「不久見道證真如」的方便，最後提出應自問求法動機。","p":["悟後不可自以為與善知識智慧相同而生慢","善知識難值：出興世難、得見知難、得隨順難等","四輩善知識：止諍、諫止隨惡知識、教治未來生等","發願「不遇聲聞緣覺師」須以實修六度萬行來成就","六度萬行即化長劫為短劫的見道方便"],"k":["善知識","發願","六度萬行","菩薩僧","見道"]},"1761-a06_078":{"s":"本集先總結發願須以六度實行；再說明宗門指第一義諦、自心如來的親證，教門則是其宣說與記載；引《解脫深密經》六種通與《楞伽經》說通，說明宗門通達的層次；並以人無我智開演教門，分述聲聞（四聖諦、三苦八苦）、緣覺（十因緣、十二因緣）與菩薩人無我智的差別。","p":["宗門為自心如來功能差別，教門為其宣說記載","宗門親證自七住起，至佛地究竟通達","六種通：真實義通、得通、離二邊通、意通、說通等","聲聞人無我智：依蘊處界觀四聖諦、三苦八苦","緣覺觀十因緣、十二因緣；菩薩證藏識無我為別教"],"k":["宗門教門","人無我","四聖諦","十二因緣","第一義諦","別教"]},"1762-a06_079":{"s":"本集說明菩薩依大乘密意宣說四聖諦、十二因緣，並比較二乘與菩薩的法無我智；講宗門與教門不可相離：可藉教悟宗（引《楞嚴經》與永嘉玄覺例），證悟不得違教，「不可說」是不可明說，講者批評「悟與教無關」之說；並開始講三乘菩提異同，述聲聞菩提及慧解脫、俱解脫之別。","p":["二乘不知四諦、十二因緣背後即如來藏","二乘法無我限於蘊處界；菩薩依藏識證法無我","可藉教悟宗，宗門證悟不得違背教門","「不可說」是不可明說，非悟境與經教無關","聲聞菩提斷我見我執；分慧解脫與俱解脫"],"k":["宗門教門","法無我","藉教悟宗","三乘菩提","聲聞菩提","俱解脫"]},"1696-a06_080":{"s":"本集續述聲聞鈍根與緣覺二類（有佛世聞法而證、無佛世獨覺），及各種悟入因緣；再從所斷二障、修證時劫、四種涅槃與第八識異名說明佛菩提與二乘的差異；引《優婆塞戒經》聞思修及三獸渡河喻，講者並批評「三乘一味、大乘只是悲心較切」之說，強調三乘匯歸一佛乘。","p":["緣覺有聞法而證與無佛世自悟的獨覺兩類","二乘只斷煩惱障現行；佛斷隨眠及所知障","四種涅槃：自性清淨與無住處唯大乘所證","《優婆塞戒經》：兔、馬、香象渡十二因緣河","大乘本含攝二乘，三乘皆匯歸一佛乘"],"k":["三乘菩提","緣覺","四種涅槃","所知障","一佛乘","優婆塞戒經"]},"1694-a06_081":{"s":"本集說明三乘共道即解脫道：聲聞依四聖諦、八正道斷結證四果；緣覺以十因緣逆推得知「齊識而還」的入胎識，再觀十二因緣滅；二乘知無餘涅槃非斷滅，卻不知本際何在。菩薩明心發起法身德、般若德、解脫德，前二者不共二乘，解脫德為三乘共有，菩薩則留惑潤生。","p":["聲聞以四聖諦為主、八正道為法，斷結證四果","緣覺逆推十因緣，知有名色所依的入胎識","二乘知無餘涅槃非斷滅，但不知本際何在","菩薩明心發起法身德、般若德，不共二乘","解脫德三乘共有，菩薩留一分思惑潤生"],"k":["解脫道","十因緣","入胎識","三德","無餘涅槃","留惑潤生"]},"1701-a06_082":{"s":"本集講二乘兩種涅槃（上）：詳解四聖諦，以生活例子說明三苦（苦苦、壞苦、行苦）與八苦，並述苦集滅道；說明斷三縛結（我見、疑見、戒禁取見）的簡擇方法，講者並批評一念不生、說法聽法這念心等說；述初果極七往返，並引《優婆塞戒經》與貧女難陀燃燈例，說供養初果以上得無量報。","p":["二乘入無餘涅槃須斷結，佛法非僅四諦八正道","三苦：苦苦、壞苦、行苦；八苦含五陰熾盛苦","苦集源於無明造業，滅五陰即苦集滅聖諦","斷我見後簡擇諸方說法，斷疑見、戒禁取見","初果極七往返；施須陀洹以上得無量報"],"k":["四聖諦","三縛結","初果","三苦八苦","布施"]},"1702-a06_083":{"s":"本集續講二果至四果：二果薄貪瞋癡；三果斷五下分結必發初禪，說明初禪三類發起情形與勘驗方法，講者並批評坦特羅樂觸、氣功之說；述三果七種般涅槃，即《增壹阿含》所說有餘涅槃；四果分慧解脫等三類；最後引《十二門論》說二乘實無人證涅槃，並述正覺弘法所受抵制。","p":["二果薄貪瞋癡，欲界天人間一往來","三果斷五下分結，必發初禪；初禪發有三類","三果有七種般涅槃，即《增壹阿含》有餘涅槃","四果分慧解脫、俱解脫、三明六通阿羅漢","五陰滅盡無人證涅槃，佛方便說二乘證涅槃"],"k":["三果","初禪","五下分結","有餘涅槃","阿羅漢","中般涅槃"]},"1758-a06_084":{"s":"本集依菩薩五十二階位說明大乘四種涅槃：七住明心證本來自性清淨涅槃並發起三德；十住眼見佛性成如幻觀；十行陽焰觀；十迴向如夢觀、性障永伏如三果，可證有餘依涅槃；初地滿心能證無餘涅槃而不取；三地俱解脫、六地滅盡定；成佛證無住處涅槃。","p":["二乘有餘涅槃有二義，多數人只知其一","七住明心證本來自性清淨涅槃，具四種性","十迴向滿心前性障永伏，可證有餘依涅槃","初地滿心如慧解脫，能入無餘涅槃而不取證","成佛證無住處涅槃，不住生死亦不住涅槃"],"k":["四種涅槃","本來自性清淨涅槃","五十二階位","無住處涅槃","眼見佛性","留惑潤生"]},"1678-a06_085":{"s":"本集指出四種涅槃中，本來自性清淨涅槃與無住處涅槃不共二乘；引《解深密經》「阿陀那識甚深細」說佛不為凡愚開演；再依《成唯識論》卷十的定義歸納三個重點，本集講第一點：此涅槃是一切法根本、與諸法非一非異（以手與身喻），並引《勝鬘經》說自性清淨心而有染污，講者批評應成派六識論者。","p":["菩薩不滅蘊處界即證涅槃，非阿羅漢所知","佛不為凡愚開演阿陀那識，恐執為我","《成唯識論》卷十定義本來自性清淨涅槃","一切法從此藉緣出生，與諸法非一非異","《勝鬘經》：自性清淨心而有染污，難可了知"],"k":["本來自性清淨涅槃","阿陀那識","非一非異","自性清淨心","成唯識論","應成派中觀"]},"1682-a06_086":{"s":"本集講本來自性清淨涅槃第二重點：無生無滅、無始本有（引《心經》不生不滅、《成唯識論》「無始時來界」），以及不分別六塵、離見聞覺知（引《金剛三昧經》、《維摩詰經》、《心地觀經》、《占察經》及黃檗禪師開示）；講者批評以說法聽法之心、意識細心、樂觸、無妄想心為真心的說法。","p":["此心不生不滅、無始本有，非修行而得","一切境界與業種皆不外於此心，故有輪迴與涅槃","意識無論粗細、樂觸境界皆生滅法，非真心","經論與黃檗皆說真心離見聞覺知、不分別六塵","應以見聞覺知心往離見聞覺知的方向參"],"k":["本來自性清淨涅槃","不分別六塵","離見聞覺知","意識","常見"]},"1680-a06_087":{"s":"本集講第三重點：菩薩親證本來自性清淨涅槃的智慧非凡夫二乘所知。舉雪峰義存說明破參不易；破參前須經十信至六住並以四加行斷我見；悟後須能安忍且有善知識攝受，舉《瓔珞經》淨目天子、舍利弗退失例；引《成唯識論》卷九說真見道與相見道，駁「悟即初地」之說，並總結三德與四涅槃。","p":["雪峰義存多次參訪方於鰲山成道，破參不易","破參前須經十信至六住，以四加行斷我見","悟後須安忍並有善知識攝受，否則易退失","真見道得根本智，相見道得後得智，圓滿方入初地","三德中解脫德共三乘，法身德、般若德不共"],"k":["真見道","相見道","總相智","破參","善知識","三德"]},"1693-a06_088":{"s":"本集說明二乘無生智只是將滅止生，菩薩則觀此心與所生蘊處界本來無生；二乘視諸法實有而畏生死，菩薩依真心觀人法無我；引《入楞伽經》說有情八識具足、真妄和合運作似一，講者批評六識論、意識細心與無妄想心為真心等說；並依《成唯識論》卷三說阿賴耶、異熟、無垢皆第八識異名。","p":["二乘無生智為將滅止生，菩薩證本來無生","二乘以為諸法實有而畏生死，急入無餘涅槃","有情皆八識具足：前七識妄，第八識真","意識粗細皆意法因緣生，修清淨也不成真心","阿賴耶、異熟、無垢識仍是八識論，非另立識"],"k":["無生智","八識論","真妄和合","法無我","第八識異名","六識論"]},"1683-a06_089":{"s":"本集講一念無明（四種住地煩惱）與無始無明之別，說明二乘只斷煩惱現行，未斷習氣種子隨眠與無始無明；以鴿入舍利弗影、畢陵伽婆蹉稱恆河神「小婢」等例說明習氣；並依菩薩位次述如幻、陽焰、如夢等現觀及色受想行識五陰次第盡，最終斷盡習氣與無始無明成佛。","p":["一念無明含見一處、欲愛、色愛、有愛住地","無始無明是對生命實相無知，不障解脫","二乘只斷煩惱現行，未斷習氣種子隨眠","鴿入佛影無怖、畢陵「小婢」例說明習氣","菩薩依地次第五陰盡，斷習氣與無始無明"],"k":["一念無明","無始無明","習氣種子","四住地煩惱","五陰盡"]},"1685-a06_090":{"s":"本集講三乘異生性的差別：異生性是造下來世不得為人而墮三惡道的體性，含謗佛、謗法、謗賢聖等；舉善星比丘、世親菩薩早年謗大乘、婆羅門女謗比丘為例；引《成唯識論》卷九說二乘見道即斷異生性，菩薩至初地方斷；最後略提其他不共處，總結大乘函蓋二乘，講者批評坦特羅與「阿羅漢即佛」之說。","p":["異生性：謗佛、謗法、謗賢聖等致墮三惡道","善星謗佛、世親謗大乘後以弘法轉業","婆羅門女輕心謗比丘，五百世為瞎眼鳥","二乘初果見道即斷異生性，菩薩至初地才斷","大乘函蓋二乘法道，阿羅漢不能稱為佛"],"k":["異生性","謗法","初地","成唯識論","世親菩薩"]},"1679-a06_091":{"s":"本集比較三乘聖人斷煩惱的同異：聲聞依四聖諦八正道、獨覺與緣覺依因緣觀，同樣斷我見我執（見惑思惑）而出離三界；但二乘只斷三界愛現行，不能斷習氣種子。菩薩從初地分斷習氣，到佛地斷盡二障，並舉蜈蚣之例及《大方便佛報恩經》鴿入舍利弗影仍怖畏為證。","p":["三乘共斷我見我執，即見惑與思惑","獨覺於無佛之世自觀因緣，緣覺依佛開示證果","二乘只斷三界愛現行，習氣種子仍在","鴿入舍利弗影猶怖、入佛影無怖","菩薩初地起分斷習氣，佛地究竟斷盡"],"k":["習氣種子","斷我見","我執","煩惱障","辟支佛","阿羅漢"]},"1684-a06_092":{"s":"本集先引《大智度論》畢陵伽婆蹉稱恆河神為「小婢」的典故，說明阿羅漢仍有慢習；接著進入大小乘五種境界差別的第一種「斷疑」，依《優婆塞戒經》分煩惱疑與無記疑，辨正初果「於諸方大師不疑」的正確意思，並開始解說異熟的變異而熟、異時而熟。","p":["畢陵尚慢：二乘身口業習氣未盡","菩薩斷我執後可留惑潤生","疑分煩惱疑與無記疑，二乘只斷前者","「於諸方大師不疑」指能判斷大師是否斷我見","無記疑關乎異熟：變異而熟、異時而熟"],"k":["斷疑","無記疑","異熟","疑見","習氣種子","留惑潤生"]},"1681-a06_093":{"s":"本集續說無記疑，以往生他方淨土、來世換了身形等例子，解說異熟有異地而熟、異類而熟、變異而熟等面向。講者說明無記疑範圍深廣，只有諸佛究竟斷盡，地上菩薩只能少分多分斷除，二乘無法斷；倒駕慈航的妙覺菩薩是例外，並說自稱成佛而仍有無記疑即是大妄語。","p":["無記疑是對異熟種子不能具足了知","異地而熟、異類而熟、變異而熟舉例","異熟法本身無善惡，屬無記性","唯佛究竟斷無記疑，等覺尚未斷盡","倒駕慈航的妙覺菩薩為例外"],"k":["無記疑","異熟","異熟識","一切種智","倒駕慈航"]},"1686-a06_094":{"s":"本集依《優婆塞戒經》「聲聞厭於多聞，緣覺厭於思惟」，說明大小乘第二種差別在多聞與思惟：定性二乘只求解脫，常入滅盡定，不樂聽聞成佛之法；菩薩乃至八地仍樂於多聞思惟。並駁斥「悟後應讀懂一切經典」之說，指初悟者只懂般若類經典，且多聞須以智慧簡擇善知識。","p":["聲聞厭多聞，緣覺厭思惟，佛於二者無厭","定性阿羅漢飯後常入滅盡定","七住明心只得般若總相智","悟後應懂心經金剛經，未必懂唯識經典","多聞須以正見擇善知識，免受邪教導"],"k":["多聞熏習","定性聲聞","緣覺","明心","唯識種智","善知識"]},"1687-a06_095":{"s":"本集講大小乘第三種差別「智器清淨」，依《優婆塞戒經》淨物置淨器之喻，說二乘解脫智清淨但根器不淨，唯佛智器俱淨。並引《大乘起信論》退墮二乘地、焦芽敗種、《華嚴經》藥王樹不能利益二乘、《大般若經》習氣相續、《雜寶藏經》聲聞不能作眾生大善知識等為證。","p":["二乘智淨而器不淨，如來智器俱淨","定性二乘入無餘涅槃，被稱焦芽敗種","佛智藥王樹於二乘無為深阬不能利益","二乘無大慈悲，習氣相續仍在","聲聞不能為眾生作大善知識"],"k":["智器俱淨","焦芽敗種","定性二乘","習氣種子","大慈大悲"]},"1689-a06_096":{"s":"本集講第四種差別「行淨」，依《優婆塞戒經》說二乘雖有淨智而行不清淨，如來智行俱淨。引《大智度論》大迦葉聞菩薩伎樂不能安坐而欲起舞，說明二乘有習氣，其不受三昧不究竟；並說二乘智慧只在廣義上清淨，只觀蘊處界世俗諦，不涉實相法界，從狹義看並不究竟。","p":["淨分智淨與行淨，二乘行不清淨","二乘身口行可淨，意行因習氣不能絕對清淨","大迦葉聞伎樂欲舞，顯示習氣未盡","不受三昧不與二乘共","二乘智只知蘊處界世俗諦，不知實相"],"k":["行淨","習氣種子","不受三昧","大迦葉","世俗諦","實相"]},"1688-a06_097":{"s":"本集講第五種差別「行有邊與行無邊」，依《優婆塞戒經》說二乘捨壽入無餘涅槃，利益眾生之行有邊；菩薩依四宏誓願與初地十無盡願（《華嚴經》十盡句），三大阿僧祇劫乃至成佛後仍利樂有情，其行無邊。並引《佛說華手經》網明菩薩之語，總結五種差別，以爪上塵與大地土比喻解脫道與佛菩提道。","p":["二乘入無餘涅槃後再無利生之行","菩薩發四宏誓願與十無盡願","華嚴十盡句：眾生界盡我願乃盡","華手經：如來所行名無邊行","解脫道如爪上塵，佛菩提道如大地土"],"k":["無邊行","十無盡願","四宏誓願","普賢行","無餘涅槃"]},"1692-a06_098":{"s":"本集依《勝鬘經》說明二乘所得涅槃是佛方便說：唯如來成就無量、不可思議功德與第一清淨，阿羅漢仍有習氣與上煩惱等餘過，去涅槃界遠。並講分段死與不思議變易死，說明佛具四種涅槃含無住處涅槃，以及「我生已盡、梵行已立、所作已辦」在三乘中的定位。","p":["阿羅漢辟支佛得涅槃是佛方便說","二乘有餘過：習氣未斷、上煩惱未斷","七住菩薩證本來自性清淨涅槃","二種死：分段死與不思議變易死","我生已盡等三句是依分段生死而說"],"k":["勝鬘經","涅槃","變易生死","分段生死","無住處涅槃"]},"1690-a06_099":{"s":"本集續解《勝鬘經》：二乘「不受後有」是方便說，因未斷習氣與上煩惱，仍有變易生死。逐一解說住地煩惱與起煩惱、四住地（見一處、欲愛、色愛、有愛住地），以及「心不相應無始無明住地」；說明四住地力是上煩惱依種，故菩薩留惑潤生，而無明住地力最大，如波旬於他化自在天。","p":["二乘不受後有是方便說，非究竟","四住地生起一切起煩惱，剎那相應","無始無明住地與覺知心不相應","四住地為上煩惱依種，菩薩留惑潤生","無明住地力最大，唯佛菩提智能斷"],"k":["四住地","無始無明","上煩惱","勝鬘經","留惑潤生"]},"1691-a06_100":{"s":"本集歸納一念無明與無始無明的差別：一念無明以我見為根本，分四住地，是引生分段生死的煩惱障，無始有終，阿羅漢可斷盡（引《阿含》與《瑜伽師地論》）。無始無明是對法界實相的無知，不障解脫而障成佛，是所知障。並辨正「所知太多為所知障」之誤解，說明斷盡二障才成佛、第八識成無垢識。","p":["明心破無始無明時必同斷我見","一念無明分四住地，無始有終","無始無明不障出離三界，障實相","所知障是對實相無知，非所知太多","斷盡二障隨眠，第八識成無垢識"],"k":["一念無明","無始無明","所知障","煩惱障","如來藏"]},"1709-a06_101":{"s":"本集探討什麼是無明：引《分別緣起初勝法門經》、《緣起經》十二因緣與無明定義、《雜阿含經》舍利弗答拘絺羅，說明無明即對五陰無常及諸法無知。無明使眾生不斷入胎受生；無明分二乘的一念無明（煩惱障）與大乘的無始無明（所知障），通教只斷前者，別教明心破後者。","p":["無明是一切雜染法的根本依處","緣起經：於前際後際等諸法無知即無明","於五受陰如實不知，名為無明","因無明，意根帶阿賴耶識不斷受生","無明分一念無明與無始無明"],"k":["無明","十二因緣","一念無明","無始無明","五陰","所知障"]},"1676-a06_102":{"s":"本集詳說一念無明：因一念心動即生我見我執、流轉生死而得名。解釋「住地」之義，以及見一處住地（見惑）、欲界愛、色界愛（含外道五現見涅槃）、無色界愛（有愛）住地。說明一念無明源於阿賴耶識中的煩惱種子，而非見聞覺知靈性，引《瓔珞本業經》、《勝鬘經》，並說其無始有終。","p":["一念心動導致意根意識不能滅除","見一處住地屬見惑，餘三住地屬思惑","色界愛住地即貪著初禪至四禪境界","有愛住地是執著能知能覺的心","一念無明源於阿賴耶識的煩惱種子"],"k":["一念無明","四住地","見惑","思惑","起煩惱","阿賴耶識"]},"1782-a06_103":{"s":"本集詳說無始無明：屬所知障，所斷為塵沙惑即上煩惱，障成佛而不障解脫。依《勝鬘經》說它與覺知心不相應，要到探究生命實相時才相應，明心證如來藏才算打破；悟後探求為何未成佛時，才與上煩惱相應。並解說四住地為上煩惱依種，故菩薩須留惑潤生、保有五陰。","p":["三惑：見惑、思惑與塵沙惑","所知障是對實相及如來藏種子所知不足","探究法界實相時才與無始無明相應","明心破無始無明，悟後求成佛才起上煩惱","上煩惱依四住地，須留惑潤生"],"k":["無始無明","塵沙惑","上煩惱","所知障","明心","留惑潤生"]},"1703-a06_104":{"s":"本集說明二種無明如何究竟斷盡：無明在自己的如來藏中。明心時同時破所知障與見一處住地、斷三縛結；再依四果次第（極受七有、薄地、離地、畢地）修斷三界愛。菩薩依賴耶緣起受生，於初地、七地、八地次第斷習氣與上煩惱，至金剛喻定成佛；並強調悟後須起修。","p":["無明存於自己的如來藏，與他人無關","明心證如來藏時同斷我見與三縛結","初果至四果次第斷三界愛","七地滿心改名異熟識，佛地成無垢識","悟後起修，非悟即成佛"],"k":["一念無明","無始無明","四果","異熟識","無垢識","悟後起修"]},"1759-a06_105":{"s":"本集比較大小乘所斷無明與所證涅槃：二乘依四聖諦或因緣觀斷一念無明，證有餘依、無餘依涅槃；大乘有四種涅槃，七住證本來自性清淨涅槃，初地入地心得兩種、滿心得三種，唯佛具四種含無住處涅槃。並依《優婆塞戒經》說菩薩明心乃至佛能一念破二障，四種涅槃都依如來藏立名。","p":["慧解脫阿羅漢以四聖諦觀斷我見我執","有餘依涅槃為微苦所依，捨報入無餘","說無垢稱經：真如即般涅槃","初地入地心得二種，佛具四種涅槃","一念破智障與解脫障，故名為佛"],"k":["四種涅槃","本來自性清淨涅槃","無住處涅槃","一念無明","無始無明","二障"]},"1765-a06_106":{"s":"本集解說如來大般涅槃的常樂我淨四德，引《大般涅槃經》、《勝鬘經》說明唯佛地無垢識不再變異才是真常；佛地第八識與別境等心所相應、有證自證分，才稱為我。二乘法則說非常非樂非我非淨，菩薩四倒未盡。講者並批評應成派中觀把如來藏視為外道神我、藏密以雙身法為報身佛之樂。","p":["常樂我淨是佛地無垢識的四德","自性清淨心而有染，唯佛能如實知","因地第八識受熏變易，非真常","佛地第八識有證自證分，才名為我","講者批評藏密雙身法與應成中觀"],"k":["常樂我淨","大般涅槃","無垢識","如來藏","勝鬘經"]},"1760-a06_107":{"s":"本集回應「如來藏是外道梵我、神我」的質疑：先說明《奧義書》梵我一如思想，指出梵即大梵天，外道神我其實是依緣而生的意識心。再說小乘學說難以解決輪迴主體與感果功能，意識細心說也不成立；依《楞伽經》與《成唯識論》阿賴耶識自相、因相、果相，說明如來藏離見聞覺知、本具無我性，不同於神我。","p":["梵我一如思想源自奧義書","梵即大梵天，神我實為意識心","輪迴主體與感果功能兩大難題","楞伽經：七識不流轉，如來藏是涅槃因","成唯識論阿賴耶識三相：自相、因相、果相"],"k":["如來藏","梵我","神我","阿賴耶識","輪迴主體","意識細心"]},"1698-a06_108":{"s":"本集論證聲聞解脫道依如來藏建立：初果依《雜阿含經》觀六識由根塵為緣而生，再推究六根由本識而生，以斷我見；須接受意根滅、識滅才證涅槃。無餘涅槃滅盡五陰卻非斷滅，如空村之喻；並引《中阿含經》內有恐怖、舍利弗破焰摩迦邪見及「五陰非我、不異我、不相在」為證。","p":["六識根塵緣生，六根依本識而生","解脫須接受意根滅、識滅","無餘涅槃非斷滅，如來藏獨住","否定如來藏者觀滅盡會生內有恐怖","舍利弗破焰摩迦「阿羅漢死後無所有」"],"k":["如來藏","斷我見","無餘涅槃","斷滅見","五陰","阿含經"]},"1699-a06_109":{"s":"本集從三法印論證二乘菩提依如來藏建立：分別解說身口意行粗細之諸行無常、二乘與大乘所證人無我法無我的差別，以及如來藏獨住的涅槃寂靜。引《雜阿含經》「誰般涅槃」、《金剛經》「實無眾生得滅度」，並批評以緣起性空統一三法印的主張，講者認為那會落入斷滅與戲論。","p":["三法印以涅槃寂靜的如來藏為中心","身口意行不論粗細皆屬行陰而無常","二乘與大乘所證法無我不同","誰般涅槃：滅盡自己而本際獨存","講者批評緣起性空統一三法印說"],"k":["三法印","如來藏","涅槃寂靜","諸法無我","緣起性空","斷滅見"]},"1745-a06_110":{"s":"本集總結三乘菩提異同，說「唯一佛乘，無二無三」：佛依四悉檀隨機說法，引《法華經》一大事因緣與一佛乘，說明成佛須證一切種智，而三乘皆依如來藏建立。因別教難信，佛先施設二乘，再以三轉法輪引導，故是小從大起。講者並批評「解脫道即成佛之道」的說法及「金剛持佛」雙身法。","p":["四悉檀：世界、為人、對治、第一義","法華經：諸佛唯為一佛乘說法","一切種智是如來藏種子的具足證知","一會、二會、三會說法與三轉法輪","先小後大，而小從大起"],"k":["唯一佛乘","法華經","四悉檀","一切種智","三轉法輪","如來藏"]},"1715-a06_111":{"s":"本集開始講佛教歷史與宗派見解。先引《大集經》五個五百年的預記，說明末法時期正法難遇、錯誤知見如稗草種子；再引《六度集經》說六度是渡生死大海的方法，引《法華經》說諸佛為開示悟入佛知見這一大事因緣出世。並以水晶球為喻，說阿羅漢只證空相，佛出世是要眾生證得本來清淨的如來藏。","p":["《大集經》預記：正法逐漸衰微，末法多鬥諍","錯誤佛法如稗草、毒種，再努力也結不出正果","六度波羅蜜是渡無極生死大海的方法","諸佛為開示悟入佛知見一大事因緣出世","阿羅漢只證空相；佛令眾生證本來清淨的如來藏"],"k":["一大事因緣","如來藏","末法","六度波羅蜜","空相與空性"]},"1717-a06_112":{"s":"本集說明成就佛國需要眾多有緣弟子共同護持，並講頻婆娑羅王迴向功德、救度累劫為餓鬼的親眷的本生故事。指出世尊下生前，菩薩已先到印度準備，使五乘教法的內容在民間流傳；並介紹印度文化以宗教解脫為目標，如吠陀的人生四目的與四行期。","p":["成佛事業需無量有緣弟子共同成就","頻婆娑羅王迴向功德，救親眷脫離餓鬼道","佛下生前菩薩先來，傳播五乘教法的實質","印度文化自古以宗教解脫為人生終極目標","吠陀的法欲利解脫與四行期"],"k":["本生故事","迴向功德","五乘佛法","印度文化","吠陀"]},"1716-a06_113":{"s":"本集說明佛出世前，菩薩以外道身分傳人天乘因果之法，並舉《吠陀》的「一」與《石氏奧義書》偈，說古印度已追求萬有本源；又講樹神化現比丘尼點化比丘的故事。講者認為緣起性空、性空唯名在佛前外道已說過，不是佛教的不共法，並引出梵我與涅槃相似的問題。","p":["菩薩以外道表相傳五戒十善與因果","吠陀「一」與奧義書偈：追求萬法本源","樹神化比丘尼說法，令退心比丘證果","《大林》書三類業與見道觀念","緣起性空、性空唯名早見於外道，非不共法"],"k":["如來藏","奧義書","緣起性空","菩薩示現","梵我"]},"1714-a06_114":{"s":"本集說明佛前的菩薩以隱覆方式在印度傳播如來藏概念，如佛的禪定老師與耆婆。接著講佛陀生平：初生說「天上天下唯我獨尊」、阿私陀仙預言、苦行與成道時四智圓明。再詳說五時三教：華嚴時、鹿苑阿含時（藏教）、般若方等時（通教）、唯識種智時（別教）、法華涅槃時（圓教），總結為「五時一味」。","p":["佛前菩薩以相似法讓眾生熏習如來藏概念","初生七步、唯我獨尊是第一義諦開示","成道時親證如來藏，四智圓明","五時：華嚴、阿含、般若、唯識、法華涅槃","五時三教皆以如來藏法乳所成，五時一味"],"k":["五時三教","如來藏","判教","三轉法輪","四智圓明"]},"1778-a06_115":{"s":"本集依《大梵天王問佛決疑經》講拈花微笑的公案：大梵天王獻花，世尊拈花，大迦葉微笑，佛以正法眼藏、涅槃妙心付囑迦葉。說明如來藏是諸佛密意，非語言思量所能測度，「非因非果、非修非證」，唯佛與佛能究盡；並解說「金色頭陀」顯示迦葉的出身。","p":["五時一味：如來藏貫穿佛一代時教","世尊初生即開示大事因緣，眾生不會","拈花微笑，以正法眼藏付囑大迦葉","如來藏非思量所及，非因非果、非修非證","大梵天王與十六國王讚歎如來藏密意"],"k":["教外別傳","拈花微笑","正法眼藏","如來藏","大梵天王問佛決疑經"]},"1780-a06_116":{"s":"本集續講《大梵天王問佛決疑經》：佛性須持戒才能顯露，真如是無漏性戒；佛預記魔波旬將現四眾與聖者身相，說方等經非佛說來壞法，講者認為這類說法今日瀰漫佛教界。經中說一切相皆是真實相，講者解釋是指諸相背後平等的如來藏，並列舉經文所遮的錯誤觀法。","p":["佛性因持戒顯露，真如即無漏性戒","預記魔波旬作四部像，說大乘方等經非佛說","不受方等經者非佛弟子","一切相皆真實相，指諸相背後的如來藏","勿作空假觀、緣起所生觀等，須以神會"],"k":["如來藏","大乘非佛說","諸法實相","性戒","大梵天王問佛決疑經"]},"1779-a06_117":{"s":"本集總結決疑經：如來藏須心心相印、以神會之，三乘都以如來藏為唯一佛乘串起。接著講佛滅後能證真如者稀少，以晨星與金字塔為喻；評中國判教史，講者認為慧遠、智者大師因未實證而判教有誤，直到玄奘、窺基才完整呈現；並述《成唯識論》源自護法菩薩，以及唯識宗兩代後中衰的經過。","p":["如來藏須以神會，妄心作觀即隔億劫","如來藏為唯一佛乘，串起三乘佛法","能證真如者稀少，如晨星、金字塔頂端","講者認為未證者判教難免有誤，玄奘才完整","《成唯識論》源自護法，玄奘後兩代中衰"],"k":["如來藏","判教","玄奘","成唯識論","唯識種智","窺基"]},"1781-a06_118":{"s":"本集依《付法藏因緣傳》講阿難晚年的事蹟：糾正比丘誤誦的「水老鶴」偈，比丘之師卻說阿難老糊塗；阿難感慨後決定入滅，度化五百仙人證阿羅漢，把法付囑罽賓國的末田地，最後神變火化分舍利。講者藉此說明佛滅不久正法已衰、法傳邊地，並指出佛教在印度從未成為最大宗教。","p":["阿難糾正誤偈：不解生滅法，不如生一日","比丘之師輕視阿難，阿難感慨正法速衰","阿闍世王追送，五百仙人隨阿難出家證果","付法罽賓末田地，神變火化分舍利","佛滅數十年正法已衰，法傳邊地"],"k":["阿難","付法藏","正法衰敗","末田地","佛教史"]},"1712-a06_119":{"s":"本集說明佛世與阿育王時，佛教都不是印度最大宗教，婆羅門教與六師外道融合成的印度教才是主力。又說部派分裂是因凡夫僧多、互不相服。接著依窺基《說無垢稱經疏》介紹八門宗義的前六門，從我法俱有宗到諸法但名宗，並指後者即應成中觀，源自印度教的辯論術。","p":["佛教從未在印度占壓倒優勢，印度教為主力","阿育王等平等護持各宗教","凡夫僧把持僧團，導致部派一再分裂","窺基八門宗義：前四門純屬小乘","諸法但名宗即應成中觀，源於辯論術"],"k":["八門宗義","部派佛教","應成中觀","窺基","佛教史"]},"1713-a06_120":{"s":"本集續談八門宗義，說應成技巧不是佛護所創，部派自稱阿羅漢傳承卻水火不容，是因錯會二乘菩提、引入外道思想；講者並認為南傳佛法只是赤銅鍱部支派、較晚才興盛。再介紹第七勝義皆空宗（清辨、自續中觀）與第八應理圓實宗（護法、瑜伽行），並引《長阿含》入胎識說明空相與空性的關係。","p":["部派見解互異，因錯會二乘菩提、引入外道","講者認為南傳佛法屬赤銅鍱部，晚起非原始","勝義皆空宗：清辨自續中觀","應理圓實宗：護法，以真如為第一義諦","空相依入胎識空性而有，應成中觀傷害最深"],"k":["八門宗義","自續中觀","應成中觀","空相與空性","入胎識"]},"1785-a06_121":{"s":"本集總結三乘菩提架構的前三點結論：一、如來藏是宇宙與生命運轉的根本，引《心地觀經》《華嚴經》說三界唯心、萬法唯心造，業種藏於如來藏、依異熟性受報；二、佛陀依實證如來藏，斷盡煩惱障與所知障而成佛；三、成佛須歷經五十二階位，並詳述十信至十迴向的修證內容。","p":["如來藏是宇宙及生命的根本實相","業種存於如來藏，依異熟性自受果報","依本來自性清淨涅槃斷二障而成佛","成佛須圓滿五十二階位","七住明心、十住見性、十迴向滿心入地"],"k":["如來藏","五十二階位","煩惱障","所知障","本來自性清淨涅槃"]},"1786-a06_122":{"s":"本集續講結論：依序說明二地到妙覺的修證，講者認為未到妙覺而想即身成佛是大妄語；四、三身都以清淨法身為依止；五、引《報恩經》《菩薩地持經》《起信論》說明成佛須三大阿僧祇劫；六、二乘是由一佛乘方便施設的化城；七、世尊三轉法輪化緣周畢才入滅，應以第三轉法輪了義法為依止。","p":["二地至十地、等覺、妙覺的修證內容","未到妙覺妄想即身成佛，是大妄語","佛三身皆依清淨法身如來藏成就","成佛須三大阿僧祇劫，無超越之法","二乘是方便化城；應依第三轉法輪了義法"],"k":["五十二階位","三大阿僧祇劫","一佛乘","三身","三轉法輪","即身成佛"]},"1731-a06_123":{"s":"本集回答修學佛法為何一定要評論外道。講者說宇宙生命實相非世間智慧所及，舉《解深密經》七萬七千外道推求不得為例；說明外道指遠離如來藏真理的法門，未證悟者難辨正邪，斷人法身慧命罪重。因末法邪師多，善知識須「摧邪顯正」，並引佛說「我不與世間諍」，說明依正理破邪不算諍論。","p":["佛法實相非世智、科學所能推求","遠離如來藏真理的法門稱為外道","未證如來藏者難辨正邪，斷慧命罪重","末法邪師多，須摧邪才能顯正","佛說「我不與世間諍」，如法論說非諍論"],"k":["摧邪顯正","外道","如來藏","法身慧命","末法"]},"1739-a06_124":{"s":"本集說明「外道」一詞不含歧視，指所修不符正道者。將佛世九十六種外道歸為四種邪執：邪因邪果、無因有果、有因無果、無因無果，並以如來藏的異熟性說明因果真實。講者批評末法附佛法外道混入佛門、以相似佛法取代正法，引《雜阿含》與獅子身中蟲之喻；並說佛陀以施論、戒論、生天論次第接引外道。","p":["外道指所修不合正道，並非歧視","四種邪執：邪因邪果、無因有果等","人天善法未假冒佛法者仍予讚歎","相似像法興起則正法滅，如獅子身中蟲","佛以施論、戒論、生天論接引外道入正法"],"k":["外道","四種邪執","相似佛法","因果","如來藏"]},"1787-a06_125":{"s":"本集依三乘菩提正見檢視應成派中觀。講者先勸未悟者勿隨意評論善知識，再說不承認如來藏的教法不是真實佛法，並述應成派以《入中論》等曲解龍樹、否定阿賴耶識的源流，也批評台灣某法師承襲六識論。接著列出六點錯誤：細意識常住、細意識持種入胎、樂空雙運、外境極微實有、阿賴耶由細意識假立、即身成佛。","p":["未明心前勿隨意評論善知識","不承認如來藏者非真實佛教","講者評應成派曲解龍樹中論、否定阿賴耶識","列細意識常住、持種入胎等六點錯誤","造業必自受報：隱身草、野狐公案"],"k":["應成中觀","六識論","細意識","阿賴耶識","如來藏"]},"1793-a06_126":{"s":"本集是綜論第一集，概略複習菩薩五十二階位。說明十信位須一劫到萬劫才能圓滿；十住位依序修布施到般若，在般若度隨善知識建立正知見，如五蘊虛妄、無餘涅槃有本際、兩種因緣法中「識」的不同、真心離見聞覺知；接著是七住明心、十住見性，直到十地、等覺百劫修相好與妙覺成佛。","p":["五十二階位如求學，須次第圓滿","十信位圓滿須一劫至一萬大劫","十住位次第修布施至般若度","七住明心、十住見性成就如幻觀","十地依次現觀，等覺百劫修相好"],"k":["五十二階位","六度波羅蜜","明心見性","十信位","菩薩道"]},"1795-a06_127":{"s":"本集是綜論第二集，說明菩薩悟前悟後的差異：悟前不知從何下手，破參後發起二乘不知的般若智慧，並同時斷除我見、疑見、戒禁取見三縛結，能檢點諸方說法。接著說明聲聞菩提的四聖諦，指出《阿含經》以本際、如、「非我非異我不相在」的我等異名隱說如來藏，以及初轉法輪隱說而不明說的原因。","p":["破參後發起般若智慧，二乘不能知","證悟同時斷我見、疑見、戒禁取見","以斷三縛結的智慧檢點諸方說法","阿含以本際、如、真實我隱說如來藏","初轉法輪重解脫，故只隱說真心"],"k":["明心","三縛結","四聖諦","如來藏","無餘涅槃本際"]},"1794-a06_128":{"s":"本集是綜論第三集。先引《無上依經》說否定真心、執一切法空會成斷見外道。接著解說緣覺與獨覺：十因緣「齊識而還」的識是入胎識，十二因緣的識是識陰六識，並比較緣覺與佛菩提、聲聞與緣覺的異同。最後依《楞伽經》說八識，分析第八、七、六識的體性，駁斥把意識修成真心以及六識論的主張。","p":["否定真心、執一切法空即斷見外道","十因緣之識為入胎識，十二因緣之識為六識","緣覺知有入胎識而未能實證","八識：第八識恆而不審、第七識恆審思量","意識審而不恆，不能修成真心"],"k":["緣覺菩提","十因緣","八識","入胎識","斷見與常見"]},"1797-a06_129":{"s":"本集是綜論第四集，講菩薩所證的四種涅槃。說明六住位四加行為何要先建立「似有真如」以免落入斷滅；七住證本來自性清淨涅槃；初地能取無餘涅槃而不取、留惑潤生，即證有餘涅槃；三地俱解脫、七地受引發如來無量妙智三昧；妙覺成佛證無住處涅槃。最後說二乘沒有法身德與般若德。","p":["四加行須先立「似有真如」，免落斷滅","七住明心證本來自性清淨涅槃","初地能證無餘涅槃而不取，留惑潤生","妙覺成佛證無住處涅槃","二乘缺法身德、般若德，不解教外別傳"],"k":["四種涅槃","本來自性清淨涅槃","四加行","留惑潤生","法身德"]},"1796-a06_130":{"s":"本集是系列最終集，總結三乘菩提的差異並匯歸一佛乘。說明二乘只斷煩惱現行，菩薩更斷習氣與無始無明；引《勝鬘經》說生死依如來藏而有。三乘共有解脫德，菩薩不共的是法身德與般若德。再引《法華經》化城喻與《勝鬘經》說三乘即一乘，以小學、中學、大學為喻，說大小乘不應互斥，如來藏是第一義諦。","p":["二乘斷煩惱現行；菩薩兼斷習氣與無明","《勝鬘經》：生死依如來藏而有","三乘共解脫德，菩薩不共法身德、般若德","法華化城喻：二乘是一佛乘的方便","大小乘都在成佛之道中，以如來藏為本"],"k":["一佛乘","如來藏","無始無明","法身德","化城喻"]},"2055-a08_001":{"s":"本集為「菩薩正行」系列概說，說明菩提與菩薩的意義：佛法本唯一佛乘，二乘為方便施設，並以《法華經》羊車、鹿車、大白牛車喻三乘。依《菩薩瓔珞本業經》區分名字菩薩、實義菩薩、賢位與聖位菩薩，概述五十二階位的修學內容，並提醒末法時應謹慎簡擇說法者。","p":["菩薩即覺有情，須發大心勇猛求佛道","三車喻說明聲聞、緣覺、菩薩三乘差別","依瓔珞經分假名、實義、賢位、聖位菩薩","概述十信至妙覺各階位修學內容","講者批評否定如來藏的教派，勸親近善友"],"k":["菩薩","三乘菩提","五十二階位","實義菩薩","如來藏","菩薩瓔珞本業經"]},"2057-a08_002":{"s":"本集引《占察善惡業報經》地藏菩薩開示，說明修大乘最初根本業是依止「一實境界」即眾生心體如來藏來修信解。舉六祖「五何期」、如來藏收藏業種為實現因果的主體，並講解《大乘起信論》一心二門及本覺、始覺、不覺；講者認為否定如來藏者不能真正信受因果。","p":["占察經：依止一實境界修信解入菩薩種性","一實境界即不生不滅、自性清淨的如來藏","如來藏收藏業種，是實現因果的主體","否定如來藏則因果不定，易退失道心","起信論一心二門與本覺、始覺、不覺"],"k":["如來藏","一實境界","占察善惡業報經","大乘起信論","十信位","因果"]},"2056-a08_003":{"s":"本集依《菩薩瓔珞本業經》「先正三業，習三寶教，信向因果」，說明人天善法是菩薩道基礎，佛陀接引眾生先說施論、戒論、生天之論。重點講施論：布施能遠離貧窮，如來藏收藏業種使果報不失；並依《優婆塞戒經》說報恩、功德、貧窮三種福田，強調孝養父母、敬事師長，避開鄙惡田。","p":["先正三業、習三寶教、信向因果","佛陀先說施論、戒論、生天之論再說四聖諦","布施為修行第一課，能遠離貧窮","三種福田：報恩田、功德田、貧窮田","孝養父母、敬事師長為首要福田"],"k":["施論","布施","福田","人天善法","孝養父母","如來藏"]},"1971-a08_004":{"s":"本集續講戒論與生天之論：五戒中殺盜淫妄為性戒、不飲酒為遮戒，持五戒可得人身；十善業增加意業不貪瞋癡，由止惡轉為積極行善，可生欲界天。再以難陀、鬱頭藍弗等故事說明「欲為不淨，上漏為患，出要為上」，引導由人天善法轉入出離三界的佛道。","p":["殺盜淫妄為性戒，不飲酒為遮戒","十善業增意業，由止惡轉為行善","難陀故事說明欲為不淨","鬱頭藍弗生非想天後仍將下墮","十善業道為三乘佛法的根本"],"k":["戒論","五戒","十善業","生天之論","出要為上","三界"]},"2058-a08_005":{"s":"本集說明「習三寶教」前須正確認識三寶：佛的法身、報身、應化身皆攝歸清淨法身如來藏，「法王」之號唯佛可用；依《大乘理趣六波羅蜜多經》說法寶、僧寶各有三層次，第一義皆指如來藏。講者並批評達賴喇嘛否定根本識、自稱法王及另立「上師寶」的說法，強調依法不依人。","p":["佛三身皆攝歸清淨法身如來藏","「法王」稱號唯佛世尊可用","法寶三層：如來藏、菩提分法、經律論","僧寶三層：第一義僧、聖僧、福田僧","講者批評否定如來藏、另立上師寶之說"],"k":["三寶","佛寶","法寶","僧寶","如來藏","依法不依人"]},"1955-a08_006":{"s":"本集說明具足人天善法後進入十信位，修集對三寶及佛法的信心。依《瓔珞經》列十信十心，十信滿足需一劫至萬劫，之後方能發菩提心成為菩薩。詳講前四心：信心、念心（六念、無相念佛）、精進心、慧心，並說明三歸依的意義與檢驗，以及歸依後受五戒稱第一義戒。","p":["十信位十心：信、念、精進、慧、定等","十信滿足需一劫乃至萬劫","三歸依的真偽檢驗與三自歸","歸依後受五戒稱為第一義戒","念心以六念說明，推介無相念佛"],"k":["十信位","三歸依","五戒","六念","信心","菩提心"]},"1949-a08_007":{"s":"本集續講十信位後六心：定心為對正理心得決定，另有不退心、迴向心、護心、戒心、願心；前五心即三十七道品中的五根五力。願心成就即發四宏誓願，成為初發心菩薩入初住位。並列舉發菩提心的種種因緣，說明菩薩性非眾生本有，須善業與善知識因緣方能發起。","p":["定心指對正理心得決定，不被邪見動搖","前五心即五根、五力","不退、迴向、護、戒、願心的內涵","願心具足發四宏誓願，進入初住位","菩薩性非本有，須善業因緣發起"],"k":["十信位","五根五力","四宏誓願","初發菩提心","菩薩性"]},"1936-a08_008":{"s":"本集比較三乘菩提：二乘斷我見我執證阿羅漢入無餘涅槃，佛菩提以明心證如來藏為入門、須三大阿僧祇劫。說明初果至四果的斷結內容、通教菩薩與別教的差別，強調初發堅固菩提心即勝二乘，並說下、中、上三品菩提心非定性。講者另批評假藏傳佛教以雙身法稱梵行。","p":["解脫道斷我見我執，佛道以明心為入門","初果至四果的斷結與證境","三果須發起初禪；講者批評雙身法非梵行","通教菩薩未證如來藏，不入別教七住","三品菩提心並非定性，可升可退"],"k":["三乘菩提","解脫道","四果","通教菩薩","菩提心","斷我見"]},"1954-a08_009":{"s":"本集續說三種菩提性無定性，以金礦喻說明菩薩性須熏習外緣才顯現，至十行滿心方具足。依《優婆塞戒經》說修大乘菩薩的條件：求大智慧、欲知一切法真實、大莊嚴、心堅固、多度眾生、不惜生命；並說退與不退、出家八重與在家六重戒，及在家發菩提心勝一切辟支佛。","p":["三種菩提無定性，隨外緣轉變","菩薩性至十行滿心方具足","修大乘菩薩的六個條件","勤修善法及三十二相業為不退","出家八重、在家六重；在家發心殊勝"],"k":["菩薩性","優婆塞戒經","不退轉","在家菩薩","菩薩戒"]},"2015-a08_010":{"s":"本集說明發起菩薩性是成佛關鍵，依佛菩提修證建立凡夫性、習種性、性種性、道種性、聖種性等種性次第。引《瑜伽師地論》《菩薩地持經》說無種性者終不能成佛，介紹十住、十行、十迴向各位；並以《大乘莊嚴經論》大悲、大信、大忍、大行四相及六度性相描述菩薩性特質。","p":["六種菩薩種性對應五十二階位","無菩薩種性者終不能成就佛道","十住習種性、十行性種性、十迴向道種性","菩薩性四相：大悲、大信、大忍、大行","六度及四攝為菩薩修行總綱"],"k":["菩薩性","菩薩種性","十住","十行","十迴向","六波羅蜜"]},"2004-a08_011":{"s":"本集解說菩提即覺悟，分聲聞、獨覺、佛菩提三種，比較其種性、所斷、時間與果證差別。依《大智度論》卷53說佛菩提有五種：發心、伏心、明心、出到、無上菩提，對應菩薩從初發心到成佛的過程，並說明因地心與果地覺必同為第八識如來藏。","p":["菩提即覺悟，分聲聞、獨覺、佛菩提","二乘斷煩惱障現行，佛菩提兼斷所知障","五種菩提：發心、伏心、明心、出到、無上","明心菩提：觀三世五陰虛妄而證第八識","因地心與果地覺同為如來藏"],"k":["菩提","三乘菩提","五種菩提","大智度論","如來藏","明心"]},"2005-a08_012":{"s":"本集續說因地心與果地覺必是同一心：前六識是緣生法、末那識入涅槃即滅，唯第八識不生不滅。引《大乘密嚴經》金與指環喻、《成唯識論》阿賴耶識為一切法依，並依《楞嚴經》「發覺初心二決定義」說明以生滅心為本修因不能成佛；講者並批評以觀想明點為如來藏之說。","p":["前六識與末那識皆非因地真心","密嚴經金與指環喻：賴耶與清淨藏同體","阿賴耶識→異熟識→無垢識，心體不變","楞嚴經：不可以生滅心為本修因","講者批評以觀想明點為如來藏"],"k":["因地心","阿賴耶識","如來藏","楞嚴經","大乘密嚴經","無垢識"]},"2009-a08_013":{"s":"本集說明發菩提心即發求證無上正覺、自利利他之心。依《大方便佛報恩經》說正法、像法、末法及法滅後四種發心情況，並述釋迦佛因地在火車地獄見同伴受苦而生悲心發菩提心的故事；再依《優婆塞戒經》說為增長壽命財富、令菩薩種性不斷而發心。","p":["發心須立四宏誓願，自利利他","報恩經四種發菩提心的情況","釋迦佛因地火車地獄發心故事","布施、持戒能增壽增財，即是菩提心","菩薩種性非人人本有，須心量廣大"],"k":["菩提心","發心","四宏誓願","大方便佛報恩經","菩薩種性"]},"2010-a08_014":{"s":"本集續說發菩提心的因緣：真菩薩種性須知二乘不具法身德、般若德，且不畏佛道長遠。說明人天善業與二乘解脫皆非作已不失的真實善業，引《金剛經》說明依離四相的如來藏行善才是真善法；並說為勝過人天二乘果報、不捨眾生、斷起煩惱與上煩惱而發心。","p":["二乘無法身德、般若德，解脫德不具足","人天善與二乘解脫皆非永不失的善業","依離四相的如來藏行善才是真善法","講者批評以性空唯名解釋般若","為斷起煩惱與上煩惱而發菩提心"],"k":["菩提心","如來藏","金剛經","善業","三德","煩惱障"]},"1956-a08_015":{"s":"本集說明發菩提心後首要親近真善知識。以善財童子五十三參、薩遮尼犍子為例，說明不可依身相或口才判斷，而應看是否依止如來藏並能教人實證；講者批評六識論者與雙身法為惡知識。並說發心後自我要求與待人的十件事，及智者見五濁等五事而發菩提心。","p":["發心後第一要事是親近善友","善財童子五十三參不看身相","善知識本質是依止如來藏、教人實證","不見人過、不輕慢、不嫉妒、視眾生如子","智者見五濁等五事而發菩提心"],"k":["善知識","菩提心","善財童子","五濁","如來藏"]},"1996-a08_016":{"s":"本集為因果系列首講，先指出大悲是發菩提心最殊勝的生因，再說明佛教主張有因有果的三世因果。列舉古印度外道四種因果主張及佛陀所破的宿作、自在天、無因三種邪見；以眾生種種差異證明有過去生，並質疑由神或上帝決定果報及贖罪券等觀念。","p":["大悲心是發菩提心最殊勝的生因","古印度外道四種因果主張","佛陀破宿作因、自在天、無因三種邪見","眾生差異證明有過去生","質疑神或上帝決定罪福果報"],"k":["因果","三世因果","外道","大悲心","業報"]},"1998-a08_017":{"s":"本集說明因果法則超越一切有情，連佛也不能改變。舉百丈禪師野狐公案「不落因果」與「不昧因果」，破斥把佛視為造物主的觀點，說十方諸佛平等；以釋迦佛三月食馬麥及《佛說興起行經》十事宿緣為例，並指出全知全能造物主觀的矛盾，最後預告宿命論問題。","p":["因果法則非任何單一有情能操控","野狐公案：不落因果與不昧因果","佛非造物主，十方諸佛平等","釋迦佛三月食馬麥的宿世因緣","十事宿緣：成佛仍受殘餘業報"],"k":["因果","野狐公案","十事宿緣","造物主","身口意"]},"1997-a08_018":{"s":"本集探究業種存於何處：破斥業種由虛空執持、以緣起性空為空性、虛空能量為生命本源等說法。分析色身、前六識、中陰身只有一期生滅，末那識若持種將揀擇善種，皆不能持種；結論是無覆無記的第八識阿賴耶識如來藏執持業種與無明種，為因果法則所依。","p":["虛空只是施設名稱，不能持業種","虛空能量說屬外道，能量由共業所感","色身、六識與中陰身只有一期生死","末那識若持種會揀擇，不能持種","無覆無記的阿賴耶識是因果所依"],"k":["阿賴耶識","如來藏","業種","因果","末那識","虛空"]},"2000-a08_019":{"s":"本集說明佛法講「因緣果報」而非宿命論：因須與緣和合才生果，善惡因緣的大小先後不同，果報千差萬別。引《優婆塞戒經》四種業及修身戒心慧可轉重為輕；再依《大般涅槃經》《因明入正理論疏》解說生因與了因的意義與先後關係，並以聽法斷我見為例。","p":["因果不離因緣，有別於宿命論","優婆塞戒經四種業，不定業可轉","修身戒心慧能轉重業為輕","生因如種生芽，了因如燈照物","了因是生因之果，二者有先後"],"k":["因緣果報","生因","了因","宿命論","優婆塞戒經","業"]},"1963-a08_020":{"s":"本集回應善生菩薩之問，依《優婆塞戒經》說大悲心是發菩提心的生因：自己觀察而發的悲心堅固，由他人勸說而發屬了因、易退。以無佛之世最初發心、釋迦佛火車地獄發心、忍辱仙人及常不輕菩薩為例，說以大悲為生因能疾得成佛，並依《華嚴經》列觀眾生起大悲的十種因緣。","p":["發菩提心有生因、了因或二者具足","優婆塞戒經：生因即是大悲","無佛之世最初發心必出於大悲","忍辱仙人、常不輕菩薩以悲修忍","華嚴經十種觀眾生起大悲"],"k":["大悲心","生因","菩提心","了因","常不輕菩薩","華嚴經"]},"2059-a08_021":{"s":"本集依《優婆塞戒經》〈悲品〉講菩薩生悲的因緣：見眾生諸根不具、生於邊地、處飢饉世與刀兵劫，以及值佛出世聞甘露法卻不能受持。說明諸根不具含扶塵根與勝義根，多為往昔謗法餘報；二種甘露即解脫道與佛菩提道，並指出離念靈知意識亦須滅盡方入涅槃。","p":["諸根不具分扶塵根與勝義根不具，多屬謗法餘報","邊地指無了義正法之處，非僅地理","飢饉世、刀兵劫中眾生互相殘害而生悲","聞二種甘露法不能受持，與佛法緣淺","意識離念靈知亦滅，無餘涅槃唯如來藏獨存"],"k":["悲心","優婆塞戒經","勝義根","甘露法門","無餘涅槃","如來藏"]},"2060-a08_022":{"s":"本集續講菩薩生悲因：見眾生信邪惡友不從善知識、多財不施、謀生皆苦、眷屬不相愛念而生悲。重點解說經文「非想非非想處定樂如地獄苦」：四禪八定之樂的層次，非非想天福盡後小惡業成熟而下墮，故佛憫鬱頭藍弗；勸修定者將福德迴向人間續修佛法。","p":["邪惡友常現慈善相，須依實質簡擇善知識","多財不施、謀生之苦、眷屬相害皆為生悲因","初禪至四空定之樂與捨樂次第","非非想天福盡，小惡業緣熟而墮三途","定福宜迴向人間修學，佛憫鬱頭藍弗"],"k":["悲心","非想非非想定","四禪八定","邪惡友","因果業報","優婆塞戒經"]},"1981-a08_023":{"s":"本集講「悲與大悲」的差別：未成佛時作觀名悲，成佛後名大悲，因觀有邊無邊、心動轉不動轉、救濟有限或大救濟、不共慧或與慧共行而分。並說六波羅蜜以悲心為生因、聞熏正理為了因，無悲是聲聞種性；最後說出家修悲不難，在家多惡因緣故難。","p":["非非想定境界眾生本具，修定在捨不在得","得道指成佛，成佛後之觀名為大悲","悲與大悲四種差別：邊際、動轉、救濟、慧行","六度以悲為生因，聞熏正理為了因","無悲屬聲聞種性；在家修悲多惡因緣"],"k":["大悲","六波羅蜜","生因與了因","菩薩種性","聲聞種性","優婆塞戒經"]},"1975-a08_024":{"s":"本集講在家菩薩應先修悲：不修悲不得優婆塞戒，各種菩薩戒皆以悲為根本。出家人依古天竺聲聞戒不捉金銀，難具財施，只能具足五波羅蜜；在家人能一切時一切施。修悲者能難施能施、難忍能忍、難作能作，進而具足六度；悲為一切善法根本，少許善業獲果如須彌山。","p":["無悲心不得菩薩戒戒體","出家受聲聞戒難具財施，故不具檀度","在家一切時一切施，易具六波羅蜜","難施能施、難忍能忍、難作能作為修悲目標","布施成則餘五度漸具，少善獲大果"],"k":["修悲","布施波羅蜜","優婆塞戒","六波羅蜜","在家菩薩","菩薩戒"]},"1945-a08_025":{"s":"本集進入〈解脫品〉，講修悲者得一切法體諸解脫分，其體為身口意，由方便而得。方便有耳聞、思惟二種：聞思斷我見，修所得慧斷我執；又有惠施、持戒、多聞三種，分別對治慳貪、見取見與瞋、無知。善生問三方便有無定數，佛答無定數，無量財施者未必得，一把麵施乞兒能得如見解脫分。","p":["解脫分以身口意為體，自殺非解脫","耳聞、思惟：如理作意令意根接受斷我見","惠施、持戒、多聞三方便及其對治","三方便無定數，佛法不可世俗化","如見解脫分不落斷滅；一日八戒亦能得"],"k":["解脫分","聞思修","斷我見","三方便","身口意","見取見"]},"1974-a08_026":{"s":"本集續講解脫分法：讀誦十二部經未必得，讀一四句偈亦能得，舉周利槃陀伽掃塵證阿羅漢為例，因眾生心不同。說明貪瞋癡對應欲界、色界、無色界，惠施斷貪、持戒斷瞋、多聞斷癡；但關鍵在一心觀察生死過咎與涅槃安樂。最後說得解脫分的三時：佛出世、緣覺出世、色究竟天說法。","p":["周利槃陀伽掃塵悟解脫，眾生心各不同","欲界重貪、色界重瞋、無色界之癡即我見","施斷貪、戒斷瞋、聞斷癡為前方便","須一心觀生死過咎、涅槃安樂方得解脫分","得解脫分三時：佛出世、緣覺出、色究竟天"],"k":["解脫分","貪瞋癡","生死過咎","涅槃","三界","我見"]},"2064-a08_027":{"s":"本集講解脫分法體為身口意：佛往昔初發心時聞淨居天說解脫法；欲界天放逸、色界天無三方便、無色界無身口，鬱單曰人生活安樂亦無三方便，皆不能得。強調修定不能得解脫，滅盡定亦由解脫慧取證。又說聲聞、緣覺、菩薩三人能得解脫分，遇善知識可轉，菩薩入地以上之解脫不可退轉失壞。","p":["欲界天放逸、色界無三方便、無色界無身口","解脫由智慧非由禪定，打坐不等於解脫","鬱單曰人不覺苦，無施戒聞故不得","遇善知識可轉聲聞為緣覺、緣覺為菩薩解脫","二乘解脫可退，菩薩入地後解脫不退"],"k":["解脫分","身口意","三乘菩提","禪定與解脫","鬱單曰","不退轉"]},"2002-a08_028":{"s":"本集回答善生所問：說法者如何分別有無解脫分。講者認為弘法者須能依諸方大師著作判斷其是否斷我見，教人保持清楚明白、念念分明即落意識境界。經文說至心聽法、聞三惡道苦生怖畏、堅持齋戒小罪不犯者得解脫分；又說得非非想定而無解脫分者是地獄人，阿鼻地獄中得解脫分者是涅槃人。","p":["弘法者須具簡擇有無解脫分之見地","落於意識境界即我見未斷，不得解脫分","畏三惡道苦、堅持齋戒小罪不犯得解脫分","持戒須配合慧學，免破法而自以為護法","非非想定外道如地獄人；佛憫鬱頭藍弗"],"k":["解脫分","斷我見","持戒","意識境界","鬱頭藍弗","提婆達多"]},"2065-a08_029":{"s":"本集講經文「舍利弗等六萬劫求菩提道而退，以未得解脫分」，引《菩薩瓔珞本業經》說明明心後退失之因：未觀察真心與涅槃關係致我見未斷淨、不受善知識攝受、慢心私心、悟得太易、文字障誤解「真如是識之實性」。退者曾觸如來藏，仍勝緣覺；並講解脫分下中上三品與四種涅槃。","p":["舍利弗等明心後無善知識攝受而退失菩提","未將如來藏與無餘涅槃關聯觀察，退回意識","悟得太易、文字障另覓真如皆為退因","退者曾證如來藏，慧根仍勝緣覺","解脫分三品：聲聞、緣覺、諸佛；四種涅槃"],"k":["退轉","明心","解脫分","如來藏","善知識","四種涅槃"]},"2063-a08_030":{"s":"本集講經文：無量世如聞而行求優婆塞戒、比丘戒亦不得戒，因未得解脫分，只名修戒不名持戒；說明戒體實質須斷我見，菩薩戒體須明心轉依。又說得解脫分的菩薩不造業求生三界諸天，將施、戒、修定等生天業迴向人間利益眾生；聲聞得解脫分不過三身，菩薩經無量身不退，勝過二乘。","p":["未得解脫分，受戒只名修戒不名持戒","戒體實質：聲聞須斷我見，菩薩須明心轉依","諸天皆難利益眾生，故願生人間","施、戒、修定為生天業，迴向人間行道","聲聞不過三身得解脫，菩薩無量身不退"],"k":["戒體","解脫分","菩薩戒","迴向","生天業","不退轉"]},"2061-a08_031":{"s":"本集由正益老師講菩薩的解脫分異於二乘與凡夫：凡夫於有為法求究竟，二乘以滅盡三界求涅槃而未親證涅槃性。以一命償一命為例推論，虛空介質或主宰者皆無法記錄與決定業報；阿羅漢入滅非斷滅，涅槃有本住真常性。又說二乘解脫實由菩薩示現聲聞方便導引，並舉貧女供燈說明少施亦成無量功德。","p":["有為法無常，三界中無究竟安穩處","二乘以滅盡身心求涅槃，未親證涅槃性","業報因果非虛空或主宰者所能記錄決定","阿羅漢入滅非斷滅，本有常住涅槃性","菩薩示現聲聞導引二乘；貧女一燈"],"k":["解脫分","涅槃","因果業報","如來藏","二乘","布施"]},"2006-a08_032":{"s":"本集講菩提的四個種子：一、不貪著自他財物，以布施對治慳吝，並舉整理家中閒置物品結緣為例；二、不惜身命，正法久住重於自身性命，色身只是道器；三、忍受眾生打罵侮辱；四、憐愍眾生，以方便與佛法結緣。講者並批評末法時期世間多所謂大師說法不實。","p":["不貪財物，以布施及整理積物對治慳吝","財施攝眾，戒行德行亦是布施","不惜身命，正法久住重於生命","色身是道器；重病菩薩仍於醫院說法","忍受侮辱、憐愍眾生，方便勸人念佛"],"k":["菩提種子","布施","不惜身命","忍辱","悲愍眾生","正法久住"]},"1962-a08_033":{"s":"本集講增長菩提種子之法：不應輕視自己（舉鈍根老比丘供佛得授記、淨土可安住）；自身受苦心不厭悔，與人衝突時反省心行並練習；勤行精進不休不息；救濟眾生無量苦惱；常讚歎三寶功德。並引寶海梵志攝受五逆十惡之願，及《法華經》《地藏經》少分修行功德無量之說。","p":["勿自輕：鈍根老比丘供佛蒙授記","寶海梵志願攝受五逆十惡眾生","受苦不悔，遇衝突時檢討心行並練習","勤行精進，一合掌、一偈皆有功德","以財、法、無畏施救苦，常讚歎三寶"],"k":["菩提心","精進","授記","悲華經","三寶","布施"]},"1999-a08_034":{"s":"本集講如何增長熾然菩提種子，從波羅蜜法切入：到彼岸是在生死中找到不生不死者，生死海與彼岸皆如來藏所生如幻。說明因果須有能判定業報之識，並辨口業、意業；行六度應依無人我眾生壽者相，眾生皆有如來藏、功德本具。舉《悲華經》肉山布施與供佛細線成善攝受如來為例，強調以成就佛果為不放逸。","p":["波羅蜜：在生死中證不生不死之實","六度、十度乃至無量波羅蜜皆不離般若","業報因果唯如來藏能記錄，口意業之辨","依無我相行布施，施者受者皆如來藏","細線供佛成佛；以佛果為究竟名不放逸"],"k":["六波羅蜜","如來藏","布施","不放逸","因果業報","斷我見"]},"1994-a08_035":{"s":"本集講求菩提的四事：親近善友（舉禪宗行腳參方、大慧宗杲與雪峰義存、善財童子參訪）；心堅難壞（達摩面壁九年、六祖隱於獵人隊十五年）；難行能行（龍女成佛、讀導師書的小菩薩）；憐愍眾生。講者並指出講如來藏的道場甚少，以磨磚作鏡公案說明禪不在坐。","p":["親近善友：禪宗參方與善財童子五十三參","禪不在坐，舉磨磚作鏡公案","心堅難壞：達摩面壁、六祖隱獵人隊","難行能行：龍女成佛、讀書學法的小菩薩","憐愍眾生，眾生皆有如來法性"],"k":["善知識","禪宗","菩提心","難行能行","悲愍眾生","如來藏"]},"1983-a08_036":{"s":"本集講《優婆塞戒經》「更有四事來求菩提」：見他得利心生歡喜、常樂稱讚他人功德、常樂修集六念處、勤說生死過咎。說明不隨喜、嫉妒會使菩薩難以安住而易退轉，並引《佛為首迦長者說業報差別經》說嫉妒、作留難、不隨喜他人布施者，未來資生與威勢減損。勸菩薩隨順因果、調伏自他心念。","p":["見他得利應隨喜，不生輕蔑嫉妒","常樂當眾稱讚他人功德","修念佛法僧戒施天六念處","勤說生死過咎，伺機說人天善法","嫉妒、作留難致資生勢力減損"],"k":["隨喜","六念處","嫉妒","業報差別","菩提心","優婆塞戒經"]},"2003-a08_037":{"s":"本集講經文「初發無上菩提心即名無上福田」及「修佛道多退轉，如菴羅花與魚子」。舉釋迦因地於地獄為他人求饒而發心，引《華嚴經》說菩提心功德等同一切佛法、三世如來由此出生。又引《大方廣如來不思議境界經》說會中菩薩、聲聞、天龍皆諸佛菩薩示現，並說娑婆名堪忍是因有忍辱行菩薩。","p":["初發菩提心即為無上福田，勝一切世間","修佛道者多退，如魚子少成","釋迦因地於地獄中為他人求饒而發心","華嚴：三世如來皆從菩提心出生","會中聲聞天龍皆菩薩示現；娑婆名堪忍"],"k":["菩提心","福田","華嚴經","退轉","娑婆世界","忍辱"]},"1995-a08_038":{"s":"本集講經文「了知法性名為佛」：法性有總相與別相，聲聞、緣覺只知總相，如來總別相皆覺了。總相指無常苦空無我，別相是出生萬法的真如，二乘法依此而立。引《楞伽經》本住法與古城喻，談趙州喝茶、外道問佛良久等公案，說真如無見聞覺知；並說阿含聲聞道非成佛之道，講者批評稱如來藏為自性見者。","p":["聲聞緣覺知總相，如來總別相皆了","假必依實，別相即法界根本真如","楞伽本住法：法界常住，不說一字","禪宗公案不可作意境解，真如無見聞覺知","二乘依別相成立；阿羅漢終將迴入"],"k":["法性","總相別相","真如","楞伽經","禪宗公案","如來藏"]},"1973-a08_039":{"s":"本集講經文：二乘斷煩惱現行而不斷習氣，如來拔一切煩惱習氣根源；疑有煩惱疑與無記疑，二乘不斷無記疑，如來二疑俱斷。說明菩薩須在境界中現起習氣並轉依真如而斷，變易生死至佛地方斷。引《大寶積經》處非處智力，駁「本來是佛而後下墮」之說；引《勝鬘經》說四住地與無始無明住地，無明住地唯如來菩提智能斷。","p":["二乘斷煩惱現行，不斷習氣與無記疑","菩薩於境界中現起習氣，轉依真如而斷","處非處智力：如來習氣永斷","本來是佛後下墮之說不能成立","勝鬘：無明住地力最大，唯佛智能斷"],"k":["習氣種子","異熟生死","無始無明住地","勝鬘經","處非處智力","煩惱障"]},"2001-a08_040":{"s":"本集講佛的究竟行：聲聞厭於多聞、緣覺厭於思惟，佛於二者無疲厭；二乘雖有淨智而行不清淨，如來智行俱淨，一念破智障與解脫障。引《大寶積經》說如來法身為常樂我淨波羅蜜，作此見者名真佛子；講者批評以「貪欲是涅槃」主張大貪瞋癡可成佛者為邪見，並引《中阿含》《雜阿含》說名色之因即常住之識。","p":["佛於多聞、思惟皆無疲厭，究竟精進","二乘行不淨，仍含變易種子","如來一念破所知障與解脫障","如來法身常樂我淨，作此見名真佛子","貪欲是涅槃須依親證，識為名色之本"],"k":["究竟行","常樂我淨","所知障","第八識","二乘","邪見"]},"1972-a08_041":{"s":"本集講解經文「如來世尊能於一念破壞二障」，說明佛破智障（所知障）與解脫障，與只破解脫障的聲聞、緣覺不同；菩薩證第八識如來藏時一念同時斷我見。講者並以是否斷我見來檢驗盜得表相密意者，提及《阿含經》中已有禪宗公案，最後開始講「如來具足智因智果」。","p":["佛一念破智障與解脫障，二乘只破解脫障","菩薩證如來藏時一念相應，同時斷我見","只得表相密意而未斷我見者，非真明心","《阿含經》已有禪宗公案及破野狐之說","世間與出世間智慧之因皆是第八識"],"k":["一念破二障","所知障","如來藏","斷我見","明心","禪宗公案"]},"1951-a08_042":{"s":"本集續講「如來具足智因智果」，說明宇宙與有情的根源在第八識如來藏，阿羅漢入無餘涅槃後仍有如來藏；智果即修學圓滿一切種智。接著解釋「出言無二無謬，亦無虛妄；智慧無礙，樂說亦爾」，講者批評部分佛學研究者對如來藏有無模稜兩可，並開始講因智與時智。","p":["器世間與有情的根本因是第八識如來藏","無餘涅槃後非斷滅，仍有如來藏","智果即具足一切種智，需三大阿僧祇劫","出言無二：對如來藏有無絕不模稜兩可","時智：依根機說法，即為人與對治悉檀"],"k":["智因智果","如來藏","一切種智","出言無二","無餘涅槃","四悉檀"]},"1950-a08_043":{"s":"本集講解如來具足相智，以及「無有覆藏，不須守護，無能說過」，說明佛不隱藏往昔過失，且習氣種子已斷盡；接著講佛悉知眾生起結、滅結因緣，不被世間八法所染污；最後講佛的大憐愍：捨天界福樂而在人間成佛，菩薩也學習佛乘願再來。","p":["相智：唯佛能具足了知一切法的法相","佛習氣種子斷盡，故不須守護身口意","佛知眾生貪重或瞋重，教以相應滅結法","佛八風吹不動，不受世間八法染污","大憐愍：佛在人間成佛，菩薩乘願再來"],"k":["相智","習氣種子","起結滅結","世間八法","大憐愍","乘願再來"]},"1952-a08_044":{"s":"本集續講如來大憐愍、救拔苦惱，說明菩薩能背捨禪定的愛味，依願力而非業力回到人間。接著講「身心二力悉皆滿足」：以《大般涅槃經》五百力士舉石的典故說明佛身力超越一切；佛的心力無邊，能真正緣於一切眾生。最後開始解說「無上師」等佛號。","p":["菩薩依願力乘願再來，外道依業生禪天","五百力士舉石典故顯示佛身力圓滿","經說實為慈善根力所現，成為禪門公案","佛心力無邊，能真正繫念一切眾生","無上師唯佛獨稱，自稱者為大妄語"],"k":["身心二力","大憐愍","乘願再來","大般涅槃經","無上師","佛十號"]},"1953-a08_045":{"s":"本集逐一解釋佛的種種名號：無上師、大丈夫、人中香象、師子、龍王、調御示導、大船師、大醫王、淨蓮花、無師獨覺、大施主、大沙門等，說明二乘雖有菩提卻沒有這些功德。最後講「出家菩薩分別三種菩提是不為難」，主張此處的出家應指實證大乘見道的菩薩。","p":["佛第八識為無垢識，故稱無上師","大丈夫、香象、龍王等顯佛尊貴與威德","佛無師獨覺而不捨眾生，異於辟支佛","大施主兼行財施、法施、無畏施","能分別三乘菩提者應是大乘見道菩薩"],"k":["佛十號","無上師","三乘菩提","出家菩薩","無垢識","辟支佛"]},"2016-a08_046":{"s":"本集依經文「出家菩薩分別三種菩提是不為難」，說明真出家菩薩應以能否分別三乘菩提來判斷，而非剃髮外相。講者批評過去佛教界以十二因緣觀為成佛，並介紹平實導師《阿含正義》所提的十因緣觀與入胎識；接著說明大乘僧團四眾平等，引《長阿含經》「不以除鬚髮害他為沙門」為證。","p":["以能分別三乘菩提來定義出家菩薩","若成佛只是觀十二因緣，三乘便無差別","十因緣觀：齊識而返，識即入胎識","如來藏永離三界之家，才是真正出家","大乘四眾平等，只依實證與德行分高下"],"k":["三乘菩提","出家菩薩","十因緣觀","四眾平等","如來藏","入胎識"]},"2052-a08_047":{"s":"本集先說明「害他」是讓眾生墮入斷見或常見，再論菩薩戒含攝出家戒：聲聞戒盡形壽受持，菩薩戒生生世世不捨，佛所制的比丘戒等都從菩薩戒流出。講者說明正覺崇隆出家僧寶，但僧眾應先尊崇佛寶與法寶，並批評另加歸依上師的四歸依。最後開始講修三十二相業與菩薩身力。","p":["三壇大戒最終依止菩薩戒","聲聞戒盡形壽，菩薩戒生生世世不捨","比丘戒等從佛的菩薩戒中流出","崇隆僧寶，但僧應尊崇佛寶法寶","菩薩身力初修三十二相業時成就，須滿十信"],"k":["菩薩戒","聲聞戒","四眾平等","三寶","三十二相業","十信位"]},"1943-a08_048":{"s":"本集講解修三十二相業要兼得的定：菩提定，即對三乘菩提依如來藏而心得決定；有定，即四禪八定等三界有的定。接著講知宿命定與生正法因定：前者以平實導師的如夢觀為例，說明菩薩知宿命不受八萬大劫限制；後者說明在外門廣修福德後，漸能分辨法義辨正，並決心求證大乘菩提。","p":["菩提定：信受三乘菩提依如來藏而立","無菩提定則所修福德可能因謗法而失","有定：四禪八定，通於世間與外道","知宿命定以如夢觀為例，無時劫限制","生正法因定：外門修福後決心求證菩提"],"k":["三十二相業","菩提定","有定","知宿命定","生正法因定","如來藏"]},"1942-a08_049":{"s":"本集說明生正法因定，即相信三乘正法以如來藏為因；並解說「多聞無厭」是圍繞如來藏熏習聽聞，以此貫串一切法。接著講每一相都要有百福莊嚴，即修心五十與具心五十，引論文「百思」與農夫耕種的比喻；五十思是十善業道各起五思，並以手足軟相、摩洗父母為例，講解離殺五思。","p":["多聞即圍繞如來藏熏習，貫串一切法","每一相以百福莊嚴，故勝於轉輪聖王相","修心五十、具心五十，喻農夫整地施肥","十善業道各起五思，合為五十思","以手足軟相為例說明離殺等五思"],"k":["三十二相業","百福莊嚴","十善業道","多聞無厭","迴向","如來藏"]},"1944-a08_050":{"s":"本集續講五十思，說明以迴向思把有漏的人天善業轉為無漏解脫與佛果之因，並講具心五十的檢討改進。接著解釋功德層次由毛孔、隨形好、相到白毫相、無見頂相：白毫相來自宣說正法實法不虛，無見頂相喻如來藏無頂。最後說明三十二相是大悲的果報，修滿即滿三大阿僧祇劫，修習次第不一定。","p":["迴向思將人天有漏善轉為無漏之因","功德層層遞增至白毫相、無見頂相","白毫相因宣說如來藏正法實法不虛","無見頂相喻如來藏，為諸相根本","三十二相是大悲果報，修滿即三大阿僧祇劫"],"k":["三十二相","白毫相","無見頂相","百福莊嚴","迴向","三大阿僧祇劫"]},"2038-a08_051":{"s":"本集由正文老師接講，依平實導師《優婆塞戒經講記》說明〈發願品〉：三十二相業唯智者能作，智者是善發無上大願（四宏誓願）的人，而不求世俗大願或轉輪聖王。並講菩薩所作善業與眾生共享，親近諸佛、聲聞、緣覺、善知識並供養請法；也講菩薩應發的願：寧受苦不退菩提、被辱更增慈心、不受女身等身，以及有自在力為他給使。","p":["三十二相業唯智者能作：自用節儉、布施大方","智者善發無上大願，即四宏誓願","親近佛、二乘、善知識，供養諮問受持","願寧受大苦不退菩提，被辱更增慈心","願不受女身、無根、二根、奴婢身"],"k":["發願","四宏誓願","優婆塞戒經","三十二相業","善知識","智者"]},"2039-a08_052":{"s":"本集續講〈發願品〉中菩薩應發的願：諸根具足、遠離惡友、不生在無正法的邊地、常生豪姓並財寶自在、得好念心與自在之心。並說明心得勇健、心不放逸才是真苦行，為利眾生不惜身命也不為身命造惡業；利他不求回報，受持十二部經並轉教他人，壞眾生惡見，見飢施身；也要怨親平等，修六念、無我想與十二因緣。","p":["遠離惡友，免被反覆影響而退轉","不生惡國邊地，有正法處才是中國","心得勇健，心不放逸才是真苦行","為利眾生不惜身命，不為身命造惡業","怨親平等，常修六念、無我想、十二因緣"],"k":["發願","心不放逸","遠離惡友","不惜身命","六念","十二因緣"]},"2017-a08_053":{"s":"本集講完發願後，進入「菩薩具足哪些條件得名為法財長者」。經文以多組三事說明：不樂外道典籍、不貪生死樂、樂供三寶；為人受苦不悔、具無上智慧、不憍慢；受地獄苦如三禪樂、見他得利不妒、善業不為生死；見他受苦如己、善事為眾生、方便令離苦；觀生死樂如毒蛇、樂處生死利生、觀無生法忍功德；以及捨身、捨命、捨財。","p":["除菩提不求餘果，為利眾生才求世報","外道指心外求法；以平實導師寫書為不貪生死之例","為人受苦不悔、具無上智慧、不生憍慢","觀生死樂如毒蛇，卻樂處生死利益眾生","為眾生捨身、捨命、捨財"],"k":["法財長者","優婆塞戒經","無生法忍","留惑潤生","布施","外道"]},"2019-a08_054":{"s":"本集續講法財長者的條件：捨身、捨命、捨財都為眾生；多聞無厭、能忍諸惡、教他修忍，並以寫書詳細辨正、救護誹謗阿賴耶識者為例；自省己過、善覆他罪、樂修慈心，但強調法義上不可和稀泥；至心持戒、四攝攝取眾生、口言柔濡；以及大法施與大財施，以貧女點燈說明至誠心的布施。","p":["捨身、捨命、捨財都為眾生，非求來世利益","能忍諸惡：詳細說明錯處以救護謗法者","事相上善覆他罪，法義上不可和稀泥","至心持戒、四攝攝眾、言語柔軟","大法施需親證佛菩提；貧女點燈喻大財施"],"k":["法財長者","多聞無厭","忍辱","四攝法","法布施","阿賴耶識"]},"2018-a08_055":{"s":"本集續講法財長者的條件：以二施勸眾生；常以大乘教化、悟後轉進增上（明心七住、見性十住、進修別相智與種智）、不輕眾生；雖具煩惱能堪忍、留惑潤生而能壞他結；見他得利歡喜、不獨受安樂、不滿足於二乘；聞苦行不怖、有求不言無、不念我勝；最後講觀因觀果、能斷能得因果，以平實導師指名道姓辨正法義前的考量為例。","p":["常以大乘教化，講者批評只講二乘法者","悟後須轉進增上，明心只是七住位","不輕眾生，新學者也可能是久修菩薩","見他得法歡喜如己，不於二乘生足想","善觀因果，辨正法義前先考慮後果"],"k":["法財長者","大乘","留惑潤生","觀因果","明心見性","法義辨正"]},"2020-a08_056":{"s":"本集先總結法財長者的觀因果，說明指名道姓辨正法義是學窺基大師的做法，並講十地法王與寫書校對的謹慎，及在家菩薩立願較難。接著進入〈名義菩薩品〉的假名菩薩：樂受外術典籍（講者以藏密為例批評）、為身命殺生樂於生死、不信三寶、生疑網心、不能忍辱、自輕不能得菩提、怖畏煩惱、不勤修壞結方便、親近惡友而懈怠亂心。","p":["指名道姓辨正法義需先觀現世與來世因果","在家菩薩多惡因緣，立法財長者願較難","樂受五術等外術並以之教人，為假名菩薩","殺生樂生死、疑三寶、不忍辱、自輕","怖煩惱不肯潤生、不除性障、親近惡友"],"k":["假名菩薩","觀因果","法財長者","外道","性障","藏密"]},"1938-a08_057":{"s":"本集續講假名菩薩：親近惡友導致懈怠亂心、樂處無明不信六度、不樂修福不觀生死、樂於傳播他人惡語，共十二種。接著講另外十種：聽聞成佛需無量劫苦行便生悔、無慚無愧、不生憐愍、樂奉外道殺羊祀天（講者以藏密為例批評）、信心不堅固、倚色命財生憍慢、所作顛倒，以及為生死樂布施、為生天持戒、為長壽修禪定。","p":["親近謗法惡友致懈怠亂心","聞成佛須無量劫苦行便生悔，心不真實","無慚無愧、不憐愍、樂奉外道殺生祭祀","倚色命財生憍慢，所作顛倒不能利益","為生死樂布施、為生天持戒、為長壽修定"],"k":["假名菩薩","六度","慚愧","憐愍","外道","禪定"]},"1939-a08_058":{"s":"本集開始說明實義菩薩的條件：能聽受般若等深妙法義、樂近善友、樂供養師長父母善友、樂聽十二部經並受持讀誦書寫思惟、為法不惜身命妻子財物且心堅固、憐愍眾生而言語柔軟真實、不自輕、舒手惠施（但不布施破法道場）、磨利智慧刀並讀外典以破邪見、善知方便調伏眾生而不怖，以及常教眾生「菩提易得」。","p":["能聽深義：般若總相智、別相智、種智","樂聽十二部經，受持讀誦書寫並思惟","為法不惜身命財物，其心堅固","舒手惠施，但不布施破法的人或道場","磨利智慧刀，習外典以破邪見"],"k":["實義菩薩","般若","善知識","布施","十二部經","菩提易得"]},"1941-a08_059":{"s":"本集續講實義菩薩的條件：教眾生菩提易得、輕賤煩惱（但保留求法的善法欲）、心不放逸常修忍辱、為四種涅槃持戒精進、為眾生奔走受苦不悔、見人退失菩提心生憐愍、救眾生苦惱、觀生死過罪（講者並批評一神教原罪說）、具無上六波羅蜜、信心堅固修慈悲而不求果報、怨親無二、知無常而不惜身命，以及四攝攝眾、隨眾生語。","p":["常說菩提易得，使眾生不怖而精進","輕賤煩惱，但求悟的善法欲須保留","心不放逸才是真苦行，常修忍辱","為四種涅槃持戒精進，含自性清淨涅槃","以如來藏為中心修無上六波羅蜜"],"k":["實義菩薩","四種涅槃","六波羅蜜","忍辱","菩提易得","四攝法"]},"1940-a08_060":{"s":"本集講完實義菩薩的三十個條件：以四攝法與世諦隨順眾生；為眾生受苦時心不動如須彌山；記住眾生的少分善；於三寶證信不疑並樂於供養；財少時先救貧苦；樂讚人善並為人開示涅槃；伎藝不藏私、見學生勝己則歡喜；不念自利、常念利他。最後說明在家菩薩惡因緣多，當實義菩薩較難，並讚歎依教奉行的在家菩薩。","p":["懂世諦，隨順眾生語言帶入佛法","為眾生受苦，心不動如須彌山","財少時先救貧苦，後施福田","讚人善並開導涅槃，伎藝不留一手","不念自利常念利他；在家當實義菩薩較難"],"k":["實義菩薩","四攝法","證信","利他","布施","在家菩薩"]},"1964-a08_061":{"s":"本集開啟「如何使菩薩道心更堅固不退」子題，先說明發菩提心的尊貴難得：沙彌發心又退心、度一人發菩提心勝度三千大千世界人成阿羅漢、世尊前身在火車地獄因發心而脫苦。接著指出長劫修行與末法邪師使人易退心，並以釋迦菩薩修外道苦行仍不退、國王割身燃千燈求法的本生，說明菩薩為法不惜身命。","p":["菩薩發無上大願，二乘無學不敢發","沙彌發心又退心，阿羅漢前後態度不同","世尊前身在火車地獄發菩提心而脫苦","苦行不能成佛，但釋迦菩薩求法之心不退","國王割身燃千燈供養求法，迴向佛道"],"k":["發菩提心","道心不退","真實義菩薩","本生故事","為法捨身","苦行"]},"1966-a08_062":{"s":"本集講真實義菩薩四事的前兩事：毀壞眾生煩惱、令眾生得安樂。舉佛以偈化度辱罵的婆羅門突邏闍懺悔為例，講者並舉平實導師面對毀謗與訴訟仍盼對方懺悔之事；再以《賢愚經》國王化大魚以身肉濟饑荒、《菩薩本生鬘論》尸毘王割肉救鴿，說明菩薩為眾生安樂而捨身。","p":["世尊為四事修苦行，知自己是真實義菩薩","佛以偈化度辱罵的婆羅門突邏闍懺悔","講者舉平實導師遭毀謗訴訟仍盼對方懺悔","國王化大魚，以身肉濟饑荒十二年","尸毘王割肉救鴿，迴向佛道而不悔"],"k":["真實義菩薩","毀壞煩惱","利樂眾生","本生故事","捨身布施","如來藏色"]},"1965-a08_063":{"s":"本集講真實義菩薩四事的後兩事：滅除對色身的貪著、回報父母恩。說明色身四特點：本無今有、剎那生滅；依四大和合而成（引《大寶積經》歌羅邏身）；有五種不淨；但為修道之器不應毀壞。再以《大方便佛報恩經》須闍提太子割肉奉親的本生及《雜寶藏經》說明父母恩重難報，孝養可速成佛道。","p":["色身本無今有、剎那生滅，非常住法","歌羅邏身依地水火風四大互相依持而成","色身有種子、居處、食物等五種不淨","色身是修道之器，不應隨便毀壞","須闍提割肉奉親，父母恩重難以報盡"],"k":["色身無常","四大","五種不淨","孝養父母","真實義菩薩","本生故事"]},"1969-a08_064":{"s":"本集說明惡友與煩惱業都是菩薩的道莊嚴伴，以提婆達多為例：共命鳥本生，及《法華經》佛說其為善知識並授記。再說菩薩示現受報非由業報，以世尊與五百比丘三月食馬麥為例，說明度五百馬身菩薩、宿世謗比丘的餘殃，並引《大寶積經》說此為方便示現、佛得上味相。講者藉此勸人慎勿毀謗正法。","p":["惡友與煩惱業皆是菩薩的道莊嚴伴","佛說提婆達多是善知識並為其授記","世尊食馬麥三月，為度五百馬身菩薩","宿世謗比丘應食馬麥，示現餘殃警人慎口","經說食馬麥是方便示現，佛得上味相"],"k":["逆增上緣","提婆達多","馬麥","方便示現","毀謗業報","煩惱"]},"1967-a08_065":{"s":"本集先以《菩薩本行經》跋彌王化魚、以身肉治國人瘡病，說明菩薩受生畜生道是為度眾而非業報。接著說六度「非得非不得」：從真心實際理地無所得，事相上仍有果德。引般若經、《心經》、《金剛經》，以空性（第八識實相心）與空相兩個重點簡擇經義，講者並以此批評常見、斷見與邪淫外道之說。","p":["跋彌王化魚治民瘡病，為度眾生受畜生身","六度從理上非得，事相上非不得","第八識實相心離見聞覺知、離六塵","以空性與空相簡擇《心經》《金剛經》","以此標準辨別常見、斷見與邪淫外道"],"k":["空性與空相","第八識","般若波羅蜜","心經","金剛經","理事圓融"]},"1968-a08_066":{"s":"本集說菩薩平等利益眾生不求回報，受人點滴之恩則湧泉以報；講者舉平實導師四例說明菩薩典範，如面對毀謗不計較、接受毀謗者懺悔。接著說菩薩以柔軟語與四攝法化導眾生而不厭倦，再述菩薩四種與六種不可思議，含臨終為謗者說法（隨重、隨習、隨念），最後說在家菩薩行菩薩行比出家更難。","p":["菩薩利他不求報，受恩必思回報","講者舉平實導師四例說明菩薩典範","菩薩以柔軟語與四攝法攝受眾生","四種不可思議，含臨終為謗者說法","六種不可思議：處煩惱不捨、施而不悔"],"k":["菩薩不可思議","四攝法","布施","報恩","在家菩薩","臨終三隨"]},"2024-a08_067":{"s":"本集開始「菩薩如何自利利他」子題，依善生菩薩之問說明菩提與菩提道：菩提是覺悟一切有情真心如來藏第八識，菩提道是成佛的法道，涵蓋五十二階位。詳述十信、十住六度（七住明心、十住眼見佛性成如幻觀）、十行陽焰觀、十迴向如夢觀、諸地現觀與意生身、等覺百劫修福、妙覺成佛，並介紹平實導師所編發願文。","p":["菩提是覺悟一切有情真心如來藏","菩提道是成佛法道，涵蓋五十二階位","十住修六度，七住明心、十住見佛性","十行陽焰觀、十迴向如夢觀滿第一大劫","諸地各有現觀，等覺修福，妙覺成佛"],"k":["菩提道","五十二階位","如來藏","明心見性","六度","十地"]},"2026-a08_068":{"s":"本集說明佛菩提為何勝於二乘菩提：聲聞觀四聖諦、緣覺與獨覺觀因緣法，所觀都是蘊處界；菩薩所觀為真如。三乘共有解脫德，菩薩另有法身德、般若德，並證本來自性清淨涅槃與無住處涅槃。再以海與海浪喻解釋菩提與菩提道非一非異，並用來詮釋《心經》色空關係與《金剛經》「所謂…即非…是名」。","p":["聲聞、緣覺、獨覺皆觀蘊處界虛妄","菩薩觀真如，具解脫、法身、般若三德","菩薩另證自性清淨涅槃與無住處涅槃","菩提與菩提道非一非異，如海與海浪","《心經》《金剛經》皆說空相與空性心"],"k":["佛菩提","二乘菩提","四種涅槃","非一非異","心經","金剛經"]},"2025-a08_069":{"s":"本集講經中「學與學果」：以三大阿僧祇劫的布施能否有智慧、遍一切時、遍一切眾生來區分。說明信、位、行、念四種不退，強調七住明心須善知識攝受才得位不退，引《菩薩瓔珞本業經》舍利弗等退轉例。並說學與學果有寬嚴兩種定義，再講布施與波羅蜜的四句分別，以及二乘的有學與無學。","p":["第一、二大劫布施名學，第三大劫名學果","信不退、位不退、行不退、念不退","明心須善知識攝受，方得七住位不退","學與學果有寬鬆與嚴格兩種定義","布施與波羅蜜有四句分別"],"k":["學與學果","四不退","布施波羅蜜","善知識","三大阿僧祇劫","八地"]},"2027-a08_070":{"s":"本集續講十種學與學果：盡智與無生智（舉周利槃特伽為例）、調伏與解脫、修集十力、自利利他、世間與出世間法、不惜身財命、人天善業與無漏業（引《增壹阿含經》）、財施與法施、破慳嫉、受持五根。共通原則是自利名學、自利利他名學果。最後說菩薩觀機逗教，並分下品、中品、上品菩薩。","p":["十種學與學果，含盡智與無生智之別","調伏如石壓草，解脫則已斷除煩惱","人天善業是有漏法，應求無漏業","能自利名學，能自利利他名學果","下品唯自利、中品唯利他、上品兼利"],"k":["學與學果","盡智與無生智","自利利他","五根五力","法布施","三品菩薩"]},"2030-a08_071":{"s":"本集改由正圜老師主講，依平實導師《優婆塞戒經講記》第三輯，解說「利益有二、樂有二種、福德亦爾」經文。說明只求現世回報不是真實利益，能利後世方能兼利；世間樂無常，出世間樂為究竟樂，以維摩詰大士說如來藏如如不動才是真宴坐為例；並說世間福德與出世間福德的差別，護持正法可兼得二福。","p":["只求現世回報非實，能利後世方能兼利","世間樂無常，出世間樂為究竟樂","維摩詰：如來藏如如不動才是真宴坐","世間福德換不到出世間的證悟果報","護持、助印正法兼具兩種福德"],"k":["自利利他","優婆塞戒經","出世間樂","福德","維摩詰","宴坐"]},"2032-a08_072":{"s":"本集解說《優婆塞戒經》中以一法至五法自利利他的經文：不放逸（引《成唯識論》，強調心不放逸才是真苦行）、多聞與思惟、憐愍眾生、勤行精進、具足念心、四威儀；五法中先講信根、持戒與多聞，說明戒有戒相與二地滿心轉內相分的層次，以及直到等覺都需要多聞。","p":["不放逸是心不放逸、淨念相繼，非枯坐","多聞之後須思惟消化，才能為人演說","憐愍眾生、勤行精進、具足念心","四威儀可使眾生恭敬三寶","信根、持戒、多聞各有層次"],"k":["不放逸","多聞思惟","念心所","四威儀","信根","持戒"]},"2028-a08_073":{"s":"本集續講五法中的布施與智慧：等覺菩薩仍布施內財，佛也為阿那律縫衣修福。再說六念：念佛、法、僧、施、戒、天；念戒部分說明證悟者依道共戒攝心，不著有戒、不取相戒等，念天部分強調修禪定以攝受天人。最後開始講七慢，先說明慢、過慢、慢過慢與我慢的內涵。","p":["等覺菩薩乃至佛仍修布施","智慧是為幫助眾生親證三乘菩提","六念：念佛、法、僧、施、戒、天","證悟者依道共戒攝心，不取相戒","七慢先說慢、過慢、慢過慢、我慢"],"k":["布施","六念","道共戒","七慢","禪定","自利利他"]},"2031-a08_074":{"s":"本集續說七慢中的高慢、卑慢、增上慢，以法華會上五千聲聞退席說明阿羅漢的增上慢，並說所說所想皆如實便不生慢。接著解說經文：見人有過應先隨其意再說法，否則為下品菩薩；度人時要柔和隨順，寫書破邪則要直指要害。最後說樂近善友、供養善友、至心聽法、能問法義者方能自利利他。","p":["高慢、卑慢與增上慢的內涵","法華會上五千聲聞退席，示增上慢","所說所想皆如實，便不生諸慢","先隨其意再說法，否則為下品菩薩","近善友、供養、至心聽、能問義方能兼利"],"k":["七慢","增上慢","善巧方便","親近善友","聞法問義","下品菩薩"]},"2029-a08_075":{"s":"本集續講《優婆塞戒經》層層遞進的自利利他：能問義後至心受持、思惟、解義、如法而住。如法住者應具八智，本集說明其中七智：法智與類智（四聖諦十六心）、義智、根智（信進念定慧五根）、上下智、時智、知足智（出世間法也不可躐等妄求），以及自他智（自相、共相智）。","p":["持、思惟、解義、如法住方能自他利","法智、類智與四聖諦十六心","根智觀五根，上下智辨眾生根性","知足智：出世間法亦不可躐等妄求","自他智：由自身推及三界眾生"],"k":["八智","四聖諦","五根","知足智","自共相智","如法住"]},"2037-a08_076":{"s":"本集說明八智的最後一項「眾智」：了知眾生皆當作佛，因此不輕視、不訶責眾生（舉常不輕菩薩）。接著解說具八智者說法的十六事，如時說、次第說、和合說（不排斥三乘任一法）、隨義說、如法說、真正說（真如是阿賴耶識的所顯性），以及說已不生憍慢、不求世報，可作為簡擇善知識的依據。","p":["眾智：知眾生皆當作佛，不輕不訶","說法十六事：時說、至心說、次第說等","和合說：不排斥三乘菩提任一法","真正說：真如是阿賴耶識的所顯性","說法後不生憍慢、不求世間果報"],"k":["八智","說法十六事","和合說","平等性智","阿賴耶識","簡擇善知識"]},"2033-a08_077":{"s":"本集解說具八智的菩薩「能從他聽」及聽法十六事：時聽、樂聽、至心聽、恭敬聽、不求過、不為論議、不為勝、不輕說者、不輕於法、終不自輕（引《金剛經》說已於無量佛所種善根）、遠離五蓋、為受持讀誦、為除五欲（以天花喻）、為具信心、為調眾生，以及為斷聞根而聽。","p":["能從他聽，是攝受眾生的重要關鍵","聽法十六事：時聽、樂聽、至心、恭敬等","聽時不輕說者、不輕於法、終不自輕","遠離五蓋，為修除五欲習氣而聽","為斷聞根而聽，聞根斷盡即成佛"],"k":["聽法十六事","五蓋","五欲","聞根","八智","自利利他"]},"2035-a08_078":{"s":"本集解說清淨與不清淨說法各五事。不清淨說法為利、為報、為勝他、為世報及有疑而說；清淨說法則先施後說、為增長三寶、為斷自他煩惱、為分別邪正、為使聽者得最勝法。說明三寶的三個層次，講者並以一貫道的三寶作對比加以批評，又引玄奘大師「若不摧邪，無以顯正」說明分別邪正的重要。","p":["不清淨說法：為利、為報、為勝他等","清淨說法先施後說，今可以佛書結緣","三寶分自性、出世、世間住持三個層次","講者批評一貫道另立三寶，非增長三寶","引玄奘大師「若不摧邪，無以顯正」"],"k":["清淨說法","三寶","摧邪顯正","玄奘","一貫道","說法心態"]},"2034-a08_079":{"s":"本集解說正說的條件：具足了知十二部經、聲論、因論，知因知喻、知自他取。聽法者分為略聞多解、隨分別解、隨本意解、須逐字解四種，如來說法正為前三種。又以樹林喻在家人的易調難出等四類，並說明訶責、濡語、兼用，自調與請他調，施調與咒調等調伏方法，須善觀根器與時節。","p":["知十二部經、聲論、因論方為正說","聽者四種，如來說法正為前三種","以樹林喻在家人易調難出等四類","以訶責、濡語或兩者兼用調伏眾生","施調以恩攝受，咒調多用於鬼神"],"k":["正說","因論","根器","調伏眾生","見取見","善巧方便"]},"2036-a08_080":{"s":"本集解說菩薩為人說正法的兩種方便：善知世事、為眾生給使。說明工巧明好者道種智進步較快，有增上慢而不肯為眾生做事者會障礙種智；為眾生做事不可求世間利益，講者並以假藏傳佛教為例加以批評。又說在家菩薩弘法須忍辱負重，舉平實導師將毀謗轉為法義辨正書籍為例，〈自利利他品〉至此講畢。","p":["說法二方便：善知世事、為眾生給使","工巧明好者道種智修證較迅速","為眾生做事，不可求世間利益","在家菩薩弘法須忍辱負重","將質疑毀謗轉為法義辨正與法施"],"k":["善知世事","工巧明","忍辱負重","在家菩薩","道種智","摧邪顯正"]},"1937-a08_091":{"s":"本集依《優婆塞戒經》卷二「菩薩具足福德、智慧二法，能自他莊嚴」，先列舉經論中「莊嚴」的多種用法（含以善法或惡業自莊嚴），再說明人天、二乘、菩薩各自應成就的莊嚴，並強調菩薩須以他莊嚴來成就自莊嚴，與所度眾生共成佛國。","p":["經論中「莊嚴」隨前後文而有多種含義","五戒十善、三綱五常為人天莊嚴","二乘依四聖諦、十二因緣斷我見我執出三界","菩薩證如來藏，兼得世出世間莊嚴","菩薩以他莊嚴自莊嚴，與眾生共成佛國"],"k":["自他莊嚴","優婆塞戒經","福德與智慧","五乘佛法","如來藏","四聖諦"]},"2051-a08_092":{"s":"本集續講《優婆塞戒經》福德、智慧二莊嚴。以家庭、公司、總統、金轉輪聖王到世尊教化百億四天下，比較福報的範圍；指出世間福報無法成辦三乘菩提，須有「他莊嚴的福」。智慧則分世間智慧、共二乘的出世間智慧，及證自心如來後的世出世間智慧。","p":["世間福報範圍有大小，終有享盡之時","世尊福報廣大，教化百億四天下","修證三乘菩提須具他莊嚴之福","智慧分世間、出世間、世出世間三層","福德與智慧如鳥兩翼，不可分離"],"k":["福德莊嚴","智慧莊嚴","工巧明","世出世間智慧","優婆塞戒經","轉輪聖王"]},"2050-a08_093":{"s":"本集解說《優婆塞戒經》「施、戒、精進名福莊嚴；忍、定、智慧名智莊嚴」，以及六念中念佛法僧為智莊嚴、念戒施天為福莊嚴。講者批評主張「現已無佛」或「三乘只是解脫道」者未具三寶信，並提醒布施應避開破法團體，最後以地藏菩薩說明具二莊嚴者為眾生受苦而不憂悔。","p":["施戒精進屬福莊嚴，忍定慧屬智莊嚴","忍辱、禪定、般若皆依智慧觀察而成","念佛法僧為智莊嚴，念戒施天為福莊嚴","布施須辨別對象，免與破法者共業","具二莊嚴者為眾生受三惡苦不生憂悔"],"k":["六波羅蜜","六念","福德莊嚴","智慧莊嚴","十信位","地藏菩薩"]},"2007-a08_094":{"s":"本集說明《優婆塞戒經》「福德莊嚴即智莊嚴，智慧莊嚴即福莊嚴」，並會通平實導師「五度修福業，憑之得般若」之偈。逐一說明布施、持戒、精進中有智慧，忍辱、禪定、般若中有福德，引《摩訶般若波羅蜜經》說明福慧互相增上，乃至無住行施、福智無比。","p":["六度每一度皆兼有福德與智慧層次","布施須以智慧辨別對象是否如法","持戒犯否輕重及開緣須依智慧判斷","禪定生色界、教化眾生得無量世福","福慧互為依憑增上，速成佛道"],"k":["福智互攝","六度","優婆塞戒經","摩訶般若波羅蜜經","般若","菩薩戒"]},"2054-a08_095":{"s":"本集講《優婆塞戒經》有智之人分別世法與出世法，能二世自他利益。世法含一切世論與世定；斷我見者修定是次第捨離，菩薩則以四禪八定淨除如來藏雜染種子。又說五明，內明須探究蘊處界的根本，並指出慈悲須依出世間法，才不成溺愛般的濫慈悲。","p":["世法分一切世論與一切世定","斷我見者修定為次第伏捨，有八背捨","菩薩修定為淨除如來藏雜染種子","五明中內明探究蘊處界的根本","慈悲須依出世間法，遠離濫慈悲"],"k":["五明","四禪八定","慈悲","斷我見","如來藏","世間法與出世間法"]},"2008-a08_096":{"s":"本集解說《優婆塞戒經》「菩薩施時觀二種田：福田與貧窮田」。先說明具二莊嚴的菩薩摩訶薩因離四相而施時不悔，並比較二乘與大乘三三昧的差異；再分析報恩田、功德田、貧窮田的果報，講者批評在假善知識處布施如同施於毒田，並指出在何種法中布施便得何種智慧。","p":["菩薩摩訶薩離四相，一切施時不生憂悔","二乘三三昧依蘊處界，大乘依如來藏","福田含報恩田、功德田，另有貧窮田","布施假善知識如施毒田，成破法共業","所施之法不同，來世所得智慧亦不同"],"k":["福田","布施","三三昧","菩薩摩訶薩","優婆塞戒經","善知識"]},"2053-a08_097":{"s":"本集講《優婆塞戒經》菩薩施親為報恩、施怨讎為除惡，以及在一次布施中具足六波羅蜜的例證。說明外門修六度只有六度而無波羅蜜，須七住明心後轉依如來藏、內門修行，三輪體空才有所依、布施因果不昧；定性二乘不能到彼岸。講者並批評有人藉布施法斂財。","p":["施親為報恩，施怨讎為除自他之惡","外門六度無波羅蜜，內門自七住位始","三輪體空須依如來藏，布施因果不昧","定性二乘自滅於三界，無到彼岸可言","一次布施即具施戒忍進禪慧六度"],"k":["六波羅蜜","三輪體空","七住位","如來藏","布施","內門修行"]},"2022-a08_098":{"s":"本集解說《優婆塞戒經》「眾生貪心殺時一念具足十二因緣，菩薩施時一念具足六事」。強調須先作十因緣觀確認第八識，再觀十二因緣；接著講造不共法之因緣名福莊嚴、教化眾生得三種菩提名智莊嚴等數組對照，並引《摩訶般若經》說菩薩為聲聞辟支佛作福田。","p":["觀十二因緣前須先作十因緣觀確定第八識","貪心殺生時一念中具足十二因緣","菩薩布施時一念具足六度、六度互攝","造不共法因緣為福，教化三菩提為智","菩薩常為聲聞、辟支佛作福田"],"k":["十二因緣","十因緣","福德智慧莊嚴","六度互攝","如來藏","摩訶般若波羅蜜經"]},"2062-a08_099":{"s":"本集講《優婆塞戒經》菩薩莊嚴無上菩提的五法：信心、悲心、勇健、讀誦世論不厭、學諸世業不厭；並開始講具二莊嚴的七相，說明自知罪過、不說他過、樂瞻病人、樂施貧人、獲菩提心五相。講者批評只教「一句佛號唸到底」而不說三福淨業的教法，以及以比丘相繪「佛陀問病圖」的說法。","p":["信心指對三寶常住，尤其自性三寶之信","悲心有層次，終至視眾生猶如一子","勇健心難持續，須善知識攝受","讀誦世論、學諸世業以攝眾增智","七相前五：知過、不說他過、瞻病、施貧等"],"k":["五法","信心","悲心","優婆塞戒經","三寶","念佛"]},"2021-a08_100":{"s":"本集續講七相的心不放逸與一切時中修六度，再說另外七相：樂化怨讎、化時不厭、要令成熟解脫、以世語世事化眾、能忍惡事、不說他人不喜事、見破戒者不瞋常憐愍。最後解釋經中「在家修集二莊嚴為難」，引《維摩詰經》說明發菩提心、證自心如來才是真出家。","p":["獲菩提心後見己過而心不放逸","樂化怨讎、化時不厭、令眾生成熟解脫","能忍惡事，以平實導師受謗不改為例","見破戒弊惡人不瞋而常生憐愍","依《維摩詰經》，發菩提心即是出家"],"k":["七相","福智莊嚴","出家真義","維摩詰經","優婆塞戒經","度化眾生"]},"2040-a08_101":{"s":"本集開始「菩薩應如何教化弟子」單元。先說明菩薩道修證次第，以及成佛所需的智慧與福德莊嚴必須依實證如來藏；引《央掘魔羅經》久學菩薩八相，說明實義菩薩方能攝受弟子。再依《優婆塞戒經》以四攝法攝取弟子，並列舉應教弟子遠離的惡法。","p":["菩薩道次第如階梯，不可躐等","成佛所需福慧須依實證如來藏","《央掘魔羅經》久學菩薩八相","以布施、愛語、利行、同事攝取弟子","教弟子遠離邪淫、放逸、我見及斷常見"],"k":["四攝法","實義菩薩","久學菩薩","如來藏","優婆塞戒經","修道次第"]},"2044-a08_102":{"s":"本集續講教弟子遠離不能安忍無所得空、以定境起慢等惡法，並列應增善法：菩提意樂、甚深般若、大悲願、菩薩戒、五根、擇法覺分、大乘止觀、八聖道。經說為名利畜弟子名假名菩薩；再講法布施即正法，愛語是應時說法、對治貪瞋癡慢散亂，利行則以十二部經教學。","p":["遠離執著定境、輕慢正法與善知識","應增善法含菩提意樂、般若、八聖道","為名利畜弟子者名假名菩薩","愛語即應時說法，以五種觀門對治煩惱","利行以十二部經辨相似像法與斷滅空"],"k":["四攝法","法布施","愛語","利行","五停心觀","般若空"]},"2042-a08_103":{"s":"本集講利行須依弟子利、中、鈍根而施教，及同事是將自己所證傳授弟子。經說畜惡弟子而不教誨，其過重於惡律儀。接著說明出家菩薩可畜出家與在家弟子、在家菩薩只畜在家弟子；出家菩薩教出家弟子十二部經、懺悔及法、義、時、知足、自、眾、根、分別八智，師徒俱得利益、增長三寶。","p":["鈍根令生信，中根令純淑，利根令解脫","同事是令弟子同證所證之法","畜惡弟子不教，過重於惡律儀","出家菩薩畜二種弟子，在家菩薩一種","教出家弟子八智，分別智辨相似像法"],"k":["八智","同事","出家弟子","優婆塞戒經","相似像法","四攝法"]},"2049-a08_0104":{"s":"本集講出家實義菩薩教化在家弟子，須先教不放逸法；引《如來不思議祕密大乘經》說明不放逸是善法生處，具淨信、精進、正念正知方能勤修深固之法。依次講解前六項：供養父母師長、至心受戒不妄毀犯並受寄不抵、見恚能忍、不惡口無義語、憐愍眾生不食肉、恭敬國王長者大臣。","p":["不放逸即法行，如大地生長一切善法","淨信、精進、正念正知能修深固之法","供養父母師長為報恩田，即是布施","菩薩戒積極入世，須至心受持不妄犯","見恚能忍、不惡口、慈愍不食眾生肉"],"k":["不放逸法","在家弟子","菩薩戒","忍辱","報恩","優婆塞戒經"]},"2045-a08_105":{"s":"本集續講出家菩薩教在家弟子的不放逸法第七至十一項：調伏妻子眷屬、分別怨親不輕眾生不親惡友、節食除貪、不往鬥諍之處、戲笑不說惡語。再說弟子貧病時，師可貸三寶物救助，病癒十倍償還；不能償者，可以證果、發菩提心、教千人生信或壞一人邪見抵償。最後引出在家菩薩教在家弟子。","p":["在家菩薩應先調伏攝受妻子眷屬","不以貧富或證量輕慢眾生，遠離惡友","節食除貪、不入鬥諍處、戲笑不惡語","弟子貧病可貸三寶物，病癒十倍償還","無力償者以證果、發心、破邪見抵償"],"k":["不放逸法","在家弟子","三寶物","發菩提心","少欲知足","優婆塞戒經"]},"2047-a08_106":{"s":"本集講在家實義菩薩教在家弟子的不放逸法：供給兄弟妻子親友、先給僮僕飲食、教信向三寶、苦樂共俱、不打罵、瞻病、為子女擇婚。並須教如來五部大乘經典，闡明般若中道無我不同於二乘及外道無我；又講先以布施攝受內外諸道、以六和敬共處，以及如法求財、樂為福德並隨喜他人。","p":["供給眷屬，先給僮僕飲食，教信三寶","教如來五部經典：般若華嚴大集寶積涅槃","般若中道無我異於二乘及外道無我","供養內外諸道，先以施攝，後當調伏","六和敬，見和同解大小乘解脫共不共"],"k":["六和敬","般若中道","無我","五部大乘經典","在家菩薩","不放逸法"]},"2041-a08_107":{"s":"本集講在家菩薩若為國主應如何治國教民。先說國土荒廢源於人民慳貪不善；再依《優婆塞戒經》說護民如子、懲惡不斷命、六分稅一、讀誦五部經典（引《金光明最勝王經》四天王護國）、如法護國、遠離賭博射獵飲酒等七惡、常供養出家人、不舉四兵，並引阿含偈說明四攝法的重要。","p":["國土荒廢源於人民慳貪多行不善","國主護民如子，懲惡不斷命，六分稅一","讀誦五部經典，得四天王等天眾護持","如法護國，遠離賭博射獵飲酒等七惡","以四攝攝取人民，阿含偈喻如車輪"],"k":["國主","四攝法","如法護國","金光明最勝王經","在家菩薩","優婆塞戒經"]},"2046-a08_108":{"s":"本集先引《大薩遮尼乾子所說經》說明王者為民父母，須知民苦樂、如法攝護；再說在家菩薩因多惡因緣，畜弟子較難。接著講《優婆塞戒經》受優婆塞戒前須供養六方，依次說明東方父母、南方師長、西方妻子、北方善知識、下方奴婢的供養方式，及其各自的回報。","p":["王者民之父母，須知民苦樂而攝護","在家菩薩多惡因緣纏繞，畜弟子為難","受優婆塞戒前須先供養六方","東方父母、南方師長，各以五事回報","西方妻子十四事、北方善知識四事回報"],"k":["供養六方","優婆塞戒","國主","孝養父母","善知識","優婆塞戒經"]},"2043-a08_109":{"s":"本集講六方中的上方，即供養沙門、婆羅門，出家人以生信、智慧、行施、持戒、多聞五事回報；供養六方者能增長財命，有資格受優婆塞戒。接著說明受戒程序：先徵得父母、妻子僮僕、國主同意，再向出家菩薩求受，並逐項問遮難，引《瑜伽師地論》說明，最後開始講外道須深盜法的故事。","p":["上方為沙門婆羅門，出家人五事回報","供養六方具世間善，方可受優婆塞戒","受戒前須稟告父母、妻子僮僕、國主","引《瑜伽師地論》說二根無根者不許出家","問負三寶物、身心病、五逆、盜法等遮難"],"k":["優婆塞戒","受戒遮難","供養六方","盜法","瑜伽師地論","須深"]},"2048-a08_110":{"s":"本集續講須深盜法的故事：慧解脫比丘雖無禪定神通也能解脫，佛為須深說「先知法住，後知涅槃」及十二因緣流轉還滅，須深因而斷我見並懺悔，佛教以具體懺悔文，並說盜法之苦重於日受三百矛。其後講解其餘受戒遮難，其中講者批評藏密雙身法的相關作為。","p":["慧解脫比丘無禪定神通也能解脫","先知法住後知涅槃，觀十二因緣流轉還滅","須深斷我見後至誠懺悔，自知見罪","盜法之苦重於日受三百矛","問壞八戒齋、棄病親、兩舌、大妄語等"],"k":["盜法","受戒遮難","十二因緣","慧解脫","懺悔","優婆塞戒"]},"1993-a08_111":{"s":"本集導讀《優婆塞戒經講記》〈受戒品〉，說明求受優婆塞戒須先得父母親眷同意，並以泰國出家習俗及《六度集經》世尊因地刺身求戒故事，顯示佛戒稀有難得。引《梵網經》說明不應向外道說戒，又指出優婆塞戒須由出家法師傳授，與在家亦可互傳的菩薩戒不同，並開始講解戒師的遮難問題。","p":["受戒前須得父母、妻子、親眷同意與祝福","世尊因地刺身求戒，顯佛戒稀有難得","佛戒不應向未受戒者及外道邪見人宣說","優婆塞戒須出家法師傳，梵網等菩薩戒在家亦可傳","遮難：親眷同意、虧負三寶財物、重病、污淨行"],"k":["優婆塞戒","受戒品","遮難","菩薩戒","戒師資格"]},"1987-a08_112":{"s":"本集續講受優婆塞戒的遮難：五逆罪中破和合僧最常見，廣義的出佛身血即毀謗正法，如否定第七、八識；又說明盜法、二根與無根人、毀八關戒齋、離棄病中父母師長、殺發菩提心人等皆不得受戒。並引《賢愚經》差摩受八關戒齋得羅剎贈金致富的故事，說明八關戒齋現世亦有大利益。","p":["五逆罪中破和合僧最常見，挑撥分派即是","廣義出佛身血：謗法、否定第八識如來藏","盜法：為名聞利養或為原道場而來求法","二根、無根人及毀八關戒齋者不得受戒","差摩持八關戒齋，羅剎不害且贈金致富"],"k":["遮難","五逆罪","破和合僧","盜法","八關戒齋","優婆塞戒"]},"1985-a08_113":{"s":"本集講竊盜現前僧物、兩舌惡口、邪淫、妄語等遮難，引《雜阿含》沙彌偷黑糖餅受報為例；接著說明優婆塞戒是沙彌、比丘、菩薩三壇大戒的根本。講者批評部分受三壇大戒者以比丘戒為根本、菩薩戒為輔，認為是顛倒；最後講三歸不再歸依外道，以及施無畏予眾生即度眾到彼岸的真義。","p":["竊盜現前僧物即虧欠十方三寶，罪極重","兩舌、惡口、邪淫母姊、妄語者不許受戒","優婆塞戒是三壇大戒的根本","大乘出家應以菩薩戒為根本戒","施無畏即度眾生出輪迴、到彼岸"],"k":["優婆塞戒","現前僧物","三壇大戒","菩薩戒","無畏施","般若波羅蜜"]},"1992-a08_114":{"s":"本集以世尊本生為商人、不畏魔王恐嚇仍行布施的故事，說明布施統攝六度，並指三輪體空須依三乘實證而非意識推理。接著講戒師須詳說開、遮、持、犯，否則不算得戒；再解說殺生、偷盜的現世與來世惡報及三惡道之苦，強調盜法之罪最重，並開始講迦毘梨百頭魚的故事。","p":["本生：商人不畏魔王恐嚇，堅持布施","布施統攝其餘五度；三輪體空須實證","戒師須詳說開遮持犯，否則不能得戒","殺生、偷盜現報與三惡道報","盜法違法毗奈耶，罪最重"],"k":["布施","六度","三輪體空","開遮持犯","五戒","盜法"]},"1988-a08_115":{"s":"本集講完迦毘梨故事：他假裝出家盜學佛法，辯不過就以獸名罵僧，因此受百頭魚身，賢劫千佛過後仍不得脫。又舉摩摩帝侵占僧寶物並惡口罵聖僧，墮糞坑為大蟲歷經七佛的故事，說明盜三寶物與惡口的重報；並講妄語、飲酒、邪淫的過失。講者批評某派以男女雙修為修行，認為違背佛法。","p":["迦毘梨盜法又惡口，受百頭魚報","盜法加惡口的罪報極難改變","摩摩帝侵占僧物罵聖僧，墮糞坑經七佛","妄語、酗酒的現世與來世惡報","邪淫指配偶以外，現報後報皆苦"],"k":["盜法","惡口","三寶物","妄語","邪淫","飲酒"]},"1990-a08_116":{"s":"本集說明五戒是一切佛戒的基礎，可作為檢驗戒律是否為佛正戒的標準，講者並據此批評坦特羅一派違背五戒的戒條。接著引《出譬喻經》梵摩達王布施衣服、由持五戒賢者咒願，使無衣女鬼得以生天，說明持五戒的福德及阻人布施的惡果；再以闇婆婆利女供佛獻園及講者在泰國遇到的反質祝願，介紹祝願（咒願）法。","p":["五戒是一切佛戒的基礎與檢驗標準","講者批評坦特羅戒條違背五戒","持五戒賢者受供咒願，鬼神得生天","阻止別人布施有相應惡果","受供須為施主祝願，含說法、授記、反質"],"k":["五戒","持戒福德","布施","咒願","坦特羅"]},"1984-a08_117":{"s":"本集講戒師以五戒為基礎進一步告誡：遇貪、瞋、癡、怖畏時不作虛妄語行，不去屠家、淫女、酒肆、國王、旃陀羅家，不賣生命、刀劍、毒藥、酒及壓油，不作羅網、藍染、釀皮，不賭博放逸。並說明須如法求財、財分四分、遠離四種惡人，再以《賢愚經》微妙比丘尼因前世惡誓今生一一應驗的故事，警示亂發惡誓的口業。","p":["遇貪瞋癡怖時不作虛妄語、虛妄行","五處不去、五事不販賣、三事不作","不賭博、不放逸，不親近四種人","須如法自求財物，財分四分運用","微妙比丘尼前世惡誓，今生全部應驗"],"k":["優婆塞戒","正命","妄語","惡誓","因果報應"]},"1989-a08_118":{"s":"本集說明遮難後，戒子須在僧團親近戒師服務六個月接受觀察，再由二十位僧眾和合羯磨，默然同意才傳戒，經文並明示受者為男子身。講者說明此經的因果與實相道理女眾亦應研讀，對參禪也有助益。戒師再授三歸，說明持此戒可證初果乃至三果，破戒則墮三惡道，並以《賢愚經》重姓比丘的故事說明三歸與持戒的大善果。","p":["戒子須在僧團實習六個月受觀察","二十僧和合羯磨，默然同意方可傳戒","經中因果實相之理女眾也應研讀","持此戒可證初果至三果，破戒墮三惡道","重姓比丘因三歸、不殺戒、供佛一錢得福"],"k":["優婆塞戒","羯磨","三歸依","持戒功德","初果"]},"1986-a08_119":{"s":"本集說明受優婆塞戒後仍可受用五欲，不障證初果至三果；在家人能否證四果，關鍵在離欲而不在出家表相。接著介紹一分、少分、無分、多分、滿分五種受持法；又以《法句經》摩訶盧比丘前世慢心吝法的故事，說明持戒而輕慢他人即是我見。最後指出凡夫是在學戒，二地以上才能說持戒清淨無犯。","p":["受此戒仍可受用五欲，不障證初至三果","在家能否證四果，關鍵在離欲而非表相","優婆塞戒有一分至滿分五種受持","持戒生慢心即我見，違背諸法無我","凡夫是學戒，二地以上方能說持戒清淨"],"k":["優婆塞戒","四沙門果","五欲","我見","慢心","學戒"]},"1991-a08_120":{"s":"本集說明初地前菩薩必有犯戒，受戒正是為了約束提醒自己，犯戒時應如法懺悔、知時安忍，即「有持有犯名菩薩」。接著依《瑜伽師地論》講下、中、上品律儀，以及靜慮律儀可損伏犯戒種子；配合未到地定證初果，才是永害惡趣種子的無漏律儀，三果則一切惡戒種子永害。並以《法句經》烏龜縮殼的比喻說明戒能護身。","p":["受戒後犯戒是常態，應發露懺悔、安忍","有持有犯名菩薩，無持無犯名外道","瑜伽論分下、中、上品律儀","靜慮律儀以定力損伏犯戒種子","未到地定加初果為無漏律儀，三果種子永害"],"k":["律儀","瑜伽師地論","懺悔","靜慮律儀","無漏律儀","戒定慧"]},"2013-a08_121":{"s":"本集開啟「如何讓戒行清淨」單元，依《優婆塞戒經》七十多條方法分五單元，本集講依正信正解修持淨戒。信即信三寶與深信因果，並以阿賴耶識為因果的根本因；講者批評無因論、網路謗法及把佛法當學術研究的作法。解心方面，說明疑佛、法、戒、教、梵行五種穢染及五種繫縛弊病，應先對治。","p":["戒律是通往常樂我淨妙道的護欄","深信三寶，由外三寶入自性三寶","深信因果，阿賴耶識是果報根本因","批評無因論、網路謗法及學術化佛學","解心：除五種穢染與五種繫縛弊病"],"k":["正信","三寶","深信因果","阿賴耶識","解心","持戒清淨"]},"2014-a08_122":{"s":"本集講菩薩依真善知識、精進正法攝持淨戒：應恭敬親近善知識與善友，並以世尊帶難陀拿臭魚茅草與香紙的比喻，說明近朱近墨之別。接著講由聞思修勤修善法、正知苦樂皆是相對無常、有為法無常而從如來藏看則常，以及應觀五陰尤其識陰虛妄以斷我見，同時須信有涅槃本際，才能抉擇法與非法。","p":["恭敬請法，親近真善知識與善友","難陀臭魚香紙喻：親近善惡友之別","聞思修出生善法，親證實修最重要","苦樂相對無常，轉依如來藏離苦樂繫縛","觀識陰虛妄斷我見，須信有涅槃本際"],"k":["善知識","善友","斷我見","苦樂","如來藏","我所"]},"2011-a08_123":{"s":"本集講菩薩以慈心攝持淨戒：心常想著利益眾生、在眾生心中種下菩提正因，戒行自然清淨。說明引導眾生要善巧方便，例如對執離念靈知為真心者先讚歎再提問；並依世尊次第說施論、戒論、生天之論，再說五陰無常苦空無我。又講要量力承擔、主動結善緣、先利益怨家，並舉平實導師對批評者不起怨的態度為例。","p":["慈心利生，在眾生心中種菩提正因","善巧引導，不直接否定對方以免斷緣","依世尊次第：施論、戒論、生天論","量力而行，不承擔超出能力的事","主動結善緣，先利益怨家再利眷屬"],"k":["慈心","善巧方便","次第說法","利樂眾生","怨親平等"]},"2012-a08_124":{"s":"本集講菩薩以悲心攝持淨戒：悲是拔苦，菩薩關心眾生迷於五欲與外道邪見，施無畏救護。舉世尊不捨善星比丘為例，說明對造惡眾生以憐愍代替責備；並說五濁惡世逆境正可修除習氣、成就福德，不必求往生避難。又說菩薩度眾不疲不悔，珍惜色身與眾生緣，以富樓那為例，並指出轉依如來藏故心無恐懼。","p":["悲是拔苦，救護迷於五欲、邪見的眾生","世尊不捨善星比丘，以憐愍對待造惡者","感謝五濁惡世逆境，可修除習氣性障","度眾不疲不悔，珍惜色身與眾生緣","轉依如來藏故心無恐懼；悲拔苦、慈與樂"],"k":["悲心","拔苦","無畏施","善星比丘","富樓那","如來藏"]},"2023-a08_125":{"s":"本集講菩薩以堅固菩提正行攝持淨戒：不輕言自己不能證果，自輕即違背誓願、戒不清淨；不輕己則謹慎身口意。又說求悟之心要堅固、長遠，見他人開悟應隨喜不嫉妒，菩薩性靠多世累積，度眾大事不倦不悔。並引《涅槃經》草繫比丘與護浮囊喻，說明細微戒也要謹慎；未斷我見者寧可嚴持戒律，不輕用開遮。","p":["不輕言不能證果，自輕即違誓願","趣向佛菩提心須堅固，要有長遠心","見他人開悟應隨喜，菩薩性多世累積","度眾大事不疲不悔，深信堅固猶若金剛","草繫比丘、護浮囊：細戒亦須謹慎"],"k":["菩提心","持戒清淨","草繫比丘","護浮囊","開遮"]},"1976-a08_126":{"s":"本集開講息惡法則，先引《阿含經》佛陀教比丘止息惡念的五法：念善相應、念惡有災患、不念此念、思行漸減念、以心修心。再依《優婆塞戒經》善生菩薩所問，說明遇內外惡不淨因緣時應修念佛心，以增長悲慧；並解釋悲是拔除眾生逆於正道的邪念，以平實導師破邪顯正為悲心的例子。","p":["能正信大乘三寶者稀有難得","阿含止惡念五法：念善相應等","內外惡不淨因緣應修念佛心","念佛心可遠離惡緣、增長悲慧","真正的悲是拔除眾生邪念、導向正道"],"k":["息惡","念佛","悲慧","惡念","修定","優婆塞戒經"]},"1978-a08_127":{"s":"本集依《優婆塞戒經》講觀如來七勝事以息惡：身勝來自無量福德，如法住勝為主動護念眾生，智勝為四無礙智，具足勝為行命戒見具足，行處勝為依如來藏的三三昧與九次第定，不可思議勝含六通、十力、四無所畏等，解脫勝為斷盡煩惱障習氣與所知障。說明觀佛形像、思佛功德可使戒行清淨。","p":["身勝：相好與身力由無量福德成就","如法住勝：主動積極護念救濟眾生","智勝、具足勝：四無礙智，行命戒見具足","行處勝：依如來藏修三三昧、九次第定","解脫勝：斷煩惱障習氣及所知障"],"k":["念佛","如來七勝事","三三昧","四無礙智","解脫","所知障"]},"1977-a08_128":{"s":"本集講了知如來十號功德以息惡：無上尊、如來、阿羅漢（應供）、正等覺、明行足、善逝、世間解、調御丈夫、天人師、佛薄伽梵。逐一說明其義，如菩薩證如來藏的三三昧、依十因緣觀十二因緣、佛雖稱阿羅漢但證境不等同阿羅漢、覺了世諦與真諦、三明無侷限、破四魔等，指出了知佛境界可生恭敬而使戒行清淨。","p":["無上尊：從不淨觀至佛地，勝於二乘","如來：二種三三昧，依十因緣觀十二因緣","佛稱阿羅漢為應供，證境不等同阿羅漢","正等覺覺了世諦與真諦，明行足具三明","天人師為佛專用名號；佛破四魔"],"k":["如來十號","念佛","三三昧","二諦","三明","四魔"]},"1980-a08_129":{"s":"本集講深會如來願行以息惡：如來修戒定慧皆為利益眾生，增上三學從初地起；如來怨親平等，已斷四住地煩惱及塵沙惑。經說眾生為一煩惱受無量苦，講者解為我見，引平實導師開示說斷我見比明心更重要，須逐一觀察蘊處界、能取所取的虛妄。最後講如來為眾生難施能施、難忍能忍。","p":["如來修戒定慧全為利益眾生","怨親平等，會記恨即非入地菩薩","如來斷盡四住地煩惱與塵沙惑","眾生為我見一煩惱受無量生死苦","斷我見須一一觀蘊處界、能取所取虛妄"],"k":["斷我見","增上三學","怨親平等","四住地煩惱","能取所取","明心"]},"1979-a08_130":{"s":"本集講念佛清淨因緣：佛有莊嚴淨與果報淨，具八萬音聲令眾生不厭。講者依平實導師之說，批評覺音《清淨道論》未說斷我見內涵，也質疑「南傳上座部是真正的大乘」的說法；引無著菩薩分世間清淨與出世間清淨，並批評喇嘛教。說明莊嚴清淨須以正財、智慧選擇福田，本集也是三乘菩提正行內容的暫告段落。","p":["佛說因果：因果經、鸚鵡經、占察經","佛有二淨：莊嚴淨與果報淨","講者批評《清淨道論》未說斷我見","世間清淨與出世間清淨，唯佛究竟清淨","莊嚴須以正財，布施要以智慧觀察福田"],"k":["清淨","念佛","莊嚴","清淨道論","斷我見","福田"]},"2331-a10_001":{"s":"本集說明佛教三寶的內涵。先指出一貫道「玄關、口訣、合同」與道教「精氣神」三寶都不出三界，再介紹住持三寶（佛像、經典、出家人）與自性三寶（本有、本來清淨的自心如來）。講者也提醒不要供養男女合抱像，並批評喇嘛教假冒僧寶、另立「四歸依」不如法。","p":["一貫道、道教三寶不能出離三界生死","住持三寶：佛像、經典、住寺出家人","講者認為密教部多偽經，男女合抱像不應供養","自性三寶即自心如來，本有而本來清淨","一念不生、了了常知仍是意識，不是自性僧寶"],"k":["三寶","歸依","自性三寶","住持三寶","如來藏","四歸依"]},"2333-a10_002":{"s":"本集依《優婆塞戒經》善生問如何供養三寶，講解報恩田、功德田、貧窮田三種福田。報恩田分父母、師長、和尚三種恩，引《雜寶藏經》七歲孝子與慈童女故事說明孝養的福德；功德田指布施證果者得無量報；貧窮田包括貧苦眾生、出家人與畜生、餓鬼。講者認為喇嘛是毒田，應當遠離。","p":["世間福田有報恩、功德、貧窮三種","孝養父母福德無量，引慈童女故事","和尚恩：世尊、得法善知識、剃度和尚","布施須陀洹以上得無量報","貧窮田含窮苦者、出家人及畜生餓鬼"],"k":["福田","報恩田","孝養父母","功德田","布施","優婆塞戒經"]},"2332-a10_003":{"s":"本集說明佛寶、法寶為何兼具報恩田與功德田，僧寶又為何三田具足，並說福田的種子含藏在自心如來中不會遺失。依經講供養如來生身、舍利、形像與塔廟，並說明供養應親自去做、不爭勝、施後不悔；再以貧女布施二錢的故事，說明以至誠心布施的福德最大。","p":["世尊示現八相、說法四十九年，為報恩與功德田","護持三乘正法即在法寶種福田","僧寶兼具報恩、功德、貧窮三田","供養如來生身、舍利、形像、塔廟","親自供養、不爭勝、不後悔，以至誠心為重"],"k":["供養三寶","福田","自心如來","舍利塔廟","布施"]},"2336-a10_004":{"s":"本集續講供養塔廟與如來聖像的細節：塔廟髒污毀壞時應清掃修補，彩繪聖像不可摻動物膠、乳汁或蛋白，聖像須是全身。講者批評喇嘛教的火供、五甘露，以及源自濕婆信仰的酥油灌沐都不如法。最後引《阿含經》佛說過去供養燈光如來的福德已經耗盡，勸人把福業迴向求證三乘菩提。","p":["塔廟破損髒污應親自修補打掃","繪製聖像不可用動物膠、乳汁或蛋白","講者認為三界天人不吃人間燒食，火供不如法","聖像應為全身，殘缺者先收藏再修補","有為福業終會耗盡，應迴向求解脫"],"k":["供養如來形像","塔廟","火供","隨喜","迴向"]},"2334-a10_005":{"s":"本集說明能詳細讚歎如來身心功德，才是真正供養佛寶。逐項解說三十二相八十種好、宿住隨念智力（舍利弗與老人出家的例子）、四無畏、五智、十二因緣智（十因緣中齊識而還的入胎識）、四禪八定與六度。講者並逐一批評喇嘛教在肉髻、五佛配五智五色、以意識為真心、拙火得禪定等方面的說法。","p":["能詳細讚歎如來功德，即是真正供養佛","宿住隨念智力：觀見老人八萬劫前有出家緣","每尊佛都具五智，並非五佛各配一智","十因緣的識是入胎識，十二因緣的識是六識","初禪須斷結、離欲界愛，修拙火無法得到"],"k":["佛功德","三十二相","五智","十二因緣","四禪八定","藏傳密宗"]},"2335-a10_006":{"s":"本集講真正供養法寶與僧寶。事相上，受持、讀誦、解說、書寫三藏十二部經就是供養法寶；理上，由自性佛寶藉緣出生一切法引申四件事，講者並批評應成派中觀的斷見與達賴的「業種藏於虛空」說。僧寶則以有無證法證果認定，不看出家表相，舉阿支羅迦葉、彌勒菩薩的開示與德光論師為例。","p":["受持、讀誦、書寫三藏十二部經即供養法","諸法由自心如來藉緣變現，眾生未曾觸到外境","善惡業種藏在自心如來，引貧女難陀點燈","僧寶以證法證果認定，不看出家表相","自心如來常護念眾生；在家供養三寶較難"],"k":["供養法寶","供養僧寶","如來藏","業種","真出家"]},"2305-a10_007":{"s":"本集開始講六波羅蜜，先講布施波羅蜜。說明少量布施也能得大果報（韓信報漂母）、不分別對方持戒或破戒才是清淨布施；講者主張不要布施常見外道、斷見外道和密宗等破法者，不得已時只少量布施並限定用途。另講隨喜不嫉妒、財法無畏三施，以及菩薩不欺誑、不酗酒賭博、應有慚愧心。","p":["具足六度才能從名義菩薩成為真實義菩薩","少物布施也得大果報，不分別持戒破戒","講者主張不布施常見、斷見外道及密宗破法者","隨喜他人布施，不生嫉妒；兼行財、法、無畏三施","菩薩布施不欺誑、不酗酒賭博，應有慚愧"],"k":["布施波羅蜜","六度","三施","隨喜","慚愧"]},"2307-a10_008":{"s":"本集講持戒與忍辱波羅蜜。持戒部分：清淨身口意、犯戒時心生慚愧並作對首懺或對眾懺，引《菩薩瓔珞本業經》「有犯名菩薩，無犯名外道」；並說不故犯、不惱害眾生、知恩報恩，不兩舌、不說無義語。忍辱部分：舉烏龜起瞋墜亡的故事，引《正法念處經》《羅云忍辱經》，以及羼提仙人被歌利王割截而住於無四相的事例。","p":["犯戒應慚愧懺悔，分對首懺、對眾懺","不故意犯戒、不惱害眾生，應知恩報恩","兩舌、說無義語會招來惡報","烏龜起瞋墜亡，說明不忍辱的害處","羼提仙人住於無四相的真心而能忍辱"],"k":["持戒波羅蜜","忍辱波羅蜜","懺悔","兩舌","羼提仙人"]},"2306-a10_009":{"s":"本集由正禮老師接講。善生問外道禮拜六方，佛說佛法的六方就是六度；供養六波羅蜜，是讓布施等法性在自身顯發增長，依據的是因果律，而不是鬼神庇祐。接著解說供養精進波羅蜜的經文：不貪坐臥之樂、不顧飢渴寒熱、不擇時節、不輕自身、讚歎精進的果報，並指出否定第八識的人是方向錯誤的邪進。","p":["佛法的六方即布施到智慧六度","供養六度是讓它的法性在自身顯發","精進要不貪坐臥、不顧飢渴、不擇時節","不輕視自身，大事未完成也不生悔","否定第八識如來藏是方向錯誤的邪進"],"k":["精進波羅蜜","六方","供養六度","邪精進","第八識如來藏"]},"2310-a10_010":{"s":"本集續講精進：講者以修雙身法求成佛為邪進的例子，並說善法不可半途而廢，修證時不隨他人的說法（如斷我見）。接著解說供養禪波羅蜜的經文：樂處空閒、不樂聽世間事、先語軟語安慰眾生；勉勵三賢位菩薩常樂出家教化眾生，並說明欲界飲食與男女的覺觀都是妨礙初禪的惡覺觀。","p":["講者以修雙身法求成佛為方向錯誤的邪進","善法不半途而廢，修證不隨他人之語","禪度要心樂空閒、不樂聽世間事","先語軟語安慰眾生，不觸碰其痛處","欲界飲食與男女覺觀都是妨礙初禪的惡覺觀"],"k":["禪波羅蜜","精進波羅蜜","惡覺觀","初禪","先語軟語"]},"2308-a10_011":{"s":"本集續講供養禪波羅蜜：四禪八定是逐層遠離三界的覺觀，菩薩則以實證第八識來遠離覺觀；又說見怨修慈、樂說定報都須如實。講者批評某比丘《性空學探源》「空義之次第禪定化」的說法，指其混淆三三昧中的空三昧與空無邊處，並把無色界次第視為後人所組織。","p":["四禪八定逐層遠離三界覺觀","見怨修慈：報仇之心也是惡覺觀","樂說定報，須如實說明禪定的生處","三三昧中的空三昧是智慧，不是空無邊處","講者批評《性空學探源》稱無色界是後人組織"],"k":["禪波羅蜜","三三昧","四禪八定","惡覺觀","無色界"]},"2309-a10_012":{"s":"本集先為禪度作結：正定分世間正定與出世間正定，講者把雙身法的淫樂一心判為邪定。接著解說供養般若波羅蜜的經文：以清淨身口意學習一切世間事，依第八識的法性修學五明；見人勝己不嫉妒、勝人不憍慢；孝養父母師長是實證般若的遠因，入正法熏習是近因，善知識教導參禪是正因。","p":["正定分世間與出世間，講者認為雙身法屬邪定","依如來藏法性修學五明，以內明為根本","見勝己者不妒、勝人不慢、苦樂不動心","孝養父母師長是實證般若的遠因","善知識教導參禪是實證般若的正因"],"k":["般若波羅蜜","五明","正定","報恩田","參禪"]},"2302-a10_013":{"s":"本集依《優婆塞戒經》講六方各有四事。施方四事：以布施調伏眾生（例如化解怨家，並引《法華經》窮子喻中的大富長者）、離對（不被財物繫縛）、自利與利他。戒方從莊嚴菩提講起，說優婆塞戒到菩薩戒是初地的根基，並引平實導師書中所說，證悟菩薩依道共戒持心地戒、不取相戒。","p":["六方每一方都有四件要事","以布施調伏眾生，例如化解怨家","離對：離開財物繫縛，契合如來藏","受持優婆塞戒至菩薩戒是初地的根基","證悟菩薩依道共戒持戒，不取相戒"],"k":["六度四事","布施","離對","道共戒","菩薩戒"]},"2304-a10_014":{"s":"本集續講戒方：持戒應先從取相戒開始，再依道共戒；遠離惡戒才是離對，講者以雙身法的三昧耶戒為惡戒之例。忍方四事：要忍於無我、忍於意識生滅，具足二乘無生忍、大乘無生忍與無生法忍才能莊嚴菩提。進方四事：以四宏誓願說明精進，菩薩從位不退、行不退到念不退。","p":["先持取相戒，後依道共戒而無戒可持","遠離惡戒才能離對","忍於無我與意識生滅以莊嚴菩提","二乘無生忍、大乘無生忍、無生法忍","精進：位不退、行不退、念不退"],"k":["六度四事","無生忍","無生法忍","精進波羅蜜","道共戒"]},"2303-a10_015":{"s":"本集講禪方與智方四事。禪方：入地須有初禪以上的證量，發起初禪必須除五蓋、離欲界愛，講者認為修雙身法者無法得初禪；下地境界對上地來說都是惡覺觀。智方：要修智慧才能得初地，講者批評某「上人」《心靈十境》以殷勤心、歡喜心即入初地的說法是淺化佛法，並說除煩惱障、智慧障為自利。","p":["入地須具初禪以上的禪定證量","發起初禪須除五蓋、離欲界愛","下地境界對上地而言都是惡覺觀","初地須修智慧、見道而得，不只是歡喜心","除二障為自利，教化調伏眾生為利他"],"k":["禪波羅蜜","智波羅蜜","初禪","惡覺觀","初地","二障"]},"2341-a10_016":{"s":"本集依經辨正「定有六波羅蜜」，破斥「戒即是忍、定即是慧」而只立四波羅蜜的主張。說明智慧是因、布施是果，精進是因、持戒是果，三昧是因、忍辱是果；戒從他得而忍不必如此；舍摩他與毘婆舍那不同，無分別智是止觀雙運，不是一念不生。最後說明六度依布施的次第而說。","p":["佛破戒即忍、定即慧而只有四度的說法","智慧因布施果、精進因持戒果、三昧因忍果","戒從他得，忍則不必，所以二者不同","無分別智是止觀雙運，不是一念不生","六度依布施次第說出，相互含攝而各不同"],"k":["六波羅蜜","止觀","無分別智","舍摩他","毘婆舍那"]},"2276-a10_017":{"s":"本集由正鈞老師主講，依《優婆塞戒經》卷四說明「波羅蜜」即離開生死此岸、到達無生死的彼岸。人天善法乃至四禪八定都不出三界；二乘入無餘涅槃後已無我，引《法華經》舍利弗之語，說明二乘並非真到彼岸。菩薩在七住位證如來藏、得三三昧，才開始有一分波羅蜜；三輪體空也必須依如來藏。","p":["波羅蜜即離開生死此岸、到無生死彼岸","人天善法乃至四禪八定都不出三界","二乘入無餘涅槃已無我，嚴格說無到彼岸","七住位證如來藏得三三昧，始有波羅蜜","三輪體空須依如來藏，不只蘊處界虛妄"],"k":["波羅蜜","到彼岸","三三昧","三輪體空","如來藏","優婆塞戒經"]},"2298-a10_018":{"s":"本集續講《優婆塞戒經》卷四六波羅蜜的相貌。持戒從三歸、五戒到菩薩心地戒，須經長劫逐步熏修；福德不足時持戒容易猶豫，所以布施列為六度之首。並說明忍辱的目的逐漸轉變、精進即不斷讚佛，金剛三昧不是世間禪定；成佛時具足六度，名為智波羅蜜；在家人要清淨六度較難。","p":["持戒從三歸、五戒到菩薩戒漸次熏修","福德不足則持戒猶豫，故布施居六度之首","忍辱從為了利益轉為斷煩惱、攝受眾生","金剛三昧不入不出，不是世間禪定","明心後轉入內門六度，成佛時具足智波羅蜜"],"k":["持戒波羅蜜","六波羅蜜","金剛三昧","內門六度","優婆塞戒經"]},"2299-a10_019":{"s":"本集依《優婆塞戒經》卷四，說明已修六波羅蜜的菩薩能拔濟沉溺苦海的眾生，但眾生是否願受度，取決於菩薩的福德與善巧。接著講布施要五陰具足、自他俱利，並說施果有財勝、田勝、施主勝三種，指出三輪體空應以如來藏為依止，不能只就蘊處界虛妄來理解。","p":["六度菩薩有能力救度沉溺生死苦海的眾生","以孩童戲水為喻：眾生不覺生死苦，難以勸度","慳於財法食得癡貧報，樂施能化怨為親","布施須身口意五陰具足，觀想布施不成施法","三輪體空應依如來藏，施果分財勝、田勝、施主勝"],"k":["六波羅蜜","布施","優婆塞戒經","三輪體空","如來藏","福德資糧"]},"2344-a10_020":{"s":"本集講解《優婆塞戒經》卷四有智者布施的五種相貌：至心施、自手施、信心施、時節施、如法求物施，各舉世間例子說明不清淨的動機與不如法的取物方式，並引須深盜法的事例說明求法也要如法。最後解說五種施各自的果報，以及五者彼此含攝、果報錯綜複雜。","p":["至心施：不夾雜求名、生天等不淨目的","自手施：親自施與，不假手他人","信心施：深信施果，施後不生悔念","時節施：對方需要時即時施與，如「及時雨」","如法求物施：不以盜、欺、誑取財，求法亦須如法"],"k":["布施五相","至心施","自手施","如法求物施","布施果報","優婆塞戒經"]},"2340-a10_021":{"s":"本集說明如法求物施的果報是所得財物不被王、賊、水、火所侵；反之，不如法得財而布施，今世雖得財也會因這四家而失去。接著講所施色香味觸與未來受用的對應，布施塔像仍因信心與福田而得果，並介紹法施與財施的分別，以及外財、內財布施。","p":["不如法得財布施，今世財物為王賊水火所侵","以色香味觸布施，各得相應的殊妙果報","施塔像雖無人受，因信心與福田仍得五報","法施得財法二報，財施只得財寶報","財施分外財、內財，內財含身力、捐血等"],"k":["如法財施","財施","法施","福田","內財外財","布施果報"]},"2385-a10_022":{"s":"本集續講法施得財法二報：為人說法自己也溫故知新，並引《優婆塞戒經》卷五說明眾生聞法斷瞋等，施主也在未來無量世得相應果報。接著從出三界、淨多垢少、果報無盡、唯佛出世才有四方面說明法施勝於財施，最後講菩薩修財法二施是為了令眾生遠離苦惱、心得調伏。","p":["說法者備法時自熏，也成就未來證法因緣","眾生聞法斷瞋，施主未來無量世得成上色","想作法施須先證法，並且財法二施都要修","法施可出三界、淨多垢少、果報輾轉無盡","財法二施對治慳貪，令眾生離苦、心得調伏"],"k":["法施","財施","法施勝於財施","斷慳貪","信願行","優婆塞戒經"]},"2343-a10_023":{"s":"本集先總結財法二施的自利利他，再依《優婆塞戒經》講法施、無畏施、財施三類：法施包括教人受戒出家、破邪顯正、宣說四倒；講者並批評以一念不生的覺知心入涅槃的說法違背三法印。之後說明無畏施含攝於財法二施，並講施有四累：慳貪心、不修施、輕小物、求世報。","p":["菩薩行財法施，自除煩惱也教眾生調心","法施：教人受戒出家，壞邪見、說如來藏真實法","宣說常樂我淨四倒，破離念靈知為常的見解","無畏施救眾生怖畏，含攝於財施、法施","施有四累：慳貪、不修施、輕小物、求世報"],"k":["法施","無畏施","財施","四倒","如來藏","施有四累"]},"2339-a10_024":{"s":"本集說明以修無我、修無常對治布施四累，並講要常樂布施須除瞋心、慳心、妒心、過惜身命、不信因果五事，以及樂施所得的五種可愛果報。接著依經文解說菩薩摩訶薩「一切施」的種種相貌，以及不以酒毒刀杖布施、不施不淨食藥等應遮與開緣的分寸。","p":["修無我、修無常以破除布施四累","樂施須除瞋、慳、妒、惜身命、不信因果","樂施果報：不離聖人、入眾無畏、莊嚴菩提等","一切施：如法求物、淨心、怨親等施、施不求報","不施酒毒刀杖，有利益眾生之開緣但須拿捏"],"k":["一切施","修無我","修無常","布施障礙","慳吝","開緣"]},"2360-a10_025":{"s":"本集開始講「智者布施的心態」，先說明布施果報受施主、受者、所施物及所得利益影響，再依《優婆塞戒經》解說下、中、上三品施主的差別。以波斯匿王供佛三月及世尊往昔供養燈光如來而福報享盡為例，說明不應求後世福報而應迴向解脫，並描述上品施主依自心如來無我法性平等布施。","p":["布施果報隨施主智慧與所施利益而有差別","下品施主不信業果、深著慳悋，見求者生瞋","中品施主雖信業果仍慳，或為後世報而施","波斯匿王例：供養福德會在生死中享盡","上品施主深信因果，依自心如來平等布施"],"k":["三品施主","布施心態","深信因果","迴向解脫","自心如來","波斯匿王"]},"2363-a10_026":{"s":"本集說明有正知見的菩薩在多財不施、少財不施、貪著好物、誤以無我無求為由不施四種情況下，如何思惟破除慳貪。接著講智者因對三寶有清淨信力與精進力而施後不悔、得七聖財，並依《優婆塞戒經》解說智人行施為自他利的種種心態，以「如失火家得出財物」喻布施可把無常財轉為聖財。","p":["四種不能發心布施的情況及對治的思惟","誤以無我無求而不施，須知法無常才有因果","清淨信力與精進力，成就七聖財","智人施為自他利：知財無常、令眾生歡喜","見乞者如失火家得出財物，施後教其供養三寶"],"k":["七聖財","破慳貪","智者布施","無常","信力","優婆塞戒經"]},"2362-a10_027":{"s":"本集解說樂施能遠離放逸、以身分布施不起一念惡心，講者並提醒捨報時捐贈器官應把捐贈者當活人照料，以免因疼痛起惡心。接著講觀財無常、觀眾生如一子而具檀波羅蜜，並依經文說明智者樂施的四事：破煩惱、發種種願、得受安樂、多饒財寶，以天魔波旬依施發惡願為例。","p":["樂施遠離放逸，以身分施不起一念惡心","捨報時捐器官應當作活人照料，免生惡心","觀財無常、觀眾生如一子，具足檀波羅蜜","無貪名施：身口意業加施物，具足才算無貪","因施發願影響受報，舉天魔波旬發惡願為誡"],"k":["檀波羅蜜","內財布施","器官捐贈","破煩惱","誓願力","無貪"]},"2367-a10_028":{"s":"本集說明以佛菩提法布施能得無上安樂，並強調只有佛果才稱得上「無上」；接著講布施多饒財寶的道理。再依《優婆塞戒經》說明樂施能壞邪見、無信、放逸、慳悋、瞋癡五種弊惡法，現世得四種果報，施後無悔即使墮惡道也不受飢渴；最後講智者布施是為調伏自心、壞怨瞋心，不求名稱與天人果報。","p":["以佛菩提法布施得無上安樂，唯佛果稱無上","樂施壞五弊惡法，邪見指六識論、無三世","現世四果報：怨家樂見、善名流布等","施後無悔：雖墮惡道不受飢渴，人天殊勝","智者為調伏自心、壞怨瞋心而行布施"],"k":["無上安樂","五弊惡法","八識論","施後無悔","調伏自心","七聖財"]},"2364-a10_029":{"s":"本集依《優婆塞戒經》說明智者布施觀察「以不堅財易堅財」、不隨順慳吝之心，並解說七聖財。又講應先以外財試心，再施內財，因此永離諸有、得正解脫，並以卸下重擔為喻，強調布施與智慧不能相離。最後說明有財說無就是放逸，貧窮人也能以洗器餘汁、麵屑施蟻、以身佐助等方式布施。","p":["以不堅的世間財換取堅固的七聖財","先施外財試心，調伏後再施內財","二施得永離諸有與正解脫，須以智慧為本","有財卻說無財，是自說來世貧窮的放逸","貧者亦能施：洗器汁、麵屑施蟻、身力佐助"],"k":["七聖財","外財內財","正解脫","貧窮布施","智慧與布施","慳吝"]},"2366-a10_030":{"s":"本集說明貧者以身佐助或遙聞隨喜，因心相等，所得福德與施主無異，並以買香、聞香為喻。接著依《優婆塞戒經》說明真正的貧窮是對福田無信，以及除布施外不得人天樂與無上樂、阿羅漢托空缽是因先世不施等道理，強調布施應為斷生死、求佛果，不為人天樂。","p":["隨喜佐助布施，心等故福德無差別","真貧窮是無信、疑福田，信為七聖財之首","除布施外，不得人天樂與無上樂","阿羅漢托空缽，緣於先世沒有布施","應為斷生死、成佛果而施，不求人天樂"],"k":["隨喜功德","貧窮","無上樂","福德資糧","般若智慧","斷生死"]},"2361-a10_031":{"s":"本集說明「布施得福之因果原理」：依般若智慧從如來藏看，沒有施者、受者與受報者，講者批評六識論者把這解讀成緣起空而懷疑因果。並引《彌勒菩薩所問經論》解釋為何慳人富而施者貧，再依《優婆塞戒經》講佛陀以種子生芽為喻破斥外道，說明無明、業、愛如何依十二因緣長養五陰苦芽。","p":["依如來藏般若說無施者、受者、受報者","講者批評六識論誤解《金剛經》而疑因果","慳人富因曾施勝田；施者貧因昔施心態不正","以種子常與無常的問答破斥外道","以十二因緣說明業、愛長養五陰苦芽"],"k":["布施因果","如來藏","六識論","十二因緣","金剛經","優婆塞戒經"]},"2365-a10_032":{"s":"本集續講布施因果原理，說明芽是「本無今有」，駁斥外道說子中先有芽、以「時」為常法等主張。並以種子、芽、莖、葉、花、果相似相續為喻，說明前後世五陰雖不同，卻由同一如來藏持業種、經中陰身入胎而相續不斷；也講一道五陰增五道業、重業先受報，以及佛陀破外道「異作異受」之過，說明即作即受、異作異受、無作無受。","p":["芽是本無今有，破子中先有芽之說","破外道以時為常法，種芽相似相續不斷","前後世五陰由同一如來藏與中陰相續","一道五陰造五道業，重業先受報，業可轉","外道作者是我、受者是身，才有異作異受之過"],"k":["如來藏","相似相續","中陰身","異作異受","業種","五陰"]},"2289-a10_033":{"s":"本集是《優婆塞戒經講記》的導讀，解釋即作即受、異作異受、無作無受三種說法，並以《百喻經》渴者見水卻不飲為喻，說明五蘊非真實有。講者批評以杯子假合解釋「空」的說法是推理而非實證；並講造業與受報非一非異，由如來藏收藏業種，接著引經文說明佛得與天得五陰不同，開始講《六度集經》第二帝釋的故事。","p":["即作即受、異作異受、無作無受三義","《百喻經》喻：眾生追逐五蘊如追陽焰","講者批評以推理說空，未證初果","意識異作異受，末那自作自受，如來藏非作非受","佛得與天得五陰身名各異，不可說此作彼受"],"k":["即作即受","異作異受","無作無受","如來藏","五蘊","優婆塞戒經講記"]},"2293-a10_034":{"s":"本集講完第二帝釋陷害國王而生身墮地獄的本生故事，說明天人若依止五欲仍會下墮，只有佛無苦無惡報。再引《經律異相》佛在阿耆達國食馬麥三月的故事，說明佛所受都是淨白妙果，馬麥也化為天廚妙味。最後依經文講佛所說的兩種「異」，並開始解說放火燒村的譬喻。","p":["第二帝釋惡因成熟，以天身墮入地獄","天人未離五欲、三毒，仍可能受苦下墮","佛食馬麥，阿難嘗之卻是上上美味","佛斷盡二障，只有善業善報，示現是為度眾","異有二種：次第生次第滅、次第生不次第滅"],"k":["異作異受","本生故事","馬麥","五陰身","天人五衰","佛果"]},"2291-a10_035":{"s":"本集講解《優婆塞戒經》放火燒村、執炬遠行百里的譬喻，說明前後火相續不斷，所以可說「亦即亦異」，五陰也可說即作即受、異作異受，因為是同一如來藏相續。並引《法句經》帝釋臨終歸依三寶、免受驢胎的故事；再以恆河兩岸與中流為喻，破斥以河神為河的說法，又以惡口而腳受鎖說明不能只定說一邊。","p":["小火延燒大村，前後相續故放火者有罪","執炬百里之賭：亦即亦異，兩說都有理","帝釋臨終歸依三寶，免受驢胎而證初果","恆河由兩岸與中流相續合成，非河神","惡口而腳被鎖，不能只定說一種作受"],"k":["即作即受","異作異受","如來藏","亦即亦異","五陰相續","優婆塞戒經"]},"2297-a10_036":{"s":"本集續講《優婆塞戒經》油燈喻：燈明由器、油、炷、火、人功等眾緣和合而成，油不是常法；並以明喻六入、油喻業種，說明如來藏所持業種令五陰有增有減、有彼有此。講者批評部分法師把「有彼有此」解為現象互生，並以《本生經》鼠咬衣的故事說明吉凶占卜不正確；最後以阿坻耶語、七世孫繼承財物為喻作結。","p":["燈明由眾緣和合而生，燈油也是無常","明喻六入、油喻業種，業種出生五陰十八界","有彼有此指業種與十八界，非現象互生","鼠咬衣本生故事：現象不能生吉凶","阿坻耶語、七世孫承財，喻即作即受、異作異受"],"k":["有彼有此","業種","六入","如來藏","緣起","異作異受"]},"2294-a10_037":{"s":"本集續講《優婆塞戒經》作者與受者的關係，以阿坻耶語、拉丁文及七世孫繼承遺產為喻，說明前後世五陰「即作即受，異作異受」，同一如來藏現行而非同一五陰。並引《中阿含經》都提子之父因增上慢轉生白狗的故事，及經文「五陰作業成已便過」之外道質疑；講者批評否定阿賴耶識執持業種的說法，最後講舍利弗、目犍連遊地獄見晡剌拏，目犍連遭外道打死入滅。","p":["拉丁文、遺產繼承喻前後世五陰","都提子之父因增上慢轉生白狗","白狗與其父是同一如來藏非同一五陰","講者批評「業果酬報系統」說無因","目犍連傳晡剌拏遺言遭外道打死"],"k":["即作即受異作異受","如來藏","業種","五陰","謗法","目犍連"]},"2296-a10_038":{"s":"本集先說目犍連被打死的過去世因緣：昔為修道人答頑童問寒時出言輕慢而遭石擊，說明業力佛亦不能違，應慎三業、勿謗正法。接著解釋經文橘子由酸轉甜、服藥、小兒學事三喻，說明業「待時待器」受報；引平實導師開示以「勢力、慣性」解釋業種，並說習氣藏於末那識。最後進入卷五〈雜品之餘〉，解說慳與慳垢。","p":["目犍連前世輕慢頑童而遭石擊","橘子、服藥、小兒學事喻業不失","業種即勢力，如物理慣性","業須待時待器方受報","習氣藏於末那識；慳與慳垢之義"],"k":["業種","待時待器","習氣","末那識","慳垢","因果"]},"2290-a10_039":{"s":"本集說明慳垢與無我背道而馳，解脫功德須從布施中得。以羅旬踰比丘的故事為例：他過去世慳貪，以泥沙放入沙門缽中，今生托缽常空，雖證阿羅漢仍吞泥土入滅，說明福德與解脫密切相關。並講法與次法、福慧兩足，聲聞種性與菩薩種性之別，最後解說經文智者行施不為報恩、求名等，而是為憐愍、破煩惱、入涅槃而施。","p":["慳垢之人難以捨我、實證無我","羅旬踰前世施泥沙，今生乏食","福德是證法的次法，福慧兩足","菩薩種性才得大乘開悟之法","智者行施無所求，為憐愍、破煩惱"],"k":["布施","慳垢","福德","次法","菩薩種性","無所求施"]},"2295-a10_040":{"s":"本集以狗控告人並「罰他作大富翁」的寓言，說明富貴而不行善比畜生更危險。接著解說《優婆塞戒經》卷五菩薩布施應遠離四惡、五法，以及施後不得勝妙果報的三事與不得上果的八事，並引《分別業報經》說大布施而多瞋、輕慢者轉生龍、金翅鳥等。最後以梁武帝與達摩論福德功德、誌公預言及侯景餓死武帝的傳說，說明因果異時、異世而報。","p":["狗的寓言：富貴不修善將受苦","菩薩施離四惡：破戒疑網邪見慳悋","施時五法、三事、八事皆不淨施","大布施而多瞋輕慢墮龍、金翅鳥","梁武帝事說福德功德與異世而報"],"k":["淨施","布施","福德與功德","異時而報","梁武帝","因果"]},"2292-a10_041":{"s":"本集說明善惡因果不能互相抵銷，並解說經文何謂淨施：具足色香味觸、如法得財、觀財無常、為破煩惱、淨自心而施。引平實導師開示，以「誰施、誰受，皆十二入」作五蘊空觀的布施，不求果報則報逐施主如犢隨母，求果則如市易。再講福田倍報，從施畜生百倍到施須陀洹無量報，強調四雙八輩才是真實福田，並以立足點平等說明福田差別。","p":["善惡業果各自受報，不能抵銷","淨施的五種條件與十二入觀","無所求施，報逐施主如犢隨母","施畜生百倍至施初果無量報","四雙八輩是真福田；立足點平等"],"k":["淨施","十二入","福田","四雙八輩","布施果報","無所求施"]},"2372-a10_042":{"s":"本集由正元老師講解《優婆塞戒經》卷五法施的內涵、殊勝與果報。說明四眾皆可法施，在家者若有證悟亦可說法，大乘以心出家為真出家，選擇善知識應依實證而非表相；助印、流通正法經書也是法施。再逐句解說經文：眾生聞法斷瞋、不殺、不盜、樂施等，施主未來世得上色、長壽、財寶、大力、安樂、無礙辯、信心明了，故法施勝於財施。","p":["法施是教人具信戒施多聞智慧","在家證悟者亦可法施，心出家為真","助印、流通正法書籍也是法施","法施得上色、長壽、財寶等果報","法施勝於財施，應隨分去作"],"k":["法施","財施","心出家","善知識","布施果報"]},"2345-a10_043":{"s":"本集講為亡者追福的正確觀念。先說「祖上積德、福蔭子孫」不合因果，有福父母多生有福子女是共業、物以類聚，報恩與索債為例外；依經文，子修善不能令父不墮惡道，因身口意業各別。再說明追福唯有墮餓鬼道者能得，生天、人、地獄、畜生皆不得，原因是餓鬼本因慳貪而常思念欲得；以財物供養修行人並請其呪願，可令餓鬼得大勢力、隨施隨得，乃至施蕩滌汁亦得福。","p":["祖上積德福蔭子孫不合因果","子女修善不能救父母不墮惡道","追福唯有餓鬼道亡者能得","供養修行人並呪願，餓鬼隨施隨得","以慈心施蕩滌汁亦得福德"],"k":["追福","餓鬼道","因果","自作自受","布施"]},"2376-a10_044":{"s":"本集補充追福之理：一生行善者不墮餓鬼，不需追福；盂蘭盆於自恣日供養聖僧可度七世父母，與此不相矛盾。接著依經文說祭祀時隨祠處由樹神、河神、舍宅神等受用，祭祀能令受者歡喜而得福、護身財，但殺生祭祀不能得福，應以香花乳酪等供養。再說布施福德命終不失，唯物壞、不用二時中失；最後解說一切施、不思議施及對十一種難施之人布施。","p":["盂蘭盆供養聖僧與追福不矛盾","隨祭祀處所由當地鬼神受用","殺生祭祀不得福，應用香花乳酪","福德命終不失，唯物壞不用時失","一切施、不思議施與十一種人"],"k":["祭祀","追福","不殺生","福德","一切施","不思議施"]},"2342-a10_045":{"s":"本集講《優婆塞戒經》卷五布施三根本：施貧窮為憐愍、施怨家不求報、施福德人為喜敬。並說勸人共同布施勝於獨作，因財少物惡而羞不施會增來世貧苦，引《賢愚經》老婢以一缽水供養迦旃延而生天的故事。再依財物、施心、福田三者勝劣說明五種果報差別，智者施時不貪果報；最後說不能布施之人與大施主之相，及南閻浮提人勇健、念心、身口意清淨三事。","p":["布施三根本：貧窮、怨家、福德人","勸人共作勝於獨自供養三寶","羞於少物不施，增長來世貧苦","財物、施心、福田勝劣決定果報","閻浮提人勇健、念心、三業清淨"],"k":["布施","福田","布施果報","大施主","施心"]},"2338-a10_046":{"s":"本集講布施後生悔心的六種原因：貪愛財物、諮承邪見、見受者過，以及畏他呵責、畏財盡受苦、見他施後受衰惱，並以銀行存款比喻三世因果。說明智者三時不生悔，能明信因果（從他聞法、內自思惟）、親近善友、不貪著財（觀無常、不自在），引《大智度論》說財物五家所共。最後解說布施與波羅蜜的四句，講者以只行救濟、不教如來藏與斷我見者為「有布施無波羅蜜」之例。","p":["施後生悔的六種原因","三世因果如存款，到期才得報","明信因果、親近善友、不貪著財","財物無常，五家所共","有布施無波羅蜜等四句差別"],"k":["布施","悔心","三世因果","善知識","布施波羅蜜","無常"]},"2301-a10_047":{"s":"本集講《優婆塞戒經》卷五智者布施的三個層次：捨外物、捨內外物、施後兼化眾生。談到器官捐贈時，講者提醒應附加麻醉條件，以免意識未離時受痛起瞋。接著解說「先教後施」：先問貧者能否受三歸、齋戒，不能則教說無常、無我、涅槃寂滅，或說諸法無性，教後再施；並以老人八萬劫前念一聲南無佛而得出家的故事說明結緣之重要，強調怨親無擇、先教後施才是大施主。","p":["智者施分三層：外物、內外物、兼化","器官捐贈應先麻醉以免受苦起瞋","先教三歸齋戒或三法印，然後施物","一聲南無佛之善根亦能得度","先教後施、怨親無擇名大施主"],"k":["大施主","先教後施","三歸依","三法印","布施","教化眾生"]},"2359-a10_048":{"s":"本集講無財者如何布施：可教有財者行施，或以身力佐助。依經文說可誦醫方咒術求藥施人，但講者強調須遵守現代醫療法規，小小戒可隨時地調整，並提醒勿用驅使鬼神的邪咒。再詳說瞻養病人的要點：不厭不淨、善巧說明飲食宜忌而不妄語、臨終教歸依懺悔、被罵默不報之、慎無責恩、病癒後所施可受而轉施，如是瞻病者名大施主。","p":["無財可教人施或以身力佐助","誦醫方須守法，勿用邪咒","瞻病不厭不淨，善巧說明不妄語","病重者教歸依懺悔，被罵默不報","慎無責恩，病癒所施轉施窮人"],"k":["布施","瞻病","無財之施","大施主","持戒"]},"2358-a10_049":{"s":"本集先說有財者亦應學醫方、設瞻病舍。主要解說《優婆塞戒經》卷五為行路人提供交通方便的布施：平整拓寬道路、險處施板梯繩索、曠路作井種果樹、立柱繫畜、作基埵供挑擔者休息、造客舍、架橋施船、扶助老弱過險、救護被追捕者、安慰失土破家者、為遠行者洗浴按摩、指示正道與非道，並舉奉茶、揹水隊、造橋團體與賑災為例，說明福德資糧須逐步修集。","p":["富者亦應學醫方、設瞻病舍","平治道路、險處施梯索","曠路作井、種樹、作基埵與客舍","架橋施船、扶老弱、救怖畏者","外門六度福德足，方入了義正法"],"k":["布施","無畏施","福德資糧","菩薩道","利樂眾生"]},"2373-a10_050":{"s":"本集講《優婆塞戒經》卷五生活起居的布施與供養：為修行人縫補鞋衣、修整缽盂；除遣鼠蛇毒蟲，引佛陀指示為清潔浴室而非為傷蟲，說明不構成殺生根本罪；施如意、耳鉤；為招提僧縫洗坐臥具、廁所置淨水澡豆灰土。並說新物先奉佛、父母師長，供佛之物以花香贖回，飲食先施沙門梵志；遠來者應軟語問訊、洗浴塗油。講者另主張常見問訊手勢源於外道雙修手印，建議改用合掌。","p":["為修行人縫補衣鞋、修整缽盂","為清潔而除蟲，不為殺生","施如意耳鉤，廁置淨水澡豆灰土","新物先奉佛，再請父母師長受用","遠來者軟語問訊，講者建議合掌"],"k":["供養","布施","供佛","問訊","殺生戒"]},"2369-a10_051":{"s":"本集由正圜老師接講〈雜品之餘〉最後部分，先說明菩薩道以布施為首，乃至等覺百劫修相好。經文說不能常施可於六齋日施，並教簡易記法；見盲者扶持施杖，見失財喪親者施財慰喻，說煩惱與福德二果，順帶解釋我所、我見、我執。講者指出經說在家作淨施主難，如今反而常是出家道場受阻，並說明正覺同修會以整理佛法為主、隨緣救濟。最後進入〈淨三歸品〉，說受三歸是為破苦斷煩惱、得寂滅樂。","p":["六度以布施為首，等覺百劫修相好","六齋日記法：白月黑月第八與末兩日","慰喻失親者，說我所我見我執","講者認為今在家作淨施主反較易","受三歸為破苦斷惱、得寂滅樂"],"k":["布施","六齋日","我見","我執","淨施主","三歸依"]},"2311-a10_052":{"s":"本集講〈淨三歸品〉，先解釋三苦（苦苦、壞苦、行苦），指出樂受亦不離行苦，無上寂滅之樂須斷我見我執，而非保持離念靈知。再說佛能說壞煩惱因令得正解脫；講者批評覺音《清淨道論》與阿姜曼的說法未斷我見，屬邪解脫。法是十八界、五陰虛妄等壞煩惱因之法，配合四聖諦、八正道斷我執；僧則秉受此法。並說三歸不可合為一歸，法常住而須佛分別、僧稟受，如來唯歸依於法。","p":["三苦：苦苦、壞苦、行苦","寂滅樂須斷我見我執，非離念靈知","佛能說壞煩惱因，令得正解脫","觀十八界、五陰虛妄以斷我見","三歸不可合一；如來唯歸依法"],"k":["三歸依","斷我見","三苦","正解脫","四不壞信","如來藏"]},"2314-a10_053":{"s":"本集續講〈淨三歸品〉，依經文說三寶各異如同佛、緣覺、聲聞各異，從發心、莊嚴、得道、性分四方面比較三乘菩提的差異，講者據此批評主張解脫道即成佛之道的說法。並說能解法故方便說佛即法，但佛不入僧數，否則無三寶、三歸與四不壞信；菩薩與法、佛與法亦不同，菩薩分後身與修道兩種，歸依後身菩薩名歸依法，歸依修道菩薩名歸依僧。","p":["三乘發心、莊嚴、得道、性分各異","解脫道不等於成佛之道","能解法故方便說佛即是法","佛不入僧數，三寶不可合一","歸依後身菩薩名歸依法"],"k":["三寶","三乘菩提","三歸依","解脫道","佛菩提道"]},"2313-a10_054":{"s":"本集續講〈淨三歸品〉，解說經文佛、法、僧的定義：觀有為過患獨處修行得甘露味為佛，無漏無為法界為法（須在法界功能差別中實證），受持禁戒、讀誦解說十二部經為僧。如來滅後歸依佛即歸依過去諸佛無學之法，佛在世與涅槃後供養果報無差別，並以懸受供養、遠方父母等喻說明。再說三說三歸即成優婆塞、優婆夷，以及應先歸依佛的理由，講者並以醉象故事說明佛威儀三業寂靜非阿羅漢所及。","p":["佛、法、僧三者的定義不同","無漏無為須在法界中實證","佛滅後歸依過去諸佛無學之法","佛在世與滅後供養果報無差別","三說三歸即成優婆塞，應先歸依佛"],"k":["三歸依","三寶","歸依佛","供養","優婆塞","解脫"]},"2318-a10_055":{"s":"本集依《優婆塞戒經講記》第六輯，講解經文「智者深觀生死之法是大苦聚」一段，說明為何歸依佛後應歸依法。指出三界生死法（含四禪八定、四空天）皆是大苦聚，充滿渴愛飢饉與怖畏險難，並解說無常見常、無我見我、無樂見樂、不淨見淨四種顛倒，唯有無上正法能斷除。","p":["三界一切生死法皆是大苦聚，四空天亦不例外","五欲生渴愛，心不滿足即是飢饉","四禪八定修證艱險，仍屬生死有為法","四倒：以意識離念靈知為常、為我、為樂、為淨","唯證無上正法能斷四倒，故應歸依法"],"k":["三歸依","歸依法","四顛倒","生死大苦","渴愛","離念靈知"]},"2315-a10_056":{"s":"本集講解《優婆塞戒經》說外道無慚無愧、非如法住，而佛與真僧少欲知足、得正解脫且能轉說，故應次歸依僧。並說明三寶次第：法在僧前，僧破法則不應歸依、弘法則應護持；再解說供養三寶、優婆塞得戒體的開遮，以及八關戒齋的內容與意義。","p":["外道執四禪八定為涅槃，無慚無愧、慳法不說","真僧少欲知足、如法而住、能為人轉說","法先僧後：僧說錯法應護法，說正法應護僧","善來比丘、少分受戒皆可得戒，戒有開遮","八關戒齋以過午不食為特點，種出家因緣"],"k":["三歸依","歸依僧","八關戒齋","優婆塞戒","戒體","開遮"]},"2317-a10_057":{"s":"本集講解《優婆塞戒經》卷五「淨潔身口意業…是名五陰」一段，說明受戒持戒者是五陰，以不受邪見、不說邪見、信受正見、說正見、修行正法五法持戒。並說明受三歸後信受外道法、為求生天受樂而行善如市易，即失三歸；而為護家宅身命祭祀諸神、以世俗禮敬自在天則不失歸依。","p":["持戒的是五陰，如來藏不受一切法","五法：不受邪見、不說邪見、信正見等","接受外道或自在天法義即失三歸","行善求生天受樂如市易，與解脫無關","為護身命祭祀諸神不失歸依，但不可歸依外道"],"k":["三歸依","失三歸","五陰持戒","正見","外道","開遮"]},"2312-a10_058":{"s":"本集講解《優婆塞戒經》卷五破斥外道邪見一段：一切物為自在天所作、投淵赴火自餓可離苦、時節星宿決定苦樂等說法。講者以同時同宿者果報各異、天與阿修羅勝負不同等理由逐一破斥，說明眾生苦樂皆由自己所造善惡業而來，並批評一神教造物說與修財神法之說。","p":["造物主之說與修善業得報自相矛盾","投淵、自焚、自餓本身即苦因，不能離苦","同時同宿者苦樂各異，星宿決定說不成立","流年惡宿須修善攘除之說亦自相矛盾","眾生苦樂皆隨業行，非由年宿時節"],"k":["破邪見","因果業報","自在天","造物主","星宿","三歸依"]},"2316-a10_059":{"s":"本集講解《優婆塞戒經》卷五經文，以阿闍世王、提婆達多造惡業墮地獄，鬱頭藍弗因邪見將墮大地獄，說明果報由業而非年宿。並解說「一切善法，欲為根本」、得決定聚，善法欲須配合正見智慧；以呼「南無佛」得度及給孤獨長者令胎兒受歸依為例，說明三歸須口自宣說。","p":["阿闍世王、提婆達多因惡業墮地獄，非因年宿","鬱頭藍弗執非非想定為涅槃，因邪見當墮地獄","一切善法以善法欲為根本，得決定聚離三障","善法欲依邪見成邪定聚，須有智慧配合","三歸須口自宣說，胎中受歸雖未成就亦能護之"],"k":["邪見","善法欲","三歸依","因果業報","斷我見","決定聚"]},"2374-a10_060":{"s":"本集以太虛大師「破邪崇正」一語，說明論辨法義是道非道並非說人是非，而是救護眾生的悲願。講解《優婆塞戒經》佛破自在天作佛之說，舉德護長者設火坑毒飯害佛、月光童子勸諫之事，並引平實導師《宗通與說通》，說明初迴向位菩薩應破邪顯正、救護眾生迴向正道。","p":["破邪崇正是在家及出家佛弟子的正行與職責","佛破「自在天作佛」與「一切皆自在天作」","德護長者以火坑毒飯害佛，反得悔悟","初迴向位加行以破邪顯正救護眾生為要","只施物資如丟救生圈，應教人脫離輪迴"],"k":["破邪顯正","外道","十迴向位","自在天","菩薩悲願"]},"2387-a10_061":{"s":"本集延續佛陀對外道的論析，講解《優婆塞戒經》中外道主張自在天造作眾生、解脫後回歸其身中、解脫是無常法等說，佛以「若無常者云何名為解脫」破之。講者並批評喇嘛教母子光明說與應成派中觀一切法空之見，引玄奘菩薩與師子光之辯，再述太子四門遊觀而出家，說明佛陀摧邪顯正出於大悲。","p":["一神教善神造萬物與惡魔災禍之說相矛盾","講者評喇嘛教母子合光成就法身為妄想","法身是第八識，無形無色亦無光芒","玄奘破師子光：中觀與瑜伽唯識不相違","解脫若無常，太子見老病死即應解脫"],"k":["解脫","破邪顯正","第八識","應成派中觀","玄奘","四門遊觀"]},"2384-a10_062":{"s":"本集講解《優婆塞戒經》「若能了了正見真我，是名解脫」，先破極微外道與性我相異外道之說，再引《大般涅槃經》說明真我即如來藏。講者說明斷我見須先認清五陰假我、依止善知識，舉舍利弗教目連調換弟子觀法之例，並說明二乘與大乘兩條解脫之路，及「不空空」的真解脫。","p":["見微塵、見性我相異皆非解脫","真我即如來藏，被煩惱所覆故眾生不見","須先認清五陰假我，依善知識斷三縛結","二乘滅十八界入無餘涅槃，菩薩證如來藏本住涅槃","真解脫是不空空，非一切法空的斷滅"],"k":["正見真我","如來藏","解脫","斷我見","無餘涅槃","般若"]},"2337-a10_063":{"s":"本集講解《優婆塞戒經》「若人能受三歸依者，是人乃能真見四諦」，說明三歸依是一切無量善法及無上菩提的根本。講者說明真正開悟須轉依如來藏的直心，必然歸依佛法僧而不再歸依外道神祇；只知密意未經參究則無法轉依，並引《大般涅槃經》說明淨三歸須親證第八識並轉依。","p":["見四真諦方能見性見我，三歸為無量善法根本","開悟必轉依如來藏直心，必歸依三寶","只知密意無參究過程，不能轉依、非開悟","初迴向位須破邪顯正，以種未來正因","淨三歸即親證第八識並轉依、發起菩薩性"],"k":["淨三歸","開悟","轉依","如來藏","四真諦","法身"]},"2277-a10_064":{"s":"本集說明《優婆塞戒經》所說「正觀四真諦」，先區分勝義諦與世俗諦，再述佛初度二商主與善生女受三歸五戒，以及以四聖諦三轉十二行度五比丘。詳解聲聞苦、集、滅、道四聖諦與八正道，並介紹大乘六種諦現觀，指出現觀智諦現觀為明心後轉依第八識的關鍵。","p":["凡有言說皆屬俗諦，第一義諦無言說","佛先度二商主與善生女，再度五比丘","四聖諦三轉：示轉、勸轉、證轉","知苦斷集證滅修道，八正道以正見為首","大乘六種諦現觀，以現觀智諦現觀為關鍵"],"k":["四聖諦","諦現觀","八正道","三轉十二行","解脫道","第八識"]},"2278-a10_065":{"s":"本集講解《優婆塞戒經》卷六「何等之人得三歸依」，說明須信因、信果、信諦、信有得道，並至心親近三寶、受善友教才得三歸。講者指出依止否定如來藏、主張六識論者即無歸依實義；又講解眾生無邊、人身難得一段經文，說明依善知識使五根成五力，方能自行簡擇。","p":["信因、信果、信諦、信有得道方得三歸","菩薩畏因眾生畏果，起念即是因","不信有得道者，依人不依法","依止六識論、否定如來藏者無歸依實義","人身難得，依善知識由五根成五力"],"k":["三歸依","信因果","善知識","五根五力","優婆塞戒","人身難得"]},"2349-a10_066":{"s":"本集講解《優婆塞戒經》卷六罪有性重與遮重，說明性重涉及心性缺陷，遮重則是佛所特別遮止，如酒戒與對因緣未熟者說第一義諦。以央掘魔羅受外道戒殺人而重罪作輕、後證阿羅漢，以及伊羅缽龍摘草不信佛語而輕罪作重墮龍身為例，勸誡於微小罪見大怖畏。","p":["罪分性重與遮重，五戒中酒戒屬遮重","對因緣未熟者說第一義諦亦屬遮罪","央掘魔羅受外道戒殺人，重罪作輕證羅漢","伊羅缽龍不信佛語而墮龍身，輕罪作重","外道戒多依貪欲而設，佛戒正向解脫"],"k":["性罪","遮罪","五戒","央掘魔羅","伊羅缽龍","持戒"]},"2375-a10_067":{"s":"本集講解《優婆塞戒經》卷六，說明未來人壽八萬四千歲時受戒與今惡世受戒果報相等，因三善根平等，且惡世持戒更費心力。並說明受戒者為天人守護、雖遭惡對心無愁惱、眾生樂來依止，進而論述戒定慧相輔相成及初果斷三縛結、具四不壞信。","p":["未來長壽時受戒與今世受戒果報相等","三善根平等，惡世持戒功德更大","持戒者天人守護，遭惡對而心無愁惱","戒為定慧之基，三者缺一不可","初果斷三縛結、具四不壞信，仍須七返"],"k":["持戒功德","三善根","戒定慧","初果","三縛結","四不壞信"]},"2275-a10_068":{"s":"本集講解《優婆塞戒經》卷六，說明五戒即五大施，令眾生離五怖畏，是最勝的無畏施，易修且不失財物，離此則不能證須陀洹乃至無上菩提。並講解五戒有慈、悲、喜、忍、信五善法圍繞，以及持戒能破邪見、離疑網、具正念、離惡覺觀，特別提醒口業與酒戒的輕重差別。","p":["五戒即五種無畏施，施無畏最為第一","口業易犯，應少說人是非、護人名譽","持五戒自在無礙，離此不能證初果","慈悲喜忍信五善法自然圍繞持戒者","飲酒依作意分輕重，藥用不犯"],"k":["五戒","無畏施","慈悲喜忍信","酒戒","妄語","布施"]},"2262-a10_069":{"s":"本集講解《優婆塞戒經》卷六「當先立制，我若不作要自剋罰」一段，以正覺四種修（修學知見、修習定力、修集福德、修除性障）對應經文布施、坐禪、修善、讀經、供養父母，強調菩薩戒須積極造善。並開始解說五戒五果，詳述無作果，再引《大乘本生心地觀經》以慳貪為例說明報果。","p":["初始修行當先立制，自誓作戒","經文諸行對應四種修","孝養父母是菩薩最基本的福德","菩薩戒不只防惡，懈怠不行善亦違戒精神","無作果是長久熏習成就的心性習慣"],"k":["五戒","五種果","菩薩戒","四種修","無作果","孝養父母"]},"2266-a10_070":{"s":"本集續引《大乘本生心地觀經》，以慳貪損他為例，說明地獄、畜生、餓鬼為三種正感之果，生人間貧賤則是餘報相似果；再解說作果與解脫果。並引《根本說一切有部毘奈耶》實力子阿羅漢遭誣謗的宿世因緣，說明報果、餘果與邪惡願的力量，以及布施與誹謗依福田不同而輕重有別。","p":["慳貪者歷地獄、畜生、餓鬼三正感之果","生人間貧賤不自在為餘報、相似果","作果是自然精進行善，終得解脫果","實力子宿世隨母誹謗，今世受誣謗","邪惡願隨福德成熟，誹謗阿羅漢過失極重"],"k":["五種果","報果","餘果","因果業報","邪惡願","布施"]},"2264-a10_071":{"s":"本集講解《優婆塞戒經》卷六優婆塞至寺廟親近比丘、諮問法味、聽受憶念、分別義理後轉化眾生，名為自利利他。講者以四種法要與四預流支對照說明，再詳解四宏誓願所含成佛綱要，並以《梵網經》「佛性常住、孝順心、慈悲心」及六祖自性偈說明自度度他的精神。","p":["親近比丘、聞法、憶念、轉化眾生即自利利他","四種法要即四預流支：親近善友等","四宏誓願涵蓋從發心到成佛的綱要","煩惱障與所知障須斷，方能成佛","佛性常住、孝順心、慈悲心為菩薩戒精神"],"k":["自利利他","四宏誓願","四預流支","梵網經","如來藏","煩惱障"]},"2270-a10_072":{"s":"本集講解《優婆塞戒經》卷六優婆塞「如法住」與「非如法住」：輕慢比丘求過聽法、奉事外道、深信日月星宿、教人作五惡、先取他物才辦事、典官估賣、計價治病與治已賣物、違官私制、犯客煩惱不懺悔、為身命作惡皆非如法住；自不作惡、不教他作、心不念惡則名如法住。","p":["輕慢比丘、奉事外道、信星宿非如法住","自不作而教人作五惡，亦非如法住","職業上收錢辦事、計價治病、偷斤減兩皆非如法","佛法中如來藏平等，不重男輕女","因客煩惱犯過應慚愧懺悔，不可為身命作惡"],"k":["如法住","優婆塞戒","客煩惱","懺悔","正命","如來藏"]},"2267-a10_073":{"s":"本集講解《優婆塞戒經》卷六「雖得人身，行於非法，不名為人」一段，說明如何依不堅固的身命財求取法身慧命。講者闡述善修正念即四念處，斷我見須具足福德、知見與未到地定；並以布施三輪體空、道路與電視影像為喻，說明五蘊剎那生滅、本無作者受者，而如來藏執持業種，故果報不亡。","p":["行於非法、不知懺悔者，不名為人","善修正念即四念處，先修五停心觀等方便","斷我見須福德、正知見及未到地定","觀一切法無常、無我、無我所","本無作者亦無受者，但如來藏持種，果報不亡"],"k":["優婆塞戒經","四念處","斷我見","未到地定","三輪體空","如來藏"]},"2269-a10_074":{"s":"本集續講《優婆塞戒經》卷六，說明於一切法心無取著、見一切法不得自在，並逐句解釋人身難得、難具諸根、難得正見、難得信心、難遇善友、難聞正法、難得受持。講者強調煩惱須「先以定動，後以智拔」，修福應迴向解脫與佛菩提，而非求來世福報，以不堅身命財換取法身慧命法財。","p":["心無取著，不落凡夫著相或外道以定為禪","煩惱對治：先以定動，後以智拔","四不壞淨須證初果斷我見方得","人身難得乃至難得受持，能如是觀名為人身","福德應迴向佛菩提，成為功德而非世間福報"],"k":["人身難得","優婆塞戒經","四不壞淨","先以定動後以智拔","福德與功德"]},"2263-a10_075":{"s":"本集講解以不堅身、財、命換取堅固身、財、命，並引玄奘所譯《本事經》對照：布施、持五戒、修四聖諦。講者說明觀三界無常、施戒保人身以求證法身，再講戒戒、定戒、無漏戒三戒，以及〈尸波羅蜜品〉中菩薩趣向菩提心堅固所具的四法。","p":["本事經：以不堅財身命貿易堅財身命","觀欲界至非想非非想皆無常，不求三界","施戒保人身，廣施世財以增法財，證四諦","三戒：戒戒、定戒、無漏戒","菩薩堅固四法：苦不捨如法、自在修忍等"],"k":["三堅三不堅","本事經","戒戒定戒無漏戒","四聖諦","尸波羅蜜","優婆塞戒經"]},"2268-a10_076":{"s":"本集解說「是菩提道初根本地，名之為戒」，說明此戒為廣義心地戒，亦名初地、導地、平地、等地、慈地、悲地、佛跡，並以如來藏平等慈悲說明之。接著講戒有諸天樂與菩提樂二果，應求菩提樂；並依經文分辨污戒（受戒後悔、求人天樂、為畏貧窮等而受戒）與淨戒。","p":["菩提道初根本地名為戒，指廣義心地戒","戒亦名平地、等地、慈地、悲地、佛跡","戒有二果：諸天樂與菩提樂，應求菩提樂","受戒後悔、求人天樂、為畏懼利養受戒為污戒","淨戒：不樂久處生死，觀人天樂與獄苦無差"],"k":["污戒與淨戒","菩薩戒","攝心為戒","菩提樂","如來藏","優婆塞戒經"]},"2265-a10_077":{"s":"本集續講《優婆塞戒經》淨戒經文：知業輕重、繫心修不放逸，失念、客煩惱暫起、小放逸亦得犯罪，說明菩薩攝心為戒嚴於聲聞戒。講者並述無相念佛成就動中定以轉看話頭參禪，再引〈羼提波羅蜜品〉生忍五事，強調先以定動、後以智拔，定慧等持。","p":["菩薩心地戒，一念起即決定業之善惡","繫心正念、藏六如龜，修不放逸","失念、客煩惱暫起、小放逸亦得犯罪","無相念佛成動中定，可轉為看話頭參禪","生忍五事：惡來不報、觀無常、修慈悲等"],"k":["淨戒","不放逸","無相念佛","忍辱","先以定動後以智拔","四正勤"]},"2353-a10_078":{"s":"本集依《優婆塞戒經》卷六「當觀三事不作惡行：自為、為世、為法」，探討持戒不犯的助力。自為是深信因果、如來藏執持業種；為世是生起慚愧，知天神、鬼神與佛菩薩、護法菩薩皆知己行；為法是受戒為求證三乘菩提並利益眾生，須恆心不退。","p":["戒依三界因果律制定，目的在助人成就","自為：深信因果，犯戒違背自己成佛目標","為世：慚愧心，天神鬼神及佛菩薩皆知己行","為法：受戒為證三乘菩提，須如雞抱卵不斷","菩提屬於眾生，利他中成就自他"],"k":["持戒","因果","慚愧","優婆塞戒經","菩薩戒","利益眾生"]},"2354-a10_079":{"s":"本集依《優婆塞戒經》卷六「受戒已修三善業，多聞布施，修定修善，供養三寶，名為莊嚴菩提」，逐項說明持戒與莊嚴菩提的關係：十善業以持戒為本，多聞莊嚴最勝，以種種善法攝眾生，並應供養三寶、知恩報恩。最後講有作戒與無作戒，說明持戒習性可帶到未來世。","p":["持戒對一切眾生，故得廣大福德","十善業以持戒為本，戒能杜塞惡趣","多聞莊嚴最勝，多聞有八種清淨","修定修善、以種種善法攝受眾生","有作戒成就後，來世可成無作戒自然不犯"],"k":["莊嚴菩提","十善業","多聞","供養三寶","無作戒","優婆塞戒經"]},"2356-a10_080":{"s":"本集講解《優婆塞戒經》卷六持戒與波羅蜜的四種關係：是戒非波羅蜜（聲聞、辟支佛戒）、是波羅蜜非戒（檀波羅蜜，如善來比丘）、是戒是波羅蜜（瞿陀身、仙人青雀事）、非戒非波羅蜜（世俗施）。並區分二乘出世間波羅蜜多與菩薩出世間上上波羅蜜多，提醒勿受邪戒，受菩薩戒應求善知識。","p":["波羅蜜即到彼岸；菩薩不滅五蘊而證彼岸","是戒非波羅蜜：受戒而尚未見道","是波羅蜜非戒：善來比丘頓捨煩惱成檀度","是戒是波羅蜜：見道菩薩持戒行忍，有道共戒","非佛所制的邪戒屬戒禁取，應當簡擇"],"k":["波羅蜜","持戒","道共戒","戒禁取見","優婆塞戒經","菩薩戒"]},"2330-a10_081":{"s":"本集說明戒行圓滿須至二地滿心「猶如光影」現觀，之前皆屬學戒。依《攝大乘論》講六度前前引生後後、後後清淨前前，再依《優婆塞戒經》卷六說明修忍、三昧、智慧、精進、多聞能增長尸波羅蜜；並指出只受小小戒、少欲知足而不憐愍眾生者，不能具足尸波羅蜜。","p":["二地滿心猶如光影現觀，方為真實持戒","六度前前引生後後，後後清淨前前","布施、忍辱、精進、禪定、智慧皆增長持戒","世間、聲聞、菩薩三種三三昧引生定道共戒","受小戒而不憐愍眾生，不能具足尸波羅蜜"],"k":["尸波羅蜜","六度","三三昧","攝大乘論","多聞","不放逸"]},"2357-a10_082":{"s":"本集將《優婆塞戒經》卷六一段開示分三部分說明離惡修善：口不說惡、耳不樂聞、不說世事、不住惡覺觀、不親惡友，名寂靜淨戒；見破戒惡人不生惡心而方便調伏、憐愍，不為身命破戒；食後修慚愧與不放逸，入村落如入刀林，攝護諸根。","p":["善法非顛倒且安隱，惡法反之","口不說惡、耳不樂聞，不樂說聽世俗事","遠離惡覺觀，不親惡友，名寂靜淨戒","見破戒惡人不生惡心，方便調伏並憐愍","慚愧與不放逸為修善防惡之根本"],"k":["寂靜淨戒","惡覺觀","親近善知識","慚愧","不放逸","攝護諸根"]},"2355-a10_083":{"s":"本集依《優婆塞戒經》卷六講持戒與攝護諸根：攝護諸根、四威儀不作惡、堪受眾苦不作邪命，輕重戒等生怖畏，遭惡時不犯小戒，離惡友並令眾生遠邪見、知恩報恩，即能具足尸波羅蜜。講者比較二乘藏六如龜的攝根法與菩薩以無相念佛都攝六根、不離六塵的方法。","p":["攝護諸根可免攀緣六塵引生煩惱","二乘法：藏六如龜，守意如城","無相念佛都攝六根，於動中保持淨念","菩薩不離六塵，觸知即止，不起攀緣","不作邪命、不犯小戒、令眾生遠離邪見"],"k":["攝護諸根","尸波羅蜜","無相念佛","邪命","動中定","破邪顯正"]},"2319-a10_084":{"s":"本集依《優婆塞戒經》卷六說明佛未出世時唯有十善法流傳，十善是人天乃至三乘菩提的根基，菩薩應從積極面行十善，不愚癡（不邪見）為其根本。再講雜心生雜煩惱、雜業、雜有、雜身、見雜色而起惡思惟、愛與業的輪轉，以及業報有正報餘報、受報先後的次第。","p":["佛未出世時，十善法由過去佛傳下","菩薩行十善：不殺而護生、不盜而布施等","十善如大地，人天及三乘皆依之成就","雜心→雜業→雜身，見雜色起惡思惟即無明","重業、臨終業、數習業、最初業先受報"],"k":["十善業","業報","惑業苦","異熟","邪見","優婆塞戒經"]},"2321-a10_085":{"s":"本集依《優婆塞戒經》卷六「風雲持大水…悉因眾生十業道故」，說明器世間由共業有情如來藏中共相種子所變生，三界唯心，世界成住壞空皆隨眾生業力。講者據經破斥大梵天造物及自然外道之說，並述極樂七寶池隨念佛願力增長、心淨則國土淨，以及各業所感的增上果。","p":["風雲即動能，執持四大與諸天宮","器世間由共業有情如來藏共相種子變生","世界成住壞空隨眾生業力而轉","世界非大梵天所造，亦非自然而有","心淨則國土淨；四季煩惱差別亦由雜業"],"k":["器世間","共業","三界唯心","如來藏","十善業","成住壞空"]},"2320-a10_086":{"s":"本集說明五陰世間的由來：五蘊顯示五種我事，五陰從業起、業因心起，由如來藏依業出生，所受為異熟果。依《優婆塞戒經》卷六講眾生異界異有、異命異名，業雖無量而歸為十；再引《大般涅槃經》說十惡上中下與十善四品分感三惡道與四洲，並述菩薩修十善的五種法。","p":["五蘊顯五種我事，被眾生執為真我","五陰從業起，由如來藏依業出生","異熟果：異時、異類、異地而熟","十惡三品感三惡道，十善四品感四洲","自作、他作、自他共作皆有業報"],"k":["五陰世間","十善業","異熟果","如來藏","業報","閻浮提"]},"2323-a10_087":{"s":"本集依《優婆塞戒經》卷六講十惡業道各有根本、方便、成已三罪，三者輕重不同。逐一說明殺生的根本（有他想、疑心斷命、動身作相或口說殺）、方便（求刀磨利、置毒作索）、成已（事後稱量受用、無慚自讚），以及偷盜的三事，最後開始講邪淫的根本罪。","p":["十惡業道各有根本、方便、成已三罪","殺生根本：決定要殺，含作相、口說殺","殺生方便：求刀磨利、置毒、設索","殺生成已：殺後受用、無慚愧、自讚憍慢","偷盜三事：移置異處、壞牆入舍、藏隱受用"],"k":["十惡業道","根本方便成已","殺生","偷盜","邪淫","優婆塞戒經"]},"2325-a10_088":{"s":"本集續講十惡業道三事：邪淫的根本、方便（遣使、信物、手觸、濡細語）、成已，並說明不論男女已婚屬他皆同。再講妄語，區分世間妄語與未證言證的大妄語，舉排場莊嚴、搆言語端、託人傳說等方便罪；最後講兩舌兼破和合僧的根本、方便、成已三罪。","p":["邪淫：對已婚屬他者起淫心，男女皆同","邪淫方便：遣使、信物、手觸、濡細語","大妄語是未證言證，屬地獄業","搆言語端、託人傳說亦成妄語方便罪","兩舌兼破和合僧，罪更重"],"k":["邪淫","大妄語","兩舌","破和合僧","根本方便成已","十惡業道"]},"2324-a10_089":{"s":"本集續講口業的惡口、綺語，以及意業的貪、瞋、癡各自的根本、方便、成已三罪。惡口含變容色與加油添醋；綺語含說欲事、非時之言及無義歌頌，講者並批評喇嘛教雙身法與錯悟偈頌屬綺語；癡為誹謗業因果、真諦、賢聖。結論是應捨十惡、勤修十善。","p":["惡口：變容色罵詈、加油添醋、恐嚇取財","綺語：說欲事、非時之言、無義歌頌","貪：貪他財物，設法使其轉入己手","瞋：打罵他人，故瞋罪重，應速和解","癡：誹謗業因果、真諦、賢聖，信受邪書"],"k":["十惡業道","惡口","綺語","貪瞋癡","邪見","十善業"]},"2322-a10_090":{"s":"本集依《優婆塞戒經》卷六說明十業道可一時兼作：妄語兼兩舌、再加惡口，或邪見、惡口、妄語、綺語四者並作（講者以網路誹謗正覺者為例）；貪瞋不同時，最多八事可一時成就。接著定義作色與無作色：無方便、未成已只得作色，有莊嚴且成已則得無作色，必受果報。","p":["兩舌必含妄語，可一時成就二業道","邪見、惡口、妄語、綺語可一時並成","貪瞋不同時，六處遣使自作二事可成八事","無方便未成已只得作色，不一定受報","有莊嚴且成已得無作色，熏入心田必受報"],"k":["作色與無作色","十惡業道","妄語","兩舌","業報","優婆塞戒經"]},"2326-a10_091":{"s":"本集依《優婆塞戒經講記》講解十惡業道的輕重差別：殺父母及辟支佛、偷三寶物、對生母或羅漢尼行淫、妄說壞僧為地獄重罪，並說明勝義僧、有根與無根誹謗之別；接著開始說明十惡業道各從貪、瞋、癡三因引生，講到殺生與劫盜。","p":["十惡業道有輕有重，重者入地獄","偷三寶物易犯，一分一毫不可動","壞僧含勝義僧，無根誹謗是地獄罪","兩舌破和合僧亦屬無間重罪","殺生、劫盜各從貪瞋癡三因而生"],"k":["十惡業道","壞僧","偷三寶物","勝義僧","貪瞋癡","優婆塞戒經"]},"2328-a10_092":{"s":"本集續講《優婆塞戒經》十惡業道從貪、瞋、癡引生：說明邪淫及妄語、兩舌、惡口、綺語四口業各三種起因，指出意業的貪瞋癡落實到身口才成業道；並勉勵學人在法上用功，以禪師先證道後補受戒為例。","p":["邪淫依貪、瞋、癡分三種","畏他殺而大妄語屬從癡生","破壞邪見之眾和合亦屬愚癡","意業未落實身口則有業無道","專心法上用功，自然不犯戒"],"k":["十惡業道","口四業","貪瞋癡","妄語","兩舌","業與道"]},"2327-a10_093":{"s":"本集先澄清禪師不受戒之說並非輕戒，而是攝心為戒、以法為上；再解釋修十善一一事中得三解脫指身口意脫離三界；最後依經說明十惡業道的正報為三惡道，餘果則包括人中短命、貧窮、言不見信，以及外物衰微、收成欠佳等。","p":["菩薩攝心為戒，專修種智福德除性障","十善得三解脫：離貪瞋癡出三界","十惡業正報為地獄、餓鬼、畜生","餘報：短命貧窮、言不見信、無親厚","眾生造惡致外物衰微、時節不定"],"k":["十惡業道","十善業道","三解脫","正報與餘報","性障","攝心為戒"]},"2370-a10_094":{"s":"本集依《優婆塞戒經》說明欲壞十惡果應修十善，說明北欝單曰、地獄等處的十善屬果報而非戒所攝；並講解欲界六天無方便罪、殺業一念中得，以及同死、事不成、不追成己、遣使殺、惡口敕殺、善心殺等情況的作罪與無作罪差別。","p":["北欝單曰四善、地獄五善，非戒所攝","欲界六天只有根本、成已二罪","作莊嚴而事不成只得方便罪","不追成己則無無作罪","遣使、惡口敕殺與善心殺的罪別"],"k":["十善業道","作罪與無作罪","根本方便成已","殺業","優婆塞戒經"]},"2371-a10_095":{"s":"本集破斥「三世五陰皆不住故殺無罪」的說法，依經說明殺業確實成就；並解釋「三業自得、七業自他」，意三業從自身得，身口七業從他人得；又說明口業亦有作與無作罪，以及正果與餘果的相似不相似，與誤殺第二人時只對本所欲殺者得作、無作罪。","p":["以五陰念念滅狡辯殺無罪不成立","禪師說無殺是從如來藏實相而說","三業自得、七業自他之意","口業亦具作罪與無作罪","正果依對象不同，餘果輾轉三道"],"k":["作罪與無作罪","殺業","業道","菩薩戒","正報與餘報","如來藏"]},"2368-a10_096":{"s":"本集正銘老師講殺戒的釋疑：色身與命根雖是無記，殺之仍得罪；王敕殺而臣稱善同罪；說明覺知心未斷前下刀仍屬殺，正死位以覺知心斷滅為準；並談墮胎、賣鼠藥、自殺不得殺罪、善心如醫師開刀不得殺罪、外道咒殺祀天，及隨喜殺生亦得成已罪。","p":["色命雖無記，殺之仍得殺罪","覺知心斷滅才是正死位","墮胎、賣鼠藥皆得作與無作罪","自殺不得殺罪，善心醫治亦無罪","隨喜讚歎殺生或破法亦得成已罪"],"k":["殺戒","作罪與無作罪","正死位","墮胎","自殺","隨喜"]},"2300-a10_097":{"s":"本集講解偷盜戒的釋疑：惡心強奪得作與無作罪，數取、寄時取、市易取亦得偷罪；說明教人取、誤取歸還、悔而送回不得罪，奴僕共有財物、虛報失物、許施二衣留一、轉施他比丘的罪別；並說明取命過比丘財物、佛前供物及漂流物的得罪對象。","p":["惡心劫奪與為生活偷取罪有別","偷後悔而歸還，不得偷罪","許施後轉施他人亦得偷罪","命過比丘財物依羯磨與否論得罪","家中佛堂供品可以禮拜香花贖回"],"k":["偷盜戒","作罪與無作罪","出口成願","三寶物","羯磨"]},"2391-a10_098":{"s":"本集講解邪淫戒的釋疑：在家人於非時、非處、非女、處女、他婦及自身行淫皆屬邪淫，並說明對畜生、屬僧女、繫獄、師婦、出家人行淫的罪及得罪對象；講者批評藏傳密宗雙身法將邪淫合理化；最後依重煩惱、輕煩惱分辨邪淫罪的輕重。","p":["非時、非處、非女、處女、他婦屬邪淫","對出家人行淫從親屬與王所得罪","道邊、塔邊、祠邊行淫得邪淫罪","講者批評雙身法為最重邪淫","邪淫依重、輕煩惱分重罪輕罪"],"k":["邪淫戒","雙身法","附佛法外道","重煩惱","優婆塞戒經"]},"2329-a10_099":{"s":"本集講解口四業的釋疑：說明不妄語須如實依見聞覺知而說，以疑心轉述、暗示自己開悟、說法故意保留、異音含糊說皆屬妄語；指出破相說而無覆藏不算妄語或綺語，舉辨正雙身法與律典為例；兩舌、惡口無論是否傷及前人皆得罪，無義語則是與三乘菩提無關的言談。","p":["未確知而轉述也屬妄語輕垢罪","暗示開悟、異音含糊說皆是妄語","破相而說、無覆藏，非妄語","兩舌惡口不論成敗，作已得罪","無義語即與解脫、佛道無關之語"],"k":["口四業","妄語","兩舌","惡口","無義語","破相說"]},"2286-a10_100":{"s":"本集講作罪、無作罪的釋疑：身三口四是業也是道，意三業只是業不是道；破斥「色身念念滅故無作罪」之說，以面與鏡像、射箭、獨舞、旋火輪為喻，說明依二諦有作與無作；殺父母羅漢因福田、報恩田而重；並指出執持業種者是如來藏而非意識。","p":["意業未落實身口，業而非道","以面鏡像喻說明從作生無作","依二諦，念念滅不壞世諦罪","殺父母羅漢重罪因福田報恩田","業種由如來藏執持，非意識"],"k":["作罪與無作罪","業與道","二諦","如來藏","福田","念念生滅"]},"2288-a10_101":{"s":"本集續講作罪、無作罪：身作善而口不善得雜果，說明身口七業有作與無作，意業只有無作；以重病須眾藥比喻須施設眾戒；解釋業障的來源，業是熏習而成的慣性，證悟後轉依如來藏即能轉業；並說明受惡戒者不殺時也常得殺罪，重於無戒殺千羊，善惡皆以心為根本。","p":["身善口惡得雜果","眾生惡多，須具眾戒治之","業是熏習累積的慣性勢力","轉依如來藏可轉變業力","受惡戒者不殺時亦常得殺罪"],"k":["作罪與無作罪","業障","惡戒","轉依","如來藏","心為根本"]},"2287-a10_102":{"s":"本集講解比丘聲聞戒只有身犯、口犯而無心犯，菩薩戒則以心為本；說明「有戒可犯名菩薩，無戒可犯名外道」，不受戒者無資格批評持戒者；並說明時具足、支具足才得戒，以鑽火喻得捨持毀皆隨於心，以及菩薩戒可從在家菩薩受或自誓受，受善戒得無量福，最後提到畜牧為惡律儀。","p":["聲聞戒無心犯，菩薩戒重心地","有戒可犯名菩薩，無戒名外道","時與支不具足則不得戒","得捨持毀皆隨於心","菩薩戒可從在家菩薩受或自誓受"],"k":["菩薩戒","聲聞戒","得戒","戒體","惡律儀"]},"2350-a10_103":{"s":"本集講解惡律儀：依經列出畜羊雞豬、釣魚網魚、殺牛、獄卒、獵狗、長弶、獵師、咒龍、殺人、作賊、兩舌、苦刑加人等十五種惡律儀，以及受寄抵謾、不知恩、大惡村主、毀戒無慚悔等，皆會失戒；講者批評修雙身法、否定如來藏者失去戒體，並說明立誓即得惡戒、得大罪。","p":["律儀是心意顯於身口的威儀","經列十五種惡律儀","不知恩、毀戒不懺悔亦失戒","講者稱修雙身法、謗如來藏者無戒","自己立惡誓即得惡戒、得大罪"],"k":["惡律儀","惡戒","戒體","懺悔","雙身法"]},"2351-a10_104":{"s":"本集講解捨惡戒的四時：得二根、捨壽、受善戒、斷欲結；說明惡戒只要立誓一緣即得，善戒須具信進念定慧五根故難得；並說出家人也應受持優婆塞戒淨口業，心不淨則不得具戒，善惡戒各有上中下品，以及五戒盡形壽受、八戒齋一日一夜受的原因。","p":["惡戒於四時中捨","惡戒易得，善戒須五根故難得","出家人亦宜持優婆塞戒淨口業","善戒、惡戒各分上中下品","五戒保人身、八戒種出家因緣"],"k":["捨惡戒","五根","善戒","五戒","八關齋戒","斷欲結"]},"2386-a10_105":{"s":"本集正源老師探討菩薩戒是一生受或盡未來際受：先以五乘佛法說明五戒為人乘、保人身故盡形壽受，八關齋戒為種出家因緣故一日一夜受；再說三聚淨戒須於三大阿僧祇劫持守，《梵網經》等菩薩戒盡未來際受，而《優婆塞戒經》的在家菩薩戒為一生受，可作後世受戒的基礎。","p":["五乘佛法依根性施設，唯一佛乘","五戒是人乘，須盡形壽受持","八關齋戒一日一夜，種出家因緣","一般菩薩戒是三聚淨戒，盡未來際受","優婆塞戒一生受，為後世受戒基礎"],"k":["菩薩戒","盡未來際受","五乘佛法","五戒","八關齋戒","三聚淨戒"]},"2388-a10_106":{"s":"本集說明五逆、七逆罪及無間地獄的五種無間，解釋出佛身血因色身是法身之器而成逆罪；說明報恩田與功德田，壞此二田即名五逆；再依《摩訶般若波羅蜜經》與《大智度論》說明毀謗般若的破法罪遠重於五逆，講者並批評大乘非佛說的學術主張。","p":["無間地獄有五種無間","七逆者現身不得戒，故稱七遮","壞報恩田、功德田名五逆罪","毀謗般若喪人法身慧命","破法罪遠重於五逆罪"],"k":["五逆罪","破法罪","般若波羅蜜","福田","無間地獄","七遮"]},"2285-a10_107":{"s":"本集探討五逆中的破僧與七逆中的破羯磨轉法輪僧：依《地藏十輪經》說明勝義僧、世俗僧、啞羊僧、無慚愧僧四種僧，依窺基說明理和、事和、辨事，指出大乘一人即可名僧；並說明破僧包括謗賢聖僧與破和合僧，破羯磨轉法輪僧則含別羯磨、謗羯磨僧及謗弘正法的菩薩僧。","p":["四種僧，勝義僧可現在家相","和合僧分理和、事和、辨事","大乘依如來藏，一人即名理和僧","破僧含謗賢聖僧與破和合僧","破羯磨轉法輪僧含三種情形"],"k":["破和合僧","勝義僧","羯磨","五逆罪","如來藏","梵網經"]},"2352-a10_108":{"s":"本集依《優婆塞戒經》說明造逆罪的三因緣：極惡心、不識福德、不見正果；以及成就逆罪的四事：實是父母且作父母想、惡心、捨心、作眾生想；並評曇無德、彌沙塞、薩婆多的主張，比較現代刑法的對象錯誤與方法錯誤，說明誤殺、異見、異殺皆不成就逆罪。","p":["造逆罪有三種因緣","具足四事逆罪才成就","異名異想殺父母仍得逆罪","母有異見、兒有異殺不得逆罪","對照刑法對象錯誤、方法錯誤"],"k":["五逆罪","殺父母","成就逆罪條件","優婆塞戒經","對象錯誤"]},"2389-a10_109":{"s":"本集依《優婆塞戒經》「殺父則輕，殺母則重」一段，說明五逆、七逆罪之間的輕重差別。以阿闍世王欲殺母的故事說明殺母重於殺父；再從福德、智慧比較，說明殺諸地菩薩重於殺阿羅漢；又說明出佛身血重於殺聖人，佛不在世時破壞如來藏正法亦等同出佛身血。破僧罪留待下集。","p":["殺母重於殺父，引阿闍世王欲殺韋提希之事","殺諸地菩薩重於殺阿羅漢，因福智與利生差異","殺身兼聖人的和尚、阿闍梨，罪重於殺一般聖人","佛為法本，出佛身血重於殺聖人","佛不在世時破壞如來藏正法即同出佛身血"],"k":["五逆罪","七逆罪","優婆塞戒經","出佛身血","殺阿羅漢","如來藏"]},"2390-a10_110":{"s":"本集續講《優婆塞戒經》「破僧復重出佛身血」，細分破和合僧、《梵網經》所列破羯磨僧與破轉法輪僧的意涵。以提婆達多立五法自立僧團、寶錦龍女轉法輪受記為例，說明佛滅後仍有菩薩轉法輪；並引《本事經》與窺基之說，論證破僧為逆罪中最重，提醒破僧口業極易誤犯。","p":["破和合僧：挑撥使僧團分裂","破羯磨僧含別作羯磨及毀謗主持授戒懺悔的菩薩僧","提婆達多立五法、立異師異道屬破轉法輪僧","寶錦龍女說法受記，佛滅後仍有菩薩轉法輪","破僧最重，屬口業易犯，學人勿自以為是"],"k":["破僧","破羯磨轉法輪僧","梵網經","五逆罪","提婆達多","布薩"]},"2273-a10_111":{"s":"本集依平實導師《優婆塞戒經講記》探討業的意涵：引《大寶積經》、《楞嚴經》、《成唯識論》說明惑業苦相續與業力不失。並論證五陰與虛空都不能持業，執持業種的是無覆無記、離能取所取的第八識阿賴耶識如來藏；再以悟達國師人面瘡故事說明業經百劫不亡，並區分善、惡、無記業。","p":["一切苦樂正報、依報皆由業所感","惑、業、苦使生死相續不斷","五陰與虛空皆不能執持業力","阿賴耶識無覆無記，如實執藏並酬償業種","悟達國師人面瘡示業力不失；無記業不改受報處"],"k":["業力","業種","阿賴耶識","如來藏","惑業苦","因果"]},"2274-a10_112":{"s":"本集續講業報能否轉變：依《優婆塞戒經》說明現報、生報、後報、無報四種業，以及時與果是否決定的四種業，並列出使果報決定的五種心態。說明因緣和合才生果，透過修身、修戒、修心、修慧及遇善知識可轉重為輕；引〈鹽喻經〉、「意畫煩惱，煩惱畫業，業則畫身」及世親偈頌說明轉變名言與我執習氣即能轉業。","p":["業依受報時間分現報、生報、後報、無報","常作無悔、歡喜作等五種情形使果報決定","修身、修戒、修心、修慧能轉重業為輕","鹽喻：善業福德稀釋惡業苦報","轉變名言、我執習氣即可轉變異熟果報"],"k":["業報","定業不定業","優婆塞戒經","懺悔","二取習氣","異熟果"]},"2347-a10_122":{"s":"本集依《優婆塞戒經》講忍辱波羅蜜生忍的五種因緣：惡來不報、觀無常想、修於慈悲、心不放逸、斷除瞋恚。講者說明安忍不是一味壓抑，可事後婉轉表達意見；並教人觀世間如戲、憐憫眾生、緣取三寶來對治瞋毒，以先意問訊等方便化解宿怨、攝受眾生。","p":["生忍五因緣：惡來不報至斷除瞋恚","安忍非壓抑，可事後婉轉溝通兼顧世間法","觀無常如看戲，並為生死預作準備","憐憫眾生，勿因己而障人學佛","先意問訊、和顏悅色可化解宿世惡緣"],"k":["忍辱波羅蜜","生忍","瞋恚","無常觀","慈悲","優婆塞戒經"]},"2348-a10_123":{"s":"本集講「樂修忍辱」，強調忍辱須依正理思惟生死過患，而非勉強硬忍。以安世高前世同學因瞋轉生為湖神大蟒、後經安世高度化的故事，說明不能安忍必受醜陋惡報；並舉為父母報仇者為例，說明殺害的地獄長劫苦報，勸以誦經迴向化解冤仇，亦說瞋恚損人緣與身體。","p":["忍辱須依正理，思惟生死過患方能樂忍","安世高同學因瞋轉生醜陋大蟒，終得度化","殺人報仇招地獄長劫苦報，於事無益","誦經迴向父母與仇人，化解冤仇","瞋恚損人緣與身體，和氣生財"],"k":["忍辱波羅蜜","瞋恚","因果報應","安世高","迴向","冤親平等"]},"2379-a10_124":{"s":"本集講精進波羅蜜，說明精進即四正勤：已生惡令斷、未生惡令不生、未生善令生、已生善令增長。勸初業菩薩受持菩薩戒、定期布薩懺悔，並以比丘尼說受戒功德、皮球入地獄即彈回等譬喻說明戒功德。又對比大乘精進兼攝眾生與二乘之遠離，並以五百蝙蝠聞法精進後成阿羅漢的故事作結。","p":["精進即四正勤，惡念萌芽即應翦除","受菩薩戒、布薩懺悔，持戒功德不因破戒而失","發菩提心者縱墮惡道，佛亦能救拔","大乘精進兼攝眾生，異於二乘遠離","五百蝙蝠忍火聽法，來生出家成阿羅漢"],"k":["精進波羅蜜","四正勤","菩薩戒","懺悔","菩提心","布施"]},"2380-a10_125":{"s":"本集續講精進波羅蜜，勉勵三賢位菩薩不貪身命、以威儀攝持正念、為法精進。舉善財童子參訪示現苦行的善知識、依智慧抉擇後跳崖為例；說明精進涵蓋為法、為眾生、為菩提；並詳述玄奘菩薩為求《瑜伽師地論》、寧西行而死不東返的事蹟，以及寶海梵志、平等如來度眾的大願。","p":["三賢位菩薩應不惜身命、以威儀攝正念","善財童子求法不惜身命，精進須經智慧抉擇","精進含為法、為眾生、為佛菩提勤行","玄奘為取《瑜伽師地論》西行，不退東返","寶海梵志、平等如來願度一切眾生成佛"],"k":["精進波羅蜜","玄奘","善財童子","瑜伽師地論","攝大乘論","願力"]},"2377-a10_126":{"s":"本集講禪定波羅蜜，說明禪定（靜慮）與明心見性的禪悟不同，打坐不等於開悟。以欝頭藍弗得非想非非想定卻發惡願、後墮為怪獸為例，說明無正知見的禪定非波羅蜜；講者批評部分道場名師未證初禪或追逐名利。並指出意識離念不能轉為真心，應先證如來藏，再依次第修禪定。","p":["禪定是靜慮，與明心見性的禪悟不同","欝頭藍弗有世間定而無波羅蜜，終墮惡道","修定前須先降伏五蓋","意識離念非真心，真心本來是真","應先明心證如來藏，再次第修禪定與種智"],"k":["禪定波羅蜜","靜慮","五蓋","明心","如來藏","身見"]},"2378-a10_127":{"s":"本集續講禪定波羅蜜，說明定三昧與慧三昧相輔相成，明心也須動中定力。性障未除而勉強靜坐只是貪愛定境，難以引發根本禪定；往生兜率天不必特修禪定。教人以怨親平等、探病慰問、修慈悲喜捨為禪定方便；並提及廣欽老和尚的四禪定力，說明菩薩約於三地滿心前精修四禪八定。","p":["定三昧與慧三昧相輔，明心須動中定力","性障未除勉強靜坐，只是貪愛定境","往生兜率天不必特修禪定","怨親平等、修慈悲喜捨是禪定前方便","廣欽老和尚四禪；菩薩三地滿心前精修禪定"],"k":["禪定波羅蜜","四禪八定","慈悲喜捨","怨親平等","五蓋","三昧"]},"2381-a10_128":{"s":"本集講般若波羅蜜，強調般若不只是讀經，須以前五度累積福德與功德資糧，福智兩足才成佛。以護欄喻戒，說明破戒可懺悔、慚愧懺悔皆是善法，但不可破見。講者批評以上師先於佛、以男女淫欲為法門的喇嘛教非佛法；並說明所知障、無明住地，勸人離慢、離嫉妒，親近善知識。","p":["般若須福德、智慧兩種資糧具足","戒如道路護欄，破戒可懺悔但不可破見","講者批評喇嘛教次第顛倒，非佛法","所知障即無明住地，破除需更多福德","離慢離嫉妒，如玄奘親近善知識"],"k":["般若波羅蜜","福德資糧","持戒","邪見","所知障","善知識"]},"2383-a10_129":{"s":"本集續講般若波羅蜜，說明佛十力等功德皆來自智慧度的修學；舉阿彌陀佛法藏比丘發願、菩薩住持無佛世界、無著菩薩上兜率天聽法為例。以神射手箭箭相續比喻菩薩向佛地前進、異於二乘中途寂滅；並說明菩薩應觀根器次第教化，如善財童子、玄奘不以出家在家或外道身分揀擇善知識。","p":["佛十力等功德出自般若智慧修學","法藏比丘發願攝受眾生成就極樂","菩薩如神射手箭箭相續，二乘中途寂滅","觀眾生根器與種性，方便次第教化","求法不以出家、在家身分揀擇善知識"],"k":["般若波羅蜜","十力","攝受佛土","二乘","根器","善知識"]},"2382-a10_130":{"s":"本集為《優婆塞戒經》系列最後一集，講者論證若說一切無自性即成斷滅戲論，如來藏真如是離言說、貫串因果而有自性之理。並以問答方式說明見聞覺知心與離念靈知都不是真心，意識不能持業種，須有平等鑑照的第八識；並以《大智度論》、《金剛仙論》說明大乘經的結集，勸人勿輕謗大乘。","p":["否定如來藏自性即成斷滅、戲論","四聖諦、十二因緣、般若皆依於真如","見聞覺知與離念靈知皆非真心","意識不能持業種，須第八識平等鑑照","引《大智度論》等說大乘經結集"],"k":["如來藏","真如","斷滅見","離念靈知","業種","大乘結集"]},"2575-a12_001":{"s":"本集為《起信論講記》導讀系列首集，介紹《大乘起信論》在漢傳各宗及中華文化中的地位，並說明全論以「一心二門」（心真如門、心生滅門）為架構。以拈花微笑、鏡子譬喻、達摩安心等說明真如心實有，並開始介紹五時三教中的華嚴時與阿含藏教。","p":["《起信論》為漢傳各宗共尊的根本論典","一心開二門：心真如門與心生滅門並時運作","離真如心則二乘涅槃成斷滅","禪宗所證涅槃妙心即《起信論》所說真如","論中涵蓋資糧、見道至修道成佛的次第"],"k":["大乘起信論","一心二門","真如","如來藏","禪宗","五時三教"]},"2576-a12_002":{"s":"本集續講五時三教：般若時為通教、唯識時為別教、法華涅槃時為圓教，五時同以如來藏為一味；並述慧遠、智者到玄奘、窺基的判教。隨後進入講記引言，說明未破參者似懂非懂屬正常，並依《地藏十輪經》、《佛藏經》說明真出家人以斷身見、證果為準。","p":["般若通教、唯識別教、法華圓教","五時教法同以如來藏為一味","玄奘、窺基依實證講三時教","未破參聽《起信論》似懂非懂是正常","四種僧：證果為勝義僧，成就身見不在僧數"],"k":["五時三教","判教","勝義僧","斷身見","依法不依人","一切種智"]},"2577-a12_003":{"s":"本集重申依法不依人、以斷身見證果簡擇出家師，講者並批評部分法師主張意識常住或雙身法。接著依講記說明三乘差別：迴心聲聞、具菩薩心行的泰國僧人、定性聲聞與辟支佛，並解釋別教菩提的總相智、別相智、道種智與一切種智，最後講歸敬偈並引介作者馬鳴菩薩。","p":["以修證斷結而非外相判定出家人","講者批評意識常住等說法為成就身見","迴心聲聞與定性聲聞、辟支佛之別","別教菩提以證真如、佛性為中心","總相智、別相智、種智至一切種智"],"k":["三乘差別","斷身見","總相智","道種智","別教","馬鳴菩薩"]},"2578-a12_004":{"s":"本集介紹馬鳴菩薩生平：原修外道，被富那夜奢以二諦及神通度化而成禪門祖師，其詩歌文學影響深遠，並述「馬鳴」之名由來與《佛祖道影》中的悟道公案。講者批評以文字優美判論為偽的學者，再引講記說明證悟即證如來藏，並批評應成中觀，舉長爪梵志說明其源於外道辯論術。","p":["馬鳴原為外道，被富那夜奢度化","《佛所行讚》等文學作品影響印度","七馬聞法悲鳴而得「馬鳴」之名","證悟內容唯一：親證各自的如來藏","講者指應成中觀源於外道不立宗的辯論法"],"k":["馬鳴菩薩","如來藏","禪宗公案","應成中觀","開悟"]},"2579-a12_005":{"s":"本集說明講者認為應成中觀非佛門之論，引寧瑪派上師之說及宗喀巴判初轉法輪為了義，並依講記指應成派否定七、八識，而阿含實有說及。接著介紹日本學界望月信亨與梁啟超主張《起信論》為中國偽撰的理由及太虛之駁斥，講者主張應依內容判斷，強調實證重於考據。","p":["講者認為應成中觀在無實證者時蔓延","引藏密上師之說駁「緣起故性空」","講記：應成派否定七、八識而阿含有說","望月信亨、梁啟超的偽論說及其理由","佛法中實證第一，考據其次"],"k":["應成中觀","大乘起信論真偽","第八識","實證","考據學"]},"2580-a12_006":{"s":"本集開啟「決定淨信大乘」系列，分兩層次：以三自性辨佛法與外道、辨大乘與小乘。講解歸敬偈中佛、法（體相海、無我句義）、僧三寶之義，說明「除疑去邪執」首在深信輪迴，並講作因前二項；講者批評寂天、月稱、宗喀巴之論，並引《六祖壇經》、《證道歌》說明辨正邪的必要。","p":["兩層次：佛法對外道、大乘對小乘","體相海即如來藏，無我句義含二無我","除疑首在深信輪迴，方能起信","作因一：令眾生離苦得樂，不求利養","引「出世破邪宗」說明法義須辨邪正"],"k":["決定淨信大乘","三自性","三寶","輪迴","大乘起信論作因","破邪顯正"]},"2581-a12_007":{"s":"本集講《起信論》作因三、四的「不退」，比較信不退、位不退、行不退等說法。接著說明佛法異於外道在於正確講說三自性：法身佛無形無相，蘊處界分類無可超越，輪迴因於四相；並解釋三歸後不禮外道、五戒對應財色名食睡，以及依四種修發起未到地定而斷我見。","p":["信不退在六信，位不退在七住明心","法身佛無形相，異於有形的造物主","輪迴源於依他起性上起四相","五戒分別對治財色名食睡","四種修發起未到地定，進而斷我見"],"k":["不退","三自性","三歸五戒","斷我見","未到地定","外道"]},"2582-a12_008":{"s":"本集從輪迴與記憶論證不生不滅法必定實存：若無輪迴則文明皆無意義；以語言消失、神童為例，指出色身與意識都無法儲存記憶。再引〈物理學與佛教〉一文，以《起世經》、成住壞空、阿那律天眼等說明佛是全知，但佛非全能，修行須自力轉變心性、斷我見。","p":["若無輪迴，死後一切文明痕跡無意義","色身刹那變異、意識會斷，皆不能持記憶","引科學三條件檢驗佛說的真實性","佛全知而非全能，須眾生自力修行","心性不改，業力不轉"],"k":["輪迴","不生不滅法","記憶","如來藏","佛全知","斷我見"]},"2583-a12_009":{"s":"本集辨大乘與小乘，說明所破的是毀謗如來藏的小乘說法，而非定性聲聞。從果報需有法儲存業種切入，逐一檢視六塵、六識、前五根、意根，論證蘊處界中無一法能持業種，唯第八識能受熏持種；並引《大智度論》「識種子」、三法印涅槃寂靜及六祖「含藏識」為證。","p":["所破為謗大乘的小乘說，非定性聲聞","善惡業報須有法儲存業種","六塵、六識、五根、意根皆不能持種","否定第八識則佛法同於斷滅見","《大智度論》亦說識種子入胎"],"k":["第八識","業種","十八界","大乘與小乘","如來藏","輪迴"]},"2584-a12_010":{"s":"本集先引Ian Stevenson輪迴研究中印度女孩Sukla等案例佐證輪迴，並駁斥輪迴觀念抄自婆羅門之說。主旨在只依四阿含證成阿羅漢不是佛，以證大乘必然存在：舉結集之需、女人不能成佛而有女阿羅漢、調御丈夫、馬陰藏相、迦葉向佛懺悔、佛最尊貴等理由。","p":["Stevenson轉世案例佐證輪迴實有","駁「輪迴觀抄自婆羅門」之說","若阿羅漢即佛，則無須結集經典","女阿羅漢存在，而佛不由女身成就","迦葉懺悔、佛最尊，證阿羅漢非佛"],"k":["阿羅漢非佛","輪迴","四阿含","大乘","第八識"]},"2585-a12_011":{"s":"本集講解馬鳴菩薩造論作因第五至第八：消除業障、調伏三毒；修正確止觀，對治凡夫與二乘畏隔陰之迷、不知實相的過失；如理作意思惟、得生佛前（以入初地證無生法忍為準）而信心不退；以及信樂大乘者所得的四項大利益。","p":["作因五：消業障，調伏貪瞋癡","作因六：正止觀，對治凡夫與二乘過失","不離如來藏說緣起性空方為如理作意","得生佛前即入初地成真佛子","作因八：信樂大乘有四種大利益"],"k":["大乘起信論作因","業障","止觀","如理作意","初地","無生法忍"]},"2586-a12_012":{"s":"本集補充作因：因後世眾生根欲不同、待悟緣別，故需造論，並說明佛滅後四種根器，本論為樂聞略論者而造。接著進入立義分，以玄奘「真唯識量」說明立宗，解釋「有法」即眾生第八識、如實不空，講者批評離如來藏說緣起性空的應成派，並辨如來藏與神我、梵我之別。","p":["佛世利根不須論，佛滅後需論輔助","四種根器，本論為樂略論者而造","立義分：先立宗旨，如真唯識量","「有法」指第八識，如實不空","如來藏離見聞覺知，異於外道神我"],"k":["立義分","有法","如來藏","緣起性空","神我","三界有"]},"2587-a12_013":{"s":"本集講「眾生心」即八識心王：前五識各有界限、意識詳細分別，意根處處作主，舉閃避石頭、接住寶珠為例。說明第八識不可明講，須經參究方能信受並生智慧，舉早期禪三明講者多退轉為證；最後說明三界各地所具識數，以及人間入四空定仍須依大腦勝義根。","p":["眾生心攝盡世間與出世間法","五識各有界限，即功能差別種子","意根恆時作主，依習慣運作","第八識須參究而得，明講反害人","三界中至少需意識、意根、阿賴耶識"],"k":["八識心王","意根","阿賴耶識","參禪","三界九地"]},"2589-a12_015":{"s":"本集說明所見並非外境，而是阿賴耶識依勝義根訊號變現的內相分，以戰車三稜鏡為喻，主張一切自心所現。接著依五位百法講解：八識心王、五十一心所（五遍行可勘驗開悟、五別境與阿賴耶不相應）、十一色法、二十四不相應行法及六無為法，並說涅槃本有而非修得。","p":["阿賴耶識變現內相分供七識了別","無外法可得，一切自心所現","以五遍行恆相應勘驗所證是否真心","阿賴耶識不與五別境心所相應","涅槃本有，修行只是去除輪迴性"],"k":["內相分","五位百法","心所法","阿賴耶識","唯識","涅槃"]},"2590-a12_016":{"s":"本集解釋阿賴耶識的「本來自性清淨涅槃」：本來無生故不滅、兼具空性與有性及能生所生、離見聞覺知不貪不瞋、不來不去不生不滅。說明真如、虛空、不動等無為法皆依如來藏建立，並講有餘、無餘、無住處涅槃，以及心真如相與心生滅相顯示大乘體相用。","p":["本來性：非父母所生，無生故不滅","自性兼具空性、有性與能生所生","清淨性：離見聞覺知，不貪不厭","無為法皆依如來藏涅槃性建立","心生滅相顯示大乘體相用"],"k":["本來自性清淨涅槃","四種涅槃","無為法","阿賴耶識","心真如門","心生滅門"]},"2591-a12_017":{"s":"本集辨空相與空性：蘊處界緣生緣滅，六識不具四遍，緣起性空是講諸法空相；空性則是遍一切時處界地、不藉他緣而存的第八識如來藏。依講記指出虛空是依色法邊際施設的「色邊色」，經中說空性「性如虛空」而非即虛空，並引《央掘魔羅經》空瓶之喻說明空性非斷滅。","p":["蘊處界緣起緣滅，故稱空相","六識心不具四遍，屬無常妄心","空性指具四遍、恆不斷的如來藏","虛空是色邊色，為施設的假法","空性如空瓶，非器不存而是中虛"],"k":["空性","空相","緣起性空","虛空","如來藏","三三昧"]},"2592-a12_018":{"s":"本集闡釋講記所說「度眾生和成佛兩大目標，正是正覺陀羅尼的根本手印」。依《佛地經論》說明陀羅尼為總持，解析〈正覺總持咒〉涵蓋三轉法輪及五位百法；再說手印為標幟印契。並說明成佛須攝取佛土、度化眾生，依《金剛經》解釋「滅度一切眾生」的意涵。","p":["菩薩不取無餘涅槃，為度眾與成佛","陀羅尼即總持，一法中持一切法","〈正覺總持咒〉涵蓋三轉法輪架構","手印為佛菩薩願力法德的標幟","攝取佛土須攝取、度化眾生"],"k":["陀羅尼","正覺總持咒","手印","度眾生","成佛之道","五位百法"]},"2593-a12_019":{"s":"本集說明陀羅尼有事持與理持。咒與手印亦有召喚族類之用，故有善惡邪正之分，佛禁咒殺及「行遮道法，邪命自活」，並勸勿持與鬼神相應之咒。依《大悲心陀羅尼經》說陀羅尼相貌指如來藏體性，並指出單誦〈般若波羅蜜多咒〉或持名念佛須先聞正確般若，理事俱持方圓滿。","p":["誦〈正覺總持咒〉並迴向有大功德","咒印可召喚族類，故有善惡邪正","佛禁咒殺及以咒術邪命自活","大悲咒「陀羅尼相貌」指如來藏體性","須先聞正確般若，理持事持並重"],"k":["陀羅尼","事持理持","持咒","大悲咒","般若波羅蜜多咒","一行三昧"]},"2594-a12_020":{"s":"本集依《起信論講記》解釋《大乘起信論》「此心生滅因緣相」中心真如的生滅相。講者以食物變壞、色身新陳代謝、六識刹那生滅說明有作用的法必有生滅，並指出如來藏心體無漏無為、恆不間斷，卻含藏種子流注而能生萬法，故不必視有為法為洪水猛獸。","p":["心真如有生滅相與不生滅相，須和合方有眾生","有作用的有為法必有生滅，段食以變壞為相","六識刹那生滅，才有覺知分別的功能","如來藏心體無漏，種子流注顯生滅性而成萬法","無漏有為法是成佛所需，不應捨棄"],"k":["心真如","生滅相","如來藏","有為法","無為法","種子流注"]},"2595-a12_021":{"s":"本集續講《大乘起信論》心真如的因緣相：第八識由阿賴耶識轉為異熟識、再轉為無垢識，此修行轉易過程即是因緣相。並詳述業感緣起、賴耶緣起、真如緣起三種緣起，說明它們合同生滅相，含攝解脫道與佛菩提道。","p":["第八識依修證由阿賴耶識轉異熟識、無垢識","業感緣起：善惡業種感生未來果報","賴耶緣起：一切業種與無明集藏於阿賴耶識","真如緣起：斷二障淨除種子，成佛地真如","三種緣起成就因緣相，含攝三乘佛法"],"k":["因緣相","阿賴耶識","業感緣起","賴耶緣起","真如緣起","異熟識"]},"2596-a12_022":{"s":"本集解說《大乘起信論》大乘的體大、相大、用大。體大指如來藏不生不滅、不垢不淨、不增不減，不可分割合併複製；相大指如來藏本具無量性功德而顯現萬法相；用大指能生世出世間善因果，菩薩依之成佛。講者並批評藏密「師弟同體」之說為妄想。","p":["體大：如來藏在染在淨性恆平等、無增無減","如來藏離見聞覺知，不可分割、合併、複製","相大：本具無量性功德，顯現有情與器世間","用大：能生世出世間善惡因果，菩薩依之成佛","體、相、用本無二別，如鏡與影像"],"k":["體相用","如來藏","心真如","不增不減","大乘起信論"]},"2597-a12_023":{"s":"本集先介紹馬鳴菩薩造《大乘起信論》的緣由：像法時期部派佛教未證本識而各自臆測、互相諍論。接著依《占察善惡業報經》界定真心與妄心，說明論中「心真如即一法界大總相法門體」指第八識如來藏，一切眾生五蘊皆依法身而有，並引出「諸法皆由妄念而有差別」留待下集。","p":["部派佛教未證本識，對實我各自臆測諍論","馬鳴菩薩造略論，令學人生大乘信","真心如如不異、離六塵分別、能生一切法","妄心為六識與意根，起念分別而虛偽不實","眾生果報皆依如來藏法身而有、建立、生長"],"k":["心真如","一法界大總相法門體","真心妄心","法身","部派佛教","占察善惡業報經"]},"2598-a12_024":{"s":"本集引《占察善惡業報經》解釋「一切諸法皆由妄念而有差別」：法身不可毀滅，眾生因無明起我見我執造業，而有三界六道差別。並說明「若離妄念則無境界差別」不是指意識修成無念，而是如來藏本無妄念、離語言文字；強調須建立真心妄心差別的正知見，再講「離心攀緣無有諸相」。","p":["法身不生不滅，煩惱斷後種子仍歸法身","眾生差別源於我見我執的妄念造業","意識修成無念仍屬境界差別相，非離妄念","如來藏離語言文字，文字只是指月之指","如來藏離心攀緣，無我相人相眾生相壽者相"],"k":["妄念","法身","我見","離語言文字","真心妄心","正知見"]},"2599-a12_025":{"s":"本集續講心真如「究竟平等、永無變異、不可破壞」，說明緣起性空與意識心都不具此體性，真如之名唯屬如來藏。接著解釋「一切言說唯假非實」與「言真如者亦無相，以言遣言」，引《金剛經》、《勝天王般若經》說明真如離言說；最後談眾生如何隨順悟入，舉雲門禪師公案為例。","p":["真如究竟平等、不可破壞，唯如來藏具此體性","緣起性空與意識心皆會壞滅，不能稱真如","一切言說唯假非實，須依義不依語","真如是言說之極，以言遣言非遣其實體","知無能說所說、無能念所念即為悟入"],"k":["真如","離言說","緣起性空","以言遣言","悟入","禪宗公案"]},"2600-a12_026":{"s":"本集說明禪師如何隱覆密意，令學人於「無能說所說、無能念所念」處悟入，並引一行三昧經文強調須先熏習般若正知見與六度福德。接著解釋論中真如依言說建立的兩義：真實空，究竟遠離不實之相，以此駁斥離念靈知為真如之說；真實不空，有自體、具足無邊功德能生萬法。","p":["禪師以機鋒隱覆密意，令學人離語言妄念悟入","一行三昧須先聞般若、如說修學","真實空：究竟遠離不實之相，顯真實體","離念靈知由修定而得，有生有滅非真如","真實不空：有自體，具無邊功德能生萬法"],"k":["真實空","真實不空","一行三昧","離念靈知","般若中道","開悟"]},"2601-a12_027":{"s":"本集引《勝天王般若經》說明我見障礙真實空觀，再解釋論中真實空的三個特色：與一切染法不相應、離一切法差別相、無有虛妄分別心。接著解說真如「非有相、非無相、非有無相」，舉紹修山主公案說明悟後須轉依；講者並批評憑猜測自稱開悟、收費教人開悟的做法。","p":["五陰妄執有我即生我見，障礙真實空觀","真實空與一切染法不相應、離差別相","如來藏無虛妄分別心，非多法假名施設","真如非有相亦非無相，能生萬象","悟後須轉依成功，舉紹修山主公案"],"k":["真實空","我見","非有相非無相","轉依","中道","虛妄分別"]},"2602-a12_028":{"s":"本集續講般若中道含攝兩邊而不落兩邊：心真如與五蘊同時同處，業種才能回熏改變，故說「非非有無相」。接著解說真如與五蘊「非一相、非異相、非一異相、非非一異相」，以水與波為喻，並引《大般若經》說明諸佛與有情真如非一非異。講者也批評六識論與藏密雙身法對空性的解釋。","p":["真如與五蘊同時同處，業種方能回熏改變","心真如非非有無相，非性空唯名","真如與五蘊非一非異，如水與波","諸佛與有情真如非一非異，須修行斷染","唯心真如可為一法界大總相法門體"],"k":["非一非異","般若中道","心真如","五蘊","六識論","轉依"]},"2603-a12_029":{"s":"本集先複習《大乘起信論》作因、立義、釋義、修信、利益五分架構，再解釋心真如門的「立空」與「真實不空」。心真如是妄分別心所不能觸，故立為空，但空性亦是名相；因從無妄念，顯真心常恆不變、淨法圓滿，故名不空；但祂自身亦無不空相，唯離念智能證。","p":["《起信論》五分架構與釋義三部分","心真如是妄分別心所不能觸，故立為空","妄念非有，空性亦空；所遮能遮皆無","真心常恆不變、淨法圓滿，故名不空","亦無不空相，唯離念智所證，本來離念"],"k":["心真如門","空性","真實不空","離念智","大乘起信論","如來藏"]},"2604-a12_030":{"s":"本集講解《大乘起信論》心生滅門：依如來藏有生滅心轉，不生滅與生滅和合非一非異，名阿賴耶識。講者區分狹義阿賴耶識（第八識如來藏）與廣義阿賴耶識（真妄和合），引《入楞伽經》、《大乘密嚴經》、《心地觀經》證明阿賴耶識即如來藏，並批評將阿賴耶識說成生滅法或另立第九、十識的說法。","p":["心生滅門指不生滅與生滅和合的阿賴耶識","狹義阿賴耶識即第八識如來藏，廣義含七轉識","引《入楞伽經》大海與波喻非一非異","《密嚴經》金與指環喻因地果地同一心體","眠熟後仍須常住心體執持種子"],"k":["心生滅門","阿賴耶識","如來藏","八識論","無垢識","非一非異"]},"2659-a12_031":{"s":"本集解釋《大乘起信論》「此識有兩種義，能攝一切法、能生一切法」。講者說明阿賴耶識直接出生意根、間接藉緣變生五色根與內相分、輾轉出生六識與萬法，並依正覺同修會的總持咒，說明五位百法如何次第由八識心王顯現，以證阿賴耶識為萬法根源。","p":["阿賴耶識能攝一切法、能生一切法","直接出生意根末那識，間接變生五色根與內塵","六識及萬法為阿賴耶識輾轉變生","依總持咒說明五位百法次第顯現","否定阿賴耶識則一切法歸於斷滅"],"k":["阿賴耶識","五位百法","八識心王","總持咒","唯識","萬法根源"]},"2660-a12_032":{"s":"本集為三集之首，先概說依阿賴耶識建立的六種覺：本覺為阿賴耶識本有、六塵外的覺照功德；不覺為凡夫未證本覺；始覺為七住位初證本覺；相似覺為以定伏念的錯誤覺悟；隨分覺為初地以上分證；究竟覺為佛地斷盡二障。最後開始解說論中覺義「心第一義性離一切妄念相」。","p":["本覺是阿賴耶識本有、六塵外的覺照功德","不覺：凡夫未證本覺；始覺：七住初證本覺","相似覺：以定伏念、無語言仍屬意識境界","隨分覺：初地至等覺分證，究竟覺為佛地","阿賴耶識離妄念，故能忠實執行因果"],"k":["本覺","始覺","相似覺","隨分覺","究竟覺","阿賴耶識"]},"2661-a12_033":{"s":"本集續講覺義：阿賴耶識離一切妄念相，故能無私履行因果；其本覺能覺照十方世界與眾生心想，故說「等虛空界，無所不遍」；「法界一相」即一切如來平等法身，眾生皆有。並解釋「以待始覺立為本覺，始覺即是本覺，無別覺起」，說明始覺是意識親證第八識本有覺照。","p":["阿賴耶識離妄念，故善惡業報不錯亂","本覺覺照十方世界與眾生心想","法界一相即一切如來平等法身","本覺本自具足，非修行而得","始覺是意識證實本覺，無別覺起"],"k":["本覺","始覺","法身","法界一相","阿賴耶識","因果"]},"2662-a12_034":{"s":"本集為六種覺的第三集，講解論中凡夫「前念不覺、後念制伏」仍屬不覺，二乘人及初業菩薩捨粗分別為相似覺，法身菩薩捨中品分別為隨分覺，佛地遠離微細分別為究竟覺。講者批評以定為禪、把無妄念當開悟的教法，並總結各覺的階位對應。","p":["以定制伏妄念雖名為覺，實是不覺","二乘及初業菩薩捨粗分別，名相似覺","初地法身菩薩捨中品分別（思惑），名隨分覺","斷盡塵沙惑、心根本性常住現前為究竟覺","總結不覺至究竟覺的修證階位"],"k":["不覺","相似覺","隨分覺","究竟覺","以定為禪","塵沙惑"]},"2663-a12_035":{"s":"本集解釋《大乘起信論》「能觀一切妄念無相，則為證得如來智慧」，指出妄念即對法界實相的虛妄想，而文字障是常見的妄念相。講者批評網名「悲智者」以經中無此字而否定第八識，並引《中阿含經》說明「無想定」有時指非想非非想定，其中想知不滅，不能確保解脫。","p":["妄念相指對法界實相的虛妄想","證第八識知法界實相，即一切妄念無相","文字障：以經中無此字否定第八識","無想即涅槃須以第八識存在為前提","《中阿含》無想定可指非想非非想定，想知不滅"],"k":["妄念無相","文字障","無想定","非想非非想定","第八識","滅盡定"]},"2664-a12_036":{"s":"本集續談無想定的三種意涵。講者說明解脫靠斷我見的智慧而非禪定，淨無想道不保證涅槃；引《長阿含經》證四禪無想天無想無覺知；並引《十誦律》輸毘陀一念知五百劫的完整經文，指出其恰可證明無想天中六識皆滅，批評「悲智者」節引經文；另舉《增壹阿含經》說明無想三昧。","p":["解脫依斷我見的智慧，不依禪定","淨無想道為修禪外道所設，非究竟涅槃","《長阿含》：無想天眾生無想無所覺知","輸毘陀一念知五百劫，顯無想天六識皆滅","無想定另可指三三昧中的無想三昧"],"k":["無想定","無想天","慧解脫","三三昧","斷我見","文字障"]},"2665-a12_037":{"s":"本集先總結三種無想定，說明以文字比對理解佛法即是妄念有相。接著解釋論中「心初起者但隨俗說，心尚無有，何況有初」，指出覺知心依心真如而有，眾生因無始無明妄念相續而不名為覺；妄念息則知心相生住異滅皆無相，並引《佛說大乘稻芉經》眼識五緣說明覺知心無自性、無我。","p":["文字比對而不實證，即是妄念有相","覺心初起是隨俗說，覺知心依心真如而有","眾生無始無明妄念相續，故不名為覺","心相生住異滅皆悉無相，一心前後不相應","《稻芉經》：眼識依五緣生，顯無我"],"k":["一心前後不相應","無始無明","妄念","心生滅","無我","稻芉經"]},"2666-a12_038":{"s":"本集引《稻芉經》眼識五緣，說明諸法前後同時不相應、無自性，由如來藏統合才有知覺；講始覺不異本覺，以及本覺隨染所生的淨智相，指出破和合識是證悟後破七轉識的真實性。講者批評某講記把破和合識解為破阿賴耶識，並以鏡與影像、海與浪作喻，說明要破的只是生滅部分。","p":["眼識五緣和合，諸法彼此無知、無自性","始覺不異本覺；相似覺、隨分覺、究竟覺","本覺隨染：如來藏記錄業行而不作主","破和合識即證悟後破七轉識的真實性","以鏡與影像、海與浪喻駁「破阿賴耶識」說"],"k":["破和合識","本覺","始覺","阿賴耶識","一心二門","淨智相"]},"2667-a12_039":{"s":"本集說明淨智相須依善知識熏習修行；講者批評把心生滅門說成以生滅的阿賴耶識為根本的說法，強調二門各攝一切法、展轉不相離。並說成佛時四智圓明也稱破和合識，引《金剛經》一合相；解釋「一切心識相即是無明相」，批評某外國禪師以無對象的覺察為禪，認為那仍落在意識境界。","p":["依法熏習須依善知識並累積福德","二門各攝一切法，是同一心的兩個角度","成佛四智圓明，亦稱破和合識","《金剛經》一合相：破我執後成一合相智","以覺知心為真即無明相；放空意識不是禪"],"k":["無明相","一心二門","一合相","四智圓明","破和合識","禪"]},"2668-a12_040":{"s":"本集說明心識相與本覺非一非異、非可壞非不可壞，並講解論文海水與波的譬喻：自性清淨心因無明風動而起七識波浪，風止浪滅而水性不滅。引六祖風幡公案，以睡醒、滅盡定、無想定、非想非非想定及阿羅漢托缽、富樓那尊者等例說明無明相，並指出如來藏、七識、無明風三者皆無形相。","p":["心識與本覺非一非異、非可壞非不可壞","海水與波喻：無明風動起七識波浪","六祖「仁者心動」公案","睡醒、出定、托缽等都屬無明相","如來藏、七識、無明風三事皆無形相"],"k":["無明風","自性清淨心","海水波浪喻","滅盡定","無想定","阿羅漢"]},"2686-a12_041":{"s":"本集講解「性淨心是動識本，無明滅時動識隨滅，智性不壞」：第八識流注種子而為七轉識的根本，自身不在六塵中動心。講者批評原始佛教否定七、八識的說法，舉阿含名色由識生為證；以瞋恨怨惱與阿難的習氣說明阿羅漢仍有習氣、勿輕評他人；並說菩薩留惑潤生，以及依淨智而起的不思議用相。","p":["第八識是七轉識（動識）的根本","講者認為阿含已密意說第七、八識","阿羅漢斷現行仍有貪瞋習氣，勿輕評人","菩薩留一分思惑潤生，動識自性不壞","不思議用相依淨智，隨眾生根性示現"],"k":["動識","自性清淨心","留惑潤生","阿羅漢","不思議用相","習氣"]},"2687-a12_042":{"s":"本集先說佛隨眾生根性與心量示現身相，並非不平等；接著講覺相四大義之一「真實空」：心真如猶如虛空，無形色而能容受、出生萬法，但不等於虛空（虛空只是色邊色）；又如明鏡顯現內相分五塵而不起覺觀。涅槃中覺相不可得卻不是斷滅，並引阿含「非我、不異我、不相在」說明有真實我。","p":["佛隨眾生根性心量示現不同身相","心真如猶如虛空，而虛空只是色邊色","如明鏡現內相分五塵而不起覺觀","涅槃中一切境界相及覺相不可得，非斷滅","阿含「非我、不異我、不相在」顯真實我"],"k":["真實空","虛空明鏡","心真如","涅槃","非我不異我","本覺"]},"2688-a12_043":{"s":"本集講覺相第二義「真實不空」：一切法種都含藏在心真如中，所以圓滿成就、無能壞性；所應斷的只有有漏種子，無漏有為法種不可壞，佛依此繼續受生度眾。天、人、地獄等境界都在自心如來藏中顯現，智體具無漏功德而能熏習眾生心。末段引出《勝鬘經》自性清淨而有染之難解，講者並批評假藏傳佛教與某導師兩股勢力。","p":["一切法種含藏心真如，圓滿成就無能壞","只斷有漏種子，無漏有為法種不壞","天、人、地獄境界皆在自心如來藏中現","智體具無漏功德，為熏習眾生心之因","自性清淨而有染難解；講者批評兩股勢力"],"k":["真實不空","無漏有為法","種子","如來藏","勝鬘經","自性清淨心"]},"2689-a12_044":{"s":"本集延續講者對假藏傳佛教及某導師應成派中觀一切法空見的批評，介紹平實導師2001年《邪見與佛法》中法義辨正無遮大會的聲明與規則，以及《狂密與真密》。接著回到論文，引《勝鬘經》說明如來藏是法界藏、法身藏、出世間上上藏、自性清淨藏，並解釋客塵煩惱（四住地）與上煩惱。","p":["講者批評應成派中觀的一切法空見","法義辨正無遮大會的聲明及規則","《勝鬘經》如來藏四種藏義","客塵煩惱即四住地煩惱","上煩惱：悟後探究成佛而起"],"k":["勝鬘經","客塵煩惱","上煩惱","四住地煩惱","應成派中觀","法義辨正"]},"2690-a12_045":{"s":"本集說明上煩惱（塵沙惑）唯有悟後菩薩才相應，以平實導師1990年破參後的疑問為例；續解《勝鬘經》剎那善惡心都不觸煩惱而仍有染，佛說此二法難知，故開悟者極少。講者批評某導師說阿賴耶識是有漏虛妄分別識，引《楞嚴經》「真非真恐迷」說明阿賴耶識非真非不真、非分別非不分別。末介紹禪淨班。","p":["上煩惱即塵沙惑，悟後方相應","自性清淨心不觸煩惱而有染，二法難知","實相難證，所以開悟者極少","阿賴耶識非真非不真，體恆常住","第八識不於六塵分別，講者駁其為有漏識說"],"k":["上煩惱","塵沙惑","勝鬘經","阿賴耶識","真非真恐迷","自性清淨心"]},"2691-a12_046":{"s":"本集說明《勝鬘經》「自性清淨而有染」與《起信論》「一切染法所不能染」並不矛盾：前者就第八識所藏的七識染種說，後者就心體自性說。分析七轉識，指出末那識恆時作主卻無證自證分；染污由七識熏習，種子藏於阿賴耶識而祂自身不染。以真氣作喻，說明悟後轉依其清淨性，才能熏習轉染成淨、發起四智。","p":["勝鬘與起信二說角度不同而一致","末那識恆時作主，無證自證分","七識熏成染種，阿賴耶識收藏而自性不染","智體具無邊無漏功德，悟後漸能運用","轉依清淨性，轉染成淨而發起四智"],"k":["末那識","自性清淨心","轉依","無漏功德","熏習","四智圓明"]},"2692-a12_047":{"s":"本集講第三義「真實不空離障」：佛地煩惱、所知二障永斷，住無住處涅槃。區分煩惱障（見思惑、四住地）與所知障（無始無明，障礙成佛）：前者要斷，後者要靠發菩提心、利樂有情來增長智慧而破。講者批評某仁波切「放棄所學」與達賴「所知障是煩惱障餘習」之說，並說明異熟識、無垢識的名稱。","p":["佛地二障永斷，住無住處涅槃","煩惱障與所知障的區別","破所知障須發菩提心、利樂有情","講者批評「所知障是煩惱餘習」等說","八地改名異熟識，佛地名無垢識"],"k":["所知障","煩惱障","離障","無住處涅槃","上煩惱","無垢識"]},"2693-a12_048":{"s":"本集講第四義「真實不空示現」：依離障法，隨所應化現如來種種色聲。講者批評達賴「一切法唯名言安立」及以意識細層面取代七、八識的說法，認為龍樹的空義依如來藏而說，並引《大般若經》說有真如可證。說明阿賴耶識如實收藏業種、隨業現果報；唯如來具十力，能隨眾生煩惱施設對治法門而示現。","p":["示現大義：佛隨所應化現種種色聲","講者批評唯名言安立、意識細心之說","阿賴耶識如實存業種，隨業現果報","唯如來具十力，能無功用示現","佛依眾生煩惱施不淨觀、慈忍觀等對治"],"k":["示現大義","如來藏","如來十力","阿賴耶識","業種","般若中觀"]},"2694-a12_049":{"s":"本集說明修學須依本離妄想言說的真實義心，信受如來藏需宿世善根。解釋不覺：落在意識境界，前念起惑、後念制伏仍屬不覺；進而說始覺、相似覺、隨分覺、究竟覺都依本覺，本覺淨智相、不思議用相對應體相用三大，並以迷方喻說明不覺。講者批評說第三轉法輪非佛說者。","p":["須依本離妄想言說之心修學","不覺：制伏妄念仍屬不覺","始覺、相似覺、隨分覺至究竟覺","本覺淨智相、不思議用相與體相用三大","迷方喻；「不怕念起只怕覺遲」仍是不覺"],"k":["本覺","不覺","始覺","究竟覺","淨智相","體相用三大"]},"2695-a12_050":{"s":"本集介紹不覺的三細相（無明業相、能見相、境界相），先講無明業相：不相應本覺而造身口意業。引趙州「佛與一切人煩惱」，舉貪口腹殺生、外道教唆、佛門營利違背因果、打坐求一念不生等例，指出根本在末那識，心動則有三苦。講者並批評宗喀巴《密宗道次第廣論》合理化貪欲。","p":["不覺三細相：業相、能見相、境界相","趙州「佛與一切人煩惱」","世俗、外道、佛門中的無明業相例","無明業相的根本在末那識","心動則有苦苦、壞苦、行苦"],"k":["無明業相","三細相","不覺","末那識","三苦","因果"]},"2731-a12_051":{"s":"本集回顧一心二門與阿賴耶識生滅、不生滅和合之義，講不覺第二細相能見相：末那識恆執阿賴耶識為我，推動業種流注而有見聞覺知等性，有能見才有境界相。以無相拜佛觀察妄念的生起，強調修三福淨業與次法；說明種子恆轉如瀑流與種子六義，並解釋「阿羅漢位捨」是捨阿賴耶性而改名異熟識。","p":["一心二門；阿賴耶識和合非一非異","末那識執我，推動業種流注成能見相","有能見相方有境界相，念念相續","無相拜佛可觀妄念，須修三福與次法","阿羅漢位捨的是阿賴耶性，改名異熟識"],"k":["能見相","末那識","阿賴耶識","種子六義","無相拜佛","異熟識"]},"2732-a12_052":{"s":"本集講不覺第三細相境界相：「以依能見，妄境相現」。諸法本離言說分別，差別出於妄心執取，阿賴耶識顯現諸法時平等不分別（以倉庫作喻），並說三自性。舉例說明損減執與增益執，講者並以宗教師稱達賴為觀音化身、三乘佛學院、達賴對自焚的言論等為凡夫境界之例；末說二乘執苦為真，菩薩則由境界實證如來藏。","p":["依能見而有妄境界相","阿賴耶識現法平等，差別出於妄心","依他起、遍計執、圓成實三自性","損減執與增益執；凡夫言說隨我所而變","二乘迷執苦為真；菩薩由境證如來藏"],"k":["境界相","三自性","阿賴耶識","增益執","損減執","遍計所執"]},"2733-a12_053":{"s":"本集講解《起信論》依虛妄境界緣而生的六種粗相之前二相。虛妄境界緣是如來藏所變現的內六塵相分，七識從未接觸外五塵。智相是七轉識了別六塵的慧心所，緣境生愛、非愛心，並非般若智，連細菌也有；相續相是依智而苦樂覺念相應不斷，以率爾初心、睡醒、小朋友認字等例說明。","p":["虛妄境界緣：如來藏所現的內六塵","智相是了別六塵的慧心所，非般若","依智相生起愛、非愛的心行","率爾初心仍是妄心，仍有分別","相續相：苦樂覺念相應不斷"],"k":["三細六粗","智相","相續相","內相分","慧心所","率爾初心"]},"2734-a12_054":{"s":"本集續講六粗相：以看花為例說相續相；執著相是依苦樂覺念相續而生執著；執名等相包括表義名言與顯境名言，指出覺知性不是佛性，受想行識皆屬「名」，講者並批評假藏傳以佛父、佛母稱雙身法；起業相是依執名而起意業、口業等；業繫苦相是依業受苦、不得自在。","p":["相續相：苦樂覺受延續不斷","執著相：依苦樂相續而生執著","執名等相：表義名言與顯境名言","起業相：心動即意業，進而口業","業繫苦相：依業受苦不得自在"],"k":["六粗相","執著相","執名等相","顯境名言","起業相","業繫苦相"]},"2735-a12_055":{"s":"本集總結三細六粗，講解「一切染法悉無有相，皆因無明而生起」：染法無常故可轉染成淨，以踢到石頭、中彩券說明無常觀的好處；引《央掘魔羅經》區分佛地解脫色與二乘無餘涅槃。染法以如來藏為根本因、無明為緣因（刀體與刀利喻）；講者批評意識極細心為輪迴根本之說；勸在日常中觀照三細六粗，止於相續相。","p":["染法無常，故可轉染成淨","佛地解脫色與二乘灰身泯智不同","染法以如來藏為因、無明為緣","意識極細心仍屬緣生，非輪迴根本","日常觀照三細六粗，止於相續相"],"k":["三細六粗","無明","無常觀","如來藏","依他起","三界唯心"]},"2736-a12_056":{"s":"本集講解《大乘起信論》覺與不覺二相中的「同相」：如種種瓦器皆同土相，無漏與無明的種種幻用皆同真相，即第八識真相識。七識心王依真相識出生，無明所生業相與三界五陰、阿羅漢與佛的無漏有為法，都是真相識的一部分體性，故皆同真相。","p":["瓦器同為土所成，喻覺與不覺的同相","七識心王由真相識流注出生，故同於真相","無明引生業相、業繫苦相，五陰皆為幻用","以大海與波浪喻幻用與真相識不異","阿羅漢托缽說法、佛八相成道亦是無漏幻用"],"k":["大乘起信論","同相","真相識","如來藏","無明","幻用"]},"2737-a12_057":{"s":"本集講解「一切眾生無始以來常入涅槃」：依第八識不生不滅、離見聞覺知的寂滅境界而說涅槃，若第八識會滅則無來世、睡後亦不能醒。並以三法印說明如來藏符合涅槃寂靜，批評誤解一切法空而謗經者；最後開始解說「菩提非可修相、非可生相」，指本覺為本有。","p":["依第八識不生不滅說眾生常住涅槃","第八識若滅則無來世，睡後亦不能醒","以電視機與螢幕影像喻生滅法依不滅心","如來藏符合三法印中的涅槃寂靜","本覺本有，非修行所生，引《楞嚴經》為證"],"k":["涅槃","第八識","三法印","本覺","一切法空","大乘起信論"]},"2738-a12_058":{"s":"本集續講《起信論》「菩提非可修相」至「智相不可得」：本覺功德本具，只需修除七識染污種子；菩提智則須修證而生，證悟仍畢竟無得。本覺無色相，不可將定中透明圓相誤認真心；所見色相皆如來藏隨染幻用；七轉識了境的智相亦無實體，故不可得。","p":["本覺功德本具，修行只是去除七識染污","三乘菩提智可修而生，親證本覺仍畢竟無得","真心無形無色，見無所見，非定中圓相","所見顯色、形色、無表色等皆隨染幻用","智相依七轉識了別而有，心真如無此相"],"k":["本覺","菩提","隨染幻用","智相不可得","明心","參禪"]},"2739-a12_059":{"s":"本集講解《大乘起信論》覺與不覺的「異相」：如瓦器各各不同。先以世間人類同中有異說明，再說第八識本覺與七轉識不覺了別相貌不同，七識又隨證量有染淨之別；不覺中有制伏妄念、住於前後念中間、緣起性空等種種異相，無漏法與無明亦各有異相。","p":["世間法本即同中有異、異中有同","覺指第八識，不覺指七轉識，了別相貌各異","制伏妄念或住前後念中間，仍是不覺","只講緣起性空會落入無因或斷滅","四智、六無為及一念無明、無始無明各有異相"],"k":["異相","七轉識","本覺","無明","四住地","大乘起信論"]},"2740-a12_060":{"s":"本集解說「生滅因緣者，謂諸眾生依心意識轉」：分辨禪師所說心意識指意識過現未，而本論指第八、七、六識。說明無明種藏於阿賴耶識，駁斥藏於虛空或由造物主主宰之說；入胎時唯有七、八識，意根分別相續、眠熟不斷，故有三世相續。","p":["心意識在不同經論中意涵不同，須看前後文","阿含說意識是意法因緣生，細意識仍生滅","無明業種藏於阿賴耶識，不在虛空","能見、能現、能取三相隨五根具足而現","意根恆審思量、分別相續，眠熟不斷"],"k":["心意識","阿賴耶識","意根","無明","八識","三世相續"]},"2757-a12_061":{"s":"本集講《大乘起信論》意根五種異名之一「業識」：無明力不覺心動。以一人多名、佛有無量名號說明異名的意義；意根依前世善惡業種決定入胎，貪、瞋習氣由意根延續到來世，並舉《大智度論》愛酪沙彌死後生為酪蟲為例。","p":["一法多名，可顯示其種種體性","入胎由意根依前世業種作決定","貪色、瞋人等習氣由意根延續到後世","愛酪沙彌貪著乳酪，死後生為酪蟲","意根執取塵境，是眾生輪迴的根源"],"k":["業識","意根","一念無明","入胎","習氣","輪迴"]},"2758-a12_062":{"s":"本集講意根第二異名「轉識」：依動心能見境相。說明七轉識隨塵境運轉，熏種子入如來藏；名相須依經論前提理解。意根心動喚起意識與前五識了別境界，以雷聲驚醒、看美女時心念往返為例，並說明入定、出定及無想定、滅盡定都依意根運轉。","p":["七轉識隨六塵運轉，為能熏，如來藏為所熏","心意識、我等名相須依經論前提理解","意根慧劣，心動後喚起意識、五識了別","睡中雷響驚醒，顯示意根從不睡覺","出無想定、滅盡定都依意根觸法塵"],"k":["轉識","意根","七轉識","熏習","無想定","滅盡定"]},"2759-a12_063":{"s":"本集講意根第三異名「現識」：現一切諸境界相。阿賴耶識在勝義根顯現六塵內相分，但祂恆而不審、全屬被動，現起境界的動力是意根的作意與遍計執性。舉眠熟時仍有塵境、臨終執取不捨、中陰入胎延續往世習氣等例說明。","p":["阿賴耶識在勝義根中現六塵內相分","現起境界的動力在意根作意與遍計執性","意根滅則阿羅漢入無餘涅槃，境界不現","眠熟無夢時仍有塵境，猶如明鏡現像","臨終執取與中陰入胎皆由意根推動"],"k":["現識","意根","遍計所執性","內相分","中陰身","阿賴耶識"]},"2760-a12_064":{"s":"本集講意根第四異名「智識」：分別染淨諸差別法。意根慧心所羸劣，但與意識和合運作、反覆熏習成記憶慣性後，能刹那直接分別，舉嬰兒學會尿髒、見唐裝同修即合掌、見怨家即走開為例；講者並以喇嘛教雙身法為例，說熏習正見後意根能直接遠離。","p":["意根了別慧低劣，須與意識和合運作","反覆熏習後，意根能不假思索作分別","例：嬰兒學會尿髒、見唐裝即合掌","講者批評喇嘛教雙身法，熏正見後能直接遠離","意根種種面貌法爾如是，佛法浩瀚"],"k":["智識","意根","熏習","遍計所執性","染淨","雙身法"]},"2761-a12_065":{"s":"本集講意根第五異名「相續識」（上）：意識常間斷，意根則恆作意相應不斷，此作意即我執，中陰身、投胎及菩薩留惑潤生都靠它。意根任持過去善惡業令無失壞，舉戰後創傷、臨終業鏡為例；已曾經事忽然憶念，參禪時往世悟境亦可能重現。","p":["意識會斷，意根恆作意相應不斷","中陰身、投胎與留惑潤生皆依意根","意根任持善惡業種，令不失壞","例：戰後創傷記憶、臨終業鏡現前","已曾經事忽然憶念，往世悟境可再現"],"k":["相續識","意根","任持業種","中陰身","留惑潤生","宿命"]},"2762-a12_066":{"s":"本集講相續識（下）：講者以平實導師閉關十九天參出往世所證、讀密教典籍即知雙身法偈意為例，說明「已曾經事忽然憶念」；未曾經事則妄生分別。相續識是實現因果的動力，阿賴耶識只執藏業種；另說心不見心、意根非大腦，以及失智症與俱有依、謗法果報的關係。","p":["往世所證經意根連結，今世可再現","未曾經事，意根指揮意識妄生分別","相續識是實現因果的動力，第八識只執藏","二乘藏六如龜，菩薩正念應對不失淨念","失智症關乎勝義根受損，講者說與輕謗正法有關"],"k":["相續識","意根","妄生分別","俱有依","因果","心不見心"]},"2763-a12_067":{"s":"本集總結「生滅因緣」真實義：三界一切皆以心為自性，依如來藏有生滅心轉，生滅與不生滅和合、非一非異，名阿賴耶識，一心攝八識；講者批評心外求法者。又說三界依眾生心種而現，無色界與地獄往生不經中陰，並舉輕謗阿羅漢墮畜生道為例。","p":["一切眾生依心、意、識才有萬法生滅","如來藏與七轉識非一非異，合稱阿賴耶識","心真如門與心生滅門攝盡萬法","無色界無處所，往生無色界與地獄不經中陰","三界六道境界皆由眾生心所造業種而成"],"k":["以心為自性","阿賴耶識","心生滅門","心真如門","中陰身","三界"]},"2764-a12_068":{"s":"本集講「心的自性」：原子彈、科技乃至以水為能源的設想，皆是眾生心的自性；一切法以心為主，以如來藏為因、無明業力為緣，從妄念而起，分別諸法即分別自心。又解說「心不見心」：第八識、意根不能反觀自己，意識須藉眾緣，並說無相念佛不是實相念佛。","p":["科技發明皆依眾生心種，故無可限量","一切法以如來藏為因、無明業力為緣","三能變識生起諸法，分別諸法即分別自心","八識皆不能單憑自己見自己","無相念佛是開悟的助緣，不是實相念佛"],"k":["心的自性","心不見心","三能變識","無相念佛","妄念","無明"]},"2765-a12_069":{"s":"本集以鏡喻講一切世間境界依眾生無明、妄念建立：鏡體如阿賴耶識，光影如無明妄念，七識滅即成無餘涅槃的真寂靜。接著解說論中「意識」：凡夫依相續識執我、我所而妄取六境；意識在睡眠等位會斷，不去後世；意根的相續只是相對而說，並說明觀想時偏用末那。","p":["鏡體喻阿賴耶識，光影喻無明妄念","七識滅盡即無餘涅槃，故說涅槃寂靜","意識依相續識執我我所，妄取六境","意識常斷不至後世，意根相續是相對說","佛以陰界入說明離念靈知亦屬虛妄"],"k":["無明","妄念","意識","相續識","無餘涅槃","我所"]},"2766-a12_070":{"s":"本集講意識又名「分離識」（神足通可離本識所在，且經意根為媒介而不直接觸阿賴耶識）與「分別事識」，並依五種惡見與我愛熏習而增長。接著開始解說「無始無明熏所起識」：一念無明令眾生輪迴，無始無明則要到菩薩探究實相時才相應，悟後才與上煩惱相應。","p":["意識經意根運作，不直接觸及阿賴耶識，名分離識","意識能細分別事相，名分別事識","依我見等五惡見與我愛熏習而增長","阿羅漢不探究成佛，未與無始無明相應","菩薩參禪破參打破無始無明，悟後才遇上煩惱"],"k":["分離識","分別事識","見愛熏習","無始無明","上煩惱","一念無明"]},"2787-a12_071":{"s":"本集講「無始無明熏所起識」即第八識：阿羅漢斷一念無明現行，仍有習氣種子與無始無明隨眠，故可迴心受生。說明阿賴耶性為能藏所藏我愛執藏，阿羅漢位捨的是阿賴耶性而非心體；講者並批評某法師與南傳認為留惑潤生的菩薩是凡夫的看法，說明七住以上已非凡夫。","p":["無始無明熏所起識指第八識，非凡夫二乘所知","阿羅漢位捨阿賴耶性，改名異熟識","阿含說無餘涅槃中有本際不滅","講者駁菩薩是凡夫說，七住以上即非凡夫","地上菩薩能斷思惑而故意留惑潤生"],"k":["無始無明熏所起識","異熟識","留惑潤生","五分法身","本際","阿賴耶識"]},"2788-a12_072":{"s":"本集續說留惑潤生的菩薩各階位都不是凡夫，並回應某法師月刊所說禪宗是無頭公案、明心沒有次第：講者認為真悟者讀公案與經教相契，但贊同對狂禪的批評，指其只破初參。並說明明心只是第七住，正覺同修會已依經教列出成佛次第。","p":["留惑潤生只留最後一分思惑，非凡夫","講者認為禪宗公案與經教相契，非無頭公案","狂禪祖師只得般若總相智，未知後續道次","摩訶衍落於離念靈知，故不能破外道","明心是七住，悟後仍須修相見道與種智"],"k":["禪宗公案","留惑潤生","明心","成佛次第","般若總相智","涅槃實際"]},"2789-a12_073":{"s":"本集說明無餘涅槃是五陰十八界滅盡、唯如來藏獨存；講者批評南洋所傳阿羅漢教人保持覺知，仍落在意識境界。再解說「解行地菩薩始學觀察」：解行為勝解與勝行，悟後才能觀察阿賴耶識的運作；並概述十信到七住的修學次第，須先斷我見再參禪。","p":["無餘涅槃是十八界滅盡，唯如來藏獨存","講者批評保持覺知的教法仍是意識境界","無始無明只有菩薩會相應，障成佛不障解脫","解行地即勝解與勝行，悟後始學觀察第八識","十信至六住次第修學，斷我見後參禪入七住"],"k":["解行地","無始無明","無餘涅槃","五十二位","十住位","斷我見"]},"2790-a12_074":{"s":"本集續講《起信論講記》第二輯，解說「無始無明熏所起識」唯有法身菩薩能少分知、唯佛能總明了。說明七住明心僅得根本無分別智，初地以上具五分法身故名法身菩薩；舉周利槃特伽為例說明阿羅漢未必有解脫知見；講者並批評藏傳佛教所說輪涅不二落於意識境界，指出真正輪涅不二唯是如來藏。","p":["七住菩薩僅有根本無分別智，屬少分中少分","初地以上具戒定慧解脫解脫知見五分法身","周利槃特伽能自證解脫卻不能為人說","真輪涅不二唯如來藏境界，非意識心","勝解行地菩薩智慧尚淺，不應起慢"],"k":["法身菩薩","五分法身","解脫知見","輪涅不二","異熟識","大乘起信論"]},"2791-a12_075":{"s":"本集講解《起信論》「以其心性本來清淨，無明力故染心相現」一段前半，並引《勝鬘經》自性清淨心而有染污難可了知相印證。說明第八識本性清淨、內含七識染污種子而自體不變；並釐清本性無分別是第八識本來如此，非靠打坐把意識修成無分別，悟後意識仍須如理分別。","p":["第八識心性本來清淨，非修行後才清淨","引《勝鬘經》：自性清淨心而有染污難知","第八識含藏染污種子，自體常明潔不變","無分別是第八識本性，非打坐修成","有分別意識與無分別第八識和合運作"],"k":["自性清淨心","根本無分別智","勝鬘經","如來藏","後得無分別智"]},"2792-a12_076":{"s":"本集講解《起信論》「雖復遍生一切境界而無變易」及「不覺一法界故，不相應無明分別起，生諸染心」。引《楞伽經》說如來藏能遍興造一切趣生而離我我所；解釋心不相應無始無明住地、無明非實體法，須先找到如來藏才說打破無明；並以《勝鬘經》說明無始無明力最大，一念無明只是其中小部分。","p":["真妄二心體性不同，妄心不能修成真心","如來藏遍生諸趣而自體離我我所不變","心不相應無明須探究實相時才相應","先證如來藏才說打破無始無明，非倒果為因","一念無明僅是無始無明中的小部分"],"k":["無始無明","心不相應無明住地","如來藏","一念無明","勝鬘經","楞伽經"]},"2793-a12_077":{"s":"本集先區分一念無明（煩惱障、見思惑）與無始無明（所知障、塵沙惑），說明阿羅漢只斷一念無明，明心者才能打破無始無明。接著列出《起信論》無始無明所生六種染心及各自斷除的階位，並詳解論中「相應」與「不相應」的意義：心與分別異、知相緣相同處為相應，心不覺、常無別異、知相緣相不同為不相應。","p":["一念無明為煩惱障，無始無明為所知障","明心打破無始無明，同時斷三縛結","六種染心各於不同階位遠離或滅除","相應：心分別異、知相緣相同","不相應：心不覺、常無別異，如爬樓梯喻"],"k":["六種染心","無始無明","一念無明","所知障","煩惱障","相應不相應"]},"2794-a12_078":{"s":"本集講解六種染心的前兩種。執相應染指意識相應的斷續我執，包括俱生分別及邪分別、邪教導所生的我執（如以離念靈知為真如），聲聞緣覺及信相應地菩薩能遠離。不斷相應染指意根恆審思量的俱生相續我執，信地菩薩少分離，並說明初住至十迴向的修行次第，須至初地淨心地才永盡。","p":["執相應染是意識相應的斷續我執","我執有俱生、邪分別、邪教導三類來源","不斷相應染是意根恆審思量的相續我執","意根須依阿賴耶識及六識才能伶俐作主","歷三賢位與十六品心，至初地淨心地永盡"],"k":["執相應染","不斷相應染","意根","我執","末那識","大乘起信論"]},"2795-a12_079":{"s":"本集講解第三種分別智相應染，指意識分別所生的斷續法執，從具戒地乃至具慧地少分離、至無相行地永盡。說明具戒地為二地滿心，並詳述二地修除邪行障成猶如光影觀、三地修四禪八定五神通成谷響觀、四地依安立諦十六品心及真諦三品心成水月觀等各地修證內容。","p":["分別智相應染即意識分別的斷續法執","具戒地是二地滿心，戒行自然具足","二地修除邪行障，成猶如光影現觀","三地修禪定神通，成谷響觀","四地觀四諦十六品心，成水月觀"],"k":["分別智相應染","具戒地","具慧地","十六品心","法執","十地"]},"2796-a12_080":{"s":"本集續講分別智相應染，說明五地證無差別真如、六地細觀十二因緣而自然證滅盡定、七地無相觀任運而念念入滅盡定，故於無相行地斷盡此染。接著介紹第四種現色不相應染，屬末那相應、意識不能了知的障礙現色染污，至八地色自在地得引發如來無量妙智三昧，變相變土任運自在而除滅。","p":["五地觀生死涅槃無差別，斷下乘涅槃貪","六地細觀十二有支，少分離分別智染","七地無相觀任運，念念入滅盡定","現色不相應染屬末那相應，意識不知","八地無功用任運變相變土而除滅"],"k":["分別智相應染","現色不相應染","滅盡定","無相觀","八地","色自在地"]},"2812-a12_081":{"s":"本集講解第五種見心不相應染，屬七轉識都無法了知的極微細所知障，九地斷一分、十地再斷，至心自在地十地滿心才滅除。詳說九地所修法、義、辭、樂說四無礙，以總持如粽繩為喻；又說明十地大法智雲、諸佛放光灌頂與大神通，並須斷微細祕密無明與大神通無明才成受職菩薩。","p":["見心不相應染極細，八地菩薩亦不能知","九地修法義辭樂說四無礙解","總持如提起整串粽子的繩結","十地成就大法智雲，得諸佛灌頂","斷兩種無明後於心自在地滅除"],"k":["見心不相應染","四無礙","大法智雲","九地","十地","所知障"]},"2879-a12_082":{"s":"本集講解第六種根本業不相應染，分為根本不相應染（極微細所知障）與業不相應染（極微細俱生煩惱障種），兩者相通，須由等覺入佛地時斷除。說明等覺菩薩百劫修相好、內外財施，及最後身菩薩八相成道、四智圓明；並講述真如緣起之義，講者認為《起信論》不應被說為外道論。最後總複習六種染心。","p":["根本業不相應染含極細所知障與煩惱障種","等覺菩薩須百劫修相好，捨內外財","成佛時斷盡異熟種子，無垢識現前","真如緣起門非外道法","總複習六種染心與五十二位修證"],"k":["根本業不相應染","等覺","百劫修相好","無垢識","真如緣起","六種染心"]},"2880-a12_083":{"s":"本集講解《起信論》「染心者是煩惱障，能障真如根本智」。說明煩惱障令人追逐欲求、性障重者難以破參，世智聰明者也可能因煩惱障而落於我見；解釋根本智是初證如來藏總相、後得智是悟後觀別相，廣義根本智則至佛地無垢識。後半開始說明「無明者是所知障」，即無始無明塵沙惑。","p":["六種染心即煩惱障，能障真如根本智","性障深重者難以破參明心","根本智證總相，後得智觀別相","廣義根本智指成佛時無垢識大圓鏡智","無明即所知障，菩薩斷我見異於二乘"],"k":["煩惱障","根本無分別智","所知障","性障","後得智","真見道"]},"2881-a12_084":{"s":"本集講解「無明者是所知障，能障世間業自在智」。說明狹義業自在為菩薩於生死業得自在，廣義依《華嚴經》列壽命、心、資財、業、受生、勝解、願、神力、法、智十種自在；並依十地十種重障、十種真如說明所知障如何障礙各地，指出業自在智須從明心證如來藏開始逐步修成。","p":["業自在：於三界種種業得自在","十地菩薩具十種自在","十地各有一重障，斷之證一分真如","異生性障至於諸法未得自在障","業自在智須從明心證如來藏起步"],"k":["所知障","業自在智","十種自在","十種重障","十種真如","十地"]},"2882-a12_085":{"s":"本集講解《起信論》「以依染心，執著無量能取所取虛妄境界，違一切法平等之性」。以視網膜成像說明所見山水只是如來藏所現內相分；說明一切法性平等、寂滅、無有生相，皆歸如來藏；並解釋無明不覺故不能如實知世間境界業用，以量化寬鬆揮霍福德為例，強調見道為首要。","p":["染心七轉識執取能取所取虛妄境界","所見所聞皆是如來藏變現的內相分","大乘須證離二取的第八識並轉依","一切法性平等寂滅、無有生相","無明不覺故不能如實知境界業用"],"k":["能取所取","內相分","一切法平等","如來藏","無生","見道"]},"2883-a12_086":{"s":"本集講解《起信論》心生滅相分粗細二種：粗為相應心（意識意根之六粗相），細為不相應心（如來藏流注之三細相），並引「無明不覺生三細，境界為緣長六粗」。指出粗中之粗即執相應染，是凡夫智境；凡夫的四禪八定、數息法亦屬此類，講者並批評南傳部分禪師保持覺知觀照未斷我見。","p":["心生滅相分粗相應心與細不相應心","三細六粗皆因無明不覺而起","前三染屬粗法，後三染屬細法","粗中之粗即執相應染，凡夫智境","四禪八定、數息觀照不能斷我見"],"k":["三細六粗","相應心","執相應染","粗中之粗","斷我見","禪定"]},"2884-a12_087":{"s":"本集講解「粗中之細及細中之粗是菩薩智境」。粗中之細指不斷相應染與分別智相應染，屬第一、二大阿僧祇劫所修除；細中之粗指現色不相應染與見心不相應染，屬第三大阿僧祇劫，分別於八地、九地以上遠離。細中之細為根本業不相應染，佛地方盡，並述四智圓明，講者也批評訶佛罵祖之作為。","p":["粗中之細：不斷相應染與分別智相應染","七住證如來藏，入內門成實義菩薩","細中之粗：現色與見心不相應染","細中之細為業相，佛地才究竟遠離","佛地四智圓明，應恭敬佛像三寶"],"k":["粗中之細","細中之粗","三大阿僧祇劫","不相應染","四智圓明","菩薩智境"]},"2885-a12_088":{"s":"本集講解《起信論》「此二種相皆由無明熏習力起…因是不覺，緣是妄境」一段。說明證如來藏後不覺因漸斷、妄境緣漸滅，三種相應染心生滅相隨滅；不覺因滅則三種不相應染心的種子流注生滅相滅，強調滅的是生滅相而非第八識心體。並解釋佛地無住處涅槃不住生死亦不住涅槃，唯佛地方稱常樂我淨。","p":["粗細生滅相皆依不覺為因、妄境為緣","證如來藏後智慧生，不覺因漸斷","緣滅則三種相應染心生滅相滅","因滅是種子流注生滅相滅，非心體滅","佛地無住處涅槃方稱常樂我淨"],"k":["無明不覺","相應心","不相應心","無住處涅槃","留惑潤生","常樂我淨"]},"2886-a12_089":{"s":"本集講解《起信論》「若心滅者云何相續」問答，說明所滅的是心生滅相而非心體，以水因風起波、風止波滅而水體不滅為喻。並分析誤解經論的原因：弄錯所說對象、未依義不依語、先受邪教導（如誤解「阿羅漢位捨」為捨心體）、不肯檢驗改正，引《瑜伽師地論》勸對未解深法勿生誹謗。","p":["所滅是心相，非第八識心體","水動相依水體，風滅波止水不滅","讀經論須貫通義理，依義不依語","阿羅漢位捨的是阿賴耶名，非捨心體","邪見如網，宜依聖教、勿謗深法"],"k":["心生滅相","心體不滅","依義不依語","阿賴耶識","邪見","斷滅見"]},"2887-a12_090":{"s":"本集講解《起信論》「以無明力令其心動，無明滅故動相即滅，非心體滅；若心滅者則眾生斷」。說明一念無明令七識攀緣六塵而有分段生死，無始無明令第八識有種子變異而有變易生死；成佛時仍有種子流注但不再變異，名流注滅；並以能依所依、假必依實之理，論證如來藏心體不生不滅。","p":["一念無明令七識攀緣六塵、輪轉生死","無始無明令第八識種子流注變異","佛地種子不再變異，名為流注滅","心體若滅則眾生斷，無能依所依","阿賴耶識為所知依，假必依實"],"k":["無明","心體不滅","流注滅","所知依","如來藏","變易生死"]},"2908-a12_091":{"s":"本集講解《起信論》四種法熏習義：淨法真如、染因無明、妄心業識、妄境六塵。說明如來藏無覆無記能持一切種子、本有無漏種亦須熏習增長；無明是熏習所需的染法，佛地無染故不再受熏；七轉識為能熏心，六塵為熏習之境；並說明能取所取皆為生滅虛妄，執五蘊為我會成染污熏習。","p":["熏習使種子功能差別產生轉變","心真如無覆無記，能持善染種子","有染法才有熏習，佛地不再受熏","七轉識為能熏，須在六塵中熏習","能取所取皆虛妄，執為我成染熏"],"k":["熏習","四種法熏習","心真如","無明","能取所取","種子"]},"2909-a12_092":{"s":"本集依《起信論講記》講解《大乘起信論》「熏習義」：以衣服受香熏為喻，說明能熏是前七識、所熏是第八識如來藏。闡釋「真如淨法性非是染，無明熏故則有染相」及「真如熏故說有淨用」，強調須長時精進熏習善淨法、悟後轉依真如回熏七轉識，並說明熏習即識食之理與習種性階位。","p":["衣服受熏喻：能熏前七識，所熏第八識","引《雜阿含》《持世經》：遠離懈怠、常熏正法成串習","真如性非染，因無明熏而有染相","無明染法無淨業，須轉依真如方有淨用","熏習即識食之義；十信十住習種性須精進熏習"],"k":["熏習","大乘起信論","如來藏","轉依","識食","習種性"]},"2910-a12_093":{"s":"本集講解《大乘起信論》「云何熏習染法不斷」：依常住真如而起無明，經「種子生現行、現行熏種子」循環，使染法熏習不斷。依論文次第說明熏習生妄念心、妄念心復熏無明、不覺真法、妄境相現、生種種執著而造業受苦，並以嬰兒行為為例；結論是須親近善知識與正法道場以離染熏淨。","p":["依真如起無明，無明復熏真如，輪轉不斷","引《成唯識論》：須有持種心，否則同自然外道","嬰兒例：種子生現行同時現行熏種子","不正思惟、習近邪道、習惡知識使三結難斷","妄念心復熏無明，執意識為常而衍生諸邪見"],"k":["染法熏習","種子現行","大乘起信論","無明","邪見","持種心"]},"2911-a12_094":{"s":"本集講解能熏與所熏各具四種特性：能熏七轉識有生滅、有勝用、有增減、與所熏和合而轉；所熏如來藏具堅住性、無記性、可熏性、與能熏共和合性。講者指出以意識細心離五蘊常住或眾生共有本體之見無法成立熏習，並引《正法念處經》說明邪見為十不善業道之本。","p":["能熏四性：有生滅、有勝用、有增減、和合而轉","見分相分皆如來藏所生，自心取自心","所熏四性：堅住、無記、可熏、與能熏和合","引《攝大乘論釋》蒜香不受熏、金石不可熏喻","辨共有本體及離蘊細心之誤；信因果業報"],"k":["能熏所熏","熏習","如來藏","七轉識","無記性","八識論"]},"2912-a12_095":{"s":"本集說明染法熏習的三方面（妄境熏、妄心熏、無明熏），並講解其中「妄境熏義」的增長分別熏與增長執取熏。重點辨析無分別智：是能分別的七識證知第八識本來無分別的體性，而非把覺知心修成一念不生；講者以舉手示數的實驗說明覺知心必有分別，並批評堅持邪見所成的見取見。","p":["染法熏有妄境、妄心、無明三種","妄境熏分增長分別熏、增長執取熏","無分別智：七識證知第八識的無分別性","實驗：無語言文字時覺知心仍已分別完成","堅執邪見成見取見，即增長執取熏"],"k":["妄境熏","無分別智","大乘起信論","見取見","一念不生","真妄和合"]},"2913-a12_096":{"s":"本集講解《大乘起信論》「妄心熏義」二種：增長根本業識熏，涉及所知障、無始無明，使阿羅漢、辟支佛、菩薩受變易生死之生滅苦；增長分別事識熏，指六識於六塵事相上的分別貪取，使凡夫受分段生死業繫之苦。講者批評將所知障解為世間知識太多的說法，並說明意根亦有微細分別及真如緣起門。","p":["根本業識即第八識，含藏一切熏習種子","所知障是對法界實相所知不足，非知識太多","增長根本業識熏致變易生死，斷盡即佛地","分別事識熏使六識分別增強，致分段生死","意根亦有微細分別，如鬧鐘喚醒意識"],"k":["妄心熏","所知障","變易生死","分段生死","意根","煩惱障"]},"2914-a12_097":{"s":"本集先補充真如「非緣起、非非緣起」的中道義，再講解《大乘起信論》「無明熏義」二種：根本熏熏入第八識，成就意根我執習氣與三界受生業果，以阿羅漢抖落蜈蚣說明習氣隨眠；見愛熏屬意識層面的我見與我所貪愛，成就分別事識。講者並批評以能聽能知一念心為佛性及雙身法四喜之說。","p":["心體非緣起，所含染種須修斷故非非緣起","根本熏成就業識，使意根我執難斷","阿羅漢抖落蜈蚣顯習氣隨眠仍在","見愛熏是意識層面我見我所貪愛","講者批評以覺知心為佛性及雙身法樂空"],"k":["無明熏","根本熏","見愛熏","習氣隨眠","我執","真如緣起"]},"2915-a12_098":{"s":"本集開始講解「云何熏習淨法不斷」：淨法熏習廣義自發心學佛即開始，真正受用增長則自三乘見道後起修，故說「不識本心，學法無益」。論文說以真如熏無明，令妄念心厭生死苦、求涅槃樂，眾生因苦而求解脫；講者批評以一念不生、正念分明為涅槃的解脫道教法，並說明妄心厭求回熏真如，令人自信己身有真如。","p":["淨法熏真正起用從三乘見道悟後起修","真如熏無明，令妄念心厭苦求涅槃樂","講者批評以一念不生正念分明為涅槃","相似道場所種福德仍有助遇了義法","妄心厭求回熏真如，自信己身有真如法"],"k":["淨法熏習","真如熏","涅槃","一念無明","無始無明","大乘起信論"]},"2916-a12_099":{"s":"本集續講淨法熏習：心真如本性清淨，非由染污妄心修行轉成，若是修成者即是緣生變異法。引六祖「惠能無伎倆」偈與《維摩詰經》說明本住妙心是現成的，並說明無相念佛的用意；再釋論文「修遠離法…經無量阿僧祇劫慣習力故，無明則滅」。講者批評自續派、應成派以意識或意識細心為真如、涅槃本際之說。","p":["心真如本來清淨，非修行後才變清淨","修成的清淨是緣生法，緣散即壞","六祖偈：本心無伎倆，不須斷百思想","如實知五陰十八界虛妄，修遠離法滅無明","講者評意識細心為本際之說違三法印"],"k":["心真如","本來清淨","淨法熏習","意識細心","六祖壇經","無相念佛"]},"2917-a12_100":{"s":"本集總結「云何熏習淨法不斷」：佛法須如實知、如實證，非佛學研究；先如實觀十八界斷我見，再明心證阿賴耶識，進而修遠離法、起隨順行。引《解深密經》說長劫入短劫，並釋「無明滅故心相不起…名得涅槃，成就種種自在業用」，說明佛菩薩不入無餘涅槃而證無餘涅槃、染因染緣染果，及各地菩薩的自在業用。","p":["佛法須如實知證，非佛學研究可成","斷我見與明心後，自然修遠離法","《解深密經》：精進可長劫入短劫","佛菩薩不入無餘涅槃而證無餘涅槃","初地至佛地漸得自在業用，非想像可得"],"k":["淨法熏習","如實知","無住處涅槃","自在業用","三大阿僧祇劫","斷我見"]},"2918-a12_101":{"s":"本集講解淨法「妄心熏義」二種：分別事識熏（意識熏淨法）令凡夫二乘厭生死苦、隨己堪能趣無上道；意熏（意根熏淨法）令菩薩速趣無住涅槃。說明阿羅漢殺煩惱賊而受人天應供、慧解脫與俱解脫、見惑思惑、堪能性，並列大乘參禪要點：真妄同時、妄心不能修成真心、念屬意識心所、定境非禪，最後談知佛恩與報佛恩。","p":["分別事識熏指意識，意熏指意根第七識","阿羅漢斷見思惑，分慧解脫與俱解脫","堪能性：厭生死苦；大乘修六度福慧","參禪：真妄同時，妄心不能變真心","四加行斷我見；親證以知佛恩、護法報恩"],"k":["妄心熏","分別事識熏","意熏","慧解脫","參禪","煩惱障"]},"2919-a12_102":{"s":"本集續講妄心熏：二乘有中般涅槃（慧解脫）與現般涅槃（俱解脫，須修四禪八定、證滅盡定），大乘更須意熏以速趣無住涅槃。說明無住涅槃不住生死亦不住涅槃、本來自性清淨涅槃為根本，以及大乘須斷習氣隨眠成無垢識；意熏使末那轉為利樂有情的願力。末段開始講真如熏義的體熏與用熏。","p":["中般涅槃為慧解脫，現般涅槃為俱解脫","滅盡定滅受想二心所，可隨時入涅槃","無住涅槃：斷二種生死而不住涅槃","大乘須斷習氣隨眠，第八識成無垢識","意熏轉末那為願力；真如熏分體熏用熏"],"k":["意熏","無住處涅槃","現般涅槃","滅盡定","真如熏","無垢識"]},"2920-a12_103":{"s":"本集講解真如「體熏」：心真如具涅槃性、無漏性與難思勝境界用，勝境界用皆從心真如中現行，並依修證階位由少分至佛地圓滿。說明見道後出三界快慢不同、通教菩薩與迴心阿羅漢的位階，再以五位百法、持種熏習的堅住性及能熏所熏關係，說明真如體熏使眾生厭生死苦、求涅槃樂。","p":["難思勝境界用皆從心真如中現行","勝境界用依三賢、初地、三地、八地漸增","迴心阿羅漢未明心，位階不過六住","所熏持種心須具堅住性，熏習方不唐捐","體熏力令眾生厭生死、信有真實法"],"k":["體熏","真如熏","持種","五位百法","通教菩薩","能熏所熏"]},"2921-a12_104":{"s":"本集就真如體熏作法義辨正：區分常見外道（以意識為常、以定為禪）、斷見（不依第八識而說緣起性空）與正見（依第八識常住而說諸法緣起性空）。依識緣名色、五蘊非我不異我不相在、非心心等說明真我第八識，並講四加行四尋思；講者批評「滅相不滅」論，強調自信己身有真實法，修行方功不唐捐。","p":["常見、斷見與正見三者的區分","緣起性空須依第八識常住而說","五蘊非我、不異我、不相在；真我非心心","意識粗細皆意識，只能能熏不能所熏","講者評滅相論；自信己身有真實法"],"k":["法義辨正","緣起性空","常見外道","斷見","第八識","四加行"]},"2922-a12_105":{"s":"本集講解論中問題：一切眾生同有真如、同受熏習，為何有信不信等無量差別。說明熏習有現行熏種子與種子起現行兩向，般若空是講實相主體空性，並以識緣名色證有第八識。再以 釋迦佛三大阿僧祇劫修行、布施次第與救護眾生之難為例，說明眾生以妄為真的幾種情形，及佛示現苦行與菩提樹下明心見性的過程。","p":["熏習有現行熏種子與種子起現行兩向","般若空講實相主體空性，非一切法空","識緣名色：能生七識者必為第八識","佛修三大阿僧祇劫，明心後才修內門六度","誤認意根、一念不生或定中細心為如來"],"k":["一切眾生同有真如","般若空","識緣名色","明心見性","以妄為真","布施"]},"2923-a12_106":{"s":"本集以 平實導師參禪十九天、捨棄錯誤知見後三小時破參明心見性為例，強調正知見的重要。講者辨析以定為禪的虛空粉碎、大地平沉、一念不生等意識定境，說明禪定與解脫道的關係；再解釋佛悟道時「奇哉」之語：妄想指第六識、執著指第七識，離此即證第八識。最後回答論問：差別源於無明厚薄不同。","p":["平實導師棄錯誤知見後三小時破參","以定為禪：虛空粉碎等仍是意識境界","四禪八定助解脫道，三果須有初禪","「奇哉」語：妄想第六識、執著第七識","眾生差別因無始無明厚薄不同"],"k":["參禪","正知見","以定為禪","明心見性","如來智慧德相","無明"]},"2924-a12_107":{"s":"本集講「有情皆有真心第八識」：依《成唯識論》解釋第八識異名心、阿陀那識、所知依、種子識、阿賴耶識、異熟識、無垢識之義，並列三轉法輪與禪門的異名，皆指同一心。講者批評以意識為常、性空唯名及假藏傳佛教的說法，提出三重點，並詳論每位有情各有一真心；批評觀想明點使真心合併之說，以定中身變大小為喻。","p":["第八識七種異名，依不同義與階位而立","三轉法輪與禪門異名皆指同一真心","講者評常見、斷見及假藏傳佛教之說","每位有情各有一真心，非共有一心","觀想真心合併違《心經》不增不減"],"k":["第八識","阿賴耶識","如來藏","種子識","異熟識","藏傳佛教批判"]},"2925-a12_108":{"s":"本集續講每一真心具足一切法種：引《華嚴經》如來智慧，以初禪天身、意生身、三十二相成就為證。說明種子即功能差別、亦稱界，並依《成唯識論》分本有種子與始起種子。再述熏習三種結果：輪迴生死、成就世間與三乘法、形成習性；引《大智度論》煩惱習之喻，舉阿羅漢瞋習及動物、手機等習性為例，說明習氣須長劫斷除。","p":["真心具足一切法種，眾生皆有如來智慧","初禪天身、意生身、相好皆由法種而現","種子即功能差別，分本有與始起二類","熏習導致輪迴、成就三乘法、形成習性","《大智度論》煩惱習喻；習氣須長劫斷"],"k":["種子","第八識","功能差別","習氣","熏習","成唯識論"]},"2926-a12_109":{"s":"本集講「自性清淨心而有染污」：依《勝鬘經》說明如來藏自性清淨而含藏七轉識染污種子，難可了知。講者批評主張大乘非佛說者。再引《深密解脫經》《金剛三昧經》《心經》說明真心離語言道、離覺觀與見聞覺知，即其清淨性；真妄和合運作，非妄心修成真心；須具定慧福德次法再參禪明心，證後可觀一切有情真心皆清淨。","p":["《勝鬘經》：自性清淨心而有染污","講者評「大乘非佛說」為信心未具足","真心離語言道、離覺觀見聞覺知即清淨","真心生妄心，非妄心修成或生出真心","具足定慧福德次法後參禪明心"],"k":["自性清淨心","如來藏","勝鬘經","真妄和合","明心","大乘非佛說"]},"2927-a12_110":{"s":"本集說明真心所含藏七轉識染污種子分為煩惱現行與習氣種子隨眠，並舉畢陵尊者、須菩提、憍梵鉢提等習氣實例。進而說明斷我見等三縛結為見道，比較二乘與菩薩四果的差別：菩薩留惑潤生，後二大阿僧祇劫再斷習氣種子與所知障而成佛。","p":["煩惱分現行與習氣種子隨眠","畢陵尊者、須菩提、憍梵鉢提習氣實例","斷三縛結即見道，講者批評以意識為真心","二乘四果與菩薩四果之差別","菩薩後二大阿僧祇劫斷習氣與所知障"],"k":["習氣種子隨眠","煩惱現行","斷我見","三縛結","四果","所知障"]},"2970-a12_111":{"s":"本集說明果報須因緣具足：因是如來藏，緣是如來藏所執持的業種與內外助緣。舉佛前世為醫生致長者子死、流離王滅釋迦族兩則經中因緣，闡明凡夫畏果、菩薩畏因；並說器世間、五陰及內六塵皆由如來藏變現，眾生在如來藏中虛妄造業受報，業報不能由他人代受。","p":["引《大寶積經》：業經百劫不亡","佛前世醫生與提婆達多的業報","流離王滅釋迦族之宿世因緣","凡夫畏果，菩薩畏因，勿以惡小而為之","器世間、五陰皆如來藏所變現"],"k":["如來藏","因果業報","異熟果報","內相分","業種"]},"2971-a12_112":{"s":"本集依《大乘起信論》講體熏與用熏：以如來藏為所熏之因，加上善知識等助緣，經「現行熏種子，種子熏現行」使種子染淨轉變。並說菩薩性非本有，從六度、四加行證聲聞初果，到七住明心發起根本無分別智、十住眼見佛性，皆須善知識攝受熏習；最後說明各人差別緣不同。","p":["體熏是真心受熏，用熏是助緣熏習","現行熏種子使種子染淨轉變","菩薩性非本有，由熏習而成","明心發起根本無分別智並須轉依","差別緣使修證快慢不同"],"k":["體熏用熏","大乘起信論","根本無分別智","明心","眼見佛性","差別緣"]},"2972-a12_113":{"s":"本集依《大乘起信論》「或以四攝或以六度」一段，說明佛菩薩隨眾生因緣示現，以四攝法攝受眾生。重點講布施：須以智慧分辨福田與毒田，福田分貧窮田、報恩田、功德田，供佛功德最勝；布施須引眾生入佛法。再介紹聲聞、緣覺、佛菩提三乘，歸結唯一佛乘，並提醒末法邪師眾多。","p":["佛菩薩隨眾生因緣示現人間","四攝法：布施、愛語、利行、同事","布施須分辨福田與講者所說的毒田","三種福田與阿育王供沙因緣","三乘菩提與唯一佛乘"],"k":["四攝法","布施","福田","三乘菩提","菩薩性","大乘起信論"]},"2973-a12_114":{"s":"本集續講四攝法中的愛語、利行、同事，說明攝受眾生即攝受佛土。接著講六度波羅蜜，依五十二階位說明十信修信心，初住至六住次第修布施到般若，六住斷我見、七住證如來藏後內門廣修；再說遠波羅蜜多、近波羅蜜多、大波羅蜜多及十度波羅蜜，等覺百劫修相好。","p":["愛語、利行、同事的意義","攝受眾生即攝受佛土","初住至六住次第修六度","遠、近、大波羅蜜多與十度","等覺位百劫修相好"],"k":["六度波羅蜜","四攝法","五十二階位","十度波羅蜜","三大阿僧祇劫"]},"2974-a12_115":{"s":"本集講《大乘起信論》「一切菩提行緣」，說明修三乘菩提須法與次法並重：次法包括以無相念佛修動中定力、伏除五蓋性障、修集福德與三福淨業。再講大悲柔軟心，引《優婆塞戒經》悲為善法根本，須能難施能施、難忍能忍、難作能作；並強調先自度方能度人，提出辨別真善知識的四個方法。","p":["法次法向：法與次法須兼顧","次法：定力、除五蓋、修福德","牛呞比丘說明口業果報","悲為根本，六度以悲心為生因","辨別真善知識的四個方法"],"k":["次法","無相念佛","五蓋","大悲心","三福淨業","善知識"]},"2975-a12_116":{"s":"本集講《大乘起信論》「廣大福智藏」：福藏指不依眾生供養而能護持弘法，布施習性即菩薩性根源；智藏須明心開悟，乃至見性與入地所需道種智。並引《雜阿含經》相似像法出則正法滅，說明法義辨正與批評人不同；最後講令眾生憶念如來三十二大人相，其為大悲修福的果報。","p":["福藏：不受供養，廣種福田","財富分上有往世因果","修學不應執著在家出家表相","相似像法興則正法滅，須摧邪顯正","三十二大人相是大悲之果報"],"k":["福德","智慧","法義辨正","三十二相","菩薩性","大乘起信論"]},"2976-a12_117":{"s":"本集講《大乘起信論》差別緣中的近緣與遠緣，各有增行緣與入道緣，說明能否於此世證悟取決於過去熏習與增行。提出證道五條件：信力、定力、慧力、福德、消除慢心。後轉入平等緣，說明平等智慧即無分別智：證如來藏後意識仍能分別，諸佛菩薩以此智觀察眾生因緣而施教。","p":["近緣速得菩提，遠緣久遠方得","增行緣與入道緣的差別","證道五條件：信、定、慧、福、除慢","平等智慧即無分別智","證悟後意識仍有分別性"],"k":["差別緣","近緣遠緣","平等緣","無分別智","大乘起信論","見道"]},"2977-a12_118":{"s":"本集續講平等志願：諸佛菩薩一視同仁不捨眾生，緣不具足暫擱置，舉賢天菩薩與不思議光菩薩為例。並說明修福須具體迴向冤親債主、明心智慧任運相續；繼講「入淨三昧」：教眾生憶念佛十號功德，斷無始無明與一念無明四住地，得四種無礙眼；最後比較二乘與大乘的空、無相、無願三三昧。","p":["平等志向與平等願力","賢天菩薩暫擱不思議光菩薩","具體迴向冤親債主以減障礙","無始無明與一念無明四住地","二乘與大乘三三昧的差別"],"k":["平等緣","三三昧","無始無明","四住地煩惱","所知障","大乘起信論"]},"2978-a12_119":{"s":"本集續講平等攝受眾生：法界依平等心而平等，事相差別皆平等心所流注。依《大乘起信論》「入淨三昧、得無礙眼」，說明親證真如可現觀其空、無相、無願，而悟後僅證少分法性，入地證無生法忍方知更多；並說阿賴耶含藏種子即功能差別，二乘未真證清淨三昧，講者並破斥一切法空、捨棄如來藏的主張。","p":["一切事相由平等心流注","親證真如現觀空、無相、無願","悟後證少分，入地證無生法忍","種子即功能差別，含藏於阿賴耶","破斥一切法空而無因生之說"],"k":["平等心","三三昧","如來藏","無生法忍","種子","法眼"]},"2979-a12_120":{"s":"本集講《大乘起信論》「未相應者」：凡夫、二乘、初行菩薩以意與意識熏習，唯依信力修行，由佛菩薩差別緣與平等緣熏養無漏種。講者批評有人失去信心而否定大乘及天界地獄，並逐一破斥世間常見：自身為常、依附天主為常、與天主合一、精神超越世界；說明真常是如來藏，意識非真心，真如有體有用。","p":["未相應者唯依信力修行","無漏種子本有，熏習而增廣","意識眠熟即斷，非真實心","逐一破斥四種世間常見","真如有體有用，非一向無為"],"k":["信力","常見","意識","真如","無漏種子","大乘起信論"]},"2980-a12_121":{"s":"本集講無分別心與自在業：《大乘起信論》所說已相應者指入地法身菩薩，悟後得人無我、入地方證法無我。講者以問答駁斥對「真如緣起」的質疑：十二緣起支皆生滅，須有真實法維持次第，並以法官判刑喻真心依條件成就異熟果報；說明阿賴耶緣起、真如緣起、業感緣起義理相通，識為本源不能過彼。","p":["已相應者指入地法身菩薩","緣起各支生滅，須真實法為依","法官判刑喻如來藏成就業報","各種緣起說法義理相通","八地末那清淨，智慧倍增"],"k":["真如緣起","十二因緣","無分別心","異熟","法身菩薩","大乘起信論"]},"2981-a12_122":{"s":"本集講《大乘起信論》染熏習與淨熏習：無分別心是第八識不在六塵覺觀了別；染熏習無始不斷、成佛乃斷，淨熏習「畢竟無斷」則解為佛地種子不再受熏，只是示現。並解釋「妄心則滅，法身顯現」並非滅七轉識，而是斷除妄心的性障；同理「阿賴耶滅」指滅阿賴耶性而非心體。","p":["無分別心不在六塵上了別","染熏習成佛乃斷","佛地種子不再受熏，唯示現","二乘涅槃依佛施設而信受","妄心滅指伏斷性障，非滅七識"],"k":["熏習","無明","阿賴耶識","性障","涅槃","大乘起信論"]},"2982-a12_123":{"s":"本集實際主題為「如來藏平等平等」：一切有情各有如來藏，本具功德無有增減，無欲心所而平等出生諸法。依《大乘起信論》真如自體相，說明心佛眾生三無差別、如來藏非生滅；並回應如來藏為常見、自性見之批評，逐一辨析梵我合一的「梵、我、合、一」，指出如來藏的真實義不同於該說。","p":["如來藏平等，無欲心所","講者警示以猜測求密意者","五分法身：戒定慧與解脫知見","真如自體相無增減、非生滅","辨析梵我合一與如來藏不同"],"k":["如來藏","平等性","梵我合一","常見","五分法身","大乘起信論"]},"2983-a12_124":{"s":"本集講如來藏所含無量功德：佛地稱無垢識，六七八識相通。依《大乘起信論》大智慧光明、遍照法界、常樂我淨、寂靜不變自在等義，說明如來藏亦名法身，並辨正以打坐不動模仿寂靜不變之誤。最後引玄奘《會宗論》、《制惡見論》，說明空有二宗不應對立，講者並批評王恩洋攻擊《起信論》。","p":["佛地如來藏名無垢識","常樂我淨的佛地意義","瓶與大海喻如來藏含藏染淨","寂靜不變非打坐不動","玄奘會宗，空有不應分立攻訐"],"k":["如來藏","法身","常樂我淨","無垢識","玄奘","大乘起信論"]},"2560-a13_006":{"s":"本集講述恆伽達的故事：大臣威脅廟神求子，天子轉生為恆伽達，因父母阻撓出家而多次求死不得，終獲阿闍世王允許出家，證四果阿羅漢；佛說其前世仗義救人、發願之因緣。講者勉勵欣慕聖賢、迴向發願，在家亦可學佛護法，並勸勿輕易否定大乘法。","p":["恆伽達求出家受阻，跳崖、投河、服毒皆不死","前世為大臣救人一命，被救者證辟支佛","救人功德大，應懂得迴向發願","在家出家皆可學佛，供佛像功德等同","鬼神非究竟，應由小乘欣慕轉向大乘"],"k":["恆伽達","因果業報","迴向發願","出家","欣慕聖賢","大乘法"]},"2561-a13_007":{"s":"本集講述貧窮夫婦罽夷羅賣身借錢供養三寶的故事：國王欲搶同日供養，罽夷羅三次拒絕並說明原委，國王感動賞賜衣飾與十聚落封地，說明真心修福現得花報。講者並說明在家受阻或貧窮者亦可供佛像、以少物或絲線供養，乃至唸佛禮佛。","p":["夫婦賣身為奴，借十金錢供養三寶","國王欲改期遭拒，知情後讚歎並封賞","真心修福現前即得花報","供養佛像與親供佛功德無別","貧者可以絲線、飯食、唸佛禮佛供養"],"k":["供養三寶","修福","花報","供佛像","唸佛"]},"2562-a13_008":{"s":"本集講述大光明王騎白象遇險、象師以熱鐵丸顯示馴象，國王問誰能調身又調心，聞佛名號而發菩提心的故事，大光明王即釋迦佛前身。講者並依《華嚴經》法慧菩薩所說，說明發菩提心勝過教眾生五戒十善、四禪乃至二乘果，目的在令如來種性不斷、眾生究竟成佛。","p":["白象發情狂奔，國王險喪命","象師只能調象身，不能調其心","佛能調身亦調心，國王聞之發大願","願入地獄利益眾生，不捨菩提心","發菩提心勝過教眾生二乘果證"],"k":["發菩提心","大光明王","調心","本生故事","華嚴經"]},"2563-a13_009":{"s":"本集講述佛上忉利天為母說法，以獼猴王救母的本生說明孝道；並介紹地藏菩薩於忉利天說《地藏菩薩本願經》，以婆羅門女、光目女救母故事，說明為亡者四十九日內修福可得七分之一利益、助念之功德，以及「地獄不空，誓不成佛」等大願的由來。","p":["佛於忉利天結夏九十天為母說法","獼猴王結隊救母的本生故事","地藏經為天人說，警醒三界無安","亡者七七內修福迴向可得七分之一","光目女、婆羅門女發救度罪苦眾生大願"],"k":["地藏菩薩本願經","孝道","為母說法","助念","光目女","忉利天"]},"2564-a13_010":{"s":"本集講述微妙比丘尼以親身經歷勸誡五百新出家比丘尼：她前世因嫉妒以針害死小妾之子並發毒誓，今生喪夫失子、被迫食子、兩度被活埋；又因昔日供養緣覺並發願而證阿羅漢，仍每日受鐵針穿身之報。講者藉此說明勿發毒誓、男女愛欲無真實可樂，並批評提倡雙修者的說法。","p":["偷羅難陀勸還俗，微妙比丘尼勸捨淫欲","今生歷經喪夫失子、食子、兩度活埋","前世害子並發毒誓，果報如誓而受","供養緣覺發願，得以證阿羅漢","勿發毒誓，愛欲無常、性別亦不定"],"k":["因果業報","淫欲","毒誓","微妙比丘尼","迴向發願","如來藏"]},"2565-a13_011":{"s":"本集依《雜寶藏經》講述波羅奈國流行活埋父母之惡法，長者子藏父於地窖奉養，借天神所問四事以父教作答，使國王廢除惡法，長者子即佛前身。講者並引盂蘭盆經、觀經三福、賢愚經、本事經等說明孝養功德，真實報恩在引父母入佛法，並解說三歸依與五戒。","p":["孝養父母，如梵天、帝釋、諸佛常住家中","長者子答天神四問，勸王廢活埋父母法","目連救母與盂蘭盆會的緣起","引父母入佛法、受戒聞法才是真報恩","解說三歸依、四宏誓願與五戒"],"k":["孝養父母","雜寶藏經","三歸依","五戒","盂蘭盆經","三福淨業"]},"2566-a13_012":{"s":"本集依《賢愚經》講述一貧人賣身作長工欲齋請佛僧，主人代辦供養，命終生於長者家，出生即能言、請佛應供，全家證初果，後出家證阿羅漢。講者並解說佛、法、僧三寶的意義，主張應歸依大乘賢聖僧，並說明供佛的方式與禁忌，如不以五辛、殘食供佛，可以花、香、讚偈、禮拜供養。","p":["貧人賣身欲供佛，命終生富家而證果","佛為大醫王，四智圓明救護世間","大乘佛菩提才是圓滿法寶","依證量判勝義僧，應歸依大乘賢聖僧","供佛須親手，不用五辛殘食，可讚佛禮拜"],"k":["供佛功德","三寶","菩薩僧","五辛","歸依","賢愚經"]},"2567-a13_013":{"s":"本集依《雜寶藏經》講述棄老國大臣藏父於地窖奉養，天神連出辨蛇雌雄、稱象重、一掬水多於大海等難題，皆由老父作答，國王因而廢除棄老之法，老父即釋迦佛前身。講者並引《大乘本生心地觀經》、《優婆塞戒經》說明母恩難報、孝養與供佛福等，以及剋扣父母供養而布施為假名施。","p":["棄老國大臣違法藏父於地窖奉養","老父以智慧解答天神各項難題","國王廢棄老法，令全國孝養父母","母恩難報，孝養父母福等供佛","剋扣父母而布施是假名施"],"k":["孝養父母","雜寶藏經","大乘本生心地觀經","布施","優婆塞戒經"]},"2568-a13_014":{"s":"本集依《六度集經》講述菩薩為獼猴救出墜谷之人，反遭其以石擊頭，獼猴不生瞋而願其未來得度，獼猴即佛前身、此人即提婆達多。講者據此解說忍辱波羅蜜的生忍、法忍、無生忍、無生法忍，並區分二乘「將滅止生」與大乘如來藏本來無生，最後以達摩、慧可立雪斷臂說明難忍能忍。","p":["獼猴救人反遭害，仍不起瞋","生忍五事：惡來不報、觀無常等","法忍：了義正法雖未懂亦安忍熏習","二乘無生是滅後不生，大乘是如來藏本來無生","無生法忍即道種智、一切種智"],"k":["忍辱波羅蜜","無生法忍","如來藏","六度集經","生忍","立雪斷臂"]},"2569-a13_015":{"s":"本集依《六度集經》講述鹿王因群鹿遭獵傷亡，親見國王請求停獵、群鹿輪流入宮；遇懷孕母鹿時鹿王捨身代死，國王感動而禁殺鹿，鹿王即佛前身。講者並說明布施為六度之首、六度互相含攝，布施有因果，應以不堅身財換取堅固法身與七聖財，福慧二法須兼修。","p":["鹿王代懷孕母鹿赴死，感動國王禁獵","布施為六度基礎，六度互相含攝","貧富差別源自過去世布施差別","以不堅身財易堅身財，修七聖財","福德與智慧如鳥雙翼，須兼修"],"k":["布施","六度波羅蜜","七聖財","福德資糧","異熟果報","六度集經"]},"2570-a13_016":{"s":"本集依《撰集百緣經》講述須曼那出生即裹須曼花衣，出家不久證阿羅漢，因九十一劫前以須曼花覆毘婆尸佛舍利塔並發願。講者說明供佛功德大是因福田殊勝，並逐一解說佛的十號：應供、正遍知、明行足、善逝、世間解、無上士、調御丈夫、天人師、佛、世尊，最後說財、身、法三種供養，以法供養為最。","p":["須曼那因供佛塔須曼花而生具花衣","福田殊勝則果報殊勝","逐一解說佛十號，並與阿羅漢比較","可用十號檢驗自稱活佛、法王者","財供養、身供養、法供養，以法供養最上"],"k":["佛十號","供佛功德","福田","法供養","撰集百緣經"]},"2571-a13_017":{"s":"本集依《六度集經》講述持戒菩薩以全部財物公平換取寡母的紫磨金澡盆，其舅貪心欺詐、追討不成吐血而亡，菩薩即佛前身、舅即提婆達多。講者歸納不貪外我所財、守信直心、持戒三個重點，並引貧女難陀燈、鬼子母等故事；並批評主張大乘非佛說、否定如來藏者違犯法毘奈耶。","p":["菩薩守信換寶，舅舅貪詐吐血而亡","貧女難陀一燈供佛發願，獲授記成佛","布施清淨福田得福，布施毒田有害","鬼子母因不持戒墮鬼道，受三歸五戒","否定大乘、如來藏屬違犯法毘奈耶"],"k":["持戒","守信","布施","法毘奈耶","菩薩戒","六度集經"]},"2572-a13_018":{"s":"本集依《雜寶藏經》講述波斯匿王女善光堅稱依自己善業而活，被嫁給乞丐後掘得寶藏致富；佛說其前世莊嚴佛像並發願、勸夫勿阻供養。講者據此說明自作自受、因果不爽，並舉醜陋的金剛公主訶罵辟支佛之果報；強調自手布施，並將善行迴向無上正等正覺而非有為福德。","p":["善光公主嫁乞丐後掘寶致富","前世莊嚴佛像發願、勸夫勿阻供養","業種由如來藏執持，自作自受","金剛公主因訶罵辟支佛而貌醜","應自手布施，迴向無上正等正覺"],"k":["因果業報","自手布施","迴向","如來藏","雜寶藏經","毀謗賢聖"]},"2573-a13_019":{"s":"本集依《生經》講述暴志比丘尼綁木盆偽稱懷佛之子，被帝釋化鼠咬斷繩索揭穿；佛說其前世因買珍珠不成起瞋發誓報復。講者說明起瞋斷與眾生之緣，業種由如來藏執持而現行，並闡述共業如來藏變現器世間與自心現量；又引《興起行經》說佛前世毀謗賢聖之餘報，勸勿謗人並懺悔。","p":["暴志綁木盆謗佛，帝釋化鼠揭穿","前世買珠不成起瞋，誓世世報復","瞋恚捨眾生，比貪更重","如來藏執持業種，境界皆自心現量","毀謗賢聖果報重，應深心懺悔"],"k":["毀謗","瞋恚","如來藏","自心現量","懺悔","因果業報"]},"2574-a13_020":{"s":"本集依《雜寶藏經》講述佛避利養入貪莊嚴林，開示利養破戒皮、定肉、慧骨、善心髓，一萬二千比丘捨利養而證阿羅漢；並說夜兒達多以少欲化仙人、三藏比丘因利養謗兄之本生。講者又引伏藏毒蛇喻，說明貪著利養不得賢聖戒、定、慧，並批評佛教界追求世俗第一的現象。","p":["利養如傷皮肉骨髓，毀修行功德","佛法是少欲知足、樂寂靜之法","三藏比丘因利養起瞋而謗兄","佛見伏藏黃金稱大毒蛇","貪著利養不得賢聖戒、三昧、智慧"],"k":["利養","少欲知足","毀謗賢聖","戒定慧","雜寶藏經"]},"2615-a13_021":{"s":"本集依《雜寶藏經》講述沙彌本應七日命終，歸途中以袈裟盛土堰水救起漂流的螞蟻，因而延壽。講者分救護眾生性命與救護法身慧命兩部分：以釋迦族被流離王所滅說明殺與被殺輪轉；再解說聲聞、緣覺、佛菩提三乘及菩薩五十二階位，主張救護法身慧命、摧邪顯正最為殊勝。","p":["沙彌救蟻而延壽，短命轉長命","殺生得短命報，不殺得長壽報","釋迦族被滅源於往昔捕魚的殺業","聲聞、緣覺利生有限，佛菩提影響無量世","救護法身慧命勝於救護性命"],"k":["救護眾生","殺生","三乘菩提","法身慧命","五十二階位","摧邪顯正"]},"2616-a13_022":{"s":"本集依《生經》與《出曜經》講述喪子父母因悲痛而發狂，佛開導前者合會有離，又令婦人求取未曾死人之家的火，以四火逼身顯示其愛有限，婦人因而證初果。講者據此說明愛別離苦、眷屬為外我所，此苦不離五陰熾盛苦，並解說五陰虛妄，及二乘入無餘涅槃與菩薩證如來藏、不取涅槃的差別。","p":["喪子男子發狂，聞佛說無常而清醒","婦人求不死人家之火，體悟無常","愛別離苦源於眷屬為外我所","色、識、受、想、行五陰皆虛妄","二乘滅蘊入涅槃，菩薩依如來藏行道"],"k":["愛別離苦","五陰熾盛苦","無常","五陰","如來藏","無餘涅槃"]},"2617-a13_023":{"s":"本集講述佛以江中漂木為喻，開示修行不著此岸、彼岸、中沒等，方能趣入涅槃；牧牛人難陀聞法，依佛教先將牛交還主人後出家，後證阿羅漢。講者解說喻中各項的意義，並逐一說明八正道，以及戒定慧次第、以五陰十八界觀行斷除貪愛、伏煩惱而發起初禪。","p":["漂木不滯兩岸、不沉不腐可入大海","此岸執五蘊我，彼岸落斷見","難陀還牛於主人後出家，證阿羅漢","逐一解說八正道","觀五陰十八界無常以斷貪愛、發初禪"],"k":["八正道","涅槃","斷貪愛","五陰十八界","戒定慧","初禪"]}};
